window.__HRC_SHARD({"shard":"coi-burundi","builtAt":"2026-09-02T12:02:35+00:00","documents":[{"rec_id":"recVBVm12PPqeoZfw","doc_id":"COI Burundi - TOR - 05.10.2016","symbol":null,"title":"Terms of Reference — Commission of Inquiry on Human Rights in Burundi","type":"TOR","date":"2016-10-05","year":2016,"bodies":["COI Burundi"],"paragraphCount":55,"unnumbered":true,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/4. TORs/COI Burundi - TOR - TermsofreferenceCOIBurundiENGL.md","extractor":"pdftotext -layout"},{"rec_id":"recVpCf1yoUHf8o3q","doc_id":"COI Burundi - Official report - 11.08.2017","symbol":"A/HRC/36/54","title":"Report of the Commission of Inquiry on Human Rights in Burundi","type":"Official report","date":"2017-08-11","year":2017,"bodies":["COI Burundi"],"paragraphCount":124,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/COI Burundi - 11-08-2017 - Official document - A_HRC_36_54 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recibKcqsdbQsGvUW","doc_id":"COI Burundi - CRP - 18.09.2017","symbol":"A/HRC/36/CRP.1","title":"Rapport final détaillé de la Commission d’enquête sur le Burundi","type":"CRP","date":"2017-09-18","year":2017,"bodies":["COI Burundi"],"paragraphCount":765,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/COI Burundi - Official report - A_HRC_36_CRP.1 - FR.md","extractor":"pdftotext -layout"},{"rec_id":"recLrmWfYkW5mfR5k","doc_id":"COI Burundi - Official report - 08.08.2018","symbol":"A/HRC/39/63","title":"Report of the Commission of Inquiry on Human Rights in Burundi","type":"Official report","date":"2018-08-08","year":2018,"bodies":["COI Burundi"],"paragraphCount":98,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/COI Burundi - 08-08-2018 - Official report - A_HRC_39_63 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"rec4k1z0OD5d5iOIM","doc_id":"COI Burundi - CRP - 12.09.2018","symbol":"A/HRC/39/CRP.1","title":"Rapport final détaillé de la Commission d’enquête sur le Burundi","type":"CRP","date":"2018-09-12","year":2018,"bodies":["COI Burundi"],"paragraphCount":106,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/COI Burundi - 05-05-2020 - Official report - A_HRC_39_CRP.1 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recyNfwUx22ay0eHy","doc_id":"COI Burundi - Official report - 06.08.2019","symbol":"A/HRC/42/49","title":"Report of the Commission of Inquiry on Human Rights in Burundi","type":"Official report","date":"2019-08-06","year":2019,"bodies":["COI Burundi"],"paragraphCount":147,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/COI Burundi - 06-08-2019 - Official document - A_HRC_42_49 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"rec7cI6SF0WhzvtUM","doc_id":"COI Burundi - CRP - 05.05.2020","symbol":"A/HRC/42/CRP.2","title":"Detailed Final Report of the Commission of Inquiry on Burundi [Extracts]","type":"CRP","date":"2020-05-05","year":2020,"bodies":["COI Burundi"],"paragraphCount":170,"unnumbered":true,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/3. Annexes, CRPs and other materials/COI Burundi - 05-05-2020 - CRP - A_HRC_42_CRP.2 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recQg9nZR0kHfMTSY","doc_id":"COI Burundi - Official report - 13.08.2020","symbol":"A/HRC/45/32","title":"Report of the Commission of Inquiry on Human Rights in Burundi","type":"Official report","date":"2020-08-13","year":2020,"bodies":["COI Burundi"],"paragraphCount":137,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/COI Burundi - 13-08-2020 - Official document - A_HRC_45_32 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recjwlE047Tf8wW8i","doc_id":"COI Burundi - CRP - 17.09.2020","symbol":"A/HRC/45/CRP.1","title":"Conclusions détaillées de la Commission d’enquête sur le Burundi*","type":"CRP","date":"2020-09-17","year":2020,"bodies":["COI Burundi"],"paragraphCount":90,"unnumbered":true,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/COI Burundi - Official report - A_HRC_45_CRP.1 - EN.md","extractor":"python-docx"},{"rec_id":"rec44rTUuolNAIKRE","doc_id":"COI Burundi - CRP - 16.09.2021","symbol":"A/HRC/48/CRP.1","title":"Conclusions détaillées de la Commission d'enquête sur le Burundi","type":"CRP","date":"2021-09-16","year":2021,"bodies":["COI Burundi"],"paragraphCount":441,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/3. Annexes, CRPs and other materials/COI Burundi - 16-09-2021 - CRP - A_HRC_48_CRP.1 - FR.md","extractor":"python-docx"},{"rec_id":"recJZU7nZWB5R5U4c","doc_id":"COI Burundi - Official report - 16.09.2021","symbol":"A/HRC/48/68","title":"Report of the Commission of Inquiry on Human Rights in Burundi","type":"Official report","date":"2021-09-16","year":2021,"bodies":["COI Burundi"],"paragraphCount":196,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/COI Burundi - Official report - A_HRC_48_68 - EN.md","extractor":"python-docx"}],"paragraphs":[{"id":"coi-burundi-tor-05-10-2016-p0001","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":0,"section":null,"text":"COMMISSION OF INQUIRY ON BURUNDI","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0002","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":1,"section":"I. JUDICIAL AUTHORITY","text":"The Commission of Inquiry on Burundi was created Resolution A/HRC/RES/33.24 of the\nHuman Rights Council on 5 October 2016.1","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0003","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":2,"section":"II. MANDATE","text":"Paragraph 23 of Resolution 33/24 states that the Human Rights Council “decides to create for\na period of one year a commission of inquiry:","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0004","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":3,"section":"II. MANDATE","text":"(a) To conduct a thorough investigation into human rights violations and abuses in Burundi\nsince April 2015, including on their extent and whether they may constitute international\ncrimes, with a view to contributing to the fight against impunity;","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0005","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":4,"section":"II. MANDATE","text":"(b) To identify alleged perpetrators of human rights violations and abuses in Burundi with a\nview to ensuring full accountability;","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0006","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":5,"section":"II. MANDATE","text":"(c) To formulate recommendations on steps to be taken with a view to guaranteeing that the\nauthors of these violations and abuses, regardless of their affiliation, are held accountable for\ntheir acts;","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0007","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":6,"section":"II. MANDATE","text":"(d) To engage with the Burundian authorities and all other stakeholders, in particular United\nNations agencies, civil society, refugees, the field presence of the Office of the High\nCommissioner in Burundi, authorities of the African Union, and the African Commission on\nHuman and Peoples’ Rights, in order to provide the support and expertise for the immediate\nimprovement of the situation of human rights and the fight against impunity […]”","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0008","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":7,"section":"II. MANDATE","text":"After consultations, and taking into account comparable past experiences, the members of the\nCommission have interpreted the application of their mandate as follows.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0009","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":8,"section":"II. MANDATE","text":"i.      Subject-matter jurisdiction (ratione materiae)","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0010","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":9,"section":"II. MANDATE","text":"Paragraph 23 a) of Resolution 33/24 states that the Commission will conduct “a thorough\ninvestigation into human rights violations and abuses in Burundi […], including on their\nextent and whether they may constitute international crimes”.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0011","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":10,"section":"II. MANDATE","text":"By “human rights violations”, according to the common definition, the resolution refers to all\nhuman rights violations by state agents or entities covered by national and international law.\nBy “abuses”, the resolution refers to actions committed by non-state entities or their\nmembers.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0012","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":11,"section":"II. MANDATE","text":"With respect to human rights violations and abuses committed in Burundi since April 2015,\nparagraph 2 of Resolution 33/24 refers in particular to mass arbitrary arrests and detentions,\nincluding cases involving children, cases of torture and other cruel, inhuman and/or\ndegrading treatment, extrajudicial killings, enforced disappearances, sexual and gender-based\nviolence, persecution of and threats against members of civil society, journalists, members of\nthe opposition and demonstrators, including young demonstrators, and restrictions on\nfreedoms of expression, peaceful assembly and association. The resolution also mentions the\nexistence of “unacknowledged places of detention”2 and the worrying situation of human\nrights defenders, “many of whom are forced into exile.”3","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0013","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":12,"section":"II. MANDATE","text":"In light of the breadth of its mandate and the relatively short time for its\nimplementation, the Commission will concentrate first and foremost on the most serious\nhuman rights violations and abuses, in particular those which might constitute international\ncrimes. Indeed the Human Rights Council has asked the Commission to assess the extent of\nhuman rights violations and abuses committed in Burundi and to determine “whether they\nmay constitute international crimes”.4 The Commission will interpret the expression\n“international crimes” as “the most serious crimes of concern to the international community\nas a whole”, as defined in the Rome Statute.5 The Commission’s final report will highlight\ncertain emblematic cases and events.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0014","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":13,"section":"II. MANDATE","text":"ii.      Personal jurisdiction (ratione personae)","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0015","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":14,"section":"II. MANDATE","text":"Paragraph 23 b) of Resolution 33/24 tasks the Commission with identifying “alleged\nperpetrators of human rights violations and abuses in Burundi with a view to ensuring full\naccountability.”","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0016","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":15,"section":"II. MANDATE","text":"In particular, the Human Rights Council “expresses grave concern about the reports that most\nof the violations and abuses are being committed by the Burundian security forces and the\nImbonerakure in a climate of impunity”.6 Nevertheless, the Commission will examine\nallegations of human rights violations and abuses committed by all parties, including the\nBurundian defence forces (the army) and other state security forces (police, intelligence\nservices) as well as armed groups, or their members, in Burundi.7","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0017","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":16,"section":"II. MANDATE","text":"The Commission will establish, to the extent possible, individual responsibility for human\nrights violations and abuses. More generally, it will attempt to identify the entities\nresponsible and chains of command. In this respect, the Rome Statute provides for the\nresponsibility of military commanders or hierarchical superiors in certain situations.8","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0018","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":17,"section":"II. MANDATE","text":"iii.     Territorial jurisdiction (ratione loci)","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0019","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":18,"section":"II. MANDATE","text":"Paragraphs 23 a) and b) of Resolution 33/24 limit the geographical scope of the Commission\nof Inquiry to human rights violations and abuses “in Burundi”, that is, committed on the","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0020","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":19,"section":"II. MANDATE","text":"2\nParagraph 4 of Resolution 33/24.\n3\nParagraph 8 of Resolution 33/24.\n4\nParagraph 23 a) of Resolution 33/24.\n5\nArticle 5/1 of the Rome Statute.\n6\nParagraph 5 of Resolution 33/24.\n7\nArmed groups referred to in paragraph 7 of Resolution 33/24.\n8\nArticle 8 of the Rome Statute.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0021","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":20,"section":"II. MANDATE","text":"territory of Burundi, which includes an examination of abuses committed in Burundi by non-\nstate entities, or their members, based abroad.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0022","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":21,"section":"II. MANDATE","text":"Furthermore, paragraph 22 of Resolution 33/24 refers to “the difficult situation of the more\nthan 295,000 Burundians who have fled to neighbouring countries”, whereas paragraph 23\ninvites the Commission to engage with refugees, among others. A combined reading of these\ntwo points has led the Commission to include in the scope of its mandate, to the extent\npossible, an examination of the human rights situation relating to refugees in order to\nformulate recommendations to improve the situation.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0023","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":22,"section":"II. MANDATE","text":"iv.    Temporal jurisdiction (ratione temporis)","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0024","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":23,"section":"II. MANDATE","text":"Paragraph 23 of Resolution 33/24 specifies that the Commission will “conduct a thorough\ninvestigation into human rights violations and abuses in Burundi since April 2015 […]”. The\nresolution therefore clearly specifies the start date of the Commission’s mandate which\ncoincides with the first demonstrations against Pierre Nkurunziza’s third presidential term.\nThe Commission will only be able to conduct investigations until the end of June 2017\nbecause of editorial constraints requiring the report to be finalised in July. Subsequent events\nin Burundi can be covered during the Commission’s oral briefing to the Human Rights\nCouncil in September 2017, on the occasion of the presentation of its final report.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0025","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":24,"section":"II. MANDATE","text":"Members of the Commission are aware that there have been already been initiatives to\nobserve and investigate human rights violations in Burundi since April 2015 by the Office of\nthe High Commissioner for Human Rights in the country and by the mission of Independent\nExperts established by Human Rights Council resolution A/HRC/S-24/1. In its own\ninvestigations, the Commission will therefore take into account the conclusions of the High\nCommissioner of Human Rights presented in his report to the thirty-second session of the\nHuman Rights Council9 and by the Independent Experts in their report presented at the thirty-\nthird session of the Human Rights Council.10 However, as an independent body, the\nCommission will carry out its own investigations on some of the cases and events mentioned\nin these reports.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0026","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":25,"section":"III. APPLICABLE LAW","text":"With respect to the mandate entrusted to the Commission by the Human Rights Council,\ndescribed above, international human rights law and international criminal law will constitute\nthe law applicable to the Commission’s mandate.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0027","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":26,"section":"III. APPLICABLE LAW","text":"Regarding international human rights law, Burundi is party to most relevant instruments,\nincluding the International Covenant on Civil and Political Rights; the International Covenant\non Economic, Social and Cultural Rights; the Convention Against Torture and other Cruel,\nInhuman or Degrading Treatment or Punishment and its Optional Protocol; the International\nConvention on the Elimination of All Forms of Racial Discrimination; the Convention on the\nElimination of All Forms of Discrimination Against Women; the Convention on the Rights of\nthe Child and its two optional protocols; and the Convention on the Rights of Persons with","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0028","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":27,"section":"III. APPLICABLE LAW","text":"Disabilities. Burundi is also party to the Convention relating to the Status of Refugees and its\nOptional Protocol.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0029","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":28,"section":"III. APPLICABLE LAW","text":"In terms of international criminal law, Burundi is party to the Convention on the Prevention\nand Punishment of the Crime of Genocide. It is also party to the Rome Statute of the\nInternational Criminal Court. However, on 27 October 2016, Burundi notified the Secretary\nGeneral of the United Nations, depositary of the Rome Statue, that it intended to withdraw\nfrom this treaty. This will not affect the Commission’s mandate, since under article 127 of\nthe Rome Statute, a state’s withdrawal does not free it from its obligations while it was party\nto the Statute. Since the withdrawal does not come into effect until one year after its\nnotification, in the case of Burundi it will not take place before 26 October 2017. As the\nCommission is due to submit its report in September 2017, it can therefore base its work on\nthe Rome Statute which will remain in force throughout its mandate.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0030","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":29,"section":"III. APPLICABLE LAW","text":"In terms of international humanitarian law, Burundi is party to the Geneva Conventions and\ntheir additional protocols. If the Commission were to reach the conclusion that aspects of the\nsituation in Burundi fell under these conventions, they would also become part of the body of\napplicable law.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0031","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":30,"section":"III. APPLICABLE LAW","text":"On the regional level, Burundi is party to the African Charter on Human and Peoples’ Rights\nand to the Protocol to the African Charter on the Establishment of the African Court of\nHuman and Peoples’ Rights, as well as the African Charter on the Rights and Welfare of the\nChild and the African Union Convention Governing Specific Aspects of Refugee Problems in\nAfrica.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0032","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":31,"section":"III. APPLICABLE LAW","text":"Burundi is party to the Pact on Security, Stability and Development in the Great Lakes\nRegion which includes ten legally binding protocols, including the Protocol on Democracy\nand Good Governance, the Protocol on the Prevention and Punishment of the Crime of\nGenocide, War Crimes and Crimes Against Humanity and all forms of Discrimination, the\nProtocol on the Prevention and Suppression of Sexual Violence Against Women and\nChildren and the Protocol on the Protection and Assistance to Internally Displaced Persons.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0033","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":32,"section":"IV. Standard of proof","text":"In the course of its work, the Commission has decided to adopt the same standard of proof as\nthe majority of international commissions of inquiry on human rights, that is \"reasonable\ngrounds to believe\". This means that in order to reach conclusions, the Commission will\nensure it has gathered a body of reliable and consistent information, on the basis of which a\nreasonable and normally cautious person would have grounds to believe that an incident or\nsystematic behaviour had taken place.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0034","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":33,"section":"IV. Standard of proof","text":"This standard of proof is lower than that used by courts to determine a person’s guilt, which\nis “beyond reasonable doubt”. However, it is the same standard of proof which enables the","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0035","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":34,"section":"IV. Standard of proof","text":"Preliminary Chamber of the International Criminal Court, for example, to issue an arrest\nwarrant or a summons to appear, on application of the Prosecutor.11","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0036","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":35,"section":"IV. Standard of proof","text":"In this context, the Commission will pay particular attention to corroborating any information\nit receives or has collected. It will do so by verifying every piece of information by obtaining\nconsistent information from at least two other independent and reliable sources. However,\nthis process may not always be necessary or possible. Information provided by one primary\nreliable source may only require corroboration by one additional independent and reliable\nsource, which may include the investigator’s own observations. For example, if an\ninterviewee makes an allegation of torture, the investigator’s assessment of the reliability of\nthe source, as well as the sight and observation of scars and injuries corresponding to the\naccount, could be sufficient for the process of corroboration. In other cases, for example acts\nof sexual violence, it can be very difficult to obtain corroboration of a victim’s account from\nanother independent source, especially if the victim did not obtain medical assistance or was\nnot in a position to report the acts to the authorities. In such cases, the account can be\ncorroborated by assessing the details of the victim’s account, trying to determine if they\ncorrespond to information available in the public domain and establishing whether the acts\npoint to a pattern consistent with other similar cases.12","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0037","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":36,"section":"V. COMPOSITION","text":"i.      Members of the Commission","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0038","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":37,"section":"V. COMPOSITION","text":"On 22 November 2016, the President of the Human Rights Council announced the\nappointment of Mr Fatsah Ouguergouz (Algeria), Ms Reine Alapini Gansou (Benin) and Ms\nFrançoise Hampson (United Kingdom) as members of the Commission of Inquiry on\nBurundi. The President of the Council indicated that Mr Ouguergouz would serve as\nPresident of the Commission.13","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0039","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":38,"section":"V. COMPOSITION","text":"The members of the Commission will enjoy the privileges and immunities granted to experts\non mission, according to article VI of the Convention on the Privileges and Immunities of the\nUnited Nations.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0040","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":39,"section":"V. COMPOSITION","text":"Paragraph 25 of Resolution 33/24 of the Human Rights Council requests that “the Office of\nthe High Commissioner be provided with all the resources necessary […] to fulfil [its]\nmandate\". The Office of the United Nations High Commissioner for Human Rights has\ntherefore put at the disposal of the Commission a secretariat with specialised skills as well as\nthe administrative, technical and logistical assistance needed for the implementation of its\nmandate.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0041","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":40,"section":"V. COMPOSITION","text":"11\nArticle 58/1 of the Rome Statute.\n12\nOffice of the United Nations High Commissioner for Human Rights, Commissions of Inquiry and Fact-Finding\nMissions on International Human Rights and Humanitarian Law, 2015, pages 62-63.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0042","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":41,"section":"VI. OBLIGATIONS OF THE STATE CONCERNED","text":"In paragraph 24 of Resolution 33/24, the Human Rights Council “urges the Government of\nBurundi to cooperate fully with the commission of inquiry, to authorize it to conduct visits to\nthe country and to provide it with all the information necessary to fulfil its mandate.”","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0043","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":42,"section":"VI. OBLIGATIONS OF THE STATE CONCERNED","text":"In light of this provision and on the basis of similar experiences,14 the Commission should\nbenefit from:","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0044","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":43,"section":"VI. OBLIGATIONS OF THE STATE CONCERNED","text":"a) freedom of movement throughout the territory of Burundi. If the Government of Burundi\nrefuses to grant the Commission access to its territory, the Commission should try to visit\ncountries in the region and any other country it believes would be useful for the successful\nconduct of its investigations;\nb) unhindered access to all places and establishments, and freedom to meet and interview\nrepresentatives of national, local and military authorities, community leaders,\nnongovernmental organisations and other institutions, and any person whose testimony is\nconsidered necessary for the fulfilment of its mandate;\nc) unhindered access for individuals and organisations wishing to meet the Commission;\nd) free access to all sources of information, including documentary material and physical\nevidence;\ne) appropriate security arrangements for the Commission's members, staff and documents;\nf) protection of victims and witnesses and all those who come into contact with the\nCommission, and an undertaking that no such person shall, as a result of such contact, suffer\nharassment, threats, acts of intimidation, ill-treatment or reprisals.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0045","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":44,"section":"VI. OBLIGATIONS OF THE STATE CONCERNED","text":"In its oral briefings and its final written report, the Commission will be able to report on the\nlevel of cooperation by the Government of Burundi and any other State it approaches.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0046","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":45,"section":"VII. THE COMMISSION'S REPORT","text":"Paragraphs 23 e) and f) of Resolution 33/24 of the Human Rights Council provide for the\nCommission of Inquiry: “e) To present an oral briefing to the Human Rights Council at its\nthirty-fourth and thirty-fifth sessions, and a final report during an interactive dialogue at its\nthirty-sixth session; f) To present its report to the General Assembly and other relevant\ninternational bodies.”","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0047","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":46,"section":"VII. THE COMMISSION'S REPORT","text":"In light of these provisions, the Commission will present an oral briefing on the progress of\nits work at the March and June 2017 sessions of the Human Rights Council. It will present\nits final report at the September 2017 session. This will be a written report which will include\na set of recommendations “on steps to be taken with a view to guaranteeing that the authors\nof these violations and abuses, regardless of their affiliation, are held accountable for their\nacts”, in accordance with paragraph 23 c) of Resolution 33/24. The report will be published\non the website of the Office of the High Commissioner for Human Rights after being\ncommunicated in advance to the Government of Burundi.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0048","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":47,"section":"VII. THE COMMISSION'S REPORT","text":"Paragraph 23 f) of the resolution mentions the presentation of the report to the United Nations\nGeneral Assembly without mentioning to which session of the General Assembly the","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0049","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":48,"section":"VII. THE COMMISSION'S REPORT","text":"14\nOffice of the United Nations High Commissioner for Human Rights, Commissions of Inquiry and Fact-Finding\nMissions on International Human Rights and Humanitarian Law, 2015, pages 67-68.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0050","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":49,"section":"VII. THE COMMISSION'S REPORT","text":"Commission should make this presentation. However, as the presentation of the\nCommission's final report is scheduled for the Human Rights Council session of September\n2017, the Commission can be expected to present its report to the General Assembly during\nits 72nd ordinary session, scheduled to take place from September to December 2017.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0051","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":50,"section":"VII. THE COMMISSION'S REPORT","text":"Paragraph 23 f) of the resolution also provides for the Commission to present its final report\n“to other relevant international bodies”. This opens the possibility for the Commission to\npresent its report to bodies other than the Human Rights Council and the United Nations\nGeneral Assembly, including the United Nations Security Council15 and the African Union\nPeace and Security Council.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0052","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":51,"section":"VIII. COOPERATION","text":"In the implementation of its mandate, the Commission of Inquiry on Burundi should enjoy\nthe full cooperation of all United Nations Member States, departments and bodies, and of all\nother relevant international institutions and actors.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0053","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":52,"section":"VIII. COOPERATION","text":"In particular, the Commission will try to ensure the cooperation of the Office of the United\nNations High Commissioner of Human Rights which has an office in Burundi. However, as\nan independent body, the Commission will conduct its own investigations independently and\nseparately from the Office of the United Nations High Commissioner of Human Rights in\nBurundi.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0054","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":53,"section":"VIII. COOPERATION","text":"In countries where the Office of the United Nations High Commissioner of Human Rights\ndoes not have a field presence, the support of other United Nations agencies in the country\nwill be necessary to organise meetings with the main actors, establish dialogue with\nstakeholders and ensure follow up activities, including the protection of victims, witnesses\nand other sources.","unnumbered":true},{"id":"coi-burundi-tor-05-10-2016-p0055","rec_id":"recVBVm12PPqeoZfw","symbol":null,"n":null,"seq":54,"section":"VIII. COOPERATION","text":"15\nIn the past, several commissions of inquiry set up by the Human Rights Council have included in their\nrecommendations a request for the Security Council to take their conclusions into consideration. This was the\ncase, for example, with the Commission of Inquiry on the human rights situation in North Korea in 2014 and\nthe Commission of Inquiry on human rights in Eritrea in 2016.","unnumbered":true},{"id":"a-hrc-36-54-u0000","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":null,"seq":0,"section":null,"text":"United Nations                                                                               A/HRC/36/54\nGeneral Assembly                                                          Distr.: General\n11 August 2017\nEnglish\nOriginal: French","unnumbered":true},{"id":"a-hrc-36-54-u0001","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":null,"seq":1,"section":null,"text":"Summary\nThe Commission of Inquiry on Burundi was created by Human Rights Council\nresolution 33/24, adopted on 30 September 2016, to conduct a thorough investigation into\nhuman rights violations and abuses committed in Burundi since April 2015, to determine\nwhether any of them may constitute international crimes and to identify their alleged\nperpetrators.\nThe Commission can confirm the persistence of extrajudicial executions, arbitrary\narrests and detentions, enforced disappearances, torture and cruel, inhuman or degrading\ntreatment and sexual violence in Burundi since April 2015. Most of these violations were\ncommitted by members of the National Intelligence Service, the police, the army and the\nyouth league of the ruling party, commonly known as the Imbonerakure. The Commission\nemphasizes the scope and the gravity of the documented violations, which, in some\ninstances, entailed serious physical and psychological trauma for the victims. Human rights\nabuses were also committed by armed opposition groups, but these proved difficult to\ndocument.\nThe Commission has reasonable grounds to believe that crimes against humanity\nhave been committed in Burundi since April 2015.\nWithout a real willingness on the part of the Burundian authorities to combat\nimpunity and guarantee the independence of the judiciary, the perpetrators of these crimes\nwill remain unpunished. The Commission therefore requests the International Criminal\nCourt to initiate, as soon as possible, an investigation into the situation in Burundi since\nApril 2015.","unnumbered":true},{"id":"a-hrc-36-54-p0001","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"1","seq":2,"section":"A. Mandate","text":"The Commission of Inquiry on Burundi (hereinafter “the Commission”) was created\nfor a period of one year by Human Rights Council resolution 33/24, adopted on 30\nSeptember 2016, to conduct a thorough investigation into human rights violations and\nabuses committed in Burundi since April 2015 and, in particular, to assess their extent,\ndetermine whether they constitute international crimes, identify their alleged perpetrators\nand formulate recommendations on steps to be taken with a view to guaranteeing that the\nlatter, regardless of their affiliation, are held accountable for their acts."},{"id":"a-hrc-36-54-p0002","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"2","seq":3,"section":"A. Mandate","text":"On 22 November 2016, the President of the Human Rights Council appointed Fatsah\nOuguergouz (Algeria), Reine Alapini Gansou (Bénin) and Françoise Hampson (United\nKingdom) as members of the Commission, which was chaired by Mr. Ouguergouz. The\nCommission members were assisted by a secretariat established by the Office of the United\nNations High Commissioner for Human Rights."},{"id":"a-hrc-36-54-p0003","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"3","seq":4,"section":"A. Mandate","text":"The Commission presented two oral briefings during the thirty-fourth and thirty-fifth\nsessions of the Human Rights Council in March and June 2017. The present report\nsummarizes the final conclusions of its investigations, which will be detailed in a separate\ndocument.1"},{"id":"a-hrc-36-54-p0004","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"4","seq":5,"section":"B. Cooperation by Burundi with the Commission","text":"In its resolution 33/24, the Human Rights Council urged the Government of Burundi\nto cooperate fully with the Commission of Inquiry, to authorize it to conduct visits to the\ncountry and to provide it with all the information necessary to fulfil its mandate.\nNotwithstanding that request, the Government of Burundi refused any form of dialogue or\ncooperation with the Commission in spite of several initiatives by the latter."},{"id":"a-hrc-36-54-p0005","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"5","seq":6,"section":"B. Cooperation by Burundi with the Commission","text":"In fact, as of the completion of the present report, the Commission had sent three\nnotes verbales to the Permanent Mission of Burundi in Geneva and two letters to the\nMinister for Foreign Affairs. 2 It requested the Burundian authorities to grant it access to the\ncountry and to inform it of their views on the human rights situation in Burundi,\nparticularly in regard to attacks against agents of the State or members of the ruling party.\nThese requests have gone unanswered."},{"id":"a-hrc-36-54-p0006","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"6","seq":7,"section":"C. Methodology","text":"Following the practice of other commissions of inquiry which had been denied\naccess to the territory covered by their mandate, the Commission visited neighbouring\ncountries (Uganda, the Democratic Republic of the Congo, Rwanda and the United\nRepublic of Tanzania) and other countries hosting Burundian refugees. These visits, as well\nas numerous contacts from a distance, enabled the Commission to conduct more than 500\ninterviews with victims, witnesses and other sources."},{"id":"a-hrc-36-54-p0007","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"7","seq":8,"section":"C. Methodology","text":"The Commission adopted the same standard of proof as most of the commissions of\ninquiry on human rights, namely “reasonable grounds to believe”. It therefore took care to\ncollect a body of reliable and consistent information on the basis of which a reasonable and\nordinarily prudent person would have reason to believe that an incident or pattern of\nconduct had occurred."},{"id":"a-hrc-36-54-p0008","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"8","seq":9,"section":"C. Methodology","text":"In addition to the lack of cooperation on the part of the Government and the latter’s\nrefusal to grant it access to the country, the Commission was faced with the difficulty of\n1   Detailed final report of the Commission of Inquiry on Burundi.\n2   See annex II.\nconducting an inquiry on Burundi when victims and witnesses are still afraid to talk about\ntheir experiences. In the short period of time allotted to it, the Commission could not\nconduct a thorough investigation of certain cases and cover all the violations and abuses. It\nwas nevertheless able to document a significant sample."},{"id":"a-hrc-36-54-p0009","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"9","seq":10,"section":"D. Applicable law","text":"Burundi is a party to seven of the principal international human rights instruments:\nthe International Covenant on Civil and Political Rights, the International Covenant on\nEconomic, Social and Cultural Rights, the International Convention on the Elimination of\nAll Forms of Racial Discrimination, the Convention against Torture and Other Cruel,\nInhuman or Degrading Treatment or Punishment and the Optional Protocol thereto, the\nConvention on the Elimination of All Forms of Discrimination against Women, the\nConvention on the Rights of the Child and the two Optional Protocols thereto, and the\nConvention on the Rights of Persons with Disabilities and the Optional Protocol thereto. It\nis also a party to the African Charter on Human and Peoples’ Rights and other relevant\nAfrican instruments."},{"id":"a-hrc-36-54-p0010","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"10","seq":11,"section":"D. Applicable law","text":"Burundi has ratified the Convention on the Prevention and Punishment of the Crime\nof Genocide and, since 2004, has been a party to the Rome Statute of the International\nCriminal Court. 3 However, on 27 October 2016, it notified the Secretary-General of the\nUnited Nations of its decision to withdraw from the latter treaty. Since such withdrawal\ndoes not take effect until one year has elapsed, that notification did not affect the work of\nthe Commission, which conducted its juridical analysis using the definition of crimes\ncontained in the Rome Statute."},{"id":"a-hrc-36-54-p0011","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"11","seq":12,"section":"D. Applicable law","text":"The Commission did not regard international humanitarian law as being applicable\nwithin the framework of its mandate insofar as, given the sporadic nature of the attacks\ncarried out or claimed by armed groups in Burundi since April 2015, the existence of a non-\ninternational armed conflict could not be inferred therefrom. 4"},{"id":"a-hrc-36-54-p0012","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"12","seq":13,"section":"A. Main trends","text":"The political crisis that Burundi has faced since 2015 has been compounded by a\ngrave human rights crisis. Although warning signs of that situation had been observed\nbefore 25 April 2015, 5 President Pierre Nkurunziza’s announcement on that date of his\ndecision to seek a new term in office was followed by a significant deterioration in the\nhuman rights situation. The Commission documented violations that were frequently of an\nextremely cruel nature, particularly extrajudicial executions, arbitrary arrests and\ndetentions, enforced disappearances, acts of torture and other cruel, inhuman or degrading\ntreatment and sexual violence. Such violations had already been reported by the United\nNations High Commissioner for Human Rights, 6 the United Nations independent\ninvestigation on Burundi7 and the African Commission on Human and Peoples’ Rights.8"},{"id":"a-hrc-36-54-p0013","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"13","seq":14,"section":"A. Main trends","text":"The large number of testimonies collected by the Commission clearly show that the\ndemonstrations which began in April 2015, the failed coup d’état in May 2015 and the\nattacks against four military installations in and around Bujumbura on 11 December 2015\nconstituted decisive stages in the escalation of violence in 2015. This climate conducive to\nhuman rights violations continued in 2016 and 2017, maintained by hate speech on the part\nof the authorities and members of the ruling party — the Conseil national pour la défense\nde la démocratie-Forces de défense de la démocratie (CNDD-FDD) — and also by the\npervasive impunity that was aggravated by a judiciary lacking independence. Some\nviolations have been committed in a more clandestine, but equally brutal, manner since\n2016."},{"id":"a-hrc-36-54-p0014","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"14","seq":15,"section":"A. Main trends","text":"The victims, mostly young men (with the exception of victims of sexual violence),\nwere invariably opponents of the Government or perceived as such: demonstrators against\nPierre Nkurunziza’s candidature in the presidential election of 2015; members of opposition\npolitical parties, particularly the Mouvement pour la solidarité et la démocratie, and the\nForces nationales de libération, as well as their relatives; members of the former Burundian\nArmed Forces (“ex-FAB”); 9 members of civil society; journalists; persons suspected of\nsupporting or participating in the failed coup; and members and sympathizers of armed\nopposition groups or persons who, having gone into exile, were thereby suspected of\njoining those groups. The Commission also noted a phenomenon of recruitment of the\npopulation into CNDD-FDD and its youth league, the Imbonerakure. Any resistance often\nled to human rights violations."},{"id":"a-hrc-36-54-p0015","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"15","seq":16,"section":"A. Main trends","text":"The Commission’s interviews revealed a climate of deep and widespread fear: fear\nof testifying in view of the risk of reprisals, fear of persecution, even in exile, and fear of\nreturning to the country. In mid-July 2017, the Burundian refugee population was estimated\nat 417,098 persons, 10 i.e. around 4 per cent of the country’s total population. Many\nmembers of civil society, as well as journalists, remain in exile and international arrest\nwarrants have been issued against some of them. Those who are still in Burundi have to\nwork underground. The Government has suspended or revoked the licences of the principal\nindependent media and human rights organizations."},{"id":"a-hrc-36-54-p0016","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"16","seq":17,"section":"A. Main trends","text":"The violations of civil and political rights have had a direct impact on the enjoyment\nof economic, social and cultural rights due to the restriction of freedoms, particularly\nfreedom of movement, and the decision taken by the main donors to suspend much of their\ndirect aid to the Government as a consequence of those violations. The deteriorating\neconomic situation has, in turn, exacerbated the phenomenon of extortion, which has taken\nvarious forms, including ransom demands by agents of the State, the release of detainees in\nexchange for payment, the imposition of new taxes on an already impoverished population,\nand extortion by Imbonerakure."},{"id":"a-hrc-36-54-p0017","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"17","seq":18,"section":"1. The State’s responsibility for the conduct of its organs","text":"Under international law, including human rights law, the State is responsible for the\nconduct of its organs regardless of whether they exercise legislative, executive, judicial or\nany other functions, whatever position they hold in the organization of the State and\n6  See A/HRC/32/30.\n7\nSee A/HRC/33/37.\n8 Report of the African Commission on Human and Peoples’ Rights on its fact-finding mission to\nBurundi (7-13 December 2015).\n9 The term “ex-FAB” refers to members of the former Burundian Armed Forces, the majority of whom\nwere Tutsis. The Burundian army found itself in a deeply divided state after the attempted coup in\nMay 2015 and this led to marginalization of the “ex-FAB” and their subjection to human rights\nviolations.\n10 Office of the United Nations High Commissioner for Refugees, 20 July 2017.\nwhatever their character as an organ of the central Government or of a territorial unit of the\nState. 11 The Commission was able to ascertain that, since April 2015, the defence and\nsecurity forces have been the principal perpetrators of human rights violations in Burundi,\neven when they acted jointly with non-State actors such as the Imbonerakure."},{"id":"a-hrc-36-54-p0018","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"18","seq":19,"section":"1. The State’s responsibility for the conduct of its organs","text":"Members of the National Intelligence Service, including senior officials, in\nBujumbura and in several provinces have committed acts for which the State can be held\nresponsible, including extrajudicial executions, arbitrary arrests and detentions, enforced\ndisappearances, acts of torture and cruel, inhuman or degrading treatment and sexual\nviolence. The National Intelligence Service reports directly to the President of the Republic\nand its operations are managed by an Administrator General."},{"id":"a-hrc-36-54-p0019","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"19","seq":20,"section":"1. The State’s responsibility for the conduct of its organs","text":"The Burundian National Police have played an active role since the first\ndemonstrations against President Nkurunziza’s candidature for a new term in office. Since\nApril 2015, police officers have committed summary executions, arbitrary arrests and\ndetentions, enforced disappearances, acts of torture and cruel, inhuman or degrading\ntreatment and sexual violence. Some units, including the Unit for the Protection of\nInstitutions (Appui à la protection des institutions) and the Anti-Riot Brigade, which was\nestablished in September 2015, have been particularly implicated in gross violations of\nhuman rights."},{"id":"a-hrc-36-54-p0020","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"20","seq":21,"section":"1. The State’s responsibility for the conduct of its organs","text":"The Burundian army (National Defence Force), which kept a low profile at the\nbeginning of the crisis, has played an increasingly active role in the repression of real or\npresumed opponents. In the testimonies collected by the Commission, military personnel\nhave been identified as the alleged perpetrators of summary executions, arbitrary arrests,\ntorture and cruel, inhuman or degrading treatment. Among the units involved in grave\nviolations of human rights, the Commission has identified the Special Brigade for the\nProtection of Institutions, the Combat Engineer Battalion (Camp Muzinda) and the Support\nBattalion of the First Military Region (Camp Muha) in Bujumbura."},{"id":"a-hrc-36-54-p0021","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"21","seq":22,"section":"1. The State’s responsibility for the conduct of its organs","text":"The Commission also documented cases in which local administrative authorities\ncommitted or ordered the commission of human rights violations, including arbitrary\narrests."},{"id":"a-hrc-36-54-p0022","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"22","seq":23,"section":"1. The State’s responsibility for the conduct of its organs","text":"A number of testimonies showed that, in reality, the State operates largely through a\nparallel structure based on personal ties inherited from the time when certain CNDD-FDD\nauthorities were waging an underground armed struggle; these ties were strengthened in\nresponse to the opposition of some party members who, starting in 2014, had said they were\nnot in favour of a new term in office for President Nkurunziza. 12 Major decisions, including\nthose that have given rise to gross violations of human rights, are allegedly taken not by the\nGovernment but by the President and his entourage of “generals”, including the Minister of\nPublic Security, the Administrator General of the National Intelligence Service, the heads\nof the President’s civil cabinet and office of police affairs, and the Secretary General of\nCNDD-FDD. This entourage apparently transmits its decisions through a parallel chain of\ncommand, the structure of which varies from one branch and one province to another, with\nthe result that subordinates might sometimes hold more power than their superiors. For\nexample, the Commission ascertained that the Deputy Inspector General of the Police had\nmore power than the Inspector General."},{"id":"a-hrc-36-54-p0023","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"23","seq":24,"section":"2. Responsibility of the State for the conduct of non-State individuals or groups","text":"Under international law, including human rights law, the State may be held\ngenerally responsible for the wrongful conduct of non-State individuals or groups when the\nlatter are acting in “complete dependence”13 on the State. It might also be held responsible\nin cases in which non-State individuals or groups act on its instructions or under its\ndirection or its “effective control”14 and also when its own agents acknowledge and adopt\nthe conduct of non-State groups. 15 Bearing these principles in mind, the Commission\nexamined the question of the responsibility of the Burundian State for the acts committed\nby Imbonerakure, whose involvement in extrajudicial executions, arbitrary arrests and\ndetentions, enforced disappearances and acts of torture and cruel, inhuman or degrading\ntreatment and sexual violence it was able to document."},{"id":"a-hrc-36-54-p0024","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"24","seq":25,"section":"2. Responsibility of the State for the conduct of non-State individuals or groups","text":"The Commission cannot infer the “complete dependence” of the Imbonerakure on\nthe Burundian State, as this would imply “a particularly great degree of State control over”\nthe persons or entities in question.16 A certain alignment17 of the Imbonerakure (and, more\ngenerally, of CNDD-FDD) with the Government’s policy should nevertheless be\nemphasized."},{"id":"a-hrc-36-54-p0025","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"25","seq":26,"section":"2. Responsibility of the State for the conduct of non-State individuals or groups","text":"The Commission was, however, able to establish that members, including senior\nofficials, of the National Intelligence Service, the police, the army and the President’s\noffice have close ties to some Imbonerakure, to whom they give instructions or directives to\ncommit human rights violations."},{"id":"a-hrc-36-54-p0026","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"26","seq":27,"section":"2. Responsibility of the State for the conduct of non-State individuals or groups","text":"In some cases, the Commission was also able to establish the exercise of “effective\ncontrol” by agents of the State over some Imbonerakure. Numerous witnesses testified that\nImbonerakure were present alongside police and intelligence officers, including in\ndetention centres, when violations were committed and that Imbonerakure were seen\nwearing the same uniforms and carrying the same weapons as the police or the army in the\npresence and in full view of members of those forces. Moreover, as far as the Commission\nis aware, very few Imbonerakure have been prosecuted or convicted, and this, in itself, is\nindicative of a certain degree of indulgence on the part of the Burundian authorities which\nsuggests the existence of a form of control."},{"id":"a-hrc-36-54-p0027","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"27","seq":28,"section":"2. Responsibility of the State for the conduct of non-State individuals or groups","text":"The Commission also received reports to the effect that some Imbonerakure arrested\nindividuals and handed them over to the National Intelligence Service or the police. This\nindicates that their conduct was acknowledged and adopted by the authorities."},{"id":"a-hrc-36-54-p0028","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"28","seq":29,"section":"3. Responsibility of armed opposition groups","text":"The Commission received reports concerning targeted attacks by armed opposition\ngroups against military and police posts, as well as more large-scale attacks such as those in\nKayanza Province in July 2015 and in and around Bujumbura on 11 December 2015. On\nthe other hand, the Commission was unable to obtain information concerning attacks\nagainst civilians by organized armed groups with a known structure. The obstacles to these\ninvestigations were partly attributable to the difficulty of gaining access to witnesses, many\nof whom are in Burundi, and to the fact that the Burundian Government shared no\ninformation with the Commission.\n14 See article 8 of the articles on responsibility of States for internationally wrongful acts; Military and\nParamilitary Activities in and against Nicaragua (Nicaragua v. United States of America), Merits,\nJudgment, I.C.J. Reports 1986; and Application of the Convention on the Prevention and Punishment\nof the Crime of Genocide (Bosnia and Herzegovina v. Serbia and Montenegro), Judgment, I.C.J.\nReports 2007.\n15\nArticle 11 of the articles on responsibility of States for internationally wrongful acts. In its general\ncomment No. 3 on the African Charter on Human and Peoples’ Rights: The Right to Life (Article 4),\nthe African Commission on Human and Peoples’ Rights expressed the view that a State could be held\nresponsible for killings by non-State actors if it approved, supported or acquiesced in those acts.\n16 Application of the Convention on the Prevention and Punishment of the Crime of Genocide (Bosnia\nand Herzegovina v. Serbia and Montenegro), Judgment, I.C.J. Reports 2007.\n17 The International Court of Justice nevertheless requires “systematic alignment” in order to\ndemonstrate “complete dependence” (ibid.)."},{"id":"a-hrc-36-54-p0029","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"29","seq":30,"section":"1. Right to life","text":"The Commission received numerous testimonies concerning violations of the right\nto life for which the Burundian State can be held responsible. These violations include\nexcessive use of deadly force by the defence and security forces during the demonstrations\nbetween April and June 2015. In some cases, the police allegedly took action following acts\nof violence by demonstrators which led to the death of police officers and members of the\nruling party.18 Members of the Unit for the Protection of Institutions (Appui à la protection\ndes institutions), the Anti-Riot Brigade and the Combat Engineer Battalion also committed\nextrajudicial executions in some neighbourhoods of Bujumbura, including on 13 October\n2015 in Ngagara and on 31 October 2015 in Buringa (Bubanza Province). In reprisal for\narmed attacks against several military positions in Bujumbura and Mujejuru (Bujumbura\nProvince) on 11 December 2015, police and military personnel summarily executed dozens\nof persons in Bujumbura Mairie, including in Nyakabiga and Musaga. The bodies of\npersons who had been executed were also found in the commune of Mukike (Bujumbura\nProvince). The extrajudicial executions that took place in December 2015, on a scale that\nexceeded those reported since April 2015, were accompanied or followed by torture, rape\nand arbitrary arrests."},{"id":"a-hrc-36-54-p0030","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"30","seq":31,"section":"1. Right to life","text":"According to several testimonies, after the events of December 2015 the local\nadministrative authorities ordered bodies to be buried in common graves, particularly in\nKanyosha (Bujumbura Mairie) and Mpanda (Bubanza Province). On 29 February 2016, the\nmayor of Bujumbura informed the media of the discovery of a common grave in Mutakura\n(Bujumbura Mairie), asserting that the bodies were those of CNDD-FDD sympathizers who\nhad been killed by members of the opposition. 19 Only access to all the alleged sites of\ncommon graves, as well as forensic studies and more thorough investigations, would make\nit possible to determine the validity of those allegations."},{"id":"a-hrc-36-54-p0031","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"31","seq":32,"section":"1. Right to life","text":"The Commission received reports of extrajudicial executions of members of the\nsecurity forces, particularly members of the former Burundian Armed Forces (“ex-FAB”).\nFor example, General Athanase Kararuza, security and defence adviser to the First Vice-\nPresident, together with his wife, his daughter and a bodyguard, were killed in Bujumbura\nby members of the police and the army on 25 April 2016."},{"id":"a-hrc-36-54-p0032","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"32","seq":33,"section":"1. Right to life","text":"According to some testimonies, people have died while in the custody of law\nenforcement agencies, including in places of detention."},{"id":"a-hrc-36-54-p0033","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"33","seq":34,"section":"1. Right to life","text":"Lifeless bodies have regularly been found in several provinces, often with their arms\ntied behind their back, and sometimes decapitated. In several cases, the authorities have\nordered the interment of these bodies without identifying the victims and without any\ncredible investigation, thereby failing in their duty to protect the right to life. In other cases,\nthe victims were identified as persons who opposed President Nkurunziza’s candidature for\na new term in office or as members of opposition parties. Corpses, sometimes weighed\ndown with stones, have been found in the Rusizi River and Lake Tanganyika. Witnesses\nasserted that persons arrested by the police, military personnel or Imbonerakure had been\ntaken into the Rukoko forest and executed there."},{"id":"a-hrc-36-54-p0034","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"34","seq":35,"section":"1. Right to life","text":"The Commission also received reports of summary executions by Imbonerakure,\nacting either as auxiliaries of the defence and security forces or on their own initiative. For\nexample, on 5 August 2015 in Cibitoke (Bujumbura Mairie), members of the\nImbonerakure, accompanied by police officers, executed two men after ordering them to\nkneel with their hands in the air."},{"id":"a-hrc-36-54-p0035","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"35","seq":36,"section":"1. Right to life","text":"The Commission noted several cases of targeted assassination and attempted\nassassination attributed to members of the National Intelligence Service or the police, such\nas the assassination of Zedi Feruzi, leader of the Union pour la paix et le développement-\nZigamibanga opposition party, on 23 May 2015; the attempted assassination of Pierre\nClaver Mbonimpa, President of the Association burundaise pour la protection des droits\nhumains et des personnes détenues, on 3 August 2015; and the execution of his son, Welly\nNzitonda, on 6 November 2015."},{"id":"a-hrc-36-54-p0036","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"36","seq":37,"section":"1. Right to life","text":"The Commission also collected information on assassinations committed by persons\nwhose identity and responsibility it was unable to establish, such as the assassinations of\nGeneral Adolphe Nshimirimana, the former head of the National Intelligence Service, on 2\nAugust 2015; Colonel Jean Bikomagu, retired, on 15 August 2015; Patrice Gahungu,\nspokesperson of the Union pour la paix et le développement, on 7 September 2015; Pascal\nNshimirimana, son-in-law of Pierre Claver Mbonimpa, on 9 October 2015; Lieutenant\nColonel Darius Ikurakure on 22 March 2016; Hafsa Mossi, member of the East African\nLegislative Assembly, on 13 July 2016; and Emmanuel Niyonkuru, Minister of Water,\nEnvironment, Land Management and Urban Planning, on 1 January 2017. Major General\nPrime Niyongabo, Army Chief of Staff, and Willy Nyamitwe, communications adviser to\nthe President of the Republic, escaped assassination attempts during which other persons\nwere killed on 11 September 2015 and 28 November 2016 respectively."},{"id":"a-hrc-36-54-p0037","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"37","seq":38,"section":"2. Enforced disappearances","text":"Arrest and detention conditions in Burundi are conducive to enforced\ndisappearances. The Commission received several testimonies concerning persons who\ndisappeared after being arrested by members of the National Intelligence Service and/or the\npolice. By way of example, on 9 March 2016, nine policemen, guided by an Imbonerakure\ntravelling in a police vehicle, arrested Hugo Haramategeko, leader of the Nouvelle alliance\npour le développement du Burundi party, in Bujumbura. His family has not heard from him\nsince. In some cases, members of the National Intelligence Service or the police have\ndemanded ransoms from the relatives of disappeared persons. Augustin Hatungimana, a\nmember of the Mouvement pour la réhabilitation du citoyen-Rurenzangemero party, who\nwas arrested by the police in Bujumbura on 9 December 2015, is still missing. His family\npaid 600,000 Burundian francs to persons presenting themselves as intelligence agents and\noffering to find him."},{"id":"a-hrc-36-54-p0038","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"38","seq":39,"section":"2. Enforced disappearances","text":"The context, characterized by numerous cases of disappearance and, frequently, the\nexistence of one or more particular elements, such as the profile of the persons targeted —\npolitical opponents, members of civil society or “ex-FAB” — and threats made against the\nvictims prior to their disappearance or subsequently received by their relatives in\nconnection with their disappearance, affords reasonable grounds to fear enforced\ndisappearances. In such cases, the authorities have an obligation to open an independent\nand effective investigation. For example, Savin Nahindavyi, an intelligence officer,\ndisappeared on 1 May 2016; one of his superiors subsequently presented his condolences to\nthe family but his body was never found. Several testimonies also suggest that intelligence\nagents or members of the police were involved in the disappearances of Marie-Claudette\nKwizera, treasurer of the Ligue Iteka human rights organization, on 10 December 2015;\nJean Bigirimana, a journalist working for the Iwacu newspaper, on 22 July 2016; and Oscar\nNtasano, a former senator and owner of the Nonara Hotel in Bujumbura, on 21 April 2017."},{"id":"a-hrc-36-54-p0039","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"39","seq":40,"section":"2. Enforced disappearances","text":"Identification of the bodies discovered and exhumation of bodies by the authorities\nmight enable missing persons to be traced."},{"id":"a-hrc-36-54-p0040","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"40","seq":41,"section":"3. Right to liberty and security of person","text":"The Commission found that the most frequently reported human rights violations\nconsisted in arbitrary arrests and detentions, which, in many cases, led to other violations\nsuch as extrajudicial executions, enforced disappearances, acts of torture and cruel,\ninhuman or degrading treatment and sexual violence."},{"id":"a-hrc-36-54-p0041","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"41","seq":42,"section":"3. Right to liberty and security of person","text":"The arbitrary nature of the arrests is attributable to the fact that the persons making\nthem, such as Imbonerakure, either were not authorized to do so or failed to respect the\nprocedures prescribed by law. Moreover, many victims were not informed of the reasons\nfor their arrest."},{"id":"a-hrc-36-54-p0042","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"42","seq":43,"section":"3. Right to liberty and security of person","text":"The Commission is also concerned about draft amendments to the Criminal Code\nand the Code of Criminal Procedure which, in some cases, would enable criminal\ninvestigation officers to conduct searches without a warrant, including at night."},{"id":"a-hrc-36-54-p0043","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"43","seq":44,"section":"3. Right to liberty and security of person","text":"In many cases documented by the Commission, the persons arrested were taken to\nthe National Intelligence Service or police cells and subjected to torture or ill-treatment\nbefore being released or transferred to prisons. Several testimonies referred to secret places\nof detention located, for example, within the headquarters of the National Intelligence\nService in Bujumbura or in private houses or containers in different provinces, where\ndetainees were deprived of any contact with the outside world."},{"id":"a-hrc-36-54-p0044","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"44","seq":45,"section":"3. Right to liberty and security of person","text":"Most of the detainees did not enjoy the safeguards prescribed by the International\nCovenant on Civil and Political Rights and by Burundian law, such as access to a lawyer\nand to medical care, the possibility of petitioning a court to rule on the legality of their\ndetention, and the right to receive visits. Many victims were also detained in conditions that\nconstituted cruel, inhuman or degrading treatment and for periods extending beyond the\nmaximum allowable time of police custody, namely seven days renewable once only,\nwhich is already excessive.20 The practice in regard to release is often random; publicity\nabout an arrest, or acquaintance with a person within the State apparatus, can facilitate\nrelease. In many cases, exorbitant amounts of money have been demanded by members of\nthe National Intelligence Service, the police, the judiciary or the Imbonerakure for the\nrelease of detainees or their transfer to prisons."},{"id":"a-hrc-36-54-p0045","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"45","seq":46,"section":"4. Torture and other cruel, inhuman or degrading treatment","text":"The Commission has documented a persistent practice of torture and ill-treatment\nsince April 2015. Numerous witnesses identified the headquarters of the National\nIntelligence Service, situated near Bujumbura Cathedral, as a place where such acts\noccurred, while others referred to a police detention centre known as “Chez Ndadaye”,\nwhich was used mainly in 2015 by the Anti-Riot Brigade, among others. Several other\ndetention centres run by the police and the National Intelligence Service in Bujumbura and\nother provinces, as well as some unofficial places of detention, were also mentioned."},{"id":"a-hrc-36-54-p0046","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"46","seq":47,"section":"4. Torture and other cruel, inhuman or degrading treatment","text":"The victims interviewed by the Commission mentioned recurrent methods of torture,\nincluding beatings with clubs, rifle butts, bayonets, iron bars, metal chains or electric\ncables, as a result of which some victims’ bones were broken and other victims lost\nconsciousness; long needles thrust into victims’ bodies or unidentified substances injected\ninto them; nails ripped out. Some victims were placed beside human remains or forced to\neat faeces. Rapes were also committed and acts of torture inflicted on the genital organs of\nvictims. Detainees were forced to witness executions, convinced that they would be the\nnext victims. Acts of torture and ill-treatment were often accompanied by insults, including\nof an ethnic nature, and threats to kill the victims with firearms or grenades. In many cases\nthese acts caused severe and enduring physical and psychological trauma."},{"id":"a-hrc-36-54-p0047","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"47","seq":48,"section":"4. Torture and other cruel, inhuman or degrading treatment","text":"Victims described conditions of detention that may constitute cruel, inhuman or\ndegrading treatment, such as prison overcrowding, denial of adequate food and medical\ncare, denial of access to toilet facilities, and failure to separate adults from minors as was\nthe case at the National Intelligence Service in Bujumbura."},{"id":"a-hrc-36-54-p0048","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"48","seq":49,"section":"5. Sexual violence","text":"Notwithstanding their fears of stigmatization, the Commission was able to interview\nmore than 45 victims of sexual violence whose ages ranged from 8 to 71 at the time when\nthe acts were committed. The real number of victims, mostly women but also a few men\nand children, is probably much higher. The most recent of these acts of sexual violence\ntook place in 2017."},{"id":"a-hrc-36-54-p0049","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"49","seq":50,"section":"5. Sexual violence","text":"Most of the cases documented by the Commission involved rape or attempted rape\ncommitted while police officers or members of the Imbonerakure, sometimes acting\ntogether, were in the process of arresting the victim’s spouse or a male relative accused of\nbelonging to an opposition party, taking part in demonstrations or refusing to join CNDD-\nFDD, although such crimes also occurred while the victims were at home alone. These acts\nwere frequently accompanied by offensive gender-based, political and/or ethnic remarks.\nThe Commission wishes to emphasize the extreme cruelty of some of these acts of\nviolence. For example, a female minor was raped by three Imbonerakure wearing police\nuniforms beside the body of a relative whom they had killed. Two women were raped by\nseveral men, including Imbonerakure, who subsequently mutilated their genital organs. The\nCommission also heard the testimonies of women who had been raped by Imbonerakure or\npolice officers at roadblocks or near the borders because they were attempting to flee."},{"id":"a-hrc-36-54-p0050","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"50","seq":51,"section":"5. Sexual violence","text":"Sexual violence has been used as a means of torture to obtain information or\nconfessions from detainees. These acts include rape, forced nudity, infliction of severe\nwounds on, and injection of unknown substances into, male genital organs, and the hanging\nof weights on testicles. The Commission heard the testimony of a female victim of rapes,\nincluding gang rapes, committed over a period of four days, inter alia by police officers in a\nNational Intelligence Service cell with a view to obtaining information."},{"id":"a-hrc-36-54-p0051","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"51","seq":52,"section":"5. Sexual violence","text":"Acts of sexual violence have left the victims with severe and enduring physical and\npsychological trauma. Women have contracted HIV, fallen pregnant or suffered\nmiscarriages and several men are suffering from erectile, urinary and other problems."},{"id":"a-hrc-36-54-p0052","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"52","seq":53,"section":"6. Freedom of expression","text":"The restrictions on freedom of expression noted since April 2015 have continued. In\ncontrast to previous years when Burundi had a dynamic civil society and numerous\nindependent media, the democratic space enabling journalists to express themselves freely\nhas been severely restricted. The Government closed four private radio stations in April and\nMay 2015, in some cases after they were destroyed by law enforcement units. Only one of\nthese radio stations, Radio Isanganiro, has been authorized to resume broadcasting since\nFebruary 2016.21 In November 2016, the National Communications Council suspended one\nof the station’s programmes because it broadcast a song entitled “Human rights for\njournalists”. The Union burundaise des journalistes (Burundian Union of Journalists),\nwhich had denounced attacks on press freedom on numerous occasions, was suspended in\nOctober 2016. Many journalists remain in exile and international arrest warrants have been\nissued against some of them."},{"id":"a-hrc-36-54-p0053","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"53","seq":54,"section":"6. Freedom of expression","text":"The Commission is concerned at instances of hate speech since April 2015. Such\nlanguage, heard both in public speeches and in informal comments by Burundian\nauthorities and leaders and members of CNDD-FDD, particularly Imbonerakure, is\nintended to intimidate and sometimes dehumanize opponents by equating them with\nanimals. The use of terms such as “cockroaches” or “bugs” is disturbing, particularly as\nthey were used in the past to refer to Tutsis, especially in Rwanda. Such speech perpetuates\nconfusion between political opponents and that ethnic group."},{"id":"a-hrc-36-54-p0054","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"54","seq":55,"section":"6. Freedom of expression","text":"A video circulated in April 2017 showed around a hundred Imbonerakure chanting a\ncall to “impregnate female opponents so that they can give birth to Imbonerakure”.\nFollowing condemnation by the United Nations High Commissioner for Human Rights, 22\nthe ruling party’s National Secretary for Information and Communication promised\nsanctions against the culprits. 23 A “judicial file” has apparently been opened, 24 but the\nCommission has received no information concerning follow-up on that file,\n21 The Rema FM radio station, which is close to the ruling party, was also destroyed in May 2015. It\nresumed broadcasting in 2016.\n22 See www.ohchr.org/EN/NewsEvents/Pages/DisplayNews.aspx?NewsID=21505&LangID=E.\n23 CNDD-FDD press release No. 0002-17-SNIC, 5 April 2017.\n24 Statement by the Permanent Representative of Burundi before the Human Rights Council, 15 June\n2017.\nnotwithstanding the State’s obligation to take action.25 Moreover, Imbonerakure have made\nsimilar calls in various provinces."},{"id":"a-hrc-36-54-p0055","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"55","seq":56,"section":"7. Freedoms of association and assembly","text":"Freedom of association continues to be restricted. Only two of the civil society\norganizations, mostly working on human rights-related issues, which had been suspended\nor whose accounts had been frozen by the Government in the latter part of 2015 have been\nable to resume their activities in Burundi. On 19 October 2016, the Ministry of the Interior\nannounced the revocation of the licences of the Association burundaise pour la protection\ndes droits humains et des personnes détenues, the Forum pour le renforcement de la société\ncivile, the Forum pour la conscience et le développement, Action des chrétiens pour\nl’abolition de la torture (ACAT Burundi) and the Réseau des citoyens probes. Five days\nlater, the same Ministry suspended the licences of the Coalition de la société civile pour le\nmonitoring électoral, the Coalition burundaise pour la Cour pénale internationale, SOS-\nTorture/Burundi (even though it was established abroad) and the Ligue Iteka. The latter’s\nlicence was revoked on 3 January 2017 after it published a report on the deteriorating\nhuman rights situation in Burundi. The heads of the Coalition de la société civile pour le\nmonitoring électoral, the Forum pour le renforcement de la société civile, the Forum pour la\nconscience et le développement and ACAT Burundi have been under international arrest\nwarrants since 2015."},{"id":"a-hrc-36-54-p0056","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"56","seq":57,"section":"7. Freedoms of association and assembly","text":"The Commission is concerned at the promulgation in January 2017 of a law on\nBurundian non-profit organizations, and another on foreign non-governmental\norganizations, certain provisions of which considerably strengthen the authorities’ control\nover the activities and resources of those entities."},{"id":"a-hrc-36-54-p0057","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"57","seq":58,"section":"7. Freedoms of association and assembly","text":"Opposition parties cannot meet freely or carry out their activities in Burundi. Their\nmembers are under constant pressure to join the ruling party and many of them have been\narrested, tortured or killed."},{"id":"a-hrc-36-54-p0058","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"58","seq":59,"section":"8. Freedom of movement","text":"A number of persons have been arrested, ill-treated and, in certain instances, raped\nat roadblocks set up by police and Imbonerakure, or solely by Imbonerakure, near the\nborders, particularly with Rwanda and the United Republic of Tanzania. Others have been\nforced to pay large sums of money to police or Imbonerakure or have had their belongings\ntaken. Some persons have been threatened, arrested or tortured for helping people to flee\nthe country. Several members of the families of individuals who left the country have been\nthreatened and some have been subjected to arbitrary arrest and detention or have been\nreported missing."},{"id":"a-hrc-36-54-p0059","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"59","seq":60,"section":"8. Freedom of movement","text":"Some persons who have visited neighbouring countries, particularly Rwanda, have\nbeen arbitrarily arrested or tortured on their return to Burundi because the authorities\nallegedly accused them of collaborating with armed groups said to be based in those\ncountries."},{"id":"a-hrc-36-54-p0060","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"60","seq":61,"section":"8. Freedom of movement","text":"The Burundian authorities have taken measures that hamper freedom of movement,\nas exemplified by the “household record booklets” in which the head of each household is\nrequired to list all his dependants, as well as visitors. These booklets, which are inspected\nby the police during raids on homes, are allegedly intended to enable law enforcement\nofficials to keep track of the population. In a general context of heightened surveillance by\nthe authorities, this measure has the effect of discouraging professional or private travel."},{"id":"a-hrc-36-54-p0061","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"61","seq":62,"section":"9. Dysfunctions in the judiciary and other institutions","text":"The Commission collected testimonies concerning undue pressure brought to bear\non judges and prosecutors by their peers and also by members of the Government or the\nruling party. Several lawyers have left the country, in some cases after receiving threats.\nAccording to the information available to the Commission, very few criminal proceedings\n25   Article 20, paragraph 2, of the International Covenant on Civil and Political Rights.\nhave been instituted against alleged perpetrators of human rights violations. The\ncommissions of inquiry established by the Attorney General in the wake of the events of\nApril 2015, the killing of nine persons in the Ngagara neighbourhood on 13 October 2015\nand the events of 11 December 2015 did not act with impartiality, as demonstrated by their\nreports, which the Commission examined."},{"id":"a-hrc-36-54-p0062","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"62","seq":63,"section":"9. Dysfunctions in the judiciary and other institutions","text":"The Commission noted long delays in judicial proceedings, the holding of some\nsensitive trials on prison premises, which deterred observers from attending, and summary\ntrials conducted pursuant to the “expedited” procedure, applicable to those allegedly caught\nin the act. By way of example, 1 police officer, 7 military personnel and 12 civilians who\nhad been arrested in connection with the attack on the military camp at Mukoni (Muyinga\nProvince) on the night of 23-24 January 2017 were tried without a lawyer on 26 January.\nThe Muyinga provincial court sentenced them to heavy prison terms without regard to their\nclaims that they had been tortured while in detention, to the point where some of the\ndefendants were unable to stand during the trial."},{"id":"a-hrc-36-54-p0063","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"63","seq":64,"section":"9. Dysfunctions in the judiciary and other institutions","text":"The judiciary’s lack of independence, which has long been observed in Burundi, has\naggravated the impunity prevailing in the country. In August 2013, the first National Forum\non the Justice System, the report of which has never been made public, emphasized the\nexecutive branch’s influence over the National Judicial Service Commission, which is\nchaired by the Head of State and composed mainly of members appointed by the\nGovernment. The executive branch’s ascendancy over the judicial branch is also apparent\nin the appointment of judges and the fact that they may be transferred, which runs counter\nto the principle of the irremovability of judges. The Ministry of Justice controls the\npromotion of judges and may propose their suspension or dismissal."},{"id":"a-hrc-36-54-p0064","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"64","seq":65,"section":"9. Dysfunctions in the judiciary and other institutions","text":"The Commission also noted the lack of independence of the national institutions for\nmonitoring the authorities’ actions in the field of human rights, namely the Independent\nNational Human Rights Commission 26 and the Ombudsman, ever since the leaders and\ncertain members of those institutions were replaced in 2015 and 2016."},{"id":"a-hrc-36-54-p0065","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"65","seq":66,"section":"1. Constituent elements of crimes","text":"Article 7, paragraph 1, of the Rome Statute defines crimes against humanity as acts\n“committed as part of a widespread or systematic attack directed against any civilian\npopulation, with knowledge of the attack”. Article 7, paragraph 2 (a), further stipulates that\n“‘attack directed against any civilian population’ means a course of conduct involving the\nmultiple commission of acts […] against any civilian population, pursuant to or in\nfurtherance of a State or organizational policy to commit such attack”. In the light of the\ninformation obtained, the Commission has reasonable grounds to believe that an attack\nagainst the civilian population has been taking place in Burundi since April 2015. That\nattack has consisted in the multiple commission of acts covered by the Rome Statute 27\nagainst a largely civilian population consisting in particular of opponents of the\nGovernment or persons perceived as such. 28 The fact that members of the security forces\nare among the victims in no way changes that categorization. 29\n26\nIn November 2016, the Sub-Committee on Accreditation of the Global Alliance of National Human\nRights Institutions recommended that the Independent National Human Rights Commission should be\ndowngraded to “B” status. The final decision is to be taken in 2017.\n27 See part II of the present report.\n28 See part II.A of the present report.\n29 In The Prosecutor v. Clément Kayishema and Obed Ruzindana, the International Criminal Tribunal\nfor Rwanda ruled that the presence of certain non-civilians within the targeted population did not\nchange the civilian character of that population."},{"id":"a-hrc-36-54-p0066","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"66","seq":67,"section":"1. Constituent elements of crimes","text":"The Rome Statute requires the existence of a State or organizational policy to\ncommit the attack. However, in the case law of the International Criminal Court and other\ninternational criminal tribunals, that policy need not be of an official nature. In the Blaškić\ncase, the International Tribunal for the Former Yugoslavia ruled that the intent to commit\nan attack need not necessarily be declared expressly or even stated clearly and precisely. It\nmay be surmised from the occurrence of a series of events, including “the overall political\nbackground against which the criminal acts are set; […] the general content of a political\nprogramme, as it appears in the writings and speeches of its authors; […] the mobilization\nof armed forces; […] [and] the scale of the acts of violence perpetrated”.30 In the case of\nBurundi, the violations and abuses documented by the Commission are set against the\nbackground of a political crisis which began in April 2015, with the demonstrations against\nPierre Nkurunziza’s candidature in the presidential election, and intensified after the failed\ncoup d’état in May 2015 and the use of violence by armed groups and unidentified persons\nagainst agents of the State and, in particular, against military camps on 11 December 2015.\nThese acts led to a mobilization of the defence and security forces in order to repress any\nform of real or presumed opposition to the Government, and this continued into 2017. The\nhate speech aimed at opponents by authorities and representatives of CNDD-FDD at all\nlevels is indicative of a general political will to suppress any dissenting opinion. Moreover,\nthe International Criminal Court has ruled that, in exceptional circumstances, a State’s\npolicy may “be implemented by a deliberate failure to take action, which is consciously\naimed at encouraging such attack”.31 The fact that, generally, the alleged perpetrators of\nviolations have not been prosecuted, or pressure has been brought to bear to prevent any\nprosecution, can be interpreted as a deliberate failure by the Burundian State to take action\nand, therefore, as encouragement on its part."},{"id":"a-hrc-36-54-p0067","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"67","seq":68,"section":"1. Constituent elements of crimes","text":"The Rome Statute stipulates that the attack must be “widespread or systematic”,\nthese two conditions not being cumulative. In the case of Burundi, the number of violations,\ntheir commission in several provinces and the multiplicity of victims, perpetrators and\ninstitutions involved point to the widespread nature of the attack. Its systematic nature can\nbe inferred either from “an organized plan in furtherance of a common policy”, which the\nCommission has reasonable grounds to believe in view of its observations in the preceding\nparagraph, or from “patterns of crimes” such that the latter constitute a “non-accidental\nrepetition of similar criminal conduct on a regular basis”, 32 the existence of which the\nCommission has documented."},{"id":"a-hrc-36-54-p0068","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"68","seq":69,"section":"1. Constituent elements of crimes","text":"Finally, the Rome Statute requires that the attack must have been carried out “with\nknowledge”. In this regard, it is not necessary to prove that the perpetrator knew the details\nof the attack, since such knowledge may be deduced from “indirect evidence” such as the\ncircumstances in which the attack occurred.33 The Commission therefore believes, in the\nlight of the information at its disposal, that the alleged perpetrators whom it was able to\nidentify, most being members of the National Intelligence Service, the police, the army and\nthe Imbonerakure, could not have been unaware of the background against which their acts\nwere set, given their functions in the State’s security apparatus or their indoctrination\nwithin CNDD-FDD."},{"id":"a-hrc-36-54-p0069","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"69","seq":70,"section":"2. Types of crimes","text":"The Commission, having established that the elements of crimes against humanity\nare present, examined the types of crimes committed in Burundi since April 2015. As a\nresult, it has reasonable grounds to believe that the violations and infringements of the right\nto life that were perpetrated by agents of the State, particularly the extrajudicial executions\nand the deaths attributable to an excessive use of force by law enforcement agencies and\nImbonerakure, may constitute “murders” under the Rome Statute.34"},{"id":"a-hrc-36-54-p0070","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"70","seq":71,"section":"2. Types of crimes","text":"The Commission also finds that the many cases of arbitrary detention in National\nIntelligence Service and police cells and unofficial places of detention may constitute\n“imprisonment or other severe deprivation of physical liberty in violation of fundamental\nrules of international law” under the Rome Statute.35 Moreover, the violations frequently\ncommitted during detention, including the inhuman conditions in which detainees have\nbeen held, add to the gravity of those acts."},{"id":"a-hrc-36-54-p0071","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"71","seq":72,"section":"2. Types of crimes","text":"The actions of members of the security forces, sometimes assisted by Imbonerakure,\nwhich the Commission categorized as acts of torture and cruel, inhuman or degrading\ntreatment constitute “torture” under the Rome Statute36 insofar as they were systematically\nintended to inflict “severe physical or mental pain or suffering upon one or more persons”\nwhile such persons were “in the custody or under the control of the perpetrator”.37"},{"id":"a-hrc-36-54-p0072","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"72","seq":73,"section":"2. Types of crimes","text":"Cases of rape committed by police officers and/or Imbonerakure in the course of\narrests of opponents or reprisals against female members of the families of opponents\nconstitute “rape” under the Rome Statute.38 The other cases of sexual violence, particularly\nin detention, documented by the Commission may constitute, under the Rome Statute, “any\nother form of sexual violence of comparable gravity”, “torture” or “other inhumane acts of\na similar character intentionally causing great suffering, or serious injury to body or to\nmental or physical health”.39"},{"id":"a-hrc-36-54-p0073","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"73","seq":74,"section":"2. Types of crimes","text":"The various violations committed by agents of the State or Imbonerakure against\nmembers of opposition parties — particularly members of the Forces nationales de\nlibération and the Mouvement pour la solidarité et la démocratie — or their relatives may\nalso constitute crimes of “persecution” under the Rome Statute. 40 These crimes were\npolitically motivated and the victims were targeted by reason of their real or presumed\naffiliation with opposition parties.41 Furthermore, in certain cases of sexual violence, the\ntargeting of women having family ties with political opponents may constitute gender-\nbased persecution."},{"id":"a-hrc-36-54-p0074","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"74","seq":75,"section":"2. Types of crimes","text":"With regard to enforced disappearances, the Commission was able to establish, from\nthe viewpoint of international human rights law, some cases of disappeared persons whose\narrest or detention was confirmed by witnesses but whose disappearance was subsequently\ndenied by the Burundian authorities. 42 However, at the current stage of its investigations,\nthe Commission cannot reach the same conclusion from the viewpoint of international\ncriminal law, under which the perpetrator of such arrest, detention or abduction must have\nbeen aware that it would be followed by a refusal to acknowledge that deprivation of\nfreedom or to give information on the fate or whereabouts of the victim, or the perpetrator\nof a refusal to acknowledge the detention must have known that the victim was detained. 43\nThe Commission does not rule out the possibility that this element may be deduced from\nindirect evidence, such as a background characterized by arbitrary arrests and detentions, a\nclimate of widespread persecution and the existence of particular facts such as threats\n34 Article 7, paragraph 1 (a).\n35 Article 7, paragraph 1 (e).\n36\nArticle 7, paragraph 1 (f).\n37 International Criminal Court, Elements of crimes, p. 7.\n38 Article 7, paragraph 1 (g).\n39 Article 7, paragraphs 1 (g), (f) and (k).\n40 Article 7, paragraph 1 (h).\n41 International Criminal Court, Elements of crimes, p. 10.\n42 See part II.C.2 of the present report.\n43 International Criminal Court, Elements of crimes, p.11.\npreceding or following the disappearances. In the many cases in which, from the human\nrights viewpoint, the Commission only has reasonable grounds to fear that enforced\ndisappearances have occurred, further evidence will need to be gathered within the\nframework of a more thorough investigation before these acts can be categorized as\nenforced disappearances under international criminal law."},{"id":"a-hrc-36-54-p0075","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"75","seq":76,"section":"B. Genocide","text":"Although, within the context of certain violations such as arrests, torture and sexual\nviolence, the Commission was able to show that Tutsis were targeted by insults of an ethnic\nnature, it is not in a position to establish the existence of a political will to destroy that\nethnic group “in whole or in part”, as required by the definition of genocide given in article\n6 of the Rome Statute."},{"id":"a-hrc-36-54-p0076","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"76","seq":77,"section":"B. Genocide","text":"The Commission nevertheless remains concerned about certain speeches by State\nauthorities and officials of the ruling party. Although such statements do not constitute\ndirect and public incitement to commit genocide, 44 they help to create a dangerous climate\nof hate and to terrorize the population, and could rekindle ethnic tensions."},{"id":"a-hrc-36-54-p0077","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"77","seq":78,"section":"C. Individual responsibility","text":"The Commission has reasonable grounds to believe that the above-mentioned crimes\nagainst humanity are attributable primarily to State officials at the highest level and to\nsenior officers and members of the National Intelligence Service, the police, the army and\nthe Imbonerakure."},{"id":"a-hrc-36-54-p0078","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"78","seq":79,"section":"C. Individual responsibility","text":"The Commission has drawn up a non-exhaustive list of alleged perpetrators of\ncrimes against humanity, accompanied by information concerning specific acts that they are\nsuspected to have committed or ordered. It has made a distinction between direct\nresponsibility and the responsibility of military commanders and superiors, as provided for\nin the Rome Statute.45"},{"id":"a-hrc-36-54-p0079","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"79","seq":80,"section":"C. Individual responsibility","text":"Given the need to respect the presumption of innocence and to protect victims and\nwitnesses, the Commission has decided not to publish that list, which will be placed in the\nsafekeeping of the United Nations High Commissioner for Human Rights. The latter may\nshare it with any competent body and/or court conducting credible investigations or seeking\nto gather information on individuals or institutions pursuant to a United Nations mandate."},{"id":"a-hrc-36-54-p0080","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"80","seq":81,"section":"D. Accountability mechanisms","text":"In view of the lack of independence of the Burundian judiciary and the impunity\nenjoyed in respect of the gross violations committed by agents of the State and members of\nthe ruling party, including the Imbonerakure, the Commission believes that the Burundian\nState is neither willing nor able genuinely to investigate or prosecute those violations. 46 It\ntherefore falls to the International Criminal Court to investigate those violations and\nestablish criminal responsibility in respect thereof."},{"id":"a-hrc-36-54-p0081","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"81","seq":82,"section":"A. Main conclusions","text":"In the light of its investigations, the Commission finds that extrajudicial\nexecutions, arbitrary arrests and detentions, enforced disappearances, acts of torture\nand cruel, inhuman or degrading treatment and sexual violence have persisted in\nBurundi from April 2015 to the time when the present report was drafted."},{"id":"a-hrc-36-54-p0082","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"82","seq":83,"section":"A. Main conclusions","text":"The Commission has reasonable grounds to believe that several of these\nviolations, committed mostly by members of the National Intelligence Service, the\npolice, the army and the Imbonerakure, constitute crimes against humanity."},{"id":"a-hrc-36-54-p0083","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"83","seq":84,"section":"A. Main conclusions","text":"The Commission notes that the democratic space has been considerably\nreduced since 2015 and a climate of deep fear is affecting Burundians even in the\ncountries to which they have fled. In the Commission’s view, the risk that the refugees\nmight be subjected to gross violations of human rights if they are sent back to\nBurundi necessitates strict respect for the principle of non-refoulement47 on the part\nof the host countries."},{"id":"a-hrc-36-54-p0084","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"84","seq":85,"section":"B. Recommendations","text":"On the basis of the above conclusions, the Commission recommends as follows:\n1.         The Burundian authorities should:"},{"id":"a-hrc-36-54-p0085","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"85","seq":86,"section":"B. Recommendations","text":"Put an immediate end to the gross human rights violations being committed by\nagents of the State and Imbonerakure over which the State exercises control;"},{"id":"a-hrc-36-54-p0086","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"86","seq":87,"section":"B. Recommendations","text":"Investigate these violations, ensure that their alleged perpetrators are\nprosecuted promptly in accordance with credible, independent and fair procedures\nand that the victims obtain just reparation and, where the alleged perpetrators are\nagents of the State, suspend them from their duties pending the completion of the\ninvestigation and the judicial proceedings;"},{"id":"a-hrc-36-54-p0087","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"87","seq":88,"section":"B. Recommendations","text":"Take practical measures to bring about a rapid improvement in the human\nrights situation, in particular by:\n• Withdrawing the warrants for the arrest of heads of media outlets, civil society\norganizations and political parties who have neither used nor advocated\nviolence, and permitting their safe return to Burundi;\n• Lifting the suspension and reversing the revocation of the licences of media and\ncivil society organizations, permitting them to resume their activities with\ncomplete independence and reviewing the laws adopted in 2017 concerning\nnon-profit organizations and foreign non-governmental organizations;\n• Immediately releasing all political prisoners;\n• Ensuring that criminal investigation officers (officiers de police judiciaire) are\nnot authorized to conduct searches without a warrant, including at night, as\nenvisaged in the draft amendments to the Criminal Code and the Code of\nCriminal Procedure;\n• Ensuring that individuals lacking legal authorization, particularly\nImbonerakure, do not perform or participate in law enforcement activities,\nincluding in places of detention, and do not wear military or police uniforms or\npossess weapons;\n• Prosecuting individuals who incite hatred or violence;\n47   Article 33, paragraph 1, of the Convention relating to the Status of Refugees.\n• Putting an end to threats, intimidation and acts of extortion by agents of the\nState and Imbonerakure;\n• Giving victims of sexual violence and torture access to medical and\npsychosocial services;"},{"id":"a-hrc-36-54-p0088","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"88","seq":89,"section":"B. Recommendations","text":"Undertake a thorough reform of the judiciary;"},{"id":"a-hrc-36-54-p0089","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"89","seq":90,"section":"B. Recommendations","text":"Ensure that members of the defence and security forces respect human rights\nin all circumstances and serve the interests of the population as a whole, not solely\nthose of the ruling party;"},{"id":"a-hrc-36-54-p0090","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"90","seq":91,"section":"B. Recommendations","text":"Reconsider their decision to withdraw from the Rome Statute, cooperate fully\nwith the International Criminal Court in the ongoing preliminary examination and, if\nan investigation is initiated, continue that cooperation, inter alia by ensuring the\nprotection of victims and witnesses;"},{"id":"a-hrc-36-54-p0091","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"91","seq":92,"section":"B. Recommendations","text":"Authorize the Office of the United Nations High Commissioner for Human\nRights to resume its documentation of human rights violations in Burundi, which has\nbeen suspended since October 2016;"},{"id":"a-hrc-36-54-p0092","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"92","seq":93,"section":"B. Recommendations","text":"Sign and implement the memorandum of understanding with the African\nUnion and permit the full deployment of 100 human rights observers and 100 military\nexperts that was decided upon in 2016;"},{"id":"a-hrc-36-54-p0093","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"93","seq":94,"section":"B. Recommendations","text":"Cooperate with United Nations human rights mechanisms by once again\nreceiving special procedures missions and implementing the recent recommendations\nof treaty bodies;"},{"id":"a-hrc-36-54-p0094","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"94","seq":95,"section":"B. Recommendations","text":"Actively seek a lasting solution to the political crisis, inter alia through\ninternational initiatives to promote dialogue.\n2.     Political parties and armed opposition groups should:"},{"id":"a-hrc-36-54-p0095","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"95","seq":96,"section":"B. Recommendations","text":"Put an immediate end to human rights abuses and acts of violence committed\nby their members;"},{"id":"a-hrc-36-54-p0096","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"96","seq":97,"section":"B. Recommendations","text":"Refrain from any incitement of violence and participate in the quest for a\nlasting solution to the political crisis in Burundi.\n3.     The Human Rights Council should:"},{"id":"a-hrc-36-54-p0097","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"97","seq":98,"section":"B. Recommendations","text":"Extend the Commission’s mandate for a period of one year to enable it to\nconduct further and more thorough investigations in view of the persistence of gross\nhuman rights violations and abuses and the absence of other specific mechanisms\ncapable of undertaking independent and thorough investigations into the human\nrights situation in Burundi;"},{"id":"a-hrc-36-54-p0098","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"98","seq":99,"section":"B. Recommendations","text":"Request the Office of the United Nations High Commissioner for Human\nRights to report, at the forthcoming sessions of the Council, on the development of its\ncooperation with the Burundian Government.\n4.     The International Criminal Court should:"},{"id":"a-hrc-36-54-p0099","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"99","seq":100,"section":"B. Recommendations","text":"Initiate, as soon as possible, an investigation into the crimes committed in\nBurundi in the light of the conclusions contained in the present report and other\ninformation at its disposal.\n5.     The United Nations Security Council should:"},{"id":"a-hrc-36-54-p0100","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"100","seq":101,"section":"B. Recommendations","text":"Take due account of the Commission’s conclusions, as well as the persistence of\ngross violations of human rights, in any discussion on Burundi and, in this context,\nensure the effective implementation of resolution 2303 (2016);"},{"id":"a-hrc-36-54-p0101","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"101","seq":102,"section":"B. Recommendations","text":"Refer to the International Criminal Court any international crime that might\nbe committed in Burundi after 27 October 2017;"},{"id":"a-hrc-36-54-p0102","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"102","seq":103,"section":"B. Recommendations","text":"Impose individual sanctions on the principal alleged perpetrators of gross\nhuman rights violations and international crimes in Burundi.\n6.    The Secretary-General of the United Nations should:"},{"id":"a-hrc-36-54-p0103","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"103","seq":104,"section":"B. Recommendations","text":"Ensure that respect for human rights and restoration of the rule of law are\namong the priorities of his Special Envoy for Burundi;"},{"id":"a-hrc-36-54-p0104","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"104","seq":105,"section":"B. Recommendations","text":"Ensure that no alleged perpetrator of human rights violations or international\ncrimes in Burundi is recruited for United Nations peacekeeping missions.\n7.    The States Members of the United Nations should:"},{"id":"a-hrc-36-54-p0105","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"105","seq":106,"section":"B. Recommendations","text":"Grant prima facie refugee status to Burundian asylum seekers and ensure strict\nrespect for the principle of non-refoulement and refugee protection;"},{"id":"a-hrc-36-54-p0106","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"106","seq":107,"section":"B. Recommendations","text":"Prosecute, in accordance with the principle of universal jurisdiction, alleged\nperpetrators of international crimes committed in Burundi who are found to be in\ntheir territory;"},{"id":"a-hrc-36-54-p0107","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"107","seq":108,"section":"B. Recommendations","text":"Maintain, in the absence of any improvement in the human rights situation in\nBurundi, the individual sanctions and the suspension of direct aid to the Government;"},{"id":"a-hrc-36-54-p0108","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"108","seq":109,"section":"B. Recommendations","text":"Provide technical assistance, inter alia in respect of autopsies, exhumations and\nidentification of bodies, to enable the Burundian authorities to conduct credible and\nindependent investigations;"},{"id":"a-hrc-36-54-p0109","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"109","seq":110,"section":"B. Recommendations","text":"Support the establishment of specialized medical and psychosocial services,\nespecially for victims of torture and sexual violence;"},{"id":"a-hrc-36-54-p0110","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"110","seq":111,"section":"B. Recommendations","text":"Support the Burundian authorities in any judicial and security sector reform\nendeavours that they might wish to undertake in order to improve the human rights\nsituation.\n8.    The African Union should:"},{"id":"a-hrc-36-54-p0111","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"111","seq":112,"section":"B. Recommendations","text":"Retake the lead in seeking a lasting solution to the crisis in Burundi based on\nrespect for human rights and rejection of impunity, as provided for in its Constitutive\nAct, and play an active role in that process;"},{"id":"a-hrc-36-54-p0112","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"112","seq":113,"section":"B. Recommendations","text":"Ensure that no agent of the Burundian State who is accused of human rights\nviolations or international crimes is recruited for African Union peacekeeping\nmissions;"},{"id":"a-hrc-36-54-p0113","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"113","seq":114,"section":"B. Recommendations","text":"Ensure that the full complement of African Union human rights observers and\nmilitary experts is deployed rapidly in Burundi;"},{"id":"a-hrc-36-54-p0114","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"114","seq":115,"section":"B. Recommendations","text":"Consider, in the event that the current situation in Burundi persists, the\napplication of article 4 (h) of the Constitutive Act of the African Union, under which it\nis authorized to intervene in a member State in certain circumstances, particularly in\nthe event of crimes against humanity.\n9.    The East African Community should:"},{"id":"a-hrc-36-54-p0115","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"115","seq":116,"section":"B. Recommendations","text":"Ensure that a rapid improvement of the human rights situation is a priority in\nits mediation efforts."},{"id":"a-hrc-36-54-p0116","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"116","seq":117,"section":"10. The guarantors of the Arusha Agreement of 2000, in their capacity as committed","text":"Meet with a view to finding a lasting solution to the political and human rights\ncrisis in Burundi."},{"id":"a-hrc-36-54-p0001-a1","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"1","seq":118,"section":"II. Correspondence with the Government of Burundi","text":"Note verbale sent to the Permanent Mission of Burundi on 20 December 2016","annex":1},{"id":"a-hrc-36-54-p0002-a1","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"2","seq":119,"section":"II. Correspondence with the Government of Burundi","text":"Note verbale sent to the Permanent Mission of Burundi on 24 January 2017","annex":1},{"id":"a-hrc-36-54-p0003-a1","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"3","seq":120,"section":"II. Correspondence with the Government of Burundi","text":"Note verbale dated 26 January 2017 from the Permanent Mission of Burundi","annex":1},{"id":"a-hrc-36-54-p0004-a1","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"4","seq":121,"section":"II. Correspondence with the Government of Burundi","text":"Note verbale sent to the Permanent Mission of Burundi on 6 February 2017, together\nwith a letter addressed to the Burundian Minister for Foreign Affairs and\nInternational Cooperation","annex":1},{"id":"a-hrc-36-54-p0005-a1","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"5","seq":122,"section":"II. Correspondence with the Government of Burundi","text":"Note verbale sent to the Permanent Mission of Burundi on 13 March 2017","annex":1},{"id":"a-hrc-36-54-p0006-a1","rec_id":"recVpCf1yoUHf8o3q","symbol":"A/HRC/36/54","n":"6","seq":123,"section":"II. Correspondence with the Government of Burundi","text":"Note verbale sent to the Permanent Mission of Burundi on 20 March 2017, together\nwith a letter addressed to the Burundian Minister for Foreign Affairs and\nInternational Cooperation","annex":1},{"id":"a-hrc-36-crp-1-u0000","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":null,"seq":0,"section":"V. Annexes……………………………………………………………………………. 203","text":"Acronymes\nAPI         Appui à la protection des institutions\nAPRODH      Association pour la protection des droits de l’homme et des personnes\ndétenues\nBAE         Brigade anti-émeute\nBGC         Bataillon de génie de combat\nBNUB        Bureau des Nations Unies au Burundi\nBSPI        Brigade spéciale de protection des institutions\nCADHP       Charte africaine des droits de l’homme et des peuples\nCAE         Communauté des États d’Afrique de l’Est\nCCT         Convention contre la torture et autres peines ou traitements cruels,\ninhumains ou dégradants\nCDE         Convention relative aux droits de l'enfant\nCDPH        Convention relative aux droits des personnes handicapées\nCEDF        Convention sur l'élimination de toutes les formes de discrimination à\nl'égard des femmes\nCEPGL       Communauté économique des pays des Grands Lacs\nCIEDR       Convention internationale sur l'élimination de toutes les formes de\ndiscrimination raciale\nCIRGL       Conférence internationale pour la région des Grands Lacs\nCJAE        Cour de justice de l’Afrique de l’Est\nCNARED      Conseil national pour le respect de l’Accord d’Arusha et la restauration\nd’un État de droit au Burundi\nCNC         Conseil national de la communication\nCNDD-FDD    Conseil national pour la défense de la démocratie-Forces de défense de\nla démocratie\nCNDI        Commission nationale pour le dialogue inter-burundais\nCNIDH       Commission nationale indépendante des droits de l’homme\nCPI         Cour pénale internationale\nEINUB       Enquête indépendante des Nations Unies sur le Burundi\nFAB         Forces armées burundaises\nFDNB        Forces de défense nationales du Burundi\nFOREBU      Forces républicaines du Burundi\nFNL         Forces nationales de libération\nGMIR        Groupe mobile d’intervention rapide\nHCDH        Haut-Commissariat des Nations Unies aux droits de l’homme\nMENUB       Mission d'observation électorale des Nations Unies au Burundi","unnumbered":true},{"id":"a-hrc-36-crp-1-u0001","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":null,"seq":1,"section":"V. Annexes……………………………………………………………………………. 203","text":"MSD               Mouvement pour la solidarité et le développement\nONG               Organisation non gouvernementale\nPIDCP             Pacte international relatif aux droits civils et politiques\nPIDESC            Pacte international relatif aux droits économiques, sociaux et culturels\nPNB               Police nationale burundaise\nRED-Tabara        Résistance pour un État de droit - Tabara\nSNR               Service national de renseignement\nUA                Union africaine\nUE                Union européenne\nUPD-Zigamibanga Union pour la paix et le développement-Zigamibanga","unnumbered":true},{"id":"a-hrc-36-crp-1-p0001","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"1","seq":2,"section":"A. Mandat","text":"Résolution 33/24 du Conseil des droits de l’homme"},{"id":"a-hrc-36-crp-1-p0002","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"2","seq":3,"section":"A. Mandat","text":"Le paragraphe 23 de la résolution 33/24 du Conseil des droits de l’homme précise que\nle Conseil des droits de l’homme « décide d’établir, pour une période d’un an, une\ncommission d’enquête chargée d’accomplir les tâches suivantes :\na) Mener une enquête approfondie sur les violations des droits de l’homme et atteintes\nà ces droits commises au Burundi depuis avril 2015, notamment pour en évaluer\nl’ampleur et déterminer s’il s’agit de crimes de droit international, afin de contribuer à\nla lutte contre l’impunité ;\nb) Identifier les auteurs présumés de violations des droits de l’homme et d’atteintes à\nces droits commises au Burundi, en vue de faire pleinement respecter le principe de\nresponsabilité ;\nc) Formuler des recommandations sur les mesures à prendre pour garantir que les\nauteurs de ces actes aient à en répondre, quelle que soit leur affiliation ;\nd) Dialoguer avec les autorités burundaises et toutes les autres parties prenantes, en\nparticulier les organismes des Nations Unies, la société civile, les réfugiés, la présence\ndu Haut-Commissariat au Burundi, les autorités de l’Union africaine et la Commission\nafricaine des droits de l’homme et des peuples, afin de fournir l’appui et les conseils\nnécessaires à l’amélioration immédiate de la situation des droits de l’homme et à la\nlutte contre l’impunité [...] »."},{"id":"a-hrc-36-crp-1-p0003","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"3","seq":4,"section":"A. Mandat","text":"Le 22 novembre 2016, le Président du Conseil des droits de l’homme a annoncé avoir\nnommé comme membres de la Commission d’enquête sur le Burundi : Fatsah Ouguergouz\n(Algérie), Président de la Commission, Reine Alapini Gansou (Bénin) et Françoise Hampson\n(Royaume-Uni)1."},{"id":"a-hrc-36-crp-1-p0004","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"4","seq":5,"section":"A. Mandat","text":"Le paragraphe 25 de la résolution 33/24 du Conseil des droits de l’homme précise que\n« toutes les ressources nécessaires à l’exécution [du] mandat [de la Commission seront]\nfournies par le Haut-Commissariat [des Nations Unies aux droits de l’homme] ». À cet effet,\nle Haut-Commissariat des Nations Unies aux droits de l’homme (HCDH) a mis à la\ndisposition de la Commission un secrétariat avec les compétences spécialisées ainsi que\nl’assistance administrative, technique et logistique nécessaire à l’accomplissement de son\nmandat."},{"id":"a-hrc-36-crp-1-p0005","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"5","seq":6,"section":"2. Interprétation du mandat","text":"Les membres de la Commission d’enquête se sont réunis une première fois du 23 au\n27 janvier 2017 à Genève. Ils ont à cette occasion interprété le champ d’application du\nmandat qui leur a été confié par le Conseil des droits de l’homme.\n(a)       Compétence matérielle (ratione materiae)"},{"id":"a-hrc-36-crp-1-p0006","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"6","seq":7,"section":"2. Interprétation du mandat","text":"Le paragraphe 23 (a) de la résolution 33/24 précise que la Commission mènera « une\nenquête approfondie sur les violations des droits de l’homme et atteintes à ces droits\ncommises au Burundi [...] notamment pour en évaluer l’ampleur et déterminer s’il s’agit de\ncrimes de droit international »."},{"id":"a-hrc-36-crp-1-p0007","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"7","seq":8,"section":"2. Interprétation du mandat","text":"Par « violations des droits de l’homme », la résolution vise, selon la définition\ncourante, toutes les violations, par des agents ou entités étatiques, des droits garantis par la\nlégislation nationale et le droit international. Par « atteintes » aux droits de l’homme, la\nrésolution renvoie, conformément à la pratique actuelle, aux exactions commises par des\nentités non-étatiques organisées avec une structure connue, ou leurs membres."},{"id":"a-hrc-36-crp-1-p0008","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"8","seq":9,"section":"2. Interprétation du mandat","text":"Étant donné l’ampleur de son mandat et du délai relativement bref qui lui a été imparti\npour le mettre en œuvre, la Commission a décidé de se concentrer en priorité sur les\nviolations des droits de l’homme et les atteintes à ceux-ci les plus graves, en particulier celles\nqui sont susceptibles de constituer des crimes de droit international. Le Conseil des droits de\nl’homme lui a demandé en effet d’évaluer l’ampleur des violations et atteintes commises au\nBurundi et de « déterminer s’il s’agit de crimes de droit international »2. La Commission a\ninterprété l’expression « crimes de droit international » comme les « crimes les plus graves\nqui touchent l’ensemble de la communauté internationale », tels que définis dans le Statut de\nRome3. Dans le présent rapport, la Commission s’est attachée à mettre l’accent sur certains\ncas et événements emblématiques.\n(b)       Compétence personnelle (ratione personae)"},{"id":"a-hrc-36-crp-1-p0009","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"9","seq":10,"section":"2. Interprétation du mandat","text":"Le paragraphe 23 (b) de la résolution 33/24 charge la Commission d’« identifier les\nauteurs présumés de violations des droits de l’homme et d’atteintes à ces droits commises au\nBurundi, en vue de faire pleinement respecter le principe de responsabilité »."},{"id":"a-hrc-36-crp-1-p0010","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"10","seq":11,"section":"2. Interprétation du mandat","text":"La Commission a pris soin de distinguer entre la responsabilité en matière de droits de\nl’homme qui ne concerne que l’État du Burundi pour les actes commis par ses agents ou des\nindividus ou groupes agissant sous son autorité ou son contrôle4 et les responsabilités\nindividuelles en matière de droit pénal international5. À cet égard, la Commission a, dans la\nmesure du possible, cherché à identifier les auteurs présumés des crimes de droit international\net les chaînes de commandement afin d’établir notamment la responsabilité des chefs\nmilitaires ou des supérieurs hiérarchiques prévue par le Statut de Rome6."},{"id":"a-hrc-36-crp-1-p0011","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"11","seq":12,"section":"2. Interprétation du mandat","text":"Le Conseil des droits de l’homme s’est en particulier déclaré « profondément\npréoccupé par les informations selon lesquelles la plupart des violations et des atteintes sont\ncommises par les forces de sécurité burundaises et les Imbonerakure (membres de la ligue\ndes jeunes du parti au pouvoir), dans un climat d’impunité »7. Néanmoins, dans un souci\nd’impartialité, la Commission a tenu à examiner les allégations de violations des droits de\nl’homme et les atteintes à ceux-ci commises par toutes les parties – non seulement les forces\nde sécurité étatiques et les autorités gouvernementales, mais également les groupes armés, ou\nleurs membres, au Burundi8.\n(c)        Compétence territoriale (ratione loci)"},{"id":"a-hrc-36-crp-1-p0012","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"12","seq":13,"section":"2. Interprétation du mandat","text":"Le paragraphe 23, alinéas (a) et (b), de la résolution 33/24 circonscrit le champ\nd’application géographique de la Commission d’enquête aux violations des droits de\nl’homme et atteintes à ceux-ci « au Burundi », c’est-à-dire commises sur le territoire du\nBurundi, ce qui inclut un examen des atteintes commises sur le sol burundais par des entités\nnon-étatiques, ou leurs membres, basés à l’étranger.\n(d)        Compétence temporelle (ratione temporis)"},{"id":"a-hrc-36-crp-1-p0013","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"13","seq":14,"section":"2. Interprétation du mandat","text":"Le paragraphe 23 (a) de la résolution 33/24 précise que la Commission mènera « une\nenquête approfondie sur les violations des droits de l’homme et atteintes à ces droits\ncommises au Burundi depuis avril 2015 [...] ». La résolution fixe donc clairement le début du\nmandat de la Commission qui coïncide avec les premières manifestations contre la\ncandidature de Pierre Nkurunziza à l’élection présidentielle. En raison des exigences\néditoriales, la Commission a dû finaliser son rapport au Conseil des droits de l’homme fin\njuillet 20179. Néanmoins, elle a continué ses enquêtes après cette date. Les résultats de\nl’ensemble de ces enquêtes sont reflétés dans le présent document."},{"id":"a-hrc-36-crp-1-p0014","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"14","seq":15,"section":"2. Interprétation du mandat","text":"Les membres de la Commission sont conscients qu’un travail d’observation et\nd’enquête sur les violations des droits de l’homme et atteintes à ceux-ci commises depuis\navril 2015 au Burundi a déjà été mené par le Bureau du Haut-Commissariat aux droits de\nl’homme dans le pays et par l’Enquête indépendante des Nations Unies sur le Burundi\n(EINUB) établie par la résolution A/HRC/S-24/1 du Conseil des droits de l’homme. La\nCommission a donc pris en compte les conclusions du Haut-Commissaire aux droits de\nl’homme présentées dans son rapport à la trente-deuxième session du Conseil des droits de\nl’homme en juin 201610 et par l’EINUB dans son rapport présenté à la trente-troisième\nsession du Conseil des droits de l’homme en septembre 201611. La Commission est\nnéanmoins un organe indépendant. Elle a donc mené ses propres enquêtes et a\nsystématiquement vérifié et corroboré les informations recueillies par les organes et\nmécanismes qui ont mené avant elle des investigations sur la situation au Burundi. La\nCommission a en outre un mandat qui couvre une période plus longue puisqu’il s’étend\njusqu’à septembre 2017."},{"id":"a-hrc-36-crp-1-p0015","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"15","seq":16,"section":"B. Coopération avec la Commission","text":"Au paragraphe 24 de la résolution 33/24, le Conseil des droits de l’homme « demande\ninstamment au Gouvernement burundais de coopérer pleinement avec la commission\nd’enquête, de l’autoriser à effectuer des visites dans le pays et de lui fournir toutes les\ninformations nécessaires à l’exécution de son mandat ». En dépit de cette disposition, le\nGouvernement du Burundi, pourtant membre du Conseil des droits de l’homme et de ce fait\ntenu de coopérer avec les organes mis en place par celui-ci, a refusé toute coopération avec la\nCommission pendant la durée de son mandat."},{"id":"a-hrc-36-crp-1-p0016","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"16","seq":17,"section":"B. Coopération avec la Commission","text":"Lors du dialogue interactif sur le Burundi à la trente-troisième session du Conseil des\ndroits de l’homme le 27 septembre 2016, le Représentant permanent du Burundi a\npubliquement déploré le contexte de la mise en place de la Commission en notant que la\nrésolution 33/24 avait été adoptée « injustement et scandaleusement [...] sans la moindre\ncoopération ni consensus [du Burundi] malgré sa réclamation insistante ». Il a déclaré qu’il\nserait « impossible que la Commission travaille avec le Burundi quand on connaît les\nconditions de sa mise en place »."},{"id":"a-hrc-36-crp-1-p0017","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"17","seq":18,"section":"B. Coopération avec la Commission","text":"De son côté, la Commission a cherché à plusieurs reprises depuis le début de son\nmandat à engager un dialogue avec les autorités burundaises, comme cela lui est\nexpressément demandé par la résolution 33/2413. Le 20 décembre 2016, la Commission a\nadressé une première note verbale à la Mission permanente du Burundi à Genève pour\ndemander une audience avec le Représentant permanent, suivie d’une seconde note verbale le\n24 janvier 2017. Le 26 janvier 2017, la Mission permanente du Burundi a fait savoir par note\nverbale à la Commission que, le Burundi ayant rejeté la résolution 33/24 du Conseil des\ndroits de l’homme, elle n’était pas disposée à recevoir les membres de la Commission."},{"id":"a-hrc-36-crp-1-p0018","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"18","seq":19,"section":"B. Coopération avec la Commission","text":"Le 6 février 2017, la Commission a adressé une lettre au Ministre des relations\nextérieures et de la coopération du Burundi appelant le Gouvernement burundais à lui donner\naccès au territoire du Burundi afin de dialoguer avec les autorités nationales et de mener à\nbien ses enquêtes. Elle a également invité le Gouvernement à lui faire parvenir toutes les\ninformations qu’il jugerait utile à une appréciation objective de la situation des droits de\nl’homme au Burundi. Cette lettre est restée sans réponse. Dans une autre correspondance\nadressée au Ministre des relations extérieures du Burundi le 20 mars 2017, la Commission,\nsoucieuse de recueillir le point de vue du Gouvernement du Burundi, a une nouvelle fois\nappelé les autorités burundaises à partager avec elle toute information qu’elles jugeraient\nutiles sur la situation des droits de l’homme dans le pays depuis avril 2015. En particulier,\nelle a demandé des informations détaillées sur les atteintes aux droits de l’homme commises\nà l’encontre de membres du Gouvernement ou du parti au pouvoir, le Conseil national pour la\ndéfense de la démocratie-Forces de défense de la démocratie (CNDD-FDD), d’autorités\nadministratives ou de membres des forces de sécurité burundaises14. La Commission a\négalement exprimé son souhait de recueillir des informations portant sur d’éventuelles\nenquêtes ou poursuites judiciaires qui auraient été menées à propos de ces atteintes et de leurs\nauteurs présumés. Cette lettre est régalement restée sans réponse15."},{"id":"a-hrc-36-crp-1-p0019","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"19","seq":20,"section":"B. Coopération avec la Commission","text":"Suite à la première présentation orale de la Commission d’enquête à la trente-\nquatrième session du Conseil des droits de l’homme le 13 mars 2017, le Représentant\npermanent du Burundi a déclaré que sa délégation n’était « pas d’accord ni avec son contenu\nni avec la procédure de sa confection ni avec le processus de la mise sur pied de la\nCommission qui l’a confectionnée » et que la déclaration de la Commission reprenait « toutes\nles fausses allégations contenues dans le rapport de EINUB ». Le Représentant permanent du\nBurundi a affirmé que son Gouvernement avait envoyé des commentaires sur le rapport de\nl’EINUB mais que ceux-ci n’ont jamais été pris en compte. Il a jugé que tant que le\ncontentieux avec l’EINUB ne serait pas soldé, il serait impossible pour son Gouvernement de\ntravailler avec la Commission16. Le Représentant permanent du Burundi a repris la même\nargumentation à la trente-cinquième session du Conseil des droits de l’homme en juin 2017\ndurant laquelle la Commission a fait sa seconde présentation orale17."},{"id":"a-hrc-36-crp-1-p0020","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"20","seq":21,"section":"B. Coopération avec la Commission","text":"Le 28 août 2017, la Commission a envoyé une copie de son rapport à la Mission\npermanente du Burundi à Genève, une semaine avant sa publication officielle. La Mission\npermanente n’a pas accusé réception de ce courrier. Cependant, plusieurs représentants du\nGouvernement burundais et du parti au pouvoir ont publiquement critiqué le contenu du\nrapport de la Commission, notamment sur les médias sociaux. Le 12 septembre 2017, le\nporte-parole du Gouvernement du Burundi, Philippe Nzobonariba, a tenu une conférence de\npresse durant laquelle il a souligné que la Commission avait été créée « illégalement » sans\nl’accord des autorités burundaises en vue de répondre à un « agenda caché » destiné à\ndégrader l’image du Burundi. Il a également reproché à la Commission de ne s’être basée que\nsur des témoignages recueillis en dehors du Burundi auprès de « criminels » qui avaient fui le\npays, et de ne pas avoir enquêté sur les attaques par des groupes armés commises sur le sol\nburundais18. Le 14 septembre 2017, la Commission a eu connaissance de commentaires du\nGouvernement du Burundi sur son rapport qui ne lui ont toutefois pas été adressés\ndirectement19. Ces commentaires sont néanmoins reproduits en annexe20."},{"id":"a-hrc-36-crp-1-p0021","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"21","seq":22,"section":"2. Coopération d’autres États avec la Commission","text":"S’inspirant de la pratique d’autres commissions d’enquête qui se sont vu refuser\nl’accès au territoire couvert par leur mandat, la Commission s’est rendue dans les pays\nvoisins du Burundi afin de rencontrer des victimes, des témoins et d’autres sources, et a\négalement mené des entretiens dans plusieurs autres pays où se trouvent des réfugiés\nburundais. La Commission tient à cet égard à remercier les Gouvernements de l’Ouganda, de\nla République démocratique du Congo, du Rwanda et de la Tanzanie pour lui avoir donné\naccès à leurs territoires, ainsi que les autres États et organisations qui ont bien voulu faciliter\nla mise en œuvre de son mandat."},{"id":"a-hrc-36-crp-1-p0022","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"22","seq":23,"section":"1. Sources","text":"La Commission a collecté des informations auprès d’un large éventail de sources.\nBien que le Gouvernement du Burundi ne lui ait pas accordé l’accès au territoire burundais,\nla Commission a recueilli des informations auprès de personnes basées au Burundi, ainsi que\ndans plusieurs autres pays. La Commission s’est efforcée autant que possible de mener des\nentretiens en tête à tête avec ces personnes. Cependant, pour des raisons de sécurité, par souci\nde protection des témoins ou du fait de l’absence d’accès au territoire burundais, la\nCommission a été obligée de conduire certains entretiens à distance. Elle a dans ces cas pris\nun soin particulier à vérifier la crédibilité et la véracité des informations recueillies."},{"id":"a-hrc-36-crp-1-p0023","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"23","seq":24,"section":"1. Sources","text":"La pratique des commissions d’enquête et des missions d’établissement des faits\ndistingue entre les « sources primaires » et les « sources secondaires ». Les premières ont une\nvaleur supérieure aux secondes car les informations fournies par ces sources ont été\ndirectement recueillies par la Commission. Les sources secondaires, pour leur part, servent à\ncorroborer les sources primaires ou à fournir des éléments permettant de mieux comprendre\nle contexte dans lequel les violations des droits de l’homme et les atteintes à ceux-ci ont été\ncommises."},{"id":"a-hrc-36-crp-1-p0024","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"24","seq":25,"section":"1. Sources","text":"La Commission a considéré comme sources primaires, entre autres :\n• Les témoignages de victimes de violations des droits de l’homme et d’atteintes à ceux-\nci, de témoins oculaires, de membres de la famille ou des connaissances proches des\nvictimes ayant des informations directes sur les événements en question ;\n• Les témoignages d’autres personnes ayant des informations directes et fiables sur des\nviolations des droits de l’homme ou des atteintes à celles-ci, ou sur les circonstances\ndans lesquelles elles ont été commises ou commanditées ;\n• Les déclarations d’auteurs présumés de violations des droits de l’homme ou\nd’atteintes à ceux-ci ;\n• Les images satellites, les photos, vidéos et documents sonores provenant de sources\nfiables et que la Commission a été en mesure d’authentifier ;\n• Les documents qui appuient les témoignages directs, tels que des documents médicaux\nattestant de blessures de victimes, des correspondances, des copies de jugements ou\nd’autres documents juridiques ;\n• Les informations publiques et officielles, telles que les lois, règlements, directives,\ndéclarations, ainsi que d’autres documents et politiques officiels du Gouvernement du\nBurundi."},{"id":"a-hrc-36-crp-1-p0025","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"25","seq":26,"section":"1. Sources","text":"La Commission a considéré les sources suivantes, entre autres, comme secondaires :\n• Les soumissions qui ont été faites à la Commission, notamment suite à l’appel à\ninformations publié sur sa page internet21 ;\n• Les rapports des Nations Unies, d’États, d’organisations non gouvernementales\n(ONG), d’instituts de recherche, ou de toute autre entité que la Commission a jugés\ncrédibles et fiables sur la situation des droits de l’homme au Burundi ;\n• Les entretiens que la Commission a eus avec des personnes fiables et crédibles ayant\ndéveloppé une expertise sur le Burundi et la situation des droits de l’homme dans ce\npays ;\n• Les entretiens menés par d’autres personnes ou d’autres organisations mais que la\nCommission n’a pas eu l’occasion de corroborer elle-même."},{"id":"a-hrc-36-crp-1-p0026","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"26","seq":27,"section":"1. Sources","text":"Au total, la Commission a conduit plus de 500 entretiens avec des victimes, témoins et\nautres sources. Elle a également reçu plusieurs communications écrites contenant des\ninformations ou des allégations sur des violations des droits de l’homme. Les conclusions\ncontenues dans le présent rapport sont étayées par des références en bas de page aux\nentretiens conduits par la Commission qu’elle a considérés comme fiables et crédibles22.\nDans un souci de protection des victimes et des témoins, les sources ne sont pas identifiées\ndans ce rapport. La grande majorité des personnes avec lesquelles la Commission s’est\nentretenue se sont exprimées à la condition que leur témoignage soit traité en toute\nconfidentialité. Ce souhait a dans la majorité des cas été motivé par la crainte de représailles\nainsi que par le climat plus général de peur régnant au Burundi. Pour les mêmes raisons, la\nCommission a choisi de ne pas inclure d’autres détails en sa possession qui permettraient\nl’identification des victimes ou témoins, par exemple les lieux précis, les dates exactes ou les\ncirconstances particulières de certains événements."},{"id":"a-hrc-36-crp-1-p0027","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"27","seq":28,"section":"2. Standard de preuve","text":"La Commission a décidé d’adopter le même niveau de preuve que la majorité des\ncommissions d’enquête internationales en matière de droits de l’homme, à savoir des « motifs\nraisonnables de croire »23. Cela implique que, pour fonder ses conclusions, la Commission a\nveillé à réunir un corps d'informations fiables et concordantes, sur la base duquel une\npersonne raisonnable et normalement prudente aurait des raisons de croire qu’un incident ou\nun comportement systématique a eu lieu. Ce niveau de preuve est moins élevé que celui\nretenu par les tribunaux pour conclure à la culpabilité d’une personne ou établir la\nresponsabilité d’un État, c’est-à-dire une absence « de tout doute raisonnable »24. Il s’agit\nnéanmoins du même niveau de preuve permettant par exemple à la Chambre préliminaire de\nla Cour pénale internationale (CPI) de délivrer, sur requête du Procureur, un mandat d’arrêt\nou une citation à comparaître à l’encontre d’une personne25."},{"id":"a-hrc-36-crp-1-p0028","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"28","seq":29,"section":"2. Standard de preuve","text":"Dans cette optique, la Commission a attaché un soin particulier à corroborer les\nnombreuses informations qui lui ont été soumises ou qu’elle a recueillies. Cela a consisté à\nvérifier chacune de ces informations en cherchant à obtenir des informations concordantes\nauprès d’au moins deux autres sources indépendantes et fiables et, dans le cas où cela s’est\navéré impossible, d’écarter l’information initiale. Cette exigence de corroboration n’a\ntoutefois pas toujours été nécessaire ou possible. Une information fournie par une source\nprimaire fiable n’a dans certains cas besoin d’être corroborée que par une seule source\nsupplémentaire indépendante et fiable, qui peut inclure les propres constatations de\nl’enquêteur26. Dans d’autres cas, par exemple pour des actes de violence sexuelle ou de\ntorture, il peut être très difficile d’obtenir la corroboration du récit de la victime auprès d’une\nautre source indépendante, en particulier si la victime n’a pas bénéficié d’une assistance\nmédicale. Dans de tels cas, la corroboration a pu être obtenue en évaluant les détails du récit\nde la victime et sa crédibilité, en tentant de déterminer s’ils correspondent aux informations\ndisponibles dans le domaine public et en établissant si les actes font apparaître un schéma qui\ncorrespond à d’autres cas similaires27."},{"id":"a-hrc-36-crp-1-p0029","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"29","seq":30,"section":"2. Standard de preuve","text":"En tout état de cause, la Commission ne s’est jamais basée uniquement sur des\ninformations publiées ou sur des témoignages recueillis par d’autres organisations, que ce\nsoit des agences des Nations Unies, des ONG burundaises ou internationales, ou d’autres\nentités. Lorsque les informations recueillies par ces sources semblaient fournir des pistes\npertinentes, la Commission a systématiquement vérifié elle-même ces informations avant de\nles confirmer ou de les infirmer."},{"id":"a-hrc-36-crp-1-p0030","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"30","seq":31,"section":"3. Protection des victimes et des témoins","text":"En règle générale, le Gouvernement de l’État concerné par une enquête internationale\nest le principal responsable de la protection des personnes ayant échangé des informations\navec l’organe chargé de l’enquête. Dans le cas présent, le Gouvernement du Burundi ayant\nrefusé de coopérer avec la Commission et ne lui ayant pas donné accès à son territoire, la\nquestion de la responsabilité du Burundi en matière de protection des victimes et des témoins\navec qui la Commission a été en contact est difficilement envisageable."},{"id":"a-hrc-36-crp-1-p0031","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"31","seq":32,"section":"3. Protection des victimes et des témoins","text":"En outre, des allégations de représailles et de menaces contre des Burundais ayant\ncollaboré par le passé avec des mécanismes internationaux des droits de l’homme, ou ayant\ntémoigné auprès de représentants des Nations Unies, d’ONG ou de journalistes, ont incité la\nCommission à attacher une attention particulière à la protection des victimes, des témoins et\nde toutes autres sources. La Commission a à cet effet développé des procédures basées sur\nles standards établis par le Haut-Commissariat des Nations Unies aux droits de l’homme\n(HCDH)28, eux-mêmes articulés autour des principes directeurs d’innocuité29, de\nconfidentialité, et de participation30. La Commission a également veillé à ne pas faire des\npromesses intenables en matière de protection aux personnes avec qui elle a été en contact.\nQuand les risques encourus de représailles, ou la perception de ces risques, étaient trop\ngrands pour une personne désireuse de collaborer avec elle, la Commission a\nsystématiquement décidé de ne pas recueillir le témoignage de la personne en question afin\nde ne pas l’exposer à un danger supplémentaire, réel ou supposé."},{"id":"a-hrc-36-crp-1-p0032","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"32","seq":33,"section":"4. Sauvegarde et archivage des informations","text":"À l’instar d’autres commissions d’enquête et missions d’établissement des faits, la\nCommission a utilisé une base de données confidentielle et sécurisée mise à sa disposition\npar le HCDH. La transcription des entretiens menés par la Commission, ainsi que l’ensemble\nde la documentation qu’elle a rassemblée, sont sauvegardés dans cette base de données. Seuls\nles membres de la Commission et de son secrétariat ont eu accès à la base de données\npendant la durée du mandat de la Commission, le HCDH n’assurant que l’appui technique\nnécessaire."},{"id":"a-hrc-36-crp-1-p0033","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"33","seq":34,"section":"4. Sauvegarde et archivage des informations","text":"La Commission a fait le choix de ne pas publier dans le présent rapport la liste des\nauteurs présumés qu’elle a pu identifier. Cette liste est disponible dans la base de données\ndont la garde, à l’issue du mandat de la Commission, sera confiée au Haut-Commissaire des\nNations Unies aux droits de l’homme. La Commission autorise le Haut-Commissaire aux\ndroits de l’homme à partager les informations contenues dans la base de données avec tout\norgane et toute juridiction compétents qui mèneront des enquêtes indépendantes et crédibles\nen vue de faire la lumière sur les violations des droits de l’homme et les atteintes à ceux-ci\ncommises au Burundi, ou qui chercheront à réunir des informations sur des individus ou des\ninstitutions en application d’un mandat des Nations Unies. Cependant, l’accès aux\ninformations contenues dans la base de données ne devra être accordé que dans la mesure où\nles témoins auront préalablement donné leur accord au partage des informations contenues\ndans leurs témoignages."},{"id":"a-hrc-36-crp-1-p0034","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"34","seq":35,"section":"D. Droit applicable","text":"Le Burundi est un État de tradition moniste dans lequel les normes contenues dans les\ntraités internationaux font théoriquement partie intégrante du corpus juridique national et\npeuvent donc en principe être directement invoquées devant les juridictions nationales. Le\ndroit international applicable aux évènements relevant du mandat de la Commission recouvre\nle droit international des droits de l’homme et le droit pénal international."},{"id":"a-hrc-36-crp-1-p0035","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"35","seq":36,"section":"D. Droit applicable","text":"Le droit international humanitaire n’est pour sa part pas pertinent. Il s’applique en\neffet dans le cadre des conflits armés internationaux ou non internationaux dont les\ndéfinitions sont données par les Conventions de Genève de 1949 et leurs Protocoles\nadditionnels, auxquels le Burundi est partie. Les conflits armés internationaux opposent deux\nÉtats ou plus31, tandis que les conflits armés non internationaux sont caractérisés par des\naffrontements entre des forces gouvernementales et des groupes armés non\ngouvernementaux, ou entre groupes armés."},{"id":"a-hrc-36-crp-1-p0036","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"36","seq":37,"section":"D. Droit applicable","text":"L’État burundais n’étant pas engagé dans un conflit interétatique, la Commission s’est\ndemandé si la situation prévalant dans le pays depuis avril 2015 ne pouvait pas être qualifiée\nde conflit armé non international du fait notamment de plusieurs attaques menées par des\ngroupes armés sur le sol burundais. Sur ce point, l’article 3 commun aux Conventions de\nGenève se réfère aux conflits armés « ne présentant pas un caractère international et\nsurgissant sur le territoire de l’une des Hautes Parties contractante ». L’article 1 (2) du\nDeuxième Protocole additionnel aux Conventions de Genève relatif à la protection des\nvictimes des conflits armés non internationaux précise pour sa part qu’il « ne s'applique pas\naux situations de tensions internes, de troubles intérieurs, comme les émeutes, les actes isolés\net sporadiques de violence et autres actes analogues, qui ne sont pas considérés comme des\nconflits armés ». Or, l’examen des attaques menées ou revendiquées par des groupes armés\nau Burundi depuis avril 2015 fait clairement ressortir leur caractère isolé et sporadique, ne\npermettant pas à la Commission de conclure à l’existence d’un conflit armé non international\nau Burundi pendant la période couverte par son mandat32."},{"id":"a-hrc-36-crp-1-p0037","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"37","seq":38,"section":"1. Droit international des droits de l’homme","text":"L’article 19 de la Constitution du Burundi dispose que « les droits et devoirs\nproclamés et garantis, entre autres, par la Déclaration universelle des droits de l’homme, les\nPactes internationaux relatifs aux droits de l’homme, la Charte africaine des droits de\nl’homme et des peuples, la Convention sur l’élimination de toutes les formes de\ndiscrimination à l’égard des femmes et la Convention relative aux droits de l’enfant font\npartie intégrante de la Constitution de la République du Burundi »33. Toutefois, dans\nbeaucoup d’États de tradition moniste comme le Burundi, les normes de droit international\nsont dans les faits rarement prises en compte par les magistrats.\n(a)        Conventions à vocation universelle"},{"id":"a-hrc-36-crp-1-p0038","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"38","seq":39,"section":"1. Droit international des droits de l’homme","text":"Le Burundi est partie à sept des principaux instruments internationaux en matière de\ndroits de l’homme, à savoir :\n• le Pacte international relatif aux droits civils et politiques (PIDCP)34,\n• le Pacte international relatif aux droits économiques, sociaux et culturels (PIDESC)35,\n• la Convention internationale sur l'élimination de toutes les formes de discrimination\nraciale (CIEDR)36,\n• la Convention contre la torture et autres peines ou traitements cruels, inhumains ou\ndégradants (CCT) et son protocole facultatif37,\n• la Convention sur l'élimination de toutes les formes de discrimination à l'égard des\nfemmes (CEDF)38,\n• la Convention relative aux droits de l'enfant (CDE) et ses deux protocoles facultatifs39,\net\n• la Convention relative aux droits des personnes handicapées (CDPH) et son protocole\nfacultatif40."},{"id":"a-hrc-36-crp-1-p0039","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"39","seq":40,"section":"1. Droit international des droits de l’homme","text":"En ratifiant la CCT, le Burundi a accepté la procédure d’enquête prévue à l’article 20\nde la Convention et la procédure de plainte individuelle prévue à l’article 22. De la même\nmanière, le Burundi a accepté la procédure de plainte individuelle prévue par la CDPH."},{"id":"a-hrc-36-crp-1-p0040","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"40","seq":41,"section":"1. Droit international des droits de l’homme","text":"En sa qualité de partie aux traités susmentionnés, le Burundi est tenu de coopérer avec\nles organes de mise en œuvre établis sur la base de ces traités.\nOrganes de traités"},{"id":"a-hrc-36-crp-1-p0041","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"41","seq":42,"section":"1. Droit international des droits de l’homme","text":"Ces dernières années, le Gouvernement du Burundi a soumis plusieurs rapports\npériodiques à des organes de traités, notamment au Comité relatif aux droits de l’enfant en\n2010, au Comité des droits de l’homme en 2014 et au Comité des droits économiques,\nsociaux et culturels en 201541."},{"id":"a-hrc-36-crp-1-p0042","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"42","seq":43,"section":"1. Droit international des droits de l’homme","text":"En décembre 2015, le Comité contre la torture, qui avait déjà examiné le Burundi en\n201442, a demandé au Gouvernement du Burundi de lui soumettre un rapport spécial43 afin de\nrépondre aux allégations de violation grave de la CCT rapportées notamment par le Haut-\nCommissaire des Nations Unies aux droits de l’homme et le Conseiller spécial du Secrétaire\ngénéral des Nations Unies pour la prévention du génocide. Le Gouvernement du Burundi a\ntransmis ce rapport au Comité en juin 2016. Une délégation gouvernementale burundaise,\ndirigée par la Ministre de la justice, a participé à la première séance d’examen du rapport le\n28 juillet 2016, mais, cas unique, ne s’est pas présentée à la seconde séance le 29 juillet 2016,\npendant laquelle elle devait répondre aux questions formulées par les membres du Comité\nlors de la première séance. Le même jour, le Gouvernement du Burundi a fait savoir par note\nverbale au Comité que, selon lui, le dialogue avec les membres du Comité portait sur des\npoints et un rapport soumis par la société civile qui n’avaient pas été partagés avec lui\npréalablement et, en conséquence, demandait plus de temps pour l’examiner44. Par note\nverbale du 29 juillet 2016, le Comité a contesté ces arguments tout en appelant le\nGouvernement du Burundi à poursuivre le dialogue. Dans ses observations finales45, le\nComité a regretté ce manque de coopération et a par ailleurs exprimé « sa profonde\npréoccupation » suite à la procédure de radiation de l’ordre des avocats ouverte à la demande\ndu Procureur général près la Cour d’appel de Bujumbura à l’encontre de quatre avocats qui\navaient contribué à la rédaction d’un rapport alternatif soumis au Comité46. Il a également\ndemandé au Gouvernement du Burundi de lui soumettre, avant le 12 octobre 2016, un rapport\nspécial de suivi sur toutes les mesures prises pour mettre en œuvre l’ensemble des\nrecommandations formulées dans ses observations finales. Le Gouvernement burundais lui a\nenvoyé un rapport dans le délai prévu. Selon le Comité, il s’agit néanmoins davantage d’une\nréponse aux préoccupations soulevées par le Comité lors de la considération du rapport\nspécial que d’un suivi des recommandations formulées à cette occasion47."},{"id":"a-hrc-36-crp-1-p0043","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"43","seq":44,"section":"1. Droit international des droits de l’homme","text":"Le Gouvernement du Burundi a présenté le 26 octobre 2016 ses cinquième et sixième\nrapports périodiques au Comité pour l'élimination de la discrimination à l'égard des femmes\nqui a déploré que le climat d’instabilité politique depuis avril 2015 avait contribué à une\naugmentation des violences sexuelles et basées sur le genre par des agents des corps de\ndéfense et de sécurité et des Imbonerakure48. En 2016, le Comité pour l'élimination de toutes\nles formes de discrimination raciale a, à deux reprises, lors de ses 90ème (août 2016) et 91ème\n(novembre-décembre 2016) sessions, utilisé sa procédure d’alerte précoce et de mesures\nurgentes au sujet de la situation des droits de l’homme au Burundi.49\nConseil des droits de l’homme"},{"id":"a-hrc-36-crp-1-p0044","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"44","seq":45,"section":"1. Droit international des droits de l’homme","text":"Le Burundi est membre du Conseil des droits de l’homme depuis 2015 et ce jusqu’en\n2018. Le 2 octobre 2015, à sa trentième session, le Conseil des droits de l’homme a adopté\nune résolution exprimant sa préoccupation quant à la situation des droits de l’homme au\nBurundi50 et demandant au Haut-Commissaire des Nations Unies aux droits de l’homme de\nfaire un exposé oral à sa trente-et-unième session, en mars 2016, et de présenter un rapport\nécrit à sa trente-deuxième session, en juin 201651."},{"id":"a-hrc-36-crp-1-p0045","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"45","seq":46,"section":"1. Droit international des droits de l’homme","text":"Le Conseil des droits de l’homme a organisé, le 17 décembre 2015, une session\nspéciale sur le Burundi durant laquelle il a demandé au Haut-Commissaire aux droits de\nl’homme « d’organiser d’urgence et de dépêcher le plus rapidement possible une mission\ncomposée d’experts indépendants » afin d'entreprendre une enquête sur les violations des\ndroits de l’homme et les atteintes à ceux-ci commises au Burundi depuis avril 201552. Ces\nexperts53 se sont rendus au Burundi en mars et en juin 2016, avant d’être déclarés personae\nnon grata par les autorités burundaises suite à la présentation de leur rapport. Ce rapport54,\nprésenté à la trente-troisième session du Conseil des droits de l’homme en septembre 2016, a\nservi de base à la résolution 33/24 établissant la présente Commission.\nProcédures spéciales"},{"id":"a-hrc-36-crp-1-p0046","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"46","seq":47,"section":"1. Droit international des droits de l’homme","text":"En 2013, le Gouvernement du Burundi a formulé une invitation permanente aux\ntitulaires de mandat au titre des procédures spéciales. Suite à cette invitation, le Rapporteur\nspécial sur les défenseurs des droits de l’homme a visité le pays en novembre 201455 et le\nRapporteur spécial pour la promotion de la vérité, de la justice, de la réparation et des\ngaranties de non-répétition en décembre 201456. L’Expert indépendant sur les questions\nrelatives aux minorités et le Groupe de travail sur les disparitions forcées ou involontaires ont\ndemandé à visiter le Burundi en 2009 sans obtenir de réponse positive de la part des autorités.\nEn août 2015, le Rapporteur spécial sur les exécutions extrajudiciaires, sommaires ou\narbitraires a fait à son tour une demande de visite qui n’a pas non plus reçu de réponse\nfavorable. Le Gouvernement burundais a en revanche accepté la demande d’invitation\nformulée en 2010 par le Rapporteur spécial sur l'indépendance des juges et des avocats, mais\nce dernier n’a pas été en mesure d’effectuer une visite à ce jour57.\nl'enfant concernant l'implication d'enfants dans les conflits armés, et depuis le 6 décembre 2009 pour le\nProtocole facultatif à la Convention relative aux droits de l'enfant, concernant la vente d'enfants, la\nprostitution des enfants et la pornographie mettant en scène des enfants).\n(b)      Conventions à vocation régionale et sous-régionale"},{"id":"a-hrc-36-crp-1-p0047","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"47","seq":48,"section":"1. Droit international des droits de l’homme","text":"Aux niveaux régional et sous-régional, le Burundi est membre de l’Union africaine\n(UA), ainsi que de la Communauté des États d’Afrique de l’Est (CAE), de la Communauté\néconomique des pays des Grands Lacs (CEPGL) et de la Conférence internationale pour la\nrégion des Grands Lacs (CIRGL), dont le siège est à Bujumbura.\nDroit régional"},{"id":"a-hrc-36-crp-1-p0048","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"48","seq":49,"section":"1. Droit international des droits de l’homme","text":"Dans le cadre de l’UA, le Burundi est partie à la Charte africaine des droits de\nl’homme et des peuples (CADHP)58 et à son protocole portant création de la Cour africaine\ndes droits de l'homme et des peuples59, à la Charte africaine des droits et du bien-être de\nl'enfant60, ainsi qu’à la Convention de l’UA régissant les aspects propres aux problèmes des\nréfugiés en Afrique61. Le Burundi a par ailleurs signé mais n’a pas encore ratifié la Charte\nafricaine de la démocratie, des élections et de la gouvernance62 ainsi que le Protocole à la\nCharte africaine des droits de l'homme et des peuples relatif aux droits des femmes en\nAfrique63.\nDroit sous-régional"},{"id":"a-hrc-36-crp-1-p0049","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"49","seq":50,"section":"1. Droit international des droits de l’homme","text":"L’article 6 du traité instituant la CAE, signé le 30 novembre 1999 à Arusha en\nTanzanie, prévoit que « la bonne gouvernance y compris l’adhésion aux principes de la\ndémocratie, de la primauté du droit, de la responsabilité, de la transparence, de la justice\nsociale, de l’égalité des chances, de l’égalité des hommes et des femmes ainsi que la\nreconnaissance, la promotion et la protection des droits de l’homme et des peuples\nconformément aux dispositions de la Charte africaine des droits de l’homme et des peuples »\nfigurent parmi les principes fondamentaux de la CAE. Le Traité instituant la CAE a par\nailleurs établi une Cour de justice de l’Afrique de l’Est (CJAE) dont la tâche est de veiller à\nce que les États membres de la CAE se conforment aux dispositions du Traité64. Dénuée d’un\nmandat spécifique sur les droits de l’homme, la CJAE a cependant développé une\njurisprudence en matière de droits de l’homme en se basant notamment sur la CADHP65.\nfurther deterioration of the human rights situation in Burundi, 17 décembre 2015 ; « Des experts de\nl’ONU se félicitent de l’appel du Conseil de Sécurité sur le Burundi et exhortent à des actions concrètes\n», 13 novembre 2015 ; “Burundi and Sri Lanka, two test cases for the prevention of recurring mass\nviolations – UN expert” ; 15 septembre 2015 ; Burundi : Un expert de l'ONU demande la protection de\ntous les défenseurs des droits de l’homme après la tentative d'assassinat contre un activiste de premier\nplan, 7 août 2015 ; Burundi: UN experts call for determined Security Council action to prevent mass\nviolence in the Great Lakes region, 16 juillet 2015 ; “Tradition of impunity’ threatens Burundi’s future,\nrenders free elections impossible – UN expert warns”, 19 juin 2015 ; « La jeune démocratie du Burundi\nmise à risque par les violences pré-électorales, préviennent des experts de l’ONU », 30 avril 2015."},{"id":"a-hrc-36-crp-1-p0050","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"50","seq":51,"section":"1. Droit international des droits de l’homme","text":"Le Burundi a adhéré au Pacte sur la paix, la stabilité et le développement dans la\nrégion des Grands Lacs, signé à Nairobi en décembre 2006 et entré en vigueur en juin 2008.\nLe Pacte inclut 10 protocoles juridiquement contraignants, parmi lesquels le Protocole sur la\ndémocratie et la bonne gouvernance, le Protocole sur la prévention et la répression du crime\nde génocide, des crimes de guerre et des crimes contre l’humanité et de toute forme de\ndiscrimination, le Protocole sur la prévention et la répression de la violence sexuelle à l’égard\ndes femmes et des enfants, et le Protocole sur la protection et l’assistance aux personnes\ndéplacées."},{"id":"a-hrc-36-crp-1-p0051","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"51","seq":52,"section":"2. Droit pénal international","text":"En matière de droit pénal international, le Burundi est partie à la Convention pour la\nprévention et la répression du crime de génocide. Le Burundi est également partie au Statut\nde Rome de la Cour pénale internationale (CPI) qu’il a ratifié le 21 septembre 2004. C’est sur\ncette dernière base que, le 25 avril 2016, le Procureur de la CPI a ouvert une procédure\nd’examen préliminaire afin de déterminer si des crimes relevant de la compétence de la Cour\nauraient été commis depuis avril 2015 au Burundi66."},{"id":"a-hrc-36-crp-1-p0052","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"52","seq":53,"section":"2. Droit pénal international","text":"Le 27 octobre 2016, le Gouvernement du Burundi a notifié au Secrétaire général des\nNations Unies, dépositaire du Statut de Rome, son intention de se retirer de ce traité. Cette\nnotification n’a cependant pas eu d’incidence sur le mandat de la Commission, l’article 127\ndu Statut de Rome prévoyant que le retrait d’un État ne le dégage pas des obligations mises à\nsa charge alors qu'il était partie au Statut. Le retrait n’étant effectif qu’une année après sa\nnotification, il n’aura, dans le cas du Burundi, pas lieu avant le 27 octobre 2017. La\nCommission a donc basé son travail sur le Statut de Rome qui est resté en vigueur tout au\nlong de son mandat."},{"id":"a-hrc-36-crp-1-p0053","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"53","seq":54,"section":"2. Droit pénal international","text":"Dans son travail de qualification des violations et des atteintes commises depuis avril\n2015 au Burundi, la Commission s’est également référée au droit international coutumier67 et\nà la jurisprudence des juridictions internationales, notamment à celle des tribunaux pénaux\npour l’ex-Yougoslavie (TPIY) et le Rwanda (TPIR)."},{"id":"a-hrc-36-crp-1-p0054","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"54","seq":55,"section":"2. Droit pénal international","text":"Le paragraphe 23 (a) de la résolution 33/24 du Conseil des droits de l’homme\ndemande à la Commission d’évaluer l’ampleur des violations des droits de l’homme et des\natteintes à ceux-ci commises au Burundi depuis avril 2015 et de déterminer s’il s’agit de\ncrimes de droit international. Par « crimes de droit international », la Commission a compris\nles « crimes les plus graves qui touchent l’ensemble de la communauté internationale » tels\nqu’ils sont définis dans l’article 5 (1) du Statut de Rome, à savoir: le crime de génocide, les\ncrimes contre l’humanité, les crimes de guerre et le crime d’agression.\n(a)        Crime de génocide"},{"id":"a-hrc-36-crp-1-p0055","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"55","seq":56,"section":"2. Droit pénal international","text":"Le crime de génocide est défini à l’article 6 du Statut de Rome qui dispose qu’ « on\nentend par crime de génocide l’un quelconque des actes ci-après commis dans l’intention de\ndétruire, en tout ou en partie, un groupe national, ethnique, racial ou religieux, comme tel:\na) Meurtre de membres du groupe ;\nb) Atteinte grave à l’intégrité physique ou mentale de membres du groupe ;\nc) Soumission intentionnelle du groupe à des conditions d’existence devant entraîner\nsa destruction physique totale ou partielle ;\nd) Mesures visant à entraver les naissances au sein du groupe ;\ne) Transfert forcé d’enfants du groupe à un autre groupe »68."},{"id":"a-hrc-36-crp-1-p0056","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"56","seq":57,"section":"2. Droit pénal international","text":"Dans cette définition, l’élément intentionnel (mens rea) est primordial. Dans l’affaire\nKayishema et Ruzindana, le TPIR a considéré que « pour que le crime de génocide soit\nconstitué, il faut que la mens rea requise existe avant la commission des actes, encore que la\npréméditation ne constitue pas un critère au regard des divers actes perpétrés, la seule\ncondition exigée étant que l’acte soit commis pour donner effet à l’intention de génocide »69.\nLa jurisprudence des tribunaux pénaux internationaux et de la CPI a précisé les facteurs à\nprendre en considération pour conclure à l’intention de l’auteur du crime de génocide,\nl’existence d’un plan précis n’étant pas nécessairement requise bien qu’elle puisse constituer\nune preuve de cette intention70."},{"id":"a-hrc-36-crp-1-p0057","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"57","seq":58,"section":"2. Droit pénal international","text":"La volonté de destruction doit viser « tout ou partie » d’un groupe. Par cette\nexpression, le Statut de Rome entend préciser que l’anéantissement effectif du groupe tout\nentier n’est pas requis. L’intention de détruire doit viser un nombre assez élevé ou au moins\nune partie substantielle du groupe, comme cela a pu être rappelé par exemple par le TPIR\ndans les affaires Kayishema et Ruzindana et Bagilishema71. Le groupe visé doit être « un\ngroupe national, ethnique, racial ou religieux »72."},{"id":"a-hrc-36-crp-1-p0058","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"58","seq":59,"section":"2. Droit pénal international","text":"Le Statut de Rome, tout comme la Convention pour la prévention et la répression du\ncrime de génocide, précise que l’intention doit être de détruire « en tout ou en partie, un\ngroupe national, ethnique, racial ou religieux, comme tel ». Par cette dernière expression, le\ndroit international pénal insiste sur le fait que la ou les victimes de l’acte sont choisies non\npas en fonction de leur identité individuelle mais en raison de leur appartenance au groupe73."},{"id":"a-hrc-36-crp-1-p0059","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"59","seq":60,"section":"2. Droit pénal international","text":"L’article III de la Convention pour la prévention et la répression du crime de génocide\nprécise par ailleurs que seront punis non seulement l’acte constitutif de crime de génocide\nmais également « l’entente en vue de commettre le génocide », « la tentative de génocide », «\nla complicité dans le génocide », ainsi que « l’incitation directe et publique à commettre le\ngénocide ». La Convention pour la prévention et la répression du crime de génocide prévoit\nen outre que l’État contractant a l’obligation à la fois de réprimer et de prévenir le crime de\ngénocide, « qu’il soit commis en temps de paix ou en temps de guerre »74.\n(b)        Crimes contre l’humanité"},{"id":"a-hrc-36-crp-1-p0060","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"60","seq":61,"section":"2. Droit pénal international","text":"Les crimes contre l’humanité sont, au titre de l’article 7 (1) du Statut de Rome, des\nactes « commis dans le cadre d’une attaque généralisée ou systématique lancée contre toute\npopulation civile et en connaissance de cette attaque ». Les actes visés à l’article 7 (1) du\nStatut de Rome incluent:\na) le meurtre,\nb) l’extermination,\nc) la réduction en esclavage,\nd) la déportation ou le transfert forcé de population,\ne) l’emprisonnement ou toute autre forme de privation grave de liberté physique en\nviolation des dispositions fondamentales du droit international,\nf) la torture,\ng) le viol,\nh) l’esclavage sexuel,\ni) la prostitution forcée,\nj) la grossesse forcée, la stérilisation forcée ou toute autre forme de violence sexuelle\nde gravité comparable,\nk) la persécution de tout groupe ou de toute collectivité identifiable pour des motifs\nd’ordre politique, racial, national, ethnique, culturel, religieux ou sexiste, ou en\nfonction d’autres critères universellement reconnus comme inadmissibles en droit\ninternational,\nl) les disparitions forcées de personnes,\nm) le crime d’apartheid, et\nn) les autres actes inhumains de caractère analogue causant intentionnellement de\ngrandes souffrances ou des atteintes graves à l’intégrité physique ou à la santé\nphysique ou mentale75."},{"id":"a-hrc-36-crp-1-p0061","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"61","seq":62,"section":"2. Droit pénal international","text":"« L’attaque » peut comporter plusieurs des actes énumérés ci-dessus76. Elle doit être\n« généralisée ou systématique », ces deux conditions n’étant pas cumulatives. L’attaque pour\nêtre généralisée doit être menée à grande échelle et toucher une pluralité de victimes77. Il n’y\na cependant pas de seuil minimum établi pour définir cette échelle. Le caractère systématique\nrenvoie quant à lui à la nature organisée des actes de violence qui se manifeste par l’existence\nd’une politique ou d’un plan préconçu, sans que cette politique ou ce plan n’ait été\nnécessairement adopté officiellement par l’État78."},{"id":"a-hrc-36-crp-1-p0062","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"62","seq":63,"section":"2. Droit pénal international","text":"L’article 7 (1) du Statut de Rome spécifie que l’attaque doit être lancée « contre une\npopulation civile quelconque ». Pour que la population touchée soit qualifiée de civile, il\nsuffit qu’elle soit en majorité composée de civils. Dans l’affaire Kayishema et Ruzindana, le\nTPIR a pu préciser que la présence de certains non-civils au sein de la population ciblée ne\nmodifiait en rien son caractère civil79."},{"id":"a-hrc-36-crp-1-p0063","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"63","seq":64,"section":"2. Droit pénal international","text":"Enfin, le Statut de Rome mentionne que l’attaque doit être menée « en connaissance\nde cause ». Dans l’affaire Kayishema et Ruzindana, le TPIR a précisé : « L’auteur des crimes\ncontre l’humanité doit avoir agi en connaissance de cause, c’est-à-dire qu’il doit comprendre\nle contexte général dans lequel s’inscrit son acte [...]. Autrement dit, [l’auteur] doit savoir que\nson acte est partie intégrante d’une attaque généralisée et systématique contre la population\ncivile et qu’il a été accompli pour donner effet à une politique ou à un plan donnés »80.\n(c)        Crimes de guerre et d’agression"},{"id":"a-hrc-36-crp-1-p0064","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"64","seq":65,"section":"2. Droit pénal international","text":"Les crimes de guerre définis à l’article 8 du Statut de Rome peuvent avoir lieu dans le\ncadre de conflits armés internationaux ou non internationaux. Le crime d’agression, prévu\npour sa part à l’article 8 bis du Statut de Rome, ne peut avoir lieu qu’à l’occasion d’un conflit\narmé international. La Commission ayant conclu à l’inexistence d’un conflit armé au Burundi\npendant la période couverte par son mandat, elle n’a pas examiné l’existence possible de\ncrimes de guerre ou d’agression au Burundi."},{"id":"a-hrc-36-crp-1-p0065","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"65","seq":66,"section":"E. Responsabilités","text":"Le paragraphe 23 (b) de la résolution 33/24 charge la Commission d’« identifier les\nauteurs présumés de violations des droits de l’homme et d’atteintes à ces droits commises au\nBurundi, en vue de faire pleinement respecter le principe de responsabilité ». La Commission\na interprété cette disposition comme lui demandant d’examiner la question des\nresponsabilités à la fois sous l’angle du droit international des droits de l’homme pour les\nviolations et atteintes aux droits de l’homme et sous celui du droit pénal international pour les\ncrimes de droit international81."},{"id":"a-hrc-36-crp-1-p0066","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"66","seq":67,"section":"1. Responsabilité en droit international des droits de l’homme","text":"Les normes relatives à la protection des droits de l’homme font partie intégrante du\ndroit international qui prévoit que tout fait internationalement illicite de l’État engage sa\nresponsabilité internationale82. Il y a fait internationalement illicite lorsqu’un comportement,\nqui peut consister en une action ou une omission, est attribuable à un État en vertu du droit\ninternational et constitue une violation d’une obligation internationale de cet État83.\n(b)        Attribution d’un comportement"},{"id":"a-hrc-36-crp-1-p0067","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"67","seq":68,"section":"1. Responsabilité en droit international des droits de l’homme","text":"Le Projet d’articles sur la responsabilité de l’État pour fait internationalement illicite,\nadopté en 2001 par la Commission du droit international (CDI)84, envisage plusieurs cas de\nfigure susceptibles d’entraîner la responsabilité d’un État, parmi lesquels le comportement\nillicite d’un de ses organes, quelle que soit sa fonction – « législative, exécutive, judiciaire ou\nautre » –, la position qu’il occupe dans l’organisation de l’État, ou sa nature – qu’il soit un\norgane du gouvernement central ou d’une collectivité territoriale85. L’État peut être par\nailleurs tenu responsable pour « le comportement d’une personne ou entité qui n’est pas un\norgane de l’État [...] mais qui est habilitée par le droit de cet État à exercer des prérogatives\nde puissance publique [...] »86. L’État est également partiellement responsable pour les actes\ncommis par ses propres agents de concert avec des agents ou des entités non-étatiques."},{"id":"a-hrc-36-crp-1-p0068","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"68","seq":69,"section":"1. Responsabilité en droit international des droits de l’homme","text":"Si la responsabilité de l’État est engagée, comme cela vient d’être décrit, par le\ncomportement de ses agents ou de personnes ou entités qui par leurs prérogatives peuvent\nêtre considérées comme agents étatiques, elle peut être aussi engagée par le comportement\nd’agents ou d’entités non-étatiques. C’est le cas lorsqu’un agent ou une entité non-étatique «\nen adoptant ce comportement, agit en fait sur les instructions ou les directives ou sous le\ncontrôle d’un État »87 ou lorsque l’État reconnaît et adopte un comportement qui ne lui est\npas attribuable88. Sur la notion de contrôle, la jurisprudence internationale n’est pas uniforme.\nLa Cour internationale de justice (CIJ) a retenu la notion de « contrôle effectif »89, tandis que\nle Tribunal pénal international pour l’ex-Yougoslavie (TPIY) a introduit la notion de\n« contrôle global »90. Dans les deux cas cependant, l’État est tenu responsable non seulement\npour la participation de ses agents ou entités au financement, à l’équipement et\nl’entraînement d’un groupe non-étatique, mais aussi pour leur participation à l’organisation,\nla coordination, ou la planification des opérations menées par ce groupe. La différence entre\n« contrôle effectif » et « contrôle global » réside dans le fait que, pour être établi, le premier\nrequiert, contrairement au second, l’émission d’ordres ou d’instructions précises par l’État au\ngroupe non-étatique, ainsi que le contrôle de l’État au cours de chaque opération menée par le\ngroupe91.\n(c)        Violation d’une obligation"},{"id":"a-hrc-36-crp-1-p0069","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"69","seq":70,"section":"1. Responsabilité en droit international des droits de l’homme","text":"Aux termes de l’article 2 du Projet d’articles de la Commission du droit international,\nle comportement d’un État constitutif d’une violation d’une obligation internationale peut\nconsister soit en une action, soit en une omission. L’article 12 du même Projet d’articles\nprécise qu’« il y a violation d’une obligation internationale par un État lorsqu’un fait dudit\nÉtat n’est pas conforme à ce qui est requis de lui en vertu de cette obligation, quelle que soit\nl’origine ou la nature de celle-ci ». L’obligation internationale de l’État peut ainsi être\nd’origine conventionnelle ou coutumière. Quant à sa nature, elle peut consister en une\nobligation de résultat ou de comportement."},{"id":"a-hrc-36-crp-1-p0070","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"70","seq":71,"section":"1. Responsabilité en droit international des droits de l’homme","text":"En droit international des droits de l’homme, les États ont une triple obligation: celle\nde respecter les droits contenus dans les traités des droits de l’homme auxquels ils sont\nparties, celle de protéger les individus contre toute violation ou atteinte à ces droits et celle de\nmettre en œuvre ces droits. Ces obligations peuvent consister soit en une obligation\nd’abstention (obligation négative), soit en une obligation d’agir (obligation positive); le\ncomportement constitutif de la violation de l’obligation internationale de l’État, consistera\nselon les cas soit en une action de celui-ci soit en une omission. L’obligation de respecter les\ndroits de l’homme consiste généralement en une obligation d’abstention, alors que les\nobligations de protéger et de mettre en œuvre ces droits consistent pour leur part en une\nobligation d’agir. À titre d’exemple, la CADHP prévoit que les États parties doivent à la fois\ns’assurer que « toute personne [ait] droit à la jouissance des droits et libertés reconnus et\ngarantis dans la Charte » (article 2) et « s’engag[er] à adopter des mesures législatives ou\nautres pour les appliquer » (article 1)92. De la même manière, l’article 2 du PIDCP précise:\n« 1. Les États parties au présent Pacte s'engagent à respecter et à garantir à tous les\nindividus se trouvant sur leur territoire et relevant de leur compétence les droits\nreconnus dans le présent Pacte, sans distinction aucune, notamment de race, de\ncouleur, de sexe, de langue, de religion, d'opinion politique ou de toute autre opinion,\nd'origine nationale ou sociale, de fortune, de naissance ou de toute autre situation."},{"id":"a-hrc-36-crp-1-u0072","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":null,"seq":72,"section":"2. Les États parties au présent Pacte s'engagent à prendre, en accord avec leurs","text":"procédures constitutionnelles et avec les dispositions du présent Pacte, les\narrangements devant permettre l'adoption de telles mesures d'ordre législatif ou autre,\npropres à donner effet aux droits reconnus dans le présent Pacte qui ne seraient pas\ndéjà en vigueur.\n3. Les États parties au présent Pacte s'engagent à:\na) Garantir que toute personne dont les droits et libertés reconnus dans le\nprésent Pacte auront été violés disposera d'un recours utile, alors même que la\nviolation aurait été commise par des personnes agissant dans l'exercice de leurs\nfonctions officielles;\nb) Garantir que l'autorité compétente, judiciaire, administrative ou législative,\nou toute autre autorité compétente selon la législation de l’État, statuera sur les\ndroits de la personne qui forme le recours et développer les possibilités de\nrecours juridictionnel;\nc) Garantir la bonne suite donnée par les autorités compétentes à tout recours\nqui aura été reconnu justifié ».","unnumbered":true},{"id":"a-hrc-36-crp-1-p0071","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"71","seq":73,"section":"2. Les États parties au présent Pacte s'engagent à prendre, en accord avec leurs","text":"Un État viole donc son obligation de respecter un droit de l’homme garanti par un\ntraité auquel il est partie lorsque l’action d’un de ses agents ou d’un de ses organes porte\natteinte à ce droit. Un État viole également son obligation internationale lorsque l’action qui\nporte atteinte à ce droit est le fait d’agents ou de groupes non-étatiques lorsque ceux-ci\nagissent sur ses instructions ou ses orientations précises, ou encore sur ses directives ou sous\nson contrôle93. La Commission africaine des droits de l’homme et des peuples est quant à elle\nallée plus loin. Dans son commentaire général sur le droit à la vie, elle a considéré que « la\nresponsabilité d’un État peut être engagée en cas de tueries par des acteurs non étatiques s’il\napprouve, soutient ou acquiesce ces actes »94."},{"id":"a-hrc-36-crp-1-p0072","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"72","seq":74,"section":"2. Les États parties au présent Pacte s'engagent à prendre, en accord avec leurs","text":"L’État peut par ailleurs voir sa responsabilité engagée lorsqu’il manque à son\nobligation de protéger les droits de l’homme, notamment quand il a connaissance ou aurait dû\navoir connaissance du risque de commission d’une violation des droits de l’homme ou d’une\natteinte à ceux-ci et qu’il ne prend pas les mesures nécessaires pour prévenir cette violation.\nDans ce cas, l’État n’est pas responsable pour l’acte lui-même mais pour son manquement à\nle prévenir. De la même manière, l’État peut être tenu responsable d’atteintes aux droits de\nl’homme qu’il a laissé commettre sur son territoire par des forces non-étatiques, lorsqu’il n’a\npas pris les mesures nécessaires pour que des enquêtes soient menées sur ces atteintes et que\nleurs auteurs soient arrêtés. L’État est également tenu de veiller à ce que les auteurs de\nviolations répondent de leurs actes devant les juridictions nationales et que les victimes,\nquand cela est nécessaire, reçoivent une compensation.\nSocial and Economic Rights Action Center (SERAC) and Center for Economic and Social Rights\n(CESR) c. Nigeria, 2001."},{"id":"a-hrc-36-crp-1-p0073","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"73","seq":75,"section":"2. Les États parties au présent Pacte s'engagent à prendre, en accord avec leurs","text":"L’État doit également adopter des politiques, des pratiques ainsi qu’un corpus\nnormatif destinés à protéger et assurer le respect des droits de l’homme contenus dans les\ntraités auxquels il est partie. Certaines conventions internationales des droits de l’homme sont\ntrès précises à ce sujet et prévoient même que l’État a l’obligation de pénaliser aussi bien la\nviolation que la tentative, la complicité ou la participation à la commission de la violation.\nC’est par exemple le cas de la Convention contre la torture dont l’article 4 (1) dispose que\n« tout État Partie veille à ce que tous les actes de torture constituent des infractions au regard\nde son droit pénal. Il en est de même de la tentative de pratiquer la torture ou de tout acte\ncommis par n'importe quelle personne qui constitue une complicité ou une participation à\nl'acte de torture ». L’article 20 du PIDCP, en disposant que « tout appel à la haine nationale,\nraciale ou religieuse qui constitue une incitation à la discrimination, à l'hostilité ou à la\nviolence est interdit par la loi », demande également aux États parties de sanctionner en droit\net en fait l’incitation à commettre ces actes."},{"id":"a-hrc-36-crp-1-p0074","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"74","seq":76,"section":"2. Responsabilité en droit pénal international","text":"L’article 25 (2) du Statut de Rome prévoit que: « quiconque commet un crime relevant\nde la compétence de la Cour [pénale internationale] est individuellement responsable et peut\nêtre puni conformément au Statut. » L’article 25 (3) précise les différentes circonstances dans\nlesquelles un individu peut être reconnu responsable: « Aux termes du présent Statut, une\npersonne est pénalement responsable et peut être punie pour un crime relevant de la\ncompétence de la Cour si :\na) Elle commet un tel crime, que ce soit individuellement, conjointement avec une\nautre personne ou par l’intermédiaire d’une autre personne, que cette autre personne\nsoit ou non pénalement responsable ;\nb) Elle ordonne, sollicite ou encourage la commission d’un tel crime, dès lors qu’il y a\ncommission ou tentative de commission de ce crime ;\nc) En vue de faciliter la commission d’un tel crime, elle apporte son aide, son\nconcours ou toute autre forme d’assistance à la commission ou à la tentative de\ncommission de ce crime, y compris en fournissant les moyens de cette commission ;\nd) Elle contribue de toute autre manière à la commission ou à la tentative de\ncommission d’un tel crime par un groupe de personnes agissant de concert. Cette\ncontribution doit être intentionnelle et, selon le cas :\ni) Viser à faciliter l’activité criminelle ou le dessein criminel du groupe, si cette\nactivité ou ce dessein comporte l’exécution d’un crime relevant de la\ncompétence de la Cour; ou\nii) Être faite en pleine connaissance de l’intention du groupe de commettre ce\ncrime ;\ng) S’agissant du crime de génocide, elle incite directement et publiquement autrui à le\ncommettre ;\nh) Elle tente de commettre un tel crime par des actes qui, par leur caractère\nsubstantiel, constituent un commencement d’exécution mais sans que le crime soit\naccompli en raison de circonstances indépendantes de sa volonté. Toutefois, la\npersonne qui abandonne l’effort tendant à commettre le crime ou en empêche de\nquelque autre façon l’achèvement ne peut être punie en vertu du présent Statut pour sa\ntentative »."},{"id":"a-hrc-36-crp-1-p0075","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"75","seq":77,"section":"2. Responsabilité en droit pénal international","text":"Dans tous les cas, l'élément psychologique est déterminant pour établir la\nresponsabilité d'un auteur présumé d'un crime international. L'article 30 (1) du Statut de\nRome dispose en effet : « Nul n'est pénalement responsable et ne peut être puni à raison d'un\ncrime relevant de la compétence de la Cour que si l'élément matériel du crime est commis\navec intention et connaissance ». Conformément au Statut, l’« intention » s’évalue lorsque : «\na) Relativement à un comportement, une personne entend adopter ce comportement ; b)\nRelativement à une conséquence, une personne entend causer cette conséquence ou est\nconsciente que celle-ci adviendra dans le cours normal des événements »95. Quant à la «\nconnaissance », elle est établie quand « une personne est consciente qu’une circonstance\nexiste ou qu’une conséquence adviendra dans le cours normal des événements »96. L’ordre\nhiérarchique ou l’ordre de la loi ne constituent pas une cause d’exonération de responsabilité\npénale97, à moins que l’auteur présumé « n’ait eu l’obligation légale d’obéir aux ordres du\ngouvernement ou du supérieur en question; [...] n’ait pas su que l’ordre était illégal ; et [que]\nl’ordre n’ait pas été manifestement illégal »98. En outre, l’article 27 du Statut de Rome prévoit\nque « la qualité officielle de chef d’État ou de gouvernement, de membre d’un gouvernement\nou d’un parlement, de représentant élu ou d’agent d’un État, n’exonère en aucun cas de la\nresponsabilité pénale au regard du présent Statut [...] »."},{"id":"a-hrc-36-crp-1-p0076","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"76","seq":78,"section":"2. Responsabilité en droit pénal international","text":"Le Statut de Rome prévoit deux cas où un individu peut être tenu responsable pour un\nacte commis par une autre personne : la responsabilité des chefs militaires et celle des\nsupérieurs hiérarchiques. L’article 28 (1) du Statut dispose à cet égard qu’ « un chef militaire\nou une personne faisant effectivement fonction de chef militaire est pénalement responsable\ndes crimes relevant de la compétence de la Cour commis par des forces placées sous son\ncommandement et son contrôle effectifs, ou sous son autorité et son contrôle effectifs, selon\nle cas, lorsqu’il ou elle n’a pas exercé le contrôle qui convenait sur ces forces dans les cas où:\ni) Ce chef militaire ou cette personne savait, ou, en raison des circonstances, aurait dû savoir,\nque ces forces commettaient ou allaient commettre ces crimes ; et ii) Ce chef militaire ou\ncette personne n’a pas pris toutes les mesures nécessaires et raisonnables qui étaient en son\npouvoir pour en empêcher ou en réprimer l’exécution ou pour en référer aux autorités\ncompétentes aux fins d’enquête et de poursuites »99."},{"id":"a-hrc-36-crp-1-p0077","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"77","seq":79,"section":"2. Responsabilité en droit pénal international","text":"La responsabilité hiérarchique ne se limite pas aux forces armées mais s’applique de\nmanière plus générale. L’article 28 (2) prévoit ainsi que « le supérieur hiérarchique est\npénalement responsable des crimes relevant de la compétence de la Cour commis par des\nsubordonnés placés sous son autorité et son contrôle effectifs, lorsqu’il ou elle n’a pas exercé\nle contrôle qui convenait sur ces subordonnés dans les cas où : i) Le supérieur hiérarchique\nsavait que ces subordonnés commettaient ou allaient commettre ces crimes ou a délibérément\nnégligé de tenir compte d’informations qui l’indiquaient clairement ; ii) Ces crimes étaient\nliés à des activités relevant de sa responsabilité et de son contrôle effectifs ; et iii) Le\nsupérieur hiérarchique n’a pas pris toutes les mesures nécessaires et raisonnables qui étaient\nen son pouvoir pour en empêcher ou en réprimer l’exécution ou pour en référer aux autorités\ncompétentes aux fins d’enquête et de poursuites ». Cependant, l'article 33 du Statut de Rome\nprévoyant que l'ordre de commettre le génocide et le crime contre l'humanité est toujours\nmanifestement illégal, le subordonné qui obéit à un tel ordre fera l'objet des poursuites au\nmême titre que le supérieur hiérarchique donneur d'ordre."},{"id":"a-hrc-36-crp-1-p0078","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"78","seq":80,"section":"1. Contexte historique","text":"Depuis son indépendance le 1er juillet 1962, le Burundi a connu une instabilité\npolitique chronique marquée par des vagues de violence, des massacres et des assassinats\npolitiques où le facteur ethnique, instrumentalisé depuis la période coloniale100, a souvent pris\nle dessus101. Ces violences ont culminé en 1972 dans ce que certains auteurs ont qualifié de\ngénocide d’une partie de la population hutue par le Gouvernement burundais à majorité\ntutsie102, puis en 1993 après l’assassinat du Président Melchior Ndayaye, un Hutu\ndémocratiquement élu. L’assassinat du Président Ndadaye par des éléments de l’armée\nburundaise à majorité tutsie a entraîné en représailles des massacres de Tutsis qui ont à leur\ntour déclenché une répression par les forces armées contre la population hutue. Ces\névénements ont été à l’origine d’un conflit armé extrêmement brutal qui a duré environ 15\nans et causé la mort de dizaines de milliers de personnes. La Commission internationale\nd’enquête créée en 1995 en application de la résolution 1012 du Conseil de sécurité des\nNations Unies a conclu à « des actes de génocide perpétrés contre la minorité tutsie »103.\nCertains de ces actes se sont déroulés en parallèle du génocide au Rwanda dont l’élément\ndéclencheur a été l’attentat, le 6 avril 1994, visant l’avion qui transportait le Président\nrwandais, Juvénal Habyarimana, et son homologue burundais, Cyprien Ntaryamira104."},{"id":"a-hrc-36-crp-1-p0079","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"79","seq":81,"section":"1. Contexte historique","text":"Le 28 août 2000, après plusieurs années de négociations, 19 signataires, dont le\nGouvernement burundais de l’époque, l’Assemblée nationale et deux groupes de partis\npolitiques représentant respectivement les Hutus et Tutsis, se sont entendus, sous l’égide du\nPrésident sud-africain Nelson Mandela, sur le texte final de l’Accord d’Arusha pour la paix et\nla réconciliation au Burundi visant à mettre fin à la crise politique persistante et poser les\nbases d’un État de droit dans le pays105. Cet Accord a reconnu l’existence au Burundi d’un\n« conflit fondamentalement politique avec des dimensions ethniques extrêmement\nimportantes »106 et prévu, afin de remédier à cette situation, de mettre en place des quotas\nethniques destinés à répartir équitablement les pouvoirs politiques et les postes dans\nl’administration et les forces de défense et de sécurité entre Hutus et Tutsis. De nombreux\nBurundais considèrent l’Accord d’Arusha, et particulièrement le principe de représentation\nethnique dans les institutions publiques, comme une pierre angulaire de la marche du pays\nvers la paix et la démocratie."},{"id":"a-hrc-36-crp-1-p0080","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"80","seq":82,"section":"1. Contexte historique","text":"Le Conseil national pour la défense de la démocratie-Forces pour la défense de la\ndémocratie (CNDD-FDD), dirigé par Pierre Nkurunziza, et le PALIPEHUTU-Forces\nnationales de libération (FNL) d’Agathon Rwasa n’ont pour leur part signé des accords de\ncessez-le-feu globaux qu’en 2003 et 2006 respectivement107. Les FNL n’ont officiellement\ndéposé leurs armes et ne se sont transformées en parti politique qu’en avril 2009108."},{"id":"a-hrc-36-crp-1-p0081","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"81","seq":83,"section":"2. Contexte politique","text":"L’Accord d’Arusha prévoyait une période de transition de 36 mois. Une nouvelle\nconstitution n’a toutefois été adoptée par référendum qu’en février 2005, puis promulguée le\n18 mars 2005. Pierre Nkurunziza, candidat du CNDD-FDD, a été élu, le 19 août de la même\nannée, Président de la République par le Parlement issu des élections législatives et\nsénatoriales de juillet 2005. En juin 2010, il a été confirmé à la tête de l’État après des\nélections au suffrage universel direct qui ont été boycottées par la plupart des partis\nd’opposition. Ces élections ont été suivies d’une vague d’assassinats politiques visant\nnotamment les membres et anciens membres des FNL109."},{"id":"a-hrc-36-crp-1-p0082","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"82","seq":84,"section":"2. Contexte politique","text":"L’élection à deux reprises de Pierre Nkurunziza à la présidence a été au cœur des\ndébats qui ont conduit à la crise politique de 2015. S’il n’appartient pas à la Commission de\nse prononcer sur une question de constitutionnalité qui n’entre pas dans le cadre de son\nmandat, il est important, pour une meilleure compréhension du contexte politique au\nBurundi, de mentionner que les opposants à la candidature de Pierre Nkurunziza en 2015 se\nsont appuyés sur le texte de l’Accord d’Arusha dont l’article 7 (3) du Protocole II prévoit que\nle Président de la République « est élu pour un mandat de cinq ans renouvelable une seule\nfois. Nul ne peut exercer plus de deux mandats présidentiels ». L’article 96 de la Constitution\nde 2005 reprend le même principe mais en précisant que « le Président de la République est\nélu au suffrage universel direct pour un mandat de cinq ans renouvelable une fois ». Pierre\nNkurunziza ayant été élu en 2005 au suffrage indirect110, ses partisans considèrent sa victoire\nen 2010 comme sa première élection au suffrage universel direct. Pour eux, il était donc\nautorisé à se présenter à l’élection présidentielle de 2015."},{"id":"a-hrc-36-crp-1-p0083","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"83","seq":85,"section":"2. Contexte politique","text":"Le débat sur la question de la candidature éventuelle de Pierre Nkurunziza à l’élection\nprésidentielle de 2015 a débuté bien avant cette date. Le 21 mars 2014, des amendements à la\nConstitution, dont certains avaient été interprétés comme destinés à permettre au Président de\nse présenter « une troisième fois »111 à l’élection présidentielle, ont été rejetés à une voix près\npar l’Assemblée nationale112."},{"id":"a-hrc-36-crp-1-p0084","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"84","seq":86,"section":"2. Contexte politique","text":"Ce débat a entraîné une crispation de la vie politique et des tensions croissantes entre\nle Gouvernement d’une part, les activistes de la société civile et certains médias indépendants\nd’autre part. Déjà, le 8 mars 2014, une marche organisée à Bujumbura par des membres du\nparti d’opposition le Mouvement pour la solidarité et la démocratie (MSD) avait débouché\nsur des accrochages avec la police, ainsi sur que de nombreuses arrestations de membres du\nMSD. Une confrontation le même jour entre la police et des membres du MSD au siège du\nparti à Bujumbura et la prise en otage de deux policiers par des membres du MSD ont\nentraîné une suspension du parti pour six mois et un mandat d’arrêt contre son dirigeant,\nAlexis Sinduhije. À l’issue d’un procès expéditif, qui a eu lieu dans le cadre de la procédure\nde « flagrance », 21 personnes ont été condamnées à la prison à perpétuité et 27 autres, dont\ntrois mineurs, à des peines allant de trois à dix ans de prison. Le 16 mai 2014, le défenseur\ndes droits de l’homme et président de l’Association pour la protection des droits de l’homme\net des personnes détenues (APRODH), Pierre Claver Mbonimpa, a été arrêté et accusé\nd’atteinte à la sécurité de l’État après avoir mentionné à la radio des allégations d’armement\net de formation militaire de jeunes burundais en République démocratique du Congo (RDC)\npar des agents de l’État. Il a finalement été libéré pour raisons médicales le 29 septembre\n2014 sous la pression internationale après être tombé gravement malade en prison. En janvier\n2015, Bob Rugurika, directeur de la Radio publique africaine (RPA), a été arrêté et accusé de\ncomplicité d’assassinat et de plusieurs autres chefs d’accusation après la diffusion d’un\nreportage à la RPA dans lequel une personne interviewée avait impliqué certaines autorités\ndu Service national de renseignement (SNR) dans l’assassinat de trois religieuses italiennes\nau Burundi en 2014. Bob Rugurika a été libéré sous caution un mois plus tard. Les\narrestations de Pierre Claver Mbonimpa et de Bob Rugurika ont provoqué d’importantes\nmanifestations de soutien spontanées.\n(a)     Manifestations contre un nouveau mandat de Pierre Nkurunziza"},{"id":"a-hrc-36-crp-1-p0085","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"85","seq":87,"section":"2. Contexte politique","text":"La question du « troisième mandat » du Président Nkurunziza a monopolisé la vie\npolitique durant les premiers mois de l’année 2015. Au sein même du CNDD-FDD, les\ndissensions ont à maintes reprises repoussé la date du congrès chargé d’investir le candidat à\nl’élection présidentielle. Le 18 février 2015, le Général-Major Godefroid Niyombare, chef du\nSNR, a été limogé après avoir exprimé dans une note interne son désaccord avec le Président\nde la République. Le 25 mars 2015, 17 membres du CNDD-FDD, y compris des membres\ninfluents ou qui occupaient des postes importants au sein du parti, ont envoyé une lettre au\nPrésident de la République pour exprimer leur opposition à l’idée qu’il se porte à nouveau\ncandidat à l’élection présidentielle113. Plusieurs membres du CNDD-FDD ayant\npubliquement pris position contre une nouvelle candidature de Pierre Nkurunziza ont été\nexclus du parti et dans certains cas forcés à l’exil. De leur côté, les partis d’opposition ont\ntenté de s’organiser en deux coalitions qui ont tôt connu des divisions, les empêchant de\ndésigner un candidat commun. En outre, plus de 300 organisations de la société civile ont\nlancé fin janvier 2015 une campagne intitulée « Halte au troisième mandat »."},{"id":"a-hrc-36-crp-1-p0086","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"86","seq":88,"section":"2. Contexte politique","text":"Le 25 avril 2015, Pierre Nkurunziza a finalement été confirmé comme candidat du\nCNDD-FDD à l’élection présidentielle. Cette décision a provoqué dès le lendemain une\nvague de protestations, d’abord à Bujumbura puis dans certaines provinces. Des\nmanifestations importantes ont été dispersées violemment par la police; de nombreux\nmanifestants ont été arrêtés, d’autres ont été tués ou blessés114. Les manifestations ont\nnéanmoins continué dans plusieurs quartiers de Bujumbura, notamment à Cibitoke, Musaga,\nNgagara et Nyakabiga. Le 27 avril 2015, la RPA et la Maison de la presse115 ont été fermées\nsur ordre du Gouvernement116."},{"id":"a-hrc-36-crp-1-p0087","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"87","seq":89,"section":"2. Contexte politique","text":"Le 26 avril 2015, le Sénat a saisi la Cour constitutionnelle d’une requête aux fins d'une\naction en interprétation des articles 96 et 302 de la Constitution sur la possibilité du Chef de\nl’État de briguer un nouveau mandat. Le 5 mai 2015, la Cour constitutionnelle a rendu un\navis favorable117 malgré l’opinion dissidente du Vice-Président de la Cour, Sylvère\nNimpagaritse, qui, après avoir subi des pressions et des menaces, a dû quitter le pays.\n(b)     Tentative de coup d’État"},{"id":"a-hrc-36-crp-1-p0088","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"88","seq":90,"section":"2. Contexte politique","text":"Le 13 mai 2015, le Général-Major Niyombare a annoncé à la radio la destitution du\nPrésident Nkurunziza, profitant d’un déplacement de ce dernier à Dar es Salam pour un\nsommet des chefs d’État de l’EAC. Cette prise de pouvoir a été accueillie favorablement par\nune partie de la population qui est descendue dans les rues de Bujumbura pour fêter le coup\nd’État. Cependant, le 14 mai 2015, des combats ont opposé les militaires qui avaient tenté de\nrenverser le Gouvernement et la partie de l’armée restée loyale au Président. Ces combats se\nsont soldés par une défaite des premiers. Après avoir annoncé l’échec du coup d’État, le\nGénéral-Major Niyombare a réussi à prendre la fuite, mais d’autres officiers supérieurs qui\nauraient participé à la tentative de coup d’État, dont l’ancien Ministre de la défense, le\nGénéral Cyrille Ndayirukiye, et le Commissaire de police Zénon Ndabaneze, ont été arrêtés.\nLe 15 mai 2015, le Président Nkurunziza est rentré au Burundi."},{"id":"a-hrc-36-crp-1-p0089","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"89","seq":91,"section":"2. Contexte politique","text":"Le 18 mai 2015, le mouvement « Halte au troisième mandat » a appelé à poursuivre la\ncontestation. Plusieurs manifestations, principalement à Bujumbura dans les quartiers de\nMusaga, Kanyosha, Cibitoke, Kinama, Nyakabiga, Buyenzi et Ngagara, ont débouché sur de\nviolents heurts avec des policiers dont certains ont tiré à balles réelles sur la foule. Certains\nmanifestants ont également durci leur position et ont eu recours à la violence. En réponse à la\ntentative de coup d’État et à la poursuite des manifestations, le Gouvernement a intensifié sa\ncampagne de répression touchant particulièrement des membres des corps de défense et de\nsécurité suspectés d’avoir soutenu ou d’avoir été impliqués dans la tentative de coup d’État,\ndes membres des partis d’opposition, des activistes de la société civile et des journalistes. La\nRPA et les radios Bonesha FM, Isanganiro et Radio-Télévision Renaissance,\nmomentanément rouvertes lors du coup d’État, ont été incendiées et pillées comme les locaux\nde la radio REMA FM, proche du CNDD-FDD. Toutes ces radios ont alors cessé d’émettre\nau Burundi et nombre de journalistes et d’acteurs de la société civile ont dû fuir le pays118.\n(c)     Élections"},{"id":"a-hrc-36-crp-1-p0090","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"90","seq":92,"section":"2. Contexte politique","text":"Les élections communales et législatives se sont déroulées le 29 juin 2015. La veille,\nle Président de l'Assemblée nationale sortante, Pie Ntavyohanyuma, membre du CNDD-\nFDD, avait fait part de sa défection depuis Bruxelles. Le 7 juillet 2015, la Commission\nélectorale nationale indépendante a annoncé la victoire du CNDD-FDD qui a remporté 77 des\n100 sièges à l’Assemblée nationale."},{"id":"a-hrc-36-crp-1-p0091","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"91","seq":93,"section":"2. Contexte politique","text":"Le 17 juillet 2015, plusieurs opposants au Président Nkurunziza, parmi lesquels Jean\nMinani, Agathon Rwasa, et les anciens Présidents Domitien Ndayizeye et Sylvestre\nNtibantunganya, ont annoncé qu’ils ne prendraient pas part à l’élection présidentielle. Cette\ndernière a eu lieu les 21 et 24 juillet 2015. Pierre Nkurunziza a été déclaré vainqueur avec\n69,41 % des voix et la Cour constitutionnelle a confirmé son élection le 30 juillet 2015. Le 27\njuillet 2015, la Mission d'observation électorale des Nations Unies au Burundi (MENUB),\ndéployée dans le pays depuis le 1er janvier 2015 conformément à la résolution 2137 (2014) du\nConseil de sécurité de l’ONU, avait jugé l’environnement général du scrutin présidentiel peu\n« propice au déroulement d’un processus électoral libre, crédible et inclusif »119."},{"id":"a-hrc-36-crp-1-p0092","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"92","seq":94,"section":"2. Contexte politique","text":"Entre temps, les élections sénatoriales ont eu lieu le 24 juillet 2015. Le 27 juillet 2015,\nle Parlement a inauguré sa première session. Agathon Rwasa, dirigeant des FNL, a été élu\nPremier Vice-Président de l’Assemblée nationale le 30 juillet 2015. Deux jours plus tôt,\ncertains membres de l’opposition en exil avaient annoncé à Addis-Abeba (Éthiopie) la\nformation d’une plateforme politique : le Conseil national pour le respect de l’Accord\nd’Arusha et la restauration d’un État de droit au Burundi (CNARED)120.\n(d)     Violences post-électorales"},{"id":"a-hrc-36-crp-1-p0093","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"93","seq":95,"section":"2. Contexte politique","text":"Les violences et la répression par le Gouvernement de toute voix critique ou tout\nopposant présumé se sont poursuivies dans la foulée des élections et ont gagné en intensité.\nDans son discours d’investiture le 20 août 2015, Pierre Nkurunziza a donné deux mois aux\nforces de l’ordre pour restaurer la sécurité sur l’ensemble du territoire. Par la suite, les\nopérations policières dans les quartiers de Bujumbura réputés acquis à l’opposition se sont\nmultipliées ainsi que les arrestations de personnes accusées de rejoindre ou de soutenir des\ngroupes armés d’opposition, dont certains avaient commencé à lancer des attaques\nsporadiques."},{"id":"a-hrc-36-crp-1-p0094","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"94","seq":96,"section":"2. Contexte politique","text":"Plusieurs assassinats ou meurtres ou tentatives d’assassinat ou de meurtre, y compris\nde figures importantes, ont eu lieu à partir du mois d’août 2015121. Le 2 août 2015, le bras\ndroit du Président Nkurunziza et ancien Administrateur général du SNR, le Général Adolphe\nNshimirimana, a été tué à Bujumbura dans une attaque à la roquette. Le lendemain, le\ndéfenseur des droits de l’homme Pierre Claver Mbonimpa a été gravement blessé par balles.\nSon gendre et un de ses fils ont été assassinés les 9 octobre et le 6 novembre 2015\nrespectivement. Le 15 août 2015, le Colonel Jean Bikomagu, ancien Chef d’état-major des\nForces armées burundaises (FAB)122, a été assassiné devant son domicile à Bujumbura. Le 7\nseptembre 2015, le porte-parole du parti d’opposition l’Union pour la paix et le\ndéveloppement (UPD)-Zigamibanga, Patrice Gahungu, a été à son tour assassiné. Le\nprésident du même parti, Zedi Feruzi, avait été assassiné en mai. Le 11 septembre 2015, le\nChef d’état-major de l’armée, le Général major Prime Niyongabo, a quant à lui échappé à un\nattentat dans lequel plusieurs personnes ont été tuées."},{"id":"a-hrc-36-crp-1-p0095","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"95","seq":97,"section":"2. Contexte politique","text":"En août 2015, une commission d’enquête mise en place par le Procureur général de la\nRépublique a qualifié les manifestations contre le « troisième mandat » du Président de la\nRépublique de « mouvement insurrectionnel »123. Le rapport comprend une liste d’« insurgés\n» qui inclut des membres de l’opposition et de la société civile accusés, entre autres,\nd’atteinte à la sûreté intérieure de l’État, de détention illégale d’armes à feu, de participation\nà un mouvement insurrectionnel, de meurtre, d’assassinat et de coups et blessures. Le 12\noctobre 2015, le Procureur général de la République a lancé des mandats d’arrêt\ninternationaux contre des membres de l’opposition et de la société civile en exil."},{"id":"a-hrc-36-crp-1-p0096","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"96","seq":98,"section":"2. Contexte politique","text":"Le 2 novembre 2015, le Président Nkurunziza, dans un discours à la nation, a lancé un\nultimatum de cinq jours aux personnes en possession illégale d’armes à feu pour se rendre.\nDes opérations de fouille par la police s’en sont suivies dans plusieurs quartiers de\nBujumbura. Le 23 novembre 2015, le Ministre de l’intérieur a publié un décret suspendant les\nactivités de 10 associations de la société civile qui faisaient l’objet d’une enquête pour\nparticipation à un « mouvement insurrectionnel », parmi lesquelles l’APRODH de Pierre\nClaver Mbonimpa. Cette décision est intervenue après celle du Procureur général de la\nRépublique de geler les comptes bancaires de plusieurs organisations de la société civile124."},{"id":"a-hrc-36-crp-1-p0097","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"97","seq":99,"section":"2. Contexte politique","text":"Le mois de novembre 2015 a également été le témoin d’une augmentation des\nattaques, parfois à l’arme lourde, par des individus et groupes armés non identifiés, visant en\nparticulier les corps de défense et de sécurité.\n(e)     Événements du 11 décembre 2015"},{"id":"a-hrc-36-crp-1-p0098","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"98","seq":100,"section":"2. Contexte politique","text":"Cette tendance a culminé le 11 décembre 2015 lorsque des éléments armés non\nidentifiés ont pris d’assaut quatre installations militaires : le camp de Ngagara au nord de\nBujumbura, le « Camp de base » des forces armées et l’Institut supérieur des cadres militaires\n(ISCAM) tous deux situés à Musaga (Bujumbura Mairie), et le camp de Mujejuru dans la\nprovince de Bujumbura. Ces attaques ont entraîné une nouvelle répression brutale et des\nopérations violentes par la police et les militaires, appuyés par des Imbonerakure (ligue des\njeunes du parti CNDD-FDD) dans plusieurs quartiers de la capitale, notamment Nyakabiga et\nMusaga, lors desquelles de nombreuses personnes, dont beaucoup de civils, ont été tués125."},{"id":"a-hrc-36-crp-1-p0099","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"99","seq":101,"section":"2. Contexte politique","text":"Le 17 décembre 2015, le Procureur général de la République a créé une commission\nd’enquête sur ces événements dont les résultats ont été publiés en mars 2016126. Le rapport de\ncette commission fait état d’un bilan de quatre militaires et quatre policiers tués contre 79\n« combattants » ayant perdu la vie, ainsi que 87 capturés. Ces chiffres ne concordent pas avec\nceux avancés par plusieurs ONG ainsi que par le Haut-Commissaire des Nations Unies aux\ndroits de l’homme qui, le 15 janvier 2016, a révélé l’existence d’au moins neuf charniers à\nBujumbura et dans ses environs qui « contiendraient au moins 100 corps, tous de personnes\nqui auraient été tuées le 11 décembre 2015 »127.\n(f)     Poursuite de la violence et de la répression"},{"id":"a-hrc-36-crp-1-p0100","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"100","seq":102,"section":"2. Contexte politique","text":"Les attaques du 11 décembre 2015 contre les installations militaires n’ont pas été\nrevendiquées alors que le nombre et l’activité des groupes armés d’opposition a augmenté\ntout au long de l’année 2016. Après les Forces républicaines du Burundi (FOREBU) et le\nMouvement de la résistance populaire (MPR), tous deux créés en décembre 2015, la\nRésistance pour un État de droit au Burundi (RED-Tabara), l’Union des patriotes pour la\nrévolution (UPR), la Force de libération de la démocratie au Burundi (FLDB) et le\nMouvement patriotique chrétien (MPC) sont apparus en janvier, février et mai 2016,\nrespectivement128."},{"id":"a-hrc-36-crp-1-p0101","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"101","seq":103,"section":"2. Contexte politique","text":"Les meurtres et assassinats de civils et les attaques contre des personnalités ont\négalement continué en 2016 et 2017129. Le 22 mars 2016, le Lieutenant-Colonel Darius\nIkurakure, commandant du Bataillon génie de combat (camp Muzinda), a été tué dans les\nlocaux de l'état-major de la Force de défense nationale burundaise. Le 21 avril 2016, le\nLieutenant-Colonel Emmanuel Buzubona a été assassiné. Le 24 avril, le Ministre des droits\nde la personne humaine, des affaires sociales et du genre, Martin Nivyabandi, et son épouse\nont échappé de peu à un attentat à la grenade. Le lendemain, le Général Athanase Kararuza,\nconseiller en matière de sécurité et de défense à la Première Vice-Présidence, sa femme, sa\nfille et son agent de transmission ont été tués. Le 13 juillet 2016, Hafsa Mossi, députée de\nl’Assemblée législative de la Communauté des États d’Afrique de l’Est, a été assassinée. Le\n28 novembre 2016, le conseiller en communication du Président de la République, Willy\nNyamitwe, a été blessé dans une attaque qui a tué l’un de ses gardes du corps. Le 1er janvier\n2017, le Ministre de l’eau, de l’environnement, de l’aménagement du territoire et de\nl’urbanisme, Emmanuel Niyonkuru, a été tué par balles."},{"id":"a-hrc-36-crp-1-p0102","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"102","seq":104,"section":"2. Contexte politique","text":"De nombreuses arrestations de personnes accusées d’attenter à la sécurité de l’État ont\ncontinué à avoir lieu en même temps qu’une augmentation du nombre d’enlèvements et de\ndisparitions était observée, notamment par le Haut-Commissaire des Nations Unies aux droits\nde l’homme130."},{"id":"a-hrc-36-crp-1-p0103","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"103","seq":105,"section":"2. Contexte politique","text":"Les restrictions aux libertés publiques ont également perduré malgré l’autorisation en\nfévrier 2016 faite à la Radio Isanganiro d’émettre à nouveau – mais avec un contrôle accru de\nla part du Gouvernement –, et la levée de la suspension de l’association Parole et action pour\nle réveil des consciences et l’évolution des mentalités (PARCEM) et du gel des comptes de\nl’Association des juristes catholiques du Burundi un mois plus tard. En revanche, le 19\noctobre 2016, le Ministère de l’intérieur a émis une ordonnance pour radier définitivement\ncinq des principales associations de la société civile suspendues depuis novembre 2015 et en\na suspendu cinq autres le 24 octobre131. L’une d’entre elles, la Ligue Iteka, la plus ancienne\norganisation de défense des droits de l’homme au Burundi, a été définitivement radiée le 21\ndécembre 2016. En janvier 2017, les autorités burundaises ont adopté deux lois restrictives\nsur les ONG132. Le 4 avril 2017, le Ministre de l’intérieur a suspendu pour six mois le parti\nd’opposition MSD, l’accusant d’être engagé dans la formation d’un groupe armé et d’inciter\nà la violence et à la haine133. En juillet 2017, la RPA a également été suspendue par\nordonnance du Ministère de l’intérieur pour trouble à l’ordre public alors même que les\nrésultats de l’enquête officielle sur la destruction des médias (parmi lesquels la RPA) en mai\n2015 n’ont toujours pas été publiés134. En outre, une révision du Code pénal et du Code de\nprocédure pénale a été initiée en 2017. Certains amendements, s’ils sont adoptés,\npermettraient aux forces de sécurité de mener des perquisitions sans mandat, y compris de\nnuit, et de saisir des données électroniques, notamment des courriels135."},{"id":"a-hrc-36-crp-1-p0104","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"104","seq":106,"section":"2. Contexte politique","text":"Les prochaines élections au Burundi sont prévues en 2020. Le Président Nkurunziza a\nlancé en mai 2017 une campagne appelant la population à contribuer pour l’organisation de\nces futures élections. Il aurait lui-même versé cinq millions de francs burundais (soit environ\n2 864 dollars américains)136 à cet effet à la Banque centrale du Burundi137. La Commission a\neu connaissance d’autres demandes de contribution à la population. Un processus de révision\nde la Constitution est par ailleurs en cours, comme expliqué plus bas."},{"id":"a-hrc-36-crp-1-p0105","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"105","seq":107,"section":"3. Contexte diplomatique","text":"Plusieurs gouvernements et acteurs régionaux et internationaux se sont mobilisés\ndepuis 2015 en réponse à la crise politique et des droits de l’homme que traverse le Burundi,\navec, jusqu’à présent, un impact limité.\n(a)     Nations Unies"},{"id":"a-hrc-36-crp-1-p0106","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"106","seq":108,"section":"3. Contexte diplomatique","text":"Le 1er janvier 2015, dans la foulée de la fermeture du Bureau des Nations Unies au\nBurundi (BNUB)138, la Mission d'observation électorale des Nations Unies au Burundi\n(MENUB) a démarré ses opérations, conformément à la résolution 2137 (2014) du Conseil de\nsécurité, avec pour mandat de suivre le déroulement du processus électoral dans le pays. Le\n13 mars 2015, les membres du Conseil de sécurité ont visité le Burundi et ont appelé les\nparties prenantes à travailler ensemble pour des élections libres, transparentes et inclusives139.\nLe Haut-Commissaire des Nations Unies aux droits de l’homme, qui s’est lui aussi rendu au\nBurundi en avril 2015, a déploré l’augmentation des tensions à l’approche des élections,\n« alimentées par une hausse du harcèlement pour des motifs politiques, des intimidations et\ndes actes de violence, ainsi que des discours haineux ». Il a notamment condamné les\nviolences et intimidations par les Imbonerakure140."},{"id":"a-hrc-36-crp-1-p0107","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"107","seq":109,"section":"3. Contexte diplomatique","text":"Après les violences faisant suite aux premières manifestations contre le mandat de\nPierre Nkurunziza à l’élection présidentielle de 2015, les Nations Unies ont tenté sans succès\nde mettre en place une médiation internationale. Le Représentant spécial du Secrétaire\ngénéral de l’ONU, Saïd Djinnit, nommé le 5 mai 2015 comme facilitateur dans la crise\nburundaise, a dû renoncer à ses fonctions le 10 juin 2015 après avoir été accusé de parti-pris\nen faveur des autorités burundaises par des membres de l’opposition et de la société civile.\nQuelques semaines plus tard, son successeur, Abdoulaye Bathily, a également été obligé de\nse retirer après avoir été désavoué, cette fois par le Gouvernement."},{"id":"a-hrc-36-crp-1-p0108","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"108","seq":110,"section":"3. Contexte diplomatique","text":"Le 9 novembre 2015, le Haut-Commissaire aux droits de l’homme a souligné dans une\nprésentation au Conseil de sécurité de l’ONU que le Burundi était à « un tournant » pouvant\nconduire à une escalade de la violence avec des répercussions régionales141. Le Conseiller\nspécial du Secrétaire général de l’ONU pour la prévention du génocide, Adama Dieng, a pour\nsa part alerté le Conseil de sécurité des risques d’une escalade de la violence au Burundi sur\ndes lignes ethniques142. Le 12 novembre 2015, le Conseil de sécurité a adopté la résolution\n2248 condamnant les violations des droits de l’homme commises au Burundi et demandant à\nêtre régulièrement informé de l’évolution de la situation des droits de l’homme143."},{"id":"a-hrc-36-crp-1-p0109","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"109","seq":111,"section":"3. Contexte diplomatique","text":"Suite à cette résolution, Jamal Benomar, nommé le 9 novembre 2015 comme\nConseiller spécial du Secrétaire général de l’ONU pour la prévention des conflits avec pour\nmission de coordonner les efforts dans la crise burundaise, a effectué sa première visite au\nBurundi. Le 30 novembre 2015, il a présenté des options pour une future présence des\nNations Unies au Burundi après la fin du mandat de la MENUB en décembre 2015. Cette\nprésence a consisté jusqu’à ce jour dans le déploiement d’une équipe ayant pour tâche d’aider\nà un dialogue politique inclusif et de soutenir les efforts de désarmement et d’amélioration de\nla sécurité."},{"id":"a-hrc-36-crp-1-p0110","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"110","seq":112,"section":"3. Contexte diplomatique","text":"Face à la détérioration de la situation au Burundi qu’il a dénoncée à plusieurs reprises\nfin 2015 et pendant la première moitié de 2016144, le Conseil de sécurité a adopté, le 29 juillet\n2016, la résolution 2303 autorisant le déploiement de 228 policiers de l’ONU au Burundi.\nCette option a été rejetée par le Gouvernement du Burundi et a contribué à tendre ses\nrelations avec les Nations Unies ; les policiers n’ont jamais été déployés. Les relations entre\nle Gouvernement burundais et les Nations Unies se sont encore dégradées après la\npublication, le 20 septembre 2016, du rapport de l’EINUB concluant à de « possibles crimes\ncontre l’humanité » au Burundi145, ainsi qu’après la création de la présente Commission par\nla résolution 33/24 du Conseil des droits de l’homme. En parallèle, le Gouvernement\nburundais a annoncé, le 7 octobre 2016, son intention de se retirer de la CPI, ainsi que sa\ndécision de considérer les membres de l’EINUB comme personae non grata et de suspendre\nson accord de siège avec le Bureau du HCDH au Burundi."},{"id":"a-hrc-36-crp-1-p0111","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"111","seq":113,"section":"3. Contexte diplomatique","text":"Dans une lettre adressée au Secrétaire général de l’ONU en novembre 2016, le\nPrésident Nkurunziza a demandé le remplacement du Conseiller spécial, Jamal Benomar. Le\n12 mars 2017, celui-ci a présenté le rapport du Secrétaire général au Conseil de sécurité des\nNations Unies sur l’évolution de la situation au Burundi. À l’issue de cette présentation, les\nmembres du Conseil de sécurité « se sont déclarés à la fois extrêmement préoccupés par le\nnombre croissant de réfugiés qui quittent le pays et troublés par les informations faisant état\nd’actes de torture, de disparitions forcées et d’assassinats »146."},{"id":"a-hrc-36-crp-1-p0112","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"112","seq":114,"section":"3. Contexte diplomatique","text":"Le 5 mai 2017, le Secrétaire général des Nations Unies a annoncé la nomination de\nMichel Kafando, l’ancien président de transition du Burkina Faso, comme Envoyé spécial\ndes Nations Unies chargé de « promouvoir la paix et le développement durable au Burundi »\net d’apporter « son assistance aux efforts de la Communauté des États d’Afrique de l’Est en\nvue d’un dialogue politique entre les acteurs burundais »147. Michel Kafando a effectué sa\npremière visite au Burundi en juin 2017 et a fait une présentation au Conseil de sécurité le 26\njuillet 2017148. Le 2 août 2017, le Président du Conseil de sécurité a fait une déclaration dans\nlaquelle il a réitéré la préoccupation du Conseil de sécurité au sujet de la situation politique\nau Burundi et de la non-application de la résolution 2303 (2016), ainsi que par « les rapports\nfaisant état d’actes de torture, de disparitions forcées et d’exécutions extrajudiciaires, ainsi\nque par la persistance de l’impasse politique dans le pays et les conséquences humanitaires\ngraves qui en découlent »149. Il a regretté que « le Gouvernement burundais ait suspendu\ntoute coopération et toute collaboration avec le Haut-Commissariat des Nations Unies aux\ndroits de l’homme, présent dans le pays depuis 1995 » et a demandé au Gouvernement\nburundais de coopérer avec la présente Commission d’enquête.\n(b)     Union africaine"},{"id":"a-hrc-36-crp-1-p0113","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"113","seq":115,"section":"3. Contexte diplomatique","text":"L’Union africaine (UA) s’est également mobilisée depuis le début de la crise au\nBurundi. Le 14 juin 2015, le Conseil de paix et de sécurité de l’UA a appelé à la reprise du\ndialogue et annoncé l’envoi d’observateurs des droits de l’homme et d’experts militaires au\nBurundi. Une partie de ces derniers n’a pu être déployée qu’après la tenue de l’élection\nprésidentielle, le Gouvernement ayant refusé dans l’intervalle de leur délivrer des visas."},{"id":"a-hrc-36-crp-1-p0114","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"114","seq":116,"section":"3. Contexte diplomatique","text":"Le 17 octobre 2015, le Conseil de paix et de sécurité de l’UA a chargé la Commission\nafricaine des droits de l’homme et des peuples de mener une enquête sur les violations des\ndroits de l’homme commises en 2015. En application de cette décision, une mission\nd’établissement des faits s’est rendue au Burundi du 7 au 13 décembre 2015. Elle a déploré\nles violations « graves et massives » des droits de l’homme du fait des forces de sécurité\nburundaises et de groupes affiliés et a appelé au déploiement d’une « mission de police\ninternationale »150."},{"id":"a-hrc-36-crp-1-p0115","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"115","seq":117,"section":"3. Contexte diplomatique","text":"Le 17 décembre 2015, le Conseil de paix et de sécurité de l’UA a adopté une\nrésolution convenant de l’envoi d’une force de maintien de la paix de 5 000 hommes au\nBurundi (connue sous son sigle MAPROBU). Cette décision n’a cependant pas été suivie\nd’effet après que le Gouvernement du Burundi ait déclaré que si l’UA persistait à vouloir\ndéployer la MAPROBU, celle-ci serait considérée comme une « force d’invasion et\nd’occupation »151. L’UA a en contrepartie décidé l’envoi de 100 observateurs des droits de\nl’homme et de 100 observateurs militaires au Burundi. Faute de la signature d’un accord avec\nles autorités burundaises, seuls 32 observateurs des droits de l’homme et 10 experts militaires\nétaient déployés à la date du 1er février 2017152. Depuis l’échec du déploiement de la\nMAPROBU, l’UA a été moins active sur la question du Burundi.\n(c)     Médiation sous-régionale"},{"id":"a-hrc-36-crp-1-p0116","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"116","seq":118,"section":"3. Contexte diplomatique","text":"Le 13 juillet 2015, la Communauté des États d’Afrique de l’Est (CAE) a désigné le\nPrésident ougandais, Yoweri Museveni, comme médiateur dans la crise burundaise. Le\nPrésident Museveni s’est rendu au Burundi en juillet 2015 et a chargé son Ministre de la\ndéfense, Crispus Kiyonga, de continuer les pourparlers."},{"id":"a-hrc-36-crp-1-p0117","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"117","seq":119,"section":"3. Contexte diplomatique","text":"Ces derniers se sont vite heurtés, d’une part, au refus constant du Gouvernement\nburundais de dialoguer avec des personnes qui, selon lui, auraient été impliquées dans la\ntentative de coup d’État de mai 2015 et des organisations ayant pris part au mouvement «\nHalte au troisième mandat », et, d’autre part, au rejet par une grande partie de l’opposition du\nnouveau mandat de Pierre Nkurunziza qu’elle n’a cessé de considérer comme illégitime."},{"id":"a-hrc-36-crp-1-p0118","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"118","seq":120,"section":"3. Contexte diplomatique","text":"Les autorités burundaises ont en outre régulièrement demandé à ce que le dialogue se\ndéroule au Burundi, plutôt que dans les pays de la sous-région, et que le processus lancé par\nla CAE soit jumelé avec celui conduit par la Commission nationale pour le dialogue inter-\nburundais (CNDI), créée par décret présidentiel le 23 septembre 2015 et dont les travaux ont\nété lancés officiellement le 19 janvier 2016153. Le 12 mai 2017, la CNDI a remis au Président\nde la République son rapport final, dont, selon le communiqué publié à cette occasion, la\nprincipale proposition « concerne la nécessité d’amender la Constitution ». La CNDI a noté\nque « la majorité des Burundais consultés ont en commun la volonté de supprimer les limites\nde mandats présidentiels, même si une autre partie non négligeable estime que les limites de\nmandats sont un gage démocratique »154. Le 16 novembre 2016, le Conseil des ministres\navait déjà approuvé la mise en place d’une commission chargée de proposer des\namendements à la Constitution. Celle-ci a été officiellement créée par décret le 15 mars 2017\net ses membres nommés le 12 mai 2017155."},{"id":"a-hrc-36-crp-1-p0119","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"119","seq":121,"section":"3. Contexte diplomatique","text":"Le 2 mars 2016, la CAE a désigné l’ancien Président tanzanien Benjamin Mkapa\ncomme facilitateur dans la crise burundaise. Ce dernier, sur la base des recommandations\nadoptées lors du Sommet des Chefs d’États de la CAE du 8 septembre 2016, a développé une\nfeuille de route qu’il a soumise pour consultation au Président Nkurunziza lors d’une visite\nau Burundi début décembre 2016. À l’issue de cette visite, le facilitateur Mkapa a été\nfortement critiqué par le CNARED et plusieurs organisations membres de la plateforme\n« Halte au troisième mandat » pour avoir déclaré que la question de la légitimité du mandat\nen cours du Président Nkurunziza ne se posait plus, le principal défi au Burundi étant la\npréparation d’élections libres et justes en 2020. Depuis, le facilitateur a organisé plusieurs\nsessions de dialogue au Burundi et à l’extérieur du pays, sans progrès significatif."},{"id":"a-hrc-36-crp-1-p0120","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"120","seq":122,"section":"3. Contexte diplomatique","text":"Lors du 18ème sommet ordinaire des Chefs d’État de la CAE à Dar es Salaam les 24 et\n25 mai 2017, le facilitateur Mkapa a présenté un rapport d’étape dans lequel il a notamment\ninsisté sur la persistance d’une situation politique tendue et le manque de bonne volonté du\nGouvernement burundais de mener un dialogue inclusif.\n(d)     Sanctions individuelles et suspensions d’aide"},{"id":"a-hrc-36-crp-1-p0121","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"121","seq":123,"section":"3. Contexte diplomatique","text":"En octobre et en novembre 2015, l’Union européenne (UE) et les États-Unis ont pris\ndes sanctions ciblées (interdiction de voyage et gels des avoirs) à l’encontre de plusieurs\npersonnalités politiques burundaises156. Ces sanctions demeurent en place."},{"id":"a-hrc-36-crp-1-p0122","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"122","seq":124,"section":"3. Contexte diplomatique","text":"En outre, plusieurs pays, parmi lesquels l’Allemagne, la Belgique, les États-Unis, la\nFrance et les Pays-Bas, ont suspendu une partie importante de leur coopération avec le\nBurundi sur la base des nombreux rapports faisant état de violations graves des droits de\nl’homme dans le pays. Le 14 mars 2016, suite à un processus de consultation avec le\nGouvernement burundais, et le constat d’aucune évolution positive de la situation des droits\nde l’homme au Burundi, l’UE a décidé, en vertu de l’article 96 des Accords de Cotonou entre\nl'UE et les États d'Afrique, Caraïbes et Pacifique (ACP), de suspendre ses appuis financiers\ndirects à l'administration burundaise, y compris ses appuis budgétaires. Elle a en revanche\nmaintenu le financement de plusieurs projets visant à assurer l'accès de la population aux\nservices de base157."},{"id":"a-hrc-36-crp-1-p0123","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"123","seq":125,"section":"1. Institutions politiques","text":"Les institutions politiques du Burundi sont prévues par la Constitution adoptée par\nréférendum le 28 février 2005 et promulguée le 18 mars 2005.\n(a)     Pouvoir exécutif"},{"id":"a-hrc-36-crp-1-p0124","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"124","seq":126,"section":"1. Institutions politiques","text":"Le régime constitutionnel du Burundi est présidentiel et respecte la séparation des\npouvoirs. Le pouvoir exécutif est « exercé par un Président de la République, deux Vice-\nPrésidents de la République et les membres du Gouvernement »158. En vertu de l’article 95 de\nla Constitution, « le Président de la République est élu au suffrage universel direct pour un\nmandat de cinq ans renouvelable une fois »159. Le Président « exerce le pouvoir réglementaire\net assure l’exécution des lois »160. Il exerce ses pouvoirs par décrets contresignés, le cas\néchéant, par le Vice-Président et le ministre concernés161. Il est le chef du Gouvernement et\npréside le Conseil des ministres. Il nomme ces derniers en consultation avec les deux Vice-\nPrésidents162. Il nomme également aux emplois supérieurs, civils et militaires163."},{"id":"a-hrc-36-crp-1-p0125","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"125","seq":127,"section":"1. Institutions politiques","text":"Le Président est assisté de services, dits « de la Présidence », chargés de l’aider dans\nla préparation, l’organisation et l’exécution des missions qui lui incombent164. Ces services\ncomportent notamment un cabinet civil, sous la direction depuis août 2016 du Général\nGabriel Nizigama165, un cabinet chargé des questions militaires dirigé par le Général\nIldephonse Habarurema, et un cabinet chargé des questions de police dirigé par le Général\nGervais Ndirakobuca, alias « Ndakugarika » (« Je vais te tuer »)166. Willy Nyamitwe, élevé\nen 2017 au titre d’Ambassadeur extraordinaire et plénipotentiaire, est le Conseiller principal\nchargé de la communication du Président."},{"id":"a-hrc-36-crp-1-p0126","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"126","seq":128,"section":"1. Institutions politiques","text":"Les Premier et Deuxième Vice-Présidents, aujourd’hui Gaston Sindimwo167 et Joseph\nButore168, sont nommés par le Chef de l’État après accord préalable du Parlement169. Chacun\na un rôle particulier. Au titre de l’article 122 de la Constitution, le Premier Vice-Président\n« assure la coordination du domaine politique et administratif », tandis que « le Deuxième\nVice-Président assure la coordination du domaine économique et social »."},{"id":"a-hrc-36-crp-1-p0127","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"127","seq":129,"section":"1. Institutions politiques","text":"Le Gouvernement, pour sa part, « détermine et conduit la politique de la nation dans le\ncadre des décisions prises par consensus en Conseil des ministres »170. Sa composition doit\nrefléter la diversité ethnique et politique du pays171. Parmi les ministères dont les attributions\nentrent dans le cadre du mandat de la Commission, il faut citer le Ministère de la justice avec\nà sa tête Aimée Laurentine Kanyana172, le Ministère des droits humains, des affaires sociales\net du genre dirigé par Martin Nivyabandi, le Ministère de la sécurité publique dirigé par le\nCommissaire de police Alain-Guillaume Bunyoni173, le Ministère de l’intérieur et de la\nformation patriotique dirigé par Pascal Barandagiye174, et le Ministère de la défense nationale\net des anciens combattants dirigé par Emmanuel Ntahomvukiye175. Les membres du\nGouvernement prennent par ordonnances toutes les mesures de mise en application des\ndécrets du Président et des arrêtés des Vice-Présidents176. Chaque ministre « rend compte au\nPrésident de la République de la manière dont son ministère s’acquitte de ses tâches et de\nl’utilisation des fonds qui lui sont alloués »177."},{"id":"a-hrc-36-crp-1-p0128","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"128","seq":130,"section":"1. Institutions politiques","text":"L’administration doit également refléter la diversité des composantes de la nation\nburundaise178. En vertu de la loi n° 1/08 du 28 avril 2011 portant organisation générale de\nl'administration publique, cette dernière est composée des « Services de la superstructure\ngouvernementale » qui comportent notamment les services de la Présidence et des deux Vice-\nPrésidences, les « services centraux », parmi lesquels les coordinations des cabinets\nministériels et les directions générales, tous sous l’autorité d’un ministre, les « services\ndéconcentrés » subordonnés à l’autorité centrale mais placés au niveau des collectivités\nlocales comme les services de l’administration provinciale ou en dehors des frontières\ncomme les services extérieurs, et les « collectivités décentralisées ».\n(b)     Collectivités locales"},{"id":"a-hrc-36-crp-1-p0129","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"129","seq":131,"section":"1. Institutions politiques","text":"Le Burundi est subdivisé en provinces, communes, zones et collines. Après la dernière\nmodification de l’organisation territoriale en 2015179, le Burundi compte 18 provinces180,\ndivisées en communes, qui sont elles-mêmes sous-divisées en zones et près de 3 000 collines\nde recensement et quartiers181, subdivisions des zones."},{"id":"a-hrc-36-crp-1-p0130","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"130","seq":132,"section":"1. Institutions politiques","text":"Un Gouverneur est nommé dans chaque province par le Président, après consultation\navec les Vice-Présidents et confirmation par le Sénat. Le Gouverneur est chargé de\ncoordonner les services de l’administration œuvrant dans la province182."},{"id":"a-hrc-36-crp-1-p0131","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"131","seq":133,"section":"1. Institutions politiques","text":"Les communes sont administrées par un Conseil communal de 25 membres élus au\nsuffrage universel direct pour cinq ans183. Le Conseil communal élit à son tour un\nadministrateur communal qui est à la fois « le représentant légal de la commune et de la\npopulation de son ressort », et celui de l’État184. À ce titre, il « est chargé de l’application des\nlois et règlements. Il exerce, dans les limites territoriales de son ressort, un pouvoir général de\npolice. Il prend à cet effet toute mesure de police qu’il juge utile au maintien de l’ordre et de\nla sécurité publics »185. Il exerce un pouvoir hiérarchique direct sur le détachement de police\naffecté dans sa commune186."},{"id":"a-hrc-36-crp-1-p0132","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"132","seq":134,"section":"1. Institutions politiques","text":"Les collines et les quartiers sont administrés par des Conseils de colline ou de quartier\ncomposés de cinq membres élus au suffrage universel direct pour cinq ans. Le conseiller qui\na obtenu le plus grand nombre de voix exerce les fonctions de chef de colline ou de quartier.\nCe dernier est « l’animateur de la paix sociale et du développement dans sa circonscription »\net doit organiser au moins une fois par trimestre une rencontre ouverte à tous les habitants de\nla colline ou du quartier afin d’analyser entre autres la situation politique et sécuritaire qui y\nprévaut187.\n(c)     Pouvoir législatif"},{"id":"a-hrc-36-crp-1-p0133","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"133","seq":135,"section":"1. Institutions politiques","text":"Le pouvoir législatif, ou Parlement, est composé d’une Assemblée nationale et d’un\nSénat. Les députés siégeant à l’Assemblée nationale sont élus pour cinq ans selon un scrutin\nde listes à la représentation proportionnelle188. De leur côté, les sénateurs sont élus, à raison\nde deux sénateurs par province, par un collège électoral composé de membres des Conseils\ncommunaux de la province considérée189. L’Assemblée nationale et le Sénat doivent\nreprésenter la diversité ethnique du pays et comporter un pourcentage minimum de\nfemmes190. Depuis août 2015, la présidence de l’Assemblée nationale est exercée par Pascal\nNyabenda191 et celle du Sénat par Révérien Ndikuriyo."},{"id":"a-hrc-36-crp-1-p0134","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"134","seq":136,"section":"1. Institutions politiques","text":"En vertu de l’article 158 de la Constitution, « le Parlement vote la loi et contrôle\nl’action du Gouvernement ». Les garanties et obligations fondamentales du citoyen, telles que\n« la sauvegarde de la liberté individuelle, la protection des libertés publiques, et les sujétions\nimposées dans l’intérêt de la défense nationale et de la sécurité publique, aux citoyens en leur\npersonne et en leurs biens », sont du domaine de la loi192.\n2.     Système judiciaire193\n(a)     Juridictions"},{"id":"a-hrc-36-crp-1-p0135","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"135","seq":137,"section":"1. Institutions politiques","text":"En vertu de l’article 205 de la Constitution, « la justice est rendue par les cours et\ntribunaux sur tout le territoire de la République au nom du peuple burundais ». La Cour\nsuprême est la plus haute juridiction ordinaire et est garante de la bonne application de la loi\npar les cours et tribunaux194. Ses membres sont nommés par le Président de la République sur\nproposition du Ministre de la justice après avis du Conseil supérieur de la magistrature et\napprobation du Sénat195. La Cour suprême est divisée en trois chambres : la chambre\njudiciaire compétente au premier degré et au degré d’appel, la chambre administrative de\npremier degré et de degré d’appel, et la chambre de cassation."},{"id":"a-hrc-36-crp-1-p0136","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"136","seq":138,"section":"1. Institutions politiques","text":"Il existe trois Cours d’appel composées d’un président, d’un vice-président et de\nconseillers et de greffiers196. Situées à Bujumbura, Gitega et Ngozi, elles connaissent de\nl’appel des jugements rendus par les Tribunaux de grande instance en matière civile comme\nen matière pénale. Les Cours d’appel se prononcent également au premier degré sur les\ninfractions commises par les fonctionnaires et les juges."},{"id":"a-hrc-36-crp-1-p0137","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"137","seq":139,"section":"1. Institutions politiques","text":"À l’échelon inférieur, 18 Tribunaux de grande instance, un dans chaque province,\nreçoivent en appel, en matière civile comme en matière pénale, les jugements des Tribunaux\nde résidence. Ils connaissent également au premier degré de toutes les actions en matière\ncivile et en matière pénale dont la compétence n’est pas attribuée à une autre juridiction197."},{"id":"a-hrc-36-crp-1-p0138","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"138","seq":140,"section":"1. Institutions politiques","text":"À la base de la pyramide des juridictions ordinaires se trouvent les Tribunaux de\nrésidence198. Situés au niveau des communes, ils connaissent en matière civile des litiges dont\nla valeur n’excède pas 1 000 000 francs burundais (soit environ 573 dollars américains). En\nmatière pénale, les Tribunaux de résidence jugent, entre autres, les délits passibles de deux\nans de servitude pénale et peuvent allouer des dommages et intérêts résultant de l’infraction,\nsans limitation de valeur, sauf si la victime décide de saisir une autre juridiction civile."},{"id":"a-hrc-36-crp-1-p0139","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"139","seq":141,"section":"1. Institutions politiques","text":"Le Burundi dispose par ailleurs de juridictions spécialisées parmi lesquelles les cours\nadministratives199 qui connaissent notamment du contentieux en matière de discipline des\nfonctionnaires, la Cour anti-corruption200 seule compétente pour connaître des infractions de\ncorruption, ainsi que les tribunaux militaires et la Cour constitutionnelle. Les tribunaux\nmilitaires ont deux juridictions201. Le Conseil de guerre juge au premier degré les militaires et\nfonctionnaires assimilés d’un grade inférieur à celui de major ainsi que les civils ayant violé\nles dispositions sur le régime des armes à feu. En cas de conflit de compétence entre les\njuridictions militaires et celles de droit commun, ces dernières sont néanmoins préférées202.\nLa Cour militaire, de son côté, examine au second degré les recours faits contre les décisions\ndu Conseil de guerre. Elle connaît également au premier degré des infractions commises par\nles officiers ainsi que les fonctionnaires assimilés d’un grade égal ou supérieur à celui de\nmajor."},{"id":"a-hrc-36-crp-1-p0140","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"140","seq":142,"section":"1. Institutions politiques","text":"La Cour constitutionnelle est composée de sept membres nommés pour six ans\nrenouvelables par le Président de la République après approbation du Sénat203. Elle a pour\ntâche principale de veiller à la constitutionnalité des lois et des actes réglementaires pris dans\nles matières autres que celles relevant du domaine de la loi. Elle assure également « le respect\nde la Constitution, y compris la Charte des droits fondamentaux, par les organes de l’État, et\nles autres institutions » et statue sur la régularité des élections présidentielles et\nlégislatives204.\n(b)     Le Ministère public"},{"id":"a-hrc-36-crp-1-p0141","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"141","seq":143,"section":"1. Institutions politiques","text":"L’article 223 de la Constitution prévoit qu’« il est institué, près de la Cour suprême,\nun Parquet général de la République » dont les membres sont nommés par le Président de la\nRépublique sur proposition du Ministre de la justice après avis du Conseil supérieur de la\nmagistrature et l’approbation du Sénat."},{"id":"a-hrc-36-crp-1-p0142","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"142","seq":144,"section":"1. Institutions politiques","text":"Le Parquet général coordonne toutes les activités du Ministère public. À sa tête, le\nProcureur général de la République a la plénitude de l’exercice de l’action publique devant\ntoutes les juridictions. Valentin Bagorikunda a occupé ce poste pendant huit ans, avant d’être\nremplacé par Sylvestre Nyandwi en août 2016. Placés sous l’autorité du Procureur général de\nla République, les Parquets généraux près des Cours d’appel sont chargés d’accomplir les\nfonctions du Ministère public auprès de ces cours ainsi que des cours administratives de leur\nressort. Les Parquets près les Tribunaux de grande instance couvrent quant à eux les\nTribunaux de grande instance ainsi que les Tribunaux de résidence de leur ressort205."},{"id":"a-hrc-36-crp-1-p0143","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"143","seq":145,"section":"1. Institutions politiques","text":"L’Auditeur général près la Cour militaire, l’Auditeur près le Conseil de guerre ainsi\nque le Procureur général près la Cour anti-corruption exercent les fonctions d’Officier du\nMinistère public au niveau de leurs juridictions respectives206. Ils sont tous placés sous la\ndirection et le contrôle de leurs supérieurs hiérarchiques ainsi que sous les ordres du\nProcureur général de la République."},{"id":"a-hrc-36-crp-1-p0144","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"144","seq":146,"section":"1. Institutions politiques","text":"Dans sa mission d’exécution de la loi et des décisions de justice, le Ministère public\nest assisté par la police judiciaire. Celle-ci recherche les délinquants, réunit les indices à\ncharge et conduit les auteurs des infractions devant le Ministère public. Elle peut également\nprocéder à leur arrestation provisoire, à la perquisition des domiciles et à la saisie des biens\ndans le respect de la loi et sous le contrôle du Ministère public. La police judiciaire a été\nintégrée à la Police nationale burundaise (PNB) depuis la réunification des différentes\npolices207. Elle est sous la dépendance administrative du Ministère de la sécurité publique,\nmais exerce ses fonctions sous le contrôle du Ministère public. Chaque parquet dispose d’un\ncommissariat de police et dans chaque commune est installé un poste de police où œuvre au\nmoins un officier de police judiciaire."},{"id":"a-hrc-36-crp-1-p0145","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"145","seq":147,"section":"1. Institutions politiques","text":"Dans la mesure où il est chargé de prévenir toute menace contre l’État, l’ordre\nconstitutionnel et la sécurité publique, et détecter tout type d’activités susceptibles de créer\nl’insécurité socio-politique, tout acte de terrorisme, tout trafic illicite et toute tentative de\nconstitution d’organisation criminelle, le Service national de renseignement (SNR) est amené\nà agir en appui des institutions judiciaires, particulièrement en matière pénale. Il est stipulé\nainsi à l’article 8 de la loi n° 1/04 du 2 mars 2006 portant création, organisation et\nfonctionnement du SNR que « dans ses missions en rapport avec l’atteinte à la sûreté de\nl’État, le SNR a le devoir de mener des enquêtes sur des dossiers judiciaires qu’il soumet au\nMinistère public pour instruction. À cette fin, il est soumis aux dispositions portées par le\nCode de procédure pénale concernant la garde à vue et la détention préventive ». Le\npersonnel du SNR jouit cependant d’un statut particulier et est placé sous l’autorité directe du\nPrésident de la République208.\n(c)     Le Barreau"},{"id":"a-hrc-36-crp-1-p0146","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"146","seq":148,"section":"1. Institutions politiques","text":"La profession d’avocat est organisée comme un ordre professionnel – l’Ordre des\navocats du Burundi – jouissant de la personnalité morale. L’Ordre des avocats est administré\npar le Conseil de l’Ordre qui élit à sa tête le Bâtonnier de l’Ordre des avocats. Celui-ci\nreprésente l’Ordre auprès des instances publiques. L’Ordre des avocats gère de manière\nautonome la profession d’avocat notamment l’admission au tableau des avocats, la\ndéontologie et la discipline des avocats209. Les membres de l’Ordre exercent le monopole de\nla fonction d’avocat210.\n(d)     L’administration pénitentiaire"},{"id":"a-hrc-36-crp-1-p0147","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"147","seq":149,"section":"1. Institutions politiques","text":"La loi n° 1/026 du 22 septembre 2003 portant régime pénitentiaire désigne, sous\nl’appellation de l’« autorité chargée de l’administration pénitentiaire », le personnel relevant\nde la Direction générale des affaires pénitentiaires au sein du Ministère de la justice, ainsi que\nles directeurs de prison et leurs proches collaborateurs211. La loi dispose que « chaque\nétablissement pénitentiaire est administré par un directeur assisté d’autant de directeurs\nadjoints que de besoin », tous nommés par le Ministère de la justice « dans le respect des\néquilibres ethniques et de genre »212."},{"id":"a-hrc-36-crp-1-p0148","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"148","seq":150,"section":"1. Institutions politiques","text":"La sécurité et l’ordre au sein des établissements pénitentiaires, ainsi que l’accueil,\nl’enregistrement, la garde et l’escorte des détenus, sont assurés par la police pénitentiaire qui,\npour sa part, dépend de l’Inspection générale de la Police nationale burundaise213. En ce qui\nconcerne l’accueil des détenus, « nul ne peut être admis dans un établissement pénitentiaire\nqu’en vertu d’un titre de détention prescrit par la loi »214. En cas contraire, la détention est\nconsidérée comme « arbitraire »215."},{"id":"a-hrc-36-crp-1-p0149","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"149","seq":151,"section":"1. Institutions politiques","text":"La loi n° 1/026 du 22 septembre 2003 précise les droits et devoirs des personnes\ndétenues qui, sans exception, doivent être traitées « à tout moment et en tout temps avec\nhumanité, respect et avec la dignité inhérente à la personne humaine »216. Ces droits\ncomportent le droit à l’alimentation, le droit à l’hygiène, la santé et l’habillement, le droit à la\ncommunication et la liberté de culte."},{"id":"a-hrc-36-crp-1-p0150","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"150","seq":152,"section":"3. Autres acteurs institutionnels","text":"La Commission nationale indépendante des droits de l’homme (CNIDH) a été créée\npar décret le 11 mai 2000217, mais n’a vu le jour qu’en 2011218. Une Commission composée\nde sept membres a été élue par l’Assemblée nationale. La CNIDH, qui a quatre antennes à\nNgozi, Gitega, Makamba et Bujumbura Mairie, a un double mandat de protection et de\npromotion des droits de l’homme. Elle reçoit des plaintes sur des violations des droits de\nl’homme et peut conduire des enquêtes. Elle a le pouvoir de référer des cas devant la justice.\nElle peut mener des visites dans les centres de détention afin de prévenir la torture et les\ntraitements inhumains et dégradants. La CNIDH a la responsabilité d’attirer l’attention du\nGouvernement sur tous les cas de violation qu’elle a documentés afin que des mesures\nadéquates soient prises. En matière de promotion, la CNIDH conduit des activités de\nsensibilisation et de formation219."},{"id":"a-hrc-36-crp-1-p0151","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"151","seq":153,"section":"3. Autres acteurs institutionnels","text":"La CNIDH jouit d’un « Statut A » auprès de l’Alliance mondiale des institutions\nnationales des droits de l’homme (GANHRI). Dès 2011, elle a fait preuve d’indépendance et\nde courage dans un contexte politique pourtant tendu. Cependant, à partir de 2014, plusieurs\nacteurs se sont inquiétés du degré d’indépendance de la CNIDH. Par exemple, le Comité des\ndroits de l’homme et le Comité contre la torture dans leurs observations finales en 2014220,\nainsi que le Comité des droits économiques sociaux et culturels dans ses observations finales\nde 2015221, ont exprimé leurs préoccupations sur l’indépendance et la crédibilité de la\nCNIDH du fait notamment d’une absence d’indépendance dans le processus de\nrenouvellement de deux commissaires en 2014 et d’un manque de ressources allouées par le\nGouvernement. Ces préoccupations ont été reprises en 2015 par le Rapporteur spécial sur la\nsituation des défenseurs des droits de l’homme222. Le 23 avril 2015, cinq membres de la\nCNIDH, y compris son Président, ont été remplacés. Jean-Baptiste Baribonekeza a alors été\nélu Président de la Commission et occupe ce poste à ce jour."},{"id":"a-hrc-36-crp-1-p0152","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"152","seq":154,"section":"3. Autres acteurs institutionnels","text":"Depuis avril 2015, comme constaté entre autres par le Haut-Commissaire des Nations\nUnies aux droits de l’homme, la CNIDH a eu tendance dans ses rapports et ses communiqués\nà minimiser le nombre et la gravité de violations des droits de l’homme commises dans le\npays. D’une manière plus générale, les déclarations de la CNIDH depuis avril 2015 ne\nreflètent pas l’ampleur des violations rapportées dans le pays. Lors des dialogues interactifs\nsur le Burundi au Conseil des droits de l’homme en mars et juin 2017, le Président de la\nCNIDH a fait état d’une amélioration de la situation sécuritaire et des droits de l’homme dans\nle pays tout en appelant le Gouvernement à reconsidérer sa décision de suspension de médias\net d’organisations non gouvernementales et à reprendre sa coopération avec les mécanismes\ndes droits de l’homme. Le 28 juillet 2017, la CNIDH a publié un communiqué de presse qui\n« note avec satisfaction une nette amélioration de la situation sécuritaire et des droits de\nl’homme dans tout le pays »223. Elle a également recommandé à la Cour pénale internationale\nde « clôturer l’examen préliminaire entamé depuis le 25 avril 2016 sur la situation au\nBurundi avec une décision permettant de laisser à la justice burundaise l’opportunité de\ns’occuper de toutes les plaintes concernant les crimes pouvant avoir été commis au\nBurundi »224."},{"id":"a-hrc-36-crp-1-p0153","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"153","seq":155,"section":"3. Autres acteurs institutionnels","text":"En novembre 2016, le Sous-comité d’accréditation (SCA) de la GANHRI a procédé à\nun examen extraordinaire de la CNIDH à l’issue duquel il a recommandé que la Commission\nsoit ré-accréditée avec le statut B, ayant jugé que « la CNIDH ne s'est pas prononcée de\nmanière à promouvoir la protection des droits de l'homme en réponse à des allégations\ncrédibles à propos de violations flagrantes des droits de l'homme commises par les autorités.\nCe silence dénote un manque d'indépendance. Par conséquent, le SCA est d'avis que la\nCNIDH agit d'une manière qui compromet gravement sa conformité avec les Principes de\nParis »225. La décision finale doit être prise en 2017."},{"id":"a-hrc-36-crp-1-p0154","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"154","seq":156,"section":"3. Autres acteurs institutionnels","text":"La Commission a rencontré le Président de la CNIDH le 10 mars 2017. Ce dernier\ns’est alors engagé à collaborer avec elle et à appuyer la mise en œuvre de son mandat.\nNéanmoins, en l’absence d’un réel suivi, la Commission a adressé le 12 juin 2017 une lettre\nau Président de la CNIDH lui demandant de partager avec elle toute information utile sur la\nsituation des droits de l’homme, ainsi que sur les cas graves de violation des droits de\nl’homme et d’atteinte à ceux-ci commis en particulier depuis le début de l’année 2017. Cette\nlettre est restée sans réponse tout comme la plupart des demandes faites de manière plus\ninformelle par le secrétariat de la Commission pour obtenir une copie du rapport annuel\nd’activités de la CNIDH pour l'année 2016226. La Commission a toutefois pu obtenir, par ses\npropres moyens, une copie de son rapport annuel 2015 et de celui couvrant le premier\nsemestre de 2017."},{"id":"a-hrc-36-crp-1-p0155","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"155","seq":157,"section":"3. Autres acteurs institutionnels","text":"Le 11 septembre 2017, le Président de la CNIDH a fait une déclaration publique dans\nlaquelle il a repris certaines des critiques des autorités burundaises au sujet du rapport de la\nCommission. Il a noté que la Commission n’avait conduit que des entretiens à l’extérieur du\nBurundi sans prendre en compte le point de vue des autorités227, sans toutefois préciser que le\nGouvernement burundais a refusé à la Commission l’accès au pays et n’a pas jugé bon de\npartager des informations pertinentes avec la Commission.\n(b)     Ombudsman"},{"id":"a-hrc-36-crp-1-p0156","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"156","seq":158,"section":"3. Autres acteurs institutionnels","text":"L’Ombudsman est une institution prévue par la Constitution dont l’article 237 dispose\nqu’il « reçoit les plaintes et mène des enquêtes concernant des fautes de gestion et des\nviolations des droits des citoyens commis par des agents de la fonction publique et du\njudiciaire et fait des recommandations à ce sujet aux autorités compétentes ». L’institution\nn’a toutefois été créée que cinq ans après l’adoption de la Constitution, par la loi n° 1/03 du\n25 janvier 2010. L’Ombudsman dispose d’un bureau à Bujumbura avec un département des\ndroits de l’homme, ainsi que des antennes régionales à Ngozi et Makamba. Il présente chaque\nannée un rapport aux deux Chambres du Parlement228."},{"id":"a-hrc-36-crp-1-p0157","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"157","seq":159,"section":"3. Autres acteurs institutionnels","text":"L’Ombudsman est nommé pour une durée de six ans non renouvelables par la\nmajorité des trois quarts des membres de l’Assemblée nationale, après approbation du Sénat.\nEn novembre 2016, Édouard Nduwimana, ancien Ministre de l’intérieur et Deuxième Vice-\nPrésident de l’Assemblée nationale, a succédé à Mohamed Rukara. Cette nomination a\nsuscité des critiques notamment de l’opposition, du fait de la politique jugée répressive\nmenée par Édouard Nduwimana à l’encontre des partis politiques d’opposition, des médias et\nde la société civile lorsqu’il était Ministre de l’intérieur229. Début septembre 2017, Édouard\nNduwimana a recontré le facilitateur Benjamin Mkapa. À l’issue de cette réunion, il a déclaré\nqu’une nouvelle rencontre serait organisée en octobre 2017 dans le cadre du dialogue inter-\nburundais mais qu’aux yeux du Gouvernement, elle devait être la dernière230."},{"id":"a-hrc-36-crp-1-p0158","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"158","seq":160,"section":"4. Corps de défense et de sécurité","text":"Au titre de l’article 110 de la Constitution du Burundi, « le Président de la République\nest le Commandant en chef des corps de défense et de sécurité ». La Constitution institue\négalement un organe consultatif – le Conseil national de sécurité –, « chargé d’assister le\nPrésident de la République et le Gouvernement dans l’élaboration de la politique en matière\nde sécurité, dans le suivi de la situation du pays en matière de sécurité et dans l’élaboration\ndes stratégies de défense, de sécurité et de maintien de l’ordre en cas de crise »231. Le\nPrésident de la République préside le Conseil national de sécurité. Les deux Vice-Présidents\net les Ministres chargés de la sécurité publique, de l’intérieur, des relations extérieures, de la\ndéfense nationale et de la justice sont membres de droit du Conseil national de sécurité qui\ncompte également neuf autres membres nommés par le Président de la République232."},{"id":"a-hrc-36-crp-1-p0159","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"159","seq":161,"section":"4. Corps de défense et de sécurité","text":"L’article 245 de la Constitution précise que les corps de défense et de sécurité du\nBurundi se composent d’une Force de défense nationale, d’une Police nationale et d’un\nService national de renseignement. Les corps de défense et de sécurité actuels sont le fruit,\naprès l’Accord d’Arusha, d’une fusion des forces de défense et de sécurité existantes avant la\nguerre civile, notamment les Forces armées du Burundi (FAB), avec des éléments des\ndifférents groupes armés. Ils doivent respecter l’équilibre ethnique du pays."},{"id":"a-hrc-36-crp-1-p0160","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"160","seq":162,"section":"4. Corps de défense et de sécurité","text":"Depuis les années 2000, le Burundi participe aux efforts de maintien de la paix, que ce\nsoit dans le cadre des Nations Unies ou de l’Union africaine. En juin 2017, 767 soldats, 10\npoliciers et 13 experts militaires burundais étaient déployés dans les missions de maintien de\nla paix des Nations Unies233. Le Burundi est le second contributeur le plus important à la\nMission de l’Union africaine en Somalie (AMISOM) avec 5 432 militaires234. L’envoi dans\nune mission de maintien de la paix est perçu au Burundi comme une récompense, le salaire\nque touchent les membres des corps de défense et de sécurité burundaises dans ce cadre étant\nnettement supérieur à celui en vigueur au Burundi.\n(a)     Force de défense nationale du Burundi"},{"id":"a-hrc-36-crp-1-p0161","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"161","seq":163,"section":"4. Corps de défense et de sécurité","text":"La Force de défense nationale du Burundi (FDNB) est placée, conformément à la\nConstitution, « sous la plus haute autorité du Président de la République qui en est le\nCommandant suprême »235. La loi organique n° 1/04 du 20 février 2017 rappelle que le\nPrésident nomme aux fonctions supérieures militaires236. Il est en outre le seul habilité à\nautoriser la FDNB à participer à des opérations pour la défense de l’État, pour le\nrétablissement de l’ordre et de la sécurité publique237. La loi organique prévoit que la FDNB\npeut intervenir en appui à la police, « exceptionnellement dans le maintien et le\nrétablissement de l’ordre public sur réquisition formelle de l’autorité habilitée [...] »238. Cette\nnouvelle disposition confirme la possibilité de déployer la FDNB dans le cadre d’opérations\nde police. Une réquisition par l’autorité administrative habilitée doit être faite par écrit en\nmentionnant la disposition légale en vertu de laquelle elle est demandée239."},{"id":"a-hrc-36-crp-1-p0162","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"162","seq":164,"section":"4. Corps de défense et de sécurité","text":"La FDNB est placée sous le commandement direct du Chef de la Force de défense\nnationale du Burundi, assisté par un Chef adjoint. Ces fonctions sont aujourd’hui occupées\nrespectivement par le Général-Major Prime Niyongabo, en poste depuis 2012, et le Général\nde brigade Joseph Ndayishimiye240. La loi organique n° 1/04 du 20 février 2017 précise que\nle Chef d’état-major général est chargé d’ « exécuter la politique du Gouvernement en\nmatière de défense », en plus de commander et d’administrer la FDNB241."},{"id":"a-hrc-36-crp-1-p0163","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"163","seq":165,"section":"4. Corps de défense et de sécurité","text":"La loi organique n° 1/04 du 20 février 2017 restructure également l’organisation de la\nFDNB. En vertu de la loi n° 1/019 de 2004, le commandement de la FDNB était assuré par\nl’état-major général, comprenant un état-major interarmes, un état-major de la formation et\nun état-major de la logistique, ainsi qu’un commandement de la marine et un commandement\nde l’aviation et des unités spécialisées242. La loi n° 1/019 de 2004 prévoyait en outre que la\nFDNB se répartissait en régions militaires sur le territoire national243. La loi organique\nsimplifie la structure et concentre le commandement au niveau du Chef d’état-major général\nen supprimant les états-majors subalternes ainsi que les régions militaires. L’article 23 de la\nloi organique précise en effet que la FDNB comprend « les Services centraux de l’état-major\ngénéral (EMG/FDNB) ainsi que les composantes, à savoir la Force terrestre, la Force de la\nmarine, la Force aérienne et des Unités spécialisées ». L’EMG/FDNB est désormais organisé\nen une douzaine de services qui pour la plupart existaient déjà, parmi lesquels le Service\nchargé de l’administration et de la gestion du personnel (G1)244, le Service chargé du\nrenseignement militaire (G2)245, le Service chargé de l’entraînement et des opérations (G3),\nle Service chargé de la logistique (G4)246, ainsi que les juridictions militaires et le ministère\npublic près de ces juridictions."},{"id":"a-hrc-36-crp-1-p0164","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"164","seq":166,"section":"4. Corps de défense et de sécurité","text":"La loi organique précise également la composition de la FDNB. La Force terrestre\ncomprend notamment un état-major, des divisions, des brigades d’armes d’appui et un\nbataillon de génie de combat (BGC)247. Les Unités spécialisées comprennent notamment la\nBrigade spéciale de protection des institutions (BSPI), à ce jour commandée par le Colonel\nDominique Nyamugaruka. La BSPI est chargée de la protection de l’institution présidentielle\nà l’intérieur et à l’extérieur du pays, de celle des hautes personnalités et des lieux sensibles\ncomme le palais présidentiel, les ministères et les états-majors de la FDNB, ainsi que de\nconduire toute mission spéciale qui lui est assignée par ces états-majors248."},{"id":"a-hrc-36-crp-1-p0165","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"165","seq":167,"section":"4. Corps de défense et de sécurité","text":"La loi organique prévoit que la FDNB « peut recourir au personnel de réserve [...]\nconstitué de citoyens, toute ethnie confondue, formés militairement à cet effet par la FDNB et\nd’anciens militaires de carrière pour une durée maximum de deux ans après l’âge limite de\nretraite »249. La référence à « toute ethnie confondue » dans cette nouvelle disposition a été\ncritiquée par certains observateurs qui y voient un moyen de contourner l’équilibre ethnique\nde la FDNB garanti par l’article 61 de la loi organique250.\n(b)     Police nationale burundaise"},{"id":"a-hrc-36-crp-1-p0166","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"166","seq":168,"section":"4. Corps de défense et de sécurité","text":"La loi organique n° 1/03 de février 2017251 précise les missions de la Police nationale\nburundaise (PNB) dont les principales sont d’assurer le maintien et le rétablissement de\nl’ordre public et de participer « à la protection, au secours de la population en toute\ncirconstance et à l’assistance aux personnes en danger et en détresse »252. La loi organique\nétend les attributions de la PNB en cas de manifestations et réunions publiques. La PNB peut\nnon seulement intervenir sur réquisition écrite de l’autorité administrative, mais aussi\ninterdire désormais une manifestation « pouvant porter préjudice à l’ordre et à la sécurité\npublics ». Dans ce cas, elle en rend compte à l’autorité hiérarchique et administrative253. La\nloi organique prévoit également que « sur ordre de la loi ou du commandement de l’autorité\nlégitime, la PNB disperse et/ou neutralise tout attroupement armé ou non armé formé pour\nenvahir, piller, dévaster les propriétés, porter atteinte à la vie des personnes, s’opposer à\nl’exécution de la loi, d’un jugement, d’un arrêt ou de toute autre mesure contraignante »254."},{"id":"a-hrc-36-crp-1-p0167","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"167","seq":169,"section":"4. Corps de défense et de sécurité","text":"La loi organique réaffirme par ailleurs le rôle du Président de la République comme\n« commandant suprême du corps de la PNB », en charge notamment de nommer aux plus\nhautes fonctions de ce corps255. La gestion courante et la direction de la PNB sont assurées\npar l’Inspecteur général de la PNB assisté d’un Inspecteur général-adjoint (anciennement\nDirecteur général et Directeur général adjoint) – à ce jour les Commissaires André\nNdayambaje et Godefroid Bizimana, respectivement256, tous deux sous l’autorité directe du\nMinistre de la sécurité publique, depuis août 2015 le Commissaire de police Chef Alain-\nGuillaume Bunyoni257."},{"id":"a-hrc-36-crp-1-p0168","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"168","seq":170,"section":"4. Corps de défense et de sécurité","text":"La PNB, composée d’officiers, de brigadiers, d’agents et de personnel d’appui,\ncomprend deux types de structure : l’une centralisée et l’autre déconcentrée258. La première\ncomporte quatre commissariats généraux et sept bureaux techniques. La loi organique n° 1/03\nde février 2017 a réorganisé les commissariats généraux, tous placés « sous l’autorité de\nl’Inspecteur général de la PNB »259. Le Commissariat général de la sécurité intérieure260\nintègre désormais en son sein la gestion de la police pénitentiaire. Le Commissariat général\nde la sécurité intérieure est divisé en six commissariats centraux, qui, en plus des affaires\npénitentiaires, gèrent l’instruction, l’entraînement et les opérations, le renseignement,\nl’administration et la logistique, ainsi que les unités spécialisées261. Ces dernières comportent\nnotamment la police de roulage et de sécurité routière dirigée par Alfred Innocent Museremu\njusqu’en août 2017, l’Appui à la protection des institutions (API), sous le commandement\nd’Alexandre Muyenge, chargé d’assurer la sécurité du Président de la République et des\ninstitutions en coordination avec la BSPI, et le Groupe mobile d’intervention rapide (GMIR)\ndestiné à apporter une réponse rapide sur l’ensemble du territoire en cas d’urgence262. Les\ntrois autres commissariats généraux couvrent respectivement la police judiciaire263, les\nmigrations264 (anciennement « Commissariat de la police de l’air, des frontières et des\nétrangers ») et la formation265."},{"id":"a-hrc-36-crp-1-p0169","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"169","seq":171,"section":"4. Corps de défense et de sécurité","text":"La structure centralisée de la PNB compte également des bureaux techniques destinés\nà aider l’Inspection générale à accomplir sa mission, dont le Bureau des opérations et\nentraînements et le Bureau du renseignement. Le Bureau des opérations et entraînements est\nconstitué de services et d’unités spécialisées parmi lesquelles l’« unité anti-émeute » ou\nBrigade anti-émeute (BAE), créée par ordonnance en septembre 2015 afin de « prévenir et\ngérer les grands événements et les actes de terrorisme graves »266."},{"id":"a-hrc-36-crp-1-p0170","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"170","seq":172,"section":"4. Corps de défense et de sécurité","text":"La structure déconcentrée de la police comprend les Commissariats régionaux\ncouvrant au moins trois provinces, les Commissariats provinciaux et les Commissariats\ncommunaux267. Chaque entité est divisée en trois sous-commissariats chargés respectivement\nde la police de sécurité intérieure, de la police judiciaire et des migrations. À la tête du\nCommissariat régional se trouve un Commissaire régional, assisté de trois Sous-\nCommissaires, tous placés sous la responsabilité directe de l’Inspecteur général de la PNB268.\nDe la même manière, un Commissaire provincial dirige le Commissariat provincial et un\nCommissaire communal le Commissariat communal269.\n(c)     Service national de renseignement"},{"id":"a-hrc-36-crp-1-p0171","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"171","seq":173,"section":"4. Corps de défense et de sécurité","text":"Prévu par l’article 245 de la Constitution, le Service national de renseignement (SNR),\ncommunément appelé « la Documentation », a été institué et est régi par la loi n° 1/04 du 2\nmars 2006 qui lui confère de larges attributions. L’article 3 de cette loi dispose que le SNR\n« a pour mission la recherche, la centralisation et l’exploitation de tous les renseignements\nd’ordre politique, sécuritaire, économique et social nécessaires à l’information et à\nl’orientation de l’action du Gouvernement en vue de garantir la sûreté de l’État. II s’agit\nnotamment de:\na) Prévenir toute menace contre l’État,\nb) Collecter, centraliser et contrôler toute information susceptible de contribuer à la\nprotection de l’État et de ses institutions, et à la sauvegarde des relations\ninternationales et de la prospérité économique,\nc) Détecter les types d’activités susceptibles de créer l’insécurité, d’inciter à la haine\net/ou à la violence ou d’entraîner des changements au sein des institutions de l’Etat\npar des moyens anti-démocratiques,\nd) Identifier toute tentative de manipulation politique, ethnique, religieuse, régionaliste\nou de toute autre nature visant à déstabiliser les institutions,\ne) Prévenir toute menace à l’ordre constitutionnel, à la sécurité publique, à l’intégrité\nterritoriale et à la souveraineté nationale,\nf) Détecter tout acte de terrorisme, tout trafic illicite et toute tentative de constitution\nd’organisations criminelles,\ng) Détecter les dysfonctionnements et les malversations au sein des services de l’État,\nh) Informer sur toute menace à l’environnement écologique du pays. »"},{"id":"a-hrc-36-crp-1-p0172","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"172","seq":174,"section":"4. Corps de défense et de sécurité","text":"L’article 4 de la loi n° 1/04 de 2006 précise que le SNR relève du Président de la\nRépublique et que sa gestion courante est assurée par un Administrateur général assisté d’un\nAdministrateur général-adjoint. Le poste d’Administrateur général est actuellement occupé\npar le Général Étienne Ntakirutimana, alias « Steve », nommé en avril 2015 après le\nlimogeage du Général Godefroid Niyombare, qui avait remplacé le Général Adolphe\nNshimirimana en 2014. L’Administrateur général planifie, coordonne et contrôle toutes les\nactivités du SNR270. Sans porter préjudice aux pouvoirs du Ministère public, l’Administrateur\ngénéral du SNR ou son délégué peut prendre toute mesure légale nécessaire à\nl’accomplissement de sa mission271. II rend compte directement au Président de la\nRépublique272."},{"id":"a-hrc-36-crp-1-p0173","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"173","seq":175,"section":"4. Corps de défense et de sécurité","text":"Le SNR est organisé en cinq départements, parmi lesquels le Département du\nrenseignement intérieur273 qui a « notamment pour mission de rechercher, centraliser et traiter\nles renseignements en rapport avec la sécurité intérieure; de prévenir les activités de\ndéstabilisation de nature politique ou sociale »274 et qui chapeaute 18 responsables\nprovinciaux, eux-mêmes responsables de chefs de secteur. Le Département du renseignement\nextérieur a quant à lui pour mission de détecter et prévenir toute activité de déstabilisation\nlancée depuis l’extérieur du pays ainsi que tout acte de terrorisme."},{"id":"a-hrc-36-crp-1-p0174","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"174","seq":176,"section":"4. Corps de défense et de sécurité","text":"Le SNR est composé d’administrateurs, d’officiers de renseignement et d’inspecteurs\nde renseignement, recrutés « dans le strict respect des équilibres prévus par la Constitution ».\nIls ont chacun la qualité d’Officier de police judiciaire à compétence générale pour toute\ninfraction ayant un rapport avec les missions du SNR275."},{"id":"a-hrc-36-crp-1-p0175","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"175","seq":177,"section":"5. Partis politiques","text":"La création et l’activité des partis politiques au Burundi sont régies par le Titre III de\nla Constitution qui institue le multipartisme et garantit « la non-ingérence des pouvoirs\npublics dans le fonctionnement interne des partis »276, ainsi que par la loi n° 1/16 du 10\nseptembre 2011 portant révision de la loi n° 1/006 du 26 juin 2003 portant organisation et\nfonctionnement des partis politiques. Ce texte impose notamment aux partis politiques de\n« mettre en avant la promotion et la protection des droits fondamentaux de la personne\nhumaine, la promotion de l’État de droit fondé sur la loi, le respect et la défense de la\ndémocratie, l’intégrité du territoire et la souveraineté nationale, les droits et libertés\nindividuels et collectifs, ainsi que la proscription de l’intolérance, de l’ethnisme, du\nrégionalisme, de la xénophobie et du recours à la violence sous toutes ses formes » et leur\ninterdit aux partis politiques de « mettre sur pied une organisation militaire ou paramilitaire\nquelconque »277. La loi n° 1/16 de 2011 prévoit par ailleurs un système d’agrément auprès du\nMinistre de l’intérieur préalablement à toute création de parti politique. Le Ministre de\nl’intérieur peut suspendre pour une durée maximale de six mois ou même demander à la\nchambre administrative de la Cour suprême de dissoudre un parti politique qui troublerait\nl’ordre public ou porterait atteinte à la sûreté de l’État278. Toute contestation de ces décisions\npeut se faire devant la Cour suprême.\n(a)     Conseil national pour la défense de la démocratie-Forces de défense de la démocratie\n(i)     Le parti"},{"id":"a-hrc-36-crp-1-p0176","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"176","seq":178,"section":"5. Partis politiques","text":"Le Conseil national pour la défense de la démocratie-Forces de défense de la\ndémocratie (CNDD-FDD), au pouvoir au Burundi depuis 2005, est issu de la résistance au\ncoup d’État d’octobre 1993 marqué par l’assassinat du Président Melchior Ndadaye. Cette\nrésistance majoritairement hutue a dans un premier temps rassemblé plusieurs partis\nd’opposition à l’Union pour le progrès national (UPRONA) – le parti à dominante tutsie –,\nparmi lesquels le Front pour la démocratie au Burundi (FRODEBU) et le Parti pour la\nlibération du peuple Hutu (PALIPEHUTU). Un état-major commun a alors été institué sous\nl’appellation de FDD-Intagoheka279 afin de coordonner les opérations militaires. Cependant,\naprès seulement trois mois d’existence, cette coalition militaire a éclaté du fait de rivalités\nnotamment entre les membres du FDD-Intagoheka et les Forces nationales de libération\n(FNL), la branche armée du PALIPEHUTU. L’union politique a également été de courte\ndurée, prenant fin après que le FRODEBU ait accepté, en septembre 1994, de rejoindre un\ngouvernement d’union nationale aux côtés de l’UPRONA, et que, dans la foulée, ait été\nofficiellement créé le CNDD dont le FDD-Intagoheka est devenu l’aile militaire."},{"id":"a-hrc-36-crp-1-p0177","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"177","seq":179,"section":"5. Partis politiques","text":"Depuis 1994, l’histoire du CNDD-FDD a été elle aussi marquée par plusieurs\nscissions internes, à commencer par l’éviction en 1998 de Léonard Nyangoma de la direction\ndu CNDD par Jean-Bosco Ndayikengurukiye, le chef d’état-major des FDD280, suivi de la\ndestitution de ce dernier en 2001 au profit de Pierre Nkurunziza. Le CNDD-FDD n’a pas\nadhéré à l’Accord d’Arusha en 2000. Ce n’est qu’en 2003 qu’un accord de cessez-le-feu\nglobal a été conclu entre les autorités burundaises de l’époque et le CNDD-FDD. L’article 2\nde cet accord stipulait que celui-ci faisait « partie intégrante de l’Accord d’Arusha pour la\npaix et la réconciliation au Burundi », alors même que trois ans auparavant le CNDD-FDD en\navait critiqué le contenu, en particulier l’institutionnalisation d’un équilibre ethnique qu’il\njugeait ne pas être conforme à la réalité281."},{"id":"a-hrc-36-crp-1-p0178","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"178","seq":180,"section":"5. Partis politiques","text":"Le CNDD-FDD a officiellement été enregistré comme parti politique en 2005 pour\npouvoir concourir lors des premières élections organisées depuis la fin de la guerre civile.\nPierre Nkurunziza, candidat à ces élections, a cédé sa place à la tête du parti à Hussein\nRadjabu, un ancien compagnon d’armes. Ce dernier cependant a été destitué de son poste en\nfévrier 2007 avant d’être arrêté deux mois plus tard et condamné à une peine de 13 ans de\nprison en avril 2008 pour atteinte à la sûreté de l’État282. Ses partisans se sont alors regroupés\nau sein de deux nouveaux partis : le CNDD-FDD « épris du respect de la loi » et l'Union pour\nla paix et le développement (UPD)-Zigamibanga. La même année, Alice Nzomukunda, qui\navait démissionné du poste de Second Vice-Président en 2006, a fondé l’Alliance\ndémocratique pour le renouveau (ADR). La dernière scission importante qu’a connue le\nCNDD-FDD remonte à la veille de l’élection présidentielle de 2015 lorsque plusieurs\nmembres influents du parti se sont opposés à la volonté de Pierre Nkurunziza d’être à\nnouveau candidat à cette élection283. Nombre d’entre eux, communément appelés « les\nfrondeurs », ont ensuite pris le chemin de l’exil en 2015, certains pour militer dans les partis\nd’opposition à l’extérieur du Burundi."},{"id":"a-hrc-36-crp-1-p0179","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"179","seq":181,"section":"5. Partis politiques","text":"En décidant de devenir un parti politique, le CNDD-FDD a adopté des statuts lors de\nson congrès organisé en août 2004 à Gitega. Ces statuts, amendés en 2016284, fixent\nnotamment comme objectifs du parti : « la promotion et la protection des droits\nfondamentaux de la personne humaine, la promotion d’un État de droit fondé sur la loi et la\njustice pour tous, la promotion, le respect et la défense de la démocratie véritable basée sur le\npluralisme des partis politiques, l’intégrité du territoire et la souveraineté nationale, les droits\net libertés individuels et collectifs, ainsi que la proscription de l’intolérance basée sur\nl’ethnisme, le régionalisme, la xénophobie, le genre, la religion, et du recours à la violence\nsous toutes ses formes »."},{"id":"a-hrc-36-crp-1-p0180","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"180","seq":182,"section":"5. Partis politiques","text":"Les statuts du CNDD-FDD ont mis en place une structure complexe qui distingue les\n« instances » des « organes » du parti comprenant notamment le Congrès national et le\nComité exécutif285. Le Congrès national est composé des membres du Comité exécutif, d’un\ndélégué par assemblée communale, du trésorier général du parti, du trésorier général-adjoint,\nd’un délégué de l’organe national dirigeant de chaque mouvement intégré au parti et de\npersonnalités invitées sans droit de vote286. De son côté, le comité exécutif rassemble\nnotamment les membres du conseil des sages et de la représentation légale du parti287. Cette\ndernière est formée du bureau politique, lui-même appuyé par des secrétaires exécutifs\nnationaux, de commissaires généraux, du porte-parole du parti, et des représentants nationaux\nde la ligue des jeunes – Imbonerakure –, de la ligue des femmes membres –\nAbakenyererarugamba –, et de celle des vétérans288."},{"id":"a-hrc-36-crp-1-p0181","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"181","seq":183,"section":"5. Partis politiques","text":"À l’issue du dernier congrès extraordinaire du CNDD-FDD en août 2016, de\nnouvelles instances dirigeantes ont été désignées. Évariste Ndayishimiye a été nommé\nSecrétaire général289, Joseph Ntakarutimana, Secrétaire général-adjoint, et Zénon\nNdaruvukanye, Trésorier général. Tous trois siègent avec Gélase Ndabirabe, Secrétaire\nnational chargé de la vie du parti, du suivi et de l’évaluation, au Conseil des sages qui est\nprésidé par le Chef de l’État. Godelieve Nininahazwe a été nommée Secrétaire nationale en\ncharge des questions politiques, administratives et juridiques ; Nancy Ninette Mutoni en\ncharge de la communication ; Anastase Minani en charge de l’idéologie, de la mobilisation et\nde la diaspora ; Emmanuel Sinzohagera en charge du développement ; Athanase\nHatungimana en charge des questions socio-culturelles ; et Sylvestre Ndayizeye en charge de\nla gestion des ligues affiliées au parti290.\n(ii)     Les Imbonerakure"},{"id":"a-hrc-36-crp-1-p0182","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"182","seq":184,"section":"5. Partis politiques","text":"Les Imbonerakure, dont le nom signifie « ceux qui voient loin », forment la ligue des\njeunes du CNDD-FDD. Composé d'hommes et de femmes âgés de 18 à 35 ans, les\nImbonerakure sont organisés selon une structure pyramidale similaire à celle du CNDD-FDD\nallant de l’échelon national aux collines en passant par les communes, avec à chaque niveau\nun responsable chargé de superviser l’activité des membres. Jusqu’au congrès extraordinaire\ndu CNDD-FDD en août 2016, les Imbonerakure avaient à leur tête un président en la\npersonne de Denis Karera. Depuis le congrès, la direction du mouvement est désormais\nassurée par Sylvestre Ndayizeye qui a été désigné comme Secrétaire national du CNDD-FDD\nen charge de la gestion des ligues affiliées au parti."},{"id":"a-hrc-36-crp-1-p0183","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"183","seq":185,"section":"5. Partis politiques","text":"Des informations ont circulé depuis 2014 sur l’entraînement militaire de certains\nImbonerakure au Burundi ainsi qu’en République démocratique du Congo, ainsi que sur des\ndistributions d’armes291. En avril 2014, un câble interne du BNUB adressé au siège des\nNations Unies à New York rendait compte d’armes et d’uniformes de l'armée et de la police\nqui auraient été distribués par deux généraux à des Imbonerakure et à des militaires\ndémobilisés à Rumonge, dans le sud du pays292. Plusieurs hauts responsables, dont les deux\nVice-Présidents, le Ministre de la sécurité publique et le Président du CNDD-FDD ont\ndémenti ces allégations293.\n(b)      L’opposition politique"},{"id":"a-hrc-36-crp-1-p0184","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"184","seq":186,"section":"5. Partis politiques","text":"Depuis la loi n° 1/25 du 14 novembre 2012, l’opposition politique est dotée d’un statut\nau Burundi294. Ce texte prévoit qu’« aucun dirigeant, aucun militant de l’opposition politique\nne peut subir de sanctions en raison de ses opinions politiques » et qu’« aucune atteinte ne\npeut être portée à sa liberté d’aller et de venir pour des raisons autres que celles prévues par\nles lois en vigueur »295. Tout membre de l’opposition peut saisir la chambre administrative de\nla Cour suprême s’il considère que ses droits n’ont pas été respectés. Toutefois, la loi n° 1/25\nde 2012 précise que « nul ne peut se prévaloir des droits [reconnus aux partis d’opposition]\npour perturber la paix et la sécurité du pays, sans encourir de peines prévues et réprimées par\nle Code pénal burundais »296. La loi reconnaît par ailleurs le statut de « Chef de l’opposition »\nqui revient de fait au président du parti d’opposition disposant du plus grand nombre de\nparlementaires297."},{"id":"a-hrc-36-crp-1-p0185","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"185","seq":187,"section":"5. Partis politiques","text":"L’opposition politique demeure divisée. L’histoire du CNDD-FDD, brièvement\nabordée plus haut, a montré combien au sein même d’un parti les scissions sont nombreuses.\nPareilles scissions et rivalités se retrouvent depuis longtemps dans les partis d’opposition et\nentre les différentes formations politiques opposées au CNDD-FDD. Certains Burundais ont\ndonné le nom de « nyakurisation » – de « nyakuri » signifiant « véritable » en kirundi – au\nphénomène de scissions au sein des partis dus aux tentatives du Gouvernement de\n« récupérer » certaines d’entre elles298. Le résultat est que plusieurs partis d’opposition ont\nune aile officiellement reconnue par le Gouvernement, qui soutient globalement le CNDD-\nFDD, et une aile « non reconnue » qui continue de se comporter comme un parti\nd’opposition."},{"id":"a-hrc-36-crp-1-p0186","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"186","seq":188,"section":"5. Partis politiques","text":"Les principaux partis d’opposition au Burundi sont aujourd’hui : l’Union pour le\nprogrès national (UPRONA), scindé entre l’aile Charles Nditije et l’aile Abel Gashatsi299 ; le\nFront pour la démocratie au Burundi (FRODEBU)300, divisé entre le FRODEBU-Sahwanya,\net le FRODEBU-Nyakuri301 ; le Conseil national pour la défense de la démocratie\n(CNDD)302 ; le Mouvement pour la solidarité et le développement (MSD)303 ; l’Union pour la\npaix et le développement (UPD)- Zigamibanga 304 ; et les Forces nationales de libération\n(FNL), divisées entre l’aile Agathon Rwasa, l’aile Jacques Bigirimana et le FNL Iragi rya\ngahutu de Jacques Kenese305. Plusieurs dirigeants de ces partis sont en exil depuis 2015 ou\n2016."},{"id":"a-hrc-36-crp-1-p0187","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"187","seq":189,"section":"5. Partis politiques","text":"En juillet 2015, huit partis politiques d’opposition en exil306 se sont joints à des\nmembres de la plateforme de la société civile « Halte au troisième mandat » et quatre\nanciennes personnalités politiques307 afin de former le Conseil national pour le respect de\nl’Accord d’Arusha pour la paix et la réconciliation au Burundi et de l’État de droit\n(CNARED)308. Les FNL d’Agathon Rwasa se sont désolidarisées de cette coalition\nd’opposition quand leur dirigeant a accepté de siéger comme Premier Vice-Président de\nl’Assemblée nationale, en juillet 2015. En novembre 2015, le mouvement « Halte au\ntroisième mandat » a annoncé son retrait du CNARED309. En mai 2016, l’UPD-Zigamibanga\ns’est à son tour désolidarisée du CNARED310 qui, signe également de rivalités internes, a\nconnu depuis sa création trois dirigeants. Son président actuel, Charles Nditije, a été élu en\nmars 2017311."},{"id":"a-hrc-36-crp-1-p0188","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"188","seq":190,"section":"6. Groupes armés d’opposition","text":"À l’instar de l’opposition politique, l’opposition armée est divisée en plusieurs\ngroupes, dont la plupart, relativement nouveaux, se sont déclarés officiellement depuis les\nattaques du 11 décembre 2015. Certaines attaques avaient néanmoins été revendiquées avant\ncette date comme celle qui a visé les troupes burundaises dans la province de Kayanza en\njuillet 2015312.\n(a)     Les Forces nationales de libération"},{"id":"a-hrc-36-crp-1-p0189","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"189","seq":191,"section":"6. Groupes armés d’opposition","text":"Branche armée du parti PALIPEHUTU depuis les années 1980, les Forces nationales\nde libération (FNL) ont un long passé en tant que groupe armé. La faction combattante\nregroupée aujourd’hui autour du Général Aloys Nzabampema est le fruit de rivalités et de\nscissions internes aux FNL et semble ne plus avoir de rapports proches avec la branche\npolitique du parti. Le Général Nzabampema coordonne ses opérations militaires tandis que la\ndirection politique du mouvement est assurée par Isidore Nibizi, ancien ambassadeur du\nBurundi en Russie. Les FNL de Nzabampema seraient principalement actives dans le Sud-\nKivu en RDC et mèneraient également des incursions sporadiques dans les provinces de\nl’ouest du Burundi.\n(b)     Forces républicaines du Burundi"},{"id":"a-hrc-36-crp-1-p0190","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"190","seq":192,"section":"6. Groupes armés d’opposition","text":"Les Forces républicaines du Burundi (FOREBU)313 ont annoncé leur création le 23\ndécembre 2015 par la voix du Lieutenant-Colonel Édouard Nshimirimana, ancien directeur\ndes transmissions au sein de la FNDB314. Les FOREBU sont dirigées par le Général\nGodefroid Niyombare, ancien Administrateur général du SNR et ancien chef d’état-major de\nl’armée qui a dirigé la tentative de coup d’État en mai 2015. Les FOREBU comprennent\nd’anciens membres des corps de défense et de sécurité burundaises ayant déserté, parmi\nlesquels leur porte-parole – l’ancien Commissaire de police Édouard Nibigira – et le Général\nPhilbert Habarugura qui serait à la tête des troupes, assisté d’un chef d’état-major, le Colonel\nJules Ndihokubwayo315. Les FOREBU ont annoncé qu’elles entendent poursuivre la lutte\narmée tant que le Gouvernement du Burundi refuse de participer à un dialogue inclusif. Elles\nauraient parfois mené des opérations communes avec le RED-Tabara et, parmi leurs faits\nd’arme, ont revendiqué l’assassinat du Lieutenant-Colonel Darius Ikurakure en mars 2016316."},{"id":"a-hrc-36-crp-1-p0191","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"191","seq":193,"section":"6. Groupes armés d’opposition","text":"Le 27 août 2017, un communiqué a annoncé que les FOREBU étaient rebaptisées\nForces populaires du Burundi (FPB) et étaient désormais sous le commandement du Général-\nMajor Jérémie Ntiranyibagira, avec comme responsable de communication l’ancien porte-\nparole des forces armées burundaises, Adolphe Manirakiza. Joint par Radio France\nInternationale (RFI), ce dernier a expliqué que cette réorganisation était due à « des divisions\ninternes sur des questions politiques » et à une volonté d’être « dorénavant neutres\npolitiquement, comme doivent l’être les corps de défense et de sécurité »317. Un tweet des\nFOREBU, en date du 28 août 2017, a néanmoins nié que le mouvement avait changé de nom\net d’organigramme. Les FPB seraient en fait une nouvelle aile318.\n(c)     Résistance pour un État de droit"},{"id":"a-hrc-36-crp-1-p0192","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"192","seq":194,"section":"6. Groupes armés d’opposition","text":"La Résistance pour un État de droit (RED-Tabara) s’est officiellement déclarée le 4\njanvier 2016, mais son chef d’état-major, Melchiade Biremba, un ancien membre du MSD, a\nlaissé entendre que ce groupe existait depuis 2010319. Le mouvement aurait été désigné\nauparavant comme FRONABU (Front national burundais) - Tabara, actif depuis environ\n2011 à l’est de la République démocratique du Congo. Selon un communiqué du 1er février\n2016, le porte-parole de la RED-Tabara serait David Ihotorihirwa320. La RED-Tabara dit\npartager les objectifs du CNARED mais par d’autres moyens321. D’après certaines sources, ce\nmouvement serait lié à Alexis Sinduhije, le président du parti MSD, que les États-Unis ont\nplacé sous sanctions en décembre 2015322. Alexis Sinduhije a publiquement nié qu’il en soit\nainsi323, mais plusieurs sources ont indiqué que la RED-Tabara est composée en grande partie\nde membres ou d’anciens membres du MSD et qu’il existerait des liens entre ce groupe armé\net le parti324. Des rumeurs ont fait état de défections récentes de membres du Red-Tabara vers\nles FOREBU, ce que la RED-Tabara a nié dans un communiqué en date du 28 août 2017325.\n(d)     Autres groupes armés d’opposition"},{"id":"a-hrc-36-crp-1-p0193","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"193","seq":195,"section":"6. Groupes armés d’opposition","text":"Plusieurs autres mouvements armés se sont déclarés depuis décembre 2015, sans que\nleur composition, leur importance ou leur capacité d’action n’aient pu être établie. La plupart\nd’entre eux sont à ce jour peu connus. On citera notamment le Mouvement de la résistance\npopulaire (MRP)326, l’Union des patriotes pour la révolution (UPR)327, la Force de libération\nde la démocratie au Burundi (FLDB)328, le Mouvement patriote chrétien (MPC)329 et le\nMalibu-Front patriotique du salut (Malibu-FPS)330."},{"id":"a-hrc-36-crp-1-p0194","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"194","seq":196,"section":"A. Principales tendances","text":"La crise politique que traverse le Burundi depuis 2015 s’est doublée d’une crise grave\ndes droits de l’homme. Si les prémices de cette situation ont été observées avant le 25 avril\n2015331, l’annonce à cette date par le Président Nkurunziza de sa décision de briguer un\nnouveau mandat a été suivie d’une détérioration significative de la situation des droits de\nl’homme. La Commission a documenté des violations graves et souvent d'une brutalité\nextrême, en particulier des exécutions extrajudiciaires, des arrestations et détentions\narbitraires, des disparitions forcées, des actes de torture et autres traitements cruels,\ninhumains ou dégradants, et des violences sexuelles. Ces types de violations avaient déjà été\nconstatés par le Haut-Commissaire des Nations Unies aux droits de l’homme332, l’Enquête\nindépendante des Nations Unies sur le Burundi (EINUB)333 et la Commission africaine des\ndroits de l’homme et des peuples334."},{"id":"a-hrc-36-crp-1-p0195","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"195","seq":197,"section":"A. Principales tendances","text":"Il ressort clairement du grand nombre de témoignages recueillis par la Commission\nque les manifestations ayant débuté en avril 2015, le coup d’État manqué de mai 2015 et les\nattaques contre quatre camps militaires à Bujumbura et ses environs le 11 décembre 2015 ont\nconstitué des étapes décisives dans l’escalade de la violence en 2015. Ce climat propice aux\nviolations des droits de l’homme a perduré en 2016 et 2017, entretenu notamment par des\ndiscours de haine de la part d’autorités gouvernementales et de membres du parti au\npouvoir335, ainsi que par l’impunité généralisée, aggravée par un manque d’indépendance du\nsystème judiciaire. Certaines violations ont été commises de manière plus clandestine, mais\ntout aussi brutale, depuis 2016."},{"id":"a-hrc-36-crp-1-p0196","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"196","seq":198,"section":"A. Principales tendances","text":"Les victimes, en majorité des jeunes hommes (à l’exception des victimes de violences\nsexuelles), ont comme point commun d’être des opposants au Gouvernement ou perçus\ncomme tels : manifestants contre la candidature de Pierre Nkurunziza à l’élection\nprésidentielle de 2015, membres de partis politiques d’opposition (en particulier du MSD et\ndes FNL), ainsi que leurs proches, membres des anciennes Forces armées burundaises (ex-\nnouvelles technologies », l’UPR a annoncé qu’elle était composée de cadres civils et militaires\ndéterminés à instaurer un régime démocratique au Burundi. L’UPR serait dirigée par Antoine\nSinzumunsi, ancien substitut général près de la Cour d’appel de Bujumbura.\nFAB)336, membres de la société civile, journalistes, personnes soupçonnées d’avoir soutenu\nou participé au coup d’État manqué de 2015, membres ou sympathisants de groupes armés\nd’opposition, ou personnes sur le chemin de l’exil suspectées de ce fait de rejoindre ces\ngroupes. La Commission a également constaté un phénomène d’embrigadement de la\npopulation au sein du CNDD-FDD et des Imbonerakure. Toute résistance a souvent été\nsource de violations des droits de l’homme."},{"id":"a-hrc-36-crp-1-p0197","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"197","seq":199,"section":"A. Principales tendances","text":"Les entretiens de la Commission avec des victimes et des témoins ont révélé un climat\nde peur profonde et généralisée : peur de témoigner par crainte de représailles337, peur de\nrentrer au pays malgré les appels répétés du Gouvernement en ce sens, mais aussi peur d’être\npoursuivi jusqu’en exil. Plusieurs victimes ont fait part à la Commission de leur sentiment\nd’insécurité même à l’extérieur du Burundi, notamment au Kenya, en Ouganda, en RDC et\nen Tanzanie où certaines ont affirmé avoir reconnu des agents du SNR et des\nImbonerakure338. Si la Commission n’a pas été en mesure de vérifier cette présence d’agents\nburundais ou d’Imbonerakure en dehors du pays, elle a néanmoins constaté chez de\nnombreux réfugiés qu’elle a interrogés la crainte réelle d’être tués ou attaqués dans les pays\noù ils se trouvent ou encore d’être ramenés de force au Burundi. La Commission a recueilli\ndes témoignages de réfugiés qui ont reçu des menaces anonymes par téléphone ou par\nmessages écrits, et qui ont même été physiquement attaqués339."},{"id":"a-hrc-36-crp-1-p0198","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"198","seq":200,"section":"A. Principales tendances","text":"La population de réfugiés burundais est estimée début septembre 2017 à 407 633\npersonnes340, soit environ quatre pour cent de la population totale du pays. De nombreux\nmembres de la société civile et journalistes restent en exil, pour certains sous le coup de\nmandats d’arrêt internationaux, et ceux qui sont toujours au Burundi sont contraints de\ntravailler clandestinement. Les principaux médias indépendants et organisations des droits de\nl’homme ont été suspendus ou radiés par le Gouvernement."},{"id":"a-hrc-36-crp-1-p0199","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"199","seq":201,"section":"A. Principales tendances","text":"Les violations des droits civils et politiques ont eu un impact direct sur la jouissance\ndes droits économiques, sociaux et culturels du fait, entre autres, des restrictions aux libertés,\net de la suspension par les principaux bailleurs d’une part importante de l’aide directe au\nGouvernement décidée en conséquence de ces violations. La dégradation rapide et prononcée\nde la situation économique depuis 2015 a exacerbé à son tour le phénomène d’extorsion qui a\npris différentes formes, y compris des demandes de rançon par des agents de l’État ou des\nlibérations d’individus contre paiement de sommes d’argent, de nouvelles taxes imposées à\nune population déjà appauvrie, des pressions pour contribuer financièrement à diverses\ndépenses du Gouvernement ou du parti au pouvoir, ou des actes d’extorsion sous menace par\ndes Imbonerakure. De nombreux Burundais interrogés par la Commission se sont plaints de\ndifficultés économiques croissantes. Néanmoins, la Commission, faute de temps, d’accès au\npays et de coopération de la part du Gouvernement, n’a pas pu enquêter de manière\napprofondie sur la situation des droits économiques, sociaux et culturels au Burundi341."},{"id":"a-hrc-36-crp-1-p0200","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"200","seq":202,"section":"B. Imputabilité","text":"Le paragraphe 23 (b) de la résolution 33/24 charge la Commission « d’identifier les\nauteurs présumés de violations des droits de l’homme et d’atteintes à ces droits commises au\nBurundi, en vue de faire pleinement respecter le principe de responsabilité »."},{"id":"a-hrc-36-crp-1-p0201","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"201","seq":203,"section":"B. Imputabilité","text":"La Commission a ainsi cherché à établir si des agents ou organes de l’État burundais,\nou des individus ou entités non-étatiques agissant sur instruction ou sous le contrôle de l’État,\nont été auteurs des violations des droits de l’homme et, de ce fait, ont par leur comportement\nengagé la responsabilité de l’État du Burundi."},{"id":"a-hrc-36-crp-1-p0202","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"202","seq":204,"section":"1. Responsabilité de l’État pour le comportement de ses organes","text":"En droit international, l’État est responsable du comportement de ses organes, quelle\nque soit leur fonction – législative, exécutive, judiciaire ou autre –, leur position dans\nl’organisation étatique, ou leur nature – qu’ils appartiennent au gouvernement central ou à\nune collectivité territoriale342. La Commission a des motifs raisonnables de croire que, depuis\navril 2015, les corps de défense et de sécurité ont été les principaux auteurs de violations des\ndroits de l’homme au Burundi, même lorsqu’ils ont agi conjointement avec des agents non-\nétatiques tels que les Imbonerakure."},{"id":"a-hrc-36-crp-1-p0203","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"203","seq":205,"section":"1. Responsabilité de l’État pour le comportement de ses organes","text":"Des membres du Service national de renseignement (SNR), y compris de haut niveau,\nà Bujumbura et dans plusieurs provinces, ont commis des actes engageant la responsabilité de\nl’État dont des exécutions extrajudiciaires, des arrestations et des détentions arbitraires, des\ndisparitions forcées, des actes de torture et traitements cruels, inhumains ou dégradants et des\nviolences sexuelles."},{"id":"a-hrc-36-crp-1-p0204","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"204","seq":206,"section":"1. Responsabilité de l’État pour le comportement de ses organes","text":"La Police nationale burundaise (PNB) a joué un rôle actif dès les premières\nmanifestations contre la candidature du Président Nkurunziza à un nouveau mandat. Depuis\navril 2015, des membres de la PNB ont commis des exécutions extrajudiciaires, des\narrestations et détentions arbitraires, des disparitions forcées, des actes de torture et\ntraitements cruels, inhumains ou dégradants et des violences sexuelles. Certaines unités,\nparmi lesquelles l’unité d’Appui à la protection des institutions (API) et la Brigade anti-\némeute (BAE), créée en septembre 2015, ont été particulièrement impliquées dans des\nviolations graves des droits de l’homme."},{"id":"a-hrc-36-crp-1-p0205","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"205","seq":207,"section":"1. Responsabilité de l’État pour le comportement de ses organes","text":"La Force de défense nationale burundaise (FDNB), en retrait au tout début de la crise,\na joué un rôle de plus en plus actif dans la répression d’opposants réels ou supposés. Des\nmembres de la FDNB ont été identifiés dans les témoignages recueillis par la Commission\ncomme auteurs présumés d’exécutions extrajudiciaires, d’arrestations arbitraires, de tortures\net de traitements cruels, inhumains ou dégradants. Parmi les unités impliquées dans des\nviolations graves des droits de l’homme, la Commission a identifié la Brigade spéciale de\nprotection des institutions (BSPI), le Bataillon de génie de combat (BGC, Camp Muzinda) et\nle Bataillon Support de la Première Région militaire (Camp Muha) à Bujumbura."},{"id":"a-hrc-36-crp-1-p0206","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"206","seq":208,"section":"1. Responsabilité de l’État pour le comportement de ses organes","text":"La Commission a également recensé des cas où des autorités administratives locales\nont commis ou donné l’ordre de commettre des violations des droits de l’homme, en\nparticulier des arrestations arbitraires.\n(résolution A/HRC/RES/33/24, para. 23 (a)). Les violations et atteintes visées sont avant tout des\nviolations et atteintes aux droits civils et politiques, tels que détaillées dans le présent rapport. D’autres\nenquêtes pourraient à l’avenir se concentrer sur la question des droits économiques et sociaux et des\nliens directs entre les violations de ces deux catégories de droits au Burundi."},{"id":"a-hrc-36-crp-1-p0207","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"207","seq":209,"section":"1. Responsabilité de l’État pour le comportement de ses organes","text":"Par ailleurs, l’État burundais est responsable du comportement des autorités\njudiciaires qui n’ont pas poursuivi ou jugé ses agents auteurs présumés des violations de\ndroits de l’homme. L’obligation de protéger les droits de l’homme impose en effet à l’État\nburundais de poursuivre et juger les auteurs de violations de manière à sanctionner ces\nderniers et à assurer aux victimes leur droit à la réparation. En ne luttant pas contre\nl’impunité, l’État burundais encourage la répétition des violations des droits de l’homme et la\ncommission d’autres violations.\n2.     Responsabilité de l’État pour le comportement d’individus ou de groupes non-étatiques"},{"id":"a-hrc-36-crp-1-p0208","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"208","seq":210,"section":"1. Responsabilité de l’État pour le comportement de ses organes","text":"En droit international, y compris des droits de l’homme, l’État peut être tenu\nresponsable de manière générale des comportements illicites d’individus ou de groupes non-\nétatiques quand ces derniers sont sous sa « totale dépendance »343. Sa responsabilité peut\négalement être engagée au cas par cas quand des individus ou groupes non-étatiques agissent\nsur ses instructions, ses directives, ou sous son « contrôle effectif »344, mais aussi quand ses\npropres agents reconnaissent et adoptent le comportement de groupes non-étatiques345. Ayant\nà l’esprit ces éléments, la Commission a examiné la question de la responsabilité de l’État\nburundais pour les actes commis par des Imbonerakure, dont elle a pu documenter\nl’implication dans des exécutions extrajudiciaires, des arrestations et détentions arbitraires,\ndes disparitions forcées, des tortures et traitements cruels, inhumains ou dégradants et des\nviolences sexuelles. Dès 2008, plusieurs rapports avaient déjà fait état de l’implication\nd’Imbonerakure dans la commission d’atteintes aux droits de l’homme et dans des actes\nd’intimidation à l’encontre d’opposants réels ou supposés du CNDD-FDD, notamment\npendant les périodes pré-électorales346. En 2016, le Comité contre la torture s’est également\ninquiété « d’informations concordantes révélant que [le] groupe [des Imbonerakure] […]\naurait été armé et entraîné par les autorités de l’État partie et interviendrait en liaison avec la\npolice et les membres du Service national de renseignement dans les arrestations ainsi que de\nmanière autonome dans des actes de répression, et ce, en toute impunité »347.\nLa « totale dépendance »"},{"id":"a-hrc-36-crp-1-p0209","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"209","seq":211,"section":"1. Responsabilité de l’État pour le comportement de ses organes","text":"La « totale dépendance », si elle est démontrée, entraîne une présomption de\nresponsabilité de l’État sur tous les actes commis par les personnes ou les organes sous sa\ndépendance qui comme tels peuvent être considérés comme ses agents ou ses organes de fait.\nLa jurisprudence internationale a cependant considéré qu’une « telle assimilation aux organes\nde l’État de personnes ou d’entités auxquelles le droit interne ne confère pas ce statut ne peut\nque rester exceptionnelle, elle suppose en effet que soit établi un degré particulièrement élevé\nde contrôle de l’État sur les personnes ou les entités en cause [...] »348. Au vu des\ninformations à sa disposition, la Commission ne peut conclure à une dépendance totale des\nImbonerakure vis-à-vis de l’État burundais."},{"id":"a-hrc-36-crp-1-p0210","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"210","seq":212,"section":"1. Responsabilité de l’État pour le comportement de ses organes","text":"La jurisprudence internationale a en effet précisé que le fait qu’un État ait fourni « des\nressources militaires et financières considérables » à des individus ou organisations ne suffit\npas à conclure à la « totale dépendance » de ces derniers vis-à-vis de l’État349. Pour cela, il\nfaut pouvoir démontrer un alignement systématique de ces individus ou organisations sur la\npolitique de l’État. En outre, les juges internationaux ont à plusieurs reprises considéré que le\nfait que l’État ait créé l’organe en question constitue un indice supplémentaire d’une\ndépendance totale350."},{"id":"a-hrc-36-crp-1-p0211","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"211","seq":213,"section":"1. Responsabilité de l’État pour le comportement de ses organes","text":"Dans le cas des Imbonerakure, la Commission a recueilli des témoignages selon\nlesquels des membres des corps de défense et de sécurité, particulièrement du SNR, ont\nenvoyé certains Imbonerakure faire un entraînement militaire en République démocratique du\nCongo, notamment avant avril 2015351, et leur ont donné des armes à plusieurs reprises352,\nainsi que de l’argent après accomplissement de missions353, y compris durant la période\ncouverte par le mandat de la Commission. Cependant, il est difficile, au regard de ces\ninformations, de conclure à la fourniture de ressources militaires et financières\n« considérables » aux Imbonerakure."},{"id":"a-hrc-36-crp-1-p0212","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"212","seq":214,"section":"1. Responsabilité de l’État pour le comportement de ses organes","text":"De la même manière, si un certain alignement des Imbonerakure, comme du CNDD-\nFDD plus généralement, sur la politique de l’État burundais, voire même une identité\ncomplète de vues et d’objectifs entre ces deux entités, peut être démontré, notamment à la\nlecture des communiqués du CNDD-FDD354 ou à la lumière des slogans prononcés lors des\nmarches ou manifestations organisées par le CNDD-FDD et sa ligue des jeunes, tous en\nsoutien à la politique du Président Nkurunziza et de son gouvernement355, la Commission\nn’est pas en mesure de caractériser cet alignement de systématique356. La Commission ne\npeut notamment pas exclure une certaine marge d’autonomie des Imbonerakure vis-à-vis de\nl’État burundais, en particulier dans la commission d’actes contraires aux droits de l’homme."},{"id":"a-hrc-36-crp-1-p0213","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"213","seq":215,"section":"1. Responsabilité de l’État pour le comportement de ses organes","text":"En outre, les Imbonerakure n’ont pas été créés par l’État burundais, mais par le parti\nCNDD-FDD357. Certains témoignages ont indiqué qu’un groupe d’Imbonerakure, souvent\ndésigné comme le « groupe des démobilisés »358, avait été entraîné, armé et rémunéré à partir\nde 2006 par le Général Adolphe Nshimirimana (Administrateur général du SNR de 2004 à\n2014) afin de mener des opérations contraires aux droits de l’homme359. Si ces informations\nétaient avérées, les Imbonerakure ne pourraient pas pour autant être considérés dans leur\nensemble comme un organe créé par l’État burundais, car la ligue elle-même a été fondée par\nle CNDD-FDD dont elle dépend statutairement. On pourrait néanmoins, si ces informations\nétaient bien avérées, se demander dans quelle mesure ce groupe plus restreint de «\ndémobilisés » ne pourrait pas constituer une entité sous la totale dépendance de l’État\nburundais.\nInstructions et directives"},{"id":"a-hrc-36-crp-1-p0214","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"214","seq":216,"section":"1. Responsabilité de l’État pour le comportement de ses organes","text":"L’article 8 du Projet d’articles sur la responsabilité de l’État pour fait\ninternationalement illicite360 prévoit que « le comportement d’une personne ou d’un groupe\nde personnes est considéré́ comme un fait de l’État d’après le droit international si cette\npersonne ou ce groupe de personnes, en adoptant ce comportement, agit en fait sur les\ninstructions ou les directives ou sous le contrôle de cet État ». Au regard de cette disposition,\nla Commission a reçu des témoignages faisant état de liens étroits entre des membres, y\ncompris haut placés, du SNR, de la PNB361, de l’armée362 et de la Présidence363, d’une part, et\ncertains Imbonerakure, d’autre part, ces derniers ayant reçu des premiers des instructions ou\ndirectives pour violer les droits de l’homme, y compris des ordres spécifiques de tuer certains\nopposants ou détracteurs. La Commission a également documenté des cas précis\nd’Imbonerakure agissant sur instruction d’autres agents étatiques, par exemple des chefs de\nzone364.\n« Contrôle effectif »"},{"id":"a-hrc-36-crp-1-p0215","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"215","seq":217,"section":"1. Responsabilité de l’État pour le comportement de ses organes","text":"L’article 8 du Projet d’articles sur la responsabilité de l’État pour fait\ninternationalement illicite, déjà cité, prévoit également l’imputation du comportement d’une\npersonne ou d’un groupe de personnes à un État si ces personnes agissent sous le contrôle de\nce dernier. La Cour internationale de justice (CIJ) a précisé la notion de contrôle en\nintroduisant la qualification de « contrôle effectif »365 qui doit être démontrée « à l’occasion\nde chacune des opérations au cours desquelles les violations alléguées se seraient produites et\nnon pas en général à l’égard de l’ensemble des actions menées par les personnes ou groupes\nde personnes ayant commis lesdites violations »366. La jurisprudence internationale a retenu\nplusieurs critères dont la participation des agents de l’État au financement, l’équipement et à\nl’entraînement des individus ou groupe visés, leur participation à l’organisation, la\ncoordination ou la planification des opérations, l’émission d’ordres ou d’instructions précises,\net le contrôle de l’État au cours de chaque opération367."},{"id":"a-hrc-36-crp-1-p0216","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"216","seq":218,"section":"1. Responsabilité de l’État pour le comportement de ses organes","text":"Comme indiqué plus haut, la Commission a reçu plusieurs témoignages faisant état\nd’Imbonerakure ayant reçu des armes de la part d’agents de l’État burundais, ainsi que des\nsommes d’argent après accomplissement de missions et, dans certains cas, un entraînement\nmilitaire, ainsi que d’Imbonerakure ayant opéré avec des uniformes et des armes de la police\nou de l’armée au vu et en présence de membres de ces corps368."},{"id":"a-hrc-36-crp-1-p0217","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"217","seq":219,"section":"1. Responsabilité de l’État pour le comportement de ses organes","text":"La Commission a également pu établir sur la base de témoignages qu’elle a recueillis,\ncomme cela a été décrit plus haut, que, dans un certain nombre de cas, des agents de l’État,\nprincipalement du SNR, de la PNB, de la FDNB, et de la Présidence avaient contribué à\nl’organisation, la coordination ou la planification d’opérations menées par des Imbonerakure,\nnotamment en émettant des ordres ou des instruction précises."},{"id":"a-hrc-36-crp-1-p0218","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"218","seq":220,"section":"1. Responsabilité de l’État pour le comportement de ses organes","text":"De nombreux témoignages ont en outre rapporté la présence d’Imbonerakure aux\ncôtés de membres de la PNB ou du SNR, y compris dans des centres de détention, lorsque\ndes violations des droits de l’homme ont été commises369. Cette présence atteste dans ces cas\nparticuliers d’une forme de contrôle de l’État sur les Imbonerakure, du moins d’une\ncoparticipation de ces derniers à la commission d’actes contraires aux droits de l’homme. En\ncertaines circonstances, par exemple pendant les opérations dans les quartiers où les policiers\nou les militaires ne connaissaient pas individuellement les habitants, des Imbonerakure\nprovenant de ces localités sont intervenus comme indicateurs, guidant les agents des forces\nde sécurité et les aidant à identifier les futures victimes de violations des droits de\nl’homme370."},{"id":"a-hrc-36-crp-1-p0219","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"219","seq":221,"section":"1. Responsabilité de l’État pour le comportement de ses organes","text":"En 2017, dans une réponse à des questions posées par l’ONG Human Rights Watch, la\nSecrétaire exécutive chargée de la communication et de l’information des CNDD-FDD,\nNancy-Ninette Mutoni, a expliqué que les Imbonerakure participent à des « comités mixtes\nde sécurité humaine »371 comprenant des civils, des autorités, des agents administratifs et des\nmembres des corps de défense et de sécurité. Nancy-Ninette Mutoni a précisé que, dans ces\ncomités, les Imbonerakure « ont non seulement le droit mais également le devoir de\nsurveillance et de signaler tout mouvement et actes suspects aux forces de l’ordre »372. Cette\nexplication rejoint une déclaration du Ministre de l’intérieur, mentionnée en 2016 par le\nComité contre la torture373, selon laquelle des Imbonerakure faisaient partie de la stratégie\nnationale de sécurité dans le cadre des comités mixtes de sécurité humaine. La Commission\nn’a pas été en mesure de vérifier si ces comités mixtes fonctionnaient réellement, le Conseil\nde sécurité nationale ayant récemment appelé à les « redynamiser de manière qu’ils soient\nopérationnels sur toutes les collines ou quartiers, les zones et les communes »374. Si les\npropos de la Secrétaire exécutive chargée de la communication et de l’information du\nCNDD-FDD et du Ministre de l’intérieur reflétaient la réalité, l’implication d’Imbonerakure\nau sein des comités mixtes confirmerait également le contrôle effectif de l’État burundais sur\nles membres de la ligue des jeunes du CNDD-FDD.\nReconnaissance et adoption"},{"id":"a-hrc-36-crp-1-p0220","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"220","seq":222,"section":"1. Responsabilité de l’État pour le comportement de ses organes","text":"L’article 11 du Projet d’articles sur la responsabilité de l’État pour fait\ninternationalement illicite prévoit qu’un « comportement qui n’est pas attribuable à l’État [...]\nest néanmoins considéré́ comme un fait de cet État d’après le droit international si, et dans la\nmesure où, cet État reconnaît et adopte ledit comportement comme sien ». La Commission a\nreçu des témoignages selon lesquels des Imbonerakure ont procédé à des arrestations et remis\nles individus appréhendés au SNR ou à la PNB375. En acceptant ces individus appréhendés\nillégalement, les agents du SNR et de la PNB ont adopté et reconnu ce comportement illicite."},{"id":"a-hrc-36-crp-1-p0221","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"221","seq":223,"section":"1. Responsabilité de l’État pour le comportement de ses organes","text":"Comme indiqué plus haut, la Commission a également recueilli des témoignages\nfaisant état d’Imbonerakure ayant opéré avec des uniformes et des armes de la police ou de\nl’armée au vu et en présence de membres de ces corps. Dans ces cas, il pourrait être démontré\nque les agents étatiques reconnaissent et adoptent le fait que les Imbonerakure opèrent dans\ndes uniformes et avec des armes qu’ils ne sont pas autorisés à porter et que, dans ces\nconditions, ils commettent des actes contraires aux droits de l’homme.\nViolation de l’obligation de protéger les droits de l’homme"},{"id":"a-hrc-36-crp-1-p0222","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"222","seq":224,"section":"1. Responsabilité de l’État pour le comportement de ses organes","text":"La Commission tient enfin à souligner que l’État burundais a l’obligation de protéger\nles droits de l’homme sur son territoire, notamment quand il a connaissance ou aurait dû\navoir connaissance du risque de commission d’une atteinte à ceux-ci par des individus et des\ngroupes non-étatiques et qu’il ne prend pas les mesures nécessaires pour prévenir cette\natteinte. En ne prenant pas de telles mesures de prévention, l’État burundais viole son\nobligation de protéger les droits de l’homme. Il viole également cette obligation en ne\nprenant pas les mesures nécessaires pour que des enquêtes soient menées sur ces atteintes et\nque leurs auteurs soient arrêtés, jugés et punis. En ne luttant pas contre l’impunité, l’État\nburundais encourage la répétition des atteintes aux droits de l’homme et la commission\nd’autres atteintes à ces droits."},{"id":"a-hrc-36-crp-1-p0223","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"223","seq":225,"section":"3. Responsabilité des groupes armés d’opposition","text":"La Commission a recueilli des informations sur des attaques ciblées par des groupes\narmés d’opposition contre des postes de l’armée et de la police, ainsi que des attaques de plus\ngrande envergure comme en juillet 2015 dans la province de Kayanza et le 11 décembre 2015\ncontre quatre installations militaires à Bujumbura et à Mujejuru, dans la province de\nBujumbura. La Commission a reçu des informations sur des assassinats de membres des\ncorps de défense et de sécurité et du CNDD-FDD, y compris des Imbonerakure, à Bujumbura\net plusieurs autres localités du pays376."},{"id":"a-hrc-36-crp-1-p0224","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"224","seq":226,"section":"3. Responsabilité des groupes armés d’opposition","text":"Malgré plusieurs tentatives, la Commission a fait face à des difficultés dans ses efforts\nd’enquêter de manière approfondie sur les attaques et assassinats contre des civils et des\nmembres des corps de défense et de sécurité attribués à des groupes armés de l’opposition.\nElle n’a donc pas été en mesure de déterminer si leurs auteurs relevaient d’un groupe armé\norganisé avec une structure connue, et, tel était le cas, d’identifier quel groupe. La\nCommission a pris toutefois note que certaines attaques et assassinats contre des civils et des\nagents de l’État ont été revendiqués par des responsables de groupes armés377, mais n’a pas\nété en mesure de réunir les informations nécessaires afin de corroborer ces revendications."},{"id":"a-hrc-36-crp-1-p0225","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"225","seq":227,"section":"3. Responsabilité des groupes armés d’opposition","text":"Les obstacles à ces enquêtes sont dus en partie à l’impossibilité d’accéder aux témoins\nqui se trouvent pour beaucoup au Burundi dans la mesure où la Commission n’a pas été\nautorisée à se rendre sur le territoire burundais, mais aussi au refus du Gouvernement\nburundais de partager des informations avec la Commission malgré les différentes demandes\nque cette dernière lui a adressées en ce sens."},{"id":"a-hrc-36-crp-1-p0226","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"226","seq":228,"section":"3. Responsabilité des groupes armés d’opposition","text":"La difficulté d’enquêter sur ces cas est également liée au manque de clarté qui prévaut\nconcernant les groupes armés d’opposition dont les structures, les chaînes de\ncommandement, les capacités et les modes opératoires restent flous. Ceci est dû en grande\npartie à leurs dissensions internes et aux alliances qui se font et défont fréquemment entre ces\ngroupes et leurs membres, ainsi que certains de leurs dirigeants. En outre, d’après certains\ntémoignages recueillis par la Commission, ces groupes ne semblent pas avoir de base\nterritoriale fixe, leurs membres se déplaçant d’un pays à un autre, pour certains notamment\nentre le Rwanda et la RDC378."},{"id":"a-hrc-36-crp-1-p0227","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"227","seq":229,"section":"3. Responsabilité des groupes armés d’opposition","text":"La Commission a analysé les rapports de la CNIDH couvrant l’année 2015 et le\npremier semestre 2017379. Il ressort notamment de la lecture du rapport 2015 que des actes\nauraient été commis par des « groupes armés », des « éléments armés », des « groupes\norganisés » et des « individus armés », sans qu’il ne soit néanmoins apporté de précisions sur\nl’identité de ces groupes ou de ces individus, ni sur leur origine380. La CNIDH n’a pas\npartagé d’informations à ce sujet avec la Commission, malgré une demande spécifique de\ncelle-ci adressée à son président."},{"id":"a-hrc-36-crp-1-p0228","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"228","seq":230,"section":"1. Droit à la vie","text":"Dans les résolutions 30/27, S/24/1 et 33/24 adoptées en 2015 et 2016, le Conseil des\ndroits de l’homme a exprimé sa préoccupation sur les allégations de violation du droit à la vie\nau Burundi, en particulier les exécutions extrajudiciaires. Le Haut-Commissaire des Nations\nUnies aux droits de l’homme et l’EINUB ont également mis l’accent sur ce type de violation\net d’atteinte aux droits de l’homme dans leurs rapports respectifs au Conseil des droits de\nl’homme381, tout comme le Comité contre la torture dans ses observations finales du 9\nseptembre 2016382.\n(a)     Droit applicable\n(i)     Droit international"},{"id":"a-hrc-36-crp-1-p0229","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"229","seq":231,"section":"1. Droit à la vie","text":"Le droit à la vie est garanti par l’article 3 de la DUDH, l’article 6 (1) du PIDCP,\nl’article 6 de la CDE et l’article 10 de la CPDH. Ce droit est par ailleurs indérogeable en cas\nde « danger public exceptionnel [qui] menace l'existence de la nation et est proclamé par un\nacte officiel »383."},{"id":"a-hrc-36-crp-1-p0230","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"230","seq":232,"section":"1. Droit à la vie","text":"Les exécutions extrajudiciaires, sommaires ou arbitraires sont les violations les plus\nflagrantes du droit à la vie. Par « exécution », il est fait référence à la qualité d’agent étatique\nde l’auteur ou à l’acquiescement d’un agent étatique à la commission de l’acte. Le terme\n« extrajudiciaire » renvoie pour sa part à l’absence de procédure judiciaire. L’État a le devoir\nde prévenir les exécutions extrajudiciaires par des agents étatiques384. Conformément aux\nPrincipes relatifs à la prévention efficace des exécutions extrajudiciaires, arbitraires et\nsommaires et aux moyens d'enquêter efficacement sur ces exécutions385, il est tenu de mener\ndes enquêtes approfondies, rapides et impartiales sur ces actes, et lorsque ces enquêtes se sont\nrévélées concluantes, de poursuivre les auteurs en justice386. Le fait pour un État de ne pas\nmener des enquêtes sur des allégations de privation arbitraire du droit à la vie constitue une\nviolation du droit à un recours effectif387, mais aussi du droit à la vie lui-même388."},{"id":"a-hrc-36-crp-1-p0231","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"231","seq":233,"section":"1. Droit à la vie","text":"Le Code de conduite pour les responsables de l'application des lois389 et les Principes\nde base sur le recours à la force et l'utilisation des armes à feu par les responsables de\nl'application des lois390 restreignent l’usage de la force et des armes à feu par les représentants\nde la loi, « qu'ils soient désignés ou élus, qui exercent des pouvoirs de police et en particulier\ndes pouvoirs d'arrestation ou de détention »391. Ces textes prévoient notamment que cet usage\ndoit être « nécessaire », à savoir qu’aucun autre moyen ne peut être utilisé pour prévenir un\ncrime ou détenir un suspect, « légitime », c’est-à-dire destiné à prévenir des crimes ou\nconduire des arrestations prévues par la loi, et « proportionnel » à l’objectif poursuivi et la\ngravité de l’acte qu’il entend réprimer392. Ces conditions s’appliquent à toute situation dans\nlaquelle les responsables de l'application des lois sont obligés d’avoir recours à la force,\nnotamment dans la gestion de manifestations publiques."},{"id":"a-hrc-36-crp-1-p0232","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"232","seq":234,"section":"1. Droit à la vie","text":"L’État a par ailleurs la responsabilité de protéger la vie des personnes en détention.\nLes décès survenus en détention peuvent constituer des exécutions extrajudiciaires lorsqu’ils\nrésultent d’un usage excessif et injustifié de la force par des agents étatiques, de torture ou de\ntraitements cruels, inhumains ou dégradants par ces mêmes agents, ou de l’incapacité des\nautorités pénitentiaires de protéger la vie des détenus, par exemple du fait des mauvaises\nconditions de détention ou de la violence exercée par d’autres détenus393. La charge de la\npreuve repose alors sur les autorités qui doivent donner des explications, le décès sera sinon\nconsidéré à première vue comme une violation du droit à la vie394. Les autorités doivent\nmener des enquêtes approfondies et impartiales dans les plus brefs délais pour confirmer ou\nécarter cette présomption395."},{"id":"a-hrc-36-crp-1-p0233","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"233","seq":235,"section":"1. Droit à la vie","text":"L’État est également responsable des atteintes au droit à la vie commises par des\nagents non étatiques agissant en soutien d’agents étatiques. Même si ces agents ne reçoivent\npas directement des ordres venant d’autorités étatiques, les exécutions qu’ils commettraient\npour le compte de l’État ou avec son consentement seraient susceptibles de constituer des\nexécutions extrajudiciaires396.\n(ii)     Droit régional"},{"id":"a-hrc-36-crp-1-p0234","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"234","seq":236,"section":"1. Droit à la vie","text":"Le droit à la vie est garanti par l’article 4 de la CADHP ainsi que par l’article 5 de la\nCharte africaine des droits et du bien-être de l’enfant. Cette dernière disposition précise que\n« ce droit est imprescriptible ».\n(iii)     Droit national"},{"id":"a-hrc-36-crp-1-p0235","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"235","seq":237,"section":"1. Droit à la vie","text":"L’article 24 de la Constitution du Burundi dispose que « toute femme, tout homme a\ndroit à la vie ». Le Code pénal burundais, pour sa part, détaille les peines qui peuvent être\nprononcées contre les auteurs d’homicides volontaires, c’est-à-dire commis « avec le dessein\nd’attenter à la personne d’un individu déterminé » et les homicides involontaires qui de leur\ncôté causent la mort « par défaut de prévoyance ou de précaution, par maladresse,\nimprudence, inattention, négligence ou manquement à une obligation de sécurité ou de\nprudence imposée par la loi ou le règlement, mais sans intention d’attenter à la vie\nd’autrui »397. Parmi les homicides volontaires, le Code pénal distingue les meurtres qui\nconsistent à donner la mort volontairement à autrui et les assassinats « commis avec\npréméditation ». Tous deux sont punis de servitude pénale à perpétuité. Le fait de mutiler un\ncadavre ou de le fouiller est une circonstance aggravante qualifiée d’acte de barbarie398.\n(b)      Faits"},{"id":"a-hrc-36-crp-1-p0236","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"236","seq":238,"section":"1. Droit à la vie","text":"Les violations et atteintes au droit à la vie ne sont pas un phénomène nouveau au\nBurundi. En 2014, le Comité des droits de l’homme a exprimé sa préoccupation face aux\n« informations faisant état d’allégations d’un nombre important de meurtres, y compris par\nles forces de sécurité et de défense, en particulier dans la période qui a suivi les élections de\n2010 et pour lesquelles les enquêtes, aux fins de poursuite, de jugement et de condamnation\ndes responsables n’ont pas été menées dans tous les cas »399. La Commission a cependant\nconstaté une aggravation de la situation depuis avril 2015. La crise politique que traverse\ndepuis le pays, marquée par un climat de violence et d’impunité généralisées, a conduit à une\nmultiplication des violations et atteintes au droit à la vie par des membres des corps de\ndéfense et de sécurité en premier lieu, mais aussi par des Imbonerakure agissant sous le\ncontrôle d’agents étatiques ou seuls, ainsi que par des personnes que la Commission n’a pas\nété en mesure d’identifier. Des assassinats ciblés ont ainsi eu lieu, y compris contre des\nmembres du Gouvernement ou des agents de l’État, sans que les auteurs ne soient connus."},{"id":"a-hrc-36-crp-1-p0237","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"237","seq":239,"section":"1. Droit à la vie","text":"Selon les nombreux témoignages recueillis par la Commission, les principales\nvictimes des violations et atteintes au droit à la vie ont un profil similaire à celui des victimes\nd’autres violations graves des droits de l’homme commises depuis avril 2015. Il s’agit en\nmajorité de membres de partis d’opposition, de personnes soupçonnées d’être des\nsympathisants de ces partis ou d'appartenir à des groupes armés d'opposition, des citoyens\nopposés au nouveau mandat du Président Nkurunziza et pour certains ayant participé aux\nmanifestations de 2015, ainsi que des ex-FAB. Dans plusieurs cas, les violations du droit à la\nvie ont également touché des membres de la famille des personnes ciblées400."},{"id":"a-hrc-36-crp-1-p0238","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"238","seq":240,"section":"1. Droit à la vie","text":"La Commission a reçu des informations sur de nombreuses attaques à la grenade qui\nont eu lieu en 2015, 2016 et 2017 dans la ville de Bujumbura ainsi que dans plusieurs\nprovinces, parfois à intervalles rapprochés, et même quotidiennement pendant certaines\npériodes. Des grenades ont ainsi été lancées dans des lieux publics, tels que des bars ou\nd’autres lieux très fréquentés, tuant et blessant un certain nombre de personnes. Certaines de\nces attaques ont touché des membres ou des proches du parti au pouvoir. Dans la majorité des\ncas, l’identité des auteurs ainsi que les motifs des attaques restent inconnus et les personnes\nqui ont lancé les grenades ont pu s’enfuir.\n(i)     Violations du droit à la vie"},{"id":"a-hrc-36-crp-1-p0239","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"239","seq":241,"section":"1. Droit à la vie","text":"La Commission a documenté plusieurs actes attentatoires au droit à la vie qui du fait\nde l’identité de leurs auteurs présumés – agents étatiques ou personnes agissant sous le\ncontrôle de ces derniers – constituent des violations des droits de l’homme. Ces violations\nengagent la responsabilité de l’État burundais.\ni.     Principaux auteurs"},{"id":"a-hrc-36-crp-1-p0240","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"240","seq":242,"section":"1. Droit à la vie","text":"La Commission a reçu des témoignages indiquant que diverses composantes des corps\nde défense et de sécurité ont été responsables d’un grand nombre d’exécutions\nextrajudiciaires depuis avril 2015. La majorité des auteurs présumés de ces violations sont\nmembres de la PNB, notamment de certaines de ses unités spécialisées telles que l’API et la\nBAE, ou du SNR. Des éléments de la FDNB, relevant notamment du Bataillon génie de\ncombat (camp Muzinda), ont été également mentionnés par plusieurs témoins."},{"id":"a-hrc-36-crp-1-p0241","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"241","seq":243,"section":"1. Droit à la vie","text":"En outre, plusieurs témoins ont rapporté des cas d’exécution extrajudiciaire commis\npar des Imbonerakure conjointement avec des membres des corps de défense et de sécurité,\nprincipalement de la police et du SNR et dans une moindre mesure de l’armée401. Un\nexemple, documenté par la Commission, est celui de Paul et Meschak Ramazani402, tués à\nBujumbura par des Imbonerakure et des policiers. D’après les informations recueillies par la\nCommission, le 5 août 2015, des affrontements ont eu lieu entre des Imbonerakure et des\npoliciers d’une part et des jeunes d’autre part, dans le quartier de Cibitoke à Bujumbura.\nSuite à ces affrontements, des Imbonerakure et des policiers ont interpellé Paul et Meschak\nRamazani. Ils leur ont demandé de s’agenouiller et de mettre les mains en l’air, puis les ont\nabattus403.\nii.     Principales violations"},{"id":"a-hrc-36-crp-1-p0242","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"242","seq":244,"section":"1. Droit à la vie","text":"La plupart des violations du droit à la vie commises depuis avril 2015 sont liées à la\ncrise politique que traverse le Burundi. Certains événements marquants qui ont ponctué cette\ncrise ont été propices à de telles violations. La répression des manifestations qui ont débuté\nen 2015 et du coup d’État manqué de mai 2015, caractérisée par un usage disproportionné et\nsouvent indiscriminé de la force létale par les corps de défense et de sécurité, les opérations\nmenées durant la seconde moitié de 2015 dans certains quartiers de Bujumbura, ainsi que la\nréponse aux attaques des installations militaires à Bujumbura et ses environs le 11 décembre\n2015 ont été des épisodes particulièrement meurtriers. La Commission a également réuni des\ninformations concordantes sur des assassinats ciblés attribués à des agents étatiques et sur des\ncas de décès en détention."},{"id":"a-hrc-36-crp-1-p0243","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"243","seq":245,"section":"1. Droit à la vie","text":"La Commission a été frappée par la brutalité des formes qu’ont pu prendre les\nviolations du droit à la vie au Burundi depuis 2015, notamment les assassinats ciblés404, la\ndécapitation de cadavres405, les exécutions de plusieurs membres d'une même famille406 ou le\nmeurtre de parents en présence de leurs enfants407. De nombreuses personnes ont été tuées\naprès avoir reçu des menaces par des agents du SNR, des policiers, des militaires ou des\nImbonerakure408.\nUsage disproportionné et indiscriminé de la force létale lors des manifestations d’avril et\njuin 2015"},{"id":"a-hrc-36-crp-1-p0244","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"244","seq":246,"section":"1. Droit à la vie","text":"D’après les témoignages recueillis par la Commission, des membres des corps de\ndéfense et de sécurité, principalement des policiers, ont fait un usage disproportionné et\nindiscriminé de la force létale en tirant à balles réelles sur des manifestants qui protestaient\ncontre la candidature de Pierre Nkurunziza à l’élection présidentielle, annoncée le 25 avril\n2015. Plusieurs personnes sont mortes et d'autres gravement blessées principalement à\nBujumbura, mais également dans d’autres provinces, notamment à Makamba409. Le Haut-\nCommissaire des Nations Unies aux droits de l’homme, dans son rapport au Conseil des\ndroits de l’homme en juin 2016, a fait état d’au moins 39 civils, dont deux mineurs, ayant\nsuccombé à des blessures causées par la police à Bujumbura Mairie et dans les provinces de\nBujumbura et de Mwaro410. La CNIDH, dans son rapport annuel 2015, a fait état de deux\nélèves tués par des policiers lors des manifestations au mois de juin 2015 dans les communes\nde Mugamba et Matana, province de Bururi411."},{"id":"a-hrc-36-crp-1-p0245","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"245","seq":247,"section":"1. Droit à la vie","text":"Une personne a témoigné à la Commission de l’usage délibéré et illégitime de la force\nlétale contre des manifestants par des policiers qu'elle a observé les premiers jours des\nmanifestations:\n« Un jeune homme appelé Elvis Munezero a été tué le premier jour des\nmanifestations, le 26 avril 2015, à Mutakura. Un policier lui a tiré dans le cœur à\nbout portant [...] J’étais là [...] Le chef de police appelé [X] a dit aux policiers :\n« Pourquoi vous fuyez ? Vous devez contrôler ces gens. Utilisez le gaz lacrymogène!\nUtilisez vos armes! Vous avez des armes. Ces jeunes n’ont que des pierres ». Il était\nfâché. Puis il a commencé à tirer dans la foule lui-même [...] Je l’ai vu tirer [...] Elvis\nétait la toute première victime durant les manifestations. Après, un autre garçon\nd’environ 15 ou 16 ans a été tué d’une balle dans la tête [...] Il s’appelait\nKomezamahoro [...] Il a été tué […] le même jour qu’Elvis » 412."},{"id":"a-hrc-36-crp-1-p0246","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"246","seq":248,"section":"1. Droit à la vie","text":"Dans certains cas, des agents de la police ont fait usage de la force létale suite à des\nactes de violence par des manifestants ayant entraîné la mort de policiers et de membres du\nparti au pouvoir. Dans son rapport cité plus haut, le Haut-Commissaire des Nations Unies aux\ndroits de l’homme a fait mention du meurtre de deux policiers, de deux soldats et d’un\nImbonerakure pendant les manifestations. Dans son rapport d’août 2015, la commission\nd’enquête « chargée de faire la lumière sur le mouvement insurrectionnel déclenché le 26\navril 2015 » établie par le Procureur général de la République a indiqué qu'un Imbonerakure\na été brûlé vif le 7 mai 2015 à Nyakabiga (Bujumbura Mairie) par « des insurgés »413. La\nCommission condamne fermement ces actes de violence commis par des manifestants ou\nd'autres personnes, même s’ils n’entrent pas dans le cadre de son mandat, n’étant pas commis\npar des groupes organisés avec une structure reconnue et donc susceptibles de constituer des\natteintes aux droits de l’homme414."},{"id":"a-hrc-36-crp-1-p0247","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"247","seq":249,"section":"1. Droit à la vie","text":"La Commission a toutefois recueilli des informations montrant que la réponse des\nforces de l’ordre à ces actes n’avait pas respecté le principe de proportionnalité et avait\nsouvent été indiscriminée. Une victime a expliqué à la Commission comment un policier lui a\ntiré dessus :\n« J’étais en train de manifester [...] Les policiers sont venus en nombre important. Ils\ntiraient des gaz lacrymogènes. Les manifestants envoyaient des pierres et d’autres\nprojectiles, mais ils n’avaient pas d’armes [...] Les policiers nous ont repoussés et\nnous avons fui [...] Alors que j’étais dans ma parcelle, j’ai entendu un chef des\npoliciers dire aux autres policiers qu’il fallait tirer sur toute personne qu’ils voyaient\ndans les quartiers car des rebelles s’y étaient cachés [...] Un policier [...] a tiré tout\nd’abord sur un jeune qui a été blessé par balle à la tête [...] Un [autre] policier était\nvenu se cacher près du portail. Avec la fumée, je ne l’avais pas vu. Il a tiré sur un\njeune qui a été touché au niveau du ventre et ensuite il m’a tiré dessus [...] Après que\nle policier eut tiré sur moi, je l’ai entendu dire aux autres policiers: « La [personne]\nqu’on recherchait, je l’ai tuée »415."},{"id":"a-hrc-36-crp-1-p0248","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"248","seq":250,"section":"1. Droit à la vie","text":"La Commission a noté que tous les policiers ne se sont pas comportés de la même\nmanière envers les manifestants. Certains policiers n’ont pas obéi aux ordres selon lesquels\nils devaient faire usage de la force létale contre les manifestants et certains ont même essayé\nde les protéger. Un policier interrogé par la Commission a témoigné :\n« Mon adjoint était un officier qui avait fait la rébellion CNDD-FDD [...] Lorsque\nj'étais absent, il donnait des ordres aux policiers de fouetter et de brutaliser les\nmanifestants […] Des policiers me l'ont dit. Certains policiers sous mon\ncommandement ne voulaient pas exécuter ces ordres, mais mon adjoint les forçait. Il\ndisait aux policiers de prendre des bâtons, de battre les manifestants, de les arrêter\npour quelques heures et de les insulter »416.\nAffrontements violents et usage disproportionné de la force à l'hôpital Bumerec"},{"id":"a-hrc-36-crp-1-p0249","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"249","seq":251,"section":"1. Droit à la vie","text":"Un usage disproportionné de la force par les corps de défense et de sécurité a\négalement été constaté suite au coup d’État du 13 mai 2015. La Commission a notamment\nrecueilli des informations sur le comportement de membres de ces corps à l’hôpital Bumerec\nà Bujumbura. Le 14 mai 2015, des militaires partisans du coup d’État qui avaient été blessés\nont été admis dans cet hôpital après des échanges de tirs avec des membres des corps de\ndéfense et de sécurité fidèles au Président Nkurunziza. D’après plusieurs sources, des\npoliciers, des militaires, des agents du SNR et des Imbonerakure à la poursuite de ces\nmilitaires blessés ont fait irruption dans l’enceinte de l’hôpital. Des échanges de tirs ont eu\nlieu entre eux et les militaires qui tentaient de défendre les patients ou de protéger l’hôpital.\nDes membres des corps de défense et de sécurité ont défoncé les portes des chambres pour\ntrouver les militaires blessés et sont repartis avec au moins trois d’entre eux, dont une femme.\nLe sort des militaires blessés n’est pas connu de la Commission. Les infrastructures et les\néquipements médicaux de l’hôpital ont été largement détruits. L’attaque violente contre\nl’hôpital Bumerec, ainsi que la destruction de ses infrastructures et équipements médicaux et\nl’enlèvement de personnes blessées, constituent des entraves graves à la jouissance du droit à\nla santé. La Commission n’a pas été en mesure d’établir le nombre de personnes tuées ou\nblessées au cours de cette attaque417.\nExécutions extrajudiciaires dans le cadre d’opérations des corps de défense et de sécurité à\nBujumbura en 2015"},{"id":"a-hrc-36-crp-1-p0250","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"250","seq":252,"section":"1. Droit à la vie","text":"La Commission a reçu plusieurs témoignages sur des exécutions extrajudiciaires\ncommises par des membres des corps de défense et de sécurité lors d’opérations conduites\ndurant la seconde moitié de l’année 2015 dans certains quartiers de Bujumbura. Selon les\nautorités, le but principal de ces opérations, consistant à mener des fouilles dans les maisons,\nétait d'arrêter et de désarmer des opposants. Les policiers ont souvent bouclé les quartiers\nciblés pendant plusieurs heures, empêchant les habitants d’entrer ou de sortir de ces quartiers."},{"id":"a-hrc-36-crp-1-p0251","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"251","seq":253,"section":"1. Droit à la vie","text":"Ainsi, d’après les informations recueillies par la Commission418, le 1er juillet 2015, à la\nsuite du meurtre d’un policier par des individus armés dans le quartier de Mutakura\n(Bujumbura Mairie), des policiers, sous le commandement d’un Commissaire de police et\nd’un haut-gradé de la police attaché à la Présidence de la République, ont mené une opération\nde fouille dans ce quartier, tirant dans toutes les directions sur leur passage. Des policiers\nsont entrés dans la parcelle d'un habitant de Mutakura, Pantaléon Hakizimana, l'accusant de\ncacher des armes, et l’ont tué ainsi que ses fils jumeaux âgés de 22 ans, Franck et Fleury\nHakizimana. Ils ont également incendié leur maison. Un témoin interrogé par la Commission\na indiqué que les policiers ont cessé leurs exactions après que des militaires soient\nintervenus et aient ordonné aux policiers de quitter les lieux. « Si les militaires n’étaient pas\nintervenus, on aurait compté beaucoup plus de morts » a affirmé le témoin419."},{"id":"a-hrc-36-crp-1-p0252","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"252","seq":254,"section":"1. Droit à la vie","text":"La Commission a recueilli des informations sur des exécutions extrajudiciaires\ncommises le 13 octobre 2015 dans le quartier 3 à Ngagara (Bujumbura Mairie). Ces\nviolations ont eu lieu dans le contexte d’une opération d’envergure menée par des agents de\nl’API après que des individus non identifiés ont attaqué trois policiers de l’API, tuant l’un\nd’entre eux et blessant les deux autres. Des agents de l’API ont tué plusieurs habitants du\nquartier, dont un caméraman à la RTNB, Christophe Nkezabahizi."},{"id":"a-hrc-36-crp-1-p0253","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"253","seq":255,"section":"1. Droit à la vie","text":"S’agissant de ce dernier cas, la Commission a rassemblé des informations\nconcordantes montrant que ce qui avait été présenté par la commission d'enquête mise en\nplace par le Procureur général de la République comme un meurtre commis par des jeunes du\nquartier420 s’avérerait être un cas manifeste d’exécution sommaire421. Les personnes\ninterrogées par la Commission ont confirmé que Christophe Nkezabahizi se trouvait chez lui\nen famille quand des membres de l’API ont frappé à la porte de sa concession. Le journaliste\na pris son badge de la RTNB et est allé leur ouvrir. Quand il est arrivé au portail, des\npoliciers l’ont abattu à bout portant, puis sont entrés dans sa maison et ont obligé sa femme,\nAlice Niyonzima, sa fille de 16 ans, Inès Kamikazi, son fils de 14 ans, Trésor Irakoze, et\nÉvariste Mbonihankuye, un autre membre de la famille employé par l’Organisation\ninternationale des migrations, à sortir dans la rue où ils les ont exécutés. Plusieurs\ntémoignages ont affirmé que l’officier en charge du détachement de l’API ce jour-là a tué\nChristophe Nkezabahizi. Un témoin a relaté :\n« Après avoir tiré sur [un] voisin, les policiers sont venus chez Christophe et ils ont\ntambouriné sur le portail [...] Dès que [Christophe] a ouvert la porte, les policiers ne\nlui ont pas donné une minute. Ils l’ont giflé plusieurs fois [...] [Le responsable du\ndétachement de l’API] a tiré, à bout portant, au niveau du front de Christophe [...]\n[Une dame policière] a tiré sur la tête d’Alice, à bout portant, et sa tête a éclaté [...]\nAprès, les policiers ont tiré sur Évariste au niveau du front, et puis sur Kamy\n[Kamikazi] [...] Trésor, qui était souffrant de malaria et faible, a reçu une balle. Les\npoliciers ont tiré sur lui en dernier. Il n’est pas mort sur le champ mais, faute\nd’assistance, il est décédé » 422."},{"id":"a-hrc-36-crp-1-p0254","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"254","seq":256,"section":"1. Droit à la vie","text":"Contrairement à cette version des faits, la commission mise en place par le Procureur\ngénéral de la République a conclu que Christophe Nkezabahizi et les membres de sa famille\nont été exécutés par des jeunes dont certains venaient d’attaquer les policiers423. Plusieurs\ntémoignages recueillis par la présente Commission indiquent néanmoins que des policiers\nauraient cherché sa maison et interrogé des habitants pour la trouver. Un témoin a également\nmentionné que, juste avant le meurtre de Christophe Nkezabahizi et de sa famille, « le chef\n[des] policiers parlait à la radio […] Les voisins d'en face ont entendu […] [quelqu'un dire]:\n« Ils sont tous là ». Les policiers semblaient attendre des ordres »424."},{"id":"a-hrc-36-crp-1-p0255","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"255","seq":257,"section":"1. Droit à la vie","text":"Au cours de cette opération, des agents de la police ont également tué plusieurs autres\npersonnes, dont un domestique qui travaillait chez Christophe Nkezabahizi et un employé\nd’un bar du quartier425. La commission établie par le Procureur général de la République a\nrapporté la mort de 10 personnes au total, dont les cinq membres de la famille de Christophe\nNkezabahizi, un policier et quatre autres personnes426. Elle a réfuté toute implication des\nmembres de l’API dans les exécutions du 13 octobre 2015, les attribuant plutôt à des\n« jeunes » ou à des « malfaiteurs »."},{"id":"a-hrc-36-crp-1-p0256","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"256","seq":258,"section":"1. Droit à la vie","text":"Le 31 octobre 2015, un détachement conjoint de la BAE et du Bataillon génie de\ncombat (camp Muzinda) a ouvert le feu sur un convoi funèbre à Buringa (province de\nBubanza). Selon les informations à la disposition de la Commission427, des militaires et des\npoliciers ont tiré sur le convoi composé d’un bus et de trois voitures. Des Imbonerakure\nauraient aidé à attraper des membres du convoi qui tentaient de fuir. Selon des témoins,\nplusieurs personnes ont été tuées par des militaires et des policiers428. S’exprimant au sujet de\ncette opération, le porte-parole de la Police n’a fait état que d’un seul décès parmi les\nmembres du convoi. Il a indiqué que ces derniers avaient empêché la police de fouiller leurs\nvéhicules et que certains membres du convoi avaient tiré en l’air en se dispersant429. Si cette\nversion des faits était établie, la réponse du détachement de la BAE et du Bataillon génie de\ncombat n’en resterait pas moins disproportionnée."},{"id":"a-hrc-36-crp-1-p0257","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"257","seq":259,"section":"1. Droit à la vie","text":"La Commission a reçu plusieurs témoignages selon lesquels, le 9 décembre 2015, un\ngroupe de militaires et de policiers, commandé par des officiers du SNR et de la police, a\nmené une opération à Mutakura (Bujumbura Mairie) au cours de laquelle ils ont fait sortir\nplusieurs jeunes de leurs maisons et les ont alignés le long de la route. Ensuite, ils les ont\ndivisés en deux groupes. Le premier groupe était composé de cinq jeunes hommes qui\nvivaient ensemble. Des policiers ont tiré sur les cinq jeunes et les ont tués, puis ont dit aux\nautres jeunes de rentrer chez eux430. Selon le porte-parole de la police, cité dans les médias,\ntous ces jeunes, dont deux venaient d’être libérés de prison, auraient attaqué à la grenade des\npoliciers, et les policiers ont répliqué431.\nExécutions extrajudiciaires en réponse aux attaques des installations militaires du 11\ndécembre 2015"},{"id":"a-hrc-36-crp-1-p0258","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"258","seq":260,"section":"1. Droit à la vie","text":"La violence observée pendant la seconde moitié de l’année 2015 a culminé en\ndécembre 2015 avec l’attaque par des personnes armées non identifiées de trois installations\nmilitaires à Bujumbura et du camp de Mujejuru dans la province de Bujumbura le 11\ndécembre 2015. L’usage illégitime, disproportionné ou indiscriminé de la force par les corps\nde défense et de sécurité qui avait pu être observé pendant et depuis les manifestations d’avril\nà juin 2015 a atteint une ampleur inégalée au lendemain de cette attaque. La commission\nd’enquête établie par le Procureur général de la République sur les attaques du 11 décembre\n2015 a fait état de « pertes en vies humaines évaluées à 79 combattants, quatre militaires et\nquatre policiers »432. Ces conclusions ne concordent pas avec les celles du Haut-Commissaire\naux droits de l’homme et de l’EINUB dans leurs rapports respectifs au Conseil des droits de\nl’homme433, ni avec celles de plusieurs organisations nationales et internationales des droits\nde l’homme qui ont enquêté sur ces événements434. Il ressort également des diverses sources\nconsultées et des témoins interrogés par la Commission que le bilan serait plus élevé."},{"id":"a-hrc-36-crp-1-p0259","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"259","seq":261,"section":"1. Droit à la vie","text":"D’après les informations recueillies par la Commission, des militaires et des policiers\nont exécuté des dizaines de personnes à Bujumbura Mairie, notamment dans les quartiers de\nNyakabiga et Musaga435. La Commission a recueilli plusieurs témoignages indiquant que\ntoutes les victimes n’étaient pas des combattants, comme l’a indiqué la commission\nd’enquête établie par le Procureur général, mais comprenaient aussi de nombreux civils. Des\nphotographies de corps, avec les mains liées dans le dos et en tenue civile, jonchant les rues\nde quartiers de Bujumbura, ont notamment circulé dans les médias436."},{"id":"a-hrc-36-crp-1-p0260","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"260","seq":262,"section":"1. Droit à la vie","text":"La Commission a reçu des témoignages accablants sur la cruauté de certains membres\ndes corps de défense et de sécurité dans la foulée de l’attaque le 11 décembre 2015. Un\ntémoin a déclaré à la Commission:\n« [Le] 11 décembre 2015 [...] plusieurs personnes ont été tuées par des soldats. Leurs\ncadavres ont été traînés dans la rue. J’ai pu identifier certains d’entre eux […] Parmi\nles victimes se trouvaient [X], retrouvé à Musaga, à côté de l’église catholique à la\ntroisième avenue, et [Y] dont le corps a été trouvé au même endroit. Ils étaient tous\ndeux des élèves du secondaire. Il y avait environ 40 autres corps de personnes que je\nne connaissais pas »437.\nUn homme arrêté avec plusieurs autres personnes par des militaires a raconté à la\nCommission: « Nous avons trouvé beaucoup d’autres personnes qui avaient été\nligotées et emmenées là [dans un camp militaire]. [Les militaires] ont dit : «\nAllongez-vous et regardez vers le ciel » […] Nous étions environ 60 tous alignés, tous\ndes hommes. Puis ils ont commencé à nous fusiller un par un. Une première personne\na reçu une balle dans la tête. La personne qui ordonnait la fusillade était [un officier\nmilitaire] […] Ils tiraient systématiquement sur les personnes alignées. Ils ont tué\nbeaucoup de personnes ce jour-là […] Ils les fusillaient un à un, à bout portant […]\nIls mettaient le fusil contre la tête de chaque personne. Le fusil touchait la tête. Quand\nils tiraient sur une personne, le sang rebondissait sur la personne à côté. […] Un\nmilitaire tirait et [l’officier] donnait les ordres. [L’officier] était présent, il\nsupervisait. Le militaire qui tirait disait à chaque personne: « Dis tes dernières\nprières, petit chien » […] [X] disait [au militaire]: « Viens ici et tire » »438."},{"id":"a-hrc-36-crp-1-p0261","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"261","seq":263,"section":"1. Droit à la vie","text":"Le lendemain de l’attaque, plusieurs habitants des quartiers visés ont pu constater\nl’ampleur des exécutions qui y ont eu lieu. Un témoin, qui a cité les noms de plusieurs de ses\namis tués le 11 décembre 2015, a rapporté :\n« Pendant deux jours, le quartier de Musaga était fermé à la circulation en vue de\npermettre l’enlèvement des corps […] Quand je suis sortie pour voir ce qui se passait\nà l’extérieur, des policiers m’ont dit de rentrer. Mais j’ai eu le temps de voir juste\ndevant le portail plusieurs cadavres d’inconnus »439.\nUne autre personne interrogée par la Commission a témoigné : « Le 12 décembre, on\nest sorti et on a vu des cadavres dans les rues. Parmi les morts, il y avait une\npersonne que j’ai reconnue [...] Je le connaissais à l’université. On a trouvé son corps\ndans la rue qui sépare Nyakabiga I et Kigwati, avec deux autres cadavres de\npersonnes que je ne connaissais pas »440."},{"id":"a-hrc-36-crp-1-p0262","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"262","seq":264,"section":"1. Droit à la vie","text":"La Commission a reçu des informations sur des cas individuels d’exécution\nextrajudiciaire dans le cadre de la réponse des membres des corps de défense et de sécurité\naux attaques du 11 décembre 2015. Ainsi, un candidat officier de l’Institut des cadres\nmilitaires (ISCAM), Hermès Nduwingoma, a été blessé au moment de l’attaque de l’ISCAM.\nDes agents du SNR l'ont arrêté avec un collègue alors qu’il se rendait dans un centre\nhospitalier pour se faire soigner et l’ont amené au siège du SNR à Bujumbura. Le 12\ndécembre 2015, des témoins ont rapporté avoir reçu des photos de son corps. Après environ\nune semaine, son corps a été retrouvé à la morgue de l’hôpital du Roi Khaled avec le visage\ndéfiguré et deux impacts de balle au niveau de l’omoplate441. La Commission n’a pas été en\nmesure d’obtenir des informations sur l’état d’avancement du dossier ouvert par le Parquet\nsur ce cas, signalé dans le rapport annuel de 2015 de la CNIDH442."},{"id":"a-hrc-36-crp-1-p0263","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"263","seq":265,"section":"1. Droit à la vie","text":"La Commission a également reçu des informations sur des exécutions extrajudiciaires\nen dehors de Bujumbura Mairie, dans le cadre des représailles des forces de sécurité suite à\nl’attaque du camp militaire de Mujejuru (province de Bujumbura). Selon ces informations,\nsept jeunes hommes ont été appréhendés le 11 décembre 2015 en lien avec l’attaque et\nconduits à un poste de police dans la commune de Mugongomanga (province de Bujumbura).\nPuis, un major de l’armée, accompagné de plusieurs militaires, a demandé que les policiers\nlui remettent ces jeunes hommes, ce qu'ils ont fait. Le 12 décembre 2015, leurs corps ont été\nretrouvés sur la colline de Kanyunya, zone de Rukina, commune de Mukike (province de\nBujumbura)443. Un dossier a été ouvert par le Parquet sur ce cas444. La Commission n’a pas\npu obtenir d’informations sur l’avancée de l’instruction."},{"id":"a-hrc-36-crp-1-p0264","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"264","seq":266,"section":"1. Droit à la vie","text":"Les exécutions extrajudiciaires commises le 11 décembre 2015 ont été accompagnées\nde nombreuses arrestations arbitraires, d'actes de torture, de viols et autres violences\nsexuelles, décrits dans d’autres parties du présent rapport445.\nExécutions ou tentatives d’exécution extrajudiciaire ciblée"},{"id":"a-hrc-36-crp-1-p0265","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"265","seq":267,"section":"1. Droit à la vie","text":"La Commission a rassemblé des informations concordantes sur plusieurs assassinats\nou tentatives d’assassinat ciblé attribués à des agents du SNR, de la police ou de l’armée,\nvisant des membres de l’opposition ou de la société civile ou des personnes perçues comme\nopposants au Gouvernement."},{"id":"a-hrc-36-crp-1-p0266","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"266","seq":268,"section":"1. Droit à la vie","text":"Zedi Feruzi, président du parti d’opposition l’Union pour la paix et le développement\n(UPD)-Zigamibanga, a été tué le 23 mai 2015 alors qu’il rentrait chez lui à Ngagara\n(Bujumbura Mairie). Selon les témoignages recueillis par la Commission446, des policiers de\nl’API, à bord d’un véhicule, lui ont tendu une embuscade et l’ont tué, ainsi que l’un de ses\ngardes du corps. Deux autres personnes ont été blessées. Avant ces faits, des membres du\nCNDD-FDD avaient tenté de convaincre Zedi Feruzi de se rallier à une coalition qui\nsoutenait la candidature de Pierre Nkurunziza à l’élection présidentielle. Certaines de ces\nsollicitations avaient été accompagnées de menaces, notamment par des représentants du\nparti CNDD-FDD et des membres des corps de défense et de sécurité. Suite à l’assassinat de\nZedi Feruzi, le Gouvernement burundais, dans un communiqué publié le 24 mai 2015, a\ndéclaré avoir « instruit les instances habilitées à diligenter des enquêtes dans les meilleurs\ndélais afin que la lumière soit faite et ces criminels sérieusement châtiés »447. À la\nconnaissance de la Commission, aucune personne n’a à ce jour été poursuivie en justice."},{"id":"a-hrc-36-crp-1-p0267","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"267","seq":269,"section":"1. Droit à la vie","text":"Le 3 août 2015, Pierre-Claver Mbonimpa, fondateur et président de l’APRODH, a été\ngrièvement blessé dans une tentative d’assassinat à Bujumbura. En fin d’après-midi, au\nmoment où il s'apprêtait à quitter son travail, il a aperçu un informateur du SNR qu’il\nconnaissait rôder à moto autour de son bureau. Le même individu a ensuite suivi son véhicule\net, après avoir dépassé Kinama, lui a tiré dessus, l’atteignant d’une balle au niveau du visage\net du cou. Pierre-Claver Mbonimpa a été évacué dans un hôpital en Belgique où il est resté\npendant plusieurs mois. Un dossier d’instruction (RMP 153248/BI) a été ouvert448, mais à ce\njour aucune personne n’a été poursuivie pour cette tentative d’assassinat. L’homme qui a tiré\nsur Pierre-Claver Mbonimpa a été tué quelques semaines plus tard449."},{"id":"a-hrc-36-crp-1-p0268","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"268","seq":270,"section":"1. Droit à la vie","text":"Patrice Gahungu, porte-parole de l’UPD-Zigamibanga, a été assassiné par des\nindividus armés dans la soirée du 7 septembre 2015, alors qu’il rentrait chez lui dans le\nquartier de Gihosha à Bujumbura450. D’après certains témoignages les auteurs présumés\nauraient été des Imbonerakure agissant sur ordre et avec l’appui d’un agent du SNR451.\nL’assassinat de Patrice Gahungu a eu lieu quelques mois après celui du président du parti,\nZedi Feruzi, le 23 mai 2015452. Le porte-parole de la police a indiqué dans la presse que\nPatrice Gahungu pourrait avoir été assassiné par l’opposition453."},{"id":"a-hrc-36-crp-1-p0269","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"269","seq":271,"section":"1. Droit à la vie","text":"Le 6 novembre 2015, le fils de Pierre-Claver Mbonimpa, Welly Nzitonda, âgé de 24\nans, a été tué, après avoir été arrêté avec d'autres personnes par des policiers. Selon les\ninformations reçues par la Commission, l’auteur présumé de cet assassinat serait un policier\nen poste à Bujumbura Mairie. Une instruction a été ouverte (RMPG 718Bis/N.TH) sans qu’à\nla connaissance de la Commission, elle n’ait abouti à ce jour454. Selon le Gouvernement,\nWelly Nzitonda aurait péri « sur le champ de bataille » alors qu’il s’apprêtait, avec d’autres, à\nlancer une grenade contre des policiers à Mutakura455. Aucune source consultée par la\nCommission n’a confirmé la version des autorités sur la mort de Welly Nzitonda."},{"id":"a-hrc-36-crp-1-p0270","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"270","seq":272,"section":"1. Droit à la vie","text":"Le Général Athanase Kararuza, ex-FAB et conseiller en matière de sécurité et de\ndéfense à la Première Vice-Présidence, a été tué le 25 avril 2016 par des policiers et des\nmilitaires de plusieurs unités, au moment où il déposait sa fille à l’école à Bujumbura456.\nAvant l’assassinat, des militaires du Camp Muzinda, munis de lance-roquettes et de\nkalachnikovs, ont été vus non loin de la route que le général empruntait chaque matin pour se\nrendre au travail. Un groupe de policiers de l’API, conduit par un officier supérieur de la\nmême unité, barrait la route qui aurait pu permettre au véhicule du Général Kararuza\nd’échapper à l’embuscade. L’attaque a occasionné non seulement la mort du Général\nKararuza, atteint de plusieurs balles, mais également celle de son épouse, Consolate Gahiru,\net de leur fille, Daniella Mpundu, ainsi qu’un de ses agents de transmission. La fille du\ngénéral a été laissée pour morte avant qu’une ambulance arrive pour la transporter à l’hôpital.\nElle y est décédée le 28 avril 2016. Le Général Kararuza avait fait part en privé à certains de\nses collègues d’exactions commises par le Gouvernement. En avril 2016, à deux reprises, un\nvéhicule de l’API avait suivi son propre véhicule à Bujumbura. Un véhicule aux vitres\nteintées, du type que conduisent souvent des agents du SNR, aurait été aperçu aux environs\nde sa maison quelque temps avant son assassinat.\nDécès en détention"},{"id":"a-hrc-36-crp-1-p0271","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"271","seq":273,"section":"1. Droit à la vie","text":"La Commission a reçu des informations sur des cas de décès de personnes qui se\ntrouvaient en détention sous le contrôle des corps de défense et de sécurité, après avoir été\narrêtées457. Il incombe à l’État burundais de fournir des explications sur ces cas en menant\ndes enquêtes approfondies et impartiales dans les plus brefs délais."},{"id":"a-hrc-36-crp-1-p0272","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"272","seq":274,"section":"1. Droit à la vie","text":"Plusieurs détenus sont notamment décédés au SNR, certains des suites d’actes de\ntorture458. Une personne détenue au SNR en 2016 a témoigné :\n« J’ai été conduit seul le soir dans une autre salle où il y avait déjà deux cadavre […]\nC’était le corps d’un homme d’environ 30 à 35 ans [...] Son corps nu était placé à\nmême le sol […] Le deuxième corps aussi nu était celui d’un jeune homme dans la\nvingtaine. Il était étalé à même le sol [...] [Un officier du SNR] s’est alors adressé à\nmoi en me disant : « Tu vas recevoir le même sort qu’[eux]»459.\nUn autre témoin détenu au siège du SNR fin 2015 a déclaré : « Ils nous ont mis dans\nune pièce pour nous interroger. Ils nous ont demandé : « Où sont les armes que vous\navez utilisées et les uniformes que vous avez pris ? » [...] Beaucoup de personnes sont\nmortes [...] Certaines personnes ont été tuées devant moi. L’officier [X] est venu et il\na tiré sur certaines personnes dans la tête avec son pistolet. Je l’ai vu tirer sur cinq\npersonnes »460."},{"id":"a-hrc-36-crp-1-p0273","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"273","seq":275,"section":"1. Droit à la vie","text":"Eddy Claude Nyongera, un militaire ex-FAB, a été arrêté le 14 septembre 2016 à\nl’état-major de la FDNB, accusé d’atteinte à la sécurité intérieure de l’État, puis conduit au\nSNR où il est décédé le même jour461. Le lendemain, le porte-parole de la police a déclaré\nqu’en présence d’Officiers de police judiciaire, Eddy Claude Nyongera avait pris une grenade\n« qu’il a voulu dégoupiller pour la lancer probablement sur les autres policiers qui étaient là.\nEt ils se sont battus pour pouvoir l’empêcher de commettre cet acte. Ils ont vu que la grenade\nallait exploser, les Officiers de police judiciaire ont pris le large et la grenade a explosé le\ntuant sur le champ [...] Nous pensons qu’il a voulu mettre fin à sa vie probablement peut-être\npour des révélations qu’il venait de faire ou pour ses raisons »462. La Commission considère\nque seule une enquête approfondie et impartiale pourra déterminer la cause et les\ncirconstances du décès d’Eddy Claude Nyongera. La Commission n’a pas eu connaissance\nd’une telle enquête ait été ouverte à ce jour. Un Officier de police interrogé par la\nCommission a pour sa part estimé : « La thèse du suicide de Nyongera à la grenade est selon\nmoi ridicule. On ne peut interroger un individu dans une salle où il y a une grenade à sa\ndisposition »463."},{"id":"a-hrc-36-crp-1-p0274","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"274","seq":276,"section":"1. Droit à la vie","text":"La Commission a également recueilli des informations sur des mouvements suspects\nde détenus durant la nuit laissant supposer que plusieurs d’entre eux pourraient avoir été\nexécutés464. Un survivant a rapporté :\n« Fin 2015, [...] des Imbonerakure nous ont arrêtés dans le quartier et nous ont\nemmenés [dans un camp militaire] où nous avons été battus [...] Nous avons été\nemmenés au SNR [...] Vers trois heures du matin, des policiers nous ont embarqués\ndans un véhicule. Ils étaient tous cagoulés. Après 20 minutes en voiture, je me suis\nretrouvé dans un hangar. Puis, trois de mes codétenus ont été tués un à un d’une balle\nà la tête »465."},{"id":"a-hrc-36-crp-1-p0275","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"275","seq":277,"section":"1. Droit à la vie","text":"Plusieurs autres témoins, surtout des personnes qui avaient été détenues au SNR à\nBujumbura, ont affirmé que, pendant la nuit, des agents du SNR venaient prendre certains\ndétenus des cachots et les emmenaient vers des destinations inconnues. Ces détenus ne\nrevenaient pas aux cachots. La Commission n’a pu recueillir aucune information sur leur sort\nni confirmer s’ils sont toujours en vie."},{"id":"a-hrc-36-crp-1-p0276","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"276","seq":278,"section":"1. Droit à la vie","text":"Des témoignages ont en outre confirmé que des individus arrêtés par la police, des\nmilitaires ou des Imbonerakure ont été emmenés dans la forêt de Rukoko où ils auraient été\nexécutés. Les corps de certains d’entre eux ont ensuite été lestés de pierre avant d’être jetés\ndans la rivière Rusizi466. L'un des rescapés a témoigné :\n« Les policiers m’ont embarqué avec deux autres détenus dans une camionnette\njusqu’à la rivière Rusizi, en passant par la forêt Rukoko [...] Les deux autres détenus\nont été froidement exécutés devant la rivière, puis jetés dans le courant. Un policier\n[...] a exécuté chacun des deux autres détenus d’un vif coup de couteau au niveau du\ncou. Les deux étaient ligotés séparément »467.\niii.     Manquements de l’État à son obligation de protéger"},{"id":"a-hrc-36-crp-1-p0277","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"277","seq":279,"section":"1. Droit à la vie","text":"Si l’État burundais a failli à son obligation de respecter le droit à la vie du fait d’actes\ncommis par ses agents ou des Imbonerakure agissant sous leur contrôle, la Commission a\négalement des motifs de croire que le Gouvernement n’a pas systématiquement rempli son\nobligation de protéger. En l’état des informations recueillies par la Commission, il apparaît\nque peu d’enquêtes « indépendantes, approfondies et efficaces »468 ont été menées à terme sur\ndes allégations de violation du droit à la vie commise par des corps de défense et de sécurité.\nUn cas emblématique est celui d’un major de l’armée cité comme auteur présumé de\nviolations dans le rapport de la commission d’enquête établie par le Procureur général de la\nRépublique sur l’attaque des installations militaires le 11 décembre 2015469. Ce major n’a\njamais été arrêté ni poursuivi et serait toujours en fonction au sein de la FDNB470, alors même\nqu’il aurait été impliqué dans d’autres cas de violation grave des droits de l’homme471.\nCorps sans vie régulièrement retrouvés et inhumés sans enquête"},{"id":"a-hrc-36-crp-1-p0278","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"278","seq":280,"section":"1. Droit à la vie","text":"Depuis avril 2015, et tout au long des années 2016 et 2017, des corps sans vie ont\nrégulièrement été découverts dans plusieurs provinces, souvent les bras liés dans le dos, et\nparfois décapités472. Des cadavres, parfois lestés de pierres, ont été retrouvés dans la rivière\nRusizi et d’autres rivières, ainsi que dans le Lac Tanganyika473. D’autres ont été découverts\ndans la rue, y compris dans la capitale. Dans plusieurs cas, les autorités ont fait inhumer ces\ncorps sans identification des victimes ni enquête crédible, manquant par-là à leur obligation\nde protéger le droit à la vie. Dans d’autres cas, surtout en 2015, certaines victimes ont été\nidentifiées comme des personnes s’étant opposées au nouveau mandat du Président\nNkurunziza ou des membres de partis de l’opposition. Le phénomène de découverte de\ncadavres est devenu si courant qu’il ne semble plus susciter de réaction, à part des mentions\nbrèves dans les médias et les rapports d’organisations de la société civile. Étant donné le\nmanque d’informations concernant les circonstances de la mort de ces personnes, l’identité\ndes auteurs présumés et même l’identité de certaines victimes, la Commission n’a pas été en\nmesure de mener des enquêtes approfondies et ne peut donc pas se prononcer sur ces cas.\nCependant, elle souhaite attirer l’attention sur la gravité de ce phénomène et insister sur la\nresponsabilité des autorités burundaises de mener des enquêtes effectives sur chacun de ces\ndécès.\nAllégations de fosses communes"},{"id":"a-hrc-36-crp-1-p0279","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"279","seq":281,"section":"1. Droit à la vie","text":"Le Haut-Commissaire aux droits de l’homme474, l’EINUB475, ainsi que plusieurs\norganisations des droits de l’homme476 ont fait état d’allégations de fosses communes,\nnotamment à Buringa et Mpanda (province de Bubanza) et à Kanyosha (Bujumbura Mairie),\nsuite aux événements du 11 décembre 2015. Le 29 février 2016, le maire de Bujumbura a\nannoncé aux médias la découverte d’une fosse commune à Mutakura (Bujumbura Mairie),\naffirmant que les corps étaient ceux de sympathisants du CNDD-FDD tués par des membres\nde l’opposition477. Cette information a été reprise dans le rapport de la commission créée par\nle Procureur général de la République afin d’enquêter sur l’attaque du 11 décembre 2015.\nCette commission, rejetant notamment les allégations de fosses communes à Mutimbuzi,\nKanyosha et Bugarama évoquées par la Ligue Iteka, a affirmé que « toutes les sources ont\nprouvé que l’enterrement des corps sans vie retrouvés dans les différentes zones de combat\nde la ville de Bujumbura a été effectué dans des cimetières connus à savoir celui de Mpanda\net de Kanyosha »478."},{"id":"a-hrc-36-crp-1-p0280","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"280","seq":282,"section":"1. Droit à la vie","text":"Contrairement à ces conclusions, la présente Commission a reçu des témoignages\nattestant de l’utilisation de fosses communes par les autorités afin d’enterrer des cadavres de\npersonnes tuées au lendemain des attaques des installations militaires à Bujumbura et dans\nses environs, le 11 décembre 2015479. La Commission a en particulier reçu des informations\nsur l’existence de fosses communes dans les cimetières de Kanyosha et de Mpanda.\nS’agissant des fosses à Kanyosha, un témoin a rapporté :\n« Le 12 décembre 2015 [...] j’ai vu des pick-up, qui sont normalement à la disposition\ndes chefs de zone de la Mairie de Bujumbura, amener plusieurs corps. Ils ont utilisé\nles services des voisins pour enterrer ces corps. J’ai vu de mes propres yeux trois\ncamionnettes amener des corps pour les enterrer dans les fosses communes pendant\ndeux jours [...] Ce sont des policiers qui amenaient les corps en tenue de police\nnationale bleue [...] Tout le monde a peur. Personne ne veut en parler »480."},{"id":"a-hrc-36-crp-1-p0281","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"281","seq":283,"section":"1. Droit à la vie","text":"Le Programme opérationnel pour les applications satellitaires de l’UNITAR481,\nUNOSAT, a procédé à des relevés d’images satellitaires des sites allégués entre début\nnovembre et fin décembre 2015. Les images analysées par UNOSAT ont permis de conclure\nque des mouvements de sol ont été effectués pendant cette période à deux endroits à\nKanyosha et deux endroits dans le cimetière de Mpanda."},{"id":"a-hrc-36-crp-1-p0282","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"282","seq":284,"section":"1. Droit à la vie","text":"En l’état actuel des informations sur ces allégations d’existence de fosses communes,\nla Commission considère que seul un accès à tous les sites présumés ainsi que des expertises\nmédico-légales et des enquêtes plus approfondies pourraient permettre de déterminer le bien-\nfondé de ces allégations ainsi que les circonstances dans lesquelles les personnes enterrées\ndans ces fosses sont mortes.\n(ii)     Atteintes au droit à la vie"},{"id":"a-hrc-36-crp-1-p0283","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"283","seq":285,"section":"1. Droit à la vie","text":"La Commission a documenté plusieurs actes attentatoires au droit à la vie qui n’ont été\ncommis ni par des agents étatiques ni par des individus sous leur contrôle et qui de fait ne\npeuvent être qualifiés de violations des droits de l’homme. Leurs auteurs présumés – des\nImbonerakure agissant de leur propre chef ou des membres de groupes armés d’opposition –\nappartiennent à des structures organisées. Selon la définition retenue par la Commission,\nleurs actes peuvent dès lors être considérés comme des atteintes aux droits de l’homme482.\ni.     Atteintes au droit à la vie par des Imbonerakure"},{"id":"a-hrc-36-crp-1-p0284","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"284","seq":286,"section":"1. Droit à la vie","text":"La Commission a reçu plusieurs témoignages d’atteintes au droit à la vie par des\nImbonerakure dans différentes provinces483. Ces exactions, commises par des Imbonerakure\nseuls, en dehors du contrôle d’agents étatiques, illustrent le climat de violence et d’impunité\ngénéralisée dans la mesure où, selon les témoins interrogés, ces Imbonerakure n’ont pas été\ninquiétés pour leurs actes. Une personne dont le père, membre des FNL, a été exécuté par des\nImbonerakure en 2015 a ainsi témoigné :\n« [Des] jeunes Imbonerakure en tenue civile et armés de couteaux ont fait irruption\nchez moi. Ils ont défoncé la porte avec des coups de pied et sont entrés à l’intérieur de\nla maison. Ils ont tué mon père [...] Après la mort de mon père [...] nous sommes\npartis porter plainte à la police [...] Depuis lors, il n’y a aucune arrestation en lien\navec cette affaire. [Un an plus tard], les enquêtes [n’ont] pas abouti »484.\nUne femme a relaté le meurtre de son enfant par des Imbonerakure en 2016 et\nl’absence de réponse des autorités : « J’ai été attaquée par des Imbonerakure […] Ils\nont lancé une grenade dans ma chambre causant la mort de […] mon enfant [...] Tous\nétaient habillés en civil […] En lançant la grenade, les assaillants ont crié : « Nous\nl’avons tué ! ». [...] La grenade est passée par une fenêtre située à côté de la route\n[...] Le lendemain, je suis allée porter plainte à la police [...] Les policiers m’ont\nrépondu qu’il n’y avait pas de preuve pour soutenir ma déclaration. [...] Personne n’a\nété arrêté, malgré ma dénonciation précise des Imbonerakure de la colline »485."},{"id":"a-hrc-36-crp-1-p0285","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"285","seq":287,"section":"1. Droit à la vie","text":"En n’enquêtant pas sur ces cas malgré le dépôt de plainte par les victimes, les autorités\nburundaises ne remplissent pas non plus leur obligation de protéger."},{"id":"a-hrc-36-crp-1-p0286","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"286","seq":288,"section":"1. Droit à la vie","text":"Des témoins rencontrés par la Commission ont en outre attribué à des Imbonerakure\ncertaines attaques contre des opposants au Gouvernement, tant à Bujumbura que dans les\nprovinces486. Le fils d’un membre d’un parti de l’opposition a ainsi témoigné:\n« Après le coup d’État manqué du 13 mai 2015, les Imbonerakure […] sont venus\n[chez mon père] […] Dès qu’ils sont entrés, ils lui ont d’abord donné un coup de\ncouteau au flanc puis à la gorge […], le tuant sur le coup […] Quand [nous avons]\ncompris que notre père venait d’être tué, nous sommes passés par une fenêtre et nous\navons pris la fuite. C’est en prenant la fuite que [notre frère] […] a été atteint par une\ngrenade lancée par les Imbonerakure »487.\nii.     Atteintes au droit à la vie par des groupes armés d’opposition"},{"id":"a-hrc-36-crp-1-p0287","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"287","seq":289,"section":"1. Droit à la vie","text":"Malgré plusieurs tentatives, la Commission n’a pas été en mesure de recueillir des\ntémoignages directs ou détaillés d’atteintes au droit à la vie par des groupes armés\nd’opposition du fait de la difficulté d’accéder aux familles des victimes et aux témoins qui se\ntrouvent pour la plupart au Burundi. De plus, le Gouvernement du Burundi n’a partagé\naucune information sur ces atteintes, malgré plusieurs demandes de la part de la\nCommission488."},{"id":"a-hrc-36-crp-1-p0288","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"288","seq":290,"section":"1. Droit à la vie","text":"La Commission est préoccupée par les appels à la violence contre le Gouvernement\nburundais lancés par plusieurs groupes armés d’opposition489, ainsi que la revendication de\ncertaines attaques par des groupes armés, comme par exemple celle du camp militaire de\nMukoni à Muyinga le 24 janvier 2017 que la direction générale des Mouvements alliés pour\nla libération du Burundi (MALIBU-FPS) a attribué à sa branche armée, le Front patriotique\ndu salut (FPS)490. La tâche de la Commission a néanmoins été rendue difficile par le fait que\nplusieurs groupes armés d’opposition ont parfois revendiqué la même attaque. Cela a\nnotamment été le cas des attaques menées le 21 janvier 2016 à Cibitoke (Bujumbura Mairie)\nque le RED-Tabara et les FOREBU ont tous les deux revendiquées."},{"id":"a-hrc-36-crp-1-p0289","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"289","seq":291,"section":"1. Droit à la vie","text":"La Commission a pu toutefois interroger quelques membres de groupes armés\nd’opposition. Certains ont reconnu leur appartenance à des mouvements armés ayant perpétré\ndes attaques sur le territoire burundais491. L’un a notamment avoué avoir pris part à des\nattaques visant à saboter l’élection présidentielle en 2015492. Ce témoignage va dans le sens\nd’un entretien donné aux médias par le Général Léonard Ngendakumana, dans laquelle il a\nreconnu que des groupes armés d’opposition étaient à l’origine d'attaques à la grenade durant\nl’élection de juillet 2015493.\n(iii)     Autres meurtres et assassinats"},{"id":"a-hrc-36-crp-1-p0290","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"290","seq":292,"section":"1. Droit à la vie","text":"La Commission a collecté des informations relatives à des meurtres ou assassinats ou\ndes tentatives de meurtre ou d’assassinat commis par des personnes dont elle n’a pas pu\nétablir l’identité ou la responsabilité. Ces meurtres ou assassinats ont visé aussi bien des\nmembres de l’opposition ou des personnes assimilées comme tels que des membres ou des\nproches du Gouvernement ou du parti au pouvoir. La Commission a également reçu des\ninformations sur plusieurs assassinats de militaires, de policiers, de membres du SNR et\nd'Imbonerakure. Il ressort des témoignages recueillis que les victimes ont été spécifiquement\nciblées. Les modes opératoires, les menaces contre les proches des personnes tuées, avant ou\naprès leur mort, ainsi que le laxisme des autorités dans la poursuite des auteurs font craindre\nune implication possible d’agents de l’État dans certains de ces cas."},{"id":"a-hrc-36-crp-1-p0291","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"291","seq":293,"section":"1. Droit à la vie","text":"Le 9 octobre 2015, Pascal Nshimirimana, gendre du défenseur des droits de l'homme\nPierre-Claver Mbonimpa lui-même victime d’une tentative d’assassinat deux mois plus tôt494,\na été tué dans la zone Ngagara, commune Ntahangwa, à Bujumbura. Des individus armés non\nidentifiés ont tiré sur lui alors qu’il attendait qu'on lui ouvre le portail de sa maison495. Pascal\nNshimirimana, un commerçant, n'était pas connu pour ses activités politiques ou en faveur\ndes droits de l'homme. Il semble probable qu'il ait été tué en raison des activités de son beau-\npère. Une instruction a été ouverte sans qu’aucune conclusion, à la connaissance de la\nCommission, n’ait été rendue à ce jour496."},{"id":"a-hrc-36-crp-1-p0292","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"292","seq":294,"section":"1. Droit à la vie","text":"La Commission a reçu des informations sur plusieurs cas d’assassinat ou de meurtre\nde représentants ou de membres des partis d’opposition MSD et FNL497. Par exemple, le\ncorps de Charlotte Umugwaneza, vice-présidente du MSD dans la zone de Cibitoke\n(Bujumbura Mairie), a été retrouvé le 17 octobre 2015 non loin de Bujumbura. Certaines\nsources consultées par la Commission ont attribué son assassinat à des agents étatiques498.\nAssassinats et tentatives d’assassinat de membres du Gouvernement et du CNDD-FDD"},{"id":"a-hrc-36-crp-1-p0293","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"293","seq":295,"section":"1. Droit à la vie","text":"La Commission a reçu des informations sur des assassinats et tentatives d’assassinat\nciblés d’autorités et de membres ou de proches du parti au pouvoir. Malgré plusieurs\ntentatives, la Commission n’a pas été en mesure de mener des enquêtes approfondies sur ces\ncas en raison notamment de l’absence d’accès au territoire burundais et de collaboration des\nautorités burundaises. Quelques-uns de ces cas méritent toutefois d’être mentionnés."},{"id":"a-hrc-36-crp-1-p0294","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"294","seq":296,"section":"1. Droit à la vie","text":"Le 24 avril 2016, Martin Nivyabandi, Ministre des droits de la personne humaine, des\naffaires sociales et du genre, et sa femme ont survécu à une attaque à la grenade à\nBujumbura499. Le ministre et son épouse ont été légèrement blessés. Les auteurs de l’attaque\ndemeurent inconnus. La Commission n’a pas d’informations sur l’état d’avancement des\nenquêtes dans le cadre de cette affaire."},{"id":"a-hrc-36-crp-1-p0295","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"295","seq":297,"section":"1. Droit à la vie","text":"Le 13 juillet 2016, dans le quartier de Gihosha à Bujumbura, des personnes non-\nidentifiées ont assassiné Hafsa Mossi, députée burundaise de l’Assemblée législative de la\nCommunauté des États d’Afrique de l’Est (CAE) et membre du CNDD-FDD. Selon le porte-\nparole de la police, ses assassins se trouvaient à bord d’un véhicule immatriculé en\nTanzanie500. La Commission n’a pas été en mesure d’obtenir des témoignages directs sur les\ncirconstances et les motifs de cet assassinat. La Commission a pris note d’une déclaration du\nporte-parole de la Cour suprême le 9 novembre 2016 selon laquelle le Parquet de Ntahangwa\navait ouvert un dossier sur ce cas et que quatre personnes avait été appréhendées501."},{"id":"a-hrc-36-crp-1-p0296","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"296","seq":298,"section":"1. Droit à la vie","text":"Le 28 novembre 2016, des individus armés ont attaqué Willy Nyamitwe, le principal\nconseiller en communication du Président de la République, dans la commune de Mutimbuzi\n(province de Bujumbura). L’un de ses agents de sécurité a été tué et un autre blessé. Willy\nNyamitwe a pour sa part été blessé au bras. Les 30 novembre et 1er décembre 2016, les\nautorités burundaises ont arrêté trois militaires, dont deux colonels, en lien avec cette\nattaque502."},{"id":"a-hrc-36-crp-1-p0297","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"297","seq":299,"section":"1. Droit à la vie","text":"Le 1er janvier 2017, juste après minuit, des individus armés non identifiés ont\nassassiné Emmanuel Niyonkuru, Ministre de l’eau, de l’environnement, de l’aménagement\ndu territoire et de l’urbanisme. Dans une déclaration à RFI le 1er janvier 2017, le porte-parole\nde la police a décrit les circonstances de son décès de la manière suivante : « Aux environs de\nminuit passé de 45 minutes, lorsque ce ministre rentrait chez lui à Rohero 2, tout près du\ncampus universitaire de Mutanga, il était à bord de son véhicule qu’il conduisait [...] Arrivé à\nl’intérieur de sa parcelle, quelqu’un a tiré sur lui trois coups avec un fusil de type pistolet. Le\nministre est mort sur le champ ». Le 7 janvier 2017, dans un communiqué, le Procureur\ngénéral de la République, Sylvestre Nyandwi, a indiqué qu’une enquête était en cours503.\nAssassinats et tentatives d’assassinat de membres des corps de défense et de sécurité"},{"id":"a-hrc-36-crp-1-p0298","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"298","seq":300,"section":"1. Droit à la vie","text":"La Commission a recueilli des informations sur des assassinats et tentatives\nd’assassinat de membres de la FDNB en 2015 et 2016. Ces actes ont visé aussi bien des\nmilitaires proches du Gouvernement que des membres réputés critiques du Gouvernement ou\nperçus comme tels, notamment du fait de leur passé d’ex-FAB ou de sympathies présumées\navec les militaires qui ont participé à la tentative de coup d'État en 2015. Les cas suivants,\nprésentés de manière chronologique, sont parmi les plus emblématiques."},{"id":"a-hrc-36-crp-1-p0299","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"299","seq":301,"section":"1. Droit à la vie","text":"Le 2 août 2015, à Kamenge (Bujumbura Mairie), des individus en tenue militaire ont\nassassiné le Général Adolphe Nshimirimana, ancien Administrateur Général du SNR, ainsi\nque trois de ses gardes du corps. L'assassinat de ce personnage très influent et proche du\nPrésident Nkurunziza, cité par de nombreux témoins comme impliqué dans des violations\ngraves des droits de l'homme depuis de nombreuses années, a été suivi le lendemain de la\ntentative d'assassinat du défenseur des droits de l'homme Pierre Claver Mbonimpa, l'une des\nfigures les plus connues de la société civile burundaise504. De nombreux observateurs ont vu\nun lien entre ces deux événements et ont interprété la tentative d'assassinat de Pierre-Claver\nMbonimpa comme une riposte à l'assassinat du Général Adolphe Nshimirimana. Plusieurs\nmilitaires et policiers ont été arrêtés en lien avec cet assassinat505. Leur procès s’est ouvert le\n1er août 2016 mais à la connaissance de la Commission, n’a à ce jour pas abouti."},{"id":"a-hrc-36-crp-1-p0300","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"300","seq":302,"section":"1. Droit à la vie","text":"Le 15 août 2015, un individu armé a assassiné le Colonel à la retraite Jean Bikomagu,\nancien chef d'état-major des FAB, dans son véhicule devant son domicile au quartier de\nKabondo à Bujumbura506. Sa fille, âgée de 16 ans, qui se trouvait également à bord du\nvéhicule, a été gravement blessée. Des militaires et des policiers se sont rapidement rendus\nsur les lieux du crime. Peu de temps après, Willy Nyamitwe, le conseiller en communication\ndu Président, a annoncé que le Colonel Bikomagu venait d’être assassiné chez lui et qu’une\nsomme d’argent aurait été volée507. La Commission a reçu des informations selon lesquelles\ndes proches du Colonel Bikomagu l’auraient informé d’un plan visant à l’assassiner, mais il\naurait minimisé ces risques. Certains de ses proches ont fait l’objet de menaces après son\nassassinat. L’assassinat du Colonel Bikomagu est survenu deux semaines après l’assassinat\ndu Général Adolphe Nshimirimana. Après la mort de ce dernier, des Imbonerakure, réunis à\nKamenge, auraient crié vengeance et réclamé la mort du Colonel Bikomagu508. La\nCommission n’a pas pu obtenir des informations sur l’état d’avancement des enquêtes dans le\ndossier de l’assassinat du Colonel Bikomagu509."},{"id":"a-hrc-36-crp-1-p0301","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"301","seq":303,"section":"1. Droit à la vie","text":"Le 11 septembre 2015, des individus armés en tenue militaire à bord d’un pick-up ont\nattaqué le convoi du chef d’état-major des FDNB, le Général-Major Prime Niyongabo, à\nBujumbura. Quatre militaires de l’escorte du Général-Major Niyongabo, une policière et\ndeux assaillants ont été tués. Un assaillant a été arrêté. Le Général-Major Niyongabo n’a pas\nété blessé510. Le 28 mars 2017, le Tribunal de grande instance de Muha a condamné à la la\nréclusion à perpétuité trois militaires et à 10 ans de prison deux civils accusés dans le cadre\nde cette affaire511."},{"id":"a-hrc-36-crp-1-p0302","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"302","seq":304,"section":"1. Droit à la vie","text":"Le 22 mars 2016, le Lieutenant-colonel Darius Ikurakure, commandant du Bataillon\nde génie de combat (camp Muzinda), a été assassiné dans l’enceinte de l’état-major des\nFDNB. De nombreux témoins, y compris plusieurs personnes interrogées par la Commission,\nont impliqué Darius Ikurakure dans des violations graves des droits de l'homme, surtout\ndepuis 2015. Les circonstances de son assassinat demeurent obscures. Un témoin a rapporté :\n« En règle générale, le Lieutenant-colonel Darius venait lire le tableau d’affichage\nchaque jour à la même heure. Il semble que son assassin avait suivi depuis quelques\nsemaines ses habitudes jusqu’à savoir qu’à cette heure précise il serait là, devant le\ntableau d’affichage. C’est là qu’il a été exécuté »512.\nUne autre source a indiqué : « Tuer quelqu’un à l’intérieur de l’état-major demande\ndes complices à l’intérieur. L’état-major est une enceinte fermée, militarisée, aux\nmurs assez hauts »513."},{"id":"a-hrc-36-crp-1-p0303","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"303","seq":305,"section":"1. Droit à la vie","text":"Le même jour, le Major Didier Muhimpundu, un ex-FAB qui travaillait à l’état-major\nde l’armée dans les services de santé, a été tué à Bujumbura. Selon les informations\nrecueillies par la Commission514, alors qu’il sortait d'un restaurant, il a été abattu de deux\nballes par deux individus à bord d’un véhicule sans plaque d’immatriculation. Une balle l’a\natteint au niveau de la tête et l’autre au niveau du cœur. Des policiers étaient en service tout\nprès de la scène. Au moment de son assassinat, des véhicules avec des policiers et des\nmilitaires à bord circulaient près de sa maison et, quelques heures avant sa mort, sa voiture\navait été suivie par un véhicule de la police. Selon un témoin interrogé par la Commission :\n« Il n’y a eu aucune arrestation suite à cette affaire. Les policiers enquêteurs ont eux-\nmêmes eu peur de poursuivre »515."},{"id":"a-hrc-36-crp-1-p0304","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"304","seq":306,"section":"1. Droit à la vie","text":"Dans la soirée du 7 avril 2016, trois individus non identifiés ont assassiné par balles le\nCapitaine Elie Mugabonuwundi, médecin radiologue à l’hôpital militaire, dans le quartier\nMirango II, zone Kamenge, commune Ntahangwa à Bujumbura516. Ils auraient ensuite lancé\ndes grenades dans son domicile dont l’une a explosé sans faire de dégâts. Selon certaines\nsources, le Capitaine Mugabonuwundi avait refusé de répondre à certaines demandes\nprovenant de proches du pouvoir, qu'il aurait jugées non conformes à l’éthique de sa\nprofession517."},{"id":"a-hrc-36-crp-1-p0305","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"305","seq":307,"section":"1. Droit à la vie","text":"Le 20 avril 2016, des hommes non identifiés, armés de fusils et de grenades, ont\nassassiné le Colonel Emmanuel Buzubona, alors qu’il rentrait chez lui à Kinama (Bujumbura\nMairie)518. Bien qu'issu des rangs des ex-rebelles du FDD, le Colonel Buzubona était connu\npour ses positions critiques à l’égard du Gouvernement519."},{"id":"a-hrc-36-crp-1-p0306","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"306","seq":308,"section":"1. Droit à la vie","text":"Le 24 avril 2016, à Gatunguru dans la commune de Mutimbuzi (province de\nBujumbura), des individus armés non identifiés ont attaqué le domicile d’un officier du SNR,\nDonatien Ndabigeze. Des hommes en treillis militaires ont fait irruption chez lui. Ils ont lancé\nune grenade en direction de sa femme, la tuant sur le coup, et ont tué par balles son beau-\nfrère. Ils ont ensuite échangé des tirs avec Donatien Ndabigeze et ont lancé une grenade en sa\ndirection, le blessant au niveau de la jambe. Bien avant cette attaque, Donatien Ndabigeze\navait reçu des menaces, notamment de la part de militaires520."},{"id":"a-hrc-36-crp-1-p0307","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"307","seq":309,"section":"1. Droit à la vie","text":"Le 25 mai 2016, des individus armés ont exécuté devant son domicile à Bujumbura le\nColonel à la retraite, Lucien Rufyiri, ex-FAB et ancien fonctionnaire des services de sécurité\ndes Nations Unies. Alors que ce dernier rentrait chez lui, quatre hommes dans une voiture\naux vitres teintées l’ont abordé au niveau du portail de sa maison et ont commencé à lui\nparler. Le Colonel Rufyiri est sorti de son véhicule pour continuer la conversation. Trois des\nquatre hommes se sont alors précipités sur lui pour le forcer à monter dans leur voiture.\nComme le Colonel Rufyiri résistait, le chauffeur de la voiture a sorti un pistolet et a tiré sur\nlui à plusieurs reprises. D'après certains témoignages, le Colonel Rufyiri avait un conflit\nfoncier avec des Imbonerakure ainsi qu'avec deux généraux influents au sein du CNDD-\nFDD521."},{"id":"a-hrc-36-crp-1-p0308","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"308","seq":310,"section":"2. Disparitions forcées","text":"Sur la base des rapports du Haut-Commissaire des Nations Unies aux droits de\nl’homme et de l’EINUB522, le Conseil des droits de l’homme a condamné les disparitions\nforcées au Burundi dans la résolution 33/24, adoptée le 30 septembre 2016523. L’EINUB avait\nen effet documenté les cas de nombreuses personnes disparues depuis avril 2015, « souvent\nsuite à une arrestation arbitraire par les forces de sécurité, notamment la police et le\nSNR »524. Le Comité contre la torture s’est également inquiété en 2016 des cas de disparition\nforcée ciblant des « jeunes hommes suspectés de participer à des manifestations, des\nmembres de la société civile opposés au troisième mandat [...] ainsi que des membres de\nl’opposition », tout en notant que « dans certains cas, des rançons auraient été exigées par des\nmembres de la police »525. Le Groupe de travail sur les disparitions forcées ou involontaires a\nexaminé six cas de disparition forcée au Burundi depuis avril 2015526, dont certains sont\nrepris plus bas.\n(a)     Droit applicable\n(i)     Droit international"},{"id":"a-hrc-36-crp-1-p0309","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"309","seq":311,"section":"2. Disparitions forcées","text":"L’article 2 de la Convention internationale pour la protection de toutes les personnes\ncontre les disparitions forcées définit ces dernières comme « l'arrestation, la détention,\nl'enlèvement ou toute autre forme de privation de liberté par des agents de l'État ou par des\npersonnes ou des groupes de personnes qui agissent avec l'autorisation, l'appui ou\nl'acquiescement de l'État, suivi du déni de la reconnaissance de la privation de liberté ou de la\ndissimulation du sort réservé à la personne disparue ou du lieu où elle se trouve, la\nsoustrayant à la protection de la loi ». Le Burundi a signé ce traité en 2007, mais ne l’a pas\nencore ratifié. En tant qu’État signataire, le Burundi est néanmoins tenu de ne pas agir\ncontrairement à l’objet et au but de la Convention527. Le Burundi est en outre tenu de\nrespecter les dispositions de la Déclaration sur la protection de toutes les personnes contre les\ndisparitions forcées, adoptée par l'Assemblée générale qui codifie le droit international\ncoutumier en la matière528."},{"id":"a-hrc-36-crp-1-p0310","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"310","seq":312,"section":"2. Disparitions forcées","text":"Par leurs caractéristiques, les disparitions forcées violent également des droits\ncontenus dans d’autres conventions internationales auxquelles le Burundi est partie,\nnotamment le droit à la liberté et à la sécurité de la personne garanti par l’article 9 du PIDCP.\nElles constituent également des atteintes graves au droit à la vie, reconnu par le PIDCP, la\nCDE et la CDPH. Le Comité des droits de l’homme a en outre considéré que les disparitions\nforcées, parce qu’elles consistaient à détenir indéfiniment des personnes sans contact avec le\nmonde extérieur et en dehors de la protection de la loi, étaient « indissociables » d’actes de\ntorture ou de traitements cruels, inhumains ou dégradants529. Le Comité a considéré que les\nmembres de la famille qui restent sans nouvelle de la personne portée disparue pendant une\nlongue période sont également victimes de torture ou de traitements cruels, inhumains ou\ndégradants530."},{"id":"a-hrc-36-crp-1-p0311","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"311","seq":313,"section":"2. Disparitions forcées","text":"Dès lorsqu’il y a des motifs raisonnables de croire ou même de craindre qu’un\nindividu a été victime d’une disparition forcée, les autorités sont tenues de mener des\nenquêtes diligentes et impartiales531. Si elles ne le font pas, elles sont susceptibles de violer le\ndroit à un recours utile garanti par l’article 2 du PIDCP.\n(ii)     Droit régional"},{"id":"a-hrc-36-crp-1-p0312","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"312","seq":314,"section":"2. Disparitions forcées","text":"Il n’existe pas au niveau africain de convention spécifique relative à la protection des\npersonnes contre les disparitions forcées. Les disparitions qui pourraient être qualifiées de\nforcées au regard du droit international n’en violent pas moins le droit à la vie, dans\nl’hypothèse où la personne disparue a été tuée, ainsi que le droit à l’intégrité physique et\nmorale de la personne, le droit à ne pas être soumis à la torture et à d’autres traitements\ncruels, inhumains ou dégradants, le droit à un procès équitable, le droit à la santé physique et\nmentale et le droit à une vie familiale saine, tous garantis par la CADHP532. Des dispositions\nsimilaires existent dans d’autres traités africains, comme le Protocole à la CADHP sur les\ndroits de la femme en Afrique et la Charte africaine des droits et du bien-être de l’enfant533.\n(iii)     Droit national"},{"id":"a-hrc-36-crp-1-p0313","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"313","seq":315,"section":"2. Disparitions forcées","text":"Le Code pénal burundais mentionne les disparitions forcées parmi les violations\nconstitutives de crimes contre l’humanité et les définit comme « les cas où des personnes sont\narrêtées, détenues ou enlevées par un État ou une organisation politique ou avec\nl’autorisation, l’appui ou l’assentiment de cet État ou de cette organisation, qui refuse ensuite\nd’admettre que ces personnes sont privées de liberté ou de révéler le sort qui leur est réservé\nou l’endroit où elles se trouvent, dans l’intention de les soustraire à la protection de la loi\npendant une période prolongée »534."},{"id":"a-hrc-36-crp-1-p0314","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"314","seq":316,"section":"2. Disparitions forcées","text":"L’article 244 du Code pénal burundais prévoit qu’« est puni d’une servitude pénale\nd’un an à cinq ans, celui qui, par violences, ruses ou menaces, a séquestré ou fait séquestrer, a\nenlevé ou fait enlever une personne quelconque ». La même disposition précise que : « Si\nl’enlèvement ou la séquestration a été exécuté, soit avec l’aide d’un uniforme ou d’un insigne\nréglementaire ou paraissant tel, soit sous un faux nom ou sur un faux ordre de l’autorité\npublique, la peine est la servitude de cinq ans à dix ans ». Dans le cas où la personne enlevée\nou séquestrée a été soumise à des actes de barbarie, l’auteur encourra une peine de 10 à 20\nans d’emprisonnement. En outre, à l’instar du droit international des droits de l’homme, les\ndisparitions forcées peuvent constituer des actes de torture ou des traitements cruels,\ninhumains ou dégradants que sanctionne également le Code pénal535.\n(b)     Les faits"},{"id":"a-hrc-36-crp-1-p0315","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"315","seq":317,"section":"2. Disparitions forcées","text":"Les témoignages recueillis par la Commission ont permis de confirmer la persistance\nde disparitions forcées et d’autres disparitions depuis avril 2015 jusqu’en 2017. La\nCommission a également consulté les informations contenues dans les rapports de la\nCNIDH536 et d’organisations de défense des droits de l’homme537 qui confirment ces\ntendances. La Commission n’a toutefois pas été en mesure de vérifier tous les cas rapportés\npar ces organisations, étant donné le temps limité qu’elle a eu pour s’acquitter de son mandat."},{"id":"a-hrc-36-crp-1-p0316","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"316","seq":318,"section":"2. Disparitions forcées","text":"La Commission est consciente que, dans le passé, certaines personnes portées\ndisparues au Burundi ont été retrouvées en vie. Elles avaient été portées disparues soit parce\nqu’elles avaient été détenues au secret, parfois pendant de longues périodes538, soit pour\nd’autres raisons. La Commission n’écarte donc pas la possibilité que certaines des personnes\nsignalées comme disparues, y compris des cas cités dans ce chapitre, puissent être retrouvées.\nNéanmoins, il revient à l’État d’entreprendre des enquêtes sur la participation éventuelle de\nses agents ou de personnes travaillant avec son assentiment, comme certains Imbonerakure,\ndans des disparitions forcées. Le fait que les autorités burundaises n’aient pas répondu aux\ndiverses demandes d’information de la Commission l'a empêché de vérifier certaines\nallégations et de recueillir le point de vue des autorités."},{"id":"a-hrc-36-crp-1-p0317","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"317","seq":319,"section":"2. Disparitions forcées","text":"Le 29 juin 2017, la Ministre de la justice, Aimée Laurentine Kanyana, aurait déclaré à\nla radio avoir donné un délai d’un mois à toute personne alléguant d’une disparition pour\ndéposer une plainte devant la juridiction compétente, après quoi le dossier serait classé sans\nsuite539. Outre le fait que ce délai court et décidé arbitrairement ne prend pas la mesure de la\ngravité du phénomène des disparitions ni de la peine des proches des victimes, il est\nimportant de rappeler que les disparitions forcées sont des violations des droits de l’homme\ncontinues. Le Groupe de travail sur les disparitions forcées a en effet précisé dans son\nobservation générale « sur la disparition forcée en tant que crime continu » que « les\ndisparitions forcées sont le prototype même d’actes continus. L’acte commence au moment\nde l’enlèvement et dure tant que le crime n’est pas terminé, c’est-à-dire jusqu’à ce que l’État\nreconnaisse la détention ou fournisse des informations sur le sort de l’individu ou le lieu où il\nse trouve »540. En conséquence, aucune limite ne peut être imposée à l’accès des familles de\nvictimes à la justice et la réparation, ainsi qu’à celui des victimes elles-mêmes lorsqu’elles\nsurvivent.\n(i)     Contexte"},{"id":"a-hrc-36-crp-1-p0318","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"318","seq":320,"section":"2. Disparitions forcées","text":"Les conditions dans lesquelles les arrestations ont été menées par les forces de l’ordre\nburundaises favorisent les disparitions forcées541. Dans de nombreux cas, les victimes ont été\narrêtées par des membres des corps de défense et de sécurité à bord de véhicules, souvent\nsans plaque d’immatriculation542. La Commission a également reçu plusieurs témoignages\nselon lesquels les personnes arrêtées n’ont pas été systématiquement enregistrées dans des\nlieux de détention du SNR ou de la police, ce qui ne laisse aucun indice de leur détention\narbitraire543. Un détenu a ainsi rapporté :\n« Nous avons été transférés au SNR près de la cathédrale [de Bujumbura] [...] Nos\nnoms n’ont pas été ajoutés au registre. Nous avons été incarcérés dans le plafond\nd’une toilette, pieds et bras liés sans manger »544.\nUn autre détenu a souligné : « Dans le lieu de détention [de la police] « Chez\nNdadaye »545 [...] aucun prévenu n’est enregistré dans un quelconque registre »546."},{"id":"a-hrc-36-crp-1-p0319","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"319","seq":321,"section":"2. Disparitions forcées","text":"La Commission a distingué entre les cas pour lesquels elle a des motifs raisonnables\nde croire qu’il s’agit de disparitions forcées et ceux où elle a des motifs raisonnables de le\ncraindre. Dans la première catégorie, la Commission a reçu des informations lui permettant\nde conclure à l’existence des éléments prévus dans la définition des disparitions forcées\ndonnée par la Convention internationale pour la protection de toutes les personnes contre les\ndisparitions forcées, à savoir la privation de liberté par des agents étatiques ou des personnes\nagissant avec l’acquiescement de l’État, suivi du déni de la privation de liberté ou de la\ndissimulation du sort réservé à la personne disparue547. Dans la seconde catégorie, la\nCommission n’a pas été en mesure de conclure à l’existence de tous ces éléments, mais a des\nmotifs raisonnables de craindre que les personnes visées ont été victimes de disparitions\nforcées du fait de leur profil suggérant qu’elles ont été ciblées, du mode opératoire, des\nconditions et du contexte dans lequel ont eu lieu leurs disparitions, notamment le contexte\ngénéralisé de non-respect des garanties judiciaires lors des arrestations et des détentions."},{"id":"a-hrc-36-crp-1-p0320","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"320","seq":322,"section":"2. Disparitions forcées","text":"La Commission a également reçu des informations sur des cas de disparition pour\nlesquels elle ne dispose pas suffisamment d'informations pour conclure qu'il existe des motifs\nraisonnables de croire ou de craindre qu’il s’agit de disparitions forcées, notamment des cas\nd’enlèvement par des Imbonerakure où il n’a pas été possible de démontrer l’autorisation,\nl’appui ou l’acquiescement des autorités burundaises. La Commission a également recueilli\ndes informations sur des cas qu’elle n’a pas été en mesure de corroborer, faute de temps et\nfaute d’accès au Burundi et aux proches des victimes. Certains de ces cas devraient faire\nl'objet d'enquêtes plus approfondies et pourraient éventuellement être étudiés par le Groupe\nde travail des Nations Unies sur les disparitions forcées ou involontaires, le Comité des\ndisparitions forcées ou tout autre mécanisme ou juridiction menant des enquêtes crédibles."},{"id":"a-hrc-36-crp-1-p0321","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"321","seq":323,"section":"2. Disparitions forcées","text":"La Commission a pris note que, dans son rapport annuel de 2015, la CNIDH a relevé\n19 cas d’enlèvement ou de disparition forcée survenus au cours de l’année 2015, dont celui\nde Marie-Claudette Kwizera, trésorière de la Ligue Iteka, portée disparue depuis le 10\ndécembre 2015548. Ce cas a été également documenté par la Commission et figure dans le\nprésent rapport549. Dans son rapport semestriel couvrant la première moitié de 2017, la\nl’instabilité régnant au Burundi, qui risquent de créer des conditions propices aux disparitions forcées »\n(A/HRC/WGEID/110/1, para. 24).\nCNIDH a indiqué avoir été saisi à 20 reprises pendant cette période sur des allégations\nd’enlèvement ou de disparition forcée, dont celle de Pacifique Birikumana, chauffeur à\nl’Évêché de Ngozi, qui a été également documentée par la Commission550."},{"id":"a-hrc-36-crp-1-p0322","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"322","seq":324,"section":"2. Disparitions forcées","text":"Dans de nombreux cas, suite aux disparitions, les proches des personnes disparues ont\nfait l’objet de pressions, d’intimidations ou de menaces liées à la disparition de la part\nd'agents de la police ou du SNR ou d'Imbonerakure, ce qui les a conduits à vivre cachés ou à\nfuir le pays551.\n(ii)     Cas où il y a des motifs raisonnables de croire qu’il s’agit de disparitions forcées"},{"id":"a-hrc-36-crp-1-p0323","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"323","seq":325,"section":"2. Disparitions forcées","text":"La Commission a reçu des informations concordantes sur des cas de personnes\narrêtées et détenues par des agents des corps de défense et de sécurité qui n’ont jamais pu être\nretrouvées par leur famille. Deux d’entre elles sont membres de partis d’opposition. Ces cas\nemblématiques témoignent de l’impunité dont jouissent les forces de l’ordre dans un contexte\nde persécution politique généralisée.\nAugustin Hatungimana"},{"id":"a-hrc-36-crp-1-p0324","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"324","seq":326,"section":"2. Disparitions forcées","text":"Augustin Hatungimana, alias « Tarpon », était chargé de la jeunesse du parti\nd’opposition MRC-Rurenzangemero à Cibitoke (Bujumbura Mairie) et avait pris part aux\nmanifestations contre le nouveau mandat du Président Nkurunziza en 2015. Selon les\ntémoignages recueillis par la Commission552, le 9 décembre 2015, des policiers à bord d’un\npick-up ont arrêté Augustin Hatungimana à Cibitoke, l’accusant de donner des armes à des\njeunes du quartier. Au moment de l’arrestation qui s’est déroulée en présence notamment\nd’un officier du SNR, les policiers ont tiré en l’air pour disperser les personnes qui se\ntrouvaient autour, puis ont emmené Augustin Hatungimana vers un endroit inconnu. Des\nproches d'Augustin Hatungimana ont par la suite été informés qu’il serait détenu au SNR et\ndes agents du SNR leur ont demandé de leur donner 600 000 francs burundais (soit environ\n344 dollars américains) pour le faire libérer. Ce montant leur a été versé, mais Augustin\nHatungimana n'a pas été libéré. Le 13 décembre 2015, des policiers de la BAE, conduits par\nun officier de cette unité, sont venus chez Augustin Hatungimana. Ils ont menacé et battu\ncertains de ses proches et ont brûlé des objets lui appartenant ou appartenant à sa famille. Des\nalertes ont été lancées par des organisations de la société civile553 et des recherches ont été\neffectuées pour le retrouver, mais aucune information n’a pu être obtenue sur l’endroit où il\naurait été détenu ou sur son sort.\nBernard Baranjoreje"},{"id":"a-hrc-36-crp-1-p0325","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"325","seq":327,"section":"2. Disparitions forcées","text":"Bernard Baranjoreje était responsable de la mobilisation des jeunes au sein du parti\nMSD au niveau de Bujumbura Mairie. Selon les informations rassemblées par la\nCommission554, le 19 janvier 2016, en fin de journée, des agents de la police, dirigés par un\nofficier du SNR, à bord d’un pick-up sans plaque d’immatriculation ont arrêté Bernard\nBaranjoreje dans un bar dans le quartier de Kigobe à Bujumbura. L’un des policiers lui a dit:\n« Bernard, vous êtes encore en vie ? ». Les policiers ont arrêté et menotté plusieurs autres\npersonnes qui étaient au même endroit, puis, après avoir cherché à vérifier leur identité, les\nont libérées et sont partis avec Bernard Baranjoreje vers une destination inconnue. Il n'a pas\nété revu depuis. Les démarches effectuées par ses proches en vue de le retrouver, notamment\nau niveau de centres de détention, se sont révélées vaines.\nHugo Haramategeko"},{"id":"a-hrc-36-crp-1-p0326","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"326","seq":328,"section":"2. Disparitions forcées","text":"Hugo Haramategeko était le président du parti d'opposition Nouvelle alliance pour le\ndéveloppement du Burundi (NADEBU). Selon les témoignages recueillis par la\nCommission555, tôt dans la matinée du 9 mars 2016, des policiers guidés par un\nImbonerakure, à bord d’un véhicule de police appartenant à un haut dignitaire de l’État, se\nsont présentés au domicile d'Hugo Haramategeko à Mutakura (Bujumbura Mairie). Un\npolicier a demandé à Hugo Haramategeko de décliner son identité. Ce dernier lui a montré sa\ncarte d’identité et les policiers l’ont emmené dans le véhicule en direction du quartier de\nCibitoke. Croyant qu’il allait être détenu au poste de police de Cibitoke, ses proches s’y sont\nrendus, mais les policiers en service leur ont déclaré qu'il ne s’y trouvait pas. D’après\ncertaines sources, le véhicule à bord duquel il se trouvait aurait pris la direction de la\nprovince de Bubanza. Ses proches ont alerté des observateurs des droits de l’homme et ont\ndéposé une plainte à la CNIDH. Malgré les recherches entreprises, Hugo Haramategeko n’a\nété trouvé dans aucun centre de détention officiel du pays et son sort reste inconnu556."},{"id":"a-hrc-36-crp-1-p0327","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"327","seq":329,"section":"2. Disparitions forcées","text":"Saisi de ce dossier, le Groupe de travail sur les disparitions forcées ou involontaires,\nagissant au titre de sa procédure d’action urgente, a transmis le cas d'Hugo Haramategeko au\nGouvernement burundais le 4 juillet 2016557.\nJean Bigirimana"},{"id":"a-hrc-36-crp-1-p0328","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"328","seq":330,"section":"2. Disparitions forcées","text":"Le journaliste Jean Bigirimana avait travaillé pour Rema FM (radio proche du parti au\npouvoir) avant de rejoindre le groupe de presse indépendant Iwacu en juin 2016. Il\ncollaborait également avec le site Infos Grands Lacs."},{"id":"a-hrc-36-crp-1-p0329","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"329","seq":331,"section":"2. Disparitions forcées","text":"Selon les informations recueillies par la Commission558, le 22 juillet 2016, des agents\ndu SNR et de la police ont arrêté Jean Bigirimana sur la route reliant Bugarama à Muramvya\n(province de Muramvya) et l’ont emmené en direction de Muramvya. Depuis ce jour, ses\nproches sont sans nouvelle de lui en dépit de recherches effectuées, notamment dans des\ncentres de détention. Un Officier de police judiciaire de Muramvya a informé l’un des\nproches de Jean Bigirimana que ce dernier n’avait pas été arrêté par la police de cette\nprovince. Le porte-parole de la police, Pierre Nkurikiye, a également nié que la police avait\narrêté Jean Bigirimana et assuré qu’elle allait continuer les enquêtes sur ce dossier, « sous la\ndirection du parquet »559."},{"id":"a-hrc-36-crp-1-p0330","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"330","seq":332,"section":"2. Disparitions forcées","text":"Début août 2016, une équipe de journalistes d'Iwacu s'est rendue à plusieurs reprises\ndans la province de Muramvya afin de chercher des traces de leur collègue disparu. Des\nresponsables de la police et du SNR, du parquet de Muramvya et des représentants de la\nCNIDH les ont accompagnés durant certaines visites560. À l’occasion toutefois d’une visite\nsur le terrain effectuée sans aucune autorité, les journalistes ont découvert deux cadavres dans\nla rivière Mubarazi. Quelques jours plus tard, les deux corps ont été repêchés et amenés à la\nmorgue de Muramvya. En l’absence des collègues de son mari qui auraient pu la soutenir et\nla conseiller, la femme de Jean Bigirimina s’est rendue à la morgue afin de déterminer si l’un\ndes deux corps pouvait être celui de son mari, mais n’a pas été en mesure de l’identifier. Les\ndeux corps étaient en phase de décomposition avancée et l’un des deux était décapité. Le\nporte-parole de la police a déclaré qu'aucun des deux corps n’était celui de Jean\nBigirimana561."},{"id":"a-hrc-36-crp-1-p0331","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"331","seq":333,"section":"2. Disparitions forcées","text":"Comme rapporté dans les médias, en juin 2017, la femme de Jean Bigirimana a reçu\nune lettre la menaçant dans laquelle il était écrit : « Tu passes ton temps à parcourir le monde\nen discréditant l’image de ton pays natal, comme ton mari avait lui aussi commencé à le faire,\ntu vas bientôt le rejoindre là où il est incarcéré [...] La victime d’un assassinat a été avisée par\nl’antilope. Nous ne serons pas responsables de ton sang »562."},{"id":"a-hrc-36-crp-1-p0332","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"332","seq":334,"section":"2. Disparitions forcées","text":"La famille de Jean Bigirimana a déposé une plainte au commissariat général de la\npolice de Bujumbura en juillet 2016. Le Groupe de travail sur les disparitions forcées ou\ninvolontaires a également été saisi de ce cas et a transmis une demande d’informations au\nGouvernement du Burundi le 2 septembre 2016563.\nPacifique Birikumana"},{"id":"a-hrc-36-crp-1-p0333","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"333","seq":335,"section":"2. Disparitions forcées","text":"Pacifique Birikumana, chauffeur à l’Évêché de Ngozi, n’était pas connu pour des\nactivités politiques. Selon les informations recueillies par la Commission564, le 8 avril 2017,\nPacifique Birikumana a été chargé, dans le cadre de son travail de chauffeur, de conduire une\néquipe de militaires à Gitega. Une fois de retour à Ngozi, il s’est rendu dans un bar près de\nchez lui pour prendre un verre avec des amis. Le lendemain, des proches ont tenté de le\ncontacter sans succès. La Commission a recueilli des informations selon lesquelles des agents\ndu SNR auraient arrêté Pacifique Birikumana. En dépit des recherches entreprises dans\ndifférents lieux de détention, Pacifique Birikumana n’a pas été retrouvé à ce jour. Sa\ndisparition a été mentionnée dans le rapport de la CNIDH couvrant le premier semestre de\n2017 ainsi que dans une déclaration du FOCODE565.\n(iii)     Cas où il y a des motifs raisonnables de craindre qu’il s’agit de disparitions forcées"},{"id":"a-hrc-36-crp-1-p0334","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"334","seq":336,"section":"2. Disparitions forcées","text":"La Commission a recueilli des informations sur d'autres cas où certains indices,\ncomme le profil des victimes ou des auteurs présumés, le mode opératoire et le contexte, font\ncraindre qu’il s’agit de disparitions forcées.\nInnocent Ndayikeza"},{"id":"a-hrc-36-crp-1-p0335","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"335","seq":337,"section":"2. Disparitions forcées","text":"Innocent Ndayikeza était membre du MSD et chauffeur de taxi. Il avait loué sa voiture\nà des journalistes de RFI ayant couvert les manifestations contre le nouveau mandat du\nPrésident Nkurunziza en 2015. Selon les informations à la disposition de la Commission566,\ndans la matinée du 27 juillet 2015, deux hommes se présentant comme des clients ont\ndemandé à Innocent Ndayikeza de les conduire en ville. Une fois à bord du véhicule, ils\nl’auraient forcé sous la menace de leurs armes à se diriger vers une destination inconnue. Des\nproches ont cherché à le joindre sans succès sur son téléphone portable dans l’après-midi\njusqu’à ce qu’un inconnu au fort accent swahili, parlant mal le kirundi, réponde. Le\nlendemain après-midi, le corps d'Innocent Ndayikeza a été découvert, les bras ligotés, à\nNyabugete à Bujumbura Mairie. La victime avait la nuque tranchée et plusieurs blessures sur\nle visage. Deux semaines avant sa disparition, Innocent Ndayikeza aurait reçu plusieurs\nappels d’un Imbonerakure, lui demandant de le rencontrer pour prendre un verre.\nAlbert Dushime"},{"id":"a-hrc-36-crp-1-p0336","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"336","seq":338,"section":"2. Disparitions forcées","text":"Selon les témoignages recueillis par la Commission567, Albert Dushime a été arrêté\ndans la nuit du 21 au 22 novembre 2015 par des policiers dans la province de Kirundo. Les\npoliciers l’ont accusé d'avoir pris part à une attaque armée à Kirundo le 21 novembre 2015.\nUn officier du SNR, qui était à Kirundo au moment de son arrestation, aurait demandé à un\nresponsable de la police qu’on lui confie le détenu afin de l’acheminer à Bujumbura. Les\npoliciers auraient remis Albert Dushime à cet officier et Albert Dushime n’a plus été revu.\nUne photo, le montrant ligoté près de deux hommes en uniforme de police, a circulé sur les\nréseaux sociaux peu après son arrestation568. Une organisation de la société civile a fait état\nd’une déclaration du porte-parole de la police selon laquelle Albert Dushime aurait été\neffectivement arrêté mais qu’il était introuvable depuis son arrestation569. En novembre 2016,\nl’avocat de la famille d’Albert Dushime a déposé plainte auprès du Parquet près le Tribunal\nde grande instance de Muha. Cette plainte n’a pas connu de suite à ce jour.\nMarie-Claudette Kwizera"},{"id":"a-hrc-36-crp-1-p0337","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"337","seq":339,"section":"2. Disparitions forcées","text":"Selon les témoignages recueillis par la Commission570, le 10 décembre 2015, Marie-\nClaudette Kwizera, trésorière de l’organisation de défense des droits de l’homme la Ligue\nIteka et employée de l’Office national des télécommunications du Burundi (ONATEL), a\nreçu un appel d’une personne qui souhaitait la rencontrer alors qu’elle quittait la Clinique de\nl’œil, sur le Boulevard de l'UPRONA à Bujumbura. Au moment où elle demandait à son\ninterlocuteur son identité et le but de la rencontre, une voiture aux vitres teintées s’est arrêtée\nà l’endroit où elle se trouvait. Des personnes non-identifiées sont sorties du véhicule et l’ont\nembarquée de force. Ses proches ont entrepris des recherches la nuit même, mais n'ont pu la\ntrouver dans aucun lieu de détention."},{"id":"a-hrc-36-crp-1-p0338","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"338","seq":340,"section":"2. Disparitions forcées","text":"Une personne interrogée par la Commission a précisé qu’un agent du SNR a réclamé\nune somme d’argent importante à la famille de Marie-Claudette Kwizera, mais, malgré la\nremise de ce montant, la victime n’a pas été retrouvée571. Dans son rapport annuel 2015, la\nCNIDH a fait mention du cas de Marie-Claudette Kwizera en précisant que l’agent du SNR\ncité plus haut « a nié avoir reçu cette somme […] et a indiqué, lors des enquêtes sur ce cas,\navoir seulement promis de mener des investigations pour tenter de retrouver la victime »572."},{"id":"a-hrc-36-crp-1-p0339","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"339","seq":341,"section":"2. Disparitions forcées","text":"Dans ses commentaires sur le rapport de l’EINUB, le Gouvernement a indiqué qu’un\ndossier (RMP 154370/EB) avait été ouvert sur la disparition de Marie-Claudette Kwizera573,\nmais la Commission n’a reçu aucune information sur l’état d’avancement de ce dossier."},{"id":"a-hrc-36-crp-1-p0340","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"340","seq":342,"section":"2. Disparitions forcées","text":"Le cas de Marie-Claudette Kwizera est en train d’être examiné par le Groupe de\ntravail des Nations Unies sur les disparitions forcées ou involontaires574 et a été soulevé\npubliquement par plusieurs autres titulaires de procédures spéciales du Conseil des droits de\nl’homme575.\nSavin Nahindavyi"},{"id":"a-hrc-36-crp-1-p0341","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"341","seq":343,"section":"2. Disparitions forcées","text":"Savin Nahindavyi, agent du SNR, s’est rendu à son travail le 1er mai 2016 et n’a pas\nété revu depuis576. Des recherches effectuées par ses proches au niveau du SNR et dans\nplusieurs centres de détention se sont révélées infructueuses. Le lendemain de la disparition\nde Savin Nahindavyi, un agent du SNR a assuré sa famille qu’une enquête serait diligentée\nsur son cas. Une semaine plus tard, alors que l’enquête n’avait donné aucun résultat, l’un des\nsupérieurs hiérarchiques de Savin Nahindavyi a exprimé ses condoléances à l’un des proches\nde ce dernier."},{"id":"a-hrc-36-crp-1-p0342","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"342","seq":344,"section":"2. Disparitions forcées","text":"Savin Nahindavyi avait déménagé dans une maison qu’il venait de construire à\nGasekebuye pour satisfaire à une demande de sa hiérarchie en mai 2015 qui lui reprochait\nd’habiter le quartier « contestataire » de Musaga à Bujumbura. Selon certains témoignages\nrecueillis par la Commission, ses supérieurs auraient également pu le soupçonner de jouer un\nrôle de lanceur d’alerte en faveur de personnes détenues au SNR."},{"id":"a-hrc-36-crp-1-p0343","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"343","seq":345,"section":"2. Disparitions forcées","text":"Le cas de Savin Nahindayi est en train d’être examiné par le Groupe de travail des\nNations Unies sur les disparitions forcées ou involontaires577.\nOscar Ntasano"},{"id":"a-hrc-36-crp-1-p0344","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"344","seq":346,"section":"2. Disparitions forcées","text":"Oscar Ntasano est un homme d’affaires, propriétaire de l’hôtel Nonara à Bujumbura.\nMembre du CNDD-FDD, il avait été sénateur de 2005 à 2010 et député de la province de\nMakamba de 2010 à 2015. Selon plusieurs témoignages reçus par la Commission578, peu de\ntemps avant sa disparition, Oscar Ntasano avait été en contact avec un homme du nom de\nLambert Bitangimana au sujet d’une transaction immobilière. Le 20 avril 2017, Oscar\nNtasano s’est rendu à son bureau puis, accompagné de deux de ses employés, Thierry\nNgendabanka et Rémy Nsabumuremyi, est parti dans l’une de ses propriétés à Bujumbura où\nil avait rendez-vous avec Lambert Bitangimana. Oscar Ntasano et ses deux employés n’ont\nplus été revus."},{"id":"a-hrc-36-crp-1-p0345","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"345","seq":347,"section":"2. Disparitions forcées","text":"Le 25 avril 2017, la police a annoncé avoir retrouvé sa voiture accidentée le 22 avril à\nGashoho, dans la province de Muyinga, avec à son bord le cadavre de Lambert Bitangimana.\nLa police a présenté ce dernier comme l’auteur de l’enlèvement d'Oscar Ntasano et de ses\ndeux employés579. Or les témoignages recueillis par la Commission, ainsi que des photos\nayant circulé sur internet580, indiquent que le corps de Lambert Bitangimana avait des traces\nde strangulation sur le cou. De plus, la plaque du véhicule n'était pas celle du véhicule\nd'Oscar Ntasano."},{"id":"a-hrc-36-crp-1-p0346","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"346","seq":348,"section":"2. Disparitions forcées","text":"Selon les informations reçues par la Commission, Lambert Bitangimana aurait\ntravaillé pour le SNR et aurait participé à d'autres opérations impliquant d’éventuelles\nviolations des droits de l’homme. La Commission a également reçu des témoignages\nindiquant qu'Oscar Ntasano aurait reçu des menaces de la part d’officiels burundais en raison\nd’un contrat qu’il était en train de conclure avec les Nations Unies pour la location de l’hôtel\nNonara en vue d’y établir des bureaux. Un responsable de l’État burundais lui aurait réclamé\nla moitié des montants du contrat et l’aurait menacé de mort en cas de refus."},{"id":"a-hrc-36-crp-1-p0347","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"347","seq":349,"section":"2. Disparitions forcées","text":"La Commission a reçu des informations sur l’arrestation de plusieurs personnes en\nlien avec ce cas, mais n’a pas été mesure de confirmer l’état actuel de l’instruction de ce\ndossier.\n(iv)     Autres cas de disparition"},{"id":"a-hrc-36-crp-1-p0348","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"348","seq":350,"section":"2. Disparitions forcées","text":"Des témoins entendus par la Commission ont rapporté des cas d’enlèvement commis\npar des hommes souvent armés, identifiés par certains témoins comme des Imbonerakure.\nCes derniers se seraient introduits de nuit chez des membres de partis d'opposition ou de\nmanifestants contre le nouveau mandat du Président Nkurunziza et les auraient emmenés vers\ndes destinations inconnues581. Pour ces cas, la Commission n’a pas atteint un niveau de\ncorroboration suffisant pour attester qu’elle a des motifs raisonnables de croire, ni même de\ncraindre, que ce sont des cas de disparitions forcées et que les auteurs identifiés, comme des\nImbonerakure, agissaient en collaboration avec des agents de l’État. Cependant, vu la\nrécurrence de ce type d’enlèvement et le profil des personnes ciblées, la Commission ne peut\nles passer sous silence."},{"id":"a-hrc-36-crp-1-p0349","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"349","seq":351,"section":"2. Disparitions forcées","text":"À titre d’exemple, en mai 2015, dans la province de Bubanza, des Imbonerakure sont\nvenus chez un homme qui refusait d’adhérer au parti au pouvoir et l’ont emmené vers une\ndestination inconnue. Depuis ce jour, il n’a pas été revu582. Dans un autre cas, un militant de\nl’opposition aurait été enlevé en décembre 2015 par des Imbonerakure dans la province de\nBujumbura. Sa famille n’a depuis lors aucune nouvelle de lui583. Un autre témoignage\nrecueilli par la Commission a fait état de l’enlèvement en juillet 2016 dans la province de\nCibitoke d’un membre d’un parti de l’opposition, actif dans la campagne contre le nouveau\nmandat du Président Nkurunziza, par des hommes non identifiés584."},{"id":"a-hrc-36-crp-1-p0350","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"350","seq":352,"section":"2. Disparitions forcées","text":"La Commission a également reçu des informations sur un ex-FAB ayant disparu dans\nla province de Muyinga depuis mars 2016. Un Officier de police, soupçonné d’être impliqué\ndans de nombreux cas de violations des droits de l’homme et qui logeait dans le même hôtel\nque la victime, aurait emmené cette dernière vers une destination inconnue à bord d’un pick-\nup du SNR585."},{"id":"a-hrc-36-crp-1-p0351","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"351","seq":353,"section":"2. Disparitions forcées","text":"La Commission reconnaît que le climat général d’insécurité qui prévaut au Burundi\nest de nature à favoriser des enlèvements par divers groupes non identifiés. Dans les cas\nd’enlèvement, il est particulièrement difficile d’établir les responsabilités. Un témoin a par\nexemple rapporté l’enlèvement d’une personne par des inconnus en août 2016 :\n« Le corps de [X] qui était étudiant [...]à l’Université du Burundi a été retrouvé [...]\n[Deux semaines plus tôt], alors que [X] était sorti pour acheter quelque chose dans le\nquartier […], un véhicule aux vitres teintées l’a emmené vers une destination\ninconnue »586."},{"id":"a-hrc-36-crp-1-p0352","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"352","seq":354,"section":"2. Disparitions forcées","text":"Les allégations d’existence de fosses communes et la découverte régulière dans les\nrues et dans les cours d’eau de cadavres parfois décapités, puis enterrés sans identification ni\nenquête préalables, constituent des éléments d’incertitude supplémentaires et renforcent le\nclimat d’insécurité587.\n(v)      Demandes de rançon"},{"id":"a-hrc-36-crp-1-p0353","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"353","seq":355,"section":"2. Disparitions forcées","text":"Des témoignages recueillis par la Commission font état de rançons réclamées\nprincipalement par des agents du SNR et de la police, ou des individus qui se sont présentés\ncomme tels, à des proches de victimes de disparition. En échange de sommes d’argent parfois\nimportantes, ces individus promettent de révéler l’endroit où seraient les personnes disparues\nou celui où leurs corps se trouveraient alléguant, dans certains cas, qu’elles avaient été\ntuées588. Ces individus ont ainsi profité de l’extrême vulnérabilité des proches des personnes\ndisparues, par exemple dans les cas d’Augustin Hatungimana et de Marie-Claudette Kwizera\nmentionnés plus haut589.Une victime a raconté que pendant qu’elle était en détention:\n« [Un] responsable du SNR a dit à ma famille que j'étais mort et qu'elle pouvait aller\nchercher mon corps à [X endroit]. Il voulait de l'argent. Ma famille me cherchait\npartout. [Des membres de ma famille] sont allés au SNR. Ce responsable leur a dit\nque s’ils lui donnaient de l'argent, il leur montrerait où était mon cadavre. La famille\nlui a donné 1,5 million de francs burundais [soit environ 860 dollars américains]\nmais elle est partie déçue »590.\n(vi)     Conséquences pour les familles et les proches de disparus"},{"id":"a-hrc-36-crp-1-p0354","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"354","seq":356,"section":"2. Disparitions forcées","text":"En plus des menaces qu’ont subies les proches des disparus, le phénomène des\ndisparitions forcées a des conséquences dommageables sur la vie des familles et des proches\ndes victimes. En effet, la Commission a noté la vulnérabilité particulière des femmes, soit les\nconjointes des victimes, une fois leur conjoint disparu. Celles-ci, une fois seules à la maison,\nsont sujettes à des violations diverses. Selon l’épouse d’un disparu :\n« Mon mari s’est beaucoup impliqué dans les mouvements contre le troisième mandat\nillégal de Pierre Nkurunziza […] Il a disparu depuis le 13 mai 2015, le jour du coup\nd’État manqué, et je me suis retrouvée seule sans savoir où il se trouve. Je ne sais pas\ns’il est encore en vie ou s’il a été exécuté [...] J’ai été obligée de fuir et d’abandonner\ntout ce que j’avais peur d’être enlevée, violée ou emprisonnée »591."},{"id":"a-hrc-36-crp-1-p0355","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"355","seq":357,"section":"2. Disparitions forcées","text":"Les proches de personnes disparues ont fait part à la Commission du traumatisme\ncontinu qu’ils subissent. La fille d’un disparu s’est confiée :\n« Je suis constamment en proie à l’image de mon père qui me poursuit partout. Dans\nla rue comme dans mes rêves, je le vois »592."},{"id":"a-hrc-36-crp-1-p0356","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"356","seq":358,"section":"3. Droit à la liberté et la sécurité de la personne","text":"Depuis 2015, le Conseil des droits de l’homme a condamné les arrestations et\ndétentions arbitraires, notamment « collectives », « dont sont victimes des membres de la\nsociété civile, des journalistes, des membres de l’opposition et des manifestants, y compris de\njeunes manifestants » au Burundi593. Dans sa résolution de septembre 2016, le Conseil a\ndéploré en particulier « l’existence de lieux de détention clandestins, notamment de cellules\nsecrètes situées dans des complexes du Service national de renseignement »594. Cette\nrésolution a été adoptée sur la base des rapports du Haut-Commissaire des Nations Unies aux\ndroits de l’homme et de l’EINUB qui tous deux ont mis l’accent sur l’augmentation du\nnombre d’arrestations et de détentions arbitraires depuis avril 2015595. Le Comité contre la\ntorture et le Comité pour l'élimination de la discrimination à l'égard des femmes se sont\négalement inquiétés de cette tendance en 2016596.\n(a)     Droit applicable\n(i)     Droit international"},{"id":"a-hrc-36-crp-1-p0357","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"357","seq":359,"section":"3. Droit à la liberté et la sécurité de la personne","text":"Le droit à la liberté et à la sécurité de la personne est garanti par l'article 9 de la\nDUDH et l’article 9 du PIDCP. Le premier alinéa de cette dernière disposition précise que\n« tout individu a droit à la liberté et à la sécurité de sa personne. Nul ne peut faire l'objet\nd'une arrestation ou d'une détention arbitraire. Nul ne peut être privé de sa liberté, si ce n'est\npour des motifs et conformément à la procédure prévue par la loi »."},{"id":"a-hrc-36-crp-1-p0358","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"358","seq":360,"section":"3. Droit à la liberté et la sécurité de la personne","text":"L’arrestation qui « s'entend de l'acte qui consiste à appréhender une personne du chef\nd'une prétendue infraction ou par le fait d'une autorité quelconque »597 est arbitraire en vertu\ndu PIDCP si elle n’est pas fondée sur des raisons prévues par la loi ou en accord avec des\nprocédures prévues par la loi598. L’article 9 (2) du PIDCP dispose en outre que toute personne\narrêtée doit être informée des raisons de son arrestation au moment où celle-ci a lieu ainsi que\ndes charges qui pèsent contre elle, dans un délai court599. Les agents procédant à l’arrestation,\nne peuvent recourir à la force que lorsque cela est nécessaire et de manière proportionnée."},{"id":"a-hrc-36-crp-1-p0359","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"359","seq":361,"section":"3. Droit à la liberté et la sécurité de la personne","text":"La détention, que le PIDCP définit comme une privation de liberté, ne peut, en vertu\nde l’article 9 (1) du Pacte, avoir lieu que « pour des motifs et conformément à la procédure\nprévue par la loi ». Une détention sera arbitraire si une personne est privée de sa liberté sans\nêtre suspectée d’un crime ou d’un délit et dans le seul but par exemple de lui soutirer des\ninformations ou de faire pression sur elle600. De la même manière, le placement en détention\ndoit suivre des procédures prévues par la loi, ce qui inclut la définition des autorités habilitées\nà autoriser et prolonger la détention601, ainsi qu’un certain nombre de limites parmi lesquelles\nla durée maximale pendant laquelle une personne peut être maintenue en détention avant\nd’être présentée à un juge602."},{"id":"a-hrc-36-crp-1-p0360","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"360","seq":362,"section":"3. Droit à la liberté et la sécurité de la personne","text":"Le Comité des droits de l’homme a précisé que le terme « arbitraire » ne signifiait pas\nuniquement « contraire à la loi », mais devait être interprété plus largement afin d’inclure un\ncaractère inapproprié, injuste et imprévisible603. En conséquence, une arrestation et/ou une\ndétention peuvent être contraires au PIDCP si elles sont conformes à la législation en vigueur\nmais que les dispositions contenues dans celle-ci sont déraisonnables ou injustes, ou encore\nlorsque la privation de liberté n’est pas nécessaire ou est disproportionnée604."},{"id":"a-hrc-36-crp-1-p0361","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"361","seq":363,"section":"3. Droit à la liberté et la sécurité de la personne","text":"Le Comité des droits de l’homme a rappelé par ailleurs que les personnes dans\nl’attente de leur procès ne doivent être détenues qu’exceptionnellement et pour une courte\npériode605. Le Comité a également considéré que, sur la base de l’article 14 (3) (b) du PIDCP\nprévoyant que « toute personne accusée d'une infraction pénale a droit [...] à disposer du\ntemps et des facilités nécessaires à la préparation de sa défense et à communiquer avec le\nconseil de son choix », les personnes en détention dans l’attente de leur procès ont droit\nd’avoir accès à un conseil juridique à toutes les étapes de la procédure, y compris dans la\nphase initiale d’interrogation par la police606. Une mesure de privation de liberté qui pouvait\nêtre justifiée à l’origine peut devenir arbitraire avec le temps lorsqu’elle n’est plus nécessaire\nou juste607. Sera également jugée arbitraire la détention d’une personne dans des conditions\ninhumaines. L’article 10 (1) du PIDCP dispose en effet que « toute personne privée de sa\nliberté est traitée avec humanité et avec le respect de la dignité inhérente à la personne\nhumaine ». Le Comité des droits de l’homme a considéré à cet égard que « les personnes\nprivées de leur liberté jouissent de tous les droits énoncés dans le Pacte, sous réserve des\nrestrictions inhérentes à un milieu fermé »608."},{"id":"a-hrc-36-crp-1-p0362","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"362","seq":364,"section":"3. Droit à la liberté et la sécurité de la personne","text":"L’article 9 (4) du PIDCP dispose par ailleurs que « quiconque se trouve privé de sa\nliberté par arrestation ou détention a le droit d'introduire un recours devant un tribunal afin\nque celui-ci statue sans délai sur la légalité de sa détention et ordonne sa libération si la\ndétention est illégale ». Si l’arrestation ou la détention est jugée illégale ou arbitraire, la\nvictime a un « droit à réparation » en vertu de l’article 9 (5) du PIDCP."},{"id":"a-hrc-36-crp-1-p0363","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"363","seq":365,"section":"3. Droit à la liberté et la sécurité de la personne","text":"La détention dans des lieux secrets est interdite en droit international, notamment\nparce qu’elle peut faciliter le recours à la torture et les mauvais traitements, et peut même\nconstituer une forme de mauvais traitement en soi609. Le Rapporteur spécial sur la torture et\nautres peines ou traitements cruels, inhumains ou dégradants recommande « de veiller à ce\nque tous les lieux de détention et d’interrogatoire secrets disparaissent »610. Le Comité des\ndroits de l’homme a également insisté pour que les États détiennent des personnes\nuniquement dans « des lieux de détention officiellement reconnus comme tels et que leur\nnom et le lieu de leur détention ainsi que le nom des personnes responsables de leur détention\nfigurent dans un registre aisément accessible aux intéressés, notamment aux membres de la\nfamille et aux amis » 611."},{"id":"a-hrc-36-crp-1-p0364","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"364","seq":366,"section":"3. Droit à la liberté et la sécurité de la personne","text":"L’article 37 de la Convention relative aux droits de l’enfant prévoit en outre que les\nÉtats parties veillent à ce que « nul enfant ne soit privé de liberté de façon illégale ou\narbitraire » et que lorsque la détention d’un mineur est rendue nécessaire, il soit « traité avec\nhumanité et avec le respect dû à la dignité de la personne humaine, et d'une manière tenant\ncompte des besoins des personnes de son âge. En particulier, tout enfant privé de liberté sera\nséparé des adultes, à moins que l'on estime préférable de ne pas le faire dans l'intérêt\nsupérieur de l'enfant, et il a le droit de rester en contact avec sa famille par la correspondance\net par les visites, sauf circonstances exceptionnelles »612.\n(ii)      Droit régional"},{"id":"a-hrc-36-crp-1-p0365","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"365","seq":367,"section":"3. Droit à la liberté et la sécurité de la personne","text":"L’article 6 de la CADHP dispose, à l’instar du PIDCP, que « tout individu a droit à la\nliberté et à la sécurité de sa personne. Nul ne peut être privé de sa liberté sauf pour des motifs\net dans des conditions préalablement déterminées par la loi ; en particulier nul ne peut être\narrêté ou détenu arbitrairement ».\n(iii)     Droit national"},{"id":"a-hrc-36-crp-1-p0366","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"366","seq":368,"section":"3. Droit à la liberté et la sécurité de la personne","text":"L’article 39 de la Constitution du Burundi prévoit que « Nul ne peut être privé de sa\nliberté, si ce n’est conformément à la loi. Nul ne peut être inculpé, arrêté, détenu ou jugé que\ndans les cas déterminés par la loi promulguée antérieurement aux faits qui lui sont\nreprochés ». L’exigence de légalité de la détention est également rappelée à l’article 42 en\nvertu duquel : « Nul ne peut être soumis à des mesures de sûreté que dans les cas et les\nformes prévus par la loi notamment pour des raisons d’ordre public ou de sécurité de l’État ».\nLes garanties judiciaires, notamment en cas de privation de liberté, sont pour leur part\nrappelées aux articles 38 (droit d’être jugé dans un délai raisonnable), 39 (droit à être\ndéfendu), et 40 (présomption d’innocence)."},{"id":"a-hrc-36-crp-1-p0367","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"367","seq":369,"section":"3. Droit à la liberté et la sécurité de la personne","text":"L’article 46 de la Constitution dispose que « nul enfant ne peut être détenu si ce n’est\nen dernier recours, auquel cas la durée de sa détention sera la plus courte possible. Tout\nenfant a le droit d’être séparé des détenus de plus de 16 ans et de faire l’objet d’un traitement\net de conditions de détention adaptés à son âge ». Enfin, l’article 23 de la Constitution prévoit\nque « Nul ne sera traité de manière arbitraire par l’État ou ses organes. L’État a l’obligation\nd’indemniser toute personne victime de traitement arbitraire de son fait ou du fait de ses\norganes »."},{"id":"a-hrc-36-crp-1-p0368","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"368","seq":370,"section":"3. Droit à la liberté et la sécurité de la personne","text":"L’article 52 du Code de procédure pénale burundais dispose que « La liberté [est] la\nrègle, la détention l’exception ». Le Code de procédure pénale permet néanmoins\nl’arrestation dans trois cas de figure. Tout d’abord, un individu peut être appréhendé dans le\ncadre d’une enquête afin d’être conduit devant l’autorité judiciaire compétente, à condition\nqu’il soit soupçonné d’avoir commis une infraction punissable d’au moins un an de servitude\npénale ou qu’il y ait contre lui des indices sérieux de culpabilité, des raisons sérieuses de\ncraindre sa fuite ou que son identité soit inconnue ou douteuse. Dans ce cas, l’individu\nappréhendé doit être présenté à l’autorité judiciaire au maximum dans les 36 heures qui\nsuivent son arrestation613. L’Officier de police judiciaire est également habilité à procéder à\ndes arrestations judiciaires lorsqu’une personne est suspectée d’avoir commis une infraction\net à la condition qu’il en informe immédiatement le Procureur de la République614. Enfin,\ndans le cadre de la procédure dite de « flagrance », une personne peut être appréhendée si elle\nest en train de commettre ou vient de commettre une infraction615. Dans ce cas, tout individu\nest autorisé à saisir l’auteur présumé de l’infraction en cas d’une atteinte grave à la sécurité\ndes biens, des personnes ou de l’État et en l’absence d’une autorité judiciaire compétente, à la\ncondition cependant que l’auteur présumé soit présenté immédiatement à l’autorité\ncompétente la plus proche, qui doit en avertir le Procureur de la République616. Dans ce\ncadre, la garde à vue ne peut en aucun cas dépasser 36 heures, après quoi la personne arrêtée\ndoit être présentée devant l’autorité judiciaire compétente617."},{"id":"a-hrc-36-crp-1-p0369","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"369","seq":371,"section":"3. Droit à la liberté et la sécurité de la personne","text":"Le Code de procédure pénale précise que « les officiers du Ministère public [...]\nlorsqu’ils constatent une détention ou rétention arbitraire ou illégale [...] prennent toutes les\nmesures appropriées pour la faire cesser sur-le-champ. En outre, si les faits sont constitutifs\nd’une faute pénale, disciplinaire ou les deux, ils entreprennent les poursuites appropriées [...]\nsaisissent aux mêmes fins les autorités judiciaires compétentes. Lorsqu’il est constaté ou\nprouvé que des aveux de culpabilité ou toute autre information ont été obtenus par torture,\npar contrainte ou par tout autre moyen déloyal, ils sont frappés de nullité ainsi que les\npreuves qui en découlent »618.\nProjets de révision du Code pénal et du Code de procédure pénale"},{"id":"a-hrc-36-crp-1-p0370","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"370","seq":372,"section":"3. Droit à la liberté et la sécurité de la personne","text":"Des projets de révision du Code pénal et du Code de procédure pénale sont en cours\nau moment de la rédaction du présent rapport619. Des amendements adoptés par le\nGouvernement en mai 2017620 ont été soumis à la Commission de la justice et des droits de la\npersonne humaine de l’Assemblée nationale le 6 juin 2017621. La présente Commission, qui a\npu se procurer une copie de ces projets, considère que certains des amendements proposés\nsont problématiques, notamment celui qui introduit la possibilité pour les Officiers de police\njudiciaire de mener des perquisitions sans mandat et de nuit dans les cas de flagrance et de\ncertaines infractions622. Le projet de révision prévoit en outre que « sont exemptés de\npoursuites judiciaires, les Officiers de police judiciaire qui, dans le cadre de leur mission et\nen vue de la réussite de celle-ci ou afin de garantir leur propre sécurité ou celle d'autres\npersonnes impliquées dans l'opération, commettent des infractions absolument nécessaires, et\nce avec l'accord exprès du Procureur de la République […] Ces infractions ne peuvent être\nplus graves que les infractions pour lesquelles les méthodes sont mises en œuvre et doivent\nêtre nécessairement proportionnelles à l'objectif visé »623. Dans le contexte actuel de\nviolations des droits de l’homme par des agents de l’État, la Commission craint que ces\nnouvelles dispositions puissent être utilisées d’une manière abusive et, ce faisant, augmentent\nles risques de violations des droits de l’homme et renforcent l’impunité.\n(b)     Faits"},{"id":"a-hrc-36-crp-1-p0371","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"371","seq":373,"section":"3. Droit à la liberté et la sécurité de la personne","text":"Les arrestations et détentions arbitraires sont les violations des droits de l’homme les\nplus rapportées au Burundi durant la période couverte par le mandat de la Commission et\ndébouchent pour beaucoup d’entre elles sur d’autres violations, notamment des exécutions\nextrajudiciaires, des disparitions forcées, des tortures et traitements cruels, inhumains ou\ndégradants, et des violences sexuelles624. Les constatations et les conclusions de la\nCommission s’agissant de l’arbitraire des arrestations et des détentions au Burundi vont au-\ndelà de celles, déjà préoccupantes, exprimées par la CNIDH, notamment dans son rapport\ncouvrant le premier semestre de 2017625.\n(i)     Principales victimes"},{"id":"a-hrc-36-crp-1-p0372","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"372","seq":374,"section":"3. Droit à la liberté et la sécurité de la personne","text":"Comme pour les autres violations des droits de l’homme présentées dans ce rapport,\nles victimes d’arrestations et de détentions arbitraires incluent des opposants avérés ou\nsupposés au Gouvernement626, notamment des manifestants contre un nouveau mandat du\nPrésident Nkurunziza ou des personnes suspectées d’avoir participé aux manifestations, des\nmembres de partis politiques, particulièrement des FNL ou du MSD, ou des personnes\nsuspectées d’être sympathisants de ces partis, ainsi que des membres d’organisations de la\nsociété civile, des journalistes et d’autres personnes ayant dénoncé des violations des droits\nde l’homme627. Des ex-FAB ont également été visés628, ainsi que des personnes ayant refusé\nd’adhérer au CNDD-FDD ou de verser de l’argent au parti629."},{"id":"a-hrc-36-crp-1-p0373","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"373","seq":375,"section":"3. Droit à la liberté et la sécurité de la personne","text":"Néanmoins, les informations reçues par la Commission font apparaître que le profil\ndes personnes arrêtées et détenues arbitrairement est plus varié que celui des victimes\nd’autres violations des droits de l’homme. Toutes n’étaient pas membres de l’opposition ou\nn’avaient pas exprimé des opinions contraires au Gouvernement ou au parti au pouvoir. De\nnombreuses personnes semblent avoir été arrêtées au hasard, parce qu’elles se trouvaient au\nmauvais endroit au mauvais moment, notamment pendant les manifestations de 2015 ou à\nl’occasion des descentes menées par les corps de défense et de sécurité dans certains quartiers\nde Bujumbura, pendant lesquelles la police a ciblé et appréhendé un grand nombre de jeunes\nhommes. Certaines personnes arrêtées et détenues étaient réellement des membres de groupes\narmés de l’opposition, mais beaucoup d’autres, selon les témoignages recueillis par la\nCommission, ont été arrêtées en l’absence de tout indice de leur participation présumée à des\ncrimes ou des délits ou même à des activités légitimes qui auraient déplu aux autorités."},{"id":"a-hrc-36-crp-1-p0374","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"374","seq":376,"section":"3. Droit à la liberté et la sécurité de la personne","text":"Certaines des victimes d’arrestations et de détentions arbitraires interrogées par la\nCommission ont été sujettes à des insultes à caractère ethnique dès leur arrestation630.\nL’origine ethnique présumée de la victime aurait également suffi, dans certains cas, à\nl’assimiler à l’opposition armée631. Une victime a raconté :\n« Mon frère […] a été [tué] […] alors qu’il était sur sa moto et il a succombé sur le\nchamp […] Quand je me suis présenté sur le lieu du crime pour réclamer son corps,\nj’ai été immédiatement ligoté par des policiers […] Ils m’ont dit que je devais d’abord\nmontrer les armes, en provenance du Rwanda, que nous détenons. Ils ont ajouté qu’ils\nsavent que tous les Tutsis [d’un certain quartier de Bujumbura] détiennent des armes\nà feu qu’ils ont reçues du Gouvernement rwandais »632.\n(ii)     Principaux auteurs"},{"id":"a-hrc-36-crp-1-p0375","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"375","seq":377,"section":"3. Droit à la liberté et la sécurité de la personne","text":"Les agents de la police ont été le plus souvent cités par les victimes comme auteurs\nd’arrestations et de détentions arbitraires633. Des unités de police spécifiques, notamment\nl’Appui pour la protection des institutions (API)634, la Brigade anti-émeute (BAE)635, et le\nGroupe mobile d’intervention rapide (GMIR)636, ont été mentionneés dans plusieurs\ntémoignages recueillis par la Commission. Des agents du SNR637 et des membres de la\nFDNB638 ont également été mentionnés. Des arrestations ont souvent été menées par des\nmembres de plusieurs corps de défense et de sécurité opérant ensemble, par exemple des\nagents du SNR ou des militaires accompagnant la police639."},{"id":"a-hrc-36-crp-1-p0376","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"376","seq":378,"section":"3. Droit à la liberté et la sécurité de la personne","text":"Plusieurs témoins ont rapporté la présence d’Imbonerakure lors d’arrestations par des\nmembres des corps de défense et de sécurité640. Dans certains cas, des personnes reconnues\npar des témoins comme étant des Imbonerakure ont aidé la police ou le SNR à identifier les\npersonnes à appréhender, notamment pendant les manifestations de 2015 et les opérations de\nfouille641. Un témoin des manifestations à Bujumbura en avril 2015 a déclaré :\n« Des jeunes en civil sur des motos aidaient les policiers à appréhender les\nmanifestants. Ces jeunes sont venus un peu avant la police […] Ils étaient avec le\ncommandant [X] [de la police]. Les jeunes appréhendaient les manifestants et les\nmettaient dans son pick-up »642."},{"id":"a-hrc-36-crp-1-p0377","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"377","seq":379,"section":"3. Droit à la liberté et la sécurité de la personne","text":"Dans d’autres cas, des Imbonerakure ont procédé seuls à des arrestations643. Un\nmembre d’un parti d’opposition a ainsi témoigné :\n« [En] 2017, [des hommes] sont venus à mon lieu de travail pour me demander 15\n000 francs burundais [soit environ 8,5 dollars américains] pour la permanence du\nCNDD-FDD. J’ai refusé de payer […] En rentrant à la maison […], j’ai retrouvé [ces\nhommes] sur la route. Ils m’ont battu tellement fort que j’ai perdu connaissance. [Ils]\navaient des bâtons en bois […] Il disait qu’ils battaient « ceux qui n’entendent pas »\n[…] Je me suis réveillé au cachot de la police judiciaire […] Je sais que [ces\nhommes] étaient des Imbonerakure. […] Ils portaient des tricots avec le logo du parti\nau pouvoir » 644.\n(iii)     Arrestations arbitraires"},{"id":"a-hrc-36-crp-1-p0378","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"378","seq":380,"section":"3. Droit à la liberté et la sécurité de la personne","text":"La Commission considère que de nombreuses arrestations ont été arbitraires car les\nprocédures n’ont pas respecté le droit international, tel que décrit plus haut, ni le droit\nburundais. De nombreuses personnes n’ont pas été informées des motifs de leur arrestation,\nou ont été informées de raisons qui n’avaient pas de base légale, comme l’appartenance à un\nparti d’opposition ou le fait d’habiter dans un quartier de Bujumbura dit « contestataire » 645."},{"id":"a-hrc-36-crp-1-p0379","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"379","seq":381,"section":"3. Droit à la liberté et la sécurité de la personne","text":"Dans d'autres cas, il y a eu des erreurs flagrantes dans les procédures d’arrestation et\nde détention. Par exemple, une personne avec qui la Commission s’est entretenue a été\narrêtée alors que le mandat d’arrêt n’était pas à son nom646. Une autre, une fois libérée de\nprison, a reçu un mandat d’élargissement647 portant le nom d’une prison dans laquelle elle\nn’avait pas été détenue648."},{"id":"a-hrc-36-crp-1-p0380","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"380","seq":382,"section":"3. Droit à la liberté et la sécurité de la personne","text":"La Commission a également reçu des informations faisant état d’actes de violence lors\nd’arrestations, alors que l’usage même de la violence n’était pas nécessaire649. Par exemple,\nune personne, qui a été violemment frappée lors de son arrestation en 2016 par des\nImbonerakure, des agents du SNR et des militaires, a témoigné :\n« [Des gens de la Documentation et un Imbonerakure que je connais] m’ont arrêté et\nm’ont accusé de distribuer des vivres aux rebelles [burundais] au Rwanda. Ils m’ont\nbattu en me demandant comment je faisais pour distribuer des vivres aux rebelles […]\nJ’ai dit que je n’étais pas avec un groupe armé et que j’étais du CNDD-FDD […] Ils\nm’ont attaché. Ensuite, j’ai été battu avec des branches d’eucalyptus et frappé avec\nles pieds […] [Ils] ont déchiré mes vêtements […] et j’ai reçu des coups de pied avec\ndes bottes militaires. […]» 650.\nUn étudiant a également rapporté : « Après m’avoir arrêté, les policiers m’ont pris\nmon téléphone et ils m’ont tabassé et giflé. Ils m’ont donné des coups de pied avec\nleurs bottes. Des voisins ont vu ce qui se passait. Ils ont crié en disant : « Ne tuez pas\ncet enfant ! » Les policiers leur ont dit que s’ils continuaient à crier, ils seraient\nemmenés comme moi »651.\n(iv)      Détentions arbitraires"},{"id":"a-hrc-36-crp-1-p0381","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"381","seq":383,"section":"3. Droit à la liberté et la sécurité de la personne","text":"De nombreuses personnes, arrêtées pour des motifs apparemment politiques ou parce\nque les autorités les soupçonnaient d’avoir des liens avec des partis ou des groupes\nd’opposition, ont été détenues dans les locaux du SNR à Bujumbura. Certaines y ont été\nconduites directement652, d’autres ont été détenues dans un premier temps dans un cachot de\npolice653. Certaines personnes arrêtées dans des provinces éloignées de la capitale ont\négalement été transférées au siège du SNR à Bujumbura654 ; d’autres ont été détenues dans\nles bureaux provinciaux du SNR. Une personne a rapporté qu’une fois que les détenus\narrivaient au siège du SNR à Bujumbura, les agents du SNR les triaient afin de distinguer les\nopposants présumés des autres détenus655. Des détenus ont passé plusieurs jours ou plusieurs\nsemaines au SNR avant d’être libérés, souvent sans aucune procédure officielle656, ou\ntransférés dans une prison où ils sont restés bien souvent de longs mois dans l’attente d’un\nprocès657."},{"id":"a-hrc-36-crp-1-p0382","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"382","seq":384,"section":"3. Droit à la liberté et la sécurité de la personne","text":"Dans de nombreux témoignages recueillis par la Commission, la détention a été\narbitraire parce qu’elle n’avait pas de base légale, la victime étant privée de liberté sans être\nofficiellement accusée d’un crime ou d’un délit658. Cela a notamment été le cas pour les\npersonnes détenues dans des lieux volontairement maintenus secrets afin de les soustraire à\ntoute forme de procédure et de contrôle659. D’autres personnes interrogées par la Commission\nont été inculpées d’infractions entraînant de lourdes peines, telle que l’« atteinte à la sécurité\nintérieure de l’État », la « participation à des bandes armées » et la « participation à un\nmouvement insurrectionnel », dans certains cas sans que ces infractions ne semblent avoir de\nlien avec les actes présumés qu’ils auraient commis. Une victime a relaté comment elle avait\nété arrêtée et accusée de possession illégale d’armes après avoir porté plainte au sujet du\nmeurtre de son frère par des Imbonerakure :\n« Pendant que j’attendais la réponse [à ma plainte] […] [des policiers, des\nImbonerakure et le chef de quartier m’ont arrêté] […] Une autre personne est venue\net m’a accusé de transporter des armes dans mon véhicule […]La police ne m’a rien\ndit au moment de mon arrestation et [un]avis de recherche m’a été montré au poste\nde police […] L’Officier de police judiciaire et [la personne qui m’accusait] m’ont\nfrappé puis ils se sont tournés vers [mon parent qui m’avait accompagné] et ils l’ont\nfrappé jusqu’à ce que le Commissaire de police intervienne. Lorsque le Commissaire\nest intervenu, [la personne qui m’a accusé] a accusé [mon parent] de l’avoir giflé et\n[mon parent] a été détenu pendant trois jours […] Moi j’ai été détenu au cachot de la\npolice judiciaire […] pendant deux semaines et un jour. Puis, j’ai été transféré à la\nprison »660."},{"id":"a-hrc-36-crp-1-p0383","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"383","seq":385,"section":"3. Droit à la liberté et la sécurité de la personne","text":"La Commission a également reçu des témoignages faisant mention de membres de la\nfamille de personnes recherchées détenus à leur place661. À titre d’exemple, en 2015, la\nfemme d’un policier ex-FAB accusé d’organiser des réunions avec d’autres ex-FAB contre le\nGouvernement a été détenue pendant une semaine après que les bottes de son mari ont été\ndécouvertes dans la maison familiale. Malgré l’assurance du supérieur hiérarchique du\npolicier en question qu’il s’agissait de bottes de fonction, et que sa seule faute avait été de les\navoir gardées chez lui, le Procureur a maintenu la femme en détention pendant une semaine\net l’a libérée après qu’une somme d’argent lui ait été versée662."},{"id":"a-hrc-36-crp-1-p0384","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"384","seq":386,"section":"3. Droit à la liberté et la sécurité de la personne","text":"Dans bien des cas également, la détention a été arbitraire car elle n’a pas respecté les\ngaranties fondamentales de détention. Certains détenus ont rapporté que leurs noms n’avaient\npas été inscrits dans les registres de détention663, favorisant par-là les disparitions664. À la\nconnaissance de la Commission, les personnes arrêtées ont rarement été informées de leurs\ndroits et peu d’entre elles ont eu accès à un avocat665. Lorsque des avocats sont intervenus,\ncela n’a le plus souvent été qu’au niveau des procès ; la plupart des détenus interrogés par la\nCommission n’ont pas bénéficié d’assistance juridique dès le début de leur détention. Une\npersonne arrêtée avec d’autres à un barrage de police en 2015 a témoigné :\n« La police nous a dit qu’on ne pouvait pas continuer […] Ils nous ont conduits dans\nun endroit que je ne connaissais pas, dans une maison clôturée. Ils ont fermé la porte.\nJ’ai demandé : « Est-ce que je suis arrêté ? Si oui, je dois informer ma famille ». Le\nchef du SNR m’a giflé et a dit : « Si tu continues, je vais te tuer » […] J’ai demandé à\nvoir un avocat. Il m’a dit : « Tu ne sais pas où tu es. Attends. On va amener un avocat\ndemain. » [Le lendemain], nous avons vu le chef du SNR avec des policiers. Ils nous\nont menottés et nous ont conduits jusqu’au SNR à Bujumbura. […] [Huit jours plus\ntard], j’ai été transféré à la prison centrale [d’une province]. Le Procureur [de la\nprovince] a demandé mon dossier au SNR. Le SNR a dit que je n’avais pas de dossier\n[…] J’ai été entendu par un magistrat. Il m’a demandé pourquoi j’étais là et quels\néléments il y avait contre moi. J’ai dit qu’il n’y avait rien. Le magistrat m’a dit que je\npouvais partir […] J’ai été libéré le soir même »666."},{"id":"a-hrc-36-crp-1-p0385","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"385","seq":387,"section":"3. Droit à la liberté et la sécurité de la personne","text":"L’Ensemble de règles minima pour le traitement des détenus667 prévoit par ailleurs\nqu’ « un prévenu doit immédiatement pouvoir informer sa famille de sa détention et se voir\nattribuer toutes les facilités raisonnables pour pouvoir communiquer avec celle-ci et ses amis\net recevoir des visites de ces personnes, sous la seule réserve des restrictions et de la\nsurveillance qui sont nécessaires dans l'intérêt de l'administration de la justice, de la sécurité\net du bon ordre de l'établissement »668. Or, la Commission a recueilli plusieurs témoignages\nde personnes détenues dans les cachots du SNR à Bujumbura, dans des cachots de police ou\ndans d’autres lieux sans que leurs familles ne sachent où elles avaient été conduites ou même\nsi elles étaient encore en vie. Ces détenus n’ont pas été autorisés à communiquer avec leurs\nfamilles, ni à recevoir de visite669, alors que cette pratique est contraire au droit international\net au droit burundais670. Un homme arrêté en décembre 2015 a été détenu en isolement\npendant plusieurs semaines dans une cellule secrète au SNR. Sa famille et ses amis le croyait\nmort jusqu’à son transfert dans une prison671. Un homme torturé par des Imbonerakure en\nprésence de policiers dans un poste de police en 2016 a témoigné :\n« Je suis resté dans le même cachot, sous haute surveillance et sans recevoir de visite.\nLes policiers intimidaient le moindre visiteur qui voulait m’approcher »672."},{"id":"a-hrc-36-crp-1-p0386","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"386","seq":388,"section":"3. Droit à la liberté et la sécurité de la personne","text":"Dans un grand nombre de cas documentés par la Commission, les délais légaux de\ndétention ont été dépassés. Pour la garde-à-vue, ce délai est de sept jours, renouvelable une\nfois673. La prolongation doit être décidée par un Officier du Ministère public. Cette durée, qui\nne correspond pas au standard international de 48 heures674, n’a pas souvent été respecté et\ndes personnes appréhendées ont été transférées vers des prisons avant même qu’une décision\nsur leur détention préventive n’ait été prise675. Selon les témoignages recueillis par la\nCommission, certaines de ces personnes sont restées en prison pendant des semaines, voire\ndes mois676. Une personne a ainsi rapporté avoir été détenue pendant 18 jours au SNR en\n2015 :\n« C’est [un officier du SNR] qui est venu m’arrêter […] [Les policiers qui\nl’accompagnaient] m’ont mis dans une camionnette, et m’ont infligé quatre coups de\npoignard dans l’épaule, la jambe, le dos, la fesse […] J’ai été emprisonné au SNR\n[…] pendant 18 jours. Je ne mangeais [qu’une fois] par jour. Je n’ai pas eu le droit\nde recevoir des visiteurs. J’ai été [ensuite] transféré à la prison centrale »677.\nUne autre victime a témoigné : « [En] mai 2015, j’ai été arrêté par [des] policiers\n[…] Les policiers m’ont tabassé et j’ai perdu connaissance […] Quand j’ai repris\nconnaissance, j’étais au SNR […] Je suis resté au SNR pendant [29 jours] »678."},{"id":"a-hrc-36-crp-1-p0387","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"387","seq":389,"section":"3. Droit à la liberté et la sécurité de la personne","text":"Des détenus ont été dans l’impossibilité d'introduire un recours devant un tribunal afin\nque celui-ci statue sur la légalité de leur détention679. C’est notamment le cas des personnes\nqui ont été détenues au secret sans aucune procédure judiciaire ni même administrative680.\nLes membres de leur famille ont été également dans l’impossibilité d’introduire un recours\ncar elles n’avaient aucune information sur leur sort."},{"id":"a-hrc-36-crp-1-p0388","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"388","seq":390,"section":"3. Droit à la liberté et la sécurité de la personne","text":"Les délais légaux ont également été dépassés dans plusieurs cas de détention\npréventive681 dont la durée maximale en droit burundais est d’un mois, prolongeable de mois\nen mois par un collège de trois magistrats de la juridiction682. Une victime a témoigné :\n« [En 2015], je suis entré dans la prison centrale de Mpimba […] J’ai passé huit mois\nlà-bas sans être interrogé, puis j’ai été appelé au parquet […] qui m’a interrogé et a\ndécidé de me mettre en détention préventive. [Une personne qui travaillait pour le\nparquet] m’a aidé en suivant mon dossier et en l’[envoyant] au tribunal. C’est ainsi\nqu’on a décidé de la peine d’une année et d’une amende de 100 000 francs burundais\n[soit environ 57 dollars américains]. Il me restait deux mois [de détention à faire] que\nj’ai passé en prison et j’ai été libéré [en] 2016 »683."},{"id":"a-hrc-36-crp-1-p0389","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"389","seq":391,"section":"3. Droit à la liberté et la sécurité de la personne","text":"D’autres personnes ont continué à être détenues malgré un ordre de libération délivré\npar l’autorité habilitée, ou même après avoir été acquittées par un tribunal ou avoir purgé leur\npeine684. L’une d’elles, arrêtée en mars 2016, a rapporté :\n« J’ai comparu au tribunal de grande instance. Puis, j’ai été renvoyé à la prison\ncentrale […] [Environ un mois plus tard], on m’a envoyé une assignation en vue de\nma libération. Le Procureur a refusé de me libérer en dépit de cet ordre de mise en\nliberté arguant de la gravité de mon cas : parce que j’appartiendrais à un mouvement\nrebelle. Après environ une année passée en prison […], une commission d’État est\nvenue à la prison […] Le même [jour], cette commission a pris la décision de me\nlibérer »685.\nUn membre du MSD condamné à une année d’emprisonnement en 2016 a indiqué\nqu’après avoir purgé sa peine, le directeur de la prison n’a pas voulu le libérer : « Je\ndevais être libéré le [date] car j'ai été jugé et j'ai reçu une peine d'une année. Mais [à\ncette date-là], le directeur de la prison a refusé de me libérer. Il a dit: « L'histoire du\nMSD, ce n'est pas moi qui décide. Je dois demander à ceux qui vous ont incarcéré ».\nIl m'accusait de donner de l'argent au CNARED. Finalement j'ai été libéré […] par\nla grâce présidentielle »686."},{"id":"a-hrc-36-crp-1-p0390","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"390","seq":392,"section":"3. Droit à la liberté et la sécurité de la personne","text":"De nombreuses victimes interrogées par la Commission ont été détenues dans des\nconditions constitutives de traitements cruels, inhumains ou dégradants, rendant leur\ndétention arbitraire687. Des femmes détenues arbitrairement ont subi des violences\nsexuelles688. Des mineurs ont été détenus avec des adultes dans des circonstances\nparticulièrement difficiles et certains ont été torturés689. Un mineur, arrêté et battu au SNR à\nBujumbura, a raconté :\n« On est venu m’arrêter alors que j’étais seul à la maison. […] [J’ai été conduit] à la\nDocumentation […] Nous [le témoin et d’autres jeunes] avons été battus et on criait\nde douleur […] Je pleurais beaucoup et je pensais qu’on allait me tuer et ma maman\nne savait pas où j’étais […] Au SNR, comme à [la prison], j’étais emprisonné avec les\nadultes […] [pendant 19 jours] »690.\n(v)     Lieux de détention non reconnus"},{"id":"a-hrc-36-crp-1-p0391","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"391","seq":393,"section":"3. Droit à la liberté et la sécurité de la personne","text":"La Commission s’est entretenue avec plusieurs personnes qui avaient été détenues\ndans des lieux de détention secrets, soustraits à tout contrôle par des organes nationaux et\ninternationaux habilités comme la CNIDH et le Haut-Commissariat aux droits de l’homme691.\nC’est notamment le cas de certaines pièces dissimulées au siège du SNR à Bujumbura692. Une\npersonne a décrit avoir été cachée dans le coffre d’une voiture dans l’enceinte du SNR693 et\nune autre dans le plafond de toilettes lors de la visite d’observateurs694. Plusieurs témoins\ninterrogés par la Commission ont mentionné l’existence d’une salle secrète où des détenus\nétaient torturés695. Des victimes ont décrit certains espaces comme étant plongés dans\nl’obscurité et coupés des bruits de l’extérieur696."},{"id":"a-hrc-36-crp-1-p0392","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"392","seq":394,"section":"3. Droit à la liberté et la sécurité de la personne","text":"D’autres personnes interrogées par la Commission ont témoigné avoir été détenues\ndans des maisons privées à Bujumbura697 et dans plusieurs provinces698, d’autres dans des\ncontainers699, certains situés dans des propriétés privées. Une personne a rapporté que sa\nrésidence, ainsi que celle d’un de ces voisins, avaient été occupées par des militaires et\nutilisées comme lieux de détention700. Les victimes ont décrit des conditions de détention très\ndifficiles dans tous ces lieux non-officiels. Une personne interrogée par la Commission aurait\nainsi été détenue pendant plus de trois mois sans jamais savoir où elle était701."},{"id":"a-hrc-36-crp-1-p0393","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"393","seq":395,"section":"3. Droit à la liberté et la sécurité de la personne","text":"Plusieurs victimes ont rapporté que des agents du SNR et de la police les ont ligotées\net leur ont bandé les yeux pendant qu’ils les transportaient jusqu’à ces lieux secrets et parfois\nmême pendant la durée de leur détention. Elles n’ont par conséquent pas toujours été en\nmesure d’identifier ou de localiser ces lieux702. Une victime a décrit avoir eu les yeux bandés\npendant les quatre jours de sa détention en 2016 :\n« J’ai été arrêté […] par des policiers [...] Ils m’ont bandé les yeux […] Ils nous ont\namenés dans un endroit où il n’y avait pas de fenêtre. C’était, je pense, une maison\navec des chambres noires. […] Je suis resté là pendant quatre jours […] Ils m’ont\nlaissé les yeux bandés pendant ma détention. Ils ne me débandaient les yeux que pour\nme montrer des photos. Ils cherchaient à ce que j’identifie ceux qui avaient participé\naux manifestations contre le troisième mandat. Je pense que la maison se trouvait à\nBujumbura »703."},{"id":"a-hrc-36-crp-1-p0394","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"394","seq":396,"section":"3. Droit à la liberté et la sécurité de la personne","text":"Certaines personnes détenues dans des lieux secrets ont été témoins de la présence\nd’autres détenus, laissant supposer que le nombre de personnes ayant été enfermées dans ces\nlieux est bien plus élevé que le nombre de témoignages recueillis à ce sujet par la\nCommission. Les personnes ayant été détenues dans ces lieux ont également rapporté avoir\nété victimes de tortures et de mauvais traitements704."},{"id":"a-hrc-36-crp-1-p0395","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"395","seq":397,"section":"3. Droit à la liberté et la sécurité de la personne","text":"La Commission a aussi reçu des informations selon lesquelles des civils auraient été\ndétenus dans des camps militaires, notamment suite aux attaques contre les installations\nmilitaires à Bujumbura et dans ses environs le 11 décembre 2015705.\n(vi)     Pratiques d’extorsion"},{"id":"a-hrc-36-crp-1-p0396","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"396","seq":398,"section":"3. Droit à la liberté et la sécurité de la personne","text":"Le régime des libérations semble dans bien des cas aléatoire, la publicité faite autour\nde l’arrestation ou la connaissance d’une personne dans l’appareil d’État pouvant faciliter la\nremise en liberté706. Souvent, les moyens financiers du détenu ou de sa famille peuvent\négalement être un facteur déterminant dans sa libération ou son maintien en détention."},{"id":"a-hrc-36-crp-1-p0397","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"397","seq":399,"section":"3. Droit à la liberté et la sécurité de la personne","text":"Dans de nombreux cas, des sommes d’argent exorbitantes ont été exigées par des\nmembres du SNR, de la police, du Parquet et parfois des Imbonerakure pour libérer des\ndétenus ou les transférer vers des prisons où les conditions de détention sont relativement\nmeilleures707. Cependant, même après avoir déboursé ces sommes, certains détenus ont dû\nencore attendre. Une victime a ainsi témoigné :\n« [Un agent du SNR] m’a demandé combien d’argent j’avais sur mon compte […] [Il]\na déclaré : « Si tu acceptes de me donner ce montant, je vais changer ta punition ».\n[Je lui ai remis ce montant] […] On m’a remis dans ma cellule pendant deux\nsemaines. En dépit de la remise de la rançon, chaque soir, j’ai été battu par des\npoliciers »708."},{"id":"a-hrc-36-crp-1-p0398","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"398","seq":400,"section":"3. Droit à la liberté et la sécurité de la personne","text":"La pratique de versement de sommes d’argent contre libération existait au Burundi\nbien avant 2015. Cependant, les informations à la disposition de la Commission semblent\nindiquer que cette pratique se serait développée à partir d’avril 2015, dans un contexte où les\narrestations sont nombreuses et les conditions économiques de plus en plus difficiles.\nCertains agents de l’État, ainsi que des Imbonerakure, ont exploité la vulnérabilité et la peur\ndes détenus et de leurs familles pour exiger d’eux des sommes de plus en plus importantes,\nparfois à plusieurs reprises. Les personnes recevant cet argent sont diverses. Elles\ncomprennent de simples policiers, qui, dans certains cas, ont aidé à libérer des personnes ou à\ns’enfuir clandestinement709, ou des policiers ou agents du SNR de plus haut grade, dont\ncertains noms ont été cités de manière récurrente par les personnes interrogées par la\nCommission710. Des Imbonerakure, bien qu’ils ne soient pas habilités à détenir des personnes,\nont, dans certains cas, reçu de l’argent afin d’intervenir en vue de la libération d’une\npersonne711."},{"id":"a-hrc-36-crp-1-p0399","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"399","seq":401,"section":"3. Droit à la liberté et la sécurité de la personne","text":"D’autres personnes ont simplement été libérées sans aucune procédure judiciaire après\nde nombreux jours en détention, renforçant ainsi le caractère arbitraire de leur détention\ninitiale712."},{"id":"a-hrc-36-crp-1-p0400","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"400","seq":402,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"Se basant notamment sur les informations rassemblées par le Haut-Commissaire des\nNations Unies aux droits de l’homme et l’EINUB713, le Conseil des droits de l’homme a\ncondamné en 2015 et 2016, dans les résolutions 30/27, S/24/1 et 33/24, les cas de torture et\nles autres peines ou traitements cruels, inhumains ou dégradants au Burundi714. L’EINUB a\nconclu dans son rapport présenté au Conseil des droits de l’homme en septembre 2016 que\n« le recours à la torture ou à d'autres traitements cruels, inhumains ou dégradants contre les\nopposants au troisième mandat et des membres ciblés de l'opposition ou leurs proches pour\nextraire des informations ou comme punition a été une caractéristique de la crise »715. Le\nHaut-Commissaire aux droits de l’homme a de son côté relevé que les cas de torture au\nBurundi « sont pour la plupart le fait d’agents de la police et du Service de renseignement\nlors d’arrestations ou de détentions dans des postes de police et les locaux du Service »716. Ce\nconstat a été repris par le Comité contre la torture dans ses observations finales du 9\nseptembre 2016 dans lesquelles il a déploré « une augmentation récente des cas de torture liés\nà la crise politique »717.\n(a)     Droit applicable\n(i)     Droit international"},{"id":"a-hrc-36-crp-1-p0401","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"401","seq":403,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"La prohibition de la torture et des autres traitements cruels, inhumains et dégradants\nest une norme internationale absolue que les États ne sont pas censés ignorer et sont obligés\nde respecter et de protéger en toute circonstance718. Cette prohibition est prévue à l’article 7\nde la DUDH, l’article 7 du PIDCP, l’article 5 (b) de la CIEDR, l’article 37 (a) de la CDE, et\nsurtout par la CCT. En 2013, le Burundi a ratifié le Protocole facultatif à la CCT, mais n’a\npas à ce jour autorisé une visite du Sous-Comité de la prévention de la torture dans le pays.\nLe 16 juillet 2017, le Sous-Comité a annoncé qu’il comptait effectuer une visite au\nBurundi719 qui, avec 13 autres États, figure sur la liste des pays qui, dans l’année suivant\nl’entrée en vigueur du Protocole facultatif à la CCT, n’ont pas mis en place de mécanismes\nde prévention nationale contre la torture comme le requiert l’article 17 du même Protocole\nfacultatif."},{"id":"a-hrc-36-crp-1-p0402","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"402","seq":404,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"En vertu de l’article 1 (1) de la CCT, la torture est un acte défini par plusieurs\néléments : « la douleur ou les souffrances aiguës, physiques ou mentales » qu’elle provoque,\nl’intention de l’auteur d’infliger cette souffrance, et les objectifs recherchés, « notamment\nobtenir [de la victime] ou d'une tierce personne des renseignements ou des aveux, de la punir\nd'un acte qu'elle ou une tierce personne a commis ou est soupçonnée d'avoir commis, de\nl'intimider ou de faire pression sur elle ou d'intimider ou de faire pression sur une tierce\npersonne, ou pour tout autre motif fondé sur une forme de discrimination quelle qu'elle soit ».\nLa torture est un acte commis par un agent public « ou toute autre personne agissant à titre\nofficiel ou à son instigation ou avec son consentement exprès ou tacite ». Le Comité contre la\ntorture a précisé à ce sujet que « si les autorités de l’État ou toute autre personne agissant à\ntitre officiel ou au nom de la loi savent ou ont des motifs raisonnables de penser que des actes\nde torture ou des mauvais traitements sont infligés par des acteurs non étatiques ou du secteur\nprivé et n’exercent pas la diligence voulue pour prévenir de tels actes, mener une enquête ou\nengager une action contre leurs auteurs afin de les punir conformément à la Convention,\nl’État partie est tenu pour responsable et ses agents devraient être considérés comme les\nauteurs, les complices ou les responsables d’une quelconque autre manière [...] pour avoir\nconsenti, expressément ou tacitement, à la commission » de ces actes720."},{"id":"a-hrc-36-crp-1-p0403","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"403","seq":405,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"La CCT ne définit pas aussi clairement les traitements cruels, inhumains ou\ndégradants. L’article 16 (1) de la Convention spécifie qu’ils ne constituent pas des actes de\ntorture mais que, comme ces derniers, ils sont commis par « un agent de la fonction publique\nou toute autre personne agissant à titre officiel, ou à son instigation ou avec son consentement\nexprès ou tacite ». Le Comité contre la torture a de son côté précisé que « comparés aux actes\nde torture, les mauvais traitements peuvent différer par l’intensité de la douleur et des\nsouffrances infligées et le fait qu’il ne doit pas nécessairement être prouvé qu’ils servent des\nfins illicites »721. Le terme « dégradant » renvoie en outre à un aspect d’humiliation ou\nd’avilissement qui n’est pas nécessairement causé par une douleur ou une souffrance aiguë722."},{"id":"a-hrc-36-crp-1-p0404","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"404","seq":406,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"Les menaces de mort peuvent également constituer des actes de torture ou de mauvais\ntraitements si elles sont proférées dans le but d’infliger de graves souffrances physiques et\nmentales à la victime. De manière générale, les menaces de mort peuvent constituer des\nviolations des droits de l’homme lorsqu’elles sont proférées par des agents de l’État ou des\npersonnes agissant à leur demande ou avec leur accord723. La violation peut également être\nconstituée lorsque les autorités ont failli à prendre des mesures pour mettre fin à des menaces\nde mort ou n’ont pas poursuivi les auteurs de ces menaces724. De la même manière, les\nautorités doivent prendre les mesures nécessaires pour mettre fin à toute menace de mort\némanant d’agents non-étatiques. Une carence de leur part peut constituer une violation des\ndroits de l’homme725.\n(ii)      Droit régional"},{"id":"a-hrc-36-crp-1-p0405","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"405","seq":407,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"La prohibition de la torture et des traitements cruels, inhumains ou dégradants est\nprévue par l’article 5 de la CADHP et les articles 16 et 17 de la Charte africaine des droits et\ndu bien-être de l’enfant. La Commission africaine des droits de l’homme et des peuples a en\noutre adopté en 2008 des Lignes directrices et mesures d'interdiction et de prévention de la\ntorture et des peines ou traitements cruels, inhumains ou dégradants en Afrique. Ces lignes\ndirectrices rappellent notamment qu’« aucune circonstance exceptionnelle, comme l’état de\nguerre ou la menace de guerre, l’instabilité politique à l’intérieur du pays ou toute autre\nsituation d’urgence publique, ne peut être invoquée pour justifier la torture ou les peines ou\ntraitements cruels, inhumains ou dégradants ». De la même manière, « des notions telles que\nl’état de nécessité, l’urgence nationale, et l’ordre public ne peuvent être invoquées pour\njustifier la torture ou les peines ou traitements cruels, inhumains ou dégradants ». Par ailleurs,\n« l’ordre d’un supérieur ne peut jamais constituer une justification ou une excuse légale à des\ncas d’actes de torture ou de peines ou traitements cruels, inhumains ou dégradants »726.\n(iii)     Droit national"},{"id":"a-hrc-36-crp-1-p0406","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"406","seq":408,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"L’article 25 de la Constitution du Burundi dispose que « nul ne sera soumis à la\ntorture, ni à des peines ou traitements cruels, inhumains ou dégradants ». Le Code pénal\nburundais punit d’une servitude pénale de 10 à 15 ans la torture et les autres traitements\ncruels, inhumains ou dégradants commis par « un agent public ou toute autre personne\nagissant à titre officiel ou à son instigation ou avec son consentement exprès ou tacite »727.\nL’article 208 du Code pénal précise qu’« aucune circonstance exceptionnelle, quelle qu’elle\nsoit, qu’il s’agisse de l’état de guerre ou de menace de guerre, d’instabilité politique\nintérieure ou de tout autre état d’exception, ne peut être invoqué pour justifier la torture et\nautre peine ou traitements cruels ou inhumains ou dégradants. L’ordre d’un supérieur ou\nd’une autorité publique ne peut être invoqué pour justifier la torture »."},{"id":"a-hrc-36-crp-1-p0407","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"407","seq":409,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"Le Code pénal sanctionne également les « lésions corporelles volontaires » qui sont\npunies d’une servitude pénale de deux à huit mois728. L’infraction sera aggravée, l’auteur\npouvant alors encourir une peine de deux à 10 ans d’emprisonnement, lorsque « les coups ou\nles blessures ont causé une maladie ou une incapacité de travail permanente ; ou s’il en est\nrésulté la perte de l’usage absolu d’un organe ou une mutilation grave, ou s’ils ont été portés\ncontre une femme enceinte et dont l’auteur connaissait l’état »729. L’article 222 du Code\npénal prévoit par ailleurs que « celui qui, intentionnellement a mutilé le corps d’une\npersonne, un de ses membres ou un de ses organes ou rendu ce membre ou cet organe\nimpropre à sa fonction, ou a causé à une personne une incapacité de travail, une infirmité ou\nune maladie mentale permanentes, ou a défiguré une personne d’une façon grave et\npermanente, est puni d’une servitude pénale de dix ans à vingt ans ».\n(b)     Faits\n(i)     Tortures"},{"id":"a-hrc-36-crp-1-p0408","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"408","seq":410,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"Les pratiques de torture et de traitement cruel, inhumain ou dégradant existaient au\nBurundi bien avant la période couverte par le mandat de la Commission. En 2014, dans ses\nobservations finales sur le deuxième rapport périodique du Burundi, le Comité des droits de\nl’homme s’était déjà déclaré « préoccupé par les allégations faisant état d’un nombre élevé de\ncas de torture par les forces de police, de défense et de sécurité et des services de\nrenseignements », « par les allégations d’impunité à l’égard des responsables de cette\npratique », « par l’inexistence d’un mécanisme efficace chargé de recevoir et d’enquêter sur\nles allégations de torture par les forces de police et de défense ainsi que par les obstacles qui\nempêchent les victimes de porter plainte, notamment la crainte de représailles », et par\n« l’admission par les tribunaux d’aveux obtenus sous la torture »730. À partir d’avril 2015\nnéanmoins, les cas de torture et de mauvais traitements se sont multipliés et les méthodes\nutilisées, ainsi que les menaces les accompagnant, ont gagné en brutalité. La Commission a\nconstaté un recours quasi-systématique à la torture ou aux traitements cruels, inhumains et\ndégradants à l’encontre d’opposants présumés au Gouvernement ou au parti au pouvoir,\nparticulièrement par des membres du SNR et de la police731. La Commission a rassemblé\ndans le présent chapitre des informations sur des cas de torture et de traitements, cruels,\ninhumains ou dégradants principalement dans le contexte de la détention. Ces pratiques\nillicites ne se limitent toutefois pas à ce cadre732.\nPrincipales victimes"},{"id":"a-hrc-36-crp-1-p0409","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"409","seq":411,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"Les victimes de torture sont en majorité des jeunes hommes, parfois des mineurs, et,\ndans une moindre mesure, des hommes plus âgés et des femmes. Le profil de ces victimes\nprésente certaines similitudes. Il s’agit souvent de personnes soupçonnées d’avoir participé\naux manifestations contre un nouveau mandat du Président Nkurunziza, de résidents des\nquartiers de Bujumbura où ont eu lieu les manifestations d’avril à juin 2015 et plus tard des\ntensions avec les forces de l’ordre, de membres ou sympathisants présumés de partis\nd’opposition, en particulier des FNL et du MSD, des ex-FAB, de membres des corps de\ndéfense et de sécurité soupçonnés d’avoir participé au coup d’État manqué de mai 2015 ou de\nl’avoir soutenu, de membres ou collaborateurs présumés de groupes armés, particulièrement\nsuite aux attaques des camps militaires à Bujumbura et dans ses environs en décembre 2015\net du camp de Mukoni (province de Muyinga) en janvier 2017, et de personnes qui ont\ncherché à fuir le pays, soupçonnées de vouloir rejoindre des groupes armés d’opposition."},{"id":"a-hrc-36-crp-1-p0410","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"410","seq":412,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"De nombreuses victimes interrogées par la Commission ont expliqué que, pendant les\nséances de torture ou de mauvais traitements, les auteurs de ces actes cherchaient à leur faire\navouer leur participation aux actes évoqués plus haut ou leur appartenance présumée à des\ngroupes armés d’opposition, à révéler l’existence et la localisation de caches d’armes\nsupposées, à dénoncer des membres des groupes armés d’opposition ou à donner d’autres\ninformations liées au fonctionnement de ces groupes733. Certains détenus ont également été\ntorturés parce que les autorités les soupçonnaient, ou soupçonnaient des membres de leur\nfamille, d’avoir partagé des informations avec des médias ou des organisations\ninternationales734.\nAuteurs présumés"},{"id":"a-hrc-36-crp-1-p0411","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"411","seq":413,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"Les victimes de torture interrogées par la Commission ont cité le plus souvent, parmi\nles auteurs présumés de ces actes, des membres du SNR et de la PNB. Certaines ont\négalement cité des membres de la FDNB, notamment dans le cadre de la répression qui a\nsuivi la tentative de coup d’État de mai 2015 et les attaques d’installations militaires en\ndécembre 2015 et en janvier 2017. Plusieurs victimes ont dit avoir reconnu des responsables,\ny compris de haut rang, des corps de défense et de sécurité parmi les auteurs et les\ncommanditaires de torture, aussi bien au niveau national que provincial. Certains de ces\nresponsables auraient personnellement participé à la commission d’actes de torture ou de\nmauvais traitements735. Dans d’autres cas, ils auraient directement donné l’ordre à des\nsubalternes de torturer des détenus et ces actes de torture se seraient déroulés en leur\nprésence736."},{"id":"a-hrc-36-crp-1-p0412","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"412","seq":414,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"Si les agents de l’État ont été les principaux responsables d’actes de torture et de\ntraitements cruels, inhumains ou dégradants, de nombreux témoignages recueillis par la\nCommission ont révélé que des Imbonerakure sont intervenus comme auxiliaires de la PNB\net du SNR737, ainsi que de la FDNB738, notamment dans le cadre d’interpellations et\nd’arrestations et ont parfois livré des personnes arrêtées à des membres de ces corps qui les\nont ensuite torturées739. Des Imbonerakure ont également participé à des séances de torture\nou infligé des mauvais traitements en collaboration avec des agents étatiques ou en leur\nprésence740. Une victime de torture par des militaires en 2015, dont les cicatrices\nconsécutives aux sévices qu’elle avait subis étaient encore visibles, a rapporté:\n« Un militaire m'a donné des coups de pied [...] Il a appelé deux personnes en civil.\nL'une était un Imbonerakure appelé [X]. Les deux Imbonerakure et le militaire m'ont\nfrappé. Le militaire utilisait sa ceinture et les Imbonerakure avaient des bâtons. Ils\nm'ont frappé tous en même temps et m'ont donné des coups de pieds partout sur le\ncorps »741.\nTypes et méthodes de torture"},{"id":"a-hrc-36-crp-1-p0413","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"413","seq":415,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"Les victimes interrogées par la Commission ont déclaré avoir été torturées pendant\nplusieurs heures ou plusieurs jours, surtout au début de leur détention. Certaines ont été\ntorturées dans plusieurs lieux et par des agents d’institutions différentes, par exemple par des\nmembres de la police ou de l’armée, puis du SNR742."},{"id":"a-hrc-36-crp-1-p0414","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"414","seq":416,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"Les méthodes de torture les plus récurrentes que la Commission a relevées ont\nconsisté à :\n• battre la victime sur différentes parties du corps ou dans certains cas sur tout le corps\navec des fils électriques743, des bâtons744, des crosses d’arme à feu745, des\nmatraques746, des ceintures747, des tiges de fer à béton748, des planches de bois\nparsemées de clous749 ou d’autres objets, ayant pour effet, dans certains cas, de lui\ncasser les os ou de lui faire perdre connaissance ;\n• donner des coups de pied750 ou marcher sur la victime751 ;\n• gifler ou frapper la victime au niveau des oreilles752 ;\n• ligoter la victime les mains dans le dos, lier ses mains et ses pieds avec des cordes ou\ndes lacets de bottes militaires avant de la frapper ou de lui marcher dessus753 ;\n• verser de l’eau froide sur la victime754 ;\n• forcer la victime à s’asseoir ou à s’agenouiller sur des capsules de bouteilles ou des\npierres aiguisées755 ;\n• utiliser des pinces sur différentes parties du corps de la victime, y compris pour lui\narracher les ongles756 ;\n• frapper la victime avec des objets tranchants tels que des baïonnettes, des machettes\nou des couteaux757 ;\n• poser un fer à repasser chaud sur la victime758 ;\n• arracher des dents à la victime759 ;\n• verser un liquide, dans certains cas brûlant, sur la victime ou le lui faire boire760 ;\n• enfoncer de longues aiguilles dans le corps de la victime761 ;\n• lacérer la victime de coups de couteau chaud, de machette ou de baïonnette762."},{"id":"a-hrc-36-crp-1-p0415","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"415","seq":417,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"À titre d’exemple, en 2016, un mineur au moment des faits a été arrêté par des\npoliciers accompagnés d’Imbonerakure et d’un Officier du SNR à Bujumbura. Il a confié à la\nCommission avoir subi des tortures au siège du SNR où il a été détenu pendant trois mois :\n« Un policier m’a attaché à [un arbre] avec la corde qui avait servi à me ligoter les\nmains et les pieds. Moi j’étais à l’horizontale […] [Des policiers et des\nImbonerakure] ont amené des matraques et des fers à béton et ont commencé à me\nfrapper. Entre 13h et 17h, ils ont commencé à me battre pour voir si j’allais donner\nles noms d’autres manifestants. Ils m’ont frappé très fort [...] J’ai crié de douleur et\nles policiers ont coupé un morceau de mon t-shirt et m’ont bandé la bouche »763."},{"id":"a-hrc-36-crp-1-p0416","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"416","seq":418,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"D’autres victimes, surtout des hommes, ont témoigné avoir subi des tortures à\ncaractère sexuel qui ont notamment consisté à des scènes de nudité forcée ou à suspendre des\nbouteilles ou des bidons lourds remplis d’eau, de sable ou de terre à leurs organes génitaux764.\nEn 2015, des policiers ont arrêté un jeune homme à Bujumbura, l’accusant de connaître\nl’existence de cache d’armes. Il a été détenu au Bureau spécial de recherche (BSR), où des\npoliciers l’ont frappé avec des barres de fer. Quelques jours plus tard, deux hommes l’ont\nemmené dans une autre province, où il a été détenu et torturé dans un container :\n« Le container était subdivisé en deux parties. Une partie plus petite faisait 2m x 1.5m\nlà où les prisonniers étaient. Dans l’autre partie, plus grande, des gens subissaient\ndes séances de torture […] Dans la salle d’emprisonnement, il y avait des anneaux en\nfer à béton soudés sur le toit du container auxquels on nous a attachés avec deux\nchaines en fer […] On a amené des bouteilles de 1.5 litre remplies d’eau et attaché\nces bouteilles à nos testicules […] Nous avons subi ce genre de torture quatre jours\nde suite et pendant la journée, on ne nous détachait pas. De temps en temps, on\nrallongeait la longueur de la chaîne pour nous rapprocher du sol et on amenait une\nchaise pour que nous puissions reposer nos pieds, mais nous restions toujours dans la\nmême position, avec les bras et le corps en T. Après […] mes testicules étaient\ntellement gonflés que je ne pouvais pas marcher. J’ai demandé l’autorisation d’aller à\nl’hôpital. Ils m’ont répondu que les séances de torture qui m’attendaient seraient plus\ndouloureuses que les précédentes »765."},{"id":"a-hrc-36-crp-1-p0417","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"417","seq":419,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"Des témoignages recueillis par la Commission indiquent en outre que des agents du\nSNR ou de la police, parfois secondés par des Imbonerakure, ont forcé des victimes à\nmanger, à s’enduire ou à s’allonger dans de « grands besoins » (matières fécales humaines)\net/ou à boire « des petits besoins » (urines)766."},{"id":"a-hrc-36-crp-1-p0418","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"418","seq":420,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"En janvier 2017, plusieurs militaires et civils arrêtés en lien avec l’attaque du camp de\nMukoni ont été torturés par des agents du SNR dans la province de Muyinga afin d’obtenir\ndes informations sur l’attaque et l’identité des assaillants présumés. Certains d’entre eux ont\négalement été frappés par des Imbonerakure, supervisés par des agents provinciaux du SNR\nde Muyinga. Certaines victimes ont été frappées sur tout le corps avec de longues barres de\nfer à béton ou des bâtons. D’autres ont subi des sévices visant à porter atteinte à leur dignité,\ncomme être forcées de manger de la matière fécale. Un agent provincial haut placé du SNR a\nordonné, supervisé et participé à ces actes de torture767.\nMenaces de mort dans le cadre de la détention"},{"id":"a-hrc-36-crp-1-p0419","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"419","seq":421,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"Dans le but d’obtenir des aveux ou des informations pendant les séances de torture,\nplusieurs victimes ont été menacées de mort. Des agents du SNR et de la police ont\nnotamment menacé de les faire exploser à l’aide de grenades, de leur amputer une partie du\ncorps, ou de les tuer à l’aide d’armes à feu768. Un homme arrêté par un policier à Bujumbura\nen 2016 a raconté à la Commission :\n« [Le policier] a donné l’ordre à ses gardes du corps de me frapper. Ils m’ont frappé\npartout sur le corps. Ils m’ont menacé et ils m’ont ligoté les bras dans le dos. Puis ils\nm’ont embarqué dans ma camionnette […] [Le policier] disait […]: « Vois si tu vas\néchapper ! » Il ordonnait à ses gardes du corps : « Frappez ! Tuez cet imbécile ! »\nTous m’ont frappé […] avec [des bâtons] et les crosses de fusil […] [Le policier] a\npris une baïonnette et a dit : « Si tu ne révèles pas les armes que tu caches et l’endroit\noù tu fais la formation pour les jeunes, on va te tuer immédiatement » […] On m’a\ndéshabillé. J’étais nu. J’étais toujours ligoté avec une corde sur les bras »769.\nUn membre d’un parti d’opposition a été arrêté et menacé de mort par un agent\nprovincial haut placé du SNR en 2015. Cet agent, accompagné de policiers, l’a\nemmené dans une voiture avec d’autres détenus dans un endroit qu’il n’a pas pu\nidentifier, près d’une rivière, dans une autre province. Il a témoigné à la Commission :\n« [L’agent provincial du SNR] a dit : « On va vous tuer et jeter vos cadavres dans la\nrivière » […] Ils nous ont forcé à nous allonger à plat ventre […] Ils essayaient de\nnous faire avouer qu’on collaborait avec les rebelles […] [L’agent provincial du\nSNR] disait : « Où se trouvent les fusils ? […] Où sont-ils ? Vous acceptez ou vous\nmourrez. »\nLes détenus ont ensuite été emmenés au siège du SNR à Bujumbura, où des jeunes en\ncivil, que le témoin a décrit comme : « ni des policiers, ni des militaires », les ont\nfrappés avec des barres de fer et leur ont donné des coups de pied. Plus tard : « Les\nagents du SNR […][m’ont] accusé d’être [un] rebelle […] Derrière moi, un autre\n[agent] interrogeait un autre détenu. […] Il avait reçu une balle dans la jambe et il\nsaignait. Les agents le frappaient comme un serpent pendant qu’il saignait. […][\nL’agent] qui m’interrogeait m’a dit : « Tu vois, tu n’as pas assez de force pour\nrésister à ça. Tu vas mourir si tu n’acceptes pas ce que tu connais »770."},{"id":"a-hrc-36-crp-1-p0420","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"420","seq":422,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"Pour accentuer la pression, les auteurs ont parfois menacé les victimes qui ne\nvoulaient ou ne pouvaient pas livrer d’informations de s’attaquer aux membres de leur\nfamille771. Un mineur torturé au siège du SNR à Bujumbura a rapporté :\n« Trois policiers en tenue civile sont venus me chercher et ils m’ont amené dans une\nsalle. Ils m’ont demandé si j’avais une mère. J’ai répondu : « Oui ». Ils ont demandé\nsi j’aimais ma mère. J’ai dit : « Oui, beaucoup » et ils m’ont demandé si j’avais [des\nfrères et sœurs]. J’ai dit [oui] et ils m’ont demandé si je [les aimais]. J’ai répondu :\n« Oui ». Alors, les policiers m’ont dit de donner les noms des insurgés du quartier et\nles endroits où ils ont gardé leurs armes […] L’un d’eux m’a dit qu’ils allaient\nchercher ma mère et [mes frères et sœurs] pour les tuer devant moi ; alors ils verront\nsi je n’allais pas dire où étaient les armes »772."},{"id":"a-hrc-36-crp-1-p0421","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"421","seq":423,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"La Commission s’est entretenue avec des personnes qui non seulement ont été\ntorturées mais ont été forcées à assister à des exécutions de détenus, convaincues qu'elles\nallaient être les prochaines victimes. Ainsi, un homme arrêté par des policiers à Bujumbura\nen 2016 a d’abord été torturé et menacé de mort par des policiers qui l’accusaient de\ncollaborer avec des militaires impliqués dans la tentative de coup d’État, puis a été obligé\nd’assister à l’exécution de plusieurs autres détenus :\n« Les policiers m’ont dit : « Ce que nous t’avons dit, tu acceptes ou tu n’acceptes pas\n? Sinon, tu vas mourir. Dis-nous […] avec qui tu collabores ». J’ai répondu que je ne\nme reproche rien […] Ils ont dit : « Dis-nous simplement où tu gardes les armes »\n[…] Les autres détenus criaient […] leur innocence […] J’ai vu les policiers en train\nde les exécuter à coups de couteau. Je l’ai vu de mes propres yeux. Ils ont utilisé des\ncouteaux et des machettes. Ils sont morts sur le champ. […] Je regardais tout ça.\nC’était une manière de me torturer. […] J’ai dit [aux policiers] : « Ne me tuez pas\ncomme ça. Tuez-moi à coups de balles ». Ils ont dit : « Tu vas voir comment on va te\ntuer. » […] [Un policier] a pris une barre de fer et m’a dit : « Dis le dernier mot et on\nva te tuer » 773."},{"id":"a-hrc-36-crp-1-p0422","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"422","seq":424,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"D’autres détenus ont été placés à côté de cadavres, parfois décapités, pour les\nconvaincre qu’ils allaient subir le même sort s’ils ne faisaient pas les aveux attendus ou ne\nfournissaient pas les informations demandées774. Un homme détenu au SNR à Bujumbura en\n2016 a raconté :\n« [Un policier de l’API et un agent du SNR] m’ont sévèrement battu à l’aide de\ncrosses de fusil et de barres de fer […] Dans la cellule du SNR, j’étais en compagnie\nde 22 autres détenus [...] Vers 18 heures, j’ai été conduit seul dans une autre salle où\nil y avait déjà deux cadavres. [Un responsable du SNR] s’est alors adressé à moi en\ndisant : « Tu vas recevoir le même sort que ces Tutsis »775.\nInsultes à caractère ethnique"},{"id":"a-hrc-36-crp-1-p0423","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"423","seq":425,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"Plusieurs témoignages ont révélé que, dans certains cas, l’origine ethnique de la\nvictime a été un facteur aggravant et que certains auteurs d’actes de torture ont insulté les\nvictimes en raison de leur ethnie. Un homme torturé par des policiers et des agents du SNR\nen 2015 a répété à la Commission les insultes qui ont été proférées contre lui :\n« On me torturait dans une autre pièce, pas devant les autres détenus. On me disait\ndes injures : « Vous, les Tutsis […] vous allez tous finir sur la corde à linge, on va\nvous laver et repasser, et vous accrocher sur la corde à linge. Vous êtes des cafards,\nvous vous pensez plus malins, vous allez finir comme les Tutsis du Rwanda, vous\nn’avez aucun secours » »776.\nUn jeune homme arrêté par des policiers à Bujumbura en 2016 et torturé par des\nagents du SNR a témoigné : « On nous a dit de nous mettre en position de pompe. Ils\nont amené des matraques et ils ont commencé à nous battre dans cette position. Ils\nnous disaient que le nombre de coups allait être doublé pour celui qui criait […] [Un\nagent de police] est venu et m’a insulté disant : « C’est un petit chien tutsi ». Les\nautres policiers ont ri […] On nous a dit de nous asseoir par terre, les jambes étirées\net on a commencé à nous donner des coups de matraques sur la plante des pieds […]\n[Un agent de police] est venu et a dit aux autres policiers qu’ils ne savaient pas\nfrapper et [qu’il] allait leur montrer comment faire. [Il] a commencé à me frapper\navec une matraque sur la plante des pieds. Moi je lui disais : « Pardon […] ! Pardon\n[…] !» [L’agent de police] m’a demandé si je pensais [qu’il] pouvait [avoir un\nenfant] Tutsi comme moi, et je me suis tu »777.\nUn autre homme détenu au siège du SNR en 2015 a décrit à la Commission les actes\nde tortures qu’il a subis, accompagnés d’insultes à caractère ethnique : « Sans poser\nde questions, les policiers m'ont giflé. Je suis tombé par terre. Il y avait environ 12\npoliciers […] Ils m'ont mis dans le pick-up. Ils m'ont forcé à m'allonger par terre dans\nla voiture, en dessous du siège, et m'ont piétiné. Ils m'ont dit : « Tu fais semblant\nd'avoir une taille élancée mais tu dois te mettre là. On doit te réduire en taille. » L'un\nd'eux a mis le canon de son fusil sous mon nez et m'a dit : « Tu sens? Tu sens la\npoudre ? » Ils m’ont dit : « […] Vous, fils de bâtards, imbéciles, fils de Tutsis ! » Les\ninsultes ont continué au siège SNR où il a été torturé : « Ils ont demandé : \"Tu viens\nd'où ?\" J'ai dit : « De Bujumbura » […] Ils ont dit : « On veut connaitre tes origines.\nD'où viennent tes parents et tes grands-parents ? » […] Puis un officier est entré […]\nIl a sauté en l'air et a atterri sur mon ventre. Il a dit : « [Vous] croyez que vous allez\néchapper, vous les [Tutsis] ! »778."},{"id":"a-hrc-36-crp-1-p0424","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"424","seq":426,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"La Commission a recueilli d’autres témoignages décrivant des insultes d’agents de\npolice et du SNR à l’encontre de détenus d’origine tutsie, les appelant par exemple : « sales\nTutsis »779, « Inkende » (singes)780, « Imbwa zaba Tutsi » (chiens Tutsis)781 ou « insurgés\nTutsis »782.\nLieux de torture"},{"id":"a-hrc-36-crp-1-p0425","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"425","seq":427,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"Deux lieux de torture dans la ville de Bujumbura ont été mentionnés par de\nnombreuses victimes de torture. Le premier est le siège du SNR situé dans le quartier de\nRohero, près de la cathédrale Regina Mundi783. Avant d’y arriver, les victimes arrêtées à\nBujumbura ont souvent d’abord transité par des cachots de la police au niveau des quartiers,\nalors que celles appréhendées en province sont quant à elles souvent passées par le bureau\nprovincial du SNR ou des cachots de police au niveau communal ou provincial."},{"id":"a-hrc-36-crp-1-p0426","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"426","seq":428,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"Des témoins ont décrit le siège du SNR à Bujumbura comme un véritable centre de\ntorture où les détenus étaient torturés dans plusieurs endroits, y compris dans des cellules\nsecrètes situées par exemple au sous-sol et dans des bâtiments inachevés784. Un témoin a\nindiqué à la Commission que des séances de torture avaient lieu chaque jour au SNR en\n2015785. La Commission a également recueilli des témoignages de tortures plus récents.\nAinsi, un membre d’un parti d’opposition torturé en 2016 a été détenu dans un cachot isolé\npendant 21 jours afin de le forcer à divulguer les noms de participants aux manifestations. Il a\nraconté :\n« Même les membres de ma famille n’ont pas pu me voir, ni les observateurs de\nl’Union africaine, car ils [les agents du SNR] me cachaient. Ils m’ont caché plus de\nsept fois. Au SNR, il y a des garages où sont stationnées les voitures. Ils me mettaient\ndans une voiture, à l’arrière où il y a une caisse. On ne peut y mettre qu’une seule\npersonne et on peut la fermer à clef »786.\nUn homme arrêté en 2015 par un responsable local du SNR à Bujumbura a été\nemmené au siège du SNR dans une camionnette : « J’ai entendu le chauffeur\ndemander à [l’Officier du SNR] : « On l’amène où ? À Kamenge ? » [L’Officier] a dit\nde me conduire au SNR qui se trouve un peu en haut de la Cathédrale. Dans la\ncamionnette il y avait six policiers en uniforme, [plus] le chauffeur et [l’Officier…] Il\ny avait un chantier au SNR, et quand on m’interrogeait, j’étais dans ce bâtiment\ninachevé […] Quand on rentre au SNR, il y a différents locaux où on torture les gens.\nLa personne qui te reçoit te torture déjà à la réception. J’ai été frappé par [un\npolicier] au niveau de la cheville, sur les fesses et le cou arrière avec des planches de\nbois qui ont des clous »787."},{"id":"a-hrc-36-crp-1-p0427","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"427","seq":429,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"Le deuxième lieu de torture souvent évoqué par les victimes est le siège de la BAE\nsitué au lieu-dit « Chez Ndadaye », près de la place de l’Indépendance à Bujumbura. La\npolice semble avoir utilisé ce lieu surtout en 2015 et début 2016 pour détenir et torturer des\npersonnes ayant participé aux manifestations788. Un témoin qui travaillait non loin de ce lieu\na affirmé avoir entendu des cris plusieurs fois en 2015 et avoir vu des camionnettes avec des\npersonnes ligotées à bord y entrer en fin de journée789. Une victime de torture en janvier 2016\na confié à la Commission :\n« Au moment même de mon arrestation, [les policiers] m’ont frappé à coups de crosse\nde fusil. Je me suis évanoui et me suis retrouvé dans le camp communément appelé\n« Chez Ndadaye ». Il y avait là aussi d’autres jeunes. Le commissaire [de police] nous\na posé trois fois la même question : « Êtes-vous des rebelles ? » Nous avons répondu\npar la négative. À ce moment, le commissaire nous a frappés au niveau du cou, du\nbassin et de la partie postérieure de la cheville. J’ai été plus sévèrement battu que les\nautres [...] [Le commissaire] a insisté pour poser la même question sur\nl’appartenance à la rébellion à l’un d’entre nous […] qui avait une vingtaine\nd’années. Puis, il a tiré son pistolet et a exécuté le jeune homme d’une balle dans la\ntête »790."},{"id":"a-hrc-36-crp-1-p0428","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"428","seq":430,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"Des actes de torture ont eu lieu dans d’autres centres de détention officiels de la police\nà Bujumbura, y compris la BSR791 et le poste de police de Musaga792. D’autres détenus ont\nété torturés par des militaires, notamment au Camp Muha793. Des personnes détenues par le\nSNR ont été torturées non seulement à son siège, mais dans d’autres locaux, notamment à\nKamenge794, ainsi que dans des bureaux provinciaux du SNR, par exemple à Kayanza795 et\nMuyinga796. D’autres ont été torturées dans des lieux de détention de la police dans plusieurs\nprovinces, dont celles de Rumonge et de Cibitoke797."},{"id":"a-hrc-36-crp-1-p0429","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"429","seq":431,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"Des détenus ont également été torturés dans des lieux de détention non officiels798.\nLes lieux les plus couramment cités par les victimes sont des containers, notamment à\nKamenge799 ; des maisons privées, parfois abandonnées ou inachevées, à Bujumbura800, que\nles victimes n’ont pas toujours pu localiser précisément parce qu’elles y ont été acheminées\nles yeux bandés ou la tête cagoulée801; le bar qui appartenait au Général Adolphe\nNshimirimana, ancien Administrateur général du SNR, nommé « Iwabo w’abantu », à la\nsortie de Bujumbura802 ; et une maison dans la province de Kayanza803. Certaines personnes\nont également été torturées dans la brousse ou dans des forêts804.\n(ii)     Traitements cruels, inhumains ou dégradants"},{"id":"a-hrc-36-crp-1-p0430","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"430","seq":432,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"Outre ces cas de torture, la Commission a documenté de nombreux cas de traitements\ncruels, inhumains ou dégradants. Ces traitements ont parfois été infligés par des agents de la\npolice, du SNR et de l’armée, agissant dans certains cas avec des Imbonerakure. Ils ont\négalement revêtu un caractère plus général comme les mauvaises conditions de détention au\nsujet desquelles la Commission a recueilli plusieurs témoignages et que la CNIDH a relevé à\nplusieurs reprises dans ces rapports805.\nConditions de détention cruelles, inhumaines ou dégradantes"},{"id":"a-hrc-36-crp-1-p0431","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"431","seq":433,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"De nombreuses victimes interrogées par la Commission ont été détenues dans des\nconditions constitutives de traitements cruels, inhumains ou dégradants, par exemple dans\ndes toilettes806, des isoloirs807 ou des chambres sans fenêtre et dans l’obscurité808. Les\nvictimes étaient parfois dénudées809. Des témoins ont signalé la présence de nombreux\ndétenus dans des cellules étroites et des cachots surpeuplés, sans séparation entre adultes et\nmineurs, par exemple au SNR à Bujumbura810. Une victime de torture, détenue pendant plus\nd’un mois dans un container dans une province en 2015, a témoigné :\n« Au total, nous étions à 31 personnes dans une petite cellule du container. Nous\nsommes restés nus pendant toute la durée de la détention là-bas »811.\nUn membre d’un parti d’opposition torturé au SNR en 2015 a décrit ses conditions de\ndétention: « Mon cachot faisait quatre mètres carrés. Nous étions une quarantaine de\nprisonniers : 20 debout, 20 couchés. On dormait à tour de rôle. Tous les prisonniers\nétaient mélangés. On [les détenus] prenaient soin des détenus gravement torturés.\nJ’étais considéré par les autres détenus comme un de ceux-là, donc les autres détenus\nme laissaient dormir […] Les 40 hommes faisaient leurs besoins dans la même cellule\n[…] Il y avait des mineurs avec nous. J’ai perdu 12 kilos pendant ma détention au\nSNR »812."},{"id":"a-hrc-36-crp-1-p0432","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"432","seq":434,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"Des détenus ont parfois été privés d’une alimentation suffisante ou d’eau potable813,\ncomme l’a rapporté un jeune homme détenu en 2015 dans un container à Bujumbura, avec 15\npersonnes :\n« Quand je suis arrivé dans ce container [...] je n’ai rien reçu à boire et à manger\npendant les trois jours que j’ai passés là-bas. Les conditions étaient tellement\nmauvaises qu’un jour, un détenu a uriné dans la bouche d’un autre pour le réhydrater\n[…] Pendant la journée, il faisait très chaud dans le container et, la nuit, il faisait très\nfroid »814."},{"id":"a-hrc-36-crp-1-p0433","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"433","seq":435,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"D’autres détenus se sont vus refuser l’accès à toute hygiène corporelle ou à des lieux\nd’aisance815. Un homme détenu en 2016 au cachot d’une brigade provinciale de police a\ndéclaré :\n« La nuit, les Imbonerakure [dans le cachot] allaient chercher de l’eau. Il y avait une\npartie du cachot qu’on appelait « mondis », où on faisait les grands et les petits\nbesoins. Si tu étais nouveau ou bien un opposant, on te mettait là. Ils jetaient de l’eau\npar terre et ils nous forçaient à nous allonger sur le ciment mouillé. J’ai dû dormir là\ncette nuit-là. « Mondis » était comme un endroit où on allait pour être puni »816.\nUn homme détenu dans un poste provincial de police en 2016 a déclaré : « Là, la\nsituation était très difficile. Il n’y avait aucune communication avec l’extérieur. Je\nn’ai pas été autorisé à aller aux toilettes. Je me soulageais dans ma cellule en\nutilisant un récipient qui m’avait été donné à cet effet. Un jour, un policier m’a amené\nun repas préparé par ma famille. Les policiers l’ont versé par terre pour voir si on ne\nm’avait pas fait passer un message à travers la nourriture »817."},{"id":"a-hrc-36-crp-1-p0434","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"434","seq":436,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"Malgré les tortures et mauvais traitements qui ont souvent causé de graves blessures et\nautres problèmes de santé, de nombreuses victimes ont été privées d’accès aux soins\nmédicaux adéquats818. Un jeune homme, mineur au moment des faits, qui avait été blessé\nsuite à des sévices, a passé 12 jours au SNR en 2016 sans recevoir de soins819. Un homme\narrêté à Bujumbura en 2015 et torturé au SNR a rapporté :\n« Au SNR il n’y avait pas de traitement médical, même si on était malade ou blessé.\nIls vous laissent comme ça. Même si on meurt, ça ne fait rien pour eux […] On m’a\ncassé le nez […] Ils utilisaient des câbles pour frapper les détenus. Certains de ces\ncâbles étaient branchés avec de l’électricité mais pas tous. Moi, ils ne m’ont pas\nfrappé avec des câbles mais avec des fers, comme des fers à repasser. Le fer était\nbranché. Ils augmentaient la température jusqu’à ce que ce soit très chaud, puis ils\nmettaient le fer sur moi, sur mon dos et sur mon cou »820."},{"id":"a-hrc-36-crp-1-p0435","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"435","seq":437,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"Dans les quelques cas où les victimes ont pu voir un médecin en détention, les soins\nqu’elles ont reçus étaient insuffisants ou inadéquats. Une victime de torture en 2016 au siège\ndu SNR à Bujumbura a confié à la Commission avoir été frappée avec un fer à béton,\ncouchée sur le ventre, et avoir reçu une injection dans le testicule droit qui a occasionné une\ndouleur générale avant son évanouissement. À son réveil dans la cellule, elle a remarqué que\nson sexe était enflé :\n« Le médecin m’a vu et je lui ai montré là où j’avais le plus mal et il m’a donné du\nparacétamol. Je lui ai demandé pourquoi il me donnait seulement cela […] Il m’a dit\nde prendre cela, que ça allait m’aider »821."},{"id":"a-hrc-36-crp-1-p0436","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"436","seq":438,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"Conscients des mauvais traitements infligés aux détenus, les agents du SNR à\nBujumbura ont cherché à soustraire certaines victimes de torture au contrôle des organes\ninternationaux qui surveillent les conditions de détention et le respect des droits des détenus,\nnotamment le Bureau du Haut-Commissaire des Nations Unies aux droits de l’homme au\nBurundi et les observateurs des droits de l’homme de l’Union africaine822. Une victime de\ntorture, détenue au SNR à Bujumbura en 2015, a déclaré à la Commission :\n« Il y a un endroit au SNR où l’on cache les personnes gravement torturées. Il y a des\ncachots cachés dans le SNR. On peut entendre des cris mais on ne peut pas localiser\nl’endroit spécifiquement »823."},{"id":"a-hrc-36-crp-1-p0437","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"437","seq":439,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"Des agents du SNR ont fait pression sur certains détenus pour ne pas s’entretenir avec\nces observateurs ou ont cherché à surveiller ou contrôler leurs entretiens824. Ainsi, un homme\narrêté par un haut responsable du SNR en 2015 à Bujumbura et détenu au siège du SNR, a\ntémoigné :\n« Deux jours après mon interrogatoire, les gens des droits de l’homme sont venus […]\net on nous a mis en garde de ne pas dire n’importe quoi pendant leur visite […]\nPendant les interviews avec les gens des droits de l’homme, les agents du SNR étaient\nà côté et nous n’étions pas libres de dire ce que nous voulions. Les gens dont les yeux\navaient été crevés ou qui étaient devenus des handicapés à cause de la torture ont été\nmis dans une salle où on les a cachés »825.\n(iii)     Conséquences des tortures et des traitements cruels, inhumains ou dégradants sur les\nvictimes"},{"id":"a-hrc-36-crp-1-p0438","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"438","seq":440,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"De nombreuses victimes de torture et/ou de mauvais traitements rencontrées par la\nCommission présentaient des séquelles graves tant physiques (multiples cicatrices, infirmité\npartielle) que psychologiques826. Certaines victimes avaient des fractures, avaient perdu des\ndents, souffraient de paralysies partielles, de douleurs diverses, dont certaines à long terme, et\nd’infections urinaires ou génitales."},{"id":"a-hrc-36-crp-1-p0439","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"439","seq":441,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"Des victimes de torture à caractère sexuel, auxquelles, dans certains cas, on avait\ninjecté des produits inconnus pendant leur détention, se sont plaintes de l’atrophie de leurs\ntesticules ou de difficultés érectiles longtemps après les faits827. Un homme torturé au SNR\nen 2015 a confié à la Commission :\n« On m’a frappé tellement de fois aux parties génitales. On me disait de m’incliner,\nles bras au niveau des genoux, et on me donnait des coups de pied sur les parties\ngénitales. À cause des coups infligés, depuis je ne peux plus avoir de relations\nsexuelles. Je n’ai plus d’érection. Je suis comme devenu impuissant »828."},{"id":"a-hrc-36-crp-1-p0440","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"440","seq":442,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"De nombreuses victimes de tortures ont signalé à la Commission avoir besoin d’un\nsoutien psychologique et médical. Un cas particulièrement marquant est celui d’un homme\nqui, après avoir reçu une balle dans la jambe pendant les événements du 11 décembre 2015, a\nensuite été arrêté et torturé au SNR à Bujumbura, où des agents lui ont coupé deux doigts\nparce qu’il refusait d’admettre qu’il était dans un groupe rebelle. Il a également assisté,\nmalgré lui, à des sévices violents infligés à d’autres détenus. Depuis, il souffre de troubles\npsychiatriques graves829. Une autre victime de torture arrêtée suite aux événements 11\ndécembre 2015 et ayant frôlé la mort de très près, est elle aussi dans un état psychologique\nprécaire depuis qu’elle a assisté à des exécutions sommaires dans un camp militaire à\nBujumbura830."},{"id":"a-hrc-36-crp-1-p0441","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"441","seq":443,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"La Commission a également documenté plusieurs décès de victimes de torture dans\nles cachots du SNR à Bujumbura et dans d’autres lieux de détention831. Un jeune homme lui-\nmême victime de torture au SNR en 2015 a raconté :\n« Dans le cachot, il y avait quatre autres personnes, tous des hommes adultes. Après\nune heure, il y en a un qui est mort. Le sang est sorti de son nez et de sa bouche. Je\nn’ai pas vu quand il avait été torturé »832.\nUn autre homme arrêté et torturé par des agents de police en 2016 a déclaré à la\nCommission : « Ils m’ont pris par force et m’ont mis dans le véhicule […] Il y avait\nun autre jeune homme dans le véhicule. On lui avait ligoté les bras et les jambes. Il\nétait très sale et dans un mauvais état. […] Ils nous ont dit de sortir de la voiture et\nde nous mettre debout. Je suis sorti mais le jeune homme ne pouvait pas sortir car il\navait un problème au niveau de sa colonne vertébrale. […] [Plus tard] il est mort\ndans la voiture. Ils l’avaient frappé sur la tête. Je voyais quelque chose de blanc qui\nsortait de son nez »833.\nLa Commission a également documenté le décès d’une victime de torture dans un\ncachot de la police dans la province de Muramvya, qui, en juin 2017, a succombé à\ndes coups qui lui ont été infligés par trois Imbonerakure accompagnés d’un\nresponsable du CNDD-FDD de la province834.\nConséquences pour les familles des victimes"},{"id":"a-hrc-36-crp-1-p0442","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"442","seq":444,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"Les familles de victimes de torture n’ont pas été épargnées pendant la détention ni\naprès la libération de leurs proches. Certaines ont été harcelées et menacées par des policiers,\ndes agents du SNR ou des Imbonerakure835."},{"id":"a-hrc-36-crp-1-p0443","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"443","seq":445,"section":"4. Tortures et autres traitements cruels, inhumains ou dégradants","text":"Les membres de la famille des victimes vivent souvent dans l’angoisse, la peur et le\ndésarroi jusqu’à ce qu’ils retrouvent leurs parents et que ceux-ci soient libérés. Plusieurs\nvictimes de torture ont dit que des membres de leur famille proche ont pleuré quand ils ont vu\nl’état pitoyable dans lequel ils étaient au moment de leur libération836."},{"id":"a-hrc-36-crp-1-p0444","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"444","seq":446,"section":"5. Violences sexuelles","text":"En 2016, le Haut-Commissaire des Nations Unies aux droits de l’homme et l’EINUB,\ndans leurs rapports respectifs au Conseil des droits de l’homme, ont fait état de violences\nsexuelles commises au Burundi depuis avril 2015837. Sur cette base, dans sa résolution 33/24\nadoptée le 30 septembre 2016, le Conseil des droits de l’homme a condamné les « violences\nsexuelles et sexistes » au Burundi838."},{"id":"a-hrc-36-crp-1-p0445","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"445","seq":447,"section":"5. Violences sexuelles","text":"En novembre 2016, dans ses observations finales sur les cinquième et sixième\nrapports périodiques du Burundi, le Comité pour l'élimination de la discrimination à l'égard\ndes femmes a constaté « avec une vive consternation que les violences à l’égard des femmes\nse sont exacerbées dans l’État partie depuis le déclenchement en avril 2015 du conflit interne\nqui y règne »839. Le Comité a déploré que le Gouvernement du Burundi « n’a pris aucune\ninitiative manifeste pour rassembler des informations sur les cas de violence sexuelle\nsurvenus pendant le conflit, que l’impunité est généralisée par manque d’enquêtes, de\npoursuites et de sanctions à l’encontre des auteurs de violences à l’égard des femmes\ncommises dans le cadre du conflit et que les victimes n’ont pas accès à la justice ni aux\nréparations »840. En septembre 2016, le Comité contre la torture s’est également déclaré\n« alarmé par les allégations nombreuses et concordantes d’actes de violences sexuelles contre\ndes femmes utilisés comme arme d’intimidation et de répression durant des manifestations\nainsi que dans le cadre des fouilles et perquisitions menées par la police, les militaires et les\nImbonerakure dans les quartiers dits contestataires de Bujumbura »841.\n(a)     Droit applicable\n(i)     Droit international"},{"id":"a-hrc-36-crp-1-p0446","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"446","seq":448,"section":"5. Violences sexuelles","text":"Les violences sexuelles, à savoir les actes de nature sexuelle commis sans le\nconsentement d’une personne, portent atteinte à l’intégrité physique et psychique de la\nvictime et, considérées sous l’angle juridique, violent plusieurs droits consacrés dans les\nconventions internationales, parmi lesquels le droit à la sécurité de la personne, le droit d’être\nprotégé contre la torture et les autres traitements cruels, inhumains ou dégradants, ainsi que le\ndroit de jouir du meilleur état de santé physique et mentale842."},{"id":"a-hrc-36-crp-1-p0447","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"447","seq":449,"section":"5. Violences sexuelles","text":"Les violences sexuelles constituent des violations du droit international des droits de\nl’homme lorsqu’elles sont commises par des agents publics, à leur instigation, ou avec leur\nconsentement ou leur acquiescement, mais également quand l’État ne fait pas preuve de\ndiligence pour protéger les personnes de violences sexuelles par des agents et entités non-\nétatiques, y compris en enquêtant sur ces actes et en punissant leurs auteurs conformément à\nla législation nationale843."},{"id":"a-hrc-36-crp-1-p0448","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"448","seq":450,"section":"5. Violences sexuelles","text":"Les victimes de violences sexuelles peuvent être aussi bien des hommes, des femmes\nou des enfants. La pratique a montré néanmoins une plus grande vulnérabilité des femmes.\nLa Déclaration sur l'élimination de la violence à l'égard des femmes, proclamée par\nl’Assemblée générale des Nations Unies en 1981, définit la « violence à l'égard des femmes »\ncomme « tous actes de violence dirigés contre le sexe féminin, et causant ou pouvant causer\naux femmes un préjudice ou des souffrances physiques, sexuelles ou psychologiques, y\ncompris la menace de tels actes, la contrainte ou la privation arbitraire de liberté, que ce soit\ndans la vie publique ou dans la vie privée »844.\n(ii)      Droits régional et sous-régional"},{"id":"a-hrc-36-crp-1-p0449","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"449","seq":451,"section":"5. Violences sexuelles","text":"En 2003, le Burundi a signé le Protocole à la CADHP relatif aux droits des femmes en\nAfrique, mais ne l’a pas ratifié. Le Burundi est en revanche partie au Pacte sur la paix, la\nsécurité, la stabilité et le développement dans la Région des Grands Lacs, ainsi qu’à son\nProtocole sur la prévention et la répression de la violence sexuelle à l’égard des femmes et\ndes enfants845. Ce protocole est juridiquement contraignant et définit la violence sexuelle\ncomme incluant, entre autres, le viol, le harcèlement sexuel, les coups et blessures,\nl’agression ou la mutilation des organes de reproduction féminins, la grossesse forcée,\nl’exploitation ou la contrainte sexuelle, l’infection de femmes et d’enfants avec des maladies\nsexuellement transmissibles, ou tout autre acte de gravité comparable. Le Protocole exige que\nles États membres s’engagent à prévenir et réprimer la violence sexuelle à l’égard des\nfemmes et des enfants en prenant des mesures de prévention, de pénalisation et de répression,\nconformément aux lois nationales et au droit pénal international.\n(iii)     Droit national"},{"id":"a-hrc-36-crp-1-p0450","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"450","seq":452,"section":"5. Violences sexuelles","text":"Comme le Statut de Rome, le Code pénal burundais prévoit que « le viol, l’esclavage\nsexuel, la prostitution forcée, la grossesse forcée, la stérilisation forcée ou toute autre forme\nde violence sexuelle de gravité comparable » sont parmi les actes pouvant constituer des\ncrimes contre l’humanité846. Au-delà, le Code pénal burundais consacre une section entière\nau viol847 dont il conditionne la commission à quatre éléments : « (1) Tout homme, quel que\nsoit son âge, qui introduit son organe sexuel, même superficiellement dans celui d’une\nfemme ou toute femme, quel que soit son âge, qui a obligé un homme à introduire, même\nsuperficiellement, son organe sexuel dans le sien ; (2) Tout homme qui a fait pénétrer, même\nsuperficiellement, par la voie anale, la bouche ou tout autre orifice du corps d’une femme ou\nd’un homme son organe sexuel, toute autre partie du corps ou tout autre objet quelconque ;\n(3) Toute personne qui introduit, même superficiellement, toute autre partie du corps ou un\nobjet quelconque dans le sexe féminin ; (4) Toute personne qui oblige à un homme ou une\nfemme de pénétrer, même superficiellement, son orifice anal, sa bouche par un organe\nsexuel »848."},{"id":"a-hrc-36-crp-1-p0451","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"451","seq":453,"section":"5. Violences sexuelles","text":"Le viol est puni de cinq à 15 ans de servitude pénale. La peine sera plus sévère – de 15\nans d’incarcération à la perpétuité – si des circonstances aggravantes sont démontrées, parmi\nlesquelles la minorité de la victime ou sa vulnérabilité, ou encore lorsque l’auteur abuse de\nl’autorité que lui confère ses fonctions, que le crime est commis en bande, quand l’auteur est\nporteur d’une arme, lorsque le viol a entraîné la mort ou a causé à la victime une altération\ngrave de sa santé ou laissé des séquelles physiques ou psychologiques graves, ou lorsque le\nviol a été précédé, accompagné ou suivi d’actes de torture ou de barbarie849."},{"id":"a-hrc-36-crp-1-p0452","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"452","seq":454,"section":"5. Violences sexuelles","text":"Le Code pénal burundais précise que « la qualité officielle de l’auteur d’une infraction\nrelative aux violences sexuelles ne peut en aucun cas l’exonérer de la responsabilité ou\nconstituer une cause de diminution de la peine ». De la même manière, « l’ordre hiérarchique\nou le commandement d’une autorité légitime civile ou militaire n’exonère nullement l’auteur\nd’une infraction relative aux violences sexuelles de sa responsabilité »850."},{"id":"a-hrc-36-crp-1-p0453","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"453","seq":455,"section":"5. Violences sexuelles","text":"Ces dispositions ont été confirmées dans la loi n° 1/13 du 22 septembre 2016 « portant\nprotection des victimes et prévention et répression des violences basées sur le genre »851 dont\nl’adoption a été saluée par le Comité pour l'élimination de la discrimination à l'égard des\nfemmes852. L’article 53 de ce texte prévoit qu’« est punie d’une servitude pénale de 12 à 15\nans et d’une amende de 100 000 à 500 000 francs burundais (soit d’environ 57 à 286 dollars\naméricains) toute personne dépositaire de l’autorité publique, chargée d’une mission de\nservice public, investie d’un mandat public, tout agent de l’ordre judiciaire, tout juge, tout\nofficier du Ministère public ou de police judiciaire qui aura, implicitement ou explicitement,\nexigé ou fait subir des actes de nature sexuelle afin de poser ou s’abstenir de poser un acte\nqui relève de ses attributions ». Les différentes infractions contenues dans le Code pénal sont\négalement rappelées, mais la loi y ajoute, entre autres, les actes de mutilation sexuelle, « tout\nacte d’intimidation ayant pour but l’abandon d’une procédure judiciaire concernant les\nviolences basées sur le genre », et les violences psychologiques et affectives (c’est-à-dire\n« des actes d’intimidation, de menaces, d’injures, des remarques désobligeantes à l’égard\nd’un conjoint »)853. La loi incite le Gouvernement à prendre toutes les mesures de\nsensibilisation nécessaire à la prévention des violences basées sur le genre et prévoit la\ncréation d’« une unité spécialisée ou un point focal des violences basées sur le genre » au\nsein de chaque poste de police, ainsi que des « structures d’accueil et des centres\nd’hébergement qui s’occupent de la victime » et une chambre spécialisée sur les violences\nbasées sur le genre au sein de chaque Tribunal de grande instance854.\n(b)     Faits\n(i)     Principales victimes"},{"id":"a-hrc-36-crp-1-p0454","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"454","seq":456,"section":"5. Violences sexuelles","text":"La Commission a pu s’entretenir avec 49 victimes de violences sexuelles855, ainsi\nqu’avec d’autres sources. Le nombre réel de victimes est probablement bien supérieur au vu\nde la réticence de beaucoup d’entre elles à dénoncer les violences sexuelles qu’elles ont\nsubies, notamment par crainte de représailles et de stigmatisation ou de rejet par leur\ncommunauté – que la victime soit un homme ou une femme. Les violences sexuelles\ndocumentées par la Commission datent pour les plus anciennes d’avril 2015 et pour les plus\nrécentes de janvier 2017."},{"id":"a-hrc-36-crp-1-p0455","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"455","seq":457,"section":"5. Violences sexuelles","text":"Parmi ces 49 victimes856, 31 sont de sexe féminin, dont trois mineures au moment des\nfaits, et 18 de sexe masculin, dont un mineur. La plus jeune victime avait seulement huit ans\nlorsqu’un Imbonerakure, qui était à la recherche de son père, membre d’un parti de\nl’opposition, l’a trouvée seule chez elle et l’a violée. La plus âgée avait 71 ans au moment\ndes faits."},{"id":"a-hrc-36-crp-1-p0456","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"456","seq":458,"section":"5. Violences sexuelles","text":"Le profil des victimes de violences sexuelles interrogées par la Commission présente\ncertaines similitudes : plusieurs d’entre elles, ou des membres de leur famille, ont participé\nou ont été accusés d’avoir participé aux manifestations de 2015857, ou sont membres ou ont\nété accusés d’être membres d’un parti d’opposition, notamment du MSD ou des FNL858."},{"id":"a-hrc-36-crp-1-p0457","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"457","seq":459,"section":"5. Violences sexuelles","text":"Selon les témoignages recueillis par la Commission, les propos tenus par les auteurs\nainsi que les circonstances dans lesquelles ils ont commis des violences sexuelles font\nressortir certains motifs communs : punir la victime pour sa participation ou son soutien, ou\ncelui de ses proches, aux manifestations contre un nouveau mandat du Président Nkurunziza,\net, plus généralement, pour son affiliation politique ou celle de ses proches à un parti\nd’opposition. Par exemple, une victime, manifestante en 2015, a témoigné :\n« [Plusieurs] hommes [...] Imbonerakure sont venus chez moi [...] Ils m’ont violée en\nprésence de mon mari qu’ils avaient ligoté [...] [et l’ont tué] sous mes yeux. [...] Ils\nont versé un produit sur mon visage [...] Ils m’injuriaient en me disant : « Refais ce\nque tu as fait et tu vas voir ». Mon mari et moi faisions partie des manifestants dans\nles rues »859.\nUn homme a aussi déclaré : « À la Documentation, ils me frappaient [...] J’ai\nparticipé aux manifestations. Je suis contre le troisième mandat. Ils me tripotaient les\nparties génitales. Je me suis évanoui et après trois heures en reprenant conscience,\nj’ai senti qu’ils m’avaient violé » 860.\nUne femme a également témoigné de son viol en 2015 dans sa maison à Bujumbura :\n« J’étais seule […] Ils m’ont violée. Des hommes, des Imbonerakure, sont entrés dans\nma chambre. Ils m’ont tirée du lit et m’ont jetée par terre. Ils ont déchiré ma robe en\nme disant : « Tu es de la mauvaise ethnie ». L’un m’a maîtrisé les bras, alors qu’un\nautre maîtrisait mes jambes et un autre me pénétrait mon vagin avec son sexe […]\nJ’ai perdu connaissance donc je ne sais pas si j’ai été violée par [tous mes\nagresseurs]. Ils portaient des longs manteaux imperméables noirs. Ils m’accusaient de\nne pas appartenir à leur parti »861."},{"id":"a-hrc-36-crp-1-p0458","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"458","seq":460,"section":"5. Violences sexuelles","text":"Des violences sexuelles ont également été commises dans le cadre de la répression\nsuite aux attaques contre les camps militaires à Bujumbura et ses environs, le 11 décembre\n2015862. Par exemple, une femme arrêtée par des policiers et violée à Bujumbura a témoigné :\n« Le 11 décembre 2015, le quartier a été encerclé […] À 9h du matin, nous avons\nentendu quelqu’un frapper au portail. Ma [mère] n’a pas voulu qu’on ouvre et le\nportail a été forcé. Il y a eu des tirs en l’air pour intimider tout le monde […] Quand\nles policiers sont entrés, ils ont tout saccagé et cassé la télévision en nous disant que\nnous devions montrer là où [un de mes parents] avait caché les armes. Ils ont cherché\net n’ont rien trouvé. Ils m’ont emmenée dans le pick-up de la police où il y avait déjà\nd’autres personnes que je ne pouvais pas voir en raison de la cagoule que la police\nm’avait mise […] Nous avons été emmenés à un endroit que je ne peux pas\nreconnaître et j’ai été mise toute seule dans une chambrette à l’étroit et je ne pouvais\npas me mettre debout […] L’homme qui m’interrogeait […] m’a demandé de me\ndéshabiller. Cet homme m’a violée […] J’ai demandé pardon mais il n’a pas voulu\nme laisser et il m’a dit : « Je ne vais pas te laisser tant que quand tu ne me diras pas\nlà où ton [parent] a laissé des armes »863."},{"id":"a-hrc-36-crp-1-p0459","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"459","seq":461,"section":"5. Violences sexuelles","text":"De manière générale, les violences sexuelles semblent avoir été commises afin\nd’imposer une forme de domination sur des femmes et des hommes ayant des liens avec des\npartis ou mouvements d’opposition864. Certaines victimes ont aussi été ciblées parce qu’elles\nn’étaient pas membres du CNDD-FDD ou avaient refusé d’y adhérer ou de participer à ses\nréunions865. Certaines victimes ont dit avoir été ciblées en raison de leur appartenance\nethnique en plus d’autres motifs souvent liés à leur appartenance politique866."},{"id":"a-hrc-36-crp-1-p0460","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"460","seq":462,"section":"5. Violences sexuelles","text":"La Commission a noté la vulnérabilité particulière des femmes aux violences\nsexuelles pendant ou après l’arrestation, la disparition ou le décès de leur conjoint ou parent\nde sexe masculin. Les victimes féminines ont été ciblées, une fois seules et sans défense, afin\nde déshonorer davantage leur parent masculin ainsi que le noyau familial en général. Des\nfemmes ont ainsi rapporté à la Commission avoir été violées par des Imbonerakure après que\nces derniers aient tué leur mari ou un parent867. Par exemple, en 2015, des hommes ont tué un\nsympathisant d’un parti d’opposition et ont violé sa femme quelques jours plus tard à son\ndomicile868. Une autre victime a rapporté que des Imbonerakure ont tué son père en avril\n2015 à Bujumbura avant de la violer869."},{"id":"a-hrc-36-crp-1-p0461","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"461","seq":463,"section":"5. Violences sexuelles","text":"Certaines femmes et filles ont été violées en présence de leurs proches, ce qui a non\nseulement contribué à les humilier mais a également porté atteinte à leur dignité de manière\npermanente870. À titre d’exemple, une victime a rapporté qu’en 2015, elle a été violée par des\nhommes en tenue militaire avec des bérets bleus foncés à Bujumbura. L’un des hommes l’a\nviolée devant son mari avant de le tuer, puis un autre l’a violée devant son enfant871. Une\nautre femme a témoigné de l’enlèvement de son mari par un groupe d’hommes inconnus en\n2015. Quelques semaines plus tard, certains de ces hommes sont revenus chez elle et l’un\nd’eux l’a violée devant son enfant872."},{"id":"a-hrc-36-crp-1-p0462","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"462","seq":464,"section":"5. Violences sexuelles","text":"La majorité de cas de violences sexuelles recensés par la Commission à l’encontre\nd’hommes ont eu lieu dans le cadre de la détention. Les victimes ont été violées afin de leur\nextraire des informations ou des aveux, comme dans le cadre d’autres formes de torture873, et,\nselon les victimes, pour les humilier et porter atteinte à leur masculinité874. Par exemple, un\nhomme a témoigné des sévices qu’il a subis au siège du SNR à Bujumbura :\n« On a pris mes testicules avec des tenailles en fer et j’ai saigné au niveau du sexe. Ils\nvoulaient que j’avoue où sont les armes et que j’avoue que je travaille avec [un\ndirigeant de l’opposition] » 875.\n(ii)     Principaux auteurs présumés"},{"id":"a-hrc-36-crp-1-p0463","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"463","seq":465,"section":"5. Violences sexuelles","text":"La Commission s’est entretenue avec 27 victimes de violences sexuelles commises\npar des agents de l’État. Ces actes, du fait de l’identité de leurs auteurs, constituent des\nviolations des droits de l’homme. La plupart de ces violences sexuelles ont été perpétrées par\ndes agents de la police et/ou du SNR876. Dans certains cas, ces agents ont agi ensemble, dans\nd’autres, conjointement avec des Imbonerakure877. Dans ce dernier cas de figure, les\nImbonerakure agissaient sur instruction ou sous le contrôle d’agents étatiques, leurs actes\nengageant de ce fait la responsabilité de l’État878. Par exemple, une victime a expliqué qu’elle\navait été violée par un Imbonerakure en présence de deux agents du SNR au siège du SNR à\nBujumbura en 2015879. Une autre a témoigné de son viol à son domicile en 2016 par un\ngroupe de six à dix personnes, dont des Imbonerakure et « deux policiers en uniforme bleu »\n880\n."},{"id":"a-hrc-36-crp-1-p0464","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"464","seq":466,"section":"5. Violences sexuelles","text":"Parmi ces 27 cas de violences sexuelles, 21 ont eu lieu dans des centres de détention,\npour la plupart au siège du SNR à Bujumbura. Une victime a témoigné de son viol au SNR à\nBujumbura par deux policiers en 2015 :\n« Deux personnes en uniforme de police m’ont emmenée dans [une] salle [...] Les\ndeux policiers ont fumé un produit dans une pipe et l’un d’entre eux a soufflé la fumée\nsur moi et j’ai perdu connaissance. Je sais qu’ils m’ont violée [...] mais je ne sais pas\ncombien de personnes [l’ont fait] » 881."},{"id":"a-hrc-36-crp-1-p0465","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"465","seq":467,"section":"5. Violences sexuelles","text":"La Commission a recueilli les témoignages de 10 victimes de violences sexuelles qui\nont rapporté avoir été violées par des Imbonerakure882. Les violences sexuelles commises par\ndes Imbonerakure, sans lien avec un agent de l’État, constituent des atteintes aux droits de\nl’homme883. Une victime a témoigné:\n« J’ai été ligotée par des Imbonerakure [...] Ils étaient en tenue civile. Ils avaient\nenviron 23 ou 26 ans. Celui qui m’a violée avait une sorte d’aigle tatoué sur [son\ncorps] – c’est le sigle du parti CNDD-FDD »884."},{"id":"a-hrc-36-crp-1-p0466","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"466","seq":468,"section":"5. Violences sexuelles","text":"D’autres témoignages ont mentionné des Imbonerakure portant des tenues policières.\nÀ titre d’exemple, une fille a été violée chez elle à Bujumbura en 2015 par des individus en\ntenue policière qu’elle a identifiés comme des Imbonerakure. Les hommes cherchaient son\nfrère qui avait quitté les Imbonerakure. En guise de représailles, ils ont tué l’un de ses\nparents, puis ont violé la fille près du corps d’un parent qu’ils avaient tué885."},{"id":"a-hrc-36-crp-1-p0467","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"467","seq":469,"section":"5. Violences sexuelles","text":"Une autre victime a témoigné que plusieurs personnes qu’elle suppose être des\nImbonerakure sont venus chez elle et l’ont violée:\n« L’un deux m’a giflée. Un autre m’a donné un coup de crosse de fusil au dos et j’ai\nperdu connaissance tellement la douleur était intense. Ils m’ont ramassée alors que\nj’étais inconsciente et ils m’ont emmenée dans ma chambre. En reprenant conscience,\nj’ai entendu : « Montre-nous les armes ». Ils étaient à [plusieurs] dans ma chambre.\nL’un m’a pris le bras droit, l’autre le bras gauche et un autre a pris mes pieds. Ils\nm’ont [violée] l’un après l’autre. Ils ont tous inséré leur sexe dans mon vagin. Je\ncriais et ils me mettaient la main sur la bouche [...] [Ils] m’ont violée sauvagement\nl’un après l’autre. Ils ont ensuite inséré un pilon de bois et d’autres morceaux de bois\ndans mon vagin, très profondément, me défonçant l’utérus [...] Je ne connais pas [les\nnoms de] ces hommes. Ils avaient l’âge de mes fils. Ils portaient une tenue policière\n»886.\n(iii)     Types de violence sexuelle"},{"id":"a-hrc-36-crp-1-p0468","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"468","seq":470,"section":"5. Violences sexuelles","text":"La Commission a été frappée par le caractère particulièrement cruel et brutal des\nviolences sexuelles. L’intention des auteurs de punir et de brutaliser leurs victimes accentue\nl’aspect inhumain de ces violations et atteintes. Par exemple, des Imbonerakure en tenue\npolicière ont indiqué à une victime qu’ils ont violée et ensuite mutilée : « Il faut qu’on la\ntue », « Non, la tuer ne serait pas la torturer comme il le faut », ou encore : « Il faut la\ndéchirer »887. Selon le témoignage d’une autre victime, des manifestants et des membres de\npartis d’opposition qui avaient été arrêtés ont été contraints de violer d’autres détenus,\nnotamment au siège du SNR à Bujumbura888. Un homme arrêté en 2015 a expliqué :\n« Deux agents du SNR m’ont forcé, ainsi que quatre autres détenus, à avoir des\nrelations sexuelles […] Au début, j’avais refusé et ils m’ont brûlé avec des chocs\nélectriques sur ma poitrine et au niveau de mes épaules. Une personne faisait la\nplanche, et les quatre autres, nous devions le pénétrer, et à tour de rôle, nous faisions\nla planche. Les agents nous disaient qu’après cela, on allait tous devenir amis. Les\nquatre autres détenus ont été exécutés le lendemain »889."},{"id":"a-hrc-36-crp-1-p0469","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"469","seq":471,"section":"5. Violences sexuelles","text":"Les principaux types de violence sexuelle qui ont été rapportés à la Commission sont\nle viol890, la mutilation génitale891, la nudité forcée, l’infliction de blessures graves et/ou\nl’injection de substances inconnues dans les organes génitaux masculins et la suspension de\npoids aux testicules892. Souvent, les victimes ont subi plusieurs types de violence sexuelle."},{"id":"a-hrc-36-crp-1-p0470","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"470","seq":472,"section":"5. Violences sexuelles","text":"Dans chaque cas de viol rapporté, il y a eu pénétration vaginale ou anale de la victime\nsous la menace, la coercition et/ou le contrôle de l’auteur. Ces violences sexuelles constituent\négalement des tortures et/ou des traitements cruels, inhumains ou dégradants893. Plusieurs\nviols documentés par la Commission sont des viols collectifs894. Par exemple, une femme a\nété victime pendant quatre jours de plusieurs viols dans un centre de détention du SNR. Six\nhommes dont des policiers l’ont violée afin d’obtenir des renseignements sur les activités\nprésumées d’un membre de sa famille895. Une mineure au moment des faits a également\ntémoigné de son viol par trois hommes, dont des Imbonerakure et des hommes en tenue\npolicière:\n« Un homme m’a ligotée les mains devant avec une corde (une corde utilisée\ngénéralement pour attacher les chèvres) et j’ai été violée par trois hommes [...] Ils\nm’ont poussée par terre. J’étais au sol et j’ai essayé de me débattre. L’un d’eux m’a\ngiflée au niveau des yeux et je ne pouvais plus voir. Il a mis sa main sur ma bouche\npour pas que je crie. Les trois hommes m’ont violée. Ils disaient : « Il faut la tuer,\ntirer une balle sur elle car elle nous a vus ». Un autre a dit : « Elle va mourir de toute\nfaçon, on peut la casser ». Les trois ont inséré leur sexe dans le mien, l’un après\nl’autre. L’un d’eux m’a donné un coup de pied à la tête et j’ai perdu connaissance »\n896\n."},{"id":"a-hrc-36-crp-1-p0471","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"471","seq":473,"section":"5. Violences sexuelles","text":"La Commission a recueilli deux témoignages de femmes dont les organes génitaux ont\nété mutilés à la suite d’un viol collectif par des hommes qu’elles ont identifiés comme des\nImbonerakure897. L’une d’elles a rapporté que son mari, associé à un parti de l’opposition, a\nété tué devant elle par quatre Imbonerakure en 2015 à Bujumbura. Ces hommes l’ont ensuite\nviolée à tour de rôle et, après le viol, ont coupé son clitoris à l’aide d’un objet tranchant et lui\nont inséré du bois dans le vagin898."},{"id":"a-hrc-36-crp-1-p0472","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"472","seq":474,"section":"5. Violences sexuelles","text":"La nudité forcée a été utilisée afin d’humilier et de rabaisser les victimes, mais aussi\npour leur soutirer des informations. Des hommes ont été forcés de se déshabiller pendant des\nséances d’interrogation ou avant de se faire battre sur les parties génitales899. Des femmes ont\négalement été victimes de nudité forcée, en détention ou chez elles avant d’être violées900."},{"id":"a-hrc-36-crp-1-p0473","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"473","seq":475,"section":"5. Violences sexuelles","text":"La Commission a reçu plusieurs témoignages sur des cas de violences sexuelles dans\nle cadre de la détention. À titre d’exemple, un homme qui avait participé aux manifestations\ncontre le nouveau mandat du Président Nkurunziza a affirmé qu’en 2015, des Imbonerakure\nl’ont appréhendé à Bujumbura et l’ont conduit au siège du SNR. Pendant sa détention, il a été\nplaqué contre un mur et violé par un Imbonerakure en présence de deux agents du SNR901."},{"id":"a-hrc-36-crp-1-p0474","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"474","seq":476,"section":"5. Violences sexuelles","text":"La Commission s’est entretenue avec plusieurs hommes qui ont été battus sévèrement,\nparfois nus, sur les parties génitales par des agents du SNR, avec des barres de fer, des fils\nélectriques, des baïonnettes ou d’autres objets, et qui ont reçu à plusieurs reprises des coups\nde pied sur les parties génitales902. Certains ont été forcés d’exposer leurs parties génitales\npour être battus par derrière. Une victime a témoigné :\n« Des agents du SNR] [m’ont mis] en position verticale, les jambes droites, le dos\npenché perpendiculairement au sol. J’ai été blessé au niveau des organes génitaux.\n[...] On m’a donné une série répétée de coups de pied, très forts, dans les organes\ngénitaux »903."},{"id":"a-hrc-36-crp-1-p0475","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"475","seq":477,"section":"5. Violences sexuelles","text":"La Commission a aussi reçu plusieurs témoignages de détenus qui ont expliqué que\ndes agents du SNR ou des policiers leur ont suspendu des poids aux organes génitaux, injecté\nune substance liquide non identifiée dans les testicules, ou écrasé ou serré les testicules avec\nles mains ou des pinces en métal. Ces violences sexuelles ont occasionné des enflements, des\nsaignements et des douleurs extrêmes aux parties génitales, empêchant les victimes de se\nrelever et de marcher904. Un survivant a témoigné :\n« J’étais accroché au plafond avec une corde. [Des agents du SNR] m’ont battu très\nfort avec un fil de fer. Ils ont pris un bidon de cinq litres. Ils y ont mis de l’eau. Ils ont\naccroché le bidon à mes testicules [...]. [X] donnait les ordres aux policiers qui\nexécutaient les ordres. Ils m’ont laissé avec le bidon accroché et ils m’ont dit qu’ils\nallaient partir pour me laisser réfléchir. Ils sont sortis de la pièce pendant 30 minutes\net [X] est revenu seul. Il m’a demandé si j’avais réfléchi. Je lui ai dit que ce que\nj’avais dit était la seule vérité. Il y avait une table dans la pièce en-dessous de moi,\nmais mes pieds n’arrivaient pas à la table. Il a enlevé la table. Lui est monté sur la\ntable pour couper la corde. Je suis tombé par terre. Le bidon était toujours\naccroché »905.\nUne autre victime a affirmé : « Des [agents du SNR] m’ont déshabillé et m’ont injecté\n[un produit dans] le testicule droit. Après [l’injection], j’ai senti une douleur générale\ndans mon corps et je me suis évanoui »906."},{"id":"a-hrc-36-crp-1-p0476","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"476","seq":478,"section":"5. Violences sexuelles","text":"Un ancien membre d’un parti d’opposition détenu et torturé pendant quatre jours en\n2016 dans une maison sans fenêtre à Bujumbura a rapporté que des policiers ont menacé de\nlui couper le pénis s’il refusait de répondre à leurs questions907."},{"id":"a-hrc-36-crp-1-p0477","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"477","seq":479,"section":"5. Violences sexuelles","text":"La Commission a également documenté un cas de tentative de viol. En décembre\n2015, des policiers sont entrés dans la maison d’une femme à la recherche de documents en\nlien avec les manifestations. Certains de ces policiers ont tenté de la violer908.\n(iv)     Lieux et temps"},{"id":"a-hrc-36-crp-1-p0478","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"478","seq":480,"section":"5. Violences sexuelles","text":"Les violences sexuelles rapportées par les victimes s’étalent d’avril 2015 à janvier\n2017. La plupart ont été commises à Bujumbura909, mais la Commission a également reçu des\ntémoignages sur de tels actes dans d’autres localités910."},{"id":"a-hrc-36-crp-1-p0479","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"479","seq":481,"section":"5. Violences sexuelles","text":"Comme indiqué plus haut, tous les hommes interrogés par la Commission ont été\nvictimes de violences sexuelles en détention911. La plupart des femmes ont quant à elles subi\ndes violences sexuelles à leur domicile912, et pour certaines en tentant de fuir le pays913 ou, à\nl’instar des hommes, dans un centre de détention914."},{"id":"a-hrc-36-crp-1-p0480","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"480","seq":482,"section":"5. Violences sexuelles","text":"Selon les informations recueillies par la Commission, les centres de détention où des\nviolences sexuelles ont été commises incluent ceux du SNR915 et un poste de police dans la\nprovince de Bujumbura916. Des actes de violences sexuelles ont également été commis dans\ndes lieux de détention non-officiels, comme un container917 ou des endroits non identifiés918,\nou encore dans une forêt919. Un sympathisant d’un parti d’opposition a témoigné de son viol\npar plusieurs hommes en tenue de police dans une maison non identifiée à Bujumbura en\n2016 :\n« Ils m’ont injecté quelque chose dans mon bras gauche [...] Je n'ai pas vu ce qu'ils\nm'ont injecté […] J'étais cagoulé. La voiture a démarré et après quelques minutes,\nj’ai sombré dans un profond sommeil pour me réveiller dans la nuit dans une maison\nobscure [...] Je ne voyais personne sauf que j’entendais des voix seulement. J'étais\nseul dans une chambre [...] Je me suis réveillé avec beaucoup de douleurs surtout\ndans les côtes et au niveau de mon anus. J’avais été violé [...] j'ai constaté que mon\npantalon était descendu, mon slip aussi, et il y avait du sperme sur mon pantalon et\nsur mes vêtements » 920."},{"id":"a-hrc-36-crp-1-p0481","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"481","seq":483,"section":"5. Violences sexuelles","text":"Les femmes, comme mentionné, ont souvent été violées à leur domicile. Par exemple,\nune victime a été violée en 2015 à Bujumbura après que des policiers aient arrêté et détenu\nson mari, membre d’un parti d’opposition. Alors que la victime se trouvait seule à la maison,\ndes policiers se sont présentés chez elle et l’ont violée à tour de rôle. Elle a déclaré :\n« Il y avait [plusieurs] hommes. Ils portaient des tenues [...] bleues avec écrit dessus\n« police ». [Certains] sont entrés et les [d’autres] sont restés à l’extérieur […] [Des]\npoliciers m’ont tenu les bras comme sur la croix et un troisième policier est entré\ndans la maison et il a commencé à me déshabiller […] Comme je me défendais en me\ncourbant pour qu’il ne me déshabille pas, je me suis cognée contre le mur et\nquelqu’un m’a plaqué sa main sur la bouche pour m’empêcher de crier [...]J’étais\ncouchée sur le ciment, sur le dos face au plafond et, un à un, ils sont parvenus à avoir\ndes relations sexuelles avec moi pendant que deux d’entre eux me tenaient les mains\net ils se disaient entre eux: « Toi, tu vas, tu finis, tu vas ». Ils ouvraient leurs\npantalons rapidement car ils disaient : « Rapidement, moi aussi » [...] Un tenait mes\ndeux jambes le plus grandement écartées possible et l’autre les mains. L’un disait :\n« Fermez ses yeux pour qu’elle ne voit pas celui qui fait des rapports [sexuels]» […]\nIls [m’ont violée] à tour de rôle autant qu’ils voulaient et ils ont fait entrer leur pénis\ndans mon vagin »921.\nMI-082, TI-047"},{"id":"a-hrc-36-crp-1-p0482","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"482","seq":484,"section":"5. Violences sexuelles","text":"La Commission s’est entretenue avec deux femmes violées par des Imbonerakure ou\ndes policiers alors qu’elles tentaient de fuir le pays922. L’une d’entre elles a été violée par des\npoliciers à un barrage près d’une frontière, en 2016. Elle a témoigné :\n« La première barrière était érigée par des policiers qui m’ont demandé où j’allais\n[…] [L]es policiers ont refusé de me laisser partir et ils m’ont dit que, puisque je\ncontinuais à mentir, ils allaient me montrer. Ils m’ont dit d’aller dans [une petite\nmaison] […] Je pensais que j’y passerai la nuit […] Ils m’ont [forcée à entrer]dans la\npetite maison et je les ai suppliés de me laisser en échange d’argent. Ils n’ont pas\nvoulu de l’argent […] Ils ont écarté mes jambes avec des cordes utilisées pour\ninstaller les tentes de militaires et ils m’ont attaché les mains et les pieds. Ils étaient\n[plusieurs] à m’avoir violée à tour de rôle »923.\n(v)     Injures"},{"id":"a-hrc-36-crp-1-p0483","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"483","seq":485,"section":"5. Violences sexuelles","text":"Plusieurs victimes ont mentionné des injures à caractère ethnique, sexiste et/ou\npolitique durant les violences sexuelles924. Par exemple, une femme violée en détention a\ntémoigné des propos suivants proférés par des policiers : « Pourquoi tu nous casses les\noreilles ? Votre régime est passé, nous allons vous violer tant que nous voulons […] Tu as la\nchance, on aurait dû te tuer car on ne veut pas de ton ethnie dans ce pays »925."},{"id":"a-hrc-36-crp-1-p0484","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"484","seq":486,"section":"5. Violences sexuelles","text":"Les femmes tutsies ont particulièrement été injuriées926. À titre d’exemple, une\nvictime a témoigné avoir subi des injures à caractère ethnique et sexiste :\n« Deux policiers [...] m’ont piétiné les deux pieds en m’écartant les jambes et en\ndisant : « Nous voulions voir le sexe des Tutsis ». J’[ai crié] fort et personne n’est\nvenu à mon secours.[...] Ils m’[ont montré] des lames de rasoirs et m’[ont menacée]\nen disant : « Si tu n’acceptes pas, on va te couper le vagin ». Comme je savais qu’ils\nétaient impitoyables, j’ai accepté sous la force [...] un à un, ils sont parvenus à me\nfaire des relations sexuelles »927."},{"id":"a-hrc-36-crp-1-p0485","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"485","seq":487,"section":"5. Violences sexuelles","text":"Une autre victime a témoigné avoir subi des injures à caractère politique et ethnique\npar deux Imbonerakure qui l’ont violée suite aux attaques des camps militaires à Bujumbura\net ses environs, le 11 décembre 2015. La victime, qui vivait dans un quartier dit\n« contestataire », a rapporté :\n« Ils m’ont dit : « Pourquoi es-tu restée dans ce maudit quartier ? » [...] Ils m’ont\ndemandé aussi mon ethnie [...] Ils m’ont injuriée et accusée de travailler pour les\nopposants politiques. « Vu que tu habites [là], c’est que tu es avec l’opposition » [...]\nIls m’ont dit que j’étais un « mujeri » [signifiant « chien errant et décharné », un\nterme utilisé pour désigner les opposants] […] Ils m’ont traînée par terre [...] et j’ai\ncommencé à saigner à la tête. Ils m’ont alors dit : « Maintenant que tu vois le sang, tu\nvas commencer à parler » [...]ils m’ont dit d’enlever ma culotte [...] J’ai vu qu’ils\nallaient me violer [...] J’ai cherché à me défendre [...] Ils m’ont dit : « On ne va pas te\ntuer mais on va te donner une leçon… les autres qui sont comme toi verront que ce\npays est gouverné par des hommes. Nous nous sommes battus pour être là où on est et\npersonne ne va nous bouger de là » 928."},{"id":"a-hrc-36-crp-1-p0486","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"486","seq":488,"section":"5. Violences sexuelles","text":"Certains auteurs de viols ont déclaré à leurs victimes qu’elles devaient tomber\nenceintes afin d’enfanter des partisans du CNDD-FDD929. La Commission a reçu le\ntémoignage d’une victime, membre d’un parti d’opposition, qui a été violée collectivement\npar des Imbonerakure et des policiers en 2016 :\n« Avant de [tuer mon mari], ils ont commencé à me violer à ma résidence [...] C’était\nun groupe de six à dix personnes [...] composé d’Imbonerakure et de policiers dont\ndeux policiers en uniforme bleu. Lorsqu’ils ont voulu me violer, ils m’ont dit qu’ils\nvoulaient que je leur fasse des bébés pour qu’ils deviennent des Imbonerakure » 930."},{"id":"a-hrc-36-crp-1-p0487","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"487","seq":489,"section":"5. Violences sexuelles","text":"Ces cas sont à replacer dans un contexte où des chants, en particulier d’Imbonerakure,\nappelant à « engrosser les opposantes » ont été entendus pendant des rassemblements du parti\nau pouvoir931."},{"id":"a-hrc-36-crp-1-p0488","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"488","seq":490,"section":"5. Violences sexuelles","text":"Des violences sexuelles perpétrées contre certains hommes en détention ont également\nété accompagnées d’injures principalement à caractère ethnique932. Par exemple, un homme\nviolé en détention a été injurié par des policiers : « Sale chien de Tutsi, tu croyais que nous\nn’allons pas t’attraper ? Nous allons te tuer et personne ne saura où se trouvent tes\nrestes »933. Un homme qui a été sévèrement frappé au niveau des organes génitaux s’est fait\ninjurier par un policier qui lui a dit : « On va abattre tous les Tutsis »934. Un Imbonerakure\nqui a violé un homme en détention lui a dit : « Un Tutsi qui est contre le parti au pouvoir\nmérite d’être grillé »935.\n(vi)     Autres viols pour motifs politiques"},{"id":"a-hrc-36-crp-1-p0489","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"489","seq":491,"section":"5. Violences sexuelles","text":"La Commission a également documenté 12 cas de viol par des hommes que les\nvictimes n’ont pas été en mesure d’identifier936. Si ces viols ne peuvent pas être assimilés à\ndes violations ou des atteintes aux droits de l’homme du fait de l’incertitude sur l’identité des\nauteurs, la Commission considère néanmoins que ces cas méritent d’être relevés au vu des\nmotifs invoqués par les auteurs présumés au moment des faits et du profil des victimes."},{"id":"a-hrc-36-crp-1-p0490","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"490","seq":492,"section":"5. Violences sexuelles","text":"Certaines victimes semblent en effet avoir été ciblées parce que des membres de leur\nfamille avaient refusé de rejoindre les Imbonerakure ou le CNDD-FDD, étaient membres\nd’un parti d’opposition, ou avaient soutenu les manifestations contre le nouveau mandat du\nPrésident Nkurunziza. D’autres ont mentionné avoir été violées après la disparition,\nl’enlèvement ou l’arrestation de leur mari ou parent de sexe masculin membres présumés de\nl’opposition937."},{"id":"a-hrc-36-crp-1-p0491","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"491","seq":493,"section":"5. Violences sexuelles","text":"Plusieurs victimes ont mentionné avoir été violées par des hommes en tenue civile,\nparfois cagoulés, dont certains portaient de longs manteaux ou des imperméables noirs, ou\ndes tenues policières ou militaires938. À titre d’exemple, une femme âgée, dont le fils,\nmembre d’un parti d’opposition, avait été enlevé, a témoigné :\n« Je n’ai pas reconnu les hommes qui sont venus chez moi [...] Une semaine après\nl’enlèvement de mon fils [...]ils sont revenus à trois hommes. J’ai été violée par deux\nhommes […] Je crois que j’ai attrapé une maladie qui fait enfler mes jambes, mes\npieds sont très enflés depuis le viol. J’ai aussi mal au niveau des reins […] Ils\nportaient des pantalons militaires. Je pense que c’était les mêmes personnes qui ont\npris mon fils car ils portaient la même tenue » 939."},{"id":"a-hrc-36-crp-1-p0492","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"492","seq":494,"section":"5. Violences sexuelles","text":"Une autre victime a témoigné avoir été violée, notamment par voie anale, en 2015 par\ndes hommes qu’elle croit être des membres du CNDD-FDD ; l’un d’eux avait un aigle, le\nsymbole du parti, tatoué sur son corps. Ces hommes cherchaient son mari qui avait participé\naux manifestations, mais celui-ci avait été tué un mois plus tôt. Elle a témoigné :\n« L’un d’eux m’a dit qu’ils sont venus me donner une leçon et m’ont demandé : « Où\nest ton mari ? Qui l’a tué ? ». Ils ont dit que j’avais une fierté mal placée [...] L’un\ndes hommes m’a demandé : « Tu sais qui je suis ? » J’ai dit non et il a continué en\ndisant qu’il était connu sur le plan international. Il a enlevé sa veste et il avait un\ntatouage qui représentait un aigle [...]. Je lui ai dit ne pas le connaitre et il m’a\ngiflée. J’ai eu des vertiges, je suis tombée et j’ai perdu connaissance. Quand j’ai\nrepris connaissance, j’ai senti une douleur terrible au niveau du bas ventre car ils ont\nécarté mes jambes de force […] La douleur la plus forte était celle de derrière car\nj’avais très mal dans l’anus. [...] Le lendemain matin, j’ai eu très mal au dos et j’ai\nperdu ma grossesse de presque deux mois […]. Ces hommes avaient essayé de tordre\nmon sein et parfois, j’ai des crises et mon sein devient tout noir et me fait mal »940."},{"id":"a-hrc-36-crp-1-p0493","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"493","seq":495,"section":"5. Violences sexuelles","text":"La Commission a reçu le témoignage d’une jeune femme qui a été victime de viol\ncollectif en 2015, en même temps que sa mère, à leur domicile. Des hommes avaient enlevé\nson père et son frère qui avaient refusé de rejoindre les Imbonerakure. Quelques jours plus\ntard, trois hommes inconnus sont venus et ont violé les deux femmes. La jeune femme a\nréussi à s’enfuir après le viol mais a dû laisser derrière elle sa mère qui se faisait toujours\nvioler941."},{"id":"a-hrc-36-crp-1-p0494","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"494","seq":496,"section":"5. Violences sexuelles","text":"Une femme a témoigné qu’en 2016, des hommes ont emmené son mari et son frère,\ntous les deux membres d’un parti d’opposition. Au moment de leur arrestation, la victime\nn’était pas au domicile familial. En 2017, alors qu’elle était retournée chez elle, deux\nhommes, qui lui ont dit qu’ils avaient tué son mari, l’ont violée942.\n(vii)     Obligation de mener des enquêtes"},{"id":"a-hrc-36-crp-1-p0495","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"495","seq":497,"section":"5. Violences sexuelles","text":"De manière générale, les victimes interrogées par la Commission ont rarement porté\nplainte auprès des autorités : elles ont indiqué ne pas avoir confiance dans le système\njudiciaire, ayant constaté que de manière générale, les auteurs de violations ou d’atteintes aux\ndroits de l’homme restent impunis. En outre, la plupart des victimes interrogées par la\nCommission ont fui le Burundi peu de temps après la commission des violences sexuelles943.\nMalgré cela, les autorités burundaises sont tenues d’enquêter sur ces cas, ce qu’à la\nconnaissance de la Commission, elles n’ont pas fait.\n(c)      Conséquences des violences sexuelles pour les victimes et leurs familles"},{"id":"a-hrc-36-crp-1-p0496","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"496","seq":498,"section":"5. Violences sexuelles","text":"Les victimes de violences sexuelles font face à de multiples conséquences que ce soit\nau niveau physique ou psycho-social. Ces conséquences affectent directement les survivants,\nmais aussi leur famille et le tissu social en général. La santé sexuelle et reproductive des\nvictimes est souvent directement atteinte, et les proches ayant témoigné du viol d’un parent\nont également besoin d’un suivi psycho-social."},{"id":"a-hrc-36-crp-1-p0497","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"497","seq":499,"section":"5. Violences sexuelles","text":"De nombreuses victimes avec lesquelles la Commission s’est entretenue n’ont pas eu\naccès aux soins dans les délais requis, ce qui a aggravé les conséquences des violences\nsexuelles. Plusieurs victimes ont fui le pays juste après avoir été violées et n’ont pu obtenir\nles soins médicaux d’urgence dans les 72 heures après le viol, incluant les soins anti-VIH et\nles contraceptifs. Par exemple, une femme violée et mutilée en 2015 par quatre hommes\nqu’elle croit être des Imbonerakure a quitté le Burundi quelques jours plus tard alors qu’elle\navait urgemment besoin d’une intervention chirurgicale. Avant de fuir le pays, elle avait été\ntransportée à un dispensaire au Burundi mais elle n’y avait reçu que des soins de base afin de\ncolmater l’hémorragie944. D’autres victimes, craignant la stigmatisation, ont choisi de se\nsoigner elles-mêmes avant de prendre le chemin de l’exil945 ou sont allées à un dispensaire\nmais n’ont pas divulgué au corps médical qu’elles avaient été violées946. Quelques victimes\nque la Commission a rencontrées ont toutefois indiqué avoir reçu des soins au Burundi et/ou\nen exil, y compris des soins anti-VIH et des contraceptifs947."},{"id":"a-hrc-36-crp-1-p0498","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"498","seq":500,"section":"5. Violences sexuelles","text":"Les victimes rencontrées par la Commission ont rarement eu accès à des soins de\nsanté en exil, par manque d’information, par crainte de stigmatisation ou parce que les\nservices gratuits octroyés aux réfugiés n’étaient pas adaptés, en particulier pour les hommes\nvictimes de violences sexuelles. Ces derniers ont eu bien souvent honte d’aller consulter et\nd’obtenir les soins nécessaires qui sont généralement offerts aux femmes948. Un homme a\ntémoigné avoir été tellement traumatisé par son viol qu’il n’était pas parvenu à en parler au\nmédecin qui le traitait pour une autre affection médicale949. Or, plusieurs victimes masculines\nsouffrent de dysfonction érectile, de problèmes urinaires, ou de douleurs chroniques au\nniveau des parties génitales950. Un homme a témoigné s’être fait enlever un testicule après\navoir subi des blessures graves et être devenu impuissant951. Sur le plan psychologique, les\nvictimes masculines interrogées par la Commission ont confié ressentir un manque de désir\nsexuel, un sentiment d’isolement, ou être sujettes à un stress post-traumatique952."},{"id":"a-hrc-36-crp-1-p0499","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"499","seq":501,"section":"5. Violences sexuelles","text":"Certaines victimes féminines que la Commission a rencontrées sont porteuses du VIH\nqu’elles ont contracté suite au viol953, souffrent d’infections vaginales ou d’autres problèmes\ngynécologiques récurrents, ou d’une difficulté à avoir des rapports sexuels954. Certaines ont\nperdu une grossesse en cours955. D’autres sont tombées enceintes et portent aujourd’hui le\npoids d’élever l’enfant issu de leur viol956. De nombreuses victimes souffrent également de\nséquelles sociales et psychologiques. Une victime a témoigné avoir été abandonnée par son\nconjoint après avoir avoué le viol dont elle avait été victime957. Une autre victime a confié\navoir voulu se suicider après le viol958, alors qu’une autre a supplié les auteurs des viols dont\nelle a été victime pendant quatre jours de la tuer, ne pouvant plus supporter la souffrance.\nElle a témoigné :\n« Je me suis adressée à l’un des policiers en disant : « Je souffre tellement fort, est-ce\nque tu peux m’achever ? » Et le policier m’a répondu : « On ne peut pas te tuer tant\nque tu n’auras pas parlé »959."},{"id":"a-hrc-36-crp-1-p0500","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"500","seq":502,"section":"6. Liberté d’expression","text":"La liberté d’expression est garantie par l’article 19 de la DUDH et du PIDCP. Ce\ndernier dispose que : « (1) Nul ne peut être inquiété pour ses opinions. (2) Toute personne a\ndroit à la liberté d’expression ; ce droit comprend la liberté de rechercher, de recevoir et de\nrépandre des informations et des idées de toute espèce, sans considération de frontières, sous\nune forme orale, écrite, imprimée ou artistique, ou par tout autre moyen de son choix. (3)\nL’exercice des libertés prévues au paragraphe 2 du présent article comporte des devoirs\nspéciaux et des responsabilités spéciales. Il peut en conséquence être soumis à certaines\nrestrictions qui doivent toutefois être expressément fixées par la loi et qui sont nécessaires :\n(a) Au respect des droits ou de la réputation d’autrui ; (b) À la sauvegarde de la sécurité\nnationale, de l’ordre public, de la santé ou de la moralité publiques »."},{"id":"a-hrc-36-crp-1-p0501","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"501","seq":503,"section":"6. Liberté d’expression","text":"Dans son observation générale sur l’article 19 du PIDCP960, le Comité des droits de\nl’homme précise que la liberté d’expression couvre un champ large. Elle porte sur « le\ndiscours politique, le commentaire de ses affaires personnelles et des affaires publiques, la\npropagande électorale, le débat sur les droits de l’homme, le journalisme, l’expression\nculturelle et artistique, l’enseignement et le discours religieux », et englobe plusieurs moyens\nd’expression. Le Comité a particulièrement mis l’accent sur la liberté d’expression des\nmédias dans la mesure où « l’existence d’une presse et d’autres moyens d’information libres,\nsans censure et sans entraves est essentielle dans toute société pour garantir la liberté\nd’opinion et d’expression et l’exercice d’autres droits consacrés par le Pacte ». Le Comité\nsouligne « l’importance de la liberté d’expression pour la direction des affaires publiques et\npour l’exercice effectif du droit de vote. La communication libre des informations et des\nidées concernant des questions publiques et politiques entre les citoyens, les candidats et les\nreprésentants élus est essentielle. Cela exige une presse et d’autres organes d’information\nlibres, en mesure de commenter toute question publique et capables d’informer l’opinion\npublique sans censure ni restriction ». Les restrictions prévues à l’article 19 (3) doivent,\ntoujours selon le Comité des droits de l’homme, être fixées par la loi961, être « nécessaires\npour atteindre un objectif légitime » et proportionnelles.\n(ii)      Droits régional et sous-régional"},{"id":"a-hrc-36-crp-1-p0502","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"502","seq":504,"section":"6. Liberté d’expression","text":"L’article 9 de la Charte africaine des droits de l’homme et des peuples garantit le droit\nà l'information et celui de toute personne « d'exprimer et de diffuser ses opinions dans le\ncadre des lois et règlements ». Le Traité instituant la CAE prévoit pour sa part que ses États\nparties assurent « la promotion et la protection des droits de l’homme et des peuples\nconformément aux dispositions de la Charte africaine des droits de l’homme et des peuples\n»962. De la même manière, le Pacte sur la paix, la stabilité et le développement dans la région\ndes Grands Lacs est accompagné d’un « Protocole sur la gestion de l’information et de la\ncommunication » qui garantit la liberté d’expression et de la presse.\n(iii)     Droit national"},{"id":"a-hrc-36-crp-1-p0503","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"503","seq":505,"section":"6. Liberté d’expression","text":"La liberté d’expression est inscrite dans la Constitution du Burundi.963 Comme pour\nles autres libertés publiques, le Code pénal burundais prévoit que « tout acte arbitraire et\nattentatoire aux libertés et aux droits garantis aux particuliers par des lois, décrets,\nordonnances et arrêtés, ordonné ou exécuté par un fonctionnaire ou officier public, par un\ndépositaire ou agent de l’autorité ou de la force publique, sera puni d’une servitude pénale de\nquinze jours à un an et d’une amende de dix mille francs964 ou d’une de ces peines seulement\n»965."},{"id":"a-hrc-36-crp-1-p0504","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"504","seq":506,"section":"6. Liberté d’expression","text":"En mai 2015, le Parlement burundais a adopté loi n° 1/15966 modifiant la loi n° 1/11\ndu 4 juin 2013 qui obligeait les journalistes à communiquer leurs sources dans certains cas et\nlimitait la possibilité pour les médias de publier des informations sur les autorités nationales,\nles forces de l’ordre et les questions économiques et financières967. La nouvelle loi supprime\nces dispositions qui avaient été critiquées notamment par le Rapporteur spécial des Nations\nUnies sur la situation des défenseurs des droits de l’homme968 et par le Comité des droits de\nl’homme à l’occasion de l’examen du second rapport périodique du Burundi en 2014969. Elle\ngarantit la protection des sources ainsi que le droit pour les journalistes d’enquêter et de\ncommenter librement sur les faits de la vie publique970."},{"id":"a-hrc-36-crp-1-p0505","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"505","seq":507,"section":"6. Liberté d’expression","text":"La loi n°1/15 maintient par ailleurs d’importants pouvoirs au Conseil national de la\ncommunication (CNC), l’organe national de régulation des médias présidé depuis mars 2016\npar Karenga Ramadhani. Le CNC délivre des cartes de presse aux journalistes burundais et\nl’accréditation aux journalistes étrangers, a le pouvoir de les retirer ou d’adresser des « mises\nen garde à tout organe de presse ou journalistes défaillants » et de suspendre « la circulation,\nla distribution ou la vente de journaux, de périodiques ou de tout autre support d’information,\nla diffusion d’une émission, l’exploitation d’une station de radio ou de télévision ou d’une\nagence de presse quand ils ne se conforment pas à la loi »971. L’organisation et le\nfonctionnement du CNC, régis par la loi n°1/03 du 24 janvier 2013 portant révision de la loi\nn° 1/18 du 25 septembre 2007, sont caractérisés par une sujétion au pouvoir exécutif. Les\nmembres du CNC sont nommés par le Président de la République en concertation avec les\nVice-présidents, pour une durée de trois ans renouvelables."},{"id":"a-hrc-36-crp-1-p0506","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"506","seq":508,"section":"6. Liberté d’expression","text":"Le nouveau code électoral, adopté le 3 juin 2014, garantit la liberté de la propagande\nélectorale et la libre utilisation des médias par les candidats et les partis politiques, sous\nréserve du respect de l’ordre public et de l’interdiction des déclarations injurieuses ou\ndiffamatoires972.\n(b)     Violations de la liberté d’expression"},{"id":"a-hrc-36-crp-1-p0507","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"507","seq":509,"section":"6. Liberté d’expression","text":"La radio est la source principale d’information au Burundi, sachant que la télévision\nest trop chère pour la plupart des Burundais et que les journaux et les médias en ligne ont une\ncouverture moindre du fait du faible taux d’alphabétisation de la population. Jusqu’en avril\n2015, le Burundi était caractérisé par un pluralisme médiatique. Les médias s’exprimaient\nrelativement librement, en particulier pour rapporter des allégations de violation des droits de\nl’homme, en dépit d’intimidations répétées de la part du Gouvernement. En 2014, le Comité\ndes droits de l’homme s’était inquiété des « informations faisant état de menaces, y compris\nphysiques, et d’actes de harcèlement et d’intimidation dont les journalistes [...] font l’objet de\nla part des forces de police et de sécurité. » Le Rapporteur spécial des Nations Unies sur la\nsituation des défenseurs des droits de l’homme avait noté, lors de sa visite au Burundi en\nnovembre 2014, que « certaines catégories de défenseurs des droits sont particulièrement\nexposées, y compris des journalistes »973. En 2014 et au début de l’année 2015, les autorités\nburundaises se sont montrées particulièrement sensibles à des reportages jugés hostiles,\nréalisés par des journalistes indépendants. À titre d’exemple, pas moins de quatre journalistes\nont été convoqués en 2014 au Parquet après avoir enquêté sur des allégations de distribution\nd’armes à des Imbonerakure974. Le 20 janvier 2015, Bob Rugurika, directeur de la RPA, l’une\ndes radios les plus écoutées du pays, a été arrêté pour avoir diffusé un reportage mettant en\ncause des officiers supérieurs du SNR dans l’assassinat de trois religieuses italiennes en\nseptembre 2014. Il a été libéré sous caution le 19 février 2015, et a fui le Burundi en mai\n2015."},{"id":"a-hrc-36-crp-1-p0508","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"508","seq":510,"section":"6. Liberté d’expression","text":"Jusqu’en 2015, le pays comptait, à côté de la Radio-Télévision nationale du Burundi\n(RTNB), plusieurs chaînes de radios privées, dont les quatre principales étaient Radio\nBonesha FM, Radio Isanganiro, Radio publique africaine (RPA), et Radio Renaissance, qui\navait également une chaîne de télévision. Le Gouvernement a maintes fois accusé ces quatre\nradios d’être proches de l’opposition politique, mais elles ont pu continuer à émettre."},{"id":"a-hrc-36-crp-1-p0509","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"509","seq":511,"section":"6. Liberté d’expression","text":"Cette situation a toutefois changé à partir d’avril et mai 2015, quand le Gouvernement\nburundais a fermé la plupart des principales radios privées. À l’exception de la Radio\nIsanganiro, ces radios n’ont pas été autorisées à rouvrir après avoir été saccagées lors du coup\nd’État de mai 2015. La pression exercée par les autorités sur les médias a été constante.\nDurant la période couverte par le mandat de la Commission, les journalistes ont été menacés,\nemprisonnés, ont subi des mauvais traitements, et beaucoup d’entre eux ont été forcés à\nl’exil. S’agissant de la presse écrite, Iwacu est le seul média privé d’envergure à avoir pu\ncontinuer à fonctionner depuis le Burundi975, et ce en dépit du départ de son directeur en exil,\nde la disparition de l’un de ses journalistes976, et de pressions et de menaces à l’encontre de\ncertains de ses reporters.\n(i)   Pressions, contrôle et fermeture de médias"},{"id":"a-hrc-36-crp-1-p0510","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"510","seq":512,"section":"6. Liberté d’expression","text":"Le changement d’attitude du Gouvernement vis-à-vis des médias privés a été\nconsécutif aux premières manifestations contre l’annonce de la candidature de Pierre\nNkurunziza à l’élection présidentielle, en avril 2015. Le 27 avril 2015, le Gouvernement a\nfermé la RPA, ainsi que la Maison de la presse qui hébergeait le studio de la plateforme «\nSynergie des médias » regroupant les principales radios privées du Burundi. Un témoin\ninterrogé par la Commission a décrit cet événement :\n« Le 27 avril 2015, [...] [un commissaire de police] est venu avec des policiers pour\nfermer la Maison de la presse. Il a aussi fermé la RPA l’après-midi du même jour [...]\nIl était avec des hommes du SNR en tenue civile qui donnaient des ordres […]\n[L’Administrateur général du SNR] était dans les alentours »977."},{"id":"a-hrc-36-crp-1-p0511","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"511","seq":513,"section":"6. Liberté d’expression","text":"Une nouvelle étape a été franchie à partir de la tentative de coup d’État. Le 13 mai\n2015, la RPA, qui avait momentanément recommencé à diffuser pendant le coup d’État, a été\nattaquée et incendiée. Le même jour, les radios privées Bonesha FM, Isanganiro et la Radio-\nTélévision Renaissance ont été pillées, brûlées ou détruites, tout comme la Radio-Télévision\nRema, proche du parti au pouvoir978. Le 14 mai 2015, le siège de la RTNB a cessé\ntemporairement d’émettre après avoir été le théâtre de combats à l’arme lourde entre les\nforces loyalistes et les militaires impliqués dans la tentative de coup d’État."},{"id":"a-hrc-36-crp-1-p0512","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"512","seq":514,"section":"6. Liberté d’expression","text":"Suite à ces événements, le Procureur général de la République, Valentin Bagorikunda,\na lancé deux enquêtes : l’une sur les destructions subies par les médias et l’autre visant les\nmédias privés ayant diffusé le message des dirigeants de la tentative du coup d’État, à savoir\nles radios Isanganiro, Bonesha FM, RPA et Radio-Télévision Renaissance. Le résultat de ces\nenquêtes n’est toujours pas connu à ce jour."},{"id":"a-hrc-36-crp-1-p0513","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"513","seq":515,"section":"6. Liberté d’expression","text":"Le 10 juin 2015, le Procureur général de la République a adressé une lettre à la\nprésidente de la Maison de la presse979, autorisant la réouverture de son studio, mais notant\nque « pour des raisons d’enquêtes judiciaires en cours, l’accès à ce studio reste strictement\ninterdit aux médias suivants et ainsi qu’à leurs personnels respectifs : la Radio Bonesha FM,\nla Radio-Télévision Renaissance, la Radio RPA (Bujumbura et Ngozi), la Radio Isanganiro et\nla Radio Humuriza FM ». Cette décision, ainsi que la suspension des radios elles-mêmes, a\neu un impact direct sur la liberté des Burundais à recevoir des informations d’autres sources\nque d’organes contrôlés par le Gouvernement."},{"id":"a-hrc-36-crp-1-p0514","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"514","seq":516,"section":"6. Liberté d’expression","text":"La radio Rema a été officiellement autorisée à reprendre ses activités le 19 février\n2016 lors d’une conférence de presse tenue par le CNC. La radio Isanganiro a à cette\noccasion été également autorisée à émettre à nouveau, à condition cependant de signer un\nacte d'engagement avec le CNC en vertu duquel elle doit fournir une information « équilibrée\net objective » et ne pas porter atteinte à la sécurité du pays980. Une nouvelle équipe de\ndirection a été nommée en remplacement de l’ancienne équipe dont la directrice, le rédacteur-\nen-chef et plusieurs autres journalistes restent en exil à ce jour.\nl’Agence burundaise de presse (ABP). Plusieurs autres médias publient des articles uniquement en ligne\nou sur des comptes Twitter, par exemple Ikiriho, proche du Gouvernement."},{"id":"a-hrc-36-crp-1-p0515","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"515","seq":517,"section":"6. Liberté d’expression","text":"La Radio Isanganiro a néanmoins continué à faire l’objet de pressions. Le 26 octobre\n2016, une circulaire signée par le président du CNC a notifié à la radio la suspension pour un\nmois de son émission « Karadiridimba » (« Ce qui avance »), un programme donnant la\nparole à la diaspora burundaise, pour avoir diffusé « une chanson qui n’est pas conforme à\nl’éthique professionnelle et aux valeurs démocratiques et déontologiques ». La chanson avait\npour titre : « Droits de l'homme pour les journalistes ». Le 4 avril 2017, Joseph Nsabiyabandi,\nle rédacteur en chef de la radio, a été convoqué dans les locaux du SNR à Bujumbura où il a\nété interrogé entre autres sur sa supposée collaboration avec les radios burundaises en exil,\nHumura et Inzamba mises en place par les journalistes des radios RPA, Isanganiro, Bonesha\net Renaissance suite à la destruction et la fermeture de leurs radios respectives et leur exil en\n2015981."},{"id":"a-hrc-36-crp-1-p0516","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"516","seq":518,"section":"6. Liberté d’expression","text":"La pression des autorités burundaises sur les médias privés a continué de se manifester\nen 2017. Le 24 octobre 2016, le Ministre de l’intérieur et de la formation patriotique, Pascal\nBarandagiye, a signé une ordonnance annonçant la suspension provisoire de l’Union\nburundaise des journalistes (UBJ) et quatre autres associations sans but lucratif qui seraient\n« de nature à perturber l’ordre et la sûreté de l’État » 982. L’UBJ, un syndicat de journalistes,\nn’avait cessé de dénoncer les atteintes à la liberté de la presse. Elle n’a pas pu reprendre ses\nactivités au Burundi au moment de la rédaction du présent rapport. Son président, comme\ntant d’autres journalistes, vit en exil depuis mai 2015."},{"id":"a-hrc-36-crp-1-p0517","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"517","seq":519,"section":"6. Liberté d’expression","text":"Le 21 juin 2017, le CNC a annoncé dans un communiqué que, plusieurs médias\nn’ayant pas signé le cahier des charges requis pour opérer au Burundi, il invitait tous les\nmédias burundais à mettre en ordre leur situation avant le 31 juillet 2017983. Le 3 juillet 2017,\nle CNC a également appelé la Radio Bonesha FM, la Radio-télévision Renaissance et la RPA\nà « régulariser leur situation avant que le CNC ne prenne une décision administrative\nappropriée », en faisant référence au contentieux que ces médias auraient avec la justice984.\nComme décrit plus bas985, la plupart des dirigeants de ces radios restent sous le coup de\nmandats d’arrêt internationaux. Le 12 juillet 2017, par voie d’ordonnance, le Ministre de\nl’intérieur, se basant sur une note transmise le 15 mars 2017 par le Procureur général de la\nRépublique au CNC faisant état de condamnations éventuelles dans le cadre des dossiers en\ncours, a annoncé la suspension de la RPA « attendu qu’il est évident [que celle-ci] s’est\nrendue coupable de trouble à l’ordre publique et d’atteinte à la sûreté de l’État »986."},{"id":"a-hrc-36-crp-1-p0518","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"518","seq":520,"section":"6. Liberté d’expression","text":"Par ailleurs, les autorités burundaises ont renforcé leur mainmise sur les médias\npublics. Comme l’a souligné un témoin interrogé par la Commission :\n« La mission de la RTNB est d’accompagner l’action du Gouvernement et pour ce\nfaire, elle mobilise des ressources pour couvrir sur le terrain les activités du Président\nde la République, du Vice-Président, du Président de l’Assemblée nationale et du\nSénat [...] À la fin de l’année 2016, le Président de la République a convoqué l’ancien\nDirecteur général de la RTNB, le Directeur de la radio nationale, le Directeur de la\ntélévision nationale et le ministre de l’Information pour leur rappeler le rôle\nimportant qu’ils jouent dans la diffusion d’informations favorables au pouvoir et au\nCNDD-FDD. Il a également insisté sur la nécessité de dissimuler l’information sur la\nréalité de la situation socioéconomique du pays »987.\n(ii)     Pressions, menaces et violences contre des journalistes"},{"id":"a-hrc-36-crp-1-p0519","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"519","seq":521,"section":"6. Liberté d’expression","text":"Outre la pression exercée sur les médias depuis avril 2015, les journalistes burundais\nont été harcelés, menacés et violentés à plusieurs reprises. Un grand nombre d’entre eux\ntravaillant pour des médias privés ont été forcés de quitter le pays et restent en exil."},{"id":"a-hrc-36-crp-1-p0520","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"520","seq":522,"section":"6. Liberté d’expression","text":"Le harcèlement et les menaces par des autorités contre les journalistes se sont\namplifiés après l’annonce officielle de la candidature de Pierre Nkurunziza et suite à la\nfermeture de la radio RPA le 27 avril 2015. Un témoin interrogé par la Commission a\ndéclaré :\n« Après la fermeture de la RPA, il y a eu une chasse à l’homme contre les journalistes\nde la RPA. On a cherché à les arrêter. On cherchait aussi à récupérer leur matériel\n[…] Une équipe du SNR et de la police est venue me chercher dans ma maison. Je\nn’étais pas là »988.\nUne autre source a témoigné : « Le 27 avril 2015, j’ai reçu un coup de téléphone d’un\nvoisin qui m’a demandé si j’attendais des personnes chez moi car il y avait des\nindividus qui avaient demandé quand je rentrais. Je lui ai dit que je n’attendais\npersonne. J’ai alors appelé un ami policier qui travaillait au poste de police près de\nchez moi. Il m’a dit : « Je voulais justement t’appeler. Tu dois faire attention car il y a\ndes gens qui veulent t’éliminer ». Il a ajouté que je ne devais pas rentrer directement\nchez moi […] Je suis resté dans la clandestinité. J’ai aussi entendu que ma famille\nétait ciblée […] J’ai déplacé ma famille dans un autre endroit »989."},{"id":"a-hrc-36-crp-1-p0521","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"521","seq":523,"section":"6. Liberté d’expression","text":"Cette situation s’est aggravée après la tentative de coup d’État du 13 mai 2015 lorsque\nles autorités ont accusé plusieurs radios privées d’être de collusion avec les « putschistes ».\nUn journaliste d’une radio privée a témoigné :\n« [Après la tentative de coup d’État], les policiers me menaçaient [...] et me disaient\nde faire attention car si on m’attrapait je serais tué [...] Des amis au sein du SNR, du\nGouvernement et des policiers passaient chez moi avant le coup d’État car nous\nétions de grands amis. Après, nous sommes devenus des ennemis jurés jusqu’au jour\noù quelqu’un m’a dit : « Faites attention car des réunions se tiennent par-ci par-là\npour vous arrêter » »990."},{"id":"a-hrc-36-crp-1-p0522","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"522","seq":524,"section":"6. Liberté d’expression","text":"Le 22 mai 2015, le directeur de la Radio-Télévision Renaissance, Innocent Muhozi, a\nété convoqué par le Parquet et a comparu devant le substitut du Procureur général de la\nRépublique pour s'expliquer sur ses activités le jour de la tentative de coup d’État et la\ndéclaration du Général Niyombare diffusée à la radio. Aucune charge n’a été retenue contre\nlui991."},{"id":"a-hrc-36-crp-1-p0523","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"523","seq":525,"section":"6. Liberté d’expression","text":"Durant les mois suivants, les violences contre des journalistes, notamment par des\nagents des corps de défense et de sécurité, ont gagné en ampleur et en gravité. Le 2 août\n2015, des agents du SNR ont arrêté et frappé devant de nombreux témoins le correspondant\nde Radio France internationale (RFI) et de l’Agence France Presse (AFP), Esdras\nNdikumana, alors qu’il prenait des photos sur le lieu de l’assassinat du Général Adolphe\nNshimirimana à Bujumbura. Le Conseiller en communication du Président, Willy Nyamitwe,\nqui se trouvait à quelques mètres de la scène, n’aurait rien fait992. Des agents des services de\nrenseignement ont ensuite emmené Esdras Ndikumana au siège du SNR où il a été\nviolemment battu avec des bâtons et des barres de fer, y compris sur la plante des pieds, et où\ndes agents du SNR, en plus de lui voler ses effets personnels, lui ont cassé le doigt pour lui\narracher sa bague. Selon les informations reçues par la Commission, Esdras Ndikumana a par\nla suite été présenté à un des directeurs du SNR qui lui aurait répondu, alors qu’il se plaignait\nd’avoir été maltraité : « Toi, tu as de la chance de t’en sortir vivant »993. La Présidence de la\nRépublique a publié le 13 août 2015 un communiqué exprimant la volonté des autorités\nburundaises de « déterminer d’urgence ces actes et les circonstances de ces actes d’un autre\nâge, afin que les auteurs soient poursuivis et châtiés conformément à la loi »994. Malgré une\nplainte déposée en octobre 2015 par la victime, RFI et l’AFP, aucun suspect, à la\nconnaissance de la Commission, n’a été appréhendé à ce jour."},{"id":"a-hrc-36-crp-1-p0524","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"524","seq":526,"section":"6. Liberté d’expression","text":"Le 13 octobre 2015, un caméraman de la RTNB, Christophe Nkezabahizi, sa femme,\nsa fille, son fils et son neveu ont été tués par des policiers de l’API à leur domicile à Ngagara\nà Bujumbura995. Les policiers ont tué plusieurs autres habitants du quartier lors de la même\nopération. Des témoignages concordants recueillis par la Commission indiquent que\nChristophe Nkezabahizi aurait été spécifiquement ciblé996. Avant cet incident, le directeur de\nla RTNB avait demandé à Christophe Nkezabahizi de lui remettre tous les enregistrements\nqu’il avait faits des manifestations. Christophe Nkezabahizi aurait fait part à des proches de\nson sentiment d’être suivi, y compris le jour même de son assassinat997."},{"id":"a-hrc-36-crp-1-p0525","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"525","seq":527,"section":"6. Liberté d’expression","text":"La Commission a en outre recueilli le témoignage d’un journaliste qui a décrit les\nactes de torture qu’il a subis au siège du SNR après avoir été arrêté par des policiers en 2015\nà Bujumbura:\n« À l'intérieur [des locaux du SNR], ils ont pris mes chaussures et mes habits. Ils ont\ndéchiré ma chemise […] Là, c'était le calvaire. Ils m'ont dit de m'allonger. Ils ont pris\ndes matraques, des bâtons, des barres de fer. Ils me frappaient n'importe comment,\nd'une façon désordonnée. Il y avait des câbles électriques au plafond, sans lampes. Ils\nprenaient ces câbles et les mettaient sur mon corps, sur mes bras, sur les côtes,\npartout. Beaucoup d'autres hommes entraient et sortaient. Certains étaient en civil,\nd'autres en tenue policière [...] Ils me posaient des questions et me frappaient tout le\ntemps [...]Ils demandaient: « Pourquoi tu es ici? » « Pourquoi tu es toujours au\nBurundi? » [...] Ils me demandaient: « Où étais-tu le 13 mai ? » et me frappaient\nencore »998."},{"id":"a-hrc-36-crp-1-p0526","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"526","seq":528,"section":"6. Liberté d’expression","text":"Le 16 novembre 2015, le directeur du journal Iwacu, Antoine Kaburahe, a été\nconvoqué au Parquet général de la République dans le cadre de l’enquête sur la tentative de\ncoup d’État de mai 2015999. Il a par la suite reçu une seconde convocation, mais informé qu’il\ny avait de grands risques que celle-ci débouche sur une arrestation, il a décidé de fuir le\npays1000. Les autorités ont émis un mandat d’arrêt contre lui suite à son départ."},{"id":"a-hrc-36-crp-1-p0527","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"527","seq":529,"section":"6. Liberté d’expression","text":"Les pressions et la violence exercées contre les journalistes se sont poursuivies en\n2016. Les événements du 11 décembre 2015 et la répression qui a suivi ont rendu les\nautorités particulièrement sensibles au travail effectué par les médias indépendants. Ainsi, le\n28 janvier 2016, le journaliste français du journal Le Monde, Jean-Philippe Rémy, et le\nphotographe britannique, Phil Moore, ont été arrêtés lors d’une opération de police à\nNyakabiga, Mairie de Bujumbura, et conduits au siège du SNR. Ils ont été relâchés le\nlendemain sans qu’aucune charge n’ait été retenue contre eux, mais le matériel saisi lors de\nleur interpellation ne leur a pas été rendu. La Commission a également recueilli le\ntémoignage d’un jeune homme qui a été arrêté, détenu et torturé par le SNR en 2016. Les\nagents qui l’ont interrogé en détention lui ont notamment reproché d’avoir travaillé pour une\nradio privée1001."},{"id":"a-hrc-36-crp-1-p0528","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"528","seq":530,"section":"6. Liberté d’expression","text":"Le 2 février 2016, le Secrétaire général de la Cour suprême du Burundi a publié un\ncommuniqué de presse dressant la liste des « putschistes en fuite à l’étranger et qui font\nl’objet de mandats d’arrêt internationaux ». Dans cette liste, figurent sept journalistes, dont\nInnocent Muhozi, directeur de la Radio-Télé Renaissance, Bob Rugurika, directeur de la\nRPA, Anne Niyuhire, directrice de la Radio Isanganiro, Patrick Nduwimana, directeur de la\nRadio Bonesha FM, Patrick Mitabaro, rédacteur-en-chef de la Radio Isanganiro, Arcade\nHavyarimana, reporter pour la même radio, et Gilbert Niyonkuru, journaliste de la RPA. En\nrevanche, le mandat d’arrêt international émis à l’encontre du directeur d’Iwacu, Antoine\nKaburahe, a été annulé le 19 février 2016, mais celui-ci n’est pas rentré au Burundi, craignant\npour sa sécurité."},{"id":"a-hrc-36-crp-1-p0529","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"529","seq":531,"section":"6. Liberté d’expression","text":"Le 30 mai 2016, un communiqué de presse du Ministère de la sécurité publique a\ncondamné « avec énergie toute personne qui, devançant sciemment le cours normal des\nenquêtes, s’adonne à attribuer chaque acte criminel à qui elle veut pour justifier son penchant,\nses intérêts et convictions politiques à peine voilés, à l’instar du journaliste Esdras\nNdikumana et certains activistes des réseaux sociaux, dans le but de diviser les Burundais et\npromouvoir le crime et la violence »1002."},{"id":"a-hrc-36-crp-1-p0530","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"530","seq":532,"section":"6. Liberté d’expression","text":"Plusieurs journalistes ont été arrêtés au cours de l’année 20161003. D’autres ont été\nvictimes de violence en 2016. La Commission a recueilli un témoignage selon lequel Nestor\nNdayitwayeko, journaliste pour la RPA dans la province de Rutana, a été attaqué dans un bar\ndans la commune de Rutana en juillet 2016. Un haut gradé de la police au niveau provincial\nl’aurait battu, l’accusant de collaborer avec les ennemis du gouvernement. Nestor\nNdayitwayeko a quitté le pays en août 2016. Il est tombé malade et est décédé en novembre\n20161004."},{"id":"a-hrc-36-crp-1-p0531","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"531","seq":533,"section":"6. Liberté d’expression","text":"Le 22 juillet 2016, un journaliste d’Iwacu, Jean Bigirimana, qui travaillait auparavant\nà la radio Rema, a disparu dans la province de Muramvya. Il aurait été aperçu la dernière fois\naccompagné d'agents du SNR1005."},{"id":"a-hrc-36-crp-1-p0532","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"532","seq":534,"section":"6. Liberté d’expression","text":"La Commission a également pris connaissance d’un certain nombre de cas rapportés\nen 2016 par des ONG internationales comme la Fédération internationale des droits de\nl’homme (FIDH)1006, Reporters sans frontières (RSF)1007, Human Rights Watch1008, Amnesty\nInternational1009 et Defend Defenders1010, ainsi que par des organisations nationales comme la\nLigue Iteka1011. Faute de temps, la Commission n’a pas été en mesure de vérifier tous ces cas."},{"id":"a-hrc-36-crp-1-p0533","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"533","seq":535,"section":"6. Liberté d’expression","text":"Lors de la cérémonie organisée à l’occasion de la journée mondiale de la presse le 5\nmai 2017, le Ministre en charge de l’information, Nestor Bankumukunzi, a indiqué que son\nGouvernement espérait le retour au pays des journalistes exilés1012. Cependant, à ce jour, plus\nde 100 journalistes ont trouvé refuge en dehors du Burundi, selon les informations recueillies\npar la Commission. Les journalistes des radios fermées par le Gouvernement, réfugiés au\nRwanda, ont créé les radios Inzamba et Humura1013. Des journalistes ont également créé une\nplateforme sur les médias sociaux sous le nom de SOS Médias1014. Les journalistes\nindépendants restés au Burundi sont quant à eux contraints de faire preuve d’une extrême\nprudence ou de travailler de manière clandestine afin de rassembler des informations qu’ils\ntransmettent ensuite aux médias basés à l’extérieur du pays. Un journaliste a confié à la\nCommission :\n« Nous rapportons 30% de ce que nous savons. Nous travaillons dans un terrain\nminé »1015.\n(iii)     Autres violations de la liberté d’expression"},{"id":"a-hrc-36-crp-1-p0534","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"534","seq":536,"section":"6. Liberté d’expression","text":"Au-delà des restrictions à la liberté des médias et des violations contre les journalistes,\nl’ensemble de la répression mise en œuvre par le Gouvernement peut également être analysé\nsous l’angle de la liberté d’expression de manière plus générale. Comme le démontrent les\nviolations et atteintes décrites dans ce rapport, les victimes incluent des personnes ayant\nparticipé aux manifestations de mai à juin 2015, des sympathisants du mouvement « Halte au\ntroisième mandat », des membres des partis d’opposition ou des individus perçus comme\nopposants. Depuis avril 2015, il est devenu particulièrement périlleux d’exprimer des points\nde vue contraires à ceux des autorités et des instances du parti au pouvoir ou de dénoncer\nleurs exactions. Le 9 juin 2017, le maire de Bujumbura a interdit la tenue d’une conférence\nde presse du groupe parlementaire de la coalition Amizero y'abarundi (« Espoir des\nBurundais ») formé d’une trentaine de députés issus des FNL d'Agathon Rwasa et de\nl’UPRONA. Afin de justifier sa décision, le maire a expliqué que cette coalition n'avait pas\nd'existence légale et qu’à ce titre, ses députés ne pouvaient s'exprimer publiquement, alors\nmême que le groupe siège comme tel au Parlement1016."},{"id":"a-hrc-36-crp-1-p0535","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"535","seq":537,"section":"6. Liberté d’expression","text":"Si le musellement de toute voix discordante a touché principalement les membres de\nl’opposition, le même phénomène a également été constaté au cours des premiers mois de\n2015 au sein du CNDD-FDD à l’encontre des personnes communément appelées\n« frondeurs » qui, à tous les niveaux de direction du parti, se sont opposées à un nouveau\nmandat du Président Nkurunziza. Dix-sept d’entre eux, pour la plupart haut placés dans la\nhiérarchie du parti, ont adressé fin mars 2015 une lettre au Président lui conseillant de ne pas\nse représenter à l’élection présidentielle. La lettre dénonçait également l’influence de l’actuel\nMinistre de la sécurité publique, Alain-Guillaume Bunyoni, et de l’ancien Administrateur\ngénéral du SNR, Adolphe Nshimirimana. D’autres ont exprimé le même point de vue avant et\naprès cette initiative. Parmi les « frondeurs », ceux qui ont persisté dans leur ligne ont été\ndémis de leurs fonctions et persécutés. Certains « frondeurs » avec qui la Commission s’est\nentretenue ont échappé à des assassinats ciblés ou des arrestations et ont été forcés de fuir le\npays1017. L’un d’entre eux a rapporté à la Commission qu’un dirigeant du CNDD-FDD,\nfavorable à un nouveau mandat du Président Nkurunziza, aurait déclaré à cette époque : « la\nchance, c’est de n’être plus dans le maquis. Sinon tous les opposants auraient été\nmassacrés »1018. Certains membres de la famille de ces personnes, restés au pays, ont\négalement été la cible de persécutions1019."},{"id":"a-hrc-36-crp-1-p0536","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"536","seq":538,"section":"6. Liberté d’expression","text":"Les atteintes répétées à la liberté d’expression ont également eu un impact direct sur le\ntravail des organisations de la société civile et en particulier des défenseurs des droits de\nl’homme. La Commission a notamment recueilli le témoignage de membres d’associations de\ndéfense des droits de l’homme qui ont été l’objet de persécution après avoir fait des\ndéclarations publiques sur des allégations de violations des droits de l’homme, comme cela\nest décrit plus loin dans ce rapport1020. L’une d’eux a subi des menaces de mort de la part\nd’un membre du SNR après avoir participé en 2015 à une émission d’une radio\ninternationale1021. Un autre, ayant rapporté des violations des droits de l’homme à une radio,\na été arrêté et torturé par le SNR avant d’être relâché et de fuir le pays1022."},{"id":"a-hrc-36-crp-1-p0537","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"537","seq":539,"section":"6. Liberté d’expression","text":"La restriction à la liberté d’expression a également touché d’autres secteurs de la\nsociété. Par exemple, un professeur d’une université étrangère travaillant en partenariat avec\ndes homologues burundais a noté que ces derniers étaient peu enclins depuis 2015 à\ncommuniquer sur la situation lorsqu’ils étaient au pays de peur que leurs propos ne soient\ninterceptés. Il a noté :\n« Ils semblent ne pas se sentir à l’aise quand ils communiquent par courriel ou\ntéléphone. Ils craignent d’être sur écoute. […] Il y a une paranoïa et une\nméfiance »1023.\n(c)     L’incitation à la discrimination, à l’hostilité ou à la violence\n(i)     Le droit international applicable"},{"id":"a-hrc-36-crp-1-p0538","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"538","seq":540,"section":"6. Liberté d’expression","text":"L’article 20 du PIDCP dispose que : « (1) Toute propagande en faveur de la guerre est\ninterdite par la loi. (2) Tout appel à la haine nationale, raciale ou religieuse qui constitue une\nincitation à la discrimination, à l'hostilité ou à la violence est interdit par la loi ». Dans son\nobservation générale n° 11 sur cet article1024, le Comité des droits de l’homme précise que\n« l'interdiction prévue au paragraphe 1 s'étend à toutes les formes de propagande menaçant\nd'entraîner ou entraînant un acte d'agression ou une rupture de la paix, en violation de la\nCharte des Nations Unies, tandis que le paragraphe 2 vise tout appel à la haine nationale,\nraciale ou religieuse qui constitue une incitation à la discrimination, à l'hostilité ou à la\nviolence, que cette propagande ou cet appel ait des objectifs d'ordre intérieur ou extérieur par\nrapport à l'État intéressé »1025. Le Comité des droits de l’homme estime en outre que « les\nÉtats parties qui ne l’ont pas encore fait devraient prendre des mesures pour s’acquitter des\nobligations énoncées à l’article 20, et qu’ils devraient eux-mêmes s’abstenir de toute\npropagande ou de tout appel de ce genre »1026."},{"id":"a-hrc-36-crp-1-p0539","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"539","seq":541,"section":"6. Liberté d’expression","text":"De son côté, la CIEDR prévoit que « les États parties condamnent toute propagande et\ntoutes organisations qui s'inspirent d'idées ou de théories fondées sur la supériorité d'une race\nou d'un groupe de personnes d'une certaine couleur ou d'une certaine origine ethnique, ou qui\nprétendent justifier ou encourager toute forme de haine et de discrimination raciales »1027. La\nConvention exige à cet effet que les États parties adoptent des mesures positives, notamment\nen qualifiant de délits punissables par la loi toute diffusion d'idées fondées sur la supériorité\nou la haine raciale, toute incitation à la discrimination raciale, ainsi que tous actes de\nviolence, ou provocation à de tels actes ; mais aussi en ne permettant pas « aux autorités\npubliques ni aux institutions publiques, nationales ou locales, d'inciter à la discrimination\nraciale ou de l'encourager »1028.\n(ii)      Le droit national : un arsenal législatif adapté"},{"id":"a-hrc-36-crp-1-p0540","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"540","seq":542,"section":"6. Liberté d’expression","text":"Dans son observation générale n° 11, le Comité des droits de l’homme a précisé que\npour que l'article 20 du PIDCP « produise tous ses effets, il faudrait qu'une loi indique\nclairement que la propagande et l'appel qui y sont décrits sont contraires à l'ordre public, et\nprescrive une sanction appropriée en cas de violation ». Le droit burundais remplit cette\nexigence en prohibant et punissant les discours de haine raciale ou ethnique. L’article 253 du\nCode pénal prévoit en effet que « quiconque a manifesté de l’aversion ou de la haine raciale\nou ethnique ou aurait incité ou encouragé, ou commis un acte de nature à provoquer cette\naversion ou cette haine, est puni d’une servitude pénale de six mois à deux ans et d’une\namende de dix mille francs (soit environ six dollars américains) à cent mille francs (soit\nenviron 57 dollars américains) ou d’une de ces peines seulement »."},{"id":"a-hrc-36-crp-1-p0541","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"541","seq":543,"section":"6. Liberté d’expression","text":"L’article 78 de la Constitution vise quant à lui les partis politiques qui, selon ses\ntermes, « ne peuvent prôner la violence, l’exclusion et la haine sous toutes leurs formes,\nnotamment celles basées sur l’appartenance ethnique, régionale, religieuse ou de genre ». De\nla même manière, la loi n° 1/010 du 10 septembre 2011 régissant les partis politiques oblige\ntout parti à mettre en avant, notamment la proscription de l’intolérance, l’ethnicisme, le\nrégionalisme, la xénophobie et du recours à la violence sous toutes ses formes1029. La loi\nprévoit également que les partis politiques s’engagent par écrit à lutter contre toute idéologie\npolitique et tout acte visant à encourager la violence, la haine ou la discrimination basée,\nentre autres, sur l’appartenance ethnique, la région, le genre et la religion1030.\n(iii)     Appels à la lutte armée par des dirigeants ou des groupes armés d’opposition"},{"id":"a-hrc-36-crp-1-p0542","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"542","seq":544,"section":"6. Liberté d’expression","text":"La Commission a documenté des appels clairs et directs à la lutte armée contre le\nGouvernement du Burundi de la part de groupes armés d’opposition ainsi que d’un dirigeant\nde parti d’opposition."},{"id":"a-hrc-36-crp-1-p0543","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"543","seq":545,"section":"6. Liberté d’expression","text":"Dès sa constitution en décembre 2015, le FOREBU1031 a annoncé vouloir « chasser\npar la force Nkurunziza du pouvoir pour restaurer l’Accord d’Arusha et la démocratie au\nBurundi »1032. Son dirigeant, Godefroid Niyombare, a récemment déclaré dans un entretien\naccordé à l’hebdomadaire Jeune Afrique, le 15 mai 2017 : « Pour les FOREBU, il n’est pas\nexclu de passer un jour à la lutte armée. Pour l’heure, nous nous sommes limités à quelques\nopérations ponctuelles contre des installations militaires. La plus importante, en décembre\n2015, a mal tourné car nous n’étions pas prêts. Nous nous organisons donc afin d’être\nopérationnels le jour venu » 1033."},{"id":"a-hrc-36-crp-1-p0544","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"544","seq":546,"section":"6. Liberté d’expression","text":"Le 31 janvier 2016, le RED-Tabara1034 a pour sa part lancé un « appel solennel et\npressant à tous les Burundais en général, à la diaspora en particulier et aux vrais amis du\nBurundi afin qu’ils contribuent à cette lutte armée que vient de nous imposer Pierre\nNkurunziza » 1035. Son chef d’état-major, Melchiade Biremba, a déclaré le 23 février 2016 à\nJeune Afrique : « Nous avons décidé de prendre les armes sans tenir compte des visites des\nNations Unies ou des chefs d’État africains, parce que nous sommes convaincus que le départ\nde Nkurunziza ne pourra pas être obtenu par la négociation. Quand notre objectif sera atteint,\nnous déposerons les armes »1036."},{"id":"a-hrc-36-crp-1-p0545","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"545","seq":547,"section":"6. Liberté d’expression","text":"Alexis Sinduhije, président du parti d’opposition MSD qui aurait des liens avec le\nRED-Tabara, a affirmé dans un entretien à la radio allemande Deutsche Welle le 14 janvier\n2016 : « Je soutiens toute activité contre Nkurunziza, qu’elle soit armée, qu’elle soit\npacifique, qu’elle soit même silencieuse. C’est clair »1037. Il a toutefois réfuté par la suite être\nà la tête d’un groupe armé1038."},{"id":"a-hrc-36-crp-1-p0546","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"546","seq":548,"section":"6. Liberté d’expression","text":"Dans un communiqué du 16 mai 2015, les FNL-Isidore Nibizi et Aloys Nzabampema\nont fait mention d’un « usage de la force » pour désarmer les Imbonerakure et sortir de la\ncrise que traverse le Burundi1039.\n(iv)     Appels à la haine nationale, raciale ou religieuse qui constituent une incitation à la\ndiscrimination, à l’hostilité, ou à la violence"},{"id":"a-hrc-36-crp-1-p0547","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"547","seq":549,"section":"6. Liberté d’expression","text":"La Commission a documenté des appels à la haine constituant une incitation à\nl’hostilité ou la violence contre les opposants au Gouvernement, ces derniers incluant aussi\nbien des membres de partis d’opposition, les manifestants contre un nouveau mandat de\nPrésident de la République ou toute personne s’étant prononcée contre les choix et la\npolitique du Gouvernement, ou encore les combattants ayant rejoint les rangs des groupes\narmés d’opposition. Ces appels ont été proférés par des agents de l’État, des responsables\nlocaux jusqu’à des titulaires de plus hautes fonctions, et des membres du CNDD-FDD."},{"id":"a-hrc-36-crp-1-p0548","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"548","seq":550,"section":"6. Liberté d’expression","text":"Ces appels, qui ont pu être constatés auparavant, se sont multipliés à partir d’avril\n2015 dans un contexte électoral et post-électoral particulièrement tendu, marqué par des actes\nde violence tant du fait d’agents de l’État que de groupes armés ou de personnes non\nidentifiées. En novembre 2015, le Ministre de la sécurité publique, Alain Guillaume Bunyoni,\naurait affirmé, dans un discours rapporté par les médias et dont la Commission a pu obtenir\nune traduction: « Même si les forces de l’ordre ne parvenaient pas à ramener la sécurité, on a\nune population de neuf millions de personnes à qui il suffit de faire signe [...] En quelques\nminutes, ils seraient ici [...] Qui survivrait alors parmi ceux qui n’accepteraient pas d’aller au\nmême pas ? » 1040."},{"id":"a-hrc-36-crp-1-p0549","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"549","seq":551,"section":"6. Liberté d’expression","text":"Le Président Nkurunziza aurait lui-même promis dans un discours tenu à Bubanza le\n14 janvier 2016 : « Le général Rodrigue Bunyoni1041 est mort comme un chien parce qu’il\nétait contre le pouvoir en place. Tous ses compagnons, vous le verrez, vont bientôt mourir de\nla même façon »1042. À la fin de l’année 2016, lors d’une « croisade de prières », le Président\naurait répété, selon des témoins présents à Gitega le 28 décembre 2016 et à Rutana le 30\ndécembre 2016, que le « feu divin » détruirait « tous les Burundais qui ont refusé que le\nBurundi devienne bientôt un royaume de Dieu à travers ses dirigeants élus par le peuple »1043.\nPlus récemment encore, le Chef de l’État aurait, selon plusieurs témoins, été plus direct en\ndéclarant lors d’une réunion publique le 24 février 2017 à Bubanza à l’occasion de travaux\ncommunautaires : « Pour tous les récalcitrants, nous allons trouver une bonne cure, comme\nnous l’avons fait en 2015. Que tous les enfants le sachent, qu’ils grandissent avec des pierres\nà lancer contre toute personne qui est contre les institutions élues par les Burundais »1044."},{"id":"a-hrc-36-crp-1-p0550","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"550","seq":552,"section":"6. Liberté d’expression","text":"La Commission a noté d’autres appels à anéantir les opposants de la part de hauts\ndignitaires, de responsables locaux de l’administration, des forces de sécurité, ou du CNDD-\nFDD. À titre d’exemple, le Président de l’Assemblée nationale, Pascal Nyabenda, aurait\ndéclaré, le 6 août 2016, durant des travaux communautaires à Bubanza : « Il faut étouffer1045\ntous ceux qui se cachent derrière l’insurrection [contre Pierre Nkurunziza] et ceux qui sont en\nfaveur d’un Gouvernement de transition »1046."},{"id":"a-hrc-36-crp-1-p0551","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"551","seq":553,"section":"6. Liberté d’expression","text":"La Commission a également documenté de nombreux chants entonnés par des\nImbonerakure qui constituent des appels clairs à la violence, y compris sexuelle, contre des\nopposants1047. Ces chants, scandés lors de travaux communautaires, d’exercices physiques, de\nmarches ou de manifestations, entraînent la responsabilité de l’État burundais dans la mesure\noù il ne fait rien pour les empêcher, ni pour punir leurs auteurs."},{"id":"a-hrc-36-crp-1-p0552","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"552","seq":554,"section":"6. Liberté d’expression","text":"En avril 2017, une vidéo a circulé sur les médias sociaux montrant une centaine\nd’Imbonerakure de la commune de Ntega (province de Kirundo) répétant une douzaine de\nfois un chant appelant à « engrosser les opposantes pour qu’elles donnent naissance à des\nImbonerakure »1048. Suite à la condamnation du Haut-Commissaire des Nations Unies aux\ndroits de l’homme1049, la Secrétaire nationale chargée de l’information et de la\ncommunication du CNDD-FDD a promis des sanctions contre les fautifs1050. Dans sa\ndéclaration devant le Conseil des droits de l’homme le 15 juin 2017, le Représentant\npermanent du Burundi à Genève a indiqué qu’une instruction avait été ouverte sous la\nréférence D15/79/2017/NG. Toutefois, la Commission n’a reçu aucune information sur la\nréalité de ces poursuites malgré l’obligation de l’État d’agir. Au contraire, le Premier Vice-\nPrésident de la République a considéré ces chants comme parties intégrantes de la culture\nburundaise et en a minimisé l’impact dans un entretien accordé à la radio en ligne Bujumbura\nInternational 1, le 21 mai 20171051. Le Premier Vice-Président aurait, selon des témoins\nprésents, tenu le même type de propos lors du lancement du plan stratégique de la CNIDH, le\n25 avril 2017, à Bujumbura1052. L’Ombudsman, Édouard Nduwimana, a lui aussi minimisé la\nteneur de ces chants dans un entretien accordé le 26 mai 2017 au site internet Ikiriho en\ndéclarant : « N’eût été le contexte plutôt politique ou l’appréhension que certains ont sur les\nImbonerakure, cette chanson n’avait rien de mal. Quand je dis « Tera inda\numukeba » (engrosse un adversaire), ça ne veut pas dire les violer : on peut engrosser sans\nvioler. Des chansons pareilles ont été chantées depuis longtemps et sous d’autres\ncirconstances sans altérer l’opinion […] la chanson comme telle va dans le sens de l’intention\ndes Imbonerakure de rassembler pour que finalement tout le monde, tous les jeunes puissent\ndevenir des Imbonerakure et c’est de bonne guerre en politique. S’ils peuvent le faire, c’est\ntant mieux. Mais si cela se faisait en violant, là ça serait très dangereux. Mais « Gutera\ninda » et violer, c’est différent. Vous savez plutôt, les Imbonerakure seraient très contents de\nse marier avec les filles de l’opposition pour qu’après elles puissent mettre au monde des\nImbonerakure »1053."},{"id":"a-hrc-36-crp-1-p0553","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"553","seq":555,"section":"6. Liberté d’expression","text":"La Commission a documenté d’autres cas où un chant semblable appelant à nouveau à\n« engrosser les opposantes » a été entonné par des Imbonerakure, notamment le 6 mai 2017 à\nBujumbura près de la place de l’Indépendance par un petit groupe se rendant à un événement\norganisé par le CNDD-FDD1054. De nombreux autres chants scandés par des Imbonerakure\nou des membres du CNDD-FDD que la Commission a pu documenter depuis avril 2015 n’en\nsont pas moins graves. Ils appellent à brutaliser, voire exterminer les opposants au parti au\npouvoir et au Gouvernement. Certaines expressions reviennent dans ces chants, comme : «\npunissez-les », « piétinez-les », « lessivez-les », écrasez-les » ou « brûlez-les »1055."},{"id":"a-hrc-36-crp-1-p0554","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"554","seq":556,"section":"6. Liberté d’expression","text":"Le Haut-Commissaire des Nations Unies aux droits de l’homme, dans un communiqué\ndu 18 avril 2017 en réaction à la vidéo mentionnée plus haut, a également cité des chants\nsimilaires qui auraient été entonnés par des Imbonerakure le 1er avril 2017 lors d’un défilé\ndans la province de Kayanza, le 8 avril 2017 lors de l’inauguration d’une antenne du CNDD-\nFDD dans la province de Ruyigi, ainsi que plusieurs fois en fin de semaine durant des\nréunions d’Imbonerakure dans la province de Makamba1056."},{"id":"a-hrc-36-crp-1-p0555","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"555","seq":557,"section":"6. Liberté d’expression","text":"La Commission a noté l’utilisation de noms d’animaux visant à déshumaniser les\nopposants dans des discours tenus par des responsables de l’État ou du CNDD-FDD ainsi que\ndans des chants entonnés par des membres du CNDD-FDD, en particulier des\nImbonerakure1057. Les termes de « chiens » ou « chiens errants » reviennent le plus souvent.\nPar exemple, le 11 février 2017, selon des témoins présents, le Président du Sénat aurait\ndéclaré lors d’une réunion du CNDD-FDD à Kayogoro (province de Makamba) : « Le fait de\nne pas punir les chiens multiplie les chiens errants et décharnés ». Le Gouverneur de la\nprovince Rutana aurait dit lors d’une réunion de sécurité au niveau provincial, le 12 janvier\n2016 : « Il faut punir à jamais les ennemis du Burundi. Les membres de l’opposition, ces\nchiens errants et décharnés qui aboient »1058."},{"id":"a-hrc-36-crp-1-p0556","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"556","seq":558,"section":"6. Liberté d’expression","text":"L’emploi de noms d’insectes comme « cafards », « cancrelats », « vers de terre »,\n« fourmis » à plusieurs reprises dans des chants scandés par des Imbonerakure est\nparticulièrement préoccupant car certains ont été utilisés dans le passé pour désigner les\nTutsis, notamment pendant la période qui a précédé le génocide au Rwanda en 1994."},{"id":"a-hrc-36-crp-1-p0557","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"557","seq":559,"section":"6. Liberté d’expression","text":"Une vidéo a circulé sur les médias sociaux, le 30 mai 2017 montrant des fillettes en\nuniforme du parti CNDD-FDD, au milieu d’une grande foule1059. Un animateur leur pose des\nquestions auxquelles elles répondent comme si elles récitaient une leçon. Le dialogue est le\nsuivant :\n« – L’animateur : Avez-vous oublié le passé sombre du pays ?\n– Les enfants : Non, non, on ne l’a pas oublié. Seulement, c’est parce qu’après avoir traversé\nle danger, on oublie souvent ça. Ce qui s’est passé au Burundi en 1965, 1972, 1988, on le\nsait, ainsi que la crise sans précédent de 1993 lorsque le Président Melchior Ndadaye a été\nsauvagement assassiné, le sang de beaucoup de Burundais également été versé.\n– L’animateur : Vous Imbonerakure, considérez-vous que cela est fini ?\n– Les enfants : Surtout pas ! Chassez le naturel, il revient toujours au galop. Ceux qui ne\npensent qu’à leurs intérêts égoïstes sont toujours aux aguets comme des fourmis rouges. Les\nautres m’étonnent lorsqu’ils disent qu’ils font un clin d’œil au Gouvernement. Au contraire,\nils veulent nous nuire sournoisement comme un pou caché dans le pantalon qui pique » 1060."},{"id":"a-hrc-36-crp-1-p0558","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"558","seq":560,"section":"6. Liberté d’expression","text":"Le 30 janvier 2016, une chanson scandée en présence du Président du Sénat à Gitega\ndisait : « Que les cafards ne se multiplient pas sous nos yeux, qu’ils ne deviennent pas forts\nsous nos yeux »1061. Le même chant aurait été entonné à plusieurs autres reprises en janvier\n2016 dans la province de Kirundo par des membres du CNDD-FDD1062."},{"id":"a-hrc-36-crp-1-p0559","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"559","seq":561,"section":"6. Liberté d’expression","text":"Dans certains cas, les discours ont visé les Tutsis de manière explicite. Par exemple, la\nphrase « les Tutsis sont comme les oreilles des chèvres qui n’entendent que lorsqu’elles sont\ngrillées » a été relevée à plusieurs reprises1063. En tout état de cause, l’association souvent\nfaite ou sens-entendue entre les opposants politiques et ce groupe ethnique contribuent à\nentretenir une confusion préoccupante."},{"id":"a-hrc-36-crp-1-p0560","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"560","seq":562,"section":"6. Liberté d’expression","text":"La Commission a aussi noté, dans une moindre mesure, des propos haineux dans des\nchants qui auraient été entonnés par des membres de partis d’opposition, ainsi que dans des\ntracts anonymes trouvés dans plusieurs provinces. Des termes animaliers y ont été utilisés\npour désigner les membres du CNDD-FDD et parfois les Hutus. L’appellation de « chiens »\nrevient ; on trouve également « cochons » ou « taupes ». Le Président Nkurunziza y est\nsouvent assimilé à une « chauve-souris »1064."},{"id":"a-hrc-36-crp-1-p0561","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"561","seq":563,"section":"7. Libertés d’association et de réunion","text":"La liberté d’association est prévue aux articles 20 de la DUDH et 22 du PIDPC. Cette\ndernière disposition précise que : « (1) Toute personne a le droit de s'associer librement avec\nd'autres, y compris le droit de constituer des syndicats et d'y adhérer pour la protection de ses\nintérêts. (2) L'exercice de ce droit ne peut faire l'objet que des seules restrictions prévues par\nla loi et qui sont nécessaires dans une société démocratique, dans l'intérêt de la sécurité\nnationale, de la sûreté publique, de l'ordre public, ou pour protéger la santé ou la moralité\npubliques ou les droits et les libertés d'autrui. Le présent article n'empêche pas de soumettre à\ndes restrictions légales l'exercice de ce droit par les membres des forces armées et de la police\n»."},{"id":"a-hrc-36-crp-1-p0562","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"562","seq":564,"section":"7. Libertés d’association et de réunion","text":"L’article 10 (1) de la Charte africaine des droits de l’homme et des peuples consacre\négalement la liberté d’association, « sous réserve de se conformer aux règles édictées par la\nloi. » L’article 10 (2) précise pour sa part que « nul ne peut être obligé de faire partie d'une\nassociation sous réserve de l'obligation de solidarité prévue à l'article 29 », notamment en vue\nde « préserver et de renforcer l'indépendance nationale et l'intégrité territoriale de la patrie et,\nd'une façon générale, de contribuer à la défense de son pays », particulièrement quand celle-\nci est menacée. La Cour africaine des droits de l’homme et des peuples1065, à l’instar de la\nCommission africaine1066, a interprété cette disposition en faisant de la liberté de ne pas\ns’associer le corollaire de celle de s’associer. La Cour a ainsi rappelé « qu’il y a atteinte à la\nliberté d’association dès lors qu’un individu est contraint de s’associer avec d’autres\npersonnes » car « la liberté d’association signifie que chacun est libre de s’associer et libre de\nne pas le faire »1067.\n(ii)     Droit national : une législation de plus en plus restrictive"},{"id":"a-hrc-36-crp-1-p0563","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"563","seq":565,"section":"7. Libertés d’association et de réunion","text":"L’article 32 de la Constitution dispose que « la liberté de réunion et d’association est\ngarantie, de même que le droit de fonder des associations ou organisations conformément à la\nloi. »"},{"id":"a-hrc-36-crp-1-p0564","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"564","seq":566,"section":"7. Libertés d’association et de réunion","text":"Le régime des associations au Burundi distingue entre les organisations non-\ngouvernementales étrangères (ONGE) et les associations nationales sans but lucratif (ASBL).\nJusqu’en 2017, ces deux types d’associations étaient régis respectivement par la loi n° 1/011\ndu 23 juin 1999 « portant modification du décret-loi n° 1/033 du 22 août 1990 portant cadre\ngénéral de coopération entre la République du Burundi et les organisations non-\ngouvernementales étrangères », et par le décret-loi n° 1/11 du 18 avril 1992 « portant cadre\norganique des associations sans but lucratif ». Ce dernier texte avait fait l’objet en 2015 de\ncritiques de la part du Rapporteur spécial sur la situation des défenseurs des droits de\nl’homme qui regrettait « un certain nombre de dispositions préjudiciables au mouvement\nassociatif », notamment le « manque de clarté dans la procédure d’agrément qui entraîne\nparfois des abus, l’agrément d’une association restant conditionné au bon vouloir de\nl’autorité administrative »1068.\nLes associations nationales sans but lucratif (ASBL)"},{"id":"a-hrc-36-crp-1-p0565","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"565","seq":567,"section":"7. Libertés d’association et de réunion","text":"Initié en 2009, un processus de révision du décret-loi n° 1/11 de 1992 a abouti à\nl’adoption de la loi n° 1/02 du 27 janvier 2017 « portant cadre organique des ASBL ». Ce\nnouveau texte législatif ne lève toutefois pas les inquiétudes exprimées en 2015 par le\nRapporteur spécial sur la situation des défenseurs des droits de l’homme par rapport au projet\nde loi, notamment « un processus d’enregistrement très complexe »1069."},{"id":"a-hrc-36-crp-1-p0566","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"566","seq":568,"section":"7. Libertés d’association et de réunion","text":"La loi n° 1/02 de 2017 donne de larges pouvoirs au Ministère de l’intérieur pour\nsuspendre une ASBL, comme l’avait noté le Rapporteur spécial sur la situation des\ndéfenseurs des droits de l’homme quand la loi était encore au stade de projet. La loi précise\nque « la Cour administrative peut, sur demande du Ministère public, ordonner la fermeture\ndes locaux et la suspension des activités de l’association qui se rend coupable de trouble à\nl’ordre public ou d’atteinte à la sûreté de l’État », mais, avant la saisine de la Cour, permet au\nministère ayant l’agrément de ces associations dans ses attributions de « prendre d’office ou\nsur demande de toute personne intéressée, une décision de suspension pour une période\nn’excédant pas deux mois »1070. Les motifs vagues de « trouble à l’ordre public ou d’atteinte\nà la sûreté de l’État » laissent une grande latitude aux autorités burundaises pour suspendre\nune ASBL."},{"id":"a-hrc-36-crp-1-p0567","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"567","seq":569,"section":"7. Libertés d’association et de réunion","text":"Le Gouvernement burundais a en outre un droit de regard et de contrôle sur les\nactivités de ces associations puisque l’article 82 de la loi n° 1/02 de 2017 dispose que « toutes\nles activités des associations doivent recevoir l’aval du ministère ayant l’intérieur dans ses\nattributions ou celui du ministère sectoriel technique sous peine de sanction ». La loi prévoit\npar ailleurs que « le Ministre ayant les associations sans but lucratif dans ses attributions se\nréserve le droit de suivi et d’évaluation des activités des associations sur le terrain »."},{"id":"a-hrc-36-crp-1-p0568","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"568","seq":570,"section":"7. Libertés d’association et de réunion","text":"Le Rapporteur spécial sur la situation des défenseurs des droits de l’homme avait\négalement regretté que le projet de loi « prévoit des limites à la formation des coalitions\nd’organisations » car il n’autorise les « groupements, coalitions et assimilés [...] qu’entre les\nassociations sans but lucratif ayant des objets du même domaine et soumises aux dispositions\nde la présente loi »1071. L’article 41 de la loi n° 1/02 de 2017 confirme cette restriction que le\nRapporteur spécial avait considéré comme allant « à l’encontre de la liberté des associations\nde choisir leurs causes et leur mode de fonctionnement » et cassant « la dynamique inter-\nassociative si bénéfique à la vitalité des défenseurs des droits de l’homme »1072."},{"id":"a-hrc-36-crp-1-p0569","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"569","seq":571,"section":"7. Libertés d’association et de réunion","text":"Enfin, il est à noter que la loi n° 1/02 de 2017 étend le contrôle des autorités\nburundaises sur les ressources mêmes des ASBL puisqu’elle impose que « toutes les\nressources financières d’origine étrangère doivent transiter par la Banque centrale et être\naccompagnées d’un document illustrant son origine et son affectation »1073.\nLes organisations non-gouvernementales étrangères (ONGE)"},{"id":"a-hrc-36-crp-1-p0570","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"570","seq":572,"section":"7. Libertés d’association et de réunion","text":"Promulguée le 23 janvier 2017, la loi n° 1/01 « portant cadre général de coopération\nentre la République du Burundi et les organisations non-gouvernementales étrangères » a\nremplacé la loi n° 1/011 du 23 juin 1999 et renforce considérablement le contrôle du\ngouvernement à la fois sur les ressources et les activités des ONGE. Les ONGE qui désirent\ns’installer et intervenir au Burundi doivent désormais « payer une somme de 500 dollars\naméricains, représentant les frais administratifs non remboursables et n’ayant aucune\nincidence sur les démarches d’agrément » qui sont entreprises auprès du Ministère des\nrelations extérieures et de la coopération internationale1074. Ce ministère constitue le\n« guichet unique pour la gestion de tous les rapports entre le Gouvernement et les ONGE »\net, une fois l’ONGE opérationnelle, « peut à tout moment vérifier et revoir leur gestion\ngénérale et financière »1075. Toutes les ONGE doivent par ailleurs ouvrir un compte en\ndevises à la Banque de la République du Burundi et « virer un tiers de leurs budgets sur les\ncomptes avant la signature de la Convention de coopération » avec le Gouvernement1076.\n(iii)     Faits"},{"id":"a-hrc-36-crp-1-p0571","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"571","seq":573,"section":"7. Libertés d’association et de réunion","text":"La liberté d’association a subi des restrictions depuis avril 2015 au Burundi. Cette\nsituation n’est cependant pas nouvelle. Déjà en 2014, dans ses observations finales\nconcernant le deuxième rapport périodique du Burundi, le Comité des droits de l’homme\ns’était dit « préoccupé par les nombreux obstacles et entraves existant quant à la liberté à\ncréer des associations »1077. Malgré cela, avant 2015, les associations de la société civile, tout\ncomme les médias, ont pu jouir d’une certaine liberté au Burundi et dénonçaient souvent les\nviolations des droits de l’homme, malgré des menaces et intimidations constantes de la part\ndes autorités1078."},{"id":"a-hrc-36-crp-1-p0572","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"572","seq":574,"section":"7. Libertés d’association et de réunion","text":"La société civile au Burundi a souffert d’une certaine politisation et de pressions de la\npart du Gouvernement. Le Rapporteur spécial sur la situation des défenseurs des droits de\nl’homme avait déjà remarqué à l’issue de sa visite dans le pays en novembre 2014 : « Une\ndifficulté de taille qui se pose à la société civile est sa propre fragmentation et politisation. Le\nRapporteur spécial s’inquiète de ce que certaines associations semblent être favorisées par le\nGouvernement en raison de leur position politique, ce qui suscite du ressentiment au sein de\nla société civile traditionnellement indépendante »1079."},{"id":"a-hrc-36-crp-1-p0573","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"573","seq":575,"section":"7. Libertés d’association et de réunion","text":"Le Gouvernement burundais a, depuis longtemps, accusé les organisations\nindépendantes de la société civile d’être proches de l’opposition politique, ou même d’en\nfaire partie. Ces accusations se sont renforcées en 2015 lorsque 304 organisations de la\nsociété civile ont rejoint la campagne « Halte au troisième mandat », lancée le 26 janvier\n2015 contre la candidature du Président Nkurunziza à l’élection présidentielle1080. Suite aux\nmanifestations d’avril 2015 et à la tentative de coup d’État de mai 2015, ces organisations et\nd’autres ont subi des pressions encore plus intenses et plusieurs de leurs dirigeants ont fait\nl’objet de poursuites par les autorités.\nSuspension, gel des comptes et radiation d’organisations de la société civile"},{"id":"a-hrc-36-crp-1-p0574","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"574","seq":576,"section":"7. Libertés d’association et de réunion","text":"Lors de son discours d’investiture le 20 août 2015, le Président Nkurunziza a mis en\ngarde les associations de la société civile, les enjoignant à « ne pas s’immiscer dans les\naffaires politiques et de se garder de tout acte ou parole susceptible de provoquer la division\net des dissensions de quelque nature que ce soit, d’inciter aux tueries, comme cela est apparu\nlors des récentes insurrections »1081. Le même mois, la commission d’enquête « chargée de\nfaire la lumière sur le mouvement insurrectionnel déclenché le 26 avril 2015 », mise en place\npar le Procureur général de la République le 29 avril 2016, a publié son rapport dans lequel\n24 organisations de la société civile1082 et leurs représentants1083 ont été identifiés comme\nayant pris « part à l’organisation de cette insurrection » 1084."},{"id":"a-hrc-36-crp-1-p0575","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"575","seq":577,"section":"7. Libertés d’association et de réunion","text":"Sur cette base, le Procureur général de la République a demandé, le 19 octobre 2015,\naux banques présentes au Burundi de geler les comptes de neuf organisations citées dans le\nrapport de la commission d’enquête, ainsi que de trois de leurs dirigeants, à des fins\nd’enquête1085. Ces neuf organisations, auxquelles a été ajoutée une autre, ont par la suite vu\nleurs activités suspendues par un décret du Ministère de l’intérieur en date du 23 novembre\n20151086. Le 7 décembre 2015, le Procureur général de la République a ordonné le gel des\ncomptes de trois autres organisations, ainsi que d’une radio privée1087."},{"id":"a-hrc-36-crp-1-p0576","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"576","seq":578,"section":"7. Libertés d’association et de réunion","text":"La levée de la suspension des activités de l’organisation Parole et action pour le réveil\ndes consciences et l’évolution des mentalités (PARCEM), ainsi que du gel des comptes de\nPARCEM et de ceux de l’Association des juristes catholiques du Burundi (AJCB) le 25 mars\n2016 aurait pu laisser espérer une amélioration de la situation. Cependant, le 19 octobre\n2016, le Ministère de l’intérieur a promulgué l’ordonnance n° 530/1922 actant la radiation\ndéfinitive du FORSC, du FOCODE, de l’ACAT-Burundi, de l’Association burundaise pour\nla protection des droits humains et des personnes détenues (APRODH) et du Réseau des\ncitoyens probes (RCP). Le 24 octobre 2016, le Ministère de l’intérieur a décidé par\nordonnance la suspension provisoire de cinq nouvelles organisations, à savoir SOS-\nTorture/Burundi, la Ligue Iteka, la Coalition de la société civile pour le monitoring électoral\n(COSOME), la Coalition burundaise pour la Cour pénale internationale (CB-CPI) et l’Union\nBurundaise des Journalistes (UBJ) 1088."},{"id":"a-hrc-36-crp-1-p0577","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"577","seq":579,"section":"7. Libertés d’association et de réunion","text":"Le 3 janvier 2017, le Ministère de l’intérieur a annoncé la radiation définitive de la\nLigue Iteka, la plus ancienne organisation de protection des droits de l’homme au Burundi,\nl’accusant d’être « récidiviste dans son action de ternir l’image de marque du pays et à semer\nla haine et la division de la population burundaise »1089. Cette mesure est intervenue après\nque la Ligue Iteka a publié en novembre 2016 un rapport, conjointement avec la Fédération\ninternationale des droits de l’homme (FIDH), sur la détérioration de la situation des droits de\nl’homme au Burundi depuis avril 20151090."},{"id":"a-hrc-36-crp-1-p0578","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"578","seq":580,"section":"7. Libertés d’association et de réunion","text":"Le début de l’année 2017 a par ailleurs été marqué par la promulgation de deux lois,\névoquées plus haut, qui permettent au Gouvernement burundais d’étendre son contrôle sur\nl’activité des organisations nationales de la société civile et des ONG étrangères.\nPoursuites, menaces et autres violations contre les défenseurs des droits de l’homme"},{"id":"a-hrc-36-crp-1-p0579","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"579","seq":581,"section":"7. Libertés d’association et de réunion","text":"Les membres des organisations de la société civile et les défenseurs des droits de\nl’homme ont particulièrement été visés depuis avril 2015. Nombre d’entre eux, surtout ceux\nengagés dans la campagne « Halte au troisième mandat », ont été assimilés à des opposants,\nvoire des « insurgés », par les autorités burundaises. Le rapport de la commission d’enquête\n« chargée de faire la lumière sur le mouvement insurrectionnel déclenché le 26 avril 2015 » a\nciblé les représentants des organisations de la société civile identifiées comme responsables\nde cette « insurrection ». Sans faire de distinction entre eux ni apporter de preuves, la\ncommission d’enquête a conclu que toutes ces personnes étaient « pénalement et civilement\nresponsables des infractions de détention illégale d’armes à feu, participation à un\nmouvement insurrectionnel, coups et blessures volontaires graves, destructions méchantes,\nassassinats, atteinte à la sûreté intérieure de l’État et d’attentat contre l’autorité de l’État. Ils\nsont tenus de réparer tous les dommages causés par ces infractions »1091."},{"id":"a-hrc-36-crp-1-p0580","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"580","seq":582,"section":"7. Libertés d’association et de réunion","text":"Sur la base de ce rapport, le Procureur général de la République a émis une\nquarantaine de mandats d’arrêt internationaux en octobre 2015 contre des personnalités ayant\nexprimé leur opposition à un nouveau mandat du Président Nkurunziza, dont quatre\ndirigeants d’organisations de la société civile : Justine Nkurunziza de la Coalition de la\nsociété civile pour le monitoring électoral (COSOME), Pacifique Nininahazwe du FOCODE,\nVital Nshimirimana du FORSC, et Armel Niyongere de l’ACAT-Burundi."},{"id":"a-hrc-36-crp-1-p0581","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"581","seq":583,"section":"7. Libertés d’association et de réunion","text":"Des défenseurs des droits de l’homme ont également été arrêtés, attaqués, tués ou ont\ndisparu1092. Un des cas les plus graves est celui de Pierre Claver Mbonimpa, président de\nl’APRODH. Pierre Claver Mbonimpa avait déjà été arrêté en mai 2014 pour avoir évoqué\nl’entraînement militaire d’Imbonerakure en RDC ; il avait été libéré en septembre 2014 après\nêtre tombé très malade en prison. Le 3 août 2015, il a été victime d’une tentative d’assassinat.\nGrièvement blessé par balle, il a été évacué d’urgence pour soins médicaux et demeure en\nexil. Son gendre, Pascal Nshimirimana, a été assassiné le 9 octobre 2015 par des personnes\nnon identifiées, et son propre fils, Welly Nzitonda, a été tué le 6 novembre 2015 par un\npolicier à Bujumbura selon les informations recueillies par la Commission1093."},{"id":"a-hrc-36-crp-1-p0582","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"582","seq":584,"section":"7. Libertés d’association et de réunion","text":"Le cas de Marie Claudette Kwizera, trésorière de la Ligue Iteka, disparue le 10\ndécembre 2015 après avoir été aperçue escortée par des membres du SNR, mérite également\nd’être relevé1094. Plus récemment, Germain Rukuki, ancien employé de l’ACAT-Burundi,\nmembre de l’AJCB et président de l’association Njabutsa Tujane, a été arrêté par des agents\ndu SNR le 13 juillet 2017 et accusé d’atteinte à la sûreté de l’État et de rébellion au motif\nqu’il représenterait clandestinement l’ACAT au Burundi et pour avoir participé à un atelier\norganisé par l’ACAT au Rwanda. Le 17 août 2017, le tribunal de grande instance de\nNtahangwa a décidé son maintien en détention à la prison de Ngozi où il a été transféré après\navoir été détenu dans un premier temps au siège du SNR à Bujumbura1095. Le 25 août 2017,\nle Rapporteur spécial sur la situation des défenseurs des droits de l’homme, celui sur la\npromotion et la protection du droit à la liberté d’opinion et d’expression, celui sur le droit de\nréunion pacifique et la liberté d’association, et le Président-Rapporteur du Groupe de travail\nsur la détention arbitraire ont demandé la libération de Germain Rukiki1096. Un mois plus tôt,\nle 13 juin 2017, trois membres du PARCEM avaient été arrêtés dans la province de\nMuramvya où ils devaient organiser des ateliers d’échange avec les autorités judiciaires et\nadministratives sur les arrestations illégales et arbitraires. Ces personnes ont été transférées\nsur décision du responsable local du SNR au siège du service de renseignement à Bujumbura.\nElles sont depuis détenues à la prison de Mpimba, accusées d’atteinte à la sûreté de l’État1097."},{"id":"a-hrc-36-crp-1-p0583","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"583","seq":585,"section":"7. Libertés d’association et de réunion","text":"Des membres des organisations de la société civile et défenseurs des droits de\nl’homme ont par ailleurs reçu des menaces surtout au cours des premiers mois de la crise, ce\nqui a forcé beaucoup d’entre eux à fuir le pays1098. À titre d’exemple, Anschaire Nikoyagize,\nprésident de la Ligue Iteka, a rapporté publiquement avoir reçu des menaces à son encontre et\nà l’encontre de sa famille par le biais de coups de téléphone anonymes après le coup d’État\nmanqué de mai 2015. Sa famille proche ayant déménagé par mesure de sécurité, il a reçu des\ninformations selon lesquelles elle était ciblée par des agents du SNR et des Imbonerakure\ndans la localité où elle se trouvait. Ces menaces se confirmant et ne se sentant pas lui-même\nen sécurité à Bujumbura après que des policiers se soient positionnés près de l’endroit où il\nlogeait, il a finalement décidé de fuir le Burundi en novembre 20151099."},{"id":"a-hrc-36-crp-1-p0584","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"584","seq":586,"section":"7. Libertés d’association et de réunion","text":"Ces cas ne sont pas isolés. De nombreux autres défenseurs des droits de l’homme ont\nété forcés de quitter le pays à la suite de menaces répétées verbales ou écrites à leur encontre\net/ou à l’encontre de proches, et/ou d’un sentiment d’insécurité souvent dû à la surveillance\ndont ils ont fait l’objet par des agents de la police ou du SNR1100."},{"id":"a-hrc-36-crp-1-p0585","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"585","seq":587,"section":"7. Libertés d’association et de réunion","text":"Ces menaces et violations ont conduit à instaurer un climat d’insécurité permanent qui\na rendu le travail des rares défenseurs des droits de l’homme encore présents au Burundi à la\nfois difficile et dangereux. Ces défenseurs sont obligés de travailler de manière clandestine et\nde prendre de nombreuses précautions, pour ne pas s’exposer ou exposer leurs sources à des\nrisques de représailles, les autorités ciblant les personnes qui partagent des informations avec\nles organisations de la société civile nationales ou internationales ou les Nations Unies.\nViolations de la liberté de ne pas s’associer"},{"id":"a-hrc-36-crp-1-p0586","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"586","seq":588,"section":"7. Libertés d’association et de réunion","text":"La Commission a constaté que, depuis avril 2015, la population en général, et plus\nparticulièrement les personnes affiliées à des partis d’opposition, subissent des menaces et\ndes pressions, entraînant souvent des violations des droits de l’homme ou des atteintes à\nceux-ci, pour les forcer de rejoindre le CNDD-FDD. Ces actes sont principalement le fait\nd’Imbonerakure et/ou de responsables locaux du parti au pouvoir. Les victimes sont quant à\nelles en majorité des membres de partis d’opposition, surtout du MSD et des FNL1101. Un des\ncas les plus emblématiques est celui de Zedi Feruzi, le président de l’Union la paix et le\ndéveloppement (UPD)-Zigamibanga qui a été tué le 23 mai 2015 à Bujumbura1102. Les\ntémoignages recueillis par la Commission ont confirmé qu’avant son assassinat, il avait été\napproché par des membres, y compris haut placés, du CNDD-FDD pour que l’UPD s’allie à\nleur parti pour l’élection présidentielle de 2015, ce qu’il avait refusé1103."},{"id":"a-hrc-36-crp-1-p0587","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"587","seq":589,"section":"7. Libertés d’association et de réunion","text":"La Commission a également relevé plusieurs cas de personnes sans affiliation\npolitique et/ou ne désirant pas s’engager en faveur d’un parti qui ont subi des pressions pour\nrejoindre le CNDD-FDD ou ont été victimes de violations de leurs droits parce qu’elles\npersistaient dans leur refus1104. Mis à part les raisons politiques expliquant les efforts du\nCNDD-FDD pour grossir les rangs du parti, la recherche de nouveaux adhérents est\négalement motivée par des raisons financières afin d’obtenir le paiement de cotisations1105."},{"id":"a-hrc-36-crp-1-p0588","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"588","seq":590,"section":"7. Libertés d’association et de réunion","text":"Les violations et atteintes qu’ont subies les personnes ayant refusé de joindre le\nCNDD-FDD ou les Imbonerakure ont été de plusieurs sortes, allant de menaces de mort\ncontre elles ou leurs proches1106 jusqu’à des tortures ou traitements cruels, inhumains ou\ndégradants1107, des disparitions1108 ou des assassinats ou tentatives d’assassinat1109. La\nCommission a également recueilli les témoignages de victimes dont les biens – maison,\nterrain ou commerce – ont été confisqués ou détruits par des membres du CNDD-FDD et/ou\ndes Imbonerakure1110. Un membre d’un parti d’opposition a fait mention de croix rouges qui\nont été peintes sur sa maison et celles d’opposants connus dans son quartier peu après les\nmanifestations contre le mandat de Pierre Nkurunziza à l’élection présidentielle1111."},{"id":"a-hrc-36-crp-1-p0589","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"589","seq":591,"section":"7. Libertés d’association et de réunion","text":"Les conjoints ou autres proches des personnes que le CNDD-FDD a cherché à\nembrigader ont également été victimes de violations des droits de l’homme et d’atteintes à\nceux-ci, en particulier de menaces de mort1112, de tortures ou traitements cruels, inhumains ou\ndégradants1113, d’assassinats ou de disparitions1114.\n(b)      Liberté de réunion\n(i)      Droit international et régional applicable"},{"id":"a-hrc-36-crp-1-p0590","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"590","seq":592,"section":"7. Libertés d’association et de réunion","text":"La liberté de réunion pacifique est garantie par les articles 20 de la DUDH et 21 du\nPIDCP qui prévoit que « l’exercice de ce droit ne peut faire l'objet que des seules restrictions\nimposées conformément à la loi et qui sont nécessaires dans une société démocratique, dans\nl'intérêt de la sécurité nationale, de la sûreté publique, de l'ordre public ou pour protéger la\nsanté ou la moralité publiques, ou les droits et les libertés d'autrui ». De la même manière,\nl’article 11 de la Charte africaine des droits de l’homme et des peuples dispose que « toute\npersonne a le droit de se réunir librement avec d'autres. Ce droit s'exerce sous la seule réserve\ndes restrictions nécessaires édictées par les lois et règlements, notamment dans l'intérêt de la\nsécurité nationale, de la sûreté d'autrui, de la santé, de la morale ou des droits et libertés des\npersonnes ».\n(ii)      Droit national : une conception extensive de l’ordre public"},{"id":"a-hrc-36-crp-1-p0591","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"591","seq":593,"section":"7. Libertés d’association et de réunion","text":"La liberté de réunion est garantie par l’article 32 de la Constitution du Burundi et\nencadrée par la loi n° 1/28 du 5 décembre 2013 « portant règlementation des manifestations\nsur la voie publique et réunions publiques ». Ce texte prévoit notamment un régime de\ndéclaration préalable. Le délai pour le dépôt de cette déclaration auprès de l’autorité\ncompétente est de quatre jours ouvrables1115. L’autorité compétente a alors 48 heures pour\nfaire part de sa décision."},{"id":"a-hrc-36-crp-1-p0592","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"592","seq":594,"section":"7. Libertés d’association et de réunion","text":"Les réunions comme les manifestations publiques peuvent être interdites ou différées\npour des motifs d’ordre public. S’agissant des manifestations publiques, « l’autorité\nadministrative peut à tout moment, nonobstant la déclaration régulièrement faite, différer ou\nmettre fin à toute réunion, tout cortège, défilé, rassemblement sur la voie publique et dans les\nlieux publics, si le maintien de l’ordre public l’exige »1116. Or, la loi donne une définition\nlarge de l’ordre public qui excède les critères prévus par le PIDCP et la Charte africaine des\ndroits de l’homme et des peuples. L’article 3 (h) de la loi définit en effet l’ordre public\ncomme « l’ensemble des règles obligatoires qui touchent à l’organisation de la nation, à\nl’économie, à la morale, à la santé, à la sécurité, à la paix publique, aux droits et libertés\nessentielles de chaque individu ». Les notions d’« organisation de la nation », d’« économie »\net de « paix publique », en plus d’être vagues et pouvant donc être interprétées de manière\nextensive, vont au-delà de celles de sécurité, de sûreté, de santé et de morale prévues dans le\ndroit international et africain.\n(iii)     Faits"},{"id":"a-hrc-36-crp-1-p0593","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"593","seq":595,"section":"7. Libertés d’association et de réunion","text":"Jusqu’au début de l’année 2015, des manifestations de partis politiques et\nd’organisations de la société civile ont pu être organisées malgré des heurts avec les autorités\net les forces de l’ordre. Les manifestations d’avril à juin 2015 contre le nouveau mandat du\nPrésident Nkurunziza ont constitué un tournant majeur1117. À la connaissance de la\nCommission, aucune manifestation publique de partis ou mouvements d’opposition à la\npolitique du Gouvernement n’a pu se dérouler depuis. En revanche, jusqu’à la finalisation du\nprésent rapport, le CNDD-FDD a régulièrement organisé des marches, défilés et autres\nmanifestations avec des effectifs importants, au cours desquels des propos de haine ont été\nprononcés1118 alors même qu’aux termes de la loi n° 1/28 du 5 décembre 2013, mentionnée\nplus haut, « est considérée comme de nature à troubler l’ordre public, notamment toute\nmanifestation sur la voie publique ou réunion publique qui risque d’attiser la haine\nidentitaire, provoquer des troubles ou provoquer de la violence »1119."},{"id":"a-hrc-36-crp-1-p0594","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"594","seq":596,"section":"7. Libertés d’association et de réunion","text":"Les partis ou mouvements d’opposition au Gouvernement peuvent difficilement\norganiser des réunions publiques et leurs membres craignent de se réunir à l’intérieur du\npays, même en privé ou en petits groupes1120. Des membres des partis politiques de\nl’opposition ont par ailleurs été arrêtés ou failli être arrêtés après avoir été accusés de tenir\ndes réunions clandestines1121. Un représentant d’un parti de l’opposition a ainsi indiqué à la\nCommission :\n« Dès que trois personnes sont ensemble, si elles ne sont pas membres du CNDD-\nFDD, elles sont accusées de tenir des réunions clandestines de déstabilisation »1122."},{"id":"a-hrc-36-crp-1-p0595","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"595","seq":597,"section":"7. Libertés d’association et de réunion","text":"À titre d’exemple, en 2015, dans la province de Rumonge, un membre d’un parti\nd’opposition a été battu par des Imbonerakure qui l’ont accusé de tenir une réunion\nclandestine alors qu’il conversait avec trois amis dans la rue. Les Imbonerakure ont\négalement frappés ses amis :\n« Ils nous ont accusés de tenir une réunion clandestine et de ne pas répondre à l’appel\ndu parti au pouvoir. Ils nous ont accusés d’être parmi les opposants qui ne voulaient\npas la paix »1123."},{"id":"a-hrc-36-crp-1-p0596","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"596","seq":598,"section":"8. Liberté de circulation","text":"La liberté de circulation est le droit pour tout individu de se déplacer librement dans\nun pays, de quitter celui-ci et d'y revenir. Elle est garantie par l'article 13 de la DUDH et\nl’article 12 du PIDCP."},{"id":"a-hrc-36-crp-1-p0597","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"597","seq":599,"section":"8. Liberté de circulation","text":"Selon l’Observation générale n° 27 du Comité des droits de l’homme1124, la liberté de\ncirculation est une condition indispensable au libre développement de l'individu et est\nétroitement liée à plusieurs autres droits énoncés dans le Pacte international relatif aux droits\ncivils et politiques. Selon le Comité, le droit de circuler librement s'exerce sur l'ensemble du\nterritoire d'un État et la liberté de quitter le territoire d'un État ne peut être subordonnée à un\nbut particulier ni à la durée que l'individu décide de passer en dehors du pays. Par ailleurs,\neffectuer un voyage vers un pays étranger nécessite l’obtention de documents valables. Le\ndroit de quitter un pays comporte ainsi celui d’obtenir les documents nécessaires pour\nvoyager."},{"id":"a-hrc-36-crp-1-p0598","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"598","seq":600,"section":"8. Liberté de circulation","text":"La liberté de circulation est également garantie par l’article 12 de la CADHP qui\nprévoit, notamment en son aliéna 3, que toute personne a le droit, en cas de persécution, de\nrechercher et de recevoir asile en territoire étranger conformément à la loi de chaque pays et\naux conventions internationales."},{"id":"a-hrc-36-crp-1-p0599","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"599","seq":601,"section":"8. Liberté de circulation","text":"La liberté de circulation ne peut être limitée que si les conditions générales concernant\nles restrictions légitimes des droits fondamentaux sont remplies. L’article 12 du PIDCP\nprévoit plus précisément que les restrictions à la liberté de circulation doivent être prévues\npar la loi, nécessaires pour protéger la sécurité nationale, l'ordre public, la santé ou la\nmoralité publiques, ou les droits et libertés d'autrui, et compatibles avec les autres droits\nreconnus par le même Pacte."},{"id":"a-hrc-36-crp-1-p0600","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"600","seq":602,"section":"8. Liberté de circulation","text":"L’article 33 de la Constitution burundaise dispose pour sa part que « tous les citoyens\nburundais ont le droit de circuler et de s’établir librement n’importe où sur le territoire\nnational, ainsi que de le quitter et d’y revenir ».\n(b)      Faits"},{"id":"a-hrc-36-crp-1-p0601","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"601","seq":603,"section":"8. Liberté de circulation","text":"De nombreuses restrictions à la liberté de circulation ont été documentées par la\nCommission d’enquête depuis avril 2015 au Burundi, affectant particulièrement les\npersonnes qui ont été victimes, ou craignent d’être victimes, des violations des droits de\nl’homme et leurs proches."},{"id":"a-hrc-36-crp-1-p0602","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"602","seq":604,"section":"8. Liberté de circulation","text":"La Commission a recueilli plusieurs témoignages faisant état de barrages érigés par\ndes policiers et des Imbonerakure, ou des Imbonerakure seuls, à l’approche des frontières\nnotamment avec le Rwanda et la Tanzanie1125. Ces barrages constituent des obstacles pour les\ncitoyens burundais d’aller et de venir à l’intérieur du pays et vers les pays limitrophes. Ils\nforcent par ailleurs les personnes menacées ou d’autres candidats à l’exil à fuir le pays de\nmanière clandestine, augmentant ainsi les risques auxquels ils s’exposent."},{"id":"a-hrc-36-crp-1-p0603","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"603","seq":605,"section":"8. Liberté de circulation","text":"La Commission d’enquête a documenté des violations des droits de l’homme au\nniveau de ces barrages. Plusieurs personnes qui tentaient de fuir le pays parce qu’elles\ncraignaient pour leur vie y ont été arrêtées arbitrairement. À titre d’exemple, une personne\ninterrogée par la Commission a déclaré :\n« [En]2015, j’ai décidé d’aller [...]par la route [...] A la barrière [à la frontière], la\npolice nous a dit qu’on ne pouvait pas continuer […]. Après cinq minutes, un véhicule\ndouble-cabine est venu avec des personnes en civil et des policiers [...]Un monsieur\nest sorti. On nous a dit que c’était le chef [provincial] du SNR […]. Ils nous ont\nconduits dans un endroit que je ne connaissais pas […]. Vers sept heures, nous avons\nrevu le chef du SNR avec des policiers. Ils nous ont menottés et nous ont conduits\njusqu’au SNR à Bujumbura. Là, ils ont amené un homme […]. Il m’a frappé avec ses\npoings et avec un bâton. Il a dit : « Nous allons te tuer. Toi, Tutsi, ce n’est pas comme\navant. Aujourd’hui vous n’avez plus le pouvoir. » »1126."},{"id":"a-hrc-36-crp-1-p0604","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"604","seq":606,"section":"8. Liberté de circulation","text":"Certaines personnes ont été victimes de mauvais traitements et de torture au niveau\ndes barrages lors de leur arrestation et pendant leur détention qui a suivi1127. Ainsi, des\npersonnes ont été arrêtées et frappées en 2016 par des agents de la Police de l'air, des\nfrontières et des étrangers (PAFE) et des Imbonerakure alors qu’elles tentaient de traverser la\nfrontière avec un pays limitrophe. Ces personnes ont été par la suite détenues au siège du\nSNR à Bujumbura et l’une d’entre elles y a été torturée1128."},{"id":"a-hrc-36-crp-1-p0605","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"605","seq":607,"section":"8. Liberté de circulation","text":"La Commission d’enquête a recueilli des témoignages de femmes qui ont été victimes\nde viols alors qu’elles tentaient de fuir le pays1129. Par exemple en 2016, une femme a été\nviolée par des policiers à tour de rôle à l’une des quatre barrières qu’elle a dû franchir afin de\npouvoir rejoindre la frontière avec le Rwanda1130. Un viol dans des circonstances similaires a\nété rapporté à l’approche de la frontière avec la Tanzanie1131."},{"id":"a-hrc-36-crp-1-p0606","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"606","seq":608,"section":"8. Liberté de circulation","text":"Au niveau de ces barrages ou des postes de frontière, plusieurs personnes qui tentaient\nde quitter le pays ont été obligées de payer des sommes d’argent parfois importantes à des\npoliciers ou des Imbonerakure, ou ont été dépouillées de leurs biens1132. D’autres ont échappé\nde justesse à une arrestation ou à d’autres violations en courant pour traverser la frontière,\npoursuivis par des Imbonerakure ou des agents du SNR1133."},{"id":"a-hrc-36-crp-1-p0607","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"607","seq":609,"section":"8. Liberté de circulation","text":"La Commission d’enquête a recueilli des témoignages de personnes qui ont été\nmenacées, arrêtées ou torturées après avoir fourni une assistance à d’autres personnes qui\ncherchaient à fuir le pays1134. Une personne qui a fui en 2017 a déclaré à la Commission :\n« Les circonstances de ma fuite ont été difficiles [...]Très tôt le matin, [X] a arrangé le\ntransport jusqu’à la frontière rwandaise. On y a rencontré des Imbonerakure [...] ils\nne nous ont pas rattrapés, mais ont crié aux gens du Rwanda de nous expulser [...]\nLes Imbonerakure ont attrapé [X] qui était resté dans le véhicule. Il a été conduit au\ncachot du SNR avant d’être transféré deux jours plus tard au cachot de la police\njudiciaire où il est resté détenu pendant trois semaines [...]Ils lui ont posé beaucoup\nde questions […]. Ils voulaient m’attraper»1135."},{"id":"a-hrc-36-crp-1-p0608","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"608","seq":610,"section":"8. Liberté de circulation","text":"Dans plusieurs cas, des membres de famille de personnes qui ont réussi à quitter le\npays ont été sérieusement menacés. Certains ont été victimes d’arrestations ou de détentions\narbitraires, ou auraient disparu1136. La Commission a ainsi reçu le témoignage d’une personne\nqui a fui le Burundi en 2016. Des membres de sa famille ont été arrêtés à leur domicile\nquelques semaines après son départ. À la date de rédaction de ce rapport, plusieurs d’entre\neux seraient toujours portés disparus, tandis que le corps de l’un d’eux aurait été retrouvé\nquelques jours après son arrestation1137."},{"id":"a-hrc-36-crp-1-p0609","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"609","seq":611,"section":"8. Liberté de circulation","text":"Des personnes ayant séjourné dans des pays limitrophes, notamment au Rwanda, et\nqui sont retournées au Burundi ont été arrêtées arbitrairement ou victimes d’autres violations\ndes droits de l’homme, notamment de tortures, une fois de retour car les autorités burundaises\nles auraient notamment soupçonnées de collaborer avec des groupes armés qui seraient basés\ndans ces pays1138. La Commission d’enquête a notamment recueilli le témoignage d’une\npersonne qui a été arrêtée en 2016 par des individus non identifiés, dont l’un était en tenue\npolicière, peu après son retour au Burundi d’un pays limitrophe où sa famille était réfugiée.\nCette personne a été détenue dans un endroit non identifié où elle a été victime de violences\nsexuelles et d’autres tortures1139."},{"id":"a-hrc-36-crp-1-p0610","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"610","seq":612,"section":"8. Liberté de circulation","text":"Les autorités burundaises ont adopté d’autres mesures entravant la liberté de\ncirculation, par exemple l’obligation de tenir des cahiers de ménage qui viserait à davantage\ncontrôler les mouvements de la population. Conformément à cette obligation, chaque ménage\ndoit être en possession d’un cahier dans lequel le chef de ménage est tenu d’inscrire toutes les\npersonnes à sa charge ainsi que les visiteurs. Tout changement dans le cahier de ménage doit\nêtre validé par les autorités administratives locales. Ces cahiers font régulièrement l’objet de\ncontrôles par les policiers, la régularité de ces contrôles variant d’un endroit à l’autre1140. Une\npersonne interrogée par la Commission a expliqué comment ces opérations de contrôle se\nsont déroulées dans son quartier :\n« La PNB fait régulièrement des fouilles-perquisitions dans certains quartiers. Quand\nelle fait ce genre d’opérations, elle entre dans les ménages et demande à voir des\ndocuments, à savoir les cartes d’identité et le cahier de ménage. Quand les policiers\nfont ces opérations, les militaires bloquent toutes les entrées et sorties des quartiers\npendant plusieurs heures et les policiers entrent dans les ménages. Pendant toute cette\npériode, aucune entrée et sortie n’est possible »1141."},{"id":"a-hrc-36-crp-1-p0611","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"611","seq":613,"section":"8. Liberté de circulation","text":"Une autre personne a qualifié cette obligation de « système mis en place pour générer\nde l’argent »1142. En effet, lors de leurs opérations, les policiers exigent souvent de l’argent\nen l’absence de cahiers de ménage ou lorsque ces derniers contiennent soi-disant des erreurs.\nUn chef de ménage a raconté à la Commission que :\n« [Les policiers] ont tenté de mettre au cachot de la zone [un visiteur] qui était venu\nme rendre visite. [Il] était pourtant enregistre dans le cahier, mais ils ont dit que le\nchef de quartier n’avait pas mis sa signature dans le cahier. Pourtant cela avait été\nfait. J’ai dû donner de l’argent aux policiers et puis ils sont partis »1143."},{"id":"a-hrc-36-crp-1-p0612","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"612","seq":614,"section":"8. Liberté de circulation","text":"Même lorsqu’il y a des retards dans la distribution des cahiers de ménage, les policiers\ncontinuent de les exiger. Une personne a rapporté à la Commission les arrestations suivantes\nen 2017 :\n« Les forces de l’ordre ont bloqué quatre rues de la zone […]. J’ai vu que les policiers\nont arrêté 10 personnes. Elles étaient nouvelles dans le quartier. Elles avaient toutes\npayé pour les cahiers de ménage. Elles avaient toutes les bordereaux. Mais elles\nn’avaient pas de cahiers car ils ne sont plus disponibles. Les policiers ont quand\nmême exigé les cahiers. Ils les ont amenées à la zone […]. Elles ont été libérées\n[...]après avoir payé entre 2 000 et 10 000 francs burundais [soit entre environ un et\ncinq dollars américains] »1144."},{"id":"a-hrc-36-crp-1-p0613","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"613","seq":615,"section":"8. Liberté de circulation","text":"Toutes ces entraves à la liberté de circulation ont eu comme conséquence que des\npersonnes qui avaient par le passé l’habitude de se rendre dans les pays limitrophes ou de se\ndéplacer à l’intérieur du pays pour des raisons professionnelles ou privées, notamment pour\nvisiter des membres de leurs familles, ont limité leurs déplacements de peur d’être arrêtées\narbitrairement ou victimes d’autres violations des droits de l’homme, ou d’exposer leurs\nproches. Les déplacements à l’intérieur du pays et vers les pays voisins ont dès lors été\nsignificativement réduits et ont donc entraîné une nette diminution des activités\ncommerciales et une dégradation du tissu social et familial.\n9.     Dysfonctionnements du système judiciaire: les droits à un recours effectif et à un procès\néquitable"},{"id":"a-hrc-36-crp-1-p0614","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"614","seq":616,"section":"8. Liberté de circulation","text":"En dépit d’appels répétés aux autorités burundaises pour que des enquêtes soient\nmenées sur les allégations de violations des droits de l’homme commises1145, le Conseil des\ndroits de l’homme s’est déclaré en septembre 2016 « profondément préoccupé par les\ninformations selon lesquelles la plupart des violations et des atteintes sont commises par les\nforces de sécurité burundaises et les Imbonerakure, dans un climat d’impunité » et a déploré\n« que même dans les cas où des enquêtes ont été ouvertes sur de graves violations des droits\nde l’homme ou atteintes à ces droits, cela n’ait pas abouti à des résultats crédibles »1146. Le\nConseil des droits de l’homme a mis l’accent sur le dysfonctionnement et le manque croissant\nd’indépendance de la justice au Burundi, une situation décrite par le Haut-Commissaire des\nNations Unies aux droits de l’homme et l’EINUB dans leurs rapports respectifs1147. L’EINUB\na notamment relevé que la crise au Burundi « a renforcé la domination systématique et\ninstitutionnelle préexistante du pouvoir exécutif sur le pouvoir judiciaire »1148."},{"id":"a-hrc-36-crp-1-p0615","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"615","seq":617,"section":"8. Liberté de circulation","text":"La Commission a examiné le droit à un recours effectif et celui à un procès équitable\ndans le même chapitre, ces deux droits étant liés : un procès équitable ne pouvant avoir lieu\nsans la possibilité d’un recours effectif et ce dernier ne pouvant être garanti en dehors d’un\nsystème judiciaire indépendant et efficace1149.\n(a)      Droit à un recours effectif\n(i)      Droit applicable\nDroit international"},{"id":"a-hrc-36-crp-1-p0616","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"616","seq":618,"section":"8. Liberté de circulation","text":"L’article 8 de la DUDH et l’article 2 (3) du PIDCP garantissent à toute personne dont\nles droits auraient été violés de pouvoir exercer un recours devant une autorité compétente. Si\nla DUDH limite ce droit à un recours aux seules « juridictions nationales compétentes », le\nPIDCP étend la notion d’« autorité compétente » aux autorités « judiciaire, administrative ou\nlégislative, ou toute autre autorité compétente selon la législation de l'État ». Le PIDCP\nprécise que le recours doit pouvoir s’exercer « alors même que la violation aurait été\ncommise par des personnes agissant dans l'exercice de leurs fonctions officielles », et que\nl’État partie au Pacte doit « garantir la bonne suite donnée par les autorités compétentes à tout\nrecours qui aura été reconnu justifié »1150."},{"id":"a-hrc-36-crp-1-p0617","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"617","seq":619,"section":"8. Liberté de circulation","text":"Dans son observation générale n° 31 sur la nature de l’obligation juridique générale\nimposée aux États parties au Pacte, le Comité des droits de l’homme lie le droit d’exercer un\nrecours à l’obligation de protéger et celle pour l’État de conduire dans les meilleurs délais des\nenquêtes indépendantes, approfondies et efficaces1151. Cette exigence est, dans l’esprit du\nComité des droits de l’homme, un moyen parmi d’autres de prévenir et punir une violation."},{"id":"a-hrc-36-crp-1-p0618","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"618","seq":620,"section":"8. Liberté de circulation","text":"Par son interprétation du recours effectif, le Comité des droits de l’homme rejoint la\nCCT qui consacre l’obligation pour l’État de mener des enquêtes. L’article 12 de la\nConvention dispose en effet que « tout État partie veille à ce que les autorités compétentes\nprocèdent immédiatement à une enquête impartiale chaque fois qu'il y a des motifs\nraisonnables de croire qu'un acte de torture a été commis sur tout territoire sous sa\njuridiction ». De la même manière, l’article 6 de la CCT fait obligation à l’État partie de\ndétenir toute personne se trouvant sur son territoire, soupçonnée d'avoir commis une\ninfraction visée par la Convention et de procéder « immédiatement à une enquête\npréliminaire en vue d'établir les faits »."},{"id":"a-hrc-36-crp-1-p0619","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"619","seq":621,"section":"8. Liberté de circulation","text":"Le Comité des droits de l’homme lie également le droit à un recours effectif à\nl’obligation pour l’État, à l’issue d’une enquête impartiale, de poursuivre et traduire en\njustice les responsables de violations des droits énoncés dans le Pacte, en particulier la torture\net les traitements cruels, inhumains ou dégradants, les exécutions sommaires et arbitraires et\nles disparitions forcées. Le Comité insiste sur les cas où des fonctionnaires ou des agents de\nl’État ont violé les droits énoncés dans le Pacte. Ces derniers ne pourraient être exonérés de\nleur responsabilité personnelle, notamment par le biais d’amnisties, d’immunités préalables,\nou par « un moyen de défense fondé sur l’obéissance à des ordres supérieurs ou des délais de\nprescription excessivement brefs dans les cas où de tels délais de prescription sont\nadmissibles »1152."},{"id":"a-hrc-36-crp-1-p0620","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"620","seq":622,"section":"8. Liberté de circulation","text":"Le Comité des droits de l’homme, toujours dans son observation générale n° 31, lie\nenfin le droit d’exercer un recours à l’obtention pour la victime d’une réparation. Le PIDCP\nreconnaît expressément un droit à réparation dans deux cas : quand une personne est victime\nd'arrestation ou de détention illégale et « lorsqu'une condamnation pénale définitive est\nultérieurement annulée ou lorsque la grâce est accordée parce qu'un fait nouveau ou\nnouvellement révélé prouve qu'il s'est produit une erreur judiciaire »1153. La CCT prévoit\négalement que « tout État partie garantit, dans son système juridique, à la victime d'un acte de\ntorture, le droit d'obtenir réparation et d'être indemnisée équitablement et de manière\nadéquate, y compris les moyens nécessaires à sa réadaptation la plus complète possible. En\ncas de mort de la victime résultant d'un acte de torture, les ayants cause de celle-ci ont droit à\nindemnisation »1154.\nDroit régional"},{"id":"a-hrc-36-crp-1-p0621","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"621","seq":623,"section":"8. Liberté de circulation","text":"L’article 7 (1) (a) de la CADHP dispose que tout individu a « le droit de saisir les\njuridictions nationales compétentes de tout acte violant les droits fondamentaux qui lui sont\nreconnus et garantis par les conventions, les lois, règlements et coutumes en vigueur ». Cette\ndisposition se contente de prévoir le droit de recours aux juridictions nationales compétentes,\nsans autre précision. Néanmoins, en 2003, la Commission africaine des droits de l’homme et\ndes peuples a adopté des Directives et Principes sur le droit à un procès équitable et à\nl’assistance judiciaire en Afrique qui offrent une interprétation plus extensive du droit à un\nrecours effectif1155. Le Principe C prévoit ainsi que « le droit à un recours effectif intègre : (1)\nl’accès à la justice, (2) la réparation des préjudices subis, (3) l’accès aux informations\nconcrètes concernant les violations ».\nDroit national"},{"id":"a-hrc-36-crp-1-p0622","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"622","seq":624,"section":"8. Liberté de circulation","text":"Le droit à un recours effectif devant une autorité compétente ne figure pas comme tel\ndans la Constitution du Burundi. Toutefois, le Burundi étant un système moniste, les\nconventions internationales font théoriquement dès leur ratification partie intégrante du droit\nnational. À ce titre, le droit à un recours effectif tel que prévu par le PIDCP, ratifié en 1990\npar le Burundi, est un droit consacré en droit burundais.\n(ii)     Faits\nObligation d’ouvrir et de mener des enquêtes"},{"id":"a-hrc-36-crp-1-p0623","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"623","seq":625,"section":"8. Liberté de circulation","text":"La Commission, en l’état des informations à sa disposition, a constaté que des\nenquêtes crédibles n’ont pas été menées dans la majorité des cas de violation et d’atteinte aux\ndroits de l’homme commise par des agents de l’État ou des Imbonerakure qu’elle a\ndocumentés."},{"id":"a-hrc-36-crp-1-p0624","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"624","seq":626,"section":"8. Liberté de circulation","text":"Les autorités burundaises ont souvent cherché à justifier cette situation en avançant le\nfait que les victimes ou leurs proches ne portent pas plainte1156. Or, le Code de procédure\npénale, tout comme le droit international des droits de l’homme, précise que « même en\ndehors de toute dénonciation ou plainte, le Procureur de la République se saisit d’office dès\nqu’il a connaissance d’une infraction »1157. Au vu des nombreuses violations et atteintes\nrapportées depuis 2015, notamment par les Nations Unies et plusieurs organisations des\ndroits de l’homme nationales et internationales, le Parquet burundais aurait dû communiquer\nde manière plus détaillée sur le nombre et l’état des enquêtes ouvertes, tout au moins sur les\ninfractions ayant été rapportées publiquement. Or, à la connaissance de la Commission, cela a\nrarement été fait, et des témoignages ont indiqué que même si les autorités annonçaient\nl’ouverture d’enquêtes, il n’y avait presque jamais de suite. Une femme dont le mari a été\nassassiné en 2015 a ainsi témoigné :\n« Au Burundi, la routine est quand quelqu’un meurt, on dit qu’on a ouvert une\nenquête, mais on n’entend rien. Le Procureur général a dit avoir ouvert une enquête\n[…] mais nous n’avons jamais été approchés »1158.\nUn avocat a rapporté : « Beaucoup d’affaires ont été introduites, mais aucune suite\nn’a été donnée. C’est une justice qui est prise en otage […] Il y a une liste de cas qui\nont été soumis à la justice burundaise pour lesquels rien n’a été fait »1159."},{"id":"a-hrc-36-crp-1-p0625","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"625","seq":627,"section":"8. Liberté de circulation","text":"La Commission regrette encore une fois de n’avoir pas eu accès au Burundi. Cela lui\naurait permis d’engager un dialogue avec les autorités judiciaires et de faire un état des lieux\nplus précis de leurs réponses aux allégations de violations et d’atteintes aux droits de\nl’homme ainsi que de l’avancement des dossiers sur les cas décrits dans le présent rapport."},{"id":"a-hrc-36-crp-1-p0626","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"626","seq":628,"section":"8. Liberté de circulation","text":"De nombreuses victimes ou leurs proches interrogés par la Commission ont expliqué\nqu’ils n’ont pas porté plainte, soit par crainte de représailles, soit par manque de confiance\ndans le fonctionnement et l’indépendance du système judiciaire1160. Interrogée sur les raisons\npour lesquelles elle n’avait pas porté plainte suite à son passage à tabac par des\nImbonerakure, une victime a répondu :\n« Les Imbonerakure agissent en complicité avec les autorités, qui sont bien au courant\nde leurs forfaits. Je n’ai aucune confiance dans la justice »1161.\nUne autre victime, arrêtée et torturée en avril 2017 par des agents du SNR et de la\npolice, puis libérée sans aucune procédure, a déclaré à la Commission : « Où aurais-je\npu porter plainte à moins que je ne veuille la mort ? »1162.\nObligation de mener des enquêtes indépendantes, approfondies et efficaces"},{"id":"a-hrc-36-crp-1-p0627","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"627","seq":629,"section":"8. Liberté de circulation","text":"Dans les cas où des enquêtes ont été ouvertes, la Commission a reçu plusieurs\ntémoignages indiquant que ces enquêtes n’ont été que très rarement conduites de manière\nindépendante, approfondie et efficace. Les efforts déployés par les autorités en charge des\nenquêtes n’ont bien souvent pas été satisfaisants, alors même que, dans certains cas\ndocumentés par la Commission, les victimes ou leurs proches avaient identifié les noms de\ncertains auteurs présumés1163. La Commission a notamment été informée d’un cas où la\npolice s’est rendue sur la scène d’un crime et a interrogé des témoins qui étaient en mesure\nd’identifier un des auteurs présumés mais n’a pris aucune note au cours des entretiens qu’elle\na menés. Un membre de la famille de la victime a témoigné:\n« Parmi ceux qui ont tué [X], on a pu identifier l’un d’entre eux […] Nous avons\nentendu sa voix quand il toquait à la porte puisque c’est quelqu’un que nous\nconnaissions très bien et dont nous pouvions identifier la voix […] Au lendemain des\nfaits, les policiers sont venus pour des enquêtes. Ils ont demandé s’il y avait des\nindices. J’ai dit qu’il y en avait : que c’était la voix de [Y, un Imbonerakure] que\nj’avais entendue. Les policiers sont partis […] Je ne sais pas ce qui s’est passé en ce\nqui concerne l’enquête […] Ils ont posé des questions sans prendre de notes. Ils n’ont\narrêté personne » 1164."},{"id":"a-hrc-36-crp-1-p0628","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"628","seq":630,"section":"8. Liberté de circulation","text":"L’absence de volonté des autorités burundaises de mener des enquêtes indépendantes,\napprofondies et efficaces est particulièrement flagrante à la lecture des rapports des trois\ncommissions d’enquête mises en place en 2015 et 2016 par le Procureur général de la\nRépublique pour mener des investigations sur certains événements particulièrement graves, à\nsavoir :\n• la commission d’enquête « chargée de faire la lumière sur le mouvement\ninsurrectionnel déclenché le 26 avril 2015 à Bujumbura », dont le rapport a été publié\nen août 2015,\n• la commission « chargée d’enquêter sur les différents actes répréhensibles par la loi\npénale commis en date du 13 octobre 2015 dans la zone Ngagara en commune\nNtahangwa, Bujumbura », dont le rapport a été rendu public en décembre 2015, et\n• la commission « chargée de faire la lumière sur les allégations « d’exécutions\nextrajudiciaires » lors des combats qui ont suivi l’attaque contre quatre camps\nmilitaires le 11 décembre 2015 », dont le rapport a été publié en mars 2016."},{"id":"a-hrc-36-crp-1-p0629","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"629","seq":631,"section":"8. Liberté de circulation","text":"Ces enquêtes, de manière générale, n’ont pas cherché à établir la responsabilité\nd’agents étatiques dans les violations commises lors des événements qu’elles ont couverts,\npréférant imputer la quasi-totalité des violations à des groupes d’opposition, ou même à des\nreprésentants d’organisations de la société civile. Parmi les rares exceptions, le Major\nmilitaire Marius Gahomera et le Chef de poste de police Jean-Louis Surwavuba ont été cités\ndans le rapport de la commission d’enquête sur les événements du 11 décembre 2015, en lien\navec la mort de sept combattants capturés."},{"id":"a-hrc-36-crp-1-p0630","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"630","seq":632,"section":"8. Liberté de circulation","text":"Le titre même de la commission d’enquête établie afin « de faire la lumière sur le\nmouvement insurrectionnel déclenché le 26 avril 2015 » laisse de prime abord entendre que\nles manifestations organisées contre le nouveau mandat du Président Nkurunziza faisaient\npartie d’une insurrection. Cette commission relève que « les violations des droits de l’homme\nsous forme d’assassinats et autres ont été commises soit sur des civils soit sur des policiers ou\nmilitaires », sans donner toutefois de détails sur les types et la proportion de violations\ncommises à l’encontre des uns et des autres1165. Privilégiant la thèse du soulèvement contre\nles autorités, la commission a focalisé ses enquêtes sur les actes perpétrés contre les corps de\ndéfense et de sécurité ainsi que contre des Imbonerakure par des personnes qualifiées\nd’« insurgés », sans examiner de près les allégations de violations des droits de l’homme\ncommises par les forces de l’ordre à l’encontre de civils. Au contraire, le rapport note que\n« si [la police] n’avait pas fait preuve de retenue et de professionnalisme, il y aurait eu\nbeaucoup de personnes tuées du côté des insurgés car ces derniers ont, à maintes reprises,\ntenté de s’emparer des armes de ces policiers »1166."},{"id":"a-hrc-36-crp-1-p0631","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"631","seq":633,"section":"8. Liberté de circulation","text":"La commission d’enquête ne fait aucune distinction entre lesdits « insurgés » et les\nmanifestants qui, comme décrit dans le présent rapport, ont été victimes de violations graves\ndes droits de l’homme, en particulier par des agents de la police et du SNR. Cette\ncommission d’enquête fait par ailleurs un lien, sans pour autant le démontrer, entre les\npersonnes impliquées dans les manifestations contre un nouveau mandat du Président de la\nRépublique et les responsables du coup d’État manqué du 13 mai 20151167. Les\nresponsabilités sont attribuées de manière générale sans spécifier les actes reprochés aux\nindividus incriminés. La commission d’enquête, sans avoir apparemment procédé à des\ninvestigations au cas par cas et sans présenter aucun argument de droit et de fait, note :\n« Tous ceux qui sont impliqués dans le dossier relatif à l’atteinte à l’autorité de l’État sont\nmutatis mutandis impliqués dans les infractions relatives à cette insurrection […] Toutes ces\npersonnes, arrêtées et recherchées, sont pénalement et civilement responsables des infractions\nde détention illégale d’armes à feu, participation à un mouvement insurrectionnel, coups et\nblessures volontaires graves, destructions « méchantes », assassinats, atteinte à la sûreté\nintérieure de l’État et d’attentat contre l’autorité de l’État »1168."},{"id":"a-hrc-36-crp-1-p0632","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"632","seq":634,"section":"8. Liberté de circulation","text":"Le rapport de la commission « chargée d’enquêter sur les différents actes\nrépréhensibles par la loi pénale commis en date du 13 octobre 2015 dans la zone Ngagara en\ncommune de Ntahangwa »1169, publié en décembre 2015, soulève des interrogations\nsimilaires1170. Cette commission avait pour objectif d’enquêter sur « tous les cas de tueries et\nautres infractions qui ont été enregistrées dans la localité […], à en identifier les auteurs,\nétablir la part de responsabilité de chacun, qualifier les faits et traduire immédiatement les\nauteurs devant la juridiction compétente »1171. À l’instar de la commission précédente, elle a\nconcentré ses investigations sur les infractions commises à l’encontre des forces de l’ordre en\nabordant de manière succincte la mort de neuf civils pour laquelle le présent rapport a établi\ndans certains cas la responsabilité d’agents de l’API1172. Au contraire, la commission\nd’enquête attribue la responsabilité de toutes les infractions commises le 13 octobre 2015 à\nun groupe de malfaiteurs composé de « jeunes » identifiés par des témoins1173. D’après son\nrapport, la commission d’enquête ne semble pas avoir interrogé tous les témoins, en\nparticulier les proches des victimes, ni examiné toutes les informations disponibles sur ces\nfaits. La commission se contente de relever que les habitants des lieux où se sont déroulés les\névénements « ne voient pas d’intérêt à s’exprimer devant des envoyés du Gouvernement dont\nles enquêtes n’aboutissent à rien »1174."},{"id":"a-hrc-36-crp-1-p0633","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"633","seq":635,"section":"8. Liberté de circulation","text":"Le mandat de la troisième commission d’enquête mise en place par le Procureur\ngénéral de la République portait initialement sur l’attaque des installations militaires à\nBujumbura et ses environs le 11 décembre 20151175. Le 4 janvier 2016, ce mandat a été élargi\naux allégations d’existence de fosses communes rapportées par diverses sources. Des\nrapports des Nations Unies et d’organisations des droits de l’homme ont fait état de\nnombreuses exécutions sommaires, ainsi que de tortures, de violences sexuelles et\nd’arrestations arbitraires par des agents des forces de sécurité les 11 et 12 décembre 2015 en\nreprésailles de l’attaque des installations militaires1176. La commission d’enquête s’est pour\nsa part limitée aux attaques du 11 décembre 2015 et a conclu que 79 « combattants » ont été\ntués ainsi que quatre militaires et quatre policiers1177. Son rapport qualifie la majorité des\nvictimes de « combattants », assurant que l’administration a procédé à l’identification des\ncadavres retrouvés. Pourtant, le rapport ne mentionne que les identités de six corps et note\nque le travail d’identification « n’a pas été facile. D’une part la plupart des personnes\nretrouvées mortes ne possédaient aucune pièce d’identité, d’autre part les habitants [des\nlocalités où les corps ont été retrouvés] n’ont pas accepté de participer à cette opération\nd’identification [...] [par] peur des représailles »1178. En dépit de ces obstacles majeurs, la\ncommission d’enquête avalise le travail d’identification qui aurait été mené par\nl’administration ainsi que la décision des administrateurs des communes où des cadavres ont\nété trouvés de procéder rapidement à leur inhumation. La commission d’enquête base\nnotamment ses conclusions sur le fait que certains individus retrouvés morts portaient des\ntenues militaires ou policières et que d’autres étaient en possession d’armes, ce qui, à ses\nyeux, démontre qu’il s’agit soit de membres des corps de défense et de sécurité soit\nd’assaillants1179. Cependant, les témoignages recueillis par la présente Commission ont au\ncontraire indiqué que de nombreux corps retrouvés dans les quartiers de Bujumbura,\nnotamment à Nyakabiga et Musaga, portaient des tenues civiles et des habitants de certains\nquartiers ont reconnu parmi les victimes des voisins qui étaient des civils1180."},{"id":"a-hrc-36-crp-1-p0634","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"634","seq":636,"section":"8. Liberté de circulation","text":"La commission d’enquête sur les événements du 11 décembre 2015 a en outre conclu\nqu’il n’existait aucune fosse commune en lien avec ces événements1181, bien qu’elle n’ait pas\neu les moyens médico-légaux permettant d’établir l'existence de fosses communes. Au\nsurplus, la commission d’enquête s’est satisfaite d’avoir conduit ses enquêtes en s’entretenant\navec des « sources concordantes », sans qu’il ne soit donné de détails ni fait référence à\nd’éventuelles excavations1182. Par contre, la présente Commission a recueilli des témoignages\nsur l’enterrement de corps dans des fosses communes suite aux événements du 11 décembre\n20151183. L’EINUB a également noté en 2016, sur la base de témoignages, appuyés par\nl’analyse d’images satellitaires, que des corps auraient été enterrés dans des fosses communes\nautour des 11 et 12 décembre 2015, y compris à Kanyosha (Bujumbura) et à Mpanda.\nL’EINUB a en outre relevé des cas « d'intimidation de personnes en possession\nd'informations sur ce sujet par des membres des Imbonerakure et du SNR »1184.\nPoursuites contre les auteurs présumés de violations et d’atteintes"},{"id":"a-hrc-36-crp-1-p0635","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"635","seq":637,"section":"8. Liberté de circulation","text":"Selon les informations à la disposition de la Commission, peu de poursuites pénales\nont été initiées contre les auteurs présumés des violations graves des droits de l’homme\ncommises depuis avril 2015. Or, sans poursuite, il est impossible de garantir les droits des\nvictimes de violations des droits de l’homme à une réparation."},{"id":"a-hrc-36-crp-1-p0636","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"636","seq":638,"section":"8. Liberté de circulation","text":"Le cas du Major Marius Gahomera, commandant du 221ème bataillon d’infanterie de la\nFDNB est révélateur de ce climat d’impunité. Son nom a été cité dans le rapport de la\ncommission d’enquête sur les événements du 11 décembre 2015, qui indique : « Sept\ncombattants capturés à Mujejuru ont été retrouvés morts. L’enquête a révélé qu’ils auraient\nété tués par Surwavuba Jean-Bosco et Major Gahomera Marius »1185. La présente\nCommission a recueilli plusieurs témoignages identifiant le Major Gahomera comme auteur\nprésumé d’autres violations graves des droits de l'homme depuis avril 20151186. Malgré ces\nallégations, le Major Gahomera n’a pas été à ce jour arrêté, ni traduit en justice et reste en\nfonction au sein de l’armée selon les informations à la disposition de la Commission. La\nprésente Commission n’a pas pu obtenir d’informations sur l’évolution du dossier du Chef de\nposte de police Jean-Bosco Surwavuba, qui aurait déclaré à la commission d’enquête sur les\névénements du 11 décembre 2015 que les combattants capturés lui auraient bien été remis\nmais qu’il n’avait pas eu connaissance de leur décès1187."},{"id":"a-hrc-36-crp-1-p0637","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"637","seq":639,"section":"8. Liberté de circulation","text":"L’impunité ne bénéficie pas seulement aux membres des corps de défense et de\nsécurité, auteurs présumés de violations des droits de l’homme, mais également aux\nImbonerakure1188. Un témoin a ainsi rapporté à la Commission:\n« Mon voisin n’avait pas d’appartenance politique, mais il a été enlevé en mai 2016.\nJusqu’à aujourd’hui, il est resté introuvable. Le jour où il a été enlevé, [deux\nImbonerakure] lui [ont] montré un mandat du procureur de la province […] Il n’y\navait pas de policiers présents. Et ces hommes sont encore puissants dans la\ncommune. On n’a jamais retrouvé [mon voisin]. Il n’a été retrouvé dans aucune\nprison du pays […] À l’époque, on avait arrêté les deux Imbonerakure dans le cadre\nde cette affaire. Mais en une semaine, ils ont été relâchés grâce à leurs contacts\nauprès des autorités provinciales et communales ainsi que des gens du renseignement.\n[Quelque temps après, un] vendeur du marché a été tué [en] 2016 par erreur, car on\ncherchait à tuer son cousin. Après les enquêtes de la police, il a été démontré que les\ndeux Imbonerakure précités étaient responsables du meurtre. Une deuxième fois, ils\nont été arrêtés et relâchés en moins de deux semaines. Moi-même j’ai été battu [en\n2016] par ces mêmes hommes […] En revenant à mon lieu de travail, j’ai rencontré\nces deux hommes qui m’ont blessé […] Je suis allé déposer une plainte contre ces\ndeux personnes, mais l’officier de police n’a jamais été disponible pour me rencontrer\nafin de recevoir ma plainte. Rien n’a été fait. » 1189.\nUne autre personne a déclaré qu’en 2015 des Imbonerakure l’ont battue, ainsi que\ntrois de ses amis. Ces mêmes Imbonerakure auraient également été impliqués dans\nplusieurs autres crimes: « Les Imbonerakure ont pris un autre jeune […] Ils l’ont tué\nen l’accusant du viol d’une femme. Celui qui a tué ce garçon a passé seulement un\nmois en prison, puisque son père était le responsable de la prison […] La famille du\ngarçon qui a été tué a porté plainte à la justice. Mais rien n’a bougé »1190.\n(b)      Droit à un procès équitable\n(i)      Droit applicable\nDroit international"},{"id":"a-hrc-36-crp-1-p0638","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"638","seq":640,"section":"8. Liberté de circulation","text":"La DUDH1191 et le PIDCP garantissent l’égalité de chaque individu devant les\ntribunaux et les cours de justice, ainsi que le droit à ce que « sa cause soit entendue\néquitablement et publiquement par un tribunal compétent, indépendant et impartial, établi par\nla loi, qui décidera soit du bien-fondé de toute accusation en matière pénale dirigée contre\n[lui], soit des contestations sur ses droits et obligations de caractère civil »1192."},{"id":"a-hrc-36-crp-1-p0639","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"639","seq":641,"section":"8. Liberté de circulation","text":"Dans son observation générale n° 32, le Comité des droits de l’homme a considéré que\nla notion d’équité « implique l’absence de toute influence, pression, intimidation ou\ningérence, directe ou indirecte, de qui que ce soit et pour quelque motif que ce soit » dans les\nprocédures judiciaires. Le Comité a également noté qu’« un élément important du procès\néquitable est la rapidité de la procédure »1193. En matière pénale, l’article 14 (3) du PIDCP\nprévoit à cet égard que les affaires doivent être jugées « sans retard excessif ». Le Comité des\ndroits de l’homme précise en outre que « lorsque les retards sont dus au manque de\nressources et à l’insuffisance chronique des crédits, l’État partie devra, dans la mesure du\npossible, allouer des ressources budgétaires supplémentaires à l’administration de la\njustice »1194."},{"id":"a-hrc-36-crp-1-p0640","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"640","seq":642,"section":"8. Liberté de circulation","text":"Le Comité des droits de l’homme a précisé comme suit la notion de tribunal\ncompétent, indépendant et impartial contenu dans l’article 14 (1) du PIDCP : « le terme «\ntribunal » […] désigne un organe, quelle que soit sa dénomination, qui est établi par la loi,\nqui est indépendant du pouvoir exécutif et du pouvoir législatif ou, dans une affaire donnée,\nqui statue en toute indépendance sur des questions juridiques dans le cadre de procédures à\ncaractère judiciaire »1195. La garantie de compétence, d’indépendance et d’impartialité du\ntribunal, telle que définie, « ne souffre aucune exception »1196. Le Comité des droits de\nl’homme précise que « la garantie d’indépendance porte, en particulier, sur la procédure de\nnomination des juges, les qualifications qui leur sont demandées et leur inamovibilité jusqu’à\nl’âge obligatoire de départ à la retraite ou l’expiration de leur mandat pour autant que des\ndispositions existent à cet égard; les conditions régissant l’avancement, les mutations, les\nsuspensions et la cessation de fonctions; et l’indépendance effective des juridictions de toute\nintervention politique de l’exécutif et du législatif »1197. Le Comité affirme : « une situation\ndans laquelle les fonctions et les attributions du pouvoir judiciaire et du pouvoir exécutif ne\npeuvent pas être clairement distinguées et dans laquelle le second est en mesure de contrôler\nou de diriger le premier est incompatible avec le principe de tribunal indépendant »1198."},{"id":"a-hrc-36-crp-1-p0641","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"641","seq":643,"section":"8. Liberté de circulation","text":"En matière pénale, le PIDCP dresse une liste des garanties auxquelles a droit toute\npersonne accusée d’une infraction. Il s’agit de la présomption d’innocence jusqu’à ce que sa\nculpabilité ait été légalement établie, mais aussi, aux termes de l’article 14 (2) du Pacte, de\nson droit :\n« a) à être informée, dans le plus court délai, dans une langue qu'elle comprend et de\nfaçon détaillée, de la nature et des motifs de l'accusation portée contre elle ;\nb) à disposer du temps et des facilités nécessaires à la préparation de sa défense et à\ncommuniquer avec le conseil de son choix ;\nc) à être jugée sans retard excessif ;\nd) à être présente au procès et à se défendre elle-même ou à avoir l'assistance d'un\ndéfenseur de son choix ; si elle n'a pas de défenseur, à être informée de son droit d'en\navoir un, et, chaque fois que l'intérêt de la justice l'exige, à se voir attribuer d'office un\ndéfenseur, sans frais, si elle n'a pas les moyens de le rémunérer ;\ne) à interroger ou faire interroger les témoins à charge et à obtenir la comparution et\nl'interrogatoire des témoins à décharge dans les mêmes conditions que les témoins à\ncharge ; [...]\ng) à ne pas être forcée de témoigner contre elle-même ou de s'avouer coupable ».\nDroit régional"},{"id":"a-hrc-36-crp-1-p0642","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"642","seq":644,"section":"8. Liberté de circulation","text":"La CADHP prévoit que « toute personne a droit à ce que sa cause soit entendue ». En\nvertu de l’article 7 (1) de la Charte, « ce droit comprend :\na) le droit de saisir les juridictions nationales compétentes de tout acte violant les\ndroits fondamentaux qui lui sont reconnus et garantis par les conventions, les lois,\nrèglements et coutumes en vigueur ;\nb) le droit à la présomption d'innocence, jusqu'à ce que sa culpabilité soit établie par\nune juridiction compétente ;\nc) le droit à la défense, y compris celui de se faire assister par un défenseur de son\nchoix ;\nd) le droit d'être jugé dans un délai raisonnable par une juridiction impartiale »."},{"id":"a-hrc-36-crp-1-p0643","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"643","seq":645,"section":"8. Liberté de circulation","text":"Dans les Directives et Principes sur le droit à un procès équitable et à l’assistance\njudiciaire en Afrique qu’elle a adoptés en 2003, la Commission africaine des droits de\nl’homme et des peuples définit les critères d’une justice indépendante, équitable et impartiale\nqui, dans leur ensemble, rejoignent ceux énoncés par le Comité des droits de l’homme sur la\nbase du PIDCP1199. L’article 26 de la CADHP dispose par ailleurs que « les États parties à la\nprésente Charte ont le devoir de garantir l'indépendance des tribunaux ».\nDroit national"},{"id":"a-hrc-36-crp-1-p0644","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"644","seq":646,"section":"8. Liberté de circulation","text":"L’article 209 de la Constitution burundaise dispose que « le pouvoir judiciaire est\nimpartial et indépendant du pouvoir législatif et du pouvoir exécutif » et que « dans\nl’exercice de ses fonctions, le juge n’est soumis qu’à la Constitution et à la loi »."},{"id":"a-hrc-36-crp-1-p0645","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"645","seq":647,"section":"8. Liberté de circulation","text":"L’article 38 de la Constitution garantit également l’accès à une justice équitable :\n« Toute personne a droit, dans une procédure judiciaire ou administrative, à ce que sa cause\nsoit entendue équitablement et à être jugée dans un délai raisonnable ». L’article 206 dispose\nque « les audiences des juridictions sont publiques, sauf cas de huis clos prononcé par\ndécision judiciaire, lorsque la publicité est dangereuse pour l’ordre public ou les bonnes\nmœurs » et l’article 207 précise que « toute décision judiciaire doit être motivée avant d’être\nprononcée en audience publique »."},{"id":"a-hrc-36-crp-1-p0646","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"646","seq":648,"section":"8. Liberté de circulation","text":"Les autres garanties en matière pénale sont développées dans le Code de procédure\npénale qui prévoit notamment le droit de l’inculpé d’être informé de ses droits1200 , les droits\nde la défense1201 , les délais de procédure et les modalités de recours.\n(ii)     Faits"},{"id":"a-hrc-36-crp-1-p0647","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"647","seq":649,"section":"8. Liberté de circulation","text":"En 2000, l’Accord d’Arusha pour la paix et la réconciliation au Burundi a identifié le\nnon-respect du principe de séparation des pouvoirs et le manque d’indépendance de la\nmagistrature parmi les principales causes de la violence et de l’insécurité dans le pays1202.\nAfin d’y remédier, la Constitution de 2005 garantit l’indépendance du pouvoir judiciaire par\nrapport aux pouvoirs exécutif et législatif1203. Malgré cette garantie, plusieurs organes et\nobservateurs internationaux ont fait état d’une sujétion à la fois structurelle et de fait de la\njustice burundaise aux autres pouvoirs. Depuis avril 2015, le Comité pour l’élimination de la\ndiscrimination à l’égard des femmes, le Comité contre la torture, ainsi que le Comité des\ndroits économiques, sociaux et culturels et le Comité des droits de l’homme ont mis l’accent\nsur l’absence d’indépendance de la justice au Burundi1204. Auparavant, le Rapporteur spécial\nsur la promotion de la vérité, de la justice, de la réparation et des garanties de non-répétition\navait également déploré cette situation en dépit des quelques progrès qui avaient été\nréalisés1205.\nAbsence d’indépendance structurelle du pouvoir judiciaire et manque de ressources"},{"id":"a-hrc-36-crp-1-p0648","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"648","seq":650,"section":"8. Liberté de circulation","text":"L’article 209 de la Constitution, comme indiqué plus haut, prévoit que « le pouvoir\njudiciaire est impartial et indépendant du pouvoir législatif et du pouvoir exécutif » et fait du\nPrésident de la République le « garant de l’indépendance de la magistrature ». Ce dernier est\nassisté dans cette tâche par le Conseil supérieur de la magistrature qui est par ailleurs en\ncharge de connaître des plaintes des particuliers ou de l’Ombudsman concernant le\ncomportement professionnel des magistrats1206, et de définir la politique de la nation en\nmatière de justice, de suivre la situation du pays dans le domaine judiciaire et dans celui des\ndroits de l’homme et d’élaborer des stratégies en matière de lutte contre l’impunité."},{"id":"a-hrc-36-crp-1-p0649","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"649","seq":651,"section":"8. Liberté de circulation","text":"La composition du Conseil supérieur de la magistrature est toutefois caractérisée par\nune domination du pouvoir exécutif. Le Président de la République préside cette institution,\nle Ministre de la justice à ses côtés1207. Le Conseil supérieur de la magistrature compte par\nailleurs cinq membres nommés par le Gouvernement, trois juges des juridictions supérieures,\ndeux magistrats relevant du ministère public, deux juges des tribunaux de résidence, et trois\nmembres exerçant une profession juridique dans le secteur privé; soit, sur un total de 15\nmembres, seulement sept magistrats désignés par leurs pairs1208 . Les autres membres sont\nnommés par le Ministère de la justice. En outre, le Conseil adopte ses décisions à la majorité\nsimple. En cas de partage des voix, celle du Président de la République est prépondérante."},{"id":"a-hrc-36-crp-1-p0650","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"650","seq":652,"section":"8. Liberté de circulation","text":"L’ascendant du pouvoir exécutif sur le pouvoir judiciaire se retrouve également dans\nles conditions de nomination des magistrats se faisant par décret du Président de la\nRépublique sur proposition du Ministre de la justice après avis du Conseil supérieur de la\nmagistrature, et, pour certains postes, confirmation par le Sénat1209. Ce n’est qu’en 2014\nqu’un concours a été organisé pour la première fois afin de recruter des juges1210. Si les\nmagistrats du siège sont nommés à vie, ils sont néanmoins susceptibles d’être déplacés pour\nexercer des fonctions de même grade auprès d’une juridiction de même rang1211. Cette\ndisposition remet en cause le principe d’inamovibilité des juges. En cas de faute\nprofessionnelle ou incompétence, le Ministre de la justice peut proposer, après avis du\nConseil supérieur de la magistrature, la mise en disponibilité d’un magistrat pour une durée\nmaximale de six mois ou sa révocation. La décision finale revient au Président de la\nRépublique1212. Dans ce cas, le magistrat ne dispose d’un recours que devant le Conseil\nsupérieur de la magistrature qui a pourtant déjà donné un avis favorable à la sanction décidée\ncontre lui1213. Le Ministère de la justice contrôle en outre la notation, l’avancement et le\nniveau de rémunération1214 des magistrats. Une personne qui avait travaillé au sein du\nsystème judiciaire a ainsi témoigné :\n« [Le] pouvoir judiciaire […] dépend de l’Exécutif. Même le recrutement dépend des\nliens avec des politiques : soit des ministres, soit des parlementaires. Qui n’est pas\nmembre du CNDD-FDD n’a aucune possibilité d’avancement » 1215."},{"id":"a-hrc-36-crp-1-p0651","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"651","seq":653,"section":"8. Liberté de circulation","text":"En août 2013, des états généraux de la justice, organisés par le Gouvernement\nburundais en partenariat avec le Bureau des Nations Unies au Burundi (BNUB), le\nProgramme des Nations unies pour le développement (PNUD) et la Coopération technique\nbelge, se sont tenus à Gitega afin de formuler des recommandations pour améliorer le\nfonctionnement de la justice au Burundi1216. Plusieurs propositions ont été faites parmi\nlesquelles une réforme du Conseil supérieur de la magistrature qui serait composé d’une\nmajorité de magistrats élus par leurs pairs et l’élection du Président de la Cour suprême\négalement par ses pairs pour un mandat de six ans non renouvelable1217. Ces propositions\nsont néanmoins restées lettres mortes. Jusqu’à ce jour, le Gouvernement n’a toujours pas\npublié le rapport final de ces états généraux de la justice, ce qu’a notamment déploré le\nComité contre la torture en 20161218."},{"id":"a-hrc-36-crp-1-p0652","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"652","seq":654,"section":"8. Liberté de circulation","text":"La justice au Burundi souffre également d’un manque structurel de ressources. En\naoût 2015, le Rapporteur spécial sur la promotion de la vérité, de la justice, de la réparation et\ndes garanties de non-répétition a noté dans son rapport au Conseil des droits de l’homme :\n« Les informations reçues montrent qu’environ 2 % seulement du budget national annuel est\nalloué au système de justice, ce qui est insuffisant pour lui permettre de s’acquitter\nefficacement de ses fonctions. Dans certaines juridictions, les ressources et les équipements\nles plus essentiels font défaut »1219."},{"id":"a-hrc-36-crp-1-p0653","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"653","seq":655,"section":"8. Liberté de circulation","text":"En 2017, les fonds alloués au Ministère de la justice ne représentent, comme en 2016,\nqu’environ 1,8 % du budget général de la République du Burundi, soit le onzième poste de\ndépenses de l’État burundais1220. En comparaison, les budgets des Ministères de la défense\nnationale et de la sécurité publique représentent respectivement environ 11,2% et 6,7% du\nbudget national. L’essentiel du budget du Ministère de la justice est consacré à la\nrémunération et aux primes du personnel judiciaire. Les lignes budgétaires correspondant aux\nfrais de fonctionnement, de réhabilitation et d’équipement des infrastructures judiciaires sont\npeu pourvues. Le budget alloué à la Cour suprême et au Parquet général de la République ne\nreprésente qu’environ 3% du budget total du Ministère de la justice."},{"id":"a-hrc-36-crp-1-p0654","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"654","seq":656,"section":"8. Liberté de circulation","text":"De nombreuses personnes avec qui la Commission s’est entretenues ont soulevé le\nproblème de la corruption généralisée au sein du système judiciaire 1221. Plusieurs d'entre elles\nont indiqué avoir versé des sommes d'argent, par exemple à des procureurs ou à des\nmagistrats, notamment pour faire libérer des détenus ou pour obtenir une peine réduite au\nmoment de leur jugement1222.\nPressions sur les magistrats"},{"id":"a-hrc-36-crp-1-p0655","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"655","seq":657,"section":"8. Liberté de circulation","text":"Les pressions, qui existaient bien avant avril 2015, semblent s’être aggravées depuis.\nUn exemple marquant de cette situation a été donné par l’ancien Vice-Président de la Cour\nconstitutionnelle, Sylvère Nimpagaritse, contraint à l’exil après avoir exprimé une opinion\ndissidente à l’avis favorable de la Cour constitutionnelle donné le 5 mai 2015 sur la\npossibilité du Président Nkurunziza de se présenter à un nouveau mandat1223. Sylvère\nNimpagaritse a indiqué à RFI :\n« Le soir du 30 [avril 2015], on a déjà commencé à subir d’énormes pressions et\nmême des menaces de mort, mais on a eu le courage de revenir le lendemain. Le 1er\n[mai 2015], on a continué à délibérer. Ceux qui avaient soutenu que le\nrenouvellement du troisième mandat violait la Constitution et l’Accord d’Arusha ont\neu peur parce qu’ils ont subi des pressions, ils me l’ont dit. Et ils m’ont confié que si\njamais on ne se ravisait pas, on aura humilié le Président et que l’on risquait gros. On\nrisquait nos vies. Il fallait finalement se raviser et accepter de rejoindre le camp de\nceux qui soutiennent le troisième mandat. En mon âme et conscience, j’ai décidé de ne\npas apposer ma signature sur un arrêt, une décision qui était à côté de la loi. Je suis\nentré en clandestinité dès ce soir[-là] »1224."},{"id":"a-hrc-36-crp-1-p0656","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"656","seq":658,"section":"8. Liberté de circulation","text":"La Commission a noté que des magistrats et d’autres personnes travaillant dans le\nsystème judiciaire dans plusieurs provinces ont subi des pressions de la part de membres du\nGouvernement ou du parti au pouvoir, ainsi que de leurs pairs1225. Un témoin a rapporté :\n« [X] est un ancien membre du siège qui a jugé [un dossier politique important]. Les\n[autorités]ont demandé le délibéré aux juges avant qu’ils se prononcent et ont voulu\nqu'ils leur donnent le délibéré à l’avance, ce que les juges ont refusé de faire. Les\njuges ont été menacés. Après qu’ils ont prononcé le jugement, les juges ont été\nremplacés. [X] a fui »1226.\nUn avocat a rapporté : « Quelques magistrats sont professionnels. Mais ces derniers\nsont mis à l’écart. Ils gèrent juste des dossiers ordinaires. Le système a ses propres\nmagistrats pour la gestion de la répression politique. Ce sont ces magistrats qui sont\npromus »1227."},{"id":"a-hrc-36-crp-1-p0657","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"657","seq":659,"section":"8. Liberté de circulation","text":"Un climat de peur, comme celui qui décourage les victimes de porter plainte, est\nressenti à l’intérieur du système judiciaire même. La Commission a notamment été informée\nde pressions exercées sur des magistrats par des présidents de tribunaux ou des membres du\nParquet1228. Des mesures, notamment des mutations vers des localités éloignées, ont été\nprises à l’encontre du personnel judiciaire perçu comme étant non-aligné au CNDD-FDD ou\nqui ne suivait pas les instructions du pouvoir exécutif ou d’autres autorités. Par exemple, la\nCommission a reçu des informations à propos d’un juge qui aurait été muté d’une province\nvers une autre après avoir écarté, faute de preuves, les charges pesant sur un membre d’un\nparti d’opposition1229. Une autre personne a vu le magistrat responsable de son cas remplacé\naprès qu’aucune charge n’ait été retenue contre elle. Suite à ce remplacement, les accusations\nont changé et la personne a été condamnée à la prison à perpétuité1230. Dans au moins un cas,\nles magistrats ont admis que le dossier de l’accusé était vide, mais ont exprimé des craintes\npour sa sécurité s’il était libéré :\n« Les magistrats ont même dit à mon avocat que le dossier était un montage et qu’on\nm’accusait seulement car j’étais un ex-FAB. Les magistrats ont dit qu’ils pouvaient\nme libérer à condition que je ne reste pas dans le pays. Sinon [on] allait me tuer »1231.\nUn magistrat a par ailleurs vu son accès aux dossiers sensibles retiré et a témoigné de\nla pression exercée sur les juges afin qu’ils rendent les décisions voulues : « Les\njugements sont dictés. Je n’avais pas accès à certains dossiers. [Pour les questions\nsensibles, le tribunal est composé] du chef de juridiction, de son suppléant et d’un\nautre juge. Par exemple […] un membre [d’un parti d’opposition] a été accusé de\ntrafic d’armes […] On a fait l’audience de flagrance le dimanche même. […] Bien\nqu’il n’y ait rien eu dans le dossier, le président du siège a insisté pour donner cinq\nans d’emprisonnement au prévenu. […] Puisque les deux autres magistrats avaient\ndes voix prépondérantes, j’ai dû m’aligner sur leur position »1232."},{"id":"a-hrc-36-crp-1-p0658","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"658","seq":660,"section":"8. Liberté de circulation","text":"La Commission a recueilli plusieurs témoignages faisant état d’une influence\nimportante du CNDD-FDD sur le pouvoir judiciaire. Selon les personnes interrogées par la\nCommission, bien qu’il soit interdit aux magistrats d’adhérer à un parti politique1233, dans les\nfaits il est difficile pour un magistrat burundais de progresser professionnellement s’il n’est\npas membre ou sympathisant du parti au pouvoir ou s’il n’a pas de bons contacts parmi les\nautorités1234."},{"id":"a-hrc-36-crp-1-p0659","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"659","seq":661,"section":"8. Liberté de circulation","text":"Si, comme indiqué plus haut, les membres du Parquet peuvent exercer des pressions\nsur des magistrats du siège, ils font eux-mêmes également l’objet de pressions1235. La\nCommission a ainsi appris que des membres du Parquet avaient reçu des instructions leur\ndemandant d’abandonner certaines de leurs enquêtes. Selon les témoignages recueillis par la\nCommission, certains membres du Parquet ont dû également se justifier parce qu’ils\nn’avaient pas libéré certaines personnes, dont des Imbonerakure ou d’autres membres du\nCNDD-FDD, ou n’avaient pas ordonné l’arrestation de membres de l’opposition1236. Un\nancien membre du Parquet a également subi des pressions après avoir libéré des personnes\ndétenues en l’absence de preuves de leur participation à des crimes et délits supposés1237. Ces\npressions viendraient notamment de personnes occupant, ou ayant occupé, des postes dans\nl’administration provinciale, de parlementaires, de responsables haut-placés du CNDD-FDD\net même de militaires1238. Comme l’a expliqué un ancien membre du Parquet :\n« Les gouverneurs, les députés et d’autres autorités s’ingèrent souvent dans le\nsystème judiciaire. Ils viennent et ils disent qu’ils ont été envoyés par la Présidence et\nnous ordonnent de libérer tel ou tel détenu »1239."},{"id":"a-hrc-36-crp-1-p0660","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"660","seq":662,"section":"8. Liberté de circulation","text":"Plus récemment, le 13 juillet 2017, la volonté d’immixtion dans le travail de la justice\net le manque de compréhension du principe d’indépendance du système judiciaire ont été\nmanifestes lors d’une conférence de presse au cours de laquelle le porte-parole de la police,\nPierre Nkurikiye, a exprimé la déception de la police suite à la libération sur décision de\njustice d’une personne accusée d’un crime de droit commun : « La police fournit tous les\nefforts nécessaires pour prévenir et réprimer les crimes. Mais, ils sont voués à l’échec. Notre\npartenaire, la justice, relaxe les criminels […] Les gens qui les relâchent sont des traîtres, ils\ndonnent matière aux organisations « ennemies du pays », qui soutiennent que la criminalité\nrègne en maître au Burundi » 1240.\nPressions sur les avocats"},{"id":"a-hrc-36-crp-1-p0661","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"661","seq":663,"section":"8. Liberté de circulation","text":"En 2015, le Rapporteur spécial sur la situation des défenseurs des droits de l’homme a\nregretté les restrictions subies par l’Ordre des avocats dans son travail, notamment\nl’interdiction en 2014 de la tenue de l’assemblée générale du barreau de Bujumbura, ainsi\nque l’organisation d’un atelier de formation1241."},{"id":"a-hrc-36-crp-1-p0662","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"662","seq":664,"section":"8. Liberté de circulation","text":"En 2016, le Comité contre la torture a exprimé sa préoccupation suite à la procédure\nde radiation de l’Ordre des avocats ouverte à la demande du Procureur général près la Cour\nd’appel de Bujumbura à l’encontre de quatre avocats qui avaient contribué à la rédaction d’un\nrapport alternatif soumis au Comité1242 : Armel Niyongere, président de l’ACAT-Burundi et\ndirecteur de SOS-Torture/Burundi, Vital Nshimirimana, délégué général du Forum pour le\nrenforcement de la société civile (FORSC), Dieudonné Bashirahishize, vice-président de\nl’Association des barreaux de la Communauté d’Afrique de l’Est, et Lambert Nigarura,\nprésident de la Coalition burundaise pour la Cour pénale internationale (CB-CPI). Le\nProcureur général près de la Cour d’appel de Bujumbura les avait accusés de « participation à\nun mouvement insurrectionnel » et de « tentative de coup d’État »1243. L’Ordre des avocats a\njugé la demande de radiation infondée mais, le 16 janvier 2017, la Cour d’appel de\nBujumbura a confirmé la radiation d’Armel Niyongere, Vital Nshimirimana et Dieudonné\nBashirahishize du Barreau de Bujumbura et la suspension pour un an de Lambert Nigarura,\nen lui interdisant de siéger au Conseil de l’ordre pendant cinq ans."},{"id":"a-hrc-36-crp-1-p0663","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"663","seq":665,"section":"8. Liberté de circulation","text":"D’autres avocats ont été victimes de pressions et peinent à exercer leur métier\nlibrement et de manière efficace, notamment lorsqu’il est question de défendre des personnes\narrêtées de manière arbitraire ou abusive ou pour des raisons politiques. Alors que certains\nont du mal à avoir accès aux dossiers de leurs clients1244, d’autres ont préféré ne pas défendre\ndes clients dans des dossiers sensibles par craintes de représailles1245. Certains ont été\nvictimes de menaces, d’arrestations et de détentions arbitraires, et de mauvais traitements1246.\nPlusieurs d’entre eux vivent dans la peur et certains ont fui le pays1247. Au moins un avocat\ntravaillant sur des dossiers sensibles a été obligé de fuir après avoir reçu des informations\nprécises selon lesquelles les autorités cherchaient à l’arrêter1248. Un avocat qui était intervenu\ndans les dossiers de manifestants en 2015 a témoigné :\n« Je me suis donné comme tâche [de représenter les jeunes emprisonnés] Les\nOfficiers de police judiciaire ne voulaient pas [que je fasse ça], alors je suis entré en\nconflit avec certains [d’entre eux] […] [Un]commandant [de la police] m’a invité\ndans son bureau et c’est là où il m’a battu de ses propres mains. Il m’a menotté et m’a\ngiflé, battu, puis il m’a demandé pourquoi j’étais […] venu. Je lui ai répondu que les\nfamilles des victimes avaient demandé que je revienne assister leurs enfants sous sa\nsupervision et c’est là qu’il m’a présenté trois procès-verbaux dressés à mon insu et\ncelui de mes clients ». L’avocat a été relâché le même jour, mais a été ré-arrêté\nquelques mois plus tard : « Deux policiers sont venus dans mon cabinet et m’ont dit\nqu’ils devaient réquisitionner [mes appareils] et fouiller le cabinet. J’ai demandé un\nmandat de perquisition et la réponse que j’ai eue était de me mettre dans [un\nvéhicule] et de me conduire au bureau du SNR. Ils ont pris [mes appareils] et je ne\nsais pas où [ils sont] jusqu’à présent. Mes documents ont été déchirés et le mobilier\nsaccagé. J’ai été conduit au SNR où je suis resté pendant une semaine » 1249.\nNon-respect des garanties d’un procès équitable"},{"id":"a-hrc-36-crp-1-p0664","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"664","seq":666,"section":"8. Liberté de circulation","text":"Les garanties d’un procès équitable ne peuvent pas être respectées dès lors que la\nnature et les motifs de l’accusation sont faussés. La Commission est préoccupée à cet égard\npar les nombreux témoignages qu’elle a reçus d’aveux et d'informations extorqués sous la\ntorture1250. Des victimes ont mentionné pendant leur procès les sévices qu’elles ont subis sans\nque les juges ne prennent en compte ou n’ordonnent des enquêtes sur ces allégations1251.\nAinsi, le 26 janvier 2017, huit membres des corps de défense et de sécurité et 12 civils arrêtés\nsuite aux attaques du camp militaire de Mukoni (province de Muyinga) dans la nuit du 23 au\n24 janvier 2017 ont été condamnés à des peines parfois lourdes sans que les magistrats ne\nprennent en compte les allégations de tortures en détention faites par les accusés, et en dépit\ndu fait que certains d’entre eux tenaient à peine debout lors de l’audience1252."},{"id":"a-hrc-36-crp-1-p0665","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"665","seq":667,"section":"8. Liberté de circulation","text":"La Commission a également reçu le témoignage d’un membre d’un parti d’opposition,\narrêté en 2015 et forcé d’avouer sous la menace d’agents du SNR sa collaboration avec des\ngroupes armés d’opposition. Sa famille a versé de l’argent pour que le juge l'acquitte plus\nd’un an après son arrestation :\n« J’ai expliqué aux juges que pour sauver ma vie j’avais dû reconnaître au SNR mon\nimplication dans les groupes armés, mais que c’était faux. Après l’audience,\nquelqu’un de ma famille s’est approché d’un juge. Ce juge a demandé de l’argent.\nC’était le président du siège. Ma famille lui a donné un million de francs burundais\n[soit environ 574 dollars américains]. [En] 2017, on m’a relâché après que j’ai été\nacquitté »1253."},{"id":"a-hrc-36-crp-1-p0666","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"666","seq":668,"section":"8. Liberté de circulation","text":"La Commission a également documenté plusieurs cas où les droits de la défense n’ont\npas été respectés, notamment le droit des prévenus de disposer du temps et des facilités\nnécessaires à la préparation de leur défense et de communiquer avec un conseil de leur choix.\nLa Commission a noté en particulier l’utilisation à plusieurs reprises de la procédure de\nflagrance qui souvent ne laisse pas le temps nécessaire aux prévenus pour préparer leur\ndéfense et communiquer avec un conseil de leur choix, tel que prévu par l’article 14 (b) du\nPICDP1254. Dans le cas de l’attaque du camp militaire de Mukoni, mentionné plus haut, les\nprévenus ont été appréhendés immédiatement après l’attaque le 25 janvier 2017 et ont été\njugés et condamnés le lendemain à une lourde peine (30 ans de réclusion pour 18 des\nprévenus), sans l'assistance d'avocats1255. Dans le cadre de la même affaire, une personne a\nété arrêtée trois mois après les faits en avril 2017 et accusée d’avoir prêté sa voiture aux\nassaillants du camp de Mukoni. Alors qu’il ne s’agissait pas d’un flagrant délit1256, le prévenu\na été jugé sur le champ et condamné à trois ans et neuf mois d’emprisonnement.\nContrairement aux accusés dans le procès de janvier, il a pu se faire assister par un avocat1257."},{"id":"a-hrc-36-crp-1-p0667","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"667","seq":669,"section":"8. Liberté de circulation","text":"Selon plusieurs témoignages recueillis par la Commission, de nombreux prévenus\nn’ont pas eu accès à un avocat dès le début de leurs procès et presque jamais pendant les\ninterrogatoires. Les menaces envers les avocats et les difficultés d’accéder aux dossiers de\nleurs clients, mentionnés plus haut, ont également porté atteinte au droit à la défense. Dans le\nprocès d'une trentaine de personnes accusées d’avoir été impliquées dans la tentative de coup\nd’État de mai 2015, les avocats choisis par les accusés ont été récusés par les juges et\nremplacés par des avocats commis d’office. Les juges ont refusé d’accorder du temps aux\naccusés pour qu'ils puissent chercher eux-mêmes de nouveaux avocats. Plusieurs d’entre eux,\nqui n’ont pas voulu se faire assister par les avocats commis d’office, ont dû se défendre eux-\nmêmes1258."},{"id":"a-hrc-36-crp-1-p0668","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"668","seq":670,"section":"8. Liberté de circulation","text":"La Commission a recueilli des informations attestant de la lenteur des procédures\njudiciaires1259. La Commission a également été informée de la tenue, en dehors de la\nprocédure du huis clos1260, de certains procès dans l’enceinte de prisons, particulièrement\ndans des dossiers d’atteinte à la sécurité intérieure de l’État, de rébellion ou d'insurrection1261.\nL’accès aux prisons étant restreint, cette pratique affecte le caractère public des procès qui est\ngaranti par le droit burundais et le droit international des droits de l’homme, et décourage la\nprésence d'observateurs de la société civile ou d'autres organisations1262."},{"id":"a-hrc-36-crp-1-p0669","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"669","seq":671,"section":"III. Crimes de droit international","text":"Le paragraphe 23 a) de la résolution 33/24 du Conseil des droits de l’homme charge la\nCommission de « mener une enquête approfondie sur les violations des droits de l’homme et\natteintes à ces droits commises au Burundi depuis avril 2015, notamment pour en évaluer\nl’ampleur et déterminer s’il s’agit de crimes de droit international, afin de lutter contre\nprocédure pénale dispose par ailleurs que : « L’enquête de flagrance menée à la suite de la constatation\nd’un crime ou d’un délit flagrant ne peut se poursuivre pendant plus de trente-six heures ».\nl’impunité ». Dans cette optique, la Commission a examiné si les violations et atteintes\nqu’elle a documentées présentaient le niveau de gravité requis et réunissaient les éléments\nconstitutifs nécessaires pour pouvoir être qualifiées de crimes de droit international."},{"id":"a-hrc-36-crp-1-p0670","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"670","seq":672,"section":"III. Crimes de droit international","text":"Par l’expression « crimes de droit international », la Commission a entendu les «\ncrimes les plus graves qui touchent l'ensemble de la communauté internationale » tels qu’ils\nsont définis par le Statut de Rome de la CPI, à savoir : les crimes contre l'humanité, le crime\nde génocide, les crimes de guerre, et le crime d'agression1263. N’ayant pas considéré pas que\nla situation qui prévaut au Burundi depuis avril 2015 constitue un conflit armé1264, la\nCommission n’a pas examiné si des crimes de guerre ou d’agression avaient eu lieu et s’est\ndonc concentrée sur l’existence de crimes contre l’humanité. Elle a également examiné la\nquestion de savoir si le crime de génocide avait été commis en basant son analyse juridique\naussi bien sur le Statut de Rome que sur la Convention pour la prévention et la répression du\ncrime du génocide à laquelle le Burundi est partie."},{"id":"a-hrc-36-crp-1-p0671","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"671","seq":673,"section":"1. Éléments constitutifs du crime","text":"L’article 7 (1) du Statut de Rome définit les crimes contre l’humanité comme les actes\nci-après « commis dans le cadre d'une attaque généralisée ou systématique lancée contre une\npopulation civile et en connaissance de cette attaque :\na)      Meurtre ;\nb)      Extermination ;\nc)      Réduction en esclavage ;\nd)      Déportation ou transfert forcé de population ;\ne)      Emprisonnement ou autre forme de privation grave de liberté physique en\nviolation des dispositions fondamentales du droit international ;\nf)      Torture ;\ng)      Viol, esclavage sexuel, prostitution forcée, grossesse forcée, stérilisation forcée\net toute autre forme de violence sexuelle de gravité comparable ;\nh)     Persécution de tout groupe ou de toute collectivité identifiable pour des motifs\nd'ordre politique, racial, national, ethnique, culturel, religieux ou sexiste au sus du\nparagraphe 3, ou en fonction d'autres critères universellement reconnus comme\ninadmissibles en droit international, en corrélation avec tout acte visé dans le présent\nparagraphe ou tout crime relevant de la compétence de la Cour ;\ni)      Disparitions forcées ;\nj)      Apartheid ;\nh)    Autres actes inhumains de caractère analogue causant intentionnellement de\ngrandes souffrances ou des atteintes graves à l'intégrité physique ou à la santé\nphysique ou mentale ».\nAttaque lancée contre une population civile"},{"id":"a-hrc-36-crp-1-p0672","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"672","seq":674,"section":"1. Éléments constitutifs du crime","text":"L’article 7 (2) (a) indique que « par attaque lancée contre une population civile, on\nentend le comportement qui consiste à multiplier les actes visés au paragraphe 1 à l'encontre\nd'une population civile quelconque [...] ». Dans les Éléments des crimes adoptés par les États\nparties au Statut de Rome de la CPI, il est précisé que : « les actes ne doivent pas\nnécessairement constituer une attaque militaire1265. Il est entendu que pour qu’il y ait une\n« politique ayant pour but une telle attaque », il faut que l’État ou l’organisation favorise ou\nencourage activement une telle attaque contre une population civile »1266."},{"id":"a-hrc-36-crp-1-p0673","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"673","seq":675,"section":"1. Éléments constitutifs du crime","text":"Au vu des informations qu’elle a recueillies, la Commission a des motifs raisonnables\nde croire qu’une attaque a été menée contre une partie de la population civile depuis avril\n2015 au Burundi. Cette attaque a consisté en la multiplication d’actes visés par le Statut de\nRome1267 à l’encontre d’une population en majorité civile composée notamment d’opposants\nau Gouvernement ou de personnes perçues comme tels. La présence d’éléments des corps de\ndéfense et de sécurité, notamment d’ex-FAB, parmi les victimes ne change rien à cette\nqualification1268."},{"id":"a-hrc-36-crp-1-p0674","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"674","seq":676,"section":"1. Éléments constitutifs du crime","text":"L’article 7 (1) du Statut de Rome, en précisant par ailleurs que les actes entrant dans\nson champ d’application doivent être commis « dans le cadre d’une attaque généralisée ou\nsystématique lancée contre la population civile », exige qu’un lien soit démontré entre les\nactes individuels et l’attaque en général1269. Cette exigence exclut les actes isolés de la\nqualification de crimes contre l’humanité. Dans le cas du Burundi, la Commission a\ndocumenté un grand nombre de violations dont la nature et le mode opératoire communs, les\nbuts et leurs conséquences1270 – en l’occurrence réduire au silence toute forme d’opposition –\nles inscrivent dans le cadre d’une attaque menée contre une partie de la population civile du\nBurundi depuis avril 2015.\nExistence d’une politique d’un État ou d’une organisation"},{"id":"a-hrc-36-crp-1-p0675","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"675","seq":677,"section":"1. Éléments constitutifs du crime","text":"L’article 7 (2) (a) du Statut de Rome exige l’existence d’une « politique d’État ou\nd’une organisation » ayant pour but de commettre l’attaque. La jurisprudence de la CPI et des\nautres juridictions pénales internationales ne considère pas néanmoins que cette politique doit\nêtre « énoncée de façon formelle »1271 ou que le dessein de commettre l’attaque soit « déclaré\nexpressément, ni énoncé de façon claire et précise »1272. Ce dessein peut se déduire « de la\nsurvenance d’un ensemble de faits notamment : [...] du cadre politique global dans lesquels\ns’inscrivent les actes criminels, [...] de la teneur générale d’un programme politique, telle\nqu’elle résulte des écrits de ses auteurs et de leurs discours, [...] de la mobilisation de forces\narmées, [...] de l’ampleur des exactions perpétrées [...] »1273."},{"id":"a-hrc-36-crp-1-p0676","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"676","seq":678,"section":"1. Éléments constitutifs du crime","text":"Dans le cas du Burundi, les violations et atteintes documentées par la Commission\ns’inscrivent dans le cadre d’une crise politique qui a débuté en avril 2015 avec les\nmanifestations contre la candidature de Pierre Nkurunziza à l’élection présidentielle et s’est\naggravée après le coup d’État manqué de mai 2015 et l’usage de la violence par des groupes\narmés et des personnes non identifiées contre des agents de l’État, en particulier contre des\ninstallations militaires le 11 décembre 2015. Ces actes ont entraîné une mobilisation des\nforces de sécurité, en particulier du SNR, de la PNB et de la FDNB, afin de réprimer toute\nforme d’opposition réelle ou présumée au gouvernement, qui a débouché sur la commission à\nune grande échelle de violations graves des droits de l’homme. Les discours de haine tenus\ncontre les opposants par des autorités gouvernementales et des représentants du CNDD-FDD\nà tous les niveaux attestent d’une volonté politique générale du Gouvernement burundais,\nsoutenu par le parti au pouvoir, de réprimer toute voix discordante."},{"id":"a-hrc-36-crp-1-p0677","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"677","seq":679,"section":"1. Éléments constitutifs du crime","text":"La CPI considère par ailleurs que, dans des circonstances exceptionnelles, la politique\nd’un État « peut prendre la forme d’une abstention délibérée d’agir, par laquelle l’État [...]\nentend consciemment encourager une telle attaque »1274. Le fait que, généralement et à la\nconnaissance de la Commission, peu d'auteurs présumés de violations au Burundi ont été\npoursuivis ou que des pressions ont été exercées pour empêcher des poursuites peut être\ninterprété comme une abstention délibérée d’agir de l’État burundais et donc un\nencouragement de sa part."},{"id":"a-hrc-36-crp-1-p0678","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"678","seq":680,"section":"1. Éléments constitutifs du crime","text":"La Commission s’est également interrogée sur l’existence d’une « politique d’une\norganisation » – en l’occurrence du CNDD-FDD. Comme expliqué plus haut1275, la\nCommission a constaté un certain alignement du CNDD-FDD sur la politique de l’État\nburundais qui se manifeste souvent par une identité de vues et d’objectifs entre ces deux\nentités. Le Président de la République préside le conseil des sages, l’un des organes exécutifs\nclés du parti, et de fait contribue aux choix stratégiques du CNDD-FDD. Le Secrétaire\nnational du CNDD-FDD en charge de la gestion des ligues affiliées au parti, Sylvestre\nNdayizeye, était directeur du Département intérieur puis conseiller au SNR avant de prendre\nses fonctions au sein du CNDD-FDD en 2016. De plus, le CNDD-FDD, par la voix de ses\nreprésentants, par ses communiqués officiels et par les marches ou manifestations en faveur\ndu Gouvernement qu’il a régulièrement organisées depuis avril 2015, a fait preuve d’un\nsoutien indéfectible au Gouvernement, notamment dans sa lutte contre toute forme\nd’opposition réelle ou supposée. De fait, la Commission, ayant constaté un certain\nalignement du CNDD-FDD, n’estime pas nécessaire d’établir l’existence d’une politique qui\nlui est propre, ses membres, en particulier ceux de sa ligue des jeunes, agissant dans la\nmajorité des cas dans le cadre de la politique fixée par l’État burundais.\nCaractère généralisé ou systématique de l’attaque"},{"id":"a-hrc-36-crp-1-p0679","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"679","seq":681,"section":"1. Éléments constitutifs du crime","text":"Le Statut de Rome précise que l’attaque contre la population civile doit être\n« généralisée ou systématique », ces deux conditions n’étant pas cumulatives1276. Pour être\ngénéralisée, l’attaque doit être menée à grande échelle et toucher une pluralité de victimes1277.\nIl n’y a cependant pas de seuil minimum établi pour définir cette échelle. Dans le cas du\nBurundi, le nombre des violations, leur occurrence dans plusieurs provinces, la pluralité des\nvictimes, des auteurs et institutions impliquées permettent de conclure au caractère généralisé\nde l’attaque."},{"id":"a-hrc-36-crp-1-p0680","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"680","seq":682,"section":"1. Éléments constitutifs du crime","text":"La nature systématique de l’attaque dénote quant à elle « le caractère organisé des\nactes de violence et l’improbabilité de leur caractère fortuit »1278. Ce caractère découle d’un\n« scénario des crimes de telle sorte que ces derniers constituent une répétition délibérée et\nrégulière de comportements criminels similaires »1279. Dans le cas du Burundi, la\nCommission a également des motifs raisonnables de croire que l’attaque contre la population\ncivile a eu un caractère systématique du fait de l’occurrence d'actes de violence semblables et\nsouvent de la répétition du même mode opératoire, ainsi que le ciblage des victimes qui ne\npeuvent laisser penser que ces actes ont été commis de manière aléatoire.\nConnaissance de l’attaque"},{"id":"a-hrc-36-crp-1-p0681","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"681","seq":683,"section":"1. Éléments constitutifs du crime","text":"Le Statut de Rome exige enfin que l’attaque soit menée en connaissance de cause1280.\nÀ cet égard, il n’est pas nécessaire de prouver que l’auteur connaissait les détails de l’attaque,\ncette connaissance pouvant être déduite de « preuves indirectes » comme les circonstances\ndans lesquelles se déroule l’attaque1281. La Commission considère donc, au regard des\ninformations dont elle dispose, que les auteurs présumés qu’elle a pu identifier, en majorité\nmembres du SNR, de la PNB, de la FDNB et des Imbonerakure, ne pouvaient pas ne pas\navoir une connaissance du contexte dans lequel s’inscrivaient leurs actes, vu leurs fonctions\ndans l’appareil sécuritaire de l’État ou leur embrigadement au sein du CNDD-FDD."},{"id":"a-hrc-36-crp-1-p0682","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"682","seq":684,"section":"2. Typologie des crimes","text":"Les éléments constitutifs du crime contre l’humanité étant d’après elle réunis, la\nCommission a examiné les types de crimes commis au Burundi depuis avril 2015. Elle s’est\nfondée pour ce faire sur les Éléments des crimes, adoptés par les États parties au Statut de\nRome de la CPI, qui fournissent les critères à réunir pour conclure à l’existence des crimes de\ndroit international1282.\nMeurtres"},{"id":"a-hrc-36-crp-1-p0683","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"683","seq":685,"section":"2. Typologie des crimes","text":"La Commission a ainsi des motifs raisonnables de croire que les violations et atteintes\nau droit à la vie perpétrées par des agents de l’État, notamment des exécutions\nextrajudiciaires et les décès dus à un usage excessif de la force par les forces de l’ordre et des\nImbonerakure, sont susceptibles de constituer des « meurtres » au titre du Statut de Rome1283.\nEmprisonnements ou autres formes de privation grave de liberté physique"},{"id":"a-hrc-36-crp-1-p0684","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"684","seq":686,"section":"2. Typologie des crimes","text":"La Commission considère que les nombreux cas de détention arbitraire dans des\ncachots du SNR, de la PNB et dans des lieux de détention non officiels peuvent constituer\ndes « emprisonnements ou autres formes de privation grave de liberté physique [...]\nen violation de règles fondamentales du droit international » aux termes du Statut de\nRome1284. En outre, les violations souvent commises durant la détention, y compris les\nconditions inhumaines de celle-ci, ajoutent à la gravité des actes.\nTortures"},{"id":"a-hrc-36-crp-1-p0685","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"685","seq":687,"section":"2. Typologie des crimes","text":"La Commission a des motifs raisonnables de croire que les agissements des membres\ndes forces de sécurité, parfois secondés par des Imbonerakure, caractérisés par la\nCommission comme des actes de torture et traitements inhumains, cruels ou dégradants, sont\nconstitutifs de « tortures » selon le Statut de Rome1285 en ce qu’ils ont systématiquement eu\npour but d’infliger « à une ou plusieurs personnes une douleur ou des souffrances aiguës,\nphysiques ou mentales » alors que ces personnes étaient « sous la garde ou sous le contrôle\nde l’auteur »1286.\nViols et toute autre forme de violence sexuelle de gravité comparable"},{"id":"a-hrc-36-crp-1-p0686","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"686","seq":688,"section":"2. Typologie des crimes","text":"Les cas de viol par des agents de police et/ou des Imbonerakure dans le contexte\nd’arrestations d’opposants présumés ou de représailles contre des membres féminins de leurs\nfamilles constituent des « viols » au titre du Statut de Rome1287. D’autres cas de violence\nsexuelle documentés par la Commission, notamment en détention, sont susceptibles de\nrelever, selon le Statut de Rome, de « toute autre forme de violence sexuelle de gravité\ncomparable », de « tortures » ou « d’autres actes inhumains de caractère analogue causant\nintentionnellement de grandes souffrances ou des atteintes graves à l'intégrité physique ou à\nla santé physique ou mentale »1288.\nPersécutions d’ordre politique et sexiste"},{"id":"a-hrc-36-crp-1-p0687","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"687","seq":689,"section":"2. Typologie des crimes","text":"Les différentes violations commises par des agents de l’État ou des Imbonerakure à\nl’encontre de membres de partis d’opposition ou de leurs proches sont en outre susceptibles\nde constituer des crimes de « persécution » au titre de l’article 7 (1) (h) du Statut de Rome.\nCes crimes ont été motivés politiquement et les victimes ciblées du fait de leur appartenance,\nréelle ou supposée, à des partis ou groupes d’opposition1289. Par ailleurs, dans certains cas de\nviolence sexuelle, le fait que des femmes ayant des liens familiaux avec des opposants\npolitiques aient été ciblées pourrait constituer une persécution sexiste venant s’ajouter à la\npersécution politique.\nDisparitions forcées"},{"id":"a-hrc-36-crp-1-p0688","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"688","seq":690,"section":"2. Typologie des crimes","text":"L’article 7 (2) (i) du Statut de Rome définit les disparitions forcées comme « les cas\noù des personnes sont arrêtées, détenues ou enlevées par un État ou une organisation\npolitique ou avec l'autorisation, l'appui ou l'assentiment de cet État ou de cette organisation,\nqui refuse ensuite d'admettre que ces personnes sont privées de liberté ou de révéler le sort\nqui leur est réservé ou l'endroit où elles se trouvent, dans l'intention de les soustraire à la\nprotection de la loi pendant une période prolongée »."},{"id":"a-hrc-36-crp-1-p0689","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"689","seq":691,"section":"2. Typologie des crimes","text":"Dans le cas du Burundi, la Commission a pu établir, au regard du droit international\ndes droits de l’homme, certains cas de disparition forcée depuis avril 2015 pour lesquels des\ntémoins ont pu confirmer l’arrestation ou la détention des victimes, suivies du déni ou de la\ndissimulation de ces disparitions par les autorités burundaises1290. Toutefois, en l’état actuel\nde ses enquêtes, la Commission ne peut parvenir à la même conclusion au regard du droit\npénal international qui exige, en outre, soit que l’auteur sache lorsqu’il arrête, détient ou\nenlève un individu que son acte sera suivi d’un refus d’admettre que la victime est privée de\nliberté ou de révéler son sort ou l’endroit où elle se trouve, soit que l’auteur qui nie la\ndétention savait que la personne était détenue1291. La Commission n’exclut pas cependant que\ncet élément puisse être déduit du contexte général d’occurrence des disparitions forcées."},{"id":"a-hrc-36-crp-1-p0690","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"690","seq":692,"section":"2. Typologie des crimes","text":"Dans certains cas de disparition, la Commission n’a en revanche pas été en mesure\nd’obtenir des témoignages faisant état de l’arrestation ou de la détention des victimes.\nNéanmoins, parmi ces cas, la Commission a des motifs raisonnables de craindre que ces\ndisparitions pourraient être qualifiées de « forcées » au regard du droit international des droits\nde l’homme1292. Les craintes de la Commission sont basées sur des éléments de preuve\nindirecte, comme le contexte d’arrestations et de détentions arbitraires ou un climat de\npersécution générale, et l’existence d’éléments particuliers tels que des menaces précédant ou\nsuccédant aux disparitions et le fait que les victimes ou les membres de leur famille étaient\ndes opposants politiques ou perçus comme tels. Ces cas pourraient, s’ils étaient confirmés,\ncontribuer à établir l’existence d’un contexte général d’occurrence de disparitions forcées\nnécessaire pour démontrer, comme expliqué dans le paragraphe précédent, que l’auteur savait\nque la disparition forcée serait suivie d’un refus d’admettre que la victime est privée de\nliberté ou de révéler son sort ou l’endroit où elle se trouve."},{"id":"a-hrc-36-crp-1-p0691","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"691","seq":693,"section":"2. Typologie des crimes","text":"Toutefois, en l’absence d’informations montrant que ces victimes ont été arrêtées ou\ndétenues, la Commission ne peut qualifier cette catégorie de disparition de crimes contre\nl’humanité. Une juridiction pénale, nationale ou internationale, pourrait avoir accès à des\ninformations permettant d’établir l’arrestation ou la détention de la victime, que faute de\ntemps et d’accès au Burundi la Commission n’a pu obtenir1293."},{"id":"a-hrc-36-crp-1-p0692","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"692","seq":694,"section":"B. Génocide","text":"Si la Commission a relevé des insultes à caractère ethnique dirigées contre des Tutsis\ndans le contexte de certaines violations des droits de l’homme, notamment d’arrestations, de\ntortures et de violences sexuelles, elle n’est en revanche pas en mesure d’établir l’existence\nd’une volonté politique génocidaire à l’encontre de ce groupe depuis avril 2015 au Burundi."},{"id":"a-hrc-36-crp-1-p0693","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"693","seq":695,"section":"1. Éléments constitutifs du crime","text":"L’article 6 du Statut de Rome dispose qu’on « entend par crime de génocide l’un\nquelconque des actes ci-après commis dans l’intention de détruire, en tout ou en partie, un\ngroupe national, ethnique, racial ou religieux, comme tel :\na)     Meurtre de membres du groupe ;\nb)     Atteinte grave à l’intégrité physique ou mentale de membres du groupe ;\nc)     Soumission intentionnelle du groupe à des conditions d’existence devant\nentraîner sa destruction physique totale ou partielle ;\nd)     Mesures visant à entraver les naissances au sein du groupe ;\ne)     Transfert forcé d’enfants du groupe à un autre groupe »1294."},{"id":"a-hrc-36-crp-1-p0694","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"694","seq":696,"section":"1. Éléments constitutifs du crime","text":"La Commission a examiné les éléments constitutifs du crime de génocide pour voir\ns’il y avait des motifs raisonnables de croire qu’ils existaient au Burundi. L'élément le plus\nimportant est l’élément intentionnel (mens rea). Dans l’affaire Kayishema et Ruzindana, le\nTPIR a précisé à cet égard : « quand bien même l’existence d’un plan précis visant à détruire\nle groupe ne constituerait pas en soi un élément du génocide, il semble, cependant, qu’il soit\nvirtuellement impossible de perpétrer le crime de génocide en l’absence d’un tel plan ou\nd’une telle organisation [...] »1295. La Commission n’a reçu aucun témoignage crédible\npermettant de conclure à l’existence à la date de publication du présent rapport d’un plan ou\nde la mise en place d’une organisation destinée à détruire les Tutsis au Burundi."},{"id":"a-hrc-36-crp-1-p0695","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"695","seq":697,"section":"1. Éléments constitutifs du crime","text":"Le Statut de Rome précise en outre que l’intention de détruire doit viser « tout ou\npartie » d’un groupe. Si par cette expression le Statut entend préciser que l’anéantissement\neffectif du groupe tout entier n’est pas requis, l’intention de détruire doit toutefois viser un\nnombre assez élevé ou au moins une partie substantielle du groupe1296. Or, aucun élément au\nBurundi n’atteste de l’anéantissement depuis avril 2015 d’une partie substantielle des Tutsis\nvivant dans le pays."},{"id":"a-hrc-36-crp-1-p0696","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"696","seq":698,"section":"1. Éléments constitutifs du crime","text":"Le Statut de Rome, tout comme la Convention pour la prévention et la répression du\ncrime de génocide, dispose par ailleurs que l’intention doit être de détruire « en tout ou en\npartie, un groupe national, ethnique, racial ou religieux, comme tel ». Par ces derniers termes,\nle droit international pénal insiste sur le fait que les victimes de l’acte sont choisies non pas\nen fonction de leur identité individuelle mais en raison de leur appartenance au groupe1297. La\nCommission n’a à cet égard pas pu établir que les Tutsis qui ont subi des violations des droits\nde l’homme ou des atteintes à ceux-ci au Burundi depuis avril 2015 l’ont été en premier lieu\nen raison de leur appartenance ethnique. Si dans certains cas cette appartenance a pu être un\nmotif aggravant ou un sujet d’insultes ajoutant à la souffrance des victimes, ces dernières ont\nd’abord été visées parce qu’elles étaient des opposants au pouvoir ou perçues comme tels.\nComme l’a souligné un ancien Imbonerakure aujourd’hui en exil :\n« Que vous soyez Hutu ou Tutsi, vous pouvez être exécuté. Le critère pour choisir nos\ncibles n’est pas l’ethnie, mais l’opposition au pouvoir du Chef de l’État. D’ailleurs,\nj’ai déjà donné des ordres à des Tutsis pour aller tuer d’autres Tutsis. On nous a\nformés pour tuer, piller, violer et exterminer tous ceux qui se trouvent en résistance\npar rapport au pouvoir »1298."},{"id":"a-hrc-36-crp-1-p0697","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"697","seq":699,"section":"2. Incitation à commettre le crime de génocide","text":"L’article 25-3 e) du Statut de Rome dispose qu’une « personne est pénalement\nresponsable et peut être punie pour un crime relevant de la compétence de la Cour si : [...]\ns’agissant du crime de génocide, elle incite directement et publiquement autrui à le\ncommettre ». Le Statut reprend en cela l’article III c) de la Convention pour la prévention et\nla répression du crime du génocide qui, de la même manière, précise que sera punie\n« l’incitation directe et publique à commettre le génocide »1299."},{"id":"a-hrc-36-crp-1-p0698","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"698","seq":700,"section":"2. Incitation à commettre le crime de génocide","text":"Le droit burundais a intégré cette notion d’incitation au génocide. L’article 302 du\nCode pénal dispose que « celui qui ordonne ou incite publiquement à commettre le crime de\ngénocide [...] encourt la peine de servitude pénale à perpétuité. »\n(b).     Les faits"},{"id":"a-hrc-36-crp-1-p0699","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"699","seq":701,"section":"2. Incitation à commettre le crime de génocide","text":"La Commission n’a pas relevé des « incitations directes et publiques à commettre le\ngénocide » au Burundi. Elle a néanmoins noté dans certains discours de responsables\nburundais l’utilisation de termes inquiétants qui rappellent des expressions entendues avant et\npendant le génocide au Rwanda en 1994. Par exemple, dans un discours, le 29 octobre 2015,\ndevant des élus locaux à Bujumbura1300, le Président du Sénat, Révérien Ndikuriyo, a déclaré\n: « Si vous entendez le signal avec une consigne que ça doit se terminer, les émotions et les\npleurs n’auront plus de place ! [...] Vous devez pulvériser, vous devez exterminer ces gens\n[...] Attendez le jour où l’on dira « travaillez ! », vous verrez la différence ! »1301. Le terme\n« gukora » (travailler) avait été utilisé pendant le génocide au Rwanda pour inciter la\npopulation hutue à tuer des Tutsis. Les propos du Président du Sénat ont été condamnés par\nde nombreux acteurs burundais et internationaux dont le Conseiller spécial du Secrétaire\ngénéral des Nations Unies sur la prévention du génocide, Adama Dieng1302. En dépit de ces\ncondamnations, la Commission a reçu des informations selon lesquelles le Secrétaire national\nresponsable des ligues affiliées au CNDD-FDD, Sylvestre Ndayizeye, aurait employé le\nmême terme « travailler » et incité des Imbonerakure à le répéter, lors d’une émission de la\nRTNB à Ngozi, le 26 février 20171303. La Commission a en outre documenté des propos\nhaineux visant les Tutsis, en particulier dans des discours d'autorités et des chants entonnés\npar des membres du CNDD-FDD1304."},{"id":"a-hrc-36-crp-1-p0700","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"700","seq":702,"section":"2. Incitation à commettre le crime de génocide","text":"La Commission a également noté le développement d'une rhétorique de la part de\nresponsables du Gouvernement et du CNDD-FDD visant à manipuler le sentiment\nd’appartenance ethnique, notamment par des références fréquentes aux massacres de Hutus\nau Burundi en 19721305. Certains de ces discours semblent vouloir attiser un sentiment de\nvengeance parmi les familles des victimes de 1972. De plus, de fréquentes déclarations du\nGouvernement et du parti au pouvoir ont cherché à présenter les critiques émises au niveau\ninternational sur la situation au Burundi comme un complot contre les Hutus. Par exemple,\nun communiqué du CNDD-FDD du 23 décembre 2015 a affirmé : « C’est eux [la Belgique et\nl’ancien pouvoir tutsi] qui ont commis le génocide des Hutus en 1972 poussant les survivants\nà l’exil, c’est eux qui ont régné́ par la terreur, l’exclusion et la discrimination pendant 40 ans,\nc’est eux qui ont assassiné́ Ndadaye [premier Président hutu élu démocratiquement et\nassassiné en 1993] et replongé le pays dans la guerre civile. Et maintenant qu’il y a un régime\nissu de la rébellion hutue, c’est eux qui manigancent tout pour retourner ou installer les Tutsis\nau pouvoir par le biais d’une alternance ethnique calculée »1306."},{"id":"a-hrc-36-crp-1-p0701","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"701","seq":703,"section":"2. Incitation à commettre le crime de génocide","text":"La Commission juge cette rhétorique particulièrement dangereuse car elle pourrait\ncontribuer à raviver les tensions ethniques et terroriser une partie de la population burundaise\ndans un climat politique déjà tendu. En ne poursuivant et ne punissant pas les auteurs de ces\npropos, le Gouvernement burundais pourrait par ailleurs voir sa responsabilité engagée au\ntitre de l’article 20 du PIDCP qui condamne tout « tout appel à la haine nationale, raciale ou\nreligieuse qui constitue une incitation à la discrimination, à l'hostilité ou à la violence est\ninterdit par la loi »."},{"id":"a-hrc-36-crp-1-p0702","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"702","seq":704,"section":"2. Incitation à commettre le crime de génocide","text":"Jusqu’à présent, ces messages inflammatoires ne semblent pas avoir trouvé une large\nrésonnance au niveau de la population burundaise. Des Burundais de différentes ethnies,\ncouches sociales et professionnelles ont indiqué à la Commission que dans sa majorité la\npopulation se méfie de ce genre de rhétorique dont elle perçoit le risque de replonger le pays\ndans les violences du passé. Les nombreux Burundais interrogés par la Commission ont\négalement insisté sur le fait que, malgré certaines tentatives « d’ ethniciser » la crise, celle-ci\ndemeure à leurs yeux avant tout politique1307. Cependant, si les autorités ne prenaient pas\nurgemment des mesures fermes pour mettre fin à ces discours, la situation, déjà caractérisée\npar la persistance de tensions et l’accroissement des difficultés économiques, pourrait\ndavantage se fragiliser."},{"id":"a-hrc-36-crp-1-p0703","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"703","seq":705,"section":"1. Mandat de la Commission","text":"Le paragraphe 23 (b) de la résolution 33/24 du Conseil des droits de l’homme charge\nla Commission « d’identifier les auteurs présumés de violations des droits de l’homme et\natteintes à ces droits commises au Burundi, en vue de faire pleinement respecter le principe\nde responsabilité ». Une interprétation littérale et restrictive de ce paragraphe pourrait laisser\npenser que la Commission a reçu mandat uniquement pour identifier des responsables dans le\ncadre des droits de l’homme et non pas sur la base du droit pénal international. Toutefois,\ncomme indiqué plus haut, en droit international des droits de l’homme, seul l’État engage sa\nresponsabilité pour les actes commis par ses agents ou des individus ou groupes d’individus\nagissant sur ses instructions ou étant sous son contrôle1308. En mentionnant également les\n« auteurs présumés de violations », la résolution renvoie à des responsabilités individuelles\nqui sont pour leur part prévues par le droit pénal international."},{"id":"a-hrc-36-crp-1-p0704","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"704","seq":706,"section":"1. Mandat de la Commission","text":"Cela ressort d’une lecture combinée des paragraphes 23 (a), (b) et (c) de la résolution\n33/24. Le paragraphe (a) demande en effet à la Commission de « mener une enquête\napprofondie sur les violations des droits de l’homme et atteintes à ces droits commises au\nBurundi depuis avril 2015, notamment pour en évaluer l’ampleur et déterminer s’il s’agit de\ncrimes de droit international, afin de contribuer à la lutte contre l’impunité ». Ce paragraphe\nmontre bien qu’il est donné mandat à la Commission pour documenter à la fois des violations\ndes droits de l’homme et des crimes relevant du droit pénal international en vue de contribuer\nà la lutte contre l’impunité. La Commission estime que, pour atteindre cet objectif, elle ne\npeut se limiter à établir les responsabilités sur le seul plan des droits de l’homme en omettant\nles auteurs de crimes de droit international. Le respect du « principe de responsabilité »\nauquel fait référence le paragraphe 23 (b) de la résolution ne pourrait pas aussi être atteint si\nla Commission adoptait cette interprétation restrictive, tout comme l’alinéa (c) qui demande à\nla Commission de « formuler des recommandations sur les mesures à prendre pour garantir\nque les auteurs de ces actes aient à en répondre, quelle que soit leur affiliation »."},{"id":"a-hrc-36-crp-1-p0705","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"705","seq":707,"section":"2. Responsabilités","text":"La Commission a des motifs raisonnables de croire que les crimes contre l’humanité\ndécrits dans ce rapport sont imputables notamment à des responsables au plus haut niveau de\nl’État, des officiers supérieurs et agents du SNR, de la PNB et de la FDNB, et des\nImbonerakure. La Commission a établi une liste non-exhaustive d’auteurs présumés de\ncrimes contre l’humanité, accompagnée d’informations sur certains actes qu’ils auraient\ncommis ou commandités. Elle a décidé de ne pas publier cette liste dans un souci de respect\nde la présomption d’innocence et de protection des victimes et des témoins1309. La\nCommission a pris soin de distinguer entre les responsabilités individuelles directes et la\nresponsabilité des chefs militaires1310 et des supérieurs hiérarchiques1311, toutes deux prévues\npar le Statut de Rome."},{"id":"a-hrc-36-crp-1-p0706","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"706","seq":708,"section":"2. Responsabilités","text":"S’agissant des liens hiérarchiques et des chaînes de commandement des entités\nauxquelles appartiennent les auteurs présumés de crimes contre l’humanité, il est important\nde rappeler que le SNR relève directement de l’autorité du Président de la République, sa\ngestion courante étant confiée à un administrateur général qui supervise cinq départements.\nParmi ceux-ci, le Département du renseignement intérieur, en charge de « prévenir les\nactivités de déstabilisation de nature politique ou sociale », chapeaute 18 responsables\nprovinciaux, eux-mêmes responsables de chefs de secteur1312."},{"id":"a-hrc-36-crp-1-p0707","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"707","seq":709,"section":"2. Responsabilités","text":"En ce qui concerne la PNB, le Président de la République en est le « commandant\nsuprême », la supervision de ce corps étant confié à un Inspecteur général assisté d’un\nInspecteur général-adjoint, tous deux placés sous l’autorité directe du Ministre de la sécurité\npublique. La PNB est organisée en commissariats généraux au niveau central et en\ncommissariats régionaux, provinciaux et communaux au niveau local. Les commissariats\ngénéraux et régionaux ont à leur tête des commissaires qui rendent directement compte à\nl’Inspecteur général de la PNB et son adjoint ont autorité sur les échelons inférieurs. L’API\nrelève du Commissariat général à la sécurité intérieure tandis que la BAE est directement\nsous l’autorité de l’Inspection générale1313."},{"id":"a-hrc-36-crp-1-p0708","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"708","seq":710,"section":"2. Responsabilités","text":"La FDNB est placée sous le commandement suprême du Président de la République et\nsous le commandement direct du Chef de la FDNB, lui-même à la tête de l’état-major\ngénéral. La loi organique adoptée en 20171314 ne fait plus référence au ministre de tutelle,\nlaissant supposer que le Chef de la FDNB rapporte directement au Président. La loi\norganique a également renforcé la centralisation du pouvoir hiérarchique au niveau de l’état-\nmajor général en supprimant les états-majors subalternes et les régions militaires. Le Chef de\nla FDNB commande les Forces terrestre, de la marine et aérienne, ainsi que des unités\nspécialisées, parmi lesquelles la BSPI. Le BGC (Camp Muzinda), cité plus haut, appartient à\nla Force terrestre 1315."},{"id":"a-hrc-36-crp-1-p0709","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"709","seq":711,"section":"2. Responsabilités","text":"Plusieurs témoignages ont néanmoins montré que le fonctionnement réel de l’État\nreposerait en grande partie sur une structure parallèle basée sur des liens personnels hérités\ndu temps où certaines autorités issues du CNDD-FDD menaient la lutte armée dans le maquis\net renforcés pour faire face aux oppositions internes qui dès 2014 se sont exprimées au sein\ndu parti contre un nouveau mandat du Président Nkurunziza. De grandes décisions, y compris\ncelles qui ont débouché sur des violations graves des droits de l’homme, ne seraient pas\nprises par le Gouvernement, mais par le Président de la République entouré d’un cercle\nrestreint de « généraux », parmi lesquels le Ministre de la sécurité publique, l’Administrateur\ngénéral du SNR, le chef de cabinet chargé de la police à la Présidence ainsi que le chef du\ncabinet civil, et le Secrétaire-général du CNDD-FDD1316. Ce cercle relaierait ses décisions à\ntravers une chaîne de commandement parallèle dont la configuration varierait d’un corps et\nd’une province à l’autre, si bien que des agents subalternes peuvent parfois avoir plus de\npouvoir que leur supérieur hiérarchique. La Commission a ainsi eu la confirmation que\nl’Inspecteur général-adjoint de la PNB aurait plus de pouvoir que l’Inspecteur général1317."},{"id":"a-hrc-36-crp-1-p0710","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"710","seq":712,"section":"2. Responsabilités","text":"L'organisation des Imbonerakure semble être calquée sur celle du CNDD-FDD selon\nune structure hiérarchique pyramidale allant de la direction nationale jusqu’à des\nresponsables locaux. Depuis août 2016, les Imbonerakure sont officiellement placés sous\nl’autorité d’un « Secrétaire national du CNDD-FDD en charge de la gestion des ligues\naffiliées au parti »1318. Toutefois, la Commission a reçu des informations faisant état d’un\ngroupe d’Imbonerakure particulièrement actif dans la commission d’actes illicites dont\ncertains pourraient constituer des crimes contre l’humanité1319. Ce groupe, souvent désigné\ncomme le « groupe des démobilisés », aurait été soutenu par le Général Adolphe\nNshimirimana, ancien chef du SNR, afin de s’attaquer aux opposants du CNDD-FDD et était\nsous son contrôle direct jusqu'à son assassinat en août 2015. Un témoin interrogé par la\nCommission a déclaré :\n« Les démobilisés sont un sous-ensemble des Imbonerakure [...] [Ce] sont des\nImbonerakure qui se démarquent par leurs activités. On leur confie des opérations\nd'enlèvement, de tuerie, etc., parce qu'ils ont une formation militaire. Les démobilisés\nencadrent les autres jeunes. Ils sont nombreux. Ils sont dans toutes les provinces. Au\nmoment de la démobilisation1320, il y avait environ 15 000 démobilisés, mais ils ne\nsont pas tous impliqués dans ces activités aujourd'hui »1321."},{"id":"a-hrc-36-crp-1-p0711","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"711","seq":713,"section":"2. Responsabilités","text":"Si la Commission ne peut établir ses effectifs, les témoignages qu’elle a recueillis font\nétat de l’entraînement militaire de membres de ce groupe, notamment en République\ndémocratique du Congo, de distribution d’armes et de paiement de sommes importantes\nd’argent qu’ils recevraient d’agents étatiques après avoir effectué des missions1322. En outre,\nplusieurs témoignages mentionnent des liens étroits entre des membres de ce groupe et\nd’autres Imbonerakure, et certains membres, y compris haut placés, du SNR, de la PNB, de la\nFDNB et de la Présidence1323. Ces liens viendraient court-circuiter les chaînes officielles de\ncommandement."},{"id":"a-hrc-36-crp-1-p0712","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"712","seq":714,"section":"D. Mécanismes d’établissement des responsabilités","text":"Le Sommet mondial des chefs d’État et de gouvernement de 2005 qui s’est tenu à\nl’occasion du soixantième anniversaire des Nations Unies a réaffirmé la responsabilité\npremière des États de protéger leur population contre les génocides, les crimes de guerre et\nles crimes contre l’humanité1324. Le préambule et l’article 1er du Statut de Rome précisent que\nla CPI « est complémentaire des juridictions pénales nationales ». En vertu de ce principe dit\n« de complémentarité », la CPI examine toujours la recevabilité d’une affaire qui lui est\nsoumise en déterminant au cas par cas si l’État compétent a ouvert une enquête et entamé des\npoursuites contre les auteurs présumés des actes portés à son attention, et « s'il y a manque de\nvolonté de l'État » en question de mener à bien ces poursuites, dans le respect des garanties\nd'un procès équitable1325. La Cour examine à cet égard si : « a) la procédure a été ou est\nengagée ou la décision de l'État a été prise dans le dessein de soustraire la personne\nconcernée à sa responsabilité pénale pour les crimes relevant de la compétence de la Cour\n[...] ; b) la procédure a subi un retard injustifié qui, dans les circonstances, est incompatible\navec l'intention de traduire en justice la personne concernée ; c) la procédure n'a pas été ou\nn'est pas menée de manière indépendante ou impartiale mais d'une manière qui, dans les\ncirconstances, est incompatible avec l'intention de traduire en justice la personne\nconcernée »1326."},{"id":"a-hrc-36-crp-1-p0713","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"713","seq":715,"section":"D. Mécanismes d’établissement des responsabilités","text":"Vu le manque d’indépendance de la justice burundaise et l’impunité pour les\nviolations graves commises par des agents de l’État ou des membres du parti au pouvoir, dont\nles Imbonerakure1327, la Commission a des motifs raisonnables de croire que l’État burundais\nn’a ni la volonté ni la capacité de mener véritablement à bien des enquêtes ou des poursuites\ncrédibles sur ces violations qui pourraient constituer des crimes contre l’humanité. Il revient\ndonc, selon elle, à la CPI d’ouvrir une enquête sur ces actes et d’établir les responsabilités\npénales y relatives."},{"id":"a-hrc-36-crp-1-p0714","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"714","seq":716,"section":"D. Mécanismes d’établissement des responsabilités","text":"La Commission espère qu’une telle enquête pourra être autorisée par la Chambre\npréliminaire de la CPI avant le 27 octobre 2017, date à laquelle le retrait du Burundi du Statut\nde Rome deviendra effectif1328. Si tel était le cas, le Burundi aurait l’obligation de coopérer\navec la CPI dans le cadre de l’enquête en cours, même après octobre 20171329. Cela étant, le\nretrait d’un État du Statut de Rome « n'affecte en rien la poursuite de l'examen des affaires\nque la Cour avait déjà commencé à examiner avant la date à laquelle il a pris effet »1330.\nMême si le Procureur de la CPI ne demande pas l'ouverture d'une enquête sur le Burundi\navant le 27 octobre 2017, la procédure d’examen préliminaire entamée le 25 avril 2016 se\npoursuivra."},{"id":"a-hrc-36-crp-1-p0715","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"715","seq":717,"section":"D. Mécanismes d’établissement des responsabilités","text":"Qu’une enquête soit ou non ouverte, la CPI n’aura plus la compétence temporelle pour\nmener des investigations sur de potentiels actes relevant de sa compétence qui seraient\ncommis au Burundi après le 27 octobre 2017. Si de tels actes survenaient toutefois, le Conseil\nde sécurité des Nations Unies pourrait, au titre du Chapitre VII de la Charte des Nations\nUnies, référer la situation au Burundi au Procureur de la CPI qui serait alors saisie de fait\nsans que sa chambre préliminaire ne se prononce sur la possibilité d’ouvrir une enquête1331."},{"id":"a-hrc-36-crp-1-p0716","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"716","seq":718,"section":"D. Mécanismes d’établissement des responsabilités","text":"La Commission tient également à rappeler que, si une enquête devait être ouverte par\nla CPI sur la situation au Burundi, les États parties au Statut de Rome auraient le devoir de\ncoopérer « pleinement avec la Cour »1332."},{"id":"a-hrc-36-crp-1-p0717","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"717","seq":719,"section":"D. Mécanismes d’établissement des responsabilités","text":"La Commission encourage par ailleurs les États membres des Nations Unies à\npoursuivre, au titre de la compétence universelle, toute personne soupçonnée de crimes\ncontre l’humanité au Burundi se trouvant sur leur territoire, si cette compétence est reconnue\ndans leur droit national, et dans l’esprit du Statut de Rome dont le préambule rappelle qu’il\n« est du devoir de chaque État de soumettre à sa juridiction criminelle les responsables de\ncrimes internationaux »."},{"id":"a-hrc-36-crp-1-p0718","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"718","seq":720,"section":"A. Principales conclusions","text":"Dans l’exercice de son mandat, la Commission a recueilli des informations de\nnombreuses victimes, témoins et d’autres sources qui, après un travail de corroboration\net d’analyse, lui ont permis d’établir la persistance d’exécutions extrajudiciaires,\nd’arrestations et de détentions arbitraires, de disparitions forcées, de tortures et\ntraitements cruels, inhumains ou dégradants, et de violences sexuelles depuis avril 2015\nau Burundi."},{"id":"a-hrc-36-crp-1-p0719","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"719","seq":721,"section":"A. Principales conclusions","text":"Ces violations favorisées par un climat de violence continu en 2015 ont perduré,\npour certaines de manière plus clandestine, mais tout aussi brutale, en 2016 et 2017.\nElles ont été entretenues par des discours de haine préoccupants et par une volonté des\nautorités de contrôler plus étroitement la population, notamment en cherchant à\nl’embrigader, souvent de force, au sein du parti au pouvoir. L’espace démocratique\ns’est considérablement restreint depuis 2015. La plupart des journalistes indépendants,\ndes membres d’organisations de la société civile et des partis politiques s’étant opposés\nau nouveau mandat du Président Nkurunziza restent en exil. Les membres des partis\nd’opposition ou leurs proches demeurés au pays sont particulièrement ciblés, tout\ncomme les ex-FAB."},{"id":"a-hrc-36-crp-1-p0720","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"720","seq":722,"section":"A. Principales conclusions","text":"La Commission a identifié des membres des services de renseignement, de la\npolice et de l’armée comme les principaux auteurs de violations des droits de l’homme.\nLeur comportement engage la responsabilité de l’État burundais tout comme celui des\nmembres du parti au pouvoir, notamment de la ligue des jeunes Imbonerakure, dans les\ncas où ceux-ci ont agi sur directives, instructions ou sous contrôle d’agents étatiques ou\nquand ces derniers ont reconnu et adopté leur comportement."},{"id":"a-hrc-36-crp-1-p0721","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"721","seq":723,"section":"A. Principales conclusions","text":"La Commission a des motifs raisonnables de croire que plusieurs violations\nqu’elle a documentées constituent des crimes contre l’humanité, en particulier des\nmeurtres, des emprisonnements, des tortures, des viols et d’autres formes de violence\nsexuelle de gravité comparable, ainsi que des persécutions politiques et sexistes. Ces\ncrimes s’inscrivent dans le cadre d’une attaque généralisée et systématique contre une\npartie de la population civile du Burundi, encouragée par une politique sous-jacente\nvisant à faire taire toute opposition dans le pays."},{"id":"a-hrc-36-crp-1-p0722","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"722","seq":724,"section":"A. Principales conclusions","text":"La Commission a été particulièrement frappée par un climat de peur profonde\nqui affecte les Burundais jusque dans les pays où ils ont fui. Ce climat de peur et les\nrisques encourus de violations graves des droits de l’homme au cas où des réfugiés\nseraient renvoyés au Burundi imposent, selon la Commission, un respect strict du\nprincipe de non-refoulement par les pays de refuge1333."},{"id":"a-hrc-36-crp-1-p0723","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"723","seq":725,"section":"B. Recommandations","text":"Sur la base de ces conclusions, la Commission recommande :\n1.     Aux autorités burundaises :"},{"id":"a-hrc-36-crp-1-p0724","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"724","seq":726,"section":"B. Recommandations","text":"De mettre immédiatement un terme aux violations graves des droits de l’homme\ncommises par des agents de l’État et des Imbonerakure sur lesquels l’État exerce un\ncontrôle ;"},{"id":"a-hrc-36-crp-1-p0725","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"725","seq":727,"section":"B. Recommandations","text":"D’enquêter sur ces violations et s’assurer que les auteurs présumés soient jugés\ndans les meilleurs délais, dans des procédures crédibles, indépendantes et équitables, et\nque les victimes obtiennent une juste réparation. Dans le cas où les auteurs présumés\nsont des agents de l’État, les suspendre jusqu’au terme de l’enquête et de la procédure\njudiciaire ;"},{"id":"a-hrc-36-crp-1-p0726","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"726","seq":728,"section":"B. Recommandations","text":"De prendre des mesures concrètes pour une amélioration rapide de la situation\ndes droits de l’homme, notamment en :\n• Annulant les mandats d’arrêt contre des dirigeants de médias, d’organisations de\nla société civile et de partis politiques qui n’ont pas utilisé ou prôné la violence, et\npermettant leur retour en toute sécurité au Burundi ;\n• Levant la suspension et la radiation des médias et organisations de la société\ncivile, leur permettant de reprendre leurs activités en toute indépendance, et\nrevoyant les lois adoptées en 2017 sur les organisations non-gouvernementales\nburundaises et internationales ;\n• Libérant immédiatement tous les prisonniers politiques ;\n• S’assurant que toute personne arrêtée soit détenue dans un lieu de détention\nofficiel et que des observateurs nationaux et internationaux soient autorisés à\nleur rendre visite ;\n• Veillant à ce que les officiers de police judiciaire ne soient pas habilités à mener\ndes perquisitions sans mandat et de nuit comme envisagé dans les projets\nd’amendement du Code pénal et du Code de procédure pénale ;\n• S’assurant que des individus qui n’y sont pas légalement habilités, en particulier\ndes Imbonerakure, ne conduisent pas des activités de maintien de l’ordre ou n’y\nprennent pas part, y compris dans des lieux de détention, et qu’ils ne portent pas\ndes uniformes militaires ou de police ou ne soient pas en possession d’armes ;\n• Poursuivant les auteurs de discours haineux ou appelant à la violence ;\n• Mettant fin aux menaces, intimidations et actes d’extorsion par des agents de\nl’État et des Imbonerakure ;\n• Permettant aux victimes de violences sexuelles et de torture d’avoir accès à des\nservices médicaux et psychosociaux ;"},{"id":"a-hrc-36-crp-1-p0727","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"727","seq":729,"section":"B. Recommandations","text":"D’engager une réforme en profondeur du système judiciaire, notamment en :\n• Publiant les conclusions des états généraux de la justice qui se sont tenus en 2013\nà Gitega ;\n• Revoyant la composition du Conseil national de la magistrature afin que ses\nmembres soient en majorité désignés par leurs pairs ;\n• Revoyant les procédures de nomination, d’affectation, de notation et\nd’avancement des magistrats afin qu’elles ne dépendent pas du pouvoir exécutif ;\n• Veillant au respect strict du principe d’inamovibilité des magistrats du siège ;\n• Protégeant et garantissant l’indépendance du système judiciaire en interdisant\ntoute ingérence dans le fonctionnement de la justice par des autorités\ngouvernementales, des membres du parti au pouvoir ou des membres des corps\nde défense et de sécurité, et en prenant des sanctions contre ceux qui influencent,\nou cherchent à influencer, le fonctionnement de la justice ;\n• Développant des programmes d’aide juridictionnelle pour les plus vulnérables ;\n• Renforçant les mécanismes de protection de victimes et de témoins, ainsi que leur\nefficacité, pour restaurer la confiance de la population et encourager les témoins\nà s’exprimer sans crainte pour leur sécurité ;"},{"id":"a-hrc-36-crp-1-p0728","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"728","seq":730,"section":"B. Recommandations","text":"De s’assurer que les membres des corps de défense et de sécurité respectent les\ndroits de l’homme en toutes circonstances et servent les intérêts de la population dans\nson ensemble et pas uniquement ceux du parti au pouvoir, notamment en :\n• Renforçant le contrôle civil des corps de défense et de sécurité et l’indépendance\ndes organes chargés de ce contrôle créés par la Constitution, en particulier le\nParlement, la Commission nationale indépendante des droits de l’homme et\nl’Ombudsman ;\n• Remédiant à la carence constitutionnelle de contrôle civil du SNR ;\n• Prenant des mesures pour vérifier les antécédents, notamment en matière de\ndroits de l’homme, des agents des corps de défense et de sécurité et intégrant ces\nmesures à une refonte des procédures de recrutement et d’avancement de ces\nagents ;"},{"id":"a-hrc-36-crp-1-p0729","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"729","seq":731,"section":"B. Recommandations","text":"De revenir sur sa décision de se retirer du Statut de Rome et coopérer pleinement\navec la CPI dans la procédure d’examen préliminaire en cours et, si une enquête est\nouverte, poursuivre cette coopération et assurer la protection des victimes et témoins ;"},{"id":"a-hrc-36-crp-1-p0730","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"730","seq":732,"section":"B. Recommandations","text":"D’autoriser le HCDH à reprendre ses activités de documentation des violations\ndes droits de l’homme au Burundi, suspendues depuis octobre 2016 ;"},{"id":"a-hrc-36-crp-1-p0731","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"731","seq":733,"section":"B. Recommandations","text":"De signer et mettre en œuvre le mémorandum d’entente avec l’Union africaine et\npermettre le déploiement complet des 100 observateurs des droits de l’homme et des\n100 experts militaires, décidé en 2016 ;"},{"id":"a-hrc-36-crp-1-p0732","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"732","seq":734,"section":"B. Recommandations","text":"De coopérer avec les mécanismes des droits de l’homme des Nations Unies en\naccueillant à nouveau des missions des procédures spéciales et en mettant en œuvre les\nrecommandations récentes des organes de traité ;"},{"id":"a-hrc-36-crp-1-p0733","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"733","seq":735,"section":"B. Recommandations","text":"De s’engager activement dans la voie d’une résolution durable de la crise\npolitique, notamment dans le cadre d’initiatives de dialogue engagées au niveau\ninternational.\n2.   Aux partis politiques et groupes armés d’opposition :"},{"id":"a-hrc-36-crp-1-p0734","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"734","seq":736,"section":"B. Recommandations","text":"De mettre immédiatement un terme aux atteintes aux droits de l’homme et aux\nactes de violence commis par leurs membres ;"},{"id":"a-hrc-36-crp-1-p0735","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"735","seq":737,"section":"B. Recommandations","text":"De s’abstenir de tout discours appelant à la violence et s’engager dans la\nrecherche d’une solution durable à la crise politique au Burundi.\n3.   Au Conseil des droits de l’homme :"},{"id":"a-hrc-36-crp-1-p0736","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"736","seq":738,"section":"B. Recommandations","text":"De prolonger le mandat de la Commission pour une durée d’un an aux fins\nd’approfondir et de poursuivre ses enquêtes en raison de la persistance des violations\ngraves des droits de l’homme et des atteintes à ceux-ci et en l’absence d’autres\nmécanismes spécifiques en mesure de mener des enquêtes indépendantes et\napprofondies sur la situation des droits de l’homme au Burundi ;"},{"id":"a-hrc-36-crp-1-p0737","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"737","seq":739,"section":"B. Recommandations","text":"De demander au Haut-Commissaire des Nations Unies aux droits de l’homme de\nfaire un rapport sur l’évolution de sa coopération avec le Gouvernement du Burundi\naux prochaines sessions du Conseil.\n4.   À la Cour pénale internationale :"},{"id":"a-hrc-36-crp-1-p0738","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"738","seq":740,"section":"B. Recommandations","text":"D’ouvrir dans les plus brefs délais une enquête sur les crimes commis au Burundi\nau vu des conclusions contenues dans le présent rapport et d’autres informations à sa\ndisposition.\n5.   Au Conseil de sécurité des Nations Unies :"},{"id":"a-hrc-36-crp-1-p0739","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"739","seq":741,"section":"B. Recommandations","text":"De prendre dûment compte des présentes conclusions de la Commission et de la\npersistance de violations graves des droits de l’homme dans toute discussion sur le\nBurundi et, dans ce contexte, veiller à la mise en œuvre effective de la résolution 2303\n(2016) ;"},{"id":"a-hrc-36-crp-1-p0740","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"740","seq":742,"section":"B. Recommandations","text":"De saisir la CPI de tout crime de droit international qui serait commis au\nBurundi après le 27 octobre 2017 ;"},{"id":"a-hrc-36-crp-1-p0741","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"741","seq":743,"section":"B. Recommandations","text":"De prendre des sanctions individuelles contre les principaux auteurs présumés de\nviolations graves des droits de l’homme et de crimes de droit international au Burundi.\n6.   Au Secrétaire-général des Nations Unies :"},{"id":"a-hrc-36-crp-1-p0742","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"742","seq":744,"section":"B. Recommandations","text":"De veiller à ce que le respect des droits de l’homme et la restauration de l’État de\ndroit soient parmi les priorités de son Envoyé spécial sur le Burundi ;"},{"id":"a-hrc-36-crp-1-p0743","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"743","seq":745,"section":"B. Recommandations","text":"De veiller à ce qu’aucun auteur présumé de violations des droits de l’homme ou\nde crimes de droit international au Burundi ne soit recruté dans des missions de\nmaintien de la paix des Nations Unies.\n7.   Aux États membres des Nations Unies :"},{"id":"a-hrc-36-crp-1-p0744","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"744","seq":746,"section":"B. Recommandations","text":"D’accorder prima facie le statut de réfugié aux demandeurs d’asile burundais et\nveiller au respect strict du principe de non-refoulement, ainsi qu’à la protection des\nréfugiés ;"},{"id":"a-hrc-36-crp-1-p0745","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"745","seq":747,"section":"B. Recommandations","text":"De poursuivre, au titre de la compétence universelle, les auteurs présumés de\ncrimes de droit international commis au Burundi se trouvant sur leur territoire ;"},{"id":"a-hrc-36-crp-1-p0746","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"746","seq":748,"section":"B. Recommandations","text":"De maintenir, en l’absence de toute amélioration de la situation des droits de\nl’homme dans le pays, les sanctions individuelles et la suspension de l’aide directe au\nGouvernement burundais;"},{"id":"a-hrc-36-crp-1-p0747","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"747","seq":749,"section":"B. Recommandations","text":"De fournir une assistance technique aux autorités burundaises, dans la mesure où\nces dernières font preuve d’une véritable volonté politique, afin de mener des enquêtes\ncrédibles et indépendantes, notamment en matière d’autopsie, d’exhumation et\nd’identification des corps ;"},{"id":"a-hrc-36-crp-1-p0748","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"748","seq":750,"section":"B. Recommandations","text":"De soutenir la mise en place de services médicaux et psychosociaux spécialisés,\nnotamment pour les victimes de torture et de violences sexuelles ;"},{"id":"a-hrc-36-crp-1-p0749","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"749","seq":751,"section":"B. Recommandations","text":"De soutenir les autorités burundaises, si celles-ci font preuve d’une véritable\nvolonté politique, dans tout effort de réforme du système judiciaire et du secteur de\nsécurité qu’elles voudront engager aux fins d’améliorer la situation des droits de\nl’homme.\n8.   À l’Union africaine :"},{"id":"a-hrc-36-crp-1-p0750","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"750","seq":752,"section":"B. Recommandations","text":"De reprendre l’initiative dans la recherche d’une solution durable à la crise au\nBurundi fondée sur le respect des droits de l’homme et le rejet de l’impunité, tels que\nprévus par son Acte constitutif, et s’y engager activement ;"},{"id":"a-hrc-36-crp-1-p0751","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"751","seq":753,"section":"B. Recommandations","text":"De veiller à ce qu’aucun agent de l’État burundais accusé de violations des droits\nde l’homme ou de crimes de droit international ne soit recruté dans des missions de\nmaintien de la paix de l’Union africaine ;"},{"id":"a-hrc-36-crp-1-p0752","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"752","seq":754,"section":"B. Recommandations","text":"De s’assurer que l’équipe complète de ses observateurs des droits de l’homme et\nexperts militaires soit rapidement déployée au Burundi ;"},{"id":"a-hrc-36-crp-1-p0753","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"753","seq":755,"section":"B. Recommandations","text":"D’envisager, en cas de persistance de la situation actuelle au Burundi,\nl’application de l’article 4 (h) de son Acte constitutif, autorisant l’Union africaine à\nintervenir dans un État membre dans certaines circonstances, notamment en cas de\ncrimes contre l’humanité.\n9.   À la Communauté des États d’Afrique de l’Est :"},{"id":"a-hrc-36-crp-1-p0754","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"754","seq":756,"section":"B. Recommandations","text":"De s’assurer que l’amélioration rapide de la situation des droits de l’homme soit\nune priorité dans ses efforts de médiation.\n10.   Aux garants de l’Accords d’Arusha de 2000, en leur qualité d’acteurs engagés en faveur\nd’une paix durable au Burundi :"},{"id":"a-hrc-36-crp-1-p0755","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"755","seq":757,"section":"B. Recommandations","text":"De se réunir le plus rapidement possible en vue de trouver une solution pérenne à\nla crise politique et des droits de l’homme au Burundi."},{"id":"a-hrc-36-crp-1-p0001-a1","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"1","seq":758,"section":"A. Carte du Burundi","text":"Note verbale envoyée à la Mission permanente de la République du Burundi, le 20\ndécembre 2016","annex":1},{"id":"a-hrc-36-crp-1-p0002-a1","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"2","seq":759,"section":"A. Carte du Burundi","text":"Note Verbale envoyée à la Mission permanente de la République du Burundi, le 24\njanvier 2017","annex":1},{"id":"a-hrc-36-crp-1-p0003-a1","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"3","seq":760,"section":"A. Carte du Burundi","text":"Note verbale de la Mission permanente de la République du Burundi, le 26 janvier 2017","annex":1},{"id":"a-hrc-36-crp-1-p0004-a1","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"4","seq":761,"section":"A. Carte du Burundi","text":"Note verbale envoyée à la Mission permanente de la République du Burundi, le 6\nfévrier 2017, accompagnant une lettre destinée au ministre des Relations extérieures et\nde la coopération internationale de la République du Burundi","annex":1},{"id":"a-hrc-36-crp-1-p0005-a1","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"5","seq":762,"section":"A. Carte du Burundi","text":"Note verbale envoyée à la Mission permanente de la République du Burundi, le 13 mars","annex":1},{"id":"a-hrc-36-crp-1-p0006-a1","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"6","seq":763,"section":"A. Carte du Burundi","text":"Note envoyée à la Mission permanente de la République du Burundi, le 20 mars 2017,\naccompagnant une lettre destinée au ministre des relations extérieures et de la\ncoopération internationale de la République du Burundi","annex":1},{"id":"a-hrc-36-crp-1-p0007-a1","rec_id":"recibKcqsdbQsGvUW","symbol":"A/HRC/36/CRP.1","n":"7","seq":764,"section":"A. Carte du Burundi","text":"Lettre envoyée au Représentant permanent de la République du Burundi, le 28 août\n2017, accompagnant le rapport final de la Commission d’enquête sur le Burundi\n(A/HRC/36/54)","annex":1},{"id":"a-hrc-39-63-u0000","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":null,"seq":0,"section":null,"text":"United Nations                                                                                      A/HRC/39/63\nGeneral Assembly                                                          Distr.: General\n8 August 2018\nEnglish\nOriginal: French","unnumbered":true},{"id":"a-hrc-39-63-u0001","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":null,"seq":1,"section":null,"text":"Summary\nThe Commission of Inquiry on Burundi found that the serious human rights\nviolations documented in the first year of its mandate, including crimes against humanity,\nhave persisted in 2017 and 2018. Such violations include cases of summary execution,\nenforced disappearance, arbitrary arrest and detention, torture and other cruel, inhuman or\ndegrading treatment, sexual violence, and violations of civil liberties such as the freedoms\nof expression, association, assembly and movement (see A/HRC/36/54 and\nA/HRC/36/54/Corr.1).\nWhile the State entities that are most often implicated in these violations continue to\nbe the National Intelligence Service and the police, the Commission is concerned about the\ngrowing role being played by members of the ruling party’s youth league, the\nImbonerakure, in a situation in which recruitment drives among the general public are\nbeing used as a means of suppressing all opposition. The perpetrators of the violations are\noperating in a climate of impunity perpetuated by the lack of an independent judiciary.\nThe political crisis in Burundi has had a very negative impact on the country’s\neconomic and social situation and has fuelled an increase in poverty. The Government has\nnonetheless imposed additional taxes and contributions, in contravention of the right of all\npersons to an adequate standard of living, and has failed to devote the greatest possible\nshare of its domestic resources to the realization of economic and social rights.","unnumbered":true},{"id":"a-hrc-39-63-p0001","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"1","seq":2,"section":"A. Mandate","text":"The Commission of Inquiry on Burundi was created by Human Rights Council\nresolution 33/24, adopted on 30 September 2016, to conduct a thorough investigation into\nhuman rights violations and abuses in Burundi since April 2015, to determine whether any\nof them may constitute international crimes, to identify their alleged perpetrators and to\nformulate recommendations for ensuring that such perpetrators “are held accountable for\ntheir acts”. By its resolution 36/19, adopted on 29 September 2017, the Council extended\nthe Commission’s mandate without modification for one year."},{"id":"a-hrc-39-63-p0002","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"2","seq":3,"section":"A. Mandate","text":"In 2018, the Commission placed special emphasis on the violations and abuses\ncommitted since 2017 in order to highlight developments in the situation as compared to\nthe one prevailing in 2015 and 2016. The Commission also focused more closely on\neconomic and social rights and the functioning of the judicial system."},{"id":"a-hrc-39-63-p0003","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"3","seq":4,"section":"A. Mandate","text":"On 1 February 2018, Mr. Doudou Diène of Senegal was appointed to chair the\nCommission following the resignation of the previous Chair, Mr. Fatsah Ouguergouz. On 5\nMarch 2018, Ms. Lucy Asuagbor of Cameroon was appointed to serve as a member of the\nCommission to replace Ms. Reine Alapini Gansou, who was elected to the International\nCriminal Court. Ms. Françoise Hampson of the United Kingdom of Great Britain and\nNorthern Ireland continued to serve as a member of the Commission, as she has done since\nits inception."},{"id":"a-hrc-39-63-p0004","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"4","seq":5,"section":"A. Mandate","text":"The Commission presented two oral briefings to the Human Rights Council, at the\nCouncil’s thirty-seventh and thirty-eighth sessions. The present report summarizes the final\nconclusions of its investigations, which will be detailed in a separate document.1"},{"id":"a-hrc-39-63-p0005","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"5","seq":6,"section":"B. Cooperation by Burundi with the Commission","text":"By its resolution 36/19, the Human Rights Council urged the Government of\nBurundi to cooperate fully with the Commission of Inquiry, to authorize it to conduct visits\nto the country and to provide it with all the information necessary to fulfil its mandate. To\nthis end, the Commission sent six letters to the Permanent Mission of Burundi in Geneva\nand one letter to the Minister for Foreign Affairs and International Cooperation (annex II).\nIt called on the Burundian authorities, including during its oral briefings to the Human\nRights Council, to grant it access to Burundi and to share information on the human rights\nsituation in the country, including information concerning attacks on agents of the State and\nmembers of the ruling party. As in the past, these requests have gone unanswered. The\nBurundian authorities have consistently disputed the content of the Commission’s briefings\nand reports and have taken a hostile attitude towards the Commission, threatening twice to\ntake legal action against its members. The United Nations High Commissioner for Human\nRights has condemned this threat as being contrary to the 1946 Convention on the\nPrivileges and Immunities of the United Nations."},{"id":"a-hrc-39-63-p0006","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"6","seq":7,"section":"C. Methodology","text":"During the current mandate period, the Commission visited Belgium, Uganda, the\nDemocratic Republic of the Congo, Rwanda and the United Republic of Tanzania. It also\nconducted a mission to Ethiopia to meet with representatives of the African Union.\nThrough these visits and numerous remote contacts, in particular with individuals living in\nBurundi, the Commission conducted more than 400 interviews with victims, witnesses and\n1   That document (A/HRC/39/CRP.1) will be available shortly on the website of the Human Rights\nCouncil and the Commission of Inquiry on Burundi (www.ohchr.org/EN/HRBodies/HRC/\nIBurundi/Pages/CoIBurundi.aspx).\nother sources. These are in addition to the 500 interviews conducted and the testimonies\ngathered during its initial mandate period."},{"id":"a-hrc-39-63-p0007","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"7","seq":8,"section":"C. Methodology","text":"As it had done for its previous report (A/HRC/36/54 and A/HRC/36/54/Corr.1), the\nCommission adopted the same standard of proof as most other commissions of inquiry on\nhuman rights, namely “reasonable grounds to believe”. It therefore took care to collect a\nbody of reliable and consistent information on the basis of which a reasonable and\nordinarily prudent person would have reason to believe that an incident or pattern of\nconduct had occurred."},{"id":"a-hrc-39-63-p0008","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"8","seq":9,"section":"D. Applicable law","text":"The law applicable to the work of the Commission, namely international human\nrights law and international criminal law, has also remained the same (see A/HRC/36/54,\nparas. 9 and 10). Over the past year, there have been no new developments pointing to the\nexistence of an armed conflict to which the rules of international humanitarian law would\napply. Having decided to place greater emphasis on economic and social rights, the\nCommission based its legal analyses on the relevant instruments to which Burundi is a\nparty.2"},{"id":"a-hrc-39-63-p0009","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"9","seq":10,"section":"D. Applicable law","text":"Burundi remains a party to the Convention on the Prevention and Punishment of the\nCrime of Genocide, but it ceased to be a party to the Rome Statute of the International\nCriminal Court on 27 October 2017. The country’s withdrawal from the Rome Statute does\nnot, however, discharge it from the obligations arising therefrom while it was a party to this\ntreaty. 3 Accordingly, on 25 October 2017, Pre-Trial Chamber III of the International\nCriminal Court authorized the Prosecutor of the Court to open an investigation into crimes\ncommitted in Burundi between 26 April 2015 and 26 October 2017. The Commission has\ncontinued to refer to the definitions of crimes provided by the Rome Statute, which are\nreflected in the Criminal Code of Burundi."},{"id":"a-hrc-39-63-p0010","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"10","seq":11,"section":"A. Main trends","text":"The Commission found that the main human rights violations documented since the\npolitical crisis began in April 2015, namely cases of summary execution, disappearance and\nenforced disappearance, arbitrary arrest and detention, torture and ill-treatment, and sexual\nviolence, have persisted in 2017 and 2018. As in the past, most of the victims of these\nviolations are opponents of the Government and/or of the ruling party (the Conseil national\npour la défense de la démocratie-Forces pour la défense de la démocratie (CNDD-FDD)) or\npersons who are perceived as such, including members of opposition political parties\n(particularly the Forces nationales de libération, led by Agathon Rwasa, and the\nMouvement pour la solidarité et la démocratie); supporters of armed opposition groups;\nBurundians trying to flee the country and therefore suspected of joining such groups; or\njournalists or members of civil society organizations."},{"id":"a-hrc-39-63-p0011","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"11","seq":12,"section":"A. Main trends","text":"The violations have had lasting psychological and physical effects on the victims.\nThose that have been committed primarily against men, including enforced disappearance\nand summary execution, have had multiple consequences for the victims’ families. In\naddition to the impact of losing a spouse, wives often face harassment, threats or violence\non the part of the alleged perpetrators and are unable to meet the basic needs of their\nfamilies."},{"id":"a-hrc-39-63-p0012","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"12","seq":13,"section":"A. Main trends","text":"Before and during the campaign to amend the Constitution, CNDD-FDD and its\nyouth league, the Imbonerakure, stepped up their efforts to recruit members from among\nthe general public. These efforts focused in particular on Burundians — even those who\nwere apolitical — who had refused or been unable to register to vote and on those who had\nnot paid their contribution for the 2020 elections. These trends are further limiting freedom\nof expression in a country whose main independent media outlets and human rights\norganizations have been banned. Those that continue to operate in the country have been\nsubjected to restrictions, threats and persecution."},{"id":"a-hrc-39-63-p0013","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"13","seq":14,"section":"A. Main trends","text":"This climate of disregard for human rights continues to be fomented by repeated\ninstances in which hatred and violence have been advocated by the authorities, including\nthe Head of State and members of CNDD-FDD, and by an overall context of impunity\nexacerbated by the lack of an independent and properly functioning judicial system, as well\nas a lack of public trust in the latter. This environment has also had a direct impact on the\nenjoyment of economic and social rights, given that a growing share of the population has\nunmet needs, primarily in the areas of health, nutrition, water, hygiene and sanitation, as a\nresult of increased financial pressure from the authorities and CNDD-FDD. Whereas\nBurundi was formerly a developing country, it is now once again in a state of humanitarian\nemergency. In some cases Burundians are deprived of their rights, such as the right to\neducation, for political reasons."},{"id":"a-hrc-39-63-p0014","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"14","seq":15,"section":"A. Main trends","text":"The number of Burundian refugees increased steadily until 31 March 2018, reaching\nnearly 431,000; it then began to decline. The number today is estimated at 394,778,\naccounting for 3.7 per cent of the Burundian population. 4 The Commission met with\npersons recently granted refugee status who reported that checkpoints, in particular those\nset up by Imbonerakure, have been stepped up at the country’s borders. In some cases,\nhuman rights violations have been committed against individuals who were trying to flee or\nwho had returned to Burundi. Some of these persons have gone back into exile without\nnecessarily being registered in the host country."},{"id":"a-hrc-39-63-p0015","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"15","seq":16,"section":"1. Responsibility of the Burundian State","text":"States have a threefold obligation to respect, protect and fulfil human rights,\nincluding both civil and political rights and economic and social rights.\n(a)        Obligation to respect"},{"id":"a-hrc-39-63-p0016","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"16","seq":17,"section":"1. Responsibility of the Burundian State","text":"The obligation to respect human rights requires States, their agents and persons\nacting under their control to refrain from actively violating the rights of individuals.\n(i)       Responsibility of the State for the conduct of its organs"},{"id":"a-hrc-39-63-p0017","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"17","seq":18,"section":"1. Responsibility of the Burundian State","text":"The Commission found that members of the National Intelligence Service and the\npolice, including high-ranking officials, were involved in the commission of a large number\nof human rights violations in 2017 and 2018. Administrative authorities have also\ncommitted or ordered the commission of human rights violations, including arbitrary arrest\nand detention and ill-treatment."},{"id":"a-hrc-39-63-p0018","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"18","seq":19,"section":"1. Responsibility of the Burundian State","text":"New testimonies, including from former State and security officials, have confirmed\nthe central role being played by an informal structure surrounding the Head of State, often\nreferred to as the “committee of generals”, that includes State officials such as the Minister\nof Public Security, the Administrator-General of the National Intelligence Service, the\nheads of the President’s civil cabinet and office of police affairs, and the Secretary-General\nof CNDD-FDD. This structure sets the policy on political and security issues, including the\nmeasures to be taken in relation to opponents. It transmits its orders and directives through\na parallel hierarchy and chains of command based on a network of personal loyalties, some\nof which date back to the time of the rebellion, whose composition varies from one\nprovince or locality to another. The workings of this structure always involve more or less\n4   Office of the United Nations High Commissioner for Refugees, 30 June 2018. See\nhigh-ranking officials of the National Intelligence Service, the police, the army, the\nadministration and CNDD-FDD. In this regard, organs of the State are often\nindistinguishable from organs of the ruling party."},{"id":"a-hrc-39-63-p0019","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"19","seq":20,"section":"1. Responsibility of the Burundian State","text":"The Government has imposed additional taxes and contributions, including for the\n2020 elections (see para. 57), and has thereby exacerbated poverty and violated the\nobligation of the State to take appropriate measures to ensure that all persons have an\nadequate standard of living for themselves and their families. 5 Discrimination by State\nagents based on whether or not individuals belong to CNDD-FDD has had an impact on\nspecific rights, such as the right to education, and on employment in the civil service and in\npublic and public-private enterprises.\n(ii)       Responsibility of the State for the conduct of the Imbonerakure"},{"id":"a-hrc-39-63-p0020","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"20","seq":21,"section":"1. Responsibility of the Burundian State","text":"The information gathered, in particular from former members of the Imbonerakure\nand CNDD-FDD, confirms that the role of the Imbonerakure is growing in an overall\ncontext of recruitment among the general public and persecution of political opponents and\npersons perceived as such. The referendum campaign has given rise to numerous violations\nby Imbonerakure, who, acting either alone or in the presence of law enforcement officers,\nconduct checks to verify whether persons of voting age have registered and whether they\nhave paid their contributions for the 2020 elections. These checks have often served as a\npretext for extortion and theft. Forced recruitment into the Imbonerakure has also\nreportedly been stepped up."},{"id":"a-hrc-39-63-p0021","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"21","seq":22,"section":"1. Responsibility of the Burundian State","text":"The increase in these activities and the wider latitude being left to the Imbonerakure\ndemonstrate their collusion with formal and informal structures of State repression (see\npara. 18). The fact that the Imbonerakure are members of the “joint human security\ncommittees”, along with representatives of the administration and the police, indicates that\nthey are acknowledged to play a role in the security apparatus. With the consent of local\ngovernments, Imbonerakure have been used as auxiliaries or substitutes for law\nenforcement in the country’s interior, where such forces have a reduced presence. Some\ntestimonies have even indicated that police operations against opponents have been led by\nImbonerakure."},{"id":"a-hrc-39-63-p0022","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"22","seq":23,"section":"1. Responsibility of the Burundian State","text":"The Commission is thus in a position to establish the responsibility of the Burundian\nState for wrongful acts committed by Imbonerakure in four contexts: when their conduct is\nacknowledged and adopted by agents of the State,6 when they act on the instructions or\nunder the direction of the latter,7 and when they act in “complete dependence” on or under\nthe “effective control” of such agents."},{"id":"a-hrc-39-63-p0023","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"23","seq":24,"section":"1. Responsibility of the Burundian State","text":"Imbonerakure have continued to make arrests on their own initiative, often with\nviolence, and to hand over the persons apprehended to the police or the National\nIntelligence Service. The detention of such persons by law enforcement shows that the\nlatter have adopted the conduct of such Imbonerakure. This acknowledgement is also\ndemonstrated by the fact that no measures have been taken to put a stop to such conduct."},{"id":"a-hrc-39-63-p0024","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"24","seq":25,"section":"1. Responsibility of the Burundian State","text":"Imbonerakure have continued to act on the orders of officials, including high-\nranking officials, of the National Intelligence Service, the police and the Office of the\nPresident. Some have taken part in law enforcement operations or operations against\nopponents, acting alongside police or intelligence officers and in some cases wearing the\nsame uniforms or carrying the same weapons as the defence and security forces. Such\nconduct by Imbonerakure has even taken place in prisons, such as the Mpimba prison in\nBujumbura, and in police holding cells."},{"id":"a-hrc-39-63-p0025","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"25","seq":26,"section":"1. Responsibility of the Burundian State","text":"The growing role and freedom of action of the Imbonerakure are entirely dependent\non the discretion of State power structures and on the impunity accorded by the latter. To\ndemonstrate the “complete dependence” of an organization on the State, international\n5 International Covenant on Economic, Social and Cultural Rights, art. 11.\n6 International Law Commission, articles on responsibility of States for internationally wrongful acts,\nart. 11.\n7 Ibid., art. 8.\njurisprudence nonetheless requires the existence of a particularly great degree of control, as\nshown, for example, by the provision of considerable military and financial support and\nsystematic alignment with State policy.8 In this connection, witness statements confirm that\na group of demobilized soldiers, subsequently joined by Imbonerakure, was created in 2006\nand has since been trained, armed and remunerated by the former Administrator-General of\nthe National Intelligence Service. Following the killing of that official in 2015, the group\nwas supplemented by new members selected and used by officials of the National\nIntelligence Service, the police and the army to conduct operations, including summary\nexecutions and targeted disappearances. On the basis of this information, the Commission\nis of the view that the group is acting in complete dependence on the Burundian State."},{"id":"a-hrc-39-63-p0026","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"26","seq":27,"section":"1. Responsibility of the Burundian State","text":"The Commission remains convinced that the Imbonerakure often operate under the\n“effective control” of the Burundian State. International jurisprudence requires that such\ncontrol be demonstrated in each case through the planning and organization of operations,\nthe issuance of orders or the provision of equipment by the State. 9 Several witness\nstatements attest to that level of control during operations carried out by Imbonerakure."},{"id":"a-hrc-39-63-p0027","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"27","seq":28,"section":"1. Responsibility of the Burundian State","text":"However, to date, international judges have issued rulings only in cases involving\nentities acting outside the territory of the State in question. In such cases, the State must\nhave exercised direct control in order to be held accountable. The Imbonerakure, however,\nare committing wrongful acts on Burundian territory. The State thus has more means at its\ndisposal, in particular of a legislative, judicial and financial nature, for putting an end to\ntheir activities or, on the contrary, for promoting them through its action or deliberate\ninaction. It is therefore in a position to exercise overall effective control over the\nImbonerakure. Given that the Imbonerakure have been involved in a wide range of\nactivities, including some within the purview of the Government; have in a number of cases\nacted autonomously but with a freedom of action afforded by the authorities; and have\ncontinued to enjoy near-total impunity, the Commission is of the view that the Burundian\nState is responsible for the wrongful acts committed by the Imbonerakure, since it exercises\noverall effective control. Therefore, under international law, the Burundian State may be\nheld accountable for all of the human rights violations attributable to the Imbonerakure.\n(b)        Obligation to protect"},{"id":"a-hrc-39-63-p0028","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"28","seq":29,"section":"1. Responsibility of the Burundian State","text":"The State has a duty to protect the human rights of persons under its jurisdiction, in\nparticular when it knows or should have known of violations or abuses committed by third\nparties. By allowing its agents and/or Imbonerakure who are responsible for such acts to go\nunpunished, including by not conducting investigations or initiating proceedings against\nthem, the Burundian State is failing to meet its obligation to protect. By not taking action to\ncombat impunity and not undertaking a thorough reform of its judicial system (see paras.\n62–65), the Burundian State is encouraging the repeated commission of human rights\nviolations and abuses.\n(c)       Obligation to fulfil"},{"id":"a-hrc-39-63-p0029","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"29","seq":30,"section":"1. Responsibility of the Burundian State","text":"Article 2 of the International Covenant on Economic, Social and Cultural Rights\nrequires States parties to take steps to the maximum of their available resources with a view\nto achieving progressively the full realization of the rights recognized therein. The fact that\ninternational assistance to Burundi has decreased since 2015 as a result of violations of civil\nand political rights does not relieve the Burundian State of its obligation to devote the\nmaximum of its available resources to the realization of economic and social rights. Yet the\nCommission has noted that the country’s domestic resources are oriented more towards\ndefence and security expenditures and that there are many exemptions. The Commission\nhas also received information on the misappropriation and seizure of public property by\n8 International Court of Justice, Application of the Convention on the Prevention and Punishment of the\nCrime of Genocide (Bosnia and Herzegovina v. Serbia and Montenegro), Judgment, I.C.J. Reports\n2007.\n9 Ibid.; see also International Court of Justice, Military and Paramilitary Activities in and against\nNicaragua (Nicaragua v. United States of America), Merits, Judgment, I.C.J. Reports 1986.\nsenior officials (see para. 60) in a country that is experiencing a humanitarian crisis and in\nwhich much of the population is unable to enjoy the right to food."},{"id":"a-hrc-39-63-p0030","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"30","seq":31,"section":"2. Responsibility of armed groups and opposition political parties","text":"The existence of armed groups at the border continues to pose a threat to the\ncountry’s civilian population. To the Commission’s knowledge, none of these groups\nclaimed responsibility for an attack on Burundian soil in 2017 or 2018. Because the\nCommission has not had access to victims and the Government has repeatedly refused to\nhand over evidence, the Commission has been unable to corroborate the information it has\nreceived on the involvement of armed groups in human rights violations in Burundi since\n2015. In particular, it has not been able to identify the group responsible for the killing of at\nleast 24 people on 11 May 2018 in the district (commune) of Buganda, Province of\nCibitoke. The findings of the investigation carried out by the Burundian authorities have\nnot yet been released."},{"id":"a-hrc-39-63-p0031","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"31","seq":32,"section":"2. Responsibility of armed groups and opposition political parties","text":"The Commission noted that on 3 and 5 April 2018, a call to arms via Twitter and\nFacebook was issued by Jérémie Minani, a member of the governing body of the National\nCouncil for the Restoration of the Arusha Peace and Reconciliation Agreement for Burundi,\nthe Constitution and the Rule of Law, which is a platform for opposition political parties in\nexile. On 8 June 2018, the Civic Forum of Burundi issued a statement, signed by the\nPresident of the Council and representatives of civil society organizations in exile, calling\nfor a “revolution” by the Burundian people. While the statement cannot be described as a\nclear incitement to armed conflict, the use of revolutionary language nevertheless raises the\npossibility of recourse to violence."},{"id":"a-hrc-39-63-p0032","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"32","seq":33,"section":"1. Right to life","text":"While summary executions were not found to have taken place on a large scale, as\noccurred in 2015, several witness statements attest to the persistence of such violations,\nprimarily against persons who belonged or were suspected of belonging to the opposition,\nin particular when such persons refused to join CNDD-FDD, to register to vote in the\nreferendum or to pay contributions."},{"id":"a-hrc-39-63-p0033","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"33","seq":34,"section":"1. Right to life","text":"Most of those alleged to have perpetrated summary executions since 2017 have been\nmembers of the National Intelligence Service, the police or the Imbonerakure. Members of\nthe Imbonerakure have acted either alone or in conjunction with the security forces, or\nunder the supervision of the latter."},{"id":"a-hrc-39-63-p0034","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"34","seq":35,"section":"1. Right to life","text":"The practice of concealing the bodies, including by weighing them down with stones\nand throwing them into watercourses or by transporting them from one province or district\nto another in order to make them harder to identify, has persisted. It also continues to be the\ncase that when bodies are found, they are simply buried and no investigation is conducted.\n(b)     Enforced disappearance"},{"id":"a-hrc-39-63-p0035","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"35","seq":36,"section":"1. Right to life","text":"The phenomenon of arbitrary arrest and detention, including in secret locations, the\nconcealment of bodies and the impunity prevailing in the country have continued to create a\nclimate of secrecy that is conducive to cases of disappearance. This secrecy is exacerbated\nby the restrictions imposed on independent journalists and civil society organizations and\nby victims’ reluctance to file complaints for fear of reprisals. According to some\ntestimonies, individuals have disappeared following night-time raids on their homes carried\nout by Imbonerakure. Cases of disappearance also continue to be attributed to officers of\nthe National Intelligence Service and the police."},{"id":"a-hrc-39-63-p0036","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"36","seq":37,"section":"1. Right to life","text":"At this stage of its investigations, the Commission has reasonable grounds to believe\nthat Léopold Habarugira, an official of the opposition party Union pour la paix et le\ndéveloppement-Zigamibanga, who was arrested on 12 September 2017 by a group of\nindividuals including at least one person wearing a police uniform, has been a victim of\nenforced disappearance.10 The same appears to be true of Mouvement pour la solidarité et la\ndémocratie members Bonaventure Havyarimana, Égide Habonimana, Lionel Hafashimana,\nBénius Mbanyenimanga and Emmanuel Nyabenda, who were arrested in Bujumbura on 2\nMarch 2018 by officers of the National Intelligence Service. The twins Bukuru and Butoyi\nShabani, who were arrested in November 2016, and Évariste Nyandwi, alias Matwi, who\nwas arrested in December 2016, were detained in a house in Bujumbura that was used by\nthe National Intelligence Service as a secret place of detention. It is alleged that they were\nsubsequently executed by members of the National Intelligence Service. The Commission\nhas also gathered information on other cases in which it has reason to fear that enforced\ndisappearances have taken place.11"},{"id":"a-hrc-39-63-p0037","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"37","seq":38,"section":"2. Right to liberty and security of person","text":"Cases of arbitrary arrest and detention have continued to be perpetrated. Most such\ncases have targeted persons affiliated with opposition political parties or opposition armed\ngroups or persons perceived as such, as well as persons who did not register to vote or who\ncalled on voters to reject the constitutional amendment. Members of the former Burundian\nArmed Forces (“ex-FAB”) and persons trying to flee the country have also been targeted, as\nhave persons — even those who were apolitical — who refused to join CNDD-FDD or the\nImbonerakure."},{"id":"a-hrc-39-63-p0038","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"38","seq":39,"section":"2. Right to liberty and security of person","text":"Arrests continue to be carried out by police officers, members of the National\nIntelligence Service and administrative authorities. Collective arrests are sometimes made\nin the wake of security incidents or in the case of political opponents. Imbonerakure act in\nthe presence of police officers and/or local authorities, or on their own initiative, before\nhanding the arrested persons over to the police. It is clear that these acts are arbitrary\nbecause the Imbonerakure are not legally authorized to carry out arrests,12 the victims are\nnot informed of the reasons for their arrest and the arrests are conducted without a warrant\nand, in some cases, in a violent manner."},{"id":"a-hrc-39-63-p0039","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"39","seq":40,"section":"2. Right to liberty and security of person","text":"Signs of arbitrary detention include the absence of a legal basis or the misuse of\nvague descriptions such as “undermining the internal security of the State”, prolonged\ndetention without the possibility of appeal, failure to inform the detainee’s relatives and\nlack of access to legal counsel. Relatives of persons wanted by the authorities have been\ndetained or threatened with arrest. Some individuals have been detained in police holding\ncells before being taken to the National Intelligence Service or the Special Investigation\nBrigade. Testimonies concerning detention in unofficial places have also been obtained, as\nwell as information on the use of police holding cells to detain Imbonerakure for internal\ndisciplinary purposes."},{"id":"a-hrc-39-63-p0040","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"40","seq":41,"section":"2. Right to liberty and security of person","text":"The same arbitrariness continues to be observed with regard to release from custody.\nSome individuals have been released for no apparent reason, others because they knew\nsomeone within the State apparatus and still others in exchange for what have sometimes\namounted to large sums of money. Some individuals who were freed upon acquittal or\npresidential pardon have been rearrested or subjected to death threats, or are being sought\nby State agents or Imbonerakure. In addition, some persons who were sentenced for\npolitical reasons have been kept in detention even after they had been exonerated or had\ncompleted the term of their sentence."},{"id":"a-hrc-39-63-p0041","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"41","seq":42,"section":"3. Torture and other cruel, inhuman or degrading treatment","text":"Cases of torture and ill-treatment have persisted. While some of these acts have been\ncommitted by officers of the National Intelligence Service and the police, the majority have\n10 See the definition of “enforced disappearance” in article 2 of the International Convention for the\nProtection of All Persons from Enforced Disappearance.\n11 In these cases, some but not all elements of the definition of “enforced disappearance” are present.\nFor further details, see A/HRC/36/54, para. 38; see also A/HRC/36/CRP.1 and A/HRC/39/CRP.1.\n12 Unless the person is arrested in flagrante delicto.\nbeen committed by Imbonerakure acting alone, sometimes with the assistance or in the\npresence of police officers."},{"id":"a-hrc-39-63-p0042","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"42","seq":43,"section":"3. Torture and other cruel, inhuman or degrading treatment","text":"Most of the victims in these cases have been young men who were, or were\nperceived to be, sympathizers or members of opposition political parties and who refused to\njoin the ranks of CNDD-FDD or the Imbonerakure, or who were accused of joining armed\ngroups when they were trying to flee the country. Persons who had refused to register to\nvote or who were suspected of calling on voters to reject the constitutional amendment\nwere targeted during the referendum campaign. In some cases, women have been subjected\nto ill-treatment by Imbonerakure who were looking for a member of their family."},{"id":"a-hrc-39-63-p0043","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"43","seq":44,"section":"3. Torture and other cruel, inhuman or degrading treatment","text":"Most such acts of torture and ill-treatment have occurred in places of detention:\npolice or National Intelligence Service holding cells, the Mpimba central prison in\nBujumbura and unofficial places of detention such as private homes. There have also been\ncases in which the acts occurred in public places, such as streets or fields. Some victims\nwere beaten or kicked on different parts of their bodies or were hit with stones, sticks, rods,\nmetal bars or rifle butts, or were attacked with sharp objects such as machetes or knives.\nSome victims were burned with heated metal rods, and some were tied up or handcuffed. In\na number of cases, acts of torture were accompanied by threats, including death threats,\nintimidation and verbal abuse, sometimes of an ethnically charged nature."},{"id":"a-hrc-39-63-p0044","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"44","seq":45,"section":"3. Torture and other cruel, inhuman or degrading treatment","text":"Several victims described conditions of detention in prisons and police cells that\nconstitute cruel, inhuman or degrading treatment, including overcrowding in cells,\nunhealthy conditions and lack of food, water and medical care."},{"id":"a-hrc-39-63-p0045","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"45","seq":46,"section":"4. Sexual violence","text":"The Commission documented numerous cases of sexual violence. The majority of\nthe victims are women, targeted because they or their spouses belonged or were thought to\nbelong to the opposition or because they refused to join the ranks of CNDD-FDD or the\nImbonerakure, sometimes out of a desire to remain apolitical. Most of the perpetrators were\nImbonerakure or other men who implied that they were acting on behalf of CNDD-FDD. In\nmost of the cases, the women were raped by one or several men during attacks on their\nhomes, which often took place at night. The rapes were often accompanied by other types\nof physical violence against the victims and, in some cases, against other members of the\nhousehold. The perpetrators sometimes made death threats or ethnically charged remarks.\nThese acts, especially those committed for a specific purpose such as intimidation or\npunishment because of the victim’s assumed political affiliation, constitute acts of torture."},{"id":"a-hrc-39-63-p0046","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"46","seq":47,"section":"4. Sexual violence","text":"In the context of detention, men have also been victims of sexual violence, including\ncases of forced nudity and violence on the genital area. Such violence, which constitutes\ntorture, has taken place inter alia in National Intelligence Service cells. Sexual violence has\nbeen perpetrated by police or National Intelligence Service officers, generally against\npersons suspected of belonging to or supporting armed groups."},{"id":"a-hrc-39-63-p0047","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"47","seq":48,"section":"4. Sexual violence","text":"The fact that the victims often have not had access to appropriate health care has\nexacerbated the consequences of sexual violence. Most of the victims have not filed\ncomplaints because they were afraid of being stigmatized, did not have access to justice or\ndid not trust that effective measures would be taken against State agents or perpetrators\nlinked to CNDD-FDD. Several women who had been victims of sexual violence said that\nthey had informed the local authorities but that the latter had not taken any action. The\npersistence of multiple forms of discrimination against women in Burundi is conducive to\nsexual violence."},{"id":"a-hrc-39-63-p0048","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"48","seq":49,"section":"5. Civil liberties","text":"Most of the violations and restrictions that have been documented, particularly in the\ncontext of the referendum campaign, have curtailed the freedom of expression. With regard\nto the media, the National Communication Council, whose powers and subordination to the\nexecutive branch were reinforced by an organization act adopted in March 2018, has\ntightened its control over the media and journalists. In September 2017, the National\nCommunication Council revoked the licences of about a dozen media outlets, including\nRadio publique africaine, Radio Bonesha FM and Radio-Télévision Renaissance, all of\nwhich have been shut down since May 2015. The Council has also ordered a number of\nsuspensions. For example, it suspended radio broadcasts by the Chamber of Commerce and\nIndustry in October 2017 and broadcasts by the British Broadcasting Corporation (BBC)13\nand Voice of America in May 2018, and has suspended certain sections of the online\nnewspapers Iwacu and Le Renouveau. Many independent journalists remain in exile. Others\nhave gone into exile in 2018, and those who are still working in Burundi continue to be\nsubjected to pressure, intimidation and restrictions on the part of local authorities, the\nNational Intelligence Service and Imbonerakure."},{"id":"a-hrc-39-63-p0049","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"49","seq":50,"section":"5. Civil liberties","text":"The Commission remains concerned about the frequent instances of incitement to\nhostility or violence, which contravene article 20 of the International Covenant on Civil and\nPolitical Rights. In particular, certain speeches made by the Head of State — especially\nthose of 18 November 2017, 12 December 2017 and 2 May 2018 — have threatened\nopponents both within and outside CNDD-FDD. These speeches were echoed across the\ncountry by local authorities and members of the ruling party. Melchiade Nzopfabarushe, a\nformer Chef de Cabinet in the Office of the President, was convicted at first instance of\nhaving made remarks amounting to hate speech in April 2018, but his sentence was\nsignificantly reduced on appeal and he has since been released. Other individuals who have\npublicly made similar remarks have gone unpunished. In addition, as in previous years,\nsome Imbonerakure continue to chant militant and hateful slogans as a show of force.\n(b)         Freedoms of association and assembly"},{"id":"a-hrc-39-63-p0050","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"50","seq":51,"section":"5. Civil liberties","text":"The situation of organizations whose authorizations have been suspended or revoked\nand whose accounts have been frozen has not changed. The Burundian authorities have not\nrescinded the international arrest warrants issued against the leaders of such organizations.\nThe two laws adopted in January 2017 on Burundian non-profit organizations and foreign\nnon-governmental organizations have limited those entities’ freedom of association by\nconsiderably strengthening the authorities’ control over their activities and resources. The\nCommission has continued to document arbitrary arrests, prosecutions and severe sentences\nagainst members of civil society organizations still operating in Burundi, as illustrated by\nthe April 2018 sentencing of Germain Rukuki to 32 years’ imprisonment following an\nunfair trial."},{"id":"a-hrc-39-63-p0051","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"51","seq":52,"section":"5. Civil liberties","text":"While the freedom of association is hampered in Burundi, its corollary, the freedom\nnot to associate, is also restricted. Many witnesses have reported that local officials of\nCNDD-FDD and/or Imbonerakure have forced or attempted to force members of opposition\nparties and persons with no political affiliation to join those two organizations. This\nsituation has given rise to threats, harassment, violence and, in some cases, killings or\narbitrary arrests."},{"id":"a-hrc-39-63-p0052","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"52","seq":53,"section":"5. Civil liberties","text":"Members of opposition parties have also been subjected to pressure and restrictions\nthat prevent them from holding public meetings, particularly in the context of the\nreferendum campaign. Several people reported that they had been forced to participate in\nlocal meetings of CNDD-FDD.\n(c)        Freedom of movement"},{"id":"a-hrc-39-63-p0053","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"53","seq":54,"section":"5. Civil liberties","text":"The Commission has noted that three types of interference with freedom of\nmovement have persisted: the use of “household record booklets” to keep track of\npopulation movements; checkpoints in the vicinity of the country’s borders; and cases of\nthreats and harassment against persons whose family members have left Burundi. The\ninspection of “household record booklets”, mainly by the police, has often given rise to\nextortion. Checkpoints near the borders have been stepped up and such checks are often\ncarried out by Imbonerakure, sometimes in collaboration with the police. Cases of arbitrary\narrest, ill-treatment, extortion and threats at the checkpoints have been reported.\n13   BBC subsequently apologized to the Government of Burundi."},{"id":"a-hrc-39-63-p0054","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"54","seq":55,"section":"5. Civil liberties","text":"In 2017 and 2018, freedom of movement was also hampered by roadblocks\nthroughout the country and checkpoints at the entrance to markets. Imbonerakure,\nsometimes in collaboration with local governments, turned away persons who could not\nshow evidence that they had registered for the referendum or that they had paid\ncontributions for the 2020 elections or other levies."},{"id":"a-hrc-39-63-p0055","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"55","seq":56,"section":"D. Violations of economic and social rights","text":"Political crises in Burundi have long had a direct impact on the enjoyment of\neconomic and social rights. The Arusha Agreement identifies the failure to satisfy the basic\nneeds of citizens as one of the causes of violence in Burundi.14 The crisis that broke out in\n2015 was no exception. In 2016, Burundi went from a developing country to a country in a\nstate of humanitarian emergency.15 The United Nations Development Programme (UNDP),\nthe International Monetary Fund (IMF) and the African Development Bank have all\nrecorded zero or negative economic growth in Burundi since 2015. This reversal is taking\nplace in a country where growth is structurally “low and volatile” 16 owing to a lack of\ndiversification of the economy, which is based primarily on an agricultural sector that is\ndominated by subsistence activities and dependent on the vagaries of exports and weather."},{"id":"a-hrc-39-63-p0056","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"56","seq":57,"section":"D. Violations of economic and social rights","text":"IMF noted that the country’s growth prospects for 2018 would remain weak owing\nto internal conflicts, political constraints and governance and security challenges, as well as\nhigh levels of public debt.17 Such debt, which has been rising again since 2015, reflects the\nburden of general expenditure by the State18 and the fact that the country’s international\npartners have continued to suspend direct budget support and to reduce their donations\nsignificantly on account of repeated human rights violations in Burundi."},{"id":"a-hrc-39-63-p0057","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"57","seq":58,"section":"D. Violations of economic and social rights","text":"In response to this situation, the Government turned to domestic debt, which has\n“exploded”19 since 2015, further weakening the economy. It has also introduced new taxes\nand duties and has increased existing ones. For example, taxes on sugar and on fuel and\nlubricants were raised by 33 per cent and 95 per cent, respectively, between 2015 and 2018.\nAdded to this was the contribution “for the 2020 elections”, which was established\nextralegally in December 201720 and duplicates a provision in the State’s 2017 budget. This\ncontribution, which is payable by civil servants, households and students of voting age, has\nin a number of cases been collected forcibly, in particular by Imbonerakure. This has led to\ncases of ill-treatment, arbitrary arrest and detention, threats, intimidation and persecution in\nthe event that a person is unwilling or unable to pay."},{"id":"a-hrc-39-63-p0058","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"58","seq":59,"section":"D. Violations of economic and social rights","text":"These levies, together with various ad hoc contributions imposed at the local level,\nare impoverishing a population whose real per capita gross domestic product has shown\nnegative growth since 201521 and whose share of “non-poor” households was only 20.9 per\ncent prior to the crisis. 22 Poverty is especially prevalent among households headed by\nwomen who are single, widowed or divorced. 23 The population’s access to goods,\nespecially essential items imported from abroad, has been hindered by the rise in exchange\nrates and inflation since 2015. In the space of two years, the number of people “in need”,\nmainly in terms of health care, food, water, hygiene and sanitation, increased from 1\nmillion to 3.6 million, representing more than 34 per cent of the population.24"},{"id":"a-hrc-39-63-p0059","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"59","seq":60,"section":"D. Violations of economic and social rights","text":"Against this backdrop, the Government has not redirected its domestic resources to\ngive priority to social spending, the demand for which has risen steadily in a country whose\npopulation of 10.5 million is likely to double by 2030.25 On the contrary, a review of the\nannual State budgets shows that the amount of domestic resources devoted to defence and\nsecurity expenditures has risen faster than the amounts allocated to basic services other than\neducation. This situation has had a disproportionate impact on women because of their\nspecific needs with regard to services, including health services, and because the lack of\nsocial services increases the burden of unpaid work borne by women within the family.26"},{"id":"a-hrc-39-63-p0060","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"60","seq":61,"section":"D. Violations of economic and social rights","text":"By way of example, the budgets allocated to the National Intelligence Service, the\nSpecial Brigade for the Protection of Institutions and the Unit for the Protection of\nInstitutions (Appui à la protection des institutions), some of whose members have been\nidentified by the Commission as being among the main perpetrators of human rights\nviolations, were increased by 12 per cent, 13.3 per cent and 47.6 per cent, respectively,\nbetween 2015 and 2018, while the domestic resources provided to the Ministry of\nAgriculture and Livestock were reduced by 27.4 per cent.27 What is more, corruption and\nmisappropriation of public funds among high-level authorities are further depleting the\nresources that the State should be devoting to efforts to safeguard the rights of the\npopulation, especially with respect to food and health. Hundreds of people living with\nAIDS are going without treatment, owing in particular to the dire shortage of certain items\nin several of the country’s hospitals."},{"id":"a-hrc-39-63-p0061","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"61","seq":62,"section":"D. Violations of economic and social rights","text":"Recruitment of the population has had a direct impact on the economic and social\nrights of individuals, including in schools, universities and professional circles. Some\nteachers and students have been pressured or have been removed from their schools\nbecause they refused to join CNDD-FDD, to pay the contribution for the 2020 elections or\nto attend information meetings about the constitutional amendment. Others have had to\nleave the country. Hiring decisions in the civil service and in public-private enterprises\nhave been dictated by whether or not the applicant belongs to CNDD-FDD. Trade unions\nthat are not affiliated with the majority party have come under threat and have difficulty\noperating."},{"id":"a-hrc-39-63-p0062","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"62","seq":63,"section":"E. Dysfunction in the judicial system","text":"An in-depth study of the judicial system28 has confirmed the long-standing lack of\njudicial independence in Burundi, as the executive branch exercises institutional control\nover judges and courts through its control of the Judicial Service Commission; most courts’\nbudgets are managed by the Government; judges are appointed and promoted in an\narbitrary manner; the principle that judges should have security of tenure is absent; and\njudges are inadequately paid, creating a situation that is conducive to corruption.\nFurthermore, the judicial system in Burundi does not have enough resources to function\nproperly, despite the recent construction and rehabilitation of courtrooms."},{"id":"a-hrc-39-63-p0063","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"63","seq":64,"section":"E. Dysfunction in the judicial system","text":"At the operational level, the Commission found examples of dysfunction in all\ncomponents of the criminal justice system. The executive branch frequently issues orders\nand otherwise interferes with politically sensitive cases, either to protect members of\nCNDD-FDD and the Imbonerakure by having them acquitted or released, or to have\nopponents of the Government convicted and imprisoned. The use of the broadly and\nvaguely defined offence of “undermining the internal security of the State” to prosecute\nopponents has given rise to abuses. Interference by the authorities is sometimes\n24 Humanitarian country team, Aperçu des besoins humanitaires au Burundi 2018, November 2017.\n25 According to the World Bank, the annual population growth rate now stands at 3.1 per cent.\n26 According to the World Bank, 90 per cent of the unpaid work done in Burundi is carried out by\nwomen; see World Bank, Burundi Poverty Assessment (see note 23).\n27 Calculated by the Commission.\n28 See A/HRC/39/CRP.1.\naccompanied by threats, including threats against the physical integrity of judges, and by\nreprisals against judges if they do not follow instructions."},{"id":"a-hrc-39-63-p0064","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"64","seq":65,"section":"E. Dysfunction in the judicial system","text":"In cases involving political opponents, the rights of accused persons are routinely\nviolated at both the pretrial and the trial stages through restrictions on such persons’ access\nto counsel or obstruction of the work of counsel. The right to a defence is also adversely\naffected by the misuse of the flagrante delicto procedure, particularly in cases involving the\noffence of “undermining the internal security of the State”, and the absence of an\ninstitutionalized system of legal aid. The Commission also received several testimonies\nindicating that lawyers have been subjected to intimidation."},{"id":"a-hrc-39-63-p0065","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"65","seq":66,"section":"E. Dysfunction in the judicial system","text":"The rules of criminal procedure are rarely observed: warrantless arrests of political\nopponents are routinely carried out, pretrial detention is illegally extended and judges use\nconfessions made under torture as a basis for convicting defendants, over the objections of\ndefence counsel. Court decisions ordering the release of defendants are not always\nrespected. The inertia of the public prosecution service in most cases of human rights\nviolations and the reluctance of victims to seek redress, either because they have no faith in\nthe judicial system or because they have been threatened or intimidated, are impeding the\nimplementation of the right to an effective remedy29 and fostering impunity."},{"id":"a-hrc-39-63-p0066","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"66","seq":67,"section":"A. Constituent elements and types of crimes","text":"In view of the circumstances prevailing in 2017 and 2018, in particular the\npersistence of human rights violations, the Commission has reasonable grounds to believe\nthat crimes against humanity continue to be committed in Burundi. The definition of such\ncrimes in article 7 (1) of the Rome Statute as “acts … committed as part of a widespread or\nsystematic attack directed against any civilian population, with knowledge of the attack”\ncontinues to apply."},{"id":"a-hrc-39-63-p0067","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"67","seq":68,"section":"A. Constituent elements and types of crimes","text":"The attack involves the multiple commission of acts against a population consisting\nprimarily of civilians, pursuant to a State or organizational policy.30 In Burundi, it continues\nto be the case that most of the victims are civilians, who are targeted mainly by the police,\nthe National Intelligence Service and the Imbonerakure because of their real or perceived\nopposition to the Government and CNDD-FDD. The policy of the State is difficult to\ndistinguish from that of the majority party, as both are pursuing the same goal of keeping\nCNDD-FDD and its leadership in power. The general public is regularly reminded of the\naim of this policy, as demonstrated by recent speeches made by President Nkurunziza and\nstatements made by representatives of CNDD-FDD at all levels, particularly in the context\nof the referendum campaign (see para. 49)."},{"id":"a-hrc-39-63-p0068","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"68","seq":69,"section":"A. Constituent elements and types of crimes","text":"The number of violations found in several provinces since 2017 and the multiplicity\nof victims and perpetrators demonstrate the persistence of a widespread attack directed\nagainst the civilian population. The systematic nature of the attack is also demonstrable,\ngiven the existence of “patterns of crimes” constituting a “non-accidental repetition of\nsimilar criminal conduct on a regular basis”.31"},{"id":"a-hrc-39-63-p0069","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"69","seq":70,"section":"A. Constituent elements and types of crimes","text":"The attack continues to be carried out knowingly, as the perpetrators identified by\nthe Commission necessarily have an understanding of the context for their actions by\nreason of their roles in the country’s political and security apparatus, as well as their\nindoctrination within CNDD-FDD."},{"id":"a-hrc-39-63-p0070","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"70","seq":71,"section":"A. Constituent elements and types of crimes","text":"The Commission thus has reasonable grounds to believe that the crimes against\nhumanity which it identified previously (see A/HRC/36/54, paras. 69–74, and\nA/HRC/36/54/Corr.1) continue to be committed in Burundi. These crimes include murder,\nimprisonment or other severe deprivation of physical liberty, torture, rape and other forms\nof sexual violence of comparable gravity, and persecution on political grounds. The\nCommission remains cautious about describing the disappearances it has documented as\n“enforced” within the meaning of this term under international criminal law, in view of the\ndifficulty, at the current stage of its investigations, of proving all the elements required\nunder the Rome Statute.32"},{"id":"a-hrc-39-63-p0071","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"71","seq":72,"section":"B. Individual responsibility","text":"The Commission has supplemented the list of alleged perpetrators of crimes against\nhumanity that it drew up during its initial mandate period, taking care to distinguish\nbetween direct responsibility and the responsibility of military commanders and superiors.\nThe list remains confidential, in the interest of protecting the Commission’s sources and\nrespecting the principle of presumption of innocence. It will be turned over to the High\nCommissioner for Human Rights at the end of the Commission’s mandate. In the\nmeantime, the Commission reserves the right to share it."},{"id":"a-hrc-39-63-p0072","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"72","seq":73,"section":"IV. Measures to protect civilians and prevent the recurrence of","text":"In the light of the foregoing, there is an urgent need to put an end to the human\nrights violations and crimes against humanity which the Commission has reasonable\ngrounds to believe are continuing to be committed in Burundi. This imperative arises from\nthe responsibility to protect that lies first and foremost with the Burundian State, which\nmust take the necessary measures to ensure respect for human rights and to prosecute the\nperpetrators of violations and abuses. It must also cooperate with the international human\nrights mechanisms established by the Human Rights Council. Priority must be given to the\nimplementation of the recommendations made in January 2018 in the framework of the\nthird universal periodic review of Burundi and to cooperation with all special procedures\nand treaty bodies that examine the situation in Burundi or request to visit the country."},{"id":"a-hrc-39-63-p0073","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"73","seq":74,"section":"IV. Measures to protect civilians and prevent the recurrence of","text":"In this regard, the Commission is concerned to note that, given the suspension since\nOctober 2016 of the headquarters agreement of the Office of the United Nations High\nCommissioner for Human Rights (OHCHR) office in Burundi; the limited deployment of\nAfrican Union observers, whose ability to operate in the country is hampered by the\nabsence of an agreement with the Government; and the Government’s recent lack of\ncooperation in the implementation of Human Rights Council resolution 36/2, there are now\nno independent international mechanisms in Burundi that are in a position to investigate\nhuman rights violations. It is important for Burundi to reconsider its decision to withdraw\nfrom the Rome Statute of the International Criminal Court and to review the composition\nand functioning of the Independent National Human Rights Commission to ensure that that\nbody respects the principles relating to the status of national institutions for the promotion\nand protection of human rights (the Paris Principles)."},{"id":"a-hrc-39-63-p0074","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"74","seq":75,"section":"IV. Measures to protect civilians and prevent the recurrence of","text":"While putting an end to human rights violations remains a short-term imperative, in\nthe longer term it is also important to consider measures for preventing such violations. An\nexamination of the crisis that Burundi has been experiencing since 2015 reveals the root\ncauses, which persist to this day. The Commission has identified three main factors behind\nthe human rights crisis in Burundi: a narrowing of democratic space, especially since the\n2010 elections; the incomplete and delayed implementation of the truth, justice and security\nsector reform measures set out in the Arusha Agreement; and the shortage of land and\nresources for a steadily increasing population.33 In this context, the struggle for power is\n32 International Criminal Court, Elements of Crimes, The Hague, 2011, p. 11. See also\nA/HRC/39/CRP.1.\n33 See A/HRC/39/CRP.1.\naimed at gaining and keeping control over these resources for the purpose of personal\nenrichment and to fund activities to counter all opposition."},{"id":"a-hrc-39-63-p0075","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"75","seq":76,"section":"IV. Measures to protect civilians and prevent the recurrence of","text":"It is disturbing to observe that the findings set out in 2000 in the Arusha Agreement\nstill characterize the situation today. Article 4 of Protocol I to the Agreement describes the\nBurundi conflict as “fundamentally political” and as resulting from “a struggle by the\npolitical class to accede to and/or remain in power”. It also identifies impunity, the lack of a\nsound development policy, failure to respect the principles of good governance and human\nrights and the “non-acceptance of peaceful coexistence, diversity and pluralism” as causes\nof violence and insecurity in Burundi.34"},{"id":"a-hrc-39-63-p0076","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"76","seq":77,"section":"IV. Measures to protect civilians and prevent the recurrence of","text":"In order to prevent the recurrence of conflict in Burundi, as analysed in the Arusha\nAgreement, the Commission wishes to highlight a number of measures that fall within its\nmandate. These measures, which are outlined in the recommendations below, concern steps\nto safeguard civil liberties; thoroughly reform the judicial system and, in the meantime,\nconsider establishing an independent mechanism empowered to investigate human rights\nviolations in Burundi and to try the alleged perpetrators; reform the security sector and\nestablish credible civilian oversight mechanisms; give priority to maximizing the allocation\nof resources for improving the population’s enjoyment of economic and social rights; and\ncarry out reforms, particularly in the area of landownership, to safeguard the right to\ndevelopment."},{"id":"a-hrc-39-63-p0077","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"77","seq":78,"section":"V. Conclusions and recommendations","text":"In the light of its investigations, the Commission of Inquiry on Burundi is in a\nposition to conclude that the serious human rights violations documented in the first\nyear of its mandate, including crimes against humanity, have persisted in 2017 and\n2018. Such violations include cases of summary execution, disappearance (including\nenforced disappearance), arbitrary arrest and detention, torture and other cruel,\ninhuman or degrading treatment, sexual violence, and violations of civil liberties such\nas the freedoms of expression, association, assembly and movement (see\nA/HRC/36/54)."},{"id":"a-hrc-39-63-p0078","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"78","seq":79,"section":"V. Conclusions and recommendations","text":"While the State entities that are most often implicated in these violations\ncontinue to be the National Intelligence Service and the police, the Commission is\nconcerned about the growing role being played by the Imbonerakure in a situation in\nwhich recruitment drives among the general public are being used as a means of\nsuppressing all opposition. The Burundian State is responsible for the violations\ncommitted by Imbonerakure in this context."},{"id":"a-hrc-39-63-p0079","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"79","seq":80,"section":"V. Conclusions and recommendations","text":"Perpetrators of violations are operating in an overall climate of impunity. The\nCommission has found that, as matters stand, the Burundian judicial system is both\nunwilling and unable to identify and prosecute those responsible for violations."},{"id":"a-hrc-39-63-p0080","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"80","seq":81,"section":"V. Conclusions and recommendations","text":"The political crisis in Burundi has had a very negative impact on the country’s\neconomic and social situation and has fuelled an increase in poverty. The Government\nhas nonetheless imposed additional taxes and contributions, in contravention of the\nright of all persons to an adequate standard of living, and has failed to devote the\ngreatest possible share of its domestic resources to the realization of economic and\nsocial rights."},{"id":"a-hrc-39-63-p0081","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"81","seq":82,"section":"V. Conclusions and recommendations","text":"In this context, the Commission continues to believe that the Arusha Agreement\nmust remain the basis for any settlement of the crisis in Burundi. The Commission is\nespecially concerned to note that there are no independent international mechanisms\nin Burundi that are in a position to investigate human rights violations."},{"id":"a-hrc-39-63-p0082","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"82","seq":83,"section":"V. Conclusions and recommendations","text":"As the Government of Burundi has not yet implemented the recommendations\nput forward by the Commission in its previous report (A/HRC/36/54), the\nCommission reiterates those recommendations, in particular the ones contained in\nparagraphs 86, 87, 111, 112, 113, 114 and 115."},{"id":"a-hrc-39-63-p0083","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"83","seq":84,"section":"V. Conclusions and recommendations","text":"The Commission recommends that the Human Rights Council extend the\nmandate of the Commission for a period of one year, in view of:\n(a)    The persistence of serious human rights violations and abuses;\n(b)    The lack of action against perpetrators, especially the Imbonerakure,\nsome members of which have continued to be used by State agents for activities\ncontrary to human rights;\n(c)   The lack of other international mechanisms in a position to carry out\nindependent and thorough investigations into the human rights situation in Burundi."},{"id":"a-hrc-39-63-p0084","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"84","seq":85,"section":"V. Conclusions and recommendations","text":"The Commission also recommends that the Human Rights Council submit the\nreport and recommendations of the Commission to the United Nations Security\nCouncil for its consideration."},{"id":"a-hrc-39-63-p0085","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"85","seq":86,"section":"V. Conclusions and recommendations","text":"The Commission recommends that the Government of Burundi take the\nfollowing measures as a matter of priority:\n(a)    Put an immediate end to the gross human rights violations being\ncommitted by agents of the State and Imbonerakure;\n(b)    With the support of the international community, establish ad hoc\nmechanisms with a mandate to investigate human rights violations and to prosecute\nperpetrators of international crimes that are not being investigated by the\nInternational Criminal Court;\n(c)    With the support of the international community, establish an\nindependent body with a mandate to investigate the cases of disappearance reported\nsince April 2015, locate potential mass graves, and exhume and identify the remains;\n(d)   Take measures to ensure that victims of torture and women survivors of\nsexual violence have access to appropriate care, including free access to all sexual and\nreproductive health services and to psychological support;\n(e)  Implement the Guidelines on Combating Sexual Violence and its\nConsequences in Africa adopted by the African Commission on Human and Peoples’\nRights;\n(f)   Control price increases, in particular by reviewing duty and tax\nincreases that are undermining the population’s right to an adequate standard of\nliving and by abolishing contributions that disproportionately affect the poorest\nsectors;\n(g)    Cooperate with international human rights mechanisms, in particular\nby:\n(i)   Resuming the practice of allowing special procedures mandate holders to\nconduct missions to Burundi;\n(ii)  Implementing the recommendations of the universal periodic review,\ntreaty bodies and special procedures, including by establishing a national\nmechanism for reporting and follow-up;\n(h)   Authorize the Office of the United Nations High Commissioner for\nHuman Rights to resume all its activities in Burundi without hindrance;\n(i)    Sign and implement the memorandum of understanding with the\nAfrican Union and permit the full deployment of the 100 human rights observers\nprovided for therein."},{"id":"a-hrc-39-63-p0086","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"86","seq":87,"section":"V. Conclusions and recommendations","text":"For the medium and longer terms, the Commission also recommends that the\nGovernment of Burundi:\n(a)   Amend the Organization Act of 8 March 2018 amending Act No. 01/03 of\n24 January 2013 on the mandate, composition, organization and functioning of the\nNational Communication Council with a view to ensuring the latter’s independence;\n(b)   Ratify the International Convention for the Protection of All Persons\nfrom Enforced Disappearance;\n(c)    Amend the Code of Criminal Procedure to align its provisions with\ninternational standards, in particular the provisions on time limits for police custody\nand on oversight of detention, night-time and warrantless searches, the flagrante\ndelicto procedure and the offence of “undermining the internal security of the State”,\nand provisions that grant de jure impunity to judges and to officers of the criminal\ninvestigation police (police judiciaire);\n(d)    Put an end to arbitrary detention and improve conditions of detention\nby:\n(i)  Implementing the Guidelines on the Conditions of Arrest, Police Custody\nand Pre-Trial Detention in Africa adopted by the African Commission on\nHuman and Peoples’ Rights;\n(ii)   Ensuring that detention is subject to oversight measures for assessing its\nlegality and compatibility with human rights;\n(e)    In the absence of an independent and efficient judicial system, cooperate\nfully with the International Criminal Court in the investigation opened on 25 October\n2017;\n(f)   Undertake an in-depth reform of the judicial system to ensure its\nindependence, impartiality and effectiveness, including by:\n(i)   Implementing the Principles and Guidelines on the Right to a Fair Trial\nand Legal Assistance in Africa adopted by the African Commission on Human\nand Peoples’ Rights;\n(ii)  Publishing the conclusions of the national forum on the justice system\nheld in 2013 and convening a meeting of justice-sector stakeholders and\ninternational partners to discuss follow-up action;\n(iii) Increasing the budget for the justice sector and ensuring that it is\nmanaged autonomously;\n(iv) Raising the pay levels of judges in the ordinary courts and increasing the\nresources and facilities available to them;\n(v)    Computerizing court registries;\n(vi) Reviewing the composition of the Judicial Service Commission to ensure\nthat the majority of its members are appointed by their peers;\n(vii) Reviewing procedures for the appointment, assignment, evaluation and\npromotion of judges to ensure that such procedures are not dependent on the\nexecutive branch;\n(viii) Ensuring strict observance of the principle that judges should have\nsecurity of tenure;\n(ix) Protecting and safeguarding the independence of the judiciary by\nprohibiting any interference in the administration of justice by government\nauthorities, members of the ruling party or members of the defence and\nsecurity forces, and imposing penalties on anyone who influences or seeks to\ninfluence the administration of justice;\n(x)   Developing legal aid programmes for persons belonging to the most\nvulnerable groups;\n(xi) Strengthening victim and witness protection mechanisms and improving\ntheir effectiveness in order to restore public trust and encourage witnesses to\ncome forward without fear for their safety;\n(g)   In consultation with the beneficiaries, establish a reparations\nprogramme for victims of human rights violations, ensuring that material, symbolic,\nindividual and collective reparations are made available regardless of whether or not\nthe perpetrators are convicted;\n(h)    Establish the State fund for victims of torture provided for by law, in\nconformity with general comment No. 4 on the African Charter on Human and\nPeoples’ Rights, adopted by the African Commission on Human and Peoples’ Rights,\nconcerning the right to redress for victims of torture and other cruel, inhuman or\ndegrading punishment or treatment (art. 5);\n(i)    Establish a compensation fund for victims of arbitrary and unlawful\ndetention;\n(j)    Reform the security sector by:\n(i)    Ensuring that outsiders are not involved in defence or security activities;\n(ii)   Clearly defining the roles of the various defence and security forces, in\nparticular the National Intelligence Service;\n(iii) Suspending members of the defence and security forces who are\nsuspected of involvement in human rights violations until the relevant\ninvestigations and judicial proceedings have concluded;\n(iv) Establishing rigorous and transparent selection procedures that include\nvetting mechanisms;\n(v)    Strengthening democratic civilian control over the defence and security\nforces, in particular the National Intelligence Service;\n(k)     Meet its international obligations to respect, protect and fulfil economic\nand social rights by:\n(i)    Developing and implementing State budgets in such a way as to\nmaximize the use of available resources to ensure that the human rights of the\nsectors impoverished by the political crisis are respected, in particular the\nrights to food, water and health care, and to develop indicators disaggregated\nby factors such as gender in order to better inform its policies;\n(ii)   In consultation with population groups working in the agricultural\nsector, including women, undertaking reforms with the aim of better protecting\nwomen’s rights and making better use of land for agriculture, and developing\nemployment opportunities outside the agricultural sector;\n(iii) Taking a rights-based approach to the settlement of land conflicts,\nincluding those involving persons who fled Burundi either before or after 2015;\n(iv) Ending the inclusion of any political considerations in hiring processes\nfor the civil service, State enterprises and public-private enterprises."},{"id":"a-hrc-39-63-p0087","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"87","seq":88,"section":"V. Conclusions and recommendations","text":"The Commission recommends that political parties and armed opposition\ngroups refrain from engaging in any attacks on Burundian territory and from any\nspeech calling for violence, and that they join the effort to find a lasting solution to the\npolitical crisis."},{"id":"a-hrc-39-63-p0088","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"88","seq":89,"section":"V. Conclusions and recommendations","text":"The Commission recommends that the African Union, in its efforts to find a\nlasting solution to the crisis in Burundi, give priority to respect for human rights and\nthe rejection of impunity, as provided for in its Constitutive Act."},{"id":"a-hrc-39-63-p0089","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"89","seq":90,"section":"V. Conclusions and recommendations","text":"The Commission recommends that the technical and financial partners of\nBurundi:\n(a)    Suspend, or maintain the suspension of, any direct budget support to the\nGovernment until such time as priority is given to the allocation of domestic resources\nfor the fulfilment of the Sustainable Development Goals and the economic and social\nrights of the population, and effective measures are taken against corruption;\n(b)    Ensure that grants and financing provided to the Government are\nearmarked for projects to meet the population’s needs, and ensure that such funding\nis managed effectively and transparently;\n(c)     Regularly evaluate the impact of financial sanctions on the people of\nBurundi."},{"id":"a-hrc-39-63-p0090","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"90","seq":91,"section":"V. Conclusions and recommendations","text":"The Commission recommends that the guarantors of the Arusha Agreement, in\ntheir capacity as committed proponents of a lasting peace in Burundi, continue to seek\na durable solution to the political and human rights crisis that will preserve and\nsafeguard the achievements of the Arusha Agreement."},{"id":"a-hrc-39-63-p0001-a1","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"1","seq":92,"section":"Annex II","text":"Note verbale sent to the Permanent Mission of Burundi on 10 October 2017","annex":1},{"id":"a-hrc-39-63-p0002-a1","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"2","seq":93,"section":"Annex II","text":"Note verbale sent to the Permanent Mission of Burundi on 30 November 2017,\ntransmitting a letter addressed to the Minister for Foreign Affairs and International\nCooperation of Burundi","annex":1},{"id":"a-hrc-39-63-p0003-a1","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"3","seq":94,"section":"Annex II","text":"Note verbale sent to the Permanent Mission of Burundi on 11 January 2018","annex":1},{"id":"a-hrc-39-63-p0004-a1","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"4","seq":95,"section":"Annex II","text":"Letter sent to the Permanent Mission of Burundi on 2 March 2018","annex":1},{"id":"a-hrc-39-63-p0005-a1","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"5","seq":96,"section":"Annex II","text":"Note verbale sent to the Permanent Mission of Burundi on 13 March 2018","annex":1},{"id":"a-hrc-39-63-p0006-a1","rec_id":"recLrmWfYkW5mfR5k","symbol":"A/HRC/39/63","n":"6","seq":97,"section":"Annex II","text":"Note verbale sent to the Permanent Mission of Burundi on 26 June 2018","annex":1},{"id":"a-hrc-39-crp-1-u0000","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":0,"section":"V. Adequate measures to protect the civilian population and prevent the recurrence of conflicts 225","text":"Acronyms\nAPI        Support for the Protection of Institutions\nAPRODH     Association pour la protection des droits de l’homme and des\npersonnes détenues\nAU         African Union\nBAE        Anti-riot Brigade\nBGC        Bataillon de génie de combat\nBINUB      United Nations Integrated Office in Burundi\nBSPI       Special Brigade for the Protection of Institutions\nACHPR      African Charter on Huuman and People’s Rights\nEAC        East African Community\nCAT        Convention against Torture and Other Cruel, Inhuman or\nDegrading Treatment or Punishment\nCRC        Convention on the Rights of the Child\nCRPD       Convention on the Rights of Persons with Disabilities\nCDAW       Convention on the Elimination of All Forms of Discrimination\nagainst Women\nCEPGL      Economic Community of the Great Lakes Countries\nCERD       Convention on the Elimination of all Forms of Racial\nDiscrimination.\nICGLR      International Conference on the Great Lakes Region\nEACJ       East African Court of Justice\nCNARED     Conseil national pour le respect de l’accord d’Arusha and la\nrestauration d’un Etat de droit au Burundi\nCNC        National Communication Council\nCNDD-FDD   Conseil national pour la défense de la démocratie-Forces de\ndéfense de la démocratie\nCNDI       Commission nationale pour le dialogue inter-Burundais\nCNIDH      Independent National Commission for Human Rights\nICC        International Criminal Court\nEINUB      United Nations Independent Investigation on Burundi\nEU         European Union\nFAB        Burundian Armed Forces\nFDNB       National Defense Forces of Burundi\nFOREBU     Forces républicaines du Burundi\nFNL        Forces nationales de libération\nGMIR       Groupe mobile d’intervention rapide\nOHCHR      Office of the United Nations High-Commissioner for human\nrights\nMENUB      United Nations Mission in Burundi\nMSD        Mouvement pour la solidarité and le développement","unnumbered":true},{"id":"a-hrc-39-crp-1-u0001","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":1,"section":"V. Adequate measures to protect the civilian population and prevent the recurrence of conflicts 225","text":"NGO               Non-Governmental Organisation\nICCPR             International Covenant on Civil and Political Rights\nICESCR            International Covenant on Economic, Social and Cultural\nRights\nPNB               Burundian National Police\nRED-Tabara        Résistance pour un état de droit - Tabara\nSNR               National Intelligence Service\nUPD-Zigamibanga Union pour la paix and le développement-Zigamibanga","unnumbered":true},{"id":"a-hrc-39-crp-1-u0002","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":2,"section":"III. Human rights situation","text":"216. This section covers results of investigations conducted by the Commission since the\nrenewal of its mandate in Septembre 2017. It should be read as a continuation of the first\nreport of the Commission which focused mainly on the human rigthts violations in 2015\nand 2016. The present part covers the human rights violations in 2017 and 2018, with the\nexception of the chapter on economic and social rights which looks at the evolution of the\nsituation in this area since 2015, an aspect that the Commission did not have sufficient time\nto study in detail during its first mandate. The chapter on the dysfunctions in the judicial\nsystem provides an in-depth study of the judicial system in Burundi, whose problems date\nback to before 2015, but have since worsened.","unnumbered":true},{"id":"a-hrc-39-crp-1-u0003","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":3,"section":"A. Main trends in 2017 and 2018","text":"217. The Commission found that the main human rights violations documented since the\npolitical crisis began in April 2015, namely cases of summary execution, disappearance\nand enforced disappearance, arbitrary arrest and detention, torture and ill-treatment, and\nsexual violence,1 have persisted in 2017 and 2018. As in the past, most of the victims of\nthese violations are opponents of the Government and/or of the ruling party (the Conseil\nnational pour la défense de la démocratie-Forces pour la défense de la démocratie – CNDD-\nFDD) or persons who are perceived as such, including members of opposition political\nparties (particularly the Forces nationales de libération, led by Agathon Rwasa, and the\nMouvement pour la solidarité et la démocratie); supporters of armed opposition groups;\nBurundians trying to flee the country and therefore suspected of joining such groups; or\njournalists or members of civil society organisations.\n218. The violations have had lasting psychological and physical effects on the victims.\nThose that have been committed primarily against men, including arbitrary detention,\nenforced disappearance and summary execution, have had multiple consequences for the\nvictims’ families. In the words of a widow interviewed by the Commission: “A household\nwithout a man is very vulnerable”.2 Several women gave account of violence, including\nsexual violence,3 which at times did not spare their children, in that the latter either endured\nor witnessed the violence. Often the spouses or other members of the family were\nthreatened, including death threats or threats of harassment and attacks targeting their\nhousehold. The resulting fear and trauma were compounded by the anguish on the fate of\ntheir relatives, especially in cases of enforced disappearance, as well as in cases of spouses\nwho found themselves as head of household, the challenge of providing for their family’s\nneeds. In addition to the impact of losing a spouse, wives often face harassment, threats or\nviolence on the part of the alleged perpetrators and are unable to meet the basic needs of\ntheir families.\n219. Before and during the campaign to amend the Constitution, CNDD-FDD and its\nyouth league, the Imbonerakure, stepped up their efforts to recruit members from among\nthe general public. These efforts focused in particular on Burundians — even those who\nwere apolitical — who had refused or been unable to register to vote and on those who had\nnot paid their contribution for the 2020 elections. These trends are further limiting freedom\nof expression in a country whose main independent media outlets and human rights\norganisations have been banned. Those that continue to operate in the country have been\nsubjected to restrictions, threats and persecution.4\n220. This climate of disregard for human rights continues to be fomented by repeated\ninstances in which hatred and violence have been advocated by the authorities, including\nthe Head of State and members of CNDD-FDD,5 and by an overall context of impunity","unnumbered":true},{"id":"a-hrc-39-crp-1-u0004","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":4,"section":"A. Main trends in 2017 and 2018","text":"exacerbated by the lack of an independent and properly functioning judicial system, as well\nas a lack of public trust in the latter.6 This environment has also had a direct impact on the\nenjoyment of economic and social rights, given that a growing share of the population has\nunmet needs, primarily in the areas of health, nutrition, water, hygiene and sanitation, as a\nresult of increased financial pressure from the authorities and CNDD-FDD. Whereas\nBurundi was formerly a developing country, it is now once again in a state of humanitarian\nemergency. In some cases, Burundians are deprived of their rights for political reasons,\nsuch as the right to education.7","unnumbered":true},{"id":"a-hrc-39-crp-1-p0001","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"1","seq":5,"section":"B. Responsability","text":"Responsability of the Burundian State\n221. Under international human rights law, States have a threefold obligation to respect,\nprotect and fulfil human rights, including both civil and political rights and economic and\nsocial rights.\n(a)       Obligation to respect\n222. The obligation to respect human rights requires States, their agents and persons\nacting under their control to refrain from actively violating the rights of individuals.8\n(i)       Responsibility of the State for the conduct of its organs\n223. As in its previous report,9 the Commission found that members of the National\nIntelligence Service (SNR) and the police, including high-ranking officials, were involved\nin the commission of a large number of human rights violations in 2017 and 2018 in\nBurundi.10 These violations include extrajudicial executions, forced disappearance,\narbitrary arrests and detentions, torture and other cruel, inhumane and degrading treatment\nand sexual violence.11\n224. The Commission continued to receive information on the allegations of human\nrights violations perpetrated by high ranking officials of the SNR. Generally, SNR agents\nremain, whatever their hierarchical ranking, amongst the main perpetrators of the human\nrights violations in Burundi, specifically of extrajudicial executions, enforced\ndisappearances, arbitrary arrests and detentions and torture. They are still an essential part\nof the repressive apparatus, from Bujumbura to the local level, which was setup from April\n2015 with the aim of silencing every voice contrary to the Government and/or the CNDD-\nFDD.\n225. Police agents also continue to play an active role in the recruitment of the population\nand the persecution of political opponents to the Governement and CNDD-FDD, or persons\nperceived as such. Unlike 2015 and 2016, the information collected by the Commission\nduring the second term of its mandate did not make it possible to identify the police units\nthat are more active than others in the commission of human rights violations.12\n226. The Commission has, however, received very few information implicating members\nof the army in the Commission of human rights violations in 2017 and 2018, contrary to\nprevious years. Some witnesses continued neverthekess to stress the role of some high-\nranking officials and army officers in the repressive appararatus and who, in that context,\nmaintain close ties with Imbonerakure.13\n227. Administrative authorities have also committed or given orders to commit human\nrights violations, in particular arbitrary arrest and detention and ill treatment.\n228. In addition, the Government has imposed additional taxes and contributions, in\nparticular for the 2020 elections,14 and has thereby exacerbated poverty, and in doing so,\nviolated the obligation of the State to take appropriate measures to ensure that all persons\nhave an adequate standard of living for themselves and their families.15 Discrimination by\nState agents based on whether or not individuals belong to CNDD-FDD has had an impact\non specific rights, such as the right to education, and on employment in the civil service\nand in public and public-private enterprises.16\n(ii)        Responsibility of the State for the conduct of the Imbonerakure\n229. The information gathered, in particular from former members of the Imbonerakure\nand CNDD-FDD, confirms that the role of the Imbonerakure is growing in an overall\ncontext of recruitment among the general public and persecution of political opponents and\npersons perceived as such. The referendum campaign has given rise to numerous violations\nby Imbonerakure, who, acting either alone or in the presence of law enforcement officers,\nconducted checks to verify whether persons of voting age hadregistered and whether they\nhad paid their contributions for the 2020 elections.17 These checks have often served as a\npretext for various human rights violations and abuses, including extortion.18 Forced\nrecruitment into the Imbonerakure and/or CNDD-FDD has also reportedly been stepped up\ntargeting members of opposition political parties or persons with no political affiliation.\nThey also gave rise to violations, including threats, arbitrary arrest, torture and ill treatment,\nsummary execution and kidnapping.19\n230. The increase in these activities and the wider latitude being left to the Imbonerakure\ndemonstrate their collusion with formal and informal structures of State repression. The\nfact that Imbonerakure are members of the “mixed committees for human security”, created\nby decree in 2014,20 along with representatives of the administration and the police,\nindicates that they are acknowledged to play a role in the security apparatus.21 With the\nconsent of local governments, Imbonerakure have been used as auxiliaries or substitutes\nfor law enforcement in the country’s interior, where such forces have a reduced presence.22\nSome testimonies have even indicated that during some police operations against\nopponents, Imbonerkure had taken cpmmand over the police.23 Few testimonies also\nindicate that in a few places, Imbonerakure carried out some judicial functions, such as\nsettling conflicts or deciding on a person’s culpability even when it is in contradiction with\nthe judge’s decision.24\n231. The Commission is thus in a position to establish the responsibility of the Burundian\nState for wrongful acts committed by Imbonerakure in four contexts: when their conduct is\nacknowledged and adopted by agents of the State,25 when they act on the instructions or\nunder the direction of the latter,26 when they act in “complete dependence” on or under the\n“effective control” of such agents.\n232. Imbonerakure have continued to make arrests on their own initiative, often with\nviolence, and to hand over the persons apprehended to the police or the National\nIntelligence Service. The detention of such persons by law enforcement 27 shows that the\nlatter have adopted the conduct of such Imbonerakure. This acknowledgement is also\ndemonstrated by the fact that no measures have been taken by the State of Burundi or its\nreprestatives to put a stop to such conduct that they are fully aware of or have witnessed.28\n233. Imbonerakure have continued to act on the orders of officials, including high-\nranking officials, of the National Intelligence Service, the police and the Office of the\nPresident as well as local administrative authorities.29 Some have taken part in law\nenforcement operations or operations against opponents,30 acting alongside police or\nintelligence officers and in some cases wearing the same uniforms or carrying the same\nweapons as the defence and security forces. Such conduct by Imbonerakure has even taken\nplace in prisons, such as the Mpimba prison in Bujumbura, and in police holding cells.31\nSome incarcerated Imbonerakure assume the functions of “capita généraux” and, as such,\nare in charge of the security within the prisons.32\n234. The growing role and freedom of action of the Imbonerakure are entirely dependent\non the discretion of State power structures and on the impunity accorded by the latter. To\ndemonstrate the “complete dependence” of an organization on the State, international\njurisprudence nonetheless requires the existence of a particularly great degree of control,\nas shown, for example, by the provision of considerable military and financial support and\nsystematic alignment with State policy.33 In this connection, witness statements confirm\nthat a group of “demobilized” soldiers, subsequently joined by Imbonerakure, was created\nin 2006 and has since been trained, armed and remunerated by the former Administrator-\nGeneral of the National Intelligence Service.34 Following the killing of that official in 2015,\nthe group was supplemented by new members selected and used by officials of the National\nIntelligence Service, the police and the army to conduct operations, including summary\nexecutions and targeted disappearances.35 Witness accounts also mentioned remunerations\nthat were received as salaries or paid upon completion of the tasks.36 On the basis of this\ninformation, the Commission is of the view that the group is acting in complete dependence\non the Burundian State.\n235. The Commission remains convinced that the Imbonerakure often operate under the\n“effective control” of the Burundian State. International jurisprudence requires that such\ncontrol be demonstrated in each case through the planning and organisation of operations,\nthe issuance of orders or the provision of equipment by the State.37 In relation to the first\nelement, the Commission received information, including from former State agents and\nImbonerakure, on meetings at the local level between SNR, police and ruling party officials\nand/or Imbonerakure, during which persons to be arrested or disappeared38 are identified –\nmainly political opponents or persons likely to oppose the Government or CNDD-FDD.\nSome witnesses mentioned the existence of census aimed at identifying opponents ahead\nof the referendum and the 2020 elections,39 and even of an operation previously known as\n“Safisha” (i.e. “to clean” in Kirundi) and renamed today « Gutakara » (i.e. “to be lost” or\n“to kill”), which is aimed at eliminating opponents.40 As mentioned above,41 Imbonerakure\nacted, in several cases, on the orders and supervision of State agents. In addition, witness\naccounts mentioned the distribution of weapons and/or military equipment to\nImbonerakure42 up until 2018. Several witnesses also highlighted the fact that\nImbonerakure wear military attire and boots43 and sometimes carry firearms44. Some\nImbonerakure also received phones, SIM cards, and phone credits in order to inform\nCNDD-FDD and SNR officials on the activities of the opponents and to identify amongst\nthem those that should be apprehended.45 WhatsApp groups continued to be used to that\nend46. These various statements suggest a level of control exercised by the Burundian State\non certain Imbonerakure that could qualify as “effective control”.\n236. However, to date, international judges have issued rulings only in cases involving\nentities acting outside the territory of the State in question.47 In such cases, the State must\nhave exercised direct control in order to be held accountable. The Imbonerakure, however,\nare committing wrongful acts on Burundian territory. The State thus has more means at its\ndisposal, in particular of a legislative, judicial and financial nature, for putting an end to\ntheir activities or, on the contrary, for promoting them through its action or deliberate\ninaction. It is therefore in a position to exercise overall effective control over the\nImbonerakure. Given that the Imbonerakure have been involved in a wide range of\nactivities, including some within the purview of the Government; have in a number of cases\nacted autonomously but with a freedom of action afforded by the authorities; and have\ncontinued to enjoy near-total impunity, the Commission is of the view that the Burundian\nState is responsible for the wrongful acts committed by the Imbonerakure, since it exercises\noverall effective control. Therefore, under international law, the Burundian State may be\nheld accountable for all human rights violations attributable to the Imbonerakure.\n237. From that perspective, it should be noted that the Commission received information\nindicating that Imbonerakure were detained in state prisons, not because of exactions they\ncommitted, nor as a result of a judicial process, but as an internal disciplinary sanction.48\nThis private use of cells subject to the State authority shows not only the collusion that\nexists today between Imbonerakure and the Burundian State, but also that sanctions are\npossible against Imbonerakure. In that regard, the Burundian State; through its agents;\ncould very well arrest and detain Imbonerakure who commit human rights violations, in the\nsame way that it allows Imbonerakure to use cells to sanction some of their members by\ndepriving them a freedom. Considering that information, the impunity that Imbonerakure\nenjoy today in Burundi, appear as anything but fortuitous. In addition, as noted, an\nincreasingly active role has been given to Imbonerakure, including new tasks entrusted to\nthem by State agents.\n(b)        Obligation to protect\n238. Under international human rights law, the State has a duty to protect the human\nrights of persons under its jurisdiction, in particular when it knows or should have known\nof violations or abuses committed by third parties.49 By allowing its agents and/or\nImbonerakure who are responsible for such acts to go unpunished, including by not\nconducting investigations or initiating proceedings against them, the Burundian State is\nfailing to meet its obligation to protect. By not taking action to combat impunity and not\nundertaking a thorough reform of its judicial system,50 the Burundian State is encouraging\nthe repeated commission of human rights violations and abuses.\n(c)        Obligation to fulfill\n239. The State is also required to implement human rights. This obligation is stipulated\nin article 2 (2) of the International Covenant on Civil and Political Rights which provides\nthat “where not already provided for by existing legislative or other measures, each State\nparty to the present Covenant undertakes to take the necessary steps, in accordance with its\nconstitutional processes and with the provisions of the present Covenant, to adopt such laws\nor other measures as may be necessary to give effect to the rights recognized in the present\nCovenant”. From this perspective, the Commission is concerned by the fact that some\nrecently adopted laws in Burundi do not allow the full realisation of human rights, namely\nthe new Criminal Procedure Code promulagated in May 2018 which revised the old Code\nwhich also contained problematic provisions.51\n240. The International Covenant on Economic, Social and Cultural Rights requires State\nparties to take steps to the maximum of their available resources with a view to achieving\nprogressively the full realization of the rights recognized therein.52 The fact that\ninternational assistance to Burundi has decreased since 2015 as a result of violations of civil\nand political rights does not relieve the Burundian State of its obligation to devote the\nmaximum of its available resources to the realization of economic and social rights. Yet,\nthe Commission has noted that the country’s domestic resources are oriented more towards\ndefence and security expenditures and that there are many tax exemptions.53 The\nCommission has also received information on the misappropriation and grabbing of public\nproperty by senior officials in a country that is experiencing a humanitarian crisis and in\nwhich much of the population does not fully enjoy the right to food.54"},{"id":"a-hrc-39-crp-1-p0002","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"2","seq":6,"section":"B. Responsability","text":"Responsibility of armed groups and opposition political parties\n241. The existence of armed groups at the border continues to pose a threat to the\ncountry’s civilian population. To the Commission’s knowledge, none of these groups\nclaimed responsibility for an attack on Burundian soil in 2017 or 2018. Because the\nCommission has not had access to victims and the Government has repeatedly refused to\nhand over evidence, the Commission has been unable to corroborate the information it has\nreceived on the involvement of armed groups in human rights abuses in Burundi since 2015.\nIn particular, it has not been able to identify the group responsible for the killing of at least\n24 persons on 11 May 2018 in the commune of Buganda, province of Cibitoke. The findings\nof the investigation carried out by the Burundian authorities have not yet been released.\n242. The lack of acces of the Commission to the victims of human rights abuses by armed\nopposition groups is not due to the impossibility in which the the Commission finds itself\nin accessing the Burundian territory, but more to the fact that the victims are, for the most\npart, close to the authorities who hold functions in the State apparatus or within CNDD-\nFDD. Given the categorical refusal of the Government to cooperate with the Commission,\nthese victims do not seek to enter into contact or to share information with the latter.\n243. Furthermore, the Commission has detected certain calls for armed struggle or that\ncould amount for incitement to hatred and violence by leaders of opposition political.55"},{"id":"a-hrc-39-crp-1-u0007","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":7,"section":"1. Right to life","text":"(a)        Summary execution and other arbitrary deprivation of life\n244. In its previous report,56 the Commission noted that a large number of arbitrary\nexecutions related to the political crisis was committed by diverse components of security\nand defense forces, namely SNR and police agents, most specifically specialised units such\nas the Appui aux institutions (API) and the Anti-riot Brigade (BAE). Elements of the Army\nfrom the Combat Engineering Bataillon (camp Muzinda) had also been identified as\nresponsable for violations of the right to life. In several cases, these State sgents acted in\nconjunction with Imbonerakure.\n245. The Commission also observed the numerous death cases resulting from the\nindiscriminate and excessive use of lethal force during the operations of repressing the\ndemonstrations against President Nkurunziza’s third term and during the security\noperations carried out in some neighborhoods in Bujumbura during the second half of 2015.\nThe attempted coup d’État of 13 May 2015 and the attacks on the military facilities in\nBujumbura and its environs on 11 Decembre 2015 also gave rise to similar executions.\nTargeted killings by State agents of primarily members of opposition political parties,\nhuman right defenders or their relatives, as well as members of the former Burundian\nArmed Forces (“ex-FAB”) had also been documented, as well as cases of death in\ndetention.\n246. The Commission had noted that numerous dead bodies had been discovered in\nseveral provinces, presenting visible signs of homicide, buried without being identified and\nwithout conducting any investigation. The Commission had also received related\nallegations on the existense of mass graves used by the authorities to bury bodies of persons\nkilled following the attacks of 11 Decembre 2015.\n247. Finally, the Commission had considered that the executions of the persons who\nopposed the Gouvernement by Imbonerakure acting on their own accord and outside of any\ncontrol by State agents, constituted violations of the right to life. Furthermore, the\nCommission had also received information on several murders or assassinations – or\nattempted murders and assassinations - targeting persons perceived as members of the\nopposition by unidentified individuals; however the circumstances in which they occurred\ngave reasonable grounds to fear that State agents had been involved. Members of the\nGovernment or persons with connections to it and/or CNDD-FDD, as well as military and\npolice personnel, SNR agents and Imbonerakure had also been assassinated or targets of\nattempted assassinations, but the Commission has not been able to identify the perpetrators.\n248. Since 2017, the Commission has not received information on the violations or\nattacks on the right to life on a large scale like in 2015 and 2016, aside the massacre of at","unnumbered":true},{"id":"a-hrc-39-crp-1-u0008","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":8,"section":"1. Right to life","text":"least 24 persons in the night of the 11 to 12 May 2018 in Buganda commune in Cibitoke\nprovince.57 It did not get information that political personalities close to the Government\nand/or the CNDD-FDD, or leaders of opposition political parties had been assassinated.\n249. However, the Commission notes that summary executions of opposition members\npersisted but in a concealed manner, which explains the greater difficulties encountered in\ndocumenting individual cases of summary execution compared to the first term of its\nmandate.58 Furthermore, the Commission received credible information including from\nformer members of the State repressive apparatus, CNDD-FDD and defence and security\nforces, indicating that such executions have continued. Lists of persons to eliminate for\npolitical reasons have been drawn by officials of CNDD-FDD and defence and security\nforces, notably SNR.59 Witness accounts of murders or assassinations of persons in\ntroubling circumstances, as well as the regular discovery of bodies bearing signs of violent\ndeath, combined with the few investigations that were opened by the authorities to identify\nthe victims or find and prosecute the perpetrators of those crimes, provides reasonable\ngrounds to the Commission to believe that summary executions remain a widespread\npractice in Burundi.60","unnumbered":true},{"id":"a-hrc-39-crp-1-u0009","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":9,"section":"1. Right to life","text":"(i)         Main victims\n250. Similar to other human rights violations during the period covered by the present\nreport, the main victims executed or killed under conditions that are likely to constitute\ncases of summary execution were principally men perceived as members or supporters of\nopposition political parties, namely FNL61 and MSD62, as well as individuals who had\nrefused to join CNDD-FDD or to adhere to its politics, to register on the electrol lists ahead\nof the referendum or to pay contributions.63\n251. The Commission also received witness accounts, including from former members\nof Imbonerakure, indicating that some members of the youth league of the ruling party or\nother persons involved in human rights violations were killed to prevent them from\nspeaking of their past actions, or because they were considered as deviating from the party\nline.64","unnumbered":true},{"id":"a-hrc-39-crp-1-u0010","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":10,"section":"1. Right to life","text":"(ii)        Main perpetrators\n252. SNR agents remain amongst the main State agents responsible for summary\nexecutions in 2017 and 2018.65 They often acted in collaboration with police officers. In\nseveral cases, Imbonerakure collaborated with elements of the defence and security forces\nin the commission of summary executions.66 A witness told the Commission about the\nconduct of a joint operation between Imbonerakure and a military:\n“[X] was assassinated on […] November 2017 […] It is [...], the head of\nImbonerakure at [W] who killed him in collaboration with [...], a military […] The\ntwo came in the evening to [X], around 21 hours. They came in a Toyota Prado […]\nthey shot him at his home […] the perpetrators came to his home and called him by\nhis name”.67","unnumbered":true},{"id":"a-hrc-39-crp-1-u0011","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":11,"section":"1. Right to life","text":"253. The Commission also noted the increased involvement of Imbonerakure acting\nalone to identify the persons to kill and to summarily execute them.68 A witness recounted\nthe murder of a parent by Imbonerakure in the following words:\n“[A parent] […] who was a member of MSD was shot by unidentified Imbonerakure\n[…] [in] 2017. It was in the evening around 20 heures […] [He] was killed as he\nwas buying telephone credits […] Imbonerakure […] were on foot […] they came\nclose to him and shot him”.69\n254. Witness accounts also mention the possible utilisation of detainees for missions\noutside the prisons to execute persons who are hostile to the leadership or other targeted\npersons.70 The capita généraux would help with the identification of the most capable\ndetainees for this type of mission and the SNR would inform the police and military agents\non duty around the areas of operation so that they do not intervene. A witness stated:\n“To execute [X], it was prisoners who were sent […] It was a joint operation. [X]\nwas killed the same day as [Y] He was in a bar. They called him. He came out and\nthey killed him […] In principle, the prisoners move around with the help of\nImbonerakure. The police and the army provide the necessary cover for the\nexecution of the operation. In the specific case [of X] – and I repeat – prisoners\nwere the executors. These prisoners are not nobodies, they have more experience\nthan Imbonerakure. They are special prisonners: demobilised and former\ncombattants”.71\n(iii)        Operating mode\n255. Witnesses mentionned that the victims were mainly killed by being stabbed, targeted\nwith a grenade, beaten to death, by gunshot or by strangulation.72 In some cases, the targeted\npersons were killed in their home and their body left onsite or in the vicinity.73 In other\ncases, the persons were executed after being taken far away from their home, sometimes to\nanother province, and some corpses continued to be thrown in the rivers after being weighed\ndown with stones or to be buried in common graves (fosses communes), in particular in\nforests74. A witness said:\n“Imbonerakure attached […] men […] They were attached by the elbows behind\nthe back, feet forward. Imbonerakure beat them seriously. One of them, agonising,\nwas immediately thrown in the Rusizi River. Another, who was requested to confess,\nended up saying that he was going to say everything. He was nonetheless also\nthrown in the Rusizi River”.75\n256. Unidentified lifeless bodies continue to be found throughout the country and to be\nburied with no regard to legal formalities such as the opening of an independent\ninvestigation to establish the victim’s identity and the circumstances of death, and to look\nfor the possible culprits. This reinforces the general impunity enjoyed by the perpetrators\nof human rights violations and is in itself a violation of the State to protect the right to life\nand to offer an effective remedy to the victims and their families.76\n257. The Commission also received information indicating that SNR agents executed\npersons detained in secret detention facilities, such as a house situated in Kinindo\n(Bujumbura Mairie).77 It was reported that men might have been killed there in December\n2016 by SNR agents. After these alleged murders, witnesses had observed blood flowing","unnumbered":true},{"id":"a-hrc-39-crp-1-u0012","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":12,"section":"1. Right to life","text":"outside that house and a video showing the suspicious blood flows circulated on social\nmedia. The police spokesperson has nonetheless rejected these facts in a tweet.78 Several\nsources confirmed to the Commission that it was human blood that flowed from the house\nthrough a wastewater drainage.79","unnumbered":true},{"id":"a-hrc-39-crp-1-u0013","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":13,"section":"1. Right to life","text":"(b)        Enforced disappearances\n258. In its last report,80 the Commission highlighted a context generally conducive to\nforced disappearances since 2015, especially in view of the conditions in which arrests were\nconducted by Burundian law enforcement bodies. The Commission distinguished between\nthe cases for which it had “reasonable grounds to believe” they amounted to enforced\ndisappearance and those ones for which it only had “reasonable grounds to fear” that it\nmight be the case.\n259. In the first category, the Commission had received information supporting the\nconclusion of the existence of elements included in the definition of enforced disappearance\nin Article 2 of the International Convention for the Protection of All Persons from Enforced\nDisappearance, namely: any other form of deprivation of liberty by agents of the State or\nby persons or groups of persons acting with the authorization, support or acquiescence of\nthe State, followed by a refusal to acknowledge the deprivation of liberty or by concealment\nof the fate or whereabouts of the missing person. From that perspective, the Commission\nconsidered that Augustin Hatungimana, Bernard Baranjoreje, Hugo Haramategeko, Jean\nBigirimana and Pacifique Birikumana had been victims of enforced disappearances\nbetween 2015 and 2017.\n260. In other cases – notably those of Innocent Ndayikeza, Albert Dushime, Marie-\nClaudette Kwizera, Savin Nahindayi and Oscar Ntasano – the Commission had not been\nable to determine that all elements of the definition of enforced disappearance were met,\nbut that nonetheless, it had reasonable grounds to fear that the targeted persons had been\nvictims of enforced disappearances because of their specific profile, the operating mode,\nthe conditions and the context in which their disappearance took place, namely the overall\ncontext of no compliance to judicial guarantees during arrest and detention. Nevertheless,\nit should be noted that, since its last report, the Commission has collected new information\non the case of Savin Nahindavyi,81 which give reasonable ground to believe that the latter\nwas a victim of enforced disappearance. Accordingly, Savin Nahindavyi was detained\nduring several days in a secret place before being killed. A SNR officer subsequently got\nrid of his body in Bwiza (Bujumbura Mairie) with the help of local elected officials.82\n261. During the first term of its mandate, the Commission had collected information on\ncases of disappearance for which it had no sufficient elements to be in a position to find\nthat there was reasonable ground to believe or to fear that they constituted cases of enforced\ndisappearances, including some cases of abduction by Imbonerakure in which the\nCommission was not able to conclude that they had been committed with the permission,\nsupport or approval of the Burundian authorities.\n262. In addition, the Commission had received information indicating that relatives of\nthe missing persons were subjected to pressure, intimidation or threats by police or SNR\nofficers or Imbonerakure, and in some cases, sums of money were requested by police and\nSNR officers or persons posing as such, in exchange for information on the fate of the\nmissing persons.\n263. The Commission notes that since the renewal of its mandate in September 2017, the\nphenomenon of arbitrary arrest and detention, including in secret facilities,83 the","unnumbered":true},{"id":"a-hrc-39-crp-1-u0014","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":14,"section":"1. Right to life","text":"concealment of bodies and the impunity prevailing in the country84 have continued to create\na climate of secrecy that is conducive to cases of enforced disappearance. Several witnesses\nand relatives of victims of enforced disappearance have confirmed that many persons\nabducted or arrested by law enforcement agents were later executed 85 and, in some cases,\ntheir bodies were never found.\n264. The widespread climate of fear and the restrictions imposed on independent\njournalists and civil society organisations further exacerbate the opacity that is conducive\nto enforced disappearances. A witness who fled the country in 2018 explained:\n“When families were able to report, investigations into the disappearances were\ncarried out. But now, it is simply impossible. The society has become muzzled by\nfear […]. Today they only say that a person has been kidnapped, but they do not say\nby whom nor how. Even in the case of Léopold Habarugira.86 He was taken in broad\ndaylight as people were passing by in the neighbourhood. But no one dares talk\nabout it; they are afraid”.87\n265. The Commission used the same approach adopted in its previous report where it\nmade a distinction between cases in which it has “reasonable grounds to believe” that they\nare enforced disappearance and those in which it only has “reasonable grounds to fear” this\nmight be the case. The Commission also collected information on cases of disappearance\nfor which sufficient details were not available for them to be included in either category.\nThese include disappearances following arrests by police or SNR agents or abductions\ncommitted by Imbonerakure.","unnumbered":true},{"id":"a-hrc-39-crp-1-u0015","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":15,"section":"1. Right to life","text":"(i)        Cases where there is reasonable ground to believe that they are enforced\ndisappearances\n266. The Commission collected consistent information on disappearances that can be\nqualified as « enforced» as they happened after the victims, for the most part members of\nopposition political parties, were apprehended and detained by police and SNR agents.\nLéopold Habarugira\n267. According to witness accounts collected by the Commission,88 on 12 septembre\n2017, early morning, in Gihosha neighborhood in Bujumbura Mairie, Léopold Habarugira,\nan official of the opposition parti Union pour la paix and le développement (UPD)-\nZigamibanga89, was abudcted as he was taking a walk. A car approached him and SNR as\nwell as police agents, forced him into the car and took him to an unknown destination. No\nwarrant was shown to the victim at the time of his arrest.\n268. Léopold Habarugira’s relatives carried out searches, both in various detention\ncentres as well as hospitals in the country, in vain. Before his disappearance, the victim had\nreceived information indicating that he was in danger. In 2016, he had narrowly escaped an\nassassination attempt by individuals on a motorbike.\n269. According to information collected by the Commission, Léopold Habarugira was\nallegedly killed on the day of his arrest by SNR agents, in Gatumba, Bujumbura province,\nand he was buried in Ruyigi province.\n270. Two days after the disappearance of Léopold Habarugira, the police spokesperson\nannounced that the police had not received any complaint on the matter,90 which is contrary\nto information collected by the Commission that indicate that a complaint was indeed made\nat the judicial police in Bujumbura, although the complaint was not followed through.","unnumbered":true},{"id":"a-hrc-39-crp-1-u0016","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":16,"section":"1. Right to life","text":"271. Léopold Habarugira had allegedly a land conflict with the political party CNDD-\nFDD, as well as disputes with government entities on a delivery contract for prefabricated\nhomes.\nBukuru and Butoyi Shabani\n272. According to testimonies collected by the Commission,91 in November 2016, the\nShabani twins, Bukuru and Butoyi were arrested and taken to a private home guarded by\npolice (PNB) agents located in Kinindo, Bujumbura Mairie. They were detained in that\nhouse for about a month with other detainees placed under the control of SNR. During their\ndetention, SNR and police agents – also assigned to SNR – would have tortured them\nseverely and repeatedly. It is reported that they would have been killed later by SNR agents.\n273. Witnesses reported that SNR was initially looking for Bukuru Shabani, accused of\nparticipating in the 2015 demonstrations as well as being a member of UPD-Zigamibanga\nand part of the rebellion. Because of his resemblance to his identical twin, Butoyi Shabani\nwas inadvertently arrested and taken to the private home in Kinindo that was used as a\nsecret detention facility. When those who detained him realised they had the wrong twin,\nthey arrested Bukuru Shabani without releasing his brother, for fear that the latter would\ndenounce them, especially given that he was in bad shape following the beatings he had\nreceived.\nÉvariste Nyandwi, alias « Matwi »\n274. The use of the house in Kinindo by the police and SNR as a secret detention center\nappeared in another case for which the Commission received consistent information.92\n275. In December 2016, personnel from the defence and security forces arrested a\nbusinessman named Évariste Nyandwi, alias « Matwi » in Rutana. On the day of his arrest,\nin the evening, Évariste Nyandwi was taken by SNR and police personnel from Rutana to\nthe house in Kinindo, Bujumbura Mairie. There, he was severely and repeatedly beaten by\na SNR officer as well as other SNR agents under his supervision before being executed by\nthe latter at the beginning of 2017.\n276. Évariste Nyandwi was allegedly targeted because of a conflict with a high ranking\nofficial in the State apparatus related to a public contract won by the victim.\n277. The Commission fears that several missing persons who are still being searched for\nby their relatives died in the house used as a place of secret detention in Kinindo.\nBonaventure Havyarimana, Égide Habonimana,                   Lionel    Hafashimana,\nEmmanuel Nyabenda, and Bénius Mbanyenimanga\n278. According to testimonies collected by the Commission,93 on 2 March 2018,\nBonaventure Havyarimana, Égide Habonimana, Lionel Hafashimana, Emmanuel\nNyabenda and Bénius Mbanyenimanga, all members of the opposition political party;\nMouvement pour la solidarité and la démocratie (MSD), were arrested as they were aboard\na vehicle driven by an acquaintance near Brarudi in Bujumbura. Several vehicles with SNR\nagents on board approached their vehicle and blocked it before taking them to an unknown\ndestination in their own vehicles.\n279. The victims’ relatives carried out searches in all the detention centers in Burundi but\nwere unsuccessful. Officials in those centers denied having detained them. SNR agents\ndemanded a ransom of more than a million Burundian francs (567 US dollars) from the\nsame relatives for their release. Despite the payment of this amount, Bonaventure\nHavyarimana, Égide Habonimana, Lionel Hafashimana, Emmanuel Nyabenda and Bénius\nMbanyenimanga are still missing. According to some sources, they would have been killed\nby SNR agents on the day they were arrested.","unnumbered":true},{"id":"a-hrc-39-crp-1-u0017","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":17,"section":"1. Right to life","text":"(ii)        Cases where there is reasonable ground to fear that they might be enforced\ndisappearances\n280. The Commission received information on other cases where some factors such as\nthe profile of the victims and of the presumed authors, the operating mode and the context,\nprovide reasonable ground to fear that they might consitute a case of enforced\ndisappearance.\nGaston Cishahayo\n281. According to information collected by the Commission,94 the brigadier de police\n(police sergeant) Gaston Cishahayo has been missing since 19 October 2017. The victim is\na former FNL combattant who had joined the police and had been posted to the Muramvya\npolice station at the time of the incident. On the day of his disappearance, Gaston Cishahayo\nwent to a bar in Bugarama where he had an appointment in the afternoon. Towards 17:30,\nhe was seen in the bar in the company of the person he was meeting and the SNR agent in\ncharge of the province of Muramvya. Gaston Cishahayo left the bar a bit later. He has not\nbeen seen since.\n282. The following day, on 20 October 2017, several written messages were sent from\nGaston Cishahayo’s phone. These messages requested that no one should be looking for\nhim as he had finally fled to Rwanda. The same day, calls were made from Gaston\nCishahayo’s phone but no one was talking. Afterwards, his number was unresponsive. Still,\non 20 October 2017, a police officer in Muramvya went to Gaston Cishahayo’s home, broke\nthe lock of his room and took all his belongings, without any search warrant.\n283. On 21 October 2017, a police officer called the relatives of Gaston Cishahayo to tell\nthem that he had left the country. According to the Commission’s sources, the various\nmessages and calls received by the victim’s relatives were intended to mask the\ndisappearance by pretending that he left the country. It was also indicated that a police\nofficer in Muramvya might be in possession of one of Gaston Cishahayo’s mobile phones.\nJérémie Ntiranyibagira, Édouard Nshimirimana, Libère Nzeyimana and Libérate\nNijimbere\n284. On 21 October 2017, four members of the armed opposition group Front Populaire\ndu Burundi (FPB), Jérémie Ntiranyibagira, Édouard Nshimirimana, Libère Nzeyimana and\nLibérate Nijimbere, were allegedly arrested by officers of the Tanzanian Intelligence\nService. According to witness accounts collected by the Commission,95 they were later\nhanded over to the head of SNR in Muyinga province. They were then executed. The bodies\nof at least three of them transited through Muyinga town before being buried in a location\nthat the Commission was unable to identify using the collected information.\n285. On 8 November 2017, the United Nations Working Group on enforced or\ninvoluntary disappearance “informed the Government of Burundi of the cases of Libère\nNzeyimana and Édouard Nshimirimana, who were allegedly kidnapped on 21 October 2017\nin Muyinga and Ngara (United Republic of Tanzania) by Burundian and Tanzanian police\nofficers”.96 To the knowledge of the Commission, the Burundian Government has not\nprovided any feedback to the Working Group.\nAimé Aloys Manirakiza, alias « Musaga », and Eddy Nduwimana\n286. According to information received by the Commission,97 Aimé Aloys Manirakiza,\nnicknamed « Musaga », an ex-FAB, resident of Kanyosha in Bujumbura Mairie, was an\nImbonerakure working in Musaga, who was allegedly involved in cases of human rights\nviolations jointly with personnel – including high ranking officials – from the Office of the\nPresident, the National Intelligence Service (SNR) and the Army. In the afternoon of 25\nMay 2017, Aimé Aloys Manirakiza received a call from a person asking him to go to a","unnumbered":true},{"id":"a-hrc-39-crp-1-u0018","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":18,"section":"1. Right to life","text":"certain location with Eddy Nduwimana, a 2015 demonstrator turned Imbonerakure, who\nwas used by SNR to conduct operations against opponents to CNDD-FDD. On their way\nto the meeting point, Aimé Aloys Manirakiza and Eddy Nduwimana were allegedly\napprehended in Kanyosha and taken by a police officer from API. They were never seen\nagain.\n287. Witness accounts collected by the Commission indicate that there was an internal\nconflict within Imbonerakure of Musaga about sharing the gains induced by the fuel\nshortage. In this context, Aimé Aloys Manirakiza and Eddy Nduwimana would have been\naccused of killing two Imbonerakure with a grenade and that would have been the reason\nfor their arrest and execution.","unnumbered":true},{"id":"a-hrc-39-crp-1-u0019","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":19,"section":"1. Right to life","text":"(iii)        Other cases of disappearance\n288. The Commission has also collected information on cases of disappearance for\nwhich, due to lack of detail that can be used to corroborate the elements obtained, it cannot\nconclude that they constituted cases of enforced disappearance. However, these cases\nhighlight a general context that is conducive to enforced disappearances. In addition, the\nCommission was not able to corroborate these cases because the documentation of cases of\nenforced disappearance requires in-depth research and thorough verification that, for the\nmost part, can only be facilitated by the full cooperation with authorities in the concerned\ncountry. In particular, it requires the possibility to access the detention centers, to solicit\ninformation from those, who by virtue of their positions, have the responsibility to protect\nthe detainees and should know their fate. The refusal of the Burundian Government to\ncooperate with the Commission has not allowed the latter to verify every case of\ndisappearance brought to its attention. This can however be done by a body or an\ninvestigation mechanism that would have access to the country.\n289. The main victims of these various cases of disappearance were, during the period\ncovered by the present report, members of the opposition parties namely FNL, MSD,\nUPRONA and UPD.98 The Commission also collected information on some cases in which\nthe missing persons were Imbonerakure.99 Some missing persons were targeted because of\ntheir refusal to join the political party CNDD-FDD.100\n290. The perpetrators of disappearance brought to the Commission’s attention are mainly\nImbonerakure,101 as was the case in the first mandate. In some cases, Imbonerakure acted\nin collaboration with police agents.102 As the Commission found in the present report that\nImbonerakure are under the “effective control” of the Burundian State,103 any detention by\nImbonerakure, which would be denied by Burundian authorities after the latter have\nreceived reports by the victims’ relatives, can be characterised as a case of enforced\ndisappearance. However, as noted by the Commission,104 few relatives of missing persons\nactually request the authorities to open an investigation into the disappearance, and thus\nauthorities are rarely faced with their responsibilities.\n291. For the most part, cases of disappearance imputable to Imbonerakure took place at\nnight.105 Imbonerakure broke into their victims’ homes, assaulted them before taking them\nto unknown destinations. In mosts cases, the neighbors did not even dare to intervene for\nfear of retaliation against themselves or their relatives.\n292. Several persons that the Commission spoke to describe Imbonerakure who\ncommitted those disappearances, as individuals wearing long black coats106 and military","unnumbered":true},{"id":"a-hrc-39-crp-1-u0020","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":20,"section":"1. Right to life","text":"(iv)     Impacts on the families and relatives of the disappeared persons\n293. Generally, relatives of the disappeared do not file a complaint. Some cited fear as\nthe main reason behind their reluctance to engage with authorities.111 A witness testified:\n“We are afraid to file a complaint for our security. Nowadays, it is very difficult.\nFiling a complaint for disappearance with the police can be harmful”.112\n294. Others consider that filing a complaint would be pointless given how close the\npresumed perpetrators are to the authorities responsible for investigations,113 and more\ngenerally, due to the absence of an independent judicial system.114 A relative of a victim of\nenforced disappearance explained:\n“I did not approach a tribunal […] The judiciary is no longer independent. It is the\nvoice of Imbonerakure that counts. I was not going to humiliate myself in front of\nan authority that is not independent. It would have been a waste of time”.115\n295. The same mistrust was expressed towards the police. The wife of a disappeared\nperson confided:\n“We looked for my husband in the neighbourhood, in the forest and rivers. We\napproached the police but they did nothing. I went to the police myself but they told\nme they did not have time to look for him”.116\nAnother witness stated: “In Burundi, a police officer will never criticise the\nGovernment in power nor an Imbonerakure”.117\n296. In some cases, taking advantage of the laxity of the police and the judicial\nauthorities, the perpetrators of enforced disappearance have attacked the victims’ relatives\nall the while threatening and intimidating them.118 Often, the disappearance of the husband\nforced the wife and the children to flee the country and seek refuge in the neighbouring\ncountries.119 It should be noted that the Human Rights Committee considers that family\nmembers of the missing persons who have no news from the victims for extended periods\nof time are, due to the anguish from the uncertainty, themselves victims of torture or cruel,\ninhuman or degrading treatment.120","unnumbered":true},{"id":"a-hrc-39-crp-1-u0021","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":21,"section":"2. Right to liberty and security of the person","text":"297. In its previous report,121 the Commission noted that arbitrary arrests and detentions\nwere the most common human rights violations amongst those that were documented in\nBurundi since 2015, and most of them led to other violations, namely extrajudicial killings,\nenforced disappearance, torture and cruel, inhumane or degrading treatment and sexual\nviolence.\n298. The main victims of arbitrary arrests and detentions in 2015 and 2016 were members\nof the opposition to the Government, suspected or actual, namely persons suspected, rightly","unnumbered":true},{"id":"a-hrc-39-crp-1-u0022","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":22,"section":"2. Right to liberty and security of the person","text":"or wrongly to be members or sympathisers of political parties or armed groups in the\nopposition or of having demonstrated against President Nkurunziza’s third term. Members\nof civil society organisations, journalists and human rights activists had also been arbitrarily\narrested and detained. Ex-FAB as well as persons who had refused to adhere to CNDD-\nFDD or to give money to that party had also been targeted. In addition, several persons,\nespecially young men, seem to have been arrested haphazardly during field operations by\nthe defence and security forces in the so called « dissenting » neighbourhoods in\nBujumbura, sometimes on the basis of their supposed ethnic group.\n299. Police agents, especially those in specialised units such as the Unit for the Protection\nof Institutions (API), the Anti-riot Brigade (BAE) and the Rapid Intervention Mobile Group\n(GMIR), were the main perpetrators of these violations, often in collaboration with SNR\nagents and members of the army. Imbonerakure were present during arrests and some of\nthem made arrests themselves.\n300. The arrest were arbitrary because the required procedures were not respected and\nseveral persons were arrested for what appear as political motives. Their detentions, often\nwithin the SNR offices, had no legal basis, or the detainees were not afforded the applicable\nfundamental garanties. The statutory period for detention and preventive detention were\nregularly exceeded. In addition, several persons remained in detention after being acquitted\nby a tribunal or having completed their sentence. In some cases, persons were released\nagainst payment of substantial amounts of money to SNR agents, police and judicial\nofficers and sometimes Imbonerakure.\n301. Since the presentation of the report of the Commission, other UN human rights\nmechanisms have analysed cases of arbitrary detention in Burundi. Since June 2017, the\nWorking Group on arbitrary detention issued two opinions on Burundi. It noted that the\ndetention of Elvis Arakaza, president of the Mouvement pour la solidarité and la\ndémocratie (MSD), in Bwiza and Jabe, detained since 14 Decembre 2015, was arbitrary\nbecause devoid of any legal base, founded on the fact that M. Arakaza was exercising his\nfundamental rights and freedoms and resulted in an unfair trial.122 It also determined that\nthe detention of 19 military officers; arrested in the context of attacks on military camps on\n11 December 2015, was arbitrary as it was devoid of any legal basis, based on ethnic\ndiscrimination, and resulted in an unfair trial.123 On 28 July 2017, an urgent appeal was sent\nto several Human Rights Council Special Procedures with regards to the detention of\nGermain Rukuki, an employee of the Burundian Association of Catholic Lawyers\n(Association des juristes catholiques du Burundi: AJCB).124 Lastly, on 19 December 2017,\nanother urgent appeal was sent regarding the detention of Nestor Nibitanga, a former\nmember of the Association for the protection of human rights and detainees (Association\npour la protection des droits humains and des personnes détenues: APRODH).125 To the\nCommission’s knowledge, the Burundian Government has not provided substantial\nanswers to these urgent appeals.126\n302. In the present report, the Commission noted the persistence of cases of arrest since\n2017 but to a lesser extent than in the past. These violations seem to have reached their\nclimax during the repression of the protests against President Nkurunziza’s third term and\nin the wake of the 2015 major security incidents. As per the past, several victims of arbitrary","unnumbered":true},{"id":"a-hrc-39-crp-1-u0023","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":23,"section":"2. Right to liberty and security of the person","text":"(a)     Main victims of arbitrary arrest and detention\n303. Some participants, actual or presumed, to the 2015 demonstrations or suspected\nsupporters of the demonstrators who had been arrested in 2015 and 2016, were still\narbitrarily detained in 2017 and 2018.129 Some were serving their prison sentence following\njudgements pronounced at the end of unfair trials, particularly for “undermining the internal\nsecurity of the State”. Others were still awaiting their trial.\n304. In 2017 and 2018, members of opposition political parties, their sympathisers or any\nother person perceived as such, were the main victims of arbitrary arrests and detentions,\nespecially in the contet of the preparation of the May 2018 referendum. They were accused\nof trying to mobilise the population to oppose the constitutional revision. Members of the\nFNL led by Agathon Rwasa, active within the Amizero y'Abarundi130 coalition, were\nparticularly targeted due to the call made by this coalition to vote “no” to the constitutional\nrevision.131 MSD members or sympathisers were also victims of such acts,132 as their party\ndecided to boycott the referendum. A member of an opposition party testified:\n“ I was campaigning for the ‘no’ vote. Leaders of Imbonerakure […] continued to\nthreaten me and other persons to join [CNDD-FDD] and to vote ‘yes’ during the\nreferendum. When they said that, I stayed calm and said: ‘We will see’. [In] 2018,\nI was with the youth league [of the opposition party] […] Police agents arrested us\n[…] and drove us to jail […] They accused us of holding an illegal meeting and of\ndisrupting public order and security. We were planning to campaign for the\n305. Persons were arbitrarily arrested and detained simply because they did not appear to\nfully agree with the policies of the Government or the positions of CNDD-FDD. Some were\narrested and detained, usually for a few days, because they refused to join the CNDD-FDD\nor the Imbonerakure;134 because they failed to register on the electoral lists for the\nreferendum; because they were suspected of wanting to vote against the constitutional\nrevision;135 or because they were suspected of being part of an armed rebel group or of\nwanting to join one, especially those who were trying to flee the country.136 Another witness\nrecounted:\n“[…] When the Imbonerakure arrived, they broke down the doors of the house and\nthen said: ‘You refuse to join CNDD-FDD, we will kill you today’ […] They\nimmediately started to hit me with their sticks on my legs and on my back and then\ntook me to jail. […] I was detained for three days. After arresting me, the\nImbonerakure, took me to the jail in the zone of […] The same Imbonerakure then\nproceeded to arrest me without a judicial warrant and handed me over to the police\nwho then put me in the cell. The police, naturally, took me in”.137\n306. Human rights activists and journalists continued to be victims of arbitrary arrests\nand detention du to their legitimate professional activities,138 as demonstrated by the\nemblematic cases of Germain Rukuki, of the three members of the organisation Paroles","unnumbered":true},{"id":"a-hrc-39-crp-1-u0024","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":24,"section":"2. Right to liberty and security of the person","text":"(i)         Arbitrariness of the arrests\n307. Since June 2017, several arrests were illegally done; in violation of the legal\nprocedures established by the Burundian Law:140 with no judicial warrant (arrest warrant\nor warrant to appear/summons);141 when the summoned person was not informed about the\nmotives nor the legal basis of his/her arrest (infraction or crime in question);142 or when\nthe arrest was done by one or more individuals not mandated to do so, mainly Imbonerakure\nor agents of the local administration.143 In Burundi, only judicial police officers are legally\nauthorised to make arrest, except in cases of flagrante delicto when any person can seize\nthe presumed perpetrator of a crime in the absence of a legally authorised judicial authority,\nand present them immediately to the closest competent authority.144\n308. Several arrests had no legal base since the facts the presumed perpetrators were\naccused of were neither an offence nor a crime under Burundian law. For example, persons\nwho spoke to the Commission mentioned having been arrested because they had denounced\nviolations committed by persons close to power or because they had refused to be involved\nin such violations.145 Persons were also arrested or briefly detained by authorities looking\nfor one of their relatives.146 A witness explained what happened to his father:\n“The […] Imbonerakure […] came home at [X] and [said] to my father:\n‘Give us your sons’. My father replied: ‘I do not know where my sons are presently’.\nHe was taken to the communal police of [Y]. He was interrogated and they asked\nhim: ‘Where are your sons?’ He replied again that he did not know. They told him:\n‘Your sons are wanted and must be arrested, if not, it is you who will be condemned’.\nMy father told me that when he arrived at the police post, the police chief named\n[D] interrogated him. He was beating him at the same time”.147\n309. Other persons were arrested and detained for a few days because they refused to\nregister to vote or had called on citizens to reject the constitutional revision.148 Other\npersons who had been released following their acquittal, a presidential pardon or after their\ncase had been closed by the prosecution were arrested anew without any legal base,\ngenerally by Imbonerakure or local administration agents, or even police or SNR agents,\nwho believed that these persons should not have been released by the judicial authorities.149\n310. The arbitrary and abusive character of these arrests should have been taken into\nconsideration by judicial authorities, namely during the process to decide to put them in\npreventive detention. Excessive use of force during arrests was also reported.150 However,","unnumbered":true},{"id":"a-hrc-39-crp-1-u0025","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":25,"section":"2. Right to liberty and security of the person","text":"(ii)     Main perpetrators\n311. Amongst the security and law enforcement forces, the police was still responsible\nfor several cases of arbitrary arrest,152 but it seems that its specialised units, such as API,\nBAE and GMIR and the Bureau spécial de recherche (BSR), were mentioned less often in\nthe witness accounts collected in the Commission’s second term. Members of SNR153 and\nthe Army154 have also continued to make arbitrary arrests, sometimes in collaboration with\nthe police, but to a lesser extent than in the past, according to witness accounts.\n312. On the contrary, Imbonerakure, were increasingly more responsible of arbitrary\narrests than in 2015 and 2016. They apprehended several persons while acting alone, often\nas subsidiaries of law enforcement and security forces in the rural areas where the latter are\nnot always present, despite the fact that they are not legally authorised to make arrests.155\nThe Commission collected witness accounts reporting the implication of Imbonerakure in\nthe fabrication of false accusations to justify the arrest of some persons.156 In several cases,\nImbonerakure were present during the arrest done by law enforcement forces and\nsometimes took on an active role, for example by identifying the person to apprehend.157 A\nvictim explained:\n“In July 2017, I went home for the holidays […]. As soon as I arrived home, […] I\nwas arrested. No sooner had I dropped my affairs, […] around 20:00, Imbonerakure\n[…], one of whom had a gun, wearing dark blue police coats, came into my house.\nThey asked me where I had been and if I was coming from the rebellion. They hit\nme with their boots in my ribs and on the back […] Then the Imbonerakure took me\nto the prison in the commune of [Y]”.158\n313. The local administration officials, namely the chefs de colline, the communal\nadministrators and even the governors of province, have also been implicated in arbitrary\narrests. They gave orders to Imbonerakure or the police to arrest certain individuals while\nthey had no legal authorisation to do so. They were present during some arrests.159 A victim\nstated:\n“[…We] were arrested […] [The administrative authority] thought that we were\nlooking for information […] He asked a judicial police officer to prepare a case\nagainst us […]”.160\n314. The Commission received information that officials from SNR, police, CNDD-FDD\nand Imbonerakure at the commune or zone level, continued to meet regularly in order to\nidentify the possible opponents and to plan the arrests. Some of the arrested persons have\nlater been detained arbitrarily, whereas others went missing.161 A witness explained:\n“On […] 2018, a meeting took place at the headquarters of the zone of [X] […] The\nobjective was to [identify] the persons who could be troublemakers in the commune.\nThese types of meetings take place regularly to discuss security issues. At the time\nof the meeting, the representative[s] of [X] spoke of […] persons […] They accused\nthem of disrupting the system of the party in the zone. For the good and the stability\nof the system, these […] persons should no longer stay in the zone”.162","unnumbered":true},{"id":"a-hrc-39-crp-1-u0026","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":26,"section":"2. Right to liberty and security of the person","text":"(i)     Arbitrariness of detentions\n315. Under international law, a detention can be qualified as arbitrary for various reasons,\nin particular because it has no legal base; when due to the exercise of fundamental rights\nand liberties; or when the international norms on the right to a fair trial have been totally or\npartially infringed upon.163 In Burundi, several persons accumulate various types of\narbitrary detention.\nDétention with no legal base\n316. Numerous preventive detentions in Burundi are arbitrary because they are illegal,\neven under Burundian law. The decision to detain prevently a person should be decided by\nthe judges’ council chamber that must meet within no more than 29 days from the beginning\nof custody.164 Not only is this timeframe contrary to the international standard of 48 hours\nin this matter, but also it is hardly applied in practice.165 The decisions of placement in\npreventive detention are valid for only a month and the accused must appear monthly before\nthe council chamber, which should decide on the continuation of the detention or the release\nof the person, proceudre which is almost never respected. On this subject, a victim testified:\n“I was not tortured physically but psychologically during my detention because no\none came to listen to me after I was put in jail, i.e. I never appeared before a judge.\nI wondered if I was going to die in jail; it was real torture not knowing how many\nyears I was going to spend there”.166\n317. Other cases of arbitrary preventive detention noted by the Commission were related\nto persons arrested then detained, even briefly, for facts that constitute neither crimes nor\ninfractions under Burundian law.167 In addition, some prisoners were maintained in\ndetention after having served their sentence168 or after having been acquitted;169 because\nprison authorities refused to release them. Other persons, to whom the council chamber had\ngranted interim release, remained nevertheless in preventive detention, often upon request\nof the prosecution.170 These detentions are arbitrary as they have no legal basis.171\n318. Some Imbonerakure were detained outside of judicial proceedings, and therefore\nwithout legal basis.172 They were kept in police cells or detention centers as disciplinary\naction decided by the hierarchy of the youth league and subject to the goodwill of the latter.\nThis demonstrates a little bit more the confusion that exists between the state apparatus and\nthe CNDD-FDD.173 Amongst the Imbonerakure and the CNDD-FDD members arrested and\ndetained in this way, some were suspected of wanting to leave the party or of not wanting","unnumbered":true},{"id":"a-hrc-39-crp-1-u0027","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":27,"section":"2. Right to liberty and security of the person","text":"to behave in accordance with the party line. Such detention aimed at punishing them and at\nputting them back on the “straight and narrow”. A victim testified:\n“I was arrested for a month because I was accused of not doing the work of an\nImbonerakure as I should. The other Imbonerakure, [my] subordinates, said that I\nwas not providing the equipment I ought to have given them. The accusations came\nfrom hierarchical subordinates and the SNR agents who had investigated my case\nand these were the conclusions of the investigation. I was heard by a judicial police\nofficer who supports the system in place, but since the first meeting, my file was\nthere already complete. I did not know the file’s content and who had said what.\nThese are not criminal proceedings but proceedings within the group of\nImbonerakure. I spent a month […] in the cell with other prisoners”.174\nDetention as a result of exercising fundamental rights and freedoms\n319. Human rights activists, members of the civil society as well as journalists have\ncontinued to be arrested, detained and condemned to stiff prison sentences for having\nexercised their fundamental rights and liberties recognized by international law namely\ntheir rights to freedom of information, freedom of expression, freedom of opinion and\nfreedom of peaceful assembly.175 This is highlighted by the above-mentioned emblematic\ncases of Germain Rukuki, Nestor Nibitanga, as well as the cases of Aimé Constant Gatore,\nMarius Nizigama, and Emmanuel Nshimirimana, who were arrested in 2017 and 2018,\nrespectively. The latter are members of the organisation Paroles and actions pour le réveil\ndes consciences et l’évolution des mentalités (PARCEM).176\n320. Some provisions of the Burundian criminal law are sufficiently vague to be used\nregularly in an abusive manner in order to “criminalize” the simple exercise of public\nliberties and to prosecute the arrested persons in the absence of key elements of the alleged\noffence.177 Several persons who had been detained due to the exercise of their freedom of\nexpression, association and peaceful assembly in the context of demonstrations against\nPresident Nkurunziza’s third mandate have been accused of “undermining the internal\nsecurity of the State”.178 Some are still waiting to be tried, others are serving their sentence\ndecided at the end of an unfair trial or have spent several months, even years, in detention;\nsometimes without trial, before being released.179 As already noted, persons have also been\narrested for having refused to join CNDD-FDD or its youth league, which also amounts to\na violation of their freedom of assembly.180\nAs one victim testified:\n“I was detained for three days before being released. [The] Imbonerakure militia\narrested me. Their leader asked me: ‘Where are your parents and why do they not\nwant you to join us’ in other words they wanted to know why my parents had not\njoined the political party in power CNDD FDD. They also asked me why I had not\njoined Imbonerakure. […] They then took me to a big house that I did not know […]\nWhen they released me, […I] saw the same Imbonerakure that had arrested me.\nThey did not do harm me, but they just asked me again to join their militia and if\nnot, they would kill me. They also said that my parents should join the ruling\nparty”.181\nDetention following an unfair trial","unnumbered":true},{"id":"a-hrc-39-crp-1-u0028","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":28,"section":"2. Right to liberty and security of the person","text":"321. Several persons are currently in jail after having been sentenced to a prison term\npronounced at the end of a trial during which international law standards for fair trial were\nnot respected,182 specifically due to lack of impartiality and independence of Burundian\ncourts and the failure to respect the rights of the defence and the equality of arms.183 Some\ndetainees did not have access to a lawyer nor to any form of legal assistance during the\ncriminal procedure due to the absence of an official legal aid scheme, the lack of time to\nlook for a lawyer during an accelerated procedure, or the fear of some lawyers to take on\nsensitive cases.184 In that respect, a victim stated:\n“I stayed at the communal police post for a month and a half […]. I saw the criminal\ninvestigation police officer only once. He did not make me sign the minutes of the\nhearing. The officer asked me why I was fleeing. He then put me in jail. He asked\nme a few questions. I did not have a lawyer. I was not informed that I could request\nfor a lawyer”.185","unnumbered":true},{"id":"a-hrc-39-crp-1-u0029","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":29,"section":"2. Right to liberty and security of the person","text":"(ii)      Main perpetrators\n322. In 2017 and 2018, victims interviewed by the Commission mentioned that police\nagents,186 including those of BSR, were the main perpetrators of arbitrary detention during\npolice custody, the first phase of the process following the arrest.187 Cases of arbitrary\ndetention by SNR, in particular at its headquarters near the Regina Mundi cathedral were\nalso reported,188 but to a lesser extent than in the context of the massive detentions and\narrests of demonstrators in 2015 and 2016.\n323. Judicial authorities bear the responsibility for the cases of arbitrary detention within\nthe 11 penal institutions in the country,189 whether in the context of preventive detention or\ndetentions following the exercise of fundamental rights and freedoms or an unfair trial.\nCases of extended detention despite an acquittal judgement or after the condemend persons\nhave served their sentence fall under the responsibility of the prison authorities.190\n324. Currently, international organisations and Burundian civil society organisations no\nlonger carry out regular visits in the detention facilities as they were used to do in the past.191\nThe Independent National Commission for Human Rights (CNIDH) does not play its role\nof following up on and exposing arbitrary detentions.192","unnumbered":true},{"id":"a-hrc-39-crp-1-u0030","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":30,"section":"2. Right to liberty and security of the person","text":"(iii)     Emblematic cases\n325. The cases mentioned above of five human rights defenders, arbitrarily detained for\nseveral months, are emblematic cases of arbitrary arrest and detention in Burundi, since\nthey were arrested and detained without any legal basis in relation with their legitimate\nactivities in the area of human rights, and after having been condemned to heavy prison\nsentences following an unfair trial that found them guilty of “undermining the internal\nsecurity of the State”.\nGermain Rukuki’s arbitrary detention","unnumbered":true},{"id":"a-hrc-39-crp-1-u0031","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":31,"section":"2. Right to liberty and security of the person","text":"326. Germain Rukuki is an employee of the Burundian Association of Catholic Lawyers\n(Association des juristes catholiques du Burundi: AJCB), who had previously worked for\nthe Action des chrétiens pour l'abolition de la torture au Burundi (ACAT-Burundi), an\norganisation accused by the Burundian Government of having participated in an\ninsurrectional movement that organised the demonstration against President Nkurunziza’s\nthird term.193 Germain Rukuki was arrested on 13 July 2017 and detained at SNR until his\ncondemnation on 1 August 2017 for “undermining the internal security of the State” and\n“rebellion”, in connection with his work within ACAT-Burundi. On 17 August 2017, the\nCouncil Chamber of the Court of First Instance of Ntahangwa ruled to extend his preventive\ndetention, a ruling that was communicated to Mr. Rukuki only on 25 August 2017. He then\nappealed this decision. On 31 October 2017, the Bujumbura Court of Appeal confirmed\nMr. Rukuki’s continued preventive detention. On 26 April 2018, Germain Rukuki was\ncondemned to 32 years of imprisonment for “belonging to an insurrectional movement”,\n“undermining the internal security of the State” and “rebellion”.\n327. This extremely harsh sentence follows a criminal procedure interspersed with\nirregularities and repeated violations of the rights to defense and to a fair trial. Hence, the\narrest of Mr. Rukuki was done without an arrest or search warrant. During the investigation,\nhe was interrogated several times in the absence of his lawyers. During the first hearing of\nhis trial on 13 February 2018, the charges of “assassination of militaries, police agents and\ncivilians”, “damage to public and private buildings”, and “willingness to change the\ndemocratically elected regime” were added to the accusation while they were not raised\ndurin the investigation proceedings. Mr. Rukuki, who was detained in the Ngozi prison,\nalthough he resided in Bujumbura, was notified of the first appearance on the same day,\nwith no regard of the eight days legal notice, which is crucial for the defense preparation.\nHis lawyers were only able to examine part of the case file just before this court hearing.\nFinally, nor Mr. Rukuki, neither his lawyers were present during the reading by the Court\nof the sentencing to 32 years of imprisonmemnt. These elements support the conclusion\nthat the trial was unfair.194\n328. In addition, most of the questions asked to Mr. Rukuki during the investigation were\nin relation to his work as human rights defender and his legitimate activities within ACAT-\nBurundi in 2015. This demonstrates that the proceedings against Mr. Rukuki, and the\nsubsequent condemnation, were linked to his activities as human rights defender and\ntherefore to the exercise of his fundamental rights and freedoms.195\nArbitrary detentions of Aimé Constant Gatore, Marius Nizigama and Emmanuel\nNshimirimana\n329. Aimé Constant Gatore, Marius Nizigama and Emmanuel Nshimirimana were\nrepresentatives of the organisation PARCEM in Mbuye commune (Muramvya province),\nBuhangura zone (Muramvya province) and in Muramvya province, respectively. They were\nall arrested in June 2017 in Muramyva by SNR, because they were preparing a training\nworkshop for whistle-blowers on human rights violations. They were initially brought to\nSNR in Muramyva before being transferred to SNR headquarters in Bujumbura, where they\nwere detained for a week. They were then detained at the Mpimba prison and the Muramvya\nprison. Their trial started on 1 December 2017 at the Muramvya Court of First Instance\n(Tribunal de grande instance – “TGI”). On 8 March 2018, they were condemned to 10\nyears of prison and a penalty fee of 200,000 Burundian francs for “undermining the internal\nsecurity of the State”.196\n330. The accusation of “undermining the internal security of the State” was used\nabusively and arbitrarily. The Prosecution solely used the internal documents related to the\norganisation of the training workshop, and more precisely the list of participants.","unnumbered":true},{"id":"a-hrc-39-crp-1-u0032","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":32,"section":"2. Right to liberty and security of the person","text":"Nevertheless, the judges agreed with the prosecution and estimated that the accused, by\nseeking to establish a network of whistle-blowers on human rights violations made up of\nyoung persons some of whom were affiliated to opposition political parties and none were\nmembers of CNDD-FDD, were planning to undermine national security. In addition,\ncontrary to the established procedure, the judges rendered their verdict in the absence of\nboth the accused and their lawyers, four days before the due date while they were sitting in\na separate case.197\n331. The detention of the three PARCEM members is arbitrary as it results from the\nexercise of legitimate activities and fundamental freedoms, namely the freedoms of\nassociation and assembly, and because it was confirmed through heavy sentencing at the\noutset of an unfair trial.","unnumbered":true},{"id":"a-hrc-39-crp-1-u0033","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":33,"section":"2. Right to liberty and security of the person","text":"Arbitrary detention of Nestor Nibitanga\n332. The police and SNR arrested Nestor Nibitanga on 21 November 2017 at his\nresidence in Gitega province. He had, in the past, worked for the Association for the\nprotection of human rights and detained persons (Association pour la protection des droits\nhumains et des personnes détenues: APRODH), a civil society organisation that was\nderegistered by the Government in October 2016 198. At the time, he was not informed of\nthe motives of his arrest. His laptop and mobile phone were also confiscated at the time of\nhis arrest. Nestor Nibitanga was taken to the SNR headquarters in Bujumbura where he was\ndetained in secret until 4 Decembre 2017, at which point he was transferred to the central\nprison in Rumonge. He was accused of “undermining the internal security of the State”. On\n3 January 2018, the Council Chamber of the Court of First Instance (TGI) of Mukaza\n(Bujumbura), which held a meeting on 28 December 2018, decided to place him in\npreventive detention. On 20 June 2018, Nestor Nibitanga appeared before the Court of First\nInstance of Mukaza holding its hearing at the Rumonge prison. The Prosecution requested\na twenty-year prison term sentence. The condemnation, pronounced on 13 August 2018,\nreduced the sentence to a five-year prison term199.\n333. In this case, several irregularities were committed. Nestor Nibitanga was secretly\nheld in custody. The legal delay for analysis of the legality of his detention by the Council\nChamber was exceeded. Nestor Nibitanga should have appeared before the Council\nChamber within 15 days after being charged with “undermining the internal security of the\nState”. However, on that date, Nestor Nibitanga was transferred to Rumonge prison without\nappearing before the judges. The Council Chamber should have reached its decision within\n48 hours, which was not done in this case. There is also a problem in relation to the court\nthat was seized with this matter: whereas the crime that he was accused of allegedly took\nplace in Gitega, his place of residence, M. Nibitanga was and is still detained in Rumonge,\nwhile his case was transferred to the Prosecution at the Court of First Instance of Mukaza\n(Bujumbura Mairie). Concerning the accusation of the crime of “undermining the internal\nsecurity of the State”, the Prosecution solely used the working documents of APRODH\nseized during the search, namely, those in relation to the preparation of some APRODH\nreports at the time that the organisation was legally working.\n334. Nestor Nibitanga is therefore arbitrarily detained following the legitimate activities\nthat he carried out in the field of human rights when he worked for APRODH, his activities\nhaving been abusively qualified as “undermining the internal security of the State”. In\naddition, the criminal procedure, was – as indicated – marred by irregularities.","unnumbered":true},{"id":"a-hrc-39-crp-1-u0034","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":34,"section":"2. Right to liberty and security of the person","text":"(iv)     Unofficial places of detention\n335. Apprehended persons continued to be detained, especially in the first few days\nfollowing their arrest, in unofficial places of detention located in Bujumbura and in the rest\nof the country. The victims were not always able to clearly identify these places, but they","unnumbered":true},{"id":"a-hrc-39-crp-1-u0035","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":35,"section":"2. Right to liberty and security of the person","text":"mentioned private houses and places that were indisputably not official places of\ndetention.200 One of the victims testified:\n“After [having arrested me], they took me to a location. It was night. It must have\nbeen a house because there were lights. It certainly was an enclosed house because,\neven when you screamed, no one could hear you. We walked to get there […]. It was\nnot far from my home”.201\n336. The persons detained in such places were placed outside the protection of the law\nand were de facto more at risk of other serious human rights violations, in particular torture\nand enforced disappearances.202","unnumbered":true},{"id":"a-hrc-39-crp-1-p0003","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"3","seq":36,"section":"2. Right to liberty and security of the person","text":"Tortures and other cruel, inhumane or degrading treatments\n337. During the first term of its mandate,203 the Commission had documented several\ncases of torture and cruel, inhumane or degrading treatments committed since 2015. It\nconsidered that the use of torture and other ill treatments was quasi systematic against\npresumed opponents to the Government or CNDD-FDD during their detention, including:\ndemonstrators against President Nkurunziza’s third term, residents of neighbourhoods\nwhere these demonstrations took place, members or sympathisers of opposition political\nparties, presumed participants to the coup d’état of 13 may 2015 and to the attacks on\nmilitary facilities on 11 December 2015, as well as persons who had fled the country. The\nperpetrators and those who bear the primary responsibility were members of SNR, PNB\nand, to a lesser extent, members of FDNB; some of whom were high ranking officers; as\nwell as Imbonerakure acting as their auxiliaries. The main areas where these abuses were\ncommitted in the capital were the headquarters of SNR near the Cathédrale Regina Mundi\nand the headquarters of the Anti-riot Brigade (BAE) located in the place called « Chez\nNdadaye ». Torture and ill treatments also occurred in other detention centers of the police\nand the SNR, as well as in unofficial places of detention in Bujumbura and in the provinces.\n338. Amongst the main methods of torture detailed in the previous Commission report,\nthe victims mentioned having been beaten with clubs, rifle butts, bayonets, iron bars, metal\nchains or electric cables, which in some cases resulted in broken bones or loss of\nconsciousness. Long needles had also been inserted in various parts of the body,\nunidentified products were injected, nails were pulled out, and some victims were forced\nto stay next to dead bodies or to eat faecal matters. Rapes and other forms of sexual violence\nhad been committed, as well as enforced disappearances amounting to acts of torture 204.\nDetainees had to witness executions, convinced that they were next in line. These acts of\ntorture and ill treatments were often accompanied by insults, including ethnic related\ninsults, and death threats proffered as their authors manipulated firearms or grenades. In\nseveral cases, these violations left serious physical and psychological scars. Victims also\ndescribed conditions of detention that constitute ill, inhumane or degrading treatments,\nnotably due to the prison overcrowding and the appalling and unsanitary conditions of\ndetention, the deprivation of food and clean water, the denial of access to health facilities\nand adequate medical care, or the absence of separation between adults and minors.\n339. In the present report, the Commission focused on cases of torture and cruel,\ninhumane or degrading ill treatment perpetrated since 2017. It observed the persistence of\ncases of torture and ill treatment and noted the continuity of forms of torture used and the\nrelated consquences, as well as some evolution of the profiles of victims and perpetrators,\nas well as of the objectives pursued. The Commission also spoke with persons who had\nbeen arrested, tortured or ill-treated during the period covered by the first term of its\nmandate.205 These witness accounts have confirmed the information and conclusions on\ntorture and ill-treatment that the Commission detailed in its previous report, but they were\nnot used in the current report.\n340. This chapter ought to be read in conjunction with the chapters on enforced\ndisappearances and on sexual violence,206 which also constitute forms of torture. In\naddition, the treshold between torture and cruel and inhuman treatment being sometimes\nunclear or partly dependent on the intensity of the suffering inflicted on the victim, namely\ntaking into account his/her age, physical attributes, health and especially his/her\nvulnerability,207 some acts of violence documented by the Commission may not qualify as\ntorture but as ill-treatment and therefore they constitute serious human rights violations.\n(a)         Main victims, perpetrators and places of torture and ill treatments\n341. The profile of the victims, presumed perpetrators and places where these acts of\ntorture and ill treatments took place has partially evolved compared to the previous period\nin the specific context of the preparation and the holding of the May 2018 constitutional\nreferendum.\n(i)         Main victims\n342. The main victims of torture and ill treatments were persons considered as opponents\nto President Nkurunziza or to CNDD-FDD. The majority were young men, sometimes\nminors, albeit older men and women were also victims. The perpetrators sought to punish\nthem for being member or sympathiser of another political party.\n343. It is not uncommon that some persons who had taken part in the 2015\ndemonstrations, or others who had wanted to leave Burundi or who had spent some time\nabroad were tortured or ill-treated because they were perceived as opponents, sometimes\nrebels belonging to armed groups.208 The torture aimed to punish them, to force them to\nadmit their belonging or support to armed groups or to get information about firearms\nsupposedly in their possession.209 One of the victims interviewed by the Commission, who\nhad sought refuge in a neighbouring country and who had then returned to Burundi,\nexplained:\n“I returned to Burundi in […] 2017 […] Two days after I returned, […] a group of\n[…] people came to my house […]. I recognised one person: he was the head of\nImbonerakure on my colline […]. He said: ‘It has been two years since you left and\nhere you are changing money. You are certainly from the rebellion, the bush […].\nThe person who gave us information was right. Admit that you came to buy supplies\nfor the rebels in the bush. Think about it and you will give us an answer, but we\nknow the truth’ […]. They hit me on the head. I still have scars. The police officers\nbeat me using a stick and their feet “.210\n344. Increasingly, persons with no political activity or engagement were victims of\ntorture and ill-treatment, mainly in the context of preparation of the constitutional\nreferendum. Several persons were tortured or ill treated in order to punish them for having\nrefused to adhere to CNDD-FDD or to join its youth league.211 Increasingly, any failure or\nbreach in alignment with the Government policy is considered as a sign of belonging to the\nopposition. Hence, persons were tortured or ill-treated for having failed to register on\nelectoral lists ahead of the constitutional referendumen or were suspected – rightly or\nwrongly – of wanting to vote “no” during that referendum or to incite the masses to do\nso.212 The torture aimed at intimidating them or forcing them to follow the instructions from\nthe ruling party to vote in favour of the constitutional revision, or to force them to reveal\ntheir plan to oppose the constitutional revision. A person tortured by a police agent said:\n“I did not want to register in order to obtain a voter’s card. In December 2017, I\nhad not registered. I do not know when we had to register. I was not very interested\nbecause I had no time. I had to work […] [The] communal administrator […] asked\n[me] for my voter’s card. He was with some Imbonerakure […] and armed police\nagents in uniform […] the administrator then took a stick and he started beating me.\nThe Imbonerakure also beat me. They were saying that I had refused to do what I\nwas asked to do. Now, they were going to use force”.213\n345. The case of Simon Bizimana is emblematic in that regard. He refused to register on\nelectoral lists due to his religious faith that, according to him, required him to stay away\nfrom any political activity. He was arrested on 14 February 2018 and the video of his arrest\nand interrogation was largely circulated on social networks.214 He was then placed in\ndetention in an arbitrary manner by local authorities for having refused to register to vote.\nOn 18 March 2018, he died under suspicious conditions at Cankuzo hospital. According to\nthe official version, he died of malaria after having been released on 14 March when he\nwas in good health. Conversely, the Burundian civil society reported that he was seriously\ntortured by SNR agents before being taken to the hospital where he reportedly died of the\nabuse incurred.215\n346. Other persons, especially women, were tortured as a punishment or a retaliation,\nbecause a member of their family, suspected of being an opponent or a member of an armed\nopposition group, was wanted and remained at large.216 A woman explained:\n“On […] July 2017, at midnight, […] I had slept on the floor. He handcuffed me\nwhile I was on the floor. He held my elbows behind my back with a rope, made me\nlie on my stomach and tied another rope on my knees. After, he stepped on my legs\nand my back with his boots […]. He said: ‘Bring your husband to us, or else we will\nkill you. We were ordered to bring your husband’. I think that they were referring\nto the head of Imbonerakure in the commune from whom they had received the\norder”.217\n347. In addition, ethnically charged statements were used by some perpetrators, which\ngive grounds to believe that some cases of torture included motives based in part « on a\nform of ethnic discrimination ». 218 A man tortured by police officers during the month of\nJuly 2017 stated:\n“[The police officers and civilians who were with them] said a lot of ethnically\ncharged statements. They said: ‘You Tutsis, you have always dominated us, but this\nwill no longer be the case. We got hold of the power with a lot of difficulty and will\nnot let it go. Go tell the others that you made a mistake’ [meaning in relation to the\nHutus]. They were not talking about me specifically but about the Tutsis in general.\nThey started beating me up violently”.219\n(ii)         Main perpetrators\n348. Since 2017, the Commission noted a significant evolution with regards to the\nperpetrators of torture and ill treatment. The majority of cases is now mostly committed by\nImbonerakure acting alone, in full view of police agents or with their cooperation 220.\n“The Imbonerakure took us, tied up all three of us with our hands behind the back.\nThey also tied our feet. They tied us the same way they tie up goats. They beat us up\nand threatened us with military knives […] An Imbonerakure injured me on the leg\nwith such a knife. They beat us for about 20 minutes all over the body. The police\ndid not intervene, they only looked on during the whole time”.221\n349. PNB222 and SNR223 agents were also identified as perpetrators of acts of torture by\nvictims and witnesses. Some cases of torture and ill treatment were also committed by\nmembers of the armed forces, but to a lesser extent than during the time period covered by\nthe previous report of the Commission.224\n350. Some victims and witnesses were able to identify some of the perpetrators of torture\nand ill treatment by name because they previously knew them.225 The majority of victims,\nwithout being able to name the perpetrators, have nonetheless been able to identify the\ngroups to which they belong, their affiliation, their functions, thanks to their uniforms or\nother distinctive signs such their clothes, equipment and the places where they were brought\nto. As mentioned, several witness accounts talked about Imbonerakure wearing military\nuniforms.226 A person who spoke to the Commission said:\n“The police officers were armed and the Imbonerakure had wooden sticks while\nothers had iron bars. Imbonerakure and police officers were wearing the same\nmilitary boots as those worn only by the police and soldiers. Their shoes were\ntherefore similar but their clothes were different. Imbonerakure were wearing sports\nattire T-shirt bearing “CNDD” labels on it. Some T-shirts even had the photo of the\nPresident [of the Republic]”.227\n(iii)     Main venues for torture and ill treatment\n351. Cases of torture and ill-treatment in the context of arrest and detention were mainly\ncarried out in police station cells,228 in the SNR premises,229 and at the central prison of\nMpimba in Bujumbura where detainees were beaten by Imbonerakure in the area called\n“petit marché” or “place du marché”.230 A person arrested at the end of 2017 explained:\n“In the prison [of X], there are two areas, one reserved for persons that committed\noffenses under general law such as thieves for instance. I was taken to a different\ncell in the back. […] One hour after, the […] persons who arrested me came back,\nthey took me from my cell […], they pushed me and I fell […]. There was a metallic\nstick in the fire. I was still handcuffed. […] They asked: ‘Did you participate in the\ndemonstrations?’. I said yes […] one of them took the metallic stick and burnt me\nin the back. I have a big scar on my back […] After that, they asked: ‘Why are you\nagainst Pierre Nkurunziza?’. I did not reply their questions and kept quiet. [One of\nthem] removed the handcuffs and asked me to straighten my arms and then burnt\nthem”.231\nA former detainee recounted the torture of a prisoner that he witnessed first-hand in\nthe prison of Mpimba: “One day, [the Imbonerakure] took him to the ‘petit marché’\nof the [Mpimba] prison and they tortured him. […] they poured water on [X]. They\nstarted to beat him up […] There are individuals who are specifically targeted. [X]\nwas accused of having stolen guns […] While beating him, the Imbonerakure\nprisoners were saying : ‘You killed a lot of Hutus. You want to take power by\nforce’.”232\n352. Witness accounts also indicate that cases of torture took place in unofficial places\nof detention, such as private homes used specifically for this purpose, which the witnesses\nwere not always able to identify.233\n353. Acts of torture and ill treatment were also committed in public places, in isolated\nareas and in farms.234 Several victims were tortured and ill-treated in their homes by\nImbonerakure, police officers or both.235 A victim told the Commission what happened to\nher in July 2017:\n“On […] July 2017, around 21h30-22h, I was home alone […] the door was forced\nopened. Some came through the bedroom window and others through the door. They\nwere about ten inside the house. Some amongst them were police officers in uniform\nand others were civilians wearing military or police boots […] One of the police\nofficers hit me with a rifle butt on my head […] At some point, I fainted […] They\nkicked me and punched me and hit me with a rifle butt […] They left me for dead.\nThey threw me outside [of the house]”.236\n(b)     Methods of torture\n354. Several witnesses interviewed by the Commission declared having been tortured,\nsome for several hours, and in some cases several consecutive days.237 The most frequently\ndocumented methods of torture are largely similar to those documented by the Commission\nin its first mandate, namely:\n•    Kicking the victims and hit them with stones,238 batons,239 sticks, metal bars240 or\nguns,241 and sometimes with several objects at the same time, on different parts of\nthe body and especially on the head, back and legs.242 During the beating, victims\nwere generally held still by their torturers who sometimes used handcuffs and, in\nother cases, held their hands and feet tied up.243 Some of them were forcibly\nunclothed before being beaten on various parts of the body;244\n•    Burning the parts of the body such as the back or the arms with searing hot iron\nbars;245\n•    Slashing persons with sharp objects such as machetes and knives;246\n•    Raping or inflicting other types of sexual violence on some men in detention;247\n•    Proffering death threats or threats of torture against detainees, and therefore\nvulnerable persons, which is a form of psychological torture, especially given that\nthese threats were accompanied by physical violence.248\n355. A former detainee at SNR explained to the Commission how death threats were used\nto force him to admit his intent to attack the Government:\n“The [third] day, around three in the morning, they took me out of my cell again.\nThey told me: ‘Since you refused to accept all the accusations against you, it is now\ntime to kill you’. They showed me a big knife. They put the knife on my neck. Then\nthey put the knife in the mouth and they continued to interrogate me with the knife\nin my mouth”.249\n(c)     Other forms of cruel, inhumane or degrading treatment\n356. The Commission notes the persistence of cruel, inhumane or degrading treatments\nconstituted by the conditions of detention in Burundi, but also of acts of violence committed\nby Imbonerakure acting alone or with State agents during arrests or attempts of forced\nrecruitment of young men.\n(i)     Cruel, inhumane or degrading conditions of detention\n357. The conditions of detention in Burundi have not improved and they constitute cruel,\ninhumane or degrading treatments. Places of detention, whether prisons or police or SNR\ncells, are generally overcrowded and sometimes without access to natural light or air.250\nPeople are detained in unsanitary conditions, unable to maintain personal hygiene.251 Such\nconditions, combined with lack of adequate medical care 252 and to the lack of food and\nclean water,253 have had harmful consequences on the detainees’ health 254. A witness,\ndetained in 2018, in a police cell explained to the Commission:\n“I was detained in a small cell of two by two meters. There were 17 persons and no\nwindow, nor access to water. Everybody was there. For passing stool, we had to do\nit in a small pan […] Family brought me food and drinks. I was only able to have a\nbath once in 10 days. Some stayed for three weeks or even four weeks […] people\ncoughed and had malaria. There were persons who spent two to three months in the\ncell. People slept on the floor and after three or four hours, we would change\npositions”.255\n358. The situation in Burundian prisons remain alarming, as recognised by the Director\nGeneral for Prison Affairs on 16 July 2018 in a press conference, during which he explained\nthat as of 12 July 2018, there were 9,901 detainees in the 11 prisons of Burundi, while the\nofficial total capacity is of 4,194 persons only.256 The central prison of Mpimba counts over\na third of the total number of detainees, i.e. around 3,500 individuals. The General\nDirectorate of Prison Affairs estimates that the rate of prison overpopulation is of 230 %,\nwhich leads to serious issues with regards to the living conditions of the detainees, their\naccess to food and medical treatment as well as the separation of various categories of\ndetainees given that 57 % of them are in custody (5,682 individuals). The buildings are\ndilapidated, most of them dating back to the 1920s and 1950s, and they are not adapted to\ncurrent prison settings. The personnel of the General Directorate of Prison Affairs is made\nup 240 persons, all categories included, including central administration staff (between 40\nand 50 persons) and around 40 staff at Mpimba, which translates to only 15 staff responsible\nfor each remaining prison.257 The lack of a reinsertion program is an additional consequence\nof the lack of human and financial resources allocated to the General Directorate of Prison\nAffairs.\n359. The Commission is concerned by the central role and extensive responsibilities\ngiven to the “capita” and “capita généraux” within the prisons, who are the “heads” of the\ndetainees. The Director General of Prison Affairs 258 blamed this situation on his\nadministration’s lack of human resources. He also indicated during this press conference\nthat these capita are assigned to specific tasks such as cooking or « security », and the\n“capita généraux” help the prison administration in the management of detainees. They are\nchosen by the administration of the prison, mainly amongst the Imbonerakure detainees,259\nand manage de facto the daily life within the prison, notably by ensuring good order\namongst the detainees and controlling access of external visitors – including lawyers – to\nthe prison and detainees. This situation is a source of abuse and ill-treatment of detainees.260\nIn addition to beating them in the area called “petit marché”, the Imbonerakure designated\nas “capita” use at least one ad hoc isolation cell within the Mpimba prison in Bujumbura,\nin order to prevent some detainees from any contact with others.261\n360. In addition, the Commission noted that the annual presidential pardon of thousands\nof detainees, which aims to address the prison overpopulation, is often subject to abuse and\ncorruption, and cannot be conceived as a satisfactory tool for regulating prison population.\nThe end of arbitrary detentions and the quasi-systematic use of preventive detention should\npreced the latter, in addition to an improvement of the follow up of the situation of prisoners\nin order to guarantee that those who have served their sentences are released and that those\nwho can benefit from a conditional release are identified.262\n(ii)         Other cases of ill treatment\n361. Some acts of violence committed by Imbonerakure, alone or in the presence of\npolice and SNR agents, in contexts similar to the cases of torture detailed above, amount to\ncruel, inhumane or degrading treatments and sometimes draw near the threshold of torture.\nMost of the cases are those of young men, sometimes minors, who were beaten during the\nforced recruitment within the ranks of Imbonerakure or during their arrest.263\n(d)          Consequences of torture and cruel, inhumane or degrading treatment\n362. The impact torture and ill-treatment on the victims is both physical264 (scars, partial\nhandicap, impotence) and psychological,265 and persists in the middle to long-term. The\nCommission was able to directly observe several scars or disabilities on the victims, which\ncorrespond to the acts of torture that they had described. Several of them continue to suffer\non a daily basis from the injuries they endured because often, they did not receive adequate\nmedical treatment.266 For example, a witness, met by the Commission in 2018 and who has\nvisible scars of the torture he endured at SNR in 2015, said:\n“They took a red hot iron bar and an iron and they put them on the sole of my feet.\nTo this day, it is still painful. I cannot wear shoes for a long time, it gets swollen\notherwise”.267\n363. A man, beaten and left for dead in July 2017 by police officers and Imbonerakure,\nexplained how he became disabled since the incident:\n“From that date, I walk with a cane. They beat my abdomen and destroyed [one of\nthe organs]”.268"},{"id":"a-hrc-39-crp-1-p0004","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"4","seq":37,"section":"2. Right to liberty and security of the person","text":"Sexual violence\n364. In its previous report,269 the Commission had noted that in 2015 and 2016, the main\nvictims of sexual violence in cases that it had documented, were women and girls. The\nobjective of these acts of violence was in particular to punish them for their support, or that\nof their relatives, to the demonstrations against the President Nkurunziza’s third term; for\ntheir affiliation, or that of their relatives, to an opposition party; or for their assumed\nparticipation, or that of their relatives, to the attacks against military facilities on 11\nDecember 2015. Some victims had also been targeted because of their refusal to join\nCNDD-FDD or its activities. The victims, whose age varied from 8 to 71, had been\nparticularly targeted when they were alone following the arrest, disappearance or death of\ntheir spouses or men in their family. They have endured rape and other forms of sexual\nviolence often in their home, in the presence of their children or other members of their\nfamily, adding to their feeling of humiliation and offence against their dignity. During their\ndetention, several women had also been raped, and men had also been victims of rape and\nother forms of sexual violence. Such acts, which aimed to extract information and\nconfessions, also constitute torture.\n365. In several cases, police and SNR agents were identified as responsible of such sexual\nviolence. They sometimes had acted together or with Imbonerakure. In some cases, the\nlatter had acted alone. The victims often had endured several types of sexual violence,\nincluding rape, genital mutilations, forced nudity, infliction of serious injuries and/or the\ninjection of unknown substances in the male genital organs. Several women had been\nvictims of collective rape. These acts, sometimes accompanied by insults with ethnic and\npolitical denotation, had taken place in the victims’ residence, in police or SNR cells or in\nunofficial detention places. Several victims were not able to officially identify the status of\nthe men in civilian outfit who raped them, some of whom had equipment or accessories\nreserved for security forces.\n366. Like other types of human rights violations documented in 2015 and 2016, the\nvictims had rarely complained due to the lack of trust in the judicial system and perpetrators\nhave benefited from quasi-total impunity. All the victims of sexual violence had multiple\nphysical and/or psychological scars, in particular because of the lack of access to adequate\nmedical care and psychological support.\n367. During the second term of its mandate, the Commission collected witness accounts\nrelated to sexual violence acts committed in 2015 and 2016 which confirmed the main\ntrends established in its first report270 and which have just been described. The Commission\nalso received witness accounts on sexual violence that took place since 2017, demonstrating\nthe persistence of this type of human rights violations in Burundi. Most of the sexual\nviolence acts constitute torture, since they were committed with the approval and\ncompliance of State agents, with specific objectives in mind, such as the intimidation or\npunishment for a supposed political affiliation.271\n368. In addition, sexual violence documented by the Commission amount to both gender-\nbased violence and a form of discrimination against women. They were perpetrated in a\ncontext where the social norms and attitudes, including legal dispositions, promote multiple\nforms of discrimination and violence against women. Gender-based sexual violence were\nalready widespread before 2015. In November 2016, the Committee for the Elimination of\nDiscrimination against Women deplored that “gender-based violence against women is\nvery widespread in the member State and that domestic violence is tolerated, as a result of\ndeeply rooted patriarchal mentalities”.272 According to the health and demographic study\nof 2016 and 2017, whose results were published in April 2018 by Burundian authorities,\nalmost a quarter of surveyed Burundian women declared having been victims of sexual\nviolence compared to only 6 % of men.273 There are reasons to fear that the 2015 crisis\namplified the risks and the number of cases of sexual violence in Burundi, not only due to\nthe high level of violence in the country and the impunity enjoyed by the perpetrators of\nhuman rights violations, but also due to the aggravated poverty which, combined with\neconomic dependence of women on men, also promotes this type of violence.274\n(a)     Main victims\n369. In the majority of cases of sexual violence documented by the Commission since\n2017, the victims were women.275 Several of them were pregnant at the time of the\nviolations.276\n370. Most of them were targeted because they and/or their husband refused to join the\nCNDD-FDD or the Imbonerakure.277 Some were members of opposition political parties,278\nbut, for several of them, they seem to have been targeted because their spouse belonged to\nan opposition political party.279 Several victims who spoke to the Commission said they\nhad no political affiliation.280 A woman declared:\n“While this man was raping me, another one who was standing next to me was\nsaying: ‘If your husband had accepted, he would be an Imbonerakure and you a\nmember of CNDD-FDD. But he refused, and because a couple is made up of two\npeople, you must also pay’.”281\n371. Men, suspected of belonging to opposition political parties or to support armed\ngroups, have also been victims of sexual violence during their detention, particularly in\norder to force them to confess some facts, such as having given weapons to armed\nopposition groups or having been in contact with the latter.282\n(b)     Main perpetrators\n372. State agents, especially police283 and SNR284 agents perpetrated several cases of\nsexual violence. In most cases however, the victims identified Imbonerakure or persons\nacting on behalf of CNDD-FDD who previously knew them as perpetrators of sexual\nviolence inflicted on them or amongst persons who accompanied the latter.285 According to\nwitness accounts collected by the Commission, these perpetrators generally acted while\nmoving around as part of groups of several men, with no apparent presence of State agents.\n373. In other cases, victims were not able to officially identify the individuals who raped\nthem as Imbonerakure, but the description that they gave, their modus operandi or their\nstatements, suggest that they were effectively Imbonerakure.286 Amongst the perpetrators\nof sexual violence, some had fire weapons, grenades, batons or bladed/sharp-edged\nweapons.287 A woman who was raped by several men described their arrival:\n“Men knocked on the door […] around 10 pm, we were all sleeping. I woke up and\nopened the door. I was only wearing a loincloth. When I opened the door, four men\nbrutally entered the house without my permission. They were wearing black jackets\nwith long sleeves […], trousers, and black hoods. They were wearing gloves and\nblack military boots. They had long rifles, like Kalachnikovs”.288\n(c)     Types of sexual violence\n374. The majority of sexual violence committed in 2017 and 2018 against women were\nmostly rape, sometimes collective rape, under threat, coercion and/or control of one or\nseveral men.289 Other forms of physical violence against women and their families often\naccompanied these rapes.290 Victims explained to the Commission how they were raped:\n“After the slaps I received, I was half unconscious and I could not even scream\nanymore. I fought with my arms, in part because the hand that he had over my mouth\nwas suffocating me. The man in front of me spread my legs with his arms. At the\nsame time, the one behind me was holding me tight so that I could not move. The\nmen penetrated me with their penis one after the other […]”.291\n“He spread my legs very widely and that hurt around the hips. I could not stop\nscreaming because he was hurting me a lot [...] The man held me on the ground by\nmy upper arms with his hands and penetrated my vagina with his penis. [...] He did\nall he could to hold me still [...]”.292\n375. Several victims also reported to the Commission the death threats profferred against\nthem by the perpretrators, either during the rapes to stop them from fighting back, or after\nthe rape to intimidate them so that they do not report it.293 Two women who were raped\ntold the Commission:\n“[The man] took a granade and put it on my chest. He told me: ‘We are going to\ndetonate it if you continue to scream’.”294\n“As he left, the aggressor told me: ‘If you denounce me, […], you will see, I will\ncome back and cut you in pieces’.”295\n376. The sexual violence committed against men in 2017 and 2018 include cuts and\ninjections on the genital parts, as well as stretches of testes, causing severe pains.296 In all\ncases, these men were forced to partially or totally disrobe and to stay naked during\nprolonged periods while being interrogated or subjected to other forms of torture and cruel,\ninhumane or degrading treatment.297\n(d)     Operating modes\n377. Sexual violence against women has, for the most part, been committed during\nnocturnal raids specifically targeting their household. The perpetrators seem to have taken\ngreat care making their identification very difficult, such as the nocturnal attacks298 and in\nsome cases by wearing hoods.299\n378. Generally, the perpetrators entered the home of the victims while the persons in the\nhouse were already sleeping. One or several assailants then attacked the women who were\npresent. Sometimes, the women were alone with their children. One of them testified:\n“[…] around midnight, I heard knocks […] since I was home alone with the kids, I\ndid not go out to see what was happening […] two men [...] forced the door open.\n[…] I came out of my room running and screaming: “Do not kill my children!”.\nThey responded: ‘You’re the one we are looking for’ […]”.300\n379. When the spouses or other men in the family were present, they were generally\nsubjected to violence or taken away from the house. In several cases, they disappeared,\nprobably having been abducted. The women who testified about such abductions do not\nknow the fate of their relatives nor the place where they are. There is ground to fear that\nthese persons are victims of forced disappearance.301\n380. Many of these victims and their families had been previously harassed or spied on\nby Imbonerakure, either because they wanted to recruit the men within CNDD-FDD, or\nbecause of their presumed opposition to the Government.302 A victim told the Commission:\n“[Even]if during the day everything went well for us, people came to scare us during\nthe night, knocking on the door, walking around the house while making noise, etc.\n[…] After around two months of nocturnal harassment, men came at around\nmidnight and […] I was raped so violently that I had to be hospitalised. My husband\n[…] was kidnapped, and our house looted”.303\n381. Sexual violence against men have been committed during their detention in order to\nforce them to speak, mainly in the places that are under the responsibility of SNR.304\n(e)     Impunity\n382. According to statements collected by the Commission from victims, witnesses and\nlawyers, women subjected to sexual violence rarely seek justice because they often lack\nsupport from close family members and friends. Out of shame, most of them choose to\nremain silent in order to keep their ordeal secret.305 Moreover, the lack of trust in the judicial\nsystem,306 difficulties accessing legal advice and the need to produce a medical certificate\nin order to initiate legal proceedings constitute additional obstacles to filing complaints.307\nIn the case of sexual violence perpetrated by state agents or people linked to the ruling\nparty, these obstacles are even greater.308 The victims often fear reprisals if they denounce\nthe perpetrators who are perceived as benefitting from absolute impunity.309 One victim\nputs it as follows:\n“I did not take any steps towards filing a complaint in Burundi. This would not work\nin Burundi. A complaint will achieve nothing when those causing you harm are\nImbonerakure. Very rarely do people file a complaint, especially if the perpetrator\nis an Imbonerakure. The mere fact of denouncing such a person is considered a\ncrime [by the authorities]. Authorities before whom a complaint against\nImbonerakure is filed would usually report it back to Imbonerakure. This can result\ninto one’s family members having problems”.310\n383. Nonetheless, some victims did seek help311 from local authorities at the\nneighbourhood, colline, zone or commune level, but none of the local administrative\nrepresentatives informed them of their rights, including their right to effective remedy in\norder to obtain redress or on the procedure to follow in order to file a complaint. Worse\nstill, a woman testified about facing retaliation for having reported one of her aggressors\nwho was an Imbonerakure to a local authority. The latter ordered her arrest and the police\ndetained her for a few days, with no access to food or drinks. She subsequently received\nthreats from her aggressor:\n“I went to the chef de zone to file a complaint and report that I had recognized one\nof the attackers […], the leader of Imbonerakure in the zone […] The chef de zone\nsaid he [the leader of Imbonerakure] could not be responsible and called the police\nwho were in an office next door. He rebuked me saying: ‘You are painting a negative\nimage of Imbonerakure. In fact, I think you are a supporter of Rwasa’ […] The day\nI was released, the chef de zone and the leader of Imbonerakure […] warned me\nthat they would kill me if I went on recounting what had happened”.312\n384. The Commission noted that, in relation to cases of sexual violence committed by\nState agents or Imbonerakure, the impunity falls within a wider context in which, despite\nwidespread sexual and gender-based violence across the country,313 legal proceedings\ninitiated against the perpetrators of these acts very seldomly succeed.314 Given that the\nprospects for victims to obtain reparation are minimal, few of them are ready to start legal\nproceedings which could, on the one hand endanger them because of the absence of specific\nvictim protection measures, and on the other hand could lead to their stigmatisation within\ntheir own community. Since 2015, the impunity was exacerbated due to the obstacles faced\nby human rights organisations and other structures capable of providing comprehensive\ncare for victims, particularly in assisting them in legal proceedings.315\n(f)     Consequences of sexual violence on victims and their families\n385. Sexual violence is a source of intense physical and mental suffering for the victims,\nsome of whom are persistently or even permanently affected. Victims of sexual violence\ninterviewed by the Commission suffered, amongst other things, from infections and\nswelling around their genitals, internal injuries, breathing difficulties, difficulty passing\nurine, and pain and injuries due to the physical violence. One victim testified:\n“My spine was no longer stable. Since the rape, […] I am always in pain. I cannot\neven carry a ten-kilo weight anymore. When I am unwell, I cannot attend food\ndistribution in person; I send the children. It is only with drugs that I survive. I\ncontinue to receive treatment for my back. It is very difficult not to think about what\nhappened”.316\n386. Men mostly reported pain and swelling in their genitals that prevented them from\nwalking or sitting, issues linked to incontinence and erectile dysfunction.317 Some victims\nhave contracted sexually transmitted diseases and many have different forms of trauma and\npsychological disorder.318 Several victims reported that they passed out during or after the\nassault, or that they felt that they were no longer present during the rape,319 which indicates\nacute suffering which, for both physical and mental reasons, leads to loss of consciousness\nor dissociation – the feeling that one is no longer attached to his or her body. Most victims\nof sexual violence were afraid of being killed and/or worried for the well-being of their\nloved ones.\n387. Lack of access to proper medical care exacerbates these consequences. Often,\nvictims in detention do not request treatment as they are still under their oppressors’\ncontrol.320 Most women who were not in detention when they were sexually abused did not\nreceive any treatment in Burundi, or did so belatedly or inadequately. Some of the victims\nreported leaving the country immediately after their rape or going to medical centres late\nbecause they were afraid. The majority of interviewees did not know the type of care they\nneeded or how to access it. They did not appear to have received detailed information when\nthey went to healthcare centres that did not specialize in the treatment of victims of sexual\nviolence. Victims did not receive emergency contraceptive treatment despite the fact that\nabortion remains illegal in Burundi, except in cases of immediate danger to the mother.321\nConsequently, some rape victims had unwanted pregnancies.322\n388. Sexual violence also has a significant impact on the victims’ families and, more\ngenerally, on their social relations. Many of them find it difficult to have or maintain\nintimate and sexual relations with their spouses.323 Others reported feelings of guilt and\nshame because they were unable to defend themselves against their attackers, as well as\nfeelings of humiliation when the rape occurred in the presence of their loved ones,\nespecially their children.324\n389. Several of the victims interviewed by the Commission reported that sexual violence\nwas the trigger that drove them to flee. They said they no longer felt safe in Burundi,\nespecially since some of them were harassed and threatened by the alleged perpetrators. In\nsome cases, they first sought protection from family members or friends living in Burundi.\nMost women fled without their spouse but with several dependent children. Some women\nreported that, while on the run, being separated from children whom they were never\nreunited with.325 Often, even after fleeing to neighbouring countries, people do not feel safe.\nSeveral people interviewed by the Commission expressed feeling under continuous threat\ndue to the possibility that their attackers, or others acting on behalf of the Government of\nBurundi, may find them in the refugee camps where they are located.326"},{"id":"a-hrc-39-crp-1-p0005","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"5","seq":38,"section":"2. Right to liberty and security of the person","text":"Public Freedoms\n390. As in its previous report,327 this year, the Commission documented numerous\nviolations of public freedoms, in particular the freedoms of expression, association,\nassembly and of movement. These violations are part of a more general context of\nregimenting and controlling the population: with the aim of countering any criticism or\nopposition to Government’s and ruling party’s policies. .\n(a) Freedom of Expression\n391. Most of the violations and attacks on freedom of expression documented by the\nCommission since September 2017 took place in the context of the referendum campaign.\nAs in previous years, the Commission noted that it was difficult to voice an opinion contrary\nto that of the Government and of the ruling party and that doing so unfailingly exposed one\nto risks of human rights violations, whether or not they were member of an opposition\npolitical party. The media and journalists also continued to be subject to control and\npersecution by the authorities and Imbonerakure, when they sought to cover a story in a\nmanner deemed hostile to the Government. The Commission also noted hate speech\nconstituting incitement to hostility or violence from State officials, including the President\nof the Republic himself, and from CNDD-FDD. These calls were mainly directed against\nthose likely to call a “no” vote during the constitutional referendum. The Commission has\nnoted a few calls for armed struggle from members of the political opposition.\n(i) General context conducive to violations of freedom of expression\n392. In its previous report, the Commission highlighted that “the repression carried out\nby the Government could entirely [...] be analysed from the angle of freedom of\nexpression”.328 This observation was confirmed during the period covered by the present\nreport, in particular during the referendum campaign. In this context, persons – members\nor non-members of opposition political parties – who expressed criticism of the draft\nrevision of the Constitution or disapproved of it, urged others not to take part in the\nreferendum or to register for electoral lists were particularly targeted by the administration,\nthe SNR, the police and Imbonerakure and were, in fact, victims of various human rights\nviolations.329 A witness interviewed by the Commission reported:\n“A group of five Imbonerakure came to my house [...] [The chief of Imbonerakure]\nasked: ‘Why did you come back and yet you refuse to vote for Pierre Nkurunziza?’\nHe also said to me: ‘If this time you do not cast a “yes” vote in favour of the\namendment of the Constitution or if you vote “no”, we will eliminate you’. [X], who\nwas also there, replied: ‘I only vote if I want to and, if I do indeed vote, I can vote\n“yes” or “no”; but I will not vote under your command’. They did not say or do\nanything that day. They stayed for about 30 minutes and left. It was only three days\nlater that they killed [X].” 330\n393. In this regard, instructions were given by several authorities, including the President\nof the Republic and CNDD-FDD officials at all levels.331 Despite this, the coalition Amizero\ny’Abarundi (Hope of Burundians), which brings together several opposition parties based\nin Burundi under the leadership of Agathon Rwasa, was able to organize rallies across the\ncountry during the referendum campaign, but many among those who participated in these\nrallies and who spoke in favour of “no” have suffered human rights violations.332 A person\ninterviewed by the Commission reported:\n“[Agathon] Rwasa’s position since the beginning of the campaign is not surprising\n[...] because you cannot deprive a people that has tasted democracy of the freedom\nof expression. There was a strong civil society in Burundi and it cannot be destroyed\nso quickly. The Government did not think the opposition was going to campaign. In\nresponse, there have been several arrests and cases of torture. It targeted members\nof the coalition”. 333\n394. In its previous report,334 the Commission had also reported violations of freedom of\nexpression within CNDD-FDD itself, particularly in early 2015 when the party split over\nthe designation of Pierre Nkurunziza as the single candidate for the presidential election.\nMembers of the party, identified as « frondeurs » because they were opposed to the Head\nof State and to those who supported him in the CNDD-FDD governing bodies, had been\nrelieved from office and persecuted.\n395. The speech given by the Head of State on Veterans Day on 18 November 2017 in\nCibitoke was perceived as highlighting his desire to suppress any hint of internal opposition\nahead of the referendum intended to amend the Constitution and thus prevent a repetition\nof the 2015 experience. On this occasion, the Head of State declared: “The first\nImbonerakure is the Almighty God […] If you provoke a disagreement with Imbonerakure,\nyou disagree with the one who created them, especially when there is no reason to do so.\nAnd you engage in a fight […] Do not let any brave person derail; straighten them in time!\nHere I know a few who are starting to derail. Be vigilant within the party, straighten them\nso that they do not derail before our very eyes like the last time […] We declare zero\ntolerance from 2018. The recalcitrants must be driven out as quickly as possible, without\nwasting time and warning them once, twice or three times. I already know some\nrecalcitrants and I am keeping a watchful eye on them […] Do not joke; do not joke when\nthings get serious. All stiff-necked people, goodbye! We will issue your papers, your\nlaissez-passer! May we not go through the 2015 experience again: people revolting before\nour very eyes. It’s over! […]”.335 The Commission has received no testimony of persecution\nwithin the CNDD-FDD directly related to this speech. It nevertheless considers the latter\nto be an incitement to hostility and violence.336\n(ii) Violations of freedom of expression in the media\n396. In its previous report,337 the Commission noted a sharp increase in pressure and\ncontrol by Burundian authorities particularly over the private media, as well as numerous\ncases of Burundian journalists harassed, threatened, assaulted, arrested and arbitrarily\ndetained. There has been little change since September 2017. Burundi ranks 159 th in the\n2018 world press freedom ranking established by Reporters Without Borders (RSF).338\nAlthough the country has moved up one place since 2017, it is far from having regained the\n14 places lost since 2015.\n397. The main independent media, shut down in May 2015, remain closed to this day\nwith the main ones now officially banned from broadcasting. The National Communication\nCouncil (CNC), the state media monitoring body in Burundi, continues to exercise close\nsurveillance over all media outlets. In addition, a large number of journalists working for\nindependent media remain in exile. Others have joined them this year and those still\noperating in Burundi continue to face pressure, intimidation and restrictions from local\nauthorities, the SNR and Imbonerakure.\n398. A press bill was presented to the Ministers’ Council on 28 September 2017 and\nadopted unanimously by the National Assembly on 19 April 2018. To the best of the\nCommission’s knowledge, this new legislation has not been promulgated to date. The\nCommission could not get a copy of the bill to analyse it. It, however, notes that the law\ngoverning the press had already been amended in 2015 in response to criticisms of the\nprevious law adopted in 2013.339\na.   Media control and suspension\n399. During the period covered by the present report, the CNC maintained sanctions\nagainst the media and journalists. As in previous years, the Commission remains concerned\nabout the CNC’s dependence on the Executive.340 The appointment on 8 June 2018 by\npresidential decree of Nestor Bankumukunzi to replace the former president of the CNC,\nRamadhan Karenga, is proof of this subjugation. Formerly Minister of Posts, Information\nTechnology, Communication and Media, Mr. Bankumukunzi was unanimously elected\nhead of the CNC by its members on 14 June 2018.\n400. Subjugation of the CNC to the Executive was further reinforced by the\npromulgation, on 8 March 2018, of an organic law “amending Law no. 1/03 of 24 January\n2013 on the mission, composition, organisation and the functioning of the National\nCommunication Council (CNC)”. This new legislation confirms the appointment of the 15\nmembers of the CNC “by the President of the Republic in consultation with the Vice-\nPresidents”341 and specifies that, among its members, three are ministries representatives,\none of whom represents the Ministry of Public Security.342\n401. More ominous for the exercise of the freedom of expression is the new organic law\nthat significantly expands CNC’s jurisdiction which now covers all “media” understood as\n“any organ or company which makes information available to the public in the form of\nsigns, written signals, images, sounds or messages of any kind which do not have the\ncharacter of a private correspondence”.343 This covers both the traditional media – print and\naudio-visual media – as well as “communication companies and companies on the\nInternet”, cinematographic works, advertising or “bookstores that sell or make media\ncontent available to the public”.344 Are also under CNC’s control “all international or\nforeign media published or broadcast on the national territory, regardless of how it is made\navailable to the public”.345 In addition, the CNC makes assessments of applications for\nprofessional press cards, no longer just for journalists as it did before, but also for\n“information technicians, filmmakers and collaborators directly associated with the\nprofession”.346 It also “inspects applications for journalists’ accreditation”.347\n402. However, the CNC did not wait for this law to be passed before it exercised its\nauthority over the independent media. On 28 September 2017, through its Vice-President\nAimée-Divine Niyokwizigirwa, the CNC announced the revocation of operating licenses\nfor more than a dozen media348 including Radio publique africaine (RPA), Radio Bonesha\nFM, Radio-Télévision Renaissance which, following their demolition during the failed\ncoup in May 2015, had been closed on the orders of the Attorney General of the Republic\nso as to carry out investigations on the circumstances of these destructions and to determine\ntheir responsibility, or lack thereof, in disseminating messages from the rebels. The vice-\npresident of the CNC declared that the revocation of operating licenses was motivated by\nthese media’s breach of their terms of service and their “failure to settle their legal case on\ntime”. However, the vice-president of the CNC, interviewed by RSF, was unable to indicate\nthe stage where the legal proceedings against them were.349 To the knowledge of the\nCommission, the results of the investigations carried out by the Attorney General of the\nRepublic are still unknown to date.\n403. On 28 September 2017, the CNC suspended CCIB FM + chamber of commerce and\nindustry radio for a three-month period starting on 2 October 2017, after the publication on\n18 September 2017 of an editorial which deplored the silence of the Burundian Government\nafter the massacre of Burundian refugees in Kamanyola in the DRC. The CNC deemed this\neditorial unethical and contrary to the law governing the press in Burundi. The radio’s\ndirector Eddy Claude Nininahazwe was sacked on 6 October 2017 after his resignation the\nday before. The radio’s suspension was lifted by the CNC two months later.350\n404. Suspension measures have also targeted sections of certain media, although their\npublication was not prohibited. On 10 April 2018, the “comments” section of the Iwacu site\nwas suspended for three months, some of the comments that had been published there\nbeing, according to the CNC, “unbalanced” and their sources “not rigorously verified”.351\n405. Suspension measures also affected a journalist and two international media. On 26\nDecember 2017, the CNC suspended journalist Égide Nduwimana, who worked for the\nnewspaper Igire, for violating the law governing the press in Burundi by disseminating\ninformation and comments considered unbalanced and whose sources were not rigorously\nverified, on the demonstrations organized in support of Burundi's decision to withdraw\nfrom the International Criminal Court. The journalist was also accused of treating the\nnational heroes Prince Rwagasore and President Melchior Ndadaye “as impostors”. One\nperson questioned by the Commission said:\n“He spoke of these heroes […] whose names are used. He was attacked by a pro-\ngovernment association, which filed a complaint with the CNC. While this journalist\n[…] consulted all parties before producing his paper, [the CNC suspended] him for\nthree months. Shortly thereafter, they reduced his suspension to two months”.352\n406. In the context of the referendum campaign, the CNC also suspended, on 4 May 2018,\nactivities of the British Broadcasting Corporation (BBC) and of the Voice of America\n(VOA) for a six-month period from 7 May 2018.353 On 30 April 2018, the Burundian\nGovernment issued a press release deploring the fact that the BBC interviewed Pierre-\nClaver Mbonimpa,354 “someone wanted on an international arrest warrant issued by the\nBurundian judiciary for participation in deadly violence” and called the CNC to “assume\nits responsibilities vis-à-vis the BBC”.355 In the case of VOA, the radio was accused of\nhaving disseminated “very biased” information and of having hired a journalist “wanted by\nthe Burundian justice”.356 During the plenary session that the CNC held from 4 to 6 July\n2018 in Makamba, its president affirmed that the two radios had apologized but that their\nrepresentatives had not yet travelled to Burundi to discuss the terms of their reopening.357\n407. During the past year, the CNC has also issued warnings to certain media. On 16\nMarch 2018, the CNC sent a warning to the BBC for a report on the decision by CNDD-\nFDD’s central committee to grant the title of “Visionary” to President Nkurunziza,\nconsidered unbalanced and whose sources had allegedly not been verified.358 On 18 April\n2018, the CNC sent a warning to Radio Culture for not having sought the advice of the\nMinistries of the Interior and Public Security as well as that of the president of CNDD-\nFDD’s youth league concerning a report on the referendum.359 On the same day, a warning\nwas sent to the newspapers Iwacu and Le Renouveau for having published notices in\nEnglish.360 Meanwhile on 4 May 2018, Radio France Internationale (RFI) received a\n“warning” for a “treatment deemed tendentious and untrue” after having stated in two\nreports that “the decree fixing the campaign calendar for the constitutional referendum of\n17 May 2018 contained a provision that anyone who expressed a negative vote is liable to\nharassment, prosecution and imprisonment”.361 Two Burundian radio stations, Radio\nIsanganiro and CCIB FM +, also received a warning from the CNC about a lack of\n“rigorous verification of sources of information”.362 At its plenary session held in July 2018\nin Makamba, the CNC threatened RFI and Iwacu newspaper with sanctions if they persisted\nin giving “unbalanced and shallow” information363.\n408. The CNC’s tight media control has a direct consequence on Burundians’ access to\nindependent media, capable of processing information in an objective and impartial\nmanner. A journalist thus stressed:\n“State radio RTNB has no independence. There is no independent media in Burundi.\nEven the population says that radio Isanganiro [reopened in February 2016] is no\nlonger the same [...] You will never find information from opposition parties freely\nbroadcased. Members of the opposition are forced to give information clandestinely.\nBut other parties close to power give information whenever they want to.” 364\nA witness confirmed:\n“Freedom of expression is not guaranteed. Private radio stations were destroyed.\nThe authorities subsequently ordered the opening of some of them […] But later, I\nheard that radio Isanganiro was not free to speak. Journalists at these stations are\nforced to rectify information before broadcasting it”.365\nAnother journalist stated:\n“There are established radios such as Isanganiro and Radio Rema, the latter being\nclose to the current Government. There is also RTNB, the official station […]. The\npopulation is stuck. People are forced to listen to the radio via WhatsApp. But not\neveryone has access to WhatsApp. There is RFI and VOA that broadcast in Kirundi.\nPeople in the provinces lack media coverage. VOA has regional correspondents in\nfour or five provinces. But I must say that listening to the news broadcast via\nWhatsApp is still dangerous”.366\n409. This last testimony shows that control is also exercised over the population to ensure\nthat they do not listen to the media deemed hostile to the Government. A witness insisted\non this role assumed locally by Imbonerakure:\n“If someone is heard listening to broadcasters such as Inzamba, Humura, Bonesha\nor Isanganiro, Imbonerakure [the witness refers to Imbonerakure from a certain\ncommune] can even kill them”.367\nOne victim also recounted: “We were attacked [in] 2017 […] by Imbonerakure who\ncame home. What happened was that [X] […] was listening to Humura radio on his\nphone. […] He did not realise he was being followed by Imbonerakure […]. As soon\nas [X] arrived, Imbonerakure came to our house. [X] fled through the window,\nwhich was without wire mesh. […] As they did not find [X], they hit and slapped me\n[…] they left threatening: ‘Go get [X], otherwise you will see what will happen to\nyou tomorro’.”368\nb.         Obstacles, pressures, threats and violence against journalists\n410. Media control also has an impact on the ability of journalists to work freely. A\nwitness interviewed by the Commission noted:\n“Only journalists who are close to power can speak freely”.369\n411. The latter are however controlled too. A witness reported on the internal workings\nof the RTNB:\n“When a reporter brought in a [reportage], [the management] sorted the\ninformation out [to determine what could] be published”.370\n412. In general, the content of the information gathered and published by journalists is\nclosely monitored. The cases documented this year by the Commission371 supplement those\npresented in its previous report372 about journalists who were worried after publishing\ninformation deemed to be contrary to the policies of the Government and of the CNDD-\nFDD. A journalist testified:\n“To be a good journalist in Burundi, one must not delve too much. When the police\nand military spokespersons do not speak on a subject, it is dangerous to speak about\nit. Information that they do not give should not be disseminated. One must always\nseek balance. It’s not easy to practice the profession of journalist in Burundi\nnowadays”.373\n413. As he was taking up his position at the helm of the CNC, Mr. Bankumukunzi\ndeclared that, during the period of his leadership, granting journalists a press card would be\nCNC’s “first priority” in the short term.374 This led to fears of increased control on\njournalists by this body dependent on the Executive.\n414. During the period covered by the present report, the Commission also continued to\nreport cases of journalists subjected to restrictions, pressure and threats, as well as arrests,\narbitrary detentions and physical violence.\ni.    Restrictions, pressure and threats against journalists\n415. In March 2018, the Office of the Prosecutor in Mukaza summoned a BBC Africa\njournalist for a report published under the title “Visionary”, a designation granted to\nPresident Nkurunziza by the CNDD-FDD’s leadership.375 Accused of contempt of the Head\nof State, the journalist was questioned for almost three hours on this report. She was accused\nof relaying information that could divide Burundians and cause further violence in the\ncountry. Previously, on 16 March 2018, the same journalist had received a warning letter\nfrom the CNC regarding the same report.376 On March 30, 2018, in a statement published\nabout the BBC work, the Burundian Government cited the BBC journalist among those\nwho lacked “journalistic ethics and professional conduct”.377\nii.   Arbitrary arrests and detentions of journalists\n416. In 2017, two journalists were detained at a police station in a province in the north\nof Bujumbura after a field trip to look into the arrest of activists close to Agathon Rwasa\nwho had been accused of campaigning for the “no” vote to the constitutional referendum.\nTheir work equipment was initially confiscated before being handed to them when they left\nthe police station.378\n417. The Commission has also been informed of the case of a journalist arrested in 2017\nbecause of his or her activities.379\niii. Violence against journalists\n418. In 2018, a journalist fought with a group of Imbonerakure. During the altercation,\nImbonerakure specifically accused him of disseminating false information.380\n419. On 27 August 2018, Alain-Majesté Barenga, Bella Gloria Kimana and Alain\nNiyomucamanza, three journalists from the local radio station “Radio Culture” were hit by\npolice officers in the Ngagara zone of Ntahangwa commune in Bujumbura mairie. They\nwent to this site to report on a land dispute between residents and the local administration\nof a neighbourhood in that area.381 The following day, the CNC spoke about the case. Its\npresident, Nestor Bankumukunzi, declared: “A journalist on Burundian soil has the right to\nthe security of his or her person and material”. The police spokesman nevertheless\ndismissed the allegations382 and to the Commission’s best knowledge, no sanctions have\nbeen taken against the police officers involved.383\n420. In this context of regular obstructions to journalists’ work and violations against\nthem, the Commission continued to interview and meet journalists who had to flee\nBurundi.384\n(iii)          Incitement to discrimination, hostility and violence\n421. The International Covenant on Civil and Political Rights condemns on the one hand\nany propaganda in favour of war and on the other hand “any appeal to national, racial or\nreligious hatred which constitutes an incitement to discrimination, hostility or violence”.385\nAs in its previous report,386 the Commission noted several messages, speeches, statements\nand songs that fall into one or the other category.\na.      Calls for armed struggle by leaders or armed opposition groups\n422. During the period covered by the present report, the Commission has not heard of\nany calls for armed struggle by armed opposition groups. It is clear, however, that this type\nof struggle remains their main objective since their creation, as already established by the\nCommission.387\n423. Regarding opposition political parties, Jérémie Minani, the commissioner\nresponsible for communication and public relations of the Conseil national pour le respect\nde l'Accord d'Arusha and la réconciliation au Burundi (CNARED),388 published on 3 April\n2018 a call for armed struggle on Twitter which stated: “Faced with an irrational regime\nwhich has closed the door on all peaceful solutions, I publicly call on Burundians to take\nup arms to defend our democracy. It depends on our survival and that of Burundi’s\ndemocracy”.389 On the same day, he posted a text on Facebook in which he said: “Who will\nsave Burundi’s democracy? The game of electoral pressure seems to be over. Faced with\nan irrational regime that is in the logic of total denial of the crisis and inclusive negotiations,\ntwo options for preventing the regime from burying democracy in Burundi are available: 1.\nA total embargo initiated by States in the region (which seems unlikely to me), 2. a military\ncoup or the use of military force to neutralize the Burundian regime. Without at least one\nof these two options, opposition statements, calls to reason from the international\ncommunity, calls for boycotting the votes or voting no will not change anything; the Arusha\nAgreement and the ensuing Constitution will disappear on 17 May 2018 and all chances of\na negotiated solution to the Burundian crisis will vanish. Dear compatriots, we must\nunderstand that our democracy is in danger and it is up to us, the Burundian people, to\ndefend it. Let’s take up arms and defend our democracy, Pierre Nkurunziza has closed the\ndoor to all peaceful solutions”.390\n424. On 5 April 2018, Jérémie Minani reiterated his call for armed resistance on Twitter:\n“Since April 2015, @pnkurunziza has ordered mass atrocities that have killed more than\n6,000 people simply because they were opposed to his indefinite rule. As he has closed the\ndoor on any peaceful solution, now is the time to confront him militarily”.391 On 19 July\n2018, Jérémie Minani posted a new message on Twitter in which he recalled: “My overall\n382 See: http://www.isanganiro.org/spip.php?article15052.\n383 JI-055.\n384 QI-264, TI-149.\n385 Article 20 (1) and (2) of the Pact.\n386 A/HRC/36/CRP.1, para. 538 to 560.\n387 Ibid., para. 543 and 544.\n388 Has since become the Conseil national pour la restauration de l'Accord d'Arusha and la\nréconciliation au Burundi (National Council for the Restoration of the Arusha Agreement and\nReconciliation in Burundi).\n389 See: https://twitter.com/minanijeremie/status/981243357572882433.\n390 See: https://www.facebook.com/minani4president/photos/\na.594020177407515.1073741829.29661445314757/1175410859268441/?type=3.\n391 See: https://twitter.com/minanijeremie/status/981804215021514752.\nobjective remains a clean slate of the Burundian political system which is the cause of all\nour misfortunes”.392\n425. In a Jeune Afrique interview of CNARED’s spokesperson Pancrace Cimpaye on 2\nMay 2018, there was no call to take up arms against the Government. He however stressed\nthat Burundi’s current political and diplomatic deadlock is at risk of pushing young people\nto join armed opposition groups. “Once all the doors of negotiations are closed,” he said,\nthe risk is that young opponents of the regime head into the bush and use violence and\nweapons to push for negotiations and a new balance of power […] You know, when young\npeople decide to go to the bush, they do not require permission. When the time comes,\nCNARED will unveil its strategy. Nkurunziza will cross the red line on 17 May [the day of\nthe constitutional referendum]. Therefore, I do not know what the coalition will decide as\na result”.393 In a press release published on 24 April 2018 CNARED recalled, “After the\nreferendum of 17 May 2018, there will no longer be any room for negotiation”.394\n426. On 8 June 2018, the Coordination Committee of the Burundian Citizen Forum\npublished a declaration395 signed by Jean Minani, representative of opposition political\nparties and organisations and president of CNARED; Pierre Claver Mbonimpa,\nrepresentative of civil society in exile and president of APRODH; Marie Louise Baricako,\nrepresentative of Women’s Organisations in exile and president of the MFFPS; Venant\nBigemintwaza, representative of the Burundian diaspora gathered in the Burundian Citizen\nForum and; Alexandre Niyungeko, representative of organisations of journalists in exile\nand president of the Burundian Union of Journalists. They called upon Burundian people\n“to a revolution and a new national vision for the restoration of the Arusha Agreement and\nthe 2005 Constitution”. This declaration may not qualify as a clear call for armed struggle,\nbut the use of revolutionary terminology does cast serious doubts on the possible use of\nviolence.\nb.   Calls for national, racial or religious hatred which constitute an incitement to\ndiscrimination, hostility or violence\n427. As in the first term of its mandate, the Commission documented hate-speech\nconstituting incitment to hostility or violence against opponents of the Government. Since\nSeptember 2017, the Commission has mainly identified hate speeches or messages from\nBurundian state officials or CNDD-FDD representatives. As in previous years, these\ndeclarations, primarily targeted opponents of the Ggovernment and CNDD-FDD’s party\nline. Thus, in a tweet dated of 29 September 2017, the Ambassador of Burundi at the\nAfrican Union described as “vampires” the leaders of Burundian civil society organisations\nwho came to Geneva to attend the session of the Human Rights Council during which the\nCommission of Inquiry presented its previous report.396 From the end of 2017 and the\nannouncement of the constitutional referendum in May 2018, the opponents targeted by the\nauthors of hate speech were mainly those campaigning or likely to campaign against the\nconstitutional review, as well as any person likely to vote “no” during the constitutional\nreferendum.\n428. As previously stated,397 on 18 November 2017, President Nkurunziza held a speech\nin Cibitoke to mark Veterans Day,398 in which he threatened any opponent of the CNDD-\nFDD party line, in particular any potential “rebels”, to be “straightened”.\n429. On 12 December 2017, the Head of State officially launched a campaign to explain\nthe new Constitution draft put to the referendum in May 2018. On this occasion, he\nthreatened, in more or less colourful terms, any potential opposition to the holding of the\nreferendum. “We take this opportunity,” he stated, “to warn all those who would try to\ntorpedo this [Constitution] project, through words or action […] This means that all leaders\nat the colline, neighbourhood, commune levels or members of municipal councils\ndisplaying carelessness will answer for it in front of their hierarchical superiors […] And\nthat stealing a drum is one thing, finding where to play it is another. A word to the wise\n(there is none so deaf as he who will not hear) and let those with eyes see! […] We remind\nyou that anyone who does not love their country is recognized through their actions aimed\nat destabilizing and destroying, through carelessness, spreading rumours and lies in the\ncountry, tarnishing the image of his native land, denying the ongoing progress, deceiving\nothers and other bad behaviours that I cannot mention here for lack of time, like sowing\nhatred between brothers. You have to keep an eye out for this kind of people day and night.\nAs the saying goes “when dancing with your rival you must not close your eyes” [...]”.399\n430. President Nkurunziza reiterated these threats on 2 May 2018 in a speech delivered\nin Gitega at the launch of the referendum campaign. He then declared: “Whether a\nBurundian or a foreigner, whoever stands in the way of this election, I tell you, he will have\nto deal with God, and God, who is in heaven, is witness here. But I know that there are\npeople who refuse to hear these messages; let them just try”.400 The reference to God was\ntaken up by the wife of the Head of State, Denise Nkurunziza, during a “prayer crusade”\norganized in December 2017 during which she particularly warned: “We must respect\nauthority, authority must be respected! Know that you are condemned when an authority\ngets angry: when he or she [the authority] prays that a curse falls on you!”.401\n431. More generally, the speeches of the President of the Republic were relayed across\nthe country in more direct terms and accompanied by clear threats of violence by officials\nat all levels of the State apparatus and of CNDD-FDD. Thus, according to the Iteka League,\nthe Executive Secretary in charge of leagues affiliated to the ruling party, Sylvestre\nNdayizeye, held a public meeting on 14 December 2017 in the commune of Mpanda\n(Bubanza province) bringing together members of CNDD-FDD leagues. He allegedly\nencouraged Imbonerakure to track down all suspects of obstructing the process of amending\nthe Constitution and the referendum, as well as those who refused to help organize the 2020\nelections. It was reported that he would have ordered their elimination, including those from\nthe ranks of the Government.402\n432. In a Voice of America online article published on 18 January 2018, the following\nwords of the First Vice-President were recounted: “Opponents who campaign for the “no”\nvote must be arrested because, for us, and based on the instructions of the Head of State,\nthese are rebels”.403 In a video extract posted on social networks on 30 January 2018,\nRévocat Ruberandinzi, CNDD-FDD leader and secretary at the commune level, is seen\nexplaining to his audience: “If you followed the message [of the President] whoever goes\nagainst this project would have crossed the red line, which means that he would have\ndeparted from the white line, the path of of God’s children. He would have left the path of\nthe saints. We therefore ask you to be our observers in your neighbourhoods and on your\ncollines. […] They will have to be monitored every moment and everywhere. Whoever is\ncaught teaching the “no” vote, you must arrest him and bring him to us. If you teach\nsomeone to vote “no”, beware!”.404 On 13 February 2018, the administrator of the commune\nof Gashoho (province of Muyinga), Désiré Bigirimana, told CNDD-FDD activists who\nwere gathered at the party headquarters: “If they cheated on us in 2015, now we know the\ntruth. Whoever comes telling you anything else other than a “yes” vote during the\nreferendum, or anything other than what President Pierre Nkurunziza says will have to be\nlynched. Is that clear? Call me only after you have tied him or her up”.405\n433. On 13 February 2018, in an interview that circulated on social media,406 the\nspokesperson for the Ministry of Public Security, Pierre Nkurikiye, formulated “a warning,\nan admonition against anyone who by his action or his verb will try to obstruct this process”,\nstating that this person “will be immediately apprehended and brought to justice”, and that\nthis “warning is addressed particularly to young people who are deceived by certain\npoliticians”. He proceeded with threats, referring to the bloody police repression at the start\nof the crisis: “Young people should review our country’s recent history, especially the 2015\nevents. The police have received very clear orders. They have been asked to work as\nprofessionally as possible and with the greatest rigor and firmness, of course in accordance\nwith the law.” On 11 April 2018, the Minister of Interior, Pascal Barandagiye, held a\nmeeting in Bujumbura where he said those who would be caught mobilizing people not to\nvote would be punished by law. He also said that whoever should attempt to prevent\nBurundians from going to vote should be rendered harmless and brought before the\ncourts.407\n434. Burundian authorities have taken sanctions against Melchiade Nzopfabarushe, the\npresident of the Association of natives of Kabezi (ANAREKA) and former deputy chief of\nstaff of the President of the Republic who had declared on 28 April 2018, during a meeting\nof CNDD-FDD supporters in Kabezi (Bujumbura province), about opponents of the\nconstitutional referendum: “We have had boats made, we are going to throw them in Lake\nTanganyika. And besides, fish production has not been good lately”. These words were\ncirculated in a video posted on the Internet.408 Disowned the next day by the CNDD-\nFDD,409 Melchiade Nzopfabarushe was heard by the Bujumbura prosecution and charged\nin the process for inciting hatred. On 17 May 2018, Mr. Nzopfabarushe was sentenced by\nMukaza Court of First-Instance (TGI) to three years’ imprisonment and to the payment of\na fine of 600,000 Burundian francs (approximately 342 US dollars). However, his sentence\nwas reduced to four months imprisonment and a one-year suspended sentence on appeal on\n20 June 2018. Once the verdict was pronounced, Mr. Nzopfabarushe was released before\nhe had served his sentence.410\n435. The case of Melchiade Nzopfabarushe remains an isolated occurrence. The\nCommission has identified several instances of incitement to hatred and violence by\nmembers or officials of CNDD-FDD who have neither been sanctioned nor prosecuted. For\ninstance, on 21 April 2018, the organisation SOS Media Burundi reported that the\nprovincial secretary of the CNDD-FDD party in Muyinga had called on Imbonerakure in\nattendance to “castrate the enemy”.411 In a video, a CNDD-FDD official in Rumonge\nprovince said during a meeting: “We were asked to stand up and vote “yes”, to teach the\npopulation how to vote “yes”. In this respect, I would like to warn you that there are other\npeople with different teachings. People who invite citizens to vote against or not to vote.\nWhoever you are, even God will abandon you. If you trust the person who encourages you\nto vote “no” instead of the one who advocates “yes”, you will have signed your death\nwarrant. If this person is arrested tomorrow and reports you, you will be taken away and\nyou will never be seen again”.412\n436. On 4 May 2018, Joseph Ntakarutimana, the deputy secretary-general of CNDD-\nFDD in the Gisuru commune, Ruyigi province, declared on national radio: “As for our\ncommune Gisuru, because we know that you live together with the “Samandari” [mythical\ncharacter], it is you who rub shoulders with them, you know them, listen to them, do not\nabuse them... when the fateful date of 17 [May] comes, do not place yourself on the other\nside of fortune”.413 Similarly, according to witnesses, on 9 May 2018, in Muhuta, in\nRumonge province, Leonidas Mukeshimana, a CNDD-FDD member of Parliament,\nallegedly called the “no” campaigners as bearers of “misfortune” and warned the ‘no’\ncampaigners from opposition parties that they will be hunted down to their last\nrentrenchments. “Abigisha oya tuzobirukako n’ibirenge bishuhe”, he reportedly said, which\nliterally means: “We will run after those who call for a no vote [in the referendum] with all\nour energy”.414\n437. It is also not uncommon to see videos circulating where Imbonerakure chant warrior\nsongs as a show of force. For example, in a video published on 4 May 2018 by France 24,\nGad Niyukuri, Governor of Makamba province leads President Nkurunziza’s supporters in\na song. We hear Imbonerakure members singing: “Nkurunziza has taken over the country,\nhe will not let go! The elections are approaching! All who take the sword will perish by the\nsword!”.415 In its previous report, the Commission also noted songs by Imbonerakure\ninciting hatred and violence against opponents of CNDD-FDD.416\n438. Opponents of constitutional reform have also been repeatedly identified as traitors\nin colonial powers’ employ. Thus, on 10 May 2018, the CNDD-FDD president in\nBujumbura mairie declared on national radio: “To vote in favour of the revised Constitution\nis to wash away contempt and free oneself from the yoke of the colonisers, we have seen\nthe latter in the past, when they ganged up with the followers of the Parti démocrate-\nchrétien (the anti-independence fighters) to deceive the urban population and push them to\nburn vehicles, burn tires, burn markets, knowing full well that many residents of the\nmunicipality move on buses. All this happened while the sponsors had their tickets in their\npockets and their stay already prepared”.417 On 14 May 2018, at a rally in Bujumbura to\nclose the referendum campaign, Évariste Ndayishimiye, the secretary-general of CNDD-\nFDD, said: “I am stating this and I repeat it. Whoever votes “no” will be a traitor in the\nwhite colonizers’ employ. In fact, they are evil. Because to vote “no” is to bring a curse”.\nMr. Ndayishimiye continued his speech in a more threatening tone: “I warn these colonizers\nnot to interfere in the internal affairs of our country [...] Down with colonialism”, he said.\nAnd to hammer: “I warn those who are going to vote “no”, they are enemies of the\ncountry”.418 Évariste Ndayishimiye had already attacked “the Burundian traitors who sold\ntheir country” in a speech made on 16 September 2017 before activists gathered to protest\nagainst the report of this Commission.419 Similarly, on 31 March 2018 during the\ncelebration of International Women’s Rights Day, members of the National Forum of\nWomen allegedly performed songs calling the colonizers, Europeans and opponents of\nPierre Nkurunziza “poisonous snakes who deserve to be beheaded” before the end of 2018.\nThe women gathered that day also allegedly threatened “CNDD-FDD’s enemies” that they\nwould be hung.420\n(b) Freedom of Association\n439. In its previous report421, the Commission highlighted the pressures faced by Civil\nSociety Organisations, in particular those working on human rights issues, as well as\nprosecution, threats and other violations against their members and Human Rights\nDefenders. The situation has not improved since September 2017. Organisations that had\nbeen suspended, deregistered and whose bank accounts had been frozen have not seen their\nsituation change during the period covered by the present report. These associations, most\nof which, were involved in the “Halt-the-third-mandate” movement launched in January\n2015, continue to be perceived by the Burundian Government and CNDD-FDD as affiliated\nwith political opposition. International arrest warrants against their leaders have not been\nlifted. The attitude of the Burundian authorities towards these organisations and their\nmembers not only raises questions about the exercise of the freedom of expression in\nBurundi but more generally about the capacity of independent organisations to operate\nfreely in Burundi.\n440. In this regard, the two laws adopted in January 2017 on national non-profit\nassociations (ASBL) and foreign non-governmental organisations (FNGOs),422 which are\nstill in force, help limit freedom of association in Burundi by considerably strengthening\nthe control by the authorities over these entities’ activities and resources.423 As one witness\nnoted:\n“Today, only associations that agree to cooperate with the ruling party are free. The\nNational Assembly passed a law giving full powers to the Ministry of the Interior to\nsuspend associations. All associations operating today must have the consent of the\nauthorities”.424\nA member of an organisation working in Burundi also testified:\n“Following the law of January 2017, we had to resubmit a request for approval.\n[Once this new submission was made], we were told to do it again […] To resubmit\nour request; we were introduced to someone who should help us resubmit it. Our\nrequest could not succeed without this person. We had to give this person [money].\nAll associations must do the same. It is a mafia system at all levels. Working\nconditions are untenable”.425\n441. The United Nations Country Humanitarian Team stressed in its 2018 Humanitarian\nResponse Plan “administrative or legal restrictions and constraints affect humanitarian\norganisations and limit their operational effectiveness, now and in the future.” Among these\nadministrative constraints, the Humanitarian Response Plan specifically mentioned a\n“random” visa procedure and “the NGO law of January 2017 [which] added an additional\nlayer of difficulty for the partners, introducing considerable uncertainty as to independent\naction with due respect to humanitarian principles”.426 To date, no independent organisation\nhas been able to carry out unhindered work in the collection and analysis of Human Rights\ninformation in Burundi.\n(i) Restrictions on the work of Human Rights Defenders\n442. During the period covered by the present report, the work of Human Rights\nDefenders and of members of Human Rights organisations also continued to be hindered.\n443. Human Rights Defenders were arbitrarily arrested and detained in 2017 and 2018.427\nAccording to several human rights organisations428 and information gathered by the\nCommission,429 on the morning of 21 November 2017, members of the Burundian police,\nunder the command of the police commissioner responsible for Gitega province, came to\nNestor Nibitanga’s home, a former member of the Burundian Association for the Protection\nof Human Rights and Detained Persons (APRODH), in Gitega, and searched his house.\nThey allegedly confiscated working documents from the time Mr. Nibitanga worked for\nAPRODH. The latter was then taken to SNR premises in Gitega where he remained in\ndetention until 22 November before being transferred to the SNR premises in Bujumbura,\nwhere he was allegedly held incommunicado, with no official charge against him and\nwithout access to his family or to a lawyer, until 4 December 2017. According to a witness\nquestioned by the Commission,430 Mr. Nibitanga should have appeared before the Council\nChamber 15 days after his arrest for the latter to rule on the lawfulness of his detention.\nThis, however, did not happen until two months after Mr. Nibitanga’s arrest. He was then\ntransferred to Rumonge prison, South of Bujumbura, where he is still detained. A witness\ncommented:\n“What is surprising is that Nestor was arrested in Gitega, transferred to the Public\nProsecutor’s Office of the Bujumbura Court of Frist-Instnce (TGI) and imprisoned\nin Rumonge. It is unclear why he was tried in Bujumbura when he was arrested in\nGitega which is also where the offense is believed to have been committed. In\naddition, he was transferred to a prison very far from his legal case, especially since\nRumonge prison is a prison which is for convicts or those whose judgment has been\npronounced and not provisional detainees such as Nestor”.431\n444. On 13 August 2018, Nestor Nibitanga was sentenced by the Mukaza Court of First-\nInstance (TGI) five years’ imprisonment.432 The prosecution had required 20 years of penal\nservitude against him. In their decision, the judges argued that Mr. Nibitanga had continued\nto provide reports on the human rights situation to the APRODH while this organisation\nhad been definitively suspended in October 2016.433 Nibitanga’s lawyer said he would\nappeal against this decision.\n445. On 17 February 2018, Aloys Habimana, project coordinator for “Protection for\nAfrica” within the international NGO Front Line Defenders, was arrested by SNR in\nGatumba near the Burundian-Congolese border while on his way to the DRC. He was later\ntransferred to the SNR headquarters in Bujumbura.434 Several organisations, including Pan\nAfrica Human Rights Advocates’ Coalition (PAHRA Coalition), South Sudan Human\nRights Society for Advocacy (SSHURSA), Our Lives Matter Action-International\n(OLiMA-International), Parents-Elders Action for Children’s Education (Peace-Africa),\nInternational Children’s Foundation (ICF), Global Youth for Security and Peace Advocacy\n(GYoSPA), African Center for Justice, Peace and Reconciliation (ACJPR), Africa\nWomen’s Rights Empowerment Institute (AWoRE Institute), publicly requested for the\nrelease of Mr. Habimana on 18 February 2018.435. His release came the next day.436\n446. Human Rights Defenders arrested during the period covered by the previous\nCommission report437 have also been condemned to heavy sentences following procedures\nmarred by irregularities and violations of the rules of criminal procedures.438 On 8 March\n2018, three members of the organisation Word and Actions for the Awakening of\nConsciousness and the Evolution of Mentalities (PARCEM) were sentenced to 10 years’\nimprisonment for “undermining the internal security of the State” after they were arrested\non 13 June 2017 while preparing a workshop on human rights violations in Burundi.439\nSimilarly, Germain Rukuki, former employee of the Burundi Association of Christians for\nthe Abolition of Torture (ACAT), member of the Association of Catholic Jurists of Burundi\n(AJCB) and president of the association “Njabutsa Tujane”, was sentenced on 26 April\n2018 to 32 years’ imprisonment for “rebellion”, “undermining the internal security of the\nState” and “participation in an insurrectional movement”, while no material evidence was\npresented by the Prosecutor’s Office to demonstrate these offenses and, during the\nprocedure, his lawyers had difficulty accessing his file, and furthermore, new charges, not\nmentioned during the investigation phase, were added against him.440\n(ii)         Violations of the freedom not to associate\n447. If freedom of association is compromised in Burundi, its corollary, the freedom not\nto associate is equally undermined. As in previous years,441 the Commission has received\nseveral testimonies since September 2017 of cases of forced affiliation or attempted\nrecruitment into CNDD-FDD and/or Imbonerakure primarily instigated by\nImbonerakure442 and local officials from the ruling party 443. These cases mainly affected\nmembers of opposition parties444 or those with no political affiliation 445. One victim\ntestified as follows:\n“[The chief of Imbonerakure in my commune] came asking me to join them, telling\nme that he had spoken with my colleagues who told him that I was not a member of\nthe ruling party. I told him I own a non-profit association […] and therefore I cannot\nbe in a political party. He replied that if I loved my country and myself, I had to join\nthe ruling party, that it was for my own good and in my interest to join the ruling\nparty”.446\nAnother victim reported:\n“There are CNDD-FDD people who come from the city to ‘sensitize’ people in the\ncollines so that they become part of CNDD-FDD”.447\nOne woman, whose husband has disappeared, said:\n“Imbonerakure had often asked my husband to join the ruling party, but he was not\ninterested in politics. Even during the elections, he did not vote. On Election Day,\nhe was in the fields. Imbonerakure told him that he had to join the ruling party. They\ntook his hoe to keep him from working. I witnessed this myself, I was sometimes\npresent when they came”.448\n448. Cases of forced recruitment documented by the Commission have revealed that\nseveral human rights violations have been committed against recalcitrant persons or their\nfamily members, including cases of arbitrary executions,449 arrest and detention\narbitrariness,450 kidnapping,451 ill treatments452 and sexual violence453. These attacks were\nmainly committed by Imbonerakure or persons believed to belong to or to be related to\nImbonerakure. In several cases, they acted at night by attacking the victims’ homes.454\n(c) Freedom of assembly\n449. As in its previous report,455 the Commission noted that opposition political\nparties456or even labour unions457 had a difficult time organising meetings either because\nauthorisation had been refused by the competent authorities458 or because meetings, when\nheld, were disturbed by members of CNDD-FDD or Imbonerakure459. A witness reported:\n“The police came to arrest [FNL] members because they were accused of holding\nsensitisation meetings for a “no” vote at the referendum […] The arrest took place\nin a bar […] they were suspected of getting together in this bar to encourage a “no”\nvote during the referendum and yet they were there for a party. But because they\nwere all FNL affiliates and someone said there were FNL members in the bar, the\npolice hurried to arrest them”.460\nA former Imbonerakure narrated that when an organisation other than CNDD-FDD\nrequested authorisation to meet, Imbonerakure were informed by the leader of\nImbonerakure at the colline:\n“When a meeting began, [the Imbonerakure] showed up, made trouble by beating\nall those who were in attendance and dispersed them. In the end, these meetings no\nlonger took place. Imbonerakure asked organizers to provide written authorisation\nbefore they could meet. Even when the organizers presented their permits,\nImbonerakure often said it was not enough”.461\n450. The Commission also received confirmation that opposition political parties often\nhave to meet secretly for fear of persecution by law enforcement officers and\nImbonerakure.462 It also received testimonies from people who were forced to participate\nin meetings organized at the local level by CNDD-FDD or Imbonerakure, in particular in\nmeetings to raise awareness about the revision of the Constitution.463 One person testified\nas follows:\n“It was the leader of [X] district who invited me to the meeting. He was going door\nto door. He came and he said to me: ‘Tomorrow at such and such time, you are\ncoming to the meeting organised in this zone, you must be there’. He did not tell me\nthe meeting agenda but it was a meeting to brief us on the revision of the Constitution\nand how we must vote in the referendum. These meetings are frequent. We are called\ntwo to three times a month. I have been summoned several times; everyone has been.\nI went to such meetings several times because I had no choice, otherwise you are\nlabelled as disobedient. Even when you do not want to go, you must go or else you\nare risking your life”.464\n(d) Freedom of movement\n451. Similarly to the first term of its mandate,465 the Commission has documented\nnumerous restrictions on the freedom of movement that took multiple forms. The\nCommission collected several testimonies attesting to tighter controls and roadblocks\nmainly near Burundi borders with Tanzania and Rwanda.466 These border controls and\nroadblocks are mostly carried out and managed by Imbonerakure, in some cases in\ncollaboration with the police.467\n452. People who fled Burundi described human rights violations they suffered as they\nwere fleeing. Several of them have been victims of arbitrary arrests and/or other human\nrights violations, including ill treatments and extortions.468 One of them testified:\n“[In] […] 2017, […] my younger brother, […] and I were on the road […] to\nRwanda when we met a group of Imbonerakure […] These Imbonerakure\nsurrounded us and then the police came to watch what was going on […] The\nImbonerakure tied us up […] They beat us and threatened us with military knives\n[…] saying they would kill us […] A police officer […] asked them: ‘Why are you\narresting these people? What have they done?’ The Imbonerakure replied: ‘These\nare rebels heading to Rwanda’.”469\n453. Relatives of people who have successfully left the country have continued to be\nsubjected to harassment, threats and other human rights abuses.470 In particular, the\nCommission received the testimony of one person:\n“[X] has been persecuted by Imbonerakure because after [I] went […] into exile,\n[X] occupied [my] house. As the Imbonerakure were looking for me [but] had not\nfound [me], they decided to attack [X]. [X was arrested and has been missing\nsince]”.471\n454. Roadblocks have also been erected and inspections carried out across the country,\nlimiting the movement of Burundian citizens who, for private or professional reasons, have\nto move from one province, commune or colline to another.472 A person living in Makamba\nprovince testified:\n“There are a dozen Imbonerakure at every roadblock. You cannot go from one sous-\ncolline to another without crossing two barriers. Imbonerakure check all\nroadblocks. The police appear to be overseeing the activities of Imbonerakure. If a\nperson cannot pay, the Imbonerakure seizes the person’s property and keeps it until\nthe person is able to pay, and all of this happens in front of the police. I witnessed\nthis with my own eyes”.473\n455. The Commission has also received numerous reports of obstacles to freedom of\nmovement in connection with the constitutional referendum.474 In particular, a person\ninterviewed by the Commission referred to the receipt issued to a person after having\nregisteres as voter as “an identity card” because “the police can require the receipts\nanytime”.475 A person interviewed by the Commission described the difficulties associated\nwith checking receipts:\n“I saw the Imbonerakure inspecting the streets and asking for the voter registration\ncards. It is difficult to get around without the card because there are many\nroadblocks and, if you do not have the card, you are turned back and you go back\nto where you came from; so people are confined to their homes. My grandmother\ndid not register. She is very old and therefore she does not go out of her house”.476\n456. These receipts are particularly required at market places.477 One person told the\nCommission:\n“Life becomes very difficult without a voter registration card. For example, you\ncannot go to the market. It is as if this card is a ticket. Imbonerakure are posted at\nthe entrance of the market, checking whether we have it or not. Those who do not\nhave it are not allowed in. Imbonerakure can even request that this document be\nshown by citizens on their way to carry out fieldwork”.478\n457. Imbonerakure, sometimes in collaboration with the local administration, refused\npassage to people who could not show the receipts proving that they paid their contributions\ntowards the 2020 elections or other types of contribution.479 One person stated:\n“For [...] contributions, the Imbonerakure gave a receipt, and we were not free to\ntravel without this receipt. The Imbonerakure established checkpoints where they\nchecked for the required receipt. These roadblocks were erected between two\ncollines so that one had to go through a roadblock to move from one colline to\nanother. If you were stopped at a roadblock without the required receipt, the\nImbonerakure concluded that you had not paid yet, and sometimes demanded ten\ntimes the amount, or they beat people severely”.480\n458. The Commission also continued to receive reports confirming the use of household\nrecord booklets to monitor population movements.481 Witnesses received by the\nCommission even report frequent cases of extortion in connection with the verification of\nhousehold record booklets.482 A witness reported:\n“Most often, the police arrest people in a group, supposedly in search of household\nrecord booklets, but, in reality, people get arrested in order to extort [money from]\nthem in exchange for their release”.483\n459. The Commission was finally able to meet with many people who, after having\nstayed in a neighbouring country, even briefly, returned to Burundi and were victims of\nhuman rights violations, including arbitrary arrests, detentions, torture and ill treatments.484\nSome people were reportedly killed after returning to the country.485 They have often been\naccused of collaborating or wanting to join armed opposition groups. One person who\nreturned from Tanzania explained:\n“I left Burundi [in] 2016 [...] I returned to Burundi in [...] 2017 [...] Upon arrival,\nI wanted to go home. I found a new building […] When I got to the commune, the\nchef de zone told the commune administrator that I was coming back from a refugee\ncamp and that I had come to disrupt order […] The commune administrator called\n[the] police who came and put me in a cell... Before entering the cell, the police hit\nme [...] They accused me of having been in exile and wanting to disrupt order”.486\n460. In this regard, the Commission has received information on an organized system of\nexchange of information between various groups, composed of administrative authorities,\nmembers of the police and Imbonerakure, intended to monitor the movements of any person\nsuspected of being against the Government or the party.487 This system makes it possible\nto easily monitor the more or less long absences of members of the latter group from their\ncolline of residence, but also their return. A person interviewed by the Commission\nrecounted:\n“It was at this time [that I left my] commune to [take refuge in [...], in the same\nprovince [...]. Imbonerakure exchanged information with each other [in] the various\ncommunes. They chased me […] into [my] hiding place […] Not feeling safe, [I]\nfled Burundi”.488\n461. All these restrictions to the freedom of movement have had the consequence of\nlimiting the movements of Burundian citizens inside and outside their country.\n[…]"},{"id":"a-hrc-39-crp-1-u0039","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":39,"section":"2. Political crisis and exacerbation of poverty","text":"(c) Increased “contributions”\n630. The Commission has also noted and received numerous testimonies showing\nan increase in all kinds of “contributions” since the start of the political crisis in\n2015. These donations add to the financial pressure to which Burundians are already\nsubjected.\nA longstanding practice\n631. Analysts traced the origin of this practice at the time of the civil war when the\nCNDD-FDD rebellion imposed in-kind or financial contributions from the\npopulations of the areas where the party was established.489 Several witnesses\ninterviewed by the Commission confirmed that they had been required to make\nvarious contributions before 2015.490 Some dated this practice back to the 2000s.491\nOthers pointed out that the level of contributions has steadily increased since then.492\n632. To the knowledge of the Commission, the oldest form of contribution includes\ncontributions towards local development.493 These can consist of community work","unnumbered":true},{"id":"a-hrc-39-crp-1-u0040","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":40,"section":"2. Political crisis and exacerbation of poverty","text":"in the public interest494 or financial contributions. In the latter case, the amount\nvaries from one province to another, or even from one locality to another. Their\npurpose can be well defined. A witness who,495 among other things, had held\npolitical office at the local level mentioned the existence of a 2008 voluntary\ncommunity contribution for building secondary schools in his commune in order to\naccommodate children of former refugees. He also mentioned a similar initiative\nlaunched before the crisis started in 2015, aimed at building a university. These\ntypes of contribution continue to date.496 However, most of witnesses interviewed\nby the Commission expressed doubts about their actual destination. A former trader\nreported that Imbonerakure in the area where he operated used to collect 50,000\nBurundian (28.5 US dollars) per month towards “the development of the province”.\nHowever, as he pointed out:\n“It is a well-known fact that the money [of these contributions] was shared\nbetween them. I know this because Imbonerakure themselves bragged,\nsaying, ‘This money you give us is our wages; you pay our wages.’ I\noverheard them saying this to another customer while they were having a\nbeer at the bar I owned who had said to them: ‘We note that taxes continue\nto increase’.” 497\n633. The same witness also mentioned that, faced with continued financial pressure,\nhe had teamed up with other traders to complain to local authorities. They then had\na meeting with the municipal assistant administrator who ordered them to pay on\nthe grounds that Imbonerakure were ensuring “security of goods and commodities\nin the commune”. This interview highlights the fact that development contributions\nthat were originally “voluntary” have become mandatory overtime and have\ntherefore taken the form of taxes. This trend was confirmed by the majority of those\ninterviewed by the Commission.498 Yet, the principle of tax legality is guaranteed\nby the Constitution and law n° 1/35 of 4 December 2008 on public finances.499\nDevelopment contributions that have no legal basis though meeting tax criteria 500\nare therefore unconstitutional. The vagueness of their purpose further promotes a\nform of arbitrariness, as shown in the above testimony.\nAn increase in contributions of all kinds and with no legal basis\n634. The Commission has thus documented a multiplication of contributions\nwithout legal basis throughout Burundi.501 For example, contributions to cover\nevents and activities decided by the President of the Republic 502 or contributions\nlinked to cattle ownership503. Some contributions give rise to practices contrary to\npublic freedoms, such as those that are requested from traders under penalty of\nclosure of their stores or dismissal from the market.504 A former vendor testified:\n“As soon as we arrived at the big market and when everyone had exhibited\ntheir goods, Imbonerakure [accompanied by the chef de colline] arrived and\nasked us to pay 500 Burundian francs [0.29 US dollar] […] We had to pay\nthis sum each time you went to the market, that is to say if you were going to","unnumbered":true},{"id":"a-hrc-39-crp-1-u0041","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":41,"section":"2. Political crisis and exacerbation of poverty","text":"sell your goods every day, you had to pay every day. I went there on\nWednesdays and Sundays and I had to pay the 500 Burundian francs each\ntime. Some days, I went to the small market and there I had to pay 300\nBurundian francs [0.17 US dollar] [...] The contribution was compulsory\n635. The Commission has also gathered numerous testimonies506 on contributions\nforcibly taken to finance CNDD-FDD activities – internal meetings, public\ngatherings, headquarters, the arrival of a senior official, etc. – and this while the\ncontributor was not necessarily a member of the ruling party. One witness even\ntestified that a portion of the salaries of civil servants was withdrawn from the base\nsalary in order to contribute to the functioning of CNDD-FDD.507 This trend\nillustrates the confusion that exists today in Burundi between the resources of the\nState and those of the ruling party. State agents at the local level, such as\nneighborhood and colline leaders or even SNR officials, may thus be found\ncollecting contributions on behalf of CNDD-FDD508 and, conversely, as we have\nseen, Imbonerakure collecting contributions for local development or other forms of\nlevy allegedly for the good of the community.509\n636. Generally speaking, Imbonerakure operate with State power’s complicity,\nwhether express or implied. They are sometimes used as auxiliaries in order to put\npressure on people who do not want or cannot pay.510 In other cases, they collect the\ncontributions themselves in the presence of State agents or with impunity, without\nbeing worried by them.511 Several testimonies collected by the Commission also\nmention receipts issued by Imbonerakure once they have collected contributions.512\nThe issuance of official receipts by Imbonerakure or by public authorities513\nreinforces the idea of a practice authorized or tolerated by the State although it is not\nbased on any legislative text.\nContributions for the 2020 elections\n637. In addition to these various contributions, most of which existed prior to 2015,\na new levy has been in effect since last year. On 11 December 2017, the Minister of\nInterior and Patriotic Education and the Minister of Finance, Budget and\nPrivatisation jointly promulgated ordinance n° 530/540/1772 514 that sets monetary\ngoals for contributions needed for the organisation of presidential, legislative and\nmunicipal elections scheduled in 2020.515 Whether this new contribution is legal\nremains contentious. An expert interviewed by the Commission 516 concluded for\ninstance that it is in contradiction with two articles of the Burundian Constitution,\nnamely: article 70-4 that provides for citizens’ exceptional contribution only in the\nevent of “natural and national calamities”; and article 159-5 which provides the\n“definition of the fiscal base and the rate of taxes and duties” as “a matter of law”\nand should consequently not be decided by way of executive order. Article 3 of law\nn° 1/35 of 4 December 2008 relating to public finances also provides that “the base\ntaxation, rate and methods of collecting taxes of any kind may only be created,\ncancelled or modified by way of a finance act”.","unnumbered":true},{"id":"a-hrc-39-crp-1-u0042","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":42,"section":"2. Political crisis and exacerbation of poverty","text":"638. In addition to the contribution introduced by ordinance n° 530/540/1772, there\nis a budgetary provision known as “provision for the 2020 elections” from the 2017\nfinancial law, which Burundi’s National Court of Auditors had at the time\nconsidered consistent with “the progressive search for the country’s financial\nindependence in order to safeguard national sovereignty”.517 This provision, which\namounted to 6.2 billion Burundian francs (3.5 million US dollars) in 2017, doubled\nand reached 12.5 billion Burundian francs (7.1 million US dollars) in 2018.518 It\nreached 33.2 billion Burundian francs (18.8 million US dollars) in the latest financial\nlaw covering the period of 2018-2019.519\n639. Under ordinance n° 530/540/1772, “self-employed citizens who live off\nagriculture or simple trade that does not generate a monthly income, will contribute\n2,000 Burundian francs [1.14 US dollars] per year and per household and 1,000\nBurundian francs [0.57 US dollars] per year for pupils and students of voting age”.520\nAgain, the Commission received statements that Imbonerakure are in charge of\ncollecting these contributions from households and are also vested with the authority\nof issuing official receipts.521\n640. Ordinance n° 530/540/1772 also stipulates that civil servants will have an\naverage of 10 % of their salary – or even beyond for those with higher earnings522 –\ndeducted at source each month for two years starting in January 2018. As pointed\nout by a witness questioned by the Commission,523 this withholding tax is applied\non a salary that is “in itself insufficient” and is added to the taxes “averaging between\n20 and 30 % of monthly salaries”. Convention n° 95 of the International Labour\nOrganization (ILO) on the Protection of Wages also states, “deductions from wages\n[are] permitted under conditions and to the extent prescribed by national laws or\nregulations or fixed by collective agreement or arbitration award”.524 Yet, in the case\nof deductions from civil servants’ salaries as part of the contribution for the 2020\nelections, these three elements are lacking.\n641. In this context, the application of ordinance n° 530/540/1772 has not been\nwithout dispute. Echoing officials opposed to the levy of the contribution at source,\nthe Confederation of Burundi Trade Unions (COSYBU or Confédération des\nsyndicats du Burundi) and the Confederation of Free Trade Unions of Burundi (la\nConfédération des syndicats libres du Burundi or CBS) called for the opening of\ndialogue on voluntary contributions to the 2020 elections with the Government, in\nletter dated 8 January 2018 and addressed to the Ministers of Interior and of","unnumbered":true},{"id":"a-hrc-39-crp-1-u0043","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":43,"section":"2. Political crisis and exacerbation of poverty","text":"Finance.525 A meeting was organized on 25 January 2018 between the Ministers of\nInterior, of Finance and of Public Service, more than 35 workers’ unions and\nBurundi employers’ association to find a way out of the contribution of civil servants\nand all workers in Burundi. During this meeting, the Minister of Interior is said to\nhave declared that those who do not want to contribute only need to report it to the\ncompetent authority. “There is nothing against human rights,” he reportedly said.\nAnyone who does not want to contribute will speak […] anyone with a salary of\nzero francs will simply not contribute”.526 On 29 January 2018, the Minister of\nFinance also said in an interview with the newspaper Iwacu that “those who do not\nwant to contribute only have to report it”.527\n642. Despite these declarations, statements gathered by the Commission show that\ncivil servants’ contributions continued to be taken at source while their opinion was\nnot taken into consideration. With regard to the Army, for instance, on 16 February\n2018, the Army spokesperson, Colonel Gaspard Baratuza, stated in an interview\nwith the online newspaper Iwacu528 that the contribution to the elections “will be\nwithheld on local salaries of all military personnel”. In addition, the Commission\nhas had confirmation529 that several ministries coerce their agents into contributing\nto a common fund intended as the ministry’s contribution to the 2020 elections. The\nreality of such a practice has been reported by the Burundian press530 although\nordinance n° 530/540/1772 does not provide for it. An official testified:\n“Anyone who refuses to pay [...] risks losing their life, we are aware of what\nis going on in our country”.531\nA teacher, who initially did not want to contribute, reported:\n“A colleague came to me saying: ‘Mr. [X], my advice to you is that you pay\nthis money. This is for your own sake; you do not know what lies behind this’.\nIt was 8am and I was giving a class [...] I gave the money at 9 am. Around 1","unnumbered":true},{"id":"a-hrc-39-crp-1-u0044","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":44,"section":"2. Political crisis and exacerbation of poverty","text":"pm, on the way home, another colleague approached me to give me a\nmessage from the school director, which was: ‘Mr. [X], I am asking you to\nstop making comments and to accept to pay this contribution’ [...] My reply\nto the director’s emissary was that I had paid the contribution via the school\ntreasurer”.532\n643. This practice also affects institutions other than ministries, such as that of the\nOmbudsman,533 the National Assembly,534 the Senate,535 both Vice-Presidencies,536\nand universities,537 even though workers’ respective revenues have decreased due to\nthe politico-economic context. Leading political figures have also contributed in a\npersonal capacity such as the President of the Republic who paid nine million\nBurundian francs (5,140 US dollars)538 at the central bank, the Second Vice-\nPresident who contributed up to 2 million Burundian francs (1,142 US dollars)539\nand the President of the National Assembly up to 4.8 million Burundian francs\n(2,741 US dollars),540 all of these represent significant sums in a country with a gross\nnational income per capita of 290 US dollars.\n644. As pointed out by an expert interviewed by the Commission,541 a civil servant\nin Burundi is now subjected to a five-level levy in relation to the 2020 elections: the\nmonthly levy on basic salaries; one’s participation in the contribution by the ministry\nor supervising institution; the contribution in relation to the budgetary provision for\nthe elections provided for in the financial law; the annual contribution requested\nfrom households and, when the person has one or more dependents of school or\nvoting age, a contribution paid on their behalf. All these contributions have, as we\nhave seen, a direct impact on the standard of living of civil servants, but more\ngenerally on the population as a whole. In this regard, the Commission received\nevidence from a person who was forced, due to financial pressure, to reduce the\nnumber of meals for himself and his family,542 but also that of a parent unable to\ncover school costs for their child.543\n645. Furthermore, the context in which these various contributions are planned and\nlevied also prompts human rights violations. The Commission of Inquiry received\nseveral reports on roadblocks erected across the country by Imbonerakure in order\nto verify whether the residents of the area were indeed in possession of receipts","unnumbered":true},{"id":"a-hrc-39-crp-1-u0045","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":45,"section":"2. Political crisis and exacerbation of poverty","text":"proving that they had paid their contributions.544 These roadblocks infringe on the\nfreedom of movement, mobility and travel and lead to extortion. The Commission\nhas also documented cases of ill treatment,545 arrest and illegal detention,546 threat,\nintimidation or persecution,547 in connection with victims’ refusal or inability to pay\ntheir contributions. This, in most cases, is the work of Imbonerakure.548 Several\npeople stressed that the threats or pressure they had suffered following their refusal\nor inability to pay their contributions had pushed them to flee Burundi.549\n646. In his speech on 7 June 2018, on the occasion of the promulgation of the new\nConstitution, the President of the Republic called on Burundians “to continue [their]\nefforts to contribute” to the 2020 elections which, he said, are “on a voluntary basis,\nwithout any constraint”. Two days earlier, the Minister of Finance, Domitien\nNdihokubwayo, had declared during a press conference550 that 17.2 billion\nBurundian francs (9.8 million US dollars) had been collected as of 31 May 2018 and\nthat, in addition, the government intended to pay 12.5 billion Burundian francs (7.1\nmillion US dollars) under the budget line in the 2018 financial law. He also noted\nthat the Government had evaluated the total budget of the 2020 elections at 70\nbillion Burundian francs (40 million US dollars) while indicating that this budget\nwas “provisional” and was going to be reassessed since CENI had “used material\nand equipment during the preparation of the constitutional referendum”. This\nimplies that the Burundian Government will still have to collect at least 40 billion\nBurundian francs (22.8 million US dollars) in 2019 and until the 2020 election\ndeadline, a substantial amount in a poor country with an economic growth close to\nzero. Contrary to the Head of State’s statement, volunteer contributions would not\nsuffice in order to raise such an amount. Again, it is all Burundians who risk being\nforced to contribute.","unnumbered":true},{"id":"a-hrc-39-crp-1-u0046","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":46,"section":"2. Political crisis and exacerbation of poverty","text":"(d) Impact of violations of civil and political rights on the socio-economic situation\nof the victims’ spouses and children.\n647. As previously stated, violations of civil and political rights documented in the\nCommission’s current and previous report – specifically arbitrary executions,\narbitrary detentions and enforced disappearances – predominantly affect men, but\nthey have an impact not only on the victims but also on their families. In addition to\nthe threats, violence or trauma they suffered, most of them have also seen their\nsocio-economic situation deteriorate.\n648. Men who are absent due to detention, abduction or execution and who headed\ntheir families often leave their wives and children destitute overnight. As highlighted\nearlier in this report, women heads of households are more at risk of falling into\npoverty as a result of discrimination and their lower socio-economic status.551 The\nCommission has received numerous statements from wives of men who have been\ndetained, abducted or executed, or who have fled Burundi for fear of enduring\nviolations of their civil and political rights; citing the economic difficulties that they\nhave to face alone in order to meet the basic needs of their family, such as covering\ntheir children’s medical, housing, food, clothing and education expenses.552\n649. In many cases documented by the Commission, wives who were left alone with\ndependent family members already lived in precarious conditions before their\nspouses were victims of human rights violations or had to flee the country. For","unnumbered":true},{"id":"a-hrc-39-crp-1-u0047","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":47,"section":"2. Political crisis and exacerbation of poverty","text":"example, a woman described the economic situation of her family before the\nabduction of her husband in these terms:\n“My husband farmed other people’s land for a modest wage. The money was\nused for eating and paying rent. There was nothing left to put aside in\nsavings”.553\n650. In other cases, both spouses managed to support their families using their\ncombined income. Most wives interviewed by the Commission mentioned that they\nlived on farming mainly,554 which in the majority of cases was subsistence farming.\nMany also earned an income from small businesses such as selling fruits and\nvegetables and other food products,555 with some modest profit margins.\n651. The absence of one’s spouse has exacerbated this economic precariousness.\nAccording to some statements, women farmers reduced their activities in the fields,\nfor fear of their safety following the violence and threats suffered by their\nfamilies.556 One of them recounted:\n“After my husband left, the financial situation was difficult. My husband had\nleft nothing but hens that I could sell. I had to manage on my own and provide\nfor the children’s needs and my own [...] I was afraid of going to farm my\nsmall piece of land. When I saw people approaching and hanging around my\nfield, I went back [home] to avoid problems”.557\n652. In other cases, women were forced to reduce their economic activities in order\nto look after their children in the absence of their spouse, as in the case of a\nshopkeeper who testified of the abduction of her husband in early 2017:\n“I was in an extremely difficult economic situation after my husband’s\ndisappearance. [...] Before [...] I spent a lot of time in the countryside to\nstock up on supplies. Once my husband was gone, I had to stop traveling\nbecause I could not leave the children alone at home. My purchasing power\ndecreased as a result, because I did not sell as much as I used to”.558\n653. Several unemployed wives559 were forced to depend on the assistance of their\nown family 560 or of benefactors around them, often from religious communities,561\nand/or survive on small, informal jobs,562 due to the lack of their spouse’s income.\nOne woman testified:\n“After my husband left, I simply had nothing to eat, overnight [...] I am an\norphan and I have no brothers and sisters, so I had no family who could\nsupport me […] I asked for accommodation with an elderly mother who\nagreed to accommodate me. She saw that [...] I had nowhere to go and she\nfelt sorry for me. [...] Given the insecurity that prevailed and since my child\nand I did not have enough to eat, I decided to leave my country”.563\n654. Several women reported that due to the lack of resources to support their\nfamilies in the absence of their spouses, they were forced to reduce the quantity\nand/or quality of food they gave their children. Several statements have mentioned\ndifficulties for these women to generate enough income to ensure minimum food.564","unnumbered":true},{"id":"a-hrc-39-crp-1-u0048","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":48,"section":"2. Political crisis and exacerbation of poverty","text":"Some families have reduced the number of daily meals to just one.565 A woman\nexplained:\n“I was having a hard time dealing with my husband’s arrest and his absence\n[...] After my husband left, I [...] ate only once a day [...] My child often fell\nill because he did not eat much”.566\n655. Lack of access to sufficient and quality food has particularly severe and often\nirreversible consequences, especially for young children.567 Beyond the right to\nfood, the absence of the head of family often has an impact on other economic and\nsocial rights of children, such as the right to education. Some children whose fathers\nwere targeted for their alleged political affiliation have themselves sometimes been\nvictims of harassment and/or threats to the point of being withdrawn from school,\nbecause their families feared for their safety.568 In other cases, children had to drop\nout of school because in their father’s absence, the family’s economic resources\nbeing no longer sufficient to cover education costs.569\n656. Many women who became heads of household following the absence of their\nspouses ended up fleeing Burundi because they were unable to ensure their own\nsurvival and that of their families, in addition to being faced with growing insecurity,\nor even threats or attacks. A mother of seven recounted:\n“After the attack, I did not live well. We were in a rented house and\neverything was stolen from us […]. To support us, I did odd jobs for the\nneighbours […] I couldn't take it anymore in the end. I did not feel safe,\nneither for my children nor for myself. I thought they could come back\nanytime to attack me again”.570\nA shopkeeper whose husband sought refuge outside the country in 2016\ntestified that in 2017 Imbonerakure burned down her shop and raped her.\nHaving lost her livelihood and contracted HIV, she fled the country with her\nfive children.571\n657. For women who are left alone with dependent children, leaving the country is\nmore complicated to organize than for men leaving alone. It involves particular risks\nfor their safety and that of their children, as well as a high risk of being turned away,\nbecause fleeing as a group attracts more attention.572 Women testified that they had\nto leave children in the care of others in order to avoid endangering them or\njeopardising their escape.573\n658. Several women who have been left alone with dependent children have also\nindicated that they had to leave their house, either because it was partially or\ncompletely destroyed during attacks,574 for fear that they would be subjected to\nadditional attacks or violations of human rights,575 or for lack of means to pay rent576.\nOne woman told the Commission:\n“When the door to my house was ripped off, about two months after my\nhusband was arrested, I moved to my sister’s house with my son”.577","unnumbered":true},{"id":"a-hrc-39-crp-1-u0049","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":49,"section":"2. Political crisis and exacerbation of poverty","text":"Another woman testified: “After the abduction of my husband, we lived in\nterror at home with the children. Because of this, we slept elsewhere. We\nlooked for places where there were crowds because we no longer felt safe”.578\nA woman whose husband fled abroad in 2016 and who had five dependent\nchildren in addition to a younger sister who was minor described her financial\nsituation: “There was a big difference in my situation after my husband was\ngone. [...] I continued to work [but] ... [I] ended up leaving the house as I\ncould no longer secure enough means to afford rent”.579","unnumbered":true},{"id":"a-hrc-39-crp-1-u0050","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":50,"section":"3. Political crisis and grabbing of ressources","text":"(b) Persistence of bad governance and fraudulent grabbing of public goods\n669. Despite the challenge of carrying out investigations mostly due to obstacles to\nfreedom of the media and of the civil society and the lack of independence of the\njudicial system580 since 2015, cases of poor governance and fraudulent raids on\npublic property have continued to be revealed.581 The persistence of such cases\ncontributes to diverting significant resources that the State should have devoted to\nthe realisation of the population’s economic and social rights.\n670. Opacity in the design and implementation of State budgets continues to be\nnoted and denounced on a regular basis. As mentioned,582 the fact that no budget\nimplementation report has been made public since 2013 reinforces this opacity.\nThereon, frequent overrun of tax exemptions has been revealed by the National\nCourt of Auditors and the media,583 without the Government providing any\nexplanations on the reasons for the exemptions granted beyond budget forecasts.\n671. Official tax revenue figures have also raised questions. In February 2018, the\nMinister of Energy and Mines stated that budgetary objective had been exceeded,\nwith revenues amounting to 4.2 billion Burundian francs (2.4 million US dollars)\nfor 2017, when only three billion Burundian francs (1.7 million US dollars) had been\nplanned.584 However, calculations made by the newspaper Iwacu on the volumes of\nmining exports and relative taxes gave a figure closer to six billion Burundian francs\n(3.5 million US dollars) 585. In its 2018 report, the National Court of Auditors\nindicates no numbers under the heading “exceptional products achievements from\n2013 to 30 September 2017” by the Burundian Office of Mines and Quarries.586 For\nthe civil society organisation Observatoire de lutte contre la corruption et les\nmalversations économiques (OLUCOME) “the National Court of Auditors report\non the draft comments of the state general budget for FY2018 clearly reveals that","unnumbered":true},{"id":"a-hrc-39-crp-1-u0051","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":51,"section":"3. Political crisis and grabbing of ressources","text":"the Ministry of Energy and Mines never paid a dime to the National Treasury since\n2013. These funds may have been collected, but not by the public treasury”.587\n672. Similar opacity was noted at the level of State “exceptional revenues” which\nwitnessed clear increase between 2015 and 2018, going from 7.5 billion (4.2 million\nUS dollars) to 44.6 billion Burundian francs (25 million US dollars), an increase of\n83 per cent.588 This increase does not correspond to revenues from the participation\nof Burundian troops in peacekeeping missions which, during the period, remained\nconstant in the national budgets, i.e. 3 billion Burundian francs (1.7 million US\ndollars) per year, even if this apparent stability has, as mentioned, been called into\nquestion by several witnesses and observers who put forward the fact that this\namount did not include withdrawals carried out by the Government on salaries of\nBurundian soldiers deployed in peacekeeping missions.589 The increase in\nexceptional tax revenue comes mainly from the addition of new accounting lines\nsuch as “local government revenue” and “revenue of the Burundian Office of Mines\nand Quarries” which emerged in the general State budget respectively in 2016 and\n2018. The emergence of these new revenues, without further explanation, was noted\nat the end of 2017 by the National Court of Auditors, which requested that the\nGovernment provides additional information.590 This was not done. More generally,\nthe use of exceptional revenue is beyond any real control and calls into question the\nprinciple of the unitary nature of the budget.\n673. Similarly, extra budgetary accounts with no legal basis and which are beyond\ncontrol continue to appear in the finance acts as we have seen, despite criticism from\nthe Court of Auditors.591 This is the case of the account for “support of positive\ninitiatives”, directly managed by the Office of the President. Its endowment\namounted to two billion Burundian francs (1.1 million US dollars) in 2015; 1.2\nbillion Burundian francs (685,608 US dollars) in 2016; 1.2 billion Burundian francs\nin 2017 and 2.3 billion Burundian francs (1.3 million US dollars) in 2018.592 In a\npress release dated 15 November 2017, OLUCOME reported that, to be able to\noperate in Burundi, foreign companies had to transfer money into this account.593\n674. Poor governance also continued to be denounced by various technical and financial\npartners in Burundi. For example, in 2017, the Global Fund to Fight AIDS, Tuberculosis\nand Malaria decided to no longer channel funds allocated to Burundi through the\ngovernment, but via UNDP instead.594 In a letter dated 12 October 2017, the Fund indicated:\n“The five grants implemented in Burundi were rated B2 at the end of 2016, that is to say","unnumbered":true},{"id":"a-hrc-39-crp-1-u0052","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":52,"section":"3. Political crisis and grabbing of ressources","text":"that the programmatic and financial results do not match relevant targets”. 595 Performance\nat the Global Fund is categorized as follows: A1 (“Beyond expectations”), A (“good\nperformance”), A2 (“As expected”), B (“adequate”), B2 (“Inadequate but potential has\nbeen demonstrated”) and C (“unacceptable”). The Global Fund website indicates that the\nlast grant to Burundi was rated C.596 In its letter, the Global Fund clarified that it was\ncompelled to resort to “additional safeguard policy” mentioned to Burundian authorities in\n2016, and that it could not accept “the establishment of a project management unit within\nthe Ministry of Health” as suggested by Burundian authorities.\n675. Since 2015, an update on cases of embezzlement has also been provided. On this, a\npresidential decree promulgated in 2009597 and reviewed in 2016598 provisionally declared\nof public utility a 200-hectare area at a site in Gasenyi, Mutimbuzi commune (Bujumbura\nprovince) for the purpose of setting up buildings for the Office of the President and related\ninfrastructure. The decision led to the demolition of private houses.599 Moreover, these\nhomes were destroyed before compensation was paid and rehousing solutions put in\nplace.600 Some families who could not afford renting a house had to go back to their plots\nwhere they built huts so as not to end up on the street.601 Compensation calculations have\nbeen contested and payments have been slow to materialize.602 Deutsche Welle reported\nthat, at a public conference on 29 September 2017, Omer Niyonkuru – spokesperson for\nthe Ministry of Water, Environment, Spatial and Urban Planning – acknowledged there had\nbeen embezzlement. He declared: “Compensation funds for the 40 hectares were made\navailable by the government. When later claimed, the amount of money turned out to be\ninsufficient. Proof that there was misappropriation of funds, there is no denying it. We\nrecall that the case is in the hands of the court. In the meantime, the concerned parties are","unnumbered":true},{"id":"a-hrc-39-crp-1-u0053","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":53,"section":"3. Political crisis and grabbing of ressources","text":"invited to rely on the Administration, we stand beside them”.603 As of March 2018, the issue\nof compensation remained unresolved.604\n676. Public land usage for the benefit of the CNDD-FDD605 to build monuments for the\nparty’s glory, its offices606 or other building facilities was also noted607. A July 2018\npresidential decree thus allocated nearly three hectares of State-owned land, located in\nGitega centre, to CNDD-FDD for the construction of a centre for worship, conferences and\nsimilar events.608 The use of State vehicles and State funds to disseminate the CNDD-FDD\nmessages during the referendum campaign has also been criticized by civil society\norganisations.609","unnumbered":true},{"id":"a-hrc-39-crp-1-u0054","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":54,"section":"3. Political crisis and grabbing of ressources","text":"(c) Grabbing of other resources\n677. In a context of widespread impunity, the distinction between the political and\ncriminal reasons behind the grabbing of property, including land, is difficult to\nestablish. As we have seen, the State exercises “general effective control” over\nImbonerakure because of the freedom of action and impunity granted the latter.\nTheir unlawful acts could therefore be characterized as violations for which the State\nis responsible under international human rights law.610 In this context, the Burundian\nState could be rendered liable for cases of family conflicts, conflicts among\nneighbours or those related to inheritance, but also for cases of land grabbing in\nwhich, according to several statements collected by the Commission, Imbonerakure\nare involved.611\n678. A widow testified that one of her cousins had obtained a court ruling in his\nfavour guaranteeing him a right of usufruct over part of his late father’s land which\nhe had inherited from his paternal uncle.612 Imbonerakure assassinated her cousin in\nAugust 2016, apparently on the orders of his paternal uncle. Someone else described\nthree attacks, including grenade and housebreaking, suffered by his family in 2017","unnumbered":true},{"id":"a-hrc-39-crp-1-u0055","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":55,"section":"3. Political crisis and grabbing of ressources","text":"603 Deutshe Welle, Construction d'un nouveau palais présidentiel, des Burundais expropriés attendent\ntoujours, 23/10/2017. In English: Building of a new presidential palace, expropriated Burundians\nstill waiting (in: https://www.dw.com/fr/construction-dun-nouveau-palais-pr%C3%A9sidentiel-des-\nburundais-expropri%C3%A9s-attendent-toujours/a-41072323).\n604 Iwacu, Les expulsés de Gasenyi attendent toujours l’acquisition des nouvelles parcelles. 1 March","unnumbered":true},{"id":"a-hrc-39-crp-1-u0056","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":56,"section":"3. Political crisis and grabbing of ressources","text":"due to a land dispute with his two brothers-in-law who are Imbonerakure local\nchiefs.613 Another person, who fled Burundi in 2017, testified that his house, for\nwhich he had a property deed, was taken and given by the colline administrator to\nsomeone else, a member of the CNDD-FDD.614\n[…]","unnumbered":true},{"id":"a-hrc-39-crp-1-u0057","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":57,"section":"IV. International crimes","text":"722. Considering that the prevailing context in Burundi in 2017 and 2018 was\ncharacterized by persistent and serious human rights violations, the Commission has\nreasonable grounds to believe that the crimes against humanity it had identified in\nits previous report615 continue to be perpetrated in Burundi.\n723. However, similarly to last year, the Commission was unable to conclude that\nthere were crimes of genocide. It remains convinced that the Burundi crisis that\nbegan in April 2015 is first and foremost a political crisis. Some people of Tutsi\norigin were, as in 2015 and 2016, victims of violations, although these stemmed\nfrom their stance as members of the opposition against the Government and/or\nCNDD-FDD and not exclusively because of their ethnicity. Nonetheless, the latter\ngave rise to insults that added to the victims’ suffering.\n724. Likewise, the Commission has not documented any speeches or words that may\nconstitute public or direct incitements to genocide.616 The rhetoric used by some\nGovernment or CNDD-FDD officials aimed at manipulating the feeling of ethnic\naffiliation, which the Commission had repeatedly noted in 2015 and 2016,617 was\nless manifest in 2017 and 2018. Moreover, it noted references to ‘clan’ affiliation\nrather than ethnic origin by the President of the Republic and certain people around\nhim, as it was the tradition during the monarchy in Burundi.618 In addition, in 2017\nand 2018, speeches by leaders of the State and the ruling party, which for some\nconstitute incitement to hatred and violence, mainly targeted, as detailed\npreviously,619 opponents of the Government and of CNDD-FDD, particularly during\nthe campaign for the revision of the Constitution.","unnumbered":true},{"id":"a-hrc-39-crp-1-u0058","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":58,"section":"A. Constituent elements and types of crimes against humanity","text":"725. The definition of crimes against humanity as provided by article 7 (para. 1) of\nthe Rome Statute of the International Criminal Court – i.e. “acts when committed as\npart of a widespread or systematic attack directed against any civilian population,\nand with knowledge of the attack” – continues to be applicable to the context that\nhas prevailed in Burundi in 2017 and 2018. In order to be qualified as such, an\n“attack” does not necessarily need to be military in nature.620 It does however need\nto consist of multiple acts that constitute crimes against humanity.621 The Rome\nStatute also specifies that these acts must not be committed in isolation, but that they\nmust have been committed in the context of said attack.622 In this respect, the\nCommission has again documented this year a large number of violations which\nqualify as what may be termed “attacks”, based on their common nature and modus\noperandi, their aims and consequences – in this case the silencing of any voices\ncontrary to the Government’s and CNDD-FDD’s line.","unnumbered":true},{"id":"a-hrc-39-crp-1-u0059","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":59,"section":"A. Constituent elements and types of crimes against humanity","text":"726. In addition, the attack must be against civilians. The presence of certain non-\ncivilians among victims does not change the predominantly civilian character of the\ntarget population.623 The statements collected by the Commission this year show\nthat in Burundi, the majority of victims remain civilians, mainly targeted by the\npolice, SNR or Imbonerakure, either because they are opponents of the Government\nand/or CNDD-FDD or perceived as such.\n727. As discussed previously, the attack must also be “generalized or systematic”.\nThe number of violations found in several of the country’s provinces since 2017, the\nhigh number of victims and of perpetrators demonstrates persistent and widespread\nattacks against civilians. The systematic nature of these attacks can also be\ndemonstrated by a “crime scenario” consisting of a “deliberate and regular repetition\nof similar criminal behaviours”.624\n728. The Rome Statute further requires the existence of a “State or organisational\npolicy” aiming to perform the attack.625 The case law has clarified that this policy\ndoes not necessarily need to have been stated “in a clear and precise manner”,626 but\nthat it could be inferred from a set of facts such as the “overall political framework\nin which the criminal acts take place”, “the general content of a political program,\nas it appears in the writings and speeches of its authors”, the “mobilisation of armed\nforces” and “the extent of the abuses”.627 In Burundi, it is difficult to distinguish\nState policy from that of the leading party as both pursue the same objective of\nkeeping CNDD-FDD and its leaders in power. The defence and security forces are\nmobilized for this purpose, in collaboration with Imbonerakure, causing numerous\nviolations. The goal of this policy is often reminded to the population as\ndemonstrated by President Nkurunziza’s recent speeches and statements by\nrepresentatives at all levels of CNDD-FDD, particularly in the context of the\nreferendum campaign.628\n729. Lastly, attacks continue to be carried out in full knowledge of facts. Given the\nfunction they hold in the country’s political and security apparatus and their\nindoctrination within CNDD-FDD, perpetrators of crimes committed in 2017 and\n2018 in Burundi identified by the Commission must be fully aware of the context in\nwhich their acts take place.\n730. In this context, the Commission has reasonable grounds to believe that crimes\nagainst humanity as listed in its previous report629 continue to be committed in\nBurundi, namely: murder, imprisonment or other serious forms of deprivation of\nphysical liberty, torture, rape and other forms of sexual violence of comparable\ngravity, as well as politically motivated persecution. The Commission remains\ncautious, however, in describing the disappearances it has documented as\n“enforced” under international criminal law. Article 7 (para. 2 i) of the Rome Statute\ndefines enforced disappearance as “cases where persons are arrested, detained or\nabducted by a State or political organisation or with the authorisation, support or\nassent of that State or organisation, which then refuses to admit that these persons\nare deprived of their liberty or to reveal their fate or whereabouts, with the intention\nof removing them from protection of the law for an extended period”. Elements of\ncrimes established by the International Criminal Court also require that the\nperpetrator of an enforced disappearance knows, at the time of committing this act,\nthat “a) in the normal course of events, the arrest, detention or kidnapping will be","unnumbered":true},{"id":"a-hrc-39-crp-1-u0060","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":60,"section":"A. Constituent elements and types of crimes against humanity","text":"followed by refusal to admit that [the victim(s)] are deprived of their liberty or to\nreveal their fate or whereabouts; or that b) this refusal was preceded or accompanied\nby a deprivation of liberty”630. At this stage of investigations, the Commission was\nunable to establish any of these two elements, as it was the case in its previous\nreport.631 Still, the Commission does not exclude that these could be due to the\ngeneral context in which enforced disappearances occur.","unnumbered":true},{"id":"a-hrc-39-crp-1-u0061","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":61,"section":"B. Individual responsibilities","text":"731. The Commission has reasonable grounds to believe that in 2017 and 2018,\nofficers, including high-level officers of the SNR, the police and the military, as\nwell as Imbonerakure, committed or continued to commit crimes against humanity.\nOn this basis, the Commission updated the list of alleged perpetrators, which it drew\nup during the initial mandate period.632 This list remains confidential, in the interest\nof protecting the Commission’s sources and respecting the principle of presumption\nof innocence of the alleged perpetrators. It will be turned over to the High\nCommissioner for Human Rights at the end of the mandate. In the meantime, the\nCommission reserves the right to share it.\n732. As in its previous report,633 and in line with the Rome Statute of the\nInternational Criminal Court, the Commission was careful to distinguish between\ndirect responsibility and indirect responsibility of military commanders and\nhierarchical superiors.634 As far as the latter group is concerned, the Commission\nhas already provided a description of the hierarchical structures of SNR, the police,\nthe army and CNDD-FDD.635 Nonetheless, several statements collected this year\nconfirmed that the real functioning of the State and security apparatus largely rested\nsystematically upon parallel chains of command and circuits.636\n733. In this context, the Commission has received confirmation of the central role\nof an informal command structure often referred to as the “Gommittee of Generals”,\nmainly made up of State officials such as the Minister of Public Security, the\nAdministrateur Général of the SNR, the Chief of Cabinet responsible for the police\nat the Office of the President, the one in charge of civilian cabinet, as well as the\nSecretary General of CNDD-FDD.637 This structure decides over policy and security\nmatters, in particular measures to be taken vis-à-vis opponents. It relays its orders\nand directives through a parallel hierarchical structure and chains of command that\nare based on personal ties and trust, some of which dating back from the time of the\nrebellion, and whose articulation varies from province to province, but also from\none locality to the other. The mechanism always involves officials at a more or less\nhigh level of SNR, the police, the Army, the administration and CNDD-FDD. For\nthis reason, State entities are often confused with those of the ruling party.\n734. As mentioned earlier in this report,638 Imbonerakure have played an\nincreasingly significant role in the regimenting of the population and the persecution\nof political opponents, real or assumed. The pyramidal organisation follows the\ncountry’s administrative division up to national level where their activities have\nbeen coordinated by a “National Secretary of the CNDD-FDD in charge of the\nmanagement of the leagues affiliated to the party” since 2016. The latter reports to","unnumbered":true},{"id":"a-hrc-39-crp-1-u0062","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":62,"section":"B. Individual responsibilities","text":"the Secretary General of CNDD-FDD.639 Several statements collected by the\nCommission confirmed the party’s control over Imbonerakure.640 Witnesses\nreported close links between Imbonerakure and SNR, particularly in the repression\nof Government and CNDD-FDD opponents,641 some of the witnesses even noting\nthat Imbonerakure act under direct supervision of SNR.642 In addition to confirming\nthe hierarchical function of Imbonerakure inside the CNDD-FDD structure, some\nhighlighted close cooperation and the interlocking of the hierarchy of Imbonerakure\nwith that of SNR, as well as other State institutions and bodies, specifically the\npolice and, to a lesser extent, the Army.643 The confusion that may exist between\nImbonerakure and these State bodies can be partly attributed to the majority of\nagents in both bodies being CNDD-FDD members.\n[…]","unnumbered":true},{"id":"a-hrc-39-crp-1-u0063","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":63,"section":"VI. Conclusions and recommendations","text":"823. In the light of its investigations, the Commission of Inquiry on Burundi is in a\nposition to conclude that the serious human rights violations documented in the first\nyear of its mandate, including crimes against humanity, have persisted in 2017 and\n2018. Such violations include cases of summary execution, disappearance (including\nenforced disappearance), arbitrary arrest and detention, torture and other cruel,\ninhuman or degrading treatment, sexual violence, and violations of civil liberties such\nas the freedoms of expression, association, assembly and movement.\n824. While the State entities that are most often implicated in these violations\ncontinue to be the National Intelligence Service and the police, the Commission is\nconcerned about the growing role being played by the Imbonerakure in a situation in\nwhich recruitment drives among the general public are being used as a means of\nsuppressing all opposition. The Burundian State is responsible for the violations\ncommitted by Imbonerakure in this context.\n825. Perpetrators of violations are operating in an overall climate of impunity. The\nCommission has found that, as matters stand, the Burundian judicial system is both\nunwilling and unable to identify and prosecute those responsible for violations.\n826. The political crisis in Burundi has had a very negative impact on the country’s\neconomic and social situation and has fuelled an increase in poverty. The Government\nhas nonetheless imposed additional taxes and contributions, in contravention of the\nright of all persons to an adequate standard of living, and has failed to devote the\ngreatest possible share of its domestic resources to the realization of economic and\nsocial rights.\n827. In this context, the Commission continues to believe that the Arusha Agreement\nmust remain the basis for any settlement of the crisis in Burundi. The Commission is\nespecially concerned to note that there are no independent international mechanisms\nin Burundi that are in a position to investigate human rights violations.\n828. As the Government of Burundi has not yet implemented the recommendations\nput forward by the Commission in its previous report (A/HRC/36/54), the\nCommission reiterates those recommendations, in particular the ones contained in\nparagraphs 86, 87, 111, 112, 113, 114 and 115.\n829. The Commission recommends that the Human Rights Council extend the\nmandate of the Commission for a period of one year, in view of:\na)     The persistence of serious human rights violations and abuses;","unnumbered":true},{"id":"a-hrc-39-crp-1-u0064","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":64,"section":"VI. Conclusions and recommendations","text":"b)     The lack of action against perpetrators, especially the Imbonerakure,\nsome members of which have continued to be used by State agents for activities\ncontrary to human rights;\nc)    The lack of other international mechanisms in a position to carry out\nindependent and thorough investigations into the human rights situation in Burundi.\n830. The Commission also recommends that the Human Rights Council submit the\nreport and recommendations of the Commission to the United Nations Security\nCouncil for its consideration.\n831. The Commission recommends that the Government of Burundi take the\nfollowing measures as a matter of priority:\na)     Put an immediate end to the gross human rights violations being\ncommitted by agents of the State and Imbonerakure;\nb)     With the support of the international community, establish ad hoc\nmechanisms with a mandate to investigate human rights violations and to prosecute\nperpetrators of international crimes that are not being investigated by the\nInternational Criminal Court;\nc)     With the support of the international community, establish an\nindependent body with a mandate to investigate the cases of disappearance reported\nsince April 2015, locate potential mass graves, and exhume and identify the remains;\nd)     Take measures to ensure that victims of torture and women survivors of\nsexual violence have access to appropriate care, including free access to all sexual and\nreproductive health services and to psychological support;\ne)   Implement the Guidelines on Combating Sexual Violence and its\nConsequences in Africa adopted by the African Commission on Human and Personss’\nRights;\nf)    Control price increases, in particular by reviewing duty and tax\nincreases that are undermining the population’s right to an adequate standard of\nliving and by abolishing contributions that disproportionately affect the poorest\npersons;\ng)     Cooperate with international human rights mechanisms, in particular\nby:\ni)    Resuming the practice of allowing special procedures mandate\nholders to conduct missions to Burundi;\nii)    Implementing the recommendations of the universal periodic\nreview, treaty bodies and special procedures, including by establishing\na national mechanism for reporting and follow-up;\nh)    Authorize the Office of the United Nations High Commissioner for\nHuman Rights to resume all its activities in Burundi without hindrance;\ni)     Sign and implement the memorandum of understanding with the\nAfrican Union and permit the full deployment of the 100 human rights observers\nprovided for therein.\n832. For the medium and longer terms, the Commission also recommends that the\nGovernment of Burundi:\na)    Amend the Organization Act of 8 March 2018 amending Act No. 01/03\nof 24 January 2013 on the mandate, composition, organization and functioning of the\nNational Communication Council with a view to ensuring the latter’s independence;\nb)    Ratify the International Convention for the Protection of All Persons\nfrom Enforced Disappearance;\nc)      Amend the Code of Criminal Procedure to align its provisions with\ninternational standards, in particular the provisions on time limits for police custody","unnumbered":true},{"id":"a-hrc-39-crp-1-u0065","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":65,"section":"VI. Conclusions and recommendations","text":"and on oversight of detention, night-time and warrantless searches, the flagrante\ndelicto procedure and the offence of “undermining the internal security of the State”,\nand provisions that grant de jure impunity to judges and to officers of the criminal\ninvestigation police (police judiciaire);\nd)     Put an end to arbitrary detention and improve conditions of detention\nby:\ni)    Implementing the Guidelines on the Conditions of Arrest, Police\nCustody and Pre-Trial Detention in Africa adopted by the African\nCommission on Human and Personss’ Rights;\nii)    Ensuring that detention is subject to oversight measures for\nassessing its legality and compatibility with human rights;\ne)     In the absence of an independent and efficient judicial system, cooperate\nfully with the International Criminal Court in the investigation opened on 25 October\n2017;\nf)    Undertake an in-depth reform of the judicial system to ensure its\nindependence, impartiality and effectiveness, including by:\ni)     Implementing the Principles and Guidelines on the Right to a Fair\nTrial and Legal Assistance in Africa adopted by the African Commission\non Human and Personss’ Rights;\nii)   Publishing the conclusions of the national forum on the justice\nsystem held in 2013 and convening a meeting of justice-sector\nstakeholders and international partners to discuss follow-up action;\niii) Increasing the budget for the justice sector and ensuring that it is\nmanaged autonomously;\niv)   Raising the pay levels of judges in the ordinary courts and\nincreasing the resources and facilities available to them;\nv)     Computerizing court registries ;\nvi)   Reviewing the composition of the Judicial Service Commission to\nensure that the majority of its members are appointed by their peers;\nvii) Reviewing procedures for the appointment, assignment,\nevaluation and promotion of judges to ensure that such procedures are\nnot dependent on the executive branch;\nviii) Ensuring strict observance of the principle that judges should\nhave security of tenure;\nix)    Protecting and safeguarding the independence of the judiciary by\nprohibiting any interference in the administration of justice by\ngovernment authorities, members of the ruling party or members of the\ndefence and security forces, and imposing penalties on anyone who\ninfluences or seeks to influence the administration of justice;\nx)    Developing legal aid programmes for persons belonging to the\nmost vulnerable groups;\nxi)   Strengthening victim and witness protection mechanisms and\nimproving their effectiveness in order to restore public trust and\nencourage witnesses to come forward without fear for their safety;\ng)    In consultation with the beneficiaries, establish a reparations\nprogramme for victims of human rights violations, ensuring that material, symbolic,\nindividual and collective reparations are made available regardless of whether or not\nthe perpetrators are convicted;\nh)    Establish the State fund for victims of torture provided for by law, in\nconformity with general comment No. 4 on the African Charter on Human and","unnumbered":true},{"id":"a-hrc-39-crp-1-u0066","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":66,"section":"VI. Conclusions and recommendations","text":"Personss’ Rights, adopted by the African Commission on Human and Personss’\nRights, concerning the right to redress for victims of torture and other cruel, inhuman\nor degrading punishment or treatment (art. 5);\ni)     Establish a compensation fund for victims of arbitrary and unlawful\ndetention;\nj)     Reform the security sector by:\ni)      Ensuring that outsiders are not involved in defence or security\nactivities;\nii)    Clearly defining the roles of the various defence and security\nforces, in particular the National Intelligence Service;\niii)   Suspending members of the defence and security forces who are\nsuspected of involvement in human rights violations until the relevant\ninvestigations and judicial proceedings have concluded;\niv)   Establishing rigorous and transparent selection procedures that\ninclude vetting mechanisms;\nv)     Strengthening democratic civilian control over the defence and\nsecurity forces, in particular the National Intelligence Service;\nk)      Meet its international obligations to respect, protect and fulfil economic\nand social rights by:\ni)     Developing and implementing State budgets in such a way as to\nmaximize the use of available resources to ensure that the human rights\nof the sectors impoverished by the political crisis are respected, in\nparticular the rights to food, water and health care, and to develop\nindicators disaggregated by factors such as gender in order to better\ninform its policies;\nii)    In consultation with population groups working in the\nagricultural sector, including women, undertaking reforms with the aim\nof better protecting women’s rights and making better use of land for\nagriculture, and developing employment opportunities outside the\nagricultural sector;\niii)   Taking a rights-based approach to the settlement of land\nconflicts, including those involving persons who fled Burundi either\nbefore or after 2015;\niv)   Ending the inclusion of any political considerations in hiring\nprocesses for the civil service, State enterprises and public-private\nenterprises.\n833. The Commission recommends that political parties and armed opposition\ngroups refrain from engaging in any attacks on Burundian territory and from any\nspeech calling for violence, and that they join the effort to find a lasting solution to the\npolitical crisis.\n834. The Commission recommends that the African Union, in its efforts to find a\nlasting solution to the crisis in Burundi, give priority to respect for human rights and\nthe rejection of impunity, as provided for in its Constitutive Act.\n835. The Commission recommends that the technical and financial partners of\nBurundi:\na)      Suspend, or maintain the suspension of, any direct budget support to the\nGovernment until such time as priority is given to the allocation of domestic resources\nfor the fulfilment of the Sustainable Development Goals and the economic and social\nrights of the population, and effective measures are taken against corruption;","unnumbered":true},{"id":"a-hrc-39-crp-1-u0067","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":67,"section":"VI. Conclusions and recommendations","text":"b)     Ensure that grants and financing provided to the Government are\nearmarked for projects to meet the population’s needs, and ensure that such funding\nis managed effectively and transparently;\nc)      Regularly evaluate the impact of financial sanctions on the persons of\nBurundi.\n836. The Commission recommends that the guarantors of the Arusha Agreement,\nin their capacity as committed proponents of a lasting peace in Burundi, continue to\nseek a durable solution to the political and human rights crisis that will preserve and\nsafeguard the achievements of the Arusha Agreement.","unnumbered":true},{"id":"a-hrc-39-crp-1-u0068","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":68,"section":"2. Investigate these violations, ensure that the alleged perpetrators are prosecuted","text":"promptly in accordance with credible, independent and fair procedures, and\nthat the victims obtain just reparation, and, where the alleged perpetrators are\nagents of the State, suspend them from their duties pending the completion of\nthe investigation and the judicial proceedings;","unnumbered":true},{"id":"a-hrc-39-crp-1-u0069","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":69,"section":"3. Take practical measures to bring about a rapid improvement of the human","text":"rights situation, in particular by:\n•   Withdrawing the warrants for the arrest of heads of media outlets, civil\nsociety organizations and political parties who have neither used nor\nadvocated violence, and permitting their safe return to Burundi;\n•   Lifting the suspension and reversing the revocation of the licences of media\nand civil society organizations, permitting them to resume their activities\nwith complete independence and reviewing the laws adopted in 2017\nconcerning no-profit organizations and foreign no-governmental\norganizations;\n•   Immediately releasing all political prisoners;\n•   Ensuring that every person arrested is detained in an official place of\ndetention and that national and international observers are allowed to visit\nthem;\n•   Ensure that criminal investigation officers (officiers de police judiciaire) are\nnot authorized to conduct searches without a warrant, including at night,\nas envisaged in the draft amendments to the Criminal Code and the Code\nof Criminal Procedure;\n•   Ensuring that individuals lacking legal authorization, particularly the\nImbonerakure, do not perform or participate in law enforcement activities,\nincluding in places of detention, and do not wear military or police\nuniforms or possess weapons;\n•   Prosecuting individuals who incite hatred or violence;\n•   Putting an end to threats, intimidation and acts of extortion by State\nofficials and the Imbonerakure;\n•   Giving victims of sexual violence and torture access to medical and\npsychosocial services;\n4.    Undertake a thorough reform of the judiciary, in particular by:\n•   Publishing the conclusions of the General Convention on the Judiciary\n(États généraux de la justice) held in Gitega in 2013;\n•   Reviewing the composition of the Superior Council of Magistrates (Conseil\nsupérieur de la magistrature) so that the majority of its members are\ndesignated by their peers;\n•   Reviewing the nomination, posting, evaluation and promotion procedures\nof magistrates so that they do not depend of the executive;\n•   Ensuring the respect of the principle of security of tenure for judges;\n•   Protecting and guaranteeing the independence of the judiciary by\nprohibiting all interference in their functions by governmental authorities,\nmembers of the ruling party or security and defence forces, and imposing\nsanctions on those who influence, or seek to influence, the functioning of\nthe judiciary;","unnumbered":true},{"id":"a-hrc-39-crp-1-u0070","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":70,"section":"3. Take practical measures to bring about a rapid improvement of the human","text":"•   Developing legal aid programmes for the most vulnerable;\n•   Reinforcing the protection mechanisms for victims and witnesses, as well\nas their efficiency, in order to restore persons’s confidence in the system\nand to encourage witnesses to testify without fear for their security;","unnumbered":true},{"id":"a-hrc-39-crp-1-u0071","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":null,"seq":71,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"in all circumstances and serve the interests of the population as a whole, not\nsolely those of the ruling party, in particular by:\n•   Reinforcing civilian control over the military and the independence of the\ncompetent organs created by the Constitution to supervise this control, in\nparticular the Parliament, the National Human Rights Commission and\nthe Ombudsman;\n•   Implementing civilian control over the National Intelligence Service\n(Service national de renseignement) in line with the Constitution;\n•   Conducting background checks, in particular on human rights, on defence\nand security forces and incorporating these measures into reforms of the\nrecruitment and career progression of these agents;","unnumbered":true},{"id":"a-hrc-39-crp-1-p0006","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"6","seq":72,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"Reconsider their decision to withdraw from the Rome Statute, cooperate fully\nwith the International Criminal Court in the ongoing preliminary examination\nand, if an investigation is initiated, continue that cooperation, inter alia by\nensuring the protection of victims and witnesses;"},{"id":"a-hrc-39-crp-1-p0007","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"7","seq":73,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"Authorize the Office of the United Nations High Commissioner for Human\nRights to resume its documentation of human rights violations in Burundi,\nwhich has been suspended since October 2016;"},{"id":"a-hrc-39-crp-1-p0008","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"8","seq":74,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"Sign and implement the memorandum of understanding with the African\nUnion and permit the full deployment of 100 human rights observers and 100\nmilitary experts that was decided upon in 2016;"},{"id":"a-hrc-39-crp-1-p0009","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"9","seq":75,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"Cooperate with United Nations human rights mechanisms by once again\nreceiving special procedures missions and implementing the recent\nrecommendations of treaty bodies;"},{"id":"a-hrc-39-crp-1-p0010","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"10","seq":76,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"Actively seek a lasting solution to the political crisis, inter alia through\ninternational initiatives to promote dialogue.\nPolitical parties and armed opposition groups should:"},{"id":"a-hrc-39-crp-1-p0011","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"11","seq":77,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"Put an immediate end to human rights abuses and acts of violence committed\nby their members;"},{"id":"a-hrc-39-crp-1-p0012","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"12","seq":78,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"Refrain from any incitement of violence and participate in the quest for a\nlasting solution to the political crisis in Burundi.\nThe Human Rights Council should:"},{"id":"a-hrc-39-crp-1-p0013","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"13","seq":79,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"Extend the Commission’s mandate for a period of one year to enable it to\nconduct further and more thorough investigations in view of the persistence of\ngross human rights violations and abuses and the absence of other specific\nmechanisms capable of undertaking independent and thorough investigations\ninto the human rights situation in Burundi;"},{"id":"a-hrc-39-crp-1-p0014","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"14","seq":80,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"Request the Office of the United Nations High Commissioner for Human Rights\nto report, at the forthcoming sessions of the Council, on the development of its\ncooperation with the Burundian Government.\nThe International Criminal Court should:"},{"id":"a-hrc-39-crp-1-p0015","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"15","seq":81,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"Initiate, as soon as possible, an investigation into the crimes committed in\nBurundi in light of the conclusions contained in the present report and other\ninformation at its disposal.\nThe United Nations Security Council should:"},{"id":"a-hrc-39-crp-1-p0016","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"16","seq":82,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"Take due account of the Commission’s conclusions, as well as persistence of\ngross violations of human rights, in any discussion on Burundi and, in this\ncontext, ensure the effective implementation of resolution 2303 (2016);"},{"id":"a-hrc-39-crp-1-p0017","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"17","seq":83,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"Refer to the International Criminal Court any international crime that might\nbe committed in Burundi after 27 October 2017;"},{"id":"a-hrc-39-crp-1-p0018","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"18","seq":84,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"Impose individual sanctions against the principal alleged perpetrators of gross\nhuman rights violations and international crimes in Burundi.\nThe Secretary-General of the United Nations should:"},{"id":"a-hrc-39-crp-1-p0019","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"19","seq":85,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"Ensure that respect for human rights and restoration of the rule of law are\namong the priorities of his Special Envoy for Burundi;"},{"id":"a-hrc-39-crp-1-p0020","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"20","seq":86,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"Ensure that no alleged perpetrator of human rights violations or international\ncrimes in Burundi is recruited for United Nations peacekeeping missions.\nThe States Members of the United Nations should:"},{"id":"a-hrc-39-crp-1-p0021","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"21","seq":87,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"Grant prima facie refugee status to Burundian asylum seekers and ensure strict\nrespect for the principle of no-refoulement and refugee protection;"},{"id":"a-hrc-39-crp-1-p0022","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"22","seq":88,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"Prosecute, in accordance with the principle of universal jurisdiction, alleged\nperpetrators of international crimes committed in Burundi who are found to\nbe in their territory;"},{"id":"a-hrc-39-crp-1-p0023","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"23","seq":89,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"Maintain, in the absence of any improvement in the human rights situation in\nBurundi, the individual sanctions and the suspension of direct aid to the\nGovernment;"},{"id":"a-hrc-39-crp-1-p0024","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"24","seq":90,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"Provide technical assistance inter alia in respect to autopsies, exhumations and\nidentification of bodies, to enable the Burundian to conduct credible and\nindependent investigations;"},{"id":"a-hrc-39-crp-1-p0025","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"25","seq":91,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"Support the establishment of specialized medical and psychosocial services,\nespecially for victims of torture and sexual violence;"},{"id":"a-hrc-39-crp-1-p0026","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"26","seq":92,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"Support Burundian authorities in any judicial and security sector reform\nendeavours that they might wish to undertake in order to improve the human\nrights situation.\nThe African Union should:"},{"id":"a-hrc-39-crp-1-p0027","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"27","seq":93,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"Retake the lead in seeking a lasting solution to the crisis in Burundi based on\nrespect for human rights and rejection of impunity, as provided for in its\nConstitutive Act, and play an active role in that process;"},{"id":"a-hrc-39-crp-1-p0028","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"28","seq":94,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"Ensure that no agent of the Burundian State who is accused of human rights\nviolations or international crimes is recruited for African Union peacekeeping\nmissions;"},{"id":"a-hrc-39-crp-1-p0029","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"29","seq":95,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"Ensure that the full complement of African Union human rights observers and\nmilitary experts is deployed rapidly in Burundi;"},{"id":"a-hrc-39-crp-1-p0030","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"30","seq":96,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"Consider, in the event that the current situation in Burundi persists, the\napplication of Article 4 (h) of the Constitutive Act of the African Union, under\nwhich it is authorized to intervene in a member State in certain circumstances,\nparticularly in the event of crimes against humanity.\nThe East African Community should:"},{"id":"a-hrc-39-crp-1-p0031","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"31","seq":97,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"Ensure that a rapid improvement of the human rights situation is a priority in\nits mediation efforts.\nThe guarantors of the 2000 Arusha Agreement, in their capacity as committed\nproponents of a lasting peace in Burundi, should:"},{"id":"a-hrc-39-crp-1-p0032","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"32","seq":98,"section":"5. Ensure that members of the defence and security forces respect human rights","text":"Meet with a view to finding a lasting solution to the political and human rights\ncrisis in Burundi."},{"id":"a-hrc-39-crp-1-p0001-a1","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"1","seq":99,"section":"III. Correspondence with the Government of Burundi","text":"Note verbale sent to the Permanent Mission of Burundi on 10 October 2017","annex":1},{"id":"a-hrc-39-crp-1-p0002-a1","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"2","seq":100,"section":"III. Correspondence with the Government of Burundi","text":"Note verbale sent to the Permanent Mission of Burundi on 30 November 2017,\ntransmitting a letter addressed to the Minister for Foreign Affairs and\nInternational Cooperation of Burundi","annex":1},{"id":"a-hrc-39-crp-1-p0003-a1","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"3","seq":101,"section":"III. Correspondence with the Government of Burundi","text":"Note verbale sent to the Permanent Mission of Burundi on 11 January 2018","annex":1},{"id":"a-hrc-39-crp-1-p0004-a1","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"4","seq":102,"section":"III. Correspondence with the Government of Burundi","text":"Letter sent to the Permanent Mission of Burundi on 2 March 2018","annex":1},{"id":"a-hrc-39-crp-1-p0005-a1","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"5","seq":103,"section":"III. Correspondence with the Government of Burundi","text":"Note verbale sent to the Permanent Mission of Burundi on 13 March 2018","annex":1},{"id":"a-hrc-39-crp-1-p0006-a1","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"6","seq":104,"section":"III. Correspondence with the Government of Burundi","text":"Note verbale sent to the Permanent Mission of Burundi on 26 June 2018","annex":1},{"id":"a-hrc-39-crp-1-p0007-a1","rec_id":"rec4k1z0OD5d5iOIM","symbol":"A/HRC/39/CRP.1","n":"7","seq":105,"section":"III. Correspondence with the Government of Burundi","text":"Note verbale sent to the Permanent Mission of Burundi on 27 August 2018","annex":1},{"id":"a-hrc-42-49-u0000","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":0,"section":null,"text":"United Nations                                                                                      A/HRC/42/49\nGeneral Assembly                                                             Distr.: General\n6 August 2019\nEnglish\nOriginal: French","unnumbered":true},{"id":"a-hrc-42-49-u0001","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":1,"section":null,"text":"Summary\nSerious human rights violations have continued to be committed in Burundi since\nMay 2018, in a general climate of impunity. Some of these violations constitute\ninternational crimes. Members of the youth league of the ruling party, the Imbonerakure,\nare the main perpetrators. Officers of the National Intelligence Service and the police, along\nwith local administrative officials, are also frequently identified as perpetrators of such\nviolations.\nBurundi has been experiencing a political and economic crisis for more than four\nyears. The human rights violations are essentially political in nature, and the suppression of\ncivil liberties is intensifying in the run-up to the 2020 presidential and legislative elections.\nIn accordance with the principles of early warning and prevention, the Commission has\nidentified several risk factors in the current environment. The evolving situation must be\nmonitored with the greatest vigilance.","unnumbered":true},{"id":"a-hrc-42-49-u0002","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":2,"section":null,"text":"* It was agreed that the present report would be issued after the usual date of issue owing to\ncircumstances beyond the submitter’s control.\n** The annexes to the present document are being circulated as received, in the language of submission\nonly.","unnumbered":true},{"id":"a-hrc-42-49-p0001","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"1","seq":3,"section":"A. Mandate","text":"The Commission of Inquiry on Burundi was created by Human Rights Council\nresolution 33/24, adopted on 30 September 2016, to conduct a thorough investigation into\nhuman rights violations and abuses committed in Burundi since April 2015, to determine\nwhether any of them may constitute international crimes, to identify their alleged\nperpetrators and to formulate recommendations for ensuring that such perpetrators are held\naccountable for their acts. This mandate was extended for two additional one-year periods,\nby resolution 36/19, adopted on 29 September 2017, and by resolution 39/14, adopted on\n28 September 2018."},{"id":"a-hrc-42-49-p0002","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"2","seq":4,"section":"A. Mandate","text":"The membership of the Commission remains unchanged: Doudou Diène (Senegal),\nwho has chaired the body since 1 February 2018; Lucy Asuagbor (Cameroon), a member\nsince 5 March 2018; and Françoise Hampson (United Kingdom of Great Britain and\nNorthern Ireland), appointed on 22 November 2016."},{"id":"a-hrc-42-49-p0003","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"3","seq":5,"section":"A. Mandate","text":"The Commission has looked into violations and abuses committed since May 2018,1\npaying special attention to those related to the 2020 electoral process. 2 Using objective\nindicators defined at the international level,3 it has sought to determine whether there are\nany risk factors pointing to a possible deterioration in the human rights situation. These\nefforts are in keeping with the principles of early warning and prevention4 and have\nprovided valuable information on the current situation and potential developments."},{"id":"a-hrc-42-49-p0004","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"4","seq":6,"section":"A. Mandate","text":"In 2019, the Commission presented two oral briefings to the Human Rights Council.\nThe present report summarizes the final conclusions of its investigations, which will be\ndetailed in a separate document.5"},{"id":"a-hrc-42-49-p0005","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"5","seq":7,"section":"B. Cooperation by Burundi with the Commission","text":"As in the past, when it extended the Commission’s mandate, the Human Rights\nCouncil urged the Government of Burundi to cooperate fully with the Commission, to\nauthorize it to conduct visits to the country and to provide it with all the information\nnecessary to fulfil its mandate.6 In that spirit of cooperation, the Commission wrote to the\nBurundian authorities seeking to arrange a meeting in Geneva, transmitting requests for\nspecific information and providing a non-exhaustive list of human rights indicators to\nenable the Government to assess, in an objective manner, the impact of its policies and\npractices to protect and promote human rights. All of these communications have gone\nunanswered."},{"id":"a-hrc-42-49-p0006","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"6","seq":8,"section":"B. Cooperation by Burundi with the Commission","text":"The Burundian authorities have continued to reject the Commission’s work wholly\nand systematically, deeming it politically biased, but have offered no evidence to\nsubstantiate their accusations. They also tried, without success, to prevent the\nCommission’s report from being presented to the General Assembly in October 2018,\ndespite an explicit request to that effect by the Human Rights Council.7 The hostility of the\nBurundian authorities continued, with the Commission’s members being declared personae\n1 In order to highlight developments since the previous report (A/HRC/39/63), which covered the\nperiod 2017–2018.\n2\nPresidential and legislative elections are scheduled for 20 May 2020, and elections to the Senate for\n20 July 2020.\n3 Framework of Analysis for Atrocity Crimes (A/70/741-S/2016/71).\n4 See, for example, A/HRC/30/20.\n5 Document A/HRC/42/CRP.2, available on the Commission’s website.\n6 Human Rights Council resolution 33/24 of 30 September 2016, para. 24; and Human Rights Council\nresolution 36/19 of 29 September 2017, para. 5.\n7 Human Rights Council resolution 36/19 of 29 September 2017, para. 4.\nnon gratae in the territory of Burundi,8 subjected to threats and personal abuse, and\nthreatened with prosecution for “defamation” and “attempted destabilization” of the\ncountry."},{"id":"a-hrc-42-49-p0007","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"7","seq":9,"section":"C. Methodology","text":"The Commission undertook visits to the Democratic Republic of the Congo,\nRwanda, the United Republic of Tanzania, Belgium, France, the United Kingdom and\nEthiopia. It met with representatives of the African Union, the European Union and various\nStates, and conducted over 300 interviews with victims, witnesses and other sources living\nin Burundi or in third countries, in person or remotely, to add to the more than 1,000\ntestimonies already collected. If the Commission’s mandate is renewed, it hopes to visit all\naffected States in the region."},{"id":"a-hrc-42-49-p0008","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"8","seq":10,"section":"C. Methodology","text":"The Commission continued to apply the same methodology and the same standard\nof evidence, “reasonable grounds to believe”, which are fully consistent with internationally\naccepted guidance and practice for this type of inquiry. 9"},{"id":"a-hrc-42-49-p0009","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"9","seq":11,"section":"D. Applicable law","text":"The applicable law is international human rights law and international criminal\nlaw.10 Burundi remains a party to the same conventions as before, having not yet ratified the\ntreaties to which it indicated its readiness to become a party during the third universal\nperiodic review of the country, in January 2018."},{"id":"a-hrc-42-49-p0010","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"10","seq":12,"section":"D. Applicable law","text":"The withdrawal of Burundi from the Rome Statute of the International Criminal\nCourt, which took effect on 27 October 2017, does not discharge the country from the\nobligations arising therefrom while it was a party to the treaty11 or from its obligations\nunder customary international law concerning international crimes. The Commission has\nreferred to the definitions of crimes set forth in the Rome Statute, which are reflected in the\nCriminal Code of Burundi."},{"id":"a-hrc-42-49-p0011","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"11","seq":13,"section":"E. Developments within international and regional bodies","text":"Burundi has stressed many times its willingness to cooperate with international\nhuman rights mechanisms, other than the Commission. However, the Government\ndemanded the closure of the Burundi office of the Office of the United Nations High\nCommissioner for Human Rights, which took effect on 28 February 2019. The\nSubcommittee on Prevention of Torture and Other Cruel, Inhuman or Degrading Treatment\nor Punishment was unable to visit Burundi in 2018, as it had announced, even though States\nparties to the Optional Protocol to the Convention against Torture and Other Cruel,\nInhuman or Degrading Treatment or Punishment have a legal obligation to receive\ndelegations from the Subcommittee and grant them access to places of detention. Moreover,\nBurundi has not submitted to the treaty bodies some of its periodic reports on the\nimplementation of human rights instruments, notably the report in relation to the\nInternational Convention on the Elimination of All Forms of Racial Discrimination, which\nhas been due since November 1998."},{"id":"a-hrc-42-49-p0012","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"12","seq":14,"section":"E. Developments within international and regional bodies","text":"Despite the standing invitation granted by Burundi to special procedures mandate\nholders, no special rapporteur or working group has been able to visit the country since\nDecember 2014, and no visit is scheduled for the coming months, although the Special\nRapporteur on torture and other cruel, inhuman or degrading treatment or punishment and\nthe Working Group on Enforced or Involuntary Disappearances have requested visits. Since\nFebruary 2016, Burundi has ceased to cooperate with the special procedures mandate\nholders on alleged cases of human rights violations."},{"id":"a-hrc-42-49-p0013","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"13","seq":15,"section":"E. Developments within international and regional bodies","text":"Pursuant to its resolution 2303 (2016), the Security Council has continued to review\nthe situation in Burundi regularly, on 21 November 2018, 19 February 2019 and 14 June\n2019.12 The Special Envoy of the Secretary-General for Burundi, Michel Kafando, and\nrepresentatives of States members of the African Union have reiterated their concerns about\nthe current political situation and the impasse reached in the inclusive inter-Burundi\ndialogue, particularly in the light of the forthcoming elections, and about the human rights\nsituation and socioeconomic conditions.13"},{"id":"a-hrc-42-49-p0014","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"14","seq":16,"section":"E. Developments within international and regional bodies","text":"The most recent round of inter-Burundi talks, which took place in October 2018 in\nArusha, Tanzania, under the leadership of the Facilitator, Benjamin Mkapa, was boycotted\nby the Government of Burundi. The Facilitator completed his work on 1 February 2019\nwith the presentation of his final report to the Summit of Heads of State of the East African\nCommunity, without having achieved any tangible results. The East African Community\nhas not yet taken any steps to relaunch the dialogue."},{"id":"a-hrc-42-49-p0015","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"15","seq":17,"section":"E. Developments within international and regional bodies","text":"On 13 November 2018, the African Commission on Human and Peoples’ Rights\nadopted a resolution on the human rights situation in Burundi, 14 in which it expressed its\nconcern about the lack of adequate and independent inquiries into reported cases of human\nrights violations and the non-implementation of the recommendations it had made in 2015.\nIn the resolution, it urges Burundi to cooperate with the African Union, the United Nations\nand the East African Community in the search for a peaceful and human rights responsive\nsolution to the crisis situation in Burundi."},{"id":"a-hrc-42-49-p0016","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"16","seq":18,"section":"E. Developments within international and regional bodies","text":"According to the Office of the United Nations High Commissioner for Refugees,\nthere were 344,931 Burundian refugees in neighbouring countries as at 30 June 2019, and\n3,603 new arrivals had been registered between 1 January and 30 June 2019. 15 The\nhumanitarian crisis affecting the Burundian refugees is the world’s most underfinanced\nemergency. Thus, in 2018, the Office received only 33 per cent of the annual budget sought\nand, at the end of June 2019, only 18 per cent of the requested annual funds had been\nreceived. The Office is not recommending the return of refugees to Burundi but has been\nhelping those who choose to go back on a voluntary basis since September 2017. Between\nJanuary and June 2019, 14,104 persons returned to the country. 16"},{"id":"a-hrc-42-49-p0017","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"17","seq":19,"section":"E. Developments within international and regional bodies","text":"In 2019, according to the figures agreed by the Office for the Coordination of\nHumanitarian Affairs and the Government of Burundi, 1.77 million persons are in need of\nhumanitarian assistance and 1.7 million are suffering from food insecurity. 17 There remain\n116,000 internally displaced persons, the majority of whom are economically vulnerable\nwomen heads of household. As at 4 July 2019, 30 per cent of the budget needed to cover\nhumanitarian needs in 2019, estimated at US$ 106.3 million, had been received.\n12 The meeting initially scheduled for 28 May 2019 was cancelled at the last minute and postponed to 14\nJune 2019, in the absence of Mr. Kafando.\n13 See S/PV.8408, S/PV.8465 and S/PV.8550.\n14\nAfrican Commission on Human and Peoples’ Rights, Resolution on the Human Rights Situation in\nthe Republic of Burundi, document ACHPR/Res. 412 (LXII) 2018.\n15 This figure does not necessarily include all new arrivals as, in some countries, it has become virtually\nimpossible for Burundians to obtain refugee status.\n16 UNHCR, Regional overview of the Burundian refugee population, 30 June 2019. Available at\nhttps://data2.unhcr.org/en/documents/download/70281 (in English only).\n17 Office for the Coordination of Humanitarian Affairs, Burundi Situation Report, updated on 4 July\n2019. Available at https://reports.unocha.org/en/country/burundi."},{"id":"a-hrc-42-49-p0018","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"18","seq":20,"section":"E. Developments within international and regional bodies","text":"The targeted sanctions imposed on certain Burundian nationals by the European\nUnion and Switzerland were extended until October 2019. The sanctions imposed by the\nUnited States of America were kept in place in the case of 11 Burundian nationals."},{"id":"a-hrc-42-49-p0019","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"19","seq":21,"section":"E. Developments within international and regional bodies","text":"The investigation opened on 25 October 2017 by the Prosecutor of the International\nCriminal Court into crimes against humanity committed in Burundi between 26 April 2015\nand 26 October 2017 is continuing."},{"id":"a-hrc-42-49-p0020","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"20","seq":22,"section":"A. Main trends","text":"The main human rights violations continue to have a political dimension and\nconcern the right to life, security and liberty, the right not to be subjected to torture or ill-\ntreatment, cases of sexual violence and breaches of civil liberties. They occurred in the\nwake of the constitutional referendum in May 2018 or are taking place against the backdrop\nof preparations for the 2020 elections. For the most part, the victims continue to be\nopponents – actual or alleged – of the Government or the ruling party (the Conseil national\npour la défense de la démocratie-Forces pour la défense de la démocratie (CNDD-FDD)),\nfirst and foremost members of the new political opposition party led by Agathon Rwasa, the\nCongrès national pour la liberté, which was registered in February 2019. Others targeted are\nBurundian nationals who, having sought refuge abroad, have returned to the country since\nthe beginning of 2017 under the assistance programme for repatriation, as well as young\nmen who have come back to Burundi following a stay or a trip abroad, who are accused of\nbelonging to or supporting armed opposition groups. Human rights defenders remain\ntargets, as is demonstrated by the upholding on appeal, on 17 July 2019, of the 32-year\nprison sentence imposed on Germain Rukuki."},{"id":"a-hrc-42-49-p0021","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"21","seq":23,"section":"A. Main trends","text":"Imbonerakure, officers of the National Intelligence Service and the police and\nadministrative officials in the municipalities (communes), districts (zones) and hill districts\n(collines) have been identified as perpetrators of the violations documented. The majority\nof cases have taken place in rural areas controlled by the Imbonerakure, who seek to keep\nthe population in check and compel their allegiance to CNDD-FDD. These efforts target the\nentire population, particularly at the grass-roots level. According to the testimonies\ngathered, members of the defence forces do not seem to have been involved to a significant\nextent in the main violations documented since May 2018, even though isolated incidents\nhave been reported."},{"id":"a-hrc-42-49-p0022","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"22","seq":24,"section":"A. Main trends","text":"The fact that these violations are committed chiefly by Imbonerakure in rural areas,\ncoupled with victims’ fear or their general reluctance to bring complaints owing to a lack of\nconfidence in the judicial system, makes it more complicated to corroborate the many\nallegations of violations received."},{"id":"a-hrc-42-49-p0023","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"23","seq":25,"section":"1. Responsibility of the Burundian State","text":"As in the past, the Commission has found that the Burundian State may be held\nresponsible for the acts identified in the present report, which constitute human rights\nviolations.18"},{"id":"a-hrc-42-49-p0024","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"24","seq":26,"section":"1. Responsibility of the Burundian State","text":"The actions of agents of the State, particularly officers of the National Intelligence\nService and the police, but also of the administrative authorities that represent the State in\nthe provinces, municipalities, districts and hill districts, are directly attributable to the\nBurundian State, in conformity with its obligation to respect human rights and ensure that\nits agents refrain from violating them.\n18   See A/HRC/36/54 and Corr.1, and A/HRC/39/63."},{"id":"a-hrc-42-49-p0025","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"25","seq":27,"section":"1. Responsibility of the Burundian State","text":"The Imbonerakure often act alone or sometimes in the presence of representatives of\nthe police, the National Intelligence Service or local authorities. They enjoy considerable\nlatitude in carrying out their activities, conferred on them by the Burundian authorities,\nwhich, however, have the means to control them, as well as almost total impunity.\nImbonerakure are still regularly – indeed, almost routinely – used to supplement or replace\nthe security forces, particularly in rural areas, at the request or with the consent of\nmembers, including senior officials, of the National Intelligence Service, the police, the\nOffice of the President and local authorities. Some have military material and equipment\nreserved in principle for the defence and security forces, such as items of military uniform\nand boots, which attests to their central role within the formal and informal security\nstructures of the Burundian State. When the conduct of the Imbonerakure is acknowledged\nand adopted by agents of the State,19 when they act on the instructions of such agents20 or\nwhen they act in “complete dependence” on or under the “effective control” of such\nagents,21 the Burundian State is directly responsible for their actions."},{"id":"a-hrc-42-49-p0026","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"26","seq":28,"section":"1. Responsibility of the Burundian State","text":"In the rare cases in which Imbonerakure reportedly acted outside these scenarios, the\ngeneral impunity they enjoy following their acts also means that the responsibility of the\nBurundian State is engaged, in conformity with its obligation to protect human rights.\nIndeed, the State must, when it is aware or should have been aware of violations or abuses\ncommitted by third parties, undertake effective investigations and prosecutions, which has\nnot generally been the case."},{"id":"a-hrc-42-49-p0027","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"27","seq":29,"section":"2. Responsibility of armed groups and opposition political parties","text":"Because the Commission has not had access to victims and the Government has\nrepeatedly refused to hand over evidence, the Commission has been unable to corroborate\nthe information it has received on the involvement of armed groups in human rights\nviolations.\nC.          Violations of civil and political rights22"},{"id":"a-hrc-42-49-p0028","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"28","seq":30,"section":"1. Right to life","text":"Violations of the right to life are increasingly difficult to document because bodies\nare regularly found in public places, often bearing signs of violent death, without the\ncircumstances of the deaths being elucidated. The Commission has received no information\nconcerning steps taken by the authorities to identify the victims, investigate the causes and\ncircumstances of their deaths or find those responsible. Such failings by the Burundian\nauthorities make it ever more complex to distinguish between disappearances and\nexecutions. Many people disappear without there being any witnesses, and their fate\nremains unknown except in cases where a body is found in the days that follow. Indeed,\nmost families see no purpose in filing a complaint or fear reprisals if they seek information\nfrom the authorities about the fate of their missing relatives.\n(b)         Summary execution"},{"id":"a-hrc-42-49-p0029","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"29","seq":31,"section":"1. Right to life","text":"Summary executions have been committed mainly by members of the National\nIntelligence Service and by Imbonerakure acting alone. Some victims are beaten to death,\nwhile others are executed with firearms or knives.\n19 Yearbook of the International Law Commission, 2001, vol. II, part two (United Nations publication,\nsales No.: F.04.V.17 (part II)), International Law Commission, articles on responsibility of States for\ninternationally wrongful acts, art. 11, p. 26.\n20 Ibid., International Law Commission, articles on responsibility of States for internationally wrongful\nacts, art. 8, p. 26.\n21 A/HRC/39/63, paras. 20–27.\n22 For more details of such violations, see document A/HRC/42/CRP.2."},{"id":"a-hrc-42-49-p0030","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"30","seq":32,"section":"1. Right to life","text":"In certain cases, the bodies are found on the public highway or in watercourses, but\nsometimes the perpetrators take pains to hide them."},{"id":"a-hrc-42-49-p0031","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"31","seq":33,"section":"1. Right to life","text":"Acting in place of the authorities, Imbonerakure have killed persons accused of\nordinary crimes, including theft and witchcraft, thus arrogating to themselves the right to\ndispense justice.\n(c)        Enforced and other disappearances"},{"id":"a-hrc-42-49-p0032","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"32","seq":34,"section":"1. Right to life","text":"The Commission has pursued its inquiries into alleged cases of enforced\ndisappearance in which information or corroboration was lacking and there were thus only\nreasonable grounds to fear that an enforced disappearance had taken place. 23 In the light of\nthe new information gathered, the Commission confirms there are reasonable grounds to\nbelieve that Marie-Claudette Kwizera, treasurer of the Ligue Iteka, missing since 10\nDecember 2015, and Oscar Ntasano, a businessman, member of CNDD-FDD and former\nsenator and deputy, missing since 20 April 2017, have indeed been victims of enforced\ndisappearance. The Commission has also received information indicating that they have\nbeen executed."},{"id":"a-hrc-42-49-p0033","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"33","seq":35,"section":"1. Right to life","text":"Numerous disappearances have been reported. The victims, who sometimes had no\npolitical affiliations, disappeared after refusing to join CNDD-FDD or the Imbonerakure.\nSome were members of opposition political parties or had recently returned from exile.\nOften, they were last seen being taken away by Imbonerakure. The families generally chose\nto flee and only rarely carried out searches for their missing relatives. In the light of the\ncurrent situation in Burundi, which is conducive to enforced disappearance, and given the\nnumerous previous cases, the profile of the victims and the circumstances of the\ndisappearances, which resemble the modus operandi documented in the earlier cases, while\nthe Commission cannot conclude that these are enforced disappearances within the meaning\nof international law, nor can it exclude the possibility. It remains deeply concerned about\nthe frequency of such disappearances."},{"id":"a-hrc-42-49-p0034","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"34","seq":36,"section":"2. Right to liberty and security of person","text":"Arbitrary arrest and detention on political grounds have continued. Since the\nestablishment of the Congrès national pour la liberté in February 2019, its members have\nbeen the main targets of arbitrary arrest and detention in connection with their legitimate\npolitical activities; they are generally accused of organizing or taking part in “illegal\nmeetings” of small groups on private premises, which, however, are not offences under\nnational law. The members of other opposition parties have also been targeted and often\neven accused of supporting armed opposition groups. Sometimes, when those persons could\nnot be located, their family members were arrested in their place. Other persons were\narrested and detained following the May 2018 constitutional referendum on suspicion of\nhaving campaigned for a “No” vote. Minor schoolgirls were held for around 10 days and\nprosecuted for “insult to the Head of State” when it was discovered that photographs of the\nPresident in school textbooks had been defaced."},{"id":"a-hrc-42-49-p0035","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"35","seq":37,"section":"2. Right to liberty and security of person","text":"Arbitrary arrests have been carried out by officers of the police and the National\nIntelligence Service, but also by Imbonerakure and local administrative officials, who acted\neither jointly with the police or independently of them, later handing over those arrested to\nthe police."},{"id":"a-hrc-42-49-p0036","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"36","seq":38,"section":"2. Right to liberty and security of person","text":"These arrests were arbitrary, since, in the vast majority of cases, they were\nconducted without any legal basis, on grounds that are sufficiently vague in national law as\nto be abused or in breach of established judicial procedure. Moreover, these arrests often\ninvolved the use of excessive force. They were also illegal when carried out by\nImbonerakure or local administrative authorities, which are not authorized by law to make\narrests other than in cases of flagrante delicto."},{"id":"a-hrc-42-49-p0037","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"37","seq":39,"section":"2. Right to liberty and security of person","text":"The detentions were arbitrary and often illegal owing to the vague and abusive\nnature of the charges brought, the absence of the elements of the offences alleged and the\n23   A/HRC/36/CRP.1, para. 319.\nfailure to respect procedural guarantees and time limits prescribed by law. Prisoners who\nhave served their sentences or who have received presidential pardons have continued to be\nheld arbitrarily, mainly those convicted on political grounds."},{"id":"a-hrc-42-49-p0038","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"38","seq":40,"section":"3. Torture and other cruel, inhuman or degrading treatment","text":"Torture and ill-treatment persist throughout the country. Particularly serious cases of\ntorture have concerned young men accused of collaborating with opposition armed groups,\nspying (often because they have spent time in exile or living abroad) or campaigning\nactively for a “No” vote in the constitutional referendum. Such acts have generally been\ncommitted by officers of the National Intelligence Service and the police during arbitrary\narrests or detentions."},{"id":"a-hrc-42-49-p0039","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"39","seq":41,"section":"3. Torture and other cruel, inhuman or degrading treatment","text":"At the time of the May 2018 constitutional referendum, numerous men and women\nof all ages were subjected to torture or ill-treatment by Imbonerakure, often acting alone but\nsometimes with police officers or local administrative officials. These persons were\nsuspected of not having voted “Yes” or had refused to join CNDD-FDD or the\nImbonerakure. Members of the Congrès national pour la liberté and recently returned\nrefugees were also targeted."},{"id":"a-hrc-42-49-p0040","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"40","seq":42,"section":"3. Torture and other cruel, inhuman or degrading treatment","text":"Some victims were kicked or beaten with sticks or batons on different parts of their\nbodies, while others were wounded with sharp objects. In several cases, the torture took the\nform of sexual violence, including rape, accompanied by threats, among them death threats,\nintimidation and verbal abuse, sometimes of an ethnically charged nature."},{"id":"a-hrc-42-49-p0041","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"41","seq":43,"section":"3. Torture and other cruel, inhuman or degrading treatment","text":"Overcrowding, lack of food and insufficient access to drinking water, sanitation and\nhealth care have persisted in prisons and in the police and National Intelligence Service\ncells. These conditions continue to constitute cruel, inhuman or degrading treatment."},{"id":"a-hrc-42-49-p0042","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"42","seq":44,"section":"4. Sexual violence","text":"Numerous cases of sexual violence have been documented; the majority of victims\nwere women and girls. Such violence most often took the form of gang rape, the\nperpetrators being for the most part Imbonerakure and, in one case, military personnel.\nSome of these rapes were committed at night in victims’ homes, in front of their children\nand other members of their families, and generally involved other violations of physical\nintegrity as well as, sometimes, the abduction or execution of the family member\nconsidered to be the head of household. Other women were raped while travelling in the\ncourse of their daily activities or attempting to flee the country. In many cases, the victim\nwas told that she or her family members would be killed if she resisted, called for help or\nreported the rape. The victims, some of whom had recently returned to Burundi, were\ntargeted on account of their affiliation – real or perceived – or that of a family member with\nthe opposition or with a rebel movement, their refusal to join CNDD-FDD or the\nImbonerakure, non-payment of contributions or a “No” vote in the May 2018 constitutional\nreferendum. These acts, committed for a specific purpose such as intimidation or\npunishment because of the victim’s supposed political views, constitute acts of torture."},{"id":"a-hrc-42-49-p0043","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"43","seq":45,"section":"4. Sexual violence","text":"The majority of the rape cases occurred in rural areas. Most of the victims\nrecognized their attackers as local Imbonerakure who had intimidated them or their\nrelatives on one or more occasions in the past. However, none of the victims reported her\nattackers."},{"id":"a-hrc-42-49-p0044","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"44","seq":46,"section":"4. Sexual violence","text":"Sexual violence in the form of violence applied to the genital area or forced nudity\nhas continued to be committed by officers of the National Intelligence Service against men\nheld in the Service’s cells, under its responsibility, over periods ranging from a few weeks\nto several years."},{"id":"a-hrc-42-49-p0045","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"45","seq":47,"section":"4. Sexual violence","text":"The physical and psychological consequences of sexual violence are manifold and,\nwhile several victims received basic medical care in the aftermath – often thanks to the\nintervention of neighbours or relatives – few women and no men have received appropriate\ntreatment. The stigmatization of women and girls who are victims of sexual violence has a\nnegative impact on their enjoyment of the other rights already affected by the persistence in\nBurundi of multiple forms of discrimination against women."},{"id":"a-hrc-42-49-p0046","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"46","seq":48,"section":"4. Sexual violence","text":"The Commission has also documented cases of sexual violence, mainly gang rape\nand sometimes involving genital mutilation, committed in 2015 and 2016, which confirm\nits earlier findings. The trauma caused by such violence, and the fear of stigmatization, had\nprevented the victims from coming forward before now."},{"id":"a-hrc-42-49-p0047","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"47","seq":49,"section":"5. Civil liberties","text":"The Government controls the dissemination of media outputs in the country through\nthe National Communication Council, supposedly the independent media regulation body,\nwhich is in reality a tool for censorship. Many national and international news media have\nhad sanctions imposed on them; recent examples include the radio station Voice of\nAmerica, which was suspended indefinitely, BBC radio, which had its licence withdrawn,\nand Radio France Internationale, which received a warning. They are charged with having\nbroadcast criticism of the Government or reports that contradicted official statements.\nIndependent media are regularly accused of seeking to tarnish the country’s image and\ncause breaches of the peace."},{"id":"a-hrc-42-49-p0048","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"48","seq":50,"section":"5. Civil liberties","text":"The new law regulating the press, promulgated in September 2018, has contributed\ndirectly to the reduction of democratic space in the run-up to the elections. Among other\nrequirements, it imposes an obligation on journalists to “publish only information that is\nbalanced ... the source, reliability and accuracy of which have been established and\ncarefully verified”.24"},{"id":"a-hrc-42-49-p0049","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"49","seq":51,"section":"5. Civil liberties","text":"The Government treats any discourse not in line with official propaganda as an\nattempt to destabilize the country or an attack on national sovereignty. By contrast,\ndiscourse, songs and political statements inciting intolerance and violence against any\npolitical formation other than CNDD-FDD are tolerated by the authorities. Statistics from\ninternational organizations deemed unfavourable have also been condemned by the\nauthorities.\n(b)        Freedom of association and assembly"},{"id":"a-hrc-42-49-p0050","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"50","seq":52,"section":"5. Civil liberties","text":"The degree of control exercised by the Government over the composition and\nactivities of national and foreign non-governmental organizations (NGOs) has increased\nstill further. All foreign NGOs have had to temporarily suspend their activities, from 1\nOctober 2018, and reapply for approval. They have been required to pay one third of their\nannual budgets into the central bank of Burundi and to transmit to the authorities lists of\ntheir employees, indicating their ethnicity. The Government is now seeking to play a role in\nthe recruitment of national employees of these foreign NGOs. National NGOs are strictly\ncontrolled, both their public statements and their projects and activities. For example, the\nsuspension of the organization Parole et action pour le réveil des consciences et l’évolution\ndes mentalités (PARCEM) for presenting a report critical of socioeconomic conditions,\nbased on data from the World Bank, was confirmed by the Ministry of the Interior on 3\nJune 2019."},{"id":"a-hrc-42-49-p0051","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"51","seq":53,"section":"5. Civil liberties","text":"Efforts to force people, men for the most part, to join CNDD-FDD or the\nImbonerakure have continued, notably the use of harassment, death threats, ill-treatment\nand even arbitrary detention. Such measures violate the freedom not to associate, which is\nthe corollary of freedom of association."},{"id":"a-hrc-42-49-p0052","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"52","seq":54,"section":"5. Civil liberties","text":"Members of opposition parties have also been targeted, with a view to inducing\nthem to cease their political activities. Furthermore, all activities of opposition parties are\ntightly controlled and restricted, particularly those of the Congrès national pour la liberté.\nMeetings of small groups of members of this party have been blocked and the participants\narrested.\n24   Burundi, Act No. 1/19 of 14 September 2018 amending Act No. 1/15 of 9 May 2015 on the regulation\nof the press in Burundi, art. 52.\n(c)        Freedom of movement"},{"id":"a-hrc-42-49-p0053","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"53","seq":55,"section":"5. Civil liberties","text":"There remain obstacles to freedom of movement. Barriers, usually operated by\nImbonerakure, have been put up on roads in order to control the movement of the\npopulation. To be able to travel, Burundians had to regularly show a receipt confirming that\nthey had paid the contribution for the 2020 elections or pay a varying amount, the final\nrecipient of which remains unknown. Movement has been more strictly controlled in border\nareas and, in many cases, checkpoints have been the scene of acts of violence or\nintimidation."},{"id":"a-hrc-42-49-p0054","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"54","seq":56,"section":"5. Civil liberties","text":"In places, the local administrative authorities have imposed restrictions on\nmovement after 6 or 7 p.m. applying solely to women and girls, for the stated purpose of\nstemming “unwanted pregnancies” and “debauchery”.\n(d)         Freedom of religion"},{"id":"a-hrc-42-49-p0055","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"55","seq":57,"section":"5. Civil liberties","text":"The Government has stepped up its control over the churches. With its allies, it has\nalso issued warnings to religious leaders, including the Catholic bishops, in order to\ndiscourage any criticism or discourse of “a political nature”, and has called on the faithful\nto monitor them. Moreover, people have been forced to take part in the constitutional\nreferendum or to join CNDD-FDD, even if doing so ran counter to their religious\nconvictions."},{"id":"a-hrc-42-49-p0056","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"56","seq":58,"section":"1. Right to an adequate standard of living","text":"Burundi is one of the world’s poorest countries, with 74.7 per cent of its population\nliving in poverty.25 The country is ranked 185th out of 189 on the Human Development\nIndex, life expectancy at birth is only 57.9 years and gross national income per capita (at\npurchasing power parity) is U$ 702 per year.26 The country, which was in recession in 2015\nand 2016, has been recovering since 2017, albeit unsteadily, as the political crisis has\nlimited its access to international aid, on which it is heavily dependent, and led to a trade\ndeficit, a shortage of foreign exchange and a rise in the cost of living. The people are also\nforced, without any legal grounds, to make regular contributions of various sorts, including\nto finance the construction of local offices of the ruling party, CNDD-FDD. The main\ncontributions associated with the 2020 elections were partly compulsory, but on 30 June\n2019, the President announced that they had been abolished and would in future be made\nonly on a “voluntary” basis. The various contributions were collected by Imbonerakure,\nwho did not shy away from resorting to violence and threats. According to evidence\nprovided by witnesses, people who were unable to pay were often subjected to ill-treatment\nor deprived of access to public services (or both)."},{"id":"a-hrc-42-49-p0057","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"57","seq":59,"section":"1. Right to an adequate standard of living","text":"Many refugees who returned to Burundi under the assistance programme for\nrepatriation have had the food kits and the money they were given taken from them by\nImbonerakure and local administrative authorities. The perpetrators’ remarks, reported by\nthe victims, indicated that their food and money were taken in what amounted to retaliation\nfor having fled the country after 2015 and for not having participated in its development or\ncontributed to the elections. These people then found themselves destitute, and some were\nforced to flee again."},{"id":"a-hrc-42-49-p0058","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"58","seq":60,"section":"2. Right to work","text":"Hiring in the public and semi-public sectors, including in education, health, the\njudiciary and government-owned companies, is discriminatory; it depends on the job\ncandidate’s political affiliation rather than his or her experience or qualifications.\n25   World Bank, The World Bank in Burundi. Available at www.worldbank.org/en/country/burundi.\n26   United Nations Development Programme, Human Development Indices and Indicators: 2018\nStatistical Update, p. 25.\nEmployees who are not members of CNDD-FDD are at risk of losing their jobs. The\npoliticization of access to employment is increasing and has spread to foreign NGOs."},{"id":"a-hrc-42-49-p0059","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"59","seq":61,"section":"3. Right to education","text":"In several schools, students who had not made the contribution for the 2020\nelections, which was compulsory for every student of voting age, were not allowed to\nattend class. The situation was such that, on 8 February 2019, the Minister of Education had\nto prohibit the practice. In addition, some students have been unable to go to school or have\nbeen harassed and threatened by teachers or other students who are members of CNDD-\nFDD – although schools are theoretically settings free of political activity – on account of\ntheir affiliation with another party. The high school girls accused of defacing a photograph\nof the President were also forced out of school indefinitely. The quality of instruction is\nsuffering as qualified teachers leave and their places are taken by substitutes chosen for\ntheir political loyalties. It is common for students to drop out of school, including because\nof pregnancy or owing to the socioeconomic situation. The average length of schooling is\nonly three years.27"},{"id":"a-hrc-42-49-p0060","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"60","seq":62,"section":"4. Forced labour","text":"Community service initially consisted of street cleaning and other minor\nmaintenance work in the interest of the community. This mandatory service has now taken\non political overtones. The people have been forced, on pain of financial penalty, to build\nlocal offices for CNDD-FDD, an obligation that constitutes forced labour, which is\nprohibited by the International Labour Organization (ILO) Forced Labour Convention,\n1930 (No. 29), and the ILO Abolition of Forced Labour Convention, 1957 (No. 105), both\nratified by Burundi in 1963."},{"id":"a-hrc-42-49-p0061","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"61","seq":63,"section":"4. Forced labour","text":"The aim of other forms of community service is to contribute to local development\nby building public facilities such as stadiums, roads, schools and health centres. Since 2015,\nthe Committee of Experts on the Application of Conventions and Recommendations of ILO\nhas been examining the compatibility of this work with international law, which states that\ncompulsory service as a method of mobilizing and using labour for purposes of economic\ndevelopment is a form of forced labour.28"},{"id":"a-hrc-42-49-p0062","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"62","seq":64,"section":"A. Constituent elements and types of crimes","text":"The Commission still has reasonable grounds to believe that crimes against\nhumanity, as defined in the Rome Statute, have been committed in Burundi. These crimes\ninclude murder, imprisonment or other severe forms of deprivation of physical liberty,\ntorture, rape and other forms of sexual violence of comparable gravity, and political\npersecution.29"},{"id":"a-hrc-42-49-p0063","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"63","seq":65,"section":"A. Constituent elements and types of crimes","text":"The Commission has documented a large number of violent incidents that have\ntaken place in several provinces. Different people with similar modus operandi and a shared\nobjective – to eliminate any real or perceived political opposition that could undermine the\ngrip on power of the Government and CNDD-FDD – have been responsible for these\nincidents. They can therefore be described as “systematic attacks” deliberately targeting\ncivilians. The people are regularly reminded by representatives of the Government, local\nadministrative authorities and CNDD-FDD that their objective is to remain in power. The\nalleged perpetrators of these international crimes are necessarily informed of this objective,\nwhich means that they must understand the backdrop against which they act."},{"id":"a-hrc-42-49-p0064","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"64","seq":66,"section":"B. Individual responsibility","text":"The Commission has continued drawing up its list of alleged perpetrators of crimes\nagainst humanity, distinguishing between direct responsibility and command responsibility,\nwhether civilian or military. This list is kept confidential to protect sources and respect the\nright to the presumption of innocence of the alleged perpetrators, but the Commission\nreserves the right to disclose it."},{"id":"a-hrc-42-49-p0065","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"65","seq":67,"section":"A. Overview","text":"In accordance with the principles of prevention and early warning promoted by the\nUnited Nations, the Commission decided that it was important to determine whether there\nwere any particular risk factors linked to the 2020 elections that could have an impact on\nthe human rights situation. To that end, it used the Framework of Analysis for Atrocity\nCrimes developed by the Office on Genocide Prevention and the Responsibility to Protect.30\nRisk factors are conditions that create an environment conducive to the commission of\natrocity crimes or point to their possible occurrence. Some are structural, whereas others are\nrelated to dynamic circumstances. The objective indicators included in the Framework are\ndifferent manifestations of each risk factor and therefore assist in determining the degree to\nwhich an individual risk factor is present. Observing the situation and warning of the\nexistence of risk factors – without determining the likelihood of atrocity crimes occurring –\nare necessary steps, as the warning can itself help ward off or mitigate the risks of a\ndeterioration of the human rights situation. The Commission has sought to identify the\nindicators that would help it determine what risk factors are present in Burundi."},{"id":"a-hrc-42-49-p0066","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"66","seq":68,"section":"1. Failure to resolve the 2015 political crisis","text":"The crisis of 2015, which was primarily political, continues to affect Burundi\nsociety. The inclusive inter-Burundi dialogue is at an impasse, as the Government of\nBurundi has rejected the process and the need for it. The people are continuing to fall\nfurther into poverty, and the many refugees from Burundi are still without real prospects.\nThe Burundian authorities refuse to engage in dialogue to resolve this profound political\ncrisis and view any attempt by the international community to resolve it or to address\nhuman rights violations and international crimes as violations of national sovereignty and\nattempts to destabilize the country. Impunity prevails, and victims remain without access to\nremedies."},{"id":"a-hrc-42-49-p0067","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"67","seq":69,"section":"2. 2020 elections","text":"The existence of democratic space is a key indicator for the holding of fair, free and\ncredible elections. Democratic space in Burundi has shrunk steadily since 2015, as national\nhuman rights mechanisms are neither independent nor effective. The Government is\nincreasing its control over NGOs, and with the National Communication Council practising\ncensorship, freedom of the press has become a fiction."},{"id":"a-hrc-42-49-p0068","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"68","seq":70,"section":"2. 2020 elections","text":"There is no real multiparty system in Burundi. Most parties have been infiltrated and\ndivided so that only the wings loyal to the Government have official approval. The political\narena has been cordoned off by CNDD-FDD. The hopes raised by the approval of the\nCongrès national pour la liberté in February 2019 were quickly dashed. Its members are\nharassed or even persecuted, and the party’s activities are restricted, controlled or banned,\nhighlighting the political intolerance prevailing in Burundi. This situation suggests that the\nruling party, which could feel threatened by the popularity of the Congrès national pour la\nliberté, could be experiencing a crisis of confidence. The history of Burundi shows that\nCNDD-FDD turns to violent strategies when it faces organized opposition, particularly in\nelections. In addition, the ruling party and State institutions are becoming increasingly\ndifficult to tell apart."},{"id":"a-hrc-42-49-p0069","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"69","seq":71,"section":"2. 2020 elections","text":"There have also been excesses in the exercise of power by the Head of State. The\nHead of State has extensive powers under the Constitution, but he does not hesitate to make\ndecisions that are not his prerogative, such as the appointment of the executive officers of\nthe National Communication Council. In addition, he continues to rely on shadowy\ninformal structures, such as the “committee of generals”.31 He also uses the National\nSecurity Council, which he chairs, to govern directly.32 For example, although the Council\nhas no decision-making authority, it decided to suspend the activities of foreign NGOs in\nOctober 2018. Having the National Intelligence Service report directly to the Office of the\nPresident is another significant example of his concentration of power in his hands. The\nease with which the President bypasses institutions reveals their weakness."},{"id":"a-hrc-42-49-p0070","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"70","seq":72,"section":"2. 2020 elections","text":"The theme of the divine origin of the President’s power is increasingly common in\nofficial speeches delivered by the President and his wife. A slide into religiosity is also\napparent in some of the Head of State’s decisions, in particular his plan to reform society\nand help it recover its “true values”. His frequent references to the Burundian monarchy\nand the decision to place the royal motto “God, King, Country” back on public monuments\nare leading to speculation by analysts and some Burundians about a possible restoration of\nthe monarchy for his benefit."},{"id":"a-hrc-42-49-p0071","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"71","seq":73,"section":"2. 2020 elections","text":"The culture of secrecy typical of CNDD-FDD makes it impossible to know the\nstatus of the process for the nomination of the party’s candidate for the presidential\nelections, raising the question of whether the delay is linked to possible strife in the party,\nas in 2015."},{"id":"a-hrc-42-49-p0072","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"72","seq":74,"section":"2. 2020 elections","text":"A new electoral code entered into force on 20 May 2019. Independent candidates are\nsubject to limitations on running in parliamentary elections and must obtain better results\nthan candidates who are members of political parties."},{"id":"a-hrc-42-49-p0073","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"73","seq":75,"section":"2. 2020 elections","text":"The Independent National Electoral Commission, whose seven members are\nassociates of CNDD-FDD or its allied parties, is not independent of the executive\nauthorities or the ruling party."},{"id":"a-hrc-42-49-p0074","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"74","seq":76,"section":"3. Misuse of history","text":"The issue of ethnicity is one of considerable historical import in Burundi. Ethnicity,\nwhether a colonial fabrication or a traditional social reality, often made use of, remains one\nof the determinants of the identity of most Burundians. Since independence, numerous\nhuman rights violations with an ethnic dimension have caused many Burundians to distrust\nand resent the other group and generated a body of differing memories. The Head of State\ndelivers lecture after lecture at meetings in which he teaches the “true” history of Burundi.\nThe mandate of the new Truth and Reconciliation Commission, which is not independent,\nis to “rewrite the history of Burundi” and investigate the crimes and violations that have\nbeen committed since 1885."},{"id":"a-hrc-42-49-p0075","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"75","seq":77,"section":"3. Misuse of history","text":"The current approaches raise concerns that the imposition of a biased official version\nof the country’s history could sharpen the grievances of the past, with troubling\nconsequences. The lack of genuine and appropriate reconciliation and transitional justice\nprocesses, as provided for in the Arusha Peace and Reconciliation Agreement for Burundi,\nhelps maintain these rifts, which some may seek to exploit for political ends."},{"id":"a-hrc-42-49-p0076","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"76","seq":78,"section":"4. Security questions","text":"A number of armed rebel groups in neighbouring countries have stated that they\nmight resort to force to resolve the situation in Burundi. They could be encouraged to do so\nby the unlikelihood of a resolution to the crisis. Some refugees may also join armed groups,\nespecially since there are Imbonerakure in some camps, a circumstance that causes them to\nfeel insecure. The ability of armed groups to conduct large-scale operations in Burundi\nremains unknown. At the same time, Burundi regularly accuses Rwanda of seeking to\ndestabilize it and of forcibly detaining Burundian refugees."},{"id":"a-hrc-42-49-p0077","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"77","seq":79,"section":"4. Security questions","text":"In Burundi, the situation of the army, a stabilizing influence since the Arusha\nAgreement, has become fluid. It has long enjoyed privileged economic and social standing.\nThe attempted coup d’état in May 2015 exposed the existence of dissent in the army, which\nis now partly under surveillance. There have been purges in the form of arrests and physical\neliminations. Compliance with the requirement for ethnic balance set out in the Constitution\nseems to be a thing of the past. There is also fatigue and a degree of mistrust in the army,\nparticularly because of the threat to lucrative peace-mission deployments"},{"id":"a-hrc-42-49-p0078","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"78","seq":80,"section":"4. Security questions","text":"The National Intelligence Service, which answers directly to the Office of the\nPresident, is no longer an official part of the defence and security forces and is therefore no\nlonger subject to parliamentary oversight or ethnic quotas. This reorganization of the\nsecurity apparatus is troubling."},{"id":"a-hrc-42-49-p0079","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"79","seq":81,"section":"4. Security questions","text":"The Joint Human Security Committees, in place at all levels since 2014 and with\nextremely vague mandates, are controlled by local administrative authorities loyal to the\nruling party and by Imbonerakure. Imbonerakure have supplanted the police in all security\nissues and politicized those issues. They are conducting more and more night rounds in the\nhills and mass sports training sessions, often with a paramilitary dimension, which worries\nand intimidates part of the population. Members of the security and defence forces have\nbeen targeted in incidents that have taken place since early 2019, although the persons\nresponsible have not been identified."},{"id":"a-hrc-42-49-p0080","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"80","seq":82,"section":"C. Risk indicators","text":"This brief review of the most significant developments makes it possible to identify\nindicators that are themselves linked to eight common risk factors identified in the\nFramework of Analysis for Atrocity Crimes."},{"id":"a-hrc-42-49-p0081","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"81","seq":83,"section":"C. Risk indicators","text":"Insecurity creates an environment that is conducive to atrocity crimes (risk factor 1).\nThe existence of such an environment is suggested by the following indicators: many\nBurundians, both in the country and abroad, are living through a humanitarian emergency\n(risk factor 1 (c)); the transfer of power of 2015 triggered a major political crisis that has\nnot yet been resolved (risk factor 1 (d)); there is a risk of political instability caused by\nprobable power struggles within CNDD-FDD and by the existence of armed opposition\nmovements (risk factor 1 (e)); political tension is being generated by an autocratic regime\nthat engages in severe political repression of all its opponents, real or perceived (risk factor\n1 (f)); there is economic instability caused by scarcity of resources (risk factor 1 (g)), a\nsevere crisis in the national economy (risk factor 1 (h)) and the acute poverty of the\npopulation (risk factor 1 (i))."},{"id":"a-hrc-42-49-p0082","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"82","seq":84,"section":"C. Risk indicators","text":"Risk factor 2 is related to a history of serious human rights violations that, because\nthey have not been prevented or punished, create a risk of further violations. The presence\nof this risk factor is revealed by the following indicators: past or present serious human\nrights violations (risk factor 2 (a)); acts of genocide, crimes against humanity and war\ncrimes that have marked the country’s recent history (risk factor 2 (b)); a policy or practice\nof impunity for or tolerance of serious human rights violations (risk factor 2 (c)); the refusal\nor reluctance of the Government of Burundi to use all possible means to put an end to\nserious human rights violations (risk factor 2 (d)); the continuation of support by the\nBurundian authorities for groups accused of involvement in violations and the failure to\ncondemn their actions (risk factor 2 (e)); the Government’s refusal to acknowledge serious\nhuman rights violations or its biased accounts thereof (risk factor 2 (f)); the absence of\ngenuine reconciliation or transitional justice processes and the politicization of the work of\nthe new Truth and Reconciliation Commission (risk factor 2 (g)); widespread mistrust of\nState institutions, particularly the security forces and the judicial system, as a result of\nimpunity (risk factor 2 (h))."},{"id":"a-hrc-42-49-p0083","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"83","seq":85,"section":"C. Risk indicators","text":"Risk factor 3, the weakness of State structures, which negatively affects the capacity\nof a State to prevent, halt or prosecute atrocity crimes, is also present. National institutions,\nparticularly judicial, law enforcement and human rights institutions, lack sufficient\nresources and adequate representation (risk factor 3 (b)); the justice system is neither\nindependent nor impartial (risk factor 3 (c));33 civilian control of the security forces (by\nParliament) is not effective (risk factor 3 (d)); there are high levels of corruption or poor\ngovernance (risk factor 3 (e));34 the internal oversight and accountability mechanisms\nwhereby victims can seek recourse for their claims are inadequate or ineffective, and the\nexternal mechanisms are virtually non-existent or almost inaccessible to victims (risk factor\n3 (f))."},{"id":"a-hrc-42-49-p0084","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"84","seq":86,"section":"C. Risk indicators","text":"Risk factor 4 is the existence of reasons, aims or drivers that justify the use of\nviolence against particular groups. From an early warning perspective, it is important to be\nable to identify motivations or drivers that could encourage groups to resort to widespread\nviolence in an attempt to achieve their goals. This factor is shown to be present by:\npolitically motivated acts that, as regularly noted by members of the Government and\nCNDD-FDD, are aimed at the consolidation of power (risk factor 4 (a)); economic interests\nlinked to the preservation of power, as power is the key to control over the distribution of\nresources (risk factor 4 (b)); real or perceived threats to the interests or objectives of the\nGovernment, including any form of disloyalty to the CNDD-FDD cause (risk factor 4 (e));\nreal or perceived membership of or support for armed opposition groups (risk factor 4 (f));\nthe ideology of CNDD-FDD, characterized by a view of the party as the embodiment of\ntruth and thus belief in the supremacy of this political identity (risk factor 4 (g)); the\npoliticization of past grievances, tensions or cases of impunity (risk factor 4 (h)); social\ntrauma caused by past incidents of violence that, not adequately addressed, have aroused\nfeelings of loss, displacement, injustice and a possible desire for revenge (risk factor 4 (i))."},{"id":"a-hrc-42-49-p0085","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"85","seq":87,"section":"C. Risk indicators","text":"Risk factor 5 refers to the capacity of potential perpetrators to commit atrocity\ncrimes. This factor must be assessed in conjunction with other factors, such as those related\nto intent and motivation. In Burundi, this factor is gauged by: the availability of personnel\nand of arms and ammunition or of financial resources, public or private, for their\nprocurement (risk factor 5 (a)); the capacity to transport and deploy personnel and to\ntransport and distribute arms and ammunition (risk factor 5 (b)); the capacity to encourage\nor recruit large numbers of supporters – Imbonerakure, for example – from populations or\ngroups and the availability of the means to mobilize them (risk factor 5 (c)); a strong\nculture of obedience to authority and group conformity, a culture by which CNDD-FDD\nand the Imbonerakure are characterized (risk factor 5 (d)); the presence of or links with\nother armed forces or with non-State armed groups (risk factor 5 (e))."},{"id":"a-hrc-42-49-p0086","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"86","seq":88,"section":"C. Risk indicators","text":"Mitigating factors are the internal and external elements that can contribute to\npreventing an escalation of violence, ending it or lessening its impact. The absence of such\nfactors (risk factor 6) in Burundi is significant, as demonstrated by: the lack of a strong,\norganized and representative national civil society and of a free, diverse and independent\nnational media (risk factor 6 (b)); the lack of access to international media (risk factor 6\n(c)); the limited presence of the United Nations, international NGOs or other international\nor regional actors in the country with access to the people (risk factor 6 (d)); the lack of\nexposure to, openness towards or establishment of political or economic relations with\nother States (risk factor 6 (f)); the limited or even non-existent cooperation with\ninternational and regional human rights mechanisms (risk factor 6 (g)); the Government’s\nunwillingness to engage in genuine dialogue to resolve the 2015 crisis, make concessions or\nreceive support from the international community (risk factor 6 (h)); the lack of a warning\nmechanism, as the National Observatory for the Prevention and Eradication of Genocide,\nWar Crimes and Other Crimes against Humanity does not serve as an independent\nmechanism of that sort (risk factor 6 (k))."},{"id":"a-hrc-42-49-p0087","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"87","seq":89,"section":"C. Risk indicators","text":"Risk factor 7 refers to enabling circumstances or preparatory actions, whether\nsudden or gradual, that provide an environment conducive to the commission of atrocity\ncrimes or suggest that they may occur. The main indicators of this risk in Burundi are: the\ninterference with vital State institutions, or measures that result in changes to their\ncomposition or balance of power, as is the case with the introduction of ethnic quotas (risk\nfactor 7 (b)); the strengthening of the security apparatus or its reorganization or\nmobilization (risk factor 7 (c)); the expulsion or refusal to allow the presence of NGOs,\ninternational organizations, media or other relevant actors, or the imposition of severe\nrestrictions on their services and movements (risk factor 7 (g)); the increase in the number\nof violations of the right to life, physical integrity, liberty or security of any person\nconsidered a political opponent since the onset of the 2015 crisis (risk factor 7 (h)); the\nincrease in the number of serious acts of violence against women and children, or the\ncreation of conditions that facilitate acts of sexual violence against them, including as a tool\nof terror (risk factor 7 (i)); the increased politicization of identity, past events or\nmotivations for violence (risk factor 7 (m)); the increase in inflammatory rhetoric,\npropaganda campaigns or incitement to hatred targeting anyone considered a political\nopponent since the onset of the 2015 political crisis (risk factor 7 (n))."},{"id":"a-hrc-42-49-p0088","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"88","seq":90,"section":"C. Risk indicators","text":"Triggering factors (risk factor 8) are also present, as evidenced by the following\nindicators: measures taken by the international community are perceived by the Burundian\nauthorities as threats to State sovereignty (risk factor 8 (c)); there was an abrupt or irregular\ntransfer of power in 2015 (risk factor 8 (d)); attacks on the life, physical integrity, liberty or\nsecurity of leaders, prominent individuals or members of opposition groups have been\ncommitted (risk factor 8 (e)); there is hate propaganda targeting political opponents (risk\nfactor 8 (g)); presidential, parliamentary and local elections are scheduled for 2020 (risk\nfactor 8 (h)); the commemoration, along ethnic lines, of past crimes or of traumatic or\nhistorical incidents could exacerbate tensions between groups (risk factor 8 (k)); acts\nrelated to the process for determining accountability for past atrocities could be perceived\nas unfair (risk factor 8 (l))."},{"id":"a-hrc-42-49-p0089","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"89","seq":91,"section":"C. Risk indicators","text":"The eight common risk factors identified in the Framework of Analysis for Atrocity\nCrimes are clearly present in Burundi, and there is a significant number of indicators for\neach of them.35 Although the presence of those risk factors does not make it possible to\ndraw conclusions about the likelihood of atrocity crimes or when and in what way any such\ncrimes will be committed, it gives the international community an objective basis for\nunderstanding the reality of the situation in Burundi and the possible risks facing the\ncountry. The identification of several risk factors means that developments in Burundi must\nbe monitored very closely."},{"id":"a-hrc-42-49-p0090","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"90","seq":92,"section":"V. Conclusions and recommendations","text":"In the light of its investigations, the Commission concludes that serious human\nrights violations – including crimes against humanity – have continued to take place\nsince May 2018, in particular violations of the right to life, arbitrary arrest and\ndetention, torture and other forms of ill-treatment, sexual violence, and violations of\neconomic and social rights, all in a general climate of impunity. Violations of civil\nliberties are also on the rise."},{"id":"a-hrc-42-49-p0091","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"91","seq":93,"section":"V. Conclusions and recommendations","text":"The Commission remains the only independent and objective mechanism that\ninvestigates, documents and informs the international community about human rights\nviolations and abuses in Burundi.\n35   The Commission is of the view that the risks gauged by other indicators are only partially present.\nThose indicators have thus not been mentioned in this report, but they have been examined in\ndocument A/HRC/42/CRP.2."},{"id":"a-hrc-42-49-p0092","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"92","seq":94,"section":"V. Conclusions and recommendations","text":"The crisis has been ongoing for more than four years, with no real prospects for\na resolution. The daily living conditions of Burundians, in the country or not, are\nbecoming worse and worse."},{"id":"a-hrc-42-49-p0093","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"93","seq":95,"section":"V. Conclusions and recommendations","text":"The 2020 elections pose a major risk. To ensure that they are peaceful, fair,\nfree, transparent and credible, the Commission makes the following recommendations\nto the Burundian authorities:\n(a)   Give effect to all the Commission’s previous recommendations, which\nare more well-founded and relevant than ever, including those concerning priority\nmeasures to end human rights violations and international crimes, combat impunity\nand improve the human rights situation in the country and the medium- and longer-\nterm recommendations on reforms to the legal framework and the judicial system; 36\n(b)    Conduct prompt, independent and effective investigations into the cases\nof violations documented by the Commission since 2015 with a view to creating a\nclimate of trust and political tolerance conducive to inclusive participation in the\nelectoral process;\n(c)   Re-engage constructively and cooperatively with all international and\nregional human rights mechanisms and the Office of the United Nations High\nCommissioner for Human Rights, enabling them to carry out their human rights\nmonitoring mandates fully and freely;\n(d)    Ensure that national human rights mechanisms are institutionally and\nfinancially independent and build the capacity of their members;\n(e)     Take the measures necessary to ensure that foreign and domestic NGOs\ncan be freely established and organized and that they can operate freely, including by\namending the laws regulating them;\n(f)    Take the measures necessary to ensure freedom of information in the\ncountry and the right of local and international media to operate in accordance with\ninternational standards, including by amending the laws on the press and the National\nCommunication Council;\n(g)    Guarantee the effective enjoyment of civil liberties, including the\nfreedoms of opinion, expression, access to information, association, assembly and\nreligion, not least by ending all forced recruitment to the ruling party and its youth\nleague;\n(h)   Follow the Guidelines on Access to Information and Elections in Africa\nand the Guidelines on Freedom of Association and Assembly of the African\nCommission on Human and Peoples’ Rights;\n(i)    Ensure that all political parties can engage in legitimate activities in\ncomplete freedom and security, in an environment of political tolerance, including by\npunishing any incitement to hatred and calls for violence against other political\nparties and their members;\n(j)   Ensure, in practice, the right to participate in the conduct of public\naffairs without discrimination, in particular by amending the Electoral Code;\n(k)     Ensure, in practice, the institutional independence of the Independent\nNational Electoral Commission, including by amending the decree governing it to\nmake certain that its composition is inclusive and balanced, and strengthen the\ncapacity of its members at the municipal and provincial levels;\n(l)    Provide access to independent international and regional election\nobservers and ensure that they and national observers from civil society or political\nparties enjoy freedom of movement and action before, during and after the elections;\n(m) Follow the Guidelines for African Union Electoral Observation and\nMonitoring Missions;\n(n)    Allow political opponents to return from exile to participate in the 2020\nelections and guarantee their freedom and security, including by revoking warrants\nfor the arrest of those who have not used or advocated violence;\n(o)   Immediately release all political prisoners arrested and detained in\nconnection with the exercise of their democratic rights;\n(p)     Make the training provided to law enforcement agencies more robust to\navoid ill-treatment and ensure the peaceful control of crowds;\n(q)    Follow the Guidelines for the Policing of Assemblies by Law\nEnforcement Officials in Africa and the related training manual, both developed by\nthe African Commission on Human and Peoples’ Rights;\n(r)   End the impunity of the Imbonerakure by exercising control over them\nso as to ensure that the functions of the security forces or the judiciary are not\nusurped and put an end to their repressive activities and shows of force in the hills;\n(s)    End all illegal contributions."},{"id":"a-hrc-42-49-p0094","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"94","seq":96,"section":"V. Conclusions and recommendations","text":"The Commission recommends that, whether they participate in the elections or\nnot, all political parties in Burundi refrain from violence and incitement to hatred or\nviolence, particularly against the backdrop of the 2020 elections."},{"id":"a-hrc-42-49-p0095","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"95","seq":97,"section":"V. Conclusions and recommendations","text":"The Commission recommends that opposition rebel groups refrain from\nviolence and incitement to hatred or violence."},{"id":"a-hrc-42-49-p0096","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"96","seq":98,"section":"V. Conclusions and recommendations","text":"For the international community, including the African Union and the United\nNations system, the Commission has the following recommendations:\n(a)    Renew the mandate of the Commission for an additional year;\n(b)    Continue to monitor developments in the human rights situation in\nBurundi in the context of the 2020 elections and, in accordance with the principles of\nprevention and early warning, carry out regular risk assessments to enable the\ndevelopment and use of appropriate response strategies in the event of deterioration;\n(c)    Make every effort to ensure that an inclusive inter-Burundi dialogue is\nheld to resolve the political crisis;\n(d)    Support capacity-building for international, regional and national\nelection observers;\n(e)    Send regional or international observers only if their freedom of action is\nguaranteed in practice;\n(f)    Ensure that all humanitarian aid reaches the population;\n(g)    Respond to the appeal made by the Office of the United Nations High\nCommissioner for Refugees for funds for Burundi refugees;\n(h)   Ensure that returnees are monitored in a sustained and more regular\nand transparent manner."},{"id":"a-hrc-42-49-p0097","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"97","seq":99,"section":"V. Conclusions and recommendations","text":"In particular, the Commission recommends that the United Nations system, in\naccordance with the initiative Human Rights Up Front, take stronger measures to\npromote human rights, under the mandates of the relevant agencies and programmes,\nand to collect and publish objective and reliable data on the situation in Burundi."},{"id":"a-hrc-42-49-p0098","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"98","seq":100,"section":"V. Conclusions and recommendations","text":"In view of the risk factors that have been identified, the Commission\nrecommends that the States members of the Security Council keep Burundi on the\nCouncil’s programme of work and that the Council invite the Commission to report to\nit on its conclusions."},{"id":"a-hrc-42-49-p0001-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"1","seq":101,"section":"Annexes","text":"Lettre du Président de la Commission d’enquête, adressée à Son Excellence Monsieur\nRénovat Tabu, Ambassadeur extraordinaire et plénipotentiaire du Burundi à Genève,\nen date du 26 février 2019","annex":1},{"id":"a-hrc-42-49-p0002-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"2","seq":102,"section":"Annexes","text":"Note verbale envoyée à la Mission permanente du Burundi le 11 mars 2019","annex":1},{"id":"a-hrc-42-49-p0003-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"3","seq":103,"section":"Annexes","text":"Lettre du Président de la Commission d’enquête adressée à Son Excellence Monsieur\nRénovat Tabu, Ambassadeur extraordinaire et plénipotentiaire du Burundi à Genève,\nen date du 2 avril 2019","annex":1},{"id":"a-hrc-42-49-p0004-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"4","seq":104,"section":"Annexes","text":"Note verbale envoyée à la Mission permanente du Burundi le 18 Juin 2019","annex":1},{"id":"a-hrc-42-49-p0005-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"5","seq":105,"section":"Annexes","text":"Note verbale envoyée à la Mission permanente du Burundi le 1 er juillet 2019\nAnnexe III\nRecommandations antérieures faites par la Commission","annex":1},{"id":"a-hrc-42-49-u0106-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":106,"section":"1. Recommandations faites en 2018","text":"Version française\n100. La Commission recommande au Gouvernement burundais, comme mesures\nprioritaires:\na)   De mettre immédiatement un terme aux violations graves des droits de\nl’homme commises par des agents de l’État et des Imbonerakure ;\nb)     D’établir, avec le soutien de la communauté internationale, des mécanismes\nad hoc chargés d’enquêter sur les violations des droits de l’homme et de poursuivre les\nauteurs de crimes de droit international qui ne font pas l’objet d’une enquête par la Cour\npénale internationale;\nc)     D’établir, avec le soutien de la communauté internationale, une entité\nindépendante chargée de faire la lumière sur les cas de disparition signalés depuis avril\n2015, de localiser les possibles fosses communes, d’exhumer et d’identifier les corps ;\nd)     De prendre des mesures pour que les victimes de torture et les femmes ayant\nsubi des violences sexuelles aient accès à des soins appropriés, en particulier un libre accès\nà tous les soins de santé sexuelle et reproductive, ainsi qu’à un soutien psychologique ;\ne)    D’appliquer les Lignes directrices sur la lutte contre les violences sexuelles et\nleurs conséquences en Afrique de la Commission africaine des droits de l’homme et des\npeuples ;\nf)     De contrôler les hausses des prix, en particulier en revoyant l’augmentation\ndes taxes et des impôts qui porte atteinte au droit à un niveau de vie suffisant de la\npopulation, et en supprimant les contributions qui touchent disproportionnellement les\npersonnes les plus pauvres ;\ng)     De coopérer avec les mécanismes internationaux des droits de l’homme,\nnotamment :\nh)     En accueillant à nouveau des missions de procédures spéciales ;\n ii) En mettant en œuvre les recommandations de l’examen périodique\nuniversel, des organes conventionnels et des procédures spéciales,\nnotamment en établissant un mécanisme national d’élaboration des rapports\net de suivi ;\ni)     D’autoriser le Haut-Commissariat des Nations Unies aux droits de l’homme à\nreprendre sans entrave l’ensemble de ses activités au Burundi ;\nj)    De signer et de mettre en œuvre le mémorandum d’entente avec l’Union\nafricaine et de permettre le déploiement complet des 100 observateurs des droits de\nl’homme.\n101. La Commission recommande également au Gouvernement burundais, à moyen et\nplus long termes :\na)      De réviser la loi organique du 8 mars 2018 portant révision de la loi no 01/03\ndu 24 janvier 2013 portant missions, composition, organisation et fonctionnement du\nConseil national de la communication afin de garantir l’indépendance de ce dernier ;\nb)     De ratifier la Convention internationale pour la protection de toutes les\npersonnes contre les disparitions forcées ;\nc)     De réviser les dispositions du Code de procédure pénale pour les mettre en\nconformité avec les normes internationales, en particulier les dispositions relatives aux","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0107-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":107,"section":"1. Recommandations faites en 2018","text":"délais de garde à vue et de contrôle de la détention, aux perquisitions de nuit et sans\nmandat, à la procédure de « flagrance », à l’infraction d’« atteinte à la sûreté intérieure de\nl’État », et à celles accordant une impunité de jure aux magistrats et aux officiers de police\njudiciaire ;\nd)     De mettre fin aux détentions arbitraires et d’améliorer les conditions de\ndétention :\n En appliquant les Lignes directrices sur les conditions d’arrestation, de\ngarde à vue et de détention provisoire en Afrique de la Commission africaine\ndes droits de l’homme et des peuples;\n En garantissant le contrôle de la légalité des détentions et leur conformité\navec les droits de l’homme.\n(e)   Faute d’un système judiciaire indépendant et performant, de coopérer\npleinement avec la Cour pénale internationale dans l’enquête qu’elle a ouverte le 25 octobre\n2017;\n(f)   D’engager une réforme en profondeur du système judiciaire afin de garantir\nson indépendance, son impartialité et son effectivité, notamment:\n i) En appliquant les Directives et les Principes sur le droit à un procès\néquitable et à l’assistance judiciaire en Afrique de la Commission africaine\ndes droits de l’homme et des peuples;\n ii) En publiant les conclusions des états généraux de la justice de 2013 et\nen réunissant les acteurs du secteur et les partenaires internationaux pour\ndiscuter des mesures de suivi;\n iii) En augmentant le budget du secteur de la justice et en garantissant son\nautonomie de gestion;\n iv) En revalorisant la rémunération des magistrats des juridictions\nordinaires ainsi que les moyens et l’équipement à leur disposition;\n v) En informatisant les greffes;\n     vi) En revoyant la composition du Conseil supérieur de la magistrature\nafin que ses membres soient en majorité désignés par leurs pairs;\n vii) En revoyant les procédures de nomination, d’affectation, de notation\net d’avancement des magistrats afin qu’elles ne dépendent pas du pouvoir\nexécutif;\n viii) En veillant au respect strict du principe d’inamovibilité des\nmagistrats du siège;\n ix) En protégeant et en garantissant l’indépendance du système judiciaire\nen interdisant toute ingérence dans le fonctionnement de la justice par des\nautorités gouvernementales, des membres du parti au pouvoir ou par des\nmembres des corps de défense et de sécurité, et en prenant des sanctions\ncontre ceux qui influencent, ou cherchent à influencer, le fonctionnement de\nla justice;\n x) En développant des programmes d’aide juridictionnelle pour les plus\nvulnérables;\n xi) En renforçant les mécanismes de protection de victimes et de témoins,\nainsi que leur efficacité, pour restaurer la confiance de la population et pour\nencourager les témoins à s’exprimer sans crainte pour leur sécurité.\n(g)   De mettre en place, en consultation avec les bénéficiaires, un programme de\nréparations des victimes des violations des droits de l’homme qui comprenne des\nréparations matérielles, symboliques, individuelles et collectives, et qui ne soit pas\ndépendant de la condamnation des auteurs;","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0108-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":108,"section":"1. Recommandations faites en 2018","text":"(h)   D’établir le fond étatique pour les victimes de torture prévu par la loi et en\nconformité avec l’Observation générale no 4 de la Commission africaine des droits de\nl’homme et des peuples sur la Charte africaine des droits de l’homme et des peuples,\nconcernant le droit à réparation des victimes de torture et autres peines ou traitements\ncruels, inhumains ou dégradants (art. 5);\n(i)   D’établir un fond pour l’indemnisation des victimes de détention arbitraire et\nillégale;\n(j)   De réformer le secteur de la sécurité:\n i) En s’assurant que des éléments extérieurs n’accomplissent pas des\nactivités de défense ou de sécurité;\n ii) En délimitant clairement les rôles des différents corps de défense et de\nsécurité, en particulier du SNR;\n iii) En suspendant les membres des corps de défense et de sécurité\nsuspectés d’être impliqués dans des violations des droits de l’homme\njusqu’au terme des enquêtes et des procédures judiciaires;\n iv) En établissant des procédures strictes et transparentes de sélection qui\nintègrent des mécanismes de vérification des antécédents;\n v) En renforçant le contrôle civil et démocratique des corps de défense et\nde sécurité, en particulier du SNR.\n(k)     De s’acquitter de ses obligations internationales de respecter, de protéger et\nde garantir les droits économiques et sociaux:\n i) En élaborant et en mettant en œuvre les budgets de l’État de manière à\nutiliser au maximum les ressources disponibles pour assurer le respect des\ndroits de l’homme à la population appauvrie par la crise politique, en\nparticulier des droits à l’alimentation, à l’eau et à la santé, et pour développer\ndes indicateurs désagrégés, y compris par genre, pour mieux informer ses\npolitiques;\n ii) En entreprenant, en consultation avec les populations travaillant dans\nle secteur agricole, notamment les femmes, des réformes visant une meilleure\nprotection des droits des femmes et une meilleure utilisation des terres pour\nl’agriculture, et en développant des perspectives de travail en dehors du\nsecteur agricole;\n iii) En utilisant une approche fondée sur les droits de l’homme pour régler\nles conflits fonciers dont ceux touchant les personnes ayant fui le Burundi\navant et après 2015;\n iv) En mettant fin à toute considération politique dans les processus de\nrecrutement au sein de l’administration publique, des sociétés publiques et\ndes sociétés mixtes.\n102. La Commission recommande aux partis politiques et aux groupes armés\nd’opposition de s’abstenir de toute attaque sur le territoire burundais et de tout discours\nappelant à la violence, et de s’engager dans la recherche d’une solution durable à la crise\npolitique.\n103. La Commission recommande à l’Union africaine de donner une place importante,\ndans sa recherche d’une solution durable à la crise au Burundi, au respect des droits de\nl’homme et au rejet de l’impunité, tels que prévus par son Acte constitutif.\n104.    La Commission recommande aux partenaires techniques et financiers du Burundi:\na)     De suspendre ou de maintenir la suspension de toute aide budgétaire directe\nau Gouvernement en l’absence de priorisation des ressources internes en faveur des\nobjectifs de développement durable et des droits économiques et sociaux de la population,\net de mesures effectives contre la corruption;","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0109-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":109,"section":"1. Recommandations faites en 2018","text":"b)     De cibler les dons et les financements attribués au Gouvernement sur des\nprojets en faveur des besoins de la population et de s’assurer que ceux-ci sont gérés\nefficacement et de manière transparente;\nc)      D’évaluer régulièrement l’impact des sanctions financières sur la population\nburundaise.\n105. La Commission recommande aux garants de l’Accord d’Arusha, en leur qualité\nd’acteurs engagés en faveur d’une paix durable au Burundi, de continuer à chercher une\nsolution pérenne à la crise politique et des droits de l’homme qui préserve et garantit les\nacquis de l’Accord d’Arusha.","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0110-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":110,"section":"1. Recommandations faites en 2018","text":"Version anglaise\n106. The Commission recommends that the Government of Burundi take the following\nmeasures as a matter of priority:\na)       Put an immediate end to the gross human rights violations being committed\nby agents of the State and Imbonerakure;\nb)     With the support of the international community, establish ad hoc\nmechanisms with a mandate to investigate human rights violations and to prosecute\nperpetrators of international crimes that are not being investigated by the International\nCriminal Court;\nc)      With the support of the international community, establish an independent\nbody with a mandate to investigate the cases of disappearance reported since April 2015,\nlocate potential mass graves, and exhume and identify the remains;\nd)     Take measures to ensure that victims of torture and women survivors of\nsexual violence have access to appropriate care, including free access to all sexual and\nreproductive health services and to psychological support;\ne)   Implement the Guidelines on Combating Sexual Violence and its\nConsequences in Africa adopted by the African Commission on Human and Peoples’\nRights;\nf)      Control price increases, in particular by reviewing duty and tax increases that\nare undermining the population’s right to an adequate standard of living and by abolishing\ncontributions that disproportionately affect the poorest sectors;\ng)     Cooperate with international human rights mechanisms, in particular by:\n i) Resuming the practice of allowing special procedures mandate holders\nto conduct missions to Burundi;\n ii) Implementing the recommendations of the universal periodic review,\ntreaty bodies and special procedures, including by establishing a national\nmechanism for reporting and follow-up.\nh)     Authorize the Office of the United Nations High Commissioner for Human\nRights to resume all its activities in Burundi without hindrance;\ni)   Sign and implement the memorandum of understanding with the African\nUnion and permit the full deployment of the 100 human rights observers provided for\ntherein.\n107. For the medium and longer terms, the Commission also recommends that the\nGovernment of Burundi:\na)     Amend the Organization Act of 8 March 2018 amending Act No. 01/03 of 24\nJanuary 2013 on the mandate, composition, organization and functioning of the National\nCommunication Council with a view to ensuring the latter’s independence;\nb)     Ratify the International Convention for the Protection of All Persons from\nEnforced Disappearance;","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0111-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":111,"section":"1. Recommandations faites en 2018","text":"c)      Amend the Code of Criminal Procedure to align its provisions with\ninternational standards, in particular the provisions on time limits for police custody and on\noversight of detention, night-time and warrantless searches, the flagrante delicto procedure\nand the offence of “undermining the internal security of the State”, and provisions that\ngrant de jure impunity to judges and to officers of the criminal investigation police (police\njudiciaire);\nd)     Put an end to arbitrary detention and improve conditions of detention by:\n i) Implementing the Guidelines on the Conditions of Arrest, Police\nCustody and Pre-Trial Detention in Africa adopted by the African\nCommission on Human and Peoples’ Rights;\n ii) Ensuring that detention is subject to oversight measures for assessing\nits legality and compatibility with human rights.\ne)      In the absence of an independent and efficient judicial system, cooperate\nfully with the International Criminal Court in the investigation opened on 25 October 2017;\nf)     Undertake an in-depth reform of the judicial system to ensure its\nindependence, impartiality and effectiveness, including by:\n i) Implementing the Principles and Guidelines on the Right to a Fair\nTrial and Legal Assistance in Africa adopted by the African Commission on\nHuman and Peoples’ Rights;\n ii) Publishing the conclusions of the national forum on the justice system\nheld in 2013 and convening a meeting of justice-sector stakeholders and\ninternational partners to discuss follow-up action;\n iii) Increasing the budget for the justice sector and ensuring that it is\nmanaged autonomously;\n iv) Raising the pay levels of judges in the ordinary courts and increasing\nthe resources and facilities available to them;\n v) Computerizing court registries;\n vi) Reviewing the composition of the Judicial Service Commission to\nensure that the majority of its members are appointed by their peers;\n vii)     Reviewing procedures for the appointment, assignment,\nevaluation and promotion of judges to ensure that such procedures are not\ndependent on the executive branch;\n viii) Ensuring strict observance of the principle that judges should have\nsecurity of tenure;\n ix) Protecting and safeguarding the independence of the judiciary by\nprohibiting any interference in the administration of justice by government\nauthorities, members of the ruling party or members of the defence and\nsecurity forces, and imposing penalties on anyone who influences or seeks to\ninfluence the administration of justice;\n x) Developing legal aid programmes for persons belonging to the most\nvulnerable groups;\n xi)       Strengthening victim and witness protection mechanisms and\nimproving their effectiveness in order to restore public trust and encourage\nwitnesses to come forward without fear for their safety.\ng)    In consultation with the beneficiaries, establish a reparations programme for\nvictims of human rights violations, ensuring that material, symbolic, individual and\ncollective reparations are made available regardless of whether or not the perpetrators are\nconvicted;\nh)     Establish the State fund for victims of torture provided for by law, in\nconformity with general comment No. 4 on the African Charter on Human and Peoples’","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0112-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":112,"section":"1. Recommandations faites en 2018","text":"Rights, adopted by the African Commission on Human and Peoples’ Rights, concerning the\nright to redress for victims of torture and other cruel, inhuman or degrading punishment or\ntreatment (art. 5);\ni)     Establish a compensation fund for victims of arbitrary and unlawful\ndetention;\nj)     Reform the security sector by:\n i) Ensuring that outsiders are not involved in defence or security\nactivities;\n ii) Clearly defining the roles of the various defence and security forces,\nin particular the National Intelligence Service;\n iii) Suspending members of the defence and security forces who are\nsuspected of involvement in human rights violations until the relevant\ninvestigations and judicial proceedings have concluded;\n iv) Establishing rigorous and transparent selection procedures that\ninclude vetting mechanisms;\n v) Strengthening democratic civilian control over the defence and\nsecurity forces, in particular the National Intelligence Service.\n(k)     Meet its international obligations to respect, protect and fulfil economic and social\nrights by:\n i) Developing and implementing State budgets in such a way as to\nmaximize the use of available resources to ensure that the human rights of the\nsectors impoverished by the political crisis are respected, in particular the\nrights to food, water and health care, and to develop indicators disaggregated\nby factors such as gender in order to better inform its policies;\n ii) In consultation with population groups working in the agricultural\nsector, including women, undertaking reforms with the aim of better\nprotecting women’s rights and making better use of land for agriculture, and\ndeveloping employment opportunities outside the agricultural sector;\n iii) Taking a rights-based approach to the settlement of land conflicts,\nincluding those involving persons who fled Burundi either before or after\n2015;\n iv) Ending the inclusion of any political considerations in hiring\nprocesses for the civil service, State enterprises and public-private\nenterprises.\n108. The Commission recommends that political parties and armed opposition groups\nrefrain from engaging in any attacks on Burundian territory and from any speech calling for\nviolence, and that they join the effort to find a lasting solution to the political crisis.\n109. The Commission recommends that the African Union, in its efforts to find a lasting\nsolution to the crisis in Burundi, give priority to respect for human rights and the rejection\nof impunity, as provided for in its Constitutive Act.\n110.   The Commission recommends that the technical and financial partners of Burundi:\na)     Suspend, or maintain the suspension of, any direct budget support to the\nGovernment until such time as priority is given to the allocation of domestic resources for\nthe fulfilment of the Sustainable Development Goals and the economic and social rights of\nthe population, and effective measures are taken against corruption;\nb)    Ensure that grants and financing provided to the Government are earmarked\nfor projects to meet the population’s needs, and ensure that such funding is managed\neffectively and transparently;\nc)      Regularly evaluate the impact of financial sanctions on the people of\nBurundi.","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0113-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":113,"section":"1. Recommandations faites en 2018","text":"111. The Commission recommends that the guarantors of the Arusha Agreement, in their\ncapacity as committed proponents of a lasting peace in Burundi, continue to seek a durable\nsolution to the political and human rights crisis that will preserve and safeguard the\nachievements of the Arusha Agreement.","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0114-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":114,"section":"1. Aux autorités burundaises","text":"112. De mettre immédiatement un terme aux violations graves des droits de l’homme\ncommises par des agents de l’État et des Imbonerakure sur lesquels l’État exerce un\ncontrôle;\n113. D’enquêter sur ces violations et s’assurer que les auteurs présumés soient jugés dans\nles meilleurs délais, dans des procédures crédibles, indépendantes et équitables, et que les\nvictimes obtiennent une juste réparation. Dans le cas où les auteurs présumés sont des\nagents de l’État, les suspendre jusqu’au terme de l’enquête et de la procédure judiciaire;\n114. De prendre des mesures concrètes pour une amélioration rapide de la situation des\ndroits de l’homme, notamment en:\n• Annulant les mandats d’arrêt contre des dirigeants de médias, d’organisations de\nla société civile et de partis politiques qui n’ont pas utilisé ou prôné la violence, et\npermettant leur retour en toute sécurité au Burundi;\n• Levant la suspension et la radiation des médias et organisations de la société\ncivile, leur permettant de reprendre leurs activités en toute indépendance, et revoyant\nles lois adoptées en 2017 sur les organisations non-gouvernementales burundaises et\ninternationales;\n•   Libérant immédiatement tous les prisonniers politiques;\n• S’assurant que toute personne arrêtée soit détenue dans un lieu de détention\nofficiel et que des observateurs nationaux et internationaux soient autorisés à leur\nrendre visite;\n• Veillant à ce que les officiers de police judiciaire ne soient pas habilités à mener\ndes perquisitions sans mandat et de nuit comme envisagé dans les projets\nd’amendement du Code pénal et du Code de procédure pénale;\n• S’assurant que des individus qui n’y sont pas légalement habilités, en particulier\ndes Imbonerakure, ne conduisent pas des activités de maintien de l’ordre ou n’y\nprennent pas part, y compris dans des lieux de détention, et qu’ils ne portent pas des\nuniformes militaires ou de police ou ne soient pas en possession d’armes;\n•   Poursuivant les auteurs de discours haineux ou appelant à la violence;\n• Mettant fin aux menaces, intimidations et actes d’extorsion par des agents de\nl’État et des Imbonerakure;\n• Permettant aux victimes de violences sexuelles et de torture d’avoir accès à des\nservices médicaux et psychosociaux.\n115.   D’engager une réforme en profondeur du système judiciaire, notamment en:\n• Publiant les conclusions des états généraux de la justice qui se sont tenus en\n2013 à Gitega;\n• Revoyant la composition du Conseil national de la magistrature afin que ses\nmembres soient en majorité désignés par leurs pairs;\n• Revoyant les procédures de nomination, d’affectation, de notation et\nd’avancement des magistrats afin qu’elles ne dépendent pas du pouvoir exécutif;\n•   Veillant au respect strict du principe d’inamovibilité des magistrats du siège;","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0115-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":115,"section":"1. Aux autorités burundaises","text":"• Protégeant et garantissant l’indépendance du système judiciaire en interdisant\ntoute ingérence dans le fonctionnement de la justice par des autorités\ngouvernementales, des membres du parti au pouvoir ou des membres des corps de\ndéfense et de sécurité, et en prenant des sanctions contre ceux qui influencent, ou\ncherchent à influencer, le fonctionnement de la justice;\n•   Développant des programmes d’aide juridictionnelle pour les plus vulnérables;\n• Renforçant les mécanismes de protection de victimes et de témoins, ainsi que\nleur efficacité, pour restaurer la confiance de la population et encourager les témoins\nà s’exprimer sans crainte pour leur sécurité.\n116. De s’assurer que les membres des corps de défense et de sécurité respectent les\ndroits de l’homme en toutes circonstances et servent les intérêts de la population dans son\nensemble et pas uniquement ceux du parti au pouvoir, notamment en:\n• Renforçant le contrôle civil des corps de défense et de sécurité et l’indépendance\ndes organes chargés de ce contrôle créés par la Constitution, en particulier le\nParlement, la Commission nationale indépendante des droits de l’homme et\nl’Ombudsman;\n•   Remédiant à la carence constitutionnelle de contrôle civil du SNR;\n• Prenant des mesures pour vérifier les antécédents, notamment en matière de\ndroits de l’homme, des agents des corps de défense et de sécurité et intégrant ces\nmesures à une refonte des procédures de recrutement et d’avancement de ces agents.\n117. De revenir sur sa décision de se retirer du Statut de Rome et coopérer pleinement\navec la CPI dans la procédure d’examen préliminaire en cours et, si une enquête est\nouverte, poursuivre cette coopération et assurer la protection des victimes et témoins;\n118. D’autoriser le HCDH à reprendre ses activités de documentation des violations des\ndroits de l’homme au Burundi, suspendues depuis octobre 2016;\n119. De signer et mettre en œuvre le mémorandum d’entente avec l’Union africaine et\npermettre le déploiement complet des 100 observateurs des droits de l’homme et des 100\nexperts militaires, décidé en 2016;\n120. De coopérer avec les mécanismes des droits de l’homme des Nations Unies en\naccueillant à nouveau des missions des procédures spéciales et en mettant en œuvre les\nrecommandations récentes des organes de traité ;\n121. De s’engager activement dans la voie d’une résolution durable de la crise politique,\nnotamment dans le cadre d’initiatives de dialogue engagées au niveau international.","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0116-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":116,"section":"2. Aux partis politiques et groupes armés d’opposition","text":"122. De mettre immédiatement un terme aux atteintes aux droits de l’homme et aux actes\nde violence commis par leurs membres;\n123. De s’abstenir de tout discours appelant à la violence et s’engager dans la recherche\nd’une solution durable à la crise politique au Burundi.","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0117-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":117,"section":"3. Au Conseil des droits de l’homme","text":"124. De prolonger le mandat de la Commission pour une durée d’un an aux fins\nd’approfondir et de poursuivre ses enquêtes en raison de la persistance des violations graves\ndes droits de l’homme et des atteintes à ceux-ci et en l’absence d’autres mécanismes\nspécifiques en mesure de mener des enquêtes indépendantes et approfondies sur la situation\ndes droits de l’homme au Burundi;\n125. De demander au Haut-Commissaire des Nations Unies aux droits de l’homme de\nfaire un rapport sur l’évolution de sa coopération avec le Gouvernement du Burundi aux\nprochaines sessions du Conseil.","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0118-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":118,"section":"5. Au Conseil de sécurité des Nations Unies","text":"127. De prendre dûment compte des présentes conclusions de la Commission et de la\npersistance de violations graves des droits de l’homme dans toute discussion sur le Burundi\net, dans ce contexte, veiller à la mise en œuvre effective de la résolution 2303 (2016);\n128. De saisir la CPI de tout crime de droit international qui serait commis au Burundi\naprès le 27 octobre 2017;\n129. De prendre des sanctions individuelles contre les principaux auteurs présumés de\nviolations graves des droits de l’homme et de crimes de droit international au Burundi.","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-p0006-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"6","seq":119,"section":"5. Au Conseil de sécurité des Nations Unies","text":"Au Secrétaire-général des Nations Unies\n130. De veiller à ce que le respect des droits de l’homme et la restauration de l’État de\ndroit soient parmi les priorités de son Envoyé spécial sur le Burundi;\n131. De veiller à ce qu’aucun auteur présumé de violations des droits de l’homme ou de\ncrimes de droit international au Burundi ne soit recruté dans des missions de maintien de la\npaix des Nations Unies.","annex":1},{"id":"a-hrc-42-49-p0007-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"7","seq":120,"section":"5. Au Conseil de sécurité des Nations Unies","text":"Aux États membres des Nations Unies\n132. D’accorder prima facie le statut de réfugié aux demandeurs d’asile burundais et\nveiller au respect strict du principe de non-refoulement, ainsi qu’à la protection des\nréfugiés;\n133. De poursuivre, au titre de la compétence universelle, les auteurs présumés de crimes\nde droit international commis au Burundi se trouvant sur leur territoire;\n134. De maintenir, en l’absence de toute amélioration de la situation des droits de\nl’homme dans le pays, les sanctions individuelles et la suspension de l’aide directe au\nGouvernement burundais;\n135. De fournir une assistance technique aux autorités burundaises, dans la mesure où ces\ndernières font preuve d’une véritable volonté politique, afin de mener des enquêtes\ncrédibles et indépendantes, notamment en matière d’autopsie, d’exhumation et\nd’identification des corps;\n136. De soutenir la mise en place de services médicaux et psychosociaux spécialisés,\nnotamment pour les victimes de torture et de violences sexuelles;\n137. De soutenir les autorités burundaises, si celles-ci font preuve d’une véritable volonté\npolitique, dans tout effort de réforme du système judiciaire et du secteur de sécurité qu’elles\nvoudront engager aux fins d’améliorer la situation des droits de l’homme.","annex":1},{"id":"a-hrc-42-49-p0008-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"8","seq":121,"section":"5. Au Conseil de sécurité des Nations Unies","text":"À l’Union africain\n138. De reprendre l’initiative dans la recherche d’une solution durable à la crise au\nBurundi fondée sur le respect des droits de l’homme et le rejet de l’impunité, tels que\nprévus par son Acte constitutif, et s’y engager activement;\n139. De veiller à ce qu’aucun agent de l’État burundais accusé de violations des droits de\nl’homme ou de crimes de droit international ne soit recruté dans des missions de maintien\nde la paix de l’Union africaine;\n140. De s’assurer que l’équipe complète de ses observateurs des droits de l’homme et\nexperts militaires soit rapidement déployée au Burundi;\n141. D’envisager, en cas de persistance de la situation actuelle au Burundi, l’application\nde l’article 4 (h) de son Acte constitutif, autorisant l’Union africaine à intervenir dans un\nÉtat membre dans certaines circonstances, notamment en cas de crimes contre l’humanité.","annex":1},{"id":"a-hrc-42-49-p0009-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"9","seq":122,"section":"5. Au Conseil de sécurité des Nations Unies","text":"À la Communauté des États d’Afrique de l’Est\n142. De s’assurer que l’amélioration rapide de la situation des droits de l’homme soit une\npriorité dans ses efforts de médiation.","annex":1},{"id":"a-hrc-42-49-p0010-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":"10","seq":123,"section":"5. Au Conseil de sécurité des Nations Unies","text":"Aux garants de l’Accords d’Arusha de 2000, en leur qualité d’acteurs engagés en\nfaveur d’une paix durable au Burundi\n143. De se réunir le plus rapidement possible en vue de trouver une solution pérenne à la\ncrise politique et des droits de l’homme au Burundi.\nVersion anglaise\n1.    The Burundian authorities should:\n144. Put an immediate end to the gross human rights violations being committed by\nagents of the State and Imbonerakure over which the State exercises control;\n145. Investigate these violations, ensure that the alleged perpetrators are prosecuted\npromptly in accordance with credible, independent and fair procedures, and that the victims\nobtain just reparation, and, where the alleged perpetrators are agents of the State, suspend\nthem from their duties pending the completion of the investigation and the judicial\nproceedings;\n146. Take practical measures to bring about a rapid improvement of the human rights\nsituation, in particular by:\n• Withdrawing the warrants for the arrest of heads of media outlets, civil society\norganizations and political parties who have neither used nor advocated violence, and\npermitting their safe return to Burundi;\n• Lifting the suspension and reversing the revocation of the licences of media and civil\nsociety organizations, permitting them to resume their activities with complete\nindependence and reviewing the laws adopted in 2017 concerning non-profit\norganizations and foreign non-governmental organizations;\n• Immediately releasing all political prisoners;\n• Ensuring that every person arrested is detained in an official place of detention and\nthat national and international observers are allowed to visit them;\n• Ensure that criminal investigation officers (officiers de police judiciaire) are not\nauthorized to conduct searches without a warrant, including at night, as envisaged in\nthe draft amendments to the Criminal Code and the Code of Criminal Procedure;\n• Ensuring that individuals lacking legal authorization, particularly the Imbonerakure,\ndo not perform or participate in law enforcement activities, including in places of\ndetention, and do not wear military or police uniforms or possess weapons;\n• Prosecuting individuals who incite hatred or violence;\n• Putting an end to threats, intimidation and acts of extortion by State officials and the\nImbonerakure;\n• Giving victims of sexual violence and torture access to medical and psychosocial\nservices.\n147.     Undertake a thorough reform of the judiciary, in particular by:\n• Publishing the conclusions of the General Convention on the Judiciary (États\ngénéraux de la justice) held in Gitega in 2013;\n• Reviewing the composition of the Superior Council of Magistrates (Conseil\nsupérieur de la magistrature) so that the majority of its members are designated by\ntheir peers;\n• Reviewing the nomination, posting, evaluation and promotion procedures of\nmagistrates so that they do not depend of the executive;\n• Ensuring the respect of the principle of security of tenure for judges;\n• Protecting and guaranteeing the independence of the judiciary by prohibiting all\ninterference in their functions by governmental authorities, members of the ruling\nparty or security and defence forces, and imposing sanctions on those who influence,\nor seek to influence, the functioning of the judiciary;\n• Developing legal aid programmes for the most vulnerable;\n• Reinforcing the protection mechanisms for victims and witnesses, as well as their\nefficiency, in order to restore people’s confidence in the system and to encourage\nwitnesses to testify without fear for their security.\n148. Ensure that members of the defence and security forces respect human rights in all\ncircumstances and serve the interests of the population as a whole, not solely those of the\nruling party, in particular by:\n• Reinforcing civilian control over the military and the independence of the competent\norgans created by the Constitution to supervise this control, in particular the\nParliament, the National Human Rights Commission and the Ombudsman;\n• Implementing civilian control over the National Intelligence Service (Service\nnational de renseignement) in line with the Constitution;\n• Conducting background checks, in particular on human rights, on defense and\nsecurity forces and incorporating these measures into reforms of the recruitment and\ncareer progression of these agents.\n149. Reconsider their decision to withdraw from the Rome Statute, cooperate fully with\nthe International Criminal Court in the ongoing preliminary examination and, if an\ninvestigation is initiated, continue that cooperation, inter alia by ensuring the protection of\nvictims and witnesses;\n150. Authorize the Office of the United Nations High Commissioner for Human Rights to\nresume its documentation of human rights violations in Burundi, which has been suspended\nsince October 2016;\n151. Sign and implement the memorandum of understanding with the African Union and\npermit the full deployment of 100 human rights observers and 100 military experts that was\ndecided upon in 2016;\n152. Cooperate with United Nations human rights mechanisms by once again receiving\nspecial procedures missions and implementing the recent recommendations of treaty\nbodies;\n153. Actively seek a lasting solution to the political crisis, inter alia through international\ninitiatives to promote dialogue.\n2.     Political parties and armed opposition groups should:\n154. Put an immediate end to human rights abuses and acts of violence committed by\ntheir members;\n155. Refrain from any incitement of violence and participate in the quest for a lasting\nsolution to the political crisis in Burundi.\n3      The Human Rights Council should:\n156. Extend the Commission’s mandate for a period of one year to enable it to conduct\nfurther and more thorough investigations in view of the persistence of gross human rights\nviolations and abuses and the absence of other specific mechanisms capable of undertaking\nindependent and thorough investigations into the human rights situation in Burundi;\n157. Request the Office of the United Nations High Commissioner for Human Rights to\nreport, at the forthcoming sessions of the Council, on the development of its cooperation\nwith the Burundian Government.\n4.    The International Criminal Court should:\n158. Initiate, as soon as possible, an investigation into the crimes committed in Burundi\nin light of the conclusions contained in the present report and other information at its\ndisposal.\n5.    The United Nations Security Council should:\n159. Take due account of the Commission’s conclusions, as well as persistence of gross\nviolations of human rights, in any discussion on Burundi and, in this context, ensure the\neffective implementation of resolution 2303 (2016);\n160. Refer to the International Criminal Court any international crime that might be\ncommitted in Burundi after 27 October 2017;\n161. Impose individual sanctions against the principal alleged perpetrators of gross\nhuman rights violations and international crimes in Burundi.\n6.    The Secretary-General of the United Nations should:\n162. Ensure that respect for human rights and restoration of the rule of law are among the\npriorities of his Special Envoy for Burundi;\n163. Ensure that no alleged perpetrator of human rights violations or international crimes\nin Burundi is recruited for United Nations peacekeeping missions.\n7.    The States Members of the United Nations should:\n164. Grant prima facie refugee status to Burundian asylum seekers and ensure strict\nre64ect for the principle of non-refoulement and refugee protection;\n165. Prosecute, in accordance with the principle of universal jurisdiction, alleged\nperpetrators of international crimes committed in Burundi who are found to be in their\nterritory;\n166. Maintain, in the absence of any improvement in the human rights situation in\nBurundi, the individual sanctions and the suspension of direct aid to the Government;\n167. Provide technical assistance inter alia in respect to autopsies, exhumations and\nidentification of bodies, to enable the Burundian to conduct credible and independent\ninvestigations;\n168. Support the establishment of specialized medical and psychosocial services,\nespecially for victims of torture and sexual violence;\n169. Support Burundian authorities in any judicial and security sector reform endeavors\nthat they might wish to undertake in order to improve the human rights situation.\n8.    The African Union should:\n170. Retake the lead in seeking a lasting solution to the crisis in Burundi based on respect\nfor human rights and rejection of impunity, as provided for in its Constitutive Act, and play\nan active role in that process;\n171. Ensure that no agent of the Burundian State who is accused of human rights\nviolations or international crimes is recruited for African Union peacekeeping missions;\n172. Ensure that the full complement of African Union human rights observers and\nmilitary experts is deployed rapidly in Burundi;\n173. Consider, in the event that the current situation in Burundi persists, the application\nof Article 4 (h) of the Constitutive Act of the African Union, under which it is authorized to\nintervene in a member State in certain circumstances, particularly in the event of crimes\nagainst humanity.\n9.     The East African Community should:\n174. Ensure that a rapid improvement of the human rights situation is a priority in its\nmediation efforts.","annex":1},{"id":"a-hrc-42-49-u0124-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":124,"section":"10. The guarantors of the 2000 Arusha Agreement, in their capacity as committed","text":"Facteur de risque 1. Situations de conflit armé ou autres formes d’instabilité\na)     Conflit armé international ou non international;\nb)      Crise sécuritaire provoquée, entre autres, par la dénonciation d’accords de\npaix, un conflit armé dans les pays voisins, des menaces d’interventions étrangères ou des\nactes de terrorisme;\nc)     Crise ou urgence humanitaire, pouvant être causée notamment par une\ncatastrophe naturelle ou une épidémie;\nd)     Instabilité politique provoquée par un changement de régime ou un transfert\nde pouvoir soudain ou irrégulier;\ne)    Instabilité politique provoquée par des luttes de pouvoir ou la montée en\npuissance de mouvements d’opposition nationalistes, armés ou radicaux;\nf)     Tension politique provoquée par des régimes autocratiques ou une lourde\nrépression politique;\ng)     Instabilité économique provoquée par une pénurie de ressources ou des\ndifférends concernant leur utilisation ou leur exploitation;\nh)     Instabilité économique provoquée par une crise grave de l’économie\nnationale;\ni)     Instabilité économique provoquée par la misère, un chômage de masse ou de\nprofondes inégalités horizontales;\nj)     Instabilité sociale provoquée par une résistance à l’autorité de l’État ou à ses\npolitiques ou par des protestations de masse contre celles-ci;\nk)     Instabilité sociale provoquée par l’exclusion ou des tensions fondées sur des\nquestions d’identité, leur perception ou leurs formes extrémistes.","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0125-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":125,"section":"10. The guarantors of the 2000 Arusha Agreement, in their capacity as committed","text":"Facteur de risque 2. Antécédents de violations graves du droit international des droits\nde l’homme et du droit international humanitaire\na)      Restrictions ou violations graves, passées ou actuelles, des droits consacrés\npar le droit international des droits de l’homme et le droit international humanitaire, surtout\nsi elles sont caractérisées par un comportement systématique observé préalablement et si\nelles visent des groupes, populations ou personnes protégés;\nb)    Actes de génocide, crimes contre l’humanité, crimes de guerre ou incitation à\nles commettre, survenus dans le passé;\nc)      Politique ou pratique d’impunité ou de tolérance à l’égard de violations\ngraves du droit international des droits de l’homme et du droit international humanitaire,\nd’atrocités criminelles ou de l’incitation à les commettre;\nd)     Inaction, réticence à utiliser ou refus d’utiliser tous les moyens possibles pour\nfaire cesser des violations graves prévues, prévisibles ou persistantes du droit international\ndes droits de l’homme et du droit international humanitaire ou des atrocités criminelles\nprobables, ou incitation à les commettre;","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0126-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":126,"section":"10. The guarantors of the 2000 Arusha Agreement, in their capacity as committed","text":"e)    Maintien d’une aide à des groupes accusés de participer à des violations\ngraves du droit international des droits de l’homme et du droit international humanitaire,\nnotamment des atrocités criminelles, ou non-condamnation de leurs actes;\nf)     Justification de violations graves du droit international des droits de l’homme\net du droit international humanitaire ou d’atrocités criminelles, rapports partiaux les\nconcernant ou refus de les reconnaître;\ng)     Absence de processus de réconciliation ou de justice transitionnelle après un\nconflit, ou politisation de ce processus;\nh)      Méfiance généralisée envers les institutions de l’État ou entre différents\ngroupes en raison de l’impunité.","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0127-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":127,"section":"10. The guarantors of the 2000 Arusha Agreement, in their capacity as committed","text":"Facteur de risque 3. Faiblesse des structures de l’État\na)      Cadre juridique national n’offrant pas une protection suffisante et efficace,\nnotamment par la ratification et l’incorporation dans le droit interne des instruments relatifs\nau droit international des droits de l’homme et au droit international humanitaire;\nb)     Manque de ressources au sein des institutions nationales, en particulier les\ninstitutions judiciaires et celles chargées de l’application des lois et de la protection des\ndroits de l’homme, et manque de représentation adéquate ou de formation;\nc)     Absence de justice indépendante et impartiale;\nd)     Absence de contrôle civil efficace des forces de sécurité;\ne)     Niveaux élevés de corruption ou mauvaise gouvernance;\nf)     Absence ou insuffisance de mécanismes externes ou internes de contrôle et\nde responsabilité, notamment que les victimes peuvent saisir pour demander réparation;\ng)     Manque de sensibilisation et de formation des forces militaires, des forces\nirrégulières, des groupes armés non étatiques et des autres acteurs concernés au droit\ninternational des droits de l’homme et au droit international humanitaire;\nh)     Manque de capacité de vérifier que les moyens et méthodes de guerre sont\nconformes aux normes du droit international humanitaire;\ni)     Manque de moyens pour la réforme ou le renforcement des institutions,\nnotamment par une aide régionale ou internationale;\nj)     Ressources insuffisantes pour mettre en oeuvre des mesures globales de\nprotection des populations.","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0128-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":128,"section":"10. The guarantors of the 2000 Arusha Agreement, in their capacity as committed","text":"Facteur de risque 4. Motivations ou incitations\na)     Motivations politiques, en particulier celles visant l’acquisition ou la\nconsolidation du pouvoir;\nb)       Intérêts économiques, notamment ceux fondés sur la préservation et le bien-\nêtre des élites ou de groupes d’identité, ou sur le contrôle de la répartition des ressources;\nc)     Intérêts stratégiques ou militaires, notamment ceux fondés sur la protection\nou la saisie de territoires et de ressources;\nd)    Autres intérêts, notamment ceux visant à rendre une zone homogène dans son\nidentité;\ne)     Menaces réelles ou perçues comme telles de groupes, populations ou\npersonnes protégés contre les intérêts ou les objectifs des auteurs d’actes criminels,\nnotamment l’impression de déloyauté envers une cause;\nf)      Appartenance ou adhésion réelle ou perçue comme telle de groupes,\npopulations ou personnes protégés à des groupes d’opposition armés;\ng)     Idéologies fondées sur la suprématie d’une certaine identité ou sur des\nversions extrémistes de l’identité;","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0129-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":129,"section":"10. The guarantors of the 2000 Arusha Agreement, in their capacity as committed","text":"h)     Politisation de griefs, de tensions ou de cas d’impunité issus du passé;\ni)     Traumatisme social provoqué par des situations de violence passées\nauxquelles il n’a pas été donné de suite satisfaisante et qui ont engendré des sentiments de\nperte, de déplacement et d’injustice et un désir possible de revanche.","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0130-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":130,"section":"10. The guarantors of the 2000 Arusha Agreement, in their capacity as committed","text":"Facteur de risque 5. Capacité de commettre des atrocités criminelles\na)     Disponibilité de personnel et d’armes et munitions ou de moyens financiers\npublics ou privés permettant de les acquérir;\nb)     Capacité de transporter et déployer du personnel et de transporter et distribuer\ndes armes et des munitions;\nc)      Capacité d’encourager ou de recruter de nombreux partisans au sein de\npopulations ou de groupes et disponibilité de moyens pour les mobiliser;\nd)     Solide culture d’obéissance à l’autorité et de conformité au groupe;\ne)      Présence d’autres forces armées ou de groupes armés non étatiques ou\nexistence de liens avec de tels forces ou groupes;\nf)    Présence d’acteurs commerciaux ou d’entreprises pouvant jouer un rôle\ndéterminant en fournissant des biens, des services ou d’autres formes d’appui pratique ou\ntechnique contribuant à soutenir les auteurs;\ng)     Appui financier, politique ou autre d’acteurs nationaux influents ou riches;\nh)      Appui armé, financier, logistique ou autre, notamment sous la forme\nd’entraînement, fourni par des acteurs extérieurs, notamment des États, des organisations\ninternationales ou régionales ou des entreprises privées.","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0131-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":131,"section":"10. The guarantors of the 2000 Arusha Agreement, in their capacity as committed","text":"Facteur de risque 6. Absence de facteurs atténuants\na)    Insuffisance ou absence de processus d’autonomisation, de ressources,\nd’alliés ou d’autres éléments qui pourraient contribuer à la capacité des groupes,\npopulations ou personnes protégés de se protéger eux-même;\nb)     Absence de société civile nationale solide, organisée et représentative et de\nmédias nationaux libres, diversifiés et indépendants;\nc)    Absence d’intérêt et d’attention des acteurs de la société civile internationale\nou d’accès aux médias internationaux;\nd)     Absence ou présence limitée des Nations Unies, d’organisations non\ngouvernementales internationales ou d’autres acteurs internationaux ou régionaux dans le\npays ayant accès aux populations;\ne)      Absence d’adhésion ou de participation effective de l’État à des organisations\ninternationales ou régionales établissant des obligations afférentes au statut de membre;\nf)     Manque de contact, d’ouverture ou de relations politiques ou économiques\navec d’autres États ou organisations;\ng)    Coopération limitée de l’État avec les mécanismes internationaux et\nrégionaux des droits de l’homme;\nh)     Manque de volonté des parties à un conflit d’engager un dialogue, de faire\ndes concessions et de solliciter l’appui de la communauté internationale, ou absence\nd’incitations à le faire;\n Réticence ou échec des États Membres de l’Organisation des Nations\nUnies ou des organisations internationales ou régionales à aider un État à\nassumer sa responsabilité de protéger ses populations contre les atrocités\ncriminelles, ou à agir lorsque l’État n’assume manifestement pas cette\nresponsabilité, ou indifférence à cet égard.","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0132-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":132,"section":"10. The guarantors of the 2000 Arusha Agreement, in their capacity as committed","text":"j)     Manque de soutien des États voisins pour ce qui est de protéger les\npopulations à risque en quête de refuge : fermeture des frontières, rapatriement forcé ou\nrestrictions en matière d’aide;\nk)      Absence de mécanisme d’alerte rapide permettant de prévenir des atrocités\ncriminelles.","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0133-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":133,"section":"10. The guarantors of the 2000 Arusha Agreement, in their capacity as committed","text":"Facteur de risque 7. Circonstances propices ou action préparatoire restreignant les\ndroits fondamentaux\na)      Suspension d’institutions vitales de l’État ou ingérence dans ces institutions,\nou mesures provoquant des modifications de leur composition ou l’équilibre des pouvoirs,\nen particulier s’il en résulte l’exclusion ou une sous-représentation de groupes protégés;\nb)     Renforcement de l’appareil de sécurité, réorganisation ou mobilisation de\ncelui-ci contre des groupes, populations ou personnes protégés;\nc)      Acquisition de grandes quantités d’armes et de munitions ou d’autres objets\npouvant être utilisés pour causer des dommages;\nd)     Création de milices ou de groupes paramilitaires, ou intensification de l’appui\nà de tels milices ou groupes;\ne)      Imposition d’un contrôle strict sur l’utilisation des moyens de communication\nou interdiction d’y avoir accès;\nf)      Expulsion ou refus d’autoriser la présence d’organisations non\ngouvernementales, d’organisations internationales, de médias ou d’autres acteurs pertinents\nou imposition de lourdes restrictions à leurs services et déplacements;\ng)     Augmentation du nombre de violations du droit à la vie, de l’intégrité\nphysique, de la liberté ou de la sécurité de membres de groupes, populations ou personnes\nprotégés, ou adoption récente de mesures ou de lois qui leur portent atteinte ou constituent\nune discrimination délibérée envers eux;\nh)    Augmentation du nombre d’actes de violence graves contre les femmes et les\nenfants ou création de conditions facilitant la commission d’agressions sexuelles contre\neux, notamment comme instrument de terreur;\ni)     Imposition de conditions de vie délétères ou déportation, appréhension,\nregroupement, ségrégation, évacuation, déplacement ou transfert forcés de groupes,\npopulations ou individus protégés vers des camps, des zones rurales, des ghettos ou d’autres\nlieux désignés;\nj)      Destruction ou pillage de biens ou d’installations essentiels à des groupes,\npopulations ou personnes protégés, ou de biens liés à l’identité culturelle et religieuse;\nk)       Marquage de personnes ou de leurs biens au motif de leur appartenance à un\ngroupe;\nl)      Politisation accrue de l’identité, d’événements du passé ou de motifs de se\nlivrer à la violence;\nm)   Augmentation du nombre de déclarations provocatrices, de campagnes de\npropagande ou d’incitations à la haine visant des groupes, populations ou personnes\nprotégés.","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0134-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":134,"section":"10. The guarantors of the 2000 Arusha Agreement, in their capacity as committed","text":"Facteur de risque 8. Facteurs déclencheurs\na)       Déploiement soudain de forces de sécurité ou déclenchement d’hostilités\narmées;\nb)      Débordement de conflits armés ou graves tensions dans les pays voisins;\nc)     Mesures prises par la communauté internationale, perçues par un État comme\nmenaçant sa souveraineté;","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0135-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":135,"section":"10. The guarantors of the 2000 Arusha Agreement, in their capacity as committed","text":"d)      Changements de régime, transferts de pouvoir ou modifications du pouvoir\npolitique des groupes, survenant soudainement ou irrégulièrement;\ne)      Atteintes à la vie, à l’intégrité physique, à la liberté ou à la sécurité de\ndirigeants, de personnalités éminentes ou de membres de groupes opposés; autres actes de\nviolence graves, notamment attentats terroristes ;\nf)     Manifestations religieuses ou actes réels ou perçus comme tels d’intolérance\nreligieuse ou d’irrespect, notamment en dehors des frontières nationales ;\ng)      Actes d’incitation ou propagande haineuse visant des groupes ou des\npersonnes particulières;\nh)      Recensement, élections, activités essentielles liées à ces processus ou\nmesures qui les déstabilisent\ni)     Changements soudains affectant l’économie ou la population active, résultant\nnotamment de crises financières, de catastrophes naturelles ou d’épidémies;\nj)     Découverte de ressources naturelles ou lancement de projets d’exploitation\nayant de graves incidences sur les moyens de subsistance et la viabilité de groupes ou de\npopulations civiles;\nk)    Commémoration de crimes du passé ou d’épisodes traumatiques ou\nhistoriques pouvant exacerber les tensions entre groupes, notamment la glorification\nd’auteurs d’atrocités.\nl)     Actes liés aux processus d’établissement des responsabilités, en particulier\ns’ils sont perçus comme injustes","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0136-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":136,"section":"10. The guarantors of the 2000 Arusha Agreement, in their capacity as committed","text":"Risk factor 1. Situations of armed conflict or other forms of instability\na)   International or non-international armed conflict;\nb)      Security crisis caused by, among other factors, defection from peace\nagreements, armed conflict in neighboring countries, threats of external interventions or\nacts of terrorism;\nc)     Humanitarian crisis or emergency, including those caused by natural disasters\nor epidemics;\nd)   Political instability caused by abrupt or irregular regime change or transfer of\npower;\ne)      Political instability caused by disputes over power or growing nationalist,\narmed or radical opposition movements;\nf)   Political tension caused by autocratic regimes or severe political repression;\ng)      Economic instability caused by scarcity of resources or disputes over their\nuse or exploitation;\nh)   Economic instability caused by severe crisis in the national economy;\ni)     Economic instability caused by acute poverty, mass unemployment or deep\nhorizontal inequalities;\nj)     Social instability caused by resistance to, or mass protests against, State\nauthority or policies;\nk)     Social instability caused by exclusion or tensions based on identity issues,\ntheir perception or extremist forms.","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0137-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":137,"section":"10. The guarantors of the 2000 Arusha Agreement, in their capacity as committed","text":"Risk factor 2. Record of serious violations of international human rights and\nhumanitarian law\na)     Past or present serious restrictions to or violations of international human\nrights and humanitarian law, particularly if assuming an early pattern of conduct and if\ntargeting protected groups, populations or individuals;\nb)     Past acts of genocide, crimes against humanity, war crimes or their\nincitement;\nc)      Policy or practice of impunity for or tolerance of serious violations of\ninternational human rights and humanitarian law, of atrocity crimes, or of their incitement;\nd)      Inaction, reluctance or refusal to use all possible means to stop planned,\npredictable or ongoing serious violations of international human rights and humanitarian\nlaw or likely atrocity crimes, or their incitement;\ne)     Continuation of support to groups accused of involvement in serious\nviolations of international human rights and humanitarian law, including atrocity crimes, or\nfailure to condemn their actions;\nf)     Justification, biased accounts or denial of serious violations of international\nhuman rights and humanitarian law or atrocity crimes;\n()    Politicization or absence of reconciliation or transitional justice processes\nfollowing conflict;\nh)     Widespread","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0138-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":138,"section":"10. The guarantors of the 2000 Arusha Agreement, in their capacity as committed","text":"Risk factor 3. Weakness of State structures\na)     National legal framework that does not offer ample and effective protection,\nincluding through ratification and domestication of relevant international human rights and\nhumanitarian law treaties;\nb)     National institutions, particularly judicial, law enforcement and human rights\ninstitutions that lack sufficient resources, adequate representation or training;\nc)     Lack of an independent and impartial judiciary;\nd)     Lack of effective civilian control of security forces;\ne)     High levels of corruption or poor governance;\nf)      Absence or inadequate external or internal mechanisms of oversight and\naccountability, including those where victims can seek recourse for their claims;\ng)      Lack of awareness of and training on international human rights and\nhumanitarian law to military forces, irregular forces and non-State armed groups, or other\nrelevant actors;\nh)      Lack of capacity to ensure that means and methods of warfare comply with\ninternational humanitarian law standards;\ni)      Lack of resources for reform or institution-building, including through\nregional or international support;\nj)     Insufficient resources to implement overall measures aimed at protecting\npopulations.","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0139-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":139,"section":"10. The guarantors of the 2000 Arusha Agreement, in their capacity as committed","text":"Risk factor 4. Motives or incentives\na)      Political motives, particularly those aimed at the attainment or consolidation\nof power;\nb)      Economic interests, including those based on the safeguard and well-being of\nelites or identity groups, or control over the distribution of resources;\nc)     Strategic or military interests, including those based on protection or seizure\nof territory and resources;","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0140-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":140,"section":"10. The guarantors of the 2000 Arusha Agreement, in their capacity as committed","text":"d)      Other interests, including those aimed at rendering an area homogeneous in\nits identity;\ne)      Real or perceived threats posed by protected groups, populations or\nindividuals against interests or objectives of perpetrators, including perceptions of\ndisloyalty to a cause;\nf)     Real or perceived membership of or support for armed opposition groups by\nprotected groups, populations or individuals;\ng)      Ideologies based on the supremacy of a certain identity or on extremist\nversions of identity;\nh)      Politicization of past grievances, tensions or impunity;\ni)     Social trauma caused by past incidents of violence not adequately addressed\nand that produced feelings of loss, displacement, injustice and a possible desire for revenge.","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0141-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":141,"section":"10. The guarantors of the 2000 Arusha Agreement, in their capacity as committed","text":"Risk factor 5. Capacity to commit atrocity crimes\na)     Availability of personnel and of arms and ammunition, or of the financial\nresources, public or private, for their procurement;\nb)    Capacity to transport and deploy personnel and to transport and distribute\narms and ammunition;\nc)      Capacity to encourage or recruit large numbers of supporters from\npopulations or groups, and availability of the means to mobilize them;\nd)      Strong culture of obedience to authority and group conformity;\ne)      Presence of or links with other armed forces or with non-State armed groups;\nf)     Presence of commercial actors or companies that can serve as enablers by\nproviding goods, services, or other forms of practical or technical support that help to\nsustain perpetrators;\ng)      Financial, political or other support of influential or wealthy national actors;\nh)     Armed, financial, logistic, training or other support of external actors,\nincluding States, international or regional organizations, private companies, or others.","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0142-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":142,"section":"10. The guarantors of the 2000 Arusha Agreement, in their capacity as committed","text":"Risk factor 6. Absence of mitigating factors\na)      Limited or lack of empowerment processes, resources, allies or other\nelements that could contribute to the ability of protected groups, populations or individuals\nto protect themselves;\nb)     Lack of a strong, organized and representative national civil society and of a\nfree, diverse and independent national media;\nc)     Lack of interest and focus of international civil society actors or of access to\ninternational media;\nd)     Lack of, or limited presence of, the United Nations, international non-\ngovernmental organizations or other international or regional actors in the country and with\naccess to populations;\ne)     Lack of membership and effective participation of the State in international\nor regional organizations that establish mandatory membership obligations;\nf)     Lack of exposure, openness or establishment of political or economic\nrelations with other States or organizations;\ng)    Limited cooperation of the State with international and regional human rights\nmechanisms;\nh)    Lack of incentives or willingness of parties to a conflict to engage in\ndialogue, make concessions and receive support from the international community;","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0143-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":143,"section":"10. The guarantors of the 2000 Arusha Agreement, in their capacity as committed","text":"i)     Lack of interest, reluctance or failure of States Members of the United\nNations or members of international or regional organizations to support a State to exercise\nits responsibility to protect populations from atrocity crimes, or to take action when the\nState manifestly fails that responsibility;\nj)     Lack of support by neighbouring States to protect populations at risk and in\nneed of refuge, including by closure of borders, forced repatriation or aid restriction;\nk)      Lack of an early warning mechanism relevant to the prevention of atrocity\ncrimes.","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0144-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":144,"section":"10. The guarantors of the 2000 Arusha Agreement, in their capacity as committed","text":"Risk factor 7. Enabling circumstances or preparatory action\na)     Imposition of emergency laws or extraordinary security measures that erode\nfundamental rights;\nb)     Suspension of or interference with vital State institutions, or measures that\nresult in changes in their composition or balance of power, particularly if this results in the\nexclusion or lack of representation of protected groups;\nc)     Strengthening of the security apparatus, its reorganization or mobilization\nagainst protected groups, populations or individuals;\nd)      Acquisition of large quantities of arms and ammunition or of other objects\nthat could be used to inflict harm;\ne)      Creation of, or increased support to, militia or paramilitary groups;\nf)     Imposition of strict control on the use of communication channels, or banning\naccess to them;\ng)      Expulsion or refusal to allow the presence of non-governmental\norganizations, international organizations, media or other relevant actors, or imposition of\nsevere restrictions on their services and movements;\nh)      Increased violations of the right to life, physical integrity, liberty or security\nof members of protected groups, populations or individuals, or recent adoption of measures\nor legislation that affect or deliberately discriminate against them;\ni)    Increased serious acts of violence against women and children, or creation of\nconditions that facilitate acts of sexual violence against those groups, including as a tool of\nterror;\nj)     Imposition of life-threatening living conditions or the deportation, seizure,\ncollection, segregation, evacuation or forced displacement or transfer of protected groups,\npopulations or individuals to camps, rural areas, ghettos or other assigned locations;\nk)    Destruction or plundering of essential goods or installations for protected\ngroups, populations or individuals, or of property related to cultural and religious identity;\nl)      Marking of people or their property based on affiliation to a group;\nm)      Increased politicization of identity, past events or motives to engage in\nviolence;\nn)     Increased inflammatory rhetoric, propaganda campaigns or hate speech\ntargeting protected groups, populations or individuals.","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0145-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":145,"section":"10. The guarantors of the 2000 Arusha Agreement, in their capacity as committed","text":"Risk factor 8. Triggering factors\na)      Sudden deployment of security forces or commencement of armed hostilities;\nb)      Spillover of armed conflicts or serious tensions in neighbouring countries;\nc)    Measures taken by the international community perceived as threatening to a\nState’s sovereignty;\nd)    Abrupt or irregular regime changes, transfers of power, or changes in\npolitical power of groups;","unnumbered":true,"annex":1},{"id":"a-hrc-42-49-u0146-a1","rec_id":"recyNfwUx22ay0eHy","symbol":"A/HRC/42/49","n":null,"seq":146,"section":"10. The guarantors of the 2000 Arusha Agreement, in their capacity as committed","text":"e)      Attacks against the life, physical integrity, liberty or security of leaders,\nprominent individuals or members of opposing groups; other serious acts of violence, such\nas terrorist attacks;\nf)      Religious events or real or perceived acts of religious intolerance or\ndisrespect, including outside national borders;\ng)    Acts of incitement or hate propaganda targeting particular groups or\nindividuals;\nh)      Census, elections, pivotal activities related to those processes, or measures\nthat destabilize them;\ni)     Sudden changes that affect the economy or the workforce, including as a\nresult of financial crises, natural disasters or epidemics;\nj)     Discovery of natural resources or launching of exploitation projects that have\na serious impact on the livelihoods and sustainability of groups or civilian populations;\nk)    Commemoration events of past crimes or of traumatic or historical episodes\nthat can exacerbate tensions between groups, including the glorification of perpetrators of\natrocities;\nl)   Acts related to accountability processes, particularly when perceived as\nunfair.","unnumbered":true,"annex":1},{"id":"a-hrc-42-crp-2-p0001","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":0,"section":null,"text":"Human Rights Council\nForty-second session\n9–27 September 2019\nAgenda item Point 4\nHuman rights situations that require the Council’s attention","unnumbered":true},{"id":"a-hrc-42-crp-2-p0002","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":1,"section":null,"text":"Detailed Final Report of the Commission of Inquiry on\nBurundi      *","unnumbered":true},{"id":"a-hrc-42-crp-2-p0003","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":2,"section":null,"text":"*\n* Original in French available at\nhttps://ohchr.org/Documents/HRBodies/HRCouncil/CoIBurundi/ReportHRC42/\nA_HRC_42_CRP2_EN.pdf","unnumbered":true},{"id":"a-hrc-42-crp-2-p0004","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":3,"section":"Annexes","text":"IV. Common risk factors indicators identified in the Framework of Analysis for Atrocity","unnumbered":true},{"id":"a-hrc-42-crp-2-p0005","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":4,"section":"Annexes","text":"** Available in this translated version","unnumbered":true},{"id":"a-hrc-42-crp-2-p0006","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":5,"section":"Annexes","text":"AMISOM            African Union Mission in Somalia\nACHPR             African Charter on Human and Peoples’ Rights\nAU                African Union\nCENI              Independent National Electoral Commission\nCNARED            Conseil national pour le respect de l’Accord d’Arusha et la\nrestauration d’un État de droit au Burundi\nCNC               National Communication Council\nCNL               Congrès national pour la liberté\nCNDD-FDD          Conseil national pour la défense de la démocratie-Forces de défense\nde la démocratie\nCNIDH             Independent National Commission for Human Rights\nCNS               National Security Council\nCVR               Truth and Reconciliation Commission\nDRC               Democratic Republic of the Congo\nEAC               East- African Community\nEU                European Union\nEx-FAB            former Burundian Armed Forces\nFDNB              National Defense Forces of Burundi\nFOREBU            Forces républicaines du Burundi\nFRODEBU           Front pour la démocratie au Burundi\nFNL               Forces nationales de libération\nMSD               Mouvement pour la solidarité et le développement\nNGO               Non-Governmental Organisation\nOHCHR             Office of the United Nations High-Commissioner for human rights\nPARCEM            Parole et action pour le réveil des consciences et l’évolution des\nmentalités\nPNB               Burundian National Police\nRED-Tabara        Résistance pour un État de droit – Tabara\nRTNB              National Radio Television of Burundi\nSNR               National Intelligence Service\nUNHCR             Office of the United Nations High-Commissioner for Refugees\nUPD-Zigamibanga Union pour la paix et le développement-Zigamibanga\nUPRONA            Union pour le progrès national","unnumbered":true},{"id":"a-hrc-42-crp-2-p0007","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":6,"section":"I. Introduction","text":"1.      This report is the detailed version of the report A/HRC/42/49, presented at the forty-\nsecond session of the Human Rights Council pursuant to resolution 39/14, adopted on 28\nSeptember 2018. It should be read in continuation of the two previous reports A/HRC/36/54\nand A/HRC/39/63 that the Commission presented respectively during the thirty-six and\nthirty-nine sessions of the Human Rights Council, as well as the accompanying detailed\nreports A/HRC/36/CRP.1 and A/HRC/39/CRP.1.\n[…]","unnumbered":true},{"id":"a-hrc-42-crp-2-p0008","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":7,"section":"II. Human Rights Situation","text":"54.     As in the previous reports, the information presented in this section is directly taken\nfrom the investigations conducted by the Commission since the extension of its mandate in\nSeptember 2018. It mainly covers the violations and abuses perpetrated between May 2018\nand the publication date of this report. 87 The combined reading of the Commission’s three\nreports provides an overall view of the human rights situation in Burundi since April 2015\nand its evolution, especially concerning the operational methods, the profiles of the victims\nand the main perpetrators.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0009","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":8,"section":"A. Main trends since June 2018","text":"55.     The main human rights violations continue to have a political dimension and several\nwere perpetrated in the wake of the May 2018 constitutional referendum or in the context of\nthe preparation of the 2020 elections. With regards to civil and political rights, these\nviolations concern the right to life, the right to liberty and security, the right not to be\nsubjected to torture and ill-treatment, as well as cases of sexual violence and violations of the\nmain civil liberties.\n56.      For the most part, the victims continue to be targeted for their support or their\naffiliation, alleged or actual, to a party other than the ruling party (le Conseil national pour\nla défense de la démocratie-Forces pour la défense de la démocratie – CNDD-FDD),\nincluding in relation to certain activities carried out by other political parties such as the\ncampaign for a ” no ” vote during the constitutional referendum. Since the accreditation of\nthe Congrès national pour la liberté (CNL) on 14 February 2019, with Agathon Rwasa as\npresident, its members have been subjected to various violations of their civil and political\nrights.\n57.    Young men, accused of supporting or belonging to armed opposition groups, often\nfollowing a trip or stay abroad, or in relation to their involvement, actual or alleged, in the\nprotest against President Nkurunziza’s third term or in the 2015 security incidents, have\ncontinued to be specifically targeted.\n58.    Persons with no political affiliation or activities have also been targeted for refusing\nto join CNDD-FDD or its youth league, Imbonerakure, including in instances when their\nreligious convictions prevented them from taking part in political affairs.\n59.    Similarly, persons suspected of not wanting to tow the Government line and that of\nCNDD-FDD with regards to the constitutional referendum, namely to vote in favour of the\nconstitutional review, have also been targeted; as well as those who did not pay the mandatory\nfinancial contributions, mainly for the funding of the 2020 elections, even if this was due to\nlack of resources.\n60.     Family members and relatives of targeted persons have also been victims of\nviolations, often deliberately, but at times accidentally or for opportunistic reasons,\nspecifically in cases of sexual violence against women and girls during nocturnal attacks on\ntheir home.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0010","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":9,"section":"A. Main trends since June 2018","text":"87\nThe Commission has extended the period for the violations of the right to life and cases of sexual\nviolence – which are the most difficult to document – to include those committed since 1 January 2018.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0011","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":10,"section":"A. Main trends since June 2018","text":"61.    Burundian nationals who had fled abroad and returned home under the assistance\nprogramme for repatriation since the beginning of 2017 were also targeted. More generally,\nseveral of them, once they arrived in their colline of origin faced widespread suspicion; at\ntimes real hostility from the local administrative authorities and Imbonerakure. A witness\nwho had returned to Burundi after some time in exile, said:\n“Since our return, we live in insecurity. […] an official at the colline level […] called\na meeting to tell people to remain vigilant. […] Such meeting was organised every\nweek […] the request to remain vigilant is especially directed at authorities and\nImbonerakure who must keep an eye on those who are returning. [This local offiical]\nsaid: ‘the traitors who are returning, we must follow them because we do not know\nwhat brings them back to the country’. […] As part from this call to vigilance, we had\nto identify ourselves and explain why we came back but because of such identification\nwe became targets for Imbonerakure, whom we had to pay because they had stayed\nbehind to build the country”.88\n62.    Several violations occurred in rural areas, in zones and collines, which are patrolled\nby the Imbonerakure who are working to control the whole population, particularly at the\ngrassroots level, and compel their allegiance to CNDD-FDD. These efforts target primarily\npoor people, mostly farmers with limited means and formal education, whereas at the\nbeginning of the crisis the repression was especially directed at political leaders, civil society\nrepresentatives, including human rights activists, and students, who for the most part, resided\nin Bujumbura. However, human rights defenders remain targets as demonstrated by the\nconfirmation on appeal, on 17 July 2019, of the 32-year prison sentence imposed on Germain\nRukuki.\n63.     Violations can take multiple forms and are often cumulative and inflicted to the\nsame household: summary executions, disappearances, including forced disappearances,\narbitrary arrest and detention, torture and ill treatment, as well as sexual violence.\n64.     Imbonerakure, agents of the National Intelligence Service (SNR) and the police as\nwell administrative officials in the communes, zones and collines, have been identified as the\nmain perpetrators of the violations documented by the Commission during the current term\nof its mandate.\n65.     The victims and the witnesses often recognized the Imbonerakure who committed\nthe violations since they lived in the same commune, zone or colline, and they were known\nas members of the CNDD-FDD youth league. In other cases, they identified the\nImbonerakure by their distinctive clothing, which notably included parts of police or military\nuniforms or accessories, and they generally had sticks and clubs. A victim of sexual violence\ntestified:\n“I knew two of the four […] because they lived close to home. One went by the\nname of [X] and the other [Y]. The two that I knew were Imbonerakure. They were\noften with the chef de zone”.89\n66.    Human rights violations have continued to be committed in a climate of widespread\nimpunity, enabled by the dyfunctions of the judicial system, 90 as well as the victims’ fear of\nreprisals or their general reluctance to submit complaints due to a lack of confidence in the\nJudiciary.\n67.     This situation as well as the fact that these violations were mainly committed by the\nImbonerakure in rural areas, makes it more complicated to corroborate the numerous\nallegations of violations received.\n68.    The violations of civil liberties, which were numerous and regular at the beginning\nof the crisis and have persisted since then, have been on the rise since 2019, and they\ncontribute to the acceleratied shrinking of democratic space, which is very concerning on the\neve of the 2020 elections. In fact, the violations of the rights pertaining to the freedom of\nexpression, opinion, information, association and assembly, as well as the rights to the","unnumbered":true},{"id":"a-hrc-42-crp-2-p0012","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":11,"section":"A. Main trends since June 2018","text":"freedom of movement and religion, have been numerous and some are directly linked to the\nlaws governing different areas that were recently adopted.\n69.     The violations of social and economic rights affect the entire Burundian population,\nspecifically in its right to an adequtate standard of living. However, the Commission noted\nthat Burundian authorities and the ruling party did not hesitate to use the enjoyment of some\nsocial and economic rights as a tool for political gains, particularly the right to work, health\nand education by subjecting it to a prerequisite such as membership to CNDD-FDD and/or\nImbonerakure, or the payment of various contributions.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0013","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":12,"section":"B. Responsibilities","text":"1.   Responsibility of the Burundian State\n70.     As in the past,91 the Commission is in a position to conclude that under international\nlaw, the Burundian State can be held accountable for the acts and sortcomings identified in\nthis report, which therefore constitute human rights violations.\n71.      State agents, particularly from the National Intelligence Service and the police, 92 but\nalso administrative officials that represent the State in the provinces, communes, zones and\ncollines, and to a lesser extent the defence forces, were the perpetrators of numerous\nviolations documented by the Commission. Their actions are directly attributable to the\nStateof Burundi , pursuant to its obligation to respect human rights and therefore to ensure\nthat its agents refrain from breaching the rights of individuals under the State jurisdiction.\n72.     Imbonerakure are the main perpetrators of the violations documented in this report.\nThey often act alone or sometimes in the presence of representatives of law enforcement\nofficials. They enjoy a considerable freedom of action that is granted to them by the\nBurundian authorities, since these authorities have the means to control effectively the\nImbonerakure should they choose to do so. The Imbonerakure also enjoy near total impunity.\nImbonerakure are still regularly – indeed, almost routinely – used to supplement or replace\nthe security forces, particularly in rural areas, at the request or with the consent of members,\nincluding senior officials, of the National Intelligence Service, the police, the Office of the\nPresident and local authorities. Some have military material and equipment reserved in\nprinciple for the defence and security forces, such as items of military uniform, 93 and\naccessories such as military headgear and boots,94 which attest to their central role within the\nformal and informal security structures of the Burundian State. When the conduct of the\nImbonerakure is acknowledged and adopted by agents of the State, 95 when they act on the\ninstructions of such agents96 or when they act in “complete dependence” on or under the\n“effective control” of such agents,97 the Burundian State is directly responsible for their\nactions, still in virtue of its obligation to respect human rights.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0014","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":13,"section":"B. Responsibilities","text":"73.    In the rare cases in which Imbonerakure reportedly acted outside these scenarios, the\ngeneral impunity they enjoy following their acts also means that the responsibility of the\nBurundian State is engaged, in conformity with its obligation to protect human rights. Indeed,\nthe State must, when it is aware or should have been aware of violations or abuses committed\nby third parties, undertake effective investigations and prosecutions, which has not generally\nbeen the case.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0015","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":14,"section":"B. Responsibilities","text":"2.   Responsibility of armed groups and opposition political parties\n74.     The Commission reiterated its requests to the Burundian Government for relevant\ninformation on incidents in which the involvement or the responsibility of armed opposition\ngroups were suspected. The Government has persisted in its refusal to cooperate with the\nCommission. Consequently, and due to lack of access to victims and the repeated refusal of\nthe Government to provide information, the Commission was not in a position to corroborate\nallegations received on the involvement of armed groups in human rights abuses. The lack of\naccess to the victims of these abuses is not due to the impossibility of the Commission to\naccess the Burundian territory, but rather to the fact that the victims are mostly people who\nare close to the authorities or hold functions within the State apparatus or within CNDD-\nFDD. Given the categorical refusal of the Government to cooperate with the Commission,\nthese victims do not seek to contact or to share information with the latter.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0016","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":15,"section":"C. Violations of civil and political rights","text":"a)   Freedom of expression and information\n213. As per the past,98 most of the human rights violations committed since 2018 happened\nin a general context of indoctrination and control of the population aimed at silencing the\nopponents and suppressing any dissenting voice in relation to the policies and political line\nof the Government and CNDD-FDD.99 Consequently, almost all these violations can be\nanalysed from the perspective of freedom of expression. However, in order to avoid\nrepetition, this section will focus on the violations of the freedom of expression that targeted\nthe media and journalists, as well as those that took the shape of hate speech and incitement\nto violence.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0017","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":16,"section":"C. Violations of civil and political rights","text":"(i)    Control and censure of independent media\n214. According to the Burundian Senate: “Burundi has a good tradition of respecting the\nfreedom of expression and a very active civil society. Therefore, more than 20 public and\nprivate local radios, 5 community radios, 10 radio-television stations, 17 local news and\ncommunication agencies, 24 public and private periodicals, 26 internet sites, 8 web TV\nstations, 4 magazines and 12 professional press associations and bodies are operational. In\naddition to the local private radio stations, 4 foreign radio stations are authorised to broadcast\nfreely in Burundi. In short, the total number of medias increased from 94 in 2015 to 122 in\n2018, which translates to a substantial increase of 28 media entities in 3 years”. 100 However,\nthese numbers do not reflect independence of the media nor their capacity to work freely in\nsearching and disseminating information, since the media are subject to real censure which\nled to the suspension and the closing of several independent radio stations.\n215. Since the beginning of the 2015 crisis, private and independent medias have\nregularly been closed or suspended, and the few that stayed active are subject to excessive","unnumbered":true},{"id":"a-hrc-42-crp-2-p0018","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":17,"section":"C. Violations of civil and political rights","text":"controls and restrictions by the authorities. Journalists have been subjected to pressure,\nthreats and violence, some have also been victims of arbitrary arrest and detention and\nenforced disappearance, and many of them have been forced into exile.101 In July 2019, in an\neffort to increase the control on media, the Head of State appointed Brigadier General\nEmmanuel Miburo, President of the Board of Administration of the Burundian National\nRadio and Television (RTNB) ; Eric Nshimirimana, former head of Imbonerakure, as the\nRTNB Director-General and Secretary of its Board of Administration; and OPC1 Alfred\nInnocent Museremu, who had been appointed as the SNR security advisor on 29 December\n2017, was appointed as a simple member of the RTNB Board of Administration.102\n216. The violations of the right to freedom of information, an essential component of the\nright to freedom of expression, have therefore persisted in Burundi. Since 2018, Burundi is\nranked 159th out of 188 countries in the global press freedom index released every year by\nReporters without Borders.103","unnumbered":true},{"id":"a-hrc-42-crp-2-p0019","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":18,"section":"C. Violations of civil and political rights","text":"-   New law on the Press\n217. The controls and restrictions imposed on media are aggravated with the new law on\nthe press no. 1/19 regulating the media, which was promulgated on 14 September 2018104, in\norder to replace law no. 1/15 of 9 May 2015. The new law has provisions on the acquisition\nof the press card which limits access to the profession of journalism. It imposes strict\nconditions on the required level of education to obtain a press card, namely “at least a diploma\nat the baccalaureate level, issued by a school or a training institute in journalism; legally\nrecognised with at least six months of practical professional experience in the media\nindustry”.105 It shall be recalled that there are no specialised schools or training in journalism\nin Burundi. Holders of a diploma at the baccalaureate level combined with a certified training\nin a media entity or with three years of professional experience can also be recognised as\nprofessional journalists.106 In comparison, the 2015 law provided that journalists must have a\ndiploma equivalent to a baccalaureate and a two-year professional training or experience. 107\n218. With regards to publication and dissemination of information, the 2018 law imposes\nan outcome to journalists, who must only “publish balanced information […] whose source,\norigin, veracity and accuracy must be established and carefully verified”,108 with no reference\nto the ethics or professional conduct of journalism109. The obligation to present “balanced”\ninformation is an extremely vague notion for which there is no definition nor precise criteria,\nand which is not recognised by international standards established by the profession. 110 It is","unnumbered":true},{"id":"a-hrc-42-crp-2-p0020","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":19,"section":"C. Violations of civil and political rights","text":"precisely this legal provision that the Burundian authorities have regularly used in an abusive\nmanner to sanction the last independent media.111\n219. The new law on the Press does not mention the “right of passage” which was until\nnow given to press card holders in all the “places they are called to fulfil their mission to\ninform; notably access to areas reserved for the press, in stadiums, at airports and in\ncourtrooms and generally to cover all official or public activities”.112\n220. The scope of application of the 2018 law covers all press houses, audio-visual and\ncommunication companies, all media including web based media as well as cinematographic\ncompanies present in Burundi even if their headquarters are outside the country. 113 The law\nalso stipulates that “no foreign newspaper or written periodicals can be created, published or\nprinted without obtaining prior authorisation from the National Communication Council after\nsubmitting a written request”.114 Similarly, any film broadcast on the Burundian territory is\nhenceforth “subject to prior authorisation by the National Communication Council”. 115 In\nfact, during the session before the Senate in August 2019 to consider this draft law,\ndiscussions were held on the necessity “to put in place a policy to protect the country against\nprograms that are contrary to the Burundian culture but also against information provided by\nradio stations such as Humura and Inzamba that are not recognised by the Burundian\nlegislation”.116","unnumbered":true},{"id":"a-hrc-42-crp-2-p0021","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":20,"section":"C. Violations of civil and political rights","text":"Media censure by the National Communication Council\n221. The National Communication Council (CNC), which is supposed to be an\nindependent regulatory body for media, is in fact a censorship tool for the Government as its\nrole is to control the media and the press and it has the capacity to impose heavy sanctions;\nsuch as suspension or license withdrawal against any media that has broadcasted any\n“unbalanced” information, namely information that does not espouse the Government line or\nthat is perceived to be criticising the latter, notably the mention of human rights violations\ncommitted in Burundi.117\n222. On 29 March 2019, CNC withdrew the licence of the British Broadcasting\nCorporation (BBC)118 radio as a sanction for broadcasting the documentary Kamwe Kamwe,\nwhich revealed the existence of secret detention places throughout the country where illegally\ndetained people had allegedly been tortured and then executed by SNR members. According\nto CNC, this documentary was “untruthful, defamatory and scathing for Burundi”. The\ndecision to revoke the licence of BBC followed its 6 months suspension from 4 May 2018\nafter the broadcasting of the program Guest of the Week with Pierre-Claver Mbonimpa;\nwhich according to CNC had not respected the principles of balanced information and the\nrigorous verification of sources.119 This suspension was itself preceded by a warning\nfollowing the broadcasting of a documentary on the decision of the central committee of\nCNDD-FDD to award the title of “Visionary” to President Nkurunziza.120\n223. On the same day, CNC also decided to suspend radio Voice of America (VOA) for\nan indefinite duration after having suspended it for 6 months from May 2018. The decision\nwas justified by the fact that VOA had continued to employ a Burundian journalist; former\ndirector of the radio station Bonesha FM; who is officially wanted by the Burundian justice","unnumbered":true},{"id":"a-hrc-42-crp-2-p0022","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":21,"section":"C. Violations of civil and political rights","text":"for his alleged participation “in the murderous violence that preceded the failed coup d’état\nof 13 May 2015”. 121\n224. According to the two decisions of CNC, it is henceforth “strictly forbidden to any\njournalist, Burundian or of foreign nationality, operating on the national territory of Burundi,\nto provide directly or indirectly any information that can be broadcasted on VOA or BBC”.122\n225. In June 2019, during a press conference, the President of CNC, Nestor\nBankumukunzi, advised that he was going to sanction the broadcasting on 2 June 2019 by\nRadio France Internationale (RFI) of an interview of a human rights activist, Marguerite\nBarankitse, in which she denounced the human rights situation in the country and the\nresponsibility of the Head of State in that regard. According to CNC, her statements were\ninjurious to President Nkurunziza.123\n226. On 10 July 2019, the President of CNC announced that a warning would be “issued\nto Journal Iwacu following the failings of the latter media in order to ensure that it complies\nwith the law instead of persisting in its failures and remaining insensitive to the advice\nprovided by CNC”.124 However, no concrete details or examples were provided on the so\ncalled failures of the Journal; one of the last independent newspaper still active in the country\ndespite the exile of its director. Iwacu had already been sanctioned in April 2018 for having\nturned a blind eye to a comment of a reader “defaming” the Burundian national police by\nqualifying it as the “Presidential police”, as well as another comment qualifying the Republic\nof Burundi as a “Banana Republic with no education”. These facts had even been considered\nby CNC as constituting violations of the Constitution, and Iwacu had to close its comments\npage for 3 months.125\n227. Finally, on 6 July 2019, in view of the 2020 elections, CNC established a hotline\nwhere Burundians can send “messages evaluating the service of different radio and television\nstations working in Burundi […] focusing on aspects that can be improved […] in order to\ncontribute to the strengthening of a free, professional and responsible press”.126\n228. CNC is not an independent body as demonstrated by the clumsiness that\ncharacterised the nomination decree for its members in May 2019. The original presidential\ndecree n°100/073 of 15 May 2019 appointing the 15 new CNC members, already had the\nnames of the five members that makeup its Bureau, whereas according to the law n°1/06 of\n8 March 2018 on the missions, composition, organisation and functioning of CNC, the latter\nmust be nominated internally by its own members. The authorities tried to rectify this blunder\nby publishing a new decree under the same code n°100/073, but dated 21 May 2019, without\nmentioning the members of its Bureau.127 The President of CNC, Nestor Bankumukunzi, was\nthe one who had been initially nominated by the Head of State. Among the new members\nof CNC was the spokesperson of the Burundian police, Pierre Nkurikiye. In addition, the\nbudget of CNC is incorporated in the budget of the Office of the President. Therefore, this\nCouncil has no financial autonomy outside of the Executive.\n229. The suspicion and hostility of the representatives of the Government and the ruling\nparty CNDD-FDD towards independent media is increasingly explicit. For example, during\na public meeting with registered political parties, civil society and religious confessions and","unnumbered":true},{"id":"a-hrc-42-crp-2-p0023","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":22,"section":"C. Violations of civil and political rights","text":"in the presence of several journalists, Anastase Hicuburundi, one of the members of the\nNational Independent Electoral Commission (CENI), a member of CNDD-FDD, who is the\ncommissioner responsible for electoral operations and settlements, accused the media “of\nhaving resumed their destabilisation efforts a year ahead of the general elections scheduled\nin 2020” because they mentioned human rights violations and namely; cases of arrest and\ndetention of CNL members. He even went as far as requesting “CNC to block the road to\nthese media who refused to tow the Government line”.128\n230. The restrictions to freedom of expression and information also impact statistics and\ndata presented by international organisations which are rejected by authorities because they\ncontradict the official position on economic development or peace and security throughout\nthe country.129 For example, in February 2019, the organisation PARCEM launched a\ncampaign Ukuri ku biduhanze (truth on the challenges that haunt the country) in order to\nidentify the difficulties that Burundi faces in terms of malnutrition, poverty, epidemics or\ninflation with the objective of contributing “to reducing the manipulative speeches of some\npolitical personalities who have run out of ideas especially as the 2020 elections\napproach”.130 The organisation PARCEM used statistics from the Institute of statistics and\neconomic studies of Burundi and those of international organization such as The World Bank\nand the World Health Organization. However, the Government accused PARCEM of\n“tarnishing the image of the country” and of “threatening peace and stability” with this\ncampaign which presents data that contradict the official rhetoric and decided to suspend this\norganisation indefinitely.131","unnumbered":true},{"id":"a-hrc-42-crp-2-p0024","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":23,"section":"C. Violations of civil and political rights","text":"(ii)   Control of and restrictions to the work of journalists.\n231. As in previous years,132 independent journalists still present in Burundi continue to\nexercise their profession in a difficult ; and sometimes openly hostile ; environment and have\nbeen subject to pressure, threats and obstacles aimed at stopping them from carrying out their\ninvestigation work; namely on incidents that are political in nature, but also on daily life\nsituations and suspicions of corruption.133 Many of these interferences were done by\nauthorities, including at the local level, who did not hesitate to call security forces to arrest\njournalists or have threatened to do so. Some journalists opted to abandon investigations\njudged as too sensitive; for fear of what would happen to them.134\n232. In practice, journalists have difficulties moving around the country; their movements\nin provinces were monitored or controlled. Some were prevented from going to or prevented\nfrom carrying their investigative work in rural communes or collines by local administrative\nauthorities. Others had to ask permission from the provincial Governor in order to be able to\ngo to a given location.135 These obstacles are direct violations of the right to the freedom of\nmovement136 and to the principle of “free passage” of journalists, essential to guarantee the\nfreedom of information.\n233. The independent journalists face a climate of mistrust and open hostility from the\nauthorities.137 For example, in May 2019, a RTNB journalist, Claude Nshimirimana, was\narbitrarily arrested and temporarily detained for having been accused of participating in an\n“illegal meeting”.138 Some journalists have been accused of communicating information to","unnumbered":true},{"id":"a-hrc-42-crp-2-p0025","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":24,"section":"C. Violations of civil and political rights","text":"international or independent media including the BBC and VOA, which is prohibited by\nCNC.139 Statements from a local administrative authority reported by a direct witness\nperfectly reflect their attitude towards independent journalists:\n“These journalists are disruptors of public order”.140\n234. In such a context any contact with independent journalists can be a source of\nproblems for anyone.141 In that regard, the statement of the local administrative authority is\neloquent:\n“The source […] will be arrested for interrogation. [They] were accused of having\nspoken to the journalists”.142\n235. The situation is such that, for fear of reprisal, some journalists exercise self-\ncensorship, feel compelled to leave the country or are constrained to work anonymously for\ntheir protection. A witness explained:\n“We found dead bodies that were tied up […]. [The journalists] did not dare to report\nit. Before 2015, this would have been frontpage news”.143","unnumbered":true},{"id":"a-hrc-42-crp-2-p0026","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":25,"section":"C. Violations of civil and political rights","text":"(iii)   Hate speech and incitement to violence\n236. The Government has equated any statement from the media, NGOs and\nrepresentatives of international organisations which differs from its official rhetoric on the\npolitical security and socio-economic situation of the country to a destabilisation attempt or\nan attack on its national sovereignty and it generally reacted quickly in order to condemn or\ndenounce the authors.144 Conversely and as per the past; statements, songs and public\ndeclarations which incite intolerance and violence against any political formation other than\nCNDD-FDD; which were recently proffered; notably by local authorities and Imbonerakure,\ndid not elicit any reaction from the authorities.145\n237. For example, on 17 April 2019, during a public meeting in Gasorwe commune led\nby the provincial Governor, a police commissioner in Muyinga province threatened to\neliminate CNL political opponents, as well as members of their family if they held\nclandestine meetings in their homes:146\n“Your Excellency, Mr. Governor, dear fellow citizens, I am now talking to people who\norganise nocturnal meetings. Whomever organises meetings at night. If you make the\nmistake of organising this meeting at your house and we get to know, you will be\nputting your family in danger. In addition, everyone knows that if you lock yourself in\nyour house at 23:00 to hold clandestine meetings, me as the provincial commissioner,\nI no longer wish to be bothered. If you want to disrupt security […] I have with me\nwhat is required to solve that problem. I throw in two and I go on my way. Two\n[grenades] are enough. In fact, even two are too much. Do not expect that the\nprovincial commissioner sends in a police officer [to make an arrest] during a\nclandestine meeting in a house. You spend a night there and we arrest you in the\nmorning? That is in the past. If you want to disrupt security, we will settle it with you\non the spot. Whether you are with your children, your wife; they will all perish [with\nyou]. […] Your Excellency, Mr. Governor, I take responsibility for these words, let\nno one come looking for explanations later [should something happen]. Let the\npopulation in your province and the administrators take note, I am talking to them”.147","unnumbered":true},{"id":"a-hrc-42-crp-2-p0027","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":26,"section":"C. Violations of civil and political rights","text":"238. On 17 August 2019, during the “show of force” demonstrations, organised in Karuzi\ncommune, Karuzi province, to celebrate the “official day for the youth league of the party\nCNDD-FDD, called Imbonerakure day”, members of this league paraded while singing\ndeath threats to opponents of the party CNDD-FDD, qualified as “small recalcitrant men”\nand indicating that “one of these days we will cleanse them”.148\n239. Several other videos circulated on social media in which groups of children or\nImbonerakure chanted songs containing threats to burn or eliminate anyone who would dare\noppose the party in power namely in the context of the 2020 elections with several mentions\nthat the party CNDD-FDD, symbolised by the eagle, will never leave power. 149 The\nCommission was unable to authenticate the place, the date or the circumstances in which\nthese videos were recorded but is concerned that such videos regularly and largely circulated\nin the country without any condemnation or denouncement of these utterances by the\nBurundian authorities who are usually prompt to do so for critical statements against them.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0028","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":27,"section":"C. Violations of civil and political rights","text":"b)   Freedom of Association\n240. In its previous report,150 the Commission mentioned that violations of the freedom of\nassociation mainly affected organisations active in the area of human rights who had seen\ntheir work hindered; namely through arbitrary detentions and arrests of their members or\nemployees. The problematic legal framework that regulates national and international non-\nGovernmental organisations since 2017 has been fully implemented by the Burundian\nauthorities; which resulted in the increase of the Government control on these organisations\nand has given rise to violations of the freedom of association.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0029","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":28,"section":"C. Violations of civil and political rights","text":"(i)    Control of non-governmental organisations","unnumbered":true},{"id":"a-hrc-42-crp-2-p0030","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":29,"section":"C. Violations of civil and political rights","text":"-   National NGOs\n241. National NGOs regulated by the 2017 law on national non-profit organisations\n(ASBL)151 are subjected to the control of their activities by the ministry overseeing their\nactivities and the latter must approve each of their activities. This law provides the Minister\nof Interior with broad authority to suspend national NGO based on vague motives of\n“disruptions of public order” or “undermining the internal security of the State”. Their\nresources are also controlled by the Government since foreign funds must transit by the\nCentral Bank of Burundi and be accompanied by a document indicating their origin and their\npurpose.152\n242. For example, the Minister of Youth, Posts and Information Technology asked the\nRotaract Club to suspend an international conference on peace in Burundi, scheduled for 22\nto 24 May 2019 in Bujumbura, for “lack of collaboration with the ministry team”. The\nMinister took the opportunity to remind all that “all youth related activities or requiring the\ninvolvement of youth must necessarily obtain approval from the ministry”.153\n243. On 3 June 2019, the organisation Parole et Action pour le Réveil des Consciences et\nÉvolution des Mentalités (PARCEM) was suspended for an indefinite period confirmed by\nthe Minister of Interior because it had presented a critical report on the dire socioeconomic\nconditions in the country based on World Bank data and statistics that had been rejected by\nthe Government.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0031","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":30,"section":"C. Violations of civil and political rights","text":"-   Foreign NGOs\n244. The Government control on the composition and the activities of foreign non-\ngovernmental organisations increased in 2018 with the effective implementation of some","unnumbered":true},{"id":"a-hrc-42-crp-2-p0032","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":31,"section":"C. Violations of civil and political rights","text":"provisions of the 2017 law on foreign NGOs154 and the adoption of additional laws. The\nofficial purpose of the 2017 law is to ensure a better coordination of the assistance from\nforeign NGOs to Burundi; however, some provisions allow Burundian authorities to control\nclosely their activities and to seize part of their resources. The Minister of Foreign Affairs\nrecently recalled that the 2017 law was necessary because “it appears that, in fact, an\nimportant part of the assistance goes through NGOs and a large part is allocated to their\noperations to the detriment of development activities. The different fora held on the\nefficiency of assistance unanimously recognised that to be efficient: assistance must integrate\nthe administrative and financial networks of the beneficiary countries. This is only possible\nif the Government obtains regular and verified reports on the nature and the scope of NGO\ninterventions for a better coordination of these interventions”. 155 Indeed, since 14 March\n2016, the European Union had decided to suspend all direct financial support to the\nBurundian Government and redirected its funding to civil society organisations only. The\n2017 law which requires foreign NGOs to transfer a third of their annual budget to an account\nwith the Central Bank of Burundi offers an opportunity to the Burundian authorities to access\nforeign currency, even if it is only via the effects of official exchange rate.\n245. Initially, some provisions of the 2017 law were not respected and the National\nSecurity Council, though only a consultative body of the Government in security matters,\ndecided to suspend all activities of foreign NGOs for three months from 1 October 2018, in\norder to force them to re-register and seek a new agreement. The Minister of Interior\nexplained that in order to continue to work, foreign NGOs had to have four documents: the\nagreement with the Foreign Affairs ministry, an implementation protocol for the program\ndepending on their intervention area as well as an act in which the NGO commits to respect\nthe national development programme (2018-2027), and another in which it commits to\nrespect the banking regulation on currency exchange. Finally, he indicated that foreign NGOs\nmust follow a progressive plan over three years in order to correct the ethnic and gender\ninequalities.156\n246. In fact, the 2017 law requires foreign NGOs to provide a list of their employees to\nthe authorities indicating their ethnicity so that they can check that the quotas of 60 % Hutus\nand 40 % Tutsis are respected as well as a minimum of 30 % of women. While the ethnic\nquotas were indeed provided for in the Arusha Peace Agreement and the 2005 Burundian\nConstitution, they are only applicable to the executive and legislative powers as well as the\nsecurity forces, in order to establish a “consociational” democracy 157. The Constitution\npromulgated in 2018 has added quotas within the judicial system; but has no provisions for\nsuch quotas in the private sectors, such as international NGOs or private companies. Some\nforeign NGOs publicly announced their decision to leave the country rather than being\nsubjected to requirements of keeping a record of their employees’ ethnic group, which they\nconsidered to be against their values. These are namely; Handicap International Humanité\n& Inclusion, Avocats Sans Frontières and RCN Justice & Démocratie.\n247. On 17 July 2019, during the Council of Ministers, the Government adopted a decree\npresented by the Minister of Foreign Affairs on the “organisation, composition and\nfunctioning of the recruitment committees of local staff by foreign non-Governmental\norganisations in Burundi”. This decree established a procedural framework for the\nrecruitment of local staff by foreign NGOs, and notably the necessary approaches to take into\naccount the ethnic and gender aspects imposed by the 2017 law. The stated objective was to\n“correct the observed imbalances and contribute to the social cohesion”, and “is consistent\nwith the Government policies and practices that the NGO are called to support”.158 Sanctions","unnumbered":true},{"id":"a-hrc-42-crp-2-p0033","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":32,"section":"C. Violations of civil and political rights","text":"are planned for any failure to respect these provisions, including against candidates who\nwould have lied about their identity or their ethnicity, or against members of the recruitment\ncommittees who fail in their obligations. A second decree on the “creation, composition,\nmission and functioning of a monitoring and evaluation interministerial committee of foreign\nnon-Governmental organisations in Burundi” was also adopted during this council, which\nallows for increased Government control of the activities of foreign NGOs, officially in order\nto ensure a better coordination of the assistance provided by foreign NGOs.159\n248. On 25 June 2019, the Minister of Human Rights, Social Affairs and Gender, Martin\nNivyabandi, convened a meeting in Bujumbura of UN organisations, foreign and national\nNGOs and explained that according to him “the level and quality of interventions by these\norganisations was not very satisfactory and should be improved”, as there is “a field\ncoordination problem on the field where one finds several partners with the same objective,\nsometimes providing assistance to the same beneficiaries, which then leads to […] a waste\nof resources and a lack of efficiency in terms of information”. In addition, “planning […] is\nnot coordinated with the concerned ministry”, and the Minister asked the partners of his\nministry “to harmonise their plans and those of the national development plan”. He “insisted\non the production of reports. He reminded the representatives of the organisations present in\nthat meeting that the partners engaged to support the country in a given area must provide a\nreport to the concerned ministry”.160\n249. The NGOs, national and foreign, are simply denied the right to organise freely and\nto determine their activities and objectives as well as the means to do so; and yet these are\nintegral parts of their right to the freedom of association.161 On the contrary, the Government\nof Burundi considers that these NGOs are “under its tutelage” and that they are only allowed\nto work to support and complement the Government policies and can therefore only\nundertake activities that are approved by and convenient to the Government. 162 In fact, it\nseems that there is some confusion amongst Burundian authorities on the role and the raison\nd’être of foreign NGOs and the difference between the latter and international organisations.\nDuring a meeting between the Head of State and provincial governors held on 7 August 2019,\ninternational organisations including the United Nations High Commissionne for Refugees\nand the Internal Organisation for Migrations were accused of not respecting the law on\nforeign NGOs,163 when these are UN agencies that are clearly not regulated by this piece of\nlegislation. In addition, the Commission received a witness account alleging that national\nNGOs are now required to alert local authorities of their visits in provinces, and once in those\nprovinces, Imbonerakure controlled their activities.164\n250. It is in that perspective that for several years, the Government supported the creation\nof an alternative civil society qualified as “citizen”, made up of local NGOs which are openly\nin favour of the Government and who echo official Government positions and adopt the\nGovernment language.\n251. For example, the Integral Burundian Platform for the Efficiency of Development\nAssistance (PISC-Burundi) was created in 2011 and since its creation, it has criticised the\nBurundian civil society that deals with human rights issues, namely the Ligue ITEKA,\nFORSC, APRODH and OLUCOME. It accused them of being politicised and in favour of\nthe opposition, of tarnishing the image of the country and of grabbing all the international\nfunding without necessarily contributing to the development of the country.165\n252. In July 2017, PISC-Burundi and the Collective of the Associations of People\nInfected and Affected by HIV/AIDS (CAPES+) welcomed the improvement of the human\nrights situation in Burundi and the visible commitment of security forces and the judicial in","unnumbered":true},{"id":"a-hrc-42-crp-2-p0034","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":33,"section":"C. Violations of civil and political rights","text":"improving these rights.166 On 20 March 2018, these two associations published a joint press\nrelease in which they criticised the oral presentation of the President of this Commission to\nthe Human Rights Council on 13 March 2018. 167 In April and October 2018, they explained\nthat the inter-Burundian dialogue was no longer necessary given the “remarkable\nachievements on the political, economic and social levels”.168 Finally, on 9 April 2019, during\na press conference held in Bujumbura, representatives of PISC-Burundi and CAPES+\ncriticised the declarations of the technical and financial partners of Burundi on 5 April 2019\nin which they expressed concerns about the decision of the National Communication Council\nto withdraw the licence of BBC radio and to suspend VOA radio and called the Government\nto guarantee the freedom of association, information and expression. The two local NGOs\nexplained that with such a declaration, the technical and financial partners were trying to\nundermine the democratic process and to disrupt peace. They added that themselves did not\nhave any issues with the sanctions against the independent media. 169 In June 2019, these two\nNGOs also denounced the statement of Mr. Smaïl Chergui, Representative of the African\nUnion, made during the Security Council session of 14 June 2019, in which he stressed the\nneed to hold an inclusive inter-Burundian dialogue in order to resolve the 2015 crisis.170","unnumbered":true},{"id":"a-hrc-42-crp-2-p0035","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":34,"section":"C. Violations of civil and political rights","text":"(ii)    Political parties\n253. The right to freedom of association includes “the right to establish organisations and\nassociations involved in political and public affairs”, which is also an accessory element:\nessential in the exercise of the right of participation in public affairs.171\n254. In Burundi, the creation, organisation and functioning of political parties are\nregulated by the law no. 1/16 of 10 September 2011, 172 which recognizes the possibility of\npolitical parties to create temporary coalitions in order to pursue common objectives,\nincluding in the framework of elections,173 as well as their right to assembly, to organise\ndemonstrations and to campaign within the conditions setup by law, namely that these\nactivities take place in venues outside of public administration, parastatal and private sectors\nand educational institutions.174 The registration of political parties is compulsory, requires\nsubmitting an application with the Minister of Interior which includes various information\nand documents.175 The statutes of political parties must include some indications, such as “the\nname of the political party; the basic principles and guidelines of the political party ideology,\nhead office, composition, appointment procedure and the term of office of the governing\nbodies on the national level, commitment to respect the national charter, the Constitution,\nlaw, public order and decency, respect of the principles set out in article 22 of the present law\nby explicitly reproducing them, the internal organisation at the national level, funding","unnumbered":true},{"id":"a-hrc-42-crp-2-p0036","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":35,"section":"C. Violations of civil and political rights","text":"sources, rules to follow for the modification of statutes, procedures for the dissolution of the\npolitical party and the devolution of its assets”.176\n255. The registration in February 2019 of the new opposition party of Agathon Rwasa,\nthe Congrès national de libération (CNL), after months of administrative processes, raised\nhopes with regards to the opening of the political space. However, the first months of CNL\nexistence were marked by several obstacles to its activities, notably with regards to the simple\nact of opening its offices throughout the country, which constitutes a form of violation of the\nright to the freedom of association.177 In fact, finding offices and opening communal and\ndistrict headquarters has often been a laborious process because of the hostility of some local\nadministrative authorities and CNDD-FDD, and several of these local headquarters have\nbeen vandalised or destroyed.178 Even the inauguration of the CNL offices in Bujumbura was\npostponed by a week pursuant to the decision of the authorities for vague “security\nreasons”179. One of CNL members explained the difficulties encountered by the party to open\none of its communal headquarters:\n“CNL party wanted to open its office in commune and province [X]. On [Y] June\n2019, they sent a letter to the Governor of the province […] seeking his permission.\nThe Governor took two weeks to respond to us [and] sent us to the administrator of\n[the commune]. […] The communal administrator […] told us that he could not allow\nus to work in the colline […] for security reasons. […] the administration\nprohibited us (from working there) to stop people who might want to join us […] this\nadministrative authority gave the order to landlords not to rent their houses to CNL\nto be used as their offices”.180\n256. In addition, its members have regularly been targeted for intimidation, harassment,\nthreats and several members were victims of torture and ill treatment, arbitrary arrest and\ndetention, and some have disappeared or were executed in order to dissuade them from\ncarrying out their functions within the party and to force them to stop.181","unnumbered":true},{"id":"a-hrc-42-crp-2-p0037","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":36,"section":"C. Violations of civil and political rights","text":"(iii)   Violations of the freedom of association\n257. The efforts to force the population, mostly men, to join the party CNDD-FDD or its\nyouth league, Imbonerakure, have continued as per the past, 182 whether they are already\nmembers of another political party or without political affiliation. This practice constitutes,\nin and of itself, a violation of the corollary of the freedom of association, which is the freedom\nnot to associate with others.183 To that end, the Imbonerakure have frequently resorted to\nintimidation and threats, including death threats, arbitrary arrests, as well as torture and ill\ntreatment, in the form of rape, disappearance or executions, 184 amongst others, which\nconstitute serious violations of human rights.185 As highlighted by a witness:\n“In January 2019, [the Imbonerakure] started again to aggressively recruit young\nboys and men who are still strong, but if you refuse, they would threaten you. The","unnumbered":true},{"id":"a-hrc-42-crp-2-p0038","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":37,"section":"C. Violations of civil and political rights","text":"threats start slowly but become violent and then they threaten to kill you. They do not\nstop harassing you until you accept, or you decide to leave”.186\n258.   A victim explained the motives of her rape by Imbonerakure:\n“They accused me of being an opponent because I did not want to join the women’s\nleague of the party CNDD-FDD. The Imbonerakure wanted to intimidate me and\ninsult me in order to join the women’s league of the party. At one point, I had to go to\nthe house of […] because of the intimidations. One evening, around 18:00, as I was\ngoing home from the market, I was stopped by […] young Imbonerakure. [… They]\ntold me ‘You are a traitor. You do not want to join the party’s women’s league, we\nwill teach you a lesson so that you give birth to an Imbonerakure’.”187","unnumbered":true},{"id":"a-hrc-42-crp-2-p0039","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":38,"section":"C. Violations of civil and political rights","text":"c)   Freedom of assembly\n259. As in the previous report,188 the Commission noted that the freedom of opposition\npolitical parties to hold peaceful assemblies has regularly been violated. The holding of\npeaceful meetings by political parties in public places or in their offices is “essential in the\ncontext of elections” because this allows “the candidates to mobilise their members, to\nremind them of and spread their political messages”. 189 According to international human\nrights law, the presumption must be in favour of holding such meetings which should only\nbe subject to a procedure of notification and not of authorization, and any restrictions should\nbe exceptional.190\n260. However, members of the opposition party, namely the members of CNL called\nInyankamugayo (those who reject contempt), were not always able to organise public\nmeetings, even when they had given prior notice to the authorities and had not received\nnotices of prohibition. Some were arrested simply on account of being with several other\nCNL members, including in their homes, or for having allegedly organised or participated in\n“illegal meetings”.191 However, there is no such infringement or crime in the Burundian law,\naccording to which public meetings are only subject to a system of prior notification and can\nonly be prohibited or postponed for public order purposes. 192 Meetings and political\ngatherings, in particular by CNL, have not been authorised or were postponed without any\nreal justification other than a vague reference to security reasons. 193 The Minister of Interior,\nPascal Barandagiye, has declared that “no political party has the right to be active in any\nlocality in Burundi in which it is not represented”. 194 Consequently, because of fear, some\nmembers carry out their activities clandestinely; while others simply prefer to renounce any\npolitical activity.195 One of these militants explained:\n“It is impossible to continue with political activities. We had to stop all political\nactivities in May 2018 because of the harassment. When two or three people from the\nopposition were talking amongst themselves, they were immediately arrested”. 196\n261. In effect, only the party CNDD-FDD and its youth league, the Imbonerakure, as well\nas the so called “citizen” civil society organisations loyal to the power in place, were able to","unnumbered":true},{"id":"a-hrc-42-crp-2-p0040","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":39,"section":"C. Violations of civil and political rights","text":"freely exercise their right to freedom of assembly. They regularly organised protest marches\nand demonstrations in order to denounce statements or reports that they deemed “ arnishing\nto the image of the country” or that allegedly sought to “destabilise the country”.\n262. For example, on 15 and 22 September 2018, such gatherings were held in several\ntowns in Burundi to denounce the final report of this Commission; 197 on 15 December 2018,\nthe “citizen” civil society organised protest marches in order to protest against the\ndocumentary Kamwe Kamwe aired by BBC on 4 December 2018, which revealed SNR\npractice of torturing and executing people in various houses. 198 On 29 December 2018, new\nprotest marches were held to denounce the content of the Ugandan President’s letter to the\nBurundian President in which President Museveni criticised the refusal of President\nNkurunziza to hold a dialogue with exiled opponents.\n263. They also rejected the statements of the Conference of the catholic bishops delivered\nat the occasion of Christmas in 2018, criticising the situation of political intolerance in the\ncountry and the loss of the gains of the Arusha Peace Agreement, as well as the imposition\nof new religious practices by CNDD-FDD to all its members, such as collective prayers and\nweekly fasting.199\n264. On 8 June 2019, protest marches were organised afresh in order to criticise the\nFrench media RFI, TV5 Monde and the newspaper Le Monde which had aired an interview\nwith the human right activist Marguerite Barankitse, in which she denounced the human\nrights situation in the country and pinned the responsibility to President Nkurunziza.200 On 29\nJune 2019, new demonstrations took place to denounce the report published a few days before\nby the International Crisis Group (ICG), Burundi : à court d’option,201 in which it was\nrecalled that the 2015 political crisis was still unresolved and that ICG was concerned by the\nstalemate the country was in on the eve of the 2020 elections, as well as a report by Human\nRights Watch202 denouncing the abuses against the political opposition in the country.\n265. Persons were forced to participate in these demonstrations, namely the taxi-vélo and\ntaxi-moto drivers, sometimes as part of community work.203\n266. In addition, meetings organised by CNDD-FDD, namely its youth league but also its\nwomen’s league, take place without any restrictions even when they take the shape of “a\nshow of force” or collective sessions of physical exercise which often have a military\ndimension with the objective, or at least the impact, of intimidating the population.204\n267. Generally, the climate of fear was so widespread that people felt the need to\nparticipate in the meetings organised by the party CNDD-FDD or the local administrative\nauthorities for fear of being labelled opponents to the power.205\n“We had to participate in the party’s activities by force. During these meetings, they\nasked us to denounce those who are not from the party in […]. For every group of 10\nhouses, there is a weekly meeting organised by the party. Once a month, there was a\nmeeting at the colline level. I attended both meetings. I sometimes participated in\nmeetings at the communal level. It was the head of the party at the level of the group","unnumbered":true},{"id":"a-hrc-42-crp-2-p0041","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":40,"section":"C. Violations of civil and political rights","text":"of 10 houses who led the meetings and sometimes there were authorities at the\ncommune level that attended these meetings”.206","unnumbered":true},{"id":"a-hrc-42-crp-2-p0042","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":41,"section":"C. Violations of civil and political rights","text":"d)   Freedom of movement\n268. Violations of the freedom of movement of the Burundian population continued to be\nobserved throughout the country as in previous years,207 especially in border zones. In fact,\non 7 May 2019, during a security meeting organised in commune Mutaho in Gitega province,\nthe Head of State asked the administrative authorities, the security and defence forces, as\nwell as the civil society and the population who are part of the security quadrilogie208, to\nremain vigilant and to “control the borders”. He also asked the “security authorities and the\npopulation to follow closely the population movements, to ensure that these movements are\nnot likely to disrupt peace and security”.209\n269. Barriers, usually operated by Imbonerakure, have been put on the roads in order to\ncontrol the movement of the population and to stop some people from leaving the country or\nto arrest them upon their return.210 Imbonerakure interrogate people on their travel motives in\nan atmosphere of general suspicion of any travel to or from abroad.211 A young man said:\n“I left Burundi on [X] 2018 […] There were barriers on the road to leave the country\nbecause it is the road that leads to Rwanda […] On the road, we found three barriers\nwith Imbonerakure. […] The second and the third barriers, were about 40 minutes\napart. The barrier before the border was manned by several police officers and\nImbonerakure. […] They were about 12 in total (around four police officers and eight\nImbonerakure). We stayed there for about thirty minutes. The Imbonerakure searched\nthe car. They asked us questions on the reasons for our trip to Rwanda. […] One told\nme […] that I was leaving Burundi to join the rebellion and do what our fathers\ndid”.212\n270. Once at such a barrier, to be able to continue their journey, Burundians had to show\ntheir travel document, or sometimes a receipt confirming that they had paid their contribution\nfor the 2020 elections, failing which, they would then pay varying amounts seemingly for the\nbenefit of Imbonerakure themselves.213 These controls were often accompanied by acts of\nviolence and intimidation by Imbonerakure.214 A witness gave a detailed account of what\nhappened at one such barrier:\n“I was arrested at a barrier operated by four Imbonerakure. They were in civilian\nclothing. Two of them had some type of military beret. They were operating the\nroadblock. The latter was made up of a rope in the middle of the road. […] They\nintroduced themselves as Imbonerakure. The two that did not hold the rope showed\nme their party membership card. […] I remember seeing the eagle symbol on the card\nand their photo. They said ‘We are the Imbonerakure of this region. We are\nresponsible for controlling any movement to Tanzania’. After that, they asked me\nwhere I was coming from and to show my identity documents. Since I did not have\ntravel documents, they asked me to give them money, and since I had no money, those\nwith a membership card violently beat me with a sort of club and wanted to imprison\nme”.215\n271.   Another witness explained:","unnumbered":true},{"id":"a-hrc-42-crp-2-p0043","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":42,"section":"C. Violations of civil and political rights","text":"“Before the referendum, there was a sort of harassment. We had to pay various\ncompulsory contributions […] for the elections. It was 2,000 Burundian francs\n[around 1 US dollar] per person, even for children – I paid 6,000 Burundian francs\n[around 3 US dollars] for my wife, my child and me. […] Imbonerakure gave me a\nreceipt after I paid that amount. There is no indication that the receipt comes from\nthe party [CNDD-FDD]; and on that receipt, there is a stamp of the commune. You\nmust carry the receipt with you at all times because you had to show it at various\ncontrol points in order to pass”.216\n272. Some local administrative authorities declared measures to restrict movements after\n18:00 or 19:00 for girls and women only, with the official objective of “curbing unwanted\npregnancies and debauchery”.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0044","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":43,"section":"C. Violations of civil and political rights","text":"e)   Freedom of religion\n273. The right to freedom of thought and religion is protected by international human\nrights law.217 This right includes the freedom to change one’s religion or belief and freedom,\neither alone or in community with others and in public or private, to manifest one’s religion\nor belief, through worship, teaching practice and observance of rituals. While it is possible\nto restrain the right to manifest one’s religion, the right to free thinking and conscience, to\nhave or to adopt a religion of a conviction of one’s choice, is protected with no reservation.218\nIn addition, the right to the freedom of opinion 219 guarantees that all forms of opinion are\nprotected, including those with a religious dimension. Harassment, intimidation and\nstigmatisation, including arrest, detention, judgement or imprisonment for opinions professed\nby a person or any form of attempted coercion aimed at getting someone to hold or not to\nhold an opinion are prohibited.220\n274. In Burundi, persons were forced to take part in the constitutional referendum that\ntook place in May 2019 or to join CNDD-FDD even if this was against their religious\nconviction of not taking part in public affairs.221 One of the victims explained:\n“One day, on [X] May 2018, a jeep with tainted windows came to the house and a\nman called me and he said, ‘we need you in the party’. I replied, ‘I cannot join the\nparty because my religion forbids me from joining political parties’. I am\nprotestant. I thought that we were done but he responded: ‘by will or by force, you\nwill join the party’. In June 2018, I was coming from work with […] and a car\nstopped, and the same person called me […]. I remembered his face and he told me\n‘Still not?’ and I answered ‘No, I still cannot because I am a born again’, [he said]\n‘I know you are, but you will still join us’.”222\n275. The right to freedom of religion also covers “the indispensable acts for religious\ngroups to carry out essential activities, such as the freedom to choose their religious leaders,\ntheir priests and their teachers”.223\n276. On 7 May 2019, during a meeting in Mutaho, in Gitega province with the authorities\nwithin the security quadrilogie (administration, security, defence and justice) to evaluate the\nsituation in the country, the Head of State recommended that with the elections approaching,\nthe members of the quadrilogie should “prevent deviations in the press and the churches”.224\nAt the same time, the Government sought to increase its control on diverse churches of the\ncountry, including by trying to intervene in the management of their internal affairs, in order","unnumbered":true},{"id":"a-hrc-42-crp-2-p0045","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":44,"section":"C. Violations of civil and political rights","text":"to create divisions, in a way that is reminiscent of the divisive nyakurisation policy of the\nopposition political parties carried out by the authorities.225\n277. The Burundian branch of the Seventh Adventist Church is a victim of this practice.\nPasteur Lamec Barishinga was nominated at the Head of this Church by regional bodies in\nNovember 2018, in accordance with its internal process. On 10 May 2019, he was arrested\nfor “rebellion” with one of his deputies and 21 members of the congregation. In fact, the\nMinister of Interior refused to take act of his nomination and decided to maintain Pastor\nJoseph Ndikubwayo as the recognised holder of that position, whereas the latter had been\nrevoked by the instances of the Adventist Church for serious misconduct, including\nembezzlement of funds. Pastor Joseph Ndikubwayo is close to power, in fact he was\nnominated in 2016 to the National Security Council of the Government.\n278. On 13 May 2019, Ted Wilson, President of the International Adventist Church based\nin the United States, publicly denounced the violations of the religious freedom of the Church\nby the Burundian authorities who had imprisoned, beaten and intimidated its leaders and its\nmembers in order to prevent Pastor Lamec Barishinga from taking up his functions. The\npastor, his deputy and congregation members were finally released at the beginning of June\n2019. However, the institutional crisis within the Church is still unresolved. 226 On 28 July\n2019, in Cibitoke province at the headquarters of the evangelical mission in Buganda, pastor\nJoseph Ndikubwayo arrived; accompanied by representatives of the provincial administration\nand members of security forces in order to put in place the governing bodies of the mission.\nHowever, the congregation firmly opposed this attempt since they do not recognise this pastor\nas the legitimate leader of their Church. Fighting ensued and persons were wounded.\n279. More generally, the relations between churches and the Government are tensed and\nGovernment allies have warned the religious leaders in order to discourage them from\nuttering pronouncement that are either critical or of a “political nature”. 227 In April 2019, the\ncatholic bishops made the decision to stop allowing speeches by political leaders during\nmasses which are deemed incompatible with the religious mission.228 On 8 June 2019, during\ndemonstrations organised by the “citizen” civil society organisations, one of their\nrepresentatives denounced the participation of bishops in the political life of the country,\nincluding their repeated references to the Arusha Peace Agreement. Referencing the position\nof some bishops in 2015 with regards to President Nkurunziza’s third term, specifically the\nArchbishop of Gitega; Monseigneur Simon Ntamwana, he qualified the bishops as opponents\nof the Government:\n“We want to give a message. We request that you pass it onto the Church leaders. We\nask them not to teach us the Arusha Agreement in churches. They should stop teaching\nus about war. They should not saw discord during the elections as they did in 2015.\n[...] They opposed the State and we know it. Your Excellency, the representative of the\nPope here in Burundi, please communicate this message to your Episcopalian entities\nhere in Burundi: we were surprised and shocked to hear a priest say to his\ncongregation that voting for Nkurunziza is the same as being a slave. [...]And that is\nnot all, there are also pastors. You know it. Do not say that we only denounce one\ngroup. There are also pastors who preached fasle news. They were PDC [Party","unnumbered":true},{"id":"a-hrc-42-crp-2-p0046","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":45,"section":"C. Violations of civil and political rights","text":"Démocrate-Chrétien]. They spread fear amongst Burundians by saying that blood\nwould flow, that no one should pray for Burundi, that there is a war”.229\n280. Nevertheless, on 11 June 2019, the Conference of Catholic Bishops in Burundi\ndecided to express its concern in relation to “the progressive increase of political intolerance\nwhich […] seems to be the reason behind clashes and deaths”.230\n281. On 15 August 2019, during the celebration that marked the catholic holiday of\nAssumption at the Mugera sanctuary in the province of Gitega, the President of the National\nAssembly, Pascal Nyabenda, urged the Church authorities not to meddle in politics and to\nremain neutral as they deliver their sermons. The Bishop of the Muyinga diocese,\nMonseigneur Joachim Ntahondereye, responded to him by saying that the duty of the Church\nis to faithfully preach the word of God even when the latter hurts.231","unnumbered":true},{"id":"a-hrc-42-crp-2-p0047","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":46,"section":"C. Violations of civil and political rights","text":"f)   The right to take part in the conduct of public affairs\n282. The right to take part in the conduct of public affairs is guaranteed by the\ninternational human rights law.232 It includes the right to vote and to be elected, and the right\nto have access to public service. 233 However, the Burundian legal framework is not fully\ncompatible with international human rights law and the Commission has documented\nviolations of the right to vote freely in the context of the constitutional referendum of May\n2018.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0048","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":47,"section":"C. Violations of civil and political rights","text":"(i)    The right to stand as a candidate for election and to be elected to office\n283. In Burundi, a new Electoral Code was promulgated on 20 May 2019, 234, less than a\nyear before the forthcoming elections of 2020. Officially, this new Electoral Code was\njustified by the need to conform to the law regulating the elections with the new Constitution\npromulgated on 7 June 2018. This new Electoral Code imposed significant restrictions to\nindependent candidates to be recognised as such; as well as in relation to standing for\nelections at any level (presidency, parliament, commune and colline) and being elected to\noffice. Given the strict authorisation regime for political parties in place in Burundi as well\nas the phenomenon of separation and division that they are prey to,235 the possibility of having\nindependent candidates is nevertheless particularly important.\n284. The Code drastically limits persons who can claim the title of “independent”, as it\nrequires the non adherence to a political party for more than a year, and no leadership role in\na political party for more than two years. It also requires one to have asserted “his\nindependence from the usual political cleavages by proposing a personal social project”. The\ncoalitions of independent candidates are not authorised.236 This reinforces the control of\npolitical parties on their members, as they can prevent internal disagreement knowing that an\nexclusion from the party (or threat of exclusion) within 1 or 2 years of an upcoming election,\nmeans that the person will not have the right to stand as a candidate, even independently.\n285. The election of parliamentarians is done by proportional representation. In order to\nbe elected as a representative, an independent candidate must have obtained more than 40 %\nof the votes in the electoral constituency in which he stood, which seems thoroughly","unnumbered":true},{"id":"a-hrc-42-crp-2-p0049","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":48,"section":"C. Violations of civil and political rights","text":"unrealistic in the context of a proportional suffrage in which independent coalitions are\nprohibited. Candidates affiliated to political parties or to coalitions of political parties must,\nfor their part, obtain only 2 % of the votes cast at the national level in order to be elected. 237\nCENI has the capacity to nominate representatives amongst political parties that have\nobtained at least 2 % of the votes, in order to guarantee the respect of ethnic and gender\nquotas imposed by the Constitution (60 % Hutus, 40 % Tutsis with a minimum of 30 %\nwomen).238\n286. In order to be elected to a position of Senator; the candidates; whether independent\nor members of political parties; must obtain more than 50 % of cast votes in the electoral\nconstituency during the first two turns and, from the third turn, the majority of votes cast. 239\n287. The independent candidates at the National Assembly or the Senate do not have the\nright to have a deputy and in case their seat become vacant; it will be attributed by CENI to\na candidate on the list of one of the political parties that obtained the least votes during the\nelections, without organising partial elections.240\n288. Members of the communal councils are also elected by proportional representation;\nand an independent candidate must obtain more than 10 % of the votes cast; as opposed to\nonly 2% for candidates put forward by political parties.241\n289. With regards to the financial guarantees required to stand for an election, the\nindependent candidates are treated in a discriminatory manner in this area as well in order to\nstand for elections at the National Assembly. The deposit of 500,000 Burundian francs\n(approximately 270 US dollars) is refunded only if the independent candidate obtains 40 %\nof the cast votes in the constituency, whereas candidates from political parties can be\nreimbursed for their guarantee if the party obtains 2 % of the votes at the national level.242 For\npresidential election, the required financial guarantee was doubled and is now at thirty million\nBurundian francs (approximately 17,000 US dollars), which will be reimbursed to all the\ncandidates including independent candidates who are declared ineligible by CENI or who\nobtained at least 5 % of the votes cast during the first round.243 The deposit of 400,000\nBurundian francs (approximately 220 US dollars) for the election to the Senate is reimbursed\nto all the candidates who obtain 5 % of the votes cast in the constituency.244\n290. The provisions that impose specific constraints to independent candidates to stand\nfor election or to be elected to office are contrary to the international human rights law which\nprovides that the exercise of civil and political rights, namely that of taking part in the conduct\nof public affairs, and therefore to stand and be elected to public office; must not be linked to\nthe adherence to a political party.245\n291. Finally, the new Electoral Code maintains the deprivation of the right to vote of\npersons under preventive detention,246 whereas these persons have not yet been condemned,\nand that according to the presumption of innocence, they should continue to fully enjoy all\ntheir civil and political rights.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0050","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":49,"section":"C. Violations of civil and political rights","text":"(ii)   The right to vote freely\n292. The right to take part in the conduct of public affairs 247 includes the right to vote and\nto be elected, and the right to hold public office 248 as the Human Rights Committee has\nclarified “Persons entitled to vote must be free to vote for any candidate for election and for","unnumbered":true},{"id":"a-hrc-42-crp-2-p0051","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":50,"section":"C. Violations of civil and political rights","text":"or against any proposal submitted to referendum or plebiscite, and free to support or to oppose\nGovernment, without undue influence or coercion of any kind which may distort or inhibit\nthe free expression of the electors’ will. Voters should be able to form opinions\nindependently, free of violence or threat of violence, compulsion, inducement or\nmanipulative interference of any kind […] Results of honest elections must be respected and\nimplemented”.249\n293. During the constitutional referendum, there were several violations of this right\nbecause the Imbonerakure sought to constrain persons to vote and to choose “yes”, by\nintimidating them and threatening them and seeking to control the votes, including at the\npolling stations and in the voting booths. 250 One of the participants to the referendum\nrecounted how it unfolded:\n“I went to the polling station. […] They had built voting booths beforehand for\nanyone to go in and put what they wanted in the envelope. But on that day, there was\nan Imbonerakure who checked how you voted. […] For illiterate women,[the\nImbonerakure] voted for them […] There was an Imbonerakure who checked what I\nwrote when I went to vote, i.e. when you entered in the voting booth, the Imbonerakure\nentered with you so you were two, you and the Imbonerakure […] and he told me\n‘Vote for the Constitution, otherwise you will no return to [Y]’. I was forced to vote\nfor the referendum, but I was not in favour of it, I was totally against it. […] The\nImbonerakure were there to intimidate. There were two Imbonerakure who entered\nthe [two] voting booths. […] And then other Imbonerakure who were outside walking\namongst people who were lined up”.251\n294.    A minor who was forced to vote explained the proceedings on the day of the vote:\n“At the polling station, people were separated in two queues. One was made up of\npeople suspected of being against the party in power. It was them who showed us\nwhere to line up and that queue was the most observed. They were policemen in\nuniform and Imbonerakure. I think the separation was done based on the voting\nintention because all my parents’ (FNL) friends and acquaintances were in the same\nqueue. While we were queueing up, some said ‘Woe to whomever does not vote yes’.\n[…] Inside the polling station, they would write the name of the person who was going\nto write their vote on the ballot. During the vote count, they knew exactly who voted\nyes, who voted no. The CENI employees would say ‘If you know how to write, write\nyour own name on the ballot, if you do not know how to write, give us the ballot and\nwe will write your name’. I wrote my own name on the ballot. I think that the persons\non the other queue did not have to write their name”.252\n295. Several other irregularities were also noted concerning the possibility of the\nopposition parties’ representatives to conduct their legitimate activities, despite being\nauthorised to do so, such as assisting to the ballot count or the registration of the votes cast,\nsince some “no” votes were not recorded. 253 One of the opposition party representatives\nduring the referendum explained:\n“I received documents stating that I was a representative. With these documents, I\ncould access the [polling] stations. The day of the vote, the Imbonerakure did not\nwant us to stay in the polling stations and we resisted […]. We stayed in the polling\nstation and the Imbonerakure told us that if we resist, there would be consequences.\nDuring the vote count, the Imbonerakure did not want the ‘no’ votes to be\ncounted”.254\n[…]","unnumbered":true},{"id":"a-hrc-42-crp-2-p0052","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":51,"section":"E. Violations of economic and social rights","text":"315. In its previous report, the Commission detailed the effects of the political crisis on\nthe economic situation and more specifically: the aggravation of the pre-existing economic\nproblems such as the increase of the budget deficit, the increase of state expenditures without\nsufficient revenues, the reduction of external assistance, the excessive reliance on internal\ndebt and a consolidation of the practice of assets grabbing and corruption. This deterioration\nof the economic situation has led to an increase in poverty in the population in a context of\nsharp rising costs and shortage of goods and products, including basic products. Despite this,\nthe population faced a multiplication and increase of taxes, as well as the creation of various\nmandatory or so called “voluntary” contributions, which amplified the difficulties of daily\nlife for most of the population. Violations of the right to adequate food and the right to\nfreedom from hunger, the right to education as well as the right to work and trade union rights\nwere also observed, sometimes on the discriminatory ground of victims’ political opinion. 255\n316. As a result of this investigation, the Commission is able to confirm that the\nviolations of economic and social rights have persisted, particularly the violations of the right\nto an adequate standard of living which has direct consequences on the enjoyment of the right\nto adequate food and the right to health, but also violations of the right to work and education,\nwhich are partly carried out on a discriminatory basis linked to political opinions.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0053","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":52,"section":"E. Violations of economic and social rights","text":"1.   Right to an adequate standard of living\n317. The right to an adequate standard of living includes “the right to adequate food,\nclothing and housing, as well as to a constant improvement of living conditions”.256 However,\nBurundi is one of the poorest countries in the world with 74.7 % of the population living in\npoverty.257 The country is classified 185th out of 189 for the Index of Human Development,\nlife expectancy from birth is only 57.9 years and the middle income per inhabitant and per\nyear - in purchasing power parity – is 702 US dollars. 258 The country, in economic recession\nin 2015 and 2016, has seen a fragile recovery since 2017, because the political crisis has\nrestrained its access to international assistance that it was strongly dependent on. This\nsituation has led to a deficit of the trading balance, a lack of foreign currencies and an increase\nin the cost of living which is still felt by the entire population.\n318. Despite this difficult overall economic situation and the increasing impoverishment\nof the population, the Burundian Government and the Burundian authorities, have continued\nto force Burundians to regularly pay various contributions, even when the latter do not\nnecessarily have a legal basis. 259 The objective of the main contributions required since the\nbeginning of the year 2018 was to finance the “2020 elections” and they were partly\ncompulsory and partly “voluntary”.260 Witnesses explained that the Imbonerakure did not\nhesitate to threaten, intimidate and even resort to the use of force when requesting payment\nfor these contributions for the elections.261 In addition, people generally felt compelled to pay\ngiven that the payment receipts for these contributions were a prerequisite for access to\nvarious public services.262\n“The last time that I contributed, was around [X] November 2018 in order to have\nthe proof of residence in the province of [Y]. I sent a friend who worked close to the\ncommune and he asked for the proof on my behalf. I could not show up for fear of\nImbonerakure. The administrator of the commune asked him […] ‘Did you bring the\n2,000 francs for contribution to the elections?’. He had to pay 2,000 Burundian francs\n[around 1 US dollar] to have the proof of residence”.263","unnumbered":true},{"id":"a-hrc-42-crp-2-p0054","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":53,"section":"E. Violations of economic and social rights","text":"319. On 30 June 2019, in his speech on Independence Day on 1 July 2019, the Head of\nState announced that since the required budget for the elections has been reached, the\nmandatory contributions were abolished and only the “voluntary” ones driven by patriotic\nemulation will be paid.264 However, the Commission has received information indicating that\nthe mandatory contributions for the 2020 elections, especially the sums withheld at the source\nfor civil servants, have continued to be collected.265\n320. Other than the elections contributions, Imbonerakure collected, by intimidation or by\nforce, contributions for the construction of local headquarters of the ruling party, CNDD-\nFDD.266 A witness noted:\n“Imbonerakure also asked us to contribute to the party. They said that if we do not\njoin the party, we should still pay contributions to the party. We had to pay 2,000\nBurundian francs [around 1 US dollar] per household and per month. We received\nunstamped receipts. These contributions were for the party CNDD-FDD. We paid in\nJuly, August, September and October 2018”.267\n321. Several refugees who returned in Burundi in the framework of the assistance\nprogramme for repatriation were forcibly stripped of their food kits and monies by\nImbonerakure and local administrators or forced to catch up with their contribution payments\nthat were unpaid during their exile. Judging by the perpetrators’ statements as reported by\nthe witnesses, these were quasi-retaliatory actions against the returnees for having fled\nBurundi after 2015 and for not having participated in its development, nor contributed to the\nelections. They subsequently found themselves with no resources, and some were forced to\nflee again.268 A person who was repatriated to Burundi recounted what happened to them\nupon their return:\n“Imbonerakure continued to harass me and to take all that I had. I went to see the\nchef de colline a few days after my arrival. […] The chef de colline told me that as a\nreturning refugee; I had no right nor voice. The rights of those who stayed in the\ncountry override those of the ones who left and returned”.269\n322. This situation has important consequences on the standard of living of families\nwhose head of household was killed or disappeared, because they have difficulties feeding\nthemselves and keeping a lodging.270 A young man whose father disappeared said:\n“My mother does not work, she is a farmer. I had to work to provide for my mother\nand my brothers. I worked in the fields for 2,000 Burundian francs [around 1 US\ndollar] per day. We often slept hungry. With my father, we ate well, two to three times\nper day, but since his [disappearance], we eat once a day and even then, the food is\nhardly enough in quantity, and it is not filling. In the period 2017-2018, we were in\nthat situation until I left Burundi. We lost weight, we became very thin. It was\nimpossible to eat what we preferred because we could no longer afford it”.271\n323. The level of poverty is such that the traditional solidarities tend to disappear and\nchildren who were orphaned, often girls, find themselves with no resources and left to fend\nfor themselves. They tried to survive by doing housework, through marriage or find\nthemselves on the street, and some then decided to leave the country.272 An orphan mentioned\nwhat happened to her after her parents were killed:\n“After they were killed, they chased me away from the house and I wandered through\nthe streets, slept on the street, and lost my network of contacts and neighbours. […] I\nwas able to stay in the house until the funerals, then the landlord came to tell me that","unnumbered":true},{"id":"a-hrc-42-crp-2-p0055","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":54,"section":"E. Violations of economic and social rights","text":"I had to pay and then I left. I did not ask help from the authorities, I wandered the\nstreets. I did not go to see the Nyumbakumi [leader of the group of ten houses] either.\nThere was a lot of poverty; people saw that I was destitute, but because of poverty, no\none was willing to help me”.273\n324. This widespread poverty also has an impact on every one’s right to enjoy the best\nstate of physical and mental health attainable.274 In fact, several Burundians are no longer able\nto buy medicine or to cover medical fees that they need, and some just simply renounced any\nmedical treatment.275 A witness whose brother disappeared highlighted the following:\n“My mother is cardiac (has a heart condition) and she can no longer receive medical\ntreatment. It was my brother who gave her money to buy medicine. Since his\ndisappearance, she can no longer buy her medicine”.276\n325. The states have the obligation to take “the necessary measures to assure […] the\nprophylaxis and the treatment of epidemic, endemic, professional and other diseases, as well\nas the fight against these diseases”. 277 However, an increase of cases of malaria was noted in\nall the provinces of Burundi since the beginning of December 2018. Despite the statistics of\nthe World Health Organisation (WHO) indicating 5,738,661 cases of malaria – nearly half of\nthe Burundian population – including 1,801 deaths counted between 1 January 2019 and 21\nJuly 2019,278 the Burundian Government refused to recognise the existence of an epidemic\nsituation.279 Such a declaration would however have the advantage of increased support from\nthe international community to tackle that situation, whereas shortage of medications is\nregularly reported. A cholera epidemic was declared by the Minister of Health in June 2019,\nmainly in Bujumbura Mairie and in Cibitoke province with 199 reported cases between 5\nJune and 28 July 2019, including the death of one person.280","unnumbered":true},{"id":"a-hrc-42-crp-2-p0056","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":55,"section":"E. Violations of economic and social rights","text":"2.   Right to work\n326. According to the International Covenant on Economic, Social and Cultural Rights,\nany person has the right “to the opportunity to gain his living by work which he freely chooses\nor accepts”281 and this right must be exercised “without any discrimination as to race, colour,\nsex, language, religion, political or other opinion, national or social origin, wealth, lineage or\nany other grounds”.282 However, the recruitment in public and parastatal employ is done in a\ndiscriminatory manner based on political affiliation and not on experience or qualifications,\nincluding in the education, health, judiciary sectors or in public companies. 283 A witness\nexplained:\n“If you studied and you are an Imbonerakure, you will have the priority in the\nrecruitment of a paid job. In all cases, the Imbonerakure have the priority, even\nuneducated Imbonerakure would be given something […] any unemployed person\njoins them to be able to find a job. [X] also joined the Imbonerakure to find a job; that\nis how he was given the job of a driver of a locally elected official”.284\n327. Persons who are holding a job but are not members of the CNDD-FDD risk losing\ntheir job.285 A teacher explained:\n“If, for example, you are a teacher and you do not join the ruling party, you can be\ndismissed. […] I have colleagues who became Imbonerakure since May 2015 because\nthey were forced to do so […] In order to dismiss a teacher, they first accused him of","unnumbered":true},{"id":"a-hrc-42-crp-2-p0057","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":56,"section":"E. Violations of economic and social rights","text":"some infraction, such as having insulted the President of the Republic or possessing\na fire arm. Then they put him in jail for six months, after which the law permits the\ndirector to dismiss the teacher. Several teachers were dismissed in that way”. 286\n328. The Government is trying to extend this discriminatory practice on access to\nemployment based on political affiliation to foreign NGOs. It was also decided to put in place\nrecruitment committees for local staff in foreign NGOs in Burundi. The official reason is to\n“correct the noted imbalances and contribute to the social cohesion”. 287 However, analysts\nconsider that the real objective of the Government is to be able to offer remunerated\nemployment to members of CNDD-FDD.288","unnumbered":true},{"id":"a-hrc-42-crp-2-p0058","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":57,"section":"E. Violations of economic and social rights","text":"3.   Right to education\n329. In several educational institutions, students who did not pay the mandatory\ncontribution for elections, demanded from each student of voting age, were prohibited to\naccess courses. A witness explained:\n“Students in this school are 17 years old or older. If a student does not pay the\ncontribution, they send him home. […] The director of the school gathered the\nstudents and announced the communiqué, and he told them that everyone must love\nthe country and that whomever does not contribute is an enemy of the nation”.289\n330. In fact, suspension and expulsion from schools had become so frequent that, on 9\nFebruary 2019, the Minister of Education had to ban that practice and requested the schools\nprincipals to find other ways to guarantee that students pay their contributions, without\nstipulating what those means should be.290\n331. While the law stipulates that educational institutions must be free from any political\nactivity, students were deprived of schooling or were harassed or threatened by teachers\nand/or other students who are members of CNDD-FDD, due to their affiliation to a different\nparty, or to force them to join or to show their support to CNDD-FDD or Imbonerakure. If\nthey persisted in their refusal, they were deprived of schooling, unless they themselves\nabandoned school, including by fleeing the country.291 A former student explained:\n“At school, the students were forced to join CNDD-FDD and the head of class made\nit mandatory. There were also party meetings organised at school and not attending\nthem would make life difficult. The pressure to join CNDD-FDD is everywhere in my\nvillage; it is as if there were no other political party. If you do not join the party,\nyou are marginalised even socially. Not joining, is like withdrawing from society”.292\n332. The female students at the high school that were accused of having scrawled the\nPresident’s photo were also deprived of any schooling for an indefinite time period after\nhaving been released; while the judicial proceedings for “disrespecting the Head of State”\nwas ongoing. This constitutes a form of arbitrary sanction against them when they should be\npresumed innocent.293\n333. School drop-outs are frequent, mainly for girls, including in relation to early\npregnancies, despite the official policy allowing the girls to reintegrate schools after delivery.\n334. Even if primary school is free, there is still indirect fees for materials, uniforms or\nothers, as well as school fees for higher classes.294 Consequently, several students were forced\nto drop out of school at various ages due to their family’s economic difficulties, including\nthose that resulted from the killing, disappearance or fleeing of one of the parents, or member","unnumbered":true},{"id":"a-hrc-42-crp-2-p0059","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":58,"section":"E. Violations of economic and social rights","text":"of the family who was the main breadwinner. 295 The average length of schooling in Burundi\nis only three years.296 Two former students explained:\n“The life of my mother changed after the disappearance of my brother. It was [him]\nalone who provided for the needs of the family. I was at school, but I have since\ndropped out of school”.297\n“ I started school when I was nine years old and stayed in school for a year. I dropped\nout of school because of poverty”298.\n335. The quality of education suffers also from the desertion of qualified teachers, who\nare sometimes intimidated by some of their Imbonerakure students or other members of the\nteaching body who are also Imbonerakure, and their replacement is often based on political\naffiliation.299\n“[The three Imbonerakure] were really poor. Initially, they joined because of\npoverty; they had no choice but to join if they wanted to find work. […] When they\nfinished school, as a motivation, they recruited them as teachers and two or three\nyears later, they were promoted to the position of school principal. […] All the young\npeople who hoped to find jobs joined the ruling party. In Burundi, if you are a teacher,\nyou are forced to join the ruling party; otherwise, they bring young Imbonerakure\nwho need work to be teachers”.300\n[…]","unnumbered":true},{"id":"a-hrc-42-crp-2-p0060","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":59,"section":"E. Violations of economic and social rights","text":"5.   Discrimination against women and girls\n343. In its previous report, the Commission had analysed discrimination against women,\nparticularly in the socio-economic domain, showing how women and girls are\ndisproportionately affected by poverty due to persistent gender stereotypes within the family\nand society setting which restricts them to low income informal activities, and keeps them\neconomically dependent on their husband. 301 The Commission also note that despite\nsignificant progress made on the legal side with regards to gender equality, several\ndiscriminatory dispositions with regards to women still exist in the Burundian legislation, 302\nspecifically in matters of family law. In addition, customary law and practices continue to\ngovern some matters, namely matrimonial regimes and succession matters, perpetuating\nmultiple forms of discrimination with regards to women, and sometimes, in violation of\nBurundian laws, or because the aspects concerned are not regulated by law. The Commission\nhad finally concluded that the recent initiatives of the Burundian Government seemed to be\nguided by a paternalistic vision.303","unnumbered":true},{"id":"a-hrc-42-crp-2-p0061","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":60,"section":"E. Violations of economic and social rights","text":"a)   Persistence of patriarchal gender stereotypes\n344. In his report on the discrimination against women and girls in the cultural and family\nlife, the Working Group on the issue of discrimination against women in law and in practice,\nnotes: “The family is a place of perpetuation of traditional values, it emanates from a\npatriarchal culture and is a fundamental institution to maintain patriarchy”.304 Amongst the\nmain stereotypes emanating from patriarchy and that can lead to discriminations against\nwomen are those linked to morality and sexual behaviour, those that present the woman as\nweak, as well as the stereotypes on gender roles within the family.305","unnumbered":true},{"id":"a-hrc-42-crp-2-p0062","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":61,"section":"E. Violations of economic and social rights","text":"345. During the third term of its mandate, the Commission observed that gender\nstereotypes pertaining to private life, i.e. the expected and desired behaviour of women and\nmen within the family, tend to be elevated into social norms in the context of public life,\nsometimes in contradiction with legal provisions or public policies aimed at promoting the\nrights of women and gender equality.\n346. The National Gender Policy of Burundi established in 2012 306 clearly mentions that\nthe patriarchy is a traditional mode of social organisation in Burundi:\n“The man [...] incarnates the authority within the households, he makes the main\ndecisions and provides means of subsistence to the members of his household. The\nwoman, on her part, has the social responsibility of the domestic life; she takes care\nof the household chores and of the children and other members of the family”.307\n347. This Policy also explained how the role of the man as head of household, and the\nposition of subordination of the woman as the homemaker, translate in various social\ninstitutions and production activities, and generate important discrimination towards women\nin their exercise of fundamental rights.308 The families who, for some reason, end up with a\nwoman as head of household, immediately find themselves in a position of increased\nvulnerability as a result of such a stereotypical approach to the role of women and its\nconsequences in relation to the enjoyment of rights.\n348. The moralisation campaign of the Burundian society initiated by the Head of State\nin 2017,309 and endorsed by members of the Executive, influential public figures or even\npublic officials, has perpetuated, if not reinforced, the stereotypical conceptions of the role\nof women and the patriarchal dimension of the society.\n349. This is notably visible through the speeches of the wife of the President of the\nRepublic on official events such as the celebrations of international days or conferences for\nwomen and girls. For example, in her speech during the International Women’s Day, that she\nwas presiding over in Gitega on 8 March 2019, the First Lady insisted “on the fact that\nnational peace depends mainly on the peace that reigns in families” and “asked women to\npreserve peace in their households”.310 The Minister of Human Rights, Social Affairs and\nGender, on his part, “ indicated that the woman is not only the pillar of the family, but also\nthe pillar of the country, because sustainable development in a country starts at the household\nlevel”.311\n350. Previously, on the 26 October 2018, during the opening of the International\nConference of Women Leaders, the First Lady declared “the Burundian woman is called to\nplay a role next to her husband to contribute to the development of the country […] they must\ndemonstrate that they are capable” and she asked the Burundian men “to support the woman\nbecause without a man she is nothing and can never succeed”.312\n351. The persistence of patriarchal gender stereotypes is particularly observed in the area\nof sexual morality and marriage and affects mostly girls and young women. Official measures\nput in place to “protect” them hinder their enjoyment of other rights, such as the freedom of\nmovement or access to education.\nb)     Early or unwanted pregnancies\n352. The issue of early or unwanted pregnancies amongst young women is an important\nproblem for the Burundian society : as indicated by the frequent media publications on the","unnumbered":true},{"id":"a-hrc-42-crp-2-p0063","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":62,"section":"E. Violations of economic and social rights","text":"subject as well as the public policies “zero pregnancy in school environment” and the\nprograms developed for several years for the eradication of this phenomenon which leads to\nan important number of school drop outs amongst girls, and often results in their\nmarginalisation and impoverishment.313 However, the magnitude of this phenomenon seems\nto be less important in Burundi than in other countries of the sub-continent, since according\nto UNFPA, the rate of fertility amongst 15 to 19 years old girls in Burundi was at 58 per\nthousand in 2018 compared to 95 per thousand on average in southern Africa. 314 The causes\nof these pregnancies are multiple, varying from ignorance in sexuality which leads to\n“befriending” boys and the non usage of contraceptives to sexual violence perpetrated by\nsome members of the teaching staff or by other men on the way to school.\n353. Law n°1/13 of 22 September 2016 on the Prevention of, Victims Protection and\nRepression of Gender Based Violence has provisions for protecting the rights of students\nvictims of gender based violence in schools, specifically their right to education, as well as\nprovisions to punish their perpetrators.315\n354. However, the authorities’ speeches on the issue of pregnancies in schools tend to put\nthe onus on the young girls, who allegedly engage in debauchery, rather than on the adults\nwho have the authority over them, namely the teaching staff and the parents, but also the\nadministrative and judicial authorities and the perpetrators of sexual violence, while regularly\nreferencing law n°1/13 of September 2016.316\n355. In fact, despite this law which guarantees the right to education for the victims of\ngender based violence, in June 2018, the Minister of Education, Technical and Vocational\nTraining issued a circular which excluded from the formal education system any girl victim\nof pregnancy or forced marriage - which in itself is a form of gender based violence\nrecognised by the 2016 Law - as well as the male students responsible for the pregnancies.317\nThis circular came as a result of an exchange between the civil cabinet of the President of the\nRepublic and the cabinet of the Education Minister. It triggered a wave of protests, and\nseveral civil society associations submitted a petition to the President of the National\nAssembly. The decision for a permanent exclusion was revised a month later by the Minister\nof Education, who announced a month later in a communiqué dated 27 July 2018, the\nestablishment of a commission in charge of examining the requests for reintegration in the\nformal education system, and it authorised affected students to submit a request, but strictly\nwithin a two-week period following the publication of the communiqué. However, the\nMinister was not formally prohibiting the school principals from expelling the pregnant\nstudents or the students “responsible” for the pregnancy.318\n356. It is in this context that, on 7 june 2019, the principal of a technical high school\nexpelled ten girls and one boy due to pregnancies, arguing that they “infringed school\nregulations”. In addition, the decision stipulates that 46 female students were forcibly\nsubjected to pregnancy testing during the investigation. Forced or coerced pregancy testing\nof female students by school authorities in another school was also reported in the media. 319","unnumbered":true},{"id":"a-hrc-42-crp-2-p0064","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":63,"section":"E. Violations of economic and social rights","text":"To the Commission knowledge, this decision was not contested nor suspended by Burundian\nauthorities.\n357. These discriminatory measures represent violations of the right to education. 320\nMoreover, when they target persons below 18 years of age, they represent children’s rights\nviolations, notably the right to education but also the right to freedom from arbitrary\ninterference in their private life, and unlawful attacks on their honor or reputation. 321 The\nSpecial Rapporteur on torture had observed that “[virginity tests and] the expulsion of\npregnant girls from schools, which often result in long-term harmful consequences, constitute\nforms of discrimination and ill-treatment”.322\nc)      Curfew for women and girls\n358. In 2019, local administrators adopted disciminatory measures against women and\ngirls, which restricted their freedom of movement, with the stated objective to restore\nmorality. However, these measures, though incompatible with Burundian legislation, were\nnot cancelled by Burundian authorities who had the ability and the duty to do so.\n359. Thus, in February and May 2019, at least three communal administrators 323 imposed\nmovement restriction measures after 18:00 or 19:00 hours, targeting only or specifically girls\nand women, with the stated objective to fight against behaviors that are contrary to the\nBurundian culture, to curb unwanted pregnancies and to discourage adultery. One of these\ndecisions came directly after the visit of the President of the Senate in the commune during\nwhich the Governor of the province stated that unwanted pregancies amongst students were\na considerable problem.324 In one case, the communal administrator instructed the mixed\nsecurity committees, in which Imbonerakure are involved, to fight against those behaviors.325\nIn another commune, the administrator stated that the offenders will be punished in an\n“ exemplary fashion”.326\n360. For example, one of these communal instructions stipulates “the administrator\ndeclares that women and girls are no longer allowed to visit bars and markets past 19:00\nhours if they are not accompanied by their legitimate husband. The administrator requests\nthe authorities and the mixed security committees to fight against this shameful behaviour by\nchasing these unruly women and by denouncing them so that they are punished”.327\n361. Another one declares more tersely that: “Young women are forbidden from being\noutside past 18:00 hours”.328\n362. Several civil society representatives reacted in the media, highlighting the\ndiscriminatory nature of these measures and their consequences on girls and women,\nparticularly in rural areas. In fact, they generally need to do farm work in addition to their\ndomestic or school obligations; for those who are able to attend school. All these tasks","unnumbered":true},{"id":"a-hrc-42-crp-2-p0065","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":64,"section":"E. Violations of economic and social rights","text":"involve movement or may require that students find a well lit area to revise their coursework\nin the evening.329\n363. These measures represent violations of women’s rights and children’s rights. 330 There\nare reasons to fear that the campaign to restore morality and Burundian values by the highest\nlevel of Burundian authorities will, in practice, result in a setback to women’s rights and\ngender equality in Burundi.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0066","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":65,"section":"B. Individual Responsibilities","text":"374. The Commission still has reasonable grounds to believe that SNR agents, police as\nwell as Imbonerakure, were the main presumed perpetrators of crimes against humanity\ncommitted during the period covered by this report. On this basis, the Commission updated\nthe list of alleged individual perpetrators that it drew up during the initial mandate period. 331\nThis list remains confidential, in the interest of protecting the Commission’s sources and\nrespecting the principle of presumption of innocence of the alleged perpetrators. It will be\nturned over to the High Commissioner for Human Rights at the end of the mandate. In the\nmeantime, the Commission reserves the right to share it.\n375. The Commission continues to distinguish between direct responsibility and the\nindirect responsibility of military commanders and hierarchical superiors, including\ncivilians.332 The information collected during this mandate allow the Commission to confirm\nthe descriptions already presented in its previous reports of the hierarchical structures within\nSNR and the police, as well as the prevailing confusion between the state institutions, state\nentities and CNDD-FDD.333 The “Committee of Generals” remains the central element in the\ninformal command structure of the security apparatus. It should be noted that in virtue of the\nConstitution promulgated on 7 June 2018, SNR is no longer officially part of the defence and\nsecurity forces placed under the authority of the Government and the control of the\nParliament, which comprise only the Burundi National Police and the National Defence\nForces.334\n376. The organic law on the mission, organisation, functioning and composition of SNR\nand the law revising law n°1/05 of 2 March 2006 on the status of SNR personnel were\nadopted by the National Assembly on 28 May 2019, but have not yet been promulgated,\nnor made public at the time of the writing of this report. During the presentation of these draft\nlaws to the Assembly, the Minister of Public Security, General Alain Bunyoni, confirmed\nthat SNR is henceforth directly attached to the President. 335 In fact, its budget has long been\nincorporated in the budget of the office of the President, but henceforth SNR is not under the","unnumbered":true},{"id":"a-hrc-42-crp-2-p0067","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":66,"section":"B. Individual Responsibilities","text":"authority of the Government or under the control of the Parliament, nor subject to respect the\nethnic quotas provided for by the Constitution for the defence and security forces.\n377. Such reorganisation of SNR is important from the point of view of personal criminal\nresponsibility of President Nkurunziza for the crimes against humanity committed by SNR\nagents. In fact, in addition to the indirect criminal responsibility of the superior who “orders,\nsolicits or encourages” the commission of a crime against humanity, 336 the criminal\nresponsibility of the latter is engaged when he remains inactive in the face of criminal actions\nof a subordinate placed under his authority or effective control. This implies that if the Head\nof State, who officially exercises effective control and authority on SNR, has deliberately\nneglected to take into account pertinent information relative to crimes against humanity\nperpetrated by SNR agents, and that he does not stop them nor reprimands them, or refers\nthem to competent authorities, he can then be held criminally responsible for these crimes.337\n378. Finally, Imbonerakure have continued to play a central role with regards to the\ncontrol and the indoctrination of the population, but also the persecution of real or assumed\npolitical opponents, often alone or in cooperation with the SNR, the police and the local\nadministrative authorities who are for the most part members of CNDD-FDD. This attests\nclearly that the formal and informal security apparatus are interlocked and that there exists a\nconfusion between the state institutions and those of the ruling party CNDD-FDD. The\nviolations committed by Imbonerakure are therefore not only attributable to the Burundian\nState when they constitute violations of human rights,338 but can also constitute crimes against\nhumanity of which the Imbonerakure bear individual criminal responsibility when these acts\noccur in the context of the policy setup by the Burundian State to silence the political\nopposition.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0068","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":67,"section":"A. Overview","text":"379. The Burundian crisis, essentially political in nature, started in April 2015 with part\nof the population, the civil society, and some members of the opposition political parties\nincluding within the ruling CNDD-FDD, commonly known as “frondeurs”, opposing\nPresident Nkurunziza’s third term. These massive protests were immediately and violently\nrepressed, but the repression against the opponents to the third term never really stopped.\nSince then, persons who were opposed or indifferent to the constitutional review adopted\nduring the May 2018 referendum, or those who refused to join the CNDD-FDD party or its\nyouth league for various reasons, were also considered as opponents to the President and to\nthe ruling CNDD-FDD party. Consequently, they were the target of threats, acts of\nintimidation and retaliation which led to serious human rights violations, and crimes against\nhumanity. On the eve of the 2020 elections, the Commission has decided that it was important\nto be forward looking and determine whether risk factors indicating a possible deterioration\nof the human rights situation were present in the current political context of Burundi\ncharacterized by the 2020 presidential, parliamentary and local elections.339\n380. To that end, the Commission analysed the most significant developments since the\nbeginning of the 2015 crisis, in order to identify the current risk factors indicators. The\nCommission based this analysis on the indicators proposed in the Framework of Analysis for\nAtrocity Crimes developed in 2014 by the United Nations Office on Genocide Prevention\nand the Responsibility to Protect.340 It also took into account the methodological guidance","unnumbered":true},{"id":"a-hrc-42-crp-2-p0069","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":68,"section":"A. Overview","text":"note established by the Office of the United Nations High Commissionner for Human Rights\nin order to develop an early warning analysis and evaluation of the risks of a deterioration of\nhuman rights situation, which includes a directory of related risk factors and indicators, 341 as\nwell as the violence factors linked to the elections, internal and external to electoral processes,\nidentified by the International Institute for Democracy and Electoral Assistance. 342\n381. The Framework of Analysis for Atrocity Crimes identifies eight common risk\nfactors for the occurrence of a genocide, crimes against humanity, war crimes and ethnic\ncleansing with indicators linked to each factor. 343 It also includes two risk factors specific to\nthe crime of genocide, two risk factors specific to crimes against humanity and two risk\nfactors specific war crimes. The Commission chose to focus its analysis on the eight common\nrisk factors. If there is a risk that atrocity crimes may occur, there is necessarily a risk of\ndeterioration of the human rights situation and an increase of violations.\n382. Risk factors are defined as conditions, such as behaviours, circumstances or\nelements, that create an environment conducive to the perpetration of atrocity crimes, or\nindicate the potential, probability or risk of their occurrence. Some are structural in nature,\nwhile others pertain to more dynamic circumstances or events, such as triggering factors. It\nis important to highlight that while not all risk factors need to be present to consider that there\nis a significant risk of atrocity crimes occurring, nevertheless these crimes are rarely\ncommitted in the absence of all or some of the risk factors that the Framework identifies.\nFurthermore, it is confirmed that the more risk factors, the greater the risk that atrocity crimes\nmay be committed. Similarly, existence of a higher number of indicators of a particular risk\nfactor, increases the importance and role of that factor in a given situation. On the other hand,\nthe absence of a triggering factor or the existence of mitigating factors can prevent the\nperpetration of atrocities despite the presence of several risk factors. Monitoring the situation\nand warning of the possibility of atrocity crimes being perpetrated in a more or less near\nremain paramount, even if there is bound to be some uncertainty on what will occur. The\nwarning can itself play a certain mitigation role or, in any case, lead to the adoption or\nidentification of preventive measures that could be promptly implemented should the\nsituation deteriorates.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0070","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":69,"section":"B. Significant developments since 2015 and the current Burundian context","text":"1.      Persistence of the 2015 political crisis\n383. As Burundi prepares for the next presidential, parliamentary and local elections in\n2020, it is important to recall that the 2015 political crisis, resulting from the 2015\npresidential elections, is still unresolved. The Burundian population continue to feel the\nimpact of the crisis at various levels, including the absence of real prospects of a political\nsolution.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0071","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":70,"section":"B. Significant developments since 2015 and the current Burundian context","text":"a)      Economic instability\n384. The unequal access to resources is a structural problem in Burundi, which predates\nthe 2015 political crisis, and is linked to the weakness and the lack of diversification of the\neconomy. The latter depends primarily on the agricultural sector and coffee exports, while at\nthe same time arable land is rare and often disputed. This situation is conducive to the\nappropriation of power and political struggles aimed at securing the control of the country’s\nwealth and resources. The investments, mainly foreign ones, are still few owing to the lack\nof infrastructure, but also the poor overall economic governance and specifically the rampant\ncorruption which affects all economic sectors. Prior to 2015, the country was amongst the\npoorest in the world and women were already particularly affected due to the persistence of\ngender-based stereotypes and the existence of discrimination, both in law and in practice,\nwhich limit their access to the labour market and the means of production.344","unnumbered":true},{"id":"a-hrc-42-crp-2-p0072","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":71,"section":"B. Significant developments since 2015 and the current Burundian context","text":"385. However, the socioeconomic situation has worsened with the 2015 political crisis\nwhich led to the overall economic recession. The worrisome political and security situation\nled to the failure of some private sector funding. The budget deficit has further increased,\nparticularly due to the suspension of numerous foreign aids as a result of human rights\nviolations and the explosion of the domestic debt. Inflation increased as did the costs of basic\ngoods and products. In 2016, Burundi went back to being “a country in a humanitarian\nemergency situation”, the Burundian population became poorer and an increasing number of\nBurundians are struggling to put food on the table.345\n386. Currently, the country’s socioeconomic situation remains fragile, although the\neconomic recession was followed by a slight recovery in 2017. Poverty, which can be defined\nas a condition in which “a person is unable to attain a minimum standard of living which\nallows him to adequately participate in the society, due to the lack of revenues or\nconsumption capacities […] particularly […] the lack of access to food, adequate education\nand health”,346 prevails within the Burundian population. The structural problems that hinder\nthe economic development in Burundi have not been resolved, and the cyclical economic\nissues are closely linked to the political situation of the country; which remains uncertain on\nthe eve of the elections. Obtaining or sustaining employment, mainly in the public and\nparapublic sectors, is subject to discrimination as it is conditioned by membership or support\nto the ruling party.347","unnumbered":true},{"id":"a-hrc-42-crp-2-p0073","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":72,"section":"B. Significant developments since 2015 and the current Burundian context","text":"b)      Persistence of the refugee issue\n387. One of the direct and particularly visible consequences of the crisis is the presence\nof nearly 350,000 Burundian refugees in neighbouring countries as of 31 July 2019.348 In fact,\nserious and massive human rights violations have pushed tens of thousands of people to flee\nthe country to seek refuge mainly in Tanzania, Rwanda, DRC and Uganda, but also in\ncountries further afield. The number of persons who left Burundi kept increasing between 1\nApril 2015 and 31 March 2018, date on which 430,938 Burundian refugees were registered\nin neighbouring countries.349\n388. Since 2017 and especially in 2018, the Burundian Government has sought to\nrepatriate Burundian refugees by declaring that there was peace and security in the country.\nThe Government sent representatives in refugee camps to convince them to return home. A\ntripartite agreement was signed on 28 March 2018 between Burundi, Tanzania and the United\nNations High Commissioner for Refugees (UNHCR) in order to accelerate the return rate of\nthe refugees. The UNHCR does not recommend the return to Burundi, but since September\n2017 it has assisted refugees who chose to return home on a voluntary basis in order to ensure\nthat the return is done in adequate security conditions. In December 2018, UNHCR adopted\nits strategic plan for Burundi covering the period 2019-2020 which integrates projections on\nreturns and numbers of refugees still outside the country. It is planned that 116,000 Burundian\nrefugees would return with the assistance of UNHCR and its partners, and that 278,000\nrefugees would remain at the end of 2019 and this number would fall to 175,000 by the end\nof 2020.\n389. Difficult living conditions in the refugee camps, partly due to the lack of funding of\nthe humanitarian crisis by international donors, as well as the reassuring and appeasing\nstatements of Burundian authorities relayed by certain authorities in host countries have\nconvinced some refugees to return. Between January and July 2019, 16,232 people returned\nto Burundi,350 in addition to some 58,000 Burundians repatriated between December 2017\nand 31 December 2018 according to the UNHCR data. The number of returnees by mid-2019\nwas less than the anticipated 2,000 persons per week while at the same time 4,591 new\narrivals were recorded between 1 January and 31 July 2019. 351 The repatriation support\nprogram has in fact had some funding challenges but was mostly hindered by difficulties","unnumbered":true},{"id":"a-hrc-42-crp-2-p0074","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":73,"section":"B. Significant developments since 2015 and the current Burundian context","text":"encountered by some returnees upon their arrival in Burundi, in particular a general climate\nof hostility towards them, as well as violent incidents and human right violations which\nforced them to flee again.352 This situation dissuaded other refugees from attempting to return.\n390. In some neighbouring countries where the chances for Burundians to be registered\nas refugee are limited, or access to the process is difficult, Burundians arriving for the first\ntime or who fled again after having tried to return to Burundi due to the hostile situation in\nthe country, live in extremely difficult conditions. They don’t have access to assistance,\nincluding humanitarian assistance, and have to rely on the generosity of other refugees who\nare themselves destitute. On 24 August 2019, the Ministers of Interior of Burundi and\nTanzania announced the signing of a confidential agreement to organize the return, voluntary\nor forced, of Burundian refugees and asylum seekers, at the rate of 2,000 persons per week,\nand if required, without the assistance of UNHCR. This announcement has the potential of\nhaving a destabilising effect on those who do not wish to return to Burundi as long as the\nviolence and human rights violations that pushed them to leave the country persist and if their\nsecurity is not guaranteed.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0075","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":74,"section":"B. Significant developments since 2015 and the current Burundian context","text":"c)      Widespread impunity for human rights violations\n391. Serious human rights violations, some of which constitute crimes against humanity,\nperpetrated in Burundi on a large scale since April 2015 have been outlined in the\nCommission reports: summary executions, disappearances, including forced disappearances,\narbitrary arrests and detentions, torture and other ill-treatment as well as sexual violence.\nThese violations mainly target people who are perceived – rightly or wrongly - as opponents\nof President Nkurunziza, the CNDD-FDD party or its youth league. Since 2015, human rights\nactivists, journalists, members of opposition political parties, both men and women, were\namongst the main victims., but now anyone in the population, including in rural areas, can\nbe a target.353\n392. Impunity, defined as “the impossibility, de jure or de facto, of bringing the\nperpetrators of violations to account - whether in criminal, civil, administrative or\ndisciplinary proceedings - since they are not subject to any inquiry that might lead to their\nbeing accused, arrested, tried and, if found guilty, sentenced to appropriate penalties, and to\nmaking reparations to their victims”,354 is the norm for human rights violations and crimes\nagainst humanity committed in Burundi since 2015.\n393. In fact, despite a multitude of reports from national and international civil society\norganizations, as well international bodies, including this Commission, which revealed the\nmagnitude and the persistence of human rights violations in Burundi, the authorities in\nBurundi have not taken any comprehensive measures to bring an end to these violations.\nOn the contrary, they have denied their existence. For example, during meetings regarding\nthe security of the country, the Head of State and the security quadrilogie have consistently\nexpressed their satisfaction with the security situation. They only accepted to recognize the\nexistence of some ordinary crimes, such as family conflicts, consumption of illegal\nsubstances and prohibited drinks, cases of rape and gender-based violence as well as thefts,\nincluding cases of armed robbery. 355 The Burundian authorities have accused people who\ndenounced human rights violations of trying to destabilize the country, and severely punished","unnumbered":true},{"id":"a-hrc-42-crp-2-p0076","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":75,"section":"B. Significant developments since 2015 and the current Burundian context","text":"those who were under their jurisdiction, by accusing them, for example, of violating the\ncountry’s internal security or by deciding to suspend or close national NGOs.\n394. Generally speaking, Burundian authorities have not carried out independent and\neffective investigation into violations and crimes committed since 2015, their perpetrators\nhave rarely been prosecuted, except in cases that were highly publicised. Even in these cases,\nmost judicial proceedings were unsuccessful. No form of reparations has been offered to the\nnumerous victims, most of whom were too afraid to complain due to possible reprisal or did\nnot see its usefulness given their mistrust of public institutions, particularly the police and\nthe judiciary.356\n395. Such impunity is partly linked to the numerous structural and situational\nshortcomings of the judicial system, such as the lack of independence and capacity,\nwidespread corruption, numerous and frequent interferences of the executive power in\njudicial proceedings, including acts of intimidation towards lawyers and magistrates,\nviolation of criminal procedures and right to defence. However, it is primarily due to the\ncollusion between the judiciary and the executive, which generally seeks to protect the\nperpetrators of the violations,357 namely police and SNR agents and especially Imbonerakure\nand, to a lesser extent since 2017, military personnel.358\n396. All these perpetrators, except members of defence and security forces whose loyalty\nwas questioned during the attempted coup d’état on 13 May 2015 or the attacks against the\nmilitary camps in December 2015, continued to benefit from the unwavering support of the\nauthorities. The authorities continued to praise the qualities and the actions of Imbonerakure\nand to provide them with material support.359 For the last three years, an official day dedicated\nto Imbonerakure “Imbonerakure Day” has been organized annually in all the provinces of the\ncountry in the presence of members of Government and parliamentarians. 360 Former leaders\nof Imbonerakure at the national level have also been appointed to important functions such\nas Ezechiel Nibigira as Minister of Foreign Affairs since April 2018, and Eric Nshimirimana\nas the Head of the Burundi National Radio Television (RTNB) since July 2019.\n397. The SNR, also accused of involvement in numerous violations, has also been given\na special status compared to other security forces in the 2018 Constitution. Its missions have\nbeen expanded “in order to embrace the entire national life with a view to respond fully to\nthe needs of the citizen”, and the Minister of Public Security explained that it was necessary\nto clean up its image which has been historically vilified”.361\n398. Alleged perpetrators of violations and crimes continue to occupy positions of\nleadership within the security apparatus, while some have been recently promoted. 362","unnumbered":true},{"id":"a-hrc-42-crp-2-p0077","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":76,"section":"B. Significant developments since 2015 and the current Burundian context","text":"399. Beyond the importance of guaranteeing the victims’ right to truth including being\ninformed of the fate of their missing family members as well as their right to reparation, there\ncannot be “just and sustainable reconciliation without an effective response to the need for\njustice”.363 The persistent and widespread impunity is therefore an impediment to the\nreconciliation of the Burundian population and the resolution of the 2015 political crisis.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0078","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":77,"section":"B. Significant developments since 2015 and the current Burundian context","text":"d)      Failure of the inter-Burundian dialogue process\n400. The political crisis that emerged from the candidacy of Pierre Nkurunziza to a third\nterm and the repression that ensued have forced numerous Burundians into exile, including\nseveral political figures known as frondeurs of the CNDD-FDD, and representatives of civil\nsociety organisation.364\n401. All international community actors including representatives of the United Nations\nand the African Union have repeatedly insisted since the beginning of the crisis, on the\nnecessity of an inclusive inter-Burundian dialogue in order to find a solution to the crisis\nwhile preserving the gains and the spirit of the Arusha Agreement. 365 On 18 January 2018,\nduring its Universal Periodic Review, several countries had recommended Burundi to engage\nin an inclusive dialogue with the opposition in order to find a solution to the crisis,\nrecommendations not accepted by the Burundian Government. 366 Members of the\nInternational Organization of La Francophonie (OIF) have also reiterated their support to the\n“efforts of the international community and most particularly the East African Community\n(EAC) in favour of an inter-Burundian political dialogue”.367\n402. In fact, in accordance with the principle of subsidiarity between the African Union\nand the sub-regional organisations on the continent, since July 2015, the East African\nCommunity (EAC) initiated and supported the organisation of an inter-Burundian dialogue\nunder the auspices of President Yoweri Museveni as the Mediator and President Benjamin\nMkapa as the Facilitator.368 Despite the unanimous support of the international community\nand the efforts made since then, the mediation has reached an impasse. The fifth and last\nround of inter-Burundian talks organised in October 2018 in Arusha was boycotted by the\nBurundian Government. The Facilitator concluded his mission on 1 February 2019 with the\npresentation of his final report at the Heads of State Summit of the East African Community,\nwithout this leading to the beginning of a solution or concrete achievements. 369 The EAC\nsimply took note of the report and decided that the Burundian question would be discussed\nat a later stage; without fixing a date nor appointing a new facilitator.\n403. In its November 2018 report, the Facilitator gave an overview of the five sessions of\ndialogue that he organised between May 2016 and October 2018, recalling progress made;\nbut mostly the obstacles and difficulties encountered. According to him, from the fourth\nsession organized between 27 November and 8 December 2017, the main challenges came\nfrom the Burundian Government. That session was the first opportunity for all parties to the\ncrisis to sit around the negotiation table – after having participated separately in the first three\nsessions – in order to discuss the four thematic priorities identified during the previous\nrounds, namely: the political issues; the constitutional, legislatives and electoral issues; the\nhumanitarian questions and the socio-economic situation; and finally the security situation.\nHowever, the Government of Burundi, which had requested that the fourth session be\nimmediately organised, demanded that no invitation be extended to the persons who are\nsubjects of an arrest warrant by the Burundian judiciary. The Facilitator complied and this\nprompted members of the external opposition to cancel their participation to this session.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0079","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":78,"section":"B. Significant developments since 2015 and the current Burundian context","text":"Then, despite the fulfilment of their requirements, the Government of Burundi and the\nCNDD-FDD party sent only junior representatives.\n404. The Facilitator also mentioned that the preparation of the fifth and last session was\npostponed to 19-24 October 2018 to comply with the decision of the Burundian Government\nthat any activity be postponed to after the May 2018 constitutional referendum. Then, the\nGovernment requested that the session be further postponed to 24 October 2018 to allow the\ncommemoration of the 25th anniversary of the assassination of President Ndadaye, scheduled\nfor 21 October 2018. The Facilitator complied once again and planned the session for 24 to\n29 October. The Government requested yet again the postponement of this session to the\nmonth of November 2018, arguing that the month of October was a period of national\nmourning. It also demanded that the work programme of that session be limited to the\nroadmap for the preparation of the 2020 elections signed in Kayanza in August 2018 by the\nsole opposition parties allied to the Government; and finally the authorities requested that an\nadvance copy of the participants list be sent to them. The Facilitator considered that the\nGovernment of Burundi was not really interested in the dialogue and went ahead to organise\nthe final session without the representatives of the Burundian Government, but with several\nrepresentatives of the opposition and the civil society. The participants elaborated roadmaps\nfor the crisis recovery and the preparation of the elections, on the basis of which the\nFacilitator prepared a consensual roadmap which, according to him, could bring stability to\nBurundi.\n405. At the end of his term, the Facilitator expressed his concern regarding the political\nsituation in Burundi, particularly in the run-up to the 2020 elections in the absence of any\nagreement to find a sustainable solution to the 2015 crisis. He noted that the internal dialogue\nprocess done in parallel by the Burundian Government was an indication of its lack of\ncommitment to the EAC facilitation and mediation process, since the result of the internal\ndialogue was presented as a fait accompli. Similarly, the Government organised the\nreferendum to revise the Constitution and, in so doing, amending some provisions of the\nArusha Peace Agreement; while those issues were on the agenda of the inter-Burundian\ndialogue. Lastly, the Facilitator noted that the intransigent attitude of some members of the\npolitical opposition further weakened this process. Similarly, the fact that a regional Summit\nspecifically dedicated to Burundi was not organised, the lack of a clear funding mechanism\nand a budget dedicated to the activities of the facilitation team, were also identified as\nobstacles.\n406. In fact, the Burundian Government is in denial with regards to the reality of the 2015\ncrisis and more so with regards to its current persistence. For example, on 20 August 2018,\nin a message addressed to the Nation to mark the third anniversary of his election in 2015,\nPresident Nkurunziza declared “it was on 20 August 2015 when we were invested with the\npowers of leading Burundi, following free, transparent and peaceful elections”. 370\nConsequently, he refused to engage in a dialogue and to make concessions or to solicit the\nsupport of the international community in order to find a solution.\n407. On the contrary, the Government constantly denounces the attention given to the\npolitical situation and the human rights situation in Burundi by various international and\nregional actors, as interference or attempts to destabilize the country. It has locked itself into\na rhetoric of an international conspiracy theory mounted against it and according to which\nany initiative from the international community constitutes a threat or an infringement on its\nsovereignty.371 For example, on 22 may 2019, the First Vice-president of Burundi declared\nthat an international conspiracy against Burundi had started five years ago but the mediation\nprocess had now concluded and the priority was the preparation of the 2020 elections.372","unnumbered":true},{"id":"a-hrc-42-crp-2-p0080","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":79,"section":"B. Significant developments since 2015 and the current Burundian context","text":"2.      2020 Elections\n408. The holding of regular, transparent, free and fair elections is the fundamental\nprinciple of a functioning democratic Government,373 however, in and of themselves, they are\nnot sufficient if they do not happen in an environment that promotes “the democratic practice\nand culture, the building and strengthening of governance institutions and the inculcation of\npolitical pluralism and tolerance”,374 as well as the “creation of the necessary conditions to\nfoster citizen participation, transparency, access to information, freedom of the press and\naccountability in the management of public affairs”.375\n409. Several objective indicators help to establish if elections are free and credible, for\nexample the fact that elections are organised at regular interval; that suffrage is universal and\negalitarian; that the right of citizens to stand for elections is guaranteed in law and in practice;\nas is the right to setup political parties that are able to participate in equal measure in\nelections; that the electoral campaign happens in an open and fair context, free of\nadministrative acts, violent actions or intimation of candidates, political parties or voters; that\nthe access to media is not restricted nor discriminatory; that votes are done by secret ballot,\nthat they are honestly counted and tallied and that results are made public; and finally that\ncandidates who obtain the necessary number of votes are duly installed in office and\npermitted to remain in office until their term expires.376\n410. Beyond these specific elements to the electoral process itself, to be free, transparent,\nfair and credible, elections must take place in a “democratic space” in which the enjoyment\nof fundamental rights, particularly the rights of freedom of opinion, expression and\ninformation, and the rights to freedom of peaceful assembly and association and the right to\nparticipate in public life are guaranteed, respected and protected both in law and in practice.\nA truly democratic space implies that the State and the ruling party are clearly separate and\ndistinct and therefore, no public resources are used for the benefit of a candidate or the ruling\nparty, including the involvement of public officials and employees in the electoral\ncampaign.377\n411. The preparation of the 2020 presidential and legislative elections in Burundi\nofficially started in 2018 with the holding of the constitutional referendum on 17 May\n2018, the signing of the roadmap for the elections preparation in Kayanza in August 2018 by\nCNDD-FDD and 24 opposition parties loyal to the Government, the collection of “voluntary”\nand mandatory contributions from the population for the organisation of these elections, the\ncreation of the new Independent National Election Commission (CENI) and the progressive\nsetup of its subdivisions at the provincial and communal levels, as well as the adoption of a\nnew Electoral Code.378\n412.    In addition, the CENI has already communicated the electoral calendar:\n- 20 May 2020: Presidential election, elections of members of the National Assembly and of\nthe communal councils;","unnumbered":true},{"id":"a-hrc-42-crp-2-p0081","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":80,"section":"B. Significant developments since 2015 and the current Burundian context","text":"- 20 July 2020: Elections of Senators;\n- 24 August 2020: Elections of the members of the councils at the collines and neighbourhood\nlevels.\n413. Nevertheless, it is clear that the conditions for free, fair and credible elections are\nnot met at this point in time.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0082","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":81,"section":"B. Significant developments since 2015 and the current Burundian context","text":"a)     Shrinking of the democratic space\n414. The democratic space in Burundi started to shrink significantly from the beginning\nof the 2015 political crisis with the suspension or the closing of media organs, civil society\norganisations, the attacks against journalists and human rights activists and the increase of\nviolations of civil liberties.379 The organisation of the May 2018 constitutional referendum\nand the ongoing preparation of the 2020 elections have triggered anew the shrinking of the\ndemocratic space with an increased control by the Government of the non-governmental\norganisations and censure of mediam while the independent national institutions that are\ncompetent in human rights matters, have lost all credibility380.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0083","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":82,"section":"B. Significant developments since 2015 and the current Burundian context","text":"(i)    Closure of the Office of High Commissioner for Human Rights\n415. On 5 December 2018, the Government of Burundi sent a letter to the United Nations\nOffice of the High Commissioner for Human Rights requesting that its country Office in\nBurundi ceases its activities within two months. As a reminder, this Office had reduced its\nactivities since 11 October 2016 as it awaited the renewal of the Headquarters Agreement\nbetween the United Nations and Burundi. In September 2017, the Burundian Government\nhad however confirmed to the Human Rights Council its decision to “restore its complete\ncooperation with the Human Rights Council and the United Nations Office of the High\nCommissioner for Human Rights, including by providing full and complete cooperation with\nthe Office of the High Commissioner in Bujumbura”. 381 It appears that it was manoeuvring\nby the Government to attempt to block the renewal of the present Commission, given that a\nfew months later, in January 2018, during its Universal Periodic Review, the Government\ndid not accept the numerous recommendations to that effect that had been submitted for its\nconsideration by various States.\n416. On 28 February 2019, the Office was then closed, after 23 years in the country\nworking to support the peace consolidation and the reform of the security and justice sectors,\ndespite the regressions and countless difficulties. It had also contributed to the capacity\nbuilding of some of the State institutions and the civil society in human rights related issues.\n417. The Government of Burundi justified its decision by explaining that from now on,\nthe country has national mechanisms for the protection of human rights, which in some way\nwere going to take over from the Office of the High Commissioner for Human Rights with\nregards to all matters related to human rights. However, the closure of the office leaves a gap\nin terms of monitoring, defence and promotion of human rights in Burundi, which are rather\ncrucial for maintaining a democratic space. Currently, the national human rights institutions\nare not able to fulfil these functions in a credible and effective manner. The international and\nnational civil society is not in a position to carry out activities for the monitoring or promotion\nof human rights since it is closely monitored by the authorities.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0084","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":83,"section":"B. Significant developments since 2015 and the current Burundian context","text":"(ii)   National Human Rights Institutions\n418. There are three national institutions which are officially mandated to independently\nprotect and promote human rights: The Independent National Commission for Human Rights\n(CNIDH); the National Observatory for the Prevention and the Rradication of the Crime of\nGenocide, War Crimes and Crimes against Humanity; and the Ombudsman.382","unnumbered":true},{"id":"a-hrc-42-crp-2-p0085","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":84,"section":"B. Significant developments since 2015 and the current Burundian context","text":"-      The Independent National Commission for Human Rights\n419. The CNIDH was created and given the mandate to uphold and promote human\nrights in the country.383 It can receive complaints and carry out investigations on human rights\nviolations; carry out regular visits in detention centres and formulate recommendations in\norder to: improve the treatment and the conditions of the persons deprived of their liberty;\nprevent torture and other cruel, inhuman or degrading treatment or punishment; fight against\nrape and gender-based violence. It can also file a complaint with the Office of the Prosecutor\non cases of human rights violations; provide or facilitate legal assistance to victims; and draw\nthe Government’s attention on cases of human rights violations.384\n420. The CNIDH, which had enjoyed an “A” status with the Global Alliance of National\nHuman Rights Institutions (GANHRI) since its creation, was downgraded to “B” status in\nNovember 2017, because it had not “taken a stand to promote the protection of human rights\nin response to credible allegations of gross human rights violations by authorities”, which\ndemonstrated its lack of independence that had been a concern for several human rights\nmechanisms since 2014, including the fact that it does not have financial autonomy.385\n421. In fact, since 2015, the CNIDH has been more of a sounding board for official\nGovernment positions than an independent mechanism for the protection of human rights.\nFor example, on 13 September 2018, it published a press release criticizing the report of this\nCommission of Inquiry submitted to the Human Rights Council, 386 in which CNIDH\nexpressed its outrage for the Commission’s mention of the President of the Republic\ndelivering a hate speech. It also voiced its indignation at the fact that the Commission imputed\nliability to Imbonerakure for the most recent human rights violations. It refuted the existence\nof violations that took place in the context of the referendum as documented by this\nCommission and on the contrary declared standing up “as a witness of a clear improvement\nof the human rights situation throughout the country”.387","unnumbered":true},{"id":"a-hrc-42-crp-2-p0086","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":85,"section":"B. Significant developments since 2015 and the current Burundian context","text":"-      The Ombudsman\n422. The Ombudsman’s role is to receive complaints and carry out investigations related\nto mismanagement and violations of citizens’ rights by public officials or members of the\njudicial system.388 He must also ensure mediation between the Administration and the citizens\nand he has an observer’s role with regards to the functioning of the public Administration.\n423. The lack of independence of the current Ombudsman, Édouard Nduwimana, who is\nin this position since November 2016, is obvious. He is a former Minister of Interior of\nPresident Nkurunziza and is known as the architect of the strategy to divide the opposition\npolitical parties from within (nyakurisation),389 as well as for his repressive policy towards\nmedia and civil society. Despite his new functions, he does not hesitate to publicly display\nhis allegiance to the ruling party,390 such as his participation to the celebration of\n“Imbonerakure Day” on 17 August 2019, during which he congratulated the CNDD-FDD\nparty and its leagues and pledged a heifer to the secretary of the Imbonerakure in the province\nof Kirundo.391\n424. With regards to the current situation, the Ombudsman confines himself to calling\nmembers of various registered political parties to cohabitate peacefully and live in","unnumbered":true},{"id":"a-hrc-42-crp-2-p0087","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":86,"section":"B. Significant developments since 2015 and the current Burundian context","text":"harmony.392 He has often acted as the spokesperson of Government rhetoric and policies. 393\nFor example, he expressed his satisfaction for the “inclusive character at social level” which\nallegedly characterised the referendum campaign and ballot, whereas, as documented by this\nCommission, several incidents, acts of intimidation and violence against political opponents\nwere committed in the context of the constitutional referendum in May 2018. 394 On 19 June\n2019, endorsing the conspiracy theories of the international community targeting Burundi,\nhe organised a press conference to criticise the intervention of the African Union\nrepresentative Smaïl Chergui at the Security Council requesting the reopening of the inter-\nBurundian dialogue.395","unnumbered":true},{"id":"a-hrc-42-crp-2-p0088","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":87,"section":"B. Significant developments since 2015 and the current Burundian context","text":"-      National Observatory for the Prevention and Eradication of Genocide, War\nCrimes and other Crimes against Humanity\n425. Provided for by the Arusha Agreement and the 2005 Constitution, 396 the National\nObservatory for the Prevention and the Eradication of Genocide, War Crimes and other\nCrimes against Humanity was only established in December 2017, 397 and its members were\nappointed shortly after by the President of the Republic.398 The Observatory was at the outset\nconceived as an early warning mechanism to prevent atrocity crimes. This consultative body\nis officially responsible to observe the evolution of the Burundian society in order to prevent\nand eradicate acts of genocide, war crimes and other crimes against humanity, especially by\nsuggesting measures to effectively fight against impunity for such crimes, including at the\nlegislative level.\n426. This Observatory is not independent either since its budget is included in that of the\nPresidency, and the Observatory’s President, Jean de Dieu Mutabazi, who is the leader of the\nparty Rassemblement des démocrates du Burundi (Radebu), is close to the current leadership.\n427. Its activities since its creation are quasi negligible. The Observatory had requested\nthat international observers be invited during the constitutional referendum 399 but the\nGovernment did not heed that call. It later refuted that acts of violence and human rights\nviolations had been committed in the context of the same referendum.400\n428. Instead of taking into consideration the concerns expressed by various actors of the\ninternational community in relation to the possible deterioration of the human rights situation\nin the country, as a prevention and early warning mechanism against atrocity crimes should\ndo as per its mandate, the Observatory denounced such concerns as infringement of national\nsovereignty.401 It also issued a statement on 25 June 2019 protesting the declarations of Smaïl\nChergui, the Peace and Security Commissioner of the African Union, during the Security\nCouncil session. According to the President of this Observatory, the alarmist tone of Mr.\nChergui describing Burundi as a country in a security and political crisis denotes “his\ndeliberate desire to “harm” and to “tarnish the image of the country” and his declaration is in\nline with “the continuing destabilization efforts spearheaded by certain neo colonialists\npowers”. By his request to resume the inter-Burundian dialogue outside the country, the","unnumbered":true},{"id":"a-hrc-42-crp-2-p0089","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":88,"section":"B. Significant developments since 2015 and the current Burundian context","text":"representative of the African Union was seeking to “torpedo democracy and the 2020\nelections”.402","unnumbered":true},{"id":"a-hrc-42-crp-2-p0090","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":89,"section":"B. Significant developments since 2015 and the current Burundian context","text":"(iii)   Control of the civil society\n429. The existence of a dynamic, diversified and independent civil society, capable of\nacting freely, with intelligence and competence in the area of human rights is largely\nrecognized as a fundamental element to ensure the sustainable protection of human rights,\nand in so doing, guarantee a democratic space necessary for the holding of free, fair and\ncredible elections.403 In fact, civil society has an important role to play “in the establishment\nand maintenance of a solid democracy”, including in the framework of elections. 404 Certain\norganisations can “work directly on electoral matters such as voter education, polling\nobservation, the reform of electoral institutions and the accountability of candidates and\nelected officials”.405 More generally, it is important in an electoral context, that all civil\nsociety organisations are able to dialogue with potential elected officials, to attract attention\non their concerns and interests in order to ensure that measures are put in place. They must\nbe free to evaluate issues of public interest and to contribute to the public debate, to hold the\nGovernment accountable, to criticize Government policies and practices, to carry out\ninvestigations and advocacy on matters pertaining to governance such as corruption, but also\nto report on human rights violations and electoral fraud and to interact with international and\nregional human rights bodies.406\n430. Since 2018, Burundian authorities have increased their control of international and\nnational NGOs, officially in order to ensure better coordination of the aid provided by NGOs.\nHowever, the authorities did not hesitate to suspend all international NGOs for three months\nfrom 1 October 2018 in order to compel them to seek accreditation again and to comply with\nthe requirements of the 2017 law on foreign NGOs. The Government then decided to become\ninvolved in the international NGOs recruitment processes of national staff, mainly to\nultimately influence the recruitment of supporters of the CNDD-FDD party.407\n431. The Government also sanctioned national NGOs by banning some of their activities\nor by suspending them, such as the organisation PARCEM, one of the last remaining civil\nsociety organisations still active, which was suspended indefinitely as of July 2019.408 Before\nthe crisis, national NGOs, several of which were active in human rights matters, made up an\nactive, solid, organized and representative national civil society. Since many of them opposed\nPresident Nkurunziza’s third term, they were, along with their members and representatives,\namongst the main victims of the repression. Several of them have therefore been suspended\nor dissolved and several of their representatives and members were forced into exile in order\nto avoid arbitrary detention, perhaps even execution like some of their peers.409\n432. International NGOs, that published critical reports on the human rights situation or\nprepared advocacy papers related to it and who are outside Government purview, have been\naccused of being pawns bankrolled by countries bent on attacking the national sovereignty\nand on “torpedoing the 2020 elections in Burundi”.410","unnumbered":true},{"id":"a-hrc-42-crp-2-p0091","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":90,"section":"B. Significant developments since 2015 and the current Burundian context","text":"433. The Burundian Government clearly has a peculiar understanding of the role of civil\nsociety and the organisations therein, which must not be independent and free “to decide and\ncarry out activities of their choosing”.411 They must only serve the interest of the Government\nand support its politics and decisions. Since 2011, the Government has thus supported the\ncreation of an alternate civil society- labelled as “civic” – composed of national NGOs that\nopenly support the Government and serve as its sounding-board.412\n434. Threfore, civil society in Burundi is currently unable to play its role as the\n“cornerstone of a democratic society”.413","unnumbered":true},{"id":"a-hrc-42-crp-2-p0092","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":91,"section":"B. Significant developments since 2015 and the current Burundian context","text":"(iv)   Media censorship\n435. In order to guarantee the holding of free and credible elections, journalists and\nmedia must be able to work freely, without interference, intimidation or obstruction.\nCensorship must be prohibited, and media editorial independence must be respected. In fact,\nmedia have an important role to play in the context of elections, including relaying messages\nto political parties and candidates, monitoring and supervising the electoral process and\nproviding voters with information on candidates and the electoral process.414\n436. The media currently present in Burundi are closely monitored and subject to genuine\ncensorship by the National Communication Council (CNC). The profession of journalism is\nequally strictly regulated by the new legal framework governing media since September\n2018, under the guise of professionalization, but breaking with recognized international\nstandards of journalistic ethics and conduct. Many national radio stations and newspapers\nhave been suspended or have had their licences revoked at the beginning of the 2015 crisis.\nJournalists who are still in Burundi, have continued to face serious challenges in the course\nof their work. They have been the target of pressure, threats and violence, which led several\nof them to seek refuge abroad; while others have been killed or disappeared.415\n437. Since the end of 2018, international radio stations have also been on the receiving\nend of warnings, suspensions or licence revocations, namely BBC, VOA and RFI. In July\n2019, Iwacu, one of the last remaining independent media that is still operational, was warned\nby CNC, which accused the press group Iwacu of having published unbalanced and\nunsubstantiated information, but without providing additional information on these\naccusations. RTNB is now run by individuals who are close to the executive power.416\n438. Currently, the media present in Burundi is neither free, diversified nor independent.\nThey can barely perform the fundamental duties of the media during an electoral process:\nsince they would have to comment and debate political questions of public interest without\ncensorship or restrictions. They should also be able to promote, criticize or oppose political\nideas while working in an environment in which their security is guaranteed.417","unnumbered":true},{"id":"a-hrc-42-crp-2-p0093","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":92,"section":"B. Significant developments since 2015 and the current Burundian context","text":"b)      Clamping down the political space and political intolerance\n439. The African Charter on Democracy, Elections and Governance reaffirms that State\nparties should put in place measures to reinforce “political pluralism specifically by\nrecognizing the role, the rights and the obligations of legally registered political parties\nincluding opposition political parties that must be guaranteed a status under the national\nlaw”.418 The Bamako Declaration adopted by Member States of the International\nOrganization of La Francophonie, of which Burundi is a member State since 1970, recalls","unnumbered":true},{"id":"a-hrc-42-crp-2-p0094","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":93,"section":"B. Significant developments since 2015 and the current Burundian context","text":"that “democracy assumes the existence of political parties enjoying equal rights before the\nlaw, free to organize and to express their opinions […] democracy goes hand in hand with a\nmultiparty system”.419 A multiparty system in a context of political tolerance is therefore a\nprerequisite for the existence of a democratic society and the holding of free, fair, transparent\nand credible elections.\n440. On 22 and 23 June 2017, a political retreat was organized by the Ombudsman and\nmoderated by Mgr. Jean Louis Nahimana and Brother Emmanuel Ntakarutimana, in\nKayanza, with the aim of drawing up conclusions, conduct guidelines as well as actions to\nbe taken in the short, medium and long term, in order to allow the holding of peaceful\nelections in 2020, while working towards the establishment of a conducive socio-political\nclimate and restoring trust amongst political leaders. The participants had already recognized\nthe existence of “relative political intolerance” in Burundi, and that the political space was\nnot equally guaranteed to political leaders and officials. The non-inclusive nature of CENI\nwas noted, as well as the existence of the “youth movement affiliated to political parties who\nare manipulated by political leaders and officials”, as well as the fact that impunity continued\nto promote social crises in Burundi in a repetitive manner.420\n441. The roadmap for the 2020 elections preparation was signed a year later, on 3 August\n2018, by the ruling party CNDD-FDD and 24 political parties loyal to the Government. The\nroadmap does not contain any commitment to solve the main issues identified during the June\n2017 retreat. With regards to CENI, the commitment to improve its inclusiveness was limited\nto its local branches. Several conclusions in this roadmap echoed Government positions\nwhich refused to recognize the situation of humanitarian, economic, social and political crisis\nthat resulted from 2015. For example, with regards to the refugees that fled in 2015 and who\nare encouraged to return, the roadmap explains that their exile was caused by “rumours\nspread during the 2015 elections”, that the human rights situation is “politicized for ulterior\nmotives ”, that “false reports” on Burundi “continued to be produced with the support of\nsome countries in the European Union” and finally that no “politician” is under prosecution\nin Burundi except the “putschists”.421 This roadmap has therefore contributed more to closing\noff political space on the eve of elections than guaranteeing a favourable and peaceful\natmosphere during these elections.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0095","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":94,"section":"B. Significant developments since 2015 and the current Burundian context","text":"(i)     A deceptive multiparty system\n442. The freedom of establishment and activity of political parties is intrinsic to the\nfreedom of association because the “political parties are in fact; the first avenue for the\npopulation to participate in the conduct of public affairs” and they “ensure the pluralism and\nthe proper functioning of democracy”.422 The only possible restrictions to the establishment\nof political parties are those “prescribed or determined by law and which are necessary in a\ndemocratic society, in the interest of national security or public safety, public order (ordre\npublic), the protection of public health or morals or the protection of the rights and freedoms\nof others”.423 The presumption must however remain in favour of the establishment of\npolitical parties.424\n443. Admittedly, there are numerous political parties registered in Burundi, 425 some of\nwhich are officially part of the parliamentarian and extra-parliamentarian opposition, since\nthe country has the peculiarity of legally and officially recognizing the political opposition\nand giving a full-fledged status to the leader of the opposition. 426 However, since CNDD-\nFDD came to power, the majority or the main opposition political parties have been infiltrated","unnumbered":true},{"id":"a-hrc-42-crp-2-p0096","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":95,"section":"B. Significant developments since 2015 and the current Burundian context","text":"in order to sow dissent in their midst and break them up into several wings, one of which will\nbe loyal to the ruling power and ends up being the only one that is officially recognized. This\nwell-known phenomenon has been named nyakurisation427 of political parties, in large part\nas a result of the manoeuvring of the former Minister of Interior and Patriotic Education from\n2010 to 2015, Édouard Nduwimana, who is the current Ombudsman.\n444. For example, Union pour le progrès national (UPRONA) has an officially recognised\nwing under the leadership of Abel Gashatsi, who supported the constitutional revision, called\nfor a yes vote during the referendum, supported the exclusion of the CNARED platform from\nthe inter-Burundian dialogue, and shares Government views on the “abuses of NGOs and\nindependent media”. There is a separate wing of UPRONA led by Charles Nditije which has\nopposing views on all these issues. Similarly, the Front pour la démocratie au Burundi\n(FRODEBU) is divided into FRODEBU-Sahwanya and FRODEBU-Nyakuri Iragi rya\nNdadaye which was further subdivided into Jean Minani’s wing with the external opposition\nand that of Kefa Nibizi close to CNDD-FDD. The party Forces nationales de libération\n(FNL) was broken up into three wings : that of Jacques Bigirimana (close to CNDD-FDD),\nthat of Jacques Kenese FNL-Iragi rya gahutu and Agathon Rwasa’s movement, as he was\nelected at the National Assembly as an independent and then established a coalition and a\nparliamentarian group called Amizero y’Abarundi – until he established the party CNL,\nregistered on 14 February 2019.\n445. The registration of political parties with the Ministry of Interior is in fact\ncompulsory and constitutes an actual authorization procedure by the authorities and\nnumerous documents and information are required,428 whereas the international standards\nrelated to the right of freedom of association require simple procedures of declaration.429 The\nmonths long administrative procedures required for the registration of CNL 430 perfectly\nillustrate this situation. A new political party, the Mouvement des patriotes humanistes\n(MPH), was also registered on 19 August 2019 by the Minister of Interior after having filed\nits application on 19 April 2019.431\n446. The Minister of Interior not only has the authority to award or refuse legal\nrecognition to a political party, but he also has the authority to suspend or dissolve them. The\nopposition political parties (or one of their wings) that opposed the third term were thus","unnumbered":true},{"id":"a-hrc-42-crp-2-p0097","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":96,"section":"B. Significant developments since 2015 and the current Burundian context","text":"suspended or dissolved and their leaders and some of their followers forced into exile because\nthey were labelled criminals or insurgents bearing the responsibility of the 13 May 2015 coup\nd’État.432 For example, in October 2017, the Minister of Interior, Pascal Barandagiye,\nrequested the dissolution of the MSD party, that he had previously suspended for 6 months\nin April 2017 due to its alleged support to the establishment of an armed group. The Minister\nalso dissolved several other opposition parties even if they had limited popularity such as the\nPIT, Vert-Intwari, Naddebu, Sonovi, Rusangi and Abahuza alleging a variety of reasons.433\nThe Conseil des patriotes (CDP) was also suspended in July 2017 because it was accused of\nnot being active enough and for having belatedly submitted their activity reports for the years\n2015-2016 and 2016-2017. This suspension was finally withdrawn two years later, on 9\nAugust 2019.434","unnumbered":true},{"id":"a-hrc-42-crp-2-p0098","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":97,"section":"B. Significant developments since 2015 and the current Burundian context","text":"(ii)   Political intolerance\n447. While the right to peaceful assembly requires, at most, a simple advance notice for\nlarge public rallies,435 and Burundian legislation recognizes the right of political parties to\nhold meetings, organize demonstrations and campaign, 436 the climate of political intolerance\nis obvious and is increasingly denounced in Burundi by various actors.\n448. On 21 August 2019, faced with challenges in carrying out its activities, harassment\nand violence against its members since its creation,437 CNL officially denounced the situation\nof political intolerance and the “abuses and excesses” perpetrated against its members and\nheadquarters, namely by the youth affiliated to the ruling party, some local officials affiliated\nto the ruling power, as well as administrative officials and security officials at the local level;\nspecifically within the mixed security committees.438 On the contrary, the police spokesperson\nhas denied the political nature of the violence and incidents reported by the media, claiming\nthat these were ordinary crimes and misdeameanours orchestrated by political authorities,\nwhile adding that members of CNL were the perpetrators of most of the recorded offences.\nHe specifically accused them of attacking homes belonging to Imbonerakure and local\nauthorities affiliated to CNDD-FDD, attacking and beating local administrative authorities,\nmembers of the mixed security committees and Imbonerakure and being responsible for the\ndestruction of some CNL headquarters.439\n449. From April 2019, the party Sahwanya-FRODEBU has also denounced a serious and\nincreasing climate of political intolerance in connection with election preparations, against\nits members and those of other political parties, specifically from local administrative\nauthorities who want to create a climate of fear, and it has requested the international\ncommunity to follow closely the political and security situation.440\n450. On 24 August 2019, during a meeting organized by the Minister of Interior and\nPatriotic Education with the representatives of officially registered political parties and\nprovincial governors for the preparation of the 2020 elections, “most of the participants\nstressed the fact that the threat to the 2020 elections was closely linked to political intolerance\nand stigmatization as well as the implication of the administration in sabotaging the activities\nof political parties”. A code of conduct was adopted and includes the sensitization of youth\naffiliated to the political parties so that they adopt a behaviour of political tolerance, the\nopening of headquarters in accordance with the law and the suspension of meetings at night","unnumbered":true},{"id":"a-hrc-42-crp-2-p0099","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":98,"section":"B. Significant developments since 2015 and the current Burundian context","text":"by political parties.441 Similarly, the climate of intolerance which prevents genuine political\npluralism, has been denounced several times by representatives of the Catholic Church\ndespite requests made by the official authorities to the Church not to interfere in political\nmatters.442\n451. In conclusion, the political space is locked down by CNDD-FDD, which is the only\nparty that is truly benefiting from freedom of assembly and the latitude to conduct its\nactivities without any hindrance.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0100","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":99,"section":"B. Significant developments since 2015 and the current Burundian context","text":"(iii)   Confusion between CNDD-FDD and State institutions\n452. For elections to be considered just, there must be a clear separation between the\nruling party and the State institutions, and public resources should not be used unfairly in\nfavour of the ruling party.443\n453. In Burundi, the CNDD-FDD party in power since 2005, as well as its youth league of\nImbonerakure and its women’s league are ubiquitous throughout the country, if only\nsymbolically through the construction of multiple party branches at communal and colline\nlevels. In fact, according to data obtained from the party itself, there are 60 communal\nbranches and 1,800 in collines,444 several of which were recently built as part of the mandatory\ncommunity work - which the Commission considers as a form of forced labour - or through\ncontributions that are claimed forcefully and violently from the population.\n454. This generalized and mandatory mobilization of the population in favour of the\nruling political party perfectly illustrates the confusion that has evolved over time between\nCNDD-FDD and State institutions, primarily at the local level.\n455. The administrative division in Burundi is relatively complex. The territory is divided\nin provinces, communes, zones, collines (called “neighbourhoods” in urban communes) and,\nat the lower echelon but informally, in groups of 10 houses (Nyumbakumi).445\n456. The commune is administered by the communal council and the communal\nadministrator.446 Members of the communal council are elected for five years and elect their\nboard composed of a president, a vice-president and a secretary who is also the communal\nadministrator.447 The latter is the representative of the commune and its population, but also,\nof the State, and as such a civil registrar. He also exercises the general authority of police and\ncan take any police measures that he deems necessary to maintain public order and security.\nHe also has direct hierarchical authority over the police. He is remunerated by the State. 448\n457. The colline (“neighbourhood” in urban communes) is administered by the colline (or\nneighbourhood) council and the chef de colline (or neighbourhood)449. The colline (or\nneighbourhood) counsellors are elected for 5 years and the counsellor who secured the most\nvotes during the election becomes the chef de colline (or neighbourhood), who is “the\nfacilitator of social harmony and development in his constituency”. As such, he receives an\nallowance from the colline’s budget.450\n458. By contrast, the chef de zone is appointed by the governor of the province (or mayor\nfor urban communes), upon suggestion from the communal administrator after approval by\nthe communal council. The chef de zone is the representative of the communal administrator","unnumbered":true},{"id":"a-hrc-42-crp-2-p0101","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":100,"section":"B. Significant developments since 2015 and the current Burundian context","text":"in his constituency. He is responsible, inter alia, of leading and coordinating the development\nactivities initiated by the commune in his zone; of assisting in the management of civil status\nmatters; and ensuring the liaison between the population and the administrator.451\n459. The head of the ten houses groupings, Nyumbakumi, is elected amongst the residents\nof the area and is a traditional authority who is not officially recognized by the law regulating\ncommunal administration. He ensures the liaison between local administrative authorities\nand particularly keeping them informed of population movements including births, deaths\nand the presence of visitors, which must also be recorded in the household notebooks.452\n460. The CNDD-FDD party has a hierarchical structure which largely follows the above-\nmentioned administrative division, with party leaders at the provincial, communal and\ncollines levels. The Imbonerakure also have a similar structure, parallel to that of the party\nand the administration. Presently, the majority of local authorities are members of the\nruling party and many amongst them are also Imbonerakure. In addition, since the\nImbonerakure are members of the mixed security committees, they are entrusted, almost\nofficially, with the mission of public security in rural areas, which often takes the form of\nnight patrols.453 On 23 August 2019, during a press conference, the spokesperson of the\nnational police himself stated that “the youth” – implying the CNDD-FDD youth league -\n“must be the eyes and ears of the police and all the institutions”.454\n461. This interlocking of roles and functions reinforce the absence of distinction between\nthe ruling party, local administration and the State security apparatus. A witness explained\nthe confusion of roles in his colline:\n“A police car arrived, inside was the administrator of the commune [X]. He was the\nhead of CNDD-FDD at the provincial level and he was also an Imbonerakure. […]\n[Y], the chef de colline had been an Imbonerakure for the past five years. […] [Z]\nwas the leader of the Imbonerakure on the colline. We knew it because it was openly\ndiscussed but also because when somebody did something wrong, he was the one who\ncame to punish them. The chef de colline [Y] could give orders but the one who was\nfeared and respected was [Z, the leader of the Imbonerakure]”.455\n462. It is therefore difficult to know in what capacity a person, who is at the same time an\nadministrative authority, a party official and an Imbonerakure as well as a member of the\nmixed security committee, is acting. A former Nyumbakumi highlighted the total confusion\nbetween the party and the administration as illustrated in meetings which are simultaneously\nparty and administrative meetings:\n“The meetings took place every Saturday and I took part as Nyumbakumi. They would\nteach us about CNDD-FDD. […] During the Saturday meetings, births and deaths\nwould not be discussed. Arrivals and departures were discussed by the chef de colline\nwho had received the information from Nyumbakumi […]. These meetings […] took\nplace at the colline, but they could also take place in the zone or the commune in the\nshape of larger ‘gatherings’. Some meetings at the colline were opened to all, others\nwere strictly for the Nyumbakumi. They took place in the offices of CNDD-FDD\nbranches. Until 2018, the Nyumbakumi not affiliated to CNDD-FDD could take part\nin the meetings for all Nyumbakumi of the colline. They made it clear to them that\nthey were not ‘integrated’ in the meeting’s discussions […]. Today, it is not possible\nto be a local leader without being a member of CNDD-FDD. All this took another\ndimension because the meetings were held in the party headquarters at the colline or\nthe commune level. When the meetings were exclusively for Nyumbakumi, they would\ngive us civic lessons to disseminate. The meeting was always chaired by a senior\nauthority, either the chef de colline or the communal administrator.[…] The\nsubjects covered included civic education in favour of CNDD-FDD, distrust of other\nparties, all other topics of interest for the commune or the colline such as the","unnumbered":true},{"id":"a-hrc-42-crp-2-p0102","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":101,"section":"B. Significant developments since 2015 and the current Burundian context","text":"contributions, the management of grazing spaces for the cattle and community\nworks”.456","unnumbered":true},{"id":"a-hrc-42-crp-2-p0103","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":102,"section":"B. Significant developments since 2015 and the current Burundian context","text":"(iv)   Indoctrination of the population and show of force by CNDD-FDD\n463. Such an interlocking of political, administrative and security structures facilitates the\ncontrol of the population in its entirety. Specifically, this has taken shape with the controls\nexercised by Imbonerakure on the population to verify that people have registered on\nelectoral lists, voted during the referendum, effectively paid up the forced and the “voluntary”\ncontributions for the preparation of the 2020 elections. 457 However, CNDD-FDD seeks to\nfurther increase its dominant position in the Burundian political space, including by recruiting\nnew members, by force if necessary;458 and in multiplying “shows of force” on the whole\nterritory since 2019.459 For example, on 27 April 2019, the Imbonerakure from Kinama zone,\ncommune of Ntahangwa in the city of Bujumbura, organised a “show of force”.460 On 11 May\n2019, it was the members of the CNDD-FDD women's League, the Bakenyerarugamba, who\norganized demonstrations in the city of Bujumbura as a “show of force” while chanting\nslogans such as “you cannot push a mountain”, the mountain symbolizing CNDD-FDD.461\n464. On 17 August 2019, for the third consecutive year, a day dedicated to Imbonerakure,\nnamed “Imbonerakure Day”, was organized throughout the country. It was largely presented\nas a “show of force” by the party.462 For the first time, groups of children aged 7 to 17 years,\npresented as ibiswi vy’inkona (children of the eagle) took part in the parade of various leagues\nof CNDD-FDD.463 This indoctrination of young people is new and demonstrates that the\nentire population is impacted.\n465. CNDD-FDD feels the need to display a show of force because the new CNL party,\nwhich benefits from a certain popularity within the population, represents its main\nopponent within its traditional electoral base, composed mainly of Hutus. In fact, in Burundi,\npolitical violence has been a tool used in the past by political parties to mobilize members of\na given community, because the show of force would prove the capacity and the will of the\nconcerned party to protect its group members.464\n466. The history of elections in Burundi has also shown a certain tendency of CNDD-\nFDD to resort to strategies of violence as a means of political mobilization, particularly when\nthere is a solid political opposition which leaned on the same community and/or the same\nethnic group. Violence also has the objective of punishing the defectors, who are labelled as\ntraitors, and to prevent possible future desertions.465","unnumbered":true},{"id":"a-hrc-42-crp-2-p0104","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":103,"section":"B. Significant developments since 2015 and the current Burundian context","text":"467. It is therefore clear that CNDD-FDD party is already in full-fledged pre-electoral\ncampaign and is in the process of mobilizing troops. However, while the elections are rapidly\napproaching, and specifically because the applications for the Presidential election must be\nsubmitted to CENI between 25 February and 5 March 2020, the party is yet to announce its\ncandidate. Since CNDD-FDD is traditionally secretive, it is impossible to know how far the\nappointment procedure has gone or when it will take place. There has been uncertainty\nsurrounding this nomination since the President’s announcement that he will not seek\nreelection. This situation is reminiscent of that of 2015 since it is only on 25 April 2015 that\nCNDD-FDD appointed President Nkurunziza as its candidate during the party’s Congress,\nwhen the candidates’ applications needed to be presented to CENI between 30 April and 9\nMay 2015 for the election initially scheduled on 26 June 2015. 466 CNDD-FDD waited until\nthe very last minute because they were unable to agree on an alternative candidate to\nNkurunziza.467\n468. The lack of a declared candidate of the ruling party contributes to maintaining doubt\nin the minds of certain analysts and several Burundians with regards to the possibility of a\nfourth term of President Nkurunziza, despite his announcement that he would not seek re-\nelection, reiterated several times by himself and his spokesperson. In fact, some of the\nPresident’s statements, initiatives and positions are sufficiently ambiguous to prompt\nspeculations.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0105","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":104,"section":"B. Significant developments since 2015 and the current Burundian context","text":"(v)    Abuses of power by the Head of State\n469. By virtue of the new 2018 Constitution, the President of the Republic has broad\npowers at his disposal. Specifically, he exercises regulatory authority and ensures the\nenforcement of laws ; he appoints Government members and terminates their services ; he\npresides over the Council of Ministers; he is the Commander-in-chief of the defence and\nsecurity forces; he appoints senior officials; accredits and recalls ambassadors as well as\nspecial envoys to foreign States; he has the prerogative of clemency; he can declare a state\nof emergency by decree-law and take measures required by these circumstances. 468\n470. However, he does not hesitate to make decisions that go beyond these prerogatives, for\ninstance when he appointed by decree the composition of the new Office of the National\nCommunication Council – while these should be elected internally by members of this\nCouncil. In addition, he regularly circumvents state institutions by using opaque parallel\nstructures such as the “committee of generals”.469\n471. He increasingly relies on the National Security Council (CNS), one of the “national\ncouncils” established under the Constitution to enable a “broad participation of citizens in\nthe management of public affairs”.470 The Constitution clearly states that the CNS is “a\nconsultative body which assists the President of the Republic and the Government in\nformulating a security policy, monitoring the state of national security, and devise defence,\nsecurity and policing strategies in times of unrest. This Council carefully scrutinises the state\nof unity and national cohesion among the components of defence and security forces. It can\nalso be consulted on any other national security issue”.471 The CNS is made up of 17 members,\neight of whom are full members, namely: the President of the Republic, the two Vice-\nPresidents, the Minister in charge of Public Security, the Minister of Interior, the Minister of\nExternal Relations, the Minister of National Defence, and the Minister of Justice. The CNS\nPermanent Secretary is Major-General Silas Ntigurirwa, former AMISOM Commander from\nDecember 2013 through December 2014. He is also the former Executive Secretary of the\nNational Commission for Demobilisation, Reinsertion, and Reintegration of Former\nCombatants from 2004 through 2008. The other nine members are appointed by the\nPresident. It is the CNS that banned the activities of all international NGOs for three months\nstarting from 1 October 2018,472 although this Coucncil does not have decision-making","unnumbered":true},{"id":"a-hrc-42-crp-2-p0106","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":105,"section":"B. Significant developments since 2015 and the current Burundian context","text":"power. Yet, this decision was endorsed and immediately enforced by Government without\nfurther questioning.\n472. The new Constitution, promulgated on 7 June 2018 by the President of the Republic,\nwas presented as “emanating from the will of the people [...] Burundians have just adopted a\nnew Constitution which lives up to their expectations after some anachronistic articles of the\nformer 2005 Constitution were amended and others revised. Moreover, new articles have\nbeen added to ensure that the Constitution conforms to our time and the laws in force in our\nsub-region, the East African Community. [...] In fact, this Constitution has been amended for\nthe good, the honour and dignity of Burundi, and mostly to prepare a brighter future for\ngenerations to come”.473\n473. However, its implementation is marked by some level of inconsistency and\nuncertainty as it is not done following a clearly predefined schedule. For instance, the office\nof Prime Minister that is supposed to replace one of the Vice-Presidents has not been\nestablished474 while at the same time the right of former Presidents to become Senators was\nimmediately repealed pursuant to the new Constitution. This is despite the fact that it was\none of the provisions of the Arusha Agreement. 475 Furthermore, some provisions are already\nobsolete, such as the one naming Bujumbura as the country’s capital, since the Government\nannounced on 21 December 2018 that Gitega was the new capital of Burundi476. The provision\non the country’s motto “Work, Unity, Fatherland” 477 is de facto questioned following the\nPresident’s demands that the former monarchic motto “Imana, Umwami, Uburundi” (God,\nKing, Burundi) be inscribed on every public building in replacement of the official motto,\nwithout any legal basis. Such personal abuses of presidential powers bring to light the\nweakness of State institutions, which are clearly not able to counteract or denounce them.\n474. President Nkurunziza’s constant references to the monarchic period as a blessed era\nfor the country, the imposition of the monarchic motto, including on CNDD-FDD offices,\nalongside a sufficiently ambiguous formulation of the new constitutional provision on the\npossibility of a return to monarchy, 478 allow for speculation among analysts and Burundians\nas to the possibility of a restoration of the monarchy to the benefit of the Head of State,\nespecially as he announced he will not take part in the next presidential elections. 479\n475. President Nkurunziza’s grip spans beyond the political spectrum. He also wants to\nimpose himself as the moral leader of the Burundian population whom he has decided to\n“moralize” through teachings strongly inspired by religion and near mysticism. In 2017, he\nlaunched a moralization campaign of the society, a national “advanced civil and psychosocial\neducation” programme whose ultimate objective is to “cleanse the Burundian society from a\ndisease inoculated by colonialism in its assimilated forms, particularly neo-colonialism,\nrecolonisation and imperialism”. Given that the city of Bujumbura “has been more exposed\nto these colonial teachings” than the other parts of Burundi, the Head of State “has scheduled\nto pay five to six visits to each of the three urban communes that make up Bujumbura, and\nthree visits to the other provinces”.480 Since then, he has multiplied moralization sessions\nduring which participants are convened either based on their regional origin (“natives”,\ninhabitants from a particular commune), or based on their socio-professional category","unnumbered":true},{"id":"a-hrc-42-crp-2-p0107","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":106,"section":"B. Significant developments since 2015 and the current Burundian context","text":"(elected and appointed authorities from a particular commune, civil servants of a ministry, or\nemployees of a public corporation). Members of officially recognized political parties have\nalso been called to participate. 481 The Sahwanya-FRODEBU Party Representative, Léonce\nNgendakumana, who refused to take part in such session was accused by State media of\ntrying to destabilise the country.482\n476. These sessions are characterized by opacity as participants are neither allowed to\nbring along their phones, nor have any writing material, or any other device to record what\nhas been said. In addition, questions are not allowed. However, over time, some aspects of\nthese meetings were made public. These are sessions where the President teaches “the real\nhistory” of Burundi, according to which as a monarchy, Burundi was “a wonderful country,\nwhere milk and honey overflowed. Our country was politically, economically and socially\nstable and well organized”. All the problems the country currently faces have been caused\nexclusively by the colonisers and only the CNDD-FDD party brought democracy when it\naccessed power in 2005.483 In addition to the “historical” aspect, moralization sessions try to\nbring about a “change of mindset” which is consistent with the religious, traditional, and\npatriarchal ideas of society promoted by the President and his wife, who are evangelical\n“born again” Christians. In fact, the First Lady is a pastor with her own church named, Eglise\ndu Rocher (Church of the Rock).484\n477. Some of the latest decisions taken by the President show signs of this religious and\n“moralistic” influence, such as the banning of free union and common-law marriages, 485\ncompelling CNDD-FDD militants to devote themselves to fasting and prayers every\nThursdays and to take part regularly in “prayer crusades” or “thanksgiving prayers”,\nirrespective of their religious background, including if they are atheists. He therefore imposes\nhis personal religious practises on all his party members.486\n478. Religious and quasi-mystical references are innumerable in the Head of State’s\nspeeches. For instance, during the thanksgiving prayer organized from 20 to 25 August 2019\nby the presidential family in Bubanza province,487 he recounted how God protected him while\nhe was a rebel fighter,488 he hosted seminars on topics such as the “characteristics of a youth\nwho respects God”,489 “the value of God in the national life and the life of the youth”,490 as\nwell as a “leadership” seminar entitled “obeying God and abiding to his will” where he\ndevelops 20 points on the importance of obedience.491\n479. Regular statements of a mystical and prophetic nature on the country’s destiny are\nregular features in his speeches and in his wife’s preaching and prayers. He thus proclaimed:\n“Burundi is under divine protection, nothing can shake it”, or “We would like to inform\nBurundians that in the year 2019, God will reveal many things so far unseen in Burundi. In\nthe year 2019, we expect a new turn in our history, Burundi shall be endowed with special\ngifts from God. We will multiply these heavenly gifts, make the most of them, and they shall\nbe a source of blessings and of prosperity from God Almighty, and we will accept to work\nwith God”.492","unnumbered":true},{"id":"a-hrc-42-crp-2-p0108","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":107,"section":"B. Significant developments since 2015 and the current Burundian context","text":"480. The idea that President Nkurunziza was appointed by God to lead Burundi is often\nimplicit but also, explicitly mentioned by persons close to the Government. 493 For instance,\non 10 February 2019, according to Burundi’s Ombudsman, all inhabitants of the Rukago\nHoly Mary Parish should contribute to and participate in the 2020 elections, since every\nleader is elected according to the will of God.494\n481. Naturally, the logical conclusion is that opposing the President is equivalent to going\nagainst the will of God. This rhetoric has turned out to be the “gospel of truth” within the\nCNDD-FDD, where dissenting voices are not tolerated. This was illustrated by the fact that\nthose who left the party in opposition to President Nkurunziza’s third term in office were\nconsidered as traitors and had to flee the country. Thus, it is difficult for some CNDD-FDD\nmembers to openly express any opinion contrary to the one voiced by the President.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0109","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":108,"section":"B. Significant developments since 2015 and the current Burundian context","text":"c)   Legal framework for the elections\n482. The legal electoral framework comprises laws, including the Constitution, and other\nstatutory texts regulating or influencing an electoral process, namely laws on the\nestablishment and functioning of political parties, voters’ registration laws, those on\ncitizenship, statutory texts governing every aspects of the organization and holding of\nelections, from electoral campaign to post-electoral dispute settlement. In a more general\nsense, laws on the freedom to exercise civic liberties, which are fundamental for the\norganisation of free, fair and credible elections, as well as those ensuring the free participation\nof citizens in public affairs without fear of discrimination, can also be considered as part of\nthis legal framework.495\n483. In order to comply with international standards, the electoral legal framework should\nreflect the following principles: voting should be universal, and therefore any restriction\nshould be minimal and justified; the vote should be secret; the right to stand for election\nshould be standardized and any form of restriction should be minimal and justified; the\nelections should be frequent; electoral authorities should be neutral and impartial; and\ncandidates and political parties should be treated in a fair and equal manner.\n484. To guarantee candidates, political parties, and voters’ trust and support of the\nelectoral process, a good practice is to avoid introducing important changes to the electoral\nlegal framework during the period preceding such elections in order to prevent confusion.\nElectoral rules should be established and disseminated well in advance to allow all the\nstakeholders to understand and master them. 496 In addition, these fundamental instruments\nwhich govern the democratic life should be the result of a national consensus while\ncomplying with international standards.497\n485. In Burundi, the Electoral Code, which is the key element of the electoral legal\nframework, was revised in 2019498 through a non transparent process. Officially, the necessity\nof a new Electoral Code was justified by the need to align it with the Constitution of 7 June\n2018. The new Electoral Code amending the one of 3 June 2014 was promulgated on 20 May\n2019499 after its adoption by the National Assembly on 17 April 2019 and by Senate on 24","unnumbered":true},{"id":"a-hrc-42-crp-2-p0110","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":109,"section":"B. Significant developments since 2015 and the current Burundian context","text":"April 2019. However, only the draft bills adopted in January 2019 by the Council of Ministers\ncirculated publicly until the Code promulgation. The Sahwanya-FRODEBU political party\ncriticised the Government for its lack of transparency during consultations to amend the\nElectoral Code. According to its press release, the party representatives were invited to a\nconsultation organized by Government on 3 January 2019, but no Government official\nhonoured the appointment. It was through the press that Sahwanya-FRODEBU\nrepresentatives learned about another consultative meeting that was organized on 4 January\nto which they were not convened. They also underscored that by this time the draft bills had\nalready been sent to the Council of Ministers and that those consultations were just\n“pretence”.500\n486. As mentioned above, one of the most notable consequences of this new Electoral\nCode is the introduction of stringent requirements in order to be recognized as an independent\ncandidate, to be allowed to run for elections in that capacity, and be elected501. However, it is\nimportant for this type of candidacy to be allowed to participate in any election considering\nthe relatively complex procedure of registration of a political party by the Government. 502\n487. Moreover, the Burundian legal framework now has restrictions on the exercise of\nthe right to freedom of expression and information, the right to freedom of association and\npeaceful assembly, which are disproportionate and unnecessary in a democratic society. 503\nThus, the legal framework is not able to guarantee that elections are free, fair, transparent and\ncredible.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0111","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":110,"section":"B. Significant developments since 2015 and the current Burundian context","text":"d)   National Independent Electoral Commission\n488. In accordance with the African Charter on Democracy, Elections and Governance,\nAfrican Union member States pledged to create and reinforce national independent electoral\nbodies to manage elections with impartiality. 504 Through the Bamako Declaration, member\nStates also reaffirmed that they would “ensure that the organization of elections, from the\npreparatory phase and electoral campaign through counting of votes and proclamation of\nresults, including electoral disputes where necessary, shall be done in total transparency\nunder the jurisdiction of credible bodies known by all for their independence”.505\n489. The Independent National Electoral Commission (CENI) has a key central role in\nthe organization of the 2020 elections and the smooth running of electoral campaigns. It is\nthe body that is officially in charge of making sure the electoral process is free, impartial, and\nindependent506. More precisely, it is in charge of organizing every election by making sure it\nare free, fair and transparent by publishing provisional results within the legal time limits;\npromulgating the arrangements, code of conduct and technical details on the holding of\nelections; receiving and addressing the complains related to the abuse of electoral rules;\nmaking sure there is no incitement to ethnic violence during campaigns; and ensuring the\nrespect of ethnic quotas.507\n490. The organization and functioning of CENI are laid down in decree n°100/125 of 27\nAugust 2018. The administrative and financial autonomy of CENI are mentioned in the\ndecree,508 with resources allocated in the form of annual subsidies derived from State budget,\nas well as funds received from bilateral and multilateral donors. CENI drafts an annual report\nof its activities and sends a copy to the President of the Republic, the Minister of Interior and\nto the Court of Auditors. It comprises five commissions (operations, electoral digitization\nand maintenance of equipment; legal matters and electoral disputes; electoral logistics and\nprocurement; administration and finance; electoral education and communication) each","unnumbered":true},{"id":"a-hrc-42-crp-2-p0112","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":111,"section":"B. Significant developments since 2015 and the current Burundian context","text":"under the supervision of a member. Each commission is sub-divided into services led by\nHeads of Service appointed by CENI.\n491. The Electoral Commission should also include local offices which are called\nIndependent Provincial Electoral Commissions (CEPI) and Independent Communal\nElectoral Commissions (CECI), with members appointed by members of the Commission\ndirectly above it. Membership of CEPIs should correspond to the number of communes in\neach province, headed by a President and an Officer in charge of the electoral equipment\nsince each commune should be supervised by a member of CEPI. As for the 129 CECIs, five\nmembers are appointed for each commune for a total of about 645 for a one-year term. 509\nMembers’ wages are decided by a joint ordinnance of the Minister of Territorial\nAdministration and the Minister of Finance.510\n492. On 21 August 2018, the current seven members of CENI were appointed by the\nPresident of the Republic for a five-year non-renewable term, 511 and they were sworn-in on\n19 September 2018. Although the Constitution provides that their appointment should first\nbe approved by an absolute majority in both houses of Parliament (a two-third majority was\nrequired by the former Constitution), it would be hardly conceivable that the Parliament do\nnot validate the presidential choices considering its lack of independence vis-à-vis the\nPresident. Thus, it was no surprise to see that the National Assembly approved the CENI\nmembers proposed by the President with a 98.8 % majority.512\n493. These appointed members benefit from the same immunity as parliamentarians in\noffice,513 but the ranks and benefits granted to them are determined by a decree of the Council\nof Ministers.514 CENI, as a body alongside its members are therefore under a form of\nstructural financial dependence on the President.\n494. The appointment of some individuals close to CNDD-FDD and the Government as\nCENI members was highly criticised. In fact, among these new members, there is its\nPresident, Pierre Claver Kazihise, who is the former Head of the Association for the\nConsolidation of Peace (ACOPA) - a civil society organization close to CNDD-FDD, which\nin 2014, publicly rejected accusations of human rights violations by Imbonerakure. This\norganization also denounced concerns raised by several Burundian NGOs and the\ninternational community on the preparation of the 2015 elections by describing them as\npolitical attempts to destabilize the country whereas the country is on “track to strengthen its\ndemocracy”.515 In his capacity as ACOPA President, he co-signed a joint letter written by 16\ncivil society organizations, said to be “civic” associations, sent on 13 September 2018 to the\nSecretary-General of the United Nations and to the Mediator of the inter-Burundian dialogue\non the eve of its fifth session. In this letter, they requested that the new 2018 Constitution,\nthe roadmap of the Kayanza elections or the composition of the CENI be not subject to\ndiscussion.\n495. Among the other members who are close to the President, there is Philippe\nNzobonariba, who was Secretary-General and spokesperson of the Nkurunziza Government\nfrom 2015 to 2018, now in charge of the Presidential communication; and Serge Ndayiragije,\nformer Minister of Communication and Media, now in charge of the Presidential\nadministration and finances.\n496. In their new capacities, some CENI members made statements that raise questions\nabout their neutrality and impartiality. For example, on 7 May 2018, Jean Anastase\nHicuburundi requested the censure of independent media.516","unnumbered":true},{"id":"a-hrc-42-crp-2-p0113","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":112,"section":"B. Significant developments since 2015 and the current Burundian context","text":"497. CENI is therefore not perceived as a body capable of fulfilling its mission in a\nneutral and independent manner. This perception further damages the population and\npolitical actors’ trust in Burundian institutions and their ability to guarantee that the next\nelections will be fair and credible.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0114","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":113,"section":"B. Significant developments since 2015 and the current Burundian context","text":"3.   Misuse of history for political purposes","unnumbered":true},{"id":"a-hrc-42-crp-2-p0115","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":114,"section":"B. Significant developments since 2015 and the current Burundian context","text":"a)   Complexity of the ethnic issue\n498. In Burundi, issues on ethnicity are deeply tied to the country’s history. No matter the\norigin of ethnic differences, a colonial legacy 517 or a socio-traditional fact often used as a\nmeans to an end, it is nonetheless one of the aspects which have marked the recent history of\nthe country. As a matter of fact, since independence, violence and political unrest that caused\nnumerous human rights violations had generally an ethnic dimension. Presently, ethnic\norigin, which is traditionally determined by the father’s one, has become a social reality\nexperienced by the majority of Burundians and one of the most important identification\nelements alongside the clan and the region of origin.\n499. This ethnic dimension has been taken into account in the Arusha Peace Agreement\nand the 2005 and 2018 Constitutions, which all impose ethnic quotas in the defence and\nsecurity forces and in Parliament. The 2018 Constitution went even further as it establishes\nquotas in the judiciary, and then Government imposed such quotas on international NGOs as\nwell.518 These latest developments may sound contrary to the message repeated in the\nspeeches of the Head of State, where he says ethnic groups are a colonial making void of any\nstrong backing.\n500. Whatever the case, atrocity crimes based on ethnicity left a legacy of suspicion and\nresentment vis-à-vis the other ethnic group amongst many Burundians. In the absence of a\ngenuine reconciliation process and transitional justice, through which a historical account\nacceptable to the majority of both groups would be reached, there has been a tendency by\neach group to create its own memory, necessarily partial.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0116","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":115,"section":"B. Significant developments since 2015 and the current Burundian context","text":"b)   Absence of reconciliation and transitional justice process\n501. Following the Arusha Peace Agreement, the international community has deployed\nnumerous measures to support the establishment of a transitional justice process that would\nlead to the introduction of measures to promote the search for truth, justice, reparation for\nvictims, and prevention of subsequent atrocity crimes, and which would have “laid the\ngroundwork for national reconciliation”. However, Burundian authorities only established a\nTruth and Reconciliation Commission (CVR) in 2014 519 while the international judicial\ninvestigation commission, also provided for, is yet to be put in place.\n502. The composition of CVR was criticised from the onset because it had no member\nfrom the civil society, thus it lacked “the required confidence and credibility”.520 In addition,\nany potential judicial proceedings were postponed by Government until the conclusion of the\nwork done by CVR, which translates into an extension of the provisional immunity granted\nby the Arusha Agreement to those suspected of crimes. In 2018, by the end of its four-year\nterm, CVR reported to have heard 70,000 victims and witnesses of the crises which marked\nBurundi since 1962, and identified close to 20,000 alleged suspects and 4,000 mass graves.521\nThe work done by CVR is a priori quantitatively impressive. It was however criticized for\nnot being conducive to the victims’ involvement in the proceedings because of their fear of\nreprisals in the absence of protective measures offered to the victims, while the alleged","unnumbered":true},{"id":"a-hrc-42-crp-2-p0117","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":116,"section":"B. Significant developments since 2015 and the current Burundian context","text":"perpetrators are either in power or involved in the procedures. More generally, the lack of\ninformation on the process did not help in alleviating the victims’ mistrust in the said\nprocess.522 In addition, CVR did not take into consideration the traditional obstacles\npreventing women from taking part in the process at the community level, thus neglecting to\nintegrate a gender dimension in the process.523\n503. Considering the results produced by CVR, the Parliament decided to renew the\nCommission’s mandate for another four-year term, which is renewable, and entrusted it with\nthe mission of “investigating and shedding light on serious human rights and international\nhumanitarian laws violations perpetrated from 26 February 1885 to 4 December 2008”, thus\ncovering the colonial era. It is also requested to rewrite the history of the country. 524\n504. It is relevant to carry out such a task to establish a common historical narrative and\nnational history, considering that currently each group has its own distinct and selective\nmemory, which has instilled fear, lack of trust and suspicion between ethnic groups. 525\n505. The President of CVR, Pierre Claver Ndayicariye, officially announced he wishes to\nfulfill the mandate given to the Commission in order to contribute to the national\nreconciliation. He admitted that “the burden of such a painful past seriously weighs on the\npopulation in general. This burden is so heavy to bear that it materializes exceptionally during\nspecific periods of the year, around 29 April or 21 October, depending on the year and the\ngrieving memories, when some victims’ organizations commemorate in their own way, the\nsad events which claimed the lives of their loved ones. Looking into the dark side of our\nhistory, one thing is obvious: Burundians from every ethnic group and every region are\naffected”.526\n506. However, Pierre Claver Ndayicariye is neither known for being impartial, nor\nindependent from the Government. He was the President of CENI from 2010 to 2015, and\ntherefore organized and supervised the controversial presidential election of 2015. He\nrecently took a clear stance against journalists who reported human rights violations in\nBurundi, calling them: “Merchants of lies, you are doing a dirty job. You are a shame to\nhumanity”.527 In April 2019, he stated: “Between April and May 2015, political and\ndiplomatic manipulation received substantial funding in Burundi. The intensification of the\nplot against Burundian people passed through media disinformation”.528 Such statements as\nwell as his past allegiance raise some doubts about his ability to adequately accomplish his\ntask in an independent, impartial, and neutral manner, especially when it comes to recording\nhistorical facts which could finally help Burundian achieve a common vision of events that\ncould be taught to future generations.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0118","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":117,"section":"B. Significant developments since 2015 and the current Burundian context","text":"c)   Teaching of history in Burundi\n507. Teaching history as a school subject is generally a means to convey “collective\nmemory” or “collective identity” which helps to develop social cohesion through a sense of\nbelonging alongside values that are a foundation of a national identity. Several countries\nwhose history has been marked by difficulties and dissensions have decided not to teach\nhistory at all, or to teach only the pre-conflict period. However, such measures do not prevent\nthe prevalence of often selective, traumatizing, and dramatic informal recounts in family\nsettings and communities, thereby perpetuating former divisions and stereotypes, and\ninstilling fear and mistrust.529 For instance, refugees who were victims of atrocity crimes and\nwho lost their properties in 1972, have created narratives that circulate in refugee camps in","unnumbered":true},{"id":"a-hrc-42-crp-2-p0119","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":118,"section":"B. Significant developments since 2015 and the current Burundian context","text":"Tanzania. These narratives tend to foster ethnic divisions and related stereotypes in a climate\nof fear, victimization and suspicion. This narrative was brought into Burundi after the civil\nwar and can be heard in many speeches of current Government officials.530\n508. For a long period of time, Burundi chose not to introduce the country’s recent events\ninto school curriculum.531 A witness recounts that:\n“History curriculum was elaborated many years ago [...] I studied history in 1997\nand I know it has not changed since then. In this school curriculum, students are\ntaught the various successions of kings right up to the last one in 1961 and the\nPresidents who served, but all that happened after 1962 is left out”.532\n509. Since CNDD-FDD took power, and especially since the 2015 crisis, some teachers\nhave been discussing the 1973 and 1993 crises, which are not officially in the school\ncurriculum. They usually do it of their own volition with the political objective of convincing\nstudents of the need to maintain CNDD-FDD in power, and of recruiting them into the party.\nSimilar approaches are very common in countries led by authoritarian regimes or in conflict\ncountries as they tend to politicise the teaching of history “by intentionally using biased\nstatements to create division in a bid to perpetuate enabling circumstances to maintain a status\nquo in the current distribution of power (political and economic) in place. In this case,\neducation is used as a tool to create and develop social cleavages which constitute the root\ncause of intolerance, resentment, reinforced inequalities and forms of marginalisation (since\naccess to education and curricula has been altered), thereby increasing risks of future atrocity\ncrimes and violence”.533 A witness reported on the content of recent lessons that:\n“[The history teacher] explained the history of Burundi in a way that portrays\nCNDD-FDD as a good thing, but what he said was not all necessarily true. There was\na crisis in 1972 in Burundi which claimed the lives of many on both sides, and many\nHutus fled the country to resettle elsewhere as refugees. [The history teacher] tells\nstudents [...] that the Tutsis beheaded the Hutus, seized their property and drove them\nout of the country. [...] He then went on to invite students to join CNDD-FDD,\nbecause it is thanks to this party that the Hutus can live peacefully in the country [...]\nHe always blamed the Tutsis for what happened without mentioning what the Hutus\nthemselves did. What he says about the Tutsis is correct, but not saying what the Hutus\ndid is evidence that they want to portray CNDD-FDD party as good and Tutsis as\nbad”.534","unnumbered":true},{"id":"a-hrc-42-crp-2-p0120","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":119,"section":"B. Significant developments since 2015 and the current Burundian context","text":"d)   Use of history to achieve political gains\n510. There is a version of the country’s history which has been established as true and\ndisseminated by the Head of State himself, especially during his moralization sessions where\nhe teaches the “true” history of Burundi. He explained that: “through the patriotic and civic\neducation training programme, we have helped Burundians to separate the wheat from the\nchaff, to know the secrets and history of our country, and encouraged them to leave a strong","unnumbered":true},{"id":"a-hrc-42-crp-2-p0121","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":120,"section":"B. Significant developments since 2015 and the current Burundian context","text":"legacy behind”.535 He also stated that “from 1962 through 1993, despite being independent,\nBurundians had not enjoyed the freedom they so longed for. Strangers still had a strong grip\non Burundi. This could be seen through regimes that were supported by colonisers and\nbrought to power through military coups, not allowing citizens the least opportunity to\nmanage their affairs themselves. Since these regimes were characterized by dictatorship and\nall sorts of social discrimination as in the colonial era [...] the battle to regain and maintain\nan effective independence continued. Thus, patriotic Burundians demonstrated once again in\n2005 that they wanted their independence by getting rid of dictatorial regimes which had\ntaken power by force”.536\n511. Other persons close to the Government have also relayed simplified versions of the\ncountry’s recent history aligned with the President’s narrative that Burundi achieved real\nindependence only after CNDD-FDD came to power in 2005, all previous Governments\nbeing labelled as “putschist, genocidal, or dictatorial Governments, marked by nepotism”.537\n512. In the presentation of chronological historical facts in Burundi by the President’s\nCommunication Adviser during a Conference on the 2020 elections, held in Gitega on August\n2019, there was an obvious imbalance in the manner to present Hutus and Tutsis victims:\n“1965 - Decapitated democracy\n1969 - Killing of high-ranking Hutu military officials\n1972 - Hutu genocide (300.000 Hutus & 5.000 Tutsis)\n1988 - More than 50,000 Hutus killed by napalm\n1993 - Decapitated democracy re-established\n2015 - Failed military coup”.538\n513. Each group having its own collective memory and the commemoration of only a few\nselected events while denying the victimhood of the other group pose a real danger. For\nexample, the commemoration of the massive slaughter of a hundred Hutu students in 1995\nwas organized in 2019 by the University of Burundi, for which classes were suspended.539 On\nthis occasion, the Association of Survivors of the June 1995 massacre decided to erect a\nmemorial plaque, even though this runs counter to the will of CVR to have a common\nremembrance place for all victims.540\n514. The President of the National Council for National Unity and Reconciliation 541,\nAmbassador Guillaume Ruzoviyo, obviously foresaw this danger as he called for the\nestablishment of “collective commemoration” days for past crises in order to speed-up the\nreconciliation process in Burundi. He emphasised that “commemorations based on ethnic\nmotives where each ethnic group will discreetly organize its own commemoration events,\nneed to stop at all costs. […] This stage of the national reconciliation process […] could be\nconsolidated through the erection of ‘collective monuments of national importance’ for past\ncrises”.542\n515. The adoption of an official selective version of the country’s history tends to\ncrystallise past grievances, thereby contributing to maintain divisions which some people\nmay use to achieve their political objectives with the possibility of having serious\nconsequences. For instance, the decision by the President to glorify “the heroic personality\nof Lieutenant-General Adolphe Nshimirimana” by renaming the road formerly known as","unnumbered":true},{"id":"a-hrc-42-crp-2-p0122","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":121,"section":"B. Significant developments since 2015 and the current Burundian context","text":"route du 3 September after him,543 despite the fact that this former Head of SNR and informal\nleader of the Imbonerakure, close to President Nkurunziza, who was murdered on 2 August\n2015, is a controversial character in Burundi since he was accused by many human rights\ndefenders of being involved in multiple cases of human rights violations, especially since the\nbeginning of the 2015 crisis.\n516. The latitude of CVR to “rewrite” the country’s recent history in a bid to contribute\nto the national reconciliation therefore appears to be quite limited.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0123","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":122,"section":"B. Significant developments since 2015 and the current Burundian context","text":"4.   Security uncertainties","unnumbered":true},{"id":"a-hrc-42-crp-2-p0124","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":123,"section":"B. Significant developments since 2015 and the current Burundian context","text":"a)   Existence of armed opposition groups\n517. Several Burundian armed opposition groups,544 mostly present in Eastern Democratic\nRepublic of the Congo (DRC), Rwanda, and Uganda announced from time to time that they\nwould resort to taking up arms to “settle” the situation in Burundi by putting an end to\nPresident Nkurunziza’s regime, especially given the lack of prospective peaceful solution to\nthe crisis which began in 2015, as well as to “protect the population”.545 Although the\nCommission has not received reports of either recent attacks or incidents on the Burundian\nterritory by any of these armed groups, it is very concerned about these announcements and\ntheir possible manifestation.\n518. Among the major Burundian armed groups, there is the Resistance Group for the\nRule of Law (RED-Tabara) constituted of Burundian citizens, among whom demobilized\nfighters, police officers and army deserters, including civilian activists and youths from the\nopposition movement.546 This group has 500 to about 750 men dispatched across three\nbrigades in the DRC.547 Some hours after the attack on Ruhagarika, Buganda commune,\nCibitoke province, in the night of 11 to 12 May 2018, which claimed the life of 24 people,\nthe Government accused RED-Tabara to be the perpetrator, but Red-Tabara rejected that\naccusation. According to the Group of Experts on DRC, most of RED-Tabaras new recruits\nwould be coming from Burundi or from Burundian refugee camps, and receive upon arrival\nin the DRC, some military training including firearms handling and tactics. The RED-Tabara\nallegedly benefit from the support and funding from contacts in Burundi and other European\ncountries.548 They allegedly collaborate with local armed groups like the Maï-Maï Kihebe\nsince 2017 from whom they gather local intelligence and have safe passage of food and\nsupplies, as well as the Maï-Maï Mushombe since 2018 at least, who fought by their side\nduring a raid by the Burundian Army and Imbonerakure.549\n519. The Republican Forces of Burundi (FOREBU) are mainly made up of former\nmilitary officers who fled after the failed military coup of 13 May 2015. They are settled\nmostly in the territories of Uvira and Fizi in DRC. Some rough figures show that they had\nbetween 300 and 500 men by May 2017 including some RED-Taraba deserters. Since\n2017, the Congolese army organized several attacks against FOREBU and detained tens of\nfighters.550\n520. While RED-Tabara and FOREBU are both facing difficulties to get funding sources\nand buy weapons, they have not been able to agree on issues pertaining to command and","unnumbered":true},{"id":"a-hrc-42-crp-2-p0125","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":124,"section":"B. Significant developments since 2015 and the current Burundian context","text":"control.551 However, there is some level of cooperation between these two groups as they\nmeet periodically to exchange information and intelligence.552\n521. The Nzabampema wing of the National Liberation Forces (FNL) has settled in the\nUvira territory in DRC, particularly on the high plateaus and plains of the Rusizi River.\nAccording to the Group of Experts, following the high number of Burundian Army deserters\nin early 2016, they have about 400 fighters. 553 In its May 2016 report, the Group of Experts\nindicated that this armed group recruited in the Burundian communities living around the\nRukoko forest area (north of the capital) and in refugee camps in South Kivu.\n522. Available information on the strength of these armed groups, in men, weapons,\nequipment, and financial resources, as well as their potential political support are limited. It\nis therefore difficult to estimate accurately their capacity to conduct large-scale attacks on\nBurundian territory. According to several analysts, due to their constant reorganization and\ndifficulty to move in Burundi, as well as to acquire weapons and supplies, these armed\nopposition groups might not be presently in a position to have a real impact on the situation\nin Burundi.554\n523. Nevertheless, Burundian authorities are very concerned about these armed groups\nand the eventual support they may have from the population. Case in point: the many young\nmen coming back home from a trip or a journey abroad, who were accused of supporting or\ncooperating with one of these rebel groups.\n524. The Group of Experts on the DRC equally recorded that some soldiers of the\nBurundian Army (FDN), alongside Imbonerakure were sent to fight these armed groups in\nEastern DRC. There was a series of confrontations between the FDN and RED-Tabara in\nSouth Kivu in October and November 2018, in Kabere (Uvira territory) and its surroundings,\nand in January and February 2019 in Mulenge (Uvira territory) and its surroundings. These\nbattles led to an increase in the number of displaced persons from 12,000 in November 2018\nto 25,000 in January 2019. The FDN and Imbonerakure received support from at least two\nlocal armed groups: the Maï-Maï Mbulu and the Maï-Maï Kijangala. The former served as\nguides to lead them to the positions of the latter, which then provided them with intelligence\nabout and led them to RED-Tabara sites. They might have even fought on their side in\nexchange for food, cash, ammunitions, and thereafter, weapons. Thus, the Group of Experts\nconsidered that the Burundian Government violated the sanctions regime on firearms. 555\n525. On 6 February 2019, the DRC Armed Forces (FARDC) launched an operation\nagainst rebel groups acting in the high plateaus of the Uvira territory including Burundian\ngroups. The FDN and Imbonerakure retreated back to Burundi during that same period.\nCaptives from these Burundian armed groups who were arrested or surrendered were directly\ntransferred to Burundi. The Burundian Government denied having sent soldiers in DRC.556","unnumbered":true},{"id":"a-hrc-42-crp-2-p0126","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":125,"section":"B. Significant developments since 2015 and the current Burundian context","text":"b)   Regional tensions\n526. According to the Group of Experts on the DRC, regular incursions into rebel\npositions by FDN and Imbonerakure coupled with their association to some Maï-Maï armed\ngroups of the Uvira midpPlateaus have worsen the already tense and violent relations\nbetween and within local armed groups. In the middle of these groups fighting each other,\nthere is risk of retaliation with detrimental consequences on civil population, peace and\nsecurity in DRC.557","unnumbered":true},{"id":"a-hrc-42-crp-2-p0127","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":126,"section":"B. Significant developments since 2015 and the current Burundian context","text":"527. Moreover, the Burundian Government maintains strained relations with Rwanda, by\nconstantly accusing the country of being responsible for the Burundian crisis and of trying to\ndestabilize the country, forcefully holding back Burundian refugees in its territory, and\nrecruiting young Burundians into armed rebel groups.558 President Nkurunziza went as far as\ncalling for a Summit to end the “conflict” with his Rwandan “enemy”.559 Thus, on 4\nDecember 2018, the Burundian President sent a letter to the Ugandan President Yoweri\nMuseveni, Acting President of the EAC and Mediator of the crisis in Burundi. Therein, he\ndenounced the Final Report of the inter-Burundian Dialogue Facilitator, M. Mkapa, who\nconsidered the situation in Burundi as still alarming, although the problem was a regional\none, in which “Rwanda is attempting to destabilize Burundi”. This strained relation has an\nimpact on cross-border trade.560 The Ugandan President replied to him on 8 December 2018\nby recalling the importance of the Arusha Peace Agreement guaranteed by the international\ncommunity and the responsibility of political leaders to find solutions to crises. This\nepistolary exchange made public led to strained diplomatic relations between both countries,\nparticularly on border-crossing issues, but they did not last for long.561\n528. Finally, many Burundian refugees in neighbouring countries told the Commission\nthat they fear for their lives due to the alleged incursions of Imbonerakure and Burundian\nSNR officials in some refugee camps. They are suspected of looking for those who fled the\ncountry - mainly wanted political opponents and persons formerly close to the Government -\nin order to kill them. Refugees had stories about various security incidents which occurred in\nrefugee camps perpetrated by “infiltrated” Burundian agents. In other cases, these emissaries\nwere trying to convince and force refugees to return to Burundi.562","unnumbered":true},{"id":"a-hrc-42-crp-2-p0128","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":127,"section":"B. Significant developments since 2015 and the current Burundian context","text":"c)    Uncertainties about the behaviour of defence and security forces and other related bodies\n529. The Head of State made the following announcement in early 2019: “We will build\nthe capacities of the defence and security forces and we will provide them with adequate\nequipment and material for them to face any difficult situation in the best possible\nmanner”.563 However, he did not give details as to which forces shall be the first beneficiary\nof these measures as their situations vary, particularly in terms of their closeness to the\nPresident.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0129","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":128,"section":"B. Significant developments since 2015 and the current Burundian context","text":"(i)     The Army\n530. The Burundian Army, called National Defence Force (FDN), has been considered as\nthe country’s stabilizing factor since the Arusha Peace Agreement under which it was turned\ninto a multi-ethnic, apolitical and professional force. While enjoying the benefits of a good\nreputation which enabled them to take part in UN and AU peacekeeping operations, soldiers\nhad an enviable social and economic status in Burundi. In the beginning of the crisis in 2015,\nsoldiers demonstrated their professionalism when they refused to shoot the crowds during\nprotests and even went on to protect them against the police and Imbonerakure.564\n531. The rotational deployment of soldiers in peacekeeping missions is a strategy\nintroduced by the Burundian Government since 2007 to gain their loyalty. This is because\nthese deployments constitute a significant financial manna for soldiers, while benefiting\nGovernment as well. Thus, in an army with a total of 30,000 men, close to 5,000 are deployed\non a nearly constant basis in peacekeeping missions, particularly in the AU Mission in","unnumbered":true},{"id":"a-hrc-42-crp-2-p0130","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":129,"section":"B. Significant developments since 2015 and the current Burundian context","text":"Somalia (AMISOM), but also to a limited extent in the United Nations Multidimensional\nIntegrated Stabilization Mission in the Central African Republic (MINUSCA). Each\nAMISOM Burundian soldier officially earns USD 800 that is almost ten times more than\nwhat he earns back home. The deployment of Burundian troops in Somalia is financed by the\nEuropean Union through the African Union, who then disburses the funds to the Burundian\nGovernment that redistributes them to the deployed soldiers, after making some deductions.\nDespite the Government deductions of USD 200, salaries are still enticing.565\n532. Despite its positive image, the Army has always been under a parallel command\nsystem close to CNDD-FDD, comprising former rebels, and the synergy between them and\nex-FAB soldiers566 is still superficial. After the attempted coup of 13 May 2015, the Army\nwas deeply divided. This exposed the underlying dissensions among soldiers and high-\nranking officers from the rebellion, some of whom led the failed coup. Since then, the\nGovernment has tried to regain control of the Army by restructuring its command and putting\nin place several services like reserve units and the National Youth Service, which could help\nin placing some Imbonerakure. Tens of ex-FAB soldiers, often officers, who are considered\nas opponents by the Government, as well as some officers from armed and political\nmovements of the former Hutu rebellion such as the FNL, were transferred, replaced, or\nplaced on retirement. Some were even abducted, arrested, tortured and at times killed. The\nnumber of soldiers including officers who have deserted the Army since the beginning of the\n2015 crisis, including at the end of their deployment abroad, is estimated between 600 and\n2,000 men. Some are thought to have joined armed rebel groups in neighbouring countries.567\n533. Notwithstanding, the Government decided not to look into the involvement of some\nof the Hutu militaries who are members of CNDD-FDD in the attempted coup of 13 May\n2015. They maintained their various positions due to the strong support they have among\nsoldiers who are former FDD rebels and which dates as far back as the days of the rebellion.\nThus, keeping these individuals in the Army and under the Government control was seen as\na way of reducing further desertions.568\n534. Considering that the number of Tutsis entering the military academy is low, while\nex-FABs are placed on retirement or progressively excluded, the 50-50 ethnic balance within\ndefence and security forces provided for by the Arusha Peace Agreement and the Constitution\nis no longer respected569.\n535. The decision of the African Union that only the Burundian Troops would be affected\nby the Security Council’s decision to reduce by 1,000 troops the total number of AMISOM\nsoldiers, was very badly received by the Burundian soldiers and Government. The Head of\nState tried to get this decision revised by refusing to repatriate his soldiers, and even going\nas far as to threaten to remove all the Burundian soldiers from Somalia. He finally gave up\nand repatriated the 1,000 militaries.570 Some political analysts are of the opinion that the AU\ndecision was linked to the Burundian Government’s intransigence with regards to the holding\nof an inclusive inter-Burundian dialogue. It would seem that many soldiers shared this\nopinion and hold the Government accountable for this loss of lucrative deployment\nopportunities. It would appear they made it clear during the last referendum by massively\nvoting “no” to a constitutional amendment.571 The recent decision of the Security Council to","unnumbered":true},{"id":"a-hrc-42-crp-2-p0131","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":130,"section":"B. Significant developments since 2015 and the current Burundian context","text":"further reduce the number of AMISOM soldiers by 1,000 men by 28 February 2020 can only\nbe a source of additional concern for them. 572 This occurs at a time when participation of the\nBurundian Army in peacekeeping operations financed by the European Union and the UN is\nincreasingly decried by international non-Governmental organizations and Burundian human\nrights defenders.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0132","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":131,"section":"B. Significant developments since 2015 and the current Burundian context","text":"(ii)   The police force\n536. The Burundian National Police Force (PNB) is marked by the absence of team spirit,\nalthough the Arusha Peace Agreement provides an integration process of fighters from\nvarious armed political movements alongside a fusion of the former various police forces\nwhich had been managed separately by various Ministries. These include the gendarmerie,\npenitentiary police, judicial police, air and border police, and public security police. The\nprocess induced a mixing rather than integration of forces, and original solidarities led to the\nestablishment of parallel command structures, thus making more complex hierarchical\ncontrol of already complex police forces. In fact, some units, such as the one in charge of\nprotecting institutions (API), are de facto attached to the President of the Republic and not\nthe Minister of Public Security. The Director General of the Police does not have direct\ncontrol over all the police forces due to the numerous Directorate Generals found within the\nMinistry of Public Security. “There is a spirit of victor and vanquished which has\nprogressively gained grounds in the management and functioning of the Police. Former rebels\nremain the protégés and defenders of the political regime”.573 Not only is the police under the\nexecutive power more than the Army is, but it has absorbed a great number of CNDD-FDD\nfighters, and ethnic quotas provided for by the Constitution and the Arusha Peace Agreement\nare no longer respected. Its infamous generalized impunity and corruption makes it a security\nforce which has lost the confidence of the population.\n537. In 2005, mixed human security committees were established in some provinces as\nexperiment to narrow the gap between the police force and the population. They comprised\nrepresentatives of the “four pillars of security”, that is the police, the Administration, the\nJudiciary, and the population, including civil society representatives. These Committees were\nto provide a framework for early warning and prevention in terms of security. In 2014, an\norder signed by the Minister of Interior and the Minister of Public Security extended these\nCommittees to all the provinces and diversified and extended their missions to dozens of\ndiverse tasks, such as protecting the population against political and economic threats;\nenforcing the principle of accountability, transparency and answerability to the population;\nupholding human rights; investing in patriotic education; as well as information about the\nelectoral process and family planning.574\n538. Imbonerakure quickly took-over control of these mixed security committees, as civil\nsociety representatives. As a result, these committees became “places where the misconduct\nof the ruling party’s youth wing was justified”. On a regular basis, some Imbonerakure\nreplaced police officers on the field, conducting patrols, arrests and detentions, and\ncommitting crimes which are supported by administrative authorities, because they are\nmembers of the mixed security committees. With time, Imbonerakure went as far as defying\nthe authority of the police, the local Administration, and even the Judiciary.575\n539. Even though the police is in principle considered close to the ruling party, it is de facto\nmarginalized in some parts of the country where its missions have been taken over by the\nImbonerakure who no longer show respect towards the police and do not hesitate to oppose\nits members. Beyond any doubt, this situation has an impact on the motivation of police\nofficers and internal dynamics of this Force.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0133","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":132,"section":"B. Significant developments since 2015 and the current Burundian context","text":"(iii)   The SNR\n540. Until June 2018, the SNR was part of the established defence and security forces\nand as such, under the authority of the Government and the civilian oversight of Parliament.\nThis was despite the fact that its budgets for functioning and equipment were incorporated in\nthe President of the Republic’s budget. The 2018 Constitution places SNR outside the\nestablished defence and security forces, and as such is de facto exempted from civilian\ncontrol and the 50% Hutus and 50% Tutsis ethnic quotas within defence and security forces\nenshrined in the Constitution. The SNR is now under the direct authority and control of the\nPresident.576\n541. On 7 June 2019, the Burundian Senate adopted two bills related to SNR presented\nby the Minister of National Defence: the organic bill on the missions, organization and\nfunctioning of SNR and the bill to amend law n°1/05 of 2 March 2006 laying down the\nstatutes of SNR agents. The Minister explained that the first bill was necessary to modernize\nSNR in a bid to make it a professional and efficient force, capable of living up to national\nsecurity challenges. Among the main innovations, the law would comprise the maintenance\nof secrecy about the SNR missions, from budgetary preparation to agents’ protection for\nservice purposes and State security. It will also comprise widening the scope of SNR missions\nin order to fight current and potential threats to State security taking into consideration\nscientific and technological progress. The second bill aims to satisfy the need to provide the\nSNR officials with some incentives and guarantees of a more stable career. 577\n542. Thus, SNR is a force with a special statute as compared to that of the police or the\nArmy, and it is the only one with a formal direct relationship with the President of the\nRepublic. This sudden reorganization of security forces, which has not been explained or\njustified, is a cause for concern.\n543. There are still some uncertainties as to the potential role of these defence and\nsecurity forces in the upcoming elections. For example, there is a group called “Defence and\nSecurity Forces” (FDS) created in 2019, which presents itself as comprising acting police\nand army officials. It stated that it is fighting against “dictatorship and tyranny” from\nPresident Nkurunziza and called on all members of the defence and security forces to join\nthem as the cohesion and professionalism of those forces have been impacted by President\nNkurunziza’s divisive policy.578 Such statements once again shed light on possible underlying\ntensions.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0134","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":133,"section":"C. Risk factor indicators","text":"544. This review of most significant developments makes it possible to identify\nindicators that are themselves linked to the eight common risk factors identified in the\nFramework of Analysis for Atrocity Crimes.\n545. Insecurity creates an environment that is conducive to atrocity crimes (risk factor 1).\nThe existence of such an environment is suggested by the following indicators: many\nBurundians, both in the country and abroad, are living through a humanitarian emergency\n(risk factor 1 (c)); the transfer of power of 2015 triggered a major political crisis that has not\nyet been resolved (risk factor 1 (d)); there is a risk of political instability caused by probable\npower struggles within CNDD-FDD and by the existence of armed opposition movements\n(risk factor 1 (e)); political tension is being generated by an autocratic regime that engages\nin severe political repression of all its opponents, real or perceived (risk factor 1 (f)); there is\neconomic instability caused by scarcity of resources (risk factor 1 (g)), a severe crisis in the\nnational economy (risk factor 1 (h)) and the acute poverty of the population (risk factor 1 (i)).","unnumbered":true},{"id":"a-hrc-42-crp-2-p0135","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":134,"section":"C. Risk factor indicators","text":"546. Risk factor 2 is related to a history of serious human rights violations that, because\nthey have not been prevented or punished, create a risk of further violations. The presence of\nthis risk factor is revealed by the following indicators: past or present serious human rights\nviolations (risk factor 2 (a)); acts of genocide, crimes against humanity and war crimes that\nhave marked the country’s recent history (risk factor 2 (b)); a policy or practice of impunity\nfor or tolerance of serious human rights violations (risk factor 2 (c)); the refusal or reluctance\nof the Government of Burundi to use all possible means to put an end to serious human rights\nviolations (risk factor 2 (d)); the continuation of support by the Burundian authorities for\ngroups accused of involvement in violations and the failure to condemn their actions (risk\nfactor 2 (e)); the Government’s refusal to acknowledge serious human rights violations or its\nbiased accounts thereof (risk factor 2 (f)); the absence of genuine reconciliation or transitional\njustice processes and the politicization of the work of the new Truth and Reconciliation\nCommission (risk factor 2 (g)); widespread mistrust of State institutions, particularly the\nsecurity forces and the judicial system, as a result of impunity (risk factor 2 (h)).\n547. Risk factor 3, the weakness of State structures, which negatively affects the capacity\nof a State to prevent, halt or prosecute atrocity crimes, is also present. National institutions,\nparticularly the judicial, law enforcement and human rights institutions, lack sufficient\nresources and adequate representation (risk factor 3 (b)); the justice system is neither\nindependent nor impartial (risk factor 3 (c)); 579 civilian control of the security forces (by\nParliament) is not effective (risk factor 3 (d)); there are high levels of corruption or poor\ngovernance (risk factor 3 (e)); 580 the internal oversight and accountability mechanisms\nwhereby victims can seek recourse for their claims are inadequate or ineffective, and the\nexternal mechanisms are virtually non-existent or almost inaccessible to victims (risk factor\n3 (f)).\n548. Risk factor 4 is the existence of reasons, aims or drivers that justify the use of\nviolence against particular groups. From an early warning perspective, it is important to be\nable to identify motivations or drivers that could encourage groups to resort to widespread\nviolence in an attempt to achieve their goals. This factor is shown to be present by: politically\nmotivated acts that, as regularly recalled by members of the Government and CNDD-FDD,\nare aimed at the consolidation of power (risk factor 4 (a)); economic interests linked to the\npreservation of power, as power is the key to control over the distribution of resources (risk\nfactor 4 (b)); real or perceived threats to the interests or objectives of the Government,\nincluding any form of disloyalty to the CNDD-FDD cause (risk factor 4 (e)); real or perceived\nmembership of or support for armed opposition groups (risk factor 4 (f)); the ideology of\nCNDD-FDD, characterized by a view of the party as the embodiment of truth and thus belief\nin the supremacy of this political identity (risk factor 4 (g)); the politicization of past\ngrievances, tensions or cases of impunity (risk factor 4 (h)); social trauma caused by past\nincidents of violence that, not adequately addressed, have aroused feelings of loss,\ndisplacement, injustice and a possible desire for revenge (risk factor 4 (i)).\n549. Risk factor 5 refers to the capacity of potential perpetrators to commit atrocity\ncrimes. This factor must be assessed in conjunction with other factors, such as those related\nto intent and motivation. In Burundi, this factor is gauged by: the availability of personnel\nand of arms and ammunition or of financial resources, public or private, for their procurement\n(risk factor 5 (a)); the capacity to transport and deploy personnel and to transport and\ndistribute arms and ammunition (risk factor 5 (b)); the capacity to encourage or recruit large\nnumbers of supporters – Imbonerakure, for example – from populations or groups and the\navailability of the means to mobilize them (risk factor 5 (c)); a strong culture of obedience to\nauthority and group conformity, a culture by which CNDD-FDD and the Imbonerakure are\ncharacterized (risk factor 5 (d)); the presence of or links with other armed forces or with non-\nState armed groups (risk factor 5 (e)).\n550. Mitigating factors are the internal and external elements that can contribute to\npreventing an escalation of violence, ending it or lessening its impact. The absence of such\nfactors (risk factor 6) in Burundi is significant, as demonstrated by: the lack of a strong,\norganized and representative national civil society and of a free, diverse and independent","unnumbered":true},{"id":"a-hrc-42-crp-2-p0136","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":135,"section":"C. Risk factor indicators","text":"national media (risk factor 6 (b)); the lack of access to international media (risk factor 6 (c));\nthe limited presence of the United Nations, international NGOs or other international or\nregional actors in the country with access to the people (risk factor 6 (d)); the lack of exposure\nto, openness towards or establishment of political or economic relations with other States\n(risk factor 6 (f)); the limited or even non-existent cooperation with international and regional\nhuman rights mechanisms (risk factor 6 (g)); the Government’s unwillingness to engage in\ngenuine dialogue to resolve the 2015 crisis, make concessions or receive support from the\ninternational community (risk factor 6 (h)); the lack of a warning mechanism, as the National\nObservatory for the Prevention and Eradication of Genocide, War Crimes and Other Crimes\nagainst Humanity does not serve as an independent mechanism of that sort (risk factor 6 (k)).\n551. Risk factor 7 refers to enabling circumstances or preparatory actions, whether\nsudden or gradual, that provide an environment conducive to the commission of atrocity\ncrimes or suggest that they may occur. The main indicators of this risk in Burundi are: the\ninterference with vital State institutions, or measures that result in changes to their\ncomposition or balance of power, as is the case with regard to ethnic quotas (risk factor 7\n(b)); the strengthening of the security apparatus or its reorganization or mobilization (risk\nfactor 7 (c)); the expulsion or refusal to allow the presence of NGOs, international\norganizations, media or other relevant actors, or the imposition of severe restrictions on their\nservices and movements (risk factor 7 (g)); the increase in the number of violations of the\nright to life, physical integrity, liberty or security of any person considered a political\nopponent since the onset of the 2015 crisis (risk factor 7 (h)); the increase in the number of\nserious acts of violence against women and children, or the creation of conditions that\nfacilitate acts of sexual violence against them, including as a tool of terror (risk factor 7 (i));\nthe increased politicization of identity, past events or motivations for violence (risk factor 7\n(m)); the increase in inflammatory rhetoric, propaganda campaigns or incitement to hatred\ntargeting anyone considered a political opponent since the onset of the 2015 political crisis\n(risk factor 7 (n)).\n552. Triggering factors (risk factor 8) are also present, as evidenced by the following\nindicators: measures taken by the international community are perceived by the Burundian\nauthorities as threats to State sovereignty (risk factor 8 (c)); there was an abrupt or irregular\ntransfer of power in 2015 (risk factor 8 (d)); attacks on the life, physical integrity, liberty or\nsecurity of leaders, prominent individuals or members of opposition groups have been\ncommitted (risk factor 8 (e)); there is hate propaganda targeting political opponents (risk\nfactor 8 (g)); presidential, parliamentary and local elections are scheduled for 2020 (risk\nfactor 8 (h)); the commemoration, along ethnic lines, of past crimes, traumatic or historical\nincidents that could exacerbate tensions between groups (risk factor 8 (k)); acts related to the\nprocess for determining accountability for past atrocities that could be perceived as unfair\n(risk factor 8 (l)).\n553. So far, the Commission had not considered that there has been a lack of support\nfrom neighbouring States when it comes to protecting populations at risk in need of refuge,\nparticularly through forced repatriation or aid restrictions, which is indicator (6 j ) related to\nthe absence of mitigating factors (risk factor n°6). However, the Commission is concerned\nby the announcement made by the Tanzanian Minister of Interior on 24 August 2019 that an\nAgreement had been reached between Tanzania and Burundi to organize the repatriation,\nincluding by force, of Burundian refugees and asylum seekers in Tanzania, despite the fact\nthat their security cannot be guaranteed considering the prevailing situation in Burundi, as\npreviously shown.581\n554. The Commission also considered that some indicators of these eight risk factors\nwere only partially met. For instance, records of a security crisis caused by, among other\nfactors, denunciation of peace agreements (indicator 1 b) of risk factor n°1. In fact, the\nBurundian Government did not formally withdraw from the Arusha Peace and Reconciliation\nAgreement for Burundi signed in 2000, but the new Constitution of 2018 has de facto\nabolished some key provisions of this Agreement that were enshrined in the 2005\nConstitution. These include for instance the ethnic quotas within SNR and the full\nmembership to Senate for former Presidents, which can have important consequences.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0137","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":136,"section":"C. Risk factor indicators","text":"555. The Commission also considers that the absence of efficient measures to reinforce\nState institutions in Burundi is more a matter of lack of political will than lack of means to\nreform or reinforce those institutions, especially through regional or international support\n(indicator 3 i) of risk factor n°3 on the weakness of State structures.\n556. Lack of membership and effective participation of the State in international or\nregional organizations that establish mandatory membership obligations, (indicator 6 e) of\nthe absence of mitigating factors (risk factor n° 6) is partially met since Burundi has a\nselective approach as to its participation, but it is rather linked to its lack of cooperation with\ninternational and regional organizations, particularly when it comes to human rights.\n557. Finally, the Commission considers that the indicator on the creation of militias or\nparamilitaries groups, or an increased support towards these militias or groups (indicator 7 e)\nrelated to risk factor n°7 on enabling circumstances, is partially present. In fact, the\nCommission does not consider the Imbonerakure as a militia per say, given that they are not\nan armed paramilitary force organized like a professional army. Notwithstanding, they have\na paramilitary dimension and many aspects of the way they operate are similar to those of\nmilitias designed like “a paramilitary organization which constitute the base of some\ntotalitarian parties or dictatorships”,582 particularly those which are called “State militias,\norganized, recruited and for whom objectives and goals are set by the central Government\nitself. Based on a principle of “discharge”, the State bestows on a set of actors who then have\nlegal powers to use force, the heavy task to control and maintain peace and order. The set\nobjectives can be for defence or public purposes, such as ensuring the safety of citizens, as\nwell as of private individuals and criminals, thereby enabling the State to act according to the\nprinciple of plausible deniability of any implication in violence perpetrated on\npopulations”.583\n558. The Commission also noted that several factors of violence related to elections, both\nexternal and internal to the electoral processes 584, are also present. These are: unfavourable\nsocio-economic conditions; political and social exclusion (example of indicator: impunity,\npresence of long-standing rivalry between ethnic, religious, linguistic and cultural groups\nwhich have reached their apogee and have been materialised by violence during electoral\nperiods); conflicts related to the evolution of power relations (example of indicator: a new\nConstitution which changes the relative power of political actors; lack of, or inefficient\nmechanisms to promote a culture of dialogue among political parties; lack of press freedom);\ngender-based discrimination and violence; presence of non-State armed actors; complaints\nof genocide, crimes against humanity and war crimes; human rights violations; unethical\nmedia exposure; a disputed electoral law (example of indicator; the compliance level to\nregional and international electoral standards and obligations; the level of confidence in the\nelectoral law); poor performance of elections management bodies (OGE) (example of\nindicator; the level of confidence and reliability OGEs benefit from across the country; the\ndegree of independence and composition of OGEs; the level of impartiality of OGEs; and the\nlevel of transparency in the activities of OGEs); inadequate measures to guarantee elections\nare organized safely (example of indicator: the level of trust by populations in security\nagencies (ASS); the level of indebtedness of ASS; provocative and violent actions from\npolitical parties (example of indicator: intimidation, threats, destruction of properties, attacks\non physical integrity, abductions, killings and other acts of violence perpetrated against\nelectoral actors, journalists, potential registered voters and voters; psychological and physical\nviolence against vulnerable social groups such as women, children, ethnic and religious\nminorities, etc.; and the condition under which perpetrators of violence associated to political\nparties are sued).\n560. The Commission also took into consideration early indicators of conflict-related\nsexual violence identified in the matrix developed by UN Action against sexual violence in\nconflict (UN Action) in 2011585. The objective of this matrix is to help protection actors to","unnumbered":true},{"id":"a-hrc-42-crp-2-p0138","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":137,"section":"C. Risk factor indicators","text":"adjust their intervention strategies by taking proactive rather than reactive steps to prevent\nsexual violence, including in a context of political unrest.586\n561. The Commission notes that these early indicators of sexual violence are present in\nthe context currently prevailing in Burundi: women have been victims of intimidation or\nphysical violence, particularly sexual violence, for their (actual or perceived) participation in\npolitical activities related to the electoral process. This violence had as objective to punish\nthem for their (actual or perceived) participation in an electoral process or in political\nactivities. Moreover, the Commission also observes that there is a political context and a\nlegal framework which provide enabling circumstances for sexual violence as indicated by\nthe following indicators: cases of gender-based intimidation and electoral violence,\ninequality before the law related to the status and rights of women, and a discrepancy between\nlaw and practice regarding the security of women.587 The matrix further emphasises that: “The\nrisk of conflict-related sexual violence will be particularly acute in a context of collapse of\nrule of law, where there is a history of impunity for sexual violence and where the structures\nthat exist to protect the population and deter sexual violence are held in abeyance.\nImpunity/increased acceptance of sexual violence gives abusers a sense that, like the\nperpetrators of past crimes, they will go unpunished”, as it is the case in Burundi since\n2015.588\n562. The eight common risk factors identified in the Framework of Analysis for Atrocity\nCrimes are clearly present in Burundi, and there is a significant number of indicators for each\nof them. This also applies to violence factors during electoral processes and indicators of\nsexual violence. Although the presence of those risk factors does not make it possible to draw\nconclusions about the likelihood of such atrocity crimes be committed, and if so, when or in\nwhat way any such crimes could be committed, it gives the international community an\nobjective basis to grasp the reality of the situation in Burundi and the possible risks facing\nthe country. Finding that several risk factors indicating a possible degradation of the human\nrights situation in Burundi do exist, as well as risk factors of political violence, requires to\nkeep a close scrutiny on the developments in Burundi.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0139","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":138,"section":"V. Conclusions and recommendations","text":"563. In the light of its investigations, the Commission concludes that serious human\nrights violations – including crimes against humanity – have continued to take place\nsince May 2018, in particular violations of the right to life, arbitrary arrest and\ndetention, torture and other forms of ill-treatment, sexual violence, and violations of\neconomic and social rights, all in a general climate of impunity. Violations of civil\nliberties are also on the rise.\n564. The Commission remains the only independent and objective mechanism that\ninvestigates, documents and informs the international community about human rights\nviolations and abuses in Burundi.\n565. The crisis has been ongoing for more than four years, with no real prospects for\na resolution. The daily living conditions of Burundians, in the country or not, are\nbecoming worse and worse.\n566. The 2020 elections pose a major risk. To ensure that they are peaceful, fair, free,\ntransparent and credible, the Commission makes the following recommendations to the\nBurundian authorities:\na)     Give effect to all the Commission’s previous recommendations, which\nare more well-founded and relevant than ever, including those concerning priority\nmeasures to end human rights violations and international crimes, combat impunity","unnumbered":true},{"id":"a-hrc-42-crp-2-p0140","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":139,"section":"V. Conclusions and recommendations","text":"and improve the human rights situation in the country and the medium- and longer-\nterm recommendations on reforms to the legal framework and the judicial system; 589\nb)     Conduct prompt, independent and effective investigations into the cases\nof violations documented by the Commission since 2015 with a view to creating a climate\nof trust and political tolerance conducive to inclusive participation in the electoral\nprocess;\nc)    Re-engage constructively and cooperatively with all international and\nregional human rights mechanisms and the Office of the United Nations High\nCommissioner for Human Rights, enabling them to carry out their human rights\nmonitoring mandates fully and freely;\nd)     Ensure that national human rights mechanisms are institutionally and\nfinancially independent and build the capacity of their members;\ne)      Take the measures necessary to ensure that foreign and domestic NGOs\ncan be freely established and organized and that they can operate freely, including by\namending the laws regulating them;\nf)     Take the measures necessary to ensure freedom of information in the\ncountry and the right of local and international media to operate in accordance with\ninternational standards, including by amending the laws on the press and the National\nCommunication Council;\ng)     Guarantee the effective enjoyment of civil liberties, including the\nfreedoms of opinion, expression, access to information, association, assembly and\nreligion, not least by ending all forced recruitment to the ruling party and its youth\nleague;\nh)    Follow the Guidelines on Access to Information and Elections in Africa\nand the Guidelines on Freedom of Association and Assembly of the African Commission\non Human and Peoples’ Rights;\ni)     Ensure that all political parties can engage in legitimate activities in\ncomplete freedom and security, in an environment of political tolerance, including by\npunishing any incitement to hatred and calls for violence against other political parties\nand their members;\nj)    Ensure, in practice, the right to participate in the conduct of public\naffairs without discrimination, in particular by amending the Electoral Code;\nk)      Ensure, in practice, the institutional independence of the Independent\nNational Electoral Commission, including by amending the decree governing it to make\ncertain that its composition is inclusive and balanced, and strengthen the capacity of its\nmembers at the municipal and provincial levels;\nl)     Provide access to independent international and regional election\nobservers and ensure that they and national observers from civil society or political\nparties enjoy freedom of movement and action before, during and after the elections;\nm)     Follow the Guidelines for African Union Electoral Observation and\nMonitoring Missions;\nn)      Allow political opponents to return from exile to participate in the 2020\nelections and guarantee their freedom and security, including by revoking warrants for\nthe arrest of those who have not used or advocated violence;\no)    Immediately release all political prisoners arrested and detained in\nconnection with the exercise of their democratic rights;\np)      Make the training provided to law enforcement agencies more robust to\navoid ill-treatment and ensure the peaceful control of crowds;","unnumbered":true},{"id":"a-hrc-42-crp-2-p0141","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":140,"section":"V. Conclusions and recommendations","text":"q)    Follow the Guidelines for the Policing of Assemblies by Law\nEnforcement Officials in Africa and the related training manual, both developed by the\nAfrican Commission on Human and Peoples’ Rights;\nr)     End the impunity of the Imbonerakure by exercising control over them\nso as to ensure that the functions of the security forces or the judiciary are not usurped\nand put an end to their repressive activities and shows of force in the hills;\ns)     End all illegal contributions.\n567. The Commission recommends that, whether they participate in the elections or\nnot, all political parties in Burundi refrain from violence and incitement to hatred or\nviolence, particularly against the backdrop of the 2020 elections.\n568. The Commission recommends that opposition rebel groups refrain from\nviolence and incitement to hatred or violence.\n569. For the international community, including the African Union and the United\nNations system, the Commission has the following recommendations:\na)     Renew the mandate of the Commission for an additional year;\nb)     Continue to monitor developments in the human rights situation in\nBurundi in the context of the 2020 elections and, in accordance with the principles of\nprevention and early warning, carry out regular risk assessments to enable the\ndevelopment and use of appropriate response strategies in the event of deterioration;\nc)     Make every effort to ensure that an inclusive inter-Burundi dialogue is\nheld to resolve the political crisis;\nd)     Support capacity-building for international, regional and national\nelection observers;\ne)     Send regional or international observers only if their freedom of action is\nguaranteed in practice;\nf)     Ensure that all humanitarian aid reaches the population;\ng)     Respond to the appeal made by the Office of the United Nations High\nCommissioner for Refugees for funds for Burundi refugees;\nh)    Ensure that returnees are monitored in a sustained and more regular\nand transparent manner.\n570. In particular, the Commission recommends that the United Nations system, in\naccordance with the initiative Human Rights Up Front, take stronger measures to\npromote human rights, under the mandates of the relevant agencies and programmes,\nand to collect and publish objective and reliable data on the situation in Burundi.\n571. In view of the risk factors that have been identified, the Commission\nrecommends that the States members of the Security Council keep Burundi on the\nCouncil’s programme of work and that the Council invite the Commission to report to\nit on its conclusions.\n572. In view of the persistence of human rights violations in Burundi, the\nCommission recommends that Member States grant prima facie refugee status to\nBurundian asylum seekers and to ensure strict compliance with the principle of non-\nrefoulement and protection of refugees.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0142","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":141,"section":"Annex I","text":"Previous Recommendations made by the Commission","unnumbered":true},{"id":"a-hrc-42-crp-2-p0143","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":142,"section":"Annex I","text":"1.   Recommendations made in 2018","unnumbered":true},{"id":"a-hrc-42-crp-2-p0144","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":143,"section":"Annex I","text":"106. The Commission recommends that the Government of Burundi take the following\nmeasures as a matter of priority:\n(a)      Put an immediate end to the gross human rights violations being committed\nby agents of the State and Imbonerakure;\n(b)    With the support of the international community, establish ad hoc\nmechanisms with a mandate to investigate human rights violations and to prosecute\nperpetrators of international crimes that are not being investigated by the International\nCriminal Court;\n(c)     With the support of the international community, establish an independent\nbody with a mandate to investigate the cases of disappearance reported since April 2015,\nlocate potential mass graves, and exhume and identify the remains;\n(d)    Take measures to ensure that victims of torture and women survivors of\nsexual violence have access to appropriate care, including free access to all sexual and\nreproductive health services and to psychological support;\n(e)   Implement the Guidelines on Combating Sexual Violence and its\nConsequences in Africa adopted by the African Commission on Human and Peoples’ Rights;\n(f)     Control price increases, in particular by reviewing duty and tax increases that\nare undermining the population’s right to an adequate standard of living and by abolishing\ncontributions that disproportionately affect the poorest sectors;\n(g)    Cooperate with international human rights mechanisms, in particular by:\n      i)     Resuming the practice of allowing special procedures mandate\nholders to conduct missions to Burundi;\n      ii)    Implementing the recommendations of the universal periodic\nreview, treaty bodies and special procedures, including by establishing a\nnational mechanism for reporting and follow-up.\n(h)    Authorize the Office of the United Nations High Commissioner for Human\nRights to resume all its activities in Burundi without hindrance;\n(i)    Sign and implement the memorandum of understanding with the African\nUnion and permit the full deployment of the 100 human rights observers provided for therein.\n107. For the medium and longer terms, the Commission also recommends that the\nGovernment of Burundi:\n(a)    Amend the Organization Act of 8 March 2018 amending Act No. 01/03 of 24\nJanuary 2013 on the mandate, composition, organization and functioning of the National\nCommunication Council with a view to ensuring the latter’s independence;\n(b)    Ratify the International Convention for the Protection of All Persons from\nEnforced Disappearance;\n(c)     Amend the Code of Criminal Procedure to align its provisions with\ninternational standards, in particular the provisions on time limits for police custody and on\noversight of detention, night-time and warrantless searches, the flagrante delicto procedure\nand the offence of “undermining the internal security of the State”, and provisions that grant\nde jure impunity to judges and to officers of the criminal investigation police (police\njudiciaire);\n(d)    Put an end to arbitrary detention and improve conditions of detention by:","unnumbered":true},{"id":"a-hrc-42-crp-2-p0145","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":144,"section":"Annex I","text":"      i)    Implementing the Guidelines on the Conditions of Arrest,\nPolice Custody and Pre-Trial Detention in Africa adopted by the African\nCommission on Human and Peoples’ Rights;\n      ii)      Ensuring that detention is subject to oversight measures for\nassessing its legality and compatibility with human rights.\n(e)      In the absence of an independent and efficient judicial system, cooperate\nfully with the International Criminal Court in the investigation opened on 25 October 2017;\n(f)    Undertake an in-depth reform of the judicial system to ensure its\nindependence, impartiality and effectiveness, including by:\n      i)      Implementing the Principles and Guidelines on the Right to a\nFair Trial and Legal Assistance in Africa adopted by the African Commission\non Human and Peoples’ Rights;\n      ii)    Publishing the conclusions of the national forum on the justice\nsystem held in 2013 and convening a meeting of justice-sector stakeholders\nand international partners to discuss follow-up action;\n     iii)   Increasing the budget for the justice sector and ensuring that it\nis managed autonomously;\n      iv)    Raising the pay levels of judges in the ordinary courts and\nincreasing the resources and facilities available to them;\n       v)     Computerizing court registries;\n      vi)     Reviewing the composition of the Judicial Service Commission\nto ensure that the majority of its members are appointed by their peers;\n      vii) Reviewing procedures for the appointment, assignment,\nevaluation and promotion of judges to ensure that such procedures are not\ndependent on the executive branch;\n      viii) Ensuring strict observance of the principle that judges should\nhave security of tenure;\n       ix)    Protecting and safeguarding the independence of the judiciary\nby prohibiting any interference in the administration of justice by Government\nauthorities, members of the ruling party or members of the defense and security\nforces, and imposing penalties on anyone who influences or seeks to influence\nthe administration of justice;\n     x)     Developing legal aid programmes for persons belonging to the\nmost vulnerable groups;\n      xi)    Strengthening victim and witness protection mechanisms and\nimproving their effectiveness in order to restore public trust and encourage\nwitnesses to come forward without fear for their safety.\n(g)    In consultation with the beneficiaries, establish a reparations programme for\nvictims of human rights violations, ensuring that material, symbolic, individual and collective\nreparations are made available regardless of whether or not the perpetrators are convicted;\n(h)    Establish the State fund for victims of torture provided for by law, in\nconformity with general comment No. 4 on the African Charter on Human and Peoples’\nRights, adopted by the African Commission on Human and Peoples’ Rights, concerning the\nright to redress for victims of torture and other cruel, inhuman or degrading punishment or\ntreatment (art. 5);\n(i)    Establish a compensation fund for victims of arbitrary and unlawful\ndetention;\n(j)    Reform the security sector by:\n       i)     Ensuring that outsiders are not involved in defense or security\nactivities;","unnumbered":true},{"id":"a-hrc-42-crp-2-p0146","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":145,"section":"Annex I","text":"       ii)     Clearly defining the roles of the various defense and security\nforces, in particular the National Intelligence Service;\n      iii)   Suspending members of the defense and security forces who\nare suspected of involvement in human rights violations until the relevant\ninvestigations and judicial proceedings have concluded;\n      iv)    Establishing rigorous and transparent selection procedures that\ninclude vetting mechanisms;\n      v)      Strengthening democratic civilian control over the defense and\nsecurity forces, in particular the National Intelligence Service.\n(k)    Meet its international obligations to respect, protect and fulfil economic and\nsocial rights by:\n       i)     Developing and implementing State budgets in such a way as\nto maximize the use of available resources to ensure that the human rights of\nthe sectors impoverished by the political crisis are respected, in particular the\nrights to food, water and health care, and to develop indicators disaggregated\nby factors such as gender in order to better inform its policies;\n       ii)    In consultation with population groups working in the\nagricultural sector, including women, undertaking reforms with the aim of\nbetter protecting women’s rights and making better use of land for agriculture,\nand developing employment opportunities outside the agricultural sector;\n       iii)   Taking a rights-based approach to the settlement of land\nconflicts, including those involving persons who fled Burundi either before or\nafter 2015;\n      iv)     Ending the inclusion of any political considerations in hiring\nprocesses for the civil service, State enterprises and public-private enterprises.\n108. The Commission recommends that political parties and armed opposition groups\nrefrain from engaging in any attacks on Burundian territory and from any speech calling for\nviolence, and that they join the effort to find a lasting solution to the political crisis.\n109. The Commission recommends that the African Union, in its efforts to find a lasting\nsolution to the crisis in Burundi, give priority to respect for human rights and the rejection of\nimpunity, as provided for in its Constitutive Act.\n110.   The Commission recommends that the technical and financial partners of Burundi:\n(a)    Suspend, or maintain the suspension of, any direct budget support to the\nGovernment until such time as priority is given to the allocation of domestic resources for\nthe fulfilment of the Sustainable Development Goals and the economic and social rights of\nthe population, and effective measures are taken against corruption;\n(b)   Ensure that grants and financing provided to the Government are earmarked\nfor projects to meet the population’s needs, and ensure that such funding is managed\neffectively and transparently;\n(c)     Regularly evaluate the impact of financial sanctions on the people of\nBurundi.\n111. The Commission recommends that the guarantors of the Arusha Agreement, in their\ncapacity as committed proponents of a lasting peace in Burundi, continue to seek a durable\nsolution to the political and human rights crisis that will preserve and safeguard the\nachievements of the Arusha Agreement.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0147","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":146,"section":"Annex I","text":"2.   Recommendations made in 2017","unnumbered":true},{"id":"a-hrc-42-crp-2-p0148","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":147,"section":"Annex I","text":"1. The Burundian authorities should:\n144. Put an immediate end to the gross human rights violations being committed by\nagents of the State and Imbonerakure over which the State exercises control;\n145. Investigate these violations, ensure that the alleged perpetrators are prosecuted\npromptly in accordance with credible, independent and fair procedures, and that the victims\nobtain just reparation, and, where the alleged perpetrators are agents of the State, suspend\nthem from their duties pending the completion of the investigation and the judicial\nproceedings;\n146. Take practical measures to bring about a rapid improvement of the human rights\nsituation, in particular by:\n•      Withdrawing the warrants for the arrest of heads of media outlets, civil\nsociety organizations and political parties who have neither used nor advocated\nviolence, and permitting their safe return to Burundi;\n•      Lifting the suspension and reversing the revocation of the licenses of media\nand civil society organizations, permitting them to resume their activities with\ncomplete independence and reviewing the laws adopted in 2017 concerning non-profit\norganizations and foreign non-Governmental organizations;\n•      Immediately releasing all political prisoners;\n•      Ensuring that every person arrested is detained in an official place of\ndetention and that national and international observers are allowed to visit them;\n•       Ensure that criminal investigation officers (officiers de police judiciaire) are\nnot authorized to conduct searches without a warrant, including at night, as envisaged\nin the draft amendments to the Criminal Code and the Code of Criminal Procedure;\n•      Ensuring that individuals lacking legal authorization, particularly the\nImbonerakure, do not perform or participate in law enforcement activities, including\nin places of detention, and do not wear military or police uniforms or possess\nweapons;\n•      Prosecuting individuals who incite hatred or violence;\n•      Putting an end to threats, intimidation and acts of extortion by State officials\nand the Imbonerakure;\n•     Giving victims of sexual violence and torture access to medical and\npsychosocial services.\n147.   Undertake a thorough reform of the judiciary, in particular by:\n•     Publishing the conclusions of the General Convention on the Judiciary (États\ngénéraux de la justice) held in Gitega in 2013;\n•       Reviewing the composition of the Superior Council of Magistrates (Conseil\nsupérieur de la magistrature) so that the majority of its members are designated by\ntheir peers;\n•      Reviewing the nomination, posting, evaluation and promotion procedures of\nmagistrates so that they do not depend of the executive;\n•      Ensuring the respect of the principle of security of tenure for judges;\n•       Protecting and guaranteeing the independence of the judiciary by prohibiting\nall interference in their functions by Governmental authorities, members of the ruling\nparty or security and defense forces, and imposing sanctions on those who influence,\nor seek to influence, the functioning of the judiciary;\n•      Developing legal aid programmes for the most vulnerable;","unnumbered":true},{"id":"a-hrc-42-crp-2-p0149","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":148,"section":"Annex I","text":"•       Reinforcing the protection mechanisms for victims and witnesses, as well as\ntheir efficiency, in order to restore people’s confidence in the system and to encourage\nwitnesses to testify without fear for their security.\n148. Ensure that members of the defense and security forces respect human rights in all\ncircumstances and serve the interests of the population as a whole, not solely those of the\nruling party, in particular by:\n•      Reinforcing civilian control over the military and the independence of the\ncompetent organs created by the Constitution to supervise this control, in particular\nthe Parliament, the National Human Rights Commission and the Ombudsman;\n•      Implementing civilian control over the National Intelligence Service (Service\nnational de renseignement) in line with the Constitution;\n•      Conducting background checks, in particular on human rights, on defense\nand security forces and incorporating these measures into reforms of the recruitment\nand career progression of these agents.\n149. Reconsider their decision to withdraw from the Rome Statute, cooperate fully with\nthe International Criminal Court in the ongoing preliminary examination and, if an\ninvestigation is initiated, continue that cooperation, inter alia by ensuring the protection of\nvictims and witnesses;\n150. Authorize the Office of the United Nations High Commissioner for Human Rights to\nresume its documentation of human rights violations in Burundi, which has been suspended\nsince October 2016;\n151. Sign and implement the memorandum of understanding with the African Union and\npermit the full deployment of 100 human rights observers and 100 military experts that was\ndecided upon in 2016;\n152. Cooperate with United Nations human rights mechanisms by once again receiving\nspecial procedures missions and implementing the recent recommendations of treaty bodies;\n153. Actively seek a lasting solution to the political crisis, inter alia through international\ninitiatives to promote dialogue.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0150","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":149,"section":"Annex I","text":"2.     Political parties and armed opposition groups should:\n154. Put an immediate end to human rights abuses and acts of violence committed by\ntheir members;\n155. Refrain from any incitement of violence and participate in the quest for a lasting\nsolution to the political crisis in Burundi.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0151","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":150,"section":"Annex I","text":"3.     The Human Rights Council should:\n156. Extend the Commission’s mandate for a period of one year to enable it to conduct\nfurther and more thorough investigations in view of the persistence of gross human rights\nviolations and abuses and the absence of other specific mechanisms capable of undertaking\nindependent and thorough investigations into the human rights situation in Burundi;\n157. Request the Office of the United Nations High Commissioner for Human Rights to\nreport, at the forthcoming sessions of the Council, on the development of its cooperation with\nthe Burundian Government.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0152","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":151,"section":"Annex I","text":"4.     The International Criminal Court should:\n158. Initiate, as soon as possible, an investigation into the crimes committed in Burundi\nin light of the conclusions contained in the present report and other information at its disposal.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0153","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":152,"section":"Annex I","text":"5.     The United Nations Security Council should:\n159. Take due account of the Commission’s conclusions, as well as persistence of gross\nviolations of human rights, in any discussion on Burundi and, in this context, ensure the\neffective implementation of resolution 2303 (2016);","unnumbered":true},{"id":"a-hrc-42-crp-2-p0154","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":153,"section":"Annex I","text":"160. Refer to the International Criminal Court any international crime that might be\ncommitted in Burundi after 27 October 2017;\n161. Impose individual sanctions against the principal alleged perpetrators of gross\nhuman rights violations and international crimes in Burundi.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0155","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":154,"section":"Annex I","text":"6.     The Secretary-General of the United Nations should:\n162. Ensure that respect for human rights and restoration of the rule of law are among the\npriorities of his Special Envoy for Burundi;\n163. Ensure that no alleged perpetrator of human rights violations or international crimes\nin Burundi is recruited for United Nations peacekeeping missions.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0156","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":155,"section":"Annex I","text":"7.     The States Members of the United Nations should:\n164. Grant prima facie refugee status to Burundian asylum seekers and ensure strict\nre64ect for the principle of non-refoulement and refugee protection;\n165. Prosecute, in accordance with the principle of universal jurisdiction, alleged\nperpetrators of international crimes committed in Burundi who are found to be in their\nterritory;\n166. Maintain, in the absence of any improvement in the human rights situation in\nBurundi, the individual sanctions and the suspension of direct aid to the Government;\n167. Provide technical assistance inter alia in respect to autopsies, exhumations and\nidentification of bodies, to enable the Burundian to conduct credible and independent\ninvestigations;\n168. Support the establishment of specialized medical and psychosocial services,\nespecially for victims of torture and sexual violence;\n169. Support Burundian authorities in any judicial and security sector reform endeavors\nthat they might wish to undertake in order to improve the human rights situation.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0157","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":156,"section":"Annex I","text":"8.     The African Union should:\n170. Retake the lead in seeking a lasting solution to the crisis in Burundi based on respect\nfor human rights and rejection of impunity, as provided for in its Constitutive Act, and play\nan active role in that process;\n171. Ensure that no agent of the Burundian State who is accused of human rights\nviolations or international crimes is recruited for African Union peacekeeping missions;\n172. Ensure that the full complement of African Union human rights observers and\nmilitary experts is deployed rapidly in Burundi;\n173. Consider, in the event that the current situation in Burundi persists, the application\nof Article 4 (h) of the Constitutive Act of the African Union, under which it is authorized to\nintervene in a member State in certain circumstances, particularly in the event of crimes\nagainst humanity.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0158","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":157,"section":"Annex I","text":"9.     The East African Community should:\n174. Ensure that a rapid improvement of the human rights situation is a priority in its\nmediation efforts.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0159","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":158,"section":"Annex I","text":"10.  The guarantors of the 2000 Arusha Agreement, in their capacity as committed\nproponents of a lasting peace in Burundi, should:\n175. Meet with a view to finding a lasting solution to the political and human rights crisis\nin Burundi.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0160","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":159,"section":"Annex I","text":"Annex IV – Indicators of common risk factors identified in the\nFramework of Analysis for Atrocity Crimes (A/70/741-S/2016/71)","unnumbered":true},{"id":"a-hrc-42-crp-2-p0161","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":160,"section":"Annex I","text":"Risk factor 1. Situations of armed conflict or other forms of instability\n(a)   International or non-international armed conflict;\n(b)   Security crisis caused by, among other factors, defection from peace\nagreements, armed conflict in neighboring countries, threats of external interventions or acts\nof terrorism;\n(c)    Humanitarian crisis or emergency, including those caused by natural disasters\nor epidemics;\n(d)   Political instability caused by abrupt or irregular regime change or transfer of\npower;\n(e)     Political instability caused by disputes over power or growing nationalist,\narmed or radical opposition movements;\n(f)   Political tension caused by autocratic regimes or severe political repression;\n(g)     Economic instability caused by scarcity of resources or disputes over their\nuse or exploitation;\n(h)   Economic instability caused by severe crisis in the national economy;\n(i)    Economic instability caused by acute poverty, mass unemployment or deep\nhorizontal inequalities;\n(j)    Social instability caused by resistance to, or mass protests against, State\nauthority or policies;\n(k)    Social instability caused by exclusion or tensions based on identity issues,\ntheir perception or extremist forms.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0162","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":161,"section":"Annex I","text":"Risk factor 2. Record of serious violations of international human rights and\nhumanitarian law\n(a)    Past or present serious restrictions to or violations of international human\nrights and humanitarian law, particularly if assuming an early pattern of conduct and if\ntargeting protected groups, populations or individuals;\n(b)     Past acts of genocide, crimes against humanity, war crimes or their\nincitement;\n(c)     Policy or practice of impunity for or tolerance of serious violations of\ninternational human rights and humanitarian law, of atrocity crimes, or of their incitement;\n(d)    Inaction, reluctance or refusal to use all possible means to stop planned,\npredictable or ongoing serious violations of international human rights and humanitarian law\nor likely atrocity crimes, or their incitement;\n(e)    Continuation of support to groups accused of involvement in serious\nviolations of international human rights and humanitarian law, including atrocity crimes, or\nfailure to condemn their actions;\n(f)     Justification, biased accounts or denial of serious violations of international\nhuman rights and humanitarian law or atrocity crimes;\n(g)   Politicization or absence of reconciliation or transitional justice processes\nfollowing conflict;\n(h)   Widespread","unnumbered":true},{"id":"a-hrc-42-crp-2-p0163","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":162,"section":"Annex I","text":"Risk factor 3. Weakness of State structures\n(a)    National legal framework that does not offer ample and effective protection,\nincluding through ratification and domestication of relevant international human rights and\nhumanitarian law treaties;\n(b)    National institutions, particularly judicial, law enforcement and human rights\ninstitutions that lack sufficient resources, adequate representation or training;\n(c)     Lack of an independent and impartial judiciary;\n(d)     Lack of effective civilian control of security forces;\n(e)     High levels of corruption or poor governance;\n(f)     Absence or inadequate external or internal mechanisms of oversight and\naccountability, including those where victims can seek recourse for their claims;\n(g)     Lack of awareness of and training on international human rights and\nhumanitarian law to military forces, irregular forces and non-State armed groups, or other\nrelevant actors;\n(h)     Lack of capacity to ensure that means and methods of warfare comply with\ninternational humanitarian law standards;\n(i)     Lack of resources for reform or institution-building, including through\nregional or international support;\n(j)    Insufficient resources to implement overall measures aimed at protecting\npopulations.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0164","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":163,"section":"Annex I","text":"Risk factor 4. Motives or incentives\n(a)       Political motives, particularly those aimed at the attainment or consolidation\nof power;\n(b)     Economic interests, including those based on the safeguard and well-being of\nelites or identity groups, or control over the distribution of resources;\n(c)    Strategic or military interests, including those based on protection or seizure\nof territory and resources;\n(d)     Other interests, including those aimed at rendering an area homogeneous in\nits identity;\n(e)    Real or perceived threats posed by protected groups, populations or\nindividuals against interests or objectives of perpetrators, including perceptions of disloyalty\nto a cause;\n(f)    Real or perceived membership of or support for armed opposition groups by\nprotected groups, populations or individuals;\n(g)     Ideologies based on the supremacy of a certain identity or on extremist\nversions of identity;\n(h)     Politicization of past grievances, tensions or impunity;\n(i)    Social trauma caused by past incidents of violence not adequately addressed\nand that produced feelings of loss, displacement, injustice and a possible desire for revenge.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0165","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":164,"section":"Annex I","text":"Risk factor 5. Capacity to commit atrocity crimes\n(a)    Availability of personnel and of arms and ammunition, or of the financial\nresources, public or private, for their procurement;\n(b)   Capacity to transport and deploy personnel and to transport and distribute\narms and ammunition;\n(c)     Capacity to encourage or recruit large numbers of supporters from\npopulations or groups, and availability of the means to mobilize them;","unnumbered":true},{"id":"a-hrc-42-crp-2-p0166","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":165,"section":"Annex I","text":"(d)    Strong culture of obedience to authority and group conformity;\n(e)    Presence of or links with other armed forces or with non-State armed groups;\n(f)    Presence of commercial actors or companies that can serve as enablers by\nproviding goods, services, or other forms of practical or technical support that help to sustain\nperpetrators;\n(g)    Financial, political or other support of influential or wealthy national actors;\n(h)    Armed, financial, logistic, training or other support of external actors,\nincluding States, international or regional organizations, private companies, or others.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0167","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":166,"section":"Annex I","text":"Risk factor 6. Absence of mitigating factors\n(a)     Limited or lack of empowerment processes, resources, allies or other\nelements that could contribute to the ability of protected groups, populations or individuals\nto protect themselves;\n(b)    Lack of a strong, organized and representative national civil society and of a\nfree, diverse and independent national media;\n(c)    Lack of interest and focus of international civil society actors or of access to\ninternational media;\n(d)    Lack of, or limited presence of, the United Nations, international non-\nGovernmental organizations or other international or regional actors in the country and with\naccess to populations;\n(e)    Lack of membership and effective participation of the State in international\nor regional organizations that establish mandatory membership obligations;\n(f)    Lack of exposure, openness or establishment of political or economic\nrelations with other States or organizations;\n(g)    Limited cooperation of the State with international and regional human rights\nmechanisms;\n(h)   Lack of incentives or willingness of parties to a conflict to engage in\ndialogue, make concessions and receive support from the international community;\n(i)    Lack of interest, reluctance or failure of States Members of the United\nNations or members of international or regional organizations to support a State to exercise\nits responsibility to protect populations from atrocity crimes, or to take action when the State\nmanifestly fails that responsibility;\n(j)    Lack of support by neighbouring States to protect populations at risk and in\nneed of refuge, including by closure of borders, forced repatriation or aid restriction;\n(k)    Lack of an early warning mechanism relevant to the prevention of atrocity\ncrimes.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0168","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":167,"section":"Annex I","text":"Risk factor 7. Enabling circumstances or preparatory action\n(a)    Imposition of emergency laws or extraordinary security measures that erode\nfundamental rights;\n(b)    Suspension of or interference with vital State institutions, or measures that\nresult in changes in their composition or balance of power, particularly if this results in the\nexclusion or lack of representation of protected groups;\n(c)    Strengthening of the security apparatus, its reorganization or mobilization\nagainst protected groups, populations or individuals;\n(d)     Acquisition of large quantities of arms and ammunition or of other objects\nthat could be used to inflict harm;\n(e)    Creation of, or increased support to, militia or paramilitary groups;","unnumbered":true},{"id":"a-hrc-42-crp-2-p0169","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":168,"section":"Annex I","text":"(f)    Imposition of strict control on the use of communication channels, or banning\naccess to them;\n(g)     Expulsion or refusal to allow the presence of non-Governmental\norganizations, international organizations, media or other relevant actors, or imposition of\nsevere restrictions on their services and movements;\n(h)     Increased violations of the right to life, physical integrity, liberty or security\nof members of protected groups, populations or individuals, or recent adoption of measures\nor legislation that affect or deliberately discriminate against them;\n(i)   Increased serious acts of violence against women and children, or creation of\nconditions that facilitate acts of sexual violence against those groups, including as a tool of\nterror;\n(j)    Imposition of life-threatening living conditions or the deportation, seizure,\ncollection, segregation, evacuation or forced displacement or transfer of protected groups,\npopulations or individuals to camps, rural areas, ghettos or other assigned locations;\n(k)    Destruction or plundering of essential goods or installations for protected\ngroups, populations or individuals, or of property related to cultural and religious identity;\n(l)   Marking of people or their property based on affiliation to a group;\n(m)      Increased politicization of identity, past events or motives to engage in\nviolence;\n(n)    Increased inflammatory rhetoric, propaganda campaigns or hate speech\ntargeting protected groups, populations or individuals.","unnumbered":true},{"id":"a-hrc-42-crp-2-p0170","rec_id":"rec7cI6SF0WhzvtUM","symbol":"A/HRC/42/CRP.2","n":null,"seq":169,"section":"Annex I","text":"Risk factor 8. Triggering factors\n(a)   Sudden deployment of security forces or commencement of armed hostilities;\n(b)   Spillover of armed conflicts or serious tensions in neighbouring countries;\n(c)    Measures taken by the international community perceived as threatening to a\nState’s sovereignty;\n(d)   Abrupt or irregular regime changes, transfers of power, or changes in\npolitical power of groups;\n(e)     Attacks against the life, physical integrity, liberty or security of leaders,\nprominent individuals or members of opposing groups; other serious acts of violence, such\nas terrorist attacks;\n(f)     Religious events or real or perceived acts of religious intolerance or\ndisrespect, including outside national borders;\n(g)   Acts of incitement or hate propaganda targeting particular groups or\nindividuals;\n(h)     Census, elections, pivotal activities related to those processes, or measures\nthat destabilize them;\n(i)    Sudden changes that affect the economy or the workforce, including as a\nresult of financial crises, natural disasters or epidemics;\n(j)    Discovery of natural resources or launching of exploitation projects that have\na serious impact on the livelihoods and sustainability of groups or civilian populations;\n(k)   Commemoration events of past crimes or of traumatic or historical episodes\nthat can exacerbate tensions between groups, including the glorification of perpetrators of\natrocities;\n(l)   Acts related to accountability processes, particularly when perceived as\nunfair.","unnumbered":true},{"id":"a-hrc-45-32-u0000","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":null,"seq":0,"section":null,"text":"United Nations                                                                                  A/HRC/45/32\nGeneral Assembly                                                         Distr.: General\n13 August 2020\nEnglish\nOriginal: French","unnumbered":true},{"id":"a-hrc-45-32-u0001","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":null,"seq":1,"section":null,"text":"Summary\nNumerous serious human rights violations have been documented since May 2019 in\nconnection with the 2020 elections. The perpetrators were seeking to deprive the main\nopposition party of any chance of winning the election. These violations were mainly\ncommitted by members of the Imbonerakure youth league of the ruling party and by local\nofficials who continue to enjoy nearly total impunity. Officers of the National Intelligence\nService and the police often participated in or supported such violations or, in the case of the\npolice, sometimes stood by and allowed the perpetrators to act. The judiciary has also taken\npart in this repression.\nThe survey on the economic underpinnings of the State has shown that corruption and illicit\nfinancial flows have a negative impact on the enjoyment of human rights in Burundi. Aside\nfrom the political transition currently under way, most risk factors still remain, and far-\nreaching reforms are required to improve the situation in the medium and long term.","unnumbered":true},{"id":"a-hrc-45-32-u0002","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":null,"seq":2,"section":null,"text":"* The annexes to the present document are reproduced as received, in the language of submission only.\n** Agreement was reached to publish the present report after the standard publication date owing to\ncircumstances beyond the submitter’s control.","unnumbered":true},{"id":"a-hrc-45-32-p0001","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"1","seq":3,"section":"A. Mandate","text":"The Commission of Inquiry on Burundi was created by Human Rights Council\nresolution 33/24, adopted on 30 September 2016, to conduct a thorough investigation into\nhuman rights violations and abuses committed in Burundi since April 2015, to determine\nwhether any of them may constitute international crimes, to identify their alleged perpetrators\nand to formulate recommendations for ensuring that such perpetrators are held accountable\nfor their acts. The mandate was extended for three additional one-year terms. In its resolution\n42/26 adopted on 27 September 2019, the Human Rights Council also mandated the\nCommission to further investigate, inter alia, the respect and enjoyment of political, civil,\neconomic and social rights in the electoral context, in particular with regard to the economic\nunderpinnings of the State."},{"id":"a-hrc-45-32-p0002","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"2","seq":4,"section":"A. Mandate","text":"The membership of the Commission remains unchanged: Doudou Diène (Senegal),\nwho has chaired the body since 1 February 2018; Lucy Asuagbor (Cameroon), a member\nsince 5 March 2018; and Françoise Hampson (United Kingdom of Great Britain and Northern\nIreland), appointed on 22 November 2016."},{"id":"a-hrc-45-32-p0003","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"3","seq":5,"section":"A. Mandate","text":"The Commission has looked into violations and abuses committed since May 2019,\npaying special attention to those related to the May 2020 electoral process,1 and to violations\nof the rights of the child committed since 2015. As part of its investigation into the economic\nunderpinnings of the Burundian State, it sought to identify practices in the country’s economy\nthat were conducive to human rights violations. As part of its analysis of risk factors, it has\nidentified those to be taken into account in the context of the current political transition."},{"id":"a-hrc-45-32-p0004","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"4","seq":6,"section":"A. Mandate","text":"In 2020, the Commission presented two oral briefings to the Human Rights Council.\nThe present report summarizes the final conclusions of its investigations, which will be\ndetailed in a separate document.2"},{"id":"a-hrc-45-32-p0005","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"5","seq":7,"section":"B. Cooperation by Burundi with the Commission","text":"The Human Rights Council once again requested the Government of Burundi to\ncooperate fully with the Commission, to authorize it to conduct visits to the country and to\nprovide it with all the information necessary to carry out its mandate. The Commission sought\nto engage in a dialogue with the Burundian authorities through the Permanent Mission of the\nRepublic of Burundi to the United Nations Office and other international organizations in\nGeneva, in particular to allow for an exchange of information and to reflect the position of\nthe Government of Burundi as much as possible in its report. All of the Commission’s\ncorrespondence went unanswered."},{"id":"a-hrc-45-32-p0006","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"6","seq":8,"section":"C. Methodology","text":"The Commission undertook visits to Uganda, Rwanda and the United Republic of\nTanzania. Members of the Commission also met with representatives of the African Union,\nthe European Union and various States. However, the health crisis related to the coronavirus\n(COVID-19) pandemic and the travel restrictions imposed by many States beginning in\nMarch 2020 prevented the Commission from making some planned visits. To adapt as best\npossible to the new constraints, the Commission carried out more remote interviews. During\nthe fourth term of its mandate, it held a total of more than 300 face-to-face or remote\ninterviews with victims, witnesses and other sources, residing either in Burundi or in other\ncountries, in addition to the nearly 1,300 testimonials collected since the beginning of its\n1 Information relating to the hill district (colline) elections of 24 August 2020 is only covered in\nadditional document A/HRC/45/CRP.1, available on the Commission’s website.\nwork. The Commission deplores the fact that persons who have worked with it have faced\nintimidation and reprisals."},{"id":"a-hrc-45-32-p0007","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"7","seq":9,"section":"C. Methodology","text":"The Commission continued to apply the same methodology and the same standard of\nevidence, “reasonable grounds to believe”, which are fully consistent with internationally\naccepted guidance and practice for this type of inquiry.3"},{"id":"a-hrc-45-32-p0008","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"8","seq":10,"section":"D. Applicable law","text":"The applicable law is still international human rights law and international criminal\nlaw.4 As Burundi has not ratified any new treaties, it is party to the same conventions as\npreviously."},{"id":"a-hrc-45-32-p0009","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"9","seq":11,"section":"D. Applicable law","text":"The withdrawal of Burundi from the Rome Statute of the International Criminal Court,\nwhich took effect on 27 October 2017, does not discharge the country from the obligations\narising therefrom while it was a party to the treaty5 or from its obligations under customary\ninternational law concerning international crimes. The Commission has referred to the\ndefinitions of crimes set forth in the Rome Statute, which are reflected in the Criminal Code\nof Burundi."},{"id":"a-hrc-45-32-p0010","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"10","seq":12,"section":"A. Developments within international and regional bodies","text":"During the period covered by the present report, no special rapporteur or working\ngroup visited Burundi and no visits were planned. Special procedures mandate holders sent\na communication to the Government regarding a case of an alleged human rights violation. 6\nThe Government did not respond. The Working Group on Arbitrary Detention adopted two\nopinions in which it concluded that Germain Rukuki (a human rights defender) and Alexis\nSebahene (a soldier held in pretrial detention since August 2015) were being arbitrarily\ndetained.7"},{"id":"a-hrc-45-32-p0011","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"11","seq":13,"section":"A. Developments within international and regional bodies","text":"On 30 October 2019, the Security Council held a formal meeting to consider the\nsituation in Burundi, during which the Special Envoy of the Secretary-General for Burundi,\nMr. Kafando, announced that he was stepping down. Since then, the Security Council has\nbeen able to hold just two closed-door informal dialogues, in February and June 2020."},{"id":"a-hrc-45-32-p0012","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"12","seq":14,"section":"A. Developments within international and regional bodies","text":"The targeted sanctions adopted by the European Union against four Burundian\nnationals responsible for the violent crackdown in 2015, including Gervais Ndirakobuca, who\nwas appointed Minister of the Interior, Community Development and Public Security on 28\nJune 2020, have been renewed until October 2020. Several countries that are not in the\nEuropean Union have aligned themselves with this decision. The sanctions adopted by the\nUnited States of America are being maintained against 11 Burundian nationals, including\nAlain-Guillaume Bunyoni, the Prime Minister since 24 June 2020, and Gervais Ndirakobuca."},{"id":"a-hrc-45-32-p0013","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"13","seq":15,"section":"A. Developments within international and regional bodies","text":"The investigation opened on 25 October 2017 by the Prosecutor of the International\nCriminal Court into crimes against humanity committed in Burundi between 26 April 2015\nand 26 October 2017 is continuing."},{"id":"a-hrc-45-32-p0014","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"14","seq":16,"section":"1. Electoral process","text":"Presidential, legislative and communal elections were held on 20 May 2020, in\naccordance with the timetable set by the Independent National Electoral Commission. The\nofficial election campaign for the three elections on 20 May opened on 27 April and closed\non 17 May. According to the Electoral Code, candidates and political parties were only\nallowed to campaign during this period, and between 6 a.m. and 6 p.m."},{"id":"a-hrc-45-32-p0015","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"15","seq":17,"section":"1. Electoral process","text":"The campaign and the election took place without international observers. Those who\nwere to be sent by the East African Community declined to come after the Government of\nBurundi announced that as part of the fight against COVID-19 they would be placed in a\ntwo-week quarantine upon arrival, meaning until the day after the election."},{"id":"a-hrc-45-32-p0016","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"16","seq":18,"section":"1. Electoral process","text":"On 25 May 2020, the chair of the Independent National Electoral Commission\nannounced the provisional results of the elections, whereby Évariste Ndayishimiye won the\npresidential election with more than 68 per cent of the vote and Agathon Rwasa came in\nsecond, with 20 per cent. In a statement issued on 27 May, the Burundian Catholic Bishops’\nConference said that its 2,716 observers deployed to specific polling stations had reported\n“numerous irregularities” and that the bishops wondered “whether they might undermine the\ndeclared result”.8"},{"id":"a-hrc-45-32-p0017","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"17","seq":19,"section":"1. Electoral process","text":"On 4 June 2020, the Constitutional Court dismissed a complaint from the Congrès\nnational pour la liberté (CNL) challenging the provisional results and denouncing massive\nfraud and irregularities. It announced that Évariste Ndayishimiye had been elected with 68.7\nper cent of the vote. Agathon Rwasa, who at the same time had been elected as a member of\nparliament, said that he took note of this decision. The ruling party, the Conseil national pour\nla défense de la démocratie-Forces pour la défense de la démocratie (CNDD-FDD), also won\nthe legislative and communal elections by large margins."},{"id":"a-hrc-45-32-p0018","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"18","seq":20,"section":"1. Electoral process","text":"On 8 June 2020, the incumbent President, Pierre Nkurunziza, died unexpectedly,\naccording to official reports, from cardiac arrest. On 12 June, the Constitutional Court ruled\nthat the newly elected President, Évariste Ndayishimiye, should be sworn in immediately,\nand he came into office on 18 June. In his inaugural speech, which had its share of ambiguous\nand contradictory statements, he promised to reconcile the country through dialogue, to\ncombat impunity, to improve the human rights situation and to protect the population. He\nalso called on refugees to return home. However, he called into question whether there had\nactually been a political crisis in 2015 and pronounced an unduly limited concept of certain\ncivil liberties, supposedly based on Burundian culture."},{"id":"a-hrc-45-32-p0019","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"19","seq":21,"section":"1. Electoral process","text":"On 24 June 2020, Alain-Guillaume Bunyoni, who had been Minister of Public\nSecurity since 2015, was appointed Prime Minister, and Prosper Bazombanza, from the\nUnion pour le progrès national, was named Vice-President. The civilian chef du cabinet under\nthe Nkurunziza presidency was reappointed, as was the spokesperson. On 28 June, a new\nGovernment of 15 members was formed, including 5 women, comprising mainly persons\nfrom the previous regime, representing the CNDD-FDD hardliners’ wing. Since then, dozens\nof members of the military have been promoted, including some high-ranking officers\nregularly cited for involvement in serious human rights violations since 2015. On 10 July,\nthe Senate approved the 18 provincial governors chosen by the President, including 3 women\nand 6 senior military officers, thereby breaking with the practice of appointing civilians to\nthese key positions."},{"id":"a-hrc-45-32-p0020","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"20","seq":22,"section":"1. Electoral process","text":"On 20 July 2020, the CNDD-FDD party won 34 of the 36 Senate seats elected by local\ncouncillors.9\n8 See www.eglisecatholique.bi/index.php/fr/vie-de-l-eglise1/communiques/communique-de-la-\nconference-des-eveques-catholiques-du-burundi-sur-le-scrutin-du-20-mai-2020.\n9 Three Twa senators were co-opted."},{"id":"a-hrc-45-32-p0021","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"21","seq":23,"section":"2. Security incidents","text":"Burundi has had several serious security incidents. On 22 October 2019, an armed\nclash took place in Bubanza Province between the Burundi defence and security forces and\nan armed group. The Red Tabara opposition group claimed responsibility. On 16 November\n2019, in Cibitoke Province, a Burundian army position was attacked by a group of heavily\narmed individuals. The Government of Burundi accused Rwanda of being responsible for the\nattack, and Rwanda formally denied the accusation. Between 19 and 23 February 2020, in\nBujumbura Province, there were reports of an armed group and several exchanges of gunfire\nwith law enforcement agencies. The official account of this incident reported 22 armed\ncriminals and 2 police officers killed and 6 of the assailants captured. However, several of\nthe armed men were shot dead after being captured by Imbonerakure-backed security forces."},{"id":"a-hrc-45-32-p0022","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"22","seq":24,"section":"3. Transitional justice","text":"On 14 January 2020, the president of the Truth and Reconciliation Commission\npresented the progress report for 2019. The Commission identified 142,505 Burundians\nkilled or missing from the time of independence in 1962 until the end of the civil war in\nDecember 2008. The Commission reportedly has information on the conditions in which the\nvictims were killed or reported missing, and on the perpetrators. The Truth and\nReconciliation Commission also located thousands of mass graves, in all provinces. Since\nthe beginning of 2020, it has unearthed more sites and has exhumed thousands of human\nremains. The victims’ clothing and the material used to kill them − mainly in 1972, when the\nvictims were principally Hutus − will be kept in a museum.10"},{"id":"a-hrc-45-32-p0023","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"23","seq":25,"section":"4. Health situation","text":"Burundi has faced a cholera epidemic since June 2019, an epidemic-scale “upsurge”\nof malaria cases since January 2019 and the COVID-19 pandemic since March 2020, and it\nhas had to prepare for a possible outbreak of the Ebola virus, which has been circulating in\nthe Democratic Republic of the Congo since 2018."},{"id":"a-hrc-45-32-p0024","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"24","seq":26,"section":"4. Health situation","text":"For months, the Government of Burundi denied that there was actually a serious health\nsituation in the country, for example refusing to qualify the malaria “upsurge” as an epidemic\nor to acknowledge the existence of the COVID-19 outbreak, since, according to former\nPresident Nkurunziza, Burundi was protected from it “by the grace of God”. On 12 May\n2020, in the midst of the pandemic, the Government declared four World Health Organization\nofficials persona non grata, including the Organization’s representative in the country.\nBurundi was one of the only countries with positive cases of COVID-19 that did not adopt\nany restrictions on gatherings, which, on the contrary, increased during the election\ncampaign. According to the country’s official data, as of 20 July 2020, out of a total of 9,461\ntests carried out, 328 cases of COVID-19 had been detected, with only 1 death reported. Such\nfigures have regularly been criticized for being excessively low."},{"id":"a-hrc-45-32-p0025","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"25","seq":27,"section":"4. Health situation","text":"Since the death of President Nkurunziza on 8 June 2020, the authorities have stressed\nthe need to take barrier measures and have encouraged people with symptoms to visit health\ncentres, although information about the true scale of the pandemic continues to be lacking.\nIn his speech of 30 June 2020, President Ndayishimiye said that the COVID-19 pandemic\nwas “the greatest enemy” of the Burundian people."},{"id":"a-hrc-45-32-p0026","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"26","seq":28,"section":"5. Humanitarian situation","text":"As at 30 June 2020, according to the Office of the United Nations High Commissioner\nfor Refugees, 333,703 Burundians were still refugees in bordering countries, 6,423 had been\nrepatriated from the United Republic of Tanzania since 1 January 2020 and 3,247 new\narrivals had been officially registered in neighbouring countries."},{"id":"a-hrc-45-32-p0027","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"27","seq":29,"section":"5. Humanitarian situation","text":"In 2020, according to the figures agreed by the Office for the Coordination of\nHumanitarian Affairs and the Government of Burundi, 1.7 million persons are in need of\nhumanitarian assistance and 1.7 million are suffering from food insecurity. There are still\nabout 100,000 persons internally displaced within their own country, the majority of whom\nare economically vulnerable women heads of household.11"},{"id":"a-hrc-45-32-p0028","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"28","seq":30,"section":"A. Main trends","text":"In the context of the 2020 electoral process, which began in 2019, human rights\nviolations took on a political dimension. Above all, they affected the right to security and\nfreedom, but also the right to life and to be free from torture or ill-treatment, as well as civil\nliberties. The victims were mainly opposition political parties and their members, as well as\njournalists and independent media outlets. Violent clashes took place between members of\nthe ruling party and the CNL, but there was no mass violence, specifically thanks to the\ninternational community’s, and the Commission’s, calls for calm and reminders that political\nleaders were responsible for the actions of their activists."},{"id":"a-hrc-45-32-p0029","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"29","seq":31,"section":"A. Main trends","text":"The perpetrators of these human rights violations were mainly members of the\nImbonerakure and local administrative officials acting alone or jointly with the police or the\nNational Intelligence Service. In cases of arbitrary arrest and detention, the responsibility lies\nmainly with police and National Intelligence Service officers, but also with members of the\njudiciary."},{"id":"a-hrc-45-32-p0030","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"30","seq":32,"section":"A. Main trends","text":"The vast majority of victims have been deprived of their right to an effective remedy\ndue to the lack of independence and impartiality of the judiciary, which is still plagued by\ncorruption. It has remained a tool of repression against the political opposition and has also\nbeen used to censor the press and human rights defenders."},{"id":"a-hrc-45-32-p0031","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"31","seq":33,"section":"1. Weakened political opposition","text":"Opposition political parties and their members, mainly from the CNL, considered the\nmain rival of the ruling party, suffered serious human rights violations, which intensified in\nthe run-up to the elections. The aim was to weaken or even eliminate the chances of the CNL\nwinning the election by preventing it from carrying out certain political activities, including\ncampaigning, by intimidating its members, candidates and representatives in order to\ndiscourage them from carrying out their work and even by destroying the property and crops\nof some of its members. On election day, the aim was to prevent certain opponents from\nvoting freely and in secret and to prevent representatives appointed by the opposition parties\nfrom observing the vote. Independent candidates and candidates from other parties were more\nrarely targeted, which attests to the organized and targeted nature of such acts.\nRight to liberty"},{"id":"a-hrc-45-32-p0032","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"32","seq":34,"section":"1. Weakened political opposition","text":"Dozens of CNL activists, including those in positions of responsibility within the party\nas well as candidates for legislative and communal elections, were arbitrarily arrested and\ndetained, for example for campaigning outside the officially designated days and hours while\nwearing the party’s cap or symbol, holding illegal meetings or seeking to “disrupt the\nelection”. Some were arrested following physical clashes with members of the Imbonerakure\nattempting to disrupt election rallies. While most were released after a few days or weeks,\nsome were sentenced to relatively heavy sentences of several years in prison after hastily\narranged trials with expedited procedures, while others remained in pretrial detention."},{"id":"a-hrc-45-32-p0033","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"33","seq":35,"section":"1. Weakened political opposition","text":"The judiciary continued to be used often as a tool of political repression and to be\nbiased in favour of the CNDD-FDD party. The Imbonerakure involved in clashes with\n11   Office for the Coordination of Humanitarian Affairs, Burundi Situation Report, updated on 21 July\n2020. Available at https://reports.unocha.org/en/country/burundi.\nmembers of the CNL have rarely been prosecuted or punished. The Ministry of Public\nSecurity has consistently identified members of the CNL as responsible for “90 per cent” of\nsuch incidents, without bothering to carry out investigations.\nRight to life and physical integrity"},{"id":"a-hrc-45-32-p0034","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"34","seq":36,"section":"1. Weakened political opposition","text":"Several members of the CNL have been murdered in reprisal for their political\nactivities. Violent clashes between the Imbonerakure and members of the CNL have resulted\nin injuries and deaths on both sides. Members of the Imbonerakure have also beaten up\nactivists from the CNL individually or in small groups; some victims have been seriously\ninjured, and some of these incidents constitute a form of torture.\nRight to take part in the conduct of public affairs"},{"id":"a-hrc-45-32-p0035","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"35","seq":37,"section":"1. Weakened political opposition","text":"Acts aimed at preventing certain opposition party candidates from standing for\nelection have taken various forms. In addition to threats, physical violence and arbitrary arrest\nand detention, the authorities have also made abusive use of legal means to prevent them\nfrom running."},{"id":"a-hrc-45-32-p0036","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"36","seq":38,"section":"1. Weakened political opposition","text":"The Independent National Electoral Commission rejected the applications of 4 of the\n10 candidates who filed for the presidential election and of several opposition party lists for\nthe legislative election in some provinces, mainly invoking the lack or invalidity of\ndocuments proving respect for ensuring an ethnic or gender balance. However, it offered no\nopportunity to correct such failures. The Constitutional Court has generally validated such\ndecisions, with few exceptions."},{"id":"a-hrc-45-32-p0037","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"37","seq":39,"section":"1. Weakened political opposition","text":"On 18 May 2020, the State Prosecutor of the Republic requested the Independent\nNational Electoral Commission to remove 59 candidates from the CNL from the lists for the\nlegislative and communal elections, as the candidates were being prosecuted, with some held\nin pretrial detention and others officially wanted. On 19 May, the chair of the Independent\nNational Electoral Commission sent their names to the heads of the provincial electoral\ncommissions. Indeed, according to the Electoral Code, persons in pretrial detention\ntemporarily lose their voting rights and as such cannot be candidates in legislative and\ncommunal elections. 12 Such provisions are not only incompatible with the right to be\npresumed innocent; combined with the arbitrary mass detention of candidates from the CNL,\nthey are an abusive restriction on the right to stand for election.\nFreedom of peaceful assembly and association"},{"id":"a-hrc-45-32-p0038","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"38","seq":40,"section":"1. Weakened political opposition","text":"Before the election campaign began, local officials imposed arbitrary restrictions on\nthe CNL for the opening or inauguration of certain offices, as well as for the holding of\nlegitimate activities such as the organization of private or public meetings. Dozens of the\nparty’s offices were vandalized or were partially or totally destroyed, but the arrests following\nsuch events mainly targeted the party’s own members, who were accused of trying to harm\nthe ruling party."},{"id":"a-hrc-45-32-p0039","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"39","seq":41,"section":"1. Weakened political opposition","text":"During the election campaign, numerous election rallies were organized across the\ncountry by all the competing political parties. While most generally went well, several\nmeetings of the CNL were disrupted or encountered obstacles. Members of the\nImbonerakure, often with the support of local officials, tried to prevent some of them by\noccupying the venues that had been declared in advance with the local authorities.\nFreedom of expression"},{"id":"a-hrc-45-32-p0040","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"40","seq":42,"section":"1. Weakened political opposition","text":"Particularly virulent messages of hatred and hostility towards political opponents of\nthe CNDD-FDD party, sometimes with an ethnic dimension, circulated on social networks\nwithout eliciting the authorities’ condemnation or rebuke. The head of the CNL has regularly\nbeen presented by CNDD-FDD officials as an ally of “the country’s enemies” and\n“colonists”, or as a “puppet” of former President Pierre Buyoya. Such divisive comments\nhave fuelled and even legitimized hostility towards members of the party. In addition, the\nparty’s candidates have been arrested and prosecuted merely for criticizing local officials or\nauthorities or their actions."},{"id":"a-hrc-45-32-p0041","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"41","seq":43,"section":"2. Independent observers muzzled","text":"Journalists have been intimidated and threatened, including with death, to prevent\nthem from doing their work independently or covering sensitive issues. Some have been\nforced to seek permission from local authorities to travel, especially within the country. The\ncase of the four journalists of the Iwacu independent press group is representative of the\nproblem; they were sentenced on 30 January 2020 to two and a half years in prison for “a\nfailed attempt of complicity in undermining the internal security of the State” under articles\n16 and 607 to 626 of the Criminal Code, for having gone to cover reports of an armed clash\nbetween Burundian soldiers and an armed group on 22 October 2019. They were immediately\narrested when they arrived at the scene. Their conviction has been condemned by several\nindependent United Nations experts.13 That notwithstanding, on 5 June 2020 the Ntahangwa\nCourt of Appeal upheld the verdict."},{"id":"a-hrc-45-32-p0042","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"42","seq":44,"section":"2. Independent observers muzzled","text":"The press continued to be closely monitored by the National Communication Council.\nIn October 2019, the Council presented the Code of Conduct for the Media and Journalists\nin the 2020 Election Period, which obliges the media to work in synergy and prohibits the\nreporting of results other than those officially announced by the Independent National\nElectoral Commission or the use of opinion polls as a source of information. The fact that the\nCode was drawn up by the National Communication Council without consultation with\nprofessionals and that it de facto restricts freedom of the press has been denounced by the\nindependent media.\nHuman rights defenders and non-governmental organizations"},{"id":"a-hrc-45-32-p0043","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"43","seq":45,"section":"2. Independent observers muzzled","text":"The Government continued to make use of the judicial system to muzzle civil society.\nFor example, on 4 February 2020, some 20 human rights defenders and journalists in exile\nopposed to a third term for President Nkurunziza went on trial in absentia and without their\nrepresentation by counsel. Human rights defenders continue to be arbitrarily detained,\nincluding Germain Rukuki and Nestor Nibitanga, who were respectively sentenced to 32 and\n5 years of imprisonment."},{"id":"a-hrc-45-32-p0044","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"44","seq":46,"section":"2. Independent observers muzzled","text":"As a result of the measures taken in 2018 to increase control over foreign non-\ngovernmental organizations (NGOs) and their activities, in February 2020 such NGOs were\nordered to submit lists of their employees, including information on their ethnicities. On 20\nMarch 2020, the Government announced that those that did not respect the ethnic balance\nwould be “cancelled” and that inspections would be undertaken."},{"id":"a-hrc-45-32-p0045","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"45","seq":47,"section":"3. Population under control","text":"Control of the population by the Imbonerakure, often based on intimidation, including\nforced recruitment into the CNDD-FDD party, has increased in recent years. With the\nelectoral process, such practices continued, though they were directed more at the members\nof the CNL."},{"id":"a-hrc-45-32-p0046","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"46","seq":48,"section":"3. Population under control","text":"The fact that the Imbonerakure are everywhere in the hill districts and in the joint\nsecurity committees is a matter of concern even within the Government. The permanent\nsecretary of the National Security Council reiterated that the joint committees should not\nreplace either the police or the judiciary, that they should not organize night patrols without\nthe police and, above all, that they should be more inclusive so as to earn greater public trust.\nOn 3 March 2020, the Minister of the Interior called for the suspension of marches organized\nby young people affiliated with political parties, who were chanting songs and slogans, until\nthe beginning of the election campaign.\n13   See https://news.un.org/fr/story/2020/02/1062201."},{"id":"a-hrc-45-32-p0047","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"47","seq":49,"section":"3. Population under control","text":"The impact of such statements was limited because they were late in coming and were\nin contradiction with earlier instructions. On 15 January 2020, the permanent secretary of the\nNational Security Council had mentioned the need to revitalize the joint committees and to\n“control population flows and movements of travellers and to keep track every day of the\nforeigners staying in every household and at every hotel”."},{"id":"a-hrc-45-32-p0048","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"48","seq":50,"section":"3. Population under control","text":"Part of the population continued to be forced by the Imbonerakure and local officials\nto make contributions in cash or in kind, including to support the CNDD-FDD party, to\norganize political rallies or to give gifts to the party’s candidates."},{"id":"a-hrc-45-32-p0049","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"49","seq":51,"section":"3. Population under control","text":"Some people were prevented from participating in rallies organized by the CNL, in\nparticular owing to a lack of transport, while others were forced to participate in those\norganized by the CNDD-FDD party, as markets were closed down for the occasion. Some\nvoters had no choice but to vote for the ruling party in the various elections because they\ncould not vote in private or they were subjected to intimidation."},{"id":"a-hrc-45-32-p0050","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"50","seq":52,"section":"3. Population under control","text":"Children were forced to participate in political meetings organized by the CNDD-\nFDD party, as their classes were suspended. School principals threatened to lower students’\ngrades for the subject entitled “education” if they failed to take part. On election day,\nstudents, including minors, were forced to vote by local officials or school principals, who\ngave them the voting cards of deceased or exiled voters."},{"id":"a-hrc-45-32-p0051","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"51","seq":53,"section":"3. Population under control","text":"The electoral process took place at a time when the Burundian authorities were\nunderestimating the effect of the COVID-19 pandemic and even made use of the pandemic\nfor electoral purposes. The authorities insisted on organizing the elections without taking\nadequate measures to protect the population. They encouraged people to participate in\nmassive CNDD-FDD electoral rallies and refused to communicate transparently about the\nextent of the pandemic or the risks involved. They even threatened to punish those who took\nearly protective measures. Sick people were afraid to go for treatment or screening. Such\naction violated the right to health, and even the right to life."},{"id":"a-hrc-45-32-p0052","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"52","seq":54,"section":"4. Women in the electoral process","text":"In 2020, 52 per cent of Burundian voters are women. The Constitution provides for a\n30 per cent gender quota system, which has been implemented under the Electoral Code\nthrough a co-opting mechanism and blocked lists. Burundi ranks among the countries in\nAfrica 14 with the highest rate of women elected to national and decentralized office, for\nexample with 39 per cent of the National Assembly and 41 per cent of the Senate. In\naccordance with the constitutional quota, 5 of the 15 ministers in President Ndayishimiye’s\nGovernment are women. However, on average, only 12 to 18 per cent of those appointed or\nelected to institutions without gender quotas, such as provincial governorships or hill district\ncouncils, have been women. This shows the importance of special measures to accelerate the\nachievement of de facto equality between men and women in the country."},{"id":"a-hrc-45-32-p0053","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"53","seq":55,"section":"4. Women in the electoral process","text":"In the context of the electoral process, women members of opposition parties were\nvictims of arbitrary arrest and detention, but also of intimidation and threats, particularly\nwhen the electoral lists were published. Such actions were aimed at discouraging them from\nactively participating in the electoral process or at blocking them from exercising their civil\nliberties."},{"id":"a-hrc-45-32-p0054","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"54","seq":56,"section":"4. Women in the electoral process","text":"The electoral violence experienced by women is different from that affecting men. It\nis inherently sexist15 and is also linked to the preservation of traditional gender roles and\nstructural gender inequalities.16 Burundian women who engage in politics face multiple forms\nof discrimination, as there is a perception that political activity is difficult to reconcile with\ntheir roles as wives and mothers. Such prejudices, all of which block women from exercising\ntheir fundamental freedoms, exist both in the private sphere and in the political parties. The\ndifficulties and violence suffered by women in the opposition is made worse by the general\nclimate of intolerance towards the political opposition."},{"id":"a-hrc-45-32-p0055","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"55","seq":57,"section":"4. Women in the electoral process","text":"The Commission was unable to document sexual violence directly related to the\nelectoral process, in part owing to time constraints. Because of the trauma and stigma\nattached to such acts, victims are often discouraged from immediately reporting them.\nNevertheless, the Commission has continued to document cases of sexual violence\ncommitted inter alia for political reasons, as reported in paragraph 58 of this document."},{"id":"a-hrc-45-32-p0056","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"56","seq":58,"section":"C. Other violations","text":"The Commission had to conduct its investigations in exceptional circumstances owing\nto the COVID-19 pandemic. It had to cancel several missions to the countries bordering\nBurundi. In addition, it gave priority to investigating violations committed in the context of\nthe elections and to the economic underpinnings of the State, in accordance with its mandate.\nConsequently, the Commission has not been able to gather sufficient evidence to corroborate\ncertain allegations of violations of economic and social rights, such as the rights to an\nadequate standard of living, work or education, nor has it been able to comment on the\nevolution of certain trends mentioned in its previous report (A/HRC/42/49)."},{"id":"a-hrc-45-32-p0057","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"57","seq":59,"section":"1. Right to life","text":"People with a specific profile, such as currency traders and former members of the\nFAB (the former Burundian army), have been found dead a few days after their\ndisappearance, obviously having been executed. The police have also conducted operations\nin which people have been summarily executed instead of being apprehended. Bodies bearing\nsigns of violence continue to be found in public places, and the authorities make no attempt\nto establish the victims’ identities or the circumstances of their death. Recently, to set an\nexample, two police officers received sentences for killing civilians with their service\nweapons, in a welcome first step in the fight against police impunity."},{"id":"a-hrc-45-32-p0058","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"58","seq":60,"section":"2. Torture and sexual violence","text":"Acts of torture continued to be committed, including sexual and gender violence\naffecting mostly women and girls, but also men. Such violence was aimed at intimidating,\ncontrolling, repressing or punishing women and men for their supposed or actual political\nopinions, their refusal to join the ruling party or their links with an armed movement. These\ninclude cases of gang rape, but also the infliction of blows or burns on the genitals, buttocks\nor breasts and cases of forced nudity. Such violence was committed mainly by members of\nthe Imbonerakure or of the police during visits or attacks on the victims’ homes, but also in\nthe context of arrest or detention by the National Intelligence Service. Women have been\nraped after their repatriation to Burundi."},{"id":"a-hrc-45-32-p0059","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"59","seq":61,"section":"2. Torture and sexual violence","text":"The Commission is concerned about the structural nature of sexual violence in\nBurundi, as the testimonials collected since 2015 demonstrate that this type of violence\npersists and confirm the trends identified in its previous reports. Despite various programmes\ndesigned to facilitate access to justice for the most vulnerable persons, and specifically\nwomen, and the fact that there has been better judicial treatment of cases of gender violence, 17\nmost victims of sexual violence have received direct or indirect threats and have not dared to\nreport on the perpetrators or to seek assistance. This is inter alia due to the high number of\nperpetrators who are members of the security forces or the Imbonerakure, who have\ncontinued to enjoy almost total impunity."},{"id":"a-hrc-45-32-p0060","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"60","seq":62,"section":"3. Returnees","text":"Some returnees have continued to face hostility from local officials and the\nImbonerakure, who have intimidated and threatened them and have stolen their return kits.\n17   Republic of Burundi, Rapport national d’évaluation de la mise en oeuvre de la Déclaration et du\nProgramme d’actions de Beijing, May 2019, pp. 13 and 32.\nReturnees have sometimes been victims of serious violations that have forced them to go\nback into exile."},{"id":"a-hrc-45-32-p0061","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"61","seq":63,"section":"4. Rights of the child","text":"Since the beginning of the crisis in 2015, children have regularly been victims of\nviolations of their human rights, including their rights to liberty, security and physical\nintegrity; they have, in particular, been victims of sexual violence, as well as violations of\ntheir freedom of opinion and association through forced recruitment into the Imbonerakure\nor, in the case of younger children, into the CNDD-FDD “Little Eagles”."},{"id":"a-hrc-45-32-p0062","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"62","seq":64,"section":"4. Rights of the child","text":"Burundian children, especially girls, have suffered from the effects of the political\ncrisis, as they have been severely affected by violations of the rights of their parents and other\nmembers of their families. Some parents have lost the means to support their families as they\nhave had to flee the country. The disappearance or murder of a family member, especially a\nfather, has also left families unable to provide for children’s basic needs."},{"id":"a-hrc-45-32-p0063","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"63","seq":65,"section":"4. Rights of the child","text":"Families have been separated as a result of these violations, including when they have\nfled the country, and many children have been left orphaned. More than half of Burundian\nrefugees are thus children, and a large number are unaccompanied.18 Many boys and girls\nhave been traumatized by serious violations of the rights of family members, which they have\noften seen first-hand. Many need psychosocial and even medical care."},{"id":"a-hrc-45-32-p0064","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"64","seq":66,"section":"D. Economic underpinnings of the State","text":"Corruption, misappropriation of public funds, including funds from international\ndevelopment assistance, conflicts of interest and the illegal protection of interests underpin\nthe functioning of the Burundian economy, especially in the most lucrative sectors such as\nmining or government contracts, even though most of this behaviour is criminalized under\nBurundian law."},{"id":"a-hrc-45-32-p0065","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"65","seq":67,"section":"D. Economic underpinnings of the State","text":"In Burundi, a patrimonial concept of power dates back many years. It is the result of\na structural problem of sharing of resources, linked to the weakness of the economy, and of\nthe means of industrial production in particular, as well as the scarcity of land. The only way\nto gain access to resources is by taking power or being close to it, including through illicit\neconomic and financial means.19 This is one of the root causes of human rights violations in\nBurundi, as the perpetrators of such violations seek to eliminate all political opposition in\norder to ensure that a minority remains in power and has access to wealth. As long as such\npractices persist, there will be no incentive to carry out an in-depth reform of the system so\nas to respect and protect human rights and combat corruption; quite the contrary."},{"id":"a-hrc-45-32-p0066","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"66","seq":68,"section":"D. Economic underpinnings of the State","text":"The effects of such economic malfeasance are worrying in view of the extreme\npoverty in which more than 70 per cent of Burundians live. The State has been deprived of\ncrucial resources to finance the realization of human rights, both for economic, social and\ncultural rights such as access to health, education, food and water, and for civil and political\nrights. For example, less than 5 per cent of the Burundian population has access to electricity,\nand access to water and sanitation remains very low.20 The average length of schooling is 3.1\nyears instead of the planned 11.3 years,21 and 1.7 million Burundians are food-insecure. The\njudicial system is sorely lacking in resources, which contributes to widespread corruption\nwithin the judiciary and subjugates it to the executive branch.22 The situation is so bad that\nthe authorities have forced the already poor population to financially support the organization\nof the 2020 elections and various projects.23"},{"id":"a-hrc-45-32-p0067","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"67","seq":69,"section":"1. Corruption","text":"Corruption takes many forms and specifically includes trading in influence and abuse\nof office or power. To obtain a mining licence, a large sum of money must be paid to certain\npersons holding high political or administrative positions or to senior CNDD-FDD officials,\neither directly or through intermediaries. Some of those who benefit from this also hold\nshares in mining companies, sometimes through front operations. The Commission has also\nreceived allegations that there are similar practices in most sectors of the Burundian\neconomy, especially when foreign companies want to invest in Burundi."},{"id":"a-hrc-45-32-p0068","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"68","seq":70,"section":"2. Misappropriation of public funds","text":"From a global perspective, the Commission drew on a study of official development\nassistance disbursements from the World Bank to the poorest countries, carried out by\neconomists who showed that between 1990 and 2010 there was a strong link between such\npayments and residents’ transfers to tax havens.24 The Commission relied on public data from\nthe World Bank listing the amounts paid out per quarter and per project and the amounts of\nassets held by Burundian residents abroad, published by the Bank for International\nSettlements from 2010 to 2019.25 In this period, there is clearly a correlation for assets held\nin Belgium, Switzerland and Luxembourg. The holdings in question are those of natural or\nlegal persons with residence in Burundi, but such persons are not necessarily nationals. There\nmay be legal grounds for such transfers, but the extent of the coincidence calls for further\ninvestigation."},{"id":"a-hrc-45-32-p0069","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"69","seq":71,"section":"2. Misappropriation of public funds","text":"The Commission has received credible allegations of misappropriation of public funds\nintended for various development projects financed by international assistance. For example,\nsome Burundian families whose property was expropriated for the construction of public\nprojects did not receive the planned compensation, which reportedly had been partially\nmisappropriated. The Government of Burundi has publicly acknowledged that such\nmisappropriation has taken place in connection with the construction of the presidential\npalace in Gasenyi.26"},{"id":"a-hrc-45-32-p0070","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"70","seq":72,"section":"2. Misappropriation of public funds","text":"The construction of the Jiji and Mulembwe dams was to be accompanied by the\npayment by the Government of Burundi of US$ 14.3 million for the electrification of local\nvillages and compensation for those whose property was expropriated. 27 However, the\nfinance bills provided much lower amounts for the compensation. The difference between\nthese budgets and the amounts called for in the development assistance thus raises some\nquestions."},{"id":"a-hrc-45-32-p0071","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"71","seq":73,"section":"2. Misappropriation of public funds","text":"Mining agreements between private companies and the State generally provide for the\npayment by the company of annual compensation to the communes and the payment of\nhundreds of thousands of dollars for the economic and social development of the region.\nHowever, the Commission has reasonable grounds to believe that under several mining\nconcession agreements, a significant portion of these funds has not been received by the\nintended recipients or has not materialized in development projects on the ground. This raises\n22 A/HRC/39/CRP.1, paras. 462–579; and A/HRC/36/CRP.1, paras. 318–320 (document available on\nthe Commission’s website).\n23 A/HRC/39/CRP.1, paras. 634–646.\n24 J.J. Andersen, N. Johannesen and B. Rijkers, “Elite Capture of Foreign Aid: Evidence from Offshore\nBank Accounts”, Policy Research Working Paper 9150 (World Bank, 2020).\n25 Bank for International Settlements, “Banks’ cross-border positions on residents of Burundi”.\nAvailable at http://stats.bis.org/statx/srs/table/A6.2?c=BI&p (accessed 6 August 2020).\n26 See www.dw.com/fr/construction-dun-nouveau-palais-pr%C3%A9sidentiel-des-burundais-\nexpropri%C3%A9s-attendent-toujours/a-41072323.\n27 See http://documents.worldbank.org/curated/en/241731548424957473/pdf/PHJIMU-Rapport-dAudit-\n1-janv-au-30-Juin-2018.pdf.\nquestions about what happened to those payments and, if they were not made, why the State\ndid not seek to enforce the terms of those contracts, that were supposed to benefit its people."},{"id":"a-hrc-45-32-p0072","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"72","seq":74,"section":"2. Misappropriation of public funds","text":"Lastly, despite the fact that since 2016, the $800 monthly pay of Burundian military\npersonnel deployed in the African Union Mission in Somalia has been transferred directly by\nthe African Union into their personal bank accounts in order to avoid any misappropriation,\nthe Commission has reasonable grounds to believe that the Government of Burundi has\ncontinued to systematically tap into part of the pay using surreptitious means."},{"id":"a-hrc-45-32-p0073","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"73","seq":75,"section":"2. Misappropriation of public funds","text":"Most of the country’s technical and financial partners are aware of the risk of diversion\nof funds. They have taken steps to minimize the risk by ceasing to contribute directly to the\nState budget, instead supporting operational partners such as non-governmental\norganizations, or directly paying the beneficiaries of their assistance. However, the measures\nthat are taken are not always sufficient."},{"id":"a-hrc-45-32-p0074","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"74","seq":76,"section":"3. Conflicts of interest and the illegal protection of interests","text":"On the basis of publicly available information, the Commission has noted numerous\ncases of conflict of interest to which the authorities have turned a blind eye, even though,\nwithout being an offence in itself, such a situation is conducive to corruption, favouritism\nand the illegal protection of interests, which for their part are offences under Burundian law."},{"id":"a-hrc-45-32-p0075","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"75","seq":77,"section":"3. Conflicts of interest and the illegal protection of interests","text":"For example, despite the fact that article 142 of the Constitution prohibits ministers\nfrom engaging in any other activities, one of President Nkurunziza’s ministers has retained\nhis position as director of a civil engineering company that may do work in areas falling\nwithin his competence as a minister. Also, a senior government official has his own\ncommunications company, which has been awarded government contracts in the area directly\nunder his responsibility. Several senior officials or assistants to ministers have been\nappointed to the boards of companies operating in fields covered by their ministerial\nportfolios."},{"id":"a-hrc-45-32-p0076","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"76","seq":78,"section":"3. Conflicts of interest and the illegal protection of interests","text":"The Commission has also received credible allegations that several persons holding\nhigh political or administrative positions, including within the CNDD-FDD party, own\nsignificant shares in companies holding veritable monopolies, either in law or in practice, for\nthe marketing of certain products or services in the country."},{"id":"a-hrc-45-32-p0077","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"77","seq":79,"section":"4. Government contracts","text":"Government contracts are awarded in Burundi with very little transparency and much\nabuse of privately agreed-upon terms that often benefit those close to the people in power,\nwhich facilitates corruption and misappropriation of public funds. In 2017, government\ncontracts accounted for more than 215 billion Burundian francs (or over $111 million) – or\nmore than a quarter of the current expenditure of the State’s estimated annual budget –\nincluding 18 billion francs (or about $9 million) in privately negotiated agreements. 28\nPractices such as overcharging and under-delivery of services are common. For example,\nsome goods such as vehicles have been purchased at two to three times their current market\nvalue, and roads have very quickly fallen into disrepair after being built."},{"id":"a-hrc-45-32-p0078","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"78","seq":80,"section":"5. Customs fraud","text":"Several products, including minerals such as gold, but also coffee and oil, are exported\nor imported without being officially declared, for example by means of the corruption of\ncertain authorities, thus depriving the State of substantial tax revenues. Despite the fact that\nthe publicly available information on the country’s international trade is fragmentary, the\nCommission had noted significant inconsistencies which are a matter of concern. Of course,\nsuch discrepancies can be explained in part by reporting or accounting errors, differences in\nthe calculation of market values and the application of different exchange rates. However,\ngiven their magnitude, such differences raise the possibility of large-scale customs fraud and\nshed light on the general lack of transparency in this area.\n28   See www.armp.bi/files/Rapports/Rapports%20Annuels/ARMP_RAPPORT_ANNUEL_2017_\nVersion_du_20_avril_2018_pdf.pdf."},{"id":"a-hrc-45-32-p0079","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"79","seq":81,"section":"6. Graft","text":"The Commission has obtained evidence that several persons holding high political or\nadministrative positions, including within the CNDD-FDD party, have real estate holdings\nand/or assets in foreign countries, sometimes under a front name, and that they or members\nof their entourage hold directors’ positions in several companies based abroad, including in\nSouth Africa, Kenya and Belgium. In addition, the assets of several Burundian officials,\nparticularly in real estate, appear to be completely out of proportion with their official\nremuneration."},{"id":"a-hrc-45-32-p0080","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"80","seq":82,"section":"6. Graft","text":"In view of the corruption in the Burundian economy and allegations of the payment\nof large sums of money to those same persons in order to obtain operating licences,\nparticularly in the mining sector, the Commission has reasonable grounds to believe that\nthose officials have enriched themselves illegally. It is worth noting that Burundian elected\nofficials do not systematically declare their assets to the Supreme Court at the beginning and\nend of their terms of office, as required, however, by articles 95 and 159 of the Constitution."},{"id":"a-hrc-45-32-p0081","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"81","seq":83,"section":"1. Responsibility of the Burundian State","text":"Once again, the Commission has found that the Burundian State can be held\nresponsible for the acts constituting human rights violations documented in this report. 29"},{"id":"a-hrc-45-32-p0082","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"82","seq":84,"section":"1. Responsibility of the Burundian State","text":"The actions of agents of the State, particularly officers of the National Intelligence\nService and the police, but also of the administrative authorities that represent the State in\nthe provinces, municipalities, districts and hill districts, are directly attributable to the\nBurundian State, in conformity with its obligation to respect human rights and ensure that its\nagents refrain from violating them."},{"id":"a-hrc-45-32-p0083","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"83","seq":85,"section":"1. Responsibility of the Burundian State","text":"The Imbonerakure often act alone or sometimes in the presence of representatives of\nthe police, the National Intelligence Service or local authorities. They enjoy considerable\nlatitude in carrying out their activities, conferred on them by the Burundian authorities who\nhave the means to control them, as well as almost total impunity. Imbonerakure are still\nregularly – indeed, almost routinely – used to supplement or replace the security forces,\nparticularly in rural areas, at the request or with the consent of members, including senior\nofficials, of the National Intelligence Service, the police, the Office of the President and local\nauthorities. Some have military material and equipment reserved in principle for the defence\nand security forces, such as elements of military uniforms and boots, which attests to their\ncentral role within the formal and informal security structures of the Burundian State. When\nthe conduct of the Imbonerakure is acknowledged and adopted by agents of the State, when\nthey act on the instructions of such agents or when they act in “complete dependence” on or\nunder the “effective control” of such agents, the Burundian State is directly responsible for\ntheir actions."},{"id":"a-hrc-45-32-p0084","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"84","seq":86,"section":"1. Responsibility of the Burundian State","text":"In the rare cases in which the Imbonerakure reportedly acted outside these scenarios,\nthe nearly general impunity they enjoy following their acts also means that the responsibility\nof the Burundian State is engaged, in conformity with its obligation to protect human rights.\nIndeed, the State must, when it is aware or should have been aware of violations or abuses\ncommitted by third parties, undertake effective investigations and prosecutions, which has\nnot generally been the case."},{"id":"a-hrc-45-32-p0085","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"85","seq":87,"section":"2. Responsibility of armed groups","text":"Because the Commission has not had access to victims and the Government has\nrepeatedly refused to pass on information, the Commission has been unable to corroborate\nthe information it has received on the involvement of armed groups in human rights\nviolations, in particular in relation to security incidents involving them.\n29   See A/HRC/36/54 and Corr.1, A/HRC/39/63 and A/HRC/42/49."},{"id":"a-hrc-45-32-p0086","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"86","seq":88,"section":"A. Constituent elements and types of crimes","text":"The Commission still has reasonable grounds to believe that crimes against humanity,\nas defined in the Rome Statute, have been committed in Burundi. These crimes include\nmurder, imprisonment or other severe forms of deprivation of physical liberty, torture, rape\nand other forms of sexual violence of comparable gravity and political persecution.30"},{"id":"a-hrc-45-32-p0087","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"87","seq":89,"section":"A. Constituent elements and types of crimes","text":"The Commission has documented violent incidents committed during the electoral\nprocess in various provinces by different perpetrators who had similar types of modus\noperandi and a common objective, namely to prevent the political opposition from winning\nthe communal, legislative and presidential elections of 20 May 2020 and to allow the CNDD-\nFDD party to remain in power. Such incidents can therefore be described as “systematic\nattacks” deliberately targeting civilians. The objective of winning the elections by any means\nand staying in power was regularly reiterated by representatives of the Government and the\nCNDD-FDD party, as well as by local authorities. The fact that the candidates, agents and\nlocal officials of the CNL were almost exclusively targeted shows that there was a strategy\nagainst the party, considered to be the main rival of the CNDD-FDD party in the elections.\nThe alleged perpetrators of these international crimes are necessarily informed of this\nobjective, which means that they must understand the backdrop against which they act."},{"id":"a-hrc-45-32-p0088","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"88","seq":90,"section":"B. Individual responsibility","text":"The Commission has updated its list of alleged perpetrators of crimes against\nhumanity, which remains confidential in order to protect sources and to respect the\npresumption of innocence of the alleged perpetrators. However, the Commission reserves the\nright to share the list. The Commission is extremely concerned about the fact that some of\nthe individuals on the list hold senior positions in the new Government and have been\npromoted within the defence and security forces since the new President, Mr. Ndayishimiye,\ntook office."},{"id":"a-hrc-45-32-p0089","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"89","seq":91,"section":"V. Risk factors","text":"Common risk factors of criminal atrocities indicating a possible deterioration of the\nhuman rights situation in the context of the electoral process have diminished with the current\npolitical transition, but none have entirely disappeared. The structural ones remain\nunchanged.31 It is still crucial to take tangible measures to bring about positive change."},{"id":"a-hrc-45-32-p0090","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"90","seq":92,"section":"V. Risk factors","text":"Risk factor 1, relating to an unstable political, economic and security environment, is\nstill present: the security situation remains volatile, as evidenced by various incidents that\nhave taken place since October 2019 and recurrent tensions with some neighbouring\ncountries; many Burundians, both inside and outside the country, are in a humanitarian\nemergency; the country is going through a serious economic crisis and the majority of the\npopulation is living in abject poverty; and some political tension remains, with allegations of\nmassive electoral fraud and repression of the CNL. One way of mitigating political tension\nis for the authorities to stop violations of the rights of political opponents."},{"id":"a-hrc-45-32-p0091","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"91","seq":93,"section":"V. Risk factors","text":"Risk factors 2 and 3 relate to the general impunity enjoyed by the main perpetrators\nof serious human rights violations. They are linked to the weakness of State structures\ncapable of preventing or stopping such violations. To reduce their occurrence, it is\nindispensable to ensure the independence and impartiality of the judiciary. However, it is\ndifficult to foresee positive developments in this regard as long as the perpetrators of the\nviolations, including the Imbonerakure, continue to enjoy nearly total impunity."},{"id":"a-hrc-45-32-p0092","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"92","seq":94,"section":"V. Risk factors","text":"Risk factor 4 is the existence of motives, aims or other motivating factors justifying\nthe use of violence against specific groups. The existence of economic interests linked to the\npreservation of power, which is the key to control over the distribution of the country’s\nresources, is an important element. The authorities must fight corruption and\nmisappropriation of funds more effectively, including at the highest level of the State, to\nmitigate this risk factor. The Truth and Reconciliation Commission should adopt a more\ninclusive approach in its work and integrate the other dimensions of transitional justice into\nits activities in order to reduce the risk that grievances from the past and the desire for revenge\nmight be used for political purposes."},{"id":"a-hrc-45-32-p0093","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"93","seq":95,"section":"V. Risk factors","text":"Risk factor 5, which relates to the ability of potential perpetrators to commit criminal\natrocities, cannot be mitigated as long as the Imbonerakure remain everywhere to be seen in\nthe public sphere and substitute themselves for the law enforcement and security forces,\nincluding in joint security committees."},{"id":"a-hrc-45-32-p0094","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"94","seq":96,"section":"V. Risk factors","text":"The lack of mitigating factors (risk factor 6) such as a strong, organized and\nrepresentative national civil society and free, diverse and independent media remains a\nserious concern. President Ndayishimiye’s remarks on this subject during his inaugural\naddress were not reassuring. The possibility of opening a democratic space, which can take\nplace immediately, is a key indicator of the direction that the new Government will take. A\nresumption of cooperation with the entire United Nations system, including the Office of the\nUnited Nations High Commissioner for Human Rights, but also with international non-\ngovernmental organizations working on human rights, would be another important mitigating\nfactor."},{"id":"a-hrc-45-32-p0095","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"95","seq":97,"section":"V. Risk factors","text":"Risk factor 7, which relates to a climate and circumstances conducive to violence and\nhuman rights violations, including the politically motivated exploitation of identity, past\nevents or motives to resort to violence, worsened with the elections of 2020. Provocative\nstatements and incitement to hatred aimed at political opponents, sometimes with an ethnic\ndimension, increased. The authorities should take measures to effectively combat violations\nof the fundamental human rights of political opponents and acts of violence, including sexual\nviolence, against women and children, and to punish the perpetrators of hate speech."},{"id":"a-hrc-45-32-p0096","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"96","seq":98,"section":"V. Risk factors","text":"The main triggering factor (risk factor 8), which was the various 2020 elections, has\ndisappeared. However, the new authorities in Burundi still perceive the measures taken by\nthe international community as a threat to the State’s sovereignty. In the long term, the\nallegations of massive fraud during the elections of 20 May 2020 are also likely to weigh on\nthe legitimacy of the people who have just come to power. It remains to be seen whether\nattacks on the life, physical integrity, liberty and security of members of the opposition parties\nperpetrated during the electoral process will continue or will stop in the coming months."},{"id":"a-hrc-45-32-p0097","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"97","seq":99,"section":"V. Risk factors","text":"The continued presence of all these risk factors provides an objective basis with which\nto grasp the reality of the human rights situation in Burundi. Just as the international\ncommunity’s vigilance helped to limit the level of violence during the electoral process, it is\ncrucial in the transitional period for the human rights situation during the first months of the\nnew Government to be followed with the utmost attention by the international community.\nThe international community must not miss this opportunity to call for specific measures\nalong these lines."},{"id":"a-hrc-45-32-p0098","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"98","seq":100,"section":"VI. Conclusions and recommendations","text":"The Commission has reasonable grounds to believe that serious human rights\nviolations – some of which may constitute crimes against humanity – have been\ncommitted since May 2019, mainly in the context of the 2020 electoral process. In\nparticular, it has documented cases of violations of the right to life, numerous cases of\narbitrary arrest and detention, torture and other ill-treatment, cases of rape and sexual\nviolence and violations of key civil liberties. The main perpetrators have been the\nImbonerakure, local administrative officials, police officers and agents of the National\nIntelligence Service. They have continued to enjoy nearly total impunity."},{"id":"a-hrc-45-32-p0099","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"99","seq":101,"section":"VI. Conclusions and recommendations","text":"Children suffer the harmful effects of the many human rights violations that\nhave been committed since 2015. The country’s economic system is underpinned by\ncorruption and misappropriation of public funds, including funding from international\ndevelopment assistance, to the benefit of high-ranking persons in the Government and\nadministration who have thus enriched themselves illegally. Such practices are not\nisolated cases, but the result of a system based on a patrimonial concept of power, and\nthey are directly linked to the human rights violations committed since 2015."},{"id":"a-hrc-45-32-p0100","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"100","seq":102,"section":"VI. Conclusions and recommendations","text":"The main risk factors, particularly those with a structural dimension, are still\npresent. They can only disappear if the new authorities take concrete action."},{"id":"a-hrc-45-32-p0101","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"101","seq":103,"section":"VI. Conclusions and recommendations","text":"In view of the historical depth of the Burundian crisis and the partly structural\ndimension of human rights violations, and taking into account the principle of the\nresponsibility to protect the people of Burundi, including in the context of the political\ntransition under way in the country, as well as the measures likely to mitigate risk\nfactors, the Commission first reiterates its previous recommendations. 32 Those\nrecommendations remain entirely valid and relevant, particularly those addressed to\nthe Burundian authorities concerning measures to be given priority in order to put an\nend to human rights violations and international crimes, to combat impunity and to\nimprove the human rights situation in the country, including the reopening of the\ndemocratic space and the protection of civil liberties. Its recommendations for longer-\nterm measures relating to the review of the legal framework and the reform of the\njudiciary remain crucial."},{"id":"a-hrc-45-32-p0102","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"102","seq":104,"section":"VI. Conclusions and recommendations","text":"The Commission also makes the following recommendations to the Burundian\nauthorities:\n(a)    To reopen the country office of the Office of the United Nations High\nCommissioner for Human Rights;\n(b)    To immediately release human rights defenders and journalists who have\nbeen arbitrarily detained, as well as all political prisoners, including those from\nopposition parties arrested and detained in the context of the 2020 elections;\n(c)    To guarantee the safety, freedom and physical integrity of members of\nopposition parties, including the Congrès national pour la liberté, and to ensure that\nthey are not subjected to intimidation, harassment or any form of discrimination as a\nreprisal for their political activities;\n(d)   To restore all civil liberties to enable future elections to be free, credible\nand transparent;\n(e)   To stop the Imbonerakure from usurping the functions of the security\nforces and the judiciary and to prosecute and punish, as an example, those who have\nbeen involved in violations, or alternatively to dissolve the Imbonerakure;\n(f)   To reform the Joint Human Security Committees to make them more\ninclusive and to limit the scope of their competence;\n(g)   To fulfil the specific obligations of the authorities with regard to women’s\nrights and the rights of the child;\n(h)    To put an end to the recruitment of children by the Imbonerakure and to\ndisband the CNDD-FDD party’s “Little Eagles”;\n(i)  To establish psychosocial care services for child victims and witnesses of\nserious human rights violations, particularly among returnees;\n(j)    To ensure access to justice and appropriate medical and psychosocial\nservices for victims of sexual violence, including male victims;\n(k)       To establish a 30 per cent quota for women on hill district councils;\n(l)       To resume full cooperation with the World Health Organization;\n(m) To take measures to effectively combat economic misfeasance, in\nparticular by ensuring transparency, competition and the establishment of objective\nand pre-established criteria for the awarding of government contracts, as well as an\neffective system of domestic remedies, and to investigate allegations of cases of ill-gotten\ngains;\n(n)  To become a party to the Extractive Industries Transparency Initiative\nand to implement the related standards;\n(o)    To systematically publish the annual budget, as implemented;\n(p)   To ensure that senior political and administrative officials systematically\nmake a public declaration of their assets upon taking office and at the end of their term."},{"id":"a-hrc-45-32-p0103","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"103","seq":105,"section":"VI. Conclusions and recommendations","text":"The Commission recommends that opposition rebel groups refrain from\nviolence."},{"id":"a-hrc-45-32-p0104","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"104","seq":106,"section":"VI. Conclusions and recommendations","text":"For the international community, in keeping with its duty of vigilance, the\nCommission has the following recommendations:\n(a)    To maintain an independent international mechanism that can objectively\nmonitor the human rights situation in Burundi, including through the monitoring of\nrisk factors and the implementation of the Commission’s recommendations;\n(b)    To base the resumption of international cooperation with Burundi and the\nlifting of sanctions on tangible progress in the area of human rights and the fight against\nimpunity and corruption;\n(c)   To ensure that refugees are not forced to return to Burundi until\nconditions in the country are favourable and to request free access to returnees to assess\ntheir situation;\n(d)    To support civil society organizations active in the field of human rights\nin Burundi, in particular for investigations and public reporting."},{"id":"a-hrc-45-32-p0105","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"105","seq":107,"section":"VI. Conclusions and recommendations","text":"The Commission recommends that States and international organizations\nfunding international development assistance programmes strengthen their procedures\nto minimize the risk of misappropriation of funds and systematically investigate\nallegations that they receive in order to ensure that such assistance is fully utilized for\nthe intended purposes and to the benefit of the intended beneficiaries."},{"id":"a-hrc-45-32-p0106","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"106","seq":108,"section":"VI. Conclusions and recommendations","text":"To the United Nations system, including its agencies, the Commission makes the\nfollowing recommendations:\n(a)     In accordance with the human rights due diligence policy, to provide\nsupport only when there are guarantees that those who are to benefit from it are not\nperpetrators of serious human rights violations, either individually or institutionally,\nand not to provide such support when there have been credible allegations in this regard\nor when the competent authorities fail to take the necessary corrective or mitigating\nmeasures;\n(b)   To strengthen support for the response to sexual and gender-based\nviolence in order to better address the specific needs of victims, including among\nrefugees."},{"id":"a-hrc-45-32-p0001-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"1","seq":109,"section":"I. Carte du Burundi","text":"Note verbale envoyée à la Mission permanente du Burundi\nle 22 août 2019","annex":1},{"id":"a-hrc-45-32-p0002-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"2","seq":110,"section":"I. Carte du Burundi","text":"Note verbale envoyée à la Mission permanente du Burundi\nle 2 septembre 2019","annex":1},{"id":"a-hrc-45-32-p0003-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"3","seq":111,"section":"I. Carte du Burundi","text":"Lettre envoyée à la Mission permanente du Burundi\nle 4 octobre 2019","annex":1},{"id":"a-hrc-45-32-p0004-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"4","seq":112,"section":"I. Carte du Burundi","text":"Lettre envoyée à la Mission permanente du Burundi\nle 4 février 2020","annex":1},{"id":"a-hrc-45-32-p0005-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"5","seq":113,"section":"I. Carte du Burundi","text":"Note verbale envoyée à la Mission permanente du Burundi\nle 13 juillet 2020\nAnnexe III\nRecommandations antérieures faites par la Commission","annex":1},{"id":"a-hrc-45-32-u0114-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":null,"seq":114,"section":"1. Recommandations faites en 2019","text":"Version française\n103. La tenue des élections de 2020 est un facteur de risque important. Afin qu’elles\npuissent se dérouler dans un climat apaisé tout en étant justes, libres, transparentes et\ncrédibles, la Commission adresse aux autorités burundaises les recommandations suivantes :\na)      Mettre en œuvre toutes les recommandations précédentes de la Commission33,\nqui restent plus que jamais valables et pertinentes, notamment celles concernant les mesures\nprioritaires afin de faire cesser les violations des droits de l’homme et les crimes\ninternationaux, de lutter contre l’impunité, et d’améliorer la situation des droits de l’homme\ndans le pays, ainsi que celles à moyen et à plus long terme relatives à la révision du cadre\njuridique et à la réforme du système judiciaire ;\nb)    Diligenter sans délai des enquêtes indépendantes et effectives sur les cas de\nviolations documentés par la Commission depuis 2015, afin de permettre l’instauration d’un\nclimat de confiance et de tolérance politique encourageant une participation inclusive dans\nle processus électoral ;\nc)      Se réengager de manière constructive et coopérative auprès de tous les\nmécanismes internationaux et régionaux des droits de l’homme et du Haut-Commissariat aux\ndroits de l’homme, en leur permettant d’assurer pleinement et librement leurs mandats de\nsuivi des droits de l’homme ;\nd)      Assurer l’indépendance structurelle et financière des mécanismes nationaux\ndes droits de l’homme et renforcer la capacité de leurs membres ;\ne)      Prendre les mesures nécessaires afin de garantir la liberté d’établissement,\nd’organisation et de fonctionnement des ONG étrangères et nationales, y compris en révisant\nles lois qui les régissent ;\nf)       Prendre les mesures nécessaires afin de garantir la liberté d’information dans\nle pays et le droit des médias locaux et internationaux d’exercer leurs activités conformément\naux normes internationales, y compris en révisant les lois sur la presse et le Conseil national\nde la communication ;\ng)     Garantir la jouissance effective des libertés publiques, notamment les libertés\nd’opinion, d’expression, d’accès à l’information, d’association, d’assemblée et de religion,\ny compris en mettant fin à toute pratique de recrutement forcé au sein du parti au pouvoir et\nde sa ligue des jeunes ;\nh)      Appliquer les Lignes directrices sur l’accès à l’information et les élections en\nAfrique et les Lignes directrices sur la liberté d’association et de réunion en Afrique de la\nCommission africaine des droits de l’homme et des peuples ;\ni)      Garantir que tous les partis politiques peuvent mener leurs activités légitimes\nen toute liberté et sécurité, dans un climat de tolérance politique, notamment en sanctionnant\ntout propos d’incitation à la haine et à la violence contre les autres partis politiques et leurs\nmembres ;\nj)     Garantir, dans la pratique, notamment en révisant le Code électoral, le droit à\nprendre part à la gestion des affaires publiques sans discrimination ;\nk)      Garantir, dans la pratique, l’indépendance structurelle de la Commission\nélectorale nationale indépendante, notamment en révisant le décret la régissant afin que sa\ncomposition soit inclusive et équilibrée, et renforcer les capacités de ses membres aux\néchelons municipal et provincial ;","unnumbered":true,"annex":1},{"id":"a-hrc-45-32-u0115-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":null,"seq":115,"section":"1. Recommandations faites en 2019","text":"l)     Permettre l’accès d’observateurs électoraux indépendants, internationaux et\nrégionaux, et leur garantir, ainsi qu’aux observateurs nationaux issus de la société civile ou\ndes partis politiques, une liberté de mouvement et d’action avant, pendant et après les\nélections ;\nm)      Appliquer les Directives pour les missions d’observation et de suivi des\nélections de l’Union africaine ;\nn)     Permettre aux opposants politiques de rentrer d’exil afin de participer aux\nélections de 2020, et garantir leur liberté et leur sécurité, notamment en annulant les mandats\nd’arrêt contre ceux qui n’ont pas utilisé ou prôné la violence ;\no)     Libérer immédiatement tous les prisonniers politiques arrêtés et détenus en lien\navec l’exercice de leurs droits démocratiques ;\np)      Renforcer la formation des forces de maintien de l’ordre, afin d’éviter les\nmauvais traitements et d’assurer une gestion pacifique des foules ;\nq)      Appliquer les Lignes directrices pour le maintien de l’ordre par les agents\nchargés de l’application des lois lors des réunions en Afrique, et le manuel de formation\ny relatif, élaborés par la Commission africaine des droits de l’homme et des peuples ;\nr)       Mettre fin à l’impunité des Imbonerakure en exerçant un contrôle sur eux, afin\nd’éviter l’usurpation des fonctions des forces de sécurité ou de la justice et de faire cesser\nleurs activités répressives et démonstrations de force sur les collines ;\ns)     Mettre fin à toutes les contributions illégales.\n104. À tous les partis politiques burundais, qu’ils participent ou non aux élections, la\nCommission recommande de s’abstenir de tout acte violent et de toute incitation à la haine et\nà la violence, notamment dans le contexte des élections de 2020.\n105. Aux groupes rebelles d’opposition, la Commission recommande de s’abstenir de tout\nacte violent et de toute incitation à la haine et à la violence.\n106. À la communauté internationale, y compris l’Union africaine et le système des\nNations Unies, la Commission adresse les recommandations suivantes :\na)     Renouveler le mandat de la présente Commission pour une année\nsupplémentaire ;\nb)     Continuer à suivre l’évolution de la situation des droits de l’homme au Burundi\ndans le contexte des élections de 2020 et, conformément aux principes de prévention et\nd’alerte précoce, faire régulièrement l’évaluation des risques, afin de permettre, en cas de\ndétérioration, que soient développées et mises en œuvre des stratégies de réponse adaptées ;\nc)     Mettre tout en œuvre pour assurer la tenue d’un dialogue inter burundais\ninclusif afin de régler la crise politique ;\nd)     Soutenir le renforcement des capacités des observateurs électoraux\ninternationaux, régionaux et nationaux ;\ne)     Envoyer des observateurs régionaux ou internationaux uniquement si leur\nliberté d’action est garantie dans la pratique ;\nf)     S’assurer que l’aide humanitaire parvient intégralement à la population ;\ng)     Répondre à l’appel de financement du Haut-Commissariat des Nations Unies\npour les réfugiés en faveur des réfugiés burundais ;\nh)      S’assurer que le suivi des rapatriés se fait dans la durée, de manière plus\nfréquente et transparente.\n107. Plus particulièrement, la Commission recommande au système des Nations Unies,\nconformément à l’initiative Les droits de l’homme avant tout, d’intensifier la promotion des\ndroits de l’homme relevant des mandats propres aux agences et programmes concernés, de\nmême que la collecte et la publication de données objectives et fiables sur la situation au\nBurundi.","unnumbered":true,"annex":1},{"id":"a-hrc-45-32-u0116-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":null,"seq":116,"section":"1. Recommandations faites en 2019","text":"108. Aux États membres du Conseil de sécurité, la Commission recommande de maintenir\nle Burundi dans le programme de travail du Conseil, au regard des facteurs de risque\nidentifiés, et d’inviter la Commission à lui rendre compte de ses conclusions.","unnumbered":true,"annex":1},{"id":"a-hrc-45-32-u0117-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":null,"seq":117,"section":"1. Recommandations faites en 2019","text":"Version anglaise\n109. The 2020 elections pose a major risk. To ensure that they are peaceful, fair, free,\ntransparent and credible, the Commission makes the following recommendations to the\nBurundian authorities:\n(a)     Give effect to all the Commission’s previous recommendations, which are\nmore well-founded and relevant than ever, including those concerning priority measures to\nend human rights violations and international crimes, combat impunity and improve the\nhuman rights situation in the country and the medium- and longer-term recommendations on\nreforms to the legal framework and the judicial system 34;\n(b)    Conduct prompt, independent and effective investigations into the cases of\nviolations documented by the Commission since 2015 with a view to creating a climate of\ntrust and political tolerance conducive to inclusive participation in the electoral process;\n(c)  Re-engage constructively and cooperatively with all international and regional\nhuman rights mechanisms and the Office of the United Nations High Commissioner for\nHuman Rights, enabling them to carry out their human rights monitoring mandates fully and\nfreely;\n(d)     Ensure that national human rights mechanisms are institutionally and\nfinancially independent and build the capacity of their members;\n(e)    Take the measures necessary to ensure that foreign and domestic NGOs can be\nfreely established and organized and that they can operate freely, including by amending the\nlaws regulating them;\n(f)    Take the measures necessary to ensure freedom of information in the country\nand the right of local and international media to operate in accordance with international\nstandards, including by amending the laws on the press and the National Communication\nCouncil;\n(g)     Guarantee the effective enjoyment of civil liberties, including the freedoms of\nopinion, expression, access to information, association, assembly and religion, not least by\nending all forced recruitment to the ruling party and its youth league;\n(h)    Follow the Guidelines on Access to Information and Elections in Africa and\nthe Guidelines on Freedom of Association and Assembly of the African Commission on\nHuman and Peoples’ Rights;\n(i)    Ensure that all political parties can engage in legitimate activities in complete\nfreedom and security, in an environment of political tolerance, including by punishing any\nincitement to hatred and calls for violence against other political parties and their members;\n(j)     Ensure, in practice, the right to participate in the conduct of public affairs\nwithout discrimination, in particular by amending the Electoral Code;\n(k)    Ensure, in practice, the institutional independence of the Independent National\nElectoral Commission, including by amending the decree governing it to make certain that\nits composition is inclusive and balanced, and strengthen the capacity of its members at the\nmunicipal and provincial levels;\n(l)    Provide access to independent international and regional election observers\nand ensure that they and national observers from civil society or political parties enjoy\nfreedom of movement and action before, during and after the elections;\n(m) Follow the Guidelines for African Union Electoral Observation and\nMonitoring Missions;","unnumbered":true,"annex":1},{"id":"a-hrc-45-32-u0118-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":null,"seq":118,"section":"1. Recommandations faites en 2019","text":"(n)    Allow political opponents to return from exile to participate in the 2020\nelections and guarantee their freedom and security, including by revoking warrants for the\narrest of those who have not used or advocated violence;\n(o)    Immediately release all political prisoners arrested and detained in connection\nwith the exercise of their democratic rights;\n(p)   Make the training provided to law enforcement agencies more robust to avoid\nill-treatment and ensure the peaceful control of crowds;\n(q)   Follow the Guidelines for the Policing of Assemblies by Law Enforcement\nOfficials in Africa and the related training manual, both developed by the African\nCommission on Human and Peoples’ Rights;\n(r)     End the impunity of the Imbonerakure by exercising control over them so as\nto ensure that the functions of the security forces or the judiciary are not usurped and put an\nend to their repressive activities and shows of force in the hills;\n(s)    End all illegal contributions.\n110. The Commission recommends that, whether they participate in the elections or not,\nall political parties in Burundi refrain from violence and incitement to hatred or violence,\nparticularly against the backdrop of the 2020 elections.\n111. The Commission recommends that opposition rebel groups refrain from violence and\nincitement to hatred or violence.\n112. For the international community, including the African Union and the United Nations\nsystem, the Commission has the following recommendations:\n(a)    Renew the mandate of the Commission for an additional year;\n(b)    Continue to monitor developments in the human rights situation in Burundi in\nthe context of the 2020 elections and, in accordance with the principles of prevention and\nearly warning, carry out regular risk assessments to enable the development and use of\nappropriate response strategies in the event of deterioration;\n(c)    Make every effort to ensure that an inclusive inter-Burundi dialogue is held to\nresolve the political crisis;\n(d)     Support capacity-building for international, regional and national election\nobservers;\n(e)     Send regional or international observers only if their freedom of action is\nguaranteed in practice;\n(f)    Ensure that all humanitarian aid reaches the population;\n(g)     Respond to the appeal made by the Office of the United Nations High\nCommissioner for Refugees for funds for Burundi refugees;\n(h)   Ensure that returnees are monitored in a sustained and more regular and\ntransparent manner.\n113. In particular, the Commission recommends that the United Nations system, in\naccordance with the initiative Human Rights Up Front, take stronger measures to promote\nhuman rights, under the mandates of the relevant agencies and programmes, and to collect\nand publish objective and reliable data on the situation in Burundi.\n114. In view of the risk factors that have been identified, the Commission recommends that\nthe States members of the Security Council keep Burundi on the Council’s programme of\nwork and that the Council invite the Commission to report to it on its conclusions.","unnumbered":true,"annex":1},{"id":"a-hrc-45-32-u0119-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":null,"seq":119,"section":"2. Recommandations faites en 2018","text":"Version française\n115. La Commission recommande au Gouvernement burundais, comme mesures\nprioritaires :\na)   De mettre immédiatement un terme aux violations graves des droits de\nl’homme commises par des agents de l’État et des Imbonerakure ;\nb)      D’établir, avec le soutien de la communauté internationale, des mécanismes ad\nhoc chargés d’enquêter sur les violations des droits de l’homme et de poursuivre les auteurs\nde crimes de droit international qui ne font pas l’objet d’une enquête par la Cour pénale\ninternationale ;\nc)      D’établir, avec le soutien de la communauté internationale, une entité\nindépendante chargée de faire la lumière sur les cas de disparition signalés depuis avril 2015,\nde localiser les possibles fosses communes, d’exhumer et d’identifier les corps ;\nd)     De prendre des mesures pour que les victimes de torture et les femmes ayant\nsubi des violences sexuelles aient accès à des soins appropriés, en particulier un libre accès à\ntous les soins de santé sexuelle et reproductive, ainsi qu’à un soutien psychologique ;\ne)    D’appliquer les Lignes directrices sur la lutte contre les violences sexuelles et\nleurs conséquences en Afrique de la Commission africaine des droits de l’homme et des\npeuples ;\nf)     De contrôler les hausses des prix, en particulier en revoyant l’augmentation\ndes taxes et des impôts qui porte atteinte au droit à un niveau de vie suffisant de la population,\net en supprimant les contributions qui touchent disproportionnellement les personnes les plus\npauvres ;\ng)     De coopérer avec les mécanismes internationaux des droits de l’homme,\nnotamment :\ni)       En accueillant à nouveau des missions de procédures spéciales ;\nii)    En mettant en œuvre les recommandations de l’examen périodique universel,\ndes organes conventionnels et des procédures spéciales, notamment en établissant un\nmécanisme national d’élaboration des rapports et de suivi ;\nh)     D’autoriser le Haut-Commissariat des Nations Unies aux droits de l’homme à\nreprendre sans entrave l’ensemble de ses activités au Burundi ;\ni)      De signer et de mettre en œuvre le mémorandum d’entente avec l’Union\nafricaine et de permettre le déploiement complet des 100 observateurs des droits de l’homme.\n116. La Commission recommande également au Gouvernement burundais, à moyen et plus\nlong termes :\na)      De réviser la loi organique du 8 mars 2018 portant révision de la loi no 01/03\ndu 24 janvier 2013 portant missions, composition, organisation et fonctionnement du Conseil\nnational de la communication afin de garantir l’indépendance de ce dernier ;\nb)     De ratifier la Convention internationale pour la protection de toutes les\npersonnes contre les disparitions forcées ;\nc)    De réviser les dispositions du Code de procédure pénale pour les mettre en\nconformité avec les normes internationales, en particulier les dispositions relatives aux délais\nde garde à vue et de contrôle de la détention, aux perquisitions de nuit et sans mandat, à la\nprocédure de « flagrance », à l’infraction d’« atteinte à la sûreté intérieure de l’État », et à\ncelles accordant une impunité de jure aux magistrats et aux officiers de police judiciaire ;\nd)       De mettre fin aux détentions arbitraires et d’améliorer les conditions de\ndétention :\n• En appliquant les Lignes directrices sur les conditions d’arrestation, de garde\nà vue et de détention provisoire en Afrique de la Commission africaine des\ndroits de l’homme et des peuples ;","unnumbered":true,"annex":1},{"id":"a-hrc-45-32-u0120-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":null,"seq":120,"section":"2. Recommandations faites en 2018","text":"• En garantissant le contrôle de la légalité des détentions et leur conformité avec\nles droits de l’homme ;\ne)    Faute d’un système judiciaire indépendant et performant, de coopérer\npleinement avec la Cour pénale internationale dans l’enquête qu’elle a ouverte le 25 octobre\n2017 ;\nf)    D’engager une réforme en profondeur du système judiciaire afin de garantir\nson indépendance, son impartialité et son effectivité, notamment :\ni)     En appliquant les Directives et les Principes sur le droit à un procès équitable\net à l’assistance judiciaire en Afrique de la Commission africaine des droits de\nl’homme et des peuples ;\nii)    En publiant les conclusions des états généraux de la justice de 2013 et en\nréunissant les acteurs du secteur et les partenaires internationaux pour discuter des\nmesures de suivi ;\niii)  En augmentant le budget du secteur de la justice et en garantissant son\nautonomie de gestion ;\niv)    En revalorisant la rémunération des magistrats des juridictions ordinaires ainsi\nque les moyens et l’équipement à leur disposition ;\nv)     En informatisant les greffes ;\nvi)   En revoyant la composition du Conseil supérieur de la magistrature afin que\nses membres soient en majorité désignés par leurs pairs ;\nvii) En revoyant les procédures de nomination, d’affectation, de notation et\nd’avancement des magistrats afin qu’elles ne dépendent pas du pouvoir exécutif ;\nviii) En veillant au respect strict du principe d’inamovibilité des magistrats du\nsiège ;\nix)     En protégeant et en garantissant l’indépendance du système judiciaire en\ninterdisant toute ingérence dans le fonctionnement de la justice par des autorités\ngouvernementales, des membres du parti au pouvoir ou par des membres des corps de\ndéfense et de sécurité, et en prenant des sanctions contre ceux qui influencent, ou\ncherchent à influencer, le fonctionnement de la justice ;\nx)     En développant des programmes d’aide juridictionnelle pour les plus\nvulnérables ;\nxi)    En renforçant les mécanismes de protection de victimes et de témoins, ainsi\nque leur efficacité, pour restaurer la confiance de la population et pour encourager les\ntémoins à s’exprimer sans crainte pour leur sécurité ;\ng)     De mettre en place, en consultation avec les bénéficiaires, un programme de\nréparations des victimes des violations des droits de l’homme qui comprenne des réparations\nmatérielles, symboliques, individuelles et collectives, et qui ne soit pas dépendant de la\ncondamnation des auteurs ;\nh)      D’établir le fond étatique pour les victimes de torture prévu par la loi et en\nconformité avec l’Observation générale no 4 de la Commission africaine des droits de\nl’homme et des peuples sur la Charte africaine des droits de l’homme et des peuples,\nconcernant le droit à réparation des victimes de torture et autres peines ou traitements cruels,\ninhumains ou dégradants (art. 5) ;\ni)     D’établir un fond pour l’indemnisation des victimes de détention arbitraire et\nillégale ;\nj)     De réformer le secteur de la sécurité :\ni)    En s’assurant que des éléments extérieurs n’accomplissent pas des activités de\ndéfense ou de sécurité ;\nii)    En délimitant clairement les rôles des différents corps de défense et de sécurité,\nen particulier du SNR ;","unnumbered":true,"annex":1},{"id":"a-hrc-45-32-u0121-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":null,"seq":121,"section":"2. Recommandations faites en 2018","text":"iii)   En suspendant les membres des corps de défense et de sécurité suspectés d’être\nimpliqués dans des violations des droits de l’homme jusqu’au terme des enquêtes et\ndes procédures judiciaires ;\niv)   En établissant des procédures strictes et transparentes de sélection qui intègrent\ndes mécanismes de vérification des antécédents ;\nv)     En renforçant le contrôle civil et démocratique des corps de défense et de\nsécurité, en particulier du SNR ;\nk)      De s’acquitter de ses obligations internationales de respecter, de protéger et de\ngarantir les droits économiques et sociaux :\ni)     En élaborant et en mettant en œuvre les budgets de l’État de manière à utiliser\nau maximum les ressources disponibles pour assurer le respect des droits de l’homme\nà la population appauvrie par la crise politique, en particulier des droits à\nl’alimentation, à l’eau et à la santé, et pour développer des indicateurs désagrégés,\ny compris par genre, pour mieux informer ses politiques ;\nii)    En entreprenant, en consultation avec les populations travaillant dans le secteur\nagricole, notamment les femmes, des réformes visant une meilleure protection des\ndroits des femmes et une meilleure utilisation des terres pour l’agriculture, et en\ndéveloppant des perspectives de travail en dehors du secteur agricole ;\niii)    En utilisant une approche fondée sur les droits de l’homme pour régler les\nconflits fonciers dont ceux touchant les personnes ayant fui le Burundi avant et après\n2015 ;\niv)    En mettant fin à toute considération politique dans les processus de\nrecrutement au sein de l’administration publique, des sociétés publiques et des\nsociétés mixtes.\n117. La Commission recommande aux partis politiques et aux groupes armés d’opposition\nde s’abstenir de toute attaque sur le territoire burundais et de tout discours appelant à la\nviolence, et de s’engager dans la recherche d’une solution durable à la crise politique.\n118. La Commission recommande à l’Union africaine de donner une place importante,\ndans sa recherche d’une solution durable à la crise au Burundi, au respect des droits de\nl’homme et au rejet de l’impunité, tels que prévus par son Acte constitutif.\n119.   La Commission recommande aux partenaires techniques et financiers du Burundi :\na)    De suspendre ou de maintenir la suspension de toute aide budgétaire directe au\nGouvernement en l’absence de priorisation des ressources internes en faveur des objectifs de\ndéveloppement durable et des droits économiques et sociaux de la population, et de mesures\neffectives contre la corruption ;\nb)     De cibler les dons et les financements attribués au Gouvernement sur des\nprojets en faveur des besoins de la population et de s’assurer que ceux-ci sont gérés\nefficacement et de manière transparente ;\nc)      D’évaluer régulièrement l’impact des sanctions financières sur la population\nburundaise.\n120. La Commission recommande aux garants de l’Accord d’Arusha, en leur qualité\nd’acteurs engagés en faveur d’une paix durable au Burundi, de continuer à chercher une\nsolution pérenne à la crise politique et des droits de l’homme qui préserve et garantit les\nacquis de l’Accord d’Arusha.","unnumbered":true,"annex":1},{"id":"a-hrc-45-32-u0122-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":null,"seq":122,"section":"2. Recommandations faites en 2018","text":"Version anglaise\n121. The Commission recommends that the Government of Burundi take the following\nmeasures as a matter of priority:\n(a)     Put an immediate end to the gross human rights violations being committed by\nagents of the State and Imbonerakure;","unnumbered":true,"annex":1},{"id":"a-hrc-45-32-u0123-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":null,"seq":123,"section":"2. Recommandations faites en 2018","text":"(b)     With the support of the international community, establish ad hoc mechanisms\nwith a mandate to investigate human rights violations and to prosecute perpetrators of\ninternational crimes that are not being investigated by the International Criminal Court;\n(c)     With the support of the international community, establish an independent\nbody with a mandate to investigate the cases of disappearance reported since April 2015,\nlocate potential mass graves, and exhume and identify the remains;\n(d)    Take measures to ensure that victims of torture and women survivors of sexual\nviolence have access to appropriate care, including free access to all sexual and reproductive\nhealth services and to psychological support;\n(e)   Implement the Guidelines on Combating Sexual Violence and its\nConsequences in Africa adopted by the African Commission on Human and Peoples’ Rights;\n(f)     Control price increases, in particular by reviewing duty and tax increases that\nare undermining the population’s right to an adequate standard of living and by abolishing\ncontributions that disproportionately affect the poorest sectors;\n(g)     Cooperate with international human rights mechanisms, in particular by:\n• (i) Resuming the practice of allowing special procedures mandate holders to\nconduct missions to Burundi;\n• (ii) Implementing the recommendations of the universal periodic review, treaty\nbodies and special procedures, including by establishing a national mechanism\nfor reporting and follow-up.\n(h)    Authorize the Office of the United Nations High Commissioner for Human\nRights to resume all its activities in Burundi without hindrance;\n(i)    Sign and implement the memorandum of understanding with the African\nUnion and permit the full deployment of the 100 human rights observers provided for therein.\n122. For the medium and longer terms, the Commission also recommends that the\nGovernment of Burundi:\n(a)    Amend the Organization Act of 8 March 2018 amending Act No. 01/03 of 24\nJanuary 2013 on the mandate, composition, organization and functioning of the National\nCommunication Council with a view to ensuring the latter’s independence;\n(b)    Ratify the International Convention for the Protection of All Persons from\nEnforced Disappearance;\n(c)     Amend the Code of Criminal Procedure to align its provisions with\ninternational standards, in particular the provisions on time limits for police custody and on\noversight of detention, night-time and warrantless searches, the flagrante delicto procedure\nand the offence of “undermining the internal security of the State”, and provisions that grant\nde jure impunity to judges and to officers of the criminal investigation police (police\njudiciaire);\n(d)     Put an end to arbitrary detention and improve conditions of detention by:\n• (i) Implementing the Guidelines on the Conditions of Arrest, Police Custody\nand Pre-Trial Detention in Africa adopted by the African Commission on\nHuman and Peoples’ Rights;\n• (ii) Ensuring that detention is subject to oversight measures for assessing its\nlegality and compatibility with human rights.\n(e)     In the absence of an independent and efficient judicial system, cooperate fully\nwith the International Criminal Court in the investigation opened on 25 October 2017;\n(f)     Undertake an in-depth reform of the judicial system to ensure its independence,\nimpartiality and effectiveness, including by:\n• (i) Implementing the Principles and Guidelines on the Right to a Fair Trial and\nLegal Assistance in Africa adopted by the African Commission on Human and\nPeoples’ Rights;","unnumbered":true,"annex":1},{"id":"a-hrc-45-32-u0124-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":null,"seq":124,"section":"2. Recommandations faites en 2018","text":"• (ii) Publishing the conclusions of the national forum on the justice system held\nin 2013 and convening a meeting of justice-sector stakeholders and\ninternational partners to discuss follow-up action;\n• (iii) Increasing the budget for the justice sector and ensuring that it is managed\nautonomously;\n• (iv) Raising the pay levels of judges in the ordinary courts and increasing the\nresources and facilities available to them;\n• (v) Computerizing court registries;\n• (vi) Reviewing the composition of the Judicial Service Commission to ensure\nthat the majority of its members are appointed by their peers;\n• (vii) Reviewing procedures for the appointment, assignment, evaluation and\npromotion of judges to ensure that such procedures are not dependent on the\nexecutive branch;\n• (viii) Ensuring strict observance of the principle that judges should have\nsecurity of tenure;\n• (ix) Protecting and safeguarding the independence of the judiciary by\nprohibiting any interference in the administration of justice by government\nauthorities, members of the ruling party or members of the defence and security\nforces, and imposing penalties on anyone who influences or seeks to influence\nthe administration of justice;\n• (x) Developing legal aid programmes for persons belonging to the most\nvulnerable groups;\n• (xi) Strengthening victim and witness protection mechanisms and\nimproving their effectiveness in order to restore public trust and encourage\nwitnesses to come forward without fear for their safety.\n(g)    In consultation with the beneficiaries, establish a reparations programme for\nvictims of human rights violations, ensuring that material, symbolic, individual and collective\nreparations are made available regardless of whether or not the perpetrators are convicted;\n(h)    Establish the State fund for victims of torture provided for by law, in\nconformity with general comment No. 4 on the African Charter on Human and Peoples’\nRights, adopted by the African Commission on Human and Peoples’ Rights, concerning the\nright to redress for victims of torture and other cruel, inhuman or degrading punishment or\ntreatment (art. 5);\n(i)     Establish a compensation fund for victims of arbitrary and unlawful detention;\n(j)     Reform the security sector by:\n• (i) Ensuring that outsiders are not involved in defence or security activities;\n• (ii) Clearly defining the roles of the various defence and security forces, in\nparticular the National Intelligence Service;\n• (iii) Suspending members of the defence and security forces who are suspected\nof involvement in human rights violations until the relevant investigations and\njudicial proceedings have concluded;\n• (iv) Establishing rigorous and transparent selection procedures that include\nvetting mechanisms;\n• (v) Strengthening democratic civilian control over the defence and security\nforces, in particular the National Intelligence Service.\n(k)    Meet its international obligations to respect, protect and fulfil economic and\nsocial rights by:\n• (i) Developing and implementing State budgets in such a way as to maximize\nthe use of available resources to ensure that the human rights of the sectors","unnumbered":true,"annex":1},{"id":"a-hrc-45-32-u0125-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":null,"seq":125,"section":"2. Recommandations faites en 2018","text":"impoverished by the political crisis are respected, in particular the rights to\nfood, water and health care, and to develop indicators disaggregated by factors\nsuch as gender in order to better inform its policies;\n• (ii) In consultation with population groups working in the agricultural sector,\nincluding women, undertaking reforms with the aim of better protecting\nwomen’s rights and making better use of land for agriculture, and developing\nemployment opportunities outside the agricultural sector;\n• (iii) Taking a rights-based approach to the settlement of land conflicts,\nincluding those involving persons who fled Burundi either before or after 2015;\n• (iv) Ending the inclusion of any political considerations in hiring processes for\nthe civil service, State enterprises and public-private enterprises.\n123. The Commission recommends that political parties and armed opposition groups\nrefrain from engaging in any attacks on Burundian territory and from any speech calling for\nviolence, and that they join the effort to find a lasting solution to the political crisis.\n124. The Commission recommends that the African Union, in its efforts to find a lasting\nsolution to the crisis in Burundi, give priority to respect for human rights and the rejection of\nimpunity, as provided for in its Constitutive Act.\n125.     The Commission recommends that the technical and financial partners of Burundi:\n(a)    Suspend, or maintain the suspension of, any direct budget support to the\nGovernment until such time as priority is given to the allocation of domestic resources for\nthe fulfilment of the Sustainable Development Goals and the economic and social rights of\nthe population, and effective measures are taken against corruption;\n(b)   Ensure that grants and financing provided to the Government are earmarked\nfor projects to meet the population’s needs, and ensure that such funding is managed\neffectively and transparently;\n(c)     Regularly evaluate the impact of financial sanctions on the people of Burundi.\n126. The Commission recommends that the guarantors of the Arusha Agreement, in their\ncapacity as committed proponents of a lasting peace in Burundi, continue to seek a durable\nsolution to the political and human rights crisis that will preserve and safeguard the\nachievements of the Arusha Agreement.","unnumbered":true,"annex":1},{"id":"a-hrc-45-32-u0126-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":null,"seq":126,"section":"1. Aux autorités burundaises","text":"127. De mettre immédiatement un terme aux violations graves des droits de l’homme\ncommises par des agents de l’État et des Imbonerakure sur lesquels l’État exerce un contrôle ;\n128. D’enquêter sur ces violations et s’assurer que les auteurs présumés soient jugés dans\nles meilleurs délais, dans des procédures crédibles, indépendantes et équitables, et que les\nvictimes obtiennent une juste réparation. Dans le cas où les auteurs présumés sont des agents\nde l’État, les suspendre jusqu’au terme de l’enquête et de la procédure judiciaire;\n129. De prendre des mesures concrètes pour une amélioration rapide de la situation des\ndroits de l’homme, notamment en :\n• Annulant les mandats d’arrêt contre des dirigeants de médias, d’organisations de la\nsociété civile et de partis politiques qui n’ont pas utilisé ou prôné la violence, et\npermettant leur retour en toute sécurité au Burundi ;\n• Levant la suspension et la radiation des médias et organisations de la société civile,\nleur permettant de reprendre leurs activités en toute indépendance, et revoyant les lois\nadoptées en 2017 sur les organisations non-gouvernementales burundaises et\ninternationales ;","unnumbered":true,"annex":1},{"id":"a-hrc-45-32-u0127-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":null,"seq":127,"section":"1. Aux autorités burundaises","text":"• Libérant immédiatement tous les prisonniers politiques ;\n• S’assurant que toute personne arrêtée soit détenue dans un lieu de détention officiel et\nque des observateurs nationaux et internationaux soient autorisés à leur rendre visite ;\n• Veillant à ce que les officiers de police judiciaire ne soient pas habilités à mener des\nperquisitions sans mandat et de nuit comme envisagé dans les projets d’amendement\ndu Code pénal et du Code de procédure pénale ;\n• S’assurant que des individus qui n’y sont pas légalement habilités, en particulier des\nImbonerakure, ne conduisent pas des activités de maintien de l’ordre ou n’y prennent\npas part, y compris dans des lieux de détention, et qu’ils ne portent pas des uniformes\nmilitaires ou de police ou ne soient pas en possession d’armes ;\n• Poursuivant les auteurs de discours haineux ou appelant à la violence ;\n• Mettant fin aux menaces, intimidations et actes d’extorsion par des agents de l’État et\ndes Imbonerakure ;\n• Permettant aux victimes de violences sexuelles et de torture d’avoir accès à des\nservices médicaux et psychosociaux ;\n130.     D’engager une réforme en profondeur du système judiciaire, notamment en :\n• Publiant les conclusions des états généraux de la justice qui se sont tenus en 2013 à\nGitega ;\n• Revoyant la composition du Conseil national de la magistrature afin que ses membres\nsoient en majorité désignés par leurs pairs ;\n• Revoyant les procédures de nomination, d’affectation, de notation et d’avancement\ndes magistrats afin qu’elles ne dépendent pas du pouvoir exécutif ;\n• Veillant au respect strict du principe d’inamovibilité des magistrats du siège ;\n• Protégeant et garantissant l’indépendance du système judiciaire en interdisant toute\ningérence dans le fonctionnement de la justice par des autorités gouvernementales,\ndes membres du parti au pouvoir ou des membres des corps de défense et de sécurité,\net en prenant des sanctions contre ceux qui influencent, ou cherchent à influencer, le\nfonctionnement de la justice ;\n• Développant des programmes d’aide juridictionnelle pour les plus vulnérables ;\n• Renforçant les mécanismes de protection de victimes et de témoins, ainsi que leur\nefficacité, pour restaurer la confiance de la population et encourager les témoins à\ns’exprimer sans crainte pour leur sécurité ;\n131. De s’assurer que les membres des corps de défense et de sécurité respectent les droits\nde l’homme en toutes circonstances et servent les intérêts de la population dans son ensemble\net pas uniquement ceux du parti au pouvoir, notamment en :\n• Renforçant le contrôle civil des corps de défense et de sécurité et l’indépendance des\norganes chargés de ce contrôle créés par la Constitution, en particulier le Parlement,\nla Commission nationale indépendante des droits de l’homme et l’Ombudsman ;\n• Remédiant à la carence constitutionnelle de contrôle civil du SNR ;\n• Prenant des mesures pour vérifier les antécédents, notamment en matière de droits de\nl’homme, des agents des corps de défense et de sécurité et intégrant ces mesures à une\nrefonte des procédures de recrutement et d’avancement de ces agents ;\n132. De revenir sur sa décision de se retirer du Statut de Rome et coopérer pleinement avec\nla CPI dans la procédure d’examen préliminaire en cours et, si une enquête est ouverte,\npoursuivre cette coopération et assurer la protection des victimes et témoins ;\n133. D’autoriser le HCDH à reprendre ses activités de documentation des violations des\ndroits de l’homme au Burundi, suspendues depuis octobre 2016 ;","unnumbered":true,"annex":1},{"id":"a-hrc-45-32-u0128-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":null,"seq":128,"section":"1. Aux autorités burundaises","text":"134. De signer et mettre en œuvre le mémorandum d’entente avec l’Union africaine et\npermettre le déploiement complet des 100 observateurs des droits de l’homme et des\n100 experts militaires, décidé en 2016 ;\n135. De coopérer avec les mécanismes des droits de l’homme des Nations Unies en\naccueillant à nouveau des missions des procédures spéciales et en mettant en œuvre les\nrecommandations récentes des organes de traité ;\n136. De s’engager activement dans la voie d’une résolution durable de la crise politique,\nnotamment dans le cadre d’initiatives de dialogue engagées au niveau international.","unnumbered":true,"annex":1},{"id":"a-hrc-45-32-u0129-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":null,"seq":129,"section":"2. Aux partis politiques et groupes armés d’opposition","text":"137. De mettre immédiatement un terme aux atteintes aux droits de l’homme et aux actes\nde violence commis par leurs membres ;\n138. De s’abstenir de tout discours appelant à la violence et s’engager dans la recherche\nd’une solution durable à la crise politique au Burundi.","unnumbered":true,"annex":1},{"id":"a-hrc-45-32-u0130-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":null,"seq":130,"section":"3. Au Conseil des droits de l’homme","text":"139. De prolonger le mandat de la Commission pour une durée d’un an aux fins\nd’approfondir et de poursuivre ses enquêtes en raison de la persistance des violations graves\ndes droits de l’homme et des atteintes à ceux-ci et en l’absence d’autres mécanismes\nspécifiques en mesure de mener des enquêtes indépendantes et approfondies sur la situation\ndes droits de l’homme au Burundi ;\n140. De demander au Haut-Commissaire des Nations Unies aux droits de l’homme de faire\nun rapport sur l’évolution de sa coopération avec le Gouvernement du Burundi aux\nprochaines sessions du Conseil.","unnumbered":true,"annex":1},{"id":"a-hrc-45-32-u0131-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":null,"seq":131,"section":"5. Au Conseil de sécurité des Nations Unies","text":"142. De prendre dûment compte des présentes conclusions de la Commission et de la\npersistance de violations graves des droits de l’homme dans toute discussion sur le Burundi\net, dans ce contexte, de veiller à la mise en œuvre effective de la résolution 2303 (2016) ;\n143. De saisir la CPI de tout crime de droit international qui serait commis au Burundi\naprès le 27 octobre 2017 ;\n144. De prendre des sanctions individuelles contre les principaux auteurs présumés de\nviolations graves des droits de l’homme et de crimes de droit international au Burundi.","unnumbered":true,"annex":1},{"id":"a-hrc-45-32-p0006-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"6","seq":132,"section":"5. Au Conseil de sécurité des Nations Unies","text":"Au Secrétaire général des Nations Unies\n145. De veiller à ce que le respect des droits de l’homme et la restauration de l’État de droit\nsoient parmi les priorités de son Envoyé spécial sur le Burundi ;\n146. De veiller à ce qu’aucun auteur présumé de violations des droits de l’homme ou de\ncrimes de droit international au Burundi ne soit recruté dans des missions de maintien de la\npaix des Nations Unies.","annex":1},{"id":"a-hrc-45-32-p0007-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"7","seq":133,"section":"5. Au Conseil de sécurité des Nations Unies","text":"Aux États Membres des Nations Unies\n147. D’accorder prima farcie le statut de réfugié aux demandeurs d’asile burundais et de\nveiller au respect strict du principe de non-refoulement, ainsi qu’à la protection des réfugiés ;\n148. De poursuivre, au titre de la compétence universelle, les auteurs présumés de crimes\nde droit international commis au Burundi se trouvant sur leur territoire ;\n149. De maintenir, en l’absence de toute amélioration de la situation des droits de l’homme\ndans le pays, les sanctions individuelles et la suspension de l’aide directe au Gouvernement\nburundais ;\n150. De fournir une assistance technique aux autorités burundaises, dans la mesure où ces\ndernières font preuve d’une véritable volonté politique, afin de mener des enquêtes crédibles\net indépendantes, notamment en matière d’autopsie, d’exhumation et d’identification des\ncorps ;\n151. De soutenir la mise en place de services médicaux et psychosociaux spécialisés,\nnotamment pour les victimes de torture et de violences sexuelles ;\n152. De soutenir les autorités burundaises, si celles-ci font preuve d’une véritable volonté\npolitique, dans tout effort de réforme du système judiciaire et du secteur de sécurité qu’elles\nvoudront engager aux fins d’améliorer la situation des droits de l’homme.","annex":1},{"id":"a-hrc-45-32-p0008-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"8","seq":134,"section":"5. Au Conseil de sécurité des Nations Unies","text":"À l’Union africaine\n153. De reprendre l’initiative dans la recherche d’une solution durable à la crise au Burundi\nfondée sur le respect des droits de l’homme et le rejet de l’impunité, tels que prévus par son\nActe constitutif, et s’y engager activement ;\n154. De veiller à ce qu’aucun agent de l’État burundais accusé de violations des droits de\nl’homme ou de crimes de droit international ne soit recruté dans des missions de maintien de\nla paix de l’Union africaine ;\n155. De s’assurer que l’équipe complète de ses observateurs des droits de l’homme et\nexperts militaires soit rapidement déployée au Burundi ;\n156. D’envisager, en cas de persistance de la situation actuelle au Burundi, l’application de\nl’article 4 h) de son Acte constitutif, autorisant l’Union africaine à intervenir dans un État\nmembre dans certaines circonstances, notamment en cas de crimes contre l’humanité.","annex":1},{"id":"a-hrc-45-32-p0009-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"9","seq":135,"section":"5. Au Conseil de sécurité des Nations Unies","text":"À la Communauté des États d’Afrique de l’Est\n157. De s’assurer que l’amélioration rapide de la situation des droits de l’homme soit une\npriorité dans ses efforts de médiation.","annex":1},{"id":"a-hrc-45-32-p0010-a1","rec_id":"recQg9nZR0kHfMTSY","symbol":"A/HRC/45/32","n":"10","seq":136,"section":"5. Au Conseil de sécurité des Nations Unies","text":"Aux garants de l’Accords d’Arusha de 2000, en leur qualité d’acteurs engagés\nen faveur d’une paix durable au Burundi\n158. De se réunir le plus rapidement possible en vue de trouver une solution pérenne à la\ncrise politique et des droits de l’homme au Burundi.\nVersion anglaise\n1.     The Burundian authorities should:\n159. Put an immediate end to the gross human rights violations being committed by agents\nof the State and Imbonerakure over which the State exercises control;\n160. Investigate these violations, ensure that the alleged perpetrators are prosecuted\npromptly in accordance with credible, independent and fair procedures, and that the victims\nobtain just reparation, and, where the alleged perpetrators are agents of the State, suspend\nthem from their duties pending the completion of the investigation and the judicial\nproceedings;\n161. Take practical measures to bring about a rapid improvement of the human rights\nsituation, in particular by:\n• Withdrawing the warrants for the arrest of heads of media outlets, civil society\norganizations and political parties who have neither used nor advocated violence, and\npermitting their safe return to Burundi;\n• Lifting the suspension and reversing the revocation of the licences of media and civil\nsociety organizations, permitting them to resume their activities with complete\nindependence and reviewing the laws adopted in 2017 concerning non-profit\norganizations and foreign non-governmental organizations;\n• Immediately releasing all political prisoners;\n• Ensuring that every person arrested is detained in an official place of detention and\nthat national and international observers are allowed to visit them;\n• Ensure that criminal investigation officers (officiers de police judiciaire) are not\nauthorized to conduct searches without a warrant, including at night, as envisaged in\nthe draft amendments to the Criminal Code and the Code of Criminal Procedure;\n• Ensuring that individuals lacking legal authorization, particularly the Imbonerakure,\ndo not perform or participate in law enforcement activities, including in places of\ndetention, and do not wear military or police uniforms or possess weapons;\n• Prosecuting individuals who incite hatred or violence;\n• Putting an end to threats, intimidation and acts of extortion by State officials and the\nImbonerakure;\n• Giving victims of sexual violence and torture access to medical and psychosocial\nservices.\n162.     Undertake a thorough reform of the judiciary, in particular by:\n• Publishing the conclusions of the General Convention on the Judiciary (États\ngénéraux de la justice) held in Gitega in 2013;\n• Reviewing the composition of the Superior Council of Magistrates (Conseil supérieur\nde la magistrature) so that the majority of its members are designated by their peers;\n• Reviewing the nomination, posting, evaluation and promotion procedures of\nmagistrates so that they do not depend of the executive;\n• Ensuring the respect of the principle of security of tenure for judges;\n• Protecting and guaranteeing the independence of the judiciary by prohibiting all\ninterference in their functions by governmental authorities, members of the ruling\nparty or security and defence forces, and imposing sanctions on those who influence,\nor seek to influence, the functioning of the judiciary;\n• Developing legal aid programmes for the most vulnerable;\n• Reinforcing the protection mechanisms for victims and witnesses, as well as their\nefficiency, in order to restore people’s confidence in the system and to encourage\nwitnesses to testify without fear for their security.\n163. Ensure that members of the defence and security forces respect human rights in all\ncircumstances and serve the interests of the population as a whole, not solely those of the\nruling party, in particular by:\n• Reinforcing civilian control over the military and the independence of the competent\norgans created by the Constitution to supervise this control, in particular the\nParliament, the National Human Rights Commission and the Ombudsman;\n• Implementing civilian control over the National Intelligence Service (Service national\nde renseignement) in line with the Constitution;\n• Conducting background checks, in particular on human rights, on defense and security\nforces and incorporating these measures into reforms of the recruitment and career\nprogression of these agents.\n164. Reconsider their decision to withdraw from the Rome Statute, cooperate fully with\nthe International Criminal Court in the ongoing preliminary examination and, if an\ninvestigation is initiated, continue that cooperation, inter alia by ensuring the protection of\nvictims and witnesses;\n165. Authorize the Office of the United Nations High Commissioner for Human Rights to\nresume its documentation of human rights violations in Burundi, which has been suspended\nsince October 2016;\n166. Sign and implement the memorandum of understanding with the African Union and\npermit the full deployment of 100 human rights observers and 100 military experts that was\ndecided upon in 2016;\n167. Cooperate with United Nations human rights mechanisms by once again receiving\nspecial procedures missions and implementing the recent recommendations of treaty bodies;\n168. Actively seek a lasting solution to the political crisis, inter alia through international\ninitiatives to promote dialogue.\n2.     Political parties and armed opposition groups should:\n169. Put an immediate end to human rights abuses and acts of violence committed by their\nmembers;\n170. Refrain from any incitement of violence and participate in the quest for a lasting\nsolution to the political crisis in Burundi.\n3      The Human Rights Council should:\n171. Extend the Commission’s mandate for a period of one year to enable it to conduct\nfurther and more thorough investigations in view of the persistence of gross human rights\nviolations and abuses and the absence of other specific mechanisms capable of undertaking\nindependent and thorough investigations into the human rights situation in Burundi;\n172. Request the Office of the United Nations High Commissioner for Human Rights to\nreport, at the forthcoming sessions of the Council, on the development of its cooperation with\nthe Burundian Government.\n4.     The International Criminal Court should:\n173. Initiate, as soon as possible, an investigation into the crimes committed in Burundi in\nlight of the conclusions contained in the present report and other information at its disposal.\n5.     The United Nations Security Council should:\n174. Take due account of the Commission’s conclusions, as well as persistence of gross\nviolations of human rights, in any discussion on Burundi and, in this context, ensure the\neffective implementation of resolution 2303 (2016);\n175. Refer to the International Criminal Court any international crime that might be\ncommitted in Burundi after 27 October 2017;\n176. Impose individual sanctions against the principal alleged perpetrators of gross human\nrights violations and international crimes in Burundi.\n6.     The Secretary-General of the United Nations should:\n177. Ensure that respect for human rights and restoration of the rule of law are among the\npriorities of his Special Envoy for Burundi;\n178. Ensure that no alleged perpetrator of human rights violations or international crimes\nin Burundi is recruited for United Nations peacekeeping missions.\n7.     The States Members of the United Nations should:\n179. Grant prima facie refugee status to Burundian asylum seekers and ensure strict re64ect\nfor the principle of non-refoulement and refugee protection;\n180. Prosecute, in accordance with the principle of universal jurisdiction, alleged\nperpetrators of international crimes committed in Burundi who are found to be in their\nterritory;\n181. Maintain, in the absence of any improvement in the human rights situation in Burundi,\nthe individual sanctions and the suspension of direct aid to the Government;\n182. Provide technical assistance inter alia in respect to autopsies, exhumations and\nidentification of bodies, to enable the Burundian to conduct credible and independent\ninvestigations;\n183. Support the establishment of specialized medical and psychosocial services,\nespecially for victims of torture and sexual violence;\n184. Support Burundian authorities in any judicial and security sector reform endeavors\nthat they might wish to undertake in order to improve the human rights situation.\n8.    The African Union should:\n185. Retake the lead in seeking a lasting solution to the crisis in Burundi based on respect\nfor human rights and rejection of impunity, as provided for in its Constitutive Act, and play\nan active role in that process;\n186. Ensure that no agent of the Burundian State who is accused of human rights violations\nor international crimes is recruited for African Union peacekeeping missions;\n187. Ensure that the full complement of African Union human rights observers and military\nexperts is deployed rapidly in Burundi;\n188. Consider, in the event that the current situation in Burundi persists, the application of\nArticle 4 (h) of the Constitutive Act of the African Union, under which it is authorized to\nintervene in a member State in certain circumstances, particularly in the event of crimes\nagainst humanity.\n9.    The East African Community should:\n189. Ensure that a rapid improvement of the human rights situation is a priority in its\nmediation efforts.\n10.    The guarantors of the 2000 Arusha Agreement, in their capacity as committed proponents\nof a lasting peace in Burundi, should:\n190. Meet with a view to finding a lasting solution to the political and human rights crisis\nin Burundi.\nAnnexe IV\nIndicateurs des facteurs de risque communs identifiés\ndans le Cadre d’analyse des atrocités criminelles\n(A/70/741-S/2016/71)\nVersion française\nFacteur de risque 1. Situations de conflit armé ou autres formes d’instabilité\na)     Conflit armé international ou non international ;\nb)      Crise sécuritaire provoquée, entre autres, par la dénonciation d’accords de\npaix, un conflit armé dans les pays voisins, des menaces d’interventions étrangères ou des\nactes de terrorisme ;\nc)     Crise ou urgence humanitaire, pouvant être causée notamment par une\ncatastrophe naturelle ou une épidémie ;\nd)     Instabilité politique provoquée par un changement de régime ou un transfert\nde pouvoir soudain ou irrégulier ;\ne)    Instabilité politique provoquée par des luttes de pouvoir ou la montée en\npuissance de mouvements d’opposition nationalistes, armés ou radicaux ;\nf)     Tension politique provoquée par des régimes autocratiques ou une lourde\nrépression politique ;\ng)     Instabilité économique provoquée par une pénurie de ressources ou des\ndifférends concernant leur utilisation ou leur exploitation ;\nh)     Instabilité économique provoquée par une crise grave de l’économie\nnationale ;\ni)     Instabilité économique provoquée par la misère, un chômage de masse ou de\nprofondes inégalités horizontales ;\nj)     Instabilité sociale provoquée par une résistance à l’autorité de l’État ou à ses\npolitiques ou par des protestations de masse contre celles-ci ;\nk)     Instabilité sociale provoquée par l’exclusion ou des tensions fondées sur des\nquestions d’identité, leur perception ou leurs formes extrémistes.\nFacteur de risque 2. Antécédents de violations graves du droit international\ndes droits de l’homme et du droit international humanitaire\na)     Restrictions ou violations graves, passées ou actuelles, des droits consacrés par\nle droit international des droits de l’homme et le droit international humanitaire, surtout si\nelles sont caractérisées par un comportement systématique observé préalablement et si elles\nvisent des groupes, populations ou personnes protégés ;\nb)    Actes de génocide, crimes contre l’humanité, crimes de guerre ou incitation à\nles commettre, survenus dans le passé ;\nc)      Politique ou pratique d’impunité ou de tolérance à l’égard de violations graves\ndu droit international des droits de l’homme et du droit international humanitaire, d’atrocités\ncriminelles ou de l’incitation à les commettre ;\nd)     Inaction, réticence à utiliser ou refus d’utiliser tous les moyens possibles pour\nfaire cesser des violations graves prévues, prévisibles ou persistantes du droit international\ndes droits de l’homme et du droit international humanitaire ou des atrocités criminelles\nprobables, ou incitation à les commettre ;\ne)      Maintien d’une aide à des groupes accusés de participer à des violations graves\ndu droit international des droits de l’homme et du droit international humanitaire, notamment\ndes atrocités criminelles, ou non-condamnation de leurs actes ;\nf)     Justification de violations graves du droit international des droits de l’homme\net du droit international humanitaire ou d’atrocités criminelles, rapports partiaux les\nconcernant ou refus de les reconnaître ;\ng)     Absence de processus de réconciliation ou de justice transitionnelle après un\nconflit, ou politisation de ce processus ;\nh)      Méfiance généralisée envers les institutions de l’État ou entre différents\ngroupes en raison de l’impunité.\nFacteur de risque 3. Faiblesse des structures de l’État\na)      Cadre juridique national n’offrant pas une protection suffisante et efficace,\nnotamment par la ratification et l’incorporation dans le droit interne des instruments relatifs\nau droit international des droits de l’homme et au droit international humanitaire ;\nb)     Manque de ressources au sein des institutions nationales, en particulier les\ninstitutions judiciaires et celles chargées de l’application des lois et de la protection des droits\nde l’homme, et manque de représentation adéquate ou de formation ;\nc)      Absence de justice indépendante et impartiale ;\nd)      Absence de contrôle civil efficace des forces de sécurité ;\ne)      Niveaux élevés de corruption ou mauvaise gouvernance ;\nf)       Absence ou insuffisance de mécanismes externes ou internes de contrôle et de\nresponsabilité, notamment que les victimes peuvent saisir pour demander réparation ;\ng)     Manque de sensibilisation et de formation des forces militaires, des forces\nirrégulières, des groupes armés non étatiques et des autres acteurs concernés au droit\ninternational des droits de l’homme et au droit international humanitaire ;\nh)     Manque de capacité de vérifier que les moyens et méthodes de guerre sont\nconformes aux normes du droit international humanitaire ;\ni)     Manque de moyens pour la réforme ou le renforcement des institutions,\nnotamment par une aide régionale ou internationale ;\nj)     Ressources insuffisantes pour mettre en œuvre des mesures globales de\nprotection des populations.\nFacteur de risque 4. Motivations ou incitations\na)     Motivations politiques, en particulier celles visant l’acquisition ou la\nconsolidation du pouvoir ;\nb)     Intérêts économiques, notamment ceux fondés sur la préservation et le\nbien-être des élites ou de groupes d’identité, ou sur le contrôle de la répartition des\nressources ;\nc)      Intérêts stratégiques ou militaires, notamment ceux fondés sur la protection ou\nla saisie de territoires et de ressources ;\nd)     Autres intérêts, notamment ceux visant à rendre une zone homogène dans son\nidentité ;\ne)     Menaces réelles ou perçues comme telles de groupes, populations ou personnes\nprotégés contre les intérêts ou les objectifs des auteurs d’actes criminels, notamment\nl’impression de déloyauté envers une cause ;\nf)      Appartenance ou adhésion réelle ou perçue comme telle de groupes,\npopulations ou personnes protégés à des groupes d’opposition armés ;\ng)      Idéologies fondées sur la suprématie d’une certaine identité ou sur des versions\nextrémistes de l’identité ;\nh)      Politisation de griefs, de tensions ou de cas d’impunité issus du passé ;\ni)     Traumatisme social provoqué par des situations de violence passées auxquelles\nil n’a pas été donné de suite satisfaisante et qui ont engendré des sentiments de perte, de\ndéplacement et d’injustice et un désir possible de revanche.\nFacteur de risque 5. Capacité de commettre des atrocités criminelles\na)     Disponibilité de personnel et d’armes et munitions ou de moyens financiers\npublics ou privés permettant de les acquérir;\nb)     Capacité de transporter et déployer du personnel et de transporter et distribuer\ndes armes et des munitions;\nc)      Capacité d’encourager ou de recruter de nombreux partisans au sein de\npopulations ou de groupes et disponibilité de moyens pour les mobiliser;\nd)     Solide culture d’obéissance à l’autorité et de conformité au groupe;\ne)      Présence d’autres forces armées ou de groupes armés non étatiques ou\nexistence de liens avec de tels forces ou groupes;\nf)    Présence d’acteurs commerciaux ou d’entreprises pouvant jouer un rôle\ndéterminant en fournissant des biens, des services ou d’autres formes d’appui pratique ou\ntechnique contribuant à soutenir les auteurs;\ng)     Appui financier, politique ou autre d’acteurs nationaux influents ou riches;\nh)     Appui armé, financier, logistique ou autre, notamment sous la forme\nd’entraînement, fourni par des acteurs extérieurs, notamment des États, des organisations\ninternationales ou régionales ou des entreprises privées.\nFacteur de risque 6. Absence de facteurs atténuants\na)      Insuffisance ou absence de processus d’autonomisation, de ressources, d’alliés\nou d’autres éléments qui pourraient contribuer à la capacité des groupes, populations ou\npersonnes protégés de se protéger eux-mêmes;\nb)     Absence de société civile nationale solide, organisée et représentative et de\nmédias nationaux libres, diversifiés et indépendants;\nc)    Absence d’intérêt et d’attention des acteurs de la société civile internationale\nou d’accès aux médias internationaux;\nd)     Absence ou présence limitée des Nations Unies, d’organisations non\ngouvernementales internationales ou d’autres acteurs internationaux ou régionaux dans le\npays ayant accès aux populations;\ne)     Absence d’adhésion ou de participation effective de l’État à des organisations\ninternationales ou régionales établissant des obligations afférentes au statut de membre;\nf)     Manque de contact, d’ouverture ou de relations politiques ou économiques\navec d’autres États ou organisations;\ng)      Coopération limitée de l’État avec les mécanismes internationaux et régionaux\ndes droits de l’homme;\nh)    Manque de volonté des parties à un conflit d’engager un dialogue, de faire des\nconcessions et de solliciter l’appui de la communauté internationale, ou absence d’incitations\nà le faire;\ni)     Réticence ou échec des États Membres de l’Organisation des Nations Unies ou\ndes organisations internationales ou régionales à aider un État à assumer sa responsabilité de\nprotéger ses populations contre les atrocités criminelles, ou à agir lorsque l’État n’assume\nmanifestement pas cette responsabilité, ou indifférence à cet égard;\nj)     Manque de soutien des États voisins pour ce qui est de protéger les populations\nà risque en quête de refuge : fermeture des frontières, rapatriement forcé ou restrictions en\nmatière d’aide;\nk)    Absence de mécanisme d’alerte rapide permettant de prévenir des atrocités\ncriminelles.\nFacteur de risque 7. Circonstances propices ou action préparatoire restreignant\nles droits fondamentaux\na)      Suspension d’institutions vitales de l’État ou ingérence dans ces institutions,\nou mesures provoquant des modifications de leur composition ou l’équilibre des pouvoirs,\nen particulier s’il en résulte l’exclusion ou une sous-représentation de groupes protégés ;\nb)      Renforcement de l’appareil de sécurité, réorganisation ou mobilisation de\ncelui-ci contre des groupes, populations ou personnes protégés ;\nc)      Acquisition de grandes quantités d’armes et de munitions ou d’autres objets\npouvant être utilisés pour causer des dommages ;\nd)     Création de milices ou de groupes paramilitaires, ou intensification de l’appui\nà de tels milices ou groupes ;\ne)      Imposition d’un contrôle strict sur l’utilisation des moyens de communication\nou interdiction d’y avoir accès ;\nf)      Expulsion ou refus d’autoriser la présence d’organisations non\ngouvernementales, d’organisations internationales, de médias ou d’autres acteurs pertinents\nou imposition de lourdes restrictions à leurs services et déplacements ;\ng)     Augmentation du nombre de violations du droit à la vie, de l’intégrité\nphysique, de la liberté ou de la sécurité de membres de groupes, populations ou personnes\nprotégés, ou adoption récente de mesures ou de lois qui leur portent atteinte ou constituent\nune discrimination délibérée envers eux ;\nh)     Augmentation du nombre d’actes de violence graves contre les femmes et les\nenfants ou création de conditions facilitant la commission d’agressions sexuelles contre eux,\nnotamment comme instrument de terreur ;\ni)     Imposition de conditions de vie délétères ou déportation, appréhension,\nregroupement, ségrégation, évacuation, déplacement ou transfert forcés de groupes,\npopulations ou individus protégés vers des camps, des zones rurales, des ghettos ou d’autres\nlieux désignés ;\nj)      Destruction ou pillage de biens ou d’installations essentiels à des groupes,\npopulations ou personnes protégés, ou de biens liés à l’identité culturelle et religieuse ;\nk)      Marquage de personnes ou de leurs biens au motif de leur appartenance à un\ngroupe ;\nl)      Politisation accrue de l’identité, d’événements du passé ou de motifs de se\nlivrer à la violence ;\nm)     Augmentation du nombre de déclarations provocatrices, de campagnes de\npropagande ou d’incitations à la haine visant des groupes, populations ou personnes protégés.\nFacteur de risque 8. Facteurs déclencheurs\na)      Déploiement soudain de forces de sécurité ou déclenchement d’hostilités\narmées ;\nb)     Débordement de conflits armés ou graves tensions dans les pays voisins ;\nc)     Mesures prises par la communauté internationale, perçues par un État comme\nmenaçant sa souveraineté ;\nd)      Changements de régime, transferts de pouvoir ou modifications du pouvoir\npolitique des groupes, survenant soudainement ou irrégulièrement ;\ne)      Atteintes à la vie, à l’intégrité physique, à la liberté ou à la sécurité de\ndirigeants, de personnalités éminentes ou de membres de groupes opposés ; autres actes de\nviolence graves, notamment attentats terroristes ;\nf)     Manifestations religieuses ou actes réels ou perçus comme tels d’intolérance\nreligieuse ou d’irrespect, notamment en dehors des frontières nationales ;\ng)       Actes d’incitation ou propagande haineuse visant des groupes ou des personnes\nparticulières ;\nh)     Recensement, élections, activités essentielles liées à ces processus ou mesures\nqui les déstabilisent ;\ni)     Changements soudains affectant l’économie ou la population active, résultant\nnotamment de crises financières, de catastrophes naturelles ou d’épidémies ;\nj)     Découverte de ressources naturelles ou lancement de projets d’exploitation\nayant de graves incidences sur les moyens de subsistance et la viabilité de groupes ou de\npopulations civiles ;\nk)     Commémoration de crimes du passé ou d’épisodes traumatiques ou historiques\npouvant exacerber les tensions entre groupes, notamment la glorification d’auteurs\nd’atrocités ;\nl)     Actes liés aux processus d’établissement des responsabilités, en particulier\ns’ils sont perçus comme injustes.\nVersion anglaise\nRisk factor 1. Situations of armed conflict or other forms of instability\n(a)   International or non-international armed conflict;\n(b)   Security crisis caused by, among other factors, defection from peace\nagreements, armed conflict in neighboring countries, threats of external interventions or acts\nof terrorism;\n(c)    Humanitarian crisis or emergency, including those caused by natural disasters\nor epidemics;\n(d)   Political instability caused by abrupt or irregular regime change or transfer of\npower;\n(e)     Political instability caused by disputes over power or growing nationalist,\narmed or radical opposition movements;\n(f)   Political tension caused by autocratic regimes or severe political repression;\n(g)     Economic instability caused by scarcity of resources or disputes over their use\nor exploitation;\n(h)   Economic instability caused by severe crisis in the national economy;\n(i)    Economic instability caused by acute poverty, mass unemployment or deep\nhorizontal inequalities;\n(j)    Social instability caused by resistance to, or mass protests against, State\nauthority or policies;\n(k)    Social instability caused by exclusion or tensions based on identity issues, their\nperception or extremist forms.\nRisk factor 2. Record of serious violations of international human rights and humanitarian\nlaw\n(a)    Past or present serious restrictions to or violations of international human rights\nand humanitarian law, particularly if assuming an early pattern of conduct and if targeting\nprotected groups, populations or individuals;\n(b)   Past acts of genocide, crimes against humanity, war crimes or their incitement;\n(c)     Policy or practice of impunity for or tolerance of serious violations of\ninternational human rights and humanitarian law, of atrocity crimes, or of their incitement;\n(d)    Inaction, reluctance or refusal to use all possible means to stop planned,\npredictable or ongoing serious violations of international human rights and humanitarian law\nor likely atrocity crimes, or their incitement;\n(e)   Continuation of support to groups accused of involvement in serious violations\nof international human rights and humanitarian law, including atrocity crimes, or failure to\ncondemn their actions;\n(f)     Justification, biased accounts or denial of serious violations of international\nhuman rights and humanitarian law or atrocity crimes;\n(g)   Politicization or absence of reconciliation or transitional justice processes\nfollowing conflict;\n(h)    Widespread.\nRisk factor 3. Weakness of State structures\n(a)    National legal framework that does not offer ample and effective protection,\nincluding through ratification and domestication of relevant international human rights and\nhumanitarian law treaties;\n(b)    National institutions, particularly judicial, law enforcement and human rights\ninstitutions that lack sufficient resources, adequate representation or training;\n(c)    Lack of an independent and impartial judiciary;\n(d)    Lack of effective civilian control of security forces;\n(e)    High levels of corruption or poor governance;\n(f)     Absence or inadequate external or internal mechanisms of oversight and\naccountability, including those where victims can seek recourse for their claims;\n(g)     Lack of awareness of and training on international human rights and\nhumanitarian law to military forces, irregular forces and non-State armed groups, or other\nrelevant actors;\n(h)     Lack of capacity to ensure that means and methods of warfare comply with\ninternational humanitarian law standards;\n(i)    Lack of resources for reform or institution-building, including through regional\nor international support;\n(j)    Insufficient resources to implement overall measures aimed at protecting\npopulations.\nRisk factor 4. Motives or incentives\n(a)     Political motives, particularly those aimed at the attainment or consolidation\nof power;\n(b)     Economic interests, including those based on the safeguard and well-being of\nelites or identity groups, or control over the distribution of resources;\n(c)    Strategic or military interests, including those based on protection or seizure\nof territory and resources;\n(d)   Other interests, including those aimed at rendering an area homogeneous in its\nidentity;\n(e)     Real or perceived threats posed by protected groups, populations or individuals\nagainst interests or objectives of perpetrators, including perceptions of disloyalty to a cause;\n(f)    Real or perceived membership of or support for armed opposition groups by\nprotected groups, populations or individuals;\n(g)     Ideologies based on the supremacy of a certain identity or on extremist\nversions of identity;\n(h)    Politicization of past grievances, tensions or impunity;\n(i)    Social trauma caused by past incidents of violence not adequately addressed\nand that produced feelings of loss, displacement, injustice and a possible desire for revenge.\nRisk factor 5. Capacity to commit atrocity crimes\n(a)    Availability of personnel and of arms and ammunition, or of the financial\nresources, public or private, for their procurement;\n(b)   Capacity to transport and deploy personnel and to transport and distribute arms\nand ammunition;\n(c)    Capacity to encourage or recruit large numbers of supporters from populations\nor groups, and availability of the means to mobilize them;\n(d)    Strong culture of obedience to authority and group conformity;\n(e)    Presence of or links with other armed forces or with non-State armed groups;\n(f)    Presence of commercial actors or companies that can serve as enablers by\nproviding goods, services, or other forms of practical or technical support that help to sustain\nperpetrators;\n(g)    Financial, political or other support of influential or wealthy national actors;\n(h)    Armed, financial, logistic, training or other support of external actors,\nincluding States, international or regional organizations, private companies, or others.\nRisk factor 6. Absence of mitigating factors\n(a)    Limited or lack of empowerment processes, resources, allies or other elements\nthat could contribute to the ability of protected groups, populations or individuals to protect\nthemselves;\n(b)    Lack of a strong, organized and representative national civil society and of a\nfree, diverse and independent national media;\n(c)    Lack of interest and focus of international civil society actors or of access to\ninternational media;\n(d)    Lack of, or limited presence of, the United Nations, international non-\ngovernmental organizations or other international or regional actors in the country and with\naccess to populations;\n(e)    Lack of membership and effective participation of the State in international or\nregional organizations that establish mandatory membership obligations;\n(f)    Lack of exposure, openness or establishment of political or economic relations\nwith other States or organizations;\n(g)    Limited cooperation of the State with international and regional human rights\nmechanisms;\n(h)    Lack of incentives or willingness of parties to a conflict to engage in dialogue,\nmake concessions and receive support from the international community;\n(i)      Lack of interest, reluctance or failure of States Members of the United Nations\nor members of international or regional organizations to support a State to exercise its\nresponsibility to protect populations from atrocity crimes, or to take action when the State\nmanifestly fails that responsibility;\n(j)    Lack of support by neighbouring States to protect populations at risk and in\nneed of refuge, including by closure of borders, forced repatriation or aid restriction;\n(k)    Lack of an early warning mechanism relevant to the prevention of atrocity\ncrimes.\nRisk factor 7. Enabling circumstances or preparatory action\n(a)    Imposition of emergency laws or extraordinary security measures that erode\nfundamental rights;\n(b)    Suspension of or interference with vital State institutions, or measures that\nresult in changes in their composition or balance of power, particularly if this results in the\nexclusion or lack of representation of protected groups;\n(c)    Strengthening of the security apparatus, its reorganization or mobilization\nagainst protected groups, populations or individuals;\n(d)    Acquisition of large quantities of arms and ammunition or of other objects that\ncould be used to inflict harm;\n(e)     Creation of, or increased support to, militia or paramilitary groups;\n(f)    Imposition of strict control on the use of communication channels, or banning\naccess to them;\n(g)    Expulsion or refusal to allow the presence of non-governmental organizations,\ninternational organizations, media or other relevant actors, or imposition of severe\nrestrictions on their services and movements;\n(h)    Increased violations of the right to life, physical integrity, liberty or security of\nmembers of protected groups, populations or individuals, or recent adoption of measures or\nlegislation that affect or deliberately discriminate against them;\n(i)   Increased serious acts of violence against women and children, or creation of\nconditions that facilitate acts of sexual violence against those groups, including as a tool of\nterror;\n(j)    Imposition of life-threatening living conditions or the deportation, seizure,\ncollection, segregation, evacuation or forced displacement or transfer of protected groups,\npopulations or individuals to camps, rural areas, ghettos or other assigned locations;\n(k)    Destruction or plundering of essential goods or installations for protected\ngroups, populations or individuals, or of property related to cultural and religious identity;\n(l)     Marking of people or their property based on affiliation to a group;\n(m)     Increased politicization of identity, past events or motives to engage in\nviolence;\n(n)    Increased inflammatory rhetoric, propaganda campaigns or hate speech\ntargeting protected groups, populations or individuals.\nRisk factor 8. Triggering factors\n(a)     Sudden deployment of security forces or commencement of armed hostilities;\n(b)     Spillover of armed conflicts or serious tensions in neighbouring countries;\n(c)   Measures taken by the international community perceived as threatening to a\nState’s sovereignty;\n(d)    Abrupt or irregular regime changes, transfers of power, or changes in political\npower of groups;\n(e)     Attacks against the life, physical integrity, liberty or security of leaders,\nprominent individuals or members of opposing groups; other serious acts of violence, such\nas terrorist attacks;\n(f)    Religious events or real or perceived acts of religious intolerance or disrespect,\nincluding outside national borders;\n(g)   Acts of incitement or hate propaganda targeting particular groups or\nindividuals;\n(h)     Census, elections, pivotal activities related to those processes, or measures that\ndestabilize them;\n(i)     Sudden changes that affect the economy or the workforce, including as a result\nof financial crises, natural disasters or epidemics;\n(j)    Discovery of natural resources or launching of exploitation projects that have\na serious impact on the livelihoods and sustainability of groups or civilian populations;\n(k)   Commemoration events of past crimes or of traumatic or historical episodes\nthat can exacerbate tensions between groups, including the glorification of perpetrators of\natrocities;\n(l)    Acts related to accountability processes, particularly when perceived as unfair.","annex":1},{"id":"a-hrc-45-crp-1-p0001","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":0,"section":"E. Sexual violence against men since 2015","text":"444. Since its establishment, the Commission has collected a substantial number of witness accounts related to sexual violence against men and boys committed in Burundi between April 2015 and June 2020, particularly in the context of detention.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0002","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":1,"section":"E. Sexual violence against men since 2015","text":"445. Sexual violence against men and boys in conflict situations or countries in transition receives little recognition or consideration, due to the tendency to prioritize sexual violence against women and girls in international organizations’ policies and programmatic frameworks, and the United Nations in particular. This situation, which essentially results from the observation that women and girls are disproportionately affected by sexual violence in situations of armed conflict and transition, has the effect of creating a conflation between sexual violence and violence against women and girls.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0003","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":2,"section":"E. Sexual violence against men since 2015","text":"446. In addition, due to the gender roles and norms that prevail in Burundi, as in most societies, which associate masculinity to strength and power, men and boys are particularly reluctant to report the violence which they have been subjected to as sexual violence and would rather speak of torture. Indeed, as a result of sexual violence, men feel diminished or stripped of their virility and masculinity, and they call into question their ability to procreate and their role in the family and the community.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0004","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":3,"section":"E. Sexual violence against men since 2015","text":"447. Moreover, when social norms prohibit homosexuality and national legislation criminalizes homosexual relations without distinguishing between consensual and non-consensual sexual acts, as it is the case in Burundi, men who survive sexual violence are also at risk of being stigmatized for their alleged sexual orientation and even run the risk of being prosecuted, thus fostering a sociocultural and legal framework that favors impunity for such violence. Furthermore, it is not uncommon for survivors to find it easier to initially report that they witnessed these acts rather than declaring themselves victims of the reported acts.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0005","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":4,"section":"E. Sexual violence against men since 2015","text":"448. Interviews and research conducted by the Commission suggest that the difficulty of conceptualizing acts constituting sexual violence against men as sexual violence and not simply as acts of torture or ill-treatment also extends to human rights organizations that work in Burundi or on Burundi. Since at least 2006, methods of torture constitutive of sexual violence have been used regularly against men and women in detention, especially those under the responsibility of the SNR. However, in most cases, sexual violence against men was solely reported as torture and ill-treatment, while violence against women was reported as sexual and gender-based violence.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0006","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":5,"section":"E. Sexual violence against men since 2015","text":"449. This partial recognition - or lack thereof - of sexual violence committed by state agents against men and boys has multiple consequences. Indeed, when the sexualized nature of the acts is obscured, there is little chance that the violence will receive any adequate and specific response, be it in the form of providing assistance to survivors, fighting impunity and preventing this type of violence or access to justice and reparations. The African Commission on Human and Peoples’ Rights also underlined in 2017 that acts of sexual violence can target any individual, no matter their gender, and that sexual violence against men and boys (among others gender categories) must receive adequate and effective response from States. Better understanding of sexual violence against men is therefore necessary to improve and complete the analysis of the gender dimension of a conflict or a crisis.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0007","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":6,"section":"E. Sexual violence against men since 2015","text":"450. Victims were born between 1977 and 2000, and two of them were minors at the time of the occurrence. Several were students, some were unemployed, some others were employed in the public service, or in the private sector. Many of them resided in Bujumbura (Mairie), although they often were natives of other provinces. Several victims were affiliated with an opposition party (mainly MSD in 2015-2016 and mostly CNL in 2019-2020), but others said they were not members of any party.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0008","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":7,"section":"E. Sexual violence against men since 2015","text":"451. Commenting on the profile of male victims of sexual torture in detention at SNR, one witness said “the people targeted were mostly strong young men who looked intelligent”.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0009","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":8,"section":"E. Sexual violence against men since 2015","text":"452. The reasons cited for targeting the victims were, above all, political and security related and were generally multiple. Victims were accused of participating in protests against the third term; supporting or participating in armed actions against the Government in the capital or in certain provinces or of having information on these actions; possessing arms or ammunition; being in contact with rebels or of spying on behalf of a foreign government; providing information or working in collaboration with civil society or independent media; supporting an opposition party or of having refused to support CNDD-FDD. They were also targeted because one of their relatives was wanted for one of these reasons.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0010","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":9,"section":"E. Sexual violence against men since 2015","text":"3. Sexual violence as a form of torture used by the SNR","unnumbered":true},{"id":"a-hrc-45-crp-1-p0011","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":10,"section":"E. Sexual violence against men since 2015","text":"453. The vast majority of sexual violence against men documented by the Commission was committed in the context of arbitrary detentions under the responsibility of the SNR and ranged from a few hours to several weeks, in official or unofficial places, mainly at SNR’s headquarters located near the cathedral in Bujumbura, but also residential houses, rooms or containers located in Bujumbura, Rumonge, Ruyigi or Ngozi. Moreover, even when a place of detention was not identified, victims recognized their aggressors as SNR agents, in particular by their attire or through the presence of certain senior officers whom they identified or recognized.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0012","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":11,"section":"E. Sexual violence against men since 2015","text":"454. Sexual violence was also perpetrated by police officers, in particular the unit for the protection of institutions (API - Appui à la protection des institutions), and Imbonerakure in places of detention under the responsibility of the SNR.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0013","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":12,"section":"E. Sexual violence against men since 2015","text":"455. Sexual violence was always committed jointly with other forms of violence that also constitute torture or cruel, inhuman or degrading treatment, particularly kicking, beating with sticks, truncheons or even with the butt of a gun or electric cables. It was also accompanied by death threats, mock executions, and victims were forced to witness the torture or execution of others.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0014","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":13,"section":"E. Sexual violence against men since 2015","text":"456. Certain acts of violence, particularly those targeting genitals and rape, have been committed with the intention of inflicting severe mental or physical suffering on the victims with the aim of punishing them or extracting a confession, and are therefore constitutive of torture. Others, such as forced nudity and insults, which were clearly intended to humiliate or intimidate victims, amount to inhuman or degrading treatment.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0015","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":14,"section":"E. Sexual violence against men since 2015","text":"457. The analysis of the modus operandi of this sexual violence reveals that the sexual organs and sexuality of men were strategically and deliberately targeted, and several witness accounts suggest that the choice of torture methods to be applied on a detainee was not intuitively decided by the questioning agent.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0016","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":15,"section":"E. Sexual violence against men since 2015","text":"458. In some cases, senior SNR officers were present during torture sessions and they either participated in interrogations or left the scene after leaving instructions.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0017","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":16,"section":"E. Sexual violence against men since 2015","text":"“He then told me to stand up and walk with the can […] [a SNR official] said, ‘this bastard of a Tutsi does not want to talk. He is going to talk whether he wants to or not’. He ordered the [officers] to do the job”.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0018","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":17,"section":"E. Sexual violence against men since 2015","text":"459. In addition, several witness accounts indicate that there were tools dedicated to torture, including those targeting genitals, and that the tools was stored in a specific location at the SNR headquarters in Bujumbura. Some detainees found the tools already set up in the room where they were questioned.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0019","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":18,"section":"E. Sexual violence against men since 2015","text":"460. One man described his arrival at SNR’s detention center as follows:","unnumbered":true},{"id":"a-hrc-45-crp-1-p0020","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":19,"section":"E. Sexual violence against men since 2015","text":"“They undressed me […] because my hands were still [tied up]. Then they […] tied my testicles […] and the rope was attached to a can filled with sand. […] The can and the rope were in the room already”.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0021","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":20,"section":"E. Sexual violence against men since 2015","text":"a) Violence targeting genitals","unnumbered":true},{"id":"a-hrc-45-crp-1-p0022","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":21,"section":"E. Sexual violence against men since 2015","text":"461. One of the most common forms of sexual violence inflicted upon men and boys in detention involves tying up their genitals – testicles in most cases, to a ballast, most often a water or sand-filled container – and forcing the victim to stand up and walk, or suspend the victim in the air with their feet not touching the ground, in order for the weight of the container to pull down their testicles, for a timeframe ranging from a few minutes to several hours. This practice already existed at the SNR before the 2015 political crisis, but several sources indicated that the security forces have used it more systematically since 2015.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0023","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":22,"section":"E. Sexual violence against men since 2015","text":"462. This method, commonly referred to as the canister technique, which aims at inflicting severe pain, has been used during interrogations to force victims to give information they may have, particularly on hidden weapons caches or armed groups activities or to punish them for acts they allegedly committed.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0024","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":23,"section":"E. Sexual violence against men since 2015","text":"“This technique was used against anyone accused of being against the Government. The goal was to inflict as much pain as possible, often in order to make one confess doing things they had not done and have an excuse for sending them to prison […] these same confessions were used to bring people to court […] [or to] extract confessions against [other persons]”.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0025","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":24,"section":"E. Sexual violence against men since 2015","text":"463. One man recounted how the individuals who tortured him hung him from the ceiling before attaching a weight to his penis and testicles:","unnumbered":true},{"id":"a-hrc-45-crp-1-p0026","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":25,"section":"E. Sexual violence against men since 2015","text":"“They took a canister […] filled with sand mixed with water and tied it to my genitals. […] I felt unspeakable pain because it was my genitals that carried the canister. […] They left it there for at least ten minutes. Then I was brought down. […] They kept telling me […] ‘why do you not contribute to the leading party?’, that I am a spy for the civil society”.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0027","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":26,"section":"E. Sexual violence against men since 2015","text":"464. The same man testified that after several days in detention during which he was subjected to various forms of torture, including on his genitals, he ended up acknowledging everything he was accused:","unnumbered":true},{"id":"a-hrc-45-crp-1-p0028","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":27,"section":"E. Sexual violence against men since 2015","text":"“Begging for forgiveness, I was in so much pain, I accepted all of their accusations when in reality I am not in contact with any of the people whose names they mentioned”.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0029","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":28,"section":"E. Sexual violence against men since 2015","text":"465. Witness accounts collected by the Commission describe certain variations of this technique, such as the replacement of the container by a system of cords or tying up bags filled with mud or applying this system to several detainees concurrently, for added humiliation.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0030","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":29,"section":"E. Sexual violence against men since 2015","text":"466. Several men detained at SNR were subjected to injections of unidentified fluid into their testicles. These injections caused a burning sensation, severe pain and dizziness, sometimes fainting. A man also reported being badly burned from boiling water poured over his penis, which SNR agents lifted with sticks. Another man reported that his testicles were pinched and injured with pliers.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0031","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":30,"section":"E. Sexual violence against men since 2015","text":"467. Several men reported being kicked, including with boots,, beaten with sticks or hardwire or metal cables, and explained how the beating specifically targeted their genitals.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0032","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":31,"section":"E. Sexual violence against men since 2015","text":"“They also kicked me on the chest, [in] the ribs, on my genitals […] The blows on the genitals, they were precise; they forcibly spread my legs and then they kicked me […] the beating lasted about 30 minutes”.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0033","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":32,"section":"E. Sexual violence against men since 2015","text":"468. In some cases, detained victims were taken into the forest or the bush by SNR agents, with or without Imbonerakure, where they were subjected to sexual violence and other forms of violence:","unnumbered":true},{"id":"a-hrc-45-crp-1-p0034","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":33,"section":"E. Sexual violence against men since 2015","text":"“After we got out [of the vehicle], we were beaten; our pants pulled down and they hit us on the genitals while asking who sent us [mandated]. It was they [members of the SNR] who lowered our pants. To hit us, they used the rod of the Kalashnikov rifles”.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0035","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":34,"section":"E. Sexual violence against men since 2015","text":"469. In the course of their detention under SNR responsibility, men were raped by SNR agents or Imbonerakure, or forced under threat to have sex with other men or women detainees.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0036","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":35,"section":"E. Sexual violence against men since 2015","text":"470. Literature on sexual violence against men in conflict situations recognizes that men can be affected by different forms of rape that have not yet been specifically qualified, including situations in which a man is forced to have sex with another victim, male or female, including someone who may be a family member.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0037","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":36,"section":"E. Sexual violence against men since 2015","text":"471. More than any, this type of sexual violence touches on taboos on sexuality and the morality of the society; and is therefore much more difficult for the victims or the witnesses to denounce. It is therefore likely that many victims refuse to tell anyone about what happened to them. One victim explained:","unnumbered":true},{"id":"a-hrc-45-crp-1-p0038","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":37,"section":"E. Sexual violence against men since 2015","text":"“After forcing me to sleep with [X] they laughed a lot. Reflecting on what I had done, I wondered why they made me do it. Maybe to make a fool of me, maybe to hurt me. […]. What has happened to me has happened to other people even though people do not talk about it a lot […] There are people who cannot talk about it for mental reasons. Some are relieved to talk about it while others are so troubled, they cannot talk about it”.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0039","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":38,"section":"E. Sexual violence against men since 2015","text":"472. Men detained by the SNR were coerced into having vaginal sex with a woman detainee also under threat of death if they did not do so; act which constitutes both the rape of the detainee and the rape of these men, in the presence of the officers who had ordered them to do so.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0040","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":39,"section":"E. Sexual violence against men since 2015","text":"473. Men have been forced by SNR members to have anal sex with fellow men detainees. In case of refusal, they were severely beaten or subjected to other painful treatments. While they were complying, SNR members laughed at them and humiliated them with insults.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0041","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":40,"section":"E. Sexual violence against men since 2015","text":"“We were forced to do anal penetrations. We were told that we are friends, that we can [do anything]”.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0042","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":41,"section":"E. Sexual violence against men since 2015","text":"“They took a young man who was next to [me], told him to lie down on the ground and told me to go inside him. Then we reversed. […] During that time, the police were there laughing, hitting, saying ‘these Tutsi dogs, go back to where you come from’.”","unnumbered":true},{"id":"a-hrc-45-crp-1-p0043","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":42,"section":"E. Sexual violence against men since 2015","text":"474. In addition, at SNR, a man was raped by a man he identified as an Imbonerakure.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0044","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":43,"section":"E. Sexual violence against men since 2015","text":"475. Anal penetration, whether consensual or not, is taboo in the Burundian society. For men, it represents the opposite of a virile, socially valued sexual relationship, and therefore constitutes a factor of stigma. In addition, it should be remembered that sexual relationships between persons of the same gender are criminalized under Burundian law.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0045","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":44,"section":"E. Sexual violence against men since 2015","text":"476. Many men were subjected to forced nudity during their detention. They were forcibly stripped of their clothes or forced to undress, usually prior to an interrogation session during which they were in the presence of several other dressed men, and during which they were subjected to various forms of physical or psychological violence. This forced nudity served both to intensify the pain of other forms of violence, as well as the victims’ humiliation and sense of vulnerability, particularly because that caused them to expect further sexual violence.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0046","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":45,"section":"E. Sexual violence against men since 2015","text":"477. A man detained by SNR police officers reported that he was stripped naked before being kicked as well as beaten up with sticks and rifle butts. Policemen threatened to cut off his penis. Another, also held by the SNR, explained:","unnumbered":true},{"id":"a-hrc-45-crp-1-p0047","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":46,"section":"E. Sexual violence against men since 2015","text":"“We were naked, that is how they got to our testicles. […] Every time [the police] entered the container, they would ask us to undress. It was systematic”.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0048","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":47,"section":"E. Sexual violence against men since 2015","text":"478. Some have reported remaining naked for hours or even days among fellow inmates, men and sometimes women, who were also naked.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0049","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":48,"section":"E. Sexual violence against men since 2015","text":"“In total we were 31 people imprisoned in a small cell […]. We remained naked for the duration of the detention there [a month and a half]. The girls had also been tortured; we could see it on their bodies but we did not discuss the type of torture they suffered”.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0050","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":49,"section":"E. Sexual violence against men since 2015","text":"479. While subjected to sexual violence, several men were humiliated with insults referring to their ethnicity or sexuality.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0051","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":50,"section":"E. Sexual violence against men since 2015","text":"480. A man subjected to violence targeting his genitals declared:","unnumbered":true},{"id":"a-hrc-45-crp-1-p0052","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":51,"section":"E. Sexual violence against men since 2015","text":"“As soon as the [SNR agents] entered [the dungeon] they began to hurl insults at us, saying: ‘You Tutsis, you want us to return where we came from [the bush]. […] And now we are going to do something for you to make sure that you do not have children who are going to come and cause us problems. We are also going to ensure you are never going to want a girl’. […] Every one of them repeated the same thing every time”.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0053","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":52,"section":"E. Sexual violence against men since 2015","text":"481. Another man reported how, after being severely beaten, police officers used their hands to crush the testicles of his fellow inmate, whose arms and legs were tied, saying, “You little Hutu fool. Are you the one to want to protest against the President when you are of the same ethnic group? Tutsis are deceiving you”.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0054","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":53,"section":"E. Sexual violence against men since 2015","text":"4\t. Rape and sexual violence targeting women at SNR","unnumbered":true},{"id":"a-hrc-45-crp-1-p0055","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":54,"section":"E. Sexual violence against men since 2015","text":"482. During its investigations, the Commission also collected witness accounts relating to rape and other forms of sexual violence against women while in detention and under the responsibility of the SNR. Some of this violence was inflicted in the context of interrogations using procedures similar to what has been described for the men in order to make them confess certain information, to intimidate them or to punish them in relation to their alleged activities against the Government.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0056","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":55,"section":"E. Sexual violence against men since 2015","text":"483. Women were also raped on several occasions during their detention outside the context of interrogation. Far from constituting isolated opportunistic acts, the modus operandi of these rapes shows that this violence also helped to create the intimidating and punitive environment in which these women would confess the desired information.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0057","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":56,"section":"E. Sexual violence against men since 2015","text":"484. Witness accounts indicate that high-ranking officials of the SNR were aware of the ongoing violence and did not provide an adequate response, and that sometimes they were directly involved.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0058","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":57,"section":"E. Sexual violence against men since 2015","text":"485. Another indicator of the institution’s reputation in this regard is that relatives of women detainees at the SNR sought to ensure that these women would not be sexually tortured, mostly through their network of influence within the ruling party.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0059","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":58,"section":"E. Sexual violence against men since 2015","text":"486. A woman who had been detained by the SNR recounts her meeting with a member of her family who had pursued such steps: “the first thing [he] asked me was if I had been raped because I cried when I saw him”.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0060","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":59,"section":"E. Sexual violence against men since 2015","text":"487. Additional research and surveys would be warranted in order to determine the prevalence of this type of violations against women.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0061","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":60,"section":"E. Sexual violence against men since 2015","text":"5. Other forms of sexual violence against men","unnumbered":true},{"id":"a-hrc-45-crp-1-p0062","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":61,"section":"E. Sexual violence against men since 2015","text":"488. In the context of the crisis, other forms of sexual violence have been perpetrated against men, outside the context of SNR detention, particularly cases of “forced incest” and cases of emasculation. The violence was sometimes committed by Imbonerakure acting alongside police officers, or by armed men dressed in police or army uniforms and as civilians.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0063","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":62,"section":"E. Sexual violence against men since 2015","text":"489. This violence took place outside official places of detention, during raids on victims’ homes or during arbitrary arrests. Some cases were committed as part of the operations by security forces in the wake of the attacks on military camps in Bujumbura in December 2015 and during the first half of 2016.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0064","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":63,"section":"E. Sexual violence against men since 2015","text":"490. Men, under threat of physical violence, have been forced to commit incest by engaging in sex with a family member. In one case, the man who refused to carry out the order was severely beaten and forced to watch two of his family members being raped by police and Imbonerakure. He was later executed. In another case, the man who refused was beaten and threatened to be killed, before he obeyed orders by the police and the military who threatened him and his family. Such violence has had a highly traumatic impact on the affected families.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0065","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":64,"section":"E. Sexual violence against men since 2015","text":"491. Two witnesses said they saw that a male relative had been emasculated when his body was found. In one case, the emasculation took place before the victim’s execution as part of a night attack on his home by a group of armed men wearing different uniforms and civilian outfits. In the other case, the Imbonerakure are said to have mutilated the victim’s body; there was no way of telling whether the mutilation took place before or after his execution. Both victims were members of opposition political parties.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0066","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":65,"section":"E. Sexual violence against men since 2015","text":"6. Consequences on the victims and their families","unnumbered":true},{"id":"a-hrc-45-crp-1-p0067","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":66,"section":"E. Sexual violence against men since 2015","text":"492. Similarly to sexual violence against women and girls, sexual violence against men and boys has serious, long-lasting effects on the lives of the survivors, their health, their family relations as well as their role and place within community.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0068","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":67,"section":"E. Sexual violence against men since 2015","text":"493. The majority of survivors of sexual violence cases documented by the Commission were forced to leave Burundi, many of them believing that they would have been killed if they had stayed longer. Many of them left on their own, leaving their families behind; whom they have sometimes not heard since their departure, or even since their arrest months or years before.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0069","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":68,"section":"E. Sexual violence against men since 2015","text":"494. The men and boys subjected to violence targeting their genitals testified about pain and swelling of their testicles which, among other things, prevented them from walking normally and about severe pain that persisted for several months after these occurrences, especially when urinating. Some have developed erectile dysfunction.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0070","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":69,"section":"E. Sexual violence against men since 2015","text":"“I have been hit so many times in the genitals. They told me to bow with my arms at knee level and kicked me in the genitals. One consequence of the beating is that I can no longer have sex, I cannot have an erection, I have become like impotent”.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0071","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":70,"section":"E. Sexual violence against men since 2015","text":"495. Several of them requested access to medical care while in detention. However, treatment was only granted to two of them, in one case several months after the violence. The care in both cases proved to be clearly inadequate.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0072","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":71,"section":"E. Sexual violence against men since 2015","text":"496. Survivors did not always dare report to the medical staff that they had been raped.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0073","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":72,"section":"E. Sexual violence against men since 2015","text":"“I did not tell the doctor who was treating me because this is taboo in our culture. They gave me medicine. I have not recounted what happened to me, I am ashamed. I cannot talk about what happened in my life because I went through hell. I was humiliated and made to feel worthless”.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0074","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":73,"section":"E. Sexual violence against men since 2015","text":"497. Due to the multiple forms of violence that some men have suffered, they often present complex or severe clinical cases, sometimes also including fractures, digestive or respiratory problems.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0075","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":74,"section":"E. Sexual violence against men since 2015","text":"“The symptoms [I have]: diarrhoea, vomiting, dizziness, reddish urine, weakness […] they will not stop. The doctor is worried because even he can see that I am not getting better. […] I do not receive any psychological support, it would be better if I did, but I have to find someone who can help me”.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0076","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":75,"section":"E. Sexual violence against men since 2015","text":"498. Several men also described symptoms of depression and suicidal thoughts.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0077","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":76,"section":"E. Sexual violence against men since 2015","text":"499. A man detained by the SNR who suffered various forms of violence, including violence targeting his genitals, explained that he first thought of dying after escaping, before seeking asylum in another country:","unnumbered":true},{"id":"a-hrc-45-crp-1-p0078","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":77,"section":"E. Sexual violence against men since 2015","text":"“My problem was not so much about having a place to live as about going to a place where I did not feel the need to end my life”.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0079","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":78,"section":"E. Sexual violence against men since 2015","text":"500. Men who were raped expressed shame and fear of stigmatisation and marginalization associated with the kind of violence to which they were subjected.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0080","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":79,"section":"E. Sexual violence against men since 2015","text":"“Some things are shameful and one thinks that, if recounted, those who hear about them will start treating you differently. […] Even when I talked about it, it was not easy because I feared it would spread outside. […] You do not want to be known on the street as ‘the one who was taken from behind’. If what happened to me should be known in today’s society, it would be considered something dishonourable, for which one could be banished from society […] I would do not know where to go if that were to be known”.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0081","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":80,"section":"E. Sexual violence against men since 2015","text":"501. Sexual violence has also had a significant impact on these men’s sexuality and their emotional lives.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0082","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":81,"section":"E. Sexual violence against men since 2015","text":"“I no longer want to make love. They touched sensitive parts. […] I cannot make love to a woman because images of torture come back to me”.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0083","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":82,"section":"E. Sexual violence against men since 2015","text":"502. Survivors also expressed doubts on their ability to perform the valued and expected social functions of a man in Burundian society, particularly within the context of marriage and family.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0084","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":83,"section":"E. Sexual violence against men since 2015","text":"“When I think back to what happened [violence on genitals], it hurts a lot. And the idea of taking a wife is not something I envision because I do not know if I could manage”.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0085","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":84,"section":"E. Sexual violence against men since 2015","text":"503. In Burundian culture, marriage is a necessary step for one to be considered a successful man (or woman) in that it is the basis of the family. It is one of the most important traditional gender roles’ indicators, and a couple is generally expected to have their first child within 18 months of marriage. In a relationship, it is difficult to imagine that infertility can be caused by the man, the woman being generally held responsible. A study points out that a man’s impotence can thus become a domestic violence factor.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0086","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":85,"section":"E. Sexual violence against men since 2015","text":"“Because of this injection [into the testicle], I am afraid I will not be able to have children. I was in pain, there was pus coming out of my penis on its own and I was in great pain when I urinated”.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0087","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":86,"section":"E. Sexual violence against men since 2015","text":"504. Beyond the sometimes irreversible damage to their physical and mental health, sexual violence targeting men therefore has significant consequences on an essential component of the Burundian social fabric: the family, and on the way survivors perceive themselves and are perceived as men at the heart of the community.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0088","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":87,"section":"E. Sexual violence against men since 2015","text":"505. One woman said of the sexual torture inflicted on her husband: “Somehow this ensures that, even when he does not succumb to the torture, the victim cannot reproduce and they will live the handicap of not having sexual intercourse; it is a handicap, especially for a man. The aim is to ruin their lives permanently”.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0089","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":88,"section":"E. Sexual violence against men since 2015","text":"506. Depending on the country in which they sought asylum, these survivors had access to care more or less adapted to their physical and psychological problems. However, this assistance has not been provided as part of the support mechanisms for survivors of sexual and gender-based violence, which are generally not adapted to the specific needs of men. Programs intended to respond to and prevent sexual and gender-based violence are generally designed according to the logic of “woman and girl – victims and man – potential or actual perpetrator of violence”.","unnumbered":true},{"id":"a-hrc-45-crp-1-p0090","rec_id":"recjwlE047Tf8wW8i","symbol":"A/HRC/45/CRP.1","n":null,"seq":89,"section":"E. Sexual violence against men since 2015","text":"507. Having support groups, community associations and non-governmental organizations sensitized to the issue of sexual violence against men and boys would undoubtedly be a factor that would encourage survivors to speak up about their experience and help them obtain appropriate support.","unnumbered":true},{"id":"a-hrc-48-crp-1-u0000","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":null,"seq":0,"section":null,"text":"Conseil des droits de l’homme\nQuarante-huitième session\n13 septembre-1er octobre 2021\nPoint 4 de l’ordre du jour\nSituations des droits de l’homme qui requièrent l’attention du Conseil\nConclusions détaillées de la Commission d’enquête sur le Burundi\nTable des matières\nPage","unnumbered":true},{"id":"a-hrc-48-crp-1-p0001","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"1","seq":1,"section":"I. Introduction","text":"Le présent document détaille les conclusions décrites par la Commission d’enquête sur le Burundi dans son rapport soumis au Conseil des droits de l’homme à sa quarante-huitième session (A/HRC/48/68), en application de sa résolution 45/19 adoptée le 6 octobre 2020. Il doit être lu dans la continuité des quatre rapports que la Commission a présentés lors des trente-sixième, trente-neuvième, quarante-deuxième et quarante-cinquième sessions du Conseil des droits de l’homme, ainsi que des documents de séance détaillés qui les accompagnent."},{"id":"a-hrc-48-crp-1-p0002","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"2","seq":2,"section":"1. Mandat de la Commission","text":"Dans sa résolution 45/19, le Conseil des droits de l’homme a décidé de « Proroger le mandat de la Commission d’enquête sur le Burundi pour une nouvelle période d’un an afin qu’elle puisse poursuivre ses investigations, y compris en ce qui concerne les fondements économiques de l’État ». Le mandat global de la Commission reste celui qui a été défini initialement par le Conseil en 2016 lors de l’établissement de la Commission et complété en septembre 2019 :\n« a.\tMener une enquête approfondie sur les violations des droits de l’homme et atteintes à ces droits commises au Burundi depuis avril 2015, notamment pour en évaluer l’ampleur et déterminer s’il s’agit de crimes de droit international, afin de contribuer à la lutte contre l’impunité ;\nb.\tIdentifier les auteurs présumés de violations des droits de l’homme et d’atteintes à ces droits commises au Burundi, en vue de faire pleinement respecter le principe de responsabilité ;\nc.\tFormuler des recommandations sur les mesures à prendre pour garantir que les auteurs de ces actes aient à en répondre, quelle que soit leur affiliation ;\nd.\tDialoguer avec les autorités burundaises et toutes les autres parties prenantes, en particulier les organismes des Nations Unies, la société civile, les réfugiés, la présence du Haut-Commissariat au Burundi, les autorités de l’Union africaine et la Commission africaine des droits de l’homme et des peuples, afin de fournir l’appui et les conseils nécessaires à l’amélioration immédiate de la situation des droits de l’homme et à la lutte contre l’impunité » ; et\n« Approfondir ses enquêtes, […] eu égard en particulier aux fondements économiques de l’État »."},{"id":"a-hrc-48-crp-1-p0003","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"3","seq":3,"section":"1. Mandat de la Commission","text":"La Commission est le seul mécanisme international indépendant qui est en mesure de mener des enquêtes impartiales sur les violations des droits de l’homme commises récemment au Burundi, mais également de fournir une analyse approfondie et détaillée de la situation des droits de l’homme dans le pays. Au cours du présent terme de son mandat, elle a dû faire face à des défis particuliers. La Commission déplore notamment que sa période de travail effective ait été réduite en raison de la crise financière qui a touché les Nations Unies et le gel des recrutements qui en a découlé, ce qui a retardé la formation de son secrétariat."},{"id":"a-hrc-48-crp-1-p0004","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"4","seq":4,"section":"1. Mandat de la Commission","text":"Au cours de ce cinquième terme, la Commission a continué à travailler de manière indépendante et impartiale afin de remplir au mieux son mandat. Sa compétence matérielle est restée la même, à savoir : les violations de tous les droits de l’homme garantis par la législation nationale et le droit international commises par des agents ou entités étatiques ; ainsi que les atteintes à ces droits commises par des entités non-étatiques organisées avec une structure connue, ou par leurs membres. Sa compétence territoriale est toujours limitée aux faits commis sur le territoire burundais, même si la Commission s’estime compétente pour prendre en compte la répercussion ou la continuation de tels faits qui se produisent au-delà des frontières du Burundi. La compétence temporelle couvre la période qui a commencé en avril 2015 avec les premières manifestations contre la candidature de Pierre Nkurunziza à un troisième mandat présidentiel, et s’étend jusqu’à la date de présentation du présent rapport au Conseil des droits de l’homme en septembre 2021."},{"id":"a-hrc-48-crp-1-p0005","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"5","seq":5,"section":"1. Mandat de la Commission","text":"Cependant, dans le présent document, la Commission a décidé de s’intéresser principalement aux violations et atteintes commises depuis l’arrivée au pouvoir du Président Évariste Ndayishimiye le 18 juin 2020, et d’analyser les développements les plus significatifs en matière de droits de l’homme et de lutte contre l’impunité et la corruption. Elle a poursuivi son analyse sur les facteurs de risque de dégradation de la situation des droits de l’homme pour faire suite à celles réalisées dans le contexte électoral de 2020 et immédiatement après ces élections. La Commission a continué de se baser sur l’évolution des indicateurs déjà identifiés dans ses précédentes analyses."},{"id":"a-hrc-48-crp-1-p0006","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"6","seq":6,"section":"1. Mandat de la Commission","text":"À l’instar de ses précédents rapports, la Commission a également cherché à évaluer s’il existait des motifs raisonnables de croire que les violations documentées constituaient des crimes de droit international. Elle a poursuivi ses enquêtes visant à établir les responsabilités pour les violations des droits de l’homme et atteintes à ceux-ci, ainsi que pour les crimes contre l’humanité qu’elle a pu documenter. Elle a pris soin de distinguer entre la responsabilité en matière de droits de l’homme, qui ne concerne que l’État du Burundi pour les actes commis par ses agents ou des individus ou des groupes agissant sous son autorité ou son contrôle, et les responsabilités individuelles en matière de droit pénal international."},{"id":"a-hrc-48-crp-1-p0007","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"7","seq":7,"section":"1. Mandat de la Commission","text":"Dans le présent document, la Commission s’est également penchée sur la situation de l’État de droit au Burundi, qui est la clé pour établir un système de respect et de protection des droits de l’homme. L’État de droit a aussi un impact direct sur le niveau de développement économique, grande priorité du Président Ndayishimiye."},{"id":"a-hrc-48-crp-1-p0008","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"8","seq":8,"section":"1. Mandat de la Commission","text":"La Commission est confiante que la lecture combinée de l’ensemble de ses rapports permet de retracer la situation globale des droits de l’homme au Burundi entre avril 2015 et septembre 2021. Ces rapports ont également permis de donner une voix aux nombreuses victimes de violations des droits de l’homme et de crimes internationaux, qui ont été ignorées ou réduites au silence par les autorités burundaises successives qui ont nié l’existence de ces violations et ces crimes et ont donc refusé de les reconnaître comme des victimes et de s’acquitter de leurs obligations envers elles."},{"id":"a-hrc-48-crp-1-p0009","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"9","seq":9,"section":"1. Mandat de la Commission","text":"En outre, ces rapports donnent des éléments cruciaux et des analyses pertinentes pour comprendre la complexité de la situation dans le pays, les facteurs qui ont conduit à la crise politique de 2015 et les causes profondes des violations des droits de l’homme au Burundi, qui n’ont toujours pas été réglées, ainsi que les principaux facteurs de risque pour l’avenir."},{"id":"a-hrc-48-crp-1-p0010","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"10","seq":10,"section":"1. Mandat de la Commission","text":"La Commission a systématiquement indiqué au fil de ses rapports quelles étaient les mesures à prendre par les différents acteurs, et particulièrement les autorités burundaises, afin d’améliorer réellement et durablement la situation des droits de l’homme au Burundi et garantir que de telles crises ne se répètent pas sur le long terme. La Commission est confiante que ses recommandations restent utiles à tous les acteurs concernés, notamment le Gouvernement du Burundi, mais aussi les partenaires nationaux et internationaux, afin de guider leur engagement visant à aider le pays à changer de cap et à s’engager vers un véritable respect des droits de l’homme."},{"id":"a-hrc-48-crp-1-p0011","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"11","seq":11,"section":"2. Membres de la Commission","text":"Doudou Diène (Sénégal) est le Président de la Commission depuis sa nomination le 1er février 2018. Françoise Hampson (Royaume-Uni) est membre de la Commission depuis le 22 novembre 2016. Lucy Asuagbor (Cameroun), qui était membre depuis le 5 mars 2018, a démissionné le 24 mars 2021 suite à sa prise de nouvelles fonctions à plein temps au sein de la Commission nationale des droits de l’homme et des libertés du Cameroun."},{"id":"a-hrc-48-crp-1-p0012","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"12","seq":12,"section":"1. Coopération du Burundi","text":"Lors du renouvellement du mandat de la Commission, le Conseil des droits de l’homme a réitéré son appel « au Gouvernement burundais de coopérer pleinement avec la Commission d’enquête, d’autoriser celle-ci à se rendre dans le pays et de lui fournir toutes les informations nécessaires à la bonne exécution de son mandat »."},{"id":"a-hrc-48-crp-1-p0013","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"13","seq":13,"section":"1. Coopération du Burundi","text":"La Commission a perpétué ses démarches visant à entamer le dialogue avec les autorités burundaises, y compris à travers l’envoi de correspondances à la Mission permanente de la République du Burundi auprès de l’Office des Nations Unies et des autres organisations internationales à Genève. Elle a également réitéré sa demande aux autorités burundaises de lui transmettre des informations pertinentes sur la situation des droits de l’homme dans le pays, notamment au sujet d’éventuelles atteintes à l’encontre d’agents de l’État et de membres du parti au pouvoir et sur les enquêtes éventuellement menées sur les incidents de sécurité les plus récents. Cependant, comme par le passé et malgré une certaine ouverture affichée par le Président Ndayishimiye envers d’autres acteurs de la communauté internationale, les autorités burundaises ont persisté dans leur refus de coopérer avec la Commission."},{"id":"a-hrc-48-crp-1-p0014","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"14","seq":14,"section":"1. Coopération du Burundi","text":"Le 23 septembre 2020, lors du dialogue interactif sur le Burundi organisé dans le cadre de la quarante-cinquième session du Conseil des droits de l’homme, le Représentant permanent du Burundi à Genève a rejeté le rapport que la Commission d’enquête venait de présenter. Il l’a qualifié de « diffamatoire », « d’insultant » et de « politiquement motivé » sans étayer ses propos ni entrer sur le fond de telles accusations. Il a également indiqué que selon le Burundi, les mécanismes tels que la Commission d’enquête, le Bureau pays du Haut-Commissariat des Nations Unies aux droits de l’homme ou les procédures spéciales n’étaient pas « les seuls canaux de coopération avec les Nations Unies » et qu’il « en existe d’autres plus positifs qui promeuvent les droits humains, le développement des États et l’épanouissement des peuples », rejetant ainsi le principe même de coopération avec les principaux mécanismes internationaux des droits de l’homme."},{"id":"a-hrc-48-crp-1-p0015","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"15","seq":15,"section":"1. Coopération du Burundi","text":"Le 26 octobre 2020, lors du dialogue interactif sur le Burundi devant la Troisième Commission dans le cadre de la soixante-quinzième session de l’Assemblée générale des Nations Unies, le Représentant du Burundi a répété quasiment mot pour mot la déclaration faite à Genève le mois précédent."},{"id":"a-hrc-48-crp-1-p0016","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"16","seq":16,"section":"1. Coopération du Burundi","text":"Le 11 mars 2021, lors de la quarante-sixième session du Conseil des droits de l’homme, le Représentant permanent du Burundi a réitéré encore une fois les accusations selon lesquelles la Commission présentait des « allégations mensongères » et « politiquement orientées » sans apporter plus d’informations ou de détails. La Commission constate que le Gouvernement burundais conserve la même approche envers le travail de la Commission qu’à l’égard des autres mécanismes de droits de l’homme qui exigent une redevabilité pour les violations spécifiques des droits de l’homme."},{"id":"a-hrc-48-crp-1-p0017","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"17","seq":17,"section":"2. Coopération avec d’autres entités","text":"Le Conseil des droits de l’homme a prié « le Haut-Commissariat des Nations Unies aux droits de l’homme de fournir à la Commission d’enquête toutes les ressources nécessaires à l’exécution de son mandat ». Conformément à cette disposition et comme par le passé, la Commission a continué de bénéficier de l’entière coopération du Haut-Commissariat, qui a notamment mis à sa disposition un secrétariat avec les compétences spécialisées nécessaires à l’accomplissement de son mandat ainsi que l’indispensable assistance administrative, technique et logistique. Néanmoins, sa mise en place a été retardée en raison de la crise financière qui a affecté les Nations Unies."},{"id":"a-hrc-48-crp-1-p0018","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"18","seq":18,"section":"2. Coopération avec d’autres entités","text":"Ces facteurs ainsi que les restrictions de circulation liées à la pandémie de Covid-19 ont eu des répercussions sur la réalisation des enquêtes de la Commission. Cette dernière a dû prioriser les incidents et les violations des droits de l’homme à documenter et elle a choisi de se focaliser davantage sur les violations graves des droits civils et politiques au détriment des violations des droits économiques et sociaux qui avaient pu être couvertes dans ses précédents rapports."},{"id":"a-hrc-48-crp-1-p0019","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"19","seq":19,"section":"1. Méthodologie","text":"Au cours du présent terme de son mandat, la Commission a conservé sa méthodologie d’enquête et le niveau de preuve adopté précédemment, à savoir des « motifs raisonnables de croire », puisque ceux-ci sont parfaitement conformes aux orientations et pratiques reconnues pour les enquêtes sur des violations des droits de l’homme et des crimes internationaux par des mécanismes internationaux qui n’ont pas d’accès direct aux lieux où les faits ont été commis. Cette méthodologie repose sur les normes et règles pertinentes en la matière identifiées par le Haut-Commissariat des Nations Unies aux droits de l’homme (HCDH) et prend en compte les meilleures pratiques tirées de plus de deux décennies d’expérience."},{"id":"a-hrc-48-crp-1-p0020","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"20","seq":20,"section":"1. Méthodologie","text":"Malgré les difficultés spécifiques, la Commission a réalisé plus de 170 entretiens au cours de ce cinquième terme, ce qui fait un total de plus de 1770 témoignages réalisés depuis le début de son mandat. Ces nouveaux témoignages ont été recueillis auprès de victimes, de témoins, d’auteurs de violations et d’autres sources, qui résident au Burundi ou dans des pays tiers."},{"id":"a-hrc-48-crp-1-p0021","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"21","seq":21,"section":"1. Méthodologie","text":"La Commission a continué d’analyser chaque témoignage recueilli pour déterminer la fiabilité de la source et la validité des informations fournies. Les analyses et les conclusions présentées dans ce document sont exclusivement basées sur les informations qui ont pu être corroborées selon la méthodologie adoptée, notamment auprès d’autres sources primaires ou secondaires, et donc qui sont considérées comme crédibles par la Commission. Elle est confiante que les conclusions qu’elle présente dans le présent document sont solidement étayées et respectent le niveau de preuve adopté. Cependant, certains thèmes ou types d’incidents n’ont pas pu être suffisamment documentés, notamment en raison de la période de travail effective restreinte de son secrétariat et des restrictions de circulation internationales. C’est la raison pour laquelle les conclusions sur les violences sexuelles et basées sur le genre ou des cas de malversation économique restent limitées. Pour autant, cette absence de mention dans le présent document ne signifie nullement qu’aucun cas ou incident n’a eu lieu au cours de la période couverte. Cela indique seulement qu’en l’état actuel des choses, la Commission n’est pas en mesure de se prononcer à ce sujet."},{"id":"a-hrc-48-crp-1-p0022","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"22","seq":22,"section":"1. Méthodologie","text":"Pour son analyse des développements pertinents relatifs à la situation des droits de l’homme et aux facteurs de risque, la Commission s’est en partie basée sur des documents officiels du Gouvernement du Burundi et d’autres institutions burundaises, disponibles publiquement (rapports annuels, lois ou décrets), notamment sur leurs sites internet. Elle a également pris en compte les communications publiques telles que des comptes rendus des discours présidentiels, des communiqués de presse officiels, des messages publiés sur les comptes Twitter officiels ou personnels d’officiels burundais, des articles de la presse internationale et de médias burundais notamment la Radiotélévision nationale du Burundi (RTNB). Elle a également utilisé des rapports et autres documents publics préparés par les agences de l’Organisation des Nations Unies ou des institutions indépendantes."},{"id":"a-hrc-48-crp-1-p0023","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"23","seq":23,"section":"2. Droit applicable","text":"Le droit applicable au travail de la Commission reste le droit international des droits de l’homme et le droit pénal international ainsi que les conventions relatives à la lutte contre la corruption pour ce qui concerne les fondements économiques de l’État.\n(a)\tDroit international des droits de l’homme"},{"id":"a-hrc-48-crp-1-p0024","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"24","seq":24,"section":"2. Droit applicable","text":"Le Burundi reste partie aux mêmes conventions à vocation universelle, régionale et sous-régionale que celles mentionnées dans ses précédents rapports. Il n’a toujours pas ratifié les deux protocoles facultatifs au Pacte international relatif aux droits civils et politiques, ni la Convention internationale sur la protection des droits de tous les travailleurs migrants et des membres de leur famille, comme il s’y était pourtant engagé lors de son troisième Examen périodique universel au mois de janvier 2018.\n(b)\tDroit pénal international"},{"id":"a-hrc-48-crp-1-p0025","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"25","seq":25,"section":"2. Droit applicable","text":"Le retrait du Burundi du Statut de Rome, qui est effectif depuis le 27 octobre 2017, ne le dégage pas des obligations mises à sa charge lorsqu’il était partie à ce traité, ni de ses obligations en vertu du droit international coutumier en matière de crimes internationaux. La Commission a donc continué à se référer aux définitions des crimes énoncées dans le Statut de Rome, qui sont reprises en grande partie dans le Code pénal du Burundi, ainsi qu’à la jurisprudence des juridictions internationales, notamment celle des tribunaux pénaux pour l’ex-Yougoslavie (TPIY) et le Rwanda (TPIR).\n(c)\tConventions de lutte contre la corruption"},{"id":"a-hrc-48-crp-1-p0026","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"26","seq":26,"section":"2. Droit applicable","text":"Le Burundi est partie à la Convention de l’Union africaine pour la prévention et la lutte contre la corruption de 2003 depuis son entrée en vigueur le 5 août 2006 et à la Convention des Nations Unies contre la corruption de 2003 depuis mars 2006. Ces deux conventions sont les principaux instruments de référence en droit international pour ce qui a trait aux malversations économiques documentées par la Commission."},{"id":"a-hrc-48-crp-1-p0027","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"27","seq":27,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Le Gouvernement n’a pas autorisé le HCDH à rouvrir un bureau pays. Il n’accepte que des activités de renforcement des capacités et de coopération technique de la part du Centre des Nations Unies pour les droits de l’homme et la démocratie en Afrique centrale, basé au Cameroun.\nOrganes de traités sur les droits de l’homme"},{"id":"a-hrc-48-crp-1-p0028","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"28","seq":28,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Le Burundi n’a pas encore établi de mécanisme national de prévention de la torture comme l’exige le Protocole facultatif à la Convention contre la torture et autres peines ou traitements cruels, inhumains ou dégradants auquel il a adhéré en octobre 2013. Ses rapports périodiques sur la mise en œuvre des traités fondamentaux des droits de l’homme restent dus au Comité pour l’élimination de la discrimination raciale depuis novembre 1998 ; au Comité des droits de l’enfant depuis octobre 2015 ; au Comité des droits des personnes handicapées depuis juin 2016 ; au Comité des droits économiques, sociaux et culturels depuis octobre 2020 et au Comité pour l’élimination des discriminations envers les femmes depuis novembre 2020."},{"id":"a-hrc-48-crp-1-p0029","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"29","seq":29,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Au cours de sa 132ième session tenue du 28 juin au 23 juillet 2021, le Comité des droits de l’homme a adopté une liste de questions relatives au troisième rapport périodique soumis par le Burundi en septembre 2020. Dans sa liste de questions, le Comité a demandé au Gouvernement du Burundi, entre autres choses, de « répondre aux allégations concernant les nombreuses disparitions forcées et exécutions extrajudiciaires dues à des agents du Service national de Renseignement, de la police, des forces armées et à des Imbonerakure, dont les victimes sont principalement des opposants politiques. Ces violations, qui se sont intensifiées lors des manifestations du 2015, du référendum constitutionnel de mai 2018 et des élections de mai 2020, se poursuivent en juillet 2021 » et « à cet égard, fournir des renseignements : a) sur les mesures prises pour déterminer le sort des personnes disparues et les localiser ; b) sur les enquêtes menées, les poursuites engagées, les déclarations de culpabilité prononcées et les sanctions imposées aux responsables ; c) sur les mesures adoptées pour garantir aux familles des victimes l’accès à la justice et à des réparations adéquates »."},{"id":"a-hrc-48-crp-1-p0030","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"30","seq":30,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Le Comité lui a également demandé de « Commenter les informations faisant état de la pratique des autorités d’enterrer de manière immédiate des cadavres portant des traces de mort violente, sans les identifier, sans avertir leurs familles ni ouvrir d’enquêtes sur les circonstances des décès », mais aussi de « donner des informations sur les mesures prises pour : a) prévenir les actes de violence sexuelle perpétrés sur des femmes et des filles, mener des enquêtes sur ces actes, poursuivre et sanctionner les auteurs de ces actes, et assurer des réparations adéquates aux victimes, y compris des services médicaux et psychosociaux complets; b) sensibiliser les agents de l’État et les Imbonerakure à l’interdiction de toute forme de violence à l’égard des femmes et des filles »."},{"id":"a-hrc-48-crp-1-p0031","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"31","seq":31,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Le Comité a aussi sollicité qu’ « à la lumière des allégations sur les nombreux cas de détentions arbitraires, y compris de mineurs, ciblant principalement des opposants politiques », le Gouvernement décrive « les mesures prises pour veiller à ce que les agents publics responsables de ces faits soient sanctionnés, que les personnes arrêtées arbitrairement soient libérées et que les victimes puissent bénéficier d’une réparation adéquate » et qu’il commente « les allégations qui continuent de faire état de nombreux actes de harcèlement, d’intimidation et de violations des droits de l’homme, y compris d’enlèvements, de disparitions, de détentions arbitraires, de tortures, de violences sexuelles et d’exécutions extrajudiciaires, à l’encontre de journalistes, de défenseurs de droits de l’homme et d’opposants politiques, dont les auteurs seraient principalement des membres des forces de police et des services de renseignement, et des Imbonerakure ».\nProcédures spéciales établies par le Conseil des droits de l’homme\nCommunication sur le cas de Germain Rukuki"},{"id":"a-hrc-48-crp-1-p0032","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"32","seq":32,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Le 29 septembre 2020, la Rapporteuse spéciale sur la situation des défenseurs des droits de l’homme, le Groupe de travail sur la détention arbitraire, la Rapporteuse spéciale sur la promotion et la protection du droit à la liberté d’opinion et d’expression, le Rapporteur spécial sur le droit de réunion pacifique et la liberté d’association, et le Rapporteur spécial sur l’indépendance des juges et des avocats, ont envoyé une lettre conjointe au Gouvernement du Burundi dans laquelle ils ont fait part d’allégations d’irrégularités de procédure concernant la condamnation du défenseur des droits de l’homme Germain Rukuki à une peine de 32 ans de prison par le tribunal de grande instance de Ntahangwa. Ils ont regretté le manque de coopération de la part des autorités burundaises qui n’ont pas répondu à leurs communications antérieures sur ce cas ni donné suite à l’avis du Groupe de travail sur la détention arbitraire demandant sa libération immédiate en raison du caractère arbitraire de sa détention."},{"id":"a-hrc-48-crp-1-p0033","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"33","seq":33,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Prenant note de la décision de la Cour suprême du 30 juillet 2020 de casser l’arrêt de la cour d’appel de Ntahangwa du 17 juillet 2019 en raison d’irrégularités constatées dans les procédures, et du fait que Germain Rukuki allait être rejugé une seconde fois en appel, les titulaires de mandat au titre des procédures spéciales ont demandé au Gouvernement du Burundi, entre autres choses, de leur fournir dans un délai de 60 jours : toute information concernant les irrégularités procédurales que la Cour suprême a identifiées ; et toute information sur les mesures mises en place pour veiller à ce que les défenseurs des droits de l’homme au Burundi et leurs associations, puissent opérer dans un environnement sûr et favorable et mener leurs activités légitimes sans crainte d'intimidation ou de harcèlement d'aucune sorte. Au 10 septembre 2021, le Gouvernement du Burundi n’avait pas répondu à la communication des procédures spéciales.\nCommunication sur les allégations de violations commises à l’encontre de réfugiés burundais en Tanzanie"},{"id":"a-hrc-48-crp-1-p0034","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"34","seq":34,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Le 1er mars 2021, le Groupe de travail sur les disparitions forcées ou involontaires, le Groupe de travail sur la détention arbitraire, la Rapporteuse spéciale sur les exécutions extrajudiciaires, sommaires ou arbitraires, et le Rapporteur spécial sur la torture et autres peines ou traitements cruels, inhumains ou dégradants, ont envoyé une lettre au Gouvernement du Burundi faisant état d’allégations reçues concernant des violations graves commises contre des réfugiés burundais en Tanzanie et certains réfugiés burundais rapatriés de force au Burundi."},{"id":"a-hrc-48-crp-1-p0035","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"35","seq":35,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Les représentants des procédures spéciales ont fait état d’allégations « de disparitions forcées, de torture, de retours forcés et d’intimidation à l’encontre des réfugiés burundais. La police et les services de renseignement tanzaniens, en coopération avec les services de renseignement burundais, auraient procédé à des arrestations arbitraires et des disparitions forcées des réfugiés burundais dont certains auraient été tués ou soumis à la torture avant d'être refoulés ou contraints de signer pour un « retour volontaire ». Par exemple, selon une source, 90 réfugiés auraient disparu entre les mains des forces de sécurité tanzaniennes, tandis que 140 réfugiés auraient été victimes de détention arbitraire, de torture et d'autres violations entre 2017 et 2020. Selon une autre source, « entre octobre 2019 et août 2020, les services de police et de renseignement tanzaniens auraient fait disparaître par la force, torturé et détenu arbitrairement au moins 11 Burundais pendant une période pouvant aller jusqu'à plusieurs semaines dans des conditions dégradantes dans un commissariat de police de Kibondo, dans la région de Kigoma. Trois ont été libérés en Tanzanie, tandis que les huit autres réfugiés auraient été renvoyés de force au Burundi en août 2020, où ils auraient été détenus sans aucune charge. Depuis janvier 2020, la police tanzanienne aurait arrêté et fait disparaître de force sept autres réfugiés et demandeurs d'asile. Les arrestations auraient eu lieu dans les camps de réfugiés de Mtendeli et Nduta dans la région de Kigoma, près de la frontière avec le Burundi »."},{"id":"a-hrc-48-crp-1-p0036","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"36","seq":36,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Les experts indépendants ont également dénoncé la dégradation de la situation sécuritaire dans les camps de réfugiés en raison de la présence d’agents de renseignement burundais se faisant passer pour des réfugiés afin d’identifier des individus spécifiques qui sont ensuite arrêtés par les forces de sécurité tanzaniennes."},{"id":"a-hrc-48-crp-1-p0037","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"37","seq":37,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Le 7 avril 2021, le Gouvernement du Burundi a envoyé une communication en réponse aux experts indépendants dans laquelle il n’adresse pas les nombreuses questions et demandes d’informations complémentaires qui lui avaient été adressées. Il affirme seulement que les allégations présentées sont « mensongères et sans fondement légal » et que celles-ci sont initiées depuis 2015 par « des ennemis de la démocratie », que « les accusations rapportées par les experts sont fausses et comme toujours politiquement motivées, visant à ternir l’image du Burundi ». Il a finalement déclaré que « les groupes de travail, qui n’ont plus de raison d’être, devraient être suspendus ».\nLe Groupe de travail sur la détention arbitraire"},{"id":"a-hrc-48-crp-1-p0038","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"38","seq":38,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Au cours de la période couverte par le présent document, le Groupe de travail sur la détention arbitraire a adopté quatre avis concernant le Burundi : trois lors de sa 88ième session tenue du 24 au 28 août 2020, et un avis lors de sa 90ième session organisée du 3 au 12 mai 2021. Le Groupe de travail a conclu que les quatre cas qui lui avaient été soumis, qui concernent cinq personnes, étaient constitutifs de détention arbitraire. Le Gouvernement du Burundi a refusé de coopérer avec le Groupe de travail. Il n’a pas répondu aux demandes d’informations détaillées sur les cas en question et sur les dispositions juridiques pertinentes en droit burundais et leur compatibilité avec les obligations du Burundi en vertu du droit international des droits de l’homme."},{"id":"a-hrc-48-crp-1-p0039","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"39","seq":39,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Le premier cas concerne la détention de Jean-Claude Hamenyimana, commerçant burundais, arrêté le 19 janvier 2016 à son domicile en Mairie de Bujumbura par des policiers de l’Appui à la protection des institutions et de la Brigade de recherche et d’intervention judiciaire. M. Hamenyimana a été arrêté sans mandat d’arrêt et sans qu’il soit dûment informé des raisons de sa privation de liberté au moment de son arrestation. Le 23 août 2016, la cour d’appel de Mukaza a accepté sa demande de mise en liberté provisoire qui avait été initialement rejetée en février 2016 par le tribunal de grande instance de Ntahangwa. Cependant, cette décision de la cour d’appel n’a pas été exécutée et M. Hamenyimana est resté détenu à titre préventif jusqu’à son procès. Inculpé d’atteinte à la sûreté intérieure de l’État, il a été acquitté le 8 août 2017 par le tribunal de grande instance de Mukaza, mais il n’a été remis en liberté qu’en date du 2 mai 2019, soit près de deux ans après son acquittement. De plus, il n’avait pas eu accès à un avocat lors des premières étapes de la procédure judiciaire et il avait été torturé lors de son interrogatoire par le Service national de renseignement où des menaces et des insultes à caractère ethnique avaient été proférées contre lui. Le Groupe de travail a donc conclu que sa détention avait été arbitraire car son arrestation et sa détention étaient dépourvues de fondement juridique ; parce que les violations des normes internationales relatives au droit à un procès équitable étaient d’une gravité telle qu’elles ont rendu la privation de liberté arbitraire ; et enfin parce que la privation de liberté constituait une violation du droit international pour des raisons de discrimination fondée sur son origine ethnique."},{"id":"a-hrc-48-crp-1-p0040","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"40","seq":40,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Le deuxième avis concerne les cas d’Ernest Nyabenda et de Patrick Nsengiyumva, deux militaires ex-FABs, qui ont été arrêtés respectivement le 2 août et le 8 août 2015 suite à l’assassinat du Général Adolphe Nshimirimana, un des caciques du régime du feu Président Nkurunziza, le 2 août 2015. Ils ont été détenus au Service national de renseignement (SNR) au-delà des délais légaux de garde à vue et des mandats d’arrêt ont été préparés seulement le 4 septembre 2015 lorsqu’ils ont été transférés à la prison de Gitega. Ils n’ont été présentés à la chambre du conseil qu’en novembre 2015 et ils n’ont pas eu accès à un avocat lors de la procédure judiciaire ouverte contre eux. Entre mai et décembre 2016, quatre audiences ont été organisées dans le cadre de leur procès, mais celui-ci a depuis été reporté sine die suite à la demande du ministère public d’obtenir un délai pour faire comparaître les témoins à charge une fois que ces derniers auraient trouvé une protection adéquate. M. Nyabenda et Nsengiyumva sont donc détenus « provisoirement » depuis 2015 sans qu’aucune démarche judicaire n’ait été entreprise depuis décembre 2016. Le Groupe de travail a considéré que leur détention était arbitraire en raison du défaut de fondement juridique de leur arrestation et détention ; parce que les violations du droit à un procès équitable, notamment le droit d’être jugé sans retard excessif, étaient d’une gravité telle qu’elles ont rendu leur privation de liberté arbitraire ; et également car leur arrestation et leur détention étaient le résultat d’une discrimination ethnique et politique, du fait qu’ils ont été arrêtés et détenus uniquement parce qu’ils étaient des militaires qui avaient été membres de l’ancienne armée régulière à majorité tutsie."},{"id":"a-hrc-48-crp-1-p0041","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"41","seq":41,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Le troisième avis concerne Cadeau Bigirumugisha, un militaire ex-FAB, arrêté le 10 août 2015 suite à l’assassinat du Général Adolphe Nshimirimana. Arrêté sans mandat et sans être informé des motifs de son arrestation, il a été conduit au siège du Service national de renseignement après avoir passé six jours dans les locaux de la police militaire. Il a été présenté devant la chambre du conseil seulement en novembre 2015 et la première audience de son procès a eu lieu en juillet 2016. Trois autres audiences ont eu lieu entre juillet et le 27 décembre 2016, date à laquelle le procès a été reporté sine die suite à la demande du ministère public d’obtenir un délai pour faire comparaître les témoins à charge une fois que ces derniers auraient trouvé une protection adéquate. Il n’a pas eu accès à un avocat pendant toute la procédure judiciaire. M. Bigirumugisha est détenu « provisoirement » depuis son arrestation en août 2015 sans qu’aucune démarche judicaire n’ait été entreprise depuis décembre 2016. Le Groupe de travail a considéré que sa détention était arbitraire en raison du défaut de fondement juridique de son arrestation et de sa détention ; parce que les violations du droit à un procès équitable, notamment le droit d’être jugé sans retard excessif, étaient d’une gravité telle qu’elles ont rendu leur privation de liberté arbitraire ; et également parce que son arrestation et sa détention étaient le résultat d’une discrimination ethnique et politique, du fait qu’il a été arrêté et détenu parce qu’il était un militaire qui avait été membre de l’ancienne armée régulière à majorité tutsie."},{"id":"a-hrc-48-crp-1-p0042","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"42","seq":42,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Le quatrième avis concerne la détention de Philibert Niyonkuru, un militaire ex-FABs qui était devenu policier, lui aussi détenu « à titre provisoire » depuis son arrestation le 18 août 2015. M. Niyonkuru a été arrêté et interrogé sans avocat par le Service national de renseignement dans le cadre de l’enquête sur l’assassinat du Général Adolphe Nshimirimana. Le 16 septembre 2015, il a été interrogé, toujours sans avocat, par un magistrat du parquet de la République et un mandat a été délivré en date du 30 septembre 2015. Après cette date, M. Niyonkuru a été transféré à la prison de Gitega. En novembre 2015, la chambre de conseil a confirmé sa détention provisoire. Le 6 mai 2016, il aurait été présenté au juge du fond, sans être assisté par un avocat et sans que le ministère public présente de témoins. D’autres audiences ont été organisées le 1er août et ensuite le 11 octobre 2016, date à laquelle l’affaire a été mise en délibéré. Un mois plus tard, le tribunal aurait rouvert les débats pour permettre au ministère public de faire un complément d’enquête. Le 27 décembre 2016, une audience a été organisée et le ministère public a révélé que ses témoins n’avaient pas pu comparaître en raison d’un manque de protection, et l’affaire a été renvoyée sine die. Depuis ce jour aucune audience n’a été programmée et M. Niyonkuru reste détenu à titre provisoire."},{"id":"a-hrc-48-crp-1-p0043","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"43","seq":43,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Le Groupe de travail a également considéré que cette détention était arbitraire en raison du défaut de fondement juridique de son arrestation et de sa détention ; parce que les violations du droit à un procès équitable, notamment le droit d’être jugé sans retard excessif, étaient d’une gravité telle qu’elles ont rendu sa privation de liberté arbitraire ; et également parce que son arrestation et sa détention étaient le résultat d’une discrimination ethnique et politique, du fait qu’il a été arrêté et détenu parce qu’il avait été militaire au sein de l’ancienne armée régulière à majorité tutsie.\nLe Groupe de travail sur les disparitions forcées ou involontaires"},{"id":"a-hrc-48-crp-1-p0044","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"44","seq":44,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Au cours de sa 123ième session tenue du 15 au 19 février 2021, le Groupe de travail sur les disparitions forcées ou involontaires a décidé de porter 12 cas de disparition forcée nouvellement signalés à l’attention du Burundi, qui concernent :\n(a)\tArmel Banteyakandi, enlevé le 8 septembre 2018 devant chez lui et en présence de témoins par deux policiers ;\n(b)\tJospin Keen Iradukunda, arrêté en février 2016 à Nyakabiga I, 10ème avenue, commune Mukaza, Bujumbura Mairie, par des agents du SNR ;\n(c)\tPierre Claver Habarugira, enlevé chez lui le 4 octobre 2015 par des individus en uniforme de police ;\n(d)\tElvis Irakoze, arrêté par des policiers le 11 décembre 2015 vers 23h00 dans un bar près de chez lui à Kinanira, à côté du dispensaire MUSALAC, Bujumbura Mairie ;\n(e)\tIsmaïl Bandushubwenge, qui a été vu pour la dernière fois le 10 décembre 2015 sur la 1ère avenue, zone Musaga, Bujumbura Mairie ;\n(f)\tJean Paul Nintunze, qui a été vu pour la dernière fois le 5 juillet 2018, vers 15h00, alors qu’il s’entraînait près du camp Gihofi (521ième bataillon) où il était militaire ;\n(g)\tNestor Ndayizeye, arrêté par des agents du SNR le 20 décembre 2015 dans la commune Bugabira, province Kirundo ;\n(h)\tElie Bizimana, arrêté le 4 mars 2020 dans la commune Tenga-Gahwama, zone Rubrizi, commune Mutimbuzi, province Bujumbura (rural), par le chef du SNR de la commune Mutimbuzi ;\n(i)\tIsaïe Batumunwa, enlevé par des agents du SNR le 22 juillet 2019 à 7h00 alors qu’il était en route vers le marché de Nyeshenza ;\n(j)\tJean Claude Hakizimana, arrêté le 26 février 2020 vers 20h00 dans la commune Gihanga, par le chef des Imbonerakure de cette commune ;\n(k)\tEgide Mpawenimana, enlevé le 9 juillet 2019 près du pont qui traverse la rivière Rusizi dans la commune Mutimbuzi, par le chef du SNR de cette commune ;\n(l)\tJérémie Ndayitwayeko, arrêté le 13 mai 2019 vers midi dans la commune Muyange par le chef du SNR de la province de Bujumbura (rural), qui était accompagné par le chef du SNR de la commune Mutimbuzi."},{"id":"a-hrc-48-crp-1-p0045","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"45","seq":45,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Ce sont donc 168 cas de disparitions forcées et involontaires qui ont été transmis officiellement aux autorités burundaises depuis 2016 par le Groupe de travail, pour un total de 250 cas de disparitions forcées concernant le Burundi qui demeurent ouverts en l’absence d’informations transmises notamment par le Gouvernement afin de les élucider."},{"id":"a-hrc-48-crp-1-p0046","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"46","seq":46,"section":"1. Au sein de l’Organisation des Nations Unies","text":"La Commission d’enquête est donc particulièrement surprise par les propos du Président Ndayishimiye au sujet des disparitions forcées lors de son entretien avec RFI en date du 14 juillet 2021. Il a en effet déclaré qu’à sa connaissance « il n’y a pas de disparitions au Burundi. Sinon, vous me diriez : \"Telle personne est disparue\" », alors que le Gouvernement du Burundi a été formellement notifié d’au moins 250 cas de personnes disparues et informé de leurs noms et des détails concernant la date et les circonstances de leur disparition afin qu’il ouvre des enquêtes sur ces cas.\nConseil de sécurité des Nations Unies"},{"id":"a-hrc-48-crp-1-p0047","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"47","seq":47,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Le 4 décembre 2020, le Conseil de sécurité a décidé de retirer le Burundi de son programme de travail et de discontinuer la demande faite dans sa résolution 2303 (2016) d’examiner régulièrement la situation au Burundi.. Il a néanmoins demandé à ce que le Burundi soit couvert dans le cadre des rapports réguliers du Secrétaire général sur la région des Grands Lacs et l’Afrique centrale. Depuis 2019, les séances du Conseil afin d’examiner la situation au Burundi n’avaient pu être organisées que de manière irrégulière ou ad hoc, en raison notamment de l’opposition du Burundi."},{"id":"a-hrc-48-crp-1-p0048","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"48","seq":48,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Le Conseil de sécurité a officiellement basé sa décision sur « l’amélioration des conditions de sécurité au Burundi [...] à la suite d’élections qui se sont déroulées de façon globalement pacifique [...] Il se félicite des mesures prises pour lutter contre l’impunité ainsi que des progrès réalisés concernant certains aspects de l’égalité des genres et de l’autonomisation des femmes et encourage le Gouvernement burundais à redoubler d’efforts dans ces domaines »."},{"id":"a-hrc-48-crp-1-p0049","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"49","seq":49,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Cependant, le Conseil « constate les progrès réalisés jusqu’à présent et souligne qu’il reste encore beaucoup à accomplir pour faire avancer la réconciliation nationale, la promotion de l’état de droit et d’un système judiciaire indépendant et efficace, la préservation de l’espace démocratique et le respect des libertés fondamentales, telles que la liberté d’expression, y compris pour les membres de la presse et les acteurs de la société civile, la consolidation de la paix, la cohésion sociale et le développement ». Il note également « que les violations des droits humains et les atteintes à ces droits continuent de soulever des préoccupations » mais il se contente à cet égard de « demander au Gouvernement burundais de faire en sorte qu’il soit mis fin à ces violations et atteintes et de tenir les auteurs responsables de leurs actes ». Finalement, le Conseil « exhorte le Gouvernement burundais à coopérer avec l’ONU pour surmonter ces problèmes (…) et prend note du rapport du Secrétaire général sur la mission d’évaluation stratégique concernant les activités des Nations Unies au Burundi compte tenu de ses recommandations pertinentes »."},{"id":"a-hrc-48-crp-1-p0050","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"50","seq":50,"section":"1. Au sein de l’Organisation des Nations Unies","text":"En effet, le 2 novembre 2020, le Secrétaire général des Nations Unies avait envoyé au Conseil de sécurité son rapport sur la situation au Burundi, qui avait été préparé à la demande du Conseil et rédigé suite à la mission d’évaluation stratégique au Burundi qui s’était déroulée du 14 au 19 septembre 2020 et qui était dirigée conjointement par l’Envoyé spécial du Secrétaire-général pour la région des Grands Lacs, Huang Xia, et la Sous-Secrétaire générale pour l’Afrique, Bintou Keita."},{"id":"a-hrc-48-crp-1-p0051","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"51","seq":51,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Dans sa lettre qui transmettait son rapport au Président du Conseil, le Secrétaire général avait souligné qu’il existait « une volonté forte et réelle d’opérer un changement positif » au Burundi, et le fait que la « communauté internationale a la possibilité d’aider le Gouvernement et le peuple burundais à tirer parti de cette dynamique, en les assistant activement dans la transformation souhaitée par le pays, tout en facilitant la réconciliation, la mise en place d’un système politique inclusif et la promotion des droits humains et des libertés fondamentales pour tous les Burundais et Burundaises. La disposition du Président Ndayishimiye et du Gouvernement burundais à collaborer avec les acteurs régionaux et internationaux, dans un esprit de respect mutuel et de partenariat, est louable »."},{"id":"a-hrc-48-crp-1-p0052","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"52","seq":52,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Dans le rapport du Secrétaire général sur la mission d’évaluation stratégique, il était mentionné que « le processus électoral de 2020 a été considéré comme globalement pacifique, nonobstant quelques incidents de violence ouverte entre le parti au pouvoir et l’opposition ainsi que des allégations d’irrégularités. Les parties prenantes burundaises consultées durant la mission d’évaluation stratégique ont fait savoir qu’elles acceptaient le résultat des élections et affirmé leur volonté d’aller de l’avant et de donner au Gouvernement une chance d’honorer ses promesses électorales ». Le parti CNL avait toutefois réfuté avoir reconnu et accepté le résultat des élections de 2020 comme il a été indiqué dans le rapport."},{"id":"a-hrc-48-crp-1-p0053","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"53","seq":53,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Le Secrétaire général avait néanmoins souligné que « la situation demeure fragile. Certaines parties prenantes ont fait part de leur préoccupation face au contrôle écrasant exercé par le parti au pouvoir ». D’autres préoccupations avaient également été relevées, telles que la militarisation du régime avec la nomination de nombreux militaires à des postes clefs, ainsi que le refus du Gouvernement d’engager le dialogue sur le possible retour de Burundais en exil considérés par le pouvoir comme des criminels. De même, l’absence de solution à long terme des problèmes de paix et de sécurité, y compris au niveau régional, et « la méfiance persistante et généralisée qui règne parmi les citoyennes et citoyens et les communautés, ainsi qu’entre l’opposition et le Gouvernement » avaient été relevées."},{"id":"a-hrc-48-crp-1-p0054","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"54","seq":54,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Le Secrétaire général avait également noté que « le Gouvernement a déclaré que les membres des Imbonerakure n’étaient pas armés, ne constituaient pas une menace pour la paix et la sécurité et étaient pleinement déterminés à soutenir les efforts de développement national ». Il avait également relevé que le Gouvernement burundais minimisait l’importance des incidents impliquant des groupes armés et notamment les affrontements entre ceux-ci et les forces de sécurité ou les attaques contre des civils, les qualifiant de simples activités criminelles par des groupes de bandits."},{"id":"a-hrc-48-crp-1-p0055","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"55","seq":55,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Dans le rapport du Secrétaire général sur la mise en œuvre de l’Accord-cadre pour la paix, la sécurité et la coopération pour la République démocratique du Congo et la région, publié le 30 mars 2021, il est simplement fait état au sujet du Burundi de certains incidents de sécurité transfrontaliers ayant eu lieu depuis septembre 2020 ainsi que de la libération des journalistes d’Iwacu le 24 décembre 2020.\nCommission de consolidation de la paix"},{"id":"a-hrc-48-crp-1-p0056","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"56","seq":56,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Le 17 mars 2021, la Commission de consolidation de la paix a tenu une réunion virtuelle sur le Burundi au cours de laquelle il a été expliqué que le Burundi avait choisi de poursuivre son engagement avec cette Commission afin de mobiliser la communauté internationale à soutenir les priorités du Gouvernement du Burundi. Il a été rappelé que le Fonds pour la consolidation de la paix a versé 86 millions de dollars américains pour financer des projets de renforcement de l’État de droit, de la justice et du secteur de la sécurité, et des droits de l’homme mais aussi pour la résolution des conflits fonciers, soutenir le retour des rapatriés et leurs communautés d’accueil, ainsi que les activités visant à favoriser le dialogue et la cohésion sociale au niveau local. Il a été annoncé également qu’une évaluation indépendante des actions et projets soutenus par le Fonds entre 2014 et 2020 serait conduite afin de mesurer leur impact et guider les prochains investissements, notamment ceux en faveur des femmes et des jeunes.\nBureau de l’Envoyé spécial du Secrétaire général pour le Burundi"},{"id":"a-hrc-48-crp-1-p0057","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"57","seq":57,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Dans son rapport sur la situation au Burundi, le Secrétaire général des Nations Unies avait indiqué que le Président et le ministre des Affaires étrangères lui avaient assuré que « le Gouvernement était prêt à s’engager, dès que possible, dans un dialogue constructif sur l’avenir du Bureau de l’Envoyé(e) spécial(e) pour le Burundi ». Le Secrétaire général avait d’ailleurs recommandé que ce Bureau reste ouvert jusqu’au 31 décembre 2021 afin de préparer la transition vers une nouvelle présence qui « pourrait également encourager et soutenir, le cas échéant, un véritable dialogue sur les questions clés entre les autorités et les représentantes et représentants des groupes d’opposition, l’opposition interne et les membres de la diaspora, y compris celles et ceux qui sont en exil, ainsi que les dirigeantes et dirigeants de la société civile, en mettant l’accent sur la recherche d’un consensus pour la pérennisation de la paix, par la promotion de la réconciliation, de la cohésion nationale et de la construction et de la consolidation de la paix ». Cependant, le 17 novembre 2020, le Gouvernement du Burundi a notifié le Secrétaire général que le Bureau de l’Envoyé spécial serait formellement fermé et liquidé au 31 décembre 2020, en raison notamment de la paix et de la sécurité qui régnaient dans le pays."},{"id":"a-hrc-48-crp-1-p0058","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"58","seq":58,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Le 24 novembre 2020, l’Envoyé spécial du Secrétaire général pour les Grands Lacs a fait part au Président Ndayishimiye de la requête du Secrétaire général d’accorder à l’ONU un délai de 9 à 12 mois pour effectuer les formalités administratives, logistiques et légales en rapport avec la fermeture et la liquidation du Bureau, telles que la résiliation des contrats du personnel local et international, le paiement des fournisseurs et l’épuration d’autres obligations financières. Le Président du Burundi « a fait savoir qu’il marquait son accord, du moment que les deux parties comprennent de la même manière que ce Bureau doit être fermé et liquidé. Il a estimé toutefois que ce sont des questions techniques qui ne devraient pas poser de problème, les techniciens burundais étant appelés à travailler avec ceux de l’ONU pour déterminer les délais nécessaires pour ces formalités ainsi que le chronogramme »."},{"id":"a-hrc-48-crp-1-p0059","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"59","seq":59,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Ce Bureau a donc été officiellement fermé le 31 mai 2021. Au cours de la cérémonie marquant sa fermeture, le secrétaire permanent du ministère des Affaires étrangères du Burundi a déclaré que « la présence des Nations Unies à caractère exclusivement politique n’éta[i]t pas pertinente. Seule la présence des Nations Unies à caractère socio-économique à travers l’équipe pays pour accompagner le Burundi dans ses efforts de développement socio-économique est nécessaire »."},{"id":"a-hrc-48-crp-1-p0060","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"60","seq":60,"section":"1. Au sein de l’Organisation des Nations Unies","text":"Pour rappel, le Bureau de l’Envoyé spécial du Secrétaire général pour le Burundi avait été créé en 2015 pour apporter un appui au pays en matière de consolidation de la paix, notamment à travers ses bons offices, en appui au Gouvernement et au peuple burundais, et en coopération avec la Communauté d’Afrique de l’Est (CAE), l’Union africaine (UA) et d’autres partenaires. Le dernier Envoyé spécial, M. Kafando, avait démissionné le 30 octobre 2019 et il n’avait pas été remplacé."},{"id":"a-hrc-48-crp-1-p0061","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"61","seq":61,"section":"2. Au sein des instances régionales","text":"Le 27 avril 2021, le Conseil de paix et de sécurité de l’Union africaine s’est félicité « des progrès significatifs enregistrés dans la situation politique et sécuritaire au Burundi depuis le début de la crise en 2015 et, […] également de l’amélioration des relations entre le Burundi et ses voisins, ainsi qu'avec l’Union européenne et d'autres partenaires bilatéraux et multilatéraux ». Il a donc décidé « à la lumière des progrès significatifs accomplis et des développements positifs constatés au Burundi, de mettre fin au mandat de la Mission d’Observateurs des Droits de l’homme et d’Experts militaires de l’UA au Burundi, le 31 mai 2021 » et de retirer le Burundi de son ordre du jour.\nCommission africaine des droits de l’homme et des peuples"},{"id":"a-hrc-48-crp-1-p0062","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"62","seq":62,"section":"2. Au sein des instances régionales","text":"Le 15 décembre 2020, la Rapporteuse spéciale de la Commission africaine sur les réfugiés, les demandeurs d’asile, les déplacés internes et les migrants en Afrique a publié un communiqué dans lequel elle fait part de sa préoccupation quant à « la situation de réfugiés burundais en Tanzanie, dont le respect des droits fondamentaux tels que l’accès au droit d’asile et le principe de non refoulement seraient compromis ». Elle a notamment mentionné les rapports « faisant état de manœuvres d’intimidation à l’endroit des réfugiés burundais afin de les pousser à quitter le pays lui sont parvenus […] des menaces d’expulsions par le gouvernement tanzanien, la fermeture et la destruction des marchés dans les camps, l’imposition des restrictions à leurs activités commerciales, ainsi que l’accès aux différents services et la liberté de circuler, [et] […] des cas de disparations forcées dans certains camps de réfugiés burundais ». La Rapporteuse spéciale a également dénoncé « les pressions de plus en plus fortes que subissent les réfugiés burundais par les autorités tanzaniennes en vue de provoquer des départs forcés et/ou expulsions ».\nUnion européenne"},{"id":"a-hrc-48-crp-1-p0063","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"63","seq":63,"section":"2. Au sein des instances régionales","text":"Le 7 décembre 2020, le Président Ndayihimiye a officiellement renoué le dialogue au plus haut niveau avec l’Union européenne (UE) alors que celui-ci était au point mort depuis la prise de sanctions contre le Burundi par l’UE en mars 2016 en raison notamment de graves violations des droits de l’homme commises depuis avril 2015, conformément à l’article 96 de l’Accord de Cotonou. Le Président a reçu le Représentant de l’UE et les ambassadeurs des pays membres de l’UE ayant leur résidence à Bujumbura. Ces derniers ont promis de tout mettre en œuvre pour que l’UE puisse soutenir les efforts des institutions du Burundi pour le développement du pays, en se basant notamment sur les six priorités identifiées par le Président Ndayishimiye : la bonne gouvernance, la santé publique, l’éducation, l’agriculture et l’élevage, la gratuité des soins pour les retraités et le développement de la jeunesse."},{"id":"a-hrc-48-crp-1-p0064","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"64","seq":64,"section":"2. Au sein des instances régionales","text":"Le 2 février 2021, le Représentant de l’UE au Burundi, accompagné des ambassadeurs de l’Allemagne, la Belgique, la France, et les Pays-Bas, a poursuivi la reprise de dialogue politique au niveau technique, comme demandé par le Président Ndayishimiye, en participant à une réunion avec le ministre burundais des Affaires étrangères et de la Coopération au développement. Il s’agissait de mettre en place une feuille de route permettant de déboucher sur la normalisation des relations entre le Burundi et l’Union européenne et ses pays membres, et notamment la reprise de la coopération suspendue depuis mars 2016, y compris l’aide budgétaire directe."},{"id":"a-hrc-48-crp-1-p0065","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"65","seq":65,"section":"2. Au sein des instances régionales","text":"Le 5 février 2021, dans une lettre ouverte adressée au Haut-Représentant de l’Union européenne pour les affaires étrangères et la politique de sécurité, des députés européens ont souligné que les raisons qui avaient justifié la prise de sanctions en 2016, notamment les violations graves des droits de l’homme, n’avaient pas disparu. Selon eux, une reprise du dialogue en vue du rétablissement de la coopération dans le cadre de l’accord de Cotonou ne pouvait être envisagée tant que le Gouvernement burundais n’avait pas donné de preuves tangibles de sa volonté d’améliorer la situation des droits de l’homme dans le pays."},{"id":"a-hrc-48-crp-1-p0066","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"66","seq":66,"section":"2. Au sein des instances régionales","text":"Les rencontres entre les représentants de l’Union européenne et de ses pays membres au Burundi et le Gouvernement du Burundi se sont poursuivies à différents niveaux au premier semestre de 2021 afin de trouver un accord sur la reprise de la coopération. Du 24 avril au 4 mai 2021, le ministre des Affaires étrangères et de la Coopération au développement du Burundi s’est rendu en France, en Belgique et en Suisse afin de poursuivre le plaidoyer en faveur de la levée des sanctions de l’Union européenne."},{"id":"a-hrc-48-crp-1-p0067","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"67","seq":67,"section":"2. Au sein des instances régionales","text":"Le 21 juin 2021, l’Ambassadeur de l’Union européenne au Burundi a annoncé que le processus pour lever la suspension des aides financières directes au Gouvernement burundais était lancé. Il a précisé que la décision avait été prise à l’unanimité par les deux groupes de travail de l’UE mais qu’elle devrait encore être avalisée par le Conseil des ministres de l’UE, et que cette reprise des financements se ferait sans conditionnalité. Il a précisé que les aides financières de l’UE seraient destinées en priorité à des travaux de réaménagement du port de Bujumbura, et à soutenir des projets dans le secteur de l’agriculture, la santé, la protection de l’environnement et le changement climatique et l’accès à la justice."},{"id":"a-hrc-48-crp-1-p0068","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"68","seq":68,"section":"2. Au sein des instances régionales","text":"Le même jour, plusieurs ONGs internationales avaient publié une lettre ouverte à l’Union européenne pour lui demander de ne pas lever les sanctions contre le Burundi « en l’absence de progrès significatifs sur la situation des droits humains et sur l’impunité généralisée pour les atteintes graves aux droits humains passées et continues dans le pays ». Elles avaient notamment rappelé que la « matrice des engagements » établie en 2016, sur laquelle l’Union européenne attendait des progrès spécifiques et concrets de la part du Gouvernement burundais avant de lever les mesures, restait pertinente en l’absence de mesures prises par le Président Ndayishimiye dans ces domaines. Elles avaient finalement appelé l’Union européenne à, entre autres choses, « s’assurer que les engagements du Gouvernement burundais en matière de droits humains, y compris ceux de sa feuille de route, sont ambitieux, détaillés et exhaustifs, sont régulièrement surveillés grâce à un mécanisme de suivi rigoureux et font l’objet de discussions dans le cadre du dialogue politique avec l’UE ».\nSanctions ciblées contre des ressortissants burundais"},{"id":"a-hrc-48-crp-1-p0069","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"69","seq":69,"section":"2. Au sein des instances régionales","text":"Le 29 octobre 2020, le Conseil de l’Union européenne a prolongé jusqu'au 31 octobre 2021 les sanctions ciblées (interdiction de voyages et gels des avoirs) prises en 2015 à l'encontre de quatre personnes du Burundi et qui ont été renouvelées de manière régulière. Il s’agit de: Godefroid Bizimana (Chargé de mission à la Présidence de la République, ex-directeur général adjoint de la police), Gervais Ndirakobuca, alias « Ndakugarika » (ancien chef de cabinet de l’administration présidentielle chargé de la police nationale, ancien chef du SNR et actuel ministre de l’Intérieur, du Développement communautaire et de la Sécurité publique), Joseph Mathias Niyonzima, alias « Kazungu » (agent du SNR), et Léonard Ngendakumana (suspecté d’être impliqué dans la tentative de coup d’État de mai 2015). Le 11 novembre 2020, la Suisse a renouvelé les sanctions contre ces mêmes personnes qui avaient été décidées par l’ordonnance du 4 décembre 2015."},{"id":"a-hrc-48-crp-1-p0070","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"70","seq":70,"section":"2. Au sein des instances régionales","text":"Au 1er août 2021, les États-Unis d’Amérique maintenaient des sanctions ciblées (gel des avoirs, interdiction de voyager, mais également de réaliser des transactions commerciales avec les entreprises détenues par ces personnes) à l’encontre de 10 ressortissants burundais. Les sanctions initiales décidées par le Président Obama dans son ordre exécutif n° 73634 du 22 novembre 2015 concernaient : Alain Guillaume Bunyoni (ancien ministre de la Sécurité publique et actuel Premier ministre) ; Godefroid Niyombare (impliqué dans la tentative de coup d’État de mai 2015) et Godefroid Bizimana (ex-directeur général adjoint de la police nationale). Par la suite, d’autres personnes avaient été ajoutées par le Département du Trésor, qui a la compétence de le faire en consultation avec le Département d’État : Gervais Ndirakobuca, alias « Ndakugarika » (ancien chef de cabinet de l’administration présidentielle chargé de la police nationale, ancien chef du SNR et actuel ministre de de l’Intérieur, du Développement communautaire et de la Sécurité publique) ajouté en décembre 2015; Léonard Ngendakumana (officier) en décembre 2015 ; Joseph Mathias Niyonzima, alias « Kazungu » (agent du SNR) en décembre 2015 ; Alexis Sinduhije (président du parti politique d’opposition MSD) en décembre 2015 ; Edouard Nshimirimana (ancien lieutenant-colonel) en juin 2016 ; Ignace Sibomana (chef du renseignement militaire) en juin 2016 et Marius Ngendabanka (commandant de la première région militaire et chef adjoint des forces terrestres) en juin 2016. Cyrille Ndayirukiye (ancien ministre de la Défense), qui avait été visé par les sanctions initiales du 22 novembre 2015, est décédé en avril 2021 alors qu’il était détenu à la prison de Gitega après avoir été condamné à la perpétuité en janvier 2016 pour son implication dans le coup d’État raté de mai 2015.\nOrganisation internationale de la Francophonie"},{"id":"a-hrc-48-crp-1-p0071","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"71","seq":71,"section":"2. Au sein des instances régionales","text":"Lors de sa 112ème session tenue les 4 et 5 novembre 2020, le Conseil permanent de l’Organisation internationale de la Francophonie (OIF) a décidé de mettre fin à la suspension de la coopération multilatérale avec le Burundi qui avait été décidée en avril 2016 conformément à l’avis favorable qu’il avait déjà émis à ce sujet au cours de sa session de juillet 2020. Cette décision a été principalement basée sur la tenue des élections de 2020 et « les engagements pris par les nouvelles autorités en faveur du bien-être, de l’indépendance, de la sécurité quotidienne des Burundais, ainsi que de la garantie de leurs droits et de leurs libertés »."},{"id":"a-hrc-48-crp-1-p0072","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"72","seq":72,"section":"2. Au sein des instances régionales","text":"Le Conseil a demandé à la Secrétaire-générale de l’OIF « de poursuivre la mobilisation de la Francophonie, en lien avec ses partenaires, en faveur de la consolidation de la paix, du renforcement de la démocratie, de l’ouverture de l’espace politique, avec la participation de la société civile, de la protection des droits de l’homme et des libertés fondamentales, en particulier la liberté de la presse, ainsi que de l’égalité entre les femmes et les hommes ». Il a également proposé « qu’un rapport contenant des recommandations destinées à appuyer le Burundi dans cette direction lui soit présenté par la Secrétaire générale lors de sa prochaine session ». Finalement le Conseil a encouragé les autorités burundaises « à œuvrer à la construction d’un espace politique inclusif, à la consolidation de la stabilité politique, au renforcement de l’ouverture démocratique, de la démocratie, de l’État de droit et de l’égalité entre les femmes et les hommes, ainsi qu’à la protection des droits de l’homme, par l’adoption de mesures concrètes destinées à garantir les droits de l’homme et les libertés fondamentales des Burundais et à renforcer le climat de confiance ».\nAlliance mondiale des institutions nationales des droits de l’homme"},{"id":"a-hrc-48-crp-1-p0073","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"73","seq":73,"section":"2. Au sein des instances régionales","text":"En juin 2021, l’Alliance mondiale des institutions nationales des droits de l’homme (GANHRI) a doté à nouveau la Commission nationale des droits de l’homme du Burundi (CNIDH) de l’accréditation au statut A. De fait, la CNIDH est théoriquement censée fonctionner de manière indépendante. Dans son rapport, le sous-comité d’accréditation (SCA) s’est tout d’abord félicité « des efforts déployés par la CNIDH afin de promouvoir et de protéger les droits de l’homme dans le contexte difficile dans lequel elle opère ». Ensuite, le SCA a encouragé « la CNIDH à poursuivre ces efforts, et à renforcer son cadre institutionnel et son efficacité ». Il a également souligné que les Institutions nationales des droits de l’homme « qui ont été accréditées au statut A devraient prendre des mesures raisonnables visant à renforcer leur efficacité et leur indépendance, conformément aux Principes de Paris et aux recommandations formulées par le SCA au cours de cet examen ». Il a aussi indiqué que « pour fonctionner efficacement, une INDH [Institution nationale des droits de l’homme] doit obtenir un niveau suffisant de financement pour garantir son indépendance et sa capacité à déterminer librement ses priorités et ses activités ». Finalement, le SCA a encouragé « la CNIDH à poursuivre ses efforts en matière d’interaction avec le système international des droits de l’homme »."},{"id":"a-hrc-48-crp-1-p0074","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"74","seq":74,"section":"2. Au sein des instances régionales","text":"La Commission d’enquête note effectivement les efforts réalisés par la CNIDH pour adresser dans son rapport annuel de 2020 certains cas de torture et autres mauvais traitements, de détention arbitraire et de violations du droit à un procès équitable, mais aucun n’est lié au processus électoral ou n’a de dimension politique. De plus, la CNIDH n’a rapporté que quelques cas de violations mineures des droits civils et politiques dans le cadre du processus électoral, mais aucun cas de violation de droit à la vie, ni d’enlèvement ou de disparition forcée, ni de violation des libertés publiques. La Commission d’enquête émet donc des réserves sur de telles conclusions."},{"id":"a-hrc-48-crp-1-p0075","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"75","seq":75,"section":"2. Au sein des instances régionales","text":"La Commission d’enquête souligne cependant qu’au mois d’avril 2021, une délégation de la CNIDH a initié un contact avec elle, ce qui a permis à la Commission et à la CNIDH d’échanger sur leur travail respectif. La Commission espère que sa ré-accréditation encouragera la CNIDH à démontrer dans la pratique qu’elle est effectivement indépendante, notamment en s’occupant de tous les cas de violations, y compris les plus sensibles, et même si elle exerce sa mission dans un espace démocratique fermé qui nécessite plus que jamais une CNIDH indépendante et opérationnelle.\nCour pénale internationale"},{"id":"a-hrc-48-crp-1-p0076","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"76","seq":76,"section":"2. Au sein des instances régionales","text":"L’enquête ouverte le 25 octobre 2017 par le Procureur de la Cour pénale internationale sur les crimes contre l’humanité – notamment de meurtres, de tentatives de meurtre, d’emprisonnements ou d’autres formes de privation grave de liberté physique, de tortures, de viols, de disparitions forcées et de persécutions – commis au Burundi ou à l’extérieur du pays par des ressortissants burundais entre le 26 avril 2015 et le 26 octobre 2017 se poursuit."},{"id":"a-hrc-48-crp-1-p0077","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"77","seq":77,"section":"II. Situation des droits de l’homme au Burundi","text":"Depuis son établissement en 2016, la Commission a documenté au fil de ses rapports de nombreuses violations graves des droits de l’homme commises au Burundi depuis avril 2015, dont certaines constituent des crimes contre l’humanité. La Commission estime nécessaire de rappeler brièvement comment ces violations ont évolué au cours de cette période."},{"id":"a-hrc-48-crp-1-p0078","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"78","seq":78,"section":"II. Situation des droits de l’homme au Burundi","text":"Les principales violations des droits de l’homme sont globalement restées les mêmes : des cas d’exécution extrajudiciaire, d’arrestation et de détention arbitraires, de disparition forcée, de torture et de traitement cruel, inhumain ou dégradant, de violence sexuelle, ainsi que des violations des libertés publiques telles que les libertés d’expression, d’association, de réunion et de circulation. Des violations des droits économiques et sociaux ont également été constatées, notamment des cas de discrimination d’accès à l’emploi et à l’éducation sur la base de l’affiliation politique."},{"id":"a-hrc-48-crp-1-p0079","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"79","seq":79,"section":"II. Situation des droits de l’homme au Burundi","text":"C’est notamment le profil des victimes et des auteurs ainsi que les modes opératoires qui ont évolué en fonction des circonstances et des enjeux sur le terrain : tout d’abord la répression des manifestations contre le troisième mandat de Pierre Nkurunziza en 2015, la répression du coup d’État raté de mai 2015 et les attaques des camps militaires de décembre 2015, et ensuite l’organisation du référendum constitutionnel de mai 2018 et finalement le processus électoral de 2020 et la consolidation du pouvoir du Conseil national pour la défense de la démocratie-Forces pour la défense de la démocratie (CNDD-FDD)."},{"id":"a-hrc-48-crp-1-p0080","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"80","seq":80,"section":"1. Principales conclusions de la Commission d’enquête","text":"En 2015 et en 2016, les victimes étaient en majorité des jeunes hommes (à l’exception des victimes de violences sexuelles), qui avaient comme point commun d’être des opposants, réels ou perçus comme tels, au Gouvernement : manifestants contre la candidature du Président Nkurunziza à un troisième mandat lors de l’élection présidentielle de 2015 ; membres de partis politiques d’opposition (en particulier du parti Mouvement pour la solidarité et la démocratie (MSD) et du parti Forces nationales de libération (FNL)), ainsi que leurs proches ; membres des anciennes Forces armées burundaises (ex-FAB) ; membres de la société civile ; journalistes ; personnes soupçonnées d’avoir soutenu ou participé au coup d’État manqué de 2015 ; membres ou sympathisants de groupes armés d’opposition, ou personnes sur le chemin de l’exil suspectées de ce fait de rejoindre ces groupes. La Commission avait également constaté un phénomène d’embrigadement de la population au sein du parti au pouvoir, le CNDD-FDD, et de sa ligue des jeunes, les Imbonerakure.\nb)\t2017 - 2018"},{"id":"a-hrc-48-crp-1-p0081","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"81","seq":81,"section":"1. Principales conclusions de la Commission d’enquête","text":"Les victimes de ces violations étaient en majorité des opposants au Gouvernement et/ou au parti au pouvoir ou des personnes perçues comme tels : membres de partis politiques d’opposition (en particulier des FNL d’Agathon Rwasa et du MSD) ; sympathisants de groupes armés d’opposition ; Burundais tentant de fuir le pays et de ce fait suspectés de rejoindre ces groupes armés ; ou journalistes et membres d’organisations de la société civile. Le phénomène d’embrigadement de la population au sein du CNDD-FDD et des Imbonerakure s’était intensifié en prévision de la campagne pour la révision de la Constitution et durant celle-ci. Les Burundais, même apolitiques, refusant ou n’ayant pas pu s’inscrire sur les listes électorales, ainsi que ceux qui ne s’étaient pas acquittés de la contribution obligatoire pour financer les élections de 2020, avaient particulièrement été ciblés. La liberté d’expression s’était davantage restreinte puisque les principaux médias indépendants et les organisations de défense des droits de l’homme avaient été bannis.\nc)\t2018-2019"},{"id":"a-hrc-48-crp-1-p0082","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"82","seq":82,"section":"1. Principales conclusions de la Commission d’enquête","text":"Les principales violations des droits de l’homme avaient continué d’avoir une dimension politique et nombre d’entre elles avaient fait suite au référendum constitutionnel organisé en mai 2018 ou alors s’étaient inscrites dans le contexte de la préparation des élections de 2020. La majorité des victimes avait été ciblée en raison de l’alignement ou de l’appartenance, réelle ou supposée, à un autre parti politique que le CNDD-FDD. Les personnes qui avaient été actives au sein des mouvements ayant organisé la campagne pour le « non » au référendum constitutionnel avaient été particulièrement visées. Les membres du parti d’opposition créé par Agathon Rwasa, le Congrès national pour la liberté (CNL), et officiellement agréé le14 février 2019, avaient été victimes de nombreuses violations de leurs droits civils et politiques."},{"id":"a-hrc-48-crp-1-p0083","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"83","seq":83,"section":"1. Principales conclusions de la Commission d’enquête","text":"Des jeunes hommes accusés de soutenir ou d’appartenir aux groupes armés d’opposition, souvent en raison d’un séjour ou d’un déplacement à l’étranger, ou en lien avec leur implication, réelle ou supposée, dans la contestation contre le troisième mandat ou les incidents sécuritaires de 2015, avaient continué d’être spécifiquement visés."},{"id":"a-hrc-48-crp-1-p0084","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"84","seq":84,"section":"1. Principales conclusions de la Commission d’enquête","text":"Des personnes sans affiliation ou activité politique avaient été également ciblées pour avoir refusé de rejoindre le CNDD-FDD ou sa ligue des jeunes. De même, les personnes suspectées de ne pas vouloir suivre la ligne du Gouvernement et du CNDD-FDD, notamment pour soutenir la révision constitutionnelle, avaient également été visées, ainsi que celles qui n’avaient pas versé les diverses contributions financières exigées, principalement pour financer les élections de 2020, et même si cela était dû à un manque de moyens financiers."},{"id":"a-hrc-48-crp-1-p0085","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"85","seq":85,"section":"1. Principales conclusions de la Commission d’enquête","text":"Des membres de la famille ou des proches de personnes ciblées avaient également été victimes de violations, de manière délibérée ou suite à une erreur d’identité, ou encore par opportunisme, notamment lors d’attaques nocturnes de foyers au cours desquelles des femmes et des filles présentes avaient été victimes de violences sexuelles."},{"id":"a-hrc-48-crp-1-p0086","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"86","seq":86,"section":"1. Principales conclusions de la Commission d’enquête","text":"Des ressortissants burundais qui avaient pris refuge à l’étranger et étaient rentrés au Burundi, notamment dans le cadre du programme d’aide au retour volontaire établi en 2017, avaient été également ciblés. De manière plus générale, nombre d’entre eux, une fois arrivés sur leur colline d’origine, avaient fait face à une suspicion globale, voire une véritable hostilité de la part des autorités administratives locales et des Imbonerakure."},{"id":"a-hrc-48-crp-1-p0087","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"87","seq":87,"section":"1. Principales conclusions de la Commission d’enquête","text":"De nombreuses violations avaient eu lieu dans des zones rurales, au niveau des zones et des collines quadrillées par les Imbonerakure, qui cherchaient à contrôler la population dans son ensemble, particulièrement au niveau de la base, et contraindre son allégeance au CNDD-FDD. C’étaient donc principalement des gens modestes, voire pauvres, souvent des cultivateurs sans grands moyens ni beaucoup d’éducation qui avaient été visés à cette période alors qu’au début de la crise, la répression avait touché principalement des leaders politiques et des responsables de la société civile, y compris des défenseurs des droits de l’homme, des étudiants, qui résidaient en majorité dans la ville de Bujumbura. Les défenseurs des droits de l’homme et les journalistes sont restés des cibles du régime depuis 2015, même si beaucoup d’entre eux ont dû fuir le pays.\nd)\t2019-2020"},{"id":"a-hrc-48-crp-1-p0088","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"88","seq":88,"section":"1. Principales conclusions de la Commission d’enquête","text":"Les principales violations avaient eu lieu dans le contexte du processus électoral de 2020 qui avait commencé dès 2019, avec de nombreuses violations des libertés publiques, notamment la liberté de réunion pacifique et d’association, la liberté d’expression et d’information et celle de prendre part à la direction des affaires publiques, qui comprend le droit de voter librement et d’être élu. Les appels à la haine politique et/ou ethnique - dont certains constituaient une incitation à la discrimination, à l’hostilité ou à la violence, s’étaient multipliés durant cette période."},{"id":"a-hrc-48-crp-1-p0089","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"89","seq":89,"section":"1. Principales conclusions de la Commission d’enquête","text":"Les principales victimes avaient été les partis politiques d’opposition et leurs membres ainsi que des journalistes et des organes de presse indépendants. La population en général avait néanmoins continué de subir de manière régulière des violations des droits de l’homme et de vivre sous le contrôle étroit des Imbonerakure et des responsables administratifs locaux affiliés au parti au pouvoir.\ne)\tPrincipaux auteurs"},{"id":"a-hrc-48-crp-1-p0090","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"90","seq":90,"section":"1. Principales conclusions de la Commission d’enquête","text":"Dans un premier temps, les principaux auteurs avaient été des agents de la police, notamment de ses unités spécialisées de l’Appui à la protection des institutions (API) et les Groupes mobiles d’intervention rapide (GMIR), et du SNR, ainsi que des militaires. Cependant, ces derniers ont été plus rarement impliqués dans les cas de violation des droits de l’homme après 2016, lorsque la répression directe des manifestations de 2015, de la tentative du coup d’État de mai 2015 et des attaques des camps militaires de décembre 2015 s’est progressivement estompée."},{"id":"a-hrc-48-crp-1-p0091","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"91","seq":91,"section":"1. Principales conclusions de la Commission d’enquête","text":"En revanche, au fil des années, des Imbonerakure et des responsables administratifs locaux, agissant seuls ou conjointement avec des agents de police ou du SNR, ont été de plus en plus fréquemment impliqués dans les violations des droits de l’homme. Dans les cas d’arrestation et de détention arbitraires, en plus des agents de la police et du SNR qui en sont directement responsables, le personnel judiciaire et parfois pénitentiaire était également responsable des cas de détention arbitraire."},{"id":"a-hrc-48-crp-1-p0092","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"92","seq":92,"section":"2. Indices statistiques depuis 2015","text":"Plusieurs organisations indépendantes ont effectué chaque année des analyses quantitatives qui démontrent toute la dégradation incontestable de la situation des droits de l’homme depuis 2015, et ces indices statistiques corroborent parfaitement les constatations et les conclusions de la Commission d’enquête depuis le début de ses enquêtes. \na)\tLes libertés publiques"},{"id":"a-hrc-48-crp-1-p0093","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"93","seq":93,"section":"2. Indices statistiques depuis 2015","text":"Freedom House prépare annuellement un indice de la « liberté d’accès des populations à leurs droits politiques et aux libertés publiques » dans chaque pays. Selon le dernier indice disponible, le Burundi obtient pour l’année 2020 le score très faible de 14 points sur 100 (4 points sur 40 pour le respect des droits politiques et 10 points sur 60 pour celui des libertés publiques), ce qui le classe parmi les pays « non libres ». Le déclin du respect des droits politiques et des libertés publiques au Burundi depuis 2015 est clairement révélé par cet instrument.\nIndice des libertés publiques au Burundi de 2014 à 2020 de Freedom House\nb)\tLa liberté de la presse"},{"id":"a-hrc-48-crp-1-p0094","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"94","seq":94,"section":"2. Indices statistiques depuis 2015","text":"L’organisation Reporters sans frontières établit chaque année un classement de la situation de la liberté de la presse dans 180 pays et territoires en les ordonnant du plus respectueux de la liberté de la presse au pays le moins libre. Les performances du Burundi depuis 2015 dans ce domaine sont très claires, comme le démontre le tableau ci-dessous. Si le Burundi a gagné 13 places dans ce classement en 2021, cela est dû principalement à la libération des quatre journalistes du Groupe de presse Iwacu suite à la grâce présidentielle qui leur a été accordée.\nIndice de la liberté de la presse au Burundi de 2013 à 2021 de Reporters sans frontières\nc)\tLa corruption"},{"id":"a-hrc-48-crp-1-p0095","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"95","seq":95,"section":"2. Indices statistiques depuis 2015","text":"En ce qui concerne la corruption, l’indice de perception de la corruption publié annuellement par l’organisation Transparency international est significatif. Un score proche de zéro indique la prévalence de la corruption dans un pays, alors qu’un score proche de 100 témoigne de l’absence de corruption.\nIndice de la corruption au Burundi de 2013 à 2020 de Transparency International\nd)\tLa performance démocratique"},{"id":"a-hrc-48-crp-1-p0096","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"96","seq":96,"section":"2. Indices statistiques depuis 2015","text":"Le groupe de presse The Economist établit quant à lui un indice annuel de la performance démocratique. Le Burundi est considéré depuis 2013 comme un pays autoritaire – auparavant il était classé comme « régime hybride » – avec des scores de plus en plus faibles en matière de respect du pluralisme et de la participation politique, des libertés publiques et de la culture de tolérance politique.\nIndice de la performance démocratique du Burundi de 2013 à 2020 de The Economist\ne)\tLe développement humain"},{"id":"a-hrc-48-crp-1-p0097","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"97","seq":97,"section":"2. Indices statistiques depuis 2015","text":"L’indice du développement humain publié chaque année par le Programme des Nations Unies pour le développement (PNUD) indique que le Burundi est faiblement développé au niveau humain et qu’il affiche d’importants manquements dans la réalisation des droits économiques et sociaux qui affectent le niveau et la qualité de vie des Burundais. De plus, son évolution à cet égard tend plutôt vers la négative depuis 2015.\nIndice du développement humain au Burundi de 2014 à 2019 du PNUD\nf)\tLa gouvernance"},{"id":"a-hrc-48-crp-1-p0098","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"98","seq":98,"section":"2. Indices statistiques depuis 2015","text":"L’indice de gouvernance en Afrique préparé par la Fondation Mo Ibrahim sur la base de dizaines de sources indépendantes donne un aperçu objectif et global de l’état de la gouvernance au Burundi et de son évolution vers la négative au cours des dix dernières années, principalement à partir de 2015.\nIndice de gouvernance du Burundi de 2010 à 2019 de la Fondation Mo Ibrahim"},{"id":"a-hrc-48-crp-1-p0099","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"99","seq":99,"section":"2. Indices statistiques depuis 2015","text":"Cet indice de performance globale en matière de gouvernance, particulièrement significatif, repose sur 276 indicateurs regroupés sous quatre thèmes clefs : la sécurité et l’État de droit ; la participation, les droits et l’inclusion ; les fondements des opportunités économiques ; et le développement humain, auxquels viennent s’ajouter 45 indicateurs subjectifs de la perception de la performance en matière de gouvernance par la population. Cet indice global cache donc de très grandes disparités au niveau des tendances propres à chaque thème clef, dont le compte rendu exhaustif est disponible sur le site internet de la Fondation Mo Ibrahim."},{"id":"a-hrc-48-crp-1-p0100","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"100","seq":100,"section":"2. Indices statistiques depuis 2015","text":"Effectivement, entre 2010 et 2019, la sécurité et l’État de droit, la participation, les droits et l’inclusion ont reculé de manière significative alors que les bases des opportunités économiques et le développement humain ont stagné ou légèrement progressé. La crise politique de 2015 apparaît clairement comme un point de rupture.\nIndices des thèmes clefs de la gouvernance au Burundi de 2010 à 2019 de la Fondation Mo Ibrahim"},{"id":"a-hrc-48-crp-1-p0101","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"101","seq":101,"section":"2. Indices statistiques depuis 2015","text":"Au niveau de la sécurité et de l’État de droit, les indicateurs qui présentent des reculs particulièrement notables concernent : l’absence de violence contre les civils de la part du Gouvernement (-51,5 points) mais également de la part d’acteurs non étatiques (-81,3 points) ; l’indépendance du système judiciaire qui a reculé de 26 points en dix ans pour atteindre le score abyssal de 3,6 points (sur 100). Le contrôle institutionnel de l’action du Gouvernement a reculé (-25,9 points) tout comme celui informel par la société civile (-15,5 points). L’absence de sanctions contre des agents de l’État pour leurs fautes et abus de pouvoir est significative à cet égard (-28,6 points avec un faible score de 14,3 en 2019). De même, l’indicateur qui concerne les efforts de lutte contre le trafic d’êtres humains a reculé de 50 points pour devenir quasiment négligeable avec un score proche de zéro. La lutte contre la corruption apparaît comme globalement inexistante avec un score nul en matière d’enquêtes après un net recul de 25 points depuis 2015, et un faible score de 14,3 points pour ce qui est des politiques relatives à la lutte anti-corruption. Le seul élément positif à cet égard avait été la mise en place des institutions spécialisées de lutte contre la corruption (50 points sur 100), que le Gouvernement burundais déclare pourtant vouloir abolir."},{"id":"a-hrc-48-crp-1-p0102","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"102","seq":102,"section":"2. Indices statistiques depuis 2015","text":"En ce qui concerne la « participation, droits et inclusion », on relève que la liberté d’association s’est effondrée (-50 points), tout comme la liberté d’expression (-50 points) et la liberté de réunion (-25 points), pour devenir quasi inexistantes avec des scores de zéro point en 2019. On note également l’écroulement de l’impartialité des médias (-60,6 points) et de la liberté d’établissement et de fonctionnement des organisations de la société civile (-50,3 points ; avec un score de 2 sur 100 en 2019), ainsi que la hausse de l’absence de harcèlement des journalistes (-47,8 points ; avec un score de 5,8 sur 100 en 2019). La liberté des partis politiques a également fortement diminué (-29,6 points, avec un score de 4,7 points sur 100 en 2019). Le seul progrès remarquable est celui de la participation des femmes dans la vie politique (+24,5 points)."},{"id":"a-hrc-48-crp-1-p0103","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"103","seq":103,"section":"2. Indices statistiques depuis 2015","text":"Pour ce qui est des bases des opportunités économiques, on peut noter la performance négative de l’administration publique en matière d’état civil, de statistiques, de capacité fiscale, de mobilisation des recettes et de la gestion budgétaire, qui a globalement baissé de 7 points. La perte de l’indépendance du Bureau national des statiques (-25 points ; avec un score de zéro en 2019) est particulièrement marquante. La gestion budgétaire et financière du pays, qui requiert un budget complet et crédible lié aux priorités politiques, des systèmes de gestion financière efficaces et des rapports comptables et fiscaux opportuns et exacts est en net recul (-20,4 points). L’environnement global pour les affaires stagne (+2,3 points). En revanche, il y a eu des améliorations au niveau des infrastructures (+12,6 points)."},{"id":"a-hrc-48-crp-1-p0104","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"104","seq":104,"section":"2. Indices statistiques depuis 2015","text":"En ce qui concerne le développement humain : des progrès sont à souligner dans le domaine de la santé (+6,7 points) et de l’accès à l’eau potable (+6,5 points). L’égalité dans l’accès à l’éducation a augmenté (+11,6 points), principalement en ce qui concerne l’égalité de genre (+28,5 points). Le taux global de scolarisation a légèrement augmenté (+3,9 points). La protection sociale stagne à un niveau assez bas (-1,6 point ; avec un score de 35,6 points sur 100 en 2019) puisque les filets de protection sociale de base en cas de chômage, de situation de handicap, de pauvreté, de maladie ou de vieillesse ont baissé (-16,7 points), alors que les services et les politiques sociales en matière de santé et d’éducation augmentaient (+12,4 points). La protection de l’environnement a quant à elle progressé (+9,7 points)."},{"id":"a-hrc-48-crp-1-p0105","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"105","seq":105,"section":"B. Principales violations et situation de l’espace démocratique depuis juin 2020","text":"Des violations des droits de l’homme ont été commises depuis juin 2020, tout d’abord dans le cadre du processus électoral de 2020 comme l’avait constaté la Commission dans son rapport précédent. Une fois les élections terminées, les violations ont continué à une moindre échelle avant de connaître une recrudescence depuis juin 2021, principalement en lien avec les multiples incidents de sécurité qui ont eu lieu sur le territoire burundais. L’espace démocratique reste fermé avec un contrôle étroit exercé par les autorités sur les médias et la société civile malgré certains gestes symboliques isolés d’ouverture posés par le Président Ndayishimiye pour donner des gages à la communauté internationale que la situation serait en train de changer dans le pays. Cependant, de tels gestes ne sont pas de nature structurelle et ne peuvent donc pas continuer à améliorer durablement et en profondeur la situation des droits de l’homme."},{"id":"a-hrc-48-crp-1-p0106","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"106","seq":106,"section":"B. Principales violations et situation de l’espace démocratique depuis juin 2020","text":"La Commission a constaté que des violations des droits de l’homme commises depuis l’investiture du Président Ndayishimiye ont visé principalement des membres de partis d’opposition, des personnes soupçonnées d’être impliquées dans les attaques armées ou de collaborer avec des groupes armés, mais aussi dans une moindre mesure, des rapatriés et la population burundaise en général. Des agents du SNR, placés sous la responsabilité directe du Président Ndayishimiye, ont été les principaux auteurs des cas d’exécution, disparition forcée, arrestation et détention arbitraires et torture en lien avec les attaques armées, ayant continué à agir en toute impunité. Des policiers, relevant notamment des Groupements mobiles d’intervention rapide (GMIR), et des Imbonerakure ont également été impliqués dans des cas d’exécution, d’arrestation et de torture. Le système judiciaire a continué à être utilisé comme un outil de cette répression, en validant et prolongeant les détentions arbitraires et aucune avancée significative n’a été enregistrée en matière de lutte contre l’impunité pour les violations passées. En outre, la population burundaise vit toujours dans une situation de grande pauvreté qui impacte négativement la jouissance de ses droits économiques et sociaux, notamment le droit à un niveau de vie suffisant, le droit à l’alimentation, le droit à la santé et le droit à l’éducation."},{"id":"a-hrc-48-crp-1-p0107","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"107","seq":107,"section":"B. Principales violations et situation de l’espace démocratique depuis juin 2020","text":"Par ailleurs, les autorités burundaises semblent toutefois avoir pris conscience, dans une certaine mesure, de plusieurs problèmes profonds qui ont un impact direct sur la situation des droits de l’homme dans le pays, notamment les dysfonctionnements du système judiciaire, la prévalence de la corruption à tous les niveaux, y compris au niveau de la justice. Certaines mesures ont été prises, mais elles ont tendance à être pernicieuses sur le long terme puisqu’elles consistent à renforcer le contrôle de l’Exécutif à tous les niveaux.\n1.\tViolations des droits de l’homme et atteintes à ceux-ci commises en lien avec les incidents de sécurité\na)\tMultiplication des incidents de sécurité"},{"id":"a-hrc-48-crp-1-p0108","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"108","seq":108,"section":"B. Principales violations et situation de l’espace démocratique depuis juin 2020","text":"À la fin du mois d’août 2020 et au début de septembre 2020, plusieurs incidents sécuritaires ont été signalés, notamment des affrontements armés et des échanges de tirs entre des membres des forces de sécurité, parfois appuyés d’Imbonerakure, et des membres de groupes armés – souvent non identifiés - mais aussi des attaques contre des civils par des groupes d’hommes armés non identifiés. De tels incidents ont été notamment enregistrés entre les 23 et 25 août 2020 dans la province Rumonge, le 28 août dans la province Bujumbura (rural), le 29 août dans la province Bubanza, le 30 août dans la province Bujumbura par des groupes armés d’opposition ou d’incidents de nature sécuritaire, se contentant de parler d’actes Bujumbura (rural), le 6 septembre dans la province Rumonge, les 11 et 12 septembre 2020 dans la province Rumonge, le 26 septembre dans la province Kayanza. Il y aurait eu des morts et des blessés, parmi les forces de l’ordre et de sécurité, les Imbonerakure, les membres des groupes armés mais aussi la population civile. Cependant, le 25 septembre 2020, lors d’une émission publique, le Chef de l’État a nié qu’il s’agissait d’attaques commises par des groupes rebelles et affirmé que ces incidents étaient commis par des malfaiteurs. De nouveaux affrontements armés auraient eu lieu le 21 et le 28 novembre 2020, le 5 décembre 2020 et les 2, 9 et 16 janvier 2021 et des attaques contre les populations civiles ont été rapportées aux dates des 10, 17, 24 et 31 octobre 2020, 7, 14 et 28 novembre 2020, 26 décembre 2020 et 23 janvier 2021."},{"id":"a-hrc-48-crp-1-p0109","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"109","seq":109,"section":"B. Principales violations et situation de l’espace démocratique depuis juin 2020","text":"Des attaques ciblées visant notamment des membres du parti au pouvoir ou leurs proches ont été commises : le 4 avril 2021, une bande d’hommes armés a attaqué le domicile du président du CNDD-FDD sur la colline Makamba, dans le chef-lieu de la province Mwaro, et a tué son fils de 15 ans et un domestique. Le 16 avril 2021, un groupe d’hommes armés a attaqué un bar situé dans la commune Rusaka, province Mwaro, causant la mort de sept personnes, dont le comptable communal, son épouse et leur fille, ainsi que le percepteur communal."},{"id":"a-hrc-48-crp-1-p0110","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"110","seq":110,"section":"B. Principales violations et situation de l’espace démocratique depuis juin 2020","text":"Par la suite, ce sont des attaques aveugles contre la population qui ont eu lieu : le 9 mai 2021, dans la province Muramvya, un convoi de véhicules circulant de Gitega vers Bujumbura a été attaqué par un groupe d’hommes armés qui a tiré de manière indiscriminée sur les passagers. Le bilan annoncé est très lourd avec au moins 10 personnes tuées, dont un haut gradé de l’armée qui avait servi dans la mission de l’Union africaine en Somalie et sa fille, ainsi qu’une dizaine de personnes blessées."},{"id":"a-hrc-48-crp-1-p0111","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"111","seq":111,"section":"B. Principales violations et situation de l’espace démocratique depuis juin 2020","text":"Le 25 mai 2021, vers 19h00, des grenades ont été lancées à plusieurs endroits très fréquentés de la ville de Bujumbura, notamment des parkings de bus. Ces attaques ont fait selon le bilan officiel deux morts et des dizaines de blessés, beaucoup plus selon des sources officieuses. Quelques jours plus tard, des grenades ont été lancées dans la province Muramvya faisant des blessés."},{"id":"a-hrc-48-crp-1-p0112","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"112","seq":112,"section":"B. Principales violations et situation de l’espace démocratique depuis juin 2020","text":"Le 28 juin 2021, vers 20h00, des minibus de transport en commun ont été attaqués par un groupe d’hommes armés qui avaient bloqué la route entre Bujumbura et Gitega au niveau de la commune Rutegama (province Muramvya). Ces derniers ont tiré sur les passagers et mis le feu aux véhicules. Le bilan officieux fait état d’une vingtaine de personnes tuées dont certaines ont été brûlées vives et un couple assassiné par le groupe armé lors de sa fuite."},{"id":"a-hrc-48-crp-1-p0113","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"113","seq":113,"section":"B. Principales violations et situation de l’espace démocratique depuis juin 2020","text":"Ainsi ce sont 537 incidents de sécurité, qui ont fait 410 victimes parmi la population civile mais également les forces de l’ordre et de sécurité, les Imbonerakure et les membres des groupes armés, qui ont été dénombrés entre le 18 juin 2020 (date d’investiture du Président Ndayishimiye) et le 30 juillet 2021. \nb)\tViolations des droits à la vie, à la liberté et à l’intégrité physique"},{"id":"a-hrc-48-crp-1-p0114","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"114","seq":114,"section":"B. Principales violations et situation de l’espace démocratique depuis juin 2020","text":"Les autorités burundaises ont qualifié certains incidents soit de simples actions par des groupes de criminels, soit d’actes de terrorisme. Elles auraient essayé de rechercher les personnes responsables, ce qui est tout à fait légitime. Cependant, pour ce faire, elles ont mené des opérations de traque à grande échelle qui ont notamment ciblé des membres du parti CNL et des ex-FABs. Ainsi, après une brève période d’accalmie à la fin du processus électoral, des violations graves des droits de l’homme ont recommencé et même augmenté de manière significative à partir du mois de juin 2021. Il s’agit principalement de violations du droit à la vie avec des disparitions forcées et des exécutions, de violations du droit à la liberté et à la sécurité avec des arrestations et des détentions arbitraires, et de violations du droit à ne pas être soumis à la torture et à de mauvais traitements, souvent commises de manière cumulative contre une même personne."},{"id":"a-hrc-48-crp-1-p0115","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"115","seq":115,"section":"B. Principales violations et situation de l’espace démocratique depuis juin 2020","text":"La Commission n’a pas pu déterminer si les soupçons des autorités quant à l’implication de ces personnes dans les attaques étaient fondés sur des preuves objectives ou seulement liés à leur appartenance politique ou leur profil ethnique, et donc relevant plutôt de la répression des opposants politiques. Elle souligne néanmoins que la lutte contre la criminalité et le terrorisme doit être menée dans le respect des droits de l’homme, notamment le droit à la vie, le droit à ne pas être torturé, les droits à la liberté et à la sécurité, le droit à un procès équitable et le droit à ne pas être discriminé en raison de ses origines ethniques ou son appartenance politique."},{"id":"a-hrc-48-crp-1-p0116","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"116","seq":116,"section":"B. Principales violations et situation de l’espace démocratique depuis juin 2020","text":"Les témoignages recueillis démontrent le mode opératoire bien établi de ces violations. Des membres du CNL, des ex-FABs ou des rapatriés ont été accusés de collaborer avec des rebelles, notamment de leur fournir un soutien logistique comme leur apporter de la nourriture, cacher des armes ou collecter et/ou leur transmettre des informations.\nUne personne a expliqué :\n« Il m’a demandé pourquoi j’avais acheté une provision anormale de nourriture. Il m’accusait de faire un stock pour des combattants. […] Je lui ai dit que j’avais une famille de [X] […], que cela faisait [X] personnes à la maison et que la ration n’était pas suffisante pour une semaine […] il n'y avait rien d'anormal dans cet approvisionnement »."},{"id":"a-hrc-48-crp-1-p0117","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"117","seq":117,"section":"B. Principales violations et situation de l’espace démocratique depuis juin 2020","text":"Ils ont été arrêtés, généralement sans mandat, par des policiers, notamment ceux relevant d’unités spéciales comme les GMIR, ou des agents du SNR, accompagnés ou non d’Imbonerakure, plus rarement des Imbonerakure seuls. Parfois, certains de leurs proches ont été également arrêtés, détenus et poursuivis à leur place ou pour complicité. Pendant leur détention et leur interrogatoire par le SNR, ils ont été souvent torturés et maltraités, y compris avec des violences à caractère sexuel, dans le but de les faire avouer ou révéler des informations sur les groupes rebelles et leurs opérations. Les tortures infligées auraient, dans deux cas, provoqué des blessures fatales aux victimes et ces décès n’auraient pas fait l’objet d’une enquête.\nUn témoin a raconté :\n« Le commissaire m’a dit : \"Écoute, je suis fatigué, ne me fatigue pas encore plus. Dis-moi la vérité. Dis-moi d’où tu viens et ce que tu viens faire ?\". Après il a appelé un policier de la documentation qui s’appelle [A]. Après, [A] m’a ligoté et sur ordre du commissaire et il a commencé à me frapper jusqu’à ce qu'il se fatigue […] Il m'a ligoté les mains derrière le dos avec une corde et il m’a menotté les jambes avec des menottes […] Ils m’ont gardé ligoté et menotté jusqu'au lendemain. […] J’ai des séquelles. […] les autres fois j'étais battu avec mes codétenus. […] Il m'a frappé sur la colonne vertébrale avec quelque chose qui est en plastique mais qui est pliable. Ça s'appelle une chicote je pense. […] Les paroles et accusations qui revenaient souvent en me frappant c’était d’avouer que je faisais partie d’un groupe armé, que j’étais parti en [X] pour mobiliser un groupe armé pour renverser le pouvoir, que j’essayais de renverser le pouvoir »."},{"id":"a-hrc-48-crp-1-p0118","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"118","seq":118,"section":"B. Principales violations et situation de l’espace démocratique depuis juin 2020","text":"Pendant cette période de détention par le SNR, ils ont été quasi systématiquement détenus incomunicado, privés d’accès à un avocat, et leurs proches ignoraient où ils se trouvaient, les autorités burundaises ne reconnaissant pas les détenir. Ces faits constituent de facto une situation de disparition forcée puisque la personne est placée en dehors de la protection de la loi, même si cela n’est que de manière temporaire. Parfois, après un certain temps, certaines personnes sont réapparues dans un lieu de détention, souvent présentant des séquelles des tortures subies. Elles ont alors ensuite généralement été détenues à titre préventif dans le cadre des poursuites ouvertes contre elles pour « atteinte à la sûreté intérieure de l’État », « participation à des bandes armés » ou « détention illégale d’armes ». En revanche, la majorité des personnes disparues n’est pas réapparue et leur sort demeure inconnu jusqu’à ce jour, même s’il semble raisonnable de penser qu’elles ont été exécutées. \nUn proche d’une personne disparue a témoigné :\n« Le [X] 2021, un groupe de policiers est venu chez lui pour faire une fouille-perquisition. Ils n’ont rien trouvé chez lui. Il n’était pas chez lui, mais [Y] était là. Les policiers ont dit à [Y] qu'il devait se présenter à la police quand il revenait. Comme il ne s'accusait de rien, il s'est présenté […] à la police […]. Au bureau de la police […] des agents de la documentation sont entrés et l’ont directement sorti du bureau et l’ont mis dans un véhicule. On n’a plus de nouvelles de lui depuis cette date. On a cherché dans les cachots de [A] et de [B], mais on ne l’a pas trouvé. On ne sait pas s’il existe encore. [Il] était accusé d'être de mèche avec les rebelles ».\nQuelques semaines plus tard, la personne disparue est réapparue en détention après avoir été détenue et torturée au SNR, période pendant laquelle ses proches sont restés sans nouvelles malgré les démarches qu’elles ont effectuées."},{"id":"a-hrc-48-crp-1-p0119","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"119","seq":119,"section":"B. Principales violations et situation de l’espace démocratique depuis juin 2020","text":"Des proches des personnes arrêtées ou recherchées, notamment des femmes, ont également été arrêtées et détenues arbitrairement par le SNR et poursuivies pour ne pas les avoir dénoncées ou sans vraiment de raison officielle, dans le cadre d’enquêtes sur des incidents de sécurité dont leur époux, ou un autre membre masculin de leur famille, serait présumé responsable. Au moins l’une de ces femmes a été victime de viol durant sa détention. La Commission rappelle qu’elle avait constaté l’existence de telles pratiques par le passé : des membres des forces de sécurité ainsi que des Imbonerakure avaient régulièrement commis des violations graves du droit à l’intégrité physique, notamment des viols, et du droit à la liberté contre des femmes et des filles pour les punir des agissements de leurs proches ou les contraindre à rejoindre le CNDD-FDD ou encore lors d’attaques de foyers visant des personnes perçues comme des opposants."},{"id":"a-hrc-48-crp-1-p0120","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"120","seq":120,"section":"B. Principales violations et situation de l’espace démocratique depuis juin 2020","text":"Par ailleurs, des hommes soupçonnés d’être membres de groupes armés impliqués dans les incidents de sécurité ou d’aider ces derniers ont été exécutés par des policiers ou des agents du SNR, y compris alors qu’ils étaient en détention. Aucune enquête crédible n’a été ouverte sur ces incidents.\nUn témoin a raconté :\n« Un policier est venu et a tiré une balle sur [X] et il est mort sur le champ. J’ai vu que c’était un homme en uniforme de la police, mais je ne sais pas de quel policier il s’agissait. Il est rentré, il a regardé [X]. Il avait une torche qu’il a pointée vers [X] et lui a tiré dessus trois fois : deux fois à la tête et une fois au ventre. Puis il a éteint sa torche et il est parti. […] Le cadavre est resté là […]. Il y avait du sang partout autour du cadavre »."},{"id":"a-hrc-48-crp-1-p0121","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"121","seq":121,"section":"B. Principales violations et situation de l’espace démocratique depuis juin 2020","text":"C’est dans ce contexte que certains prisonniers ayant bénéficié de la grâce présidentielle accordée à 5 000 d’entre eux au mois de mars 2021, et qui ont commencé à être libérés progressivement à partir de la fin du mois d’avril, ont été ré-arrêtés peu après leur libération et d’autres, enlevés et portés disparus, notamment des personnes qui avaient été détenues en lien avec leur affiliation politique ou leur participation aux manifestations de 2015.\nc)\tAtteintes au droit à la vie"},{"id":"a-hrc-48-crp-1-p0122","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"122","seq":122,"section":"B. Principales violations et situation de l’espace démocratique depuis juin 2020","text":"La Commission a également reçu des allégations crédibles sur des cas d’atteinte au droit à la vie. Des Imbonerakure, des membres du CNDD-FDD avec des responsabilités administratives au niveau local et certains de leurs proches auraient été délibérément tués par des hommes armés non identifiés. Des groupes d’hommes armés non identifiés seraient également responsables des attaques indiscriminées ayant causé la mort de nombreux civils. La Commission n’a pas été en mesure d’identifier les auteurs, faute notamment d’un accès aux victimes proches du parti CNDD-FDD peu enclines à coopérer avec elle pour ce qui est des attaques ciblées, mais également en raison du refus du Gouvernement de partager avec elle des informations sur ces attaques."},{"id":"a-hrc-48-crp-1-p0123","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"123","seq":123,"section":"2. Situation des médias et des journalistes","text":"Dans ses précédents rapports, la Commission avait constaté que les médias et les journalistes indépendants qui arrivaient à opérer malgré le contexte difficile faisaient face à un contrôle étroit de leurs activités par les autorités et à un accroissement des restrictions abusives qui leur sont imposées par le truchement de la loi ou de règlements. Dans le contexte du processus électoral de 2020, les autorités avaient encore renforcé leur contrôle sur les médias et les journalistes, notamment en instrumentalisant le système judiciaire puisque des journalistes ont été poursuivis et condamnés pour avoir exercé leur travail de recherche d’informations sur des incidents de sécurité."},{"id":"a-hrc-48-crp-1-p0124","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"124","seq":124,"section":"2. Situation des médias et des journalistes","text":"Les principales avancées qui ont eu lieu depuis l’arrivée au pouvoir du Président Ndayishimiye concernent les médias. Le Gouvernement du Burundi a pris des mesures afin de desserrer l’étau qui pesait sur la presse, mais étant davantage symboliques que structurelles, elles ne peuvent pas contribuer à garantir effectivement et durablement les libertés d’information et d’expression. Des problèmes persistent et le traitement réservé aux journalistes burundais en exil depuis 2015 reste un sujet de préoccupation.\na)\tLa libération des journalistes d’Iwacu"},{"id":"a-hrc-48-crp-1-p0125","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"125","seq":125,"section":"2. Situation des médias et des journalistes","text":"Une des mesures les plus notables prises par le Président est la libération, le 24 décembre 2020, des quatre journalistes du groupe de presse Iwacu, Agnès Ndirubusa, Christine Kamikazi, Térence Mpozenzi et Egide Harerimana. Ils avaient été arrêtés le 22 octobre 2019 alors qu’ils cherchaient à couvrir des affrontements armés survenus le matin même dans la province Bubanza. Le 30 janvier 2020, ils avaient été condamnés pour « tentative impossible de complicité d’atteinte à la sureté intérieure de l’État » à deux ans et demi de prison et un million de francs burundais d’amende chacun. La peine avait été confirmée en appel le 6 juin 2020."},{"id":"a-hrc-48-crp-1-p0126","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"126","seq":126,"section":"2. Situation des médias et des journalistes","text":"Le Président Ndayishimiye a décidé de leur accorder la grâce présidentielle, mesure qui constituait en fait une remise de peine de 16 mois qui n’efface pas leur condamnation ni les amendes qui leur avaient été infligées. Les autorités burundaises n’ont donc pas reconnu ni leur innocence ni la nature arbitraire de leur arrestation et de leur détention pendant un an et deux mois.\nb)\tLevée des sanctions contre certains médias"},{"id":"a-hrc-48-crp-1-p0127","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"127","seq":127,"section":"2. Situation des médias et des journalistes","text":"Le 28 janvier 2021, lors d’un atelier de deux jours organisé pour les professionnels des médias, intitulé « Jamais sans les médias », le Président Ndayishimiye a rappelé l’importance de leur rôle dans la sauvegarde de la cohésion sociale et dans la poursuite des objectifs de développement durable. Il a réaffirmé « son engagement pour une presse libre et responsable » au Burundi et demandé au Conseil national de la Communication (CNC) de rencontrer les responsables des médias sanctionnés ou suspendus dans le pays afin de permettre de trouver des solutions afin que ces médias reprennent leurs activités."},{"id":"a-hrc-48-crp-1-p0128","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"128","seq":128,"section":"2. Situation des médias et des journalistes","text":"Le 1er février 2021, le CNC a effectivement rencontré à huis clos pour une « première prise de contact » des représentants de certains médias sanctionnés ou suspendus, notamment des radios internationales BBC et VOA, de la radio Bonesha FM, du Groupe de presse Iwacu et des journaux en ligne Ikiriho et Nawe. Le Président du CNC a souligné que la question des journalistes en exil accusés d’avoir participé au coup d’État raté du 13 mai 2015 n’était pas du ressort du CNC. Le 12 février, les sanctions contre le Groupe de presse Iwacu ont été levées par le CNC, à savoir la fermeture de la rubrique commentaires, alors que les restrictions d’accès direct au site internet d’Iwacu depuis le Burundi étaient quant à elles maintenues puisqu’il n’est accessible qu’à travers l’utilisation d’un VPN ou du site miroir."},{"id":"a-hrc-48-crp-1-p0129","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"129","seq":129,"section":"2. Situation des médias et des journalistes","text":"Le 19 février 2021, le CNC a annoncé que les sanctions imposées à la radio Bonesha étaient levées suite au changement de direction – puisque l’ancien directeur était poursuivi par la justice burundaise dans le dossier RPS 100 - et à la signature d’un cahier des charges par lequel la nouvelle direction s’engage à « prendre toutes les dispositions pertinentes afin d’éviter toute faute professionnelle qui entrerait en contradiction avec les lois et règlements en vigueur au Burundi »."},{"id":"a-hrc-48-crp-1-p0130","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"130","seq":130,"section":"2. Situation des médias et des journalistes","text":"Le 21 avril 2021, lors de son assemblée extraordinaire, le CNC a annoncé que quatre médias étaient autorisés à émettre à nouveau : la radio Voix de la réconciliation, la radio-télévision Burundi Bwiza, la télévision Isanganiro et la radio Kazoza avec une télévision en ligne ijwi ry’ukugwiza umwimbu. Cependant, le même jour, le CNC a fait également le point sur les manquements et fautes professionnelles de certains médias et a indiqué que le Groupe de presse Iwacu avait publié le 6 mars 2021 « un article qui était mal conçu […] en rapport avec une conférence publique par vidéoconférence, à laquelle avaient participé les acteurs politiques de l’opposition » et malgré la promesse du Directeur d’Iwacu de « corriger cette erreur », le CNC a mentionné qu’il continuait son enquête sur le dossier. L’article en question faisait état de la réunion virtuelle organisée par le Mouvement d’action patriotique (MAP) sur l’avenir de l’Accord d’Arusha et les risques qu’il ne devienne complètement caduc."},{"id":"a-hrc-48-crp-1-p0131","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"131","seq":131,"section":"2. Situation des médias et des journalistes","text":"Le 5 juin 2021, il a été annoncé que le média en ligne Ikiriho allait bientôt reprendre ses activités. Ce journal, pourtant réputé proche du pouvoir burundais, avait été suspendu le 12 octobre 2018 par le Procureur général de la République, officiellement suite à la plainte pour diffamation déposée par une banque qu’Ikiroho avait accusée de blanchiment d’argent, mais plus vraisemblablement en raison de luttes intestines au sein du CNDD-FDD. Le journal en ligne a repris effectivement ses activités le 16 juin 2021."},{"id":"a-hrc-48-crp-1-p0132","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"132","seq":132,"section":"2. Situation des médias et des journalistes","text":"Le 16 juin 2021, le Conseil national de la communication a annoncé « qu’il n’y a pas d’entraves à ce que la BBC World Service au Burundi soit autorisée d’introduire une nouvelle demande d’autorisation d’exploitation pour la bonne marche de la procédure ». Pour rappel, la BBC avait été suspendue par le CNC le 29 mars 2019 pour sanctionner la diffusion du reportage « Kamwe Kamwe » révélant l’existence de lieux de détention secrets à travers le pays où des personnes détenues illégalement auraient été torturées, puis exécutées par des membres du SNR. Selon le CNC, ce reportage était « mensonger, calomnieux et accablant pour le Burundi »."},{"id":"a-hrc-48-crp-1-p0133","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"133","seq":133,"section":"2. Situation des médias et des journalistes","text":"En revanche, il a été rapporté par le Comité pour la protection des journalistes que la radio internationale Voice of America (VOA), suspendue depuis 2019, ne pourrait reprendre ses activités à la condition que le cas d’un de ses journalistes recherché par la justice burundaise soit « résolu ».\nc)\tCondamnation des journalistes en exil"},{"id":"a-hrc-48-crp-1-p0134","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"134","seq":134,"section":"2. Situation des médias et des journalistes","text":"Dans le cadre de ses démarches de semi-ouverture envers la presse, le Gouvernement burundais n’a pas vraiment abordé le sort réservé aux journalistes burundais qui ont fui le Burundi dès 2015 et des médias burundais suspendus à cette date, tels que la Radio publique africaine (RPA) et Télé Renaissance. Au contraire, des développements récents sur le plan judiciaire semblent fermer la porte à toute possibilité de retour et de reprise d’activité."},{"id":"a-hrc-48-crp-1-p0135","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"135","seq":135,"section":"2. Situation des médias et des journalistes","text":"Le 2 février 2021, la Cour suprême du Burundi a affiché publiquement – dans le cadre de la signification à domicile inconnu pour exécution – sa décision datée du 23 juin 2020 dans le dossier RPS 100, dans lequel étaient poursuivis 34 « putschistes en fuite à l’étranger », dont sept journalistes, accusés d’avoir pris part à la tentative de coup d’État du 13 mai 2015, contre lesquels des mandats d’arrêt internationaux avaient été émis le 2 février 2016 par le Secrétaire général de la Cour suprême. Parmi les accusés dans ce dossier, qui sont tous en exil, il y a également des représentants de la société civile et des avocats actifs dans le domaine des droits de l’homme, des frondeurs du CNDD-FDD ainsi que des militaires."},{"id":"a-hrc-48-crp-1-p0136","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"136","seq":136,"section":"2. Situation des médias et des journalistes","text":"Tous les accusés ont été reconnus coupables d’attentat à l’autorité de l’État, assassinats et destructions. Ils ont donc été condamnés à la servitude pénale à perpétuité assortie de l’interdiction d’exercer une fonction publique, une activité professionnelle ou sociale pendant 20 ans ainsi qu’à payer conjointement - et de manière solidaire avec les 21 militaires condamnés en mai 2016 dans un autre dossier - plus de 5,5 milliards de francs burundais (environ 2,8 millions de dollars des États Unis d’Amérique) en dommages et intérêts au profit de l’État, du parti CNDD-FDD, de la Radiotélévision Rema FM et de divers particuliers. La Cour a précisé que leurs biens mobiliers et immobiliers, qui avaient été saisis par la Justice en mai 2019, seraient vendus pour payer les dommages exigés. La vente aux enchères des biens saisis en mai 2019 a effectivement été organisée de 11 au 14 novembre 2020 alors même que le jugement de la Cour suprême n’avait pas été rendu public.\nd)\tHarcèlement des journalistes"},{"id":"a-hrc-48-crp-1-p0137","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"137","seq":137,"section":"2. Situation des médias et des journalistes","text":"Malgré les discours du Président Ndayishimiye en faveur de la liberté de la presse, la pratique qui consiste à vilipender les journalistes osant critiquer le Gouvernement ou ses actions, ou encore révéler des affaires de corruption ou de mauvaise gouvernance parmi certains caciques du régime, perdure."},{"id":"a-hrc-48-crp-1-p0138","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"138","seq":138,"section":"2. Situation des médias et des journalistes","text":"Par exemple, au mois de mai 2021, un fait divers a fait couler beaucoup d’encre au Burundi, notamment sur les réseaux sociaux, à savoir le décès d’un jeune étudiant à l’Université de Bujumbura qui selon certains rapports serait « mort de faim ». Ce dernier issu d’une famille pauvre de l’intérieur du pays n’avait pas reçu la bourse d’études qui lui était due pendant plusieurs mois, tout comme nombre d’autres étudiants, en raison de dysfonctionnements au sein de l’administration publique chargée de délivrer les bourses universitaires. L’ancien porte-parole du Président Nkurunziza, qui est actuellement Chef du Bureau chargé des affaires politiques et socio-culturelles de la Présidence de la République, a tout à la fois reconnu et détaillé les dysfonctionnements et les lourdeurs administratives à la base des retards significatifs du paiement des bourses universitaires, tout en critiquant de manière virulente les personnes et les journalistes qui ont dénoncé cette situation. Dans un long message publié sur son compte Facebook il a ainsi déclaré :\n« 10. En tant que Burundais épris de patriotisme, j’estime que personne ne peut se décharger de ses responsabilités lorsque l’image de notre nation est ternie et que la réputation de nos dirigeants est mise à mal souvent par une clique de ventriotes, pêcheurs en eaux troubles ou impérialistes.\n11. La presse locale et les communicateurs auraient dû faire mieux pour éclairer l’opinion sur ce cas d’espèce. À chacun son arme et son travail pour défendre l’honneur de notre pays et barrer la route aux détracteurs »."},{"id":"a-hrc-48-crp-1-p0139","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"139","seq":139,"section":"2. Situation des médias et des journalistes","text":"Ces propos illustrent parfaitement l’ambivalence des autorités burundaises qui affirment soutenir la liberté de la presse mais considèrent les critiques comme autant d’attaques contre l’image du Burundi et ses dirigeants. De même, les médias indépendants et/ou en exil qui rapportent les incidents de sécurité ont été soupçonnés ou accusés de complicité avec les auteurs des incidents et ont fait l’objet de menaces à peine voilées, y compris par des personnes proches de certaines autorités. Le sort des quatre journalistes d’Iwacu est bien sûr présent dans toutes les têtes des journalistes."},{"id":"a-hrc-48-crp-1-p0140","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"140","seq":140,"section":"2. Situation des médias et des journalistes","text":"En l’absence de réforme de fond pour garantir effectivement la liberté de l’information et protéger les journalistes dans l’exercice de leur travail, l’autocensure reste le maître mot pour les journalistes burundais qui ont parfois été menacés. Ils évaluent au jour le jour leur marge de manœuvre, qui est laissée au bon vouloir des autorités locales. Ils se sentent surveillés, y compris dans leurs déplacements, et le CNC n’hésite pas à les convoquer pour leur demander des comptes. Ils savent qu’ils peuvent être accusés à tout moment de faire circuler des informations que le Gouvernement ou les autorités locales souhaiteraient dissimuler. Si l’attitude des autorités locales envers les journalistes indépendants semble s’être un peu assouplie ces derniers temps, comme l’expliquent les journalistes d’Iwacu partis recueillir des informations sur l’attaque des véhicules du 26 juin 2021, le fait est que la situation demeure précaire et les restrictions arbitraires toujours possibles.\nUn journaliste a expliqué :\n« Je continue de faire l'objet de menaces de la part du […] de la police, du […] du SNR […] et de quelques membres du parti CNDD-FDD, les Imbonerakure. Ils me reprochent de donner des informations qui sont relayées par les réseaux sociaux et sur les ondes des radios au Rwanda. Je suis suspect à cause de ces informations qui circulent »."},{"id":"a-hrc-48-crp-1-p0141","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"141","seq":141,"section":"2. Situation des médias et des journalistes","text":"Les médias officiels ne font preuve d’aucun esprit critique depuis bien longtemps et se refusent à émettre la moindre réserve ou questionner l’action gouvernementale, et encore moins mentionner des incidents de sécurité comme par exemple les grenades lancées dans plusieurs endroits à Bujumbura le 26 mai 2021 ni les violations des droits de l’homme, y compris les dépouilles retrouvées régulièrement sur la voie publique. Les célébrations du premier anniversaire du décès du Président Nkurunziza et de celui de l’intronisation du Président Ndayishimiye ont vu les médias officiels se lancer dans une opération de propagande en faveur de ces deux personnalités..\ne)\tRévision de la loi sur la Presse"},{"id":"a-hrc-48-crp-1-p0142","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"142","seq":142,"section":"2. Situation des médias et des journalistes","text":"Le 28 juin 2021, la ministre de la Communication, des Technologies d’information et des Médias a lancé un atelier du processus de consultation sur la révision de la loi sur la presse de 2018. Selon les informations qui ont circulé publiquement, le but de cette révision est d’encadrer les médias en ligne et les radios communautaires pour lesquelles les dispositions de la loi existante seraient lacunaires ; mais également empêcher la circulation sur les réseaux sociaux de « contenus contraires à la culture burundaise ». La seule vraie mesure structurelle prévue tend donc vers le renforcement du contrôle des contenus de la presse."},{"id":"a-hrc-48-crp-1-p0143","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"143","seq":143,"section":"3. Situation de la société civile","text":"Dans son précédent rapport, la Commission avait constaté que le Gouvernement burundais avait cherché à accroître son contrôle sur les ONGs aussi bien nationales qu’étrangères dans le but de museler les observateurs indépendants pendant la période électorale."},{"id":"a-hrc-48-crp-1-p0144","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"144","seq":144,"section":"3. Situation de la société civile","text":"Depuis l’investiture du Président Ndayishimiye, quelques développements positifs concernent la société civile, mais ce sont généralement des gestes ad hoc symboliques. Par exemple, le 2 avril 2021, le ministre de l’Intérieur, du Développement communautaire et de la Sécurité publique a autorisé l’organisation PARCEM (Parole et actions pour le réveil des consciences et l’évolution des mentalités) à reprendre ses activités. Cette organisation avait fait l’objet d’une mesure de suspension temporaire en juin 2019 pour avoir « terni l’image du pays » en ayant présenté un rapport critique sur les conditions socio-économiques. Depuis, PARCEM a repris ses activités et a notamment présenté un plan de relance économique pour lutter contre la pauvreté généralisée de la population burundaise, qui inclut notamment un plan de construction d’infrastructure et la lutte contre la corruption.\na)\tLibération de défenseurs des droits de l’homme"},{"id":"a-hrc-48-crp-1-p0145","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"145","seq":145,"section":"3. Situation de la société civile","text":"Le 27 avril 2021, le défenseur des droits de l’homme Nestor Nibitanga, un ancien collaborateur de l’Association pour la protection des droits humains et des personnes détenues (APRODH), a été libéré par grâce présidentielle après quatre années de détention arbitraire. Pour rappel, Nestor Nibitanga avait été arrêté le 21 novembre 2017 et condamné le 13 août 2018 à cinq ans de prison en raison de ses activités au sein de l’APRODH (avant que cette organisation ne soit radiée par le Gouvernement en octobre 2016) qui avaient été qualifiées abusivement « d’atteintes à la sûreté intérieure de l’État » après un procès marqué par des irrégularités et des violations des droits fondamentaux de l’accusé."},{"id":"a-hrc-48-crp-1-p0146","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"146","seq":146,"section":"3. Situation de la société civile","text":"Le 30 juin 2021, Germain Rukuki, un autre défenseur des droits de l’homme ancien membre de l’ACAT-Burundi qui était détenu arbitrairement depuis juillet 2017, a été également libéré suite à son deuxième procès en appel tenu le 24 mars 2021. En effet, en juin 2020, la Cour suprême avait cassé le premier jugement en appel datant du 17 juillet 2019 qui confirmait sa condamnation initiale à 32 ans de prison. Dans son jugement adopté le 4 juin 2021 mais rendu public seulement le 21 juin 2021, la cour d’appel de Ntahangwa l’a donc acquitté des charges de « participation à un mouvement insurrectionnel », « d’atteinte à la sureté de l’État » et « d’attentat contre l’autorité de l’État », mais elle l’a reconnu coupable de « rébellion » et condamné à une peine d’un an de prison et au paiement d’une amende de 50 000 francs burundais (environ 25 dollars) ainsi que des frais de justice. Comme Germain Rukuki était détenu depuis près de quatre ans, il aurait dû être immédiatement libéré puisqu’il avait déjà purgé sa peine. Malgré cela, il a fallu attendre une semaine et des pressions des organisations de la société civile ainsi que de la CNIDH et de l’Union européenne qui ont demandé sa libération effective.\nb)\tRenforcement du contrôle de la société civile"},{"id":"a-hrc-48-crp-1-p0147","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"147","seq":147,"section":"3. Situation de la société civile","text":"Cependant, le Gouvernement a pris des mesures qui visent plutôt à renforcer davantage son contrôle sur les activités et le fonctionnement des organisations de la société civile qu’à rouvrir véritablement l’espace démocratique et permettre à ces organisations de fonctionner librement. En effet, les autorités burundaises considèrent que la société civile est uniquement là pour les assister, niant ainsi le principe même de la liberté d’association qui inclut la liberté de décider des buts poursuivis et des moyens d’y parvenir."},{"id":"a-hrc-48-crp-1-p0148","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"148","seq":148,"section":"3. Situation de la société civile","text":"Par exemple, le Gouvernement a décidé de limiter les frais de fonctionnement au sein des projets financés par les partenaires techniques et financiers, notamment en alignant les salaires sur ceux des établissements publics burundais. Désormais, une grille salariale harmonise les rémunérations des gestionnaires et personnels ainsi que les frais de fonctionnement au sein de ces projets, notamment du fait que les financements reçus doivent être destinés aux « projets d’investissement en harmonie avec les priorités retenues dans la Politique nationale de développement et non aux frais de gestion », et comme le « volume du travail est similaire à celui se trouvant au niveau de l’administration publique et des établissements publics burundais », le Gouvernement considère que « le niveau de rémunération excessivement élevé au sein de ces projets ne se justifie pas ». Il estime également que la « performance dans les projets financés par les partenaires techniques et financiers est douteuse au regard des retards dans l’exécution des projets, avec des demandes de prolongation des délais, des contentieux observés, ainsi que des dépenses inéligibles que l’État est appelé à supporter dans certains cas ». Finalement, il considère que les « disparités salariales au sein des projets financés par les partenaires techniques et financiers ne sauraient se justifier dans un contexte national de recherche du rétablissement de l’équité salariale par la mise en place d’une politique salariale équitable dans l’administration publique burundaise ». De fait, les personnes travaillant dans de tels projets doivent désormais être rémunérées « aux niveaux des salaires en vigueur au sein des Établissements publics burundais mieux rémunérés »."},{"id":"a-hrc-48-crp-1-p0149","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"149","seq":149,"section":"3. Situation de la société civile","text":"Le 25 novembre 2020, lors du Conseil des ministres, le Président Ndayishimiye a ajouté que les projets financés par les partenaires techniques et financiers « sont pour l’État burundais et les ministres doivent les suivre de près. Les fonds accordés à ces projets doivent servir à leur réalisation et non comme frais de fonctionnement. C’est pourquoi pour les projets à venir, leur conception et leur réalisation doivent être une affaire de l’État. Les gestionnaires de ces projets doivent savoir qu’ils sont au service de l’État et non au service du partenaire qui a financé le projet »."},{"id":"a-hrc-48-crp-1-p0150","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"150","seq":150,"section":"3. Situation de la société civile","text":"En février 2021, le ministre de l’Intérieur, du Développement communautaire et de la Sécurité publique a envoyé une lettre aux représentants des ONGs étrangères actives dans une province afin de les notifier de la visite par une délégation du ministère chargée d’inspecter les réalisations mentionnées dans les rapports périodiques et de collecter des informations telles que la structure du budget, la régularité dans la préparation et la transmission des rapports sur les activités des ONGs étrangères aux autorités burundaises, la transmission du plan d’action et du budget annuel de l’organisation, la composition ethnique du personnel et les effectifs de genre, la vérification des agréments des salariés expatriés et de leur salaire ainsi que de l’implication des comités de recrutement instaurés par le Gouvernement dans les procédures d’embauche."},{"id":"a-hrc-48-crp-1-p0151","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"151","seq":151,"section":"3. Situation de la société civile","text":"Le 5 mai 2021, le ministre des Affaires étrangères et de la Coopération au développement a refusé, sans fournir d’explication, de proroger l’agrément du représentant légal d’une ONG étrangère. \nc)\tMéfiance et hostilité persistantes envers la société civile"},{"id":"a-hrc-48-crp-1-p0152","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"152","seq":152,"section":"3. Situation de la société civile","text":"Le 13 octobre 2020, Tony Germain Nkina, un avocat, qui était le représentant de l’APRODH dans la province Kayanza jusqu’à la suspension de l’organisation par le Gouvernement en 2015, a été arrêté dans la commune de Kabarore. Il s’était rendu sur les lieux pour rencontrer un de ses clients dans le cadre de ses activités professionnelles et le conseiller dans le cadre d’un conflit foncier. Après avoir été brièvement détenu par le service de renseignement à Kayanza, il a été transféré à la police, et enfin à la prison de Ngozi. Le 15 juin 2021, le tribunal de grande instance de Kayanza l’a déclaré coupable de « collaboration avec les rebelles qui ont attaqué le Burundi » et l’a condamné à cinq ans d’emprisonnement et au paiement d’une amende d’un million de francs burundais (environ 500 dollars). Son client, Apollinaire Hitimana, a également été arrêté et déclaré coupable de complicité à la même infraction et condamné à deux ans et demi d’emprisonnement et au paiement d’une amende de 500 000 francs burundais (environ 250 dollars). Pour rappel, au début du mois d’octobre 2020, plusieurs incidents de sécurité ont été enregistrés, notamment dans la province Kayanza. Le procureur l’a accusé, sans présenter d’éléments de preuve, d’être allé au Rwanda pour livrer des informations au président de l’APRODH, Pierre Claver Mbonimpa, qui vit en Europe, ainsi qu’au RED-Tabara. Cet ancien défenseur des droits de l’homme serait donc détenu principalement en lien avec ses activités passées au sein de l’APRODH."},{"id":"a-hrc-48-crp-1-p0153","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"153","seq":153,"section":"3. Situation de la société civile","text":"Un sentiment de méfiance et d’hostilité envers les organisations de la société civile est palpable de la part des autorités, qui présentent souvent les organisations de la société civile comme des prédateurs et captant l’argent des partenaires techniques et financiers, inefficaces, voire néfastes. Par exemple, le Président de l’Assemblé nationale a déclaré que « la société coopérative Sangwe est le fondement de la multiplication de richesse au niveau des collines et au niveau provincial. Les associations sans but lucratif n’ont plus de place au Burundi vu la grand’soif de développement qui presse le pas ce jour »."},{"id":"a-hrc-48-crp-1-p0154","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"154","seq":154,"section":"3. Situation de la société civile","text":"Il n’est donc pas étonnant que dans un tel contexte, quelques ONGs étrangères s’adaptent à ce que le Gouvernement attend d’eux et font des efforts supplémentaires pour plaire aux autorités."},{"id":"a-hrc-48-crp-1-p0155","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"155","seq":155,"section":"3. Situation de la société civile","text":"Pour rappel, cinq avocats et/ou représentants d’ONGs actives dans le domaine des droits de l’homme, qui avaient été accusés d’avoir pris part à la tentative de coup d’État raté du 13 mai 2015, ont été reconnus coupables d’attentat à l’autorité de l’État, assassinats et destructions et condamnés à la servitude pénale à perpétuité par la Cour suprême. Ils étaient poursuivis avec sept journalistes, des frondeurs du CNDD-FDD ainsi que des militaires dans le dossier RPS 100. Ils ont été jugés en leur absence et sans avoir pu se faire représenter par un avocat. Leurs biens mobiliers et immobiliers, qui avaient été saisis par la Justice en mai 2019, ont été vendus aux enchères organisées du 11 au 14 novembre 2020 afin de payer les 5,5 milliards de francs burundais (environ 2,8 millions de dollars) de dommages et intérêts au profit de l’État, du parti CNDD-FDD, de la Radiotélévision Rema FM et de divers particuliers."},{"id":"a-hrc-48-crp-1-p0156","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"156","seq":156,"section":"4. Situation des partis politiques d’opposition","text":"Dans le cadre des élections de 2020, la Commission avait constaté de nombreuses restrictions abusives et violations des libertés d’association, de réunion pacifique et d’expression qui visaient particulièrement le parti d’opposition CNL. Elles avaient pour objectif de réduire ses chances de gagner les élections en l’empêchant notamment de mener à bien des activités politiques usuelles dans une démocratie telles que l’organisation de rassemblements et de réunions publiques et privées, ou interdisant l’établissement ou l’ouverture de permanences du parti CNL ou en les saccageant, ainsi qu’en censurant les propos critiques envers le Gouvernement, notamment en poursuivant les auteurs en justice."},{"id":"a-hrc-48-crp-1-p0157","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"157","seq":157,"section":"4. Situation des partis politiques d’opposition","text":"Au cours du présent terme, la Commission a documenté des cas qui ont confirmé ses conclusions présentées dans son précédent rapport sur le recours à la torture, y compris à caractère sexuel dans le contexte des élections de 2020, notamment des cas de viol collectif commis contre des femmes dans le contexte des élections de 2020 par des Imbonerakure. Les victimes, des femmes célibataires ou dont le mari avait disparu suite au harcèlement ou à un enlèvement par des Imbonerakure, ont été visées en raison de leur refus de rejoindre le CNDD-FDD durant la campagne électorale. Les auteurs de ces viols, qui arboraient des accessoires ou T-shirt à l’effigie du CNDD-FDD, ont été identifiés par les victimes comme des Imbonerakure, parmi lesquels certains étaient des voisins. À l’instar des cas de violences sexuelles commis pour des motifs politiques documentés au cours des termes précédents, ces viols ont été l’aboutissement d’une période d’intimidation et de harcèlement de la part des Imbonerakure. Dans deux cas, ils ont résulté en une grossesse, aggravant la détresse matérielle et psychique des victimes. Aucune des victimes n’a osé dénoncer les faits aux autorités, et toutes ont fui le Burundi dès qu’elles en ont eu la possibilité."},{"id":"a-hrc-48-crp-1-p0158","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"158","seq":158,"section":"4. Situation des partis politiques d’opposition","text":"À l’issue des élections, les nombreuses restrictions abusives et violations des droits aux libertés d’association, de réunion pacifique et d’expression qui visaient les partis d’opposition, notamment le CNL, telles que l’interdiction d’organiser des rassemblements et des réunions ou d’ouvrir des permanences, se sont amenuisées. Cela est logiquement dû au fait que le CNL a réduit ses activités après les élections et qu’il ne représente plus une « menace » imminente pour le parti au pouvoir, d’autant plus qu’il ne participe ni au Gouvernement, ni au Bureau de l’Assemblée nationale, même s’il a obtenu plus de sièges de députés que le parti UPRONA qui a été choisi pour la deuxième vice-présidence du bureau de l’Assemblée..\na)\tRestrictions abusives des libertés d’association et de réunion"},{"id":"a-hrc-48-crp-1-p0159","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"159","seq":159,"section":"4. Situation des partis politiques d’opposition","text":"Des incidents ont néanmoins été rapportés dans plusieurs provinces : plusieurs permanences du CNL ont été saccagées notamment au mois de juin 2021, même si beaucoup avaient été fermées par le parti après les élections pour des raisons de coût financier. Il reste difficile pour le CNL, voire impossible dans certaines communes, d’organiser des réunions, comme ce fut par exemple le cas pour la célébration du 2ième anniversaire de la création du parti qui dans au moins une localité a été interrompue et interdite.\nUn témoin a raconté :\n« C’est d’abord le chef de colline qui a refusé […]  et a dit que la célébration ne peut pas avoir lieu. Ensuite le chef de zone est arrivé pour empêcher aussi les préparatifs de la cérémonie. Il était très mécontent de voir les militants mobilisés et il a commencé à détruire les hangars […]  installés pour la fête ».\nUn militant du CNL a expliqué :\n« On ne peut même pas ouvrir nos permanences et y rester pendant cinq minutes sans l’autorisation de l’administrateur communal. Il a donné l'ordre aux agents de la police d’arrêter toute personne qu’on trouvera dans une permanence du CNL sans son autorisation. […] » ."},{"id":"a-hrc-48-crp-1-p0160","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"160","seq":160,"section":"4. Situation des partis politiques d’opposition","text":"Des militants de partis d’opposition ont également été harcelés ou maltraités par des Imbonerakure en représailles à leur engagement politique et d’autres ont été intimidés pour les forcer à rejoindre le CNDD-FDD. Des marches d’Imbonerakure scandant des chants hostiles aux opposants politiques, parfois sous la forme d’entraînements sportifs, ont continué de se dérouler dans certaines collines rurales. Un témoin a rapporté les propos tenus par des Imbonerakure alors qu’ils maltraitaient des membres du CNL :\n« La seule appartenance au parti [CNL] provoque un dégoût de leur part. Pendant que les Imbonerakure les frappaient, ils disaient : \"Que vous a donné ce Rwasa ? Pourquoi continuez-vous à le soutenir ? Pourquoi vous ne l’abandonnez pas ?\" ».\nb)\tViolations du droit à la liberté et à l’intégrité physique"},{"id":"a-hrc-48-crp-1-p0161","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"161","seq":161,"section":"4. Situation des partis politiques d’opposition","text":"Certains membres du CNL ont été arrêtés et détenus arbitrairement sous divers prétextes en représailles de leurs activités politiques, telles que la collecte de contribution auprès des membres du parti pour construire des permanences ou tenir des réunions « illégales ». Ils ont parfois été torturés ou maltraités lors de leur arrestation et leur détention, même si le nombre de cas a globalement baissé à l’issue des élections avant de s’accroître à nouveau à partir de juin 2021, notamment dans le cadre de la lutte contre les groupes rebelles.\nUne personne a expliqué :\n« Sur notre colline, les membres du CNL sont maltraités et il n’y a aucun recours possible. Ils n’ont aucun endroit pour aller porter plainte et faire recours. Si tu commets la moindre infraction et si tu es un CNL, ils vont en faire une grande affaire. Il y a un membre du CNL qui a saisi des poules qui ne lui appartenaient pas car elles étaient venues picorer dans son champ de haricots. Elles appartenaient à son voisin. Comme c’était un CNL, il a été arrêté et emprisonné. Il est toujours en détention. On lui demande de payer une amende de 50 000 francs burundais [environ 25 dollars]et des dommages et intérêts au propriétaire des poules ».\nUne autre a indiqué au sujet d’un membre du CNL qui a été arrêté en janvier 2021 :\n« On ne lui reprochait rien, mais sa colline a reçu beaucoup de voix du CNL et derrière ce qui est arrivé à [X], je pense qu’ils voulaient faire peur à ceux qui voudraient adhérer au CNL ou à ceux qui sont dans le CNL ».\nc)\tViolations du droit à la vie"},{"id":"a-hrc-48-crp-1-p0162","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"162","seq":162,"section":"4. Situation des partis politiques d’opposition","text":"Des membres actifs du CNL ont été victimes de disparition forcée dans les mois qui ont suivi les élections ; ils ont été vus pour la dernière fois alors qu’ils étaient emmenés par des agents de l’État ou des Imbonerakure. Si au moins une personne a par la suite été retrouvée en détention, le sort des autres victimes reste indéterminé."},{"id":"a-hrc-48-crp-1-p0163","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"163","seq":163,"section":"4. Situation des partis politiques d’opposition","text":"Par exemple, Oscar Nahimana, un membre du CNL qui était le vice-président de la commission électorale communale indépendante de la commune Kirundo, province Kirundo, lors des élections de 2020, est porté disparu depuis le 28 septembre 2020. Il aurait été arrêté par des représentants du parti CNDD-FDD au niveau local car il aurait notamment refusé de signer des documents relatifs à la certification des élections communales et n’a plus été revu par la suite. Les autorités n’ont pas diligenté d’enquête effective malgré les démarches effectuées à différents niveaux par les responsables du parti CNL. À ce jour son sort demeure inconnu."},{"id":"a-hrc-48-crp-1-p0164","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"164","seq":164,"section":"4. Situation des partis politiques d’opposition","text":"Un autre cas est la disparition d’Elie Ngomirakiza, le représentant du CNL au niveau de la commune de Mutimbuzi, province Bujumbura (rural). Il a été vu pour la dernière fois le 9 juillet 2021 alors qu’il était emmené par des militaires. Par le passé, il avait déjà été harcelé et arrêté pour son engagement politique. Le parti CNL a entrepris des démarches auprès des autorités et de la CNIDH pour s’enquérir de son sort, mais jusqu’à présent ses démarches sont restées vaines."},{"id":"a-hrc-48-crp-1-p0165","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"165","seq":165,"section":"4. Situation des partis politiques d’opposition","text":"Au vu de ces cas récents, qui ont été portés à la connaissance des autorités burundaises et de la CNIDH, la Commission s’étonne que le Président Ndayishimiye ait affirmé le 14 juillet 2021 ne pas être au courant de cas de disparition forcée, déclarant « En tout cas, à ce que je sache, il n’y a pas de disparitions au Burundi. Sinon, vous me diriez : \"Telle personne est disparue\" […] Les gens disent qu’ils ont disparu, mais je sais qu’ils sont quelque part » ; et que le 28 juillet 2021, le Procureur général de la République ait quant à lui déclaré que les allégations sur des cas de personnes disparues étaient « mensongères » car des personnes partaient rejoindre des groupes armés sans prévenir leur famille, ce qui expliquait que les familles croyaient à tort que la personne avait disparu. Pour rappel, la CNIDH n’a pas constaté de cas de disparition dans son rapport annuel sur l’année 2020 alors que le cas d’Oscar Nahimana a notamment été enregistré pendant cette période.\nd)\tIntolérance politique et discours de haine"},{"id":"a-hrc-48-crp-1-p0166","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"166","seq":166,"section":"4. Situation des partis politiques d’opposition","text":"Les discours de haine envers les opposants ont été globalement remplacés par des appels officiels à la tolérance politique, mais des propos qui tendent à assimiler les opposants à des « ennemis du pays » ressurgissent de temps à autre. Le Président Ndayishimiye lui-même a soufflé le chaud et le froid à ce sujet, reconnaissant la liberté d’expression des partis politiques pour ensuite dénoncer ceux qui ne soutiennent pas le Gouvernement comme des « agents d’États étrangers ». Il semble donc ne tolérer l’opposition politique que si elle accepte de travailler avec son Gouvernement. Le 8 juin 2021, dans son discours prononcé à l’occasion de la levée de deuil définitive de feu Président Nkurunziza et de la célébration de la Journée nationale du Patriotisme, le Président Ndayishimiye a déclaré : « Celui qui est mécontent de ses réalisations [du feu Président Nkurunziza] en faveur du Burundi et des Burundais est tout simplement le genre de personne possédée par le démon qui ne pense qu’à faire du mal »."},{"id":"a-hrc-48-crp-1-p0167","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"167","seq":167,"section":"4. Situation des partis politiques d’opposition","text":"Toute l’ambiguïté de la position du Président Ndayishimiye sur les partis politiques et leur rôle est clairement exprimée dans ces extraits de son message adressé le 6 janvier 2021 aux représentants des partis politiques agréés à l’occasion de l’échange des vœux du nouvel an : « Autrefois, lorsqu’il y avait des élections, les partis politiques se disputaient et leurs membres se regardaient en chiens de faïence. Au lieu de parler de partis politiques qui s’opposaient entre eux, nous disions qu’il y avait des partis alliés au Gouvernement d’un côté et des partis qui s’opposaient à l’État. […] À ce moment-là, on oubliait que combattre le Gouvernement, c’est combattre le pays, mais ceux qui parlaient ainsi considéraient cela comme une marque d’honneur. Nous n’accomplissions pas notre devoir : servir le pays en respectant les autres, en renforçant la sécurité et en contribuant au développement […] ». Il a ensuite ajouté : « Au sortir d’une élection, la défaite d’un parti n’implique pas sa disparition. En effet vous, les hommes politiques, vous êtes des conseillers car vous vous y connaissez en politique. Il est important que les autorités administratives vous écoutent. Qu’on ne vous désigne pas comme des opposants de l’État mais comme des redresseurs des torts afin que nous réalisions les souhaits du peuple ». Ainsi, le 20 août 2021, les partis politiques, exception faite du CNL, ont participé à un atelier organisé par le Gouvernement du Burundi, sous la direction du ministre de l’Intérieur, de la Sécurité publique et du Développement communautaire, afin d’élaborer leurs programmes politiques et veiller à ce que ceux-ci soient conformes au plan de développement du Gouvernement pour 2018-2027.."},{"id":"a-hrc-48-crp-1-p0168","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"168","seq":168,"section":"4. Situation des partis politiques d’opposition","text":"Des députés de l’opposition ayant osé questionner ou critiquer l’action gouvernementale ont fait les frais de cette défiance envers l’opposition politique, qui semble profondément ancrée chez les dignitaires du CNDD-FDD. Par exemple, l’ancien député Fabien Banciryanino, une des rares voix critiques sous le régime du Président Nkurunziza, a été arrêté le 8 octobre 2020 et poursuivi pour rébellion, dénonciation calomnieuse et atteinte à la sûreté intérieure et extérieure de l’État. Le 7 mai 2021, il a été condamné à un an de prison. Le 26 mai 2021, lors de la séance portant sur la présentation par l’Ombudsman de son rapport annuel pour 2020, un député CNL, Nicodème Nduwimana, a été indirectement menacé par le Président de l’Assemblée nationale pour des propos tenus dans l’enceinte de l’Assemblée. Le député avait simplement demandé à l’Ombudsman s’il était au courant que des prisonniers ayant purgé leur peine restaient détenus. Le Président de l’Assemblée l’a alors interrompu pour lui demander s’il était en train de plaider « pour les personnes qui lançaient des grenades une fois sortis de prison, comme la veille à Bujumbura »."},{"id":"a-hrc-48-crp-1-p0169","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"169","seq":169,"section":"4. Situation des partis politiques d’opposition","text":"Si la violence politique semble globalement diminuer, ce n’est pas pour autant un signe d’une amélioration de la tolérance politique. Aucune mesure structurelle n’a été prise pour garantir que les coupables des violences commises lors des élections soient sanctionnés ou empêcher que de telles pratiques ne ressurgissent, notamment lors des prochaines échéances électorales. Des instructions auraient été données à des Imbonerakure après les élections pour qu’ils cessent la violence envers les opposants, mais ils restent mobilisables à tout moment par les autorités et le parti CNDD-FDD, comme cela a été le cas dans certaines provinces à la suite des incidents de sécurité.."},{"id":"a-hrc-48-crp-1-p0170","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"170","seq":170,"section":"4. Situation des partis politiques d’opposition","text":"Effectivement, depuis les attaques armées du printemps 2021, les membres du CNL sont, par endroits, à nouveau étroitement surveillés par les Imbonerakure et dans certaines provinces le nombre de cas d’arrestation et détention arbitraires, de torture et mauvais traitements mais aussi d’enlèvement et de disparition de militants du CNL a augmenté depuis juin 2021 et tout au cours de l’été 2021, souvent sous couvert de la lutte contre les groupes armés. Comme indiqué précédemment, étant donné l’opacité qui entoure ces procédures, il est impossible de déterminer pour chaque cas si les autorités disposent d’éléments de preuves objectifs ou si elles se basent principalement sur leur seule affiliation politique. La Commission considère néanmoins avoir des motifs raisonnables de croire qu’un nombre significatif d’opposants politiques ont été victimes de violations sous couvert de la traque des responsables d’attaques armées."},{"id":"a-hrc-48-crp-1-p0171","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"171","seq":171,"section":"C. Situation des rapatriés","text":"Dans ses précédents rapports, la Commission avait documenté que les personnes rapatriées au Burundi, principalement depuis la Tanzanie dans le cadre du programme d’aide au retour établi en 2017, avaient fait face à une hostilité générale de la part d’autorités administratives locales et d’Imbonerakure. Certaines avaient été victimes de graves violations des droits de l’homme qui les avaient poussées à fuir à nouveau le pays, d’autres avaient été intimidées, menacées, maltraitées, dépouillées de leur kit d’appui au retour et de leurs biens. Cette situation avait atteint son paroxysme suite aux incidents de sécurité de 2020, puisque les rapatriés, tout comme toute personne ayant voyagé à l’extérieur du pays, pouvaient être soupçonnés de lien avec les groupes armés d’opposition."},{"id":"a-hrc-48-crp-1-p0172","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"172","seq":172,"section":"C. Situation des rapatriés","text":"Le Haut-Commissariat des Nations Unies pour les réfugiés (HCR) ne considère toujours pas que les conditions au Burundi soient propices à la promotion du rapatriement librement consenti, mais il offre un soutien aux réfugiés burundais qui veulent exercer leur droit au retour, pour autant que leur décision soit volontaire, libre et informée, et que leur retour s’effectue dans la sécurité et la dignité. Depuis l’été 2020, les rapatriements de réfugiés volontaires facilités par le HCR se sont accélérés. Le 27 août 2020, a eu lieu le premier convoi de rapatriement des réfugiés burundais depuis le Rwanda dans le cadre du programme de rapatriement volontaire organisé en coopération avec le HCR. Ainsi, au 30 juin 2021, 164 990 réfugiés burundais ont été rapatriés dans le cadre du programme tripartite d’appui au retour volontaire démarré en 2017, dont 42 299 depuis janvier 2021. Les réfugiés sont principalement rentrés de Tanzanie (129 535) et du Rwanda (28 212). À la même date du 30 juin 2021, 276 275 Burundais étaient encore officiellement réfugiés dans les pays limitrophes."},{"id":"a-hrc-48-crp-1-p0173","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"173","seq":173,"section":"C. Situation des rapatriés","text":"En 2020, seulement 40% de l’appel de fonds de 293 millions de dollars lancé par le HCR pour soutenir les réfugiés burundais ont été financés. Les réfugiés ont donc vu leurs rations alimentaires se réduire ; ils ont manqué d’abris adéquats, et ont fait face à des pénuries de médicaments et des moyens de subsistance insuffisants. En février 2021, le HCR a lancé un nouvel appel de fonds de 222 millions de dollars afin de pouvoir fournir au cours de l’année 2021, avec 33 organisations partenaires, de la nourriture, des abris, des services éducatifs, ainsi que l’accès aux soins de santé et à l’eau aux quelque 315 000 Burundais qui restaient réfugiés dans les pays limitrophes à cette date. Au 1er juin 2021, les fonds reçus ne couvraient que 14% des 72,5 millions de dollars requis par le HCR lui-même pour le Burundi dans le cadre de l’appel de fonds global."},{"id":"a-hrc-48-crp-1-p0174","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"174","seq":174,"section":"C. Situation des rapatriés","text":"En février 2021, le HCR a également lancé un appel pour un montant de 104,3 millions de dollars afin de soutenir le rapatriement prévu de 143 000 réfugiés burundais en 2021, mais également soutenir les 120 494 Burundais qui ont été rapatriés depuis 2017 et n’ont pas reçu « une assistance appropriée pour une réintégration adéquate », ainsi que 87 378 membres des communautés d’accueil dans les six principales provinces de retour qui sont considérés comme particulièrement vulnérables : Ruyigi (24 566), Makamba (18 855), Muyinga (16 445), Cankuzo (10 451), Rutana (8 884), Kirundo (8 177).\na)\tClimat de méfiance envers les rapatriés"},{"id":"a-hrc-48-crp-1-p0175","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"175","seq":175,"section":"C. Situation des rapatriés","text":"Depuis les élections de 2020, le climat d’hostilité et de suspicion envers les rapatriés a diminué dans une certaine mesure, notamment grâce à des instructions qui auraient été données aux responsables administratifs de garantir un meilleur accueil aux rapatriés, puisque c’est un enjeu majeur pour permettre le retour massif des réfugiés souhaité par le Gouvernement. \nUn rapatrié a mentionné :\n« On n’a pas été harcelés par les autorités administratives. C'est clair qu’il y avait des consignes qui leur ont été données. Je ne suis pas sûr de savoir quelles sont les consignes qu’elles auraient reçues mais ce que je vois c’est qu'il y a une nette différence entre la manière dont les autorités communales et provinciales nous accueillent lorsque nous leur confions des problèmes que nous rencontrons. Les autorités locales sont beaucoup plus méfiantes à notre égard »."},{"id":"a-hrc-48-crp-1-p0176","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"176","seq":176,"section":"C. Situation des rapatriés","text":"Cependant, selon le HCR, 22% des rapatriés estiment que la situation sécuritaire au Burundi ne s’est pas améliorée depuis leur fuite. Ils font également face à des stéréotypes et à des préjugés répandus au sein des communautés locales qui affectent la cohésion sociale et l’accès des rapatriés aux droits et/ou aux services, ainsi qu’à des actes de discrimination et de harcèlement. La situation s’est aggravée avec la pandémie de Covid-19 et la perception erronée que les rapatriés sont des « porteurs de virus ». En juin 2021, la Conférence des Evêques catholiques a notamment regretté que « les rapatriés ne soient bien accueillis dans certaines localités du pays et soient malheureusement intimidés et opprimés par ceux qui devaient les aider à bien s’intégrer dans la société »."},{"id":"a-hrc-48-crp-1-p0177","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"177","seq":177,"section":"C. Situation des rapatriés","text":"Dans ce cadre, la Commission a reçu des témoignages au sujet de rapatriés qui ont continué à faire face à une méfiance générale de la part des autorités locales et des Imbonerakure.\nUn rapatrié a expliqué :\n« Quand nous sommes arrivés à la commune de [X] même, nous avons remarqué que les choses n’étaient pas roses comme ils l’avaient dit. Les personnes qui n’avaient pas fui nous considéraient avec méfiance. Ceux qu’on appelle les Imbonerakure nous posaient beaucoup de questions surtout que j’ai laissé mes parents et mes frères et sœurs au[X]. Ils me demandaient pourquoi eux ils n’étaient pas rentrés »."},{"id":"a-hrc-48-crp-1-p0178","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"178","seq":178,"section":"C. Situation des rapatriés","text":"Des personnes qui avaient été politiquement actives dans le passé et qui parfois ne sont pas rentrées dans le cadre du programme officiel d’appui au rapatriement ont continué à être soupçonnées de collaborer avec des groupes armés et étaient recherchées. Certaines ont même été torturées, surtout celles en provenance du Rwanda, notamment par des Imbonerakure. Parfois, la seule peur d’être arrêté ou tué a poussé des réfugiés, y compris ceux venus par eux-mêmes en reconnaissance, à retourner vers leur pays d’accueil.\nUn témoin a raconté :\n« Après les attaques à la grenade à Bujumbura au mois de mai 2021, on a commencé à chercher les réfugiés qui venaient […]. On disait que c’étaient des réfugiés […] qui ont fait cela. Un voisin m’a dit que mon nom avait été donné à la documentation car on recherchait des réfugiés en provenance […]. Un jour que je n’étais pas chez moi, la documentation est venue où j’habitais [...] J’ai analysé ma situation. Je ne pouvais pas aller chez moi, je ne pouvais pas aller à [X] ou à Bujumbura. J’ai pris la décision de retourner en exil ».\nUn autre témoin, arrêté et interrogé par le SNR a expliqué :\n« Ils m’ont posé les mêmes questions sur le camp, la rébellion, etc. Je leur ai dit que je n’avais aucune information là-dessus. Je leur ai dit qu’après toutes ces années passées au camp, j’avais entendu dire que la paix était revenue et j’avais donc décidé de rentrer. Je n’avais pas d’autres raisons de le faire. Ils m’ont dit que je leur cachais des choses, que j’étais venu en reconnaissance, que j’étais venu préparer le terrain pour les rebelles. […] Quand je niais, ils me frappaient et ils arrêtaient quand je n’étais plus en mesure de répondre. […] Ils me frappaient partout. J’ai même reçu un coup au niveau de la tête près de mon oreille. J’en ressens encore les douleurs ».\nb)\tConditions socioéconomiques précaires"},{"id":"a-hrc-48-crp-1-p0179","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"179","seq":179,"section":"C. Situation des rapatriés","text":"De grandes difficultés persistent également au niveau de la réintégration socio-économique des rapatriés car « les conditions d’accueil dans les zones d’origine demeurent précaires en raison de la pauvreté chronique, des vulnérabilités préexistantes dans ces localités et de l’insuffisance de réponse adéquate, liées aux solutions durables et au développement ». Il est estimé qu’environ 70% des rapatriés ont des besoins humanitaires sévères (139 354 personnes) et 23% ont des besoins extrêmes (45 293 personnes), surtout dans les provinces Cankuzo et Ruyigi."},{"id":"a-hrc-48-crp-1-p0180","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"180","seq":180,"section":"C. Situation des rapatriés","text":"Selon l’équipe du HCR au Burundi, qui assure un suivi régulier de la protection des rapatriés depuis 2019, « la pression exercée par les gouvernements régionaux pour augmenter le rythme des retours a continué de s’intensifier ce qui a eu pour effet de surcharger la capacité d’accueil du HCR, en plus dépasser la capacité d’absorption dans les zones de retour ». Parmi les principaux défis relevés par le HCR, on relève l’accès à l’eau potable avec seulement 41% des personnes interrogées par le HCR qui y ont accès ; l’accès au logement, puisque seulement 36% des ménages rapatriés ont eu accès à leur ancienne maison à leur retour, la plupart ayant été dégradées ou détruites par les phénomènes climatiques ; ainsi que la sécurité alimentaire (seulement 19% des personnes interrogées ont déclaré être satisfaites du niveau de leur sécurité alimentaire, la très grande majorité se plaignant de quantités insuffisantes pour faire deux repas par jour et de la faible diversité alimentaire). En revanche, dans le domaine de l’accès aux soins, une majorité de rapatriés se sont déclarés satisfaits (58%), même si certains ont déclaré ne pas avoir les moyens financiers nécessaires pour se soigner."},{"id":"a-hrc-48-crp-1-p0181","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"181","seq":181,"section":"C. Situation des rapatriés","text":"Selon le HCR, de nombreux rapatriés n’étaient pas satisfaits de leurs conditions de vie et de leur situation après être rentrés au Burundi. Lors des exercices de suivi des rapatriés organisés en 2020, le HCR a constaté qu’environ 33% (4 698 ménages) ne se trouvaient plus dans leurs zones de retour respectives contre seulement 9% en 2019. Une telle situation est « probablement due à une combinaison de facteurs allant des difficultés à accéder aux opportunités socio-économiques, y compris le manque de moyens de subsistance, d’abris ou de terres au retour et après le retour, le manque d’accès aux écoles et aux services de santé, ou les problèmes de sécurité, y compris les conflits locaux, mais aussi le harcèlement, persécution et discrimination par les communautés locales ou autres »."},{"id":"a-hrc-48-crp-1-p0182","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"182","seq":182,"section":"C. Situation des rapatriés","text":"De plus, à l’instar du reste de la population, les disputes foncières et intrafamiliales ne trouvent pas de solutions satisfaisantes en raison notamment des dysfonctionnements du système judiciaire burundais. Dans le cadre de telles disputes privées impliquant des rapatriés, des Imbonerakure ont parfois été appelés pour « régler cette situation » par l’intimidation et la force ou lorsque des membres du parti au pouvoir étaient parties au litige, les rapatriés ont préféré abandonner leur plainte ou requête par crainte pour leur sécurité. \nc)\tSituation des femmes rapatriées"},{"id":"a-hrc-48-crp-1-p0183","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"183","seq":183,"section":"C. Situation des rapatriés","text":"Les ménages dirigés par des femmes sont encore plus vulnérables et rencontrent des difficultés spécifiques : les femmes qui n’étaient pas légalement mariées et qui sont revenues sans leur conjoint n’ont pas le droit de retourner dans leur ancienne maison/terre et sont sujettes à la discrimination ainsi qu’à des menaces verbales et physiques. Elles courent également des risques accrus d’exposition aux violences sexuelles, y compris le viol, le trafic humain, le mariage forcé, la prostitution forcée, les violences domestiques, etc., en raison notamment de leur situation de grande pauvreté conjuguée à la dégradation socio-économique du pays. Il est estimé que globalement entre 30% et 70% de femmes rapatriées et 9% de filles de rapatriées sont exposées à des risques accrus de violences fondées sur le genre, alors que l’État a l’obligation de protéger les femmes et les filles, notamment en agissant avec diligence pour prévenir ces actes de violence, en enquêtant sur ces actes et en punissant les auteurs.\nPar exemple, une femme a raconté la violence domestique dont elle a été victime à son retour au Burundi :\n« Mon mari venait de [X] et nous nous sommes rencontrés ici au camp. […] Mon mari ne me frappait pas [au camp] parce qu'on était proche de la famille. Ce n’est que quand nous sommes rentrés au Burundi qu'il a commencé à me frapper. […] Nous sommes arrivés au Burundi et puis il a complètement changé. Il a dit qu'il n’avait pas le temps de m'aider à m’occuper de l’enfant. […] Il a commencé à passer des nuits en dehors de notre maison sans me dire où il allait. Il a commencé à me montrer une autre face de lui que je ne connaissais pas. […] Après, l’argent qu’on nous avait donné pour le rapatriement, il a tout pris et il a disparu pendant trois mois. […] Il exigeait aussi que je quitte sa maison pour qu’il amène une femme de son ethnie […] Il me frappait avec des bâtons, y compris à la tête. Surtout il me frappait dans les côtes et le ventre en disant qu’il ne voulait pas que j’ai d'autres enfants ».\nd)\tSituation des enfants rapatriés"},{"id":"a-hrc-48-crp-1-p0184","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"184","seq":184,"section":"C. Situation des rapatriés","text":"Il est estimé qu’en 2021, 28 000 enfants rapatriés entre 2017 et 2020 auraient encore un besoin de protection, tout comme 52 000 enfants qui seront rapatriés en 2021. L’enregistrement à l’état civil et l’obtention de certificat de naissance sont des défis pour les familles en situation d’extrême précarité et qui ne sont souvent pas au courant des démarches à suivre ou font face à des obstacles matériels tels que le prix, la distance pour se rendre sur les lieux pour l’enregistrement, etc. En conséquence, au 31 août 2020, seulement 45% des enfants rapatriés depuis 2017 avaient reçu un certificat de naissance."},{"id":"a-hrc-48-crp-1-p0185","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"185","seq":185,"section":"C. Situation des rapatriés","text":"Les enfants rapatriés font souvent face à des difficultés d’adaptation sociale car leur situation a un impact sur leur santé psychologique, ce qui affecte leur scolarisation. Certains ont également des difficultés à s’inscrire à l’école en l’absence de documents d’état-civil. Effectivement, seulement 48% des enfants rapatriés sont inscrits à l’école, dont 34% à l’école primaire et 14% à l’école secondaire."},{"id":"a-hrc-48-crp-1-p0186","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"186","seq":186,"section":"1. Situation socio-économique et humanitaire","text":"La situation globale de la population burundaise en matière de jouissance de ses droits économiques et sociaux reste préoccupante comme l’indiquent les différents rapports et indices statistiques établis par diverses agences des Nations Unies. Pour rappel, l’Etat burundais a l’obligation, en vertu du droit international des droits de l’homme, de prendre des mesures positives pour faciliter l’exercice des droits de l’homme de sa population, y compris les droits à un niveau de vie suffisant, à l’alimentation, à la santé, etc. En 2020, le Burundi occupe la 185ième place sur les 189 pays classés sur l’indice de développement humain. Selon la Banque mondiale, en 2019, 83,4% de la population vivait sous le seuil de pauvreté (sur la base du seuil international de pauvreté de 1,90 dollar par habitant et par jour en 2011), avec un revenu annuel par habitant particulièrement bas de 260 dollars (contre 520 en République démocratique du Congo –RDC et 1 080 en Tanzanie). Pour rappel, c’était 72,8% de la population qui vivait sous le seuil de pauvreté en 2013 et il est estimé que ce taux atteindra 87,4% de la population en 2023.\na)\tSécurité alimentaire et nutrition"},{"id":"a-hrc-48-crp-1-p0187","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"187","seq":187,"section":"1. Situation socio-économique et humanitaire","text":"En 2020, les prix des denrées de base comme le haricot, le riz et le maïs ont augmenté, notamment en raison de la fermeture partielle des frontières décidée dans le cadre de la pandémie de Covid-19 et des diverses catastrophes naturelles qui ont affecté les récoltes. Par exemple, en juillet 2020, le prix des haricots a augmenté de 31% par rapport à 2019 et de 38% par rapport à la moyenne des cinq dernières années. Le prix du maïs a quant à lui augmenté de 13% par rapport à 2019."},{"id":"a-hrc-48-crp-1-p0188","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"188","seq":188,"section":"1. Situation socio-économique et humanitaire","text":"Selon l’aperçu des besoins humanitaires en 2021 préparé par le Bureau des Nations Unies pour la coordination des affaires humanitaires (OCHA), 2,3 millions de personnes au sein d’une population globale estimée à 12,6 millions sont dans le besoin d’assistance humanitaire, dont 661 000 en situation de besoin aigu. Parmi les personnes dans le besoin, 131 000 personnes sont des déplacés internes, 185 000 sont des rapatriés, 1,8 million sont des Burundais vulnérables et 95 000 des réfugiés de pays tiers, dont 50,8% sont des femmes, 56,7% sont des enfants et 15% des personnes vivant en situation de handicap."},{"id":"a-hrc-48-crp-1-p0189","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"189","seq":189,"section":"1. Situation socio-économique et humanitaire","text":"La majorité d’entre elles a des besoins relatifs à la sécurité alimentaire (2 millions de personnes), en matière de nutrition (704 000 personnes dont 63% d’enfants et 37% de femmes), de santé (578 000 personnes), d’accès à l’eau, à l’assainissement et à l’hygiène (540 000 personnes), de protection (450 000 personnes), de protection de l’enfance (243 000 personnes), d’accès à un abri (249 000 personnes), de violence basée sur le genre (176 000 personnes) et d’accès à l’éduction (157 000 personnes). Ces chiffres sont en légère évolution par rapport à 2020 où 1,7 million de personnes avaient besoin d’assistance humanitaire, dont 600 000 en situation de besoin aigu. Les domaines dans lesquels le nombre de personnes dans le besoin ont le plus augmenté par rapport à 2020 sont la sécurité alimentaire (2 millions de personnes en 2021 contre 1,7 million en 2020), la nutrition (700 000 personnes en 2021 contre 340 000 personnes en 2020) et l’éducation (160 000 personnes en 2021 contre 70 000 en 2020)"},{"id":"a-hrc-48-crp-1-p0190","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"190","seq":190,"section":"1. Situation socio-économique et humanitaire","text":"En effet, selon le Programme alimentaire mondial, seulement 28% de la population burundaise est en situation de sécurité alimentaire et 58% souffre de malnutrition chronique. En conséquence, 52% des enfants burundais de moins de cinq ans ont un retard de croissance (stunting rate) alors que le seuil d’alerte se situe à 40%. La Banque mondiale estime quant à elle que ce sont 57,5% des garçons burundais de moins de 5 ans et 50,7% des filles qui présentent un retard de croissance en 2019, pour une moyenne de 54% des enfants burundais. Pour rappel, les retards de croissance chez les enfants très jeunes ont des effets à long terme ; ils entrainent souvent des problèmes de santé et affectent le développement cognitif, la réussite scolaire, la productivité économique et la reproduction maternelle à l’âge adulte."},{"id":"a-hrc-48-crp-1-p0191","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"191","seq":191,"section":"1. Situation socio-économique et humanitaire","text":"La population fait régulièrement face à des pénuries de produits de consommation de base, notamment le carburant, le sucre, la farine de blé et l’huile de palme ou à l’augmentation de leur prix. Par exemple, la Société sucrière de Moso (Sosumo), l’entreprise publique en charge de la production de sucre, qui avait pourtant confirmé que le niveau de production avait quadruplé entre 1988 et 2020 passant de 4 658 tonnes à 20 436 tonnes, n’a pas été en mesure de répondre à la demande intérieure et a dû avoir recours à des importations. Le prix du sucre a donc grimpé jusqu’à 3 000 francs burundais au kilogramme (approximativement 1,53 dollar). Le Gouvernement a expliqué que ces hausses de prix étaient dues à la spéculation et il a décidé de fixer les prix de vente de certains produits agricoles et interdire les exportations, notamment d’huile de palme, y compris afin de constituer des stocks stratégiques.\nb)\tCatastrophes naturelles et déplacements internes"},{"id":"a-hrc-48-crp-1-p0192","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"192","seq":192,"section":"1. Situation socio-économique et humanitaire","text":"La situation humanitaire alarmante constatée au Burundi par les agences humanitaires des Nations Unies est liée en partie aux catastrophes naturelles récurrentes, notamment les pluies excessives entraînant des inondations et des glissements de terrain, mais également à la pandémie de Covid-19. Ces facteurs ont contribué à exacerber les vulnérabilités préexistantes et ont entraîné un accroissement du nombre de déplacés internes. C’est dans les provinces Cankuzo et Ruyigi, frontalières avec la Tanzanie, mais aussi la province Kirundo, frontalière avec le Rwanda, que les conditions humanitaires sont les plus graves et les personnes dans le besoin sont les plus nombreuses."},{"id":"a-hrc-48-crp-1-p0193","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"193","seq":193,"section":"1. Situation socio-économique et humanitaire","text":"En fait, le Burundi est un des pays parmi les plus vulnérables aux catastrophes naturelles, classé au 169ième rang sur 181 pays, étant « enclavé avec un relief accidenté et sujet à des inondations et glissements de terrain récurrents ». La pression croissante sur les ressources en eau et en sol, la faible couverture forestière (seulement 12% de terres boisées en 2016) ainsi que la faiblesse d’aménagement de certaines zones à risque d’inondations expliquent notamment la fréquence de ces catastrophes. Les provinces du nord (Ngozi, Kirundo), de l’ouest (Bubanza, Bujumbura) et du centre (Gitega) sont les plus vulnérables à ces catastrophes."},{"id":"a-hrc-48-crp-1-p0194","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"194","seq":194,"section":"1. Situation socio-économique et humanitaire","text":"Près de 100 000 personnes ont été ainsi affectées par des catastrophes naturelles en 2020 qui ont causé le déplacement de 44 222 d’entre elles. De nouveaux sites de déplacés ont dû être créés en raison de la stagnation prolongée des eaux dans les localités d’origine de ces déplacés (particulièrement à l’ouest du pays) qui empêchait leur retour. L’État burundais n’est évidemment pas responsable de ces phénomènes, mais il est dans l’obligation de protéger sa population.\nc)\tSituation médicale et sanitaire"},{"id":"a-hrc-48-crp-1-p0195","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"195","seq":195,"section":"1. Situation socio-économique et humanitaire","text":"Sur le plan sanitaire, le Burundi fait régulièrement face à la résurgence de maladies à potentiel épidémique comme le choléra et le paludisme. Toutefois, peu de cas de malaria et de choléra ont été enregistrés en 2020 par rapport à 2019 qui avait été marqué par une flambée épidémique de paludisme et une persistance du choléra. Seulement 70 cas de choléra ont été enregistrés de janvier à mai 2020 et seulement cinq districts sanitaires sur 47 étaient en état d’alerte concernant le paludisme. Le Burundi fait face néanmoins à une flambée importante de cas de rougeole."},{"id":"a-hrc-48-crp-1-p0196","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"196","seq":196,"section":"1. Situation socio-économique et humanitaire","text":"La précarité financière d’une grande partie de la population fragilise l’accès aux soins de santé de base et secondaires, et le réseau des structures médicales reste inadéquat en quantité et au niveau de la variété des soins prodigués. La durée de marche pour se rendre dans la structure de soins la plus proche est de moins de 30 minutes pour seulement 49% des Burundais. Il faut marcher entre 31 et 120 minutes pour 46% des ménages, et plus de deux heures pour 5% des ménages. Pour 20% des ménages vivant en milieu rural, le temps moyen se situe entre une et deux heures de marche."},{"id":"a-hrc-48-crp-1-p0197","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"197","seq":197,"section":"1. Situation socio-économique et humanitaire","text":"Face à cette situation, le Président Ndayishimiye a promis lors de son investiture, de doter chacune des 119 communes d’un hôpital. Il a demandé que soient identifiés les centres de santé existants dans les 116 communes sans hôpital qui pourraient devenir cet hôpital. Le Gouvernement a également prévu de réviser le prix de la carte d’assurance maladie (CAM) instaurée en 1984 avec un tarif unique de 3 000 Fbu (environ 1,50 dollar). Celle-ci va devenir gratuite pour les plus vulnérables, le prix restera de 3 000 Fbu pour les ménages avec les plus faibles revenus et augmentera à 25 000 Fbu (environ 12,5 dollars) pour les ménages à revenu moyen et à 100 000 Fbu (environ 51 dollars) pour les ménages plus aisés. Le Gouvernement a expliqué que l’objectif de cette mesure était d’améliorer l’accessibilité financière des populations aux soins de santé. Il reste à voir comment cette initiative sera mise en œuvre, notamment pour l’identification des personnes les plus vulnérables ou à faible revenu, et si ces dernières pourront enfin avoir un accès facilité à des services de santé de qualité."},{"id":"a-hrc-48-crp-1-p0198","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"198","seq":198,"section":"1. Situation socio-économique et humanitaire","text":"Face à la pandémie de Covid-19, le Président Ndayishimiye a immédiatement pris le contre-pied de son prédécesseur en déclarant que cette pandémie représentait un grand risque pour le pays. Au mois de mars 2021, le pays a adopté un plan national de riposte à la pandémie de Covid-19 pour la période avril-septembre 2021. Des mesures ont été prises pour essayer d’endiguer la propagation de la maladie, notamment en ayant recours aux tests de dépistage, en décidant de mettre en quarantaine les voyageurs, en fermant partiellement les frontières terrestres et aériennes, et en reprenant la coopération avec l’Organisation mondiale de la santé (OMS) dont le nouveau Représentant est arrivé au mois d’avril 2021."},{"id":"a-hrc-48-crp-1-p0199","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"199","seq":199,"section":"1. Situation socio-économique et humanitaire","text":"Selon le bilan publié par l’OMS, au 17 août 2021, la pandémie de Covid-19 aurait fait seulement dix morts pour un total de 10 198 cas enregistrés depuis le printemps 2020, bilan qui selon certains commentateurs serait sous-évalué. Le Burundi a longtemps refusé d’entreprendre la vaccination de sa population car selon le Président, les vaccins étaient « encore au stade expérimental » ou encore que cela n’était pas nécessaire puisque « la population observe scrupuleusement les mesures barrières contre la COVID-19 ». C’est seulement à la fin juillet 2021 que les autorités burundaises ont accepté du bout des lèvres un don de vaccins de la Banque mondiale et ont autorisé les Burundais qui le souhaitaient à se faire vacciner. Cependant, aucune campagne pour inciter à la vaccination n’a été organisée et le Gouvernement a clarifié qu’il refusait d’assumer la responsabilité des éventuels effets secondaires des vaccins. Au 17 août 2021, aucune information sur la vaccination n’était disponible sur le site officiel du ministère de la Santé du Burundi.\nd)\tSituation des femmes et égalité de genre"},{"id":"a-hrc-48-crp-1-p0200","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"200","seq":200,"section":"1. Situation socio-économique et humanitaire","text":"En matière d’égalité de genre, le Burundi figure à la 124ième place sur 162 de l’indice de l’inégalité de genre (IIG), qui indique la perte du développement humain imputable à l’inégalité entre les hommes et les femmes. Le score élevé du Burundi est principalement lié aux problèmes touchant la santé reproductive des femmes et des filles, et à leur faible autonomisation et participation au marché du travail. Malgré de nombreuses déclarations (et apparentes initiatives) des autorités burundaises en faveur de l’autonomisation de la femme et de la santé maternelle notamment, cet indice a peu évolué au cours des cinq dernières années, passant de 0,515 en 2015 à 0,504 en 2019. Concernant la santé de la reproduction, un taux important de mortalité maternelle persiste avec 334 décès pour 100 000 naissances contre une moyenne de 238 décès pour 100 000 naissances dans les pays en développement. Cela est dû notamment à l’insuffisance du plateau technique des services de santé."},{"id":"a-hrc-48-crp-1-p0201","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"201","seq":201,"section":"1. Situation socio-économique et humanitaire","text":"Il est estimé qu’en 2021, 176 000 personnes, dont 24 000 rapatriés, 25 000 déplacés internes et 127 000 autres personnes vulnérables qui pour 98% sont des femmes, auront besoin d’une assistance pour leur protection, notamment par rapport aux violences sexuelles et fondées sur le genre. Les acteurs humanitaires relèvent que la plupart des centres de santé ne disposent pas des ressources et capacités nécessaires (personnel formé et médicaments) pour prendre en charge de manière adéquate et spécifique les victimes de ces violences. Les services holistiques de première urgence pour les violences basées sur le genre à savoir médical, psychosocial, voire juridique et socio-économique, ne sont pas suffisants ni facilement accessibles avec seulement six centres intégrés opérationnels sur l’ensemble du pays dont la capacité opérationnelle est fortement diminuée depuis la fin du financement de la Banque mondiale. Si les autorités burundaises parviennent à couvrir certains besoins de la prise en charge psychosociale à travers les directions provinciales du développement familial et social, la prise en charge médicale et l’assistance juridique demeurent la responsabilité de la société civile ou des acteurs humanitaires. Il est difficile de garantir la gratuité des soins médicaux pour les survivantes de violences sexuelles et basées sur le genre."},{"id":"a-hrc-48-crp-1-p0202","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"202","seq":202,"section":"1. Situation socio-économique et humanitaire","text":"Les femmes et des filles qui vivent en situation de grande pauvreté font face à un risque accru d’exposition aux violences sexuelles telles que le viol, le trafic humain, le mariage forcé, la prostitution forcée et les violences domestiques. La dégradation de leurs conditions de vie entraîne également l’adoption de stratégies négatives de survie comme la prostitution, qui augmentent à leur tour le risque de violences sexuelles et fondées sur le genre. Dans un contexte général de pauvreté accrue et de manque de ressources affectées à la prise en charge holistique des violences sexuelles et basées sur le genre, plusieurs acteurs notent également une corrélation entre le niveau de pauvreté des survivantes (ou leur degré d’autonomie économique) et leur capacité à accéder aux services, soit en raison de la distance qui les sépare des centres de prise en charge, du caractère payant des soins ou de l’assistance ou encore de leur vulnérabilité aux pressions des auteurs ou de la communauté en cas de dénonciation des faits, particulièrement quand l’auteur dispose de moyens économiques et/ou d’une influence sociale relativement plus élevée.\ne)\tSituation des enfants et leur droit à l’éducation"},{"id":"a-hrc-48-crp-1-p0203","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"203","seq":203,"section":"1. Situation socio-économique et humanitaire","text":"Selon les estimations de certains acteurs humanitaires, plus de 160 000 enfants burundais de 3 à 16 ans, dont 80 000 filles, risquent de ne pas être scolarisés ou de subir des interruptions de leur cursus en 2021, dont 35 000 enfants déplacés internes, 27 000 enfants rapatriés et 95 000 enfants vulnérables des communautés d’accueil de ces populations. Cependant, les résultats préliminaires de l’étude sur les enfants et adolescents en dehors de l’école (EADE) de 2020 révèlent que ce sont 1,9 million d’enfants qui sont non scolarisés au Burundi, dont de nombreux enfants contraints d’abandonner l’école pour contribuer aux besoins de leur famille. Par exemple, plus de 50% des enfants âgés de 4 à 19 ans résidant dans les provinces frontalières avec la Tanzanie étaient déscolarisés en 2020."},{"id":"a-hrc-48-crp-1-p0204","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"204","seq":204,"section":"1. Situation socio-économique et humanitaire","text":"Le niveau élevé de pauvreté de leur famille, une offre éducative limitée tant au niveau des infrastructures que du nombre d’enseignants et un environnement d’apprentissage peu favorable, avec notamment une insuffisance de matériel pédagogique, d’eau et d’électricité sont les principales causes de la déscolarisation. Au cours de l’année scolaire 2019-2020, 1 609 salles de classe ont été détruites par les intempéries causant des interruptions des enseignements. Il y a en moyenne 75 élèves par salle de classe dans le pays mais jusqu’à 90 élèves par classe à Bujumbura (rural) et 133 enfants par classe dans la ville de Bujumbura (Mairie), ce qui crée des conditions peu propices à l’apprentissage, d’autant plus que souvent les enseignants n’ont pas de formation suffisante."},{"id":"a-hrc-48-crp-1-p0205","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"205","seq":205,"section":"1. Situation socio-économique et humanitaire","text":"Les violences en milieu scolaire, y compris les violences sexuelles, les grossesses précoces et non désirées sont également des obstacles spécifiques à l’éducation des filles. Au cours de l’année scolaire 2017-2018, 1 432 filles avaient eu des grossesses en cours de scolarité et 1 524 filles sont tombées enceintes au cours de l’année scolaire 2018-2019."},{"id":"a-hrc-48-crp-1-p0206","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"206","seq":206,"section":"1. Situation socio-économique et humanitaire","text":"Par ailleurs, on dénombre plus de 5 000 enfants en situation de rue dans les seules villes de Bujumbura, Gitega, Ngozi et Kayanza et ces chiffres ont tendance à augmenter régulièrement, résultat de la pauvreté et/ou des maltraitances au sein des communautés ou de leur famille."},{"id":"a-hrc-48-crp-1-p0207","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"207","seq":207,"section":"2. Principales violations des droits de l’homme contre la population","text":"Par le passé, la Commission a largement documenté la pratique très fréquente de demander à la population de verser sous la contrainte des contributions soi-disant volontaires, et parfois obligatoires, notamment au profit du parti au pouvoir CNDD-FDD et pour organiser les élections de 2020. Ces contributions, souvent sans base légale et dont il est quasi impossible de vérifier le montant global et leur utilisation, ont un impact direct sur le droit à un niveau de vie suffisant de la population dont la majorité vit dans une grande pauvreté."},{"id":"a-hrc-48-crp-1-p0208","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"208","seq":208,"section":"2. Principales violations des droits de l’homme contre la population","text":"Depuis l’investiture du Président Ndayishimiye, la population a continué à être contrainte de verser des contributions afin de financer des infrastructures publiques, contribuer au développement ou soutenir le parti au pouvoir, sous peine de se voir notamment refuser l’accès à des services ou des lieux publics, ou dénier l’octroi de documents administratifs. Le ministre de l’Intérieur, du Développement communautaire et de la Sécurité publique a lui-même reconnu et dénoncé l’existence de telles pratiques par certaines autorités communales et provinciales.\nUn témoin a expliqué :\n« Nous devons donner des contributions à des barrières où on te somme de donner de l’argent. Ce sont les Imbonerakure qui le demandent. On te remet une quittance et puis après tu ne dois plus la payer. Ils ont fait cela en janvier 2021. On a donné 500 Fbu [environ 0,25 dollar]. […] C'était déjà comme cela l’année passée. Il n’y avait pas de fréquence établie. Parfois on peut te demander 1 000 Fbu, puis trois mois après 500 Fbu. On te disait que c'était pour le développement ou leur parti. Si tu n’avais pas la somme, tu devais donner quelque chose en échange. Par exemple, des haricots. Je ne sais pas si ce sont des quittances officielles. […] Le montant est pour un ménage »."},{"id":"a-hrc-48-crp-1-p0209","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"209","seq":209,"section":"2. Principales violations des droits de l’homme contre la population","text":"Par exemple, une contribution « volontaire » a ainsi été organisée auprès de fonctionnaires dans au moins une province pour financer une compétition de football en l’honneur du feu Président Nkurunziza ; des personnes ont été menacées car elles ne donnaient pas suffisamment pour le CNDD-FDD ; le gouverneur de la province Cankuzo a obligé les fonctionnaires à acheter des pagnes pour célébrer la fête du travail ; des Imbonerakure sont passés de maison en maison pour récolter les « contributions volontaires » organisés au mois d’août 2021, à l’occasion des journées dédiées à la « solidarité locale » et à « la fête communale »."},{"id":"a-hrc-48-crp-1-p0210","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"210","seq":210,"section":"2. Principales violations des droits de l’homme contre la population","text":"Le gouverneur de la province Rumonge a déclaré être « en train de construire un nouveau bureau provincial. Cela sera un bâtiment en étages de deux niveaux. Dans les prévisions, le bureau va coûter environ 1,3 milliard de francs burundais [environ 666 000 dollars]. Mais, le constat est que ça va aller au-delà. […] L’argent vient premièrement de la population. Le deadline de paiement d’au moins 2 000 francs burundais [environ 1 dollar] par toute personne de Rumonge, ayant 18 ans, est fixé au 15 mai 2021. Des communiqués ont été faits, des réunions organisées. […] Recouvrement forcé ? Moi je n’ai pas encore entendu cela. Nous passons par des communiqués. Des chefs collinaires ont des reçus de paiement. Les administrateurs ne font que le suivi. […] En matière de développement, personne ne doit traîner les pieds. […] Ceux qui traînent les pieds sont pris comme des ennemis du développement. Dans ce genre de travaux, il n’y a pas de démocratie. Il faut le comprendre. Nous devons nous aligner. Tout le monde doit suivre »."},{"id":"a-hrc-48-crp-1-p0211","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"211","seq":211,"section":"2. Principales violations des droits de l’homme contre la population","text":"Le gouverneur de la province Muyinga a quant à lui déclaré être en train de faire construire un bureau de la province pour un montant de 1,8 milliard de francs burundais (environ 915 000 dollars) financé principalement par des contributions soi-disant volontaires. Dans cette même province, les travaux de construction de bureau de la commune Muyinga, bâti notamment grâce aux contributions « volontaires » de la population, ont été lancés le 21 août 2021.\nb)\tViolences commises par les Imbonerakure"},{"id":"a-hrc-48-crp-1-p0212","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"212","seq":212,"section":"2. Principales violations des droits de l’homme contre la population","text":"Depuis l’arrivée au pouvoir d’Évariste Ndayishimiye, le nombre d’incidents violents impliquant des Imbonerakure a diminué dans plusieurs provinces suite notamment à des ordres qui leur auraient été donnés à cet effet et l’appel du Président lui-même à ce qu’ils se concentrent sur le développement du pays et arrêtent de se substituer aux forces de l’ordre et de sécurité. Cependant, dans les régions frontalières et celles qui ont été le théâtre d’attaques armées depuis septembre 2020, ils sont restés mobilisés par les autorités pour assurer la sécurité, notamment au sein des comités mixtes de sécurité. Ils ont donc continué à commettre des violences, notamment lors des rondes nocturnes qui leur offrent par endroits l’occasion de dépouiller les personnes croisées. D’ailleurs, le 30 juin 2021, des forces de défense ont reçu un ordre écrit interne de s’appuyer sur les « mouvements politiques armés » afin de mettre hors d’état de nuire les bandes armées, ce qui est une reconnaissance quasi officielle du fait que la ligue des jeunes du CNDD-FDD est armée et agit en appui des forces de défense. Dans cette optique, des armes à feu auraient été distribuées aux Imbonerakure au cours des derniers mois. Par ailleurs, des Imbonerakure ont continué à harceler et intimider des personnes afin qu’elles rejoignent le parti au pouvoir, mais dans une moindre mesure que par le passé."},{"id":"a-hrc-48-crp-1-p0213","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"213","seq":213,"section":"2. Principales violations des droits de l’homme contre la population","text":"La Commission a reçu des allégations crédibles selon lesquelles des Imbonerakure seraient mécontents et frustrés par la nouvelle approche du Président Ndayishimiye, qui leur a fait perdre à la fois du pouvoir et surtout leur source principale de revenus. Certains seraient même en train de questionner leur loyauté au Président et au CNDD-FDD, avec le risque qu’ils ne deviennent des éléments libres, et à court et moyen terme, des forces criminelles difficilement contrôlables.\nc)\tArrestations arbitraires"},{"id":"a-hrc-48-crp-1-p0214","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"214","seq":214,"section":"2. Principales violations des droits de l’homme contre la population","text":"La Commission a reçu des allégations crédibles au sujet de cas d’arrestation arbitraire de citoyens burundais, notamment à l’occasion de montages juridiques. Par exemple, des personnes seraient régulièrement arrêtées lors de fouilles-perquisitions massives parce que leur cahier de ménage n’était pas à jour ou présentait une irrégularité minime, ou dans le cadre de disputes entre voisins, et elles devraient alors verser une somme d’argent aux policiers afin d’être libérées. \nd)\tCadavres retrouvés dans l’espace public"},{"id":"a-hrc-48-crp-1-p0215","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"215","seq":215,"section":"2. Principales violations des droits de l’homme contre la population","text":"De nombreux cadavres ont été régulièrement retrouvés dans l’espace public, notamment près d’axes routiers ou de cours d’eau. Les autorités locales ont continué à les inhumer immédiatement sans chercher à identifier les personnes décédées ni enquêter sur les causes du décès et les éventuels responsables, alors que la plupart des dépouilles présentaient des signes de mort violente. Selon la Ligue Iteka, 554 personnes, dont 118 femmes, auraient été tuées au cours de la première année au pouvoir du Président Ndayishimiye, parmi lesquelles 250 dont la dépouille a été retrouvée dans l’espace public."},{"id":"a-hrc-48-crp-1-p0216","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"216","seq":216,"section":"2. Principales violations des droits de l’homme contre la population","text":"En raison des carences graves des autorités face à ce phénomène, il est impossible de distinguer les cas constituant des violations du droit à la vie imputables à des agents de l’État ou des Imbonerakure, de ceux relevant du droit commun tels que des meurtres liés à des litiges fonciers ou familiaux ou des crimes crapuleux qui sont fréquents et commis en toute impunité, surtout lorsque les victimes appartiennent à un parti d’opposition. Le comportement des autorités constitue en lui-même une violation puisqu’en refusant d’ouvrir des enquêtes crédibles et impartiales sur ces cas, elles bafouent leur obligation de protéger les droits à la vie et à un recours utile. Leur silence persistant face à ce phénomène peut même être interprété comme un acquiescement implicite de ces pratiques, notamment lorsque les victimes n’appartiennent pas au CNDD-FDD."},{"id":"a-hrc-48-crp-1-p0217","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"217","seq":217,"section":"1. Dysfonctionnement persistant des institutions judiciaires","text":"Les nombreux dysfonctionnements de la justice constatés par le passé, notamment la corruption, le trafic d’influence, les interférences d’autorités diverses et de membres du CNDD-FDD, le non-respect des procédures et des délais légaux, la non-exécution des décisions de justice, notamment celles de remise en liberté à titre provisoire ou après un acquittement, ainsi que l’inertie dans certaines procédures perdurent. Les victimes de violations restent privées de voie de recours utile, des interventions ayant lieu pour protéger les auteurs proches du parti au pouvoir. Dans de nombreux cas, les victimes ou leurs proches ont fait l’objet de menaces et d’intimidations, ce qui les a découragés de poursuivre leurs démarches."},{"id":"a-hrc-48-crp-1-p0218","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"218","seq":218,"section":"1. Dysfonctionnement persistant des institutions judiciaires","text":"Le Président Ndayishimiye et son Gouvernement ont enfin pris conscience de ces problèmes et ont dénoncé notamment la corruption omniprésente, la lenteur des procédures et la non-exécution des décisions judiciaires. Par exemple, le Président de la République a déclaré que la réforme de la justice était l’une des priorités de son Gouvernement, avec comme principaux axes de réforme, celle du statut du Conseil supérieur de la magistrature, le rétablissement des conseils de notables collinaires et la fin du principe de l’action récursoire contre les fonctionnaires coupables d’infraction dans l’exercice de leur fonction. Le 2 octobre 2020, lors du lancement de l’année judiciaire 2020-2021, le Président de la Cour suprême, le Procureur général de la République et la ministre de la Justice ont souligné les défis légaux, matériels et humains auxquels le système judiciaire faisait face, notamment « la corruption, les abus de pouvoir de la part de certains hauts dignitaires, le manque de moyens tant matériels qu’humains, l’adaptation du système et du code pénal aux réalités actuelles, la perte des valeurs intrinsèques traditionnelles ». Le 27 juillet 2021, le Président du Sénat a demandé à l’appareil judiciaire de travailler pour le bien de la population « en évitant la corruption qui handicape le secteur judiciaire. Il a découragé le mauvais comportement de certains magistrats qui exigent les pots de vin aux justiciables et a requis des sanctions exemplaires à leur encontre ». Finalement, le 24 août 2021, à l’occasion d’une séance de moralisation sur la bonne gouvernance et le patriotisme à l’intention du corps de la justice Burundaise, le Président Ndayishimiye a déclaré qu’il était avéré que « ce secteur est gangrené par beaucoup de maux et imperfections notamment en rapport avec la corruption, les malversations économiques, etc. ». Il a même ajouté, « Partout où je vais je reçois plus de 1 000 doléances contre la justice par jour. Je les trouve fondées après analyse. Les investisseurs étrangers ne viennent plus au Burundi. Vous trouvez des stratagèmes pour les dépouiller de leur argent. Ils n’ont nulle part où se plaindre. Vous vous mettez en bande pour les escroquer de leur argent […] »."},{"id":"a-hrc-48-crp-1-p0219","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"219","seq":219,"section":"1. Dysfonctionnement persistant des institutions judiciaires","text":"Cependant, au lieu de prendre des mesures structurelles, telles que celles recommandées par la Commission pour remédier à ces problèmes, les autorités burundaises ont préféré s’attaquer au principe même de l’indépendance de la justice, y compris au principe de l’inamovibilité des magistrats. En juillet 2021, la ministre de la Justice, Jeanine Nibizi, a souligné que « le Gouvernement \"ne tolérera jamais les juges et magistrats qui se cachent derrière le privilège d’indépendance de la magistrature pour prendre des décisions hâtives, qui sont en dehors de la loi à cause de la corruption ou du favoritisme\". Elle a également saisi cette opportunité pour mettre en garde les juges de Gisuru contre ces manquements. Elle les a exhortés de dire le droit, de faire en sorte que les jugements soient rendus conformément à la loi et de mettre rapidement en exécution les procès déjà clôturés ». En août 2021, la ministre a réitéré ses critiques et menaces à peine voilées contre les magistrats, lors de sa visite à la prison de Gitega qui venait de brûler partiellement. De telles décisions et déclarations ne peuvent que contribuer à saper encore plus le système judiciaire mais également l’état de droit."},{"id":"a-hrc-48-crp-1-p0220","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"220","seq":220,"section":"2. Contrôle renforcé de l’Exécutif sur le Judiciaire","text":"Le 23 janvier 2021, une nouvelle loi a été promulguée, qui instaure un conseil de notables au niveau de chaque colline. Ce conseil, dont les 15 membres sont élus pour une durée indéterminée, a pour mission de recevoir les plaintes et donner son avis sur toutes les affaires civiles relevant de la compétence des tribunaux de résidence, et de procéder à la conciliation entre les parties en conflit lorsque le litige ne relève pas « de l’ordre public et ne touche pas aux bonnes mœurs ». Il peut également « aplanir un conflit résultant d’une infraction » en décidant de l’octroi de dommages-intérêts. Le conseil ne peut toutefois pas prononcer de peines. L’accord obtenu et homologué à l’issue de la procédure de conciliation devient exécutoire et a valeur d’un jugement définitif. En cas d’échec de la conciliation ou lorsque l’une des parties au litige s’estime lésée, elle peut saisir le tribunal de résidence qui n’est pas lié par l’avis du conseil de notables, mais doit motiver l’éventuel rejet de cet avis. Un tribunal de résidence saisi d’une affaire civile doit s’assurer préalablement que le conseil de notables a bien été saisi de l’affaire."},{"id":"a-hrc-48-crp-1-p0221","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"221","seq":221,"section":"2. Contrôle renforcé de l’Exécutif sur le Judiciaire","text":"Une nouvelle juridiction de premier degré a donc été créée pour les affaires civiles au niveau des collines, avec des « notables » désignés par la voie élective, ce qui entraîne de facto une politisation de la justice. Le système politique étant totalement dominé par le parti au pouvoir, les futurs conseils de notables seront sans surprise dominés par le CNDD-FDD, voire composés à grande majorité des responsables administratifs collinaires, estompant ainsi la frontière entre l’Exécutif et le Judiciaire. S’il est vrai que les tribunaux de résidence sont effectivement gangrénés par la corruption et le trafic d’influence, aucune disposition particulière n’a été prise pour veiller à ce que de telles pratiques ne soient pas répliquées au sein des conseils de notables."},{"id":"a-hrc-48-crp-1-p0222","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"222","seq":222,"section":"2. Contrôle renforcé de l’Exécutif sur le Judiciaire","text":"Une autre grande réforme du Président Ndayishimiye est la révision du Conseil supérieur de la magistrature (CSM), avec la promulgation le 23 janvier 2021 de la loi organique portant révision de la loi organique numéro 1/13 du 12 juin 2019 portant organisation et fonctionnement du Conseil supérieur de la magistrature. Cette loi accroît et institutionnalise la possibilité pour l’Exécutif de contrôler le Judiciaire. Elle attribue au CSM, en plus de ses missions traditionnelles de « veiller au bon fonctionnement de toutes les institutions judiciaires » et de gestion des carrières des magistrats, la capacité d’« enjoindre les organes compétents d’engager des poursuites en cas d’infraction et en faire le suivi ; contrôler la qualité des jugements, arrêts et autres décisions judiciaires dénoncées ou portées à la connaissance du Conseil ainsi que leurs mesures d’exécution ». De plus, selon l’article 5 de la loi, « lorsqu’aucune voie de recours judiciaire n’est plus ouverte en faveur du requérant, le Conseil supérieur de la magistrature, s’il estime le recours recevable, peut prendre toute mesure de redressement notamment pour cause d’intérêt social évident »."},{"id":"a-hrc-48-crp-1-p0223","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"223","seq":223,"section":"2. Contrôle renforcé de l’Exécutif sur le Judiciaire","text":"Lors de la présentation du projet de loi à l’Assemblée nationale, la ministre de la Justice a expliqué qu’il était important de réformer le CSM afin de lui permettre, « dans certaines conditions rigoureuses, selon les circonstances de la cause », de prendre toute mesure de redressement contre une « décision judiciaire notoirement injuste » qui consacre « une iniquité révoltante » alors même qu’elle est «  juridiquement sans reproches » et cela « bien qu’elle soit coulée en force de chose jugée ». Elle a ajouté que ce pouvoir devait s’exercer notamment pour les jugements rendus par les cours et tribunaux dans des dossiers qui ont été difficiles à exécuter et qui peuvent causer des troubles sociaux."},{"id":"a-hrc-48-crp-1-p0224","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"224","seq":224,"section":"2. Contrôle renforcé de l’Exécutif sur le Judiciaire","text":"Force est de constater que le Conseil supérieur de la magistrature, organe dirigé et dominé par l’Exécutif, a désormais la capacité de recevoir des recours contre des décisions judiciaires pourtant rendues en dernière instance et de réviser ces dernières. La condition établie, non exclusive, de « cause d’intérêt social évident » est suffisamment vague et extensive pour lui permettre de se saisir de n’importe quelle affaire."},{"id":"a-hrc-48-crp-1-p0225","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"225","seq":225,"section":"2. Contrôle renforcé de l’Exécutif sur le Judiciaire","text":"Cette loi a lancé un mouvement global qui tend à institutionnaliser le contrôle de la Justice par l’Exécutif. Vers la fin du mois de juillet 2021, le gouverneur de la province Bujumbura (rural) a ainsi annoncé vouloir contrôler les décisions judiciaires rendues et leur exécution. Après avoir rappelé le principe de double degré de juridiction existant au Burundi, le gouverneur a indiqué ne pas vouloir que cette possibilité de faire appel « soit une source d’injustice créant ainsi des procès interminables ». Il ajoute « Nous profitons de cette occasion pour attirer l’attention de juges qui rendent des procès à leur guise sous prétexte de ce principe [de droit d’appel] que des mesures administratives seront prises à leur encontre ». Après avoir cité des problèmes de fonctionnement récurrents constatés au sein des tribunaux, notamment dans les nombreux cas de litiges fonciers, le gouverneur déclare « Afin de donner suite aux plaintes reçues au cabinet qui sont liées aux jugements mal rendus et à la mauvaise exécution des sentences, il est recommandé au président du tribunal de grande instance et au procureur de se présenter au cabinet du gouverneur une fois le mois pour une délibération conjointe avec le cabinet du gouverneur »."},{"id":"a-hrc-48-crp-1-p0226","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"226","seq":226,"section":"2. Contrôle renforcé de l’Exécutif sur le Judiciaire","text":"À peu près à la même période, en réponse aux plaintes de la population sur le fonctionnement de la justice, la ministre de la Justice a destitué plusieurs juges au cours de descentes sur le terrain et elle a menacé d’en destituer d’autres. Elle a également « mis en garde les magistrats qui partagent des messages sur les réseaux sociaux menaçant d’organiser des grèves suite aux récentes décisions du ministre de destituer certains magistrats. Elle a précisé que les magistrats qui se cachent derrière l’aspect de l’indépendance de la magistrature et qui exécutent des jugements en dehors de la loi, vont être bientôt limogés de leurs fonctions »."},{"id":"a-hrc-48-crp-1-p0227","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"227","seq":227,"section":"2. Contrôle renforcé de l’Exécutif sur le Judiciaire","text":"En juillet 2021, le Président de l’Assemblée nationale, Gélase Ndabirabe, a critiqué le principe même de l’indépendance de la Justice et il a même recommandé que les dossiers politiques et sensibles soient traités dans les comités mixtes de sécurité."},{"id":"a-hrc-48-crp-1-p0228","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"228","seq":228,"section":"2. Contrôle renforcé de l’Exécutif sur le Judiciaire","text":"Face à de telles dérives, le 29 juillet 2021, le ministre de l’Intérieur, de la Sécurité publique et du Développement communautaire, Gervais Ndirakobuca, a dû rappeler à l’ordre les responsables administratifs : « \"Ne vous ingérez pas dans le judiciaire. Il y a des choses qui sont en train de faire du bruit dans la justice. Des lettres écrites par le gouverneur de Bujumbura et celui de Bururi avançant que vous êtes en train d’exécuter mes recommandations\". Il a souligné qu’il n’existe pas d’ordres du ministre de l’Intérieur qui viennent se substituer à la justice. \"Nous savons nos limites. Ce qui se trouve dans les mains de la justice reste là\". Selon le ministre Ndirakobuca, un administratif peut seulement orienter un citoyen, un préjudiciable. \"Mais ne vous substituez pas à la justice. C’est impossible. Le pays tomberait dans un chaos. Est-ce que vous me saisissez ? Le pays serait l’anarchie. La justice reste indépendante\" »."},{"id":"a-hrc-48-crp-1-p0229","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"229","seq":229,"section":"3. Abolition des institutions judiciaires anti-corruption","text":"Une autre réforme phare du système judiciaire entreprise par le Gouvernement du Président Ndayishimiye est très controversée, à savoir l’abolition des institutions spécialisées de lutte contre la corruption. Le 29 avril 2021, l’Assemblée nationale a adopté le projet de loi organique présenté par la ministre de la Justice visant à supprimer la Cour spéciale et la Brigade spéciale anti-corruption, officiellement afin « de rapprocher la justice pénale anti-corruption des justiciables ». La ministre a précisé que ces institutions spécialisées nécessitaient des moyens matériels et humains colossaux pour leur fonctionnement alors que leurs résultats restaient mitigés. Des sections anti-corruption doivent donc être instituées au sein des parquets et parquets-généraux, tout comme des chambres anti-corruption auprès des tribunaux de grande instance et des cours d’appels. La ministre a expliqué aux députés que « la compétence matérielle de la chambre anti-corruption du tribunal de grande instance en matière de lutte contre la corruption et les infractions connexes est limitée aux auteurs et complices de la corruption et des infractions qui lui sont connexes dont la valeur ne dépasse pas 100 millions de francs burundais. Les auteurs de la corruption notamment seront jugés par leur juge naturel, le juge qui lui est proche en l’occurrence la chambre anti-corruption du tribunal de grande instance. […] les missions qui étaient confiées à la brigade spéciale anti-corruption reviennent à une unité spécialisée anti-corruption créée au sein de la police judiciaire »."},{"id":"a-hrc-48-crp-1-p0230","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"230","seq":230,"section":"3. Abolition des institutions judiciaires anti-corruption","text":"Cette décision est intervenue après que le ministère de la Bonne gouvernance, qui auparavant supervisait ces instances anti-corruption spécialisées, ait été supprimé par le Président Ndayishimiye. La raison qui avait été donnée était que la « bonne gouvernance » était désormais l’affaire de tous."},{"id":"a-hrc-48-crp-1-p0231","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"231","seq":231,"section":"3. Abolition des institutions judiciaires anti-corruption","text":"Le projet d’abolir les instances judiciaires spécialisées contre la corruption a été accueillie avec beaucoup de réserve par des membres de la société civile qui doutent de son bien-fondé. L’OLUCOME, organisation de la société civile spécialisée sur les questions de corruption et de malversations économiques, a dénoncé cette loi comme marquant un profond recul en matière de lutte contre la corruption et une violation de la Convention des Nations Unies contre la corruption."},{"id":"a-hrc-48-crp-1-p0232","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"232","seq":232,"section":"3. Abolition des institutions judiciaires anti-corruption","text":"Le 14 juin 2021, la Cour constitutionnelle, qui avait été saisie par le Président Ndayishimiye pour contrôler la conformité du projet de loi organique portant suppression des institutions anti-corruption à la Constitution, l’a déclaré non-conforme, mais seulement pour des questions de forme. Selon la Cour, la suppression de la Cour et du Parquet anti-corruption doit être faite par le biais d’une loi ordinaire et la suppression de la Brigade anti-corruption nécessite de réviser la loi organique portant création d’unités spécialisées de la police. La Cour a souligné que le Gouvernement avait toute la latitude pour remédier à ces problèmes de forme et adopter des projets de loi conformes. Il reste à voir si le Gouvernement va aller de l’avant avec son projet."},{"id":"a-hrc-48-crp-1-p0233","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"233","seq":233,"section":"4. Instrumentalisation de cas emblématiques","text":"Le manque d’indépendance de la justice burundaise est un problème qui remonte à de nombreuses années. Cependant, rarement l’instrumentalisation du système judiciaire à des fins politiques, rendue possible par le contrôle étroit exercé par l’Exécutif à son égard, n’est apparue aussi clairement que depuis l’arrivée au pouvoir du Président Ndayishimiye."},{"id":"a-hrc-48-crp-1-p0234","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"234","seq":234,"section":"4. Instrumentalisation de cas emblématiques","text":"Le cas du défenseur des droits de l’homme Germain Rukuki illustre parfaitement de telles pratiques ; la chronologie des dernières décisions judiciaires le concernant est particulièrement troublante. Le 26 avril 2018, il avait été arbitrairement condamné à 32 ans de prison pour atteinte à la sûreté de l’État en raison de ses activités légitimes au sein d’une organisation de la société civile. Le 30 juin 2020, soit 12 jours après l’investiture du Président Ndayishimiye, la Cour suprême a décidé de casser la décision prise en appel le 17 juillet 2019 qui confirmait sa condamnation. Son deuxième procès en appel a tardé à se tenir, et il n’a été organisé que le 24 mars 2021, après la reprise du dialogue avec l’Union européenne qui inclut la question de la levée des sanctions. La deuxième décision en appel aurait dû être rendue au plus tard le 24 avril 2021 conformément au délai d’un mois imparti par le Code de procédure pénale. Cependant, elle n’a été rendue publique que le 21 juin 2021 – quelques heures après l’annonce du lancement de la procédure de levée des sanctions de l’Union européenne, mais ce n’est qu’une semaine plus tard, après diverses pressions et interventions, qu’il sera effectivement libéré."},{"id":"a-hrc-48-crp-1-p0235","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"235","seq":235,"section":"5. Absence d’avancée dans la lutte contre l’impunité","text":"Dans ses rapports précédents, la Commission avait constaté que les principaux auteurs des violations commises depuis 2015 bénéficiaient d’une impunité quasi systématique, y compris dans les cas les plus graves d’exécution sommaire, disparition forcée, torture et violences sexuelles et que les victimes de violations des droits de l’homme étaient privées de voies de recours utiles offertes, car elles étaient découragées de porter plainte n’en voyant pas l’utilité, en raison des dysfonctionnements du système judiciaire, ou parce qu’elles avaient peur des représailles si elles le faisaient."},{"id":"a-hrc-48-crp-1-p0236","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"236","seq":236,"section":"5. Absence d’avancée dans la lutte contre l’impunité","text":"Aucun progrès significatif en matière de lutte contre l’impunité depuis l’investiture du Président Ndayishimiye n’a été enregistré. Au-delà des facteurs liés aux dysfonctionnements du système judiciaire, l’impunité généralisée est principalement due au manque de volonté politique des autorités burundaises au plus haut niveau. Tant que le Président Ndayishimiye et son Gouvernement continueront à nier que des violations aient été commises depuis 2015 et à rejeter le principe même de dialogue sur les questions relatives aux droits de l’homme au Burundi, il est difficile de concevoir comment il pourrait y avoir un quelconque progrès dans la lutte contre l’impunité pour les violations passées et présentes, alors que cela constitue pourtant une des clefs pour améliorer la situation globale des droits de l’homme dans le pays."},{"id":"a-hrc-48-crp-1-p0237","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"237","seq":237,"section":"5. Absence d’avancée dans la lutte contre l’impunité","text":"Les premières condamnations de l’été 2020 n’ont pas vraiment été suivies par d’autres qui auraient marqué une rupture significative avec le passé. Certes, quelques policiers et militaires ont été condamnés pour des crimes de droit commun, souvent commis sous l’emprise de l’alcool, et des Imbonerakure ont été arrêtés pour des violations graves, mais plusieurs ont été par la suite libérés et/ou « punis » en interne. Pour ceux qui restent détenus, il reste encore à voir si les procédures aboutiront."},{"id":"a-hrc-48-crp-1-p0238","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"238","seq":238,"section":"5. Absence d’avancée dans la lutte contre l’impunité","text":"Des agents du SNR et assimilés, connus pour leur implication dans de nombreuses violations des droits de l’homme, auraient été arrêtés et détenus. Toutefois, l’opacité entourant ces procédures ne permet pas de savoir si cela est lié à leurs actions passées, à d’autres crimes et délits ou relève plutôt d’un règlement de compte en interne."},{"id":"a-hrc-48-crp-1-p0239","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"239","seq":239,"section":"F. Fondements économiques de l’État","text":"Conformément à son mandat, la Commission a poursuivi ses enquêtes sur les fondements économiques de l’État burundais, puisque ceux-ci ont un impact sur la situation des droits de l’homme dans le pays. Dans son rapport précédent, la Commission avait documenté que la corruption, des détournements de fonds publics et des conflits et des prises illégales d’intérêts sous-tendaient le fonctionnement de l’économie burundaise. Les malversations économiques, telles que la corruption et les détournements de fonds, diminuent les ressources disponibles qui sont nécessaires à l’État pour garantir les droits économiques, sociaux et culturels de sa population, notamment les droits à un niveau de vie suffisant, à la nourriture, à la santé, à l’éducation, à la protection sociale et au travail, alors que la majorité des Burundais vit dans une situation de grande pauvreté. Les ressources de l’État sont également nécessaires à la protection et la promotion des droits civils et politiques, par exemple pour permettre le bon fonctionnement des systèmes judiciaire, pénitentiaire et électoral. Lutter contre la corruption et les autres malversations économiques fait donc partie des obligations de l’État burundais en vertu du droit international."},{"id":"a-hrc-48-crp-1-p0240","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"240","seq":240,"section":"F. Fondements économiques de l’État","text":"La Commission tient à souligner que toutes ses constatations sur les fondements économiques de l'État rapportées précédemment restent entièrement valables. Au cours du présent terme, la Commission a concentré ses enquêtes sur la lutte contre la corruption menée par les autorités burundaises. Elle s’est intéressée également à la question des concessions minières dont les contrats viennent d’être remis en cause par le Président Ndayishimiye et son Gouvernement."},{"id":"a-hrc-48-crp-1-p0241","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"241","seq":241,"section":"1. Situation économique et financière du Burundi – Mise à jour","text":"En 2020, les principaux indicateurs économiques ont baissé, notamment en raison de la pandémie de Covid-19. La croissance économique du pays a été estimée à 0,3% en 2020 contre 1,8% en 2019. Cette croissance économique stagnante a été caractérisée par un ralentissement de la production agricole. Le produit intérieur brut (PIB) est passé de 3,01 milliards de dollars en 2019 à 3,25 milliards en 2020. La pandémie a touché l’industrie et les services, dont la production a baissé respectivement de 4,5% et 1,8% par rapport à 2019. Concernant la demande, les investissements ont baissé d'environ 3%. La chute de la production agricole, conjuguée à la hausse des prix des produits importés, a entraîné une forte augmentation des prix. L'inflation a augmenté de 8,5 points en 2020, passant à 7,6% contre -0,7% en 2019."},{"id":"a-hrc-48-crp-1-p0242","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"242","seq":242,"section":"1. Situation économique et financière du Burundi – Mise à jour","text":"Le déficit du compte courant s'est établi à 19,1% du PIB, contre un déficit de 17,8% en 2019. Cela s'est traduit par une réduction des réserves de change, qui pourraient couvrir moins de 30 jours d'importations dans le pays à la fin de 2020. Le taux de change officiel entre le franc burundais et le dollar américain a baissé de 3,8% entre mai 2019 et mai 2020. La faiblesse de la demande mondiale ayant entraîné une baisse de 4,4% des prix à l’exportation du café et de 10,4% pour le thé, les déficits commerciaux et courants se sont aggravés."},{"id":"a-hrc-48-crp-1-p0243","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"243","seq":243,"section":"1. Situation économique et financière du Burundi – Mise à jour","text":"Le budget total de l’État a augmenté de 4,7% en 2020-2021, passant de 1648,8 millions de francs burundais (approximativement 856,5 millions dollars) par rapport au budget de l’année précédente 2019-2020 (1 574,9 milliards de francs burundais (environ 805 millions de dollars). Le budget alloué au secteur social représentait presque la moitié du budget total de l’État est passé de 44,8% à 48,4% sur la même période, cette augmentation a été surtout notable dans le secteur de la santé. Le déficit budgétaire a doublé pour atteindre 8,7% du PIB en 2020, contre 4,2% en 2019, les dépenses courantes ayant augmenté d’environ 4%."},{"id":"a-hrc-48-crp-1-p0244","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"244","seq":244,"section":"1. Situation économique et financière du Burundi – Mise à jour","text":"Les organismes de financement internationaux soutiennent des programmes d’assistance socio-économique importants pour la population burundaise. Le processus de financement d’un projet, pour être conforme aux pratiques acceptées de coopération internationale et de gestion financière, doit comprendre un certain nombre d’étapes, telles que la sélection des partenariats, une évaluation des risques, la réalisation d’audits internes et externes, l’évaluation des performances. Les organismes contactés par la Commission n’ont pas partagé d’informations indiquant qu’il y aurait eu des cas spécifiques de corruption ou de détournement de fonds par des partenaires locaux en charge de la mise en œuvre de leurs projets. Cependant, étant donné que la corruption reste un problème majeur, et tout en reconnaissant l’importance et la valeur des mécanismes déjà mis en place pour adresser les possibles allégations de corruption et de détournement de fonds, la Commission souligne qu’une approche plus proactive mériterait d’être considérée par les organismes de financement internationaux afin d’encore mieux prévenir les risques."},{"id":"a-hrc-48-crp-1-p0245","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"245","seq":245,"section":"2. Corruption","text":"Parmi les facteurs qui facilitent les pratiques de petite corruption qui empoisonnent la vie quotidienne de la population burundaise, on peut relever l’établissement par les autorités d’innombrables règles et règlements encadrant l’obtention de licences, de permis, l’enregistrement d’une nouvelle entreprise, la demande d’un prêt, la réalisation d’un investissement, la conduite ou la possession d’une voiture, l’obtention de devises étrangères, l’obtention d’un passeport, ainsi que les nombreuses autres activités qui nécessitent des documents ou des autorisations spécifiques. En effet, certains agents de l’État exercent de facto un monopole de pouvoir pour autoriser, retarder ou refuser l’approbation ou la délivrance des documents. La délivrance rapide de documents juridiques tels que les passeports ou les documents d’identités ou relatifs au foncier, l’obtention de permis, ainsi que la rapidité de leur délivrance, dépendront du paiement d’un pot-de-vin. De nombreuses personnes deviennent alors des intermédiaires ou des facilitateurs entre les citoyens et ces agents publics.\nPar exemple, un témoin qui avait des difficultés à faire enregistrer son mariage a expliqué :\n« J’ai demandé conseil et on m’a dit que ce serait mieux si je me rendais au bureau communal avec un peu d’argent et la fois suivante, je suis parti avec 17 000 Fbu [environ 8,5 dollars] que j’ai remis et on m’a inscrit. Rien n’aurait été fait si je n’avais pas donné cet argent. En fait tous les services que tu dois effectuer doivent se faire contre paiement. J’ai eu le même problème pour obtenir les documents pour ma moto, pour le contrôle technique. En fait il y a des commissionnaires qui sont chargés de t’aider avec ça, tu leur donnes de l’argent et ils s’en occupent et tu ne sais pas d’où c’est venu »."},{"id":"a-hrc-48-crp-1-p0246","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"246","seq":246,"section":"2. Corruption","text":"Le Président Ndayishimiye et son Gouvernement, reconnaissant le problème, ont fait de la lutte contre la corruption et la mauvaise gouvernance une priorité. Par exemple, le ministre de l’Intérieur, du Développement communautaire et de la Sécurité publique a dénoncé la pratique de certains conseillers communaux d’exiger des frais constituant des pots de vin pour la signature des documents liés à la vente de propriétés foncières et d’immeubles. Dans cette communication, il a également critiqué la pratique de certaines autorités communales et provinciales d’exiger des frais à titre de contribution au développement comme condition pour l’octroi des documents administratifs."},{"id":"a-hrc-48-crp-1-p0247","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"247","seq":247,"section":"2. Corruption","text":"À cet égard, la Commission rappelle ses constatations au sujet des contributions forcées par des Imbonerakure et des responsables administratifs locaux, pratique persistante et répandue qui relève principalement de l’extorsion, mais également dans certains cas qui impliquent les autorités administratives, de la corruption."},{"id":"a-hrc-48-crp-1-p0248","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"248","seq":248,"section":"2. Corruption","text":"Cependant, jusqu’à présent, les réformes entreprises par le Gouvernement burundais ont été plutôt modestes, voire contestables, comme le projet de supprimer les institutions anti-corruption spécialisées. Une fois encore, ce sont surtout des gestes symboliques qui ont été posés, comme la destitution le 1er mai 2021 de la ministre du Commerce, du Transport, de l’Industrie et du Tourisme, dont les actes risquaient « de compromettre l’économie du pays ». La ministre aurait été soupçonnée de détournements de fonds et accusée d’avoir vendu le dernier avion de la compagnie Air Burundi sans l’accord des autorités burundaises, mais aussi d’avoir mal géré des fonds destinés à la fusion de Air Burundi et la SOBUGEA. Le nouveau ministre du Commerce nommé le 12 mai 2021 a fait annuler le contrat de vente de l’avion en question. De même, au printemps 2021, des percepteurs et comptables communaux accusés de détournement de fonds ont été limogés de manière collective, sans que des enquêtes approfondies ni des poursuites judiciaires ne soient ouvertes. L’effet dissuasif de telles décisions reste à prouver alors que ces sanctions collectives laissent un sentiment d’arbitraire."},{"id":"a-hrc-48-crp-1-p0249","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"249","seq":249,"section":"2. Corruption","text":"Par ailleurs, le ministre de l’Intérieur, du Développement communautaire et de la Sécurité publique a interdit les collectes obligatoires pratiquées par les associations de transporteurs sur les parkings. Ces dernières avaient été dénoncées comme abusives, puisque les chauffeurs et autres employés du secteur ne pouvaient jamais bénéficier du soutien financier de ces associations en cas de besoin."},{"id":"a-hrc-48-crp-1-p0250","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"250","seq":250,"section":"2. Corruption","text":"Toutes ces actions ont néanmoins été saluées comme des mesures encourageantes par l’organisation PARCEM. Cette dernière recommande d’établir également des stratégies en amont pour garantir la transparence dans la gestion des fonds collectés surtout au niveau de la gestion des marchés publics, l’enrichissement illicite, et la gestion des deniers publics."},{"id":"a-hrc-48-crp-1-p0251","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"251","seq":251,"section":"2. Corruption","text":"Le Chef de l’État a parfois affiché une attitude ambiguë en matière de lutte contre la corruption, en tergiversant sur la déclaration de biens des mandataires publics pourtant prévue par la Constitution ou en déclarant que seuls les cas de corruption commis après son investiture feraient l’objet d’enquêtes, consacrant de facto l’impunité pour les faits antérieurs. Selon lui, il serait contre-productif de remuer le passé : « parce que si on poursuit ceux qui ont pillé les biens publics au cours des dernières années, on va perdre du temps dans les enquêtes, on ne va plus travailler et le pays va devenir plus pauvre. Aujourd’hui, je dis : ceux qui ont volé, c’est fait. On va mettre votre cas devant la Commission vérité et réconciliation […] »."},{"id":"a-hrc-48-crp-1-p0252","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"252","seq":252,"section":"2. Corruption","text":"Pendant l’été 2021, il a également déclaré lors d’une séance de prière du CNDD-FDD, que pour mieux combattre la corruption et en même temps contribuer au développement du pays, il accepterait désormais tous les pots-de-vin qui lui seraient offerts : « Si tu es généreux, n’hésite surtout pas à me donner un pot-de-vin. J’ai pris la décision de ne plus refuser un pot-de-vin. Je prendrai l’argent et je l’utiliserai pour construire des écoles. Puis je ne lui donne pas ce qu’il cherche. Ce n’est pas compliqué. C’est le seul moyen de combattre la corruption. […] Une fois que tu as pris le pot de vin, tu l’utilises pour construire des écoles et tu diras à la personne : \" tu n’auras pas ce que tu cherches\". Qu’il aille donc se plaindre que je lui ai pris de l’argent ! Je sais comment vaincre la corruption : tu laisses les gens faire mais tu t’assures que rien n’en sort. »."},{"id":"a-hrc-48-crp-1-p0253","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"253","seq":253,"section":"2. Corruption","text":"En l’état actuel des choses et en l’absence de réforme structurelle crédible, la Commission considère qu’elle a des motifs raisonnables de croire que la corruption continue à être endémique au Burundi, aussi bien celle qui affecte la population dans sa vie quotidienne que la grande corruption. Par exemple, des barrières continueraient d’être érigées par la police à l’intérieur du pays pour obliger les conducteurs à leur verser de l’argent pour éviter une amende, y compris lorsqu’il n’y a pas d’infraction routière avérée, pratique qui aurait même augmenté depuis le début de la pandémie de Covid-19."},{"id":"a-hrc-48-crp-1-p0254","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"254","seq":254,"section":"3. Développements concernant le secteur minier","text":"Le sous-sol burundais abrite une importante richesse en termes de ressources minérales, notamment de l’or, du nickel (environ 5% des réserves mondiales), des Terres rares, du tantale, de l’étain, du tungstène, des minéraux industriels comme le kaolin, des phosphates, des carbonates, du vanadium, du calcaire et de la tourbe. Cependant, l’exploitation minière, qu’elle soit industrielle ou artisanale, n’a pas été une source importante de revenus officiels pour l’économie du pays. En effet, elle ne représente que 1% du produit intérieur brut du pays, soit environ 30 millions de dollars, et 1,7% du budget 2019-2020."},{"id":"a-hrc-48-crp-1-p0255","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"255","seq":255,"section":"3. Développements concernant le secteur minier","text":"Le Gouvernement burundais ayant décidé de développer l’exploitation minière industrielle depuis quelques années afin d’accroître la production et les revenus tirés de ces ressources naturelles, avait accordé des droits de concession d’exploration et d’exploitation à une douzaine d’entreprises minières, conformément au Code minier révisé en 2013. Ce Code prévoit des permis d’exploitation de longue durée (25 ans), l’État se voit attribué au moins 10% du capital de la joint venture formée avec la société minière et au moins 30% des voix à son conseil d’administration, ainsi que des positions prépondérantes en son sein, tels que le poste de vice-président. Le Gouvernement conserve donc un droit de regard et de contrôle significatif sur les activités des sociétés minières malgré une participation limitée."},{"id":"a-hrc-48-crp-1-p0256","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"256","seq":256,"section":"3. Développements concernant le secteur minier","text":"Pour rappel, c’est justement dans le cadre des négociations des licences minières que la Commission avait constaté que leur obtention était conditionnée au versement de sommes importantes à des personnes haut placées, notamment l’ancien Président Nkurunziza et certains de ses proches. De même, le manque de transparence sur les montants et les versements des aides annuelles prévues dans les contrats de concessions minières pour le développement communautaire, conjugué à l’absence de réalisations visibles sur le terrain, posaient des questions sur l’existence de possibles détournements.\na)\tSuspension des licences minières"},{"id":"a-hrc-48-crp-1-p0257","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"257","seq":257,"section":"3. Développements concernant le secteur minier","text":"Le Président Ndayishimiye a, peu après son arrivée au pouvoir, commandé un audit du secteur minier, sans doute pour donner suite aux accusations du Conseil national de sécurité (CNS) de 2019, selon lesquelles les sociétés minières ne s’acquittaient pas de leurs engagements et produisaient des rapports biaisés cachant la réalité de la production obtenue. Le 8 avril 2021, le Gouvernement a interdit à la société Rainbow Mining Burundi d´exporter les matières de Terres rares qu´elle exploite à Gakara. Cette décision a été prise sur fond d’allégations que la société faisait des déclarations erronées quant aux teneurs en Terres rares et aux prix de vente réels. Le 15 avril 2021, le Premier ministre, Alain-Guillaume Bunyoni, a dénoncé les pratiques des sociétés minières qui « spolient le pays de ses richesses naturelles » et a également accusé les compagnies minières de ne pas respecter l’accord qui les lie au Gouvernement concernant les versements au Trésor public."},{"id":"a-hrc-48-crp-1-p0258","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"258","seq":258,"section":"3. Développements concernant le secteur minier","text":"Le 1er juillet 2021, le Président a annoncé que les accords de concession minière établis dans des conditions illicites ou présentant des lacunes seraient suspendus ou résiliés afin que les ressources naturelles contribuent réellement au développement du pays. Finalement, à la mi-juillet 2021, le Gouvernement a suspendu les activités de l’ensemble des sociétés minières, les accusant de ne pas avoir respecté les conventions minières qui de toute manière ne seraient pas suffisamment profitables au Burundi. Il a déclaré que les conventions minières devaient être renégociées dans une formule « gagnant-gagnant »."},{"id":"a-hrc-48-crp-1-p0259","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"259","seq":259,"section":"3. Développements concernant le secteur minier","text":"La menace de rupture unilatérale des accords miniers pourrait effectivement aboutir à des accords plus avantageux pour le pays. Cependant, les négociations doivent se faire dans une totale transparence pour pouvoir avoir un impact positif sur les pratiques de corruption. À défaut, il est possible d’envisager que ces renégociations deviennent l’occasion de nouveaux versements à des autorités haut placées. Dans l’intérêt de toutes les parties concernées, toute mesure visant à lutter contre la corruption ou réguler les activités des entreprises minières doit se faire dans le respect de l’État de droit."},{"id":"a-hrc-48-crp-1-p0260","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"260","seq":260,"section":"3. Développements concernant le secteur minier","text":"Effectivement, l’entreprise Rainbow Mining Burundi a demandé la levée de la mesure de suspension de l’exploitation minière et son Président, qui a multiplié les visites au Burundi dans ce but, a noté que la suspension en cours contrevenait à la loi burundaise et a été imposée sans procédure régulière et appropriée. Il a relevé également que le Gouvernement burundais n’avait jamais fourni de prix alternatifs crédibles et fondés sur des données pour le concentré exporté, ni d’analyse alternative crédible par un tiers des teneurs des échantillons qu’il détient pour chaque lot exporté à ce jour.\nb)\tLacunes dans le traçage et la certification des ressources minières"},{"id":"a-hrc-48-crp-1-p0261","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"261","seq":261,"section":"3. Développements concernant le secteur minier","text":"La Commission souligne le manque de progrès dans la mise en œuvre des pratiques de diligence raisonnable, d’exploitation minière responsable et d’approvisionnement conformes aux lignes directrices de l’Organisation de coopération et de développement économiques (OCDE), notamment à travers le système de suivi et de certification des minéraux de la Conférence internationale sur la région des grands lacs (CIRGL) et de l’Initiative pour la transparence dans les industries extractives (ITIE)."},{"id":"a-hrc-48-crp-1-p0262","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"262","seq":262,"section":"3. Développements concernant le secteur minier","text":"Pour rappel, les lignes directrices de l’OCDE sur le devoir de diligence fournissent des recommandations détaillées afin d’aider les entreprises à respecter les droits de l’homme et à éviter de contribuer aux conflits par leurs décisions et leurs pratiques d’achat de minéraux. Ces lignes directrices sont destinées à toute entreprise susceptible de s’approvisionner en minerais ou en métaux provenant de zones affectées par des conflits ou à haut risque. Les lignes directrices de l’OCDE ont une portée mondiale et s’appliquent à toutes les chaînes d’approvisionnement en minéraux."},{"id":"a-hrc-48-crp-1-p0263","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"263","seq":263,"section":"3. Développements concernant le secteur minier","text":"Le Mécanisme de suivi et de certification des minéraux de la CIRGL a pour but de mettre en place des chaînes de minéraux durables et libres de conflit au sein des États membres de la CIRGL, dans le but d’éliminer le soutien aux forces armées qui alimentent ou prolongent les conflits, et qui, par ailleurs, commettent de graves violations des droits de la personne. Les normes et procédures décrites dans ce document visent à empêcher les groupes armés non étatiques et les forces de sécurité publiques ou privées d’intervenir illégalement le long de la chaîne d’approvisionnement ou de commettre de graves violations des droits de l’homme. Il s’agit d’une norme régionale obligatoire de certification de quatre ressources – l’étain, le tungstène, le tantale et l’or – issues de l’un des États membres de la CIRGL ou transitant par l’un d’eux. Cependant, selon les informations recueillies par la Commission, un tel certificat serait rarement délivré par les autorités compétentes du Burundi."},{"id":"a-hrc-48-crp-1-p0264","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"264","seq":264,"section":"3. Développements concernant le secteur minier","text":"L’ITIE vise quant à elle à renforcer la confiance entre les gouvernements, les entreprises et la société civile en exigeant la divulgation des informations tout au long de la chaîne de valeur du secteur extractif : de l’octroi d’une licence d’extraction jusqu’au circuit qu’empruntent les revenus pour parvenir aux autorités, ainsi que leur contribution à l’économie et à la société dans son ensemble. En 2015, le Gouvernement burundais s’était formellement engagé à mettre en œuvre l’ITIE, et en vue de préparer sa candidature, il a entrepris avec le soutien de la Banque mondiale et de l’Agence allemande de coopération internationale pour le développement (GIZ), une étude exploratoire pour identifier les obstacles potentiels à la mise en œuvre de l’ITIE. Cependant, depuis lors, il n’y a eu aucune avancée concernant son adhésion à l’ITIE."},{"id":"a-hrc-48-crp-1-p0265","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"265","seq":265,"section":"3. Développements concernant le secteur minier","text":"L'objectif de l’initiative internationale de la chaîne d’approvisionnement de l’étain (ITSCI) est de créer des chaînes d'approvisionnement en minerais responsables qui évitent de contribuer aux conflits, aux violations des droits de l'homme ou à d'autres risques tels que la corruption. L'ITSCI fait référence au Guide de l’OCDE sur le devoir de diligence pour des chaînes d'approvisionnement en minerais responsables dans les zones de conflit et à haut risque."},{"id":"a-hrc-48-crp-1-p0266","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"266","seq":266,"section":"3. Développements concernant le secteur minier","text":"L’ITSCI et le ministère burundais de l’Hydraulique, Énergie et des Mines ont décidé de travailler ensemble en 2011, mais ce n'est qu'en 2014 que les investissements des entreprises et du gouvernement lui-même ont permis de démarrer les opérations de terrain et la formation à la traçabilité."},{"id":"a-hrc-48-crp-1-p0267","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"267","seq":267,"section":"G. Situation de l’État de droit","text":"Le respect de l’État de droit est fondamental à plusieurs niveaux puisqu’il est avéré qu’au-delà du respect et de la protection des droits civils et politiques, ce dernier a également un impact direct sur le niveau de développement économique, d’éducation, la stabilité d’un pays et la moyenne d’espérance de vie. L’État de droit repose sur quatre principes universels : la responsabilité des autorités et des personnes et entités privées devant la loi ; des lois justes et claires qui sont appliquées de manière équitable et qui garantissent les droits fondamentaux ; un gouvernement ouvert qui signifie que les procédures d’adoption et de mise en œuvre des lois soient accessibles, justes et efficaces ; et une justice accessible, indépendante et impartiale. L’État de droit repose sur trois postulats : « l’État qui agit au moyen du droit, l’État qui est assujetti au droit et l’État dont le droit comporte certains attributs intrinsèques »."},{"id":"a-hrc-48-crp-1-p0268","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"268","seq":268,"section":"G. Situation de l’État de droit","text":"Malgré la volonté affichée du Président Ndayishimiye de promouvoir l’État de droit, sérieusement détérioré depuis des années, ce dernier continue de s’éroder puisque les procédures et lois sont encore moins respectées qu’auparavant, avec de nombreuses brèches faites aux principes de légalité, de redevabilité des autorités et de séparation des pouvoirs."},{"id":"a-hrc-48-crp-1-p0269","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"269","seq":269,"section":"1. Un État burundais transgressant les lois","text":"Des autorités au plus haut niveau ont ouvertement autorisé ou accepté la transgression de la Constitution et de lois. Par exemple, les ministres n’ont pas rempli leur obligation constitutionnelle de déclarer leurs biens. Pour rappel, après avoir insisté le 23 août 2020 sur l’obligation de tous les ministres de déclarer leurs biens dans un délai de deux semaines, conformément à la Constitution de 2018, le Président Ndayishimiye a fait volte-face en déclarant lors d’une émission de radio tenue le 25 septembre 2020 : « Nous savons que la Constitution nous oblige à le faire, mais nous avons trouvé que c’est impossible. Certains passeraient une semaine à faire la liste de leurs biens. La richesse d’une personne est un secret. Nous allons voir à la fin du mandat si rien ne cloche ». Il a simplement indiqué que si certains présentaient « des signes flagrants d’enrichissement illicite » en fin de mandat, ils pourraient se voir exiger de rendre des comptes. Effectivement, selon les informations en possession de l’OLUCOME, aucune déclaration de patrimoine n’avait été faite par les membres du Gouvernement au 1er décembre 2020. Cependant, le 9 juin 2021, lors du Conseil des ministres, le Président a déclaré que ces déclarations pouvaient être remplies puisque les formulaires étaient désormais disponibles, mais il n’y a pas encore de confirmation que des ministres aient bien rempli leur déclaration."},{"id":"a-hrc-48-crp-1-p0270","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"270","seq":270,"section":"1. Un État burundais transgressant les lois","text":"L’Accord de paix d’Arusha avait prévu des quotas ethniques au sein des principales institutions étatiques de l’Exécutif et du Législatif (60% de Hutus et 40% de Tutsis) et au sein des forces de défense et de sécurité (50% de Hutus et 50% de Tutsis). Alors que le Président Ndayishimiye, à l’instar de son prédécesseur, martèle que les ethnies n’existent pas au Burundi et qu’elles ont été créées par les colonisateurs pour diviser la population burundaise, la Constitution adoptée en 2018 a repris ces quotas ethniques, y a ajouté des quotas de genre (30% de femmes) et les a même étendus aux institutions judiciaires, tout en les abolissant de facto pour le Service national de renseignement - puisque celui-ci n’est plus officiellement partie des corps de défense et de sécurité mais placé sous le contrôle direct du Chef de l’État. En parallèle, les autorités burundaises ont cherché à appliquer ces quotas aux organisations non-gouvernementales étrangères. Cependant, selon des estimations crédibles, les quotas ethniques au sein des principales institutions et des forces de défense et de sécurité ne seraient plus respectés sauf au Parlement, et l’ensemble des institutions est largement dominé par des personnes hutues."},{"id":"a-hrc-48-crp-1-p0271","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"271","seq":271,"section":"2. Un État affranchi des procédures légales","text":"Des autorités ont outrepassé leurs compétences en prenant des décisions sans respecter les procédures légales. Par exemple, au nom de la lutte contre la corruption, le 9 avril 2021, le ministre de l’Intérieur, du Développement communautaire et de la Sécurité publique, Gervais Ndirakobuca, a annoncé le limogeage avec effet immédiat des 119 comptables communaux que compte le Burundi pour « avoir handicapé la collecte des recettes communales en complicité avec les anciens percepteurs précédemment démis de leur fonction ». De la même manière, à la fin du mois de février 2021, le ministère de l’Intérieur, du Développement communautaire et de la Sécurité publique a remplacé tous les percepteurs pour la collecte et la perception des taxes et impôts en Mairie de Bujumbura, peu après les avoir accusés de détourner systématiquement des fonds, évoquant même un montant de 121 millions de francs burundais par semaine (environ 62 000 dollars)."},{"id":"a-hrc-48-crp-1-p0272","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"272","seq":272,"section":"2. Un État affranchi des procédures légales","text":"Sans se prononcer sur le fond de ces décisions, la Commission note que leur base légale est contestable, voire carrément inexistante, et elles sont donc incompatibles avec les standards relatifs à la prévisibilité du droit, notamment au vu des délais très courts pour les exécuter et l’impossibilité de faire un recours contre elles. Ainsi, les comptables communaux sont recrutés sur concours par l’administrateur communal après approbation du Conseil et non nommés par le ministre de l’Intérieur. Ce dernier a donc pris cette décision en violation de la loi sur l’administration communale de 2020, et du droit du travail, qui offre une certaine protection aux employés communaux, notamment quant aux procédures à suivre pour des licenciements pour faute."},{"id":"a-hrc-48-crp-1-p0273","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"273","seq":273,"section":"2. Un État affranchi des procédures légales","text":"En février 2021, le même ministre a décidé que les commerçants qui ont leur boutique près des marchés publics devaient fermer dans un délai de 10 jours et déménager à l’intérieur de ces marchés. Le 16 mars 2021, il a donné deux semaines aux commerçants installés près du marché de Jabe, zone Bwiza, commune Mukaza, à Bujumbura Mairie, pour déménager à l’intérieur du marché. Toutefois, la grande majorité des commerçants concernés exerçaient légalement leur activité et payaient leurs taxes aux autorités nationales et locales, en conformité avec le principe de la liberté de commerce consacré par la Constitution du Burundi et avec le Code du commerce de 2015. Selon l’OLUCOME, une telle décision est contraire au droit burundais en matière commerciale et constitue un abus de pouvoir."},{"id":"a-hrc-48-crp-1-p0274","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"274","seq":274,"section":"2. Un État affranchi des procédures légales","text":"Les autorités locales multiplient également les taxes et contributions en tout genre souvent sans aucun fondement légal. De telles pratiques existent depuis un moment, notamment les collectes de « contributions », souvent soi-disant volontaires, afin de financer aussi bien des infrastructures publiques (écoles, bâtiments administratifs locaux, stades, routes, etc.) que soutenir le parti au pouvoir CNDD-FDD (activités festives ou permanences locales)."},{"id":"a-hrc-48-crp-1-p0275","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"275","seq":275,"section":"2. Un État affranchi des procédures légales","text":"De manière certes plus anecdotique mais non moins significative, on peut noter que le Président du Sénat, Emmanuel Sinzohagera, a appelé, à plusieurs reprises lors de tournées à l’intérieur du pays, les responsables administratifs locaux à « emprisonner les couples en situation de concubinage et les faire travailler dans les champs de la commune ». Il a été également rapporté que le Président de l’Assemblée nationale, Gelase Ndabirabe, a recommandé à ces mêmes responsables administratifs le recours « aux coups de bâtons pour recadrer la population ». Le Maire de Bujumbura a ordonné aux habitants du quartier de Mukaza de repeindre la façade de leur maison à l’approche des célébrations de l’indépendance du Burundi, sous peine de se voir infliger une amende. Le gouverneur de la province Rumonge a indiqué que pour lutter contre la production, la vente et la consommation de boissons prohibées, il avait recouru à des arrestations et des détentions arbitraires comme sanction collective : « Nous avons décidé que si on la saisit [la boisson prohibée appelée ‘Kanyanga’] sur une telle colline, ce sont les élus collinaires qui seront emprisonnés les premiers. Nous avons passé à l’acte. Beaucoup d’élus collinaires ont été arrêtés et emprisonnés »."},{"id":"a-hrc-48-crp-1-p0276","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"276","seq":276,"section":"2. Un État affranchi des procédures légales","text":"En revanche, des décisions prises légalement n’ont pas été pleinement exécutées ou mises en œuvre, comme la grâce présidentielle accordée théoriquement à 5 200 prisonniers en mars 2021, qui n’a commencé à être appliquée qu’à la mi-avril. Au début de juillet 2021, seulement 2 600 prisonniers graciés avaient effectivement été libérés, dont certains ont été ré-arrêtés peu après leur libération et d’autres enlevés et portés disparus. Au 10 août 2021, selon une ONG burundaise, 4 828 prisonniers graciés avaient effectivement retrouvé leur liberté. Des décisions de justice n’ont pas été exécutées, notamment des décisions de mise en liberté provisoire dans l’attente du procès ou de remise en liberté après acquittement. Au contraire, d’autres décisions telles que la destruction des constructions considérées anarchiques ou illégales ont été exécutées quasi immédiatement sans offrir de voie de recours ni de délai raisonnable aux personnes concernées."},{"id":"a-hrc-48-crp-1-p0277","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"277","seq":277,"section":"2. Un État affranchi des procédures légales","text":"Le Président Ndayishimiye a avalisé l’ensemble de ces décisions, directement ou implicitement, et donc la manière dont elles ont été prises sans base légale, ni respect des procédures, ni possibilité pour les personnes concernées de faire recours. Le principe de légalité, la sécurité juridique, la prévention de l’abus de pouvoir, l’égalité devant la loi et la non-discrimination, et l’accès à la justice ne sont donc pas suffisamment garantis au Burundi."},{"id":"a-hrc-48-crp-1-p0278","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"278","seq":278,"section":"1. Responsabilité de l’État burundais","text":"L’État burundais peut être tenu responsable des faits constituant des violations des droits de l’homme commis par des agents de l’État, notamment du SNR et de la police, mais également des autorités administratives qui représentent l’État à divers échelons."},{"id":"a-hrc-48-crp-1-p0279","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"279","seq":279,"section":"1. Responsabilité de l’État burundais","text":"Les Imbonerakure agissent souvent seuls, parfois comme supplétifs ou en remplacement des forces de sécurité, en présence d’agents de l’État, avec leur assentiment ou à leur demande. Ils jouissent d’une grande liberté d’action conférée par les autorités burundaises, qui ont pourtant les moyens de les contrôler. Certains détiennent du matériel et des équipements réservés aux corps de défense et de sécurité, ce qui démontre leur rôle central au sein des structures de sécurité formelles et informelles de l’État burundais. L’État burundais est directement responsable de leurs actions entreprises sur instruction de ses agents, ou sous leur totale dépendance ou contrôle effectif. Pour les autres cas de figure, en ne diligentant pas les enquêtes nécessaires et en n’entamant pas de poursuites effectives, l’État burundais engage sa responsabilité en matière de protection des droits de l’homme."},{"id":"a-hrc-48-crp-1-p0280","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"280","seq":280,"section":"2. Responsabilité des groupes armés","text":"La Commission a recueilli des informations sur un cas récent d’atteinte aux droits à la liberté et à la sécurité et à l’intégrité physique qui concerne plusieurs victimes, y compris des enfants, commis sur le territoire burundais par un groupe armé non identifié. De plus, des groupes armés seraient également responsables de graves atteintes au droit à la vie dans le cadre d’attaques armées, mais la Commission n’a pas été en mesure de documenter suffisamment ces cas afin de corroborer le déroulement des faits et identifier éventuellement les auteurs, en raison notamment du refus de coopération du Gouvernement."},{"id":"a-hrc-48-crp-1-p0281","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"281","seq":281,"section":"III. Crimes de droit international","text":"Dans ses précédents rapports, la Commission avait considéré avoir des motifs raisonnables de croire que des crimes contre l’humanité, tels que définis par le Statut de Rome de la Cour pénale internationale, avaient été perpétrés au Burundi depuis 2015, à savoir des meurtres, des emprisonnements ou autres formes graves de privation de liberté physique, des tortures, des viols et autres formes de violence sexuelle de gravité comparable, et des persécutions à caractère politique."},{"id":"a-hrc-48-crp-1-p0282","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"282","seq":282,"section":"III. Crimes de droit international","text":"Au vu du contexte qui a prévalu au Burundi au cours de la période considérée dans le présent rapport, caractérisé par la poursuite des violations graves des droits de l’homme, notamment contre les opposants politiques, la Commission considère qu’elle a des motifs raisonnables de croire que des crimes contre l’humanité ont continué d’être perpétrés au Burundi."},{"id":"a-hrc-48-crp-1-p0283","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"283","seq":283,"section":"III. Crimes de droit international","text":"Pour rappel, selon le Statut de Rome, les actes constitutifs des crimes contre l’humanité doivent être « commis dans le cadre d’une attaque généralisée ou systématique lancée contre toute population civile et en connaissance de cette attaque ». L’« attaque » ne doit pas nécessairement être de nature militaire, mais peut consister en la multiplication d’actes constitutifs de crimes contre l’humanité qui ne doivent pas être des actes isolés. Cette attaque doit être dirigée contre une population civile dont le caractère civil n’est pas altéré par la présence parmi les victimes de certains non-civils. Le caractère « généralisé ou systématique » de l’attaque peut se déduire du nombre d’exactions constatées, de leur répartition géographique et de la pluralité des victimes et des auteurs. L’existence d’un « scénario des crimes » consistant en « une répétition délibérée et régulière des comportements criminels similaires » ou de modes opératoires similaires, peut également être révélateur du caractère systématique de l’attaque. De même, le « cadre politique global dans lequel s’inscrivent les actes criminels », la « teneur d’un programme politique telle qu’elle résulte des écrits de ses auteurs et de leurs discours », la « mobilisation des forces armées » et « l’ampleur des exactions perpétrées » peuvent permettre de déduire l’existence d’une « politique d’État ou d’une organisation » ayant pour but de commettre ladite attaque. Les auteurs doivent également avoir une compréhension du contexte dans lequel s’inscrivent leurs actes."},{"id":"a-hrc-48-crp-1-p0284","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"284","seq":284,"section":"III. Crimes de droit international","text":"La Commission a documenté un nombre suffisamment important d’actes pouvant être constitutifs de crimes contre l’humanité, notamment des meurtres, des emprisonnements, des tortures et des persécutions à caractère politique, pour lui permettre de déterminer qu’il ne s’agit pas d’actes isolés. Certains ont continué à s’inscrire dans le cadre du processus électoral et d’autres dans le cadre de la traque des auteurs des incidents de sécurité qui se sont multipliés dans le pays dès la fin de l’été 2020."},{"id":"a-hrc-48-crp-1-p0285","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"285","seq":285,"section":"III. Crimes de droit international","text":"Ces actes ont visé de manière délibérée des civils, notamment des responsables de partis politiques d’opposition, principalement du CNL, mais aussi des militaires ex-FABs actifs ou non. En effet, même s’il s’avérait que certaines de ces personnes avaient effectivement des liens avec des groupes armés, en l’absence d’un conflit armé sur le territoire burundais, elles n’en demeurent pas moins des civils et doivent donc être traitées comme tels dans le cadre de la traque des responsables des incidents de sécurité. Elles peuvent être poursuivies pour leurs crimes éventuels en vertu du droit burundais, mais elles doivent bénéficier de leurs droits fondamentaux, notamment le droit à la vie, le droit d’être traité avec humanité et avec le respect de la dignité inhérente à la personne humaine, et le droit à ne pas être torturé."},{"id":"a-hrc-48-crp-1-p0286","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"286","seq":286,"section":"III. Crimes de droit international","text":"La Commission souligne que depuis plusieurs années, les autorités burundaises ont régulièrement assimilé les opposants politiques et les voix critiques à des ennemis du pays et donc aux groupes armés d’opposition, et elles ont toléré, sinon alimenté les discours de haine à leur égard. Étant donné l’opacité entourant les opérations des forces de sécurité et les éventuelles procédures judiciaires, il est impossible de déterminer au cas par cas s’il existe des éléments de preuve raisonnables et objectifs démontrant l’implication des personnes ciblées dans les incidents sécuritaires. Cependant, la Commission estime qu’un nombre significatif d’entre elles l’ont été principalement sur la base de leur affiliation politique."},{"id":"a-hrc-48-crp-1-p0287","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"287","seq":287,"section":"III. Crimes de droit international","text":"La similitude des modes opératoires de ces incidents qui se sont déroulés dans plusieurs provinces et commis par des auteurs différents permet de déduire l’existence d’un « scénario des crimes » avec l’objectif d’affaiblir, voire de « neutraliser », l’opposition politique et permettre au CNDD-FDD de se maintenir au pouvoir et consolider ce dernier. Cet objectif est d’ailleurs rappelé régulièrement dans les chants et slogans de ce parti, notamment lors de la campagne électorale, et également par la suite lors de rassemblements et démonstrations de force du parti."},{"id":"a-hrc-48-crp-1-p0288","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"288","seq":288,"section":"III. Crimes de droit international","text":"Dans le cadre du processus électoral, les principaux auteurs de ces actes, à savoir des Imbonerakure, des responsables administratifs locaux et des agents des forces de sécurité et de défense, avaient agi en toute connaissance de cause puisque l’objectif des autorités et du parti CNDD-FDD de gagner les élections à tout prix était régulièrement rappelé, y compris de manière publique. De la même manière, il est évident que des agents du SNR et des policiers des unités spécialisées et dans une mesure moindre des Imbonerakure, qui ont été spécialement mobilisés dans le cadre de la lutte contre les auteurs d’actes de terrorisme et les groupes armés, avaient une compréhension du contexte global dans lequel s’inscrivaient leurs actes, et notamment l’identification des opposants politiques comme des « ennemis du pays »."},{"id":"a-hrc-48-crp-1-p0289","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"289","seq":289,"section":"B. Responsabilités individuelles","text":"Les éléments d’information recueillis par la Commission au cours du présent terme de mandat indiquent que les principaux auteurs présumés des crimes contre l’humanité commis dans ce contexte sont des agents du SNR, de la police, notamment de ses unités spécialisées telles que le GMIR, des membres du personnel judiciaire ainsi que des Imbonerakure."},{"id":"a-hrc-48-crp-1-p0290","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"290","seq":290,"section":"B. Responsabilités individuelles","text":"La Commission a établi une liste des auteurs individuels présumés depuis le premier terme de son mandat qui a été régulièrement mise à jour. Cette liste reste confidentielle afin de protéger les sources et respecter la présomption d’innocence des auteurs présumés. À la fin de son mandat, la Commission remettra cette liste au Haut-Commissaire des Nations Unies aux droits de l’homme. En attendant, la Commission se réserve la possibilité de la partager quand elle le considère nécessaire ou utile."},{"id":"a-hrc-48-crp-1-p0291","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"291","seq":291,"section":"B. Responsabilités individuelles","text":"Dans sa liste d’auteurs, la Commission fait la distinction entre les responsabilités directes et celles indirectes des chefs militaires et des supérieurs hiérarchiques, y compris civils. À cet égard, la Commission rappelle qu’en vertu de la Constitution de 2018 qui a détaché le SNR des forces de défense et de sécurité pour le rattacher directement au Président de la République, celui-ci peut voir sa responsabilité pénale personnelle engagée pour les crimes contre l’humanité commis par des agents du SNR, en tant que supérieur hiérarchique qui « ordonne, sollicite ou encourage » la commission d’un crime contre l’humanité ou s’il reste inactif face aux agissements criminels d’un subordonné placé sous son autorité et son contrôle effectifs."},{"id":"a-hrc-48-crp-1-p0292","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"292","seq":292,"section":"B. Responsabilités individuelles","text":"Finalement, dans certaines provinces, des membres de la ligue des jeunes du parti CNDD-FDD, les Imbonerakure, ont continué d’avoir un rôle central dans la traque des responsables présumés d’incidents de sécurité, agissant en coopération avec le SNR et la police ou parfois seuls. Les appareils sécuritaires formels et informels restent imbriqués et les institutions étatiques et celles du parti CNDD-FDD tendent encore à se confondre surtout quand la situation sécuritaire devient tendue ou volatile. Les exactions commises dans ce contexte par des Imbonerakure sont donc non seulement imputables à l’État burundais lorsqu’elles sont constitutives de violations des droits de l’homme, mais elles pourraient être constitutives de crimes contre l’humanité dont les Imbonerakure peuvent être tenus pénalement responsables de manière individuelle s’il est démontré que ces actes s’inscrivent dans une politique d’État consistant à persécuter l’opposition politique, y compris à la faveur de la traque des auteurs d’incidents de sécurité."},{"id":"a-hrc-48-crp-1-p0293","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"293","seq":293,"section":"1. Cadre d’analyse des facteurs de risque d’atrocités criminelles","text":"Depuis 2019, la Commission procède de manière systématique à une analyse des facteurs de risque de détérioration de la situation des droits de l’homme au Burundi. Pour ce faire, elle se base sur les indicateurs retenus pour les huit facteurs de risque communs identifiés dans le Cadre d’analyse des atrocités criminelles, qui a été élaboré par le Bureau des Nations Unies du Conseiller spécial pour la prévention du génocide et du Conseiller spécial pour la responsabilité de protéger. Ce Cadre d’analyse « résulte de recherches approfondies sur les législations, la jurisprudence des juridictions internationales et la doctrine, et des connaissances spécialisées acquises par les bureaux du Conseiller spécial pour la prévention du génocide et du Conseiller spécial pour la responsabilité de protéger ». La Commission a considéré que le Cadre d’analyse était l’outil méthodologique le plus complet et pertinent pour sa démarche qui s’inscrit dans la logique d’alerte rapide et de prévention. Une telle analyse permet de suivre objectivement l’évolution de la situation au Burundi, et si besoin, d’alerter les autorités burundaises, la communauté internationale et les autres acteurs pertinents sur une possible détérioration de la situation des droits de l’homme."},{"id":"a-hrc-48-crp-1-p0294","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"294","seq":294,"section":"1. Cadre d’analyse des facteurs de risque d’atrocités criminelles","text":"Pour rappel, les facteurs de risque sont définis comme des conditions, telles que des comportements, des circonstances et des éléments, qui créent un environnement propice à la perpétration d’atrocités criminelles ou qui indiquent un potentiel, une probabilité et un risque de leur occurrence. Certains de ces facteurs ont une dimension structurelle et d’autres sont conjoncturels, étant liés à des circonstances dynamiques ou des évènements. La Commission a constamment rappelé que constater l’existence de ces facteurs ne lui permettait pas pour autant de tirer des conclusions quant à la probabilité que des atrocités criminelles se produisent ni, le cas échéant, de déterminer à quel moment ou de quelle manière."},{"id":"a-hrc-48-crp-1-p0295","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"295","seq":295,"section":"1. Cadre d’analyse des facteurs de risque d’atrocités criminelles","text":"À la veille des élections de 2020, la Commission avait constaté que les huit facteurs de risque communs aux atrocités criminelles étaient bien présents au Burundi, avec un nombre significatif d’indicateurs pour chacun d’entre eux. Certains s’étaient d’ailleurs renforcés au fur et à mesure de l’approche des élections de mai 2020, comme le démontrait le nombre élevé d’indicateurs pour plusieurs facteurs. À l’issue des élections, certains facteurs de risque s’étaient atténués, notamment ceux ayant une dimension conjoncturelle, même si aucun n’avait entièrement disparu. Les facteurs avec une dimension structurelle demeuraient tous plus ou moins tels quels, compte tenu de l’absence de mesures de réforme en profondeur entreprises par les autorités burundaises. Pour rappel, les indices statistiques établis par diverses organisations indépendantes démontrent la dégradation progressive et continue depuis 2015 de la situation en matière de libertés publiques, liberté de la presse, corruption, performance démocratique, développement humain, et gouvernance."},{"id":"a-hrc-48-crp-1-p0296","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"296","seq":296,"section":"2. Développements notables pour l’analyse des facteurs de risque","text":"Au-delà des développements mentionnés dans la partie sur la situation des droits de l’homme, certains évènements ou incidents qui ont eu lieu depuis les élections de 2020 et l’investiture du Président Ndayishimiye sont à relever car ils sont particulièrement significatifs dans le cadre de l’analyse sur les facteurs de risque, certains démontrant la persistance de plusieurs indicateurs ou au contraire leur atténuation.\na)\tL’héritage du feu Président Nkurunziza en matière de droits de l’homme"},{"id":"a-hrc-48-crp-1-p0297","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"297","seq":297,"section":"2. Développements notables pour l’analyse des facteurs de risque","text":"Le Président Ndayishimiye revendique pleinement l’héritage du Président Nkurunziza auquel il a confirmé l’octroi, malgré son décès, du statut de « Guide suprême du patriotisme ». Le 20 mai 2021, l’Assemblée nationale a en effet adopté le projet de loi n°1/14 du 4 juin 2021 portant modification la loi n°1/06 du 10 mars 2020 portant instauration et octroi du statut de Guide suprême du patriotisme au Burundi au Président Pierre Nkurunziza. La journée nationale du patriotisme instaurée par la loi n°1/06 doit désormais être célébrée le 8 juin de chaque année, date anniversaire du décès de Pierre Nkurunziza, au lieu du mois de juillet, et « comme le Guide suprême n’est plus en vie », c’est le Président de la République qui doit désormais présider cette journée."},{"id":"a-hrc-48-crp-1-p0298","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"298","seq":298,"section":"2. Développements notables pour l’analyse des facteurs de risque","text":"Le Président Ndayishimiye a multiplié les éloges publics de son prédécesseur, comme par exemple lors de sa levée de deuil définitive le 8 juin 2021 :\n« Dieu nous avait donné Feu Son Excellence Pierre Nkurunziza comme un cadeau, une bénédiction et un Leader doté de dons extraordinaires que nous ne pouvons pas réussir à énumérer ici. […] Parler des œuvres de Feu Pierre Nkurunziza, le Guide suprême du patriotisme, prendrait des heures et des heures, car Dieu l’avait comblé de dons multiples. […] Les Burundais se souviendront toujours de Feu Pierre Nkurunziza comme celui qui a restauré la confiance entre l’autorité dirigeante et la population. Il s’est battu vaillamment pour que la démocratie ne régresse pas. […] Pour terminer, Moi en ma qualité d’Héritier, le Président de la République du Burundi, je réitère ma promesse envers les Burundais que je marcherai sur les traces du Guide Pierre Nkurunziza […] »."},{"id":"a-hrc-48-crp-1-p0299","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"299","seq":299,"section":"2. Développements notables pour l’analyse des facteurs de risque","text":"Il est donc somme toute logique qu’à l’instar de son prédécesseur, le Président Ndayishimiye refuse de coopérer pleinement avec les mécanismes internationaux des droits de l’homme et/ou de discuter des questions relatives aux violations des droits de l’homme commises au Burundi. Dans leurs comptes rendus des discussions avec l’Union européenne, le Président Ndayishimiye et le ministre des Affaires étrangères du Burundi réfèrent systématiquement à la crise politique de 2015 et aux violations des droits de l’homme commises depuis lors, comme des « malentendus », des « points de divergence », des « zones d’ombre », sur lesquels il conviendrait de simplement « tourner la page ». L’emploi de tels euphémismes vise à cacher la réalité des faits et atteste du refus du Président Ndayishimiye et des autorités burundaises d’entreprendre quelque mesure que ce soit pour lutter contre l’impunité en ce qui concerne ces violations alors qu’il s’agit d’une condition sine qua non à toute véritable réconciliation et amélioration de la situation des droits de l’homme dans le pays."},{"id":"a-hrc-48-crp-1-p0300","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"300","seq":300,"section":"2. Développements notables pour l’analyse des facteurs de risque","text":"Par ailleurs, même pour les incidents les plus récents commis depuis son investiture, le Président Ndayishimiye et son Gouvernement maintiennent le narratif selon lequel toute mention de violation des droits de l’homme constituerait une attaque politiquement motivée afin « de ternir l’image du pays » et réfutent la réalité de ces violations. Par exemple, au sujet de nombreux cas de disparition forcée qui ont été commis depuis 2015, dont certains documentés en détail par la présente Commission, d’autres notifiés aux autorités burundaises par le Groupe de travail des Nations Unies sur les disparitions forcées et involontaires, diverses hautes autorités dont le Président Ndayishimiye et Sylvestre Nyandwi, le Procureur général de la République, ont simplement nié que ces personnes aient véritablement disparu et ils ont affirmé qu’elles seraient au Rwanda ou auraient rejoint les groupes armés d’opposition, sans justifier leurs propos ou donner des informations sur les éventuelles enquêtes qui auraient été ouvertes et auraient permis de justifier  de telles affirmations."},{"id":"a-hrc-48-crp-1-p0301","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"301","seq":301,"section":"2. Développements notables pour l’analyse des facteurs de risque","text":"Comme sous la présidence de Nkurunziza, la religion et le politique demeurent étroitement liés, les références à une alliance entre Dieu et le Burundi sont fréquentes à tous les niveaux. Le Président Ndayishimiye, catholique pratiquant, organise régulièrement des prières d’action de grâce et des « séances de moralisation », il participe aux messes dominicales où il prend régulièrement la parole. Par ailleurs, Emmanuel Sinzohagera, le Président du Sénat, qui occupe lui aussi une grande place dans l’espace médiatique officiel, est également un « révérend pasteur » de l’Église méthodiste unie du Burundi dont il est en plus le représentant légal. La distinction entre ce qui relève du politique et du religieux et de la sphère privée s’est effacée. La religion continue donc d’être utilisée pour affermir l’autorité et la légitimité du Président Ndayishimiye, et plus largement, consolider le pouvoir du CNDD-FDD, avec toutes les dérives possibles que cela peut engendrer.\nb)\tLe réengagement avec la communauté internationale"},{"id":"a-hrc-48-crp-1-p0302","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"302","seq":302,"section":"2. Développements notables pour l’analyse des facteurs de risque","text":"Le Président Ndayishimiye n’a pas hésité, dans un domaine, à rompre avec son prédécesseur afin de tenter de normaliser les relations du Burundi avec la communauté internationale et réduire certaines tensions anciennes. Alors que Pierre Nkurunziza n’avait pas quitté le Burundi au cours de son troisième mandat – à part quelques heures du côté tanzanien de la frontière commune avec le Burundi - le Président Ndayishimiye a multiplié les visites sur le continent africain : la Tanzanie, la Guinée Équatoriale, l’Égypte, la République du Congo, l’Ouganda, le Kenya et la République démocratique du Congo – par ordre chronologique. Il a également reçu la visite officielle de la Présidente d’Ethiopie et de la Présidente de la République unie de Tanzanie et il a participé aux réunions de la Communauté d’Afrique de l’Est et de la Communauté économique d’Afrique centrale, auxquelles le Président Nkurunziza avait été largement absent. Le ministre des Affaires étrangères a entrepris une tournée en Europe, qualifiée de « technique », puisqu’il n’a pas rencontré ses homologues, excepté celui de la Confédération helvétique."},{"id":"a-hrc-48-crp-1-p0303","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"303","seq":303,"section":"2. Développements notables pour l’analyse des facteurs de risque","text":"Des relations de coopération ont été également renouées avec les pays de la région avec lesquels les rapports avaient parfois été tendus sous la Présidence de Nkurunziza, notamment le Rwanda. Des rencontres entre les ministres des Affaires étrangères des deux pays et même de leurs services de renseignement militaires ont été organisées depuis l’été 2020, ce qui a débouché le 30 juillet 2021 sur la remise aux autorités burundaises par le Rwanda de 19 rebelles burundais qui avaient été arrêtés sur le territoire rwandais en septembre 2020 et dont le sort demeure depuis incertain. D’ailleurs, l’affrontement armé fortuit entre des militaires burundais et rwandais à la frontière des deux pays qui a eu lieu le 28 février 2021 a été réglé très rapidement entre les services de renseignement militaires, ce qui aurait été pratiquement inimaginable quelques mois auparavant."},{"id":"a-hrc-48-crp-1-p0304","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"304","seq":304,"section":"2. Développements notables pour l’analyse des facteurs de risque","text":"La reprise du dialogue avec l’Union européenne et ses membres afin de normaliser leurs relations marque elle aussi une rupture au niveau des relations internationales du Burundi, qui s’explique par l’objectif rappelé régulièrement par les autorités burundaises d’obtenir la levée de toutes les sanctions économiques qui pèsent sur le pays depuis 2016. La plupart des gestes symboliques posés par le Président Ndayishimiye depuis son investiture s’inscrivent dans ce cadre et cette stratégie. Il reste à voir ce qu’il adviendra de cette attitude des autorités burundaises envers l’UE et ses membres une fois que leur objectif aura été atteint ou si au contraire celui-ci n’était pas atteint ou que le processus pour lever les sanctions prenait trop de temps.\nc)\tLa concentration des pouvoirs"},{"id":"a-hrc-48-crp-1-p0305","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"305","seq":305,"section":"2. Développements notables pour l’analyse des facteurs de risque","text":"La démocratie consociative instaurée par l’Accord d’Arusha prévoyait une participation de l’opposition politique au pouvoir et les gouvernements successifs du Président Nkurunziza comprenaient effectivement quelques ministres issus de l’opposition tout comme les bureaux de l’Assemblée nationale et du Sénat. Cependant, les institutions politiques actuelles, du niveau central au niveau local, sont entièrement contrôlées par le CNDD-FDD. Seul le Vice-Président, Prosper Mazombaza, qui a un rôle éminemment honorifique, est issu du parti d’opposition UPRONA, tout comme le deuxième vice-président de l’Assemblée nationale, Abel Gashatsi, alors que ce parti est loin d’être un parti d’opposition significatif. Le CNL qui a obtenu le plus grand nombre de voix et de députés après le CNDD-FDD a été totalement écarté de ces postes. Le Bureau du Sénat pour la première fois est composé uniquement de membres du CNDD-FDD. Les responsables administratifs locaux à tous les niveaux seraient également quasi exclusivement des membres du CNDD-FDD. La concentration du pouvoir au profit du CNDD-FDD est inégalée dans l’histoire récente du Burundi et s’inscrit dans un espace politique et démocratique verrouillé sans véritables contre-pouvoirs. Le Parlement contrôlé par le CNDD-FDD entérine les projets de loi à la quasi-unanimité et ne constitue pas un espace de discussion ou un outil de contrôle de l’Exécutif."},{"id":"a-hrc-48-crp-1-p0306","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"306","seq":306,"section":"2. Développements notables pour l’analyse des facteurs de risque","text":"Cet état des choses conjugué aux entorses constatées aux principes de légalité, de séparation des pouvoirs et à l’érosion continue de l’État de droit, permet de se demander légitimement si le Burundi ne devrait pas être qualifié de régime à tendance autoritaire. En effet, « l’organisation d’élections régulières par des pouvoirs qui entretiennent un système politique déséquilibré en leur faveur ne peut suffire à définir une démocratie », dont une vision réductrice focalisée sur la tenue d’élections suffisamment crédibles « néglige les aspects fondamentaux que sont l’environnement institutionnel (neutralité politique des institutions, État de droit réel et non pas seulement théorique, etc.. ) et, plus généralement, la situation du marché politique (comportements et structures politiques, inclusivité de la citoyenneté, offre politique réelle, rapports de force politiques, etc.) »."},{"id":"a-hrc-48-crp-1-p0307","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"307","seq":307,"section":"2. Développements notables pour l’analyse des facteurs de risque","text":"En fait, le seul espace où des discussions et des différends sont possibles est au sein du parti CNDD-FDD. Des tensions semblent émerger entre une aile qui comprend Alain-Guillaume Bunyoni, l’actuel Premier ministre, et Révérien Ndikuriyo, le nouveau secrétaire-général du parti élu le 24 janvier 2021, et l’aile du Président Ndayishimiye. Elles pourraient d’ailleurs expliquer certaines incohérences et revirements du Président et le fait que certaines de ses décisions ne soient pas mises en œuvre, mais également les raisons pour lesquelles le Président Ndayishimiye a cherché à consolider ses pouvoirs au sein du Gouvernement, notamment en réorganisant et en renforçant les services de la Présidence. Désormais, ce sont en effet  huit administrations spécialisées qui sont placées sous le contrôle direct du Président : la Banque de la République du Burundi, le SNR, le Secrétariat permanent du Conseil national de sécurité (CNS), le Secrétariat permanent du Conseil supérieur de la magistrature, qui est désormais chargé de revoir et « corriger » les décisions de justice, l’Inspection générale de l’État (IGE), l’Agence de promotion des investissements, l’Agence de régulation et de contrôle des télécommunications (ARCT), ainsi que le Burundi Backbone System (BBS). Ce dernier est « un consortium d'opérateurs de télécommunications burundais qui ont uni leurs forces pour construire un réseau national de fibre optique avec l'aide de la Banque mondiale. La société a été lancée en mars 2013 ». Le BBS est également un « opérateur d’infrastructures spécialisé dans la conception, la construction, l’exploitation technique et la commercialisation de réseaux très haut débit. Partenaire des institutions gouvernementales dans le cadre du réseau ‘Communication Gouvernementale’ (COMGOV), des universités, des Banques, BBS exploite des réseaux ouverts à tous les opérateurs de services et destinés aux services publics, entreprises et particuliers »."},{"id":"a-hrc-48-crp-1-p0308","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"308","seq":308,"section":"2. Développements notables pour l’analyse des facteurs de risque","text":"Par ailleurs, la différence de couverture médiatique officielle entre les représentants des deux « camps » est assez surprenante et pourrait être révélatrice de cette lutte d’influence interne. La visibilité médiatique est effectivement le principal lien entre l’homme politique et le public de citoyens et d’électeurs et donc importante pour leur popularité, même si une surexposition médiatique ne va pas sans certains risques. D’un côté, le Président Ndayishimiye est incontournable, ses activités sont couvertes de manière quasi quotidienne par la RTNB, y compris lorsqu’il s’agit d’activités privées et de nature religieuse, tout comme dans une moindre mesure celles de la première dame."},{"id":"a-hrc-48-crp-1-p0309","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"309","seq":309,"section":"2. Développements notables pour l’analyse des facteurs de risque","text":"Par contraste, le Premier ministre est remarquablement absent ; les articles le mentionnant se sont faits même de plus en plus rares depuis février 2021, et ils se limitent à faire état de quelques activités officielles. Le ministre de l’Intérieur, du Développement communautaire et de la Sécurité publique et le nouveau secrétaire général du CNDD-FDD, n’ont pas eux non plus fait l’objet d’articles récents sur le site de la RTNB, alors que celle-ci avait suivi de près les descentes sur le terrain d’Évariste Ndayishimiye lorsqu’il occupait ce poste et notamment lorsqu’il venait d’être désigné comme candidat du parti pour l’élection présidentielle. En revanche, toujours pendant cette période, le Président du Sénat est également omniprésent avec plus d’une quarantaine d’articles qui lui ont été consacrés, y compris sur ses activités privées et religieuses. Le Président de l’Assemblée nationale bénéficie quant à lui d’une couverture médiatique moindre avec seulement une dizaine d’articles, tout comme le vice-Président de la République et les autres ministres qui ne font l’objet que d’une poignée d’articles chacun.\nd)\tLe processus de justice transitionnelle et le travail de mémoire"},{"id":"a-hrc-48-crp-1-p0310","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"310","seq":310,"section":"2. Développements notables pour l’analyse des facteurs de risque","text":"La Commission vérité et réconciliation (CVR) a poursuivi ses activités qui consistent principalement à l’exhumation de fosses communes de victimes des massacres de 1972, notamment dans les provinces Gitega, Karusi, Makamba, Rumonge, Bururi, Kirundo, Muyinga, mais aussi à l’été 2021 en Mairie de Bujumbura et ses environs. Le 7 janvier 2021, le Président de la CVR a présenté son rapport d’étape pour 2020 au Parlement réuni en Congrès. Dans celui-ci, la CVR a détaillé ses activités de vérification et d’exhumation ainsi que son rapport sur le déroulement des évènements de 1972 et les principaux modes opératoires de ces massacres de masse."},{"id":"a-hrc-48-crp-1-p0311","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"311","seq":311,"section":"2. Développements notables pour l’analyse des facteurs de risque","text":"Le travail de la CVR reste entaché par les accusations concernant sa partialité, et sans surprise, ses activités ont suscité des inquiétudes parmi les Burundais. Par exemple, au cours d’une rencontre organisée le 25 mars 2021 entre la CVR, des intellectuels et des universitaires burundais, certains ont déclaré craindre que le travail de la CVR ne réveille des mémoires blessées qui pourraient conduire à des cas de représailles, et ils ont voulu savoir comment la Commission procédait pour répondre à cette question. Malheureusement, la CVR a une fois de plus esquivé la question, pourtant pertinente, légitime et cruciale. Son Président se contente de répéter que la vérité libère et permet la véritable réconciliation, et à préciser que la CVR a un mandat portant sur la période de 1885 à 2008 qui lui permettra de travailler dans le futur sur les autres crises."},{"id":"a-hrc-48-crp-1-p0312","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"312","seq":312,"section":"2. Développements notables pour l’analyse des facteurs de risque","text":"Si la recherche de la vérité est effectivement un objectif important et louable dans le cadre d’un processus de justice transitionnelle, celui-ci est néanmoins tellement complexe et sensible que des précautions doivent être prises pour éviter de faire ressurgir les anciens antagonismes. Les processus mémoriels peuvent devenir « des tyrannies mémorielles, notamment lorsque la prolifération des mémoriaux ne tient pas compte des points de vue différents ou ne tolère pas la remise en question, enferme les populations dans leur passé et laisse peu de place au souvenir d’autres événements et relations entre les groupes de personnes […] trop de mémoire, en particulier si elle représente des versions irréconciliables du passé, peut nuire à une société au lieu de l’aider. Toutes les sociétés sortant d’un conflit ou divisées font face à la nécessité d’établir un équilibre fragile entre l’oubli et la mémoire ». De plus, un processus de justice transitionnelle effectif doit comprendre une approche globale comprenant les autres piliers et pas seulement la recherche de la vérité, à savoir des poursuites pénales individuelles, la mise en place d’un programme de réparation pour les victimes et des réformes institutionnelles afin de garantir que de tels actes ne se reproduisent plus."},{"id":"a-hrc-48-crp-1-p0313","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"313","seq":313,"section":"2. Développements notables pour l’analyse des facteurs de risque","text":"Sans doute pour anticiper les possibles critiques et controverses à venir, lors d’une retraite organisée du 13 au 16 juillet 2021, la CVR a décidé que pour procéder à la qualification juridique des évènements de 1972, elle demanderait l’appui d’experts juristes pour l’aider à mener à bien ce travail. De même, le 5 août 2021, le Président de la CVR a organisé une conférence de presse pour faire le point sur le travail accompli au cours de laquelle il a clarifié qu’au-delà de l’identification et l’exhumation des fosses communes, le travail de la CVR comprenait également : des contacts et des audiences auprès des représentants des institutions ; la visite des archives disponibles ; l’identification des auteurs présumés et les sauveteurs ; l’audition des témoins, des victimes et des autres personnes ressources."},{"id":"a-hrc-48-crp-1-p0314","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"314","seq":314,"section":"2. Développements notables pour l’analyse des facteurs de risque","text":"En parallèle du travail de la CVR, le Sénat a organisé entre avril et juin 2021 une série de cinq conférences portant sur les massacres de 1972 avec pour thème « se souvenir et bien qualifier les événements de 1972 au Burundi », sans qu’elles ne soient directement liées au travail de la CVR ou organisées en concertation avec cette dernière. Le Président du Sénat a indiqué que l’objectif était de « donner une opportunité à tout Burundais qui le souhaite de témoigner sur les crimes commis au Burundi en 1972 afin que la vérité soit connue ». Le Sénat a justifié son projet par le rôle qui lui a été confié de « conseiller le Président de la République et le Président de l’Assemblée nationale sur toute question, notamment d’ordre législatif », notamment sur la question de l’éradication des divisions ethniques afin de construire un Burundi juste, équitable et véritablement réconcilié. En outre, il a été également mentionné que ces conférences permettraient au Sénat de se prononcer sur la possible abolition des quotas ethniques dans le futur comme le prévoit la Constitution, sans autrement expliquer la raison pour laquelle et comment les évènements de 1972 serviraient de base à la décision du Sénat à cet égard."},{"id":"a-hrc-48-crp-1-p0315","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"315","seq":315,"section":"2. Développements notables pour l’analyse des facteurs de risque","text":"Les organisateurs et les participants ont affirmé que ces conférences n’avaient pas pour objectif « de susciter un esprit de vengeance mais de guérir et libérer les âmes meurtries, favoriser la réconciliation afin de léguer à la jeunesse un Burundi meilleur ». Elles ne cherchaient pas non plus à « accuser les Batutsi ou les Bahutu. C’est plutôt de guérir les âmes blessées par ces évènements malheureux, favoriser une véritable réconciliation entre les burundais, informer correctement la jeunesse sur l’histoire du pays pour ne plus retomber dans les mêmes travers afin de bâtir un Burundi meilleur »."},{"id":"a-hrc-48-crp-1-p0316","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"316","seq":316,"section":"2. Développements notables pour l’analyse des facteurs de risque","text":"Cependant, le principal et quasi unique intervenant lors de ces conférences a été l’ancien président Sylvestre Ntibantunganya, qui a présenté une version controversée des évènements déclencheurs des massacres et qui en tout cas diffère de celle présentée par la CVR dans son rapport annuel. En effet, la CVR a rappelé que préalablement à la planification des massacres de 1972, « il y a eu des attaques des insurgés bahutu dans la province de Bururi surtout dans l’arrondissement de Makamba et sur le littoral du lac Tanganyika ». L’ancien Président Ntibantunganya déclare au contraire que les massacres initiaux des populations tutsies dans le Sud du pays auraient été organisés par le Président Micombero lui-même, qui se serait appuyé sur des mercenaires étrangers manipulés, afin de pouvoir par la suite justifier les massacres de Hutus commis dans le cadre de la répression. Très rapidement, dans le cadre de ces conférences, les appels se sont multipliés afin que ces évènements soient reconnus par le Gouvernement du Burundi, mais également par la communauté internationale comme un génocide contre les Hutus. Pour rappel, la CVR préfère quant à elle attendre la fin de ses enquêtes et obtenir l’appui d’experts juridiques pour procéder à l’éventuelle qualification juridique de ces évènements."},{"id":"a-hrc-48-crp-1-p0317","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"317","seq":317,"section":"2. Développements notables pour l’analyse des facteurs de risque","text":"Une telle multiplication d’initiatives parallèles et quelque peu concurrentes, voire contradictoires, conjugué à leur approche unilatérale et partiale de l’histoire du pays, accentue le risque d’une lecture mémorielle ethnique et de surenchère dans la victimisation d’une ethnie par rapport à l’autre. En toute logique, ces activités ont fait resurgir des controverses au sein de la société burundaise et ont donc accru le risque d’incitation à la haine ethnique.\ne)\tLes activités de recensement"},{"id":"a-hrc-48-crp-1-p0318","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"318","seq":318,"section":"2. Développements notables pour l’analyse des facteurs de risque","text":"Le Gouvernement a décidé d’effectuer un recensement de tous les fonctionnaires, initialement prévu pour les 26 et 27 octobre 2020, mais qui a dû être prolongé jusqu’au 6 novembre 2020. L’objectif était « d’avoir des données fiables en rapport avec toutes les ressources humaines de l’État en vue d’une gestion rationnelle ». Le ministre de la Fonction publique, du Travail et de l’Emploi a d’ailleurs proposé de mettre en place un centre des données qui hébergerait toutes les données collectées par le Gouvernement, ainsi que l’extension du recensement aux sociétés mixtes et au secteur privé."},{"id":"a-hrc-48-crp-1-p0319","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"319","seq":319,"section":"2. Développements notables pour l’analyse des facteurs de risque","text":"Cependant, ce recensement a été critiqué et il a soulevé de nombreuses préoccupations en raison notamment de questions sensibles et personnelles dont la raison d’être n’était pas justifiée dans le cadre de la gestion des ressources humaines, d’autant plus que les autorités n’ont pas présenté de réelles garanties sur la manière dont ces données seraient conservées, protégées ou utilisées. En effet, parmi la centaine de questions demandées, les fonctionnaires devaient indiquer leur appartenance ethnique, leur adresse email privée, leur confession religieuse, l’identité et la profession de leurs parents, leur éventuelle affiliation à un syndicat, ainsi que fournir une photo d’eux-mêmes et une copie recto/verso de leur carte nationale d’identité."},{"id":"a-hrc-48-crp-1-p0320","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"320","seq":320,"section":"2. Développements notables pour l’analyse des facteurs de risque","text":"Par ailleurs, comme le dernier recensement de la population burundaise remonte à 2008, dans la perspective de la mise en place de l’Union monétaire de la Communauté d’Afrique de l’Est en 2024, le Gouvernement burundais a commencé à préparer le recensement global de la population, de l’habitat, de l’agriculture et de l’élevage qui sera organisé en 2022. Dans cette perspective, la nouvelle loi portant réorganisation du système statistique au Burundi adoptée par l’Assemblée nationale le 23 février 2021 prévoit « l’obligation pour les personnes physiques et morales de répondre aux questions statistiques » sous peine de sanction pénale. La loi garantit « en contrepartie, l’affirmation du secret statistique pour protéger ces personnes ». Les 22 et 23 juillet 2021, l’Institut des statistiques et d’études économiques du Burundi (ISTEEBU) a organisé, en partenariat avec le Fonds des Nations Unies pour la population (UNFPA), un atelier technique de consultation afin d’examiner, d’enrichir et de finaliser le questionnaire du recensement général de 2022. Il reste à voir si ce dernier va inclure des questions sensibles à l’instar de celles demandées aux fonctionnaires, notamment leur appartenance ethnique, et comment cela serait perçu au sein de la société burundaise et avec quelles répercussions possibles."},{"id":"a-hrc-48-crp-1-p0321","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"321","seq":321,"section":"B. Facteurs de risque","text":"L’analyse des facteurs de risque démontre que la situation au Burundi mérite toujours une grande vigilance. L’instabilité en matière de sécurité qui crée un environnement propice aux atrocités criminelles (facteur de risque no 1) est révélée par les indicateurs suivants : crise sécuritaire provoquée par des actes de terrorisme et multiplication des incidents de sécurité (1b) ; urgence humanitaire pour les Burundais à l’intérieur et à l’extérieur du pays pouvant être causée notamment par une catastrophe naturelle ou une épidémie (1c) ; tension politique provoquée par des régimes autocratiques ou une lourde répression de l’opposition politique (1f) ; instabilité économique provoquée par une pénurie de ressources (1g) ; crise grave de l’économie nationale (1h) ; grande pauvreté de la population (1i)."},{"id":"a-hrc-48-crp-1-p0322","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"322","seq":322,"section":"B. Facteurs de risque","text":"En revanche, les indicateurs suivants se sont estompés : si la crise politique née du transfert de pouvoir non pacifique en 2015 n’a pas été résolue, les élections de 2020 et des déclarations visant à normaliser les relations entre le Burundi et la communauté internationale ont atténué cet aspect (1d). De même, les allégations de fraudes électorales massives en 2020 ne semblent pas avoir de conséquences sur la perception de la légitimité du Gouvernement (1d)."},{"id":"a-hrc-48-crp-1-p0323","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"323","seq":323,"section":"B. Facteurs de risque","text":"Le facteur de risque no 2 concerne l’existence d’antécédents de violations graves des droits de l’homme qui n’ont été ni empêchées ni punies, créant ainsi un risque de survenance de nouvelles violations. Ce facteur de nature structurelle, lié à l’absence de volonté politique et à la faiblesse des institutions pour lutter contre l’impunité, reste donc significatif : violations graves, passées et actuelles, des droits de l’homme (2a) ; actes de génocide, crimes contre l’humanité et crimes de guerre qui ont marqué l’histoire récente (2b) ; politique ou pratique d’impunité ou de tolérance à l’égard des violations graves des droits de l’homme (2c) ; refus du Gouvernement d’utiliser tous les moyens possibles pour faire cesser les violations ou sa réticence à le faire (2d) ; maintien d’une aide aux groupes accusés de violations et non-condamnation de leurs actes (2e) ; rapports partiaux concernant les violations graves des droits de l’homme ou refus du Gouvernement de reconnaître l’existence de telles violations (2f) ; absence de processus de réconciliation ou de justice transitionnelle impartial et inclusif (2g) ; méfiance généralisée de la population envers les institutions de l’État en raison de l’impunité (2h)."},{"id":"a-hrc-48-crp-1-p0324","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"324","seq":324,"section":"B. Facteurs de risque","text":"Le facteur de risque no 3, qui concerne la faiblesse des structures étatiques et met en cause la capacité de l’État de prévenir les atrocités criminelles ou de les faire cesser et de les juger, reste également présent : manque de ressources et de représentation adéquate dans les institutions judiciaires et celles chargées de l’application des lois et de la protection des droits de l’homme (3b) ; absence de justice indépendante et impartiale (3c) ; absence de contrôle civil efficace des forces de sécurité (3d) ; niveau élevé de corruption et de mauvaise gouvernance (3e) ; mécanismes internes de contrôle et d’établissement des responsabilités inadéquats et ineffectifs et mécanismes externes quasi inexistants ou difficilement accessibles aux victimes (3f)."},{"id":"a-hrc-48-crp-1-p0325","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"325","seq":325,"section":"B. Facteurs de risque","text":"Le facteur de risque n°4 porte sur l’existence de raisons, de buts ou d’autres éléments motivant l’usage de la violence contre des groupes particuliers. Ce facteur reste présent avec plusieurs indicateurs : motivations politiques visant la consolidation du pouvoir en place (4a) ; intérêts économiques liés à la conservation du pouvoir (4b) ; opposants politiques perçus comme une menace aux intérêts ou aux objectifs du Gouvernement, ou considérés comme déloyaux envers le pays (4e) ; appartenance ou adhésion, réelle ou supposée, de groupes à l’opposition armée (4f) ; idéologie du CNDD-FDD marquée par son paradigme de « vérité » et donc de suprématie de cette identité politique sur toutes les autres (4g) ; instrumentalisation des griefs et des cas d’impunité du passé à des fins politiques (4h) ; existence d’un traumatisme social provoqué par des situations de violence passées non résolues qui ont engendré des sentiments de perte, de déplacement et d’injustice ainsi qu’un désir possible de revanche (4i)."},{"id":"a-hrc-48-crp-1-p0326","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"326","seq":326,"section":"B. Facteurs de risque","text":"Le facteur de risque no 5, qui est la capacité des auteurs potentiels de commettre des atrocités criminelles, reste présent : disponibilité de personnel, d’armes et de munitions ou de moyens financiers publics ou privés permettant de les acquérir (5a) ; capacité de transporter et de déployer du personnel et de transporter et de distribuer des armes et des munitions (5b) ; capacité d’encourager ou de recruter de nombreux partisans au sein de populations ou de groupes et disponibilité de moyens pour les mobiliser (5c) ; solide culture d’obéissance à l’autorité et de conformité au groupe, présente au sein du CNDD-FDD et des Imbonerakure (5d) ; présence d’autres forces armées ou de groupes armés non étatiques (5e)."},{"id":"a-hrc-48-crp-1-p0327","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"327","seq":327,"section":"B. Facteurs de risque","text":"L’absence de facteurs atténuants (facteur de risque n°6) persiste malgré quelques gestes des autorités à l’égard des médias, qui restent insuffisants pour garantir une presse libre et indépendante. Les indicateurs sont les suivants : absence de société civile nationale solide, organisée et représentative, et de médias nationaux libres, diversifiés et indépendants (6b) ; absence d’accès aux médias internationaux (6c) ; coopération limitée, voire inexistante, avec les mécanismes internationaux et régionaux des droits de l’homme (6g) ; manque de volonté du Gouvernement d’engager un dialogue, de faire des concessions et de solliciter l’appui de la communauté internationale, notamment sur les questions des droits de l’homme (6h) ; manque de soutien de certains États limitrophes pour protéger la population burundaise en quête de refuge (6j) ; absence de mécanisme national d’alerte rapide (6k)."},{"id":"a-hrc-48-crp-1-p0328","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"328","seq":328,"section":"B. Facteurs de risque","text":"La question de la coopération et de l’engagement du Burundi avec la communauté internationale et l’Organisation des Nations Unies mais aussi les organisations non gouvernementales internationales ou autres acteurs internationaux ou régionaux (6d) et (6f) est devenue complexe. D’un côté, le pays a redoublé ses efforts au niveau diplomatique afin de normaliser ses relations avec les pays de la région, les organisations internationales et régionales dont l’Union européenne, mais, parallèlement, il s’est opposé à toute coopération portant sur les questions politiques ou relatives aux droits de l’homme, notamment en fermant le Bureau de l’Envoyé spécial des Nations Unies et en refusant la réouverture du Bureau du Haut-Commissariat aux droits de l’homme."},{"id":"a-hrc-48-crp-1-p0329","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"329","seq":329,"section":"B. Facteurs de risque","text":"Le facteur de risque n°7 porte sur un climat et des circonstances propices à la violence et aux violations des droits de l’homme, y compris l’instrumentalisation à des fins politiques de l’identité, d’événements du passé ou de motifs de se livrer à la violence. Les principaux indicateurs sont : l’ingérence dans des institutions vitales de l’État, ou des modifications de leur composition ou de l’équilibre des pouvoirs, ce qui est le cas en matière de quotas ethniques (7b) ; la mobilisation des Imbonerakure dans des zones qui sont le théâtre d’incidents de sécurité (7e) ; les violations persistantes du droit à la vie, du droit à l’intégrité physique, du droit à la liberté et du droit à la sécurité d’opposants politiques (7h) ; la politisation de l’identité et d’événements du passé, même si les déclarations provocatrices, les campagnes de propagande ou d’incitation à la haine avec une dimension politique et/ou ethnique ont diminué (7m)."},{"id":"a-hrc-48-crp-1-p0330","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"330","seq":330,"section":"B. Facteurs de risque","text":"Le facteur de risque n°8 relatif aux facteurs déclencheurs s’était amenuisé à l’issue des élections de 2020. D’autres indicateurs ont également évolué positivement à cet égard : les succès diplomatiques des autorités burundaises auprès de la communauté internationale, dont les mesures ne sont plus systématiquement perçues comme des menaces à la souveraineté de l’État, sauf celles concernant les droits de l’homme (8c) ; les allégations réitérées de fraudes lors des élections 2020 n’ont pas altéré la légitimité du pouvoir (8d) ; les actes d’incitation ou la propagande haineuse envers les opposants politiques ont officiellement diminué après les élections (8g)."},{"id":"a-hrc-48-crp-1-p0331","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"331","seq":331,"section":"B. Facteurs de risque","text":"Cependant des indicateurs persistent : des actes de violence graves (8e) ; le problème de la mémoire et de la commémoration officielle des crimes du passé ou d’épisodes traumatiques ou historiques sur une base ethnique qui pourrait exacerber les tensions entre groupes (8k) ; et des actes liés aux processus d’établissement des responsabilités pour des atrocités passées qui peuvent être perçus comme injustes (8l). Il reste aussi à voir ce qu’il sera fait du recensement de tous les fonctionnaires et de celui à venir de la population, et des craintes et critiques qu’ils suscitent en raison de questions sur l’appartenance ethnique (8h)."},{"id":"a-hrc-48-crp-1-p0332","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"332","seq":332,"section":"V. Conclusions et recommandations","text":"Après plus d’un an d’exercice du pouvoir, si le Président Ndayishimiye et son Gouvernement ont nettement amélioré les relations entre le Burundi et la communauté internationale, peu de choses ont changé en profondeur au niveau des droits de l’homme. Des gestes symboliques, parfois spectaculaires, ont été faits, mais ils ne peuvent pas contribuer à lutter durablement contre l’impunité ou la corruption ni à rouvrir l’espace démocratique. Des violations graves des droits de l’homme ont continué à être commises par des agents de l’État et des Imbonerakure à l’instigation des autorités ou avec leur acquiescement. Les facteurs de risque ont certes évolué, mais ils demeurent tous présents."},{"id":"a-hrc-48-crp-1-p0333","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"333","seq":333,"section":"V. Conclusions et recommandations","text":"La Commission fait donc les recommandations suivantes aux autorités burundaises :\na)\tMettre en œuvre les précédentes recommandations de la Commission, notamment celles concernant les mesures prioritaires pour faire cesser les violations des droits de l’homme et les crimes internationaux, lutter contre l’impunité et les malversations économiques, rouvrir l’espace démocratique, garantir les libertés publiques, réformer le système judiciaire et contrôler les Imbonerakure ;\nb)\tReconnaître publiquement l’existence des violations des droits de l’homme commises au Burundi depuis avril 2015, rechercher et punir les responsables, et accorder des réparations aux victimes ;\nc)\tGarantir la sécurité, la liberté et l’intégrité physique des opposants politiques et de leurs proches, des journalistes, des membres de la société civile, des défenseurs des droits de l’homme et des rapatriés ; veiller à ce qu’ils ne fassent pas l’objet d’actes de violence, d’intimidation, de harcèlement ou de toute forme de discrimination, notamment dans l’exercice de leurs libertés fondamentales ;\nd)\tGarantir que la recherche des responsables d’attaques armées se fasse dans le respect des droits fondamentaux et des procédures légales et sans discrimination ;\ne)\tFaire cesser définitivement l’usurpation des fonctions des forces de sécurité ou de la justice par des Imbonerakure, et poursuivre en justice et sanctionner de manière exemplaire ceux impliqués dans des violations ;\nf)\tInstaurer un mécanisme national de prévention de la torture conforme aux normes internationales, qui s’attèle en priorité à empêcher la torture par les agents du SNR ;\ng)\tCoopérer pleinement avec tous les mécanismes internationaux et régionaux des droits de l’homme, y compris sur les questions sensibles, et leur permettre d’entreprendre des activités de contrôle indépendant et, dans ce sens, rouvrir le bureau de pays du Haut-Commissariat des Nations Unies aux droits de l’homme ;\nh)\tPrendre des mesures afin de lutter efficacement contre la corruption, notamment en mettant en œuvre les recommandations du Groupe d’examen de l’application de la Convention des Nations Unies contre la corruption, mais également en :\nInstituant des sanctions significatives pour les faits de corruption de nature à garantir une dissuasion administrative, réglementaire, financière et économique :\nRenforçant la gestion des programmes de développement, notamment leur suivi et l’évaluation, les audits, les retours d’information et les examens par des organismes consultatifs internationaux et indépendants à travers des objectifs mesurables afin d’éradiquer toute possibilité de détournement des fonds ;\nMaintenant, réformant et améliorant l’efficacité des institutions spécialisées anti-corruption, notamment la Cour anti-corruption et la Brigade spéciale anti-corruption ;\ni)\tGarantir la transparence et la bonne gouvernance dans la gestion des ressources provenant de l'exploitation minière, notamment en :\nMettant en œuvre les Lignes directrices de l’OCDE sur la diligence raisonnable pour des chaînes d’approvisionnement responsables en minéraux provenant de zones touchées par un conflit ou à haut risque ;\nPrenant toutes les mesures nécessaires pour se conformer immédiatement au système de suivi et de certification des minéraux de la CIRGL ;\nAdhérant à l’Initiative pour la transparence dans les industries extractives (ITIE) ;\nÉtablissant un registre national public des membres et principaux actionnaires des sociétés burundaises qui sont parties à des contrats miniers ;\nGarantissant que les renégociations de licences minières se fassent en toute transparence ;\nj)\tGarantir que le travail de la Commission vérité et réconciliation soit professionnel, inclusif, impartial, objectif, transparent, équilibré, intègre et crédible, pour qu’il puisse contribuer véritablement et durablement à la réconciliation nationale ;\nk)\tPrendre des mesures urgentes afin de restaurer l’état de droit en garantissant le règne de la loi, y compris au sein du Gouvernement et des institutions de l’appareil d’État, et le respect de la séparation des pouvoirs, y compris en veillant au respect des équilibres ethniques dans la structure des institutions étatiques, conformément à l’accord de paix d’Arusha et la Constitution burundaise ;\nl)\tGarantir la jouissance par la population du droit à la vie dans la dignité et de ses droits économiques et sociaux, particulièrement le droit à un niveau de vie suffisant, notamment en élaborant et mettant en œuvre les budgets de l’État de manière à utiliser au maximum les ressources disponibles."},{"id":"a-hrc-48-crp-1-p0334","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"334","seq":334,"section":"V. Conclusions et recommandations","text":"La Commission recommande aux groupes armés de cesser les atteintes aux droits de l’homme et tout acte de violence contre les institutions de l’État et contre les civils."},{"id":"a-hrc-48-crp-1-p0335","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"335","seq":335,"section":"V. Conclusions et recommandations","text":"La Commission adresse à la communauté internationale les recommandations suivantes :\na)\tMaintenir sa vigilance sur la situation des droits de l’homme au Burundi, notamment grâce à un mécanisme international indépendant qui puisse suivre objectivement la situation des droits de l’homme dans ce pays ;\nb)\tVeiller à ce que les réfugiés ne soient pas forcés à rentrer au Burundi dans le cadre du programme tripartite d’appui au retour volontaire, notamment en raison de conditions de vie dégradées, et à ce que les retours soient volontaires, dignes et sécurisés ;\nc)\tSoutenir les organisations indépendantes de la société civile travaillant sur les droits de l’homme au Burundi, y compris celles en dehors du pays, notamment pour faire des enquêtes et des rapports publics sur les violations des droits de l’homme dans ce pays."},{"id":"a-hrc-48-crp-1-p0336","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"336","seq":336,"section":"V. Conclusions et recommandations","text":"La Commission adresse aux partenaires techniques et financiers du Burundi les recommandations suivantes :\na)\tMettre en place des procédures pour minimiser au maximum et éradiquer les risques de malversations économiques dans le cadre de projets d’aide au développement ;\nb)\tFavoriser les projets qui visent à atténuer durablement les facteurs de risque et améliorer la transparence et la redevabilité en matière de gestion des finances publiques."},{"id":"a-hrc-48-crp-1-p0337","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"337","seq":337,"section":"V. Conclusions et recommandations","text":"Finalement, la Commission recommande à l’Alliance mondiale des institutions nationales des droits de l’homme (GANHRI) de veiller à ce que la Commission nationale indépendante des droits de l’homme soit en mesure de fonctionner de manière conforme aux principes de Paris, y compris en l’aidant à renforcer son indépendance et ses capacités."},{"id":"a-hrc-48-crp-1-p0001-a1","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"1","seq":338,"section":"1. Recommandations faites en 2020","text":"Vu la profondeur historique de la crise burundaise et la dimension en partie structurelle des violations des droits de l’homme, et prenant en compte le principe de la responsabilité de protéger le peuple burundais, y compris dans le cadre de la transition politique en cours au Burundi, ainsi que les mesures susceptibles d’atténuer les facteurs de risque, la Commission réitère tout d’abord ses précédentes recommandations, qui demeurent entièrement valables et pertinentes, particulièrement celles adressées aux autorités burundaises concernant les mesures prioritaires pour faire cesser les violations des droits de l’homme et les crimes internationaux, lutter contre l’impunité et améliorer la situation des droits de l’homme dans le pays, notamment la réouverture de l’espace démocratique et la protection des libertés publiques. Ses recommandations portant sur les mesures à plus long terme relatives à la révision du cadre juridique et à la réforme du système judiciaire restent cruciales.","annex":1},{"id":"a-hrc-48-crp-1-p0002-a1","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"2","seq":339,"section":"1. Recommandations faites en 2020","text":"Ensuite, la Commission adresse aux autorités burundaises les recommandations suivantes:\na.\tRouvrir le bureau de pays du Haut-Commissariat aux droits de l’homme;\nb.\tLibérer immédiatement les défenseurs des droits de l’homme et journalistes détenus arbitrairement, ainsi que tous les prisonniers politiques, notamment ceux des partis d’opposition arrêtés et détenus dans le contexte des élections de 2020;\nc.\tGarantir la sécurité, la liberté et l’intégrité physique des membres des partis d’opposition, dont le CNL, et assurer qu’ils ne fassent pas l’objet d’actes d’intimidation, de harcèlement ou de toute forme de discrimination en représailles à leur engagement politique;\nd.\tRétablir toutes les libertés publiques pour permettre que les futures échéances électorales soient libres, crédibles et transparentes;\ne.\tFaire cesser l’usurpation des fonctions des forces de sécurité ou de la justice par des Imbonerakure, et poursuivre en justice et sanctionner de manière exemplaire ceux ayant été impliqués dans des violations − sinon dissoudre cette ligue;\nf.\tRéformer les comités mixtes de sécurité humaine afin de les rendre plus inclusifs et de limiter leurs compétences;\ng.\tS’acquitter de leurs obligations spécifiques en matière de droits des femmes et de droits de l’enfant;\nh.\tMettre fin au recrutement des enfants par les Imbonerakure et démanteler les « aiglons » du CNDD-FDD;\ni.\tÉtablir des services de prise en charge psychosociale pour les enfants victimes ou témoins de violations graves, particulièrement parmi les rapatriés;\nj.\tGarantir l’accès à la justice et à des services médicaux et psychosociaux adaptés aux victimes de violences sexuelles, y compris les victimes masculines;\nk.\tInstituer un quota de 30% de femmes dans les conseils collinaires;\nl.\tReprendre une pleine coopération avec l’Organisation mondiale de la Santé;\nm.\tPrendre des mesures afin de lutter efficacement contre les malversations économiques, notamment en assurant la transparence, la concurrence et l’établissement de critères objectifs et prédéterminés pour la passation des marchés publics, ainsi qu’un système de recours interne efficace, et ouvrir des enquêtes sur les allégations de cas de biens mal acquis;\nn.\tDevenir partie à l’Initiative pour la transparence dans les industries extractives et mettre en œuvre les normes associées;\no.\tPublier systématiquement le budget annuel exécuté;\np.\tGarantir que les hauts responsables politiques et administratifs procèdent systématiquement à une déclaration publique de leur patrimoine à leur prise de fonction et à la fin de leur mandat.","annex":1},{"id":"a-hrc-48-crp-1-p0003-a1","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"3","seq":340,"section":"1. Recommandations faites en 2020","text":"Aux groupes rebelles d’opposition, la Commission recommande de s’abstenir de tout acte violent.","annex":1},{"id":"a-hrc-48-crp-1-p0004-a1","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"4","seq":341,"section":"1. Recommandations faites en 2020","text":"À la communauté internationale, conformément à son devoir de vigilance, la Commission adresse les recommandations suivantes:\na.\tMaintenir un mécanisme international indépendant qui puisse suivre objectivement la situation des droits de l’homme au Burundi, y compris au moyen des facteurs de risque et de la mise en œuvre des recommandations de la Commission;\nb.\tBaser la reprise de la coopération internationale avec le Burundi et la levée des sanctions sur des progrès tangibles en matière de droits de l’homme et de lutte contre l’impunité et la corruption;\nc.\tS’assurer que les réfugiés ne soient pas forcés à rentrer au Burundi tant que les conditions dans le pays ne sont pas propices, et demander un accès libre aux rapatriés pour évaluer leur situation;\nd.\tSoutenir les organisations de la société civile actives dans le domaine des droits de l’homme au Burundi, notamment pour faire des enquêtes et des rapports publics.","annex":1},{"id":"a-hrc-48-crp-1-p0005-a1","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"5","seq":342,"section":"1. Recommandations faites en 2020","text":"Aux États et aux organisations internationales qui financent des programmes d’aide internationale au développement, la Commission recommande de renforcer leurs procédures pour minimiser les risques de détournement de fonds et d’ouvrir systématiquement des enquêtes sur les allégations reçues à ce sujet, afin de s’assurer que ladite assistance est entièrement utilisée pour les objectifs prévus et au profit des bénéficiaires envisagés.","annex":1},{"id":"a-hrc-48-crp-1-p0006-a1","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"6","seq":343,"section":"1. Recommandations faites en 2020","text":"Au système des Nations Unies, y compris à ses agences, la Commission adresse les recommandations suivantes:\na.\tConformément à la politique de diligence voulue en matière de droits de l’homme, fournir un appui uniquement lorsqu’il y a des garanties que ceux qui sont appelés à en bénéficier ne sont pas des auteurs de violations graves des droits de l’homme, sur le plan individuel ou institutionnel, et ne pas fournir un tel appui lorsqu’il y a eu des allégations crédibles à cet égard ou lorsque les autorités compétentes ne prennent pas les mesures de correction ou d’atténuation nécessaires;\nb.\tRenforcer l’appui à la réponse aux violences sexuelles ou fondées sur le genre pour mieux prendre en compte les besoins spécifiques des victimes, y compris parmi les réfugiés.\nVersion anglaise","annex":1},{"id":"a-hrc-48-crp-1-p0001-a2","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"1","seq":344,"section":"1. Recommandations faites en 2020","text":"In view of the historical depth of the Burundian crisis and the partly structural dimension of human rights violations, and taking into account the principle of the responsibility to protect the people of Burundi, including in the context of the political transition under way in the country, as well as the measures likely to mitigate risk factors, the Commission first reiterates its previous recommendations. Those recommendations remain entirely valid and relevant, particularly those addressed to the Burundian authorities concerning measures to be given priority in order to put an end to human rights violations and international crimes, to combat impunity and to improve the human rights situation in the country, including the reopening of the democratic space and the protection of civil liberties. Its recommendations for longer-term measures relating to the review of the legal framework and the reform of the judiciary remain crucial.","annex":2},{"id":"a-hrc-48-crp-1-p0002-a2","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"2","seq":345,"section":"1. Recommandations faites en 2020","text":"The Commission also makes the following recommendations to the Burundian authorities:\na.\tTo reopen the country office of the Office of the United Nations High Commissioner for Human Rights;\nb.\tTo immediately release human rights defenders and journalists who have been arbitrarily detained, as well as all political prisoners, including those from opposition parties arrested and detained in the context of the 2020 elections;\nc.\tTo guarantee the safety, freedom and physical integrity of members of opposition parties, including the Congrès national pour la liberté, and to ensure that they are not subjected to intimidation, harassment or any form of discrimination as a reprisal for their political activities;\nd.\tTo restore all civil liberties to enable future elections to be free, credible and transparent;\ne.\tTo stop the Imbonerakure from usurping the functions of the security forces and the judiciary and to prosecute and punish, as an example, those who have been involved in violations, or alternatively to dissolve the Imbonerakure;\nf.\tTo reform the Joint Human Security Committees to make them more inclusive and to limit the scope of their competence;\ng.\tTo fulfil the specific obligations of the authorities with regard to women’s rights and the rights of the child;\nh.\tTo put an end to the recruitment of children by the Imbonerakure and to disband the CNDD-FDD party’s “Little Eagles”;\ni.\tTo establish psychosocial care services for child victims and witnesses of serious human rights violations, particularly among returnees;\nj.\tTo ensure access to justice and appropriate medical and psychosocial services for victims of sexual violence, including male victims;\nk.\tTo establish a 30 per cent quota for women on hill district councils;\nl.\tTo resume full cooperation with the World Health Organization;\nm.\tTo take measures to effectively combat economic misfeasance, in particular by ensuring transparency, competition and the establishment of objective and pre-established criteria for the awarding of government contracts, as well as an effective system of domestic remedies, and to investigate allegations of cases of ill-gotten gains;\nn.\tTo become a party to the Extractive Industries Transparency Initiative and to implement the related standards;\no.\tTo systematically publish the annual budget, as implemented;\np.\tTo ensure that senior political and administrative officials systematically make a public declaration of their assets upon taking office and at the end of their term.","annex":2},{"id":"a-hrc-48-crp-1-p0003-a2","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"3","seq":346,"section":"1. Recommandations faites en 2020","text":"The Commission recommends that opposition rebel groups refrain from violence.","annex":2},{"id":"a-hrc-48-crp-1-p0004-a2","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"4","seq":347,"section":"1. Recommandations faites en 2020","text":"For the international community, in keeping with its duty of vigilance, the Commission has the following recommendations:\na.\tTo maintain an independent international mechanism that can objectively monitor the human rights situation in Burundi, including through the monitoring of risk factors and the implementation of the Commission’s recommendations;\nb.\tTo base the resumption of international cooperation with Burundi and the lifting of sanctions on tangible progress in the area of human rights and the fight against impunity and corruption;\nc.\tTo ensure that refugees are not forced to return to Burundi until conditions in the country are favourable and to request free access to returnees to assess their situation;\nd.\tTo support civil society organizations active in the field of human rights in Burundi, in particular for investigations and public reporting.","annex":2},{"id":"a-hrc-48-crp-1-p0005-a2","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"5","seq":348,"section":"1. Recommandations faites en 2020","text":"The Commission recommends that States and international organizations funding international development assistance programmes strengthen their procedures to minimize the risk of misappropriation of funds and systematically investigate allegations that they receive in order to ensure that such assistance is fully utilized for the intended purposes and to the benefit of the intended beneficiaries.","annex":2},{"id":"a-hrc-48-crp-1-p0006-a2","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"6","seq":349,"section":"1. Recommandations faites en 2020","text":"To the United Nations system, including its agencies, the Commission makes the following recommendations:\na.\tIn accordance with the human rights due diligence policy, to provide support only when there are guarantees that those who are to benefit from it are not perpetrators of serious human rights violations, either individually or institutionally, and not to provide such support when there have been credible allegations in this regard or when the competent authorities fail to take the necessary corrective or mitigating measures;\nb.\tTo strengthen support for the response to sexual and gender-based violence in order to better address the specific needs of victims, including among refugees.","annex":2},{"id":"a-hrc-48-crp-1-p0001-a3","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"1","seq":350,"section":"2. Recommandations faites en 2019","text":"La tenue des élections de 2020 est un facteur de risque important. Afin qu’elles puissent se dérouler dans un climat apaisé tout en étant justes, libres, transparentes et crédibles, la Commission adresse aux autorités burundaises les recommandations suivantes:\na.\tMettre en œuvre toutes les recommandations précédentes de la Commission, qui restent plus que jamais valables et pertinentes, notamment celles concernant les mesures prioritaires afin de faire cesser les violations des droits de l’homme et les crimes internationaux, de lutter contre l’impunité, et d’améliorer la situation des droits de l’homme dans le pays, ainsi que celles à moyen et plus long termes relatives à la révision du cadre juridique et à la réforme du système judiciaire;\nb.\tDiligenter sans délai des enquêtes indépendantes et effectives sur les cas de violations documentés par la Commission depuis 2015, afin de permettre l’instauration d’un climat de confiance et de tolérance politique encourageant une participation inclusive dans le processus électoral;\nc.\tSe réengager de manière constructive et coopérative auprès de tous les mécanismes internationaux et régionaux des droits de l’homme et du Haut-Commissariat aux droits de l’homme, en leur permettant d’assurer pleinement et librement leurs mandats de suivi des droits de l’homme;\nd.\tAssurer l’indépendance structurelle et financière des mécanismes nationaux des droits de l’homme et renforcer la capacité de leurs membres;\ne.\tPrendre les mesures nécessaires afin de garantir la liberté d’établissement, d’organisation et de fonctionnement des ONG étrangères et nationales, y compris en révisant les lois qui les régissent;\nf.\tPrendre les mesures nécessaires afin de garantir la liberté d’information dans le pays et le droit des médias locaux et internationaux d’exercer leurs activités conformément aux normes internationales, y compris en révisant les lois sur la presse et le Conseil national de la communication;\ng.\tGarantir la jouissance effective des libertés publiques, notamment les libertés d’opinion, d’expression, d’accès à l’information, d’association, d’assemblée et de religion, y compris en mettant fin à toute pratique de recrutement forcé au sein du parti au pouvoir et de sa ligue des jeunes;\nh.\tAppliquer les Lignes directrices sur l’accès à l’information et les élections en Afrique et les Lignes directrices sur la liberté d’association et de réunion en Afrique de la Commission africaine des droits de l’homme et des peuples;\ni.\tGarantir que tous les partis politiques peuvent mener leurs activités légitimes en toute liberté et sécurité, dans un climat de tolérance politique, notamment en sanctionnant tout propos d’incitation à la haine et à la violence contre les autres partis politiques et leurs membres;\nj.\tGarantir, dans la pratique, notamment en révisant le Code électoral, le droit à prendre part à la gestion des affaires publiques sans discrimination;\nk.\tGarantir, dans la pratique, l’indépendance structurelle de la Commission électorale nationale indépendante, notamment en révisant le décret la régissant afin que sa composition soit inclusive et équilibrée, et renforcer les capacités de ses membres aux échelons municipal et provincial;\nl.\tPermettre l’accès d’observateurs électoraux indépendants, internationaux et régionaux, et leur garantir, ainsi qu’aux observateurs nationaux issus de la société civile ou des partis politiques, une liberté de mouvement et d’action avant, pendant et après les élections;\nm.\tAppliquer les Directives pour les missions d’observation et de suivi des élections de l’Union africaine;\nn.\tPermettre aux opposants politiques de rentrer d’exil afin de participer aux élections de 2020, et garantir leur liberté et leur sécurité, notamment en annulant les mandats d’arrêt contre ceux qui n’ont pas utilisé ou prôné la violence;\no.\tLibérer immédiatement tous les prisonniers politiques arrêtés et détenus en lien avec l’exercice de leurs droits démocratiques;\np.\tRenforcer la formation des forces de maintien de l’ordre, afin d’éviter les mauvais traitements et d’assurer une gestion pacifique des foules;\nq.\tAppliquer les Lignes directrices pour le maintien de l’ordre par les agents chargés de l’application des lois lors des réunions en Afrique, et le manuel de formation y relatif, élaborés par la Commission africaine des droits de l’homme et des peuples;\nr.\tMettre fin à l’impunité des Imbonerakure en exerçant un contrôle sur eux, afin d’éviter l’usurpation des fonctions des forces de sécurité ou de la justice et de faire cesser leurs activités répressives et démonstrations de force sur les collines;\ns.\tMettre fin à toutes les contributions illégales.","annex":3},{"id":"a-hrc-48-crp-1-p0002-a3","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"2","seq":351,"section":"2. Recommandations faites en 2019","text":"À tous les partis politiques burundais, qu’ils participent ou non aux élections, la Commission recommande de s’abstenir de tout acte violent et de toute incitation à la haine et à la violence, notamment dans le contexte des élections de 2020.","annex":3},{"id":"a-hrc-48-crp-1-p0003-a3","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"3","seq":352,"section":"2. Recommandations faites en 2019","text":"Aux groupes rebelles d’opposition, la Commission recommande de s’abstenir de tout acte violent et de toute incitation à la haine et à la violence.","annex":3},{"id":"a-hrc-48-crp-1-p0004-a3","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"4","seq":353,"section":"2. Recommandations faites en 2019","text":"À la communauté internationale, y compris l’Union africaine et le système des Nations Unies, la Commission adresse les recommandations suivante:\na.\tRenouveler le mandat de la présente Commission pour une année supplémentaire;\nb.\tContinuer à suivre l’évolution de la situation des droits de l’homme au Burundi dans le contexte des élections de 2020 et, conformément aux principes de prévention et d’alerte précoce, faire régulièrement l’évaluation des risques, afin de permettre, en cas de détérioration, que soient développées et mises en œuvre des stratégies de réponse adaptées;\nc.\tMettre tout en œuvre pour assurer la tenue d’un dialogue interburundais inclusif afin de régler la crise politique;\nd.\tSoutenir le renforcement des capacités des observateurs électoraux internationaux, régionaux et nationaux;\ne.\tEnvoyer des observateurs régionaux ou internationaux uniquement si leur liberté d’action est garantie dans la pratique;\nf.\tS’assurer que l’aide humanitaire parvient intégralement à la population;\ng.\tRépondre à l’appel de financement du Haut-Commissariat des Nations Unies pour les réfugiés en faveur des réfugiés burundais;\nh.\tS’assurer que le suivi des rapatriés se fait dans la durée, de manière plus fréquente et transparente.","annex":3},{"id":"a-hrc-48-crp-1-p0005-a3","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"5","seq":354,"section":"2. Recommandations faites en 2019","text":"Plus particulièrement, la Commission recommande au système des Nations Unies, conformément à l’initiative Les droits de l’homme avant tout, d’intensifier la promotion des droits de l’homme relevant des mandats propres aux agences et programmes concernés, de même que la collecte et la publication de données objectives et fiables sur la situation au Burundi.","annex":3},{"id":"a-hrc-48-crp-1-p0006-a3","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"6","seq":355,"section":"2. Recommandations faites en 2019","text":"Aux États membres du Conseil de sécurité, la Commission recommande de maintenir le Burundi dans le programme de travail du Conseil, au regard des facteurs de risque identifiés, et d’inviter la Commission à lui rendre compte de ses conclusions.\nVersion anglaise","annex":3},{"id":"a-hrc-48-crp-1-p0001-a4","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"1","seq":356,"section":"2. Recommandations faites en 2019","text":"The 2020 elections pose a major risk. To ensure that they are peaceful, fair, free, transparent and credible, the Commission makes the following recommendations to the Burundian authorities:\na.\tGive effect to all the Commission’s previous recommendations, which are more well-founded and relevant than ever, including those concerning priority measures to end human rights violations and international crimes, combat impunity and improve the human rights situation in the country and the medium- and longer-term recommendations on reforms to the legal framework and the judicial system;\nb.\tConduct prompt, independent and effective investigations into the cases of violations documented by the Commission since 2015 with a view to creating a climate of trust and political tolerance conducive to inclusive participation in the electoral process;\nc.\tRe-engage constructively and cooperatively with all international and regional human rights mechanisms and the Office of the United Nations High Commissioner for Human Rights, enabling them to carry out their human rights monitoring mandates fully and freely;\nd.\tEnsure that national human rights mechanisms are institutionally and financially independent and build the capacity of their members;\ne.\tTake the measures necessary to ensure that foreign and domestic NGOs can be freely established and organized and that they can operate freely, including by amending the laws regulating them;\nf.\tTake the measures necessary to ensure freedom of information in the country and the right of local and international media to operate in accordance with international standards, including by amending the laws on the press and the National Communication Council;\ng.\tGuarantee the effective enjoyment of civil liberties, including the freedoms of opinion, expression, access to information, association, assembly and religion, not least by ending all forced recruitment to the ruling party and its youth league;\nh.\tFollow the Guidelines on Access to Information and Elections in Africa and the Guidelines on Freedom of Association and Assembly of the African Commission on Human and Peoples’ Rights;\ni.\tEnsure that all political parties can engage in legitimate activities in complete freedom and security, in an environment of political tolerance, including by punishing any incitement to hatred and calls for violence against other political parties and their members;\nj.\tEnsure, in practice, the right to participate in the conduct of public affairs without discrimination, in particular by amending the Electoral Code;\nk.\tEnsure, in practice, the institutional independence of the Independent National Electoral Commission, including by amending the decree governing it to make certain that its composition is inclusive and balanced, and strengthen the capacity of its members at the municipal and provincial levels;\nl.\tProvide access to independent international and regional election observers and ensure that they and national observers from civil society or political parties enjoy freedom of movement and action before, during and after the elections;\nm.\tFollow the Guidelines for African Union Electoral Observation and Monitoring Missions;\nn.\tAllow political opponents to return from exile to participate in the 2020 elections and guarantee their freedom and security, including by revoking warrants for the arrest of those who have not used or advocated violence;\no.\tImmediately release all political prisoners arrested and detained in connection with the exercise of their democratic rights;\np.\tMake the training provided to law enforcement agencies more robust to avoid ill-treatment and ensure the peaceful control of crowds;\nq.\tFollow the Guidelines for the Policing of Assemblies by Law Enforcement Officials in Africa and the related training manual, both developed by the African Commission on Human and Peoples’ Rights;\nr.\tEnd the impunity of the Imbonerakure by exercising control over them so as to ensure that the functions of the security forces or the judiciary are not usurped and put an end to their repressive activities and shows of force in the hills;\ns.\tEnd all illegal contributions.","annex":4},{"id":"a-hrc-48-crp-1-p0002-a4","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"2","seq":357,"section":"2. Recommandations faites en 2019","text":"The Commission recommends that, whether they participate in the elections or not, all political parties in Burundi refrain from violence and incitement to hatred or violence, particularly against the backdrop of the 2020 elections.","annex":4},{"id":"a-hrc-48-crp-1-p0003-a4","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"3","seq":358,"section":"2. Recommandations faites en 2019","text":"The Commission recommends that opposition rebel groups refrain from violence and incitement to hatred or violence.","annex":4},{"id":"a-hrc-48-crp-1-p0004-a4","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"4","seq":359,"section":"2. Recommandations faites en 2019","text":"For the international community, including the African Union and the United Nations system, the Commission has the following recommendations: \na.\tRenew the mandate of the Commission for an additional year;\nb.\tContinue to monitor developments in the human rights situation in Burundi in the context of the 2020 elections and, in accordance with the principles of prevention and early warning, carry out regular risk assessments to enable the development and use of appropriate response strategies in the event of deterioration;\nc.\tMake every effort to ensure that an inclusive inter-Burundi dialogue is held to resolve the political crisis;\nd.\tSupport capacity-building for international, regional and national election observers;\ne.\tSend regional or international observers only if their freedom of action is guaranteed in practice;\nf.\tEnsure that all humanitarian aid reaches the population;\ng.\tRespond to the appeal made by the Office of the United Nations High Commissioner for Refugees for funds for Burundi refugees;\nh.\tEnsure that returnees are monitored in a sustained and more regular and transparent manner.","annex":4},{"id":"a-hrc-48-crp-1-p0005-a4","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"5","seq":360,"section":"2. Recommandations faites en 2019","text":"In particular, the Commission recommends that the United Nations system, in accordance with the initiative Human Rights Up Front, take stronger measures to promote human rights, under the mandates of the relevant agencies and programmes, and to collect and publish objective and reliable data on the situation in Burundi.","annex":4},{"id":"a-hrc-48-crp-1-p0006-a4","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"6","seq":361,"section":"2. Recommandations faites en 2019","text":"In view of the risk factors that have been identified, the Commission recommends that the States members of the Security Council keep Burundi on the Council’s programme of work and that the Council invite the Commission to report to it on its conclusions.","annex":4},{"id":"a-hrc-48-crp-1-p0001-a5","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"1","seq":362,"section":"3. Recommandations faites en 2018","text":"La Commission recommande au Gouvernement burundais, comme mesures prioritaires:\na.\tDe mettre immédiatement un terme aux violations graves des droits de l’homme commises par des agents de l’État et des Imbonerakure;\nb.\tD’établir, avec le soutien de la communauté internationale, des mécanismes ad hoc chargés d’enquêter sur les violations des droits de l’homme et de poursuivre les auteurs de crimes de droit international qui ne font pas l’objet d’une enquête par la Cour pénale internationale;\nc.\tD’établir, avec le soutien de la communauté internationale, une entité indépendante chargée de faire la lumière sur les cas de disparition signalés depuis avril 2015, de localiser les possibles fosses communes, d’exhumer et d’identifier les corps;\nd.\tDe prendre des mesures pour que les victimes de torture et les femmes ayant subi des violences sexuelles aient accès à des soins appropriés, en particulier un libre accès à tous les soins de santé sexuelle et reproductive, ainsi qu’à un soutien psychologique;\ne.\tD’appliquer les Lignes directrices sur la lutte contre les violences sexuelles et leurs conséquences en Afrique de la Commission africaine des droits de l’homme et des peuples;\nf.\tDe contrôler les hausses des prix, en particulier en revoyant l’augmentation des taxes et des impôts qui porte atteinte au droit à un niveau de vie suffisant de la population, et en supprimant les contributions qui touchent disproportionnellement les personnes les plus pauvres;\ng.\tDe coopérer avec les mécanismes internationaux des droits de l’homme, notamment:\n•\ti) En accueillant à nouveau des missions de procédures spéciales;\n•\tii) En mettant en œuvre les recommandations de l’examen périodique universel, des organes conventionnels et des procédures spéciales, notamment en établissant un mécanisme national d’élaboration des rapports et de suivi;\nh.\tD’autoriser le Haut-Commissariat des Nations Unies aux droits de l’homme à reprendre sans entrave l’ensemble de ses activités au Burundi;\ni.\tDe signer et de mettre en œuvre le mémorandum d’entente avec l’Union africaine et de permettre le déploiement complet des 100 observateurs des droits de l’homme.","annex":5},{"id":"a-hrc-48-crp-1-p0002-a5","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"2","seq":363,"section":"3. Recommandations faites en 2018","text":"La Commission recommande également au Gouvernement burundais, à moyen et plus long termes:\na.\tDe réviser la loi organique du 8 mars 2018 portant révision de la loi no 01/03 du 24 janvier 2013 portant missions, composition, organisation et fonctionnement du Conseil national de la communication afin de garantir l’indépendance de ce dernier;\nb.\tDe ratifier la Convention internationale pour la protection de toutes les personnes contre les disparitions forcées;\nc.\tDe réviser les dispositions du Code de procédure pénale pour les mettre en conformité avec les normes internationales, en particulier les dispositions relatives aux délais de garde à vue et de contrôle de la détention, aux perquisitions de nuit et sans mandat, à la procédure de « flagrance », à l’infraction d’« atteinte à la sûreté intérieure de l’État », et à celles accordant une impunité de jure aux magistrats et aux officiers de police judiciaire;\nd.\tDe mettre fin aux détentions arbitraires et d’améliorer les conditions de détention:\n•\tEn appliquant les Lignes directrices sur les conditions d’arrestation, de garde à vue et de détention provisoire en Afrique de la Commission africaine des droits de l’homme et des peuples;\n•\tEn garantissant le contrôle de la légalité des détentions et leur conformité avec les droits de l’homme.\ne.\tFaute d’un système judiciaire indépendant et performant, de coopérer pleinement avec la Cour pénale internationale dans l’enquête qu’elle a ouverte le 25 octobre 2017;\nf.\tD’engager une réforme en profondeur du système judiciaire afin de garantir son indépendance, son impartialité et son effectivité, notamment:\n•\ti) En appliquant les Directives et les Principes sur le droit à un procès équitable et à l’assistance judiciaire en Afrique de la Commission africaine des droits de l’homme et des peuples;\n•\tii)\tEn publiant les conclusions des états généraux de la justice de 2013 et en réunissant les acteurs du secteur et les partenaires internationaux pour discuter des mesures de suivi;\n•\tiii) En augmentant le budget du secteur de la justice et en garantissant son autonomie de gestion;\n•\tiv) En revalorisant la rémunération des magistrats des juridictions ordinaires ainsi que les moyens et l’équipement à leur disposition;\n•\tv) En informatisant les greffes;\n•\tvi) En revoyant la composition du Conseil supérieur de la magistrature afin que ses membres soient en majorité désignés par leurs pairs;\n•\tvii) En revoyant les procédures de nomination, d’affectation, de notation et d’avancement des magistrats afin qu’elles ne dépendent pas du pouvoir exécutif;\n•\tviii) En veillant au respect strict du principe d’inamovibilité des magistrats du siège;\n•\tix) En protégeant et en garantissant l’indépendance du système judiciaire en interdisant toute ingérence dans le fonctionnement de la justice par des autorités gouvernementales, des membres du parti au pouvoir ou par des membres des corps de défense et de sécurité, et en prenant des sanctions contre ceux qui influencent, ou cherchent à influencer, le fonctionnement de la justice;\n•\tx) En développant des programmes d’aide juridictionnelle pour les plus vulnérables;\n•\txi) En renforçant les mécanismes de protection de victimes et de témoins, ainsi que leur efficacité, pour restaurer la confiance de la population et pour encourager les témoins à s’exprimer sans crainte pour leur sécurité.\ng.\tDe mettre en place, en consultation avec les bénéficiaires, un programme de réparations des victimes des violations des droits de l’homme qui comprenne des réparations matérielles, symboliques, individuelles et collectives, et qui ne soit pas dépendant de la condamnation des auteurs;\nh.\tD’établir le fond étatique pour les victimes de torture prévu par la loi et en conformité avec l’Observation générale no 4 de la Commission africaine des droits de l’homme et des peuples sur la Charte africaine des droits de l’homme et des peuples, concernant le droit à réparation des victimes de torture et autres peines ou traitements cruels, inhumains ou dégradants (art. 5);\ni.\tD’établir un fond pour l’indemnisation des victimes de détention arbitraire et illégale;\nj.\tDe réformer le secteur de la sécurité:\n•\ti) En s’assurant que des éléments extérieurs n’accomplissent pas des activités de défense ou de sécurité;\n•\tii) En délimitant clairement les rôles des différents corps de défense et de sécurité, en particulier du SNR;\n•\tiii) En suspendant les membres des corps de défense et de sécurité suspectés d’être impliqués dans des violations des droits de l’homme jusqu’au terme des enquêtes et des procédures judiciaires;\n•\tiv) En établissant des procédures strictes et transparentes de sélection qui intègrent des mécanismes de vérification des antécédents;\n•\tv) En renforçant le contrôle civil et démocratique des corps de défense et de sécurité, en particulier du SNR.\nk.\tDe s’acquitter de ses obligations internationales de respecter, de protéger et de garantir les droits économiques et sociaux:\n•\ti) En élaborant et en mettant en œuvre les budgets de l’État de manière à utiliser au maximum les ressources disponibles pour assurer le respect des droits de l’homme à la population appauvrie par la crise politique, en particulier des droits à l’alimentation, à l’eau et à la santé, et pour développer des indicateurs désagrégés, y compris par genre, pour mieux informer ses politiques;\n•\tii) En entreprenant, en consultation avec les populations travaillant dans le secteur agricole, notamment les femmes, des réformes visant une meilleure protection des droits des femmes et une meilleure utilisation des terres pour l’agriculture, et en développant des perspectives de travail en dehors du secteur agricole;\n•\tiii) En utilisant une approche fondée sur les droits de l’homme pour régler les conflits fonciers dont ceux touchant les personnes ayant fui le Burundi avant et après 2015;\n•\tiv) En mettant fin à toute considération politique dans les processus de recrutement au sein de l’administration publique, des sociétés publiques et des sociétés mixtes.","annex":5},{"id":"a-hrc-48-crp-1-p0003-a5","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"3","seq":364,"section":"3. Recommandations faites en 2018","text":"La Commission recommande aux partis politiques et aux groupes armés d’opposition de s’abstenir de toute attaque sur le territoire burundais et de tout discours appelant à la violence, et de s’engager dans la recherche d’une solution durable à la crise politique.","annex":5},{"id":"a-hrc-48-crp-1-p0004-a5","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"4","seq":365,"section":"3. Recommandations faites en 2018","text":"La Commission recommande à l’Union africaine de donner une place importante, dans sa recherche d’une solution durable à la crise au Burundi, au respect des droits de l’homme et au rejet de l’impunité, tels que prévus par son Acte constitutif.","annex":5},{"id":"a-hrc-48-crp-1-p0005-a5","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"5","seq":366,"section":"3. Recommandations faites en 2018","text":"La Commission recommande aux partenaires techniques et financiers du Burundi:\na.\tDe suspendre ou de maintenir la suspension de toute aide budgétaire directe au Gouvernement en l’absence de priorisation des ressources internes en faveur des objectifs de développement durable et des droits économiques et sociaux de la population, et de mesures effectives contre la corruption;\nb.\tDe cibler les dons et les financements attribués au Gouvernement sur des projets en faveur des besoins de la population et de s’assurer que ceux-ci sont gérés efficacement et de manière transparente;\nc.\tD’évaluer régulièrement l’impact des sanctions financières sur la population burundaise.","annex":5},{"id":"a-hrc-48-crp-1-p0006-a5","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"6","seq":367,"section":"3. Recommandations faites en 2018","text":"La Commission recommande aux garants de l’Accord d’Arusha, en leur qualité d’acteurs engagés en faveur d’une paix durable au Burundi, de continuer à chercher une solution pérenne à la crise politique et des droits de l’homme qui préserve et garantit les acquis de l’Accord d’Arusha.\nVersion anglaise","annex":5},{"id":"a-hrc-48-crp-1-p0001-a6","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"1","seq":368,"section":"3. Recommandations faites en 2018","text":"The Commission recommends that the Government of Burundi take the following measures as a matter of priority:\na.\tPut an immediate end to the gross human rights violations being committed by agents of the State and Imbonerakure;\nb.\tWith the support of the international community, establish ad hoc mechanisms with a mandate to investigate human rights violations and to prosecute perpetrators of international crimes that are not being investigated by the International Criminal Court;\nc.\tWith the support of the international community, establish an independent body with a mandate to investigate the cases of disappearance reported since April 2015, locate potential mass graves, and exhume and identify the remains;\nd.\tTake measures to ensure that victims of torture and women survivors of sexual violence have access to appropriate care, including free access to all sexual and reproductive health services and to psychological support;\ne.\tImplement the Guidelines on Combating Sexual Violence and its Consequences in Africa adopted by the African Commission on Human and Peoples’ Rights;\nf.\tControl price increases, in particular by reviewing duty and tax increases that are undermining the population’s right to an adequate standard of living and by abolishing contributions that disproportionately affect the poorest sectors;\ng.\tCooperate with international human rights mechanisms, in particular by:\n•\ti) Resuming the practice of allowing special procedures mandate holders to conduct missions to Burundi;\n•\tii) Implementing the recommendations of the universal periodic review, treaty bodies and special procedures, including by establishing a national mechanism for reporting and follow-up.\nh.\tAuthorize the Office of the United Nations High Commissioner for Human Rights to resume all its activities in Burundi without hindrance;\n•\ti) Sign and implement the memorandum of understanding with the African Union and permit the full deployment of the 100 human rights observers provided for therein.","annex":6},{"id":"a-hrc-48-crp-1-p0002-a6","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"2","seq":369,"section":"3. Recommandations faites en 2018","text":"For the medium and longer terms, the Commission also recommends that the Government of Burundi:\na.\tAmend the Organization Act of 8 March 2018 amending Act No. 01/03 of 24 January 2013 on the mandate, composition, organization and functioning of the National Communication Council with a view to ensuring the latter’s independence;\nb.\tRatify the International Convention for the Protection of All Persons from Enforced Disappearance;\nc.\tAmend the Code of Criminal Procedure to align its provisions with international standards, in particular the provisions on time limits for police custody and on oversight of detention, night-time and warrantless searches, the flagrante delicto procedure and the offence of “undermining the internal security of the State”, and provisions that grant de jure impunity to judges and to officers of the criminal investigation police (police judiciaire);\nd.\tPut an end to arbitrary detention and improve conditions of detention by:\n•\ti) Implementing the Guidelines on the Conditions of Arrest, Police Custody and Pre-Trial Detention in Africa adopted by the African Commission on Human and Peoples’ Rights;\n•\tii) Ensuring that detention is subject to oversight measures for assessing its legality and compatibility with human rights.\ne.\tIn the absence of an independent and efficient judicial system, cooperate fully with the International Criminal Court in the investigation opened on 25 October 2017;\nf.\tUndertake an in-depth reform of the judicial system to ensure its independence, impartiality and effectiveness, including by:\n•\ti) Implementing the Principles and Guidelines on the Right to a Fair Trial and Legal Assistance in Africa adopted by the African Commission on Human and Peoples’ Rights;\n•\tii) Publishing the conclusions of the national forum on the justice system held in 2013 and convening a meeting of justice-sector stakeholders and international partners to discuss follow-up action;\n•\tiii) Increasing the budget for the justice sector and ensuring that it is managed autonomously;\n•\tiv) Raising the pay levels of judges in the ordinary courts and increasing the resources and facilities available to them;\n•\tv) Computerizing court registries;\n•\tvi) Reviewing the composition of the Judicial Service Commission to ensure that the majority of its members are appointed by their peers;\n•\tvii) Reviewing procedures for the appointment, assignment, evaluation and promotion of judges to ensure that such procedures are not dependent on the executive branch;\n•\tviii) Ensuring strict observance of the principle that judges should have security of tenure;\n•\tix) Protecting and safeguarding the independence of the judiciary by prohibiting any interference in the administration of justice by government authorities, members of the ruling party or members of the defence and security forces, and imposing penalties on anyone who influences or seeks to influence the administration of justice;\n•\tx) Developing legal aid programmes for persons belonging to the most vulnerable groups;\n•\txi) Strengthening victim and witness protection mechanisms and improving their effectiveness in order to restore public trust and encourage witnesses to come forward without fear for their safety.\ng.\tIn consultation with the beneficiaries, establish a reparations programme for victims of human rights violations, ensuring that material, symbolic, individual and collective reparations are made available regardless of whether or not the perpetrators are convicted;\nh.\tEstablish the State fund for victims of torture provided for by law, in conformity with general comment No. 4 on the African Charter on Human and Peoples’ Rights, adopted by the African Commission on Human and Peoples’ Rights, concerning the right to redress for victims of torture and other cruel, inhuman or degrading punishment or treatment (art. 5);\ni.\tEstablish a compensation fund for victims of arbitrary and unlawful detention;\nj.\tReform the security sector by:\n•\ti) Ensuring that outsiders are not involved in defence or security activities;\n•\tii) Clearly defining the roles of the various defence and security forces, in particular the National Intelligence Service;\n•\tiii) Suspending members of the defence and security forces who are suspected of involvement in human rights violations until the relevant investigations and judicial proceedings have concluded;\n•\tiv) Establishing rigorous and transparent selection procedures that include vetting mechanisms;\n•\tv) Strengthening democratic civilian control over the defence and security forces, in particular the National Intelligence Service.\nk.\tMeet its international obligations to respect, protect and fulfil economic and social rights by:\n•\ti) Developing and implementing State budgets in such a way as to maximize the use of available resources to ensure that the human rights of the sectors impoverished by the political crisis are respected, in particular the rights to food, water and health care, and to develop indicators disaggregated by factors such as gender in order to better inform its policies;\n•\tii) In consultation with population groups working in the agricultural sector, including women, undertaking reforms with the aim of better protecting women’s rights and making better use of land for agriculture, and developing employment opportunities outside the agricultural sector;\n•\tiii) Taking a rights-based approach to the settlement of land conflicts, including those involving persons who fled Burundi either before or after 2015;\n•\tiv) Ending the inclusion of any political considerations in hiring processes for the civil service, State enterprises and public-private enterprises.","annex":6},{"id":"a-hrc-48-crp-1-p0003-a6","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"3","seq":370,"section":"3. Recommandations faites en 2018","text":"The Commission recommends that political parties and armed opposition groups refrain from engaging in any attacks on Burundian territory and from any speech calling for violence, and that they join the effort to find a lasting solution to the political crisis.","annex":6},{"id":"a-hrc-48-crp-1-p0004-a6","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"4","seq":371,"section":"3. Recommandations faites en 2018","text":"The Commission recommends that the African Union, in its efforts to find a lasting solution to the crisis in Burundi, give priority to respect for human rights and the rejection of impunity, as provided for in its Constitutive Act.","annex":6},{"id":"a-hrc-48-crp-1-p0005-a6","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"5","seq":372,"section":"3. Recommandations faites en 2018","text":"The Commission recommends that the technical and financial partners of Burundi:\na.\tSuspend, or maintain the suspension of, any direct budget support to the Government until such time as priority is given to the allocation of domestic resources for the fulfilment of the Sustainable Development Goals and the economic and social rights of the population, and effective measures are taken against corruption;\nb.\tEnsure that grants and financing provided to the Government are earmarked for projects to meet the population’s needs, and ensure that such funding is managed effectively and transparently;\nc.\tRegularly evaluate the impact of financial sanctions on the people of Burundi.","annex":6},{"id":"a-hrc-48-crp-1-p0006-a6","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"6","seq":373,"section":"3. Recommandations faites en 2018","text":"The Commission recommends that the guarantors of the Arusha Agreement, in their capacity as committed proponents of a lasting peace in Burundi, continue to seek a durable solution to the political and human rights crisis that will preserve and safeguard the achievements of the Arusha Agreement.","annex":6},{"id":"a-hrc-48-crp-1-p0001-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"1","seq":374,"section":"1. Aux autorités burundaises","text":"De mettre immédiatement un terme aux violations graves des droits de l’homme commises par des agents de l’État et des Imbonerakure sur lesquels l’État exerce un contrôle;","annex":7},{"id":"a-hrc-48-crp-1-p0002-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"2","seq":375,"section":"1. Aux autorités burundaises","text":"D’enquêter sur ces violations et s’assurer que les auteurs présumés soient jugés dans les meilleurs délais, dans des procédures crédibles, indépendantes et équitables, et que les victimes obtiennent une juste réparation. Dans le cas où les auteurs présumés sont des agents de l’État, les suspendre jusqu’au terme de l’enquête et de la procédure judiciaire;","annex":7},{"id":"a-hrc-48-crp-1-p0003-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"3","seq":376,"section":"1. Aux autorités burundaises","text":"De prendre des mesures concrètes pour une amélioration rapide de la situation des droits de l’homme, notamment en:\n•\tAnnulant les mandats d’arrêt contre des dirigeants de médias, d’organisations de la société civile et de partis politiques qui n’ont pas utilisé ou prôné la violence, et permettant leur retour en toute sécurité au Burundi;\n•\tLevant la suspension et la radiation des médias et organisations de la société civile, leur permettant de reprendre leurs activités en toute indépendance, et revoyant les lois adoptées en 2017 sur les organisations non-gouvernementales burundaises et internationales;\n•\tLibérant immédiatement tous les prisonniers politiques;\n•\tS’assurant que toute personne arrêtée soit détenue dans un lieu de détention officiel et que des observateurs nationaux et internationaux soient autorisés à leur rendre visite;\n•\tVeillant à ce que les officiers de police judiciaire ne soient pas habilités à mener des perquisitions sans mandat et de nuit comme envisagé dans les projets d’amendement du Code pénal et du Code de procédure pénale;\n•\tS’assurant que des individus qui n’y sont pas légalement habilités, en particulier des Imbonerakure, ne conduisent pas des activités de maintien de l’ordre ou n’y prennent pas part, y compris dans des lieux de détention, et qu’ils ne portent pas des uniformes militaires ou de police ou ne soient pas en possession d’armes;\n•\tPoursuivant les auteurs de discours haineux ou appelant à la violence;\n•\tMettant fin aux menaces, intimidations et actes d’extorsion par des agents de l’État et des Imbonerakure;\n•\tPermettant aux victimes de violences sexuelles et de torture d’avoir accès à des services médicaux et psychosociaux.","annex":7},{"id":"a-hrc-48-crp-1-p0004-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"4","seq":377,"section":"1. Aux autorités burundaises","text":"D’engager une réforme en profondeur du système judiciaire, notamment en:\n•\tPubliant les conclusions des états généraux de la justice qui se sont tenus en 2013 à Gitega;\n•\tRevoyant la composition du Conseil national de la magistrature afin que ses membres soient en majorité désignés par leurs pairs;\n•\tRevoyant les procédures de nomination, d’affectation, de notation et d’avancement des magistrats afin qu’elles ne dépendent pas du pouvoir exécutif;\n•\tVeillant au respect strict du principe d’inamovibilité des magistrats du siège;\n•\tProtégeant et garantissant l’indépendance du système judiciaire en interdisant toute ingérence dans le fonctionnement de la justice par des autorités gouvernementales, des membres du parti au pouvoir ou des membres des corps de défense et de sécurité, et en prenant des sanctions contre ceux qui influencent, ou cherchent à influencer, le fonctionnement de la justice;\n•\tDéveloppant des programmes d’aide juridictionnelle pour les plus vulnérables;\n•\tRenforçant les mécanismes de protection de victimes et de témoins, ainsi que leur efficacité, pour restaurer la confiance de la population et encourager les témoins à s’exprimer sans crainte pour leur sécurité.","annex":7},{"id":"a-hrc-48-crp-1-p0005-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"5","seq":378,"section":"1. Aux autorités burundaises","text":"De s’assurer que les membres des corps de défense et de sécurité respectent les droits de l’homme en toutes circonstances et servent les intérêts de la population dans son ensemble et pas uniquement ceux du parti au pouvoir, notamment en:\n•\tRenforçant le contrôle civil des corps de défense et de sécurité et l’indépendance des organes chargés de ce contrôle créés par la Constitution, en particulier le Parlement, la Commission nationale indépendante des droits de l’homme et l’Ombudsman;\n•\tRemédiant à la carence constitutionnelle de contrôle civil du SNR;\n•\tPrenant des mesures pour vérifier les antécédents, notamment en matière de droits de l’homme, des agents des corps de défense et de sécurité et intégrant ces mesures à une refonte des procédures de recrutement et d’avancement de ces agents.","annex":7},{"id":"a-hrc-48-crp-1-p0006-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"6","seq":379,"section":"1. Aux autorités burundaises","text":"De revenir sur sa décision de se retirer du Statut de Rome et coopérer pleinement avec la CPI dans la procédure d’examen préliminaire en cours et, si une enquête est ouverte, poursuivre cette coopération et assurer la protection des victimes et témoins;","annex":7},{"id":"a-hrc-48-crp-1-p0007-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"7","seq":380,"section":"1. Aux autorités burundaises","text":"D’autoriser le HCDH à reprendre ses activités de documentation des violations des droits de l’homme au Burundi, suspendues depuis octobre 2016;","annex":7},{"id":"a-hrc-48-crp-1-p0008-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"8","seq":381,"section":"1. Aux autorités burundaises","text":"De signer et mettre en œuvre le mémorandum d’entente avec l’Union africaine et permettre le déploiement complet des 100 observateurs des droits de l’homme et des 100 experts militaires, décidé en 2016;","annex":7},{"id":"a-hrc-48-crp-1-p0009-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"9","seq":382,"section":"1. Aux autorités burundaises","text":"De coopérer avec les mécanismes des droits de l’homme des Nations Unies en accueillant à nouveau des missions des procédures spéciales et en mettant en œuvre les recommandations récentes des organes de traité;","annex":7},{"id":"a-hrc-48-crp-1-p0010-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"10","seq":383,"section":"1. Aux autorités burundaises","text":"De s’engager activement dans la voie d’une résolution durable de la crise politique, notamment dans le cadre d’initiatives de dialogue engagées au niveau international.","annex":7},{"id":"a-hrc-48-crp-1-p0011-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"11","seq":384,"section":"2. Aux partis politiques et groupes armés d’opposition","text":"De mettre immédiatement un terme aux atteintes aux droits de l’homme et aux actes de violence commis par leurs membres;","annex":7},{"id":"a-hrc-48-crp-1-p0012-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"12","seq":385,"section":"2. Aux partis politiques et groupes armés d’opposition","text":"De s’abstenir de tout discours appelant à la violence et s’engager dans la recherche d’une solution durable à la crise politique au Burundi.","annex":7},{"id":"a-hrc-48-crp-1-p0013-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"13","seq":386,"section":"3. Au Conseil des droits de l’homme","text":"De prolonger le mandat de la Commission pour une durée d’un an aux fins d’approfondir et de poursuivre ses enquêtes en raison de la persistance des violations graves des droits de l’homme et des atteintes à ceux-ci et en l’absence d’autres mécanismes spécifiques en mesure de mener des enquêtes indépendantes et approfondies sur la situation des droits de l’homme au Burundi;","annex":7},{"id":"a-hrc-48-crp-1-p0014-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"14","seq":387,"section":"3. Au Conseil des droits de l’homme","text":"De demander au Haut-Commissaire des Nations Unies aux droits de l’homme de faire un rapport sur l’évolution de sa coopération avec le Gouvernement du Burundi aux prochaines sessions du Conseil.","annex":7},{"id":"a-hrc-48-crp-1-p0015-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"15","seq":388,"section":"4. À la Cour pénale internationale","text":"D’ouvrir dans les plus brefs délais une enquête sur les crimes commis au Burundi au vu des conclusions contenues dans le présent document et d’autres informations à sa disposition.","annex":7},{"id":"a-hrc-48-crp-1-p0016-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"16","seq":389,"section":"5. Au Conseil de sécurité des Nations Unies","text":"De prendre dûment compte des présentes conclusions de la Commission et de la persistance de violations graves des droits de l’homme dans toute discussion sur le Burundi et, dans ce contexte, veiller à la mise en œuvre effective de la résolution 2303 (2016);","annex":7},{"id":"a-hrc-48-crp-1-p0017-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"17","seq":390,"section":"5. Au Conseil de sécurité des Nations Unies","text":"De saisir la CPI de tout crime de droit international qui serait commis au Burundi après le 27 octobre 2017;","annex":7},{"id":"a-hrc-48-crp-1-p0018-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"18","seq":391,"section":"5. Au Conseil de sécurité des Nations Unies","text":"De prendre des sanctions individuelles contre les principaux auteurs présumés de violations graves des droits de l’homme et de crimes de droit international au Burundi.","annex":7},{"id":"a-hrc-48-crp-1-p0019-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"19","seq":392,"section":"6. Au Secrétaire-général des Nations Unies","text":"De veiller à ce que le respect des droits de l’homme et la restauration de l’État de droit soient parmi les priorités de son Envoyé spécial sur le Burundi;","annex":7},{"id":"a-hrc-48-crp-1-p0020-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"20","seq":393,"section":"6. Au Secrétaire-général des Nations Unies","text":"De veiller à ce qu’aucun auteur présumé de violations des droits de l’homme ou de crimes de droit international au Burundi ne soit recruté dans des missions de maintien de la paix des Nations Unies.","annex":7},{"id":"a-hrc-48-crp-1-p0021-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"21","seq":394,"section":"7. Aux États membres des Nations Unies","text":"D’accorder prima facie le statut de réfugié aux demandeurs d’asile burundais et veiller au respect strict du principe de non-refoulement, ainsi qu’à la protection des réfugiés;","annex":7},{"id":"a-hrc-48-crp-1-p0022-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"22","seq":395,"section":"7. Aux États membres des Nations Unies","text":"De poursuivre, au titre de la compétence universelle, les auteurs présumés de crimes de droit international commis au Burundi se trouvant sur leur territoire;","annex":7},{"id":"a-hrc-48-crp-1-p0023-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"23","seq":396,"section":"7. Aux États membres des Nations Unies","text":"De maintenir, en l’absence de toute amélioration de la situation des droits de l’homme dans le pays, les sanctions individuelles et la suspension de l’aide directe au Gouvernement burundais;","annex":7},{"id":"a-hrc-48-crp-1-p0024-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"24","seq":397,"section":"7. Aux États membres des Nations Unies","text":"De fournir une assistance technique aux autorités burundaises, dans la mesure où ces dernières font preuve d’une véritable volonté politique, afin de mener des enquêtes crédibles et indépendantes, notamment en matière d’autopsie, d’exhumation et d’identification des corps;","annex":7},{"id":"a-hrc-48-crp-1-p0025-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"25","seq":398,"section":"7. Aux États membres des Nations Unies","text":"De soutenir la mise en place de services médicaux et psychosociaux spécialisés, notamment pour les victimes de torture et de violences sexuelles;","annex":7},{"id":"a-hrc-48-crp-1-p0026-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"26","seq":399,"section":"7. Aux États membres des Nations Unies","text":"De soutenir les autorités burundaises, si celles-ci font preuve d’une véritable volonté politique, dans tout effort de réforme du système judiciaire et du secteur de sécurité qu’elles voudront engager aux fins d’améliorer la situation des droits de l’homme.","annex":7},{"id":"a-hrc-48-crp-1-p0027-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"27","seq":400,"section":"8. À l’Union africaine","text":"De reprendre l’initiative dans la recherche d’une solution durable à la crise au Burundi fondée sur le respect des droits de l’homme et le rejet de l’impunité, tels que prévus par son Acte constitutif, et s’y engager activement;","annex":7},{"id":"a-hrc-48-crp-1-p0028-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"28","seq":401,"section":"8. À l’Union africaine","text":"De veiller à ce qu’aucun agent de l’État burundais accusé de violations des droits de l’homme ou de crimes de droit international ne soit recruté dans des missions de maintien de la paix de l’Union africaine;","annex":7},{"id":"a-hrc-48-crp-1-p0029-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"29","seq":402,"section":"8. À l’Union africaine","text":"De s’assurer que l’équipe complète de ses observateurs des droits de l’homme et experts militaires soit rapidement déployée au Burundi;","annex":7},{"id":"a-hrc-48-crp-1-p0030-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"30","seq":403,"section":"8. À l’Union africaine","text":"D’envisager, en cas de persistance de la situation actuelle au Burundi, l’application de l’article 4 (h) de son Acte constitutif, autorisant l’Union africaine à intervenir dans un État membre dans certaines circonstances, notamment en cas de crimes contre l’humanité.","annex":7},{"id":"a-hrc-48-crp-1-p0031-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"31","seq":404,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"De s’assurer que l’amélioration rapide de la situation des droits de l’homme soit une priorité dans ses efforts de médiation.\n10.\tAux garants de l’Accords d’Arusha de 2000, en leur qualité d’acteurs engagés en faveur d’une paix durable au Burundi","annex":7},{"id":"a-hrc-48-crp-1-p0032-a7","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"32","seq":405,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"De se réunir le plus rapidement possible en vue de trouver une solution pérenne à la crise politique et des droits de l’homme au Burundi.\nVersion anglaise\n1.\tThe Burundian authorities should:","annex":7},{"id":"a-hrc-48-crp-1-p0001-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"1","seq":406,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Put an immediate end to the gross human rights violations being committed by agents of the State and Imbonerakure over which the State exercises control;","annex":8},{"id":"a-hrc-48-crp-1-p0002-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"2","seq":407,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Investigate these violations, ensure that the alleged perpetrators are prosecuted promptly in accordance with credible, independent and fair procedures, and that the victims obtain just reparation, and, where the alleged perpetrators are agents of the State, suspend them from their duties pending the completion of the investigation and the judicial proceedings;","annex":8},{"id":"a-hrc-48-crp-1-p0003-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"3","seq":408,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Take practical measures to bring about a rapid improvement of the human rights situation, in particular by:\n•\tWithdrawing the warrants for the arrest of heads of media outlets, civil society organizations and political parties who have neither used nor advocated violence, and permitting their safe return to Burundi;\n•\tLifting the suspension and reversing the revocation of the licences of media and civil society organizations, permitting them to resume their activities with complete independence and reviewing the laws adopted in 2017 concerning non-profit organizations and foreign non-governmental organizations;\n•\tImmediately releasing all political prisoners;\n•\tEnsuring that every person arrested is detained in an official place of detention and that national and international observers are allowed to visit them;\n•\tEnsure that criminal investigation officers (officiers de police judiciaire) are not authorized to conduct searches without a warrant, including at night, as envisaged in the draft amendments to the Criminal Code and the Code of Criminal Procedure;\n•\tEnsuring that individuals lacking legal authorization, particularly the Imbonerakure, do not perform or participate in law enforcement activities, including in places of detention, and do not wear military or police uniforms or possess weapons;\n•\tProsecuting individuals who incite hatred or violence;\n•\tPutting an end to threats, intimidation and acts of extortion by State officials and the Imbonerakure;\n•\tGiving victims of sexual violence and torture access to medical and psychosocial services.","annex":8},{"id":"a-hrc-48-crp-1-p0004-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"4","seq":409,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Undertake a thorough reform of the judiciary, in particular by:\n•\tPublishing the conclusions of the General Convention on the Judiciary (États généraux de la justice) held in Gitega in 2013;\n•\tReviewing the composition of the Superior Council of Magistrates (Conseil supérieur de la magistrature) so that the majority of its members are designated by their peers;\n•\tReviewing the nomination, posting, evaluation and promotion procedures of magistrates so that they do not depend of the executive;\n•\tEnsuring the respect of the principle of security of tenure for judges;\n•\tProtecting and guaranteeing the independence of the judiciary by prohibiting all interference in their functions by governmental authorities, members of the ruling party or security and defence forces, and imposing sanctions on those who influence, or seek to influence, the functioning of the judiciary;\n•\tDeveloping legal aid programmes for the most vulnerable;\n•\tReinforcing the protection mechanisms for victims and witnesses, as well as their efficiency, in order to restore people’s confidence in the system and to encourage witnesses to testify without fear for their security.","annex":8},{"id":"a-hrc-48-crp-1-p0005-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"5","seq":410,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Ensure that members of the defence and security forces respect human rights in all circumstances and serve the interests of the population as a whole, not solely those of the ruling party, in particular by:\n•\tReinforcing civilian control over the military and the independence of the competent organs created by the Constitution to supervise this control, in particular the Parliament, the National Human Rights Commission and the Ombudsman;\n•\tImplementing civilian control over the National Intelligence Service (Service national de renseignement) in line with the Constitution;\n•\tConducting background checks, in particular on human rights, on defense and security forces and incorporating these measures into reforms of the recruitment and career progression of these agents.","annex":8},{"id":"a-hrc-48-crp-1-p0006-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"6","seq":411,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Reconsider their decision to withdraw from the Rome Statute, cooperate fully with the International Criminal Court in the ongoing preliminary examination and, if an investigation is initiated, continue that cooperation, inter alia by ensuring the protection of victims and witnesses;","annex":8},{"id":"a-hrc-48-crp-1-p0007-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"7","seq":412,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Authorize the Office of the United Nations High Commissioner for Human Rights to resume its documentation of human rights violations in Burundi, which has been suspended since October 2016;","annex":8},{"id":"a-hrc-48-crp-1-p0008-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"8","seq":413,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Sign and implement the memorandum of understanding with the African Union and permit the full deployment of 100 human rights observers and 100 military experts that was decided upon in 2016;","annex":8},{"id":"a-hrc-48-crp-1-p0009-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"9","seq":414,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Cooperate with United Nations human rights mechanisms by once again receiving special procedures missions and implementing the recent recommendations of treaty bodies;","annex":8},{"id":"a-hrc-48-crp-1-p0010-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"10","seq":415,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Actively seek a lasting solution to the political crisis, inter alia through international initiatives to promote dialogue.\n2.\tPolitical parties and armed opposition groups should:","annex":8},{"id":"a-hrc-48-crp-1-p0011-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"11","seq":416,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Put an immediate end to human rights abuses and acts of violence committed by their members;","annex":8},{"id":"a-hrc-48-crp-1-p0012-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"12","seq":417,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Refrain from any incitement of violence and participate in the quest for a lasting solution to the political crisis in Burundi.\n3.\tThe Human Rights Council should:","annex":8},{"id":"a-hrc-48-crp-1-p0013-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"13","seq":418,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Extend the Commission’s mandate for a period of one year to enable it to conduct further and more thorough investigations in view of the persistence of gross human rights violations and abuses and the absence of other specific mechanisms capable of undertaking independent and thorough investigations into the human rights situation in Burundi;","annex":8},{"id":"a-hrc-48-crp-1-p0014-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"14","seq":419,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Request the Office of the United Nations High Commissioner for Human Rights to report, at the forthcoming sessions of the Council, on the development of its cooperation with the Burundian Government.\n4.\tThe International Criminal Court should:","annex":8},{"id":"a-hrc-48-crp-1-p0015-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"15","seq":420,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Initiate, as soon as possible, an investigation into the crimes committed in Burundi in light of the conclusions contained in the present report and other information at its disposal.\n5.\tThe United Nations Security Council should:","annex":8},{"id":"a-hrc-48-crp-1-p0016-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"16","seq":421,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Take due account of the Commission’s conclusions, as well as persistence of gross violations of human rights, in any discussion on Burundi and, in this context, ensure the effective implementation of resolution 2303 (2016);","annex":8},{"id":"a-hrc-48-crp-1-p0017-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"17","seq":422,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Refer to the International Criminal Court any international crime that might be committed in Burundi after 27 October 2017;","annex":8},{"id":"a-hrc-48-crp-1-p0018-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"18","seq":423,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Impose individual sanctions against the principal alleged perpetrators of gross human rights violations and international crimes in Burundi.\n6.\tThe Secretary-General of the United Nations should:","annex":8},{"id":"a-hrc-48-crp-1-p0019-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"19","seq":424,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Ensure that respect for human rights and restoration of the rule of law are among the priorities of his Special Envoy for Burundi;","annex":8},{"id":"a-hrc-48-crp-1-p0020-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"20","seq":425,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Ensure that no alleged perpetrator of human rights violations or international crimes in Burundi is recruited for United Nations peacekeeping missions.\n7.\tThe States Members of the United Nations should:","annex":8},{"id":"a-hrc-48-crp-1-p0021-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"21","seq":426,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Grant prima facie refugee status to Burundian asylum seekers and ensure strict re64ect for the principle of non-refoulement and refugee protection;","annex":8},{"id":"a-hrc-48-crp-1-p0022-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"22","seq":427,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Prosecute, in accordance with the principle of universal jurisdiction, alleged perpetrators of international crimes committed in Burundi who are found to be in their territory;","annex":8},{"id":"a-hrc-48-crp-1-p0023-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"23","seq":428,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Maintain, in the absence of any improvement in the human rights situation in Burundi, the individual sanctions and the suspension of direct aid to the Government;","annex":8},{"id":"a-hrc-48-crp-1-p0024-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"24","seq":429,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Provide technical assistance inter alia in respect to autopsies, exhumations and identification of bodies, to enable the Burundian to conduct credible and independent investigations;","annex":8},{"id":"a-hrc-48-crp-1-p0025-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"25","seq":430,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Support the establishment of specialized medical and psychosocial services, especially for victims of torture and sexual violence;","annex":8},{"id":"a-hrc-48-crp-1-p0026-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"26","seq":431,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Support Burundian authorities in any judicial and security sector reform endeavors that they might wish to undertake in order to improve the human rights situation.\n8.\tThe African Union should:","annex":8},{"id":"a-hrc-48-crp-1-p0027-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"27","seq":432,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Retake the lead in seeking a lasting solution to the crisis in Burundi based on respect for human rights and rejection of impunity, as provided for in its Constitutive Act, and play an active role in that process;","annex":8},{"id":"a-hrc-48-crp-1-p0028-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"28","seq":433,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Ensure that no agent of the Burundian State who is accused of human rights violations or international crimes is recruited for African Union peacekeeping missions;","annex":8},{"id":"a-hrc-48-crp-1-p0029-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"29","seq":434,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Ensure that the full complement of African Union human rights observers and military experts is deployed rapidly in Burundi;","annex":8},{"id":"a-hrc-48-crp-1-p0030-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"30","seq":435,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Consider, in the event that the current situation in Burundi persists, the application of Article 4 (h) of the Constitutive Act of the African Union, under which it is authorized to intervene in a member State in certain circumstances, particularly in the event of crimes against humanity.\n9.\tThe East African Community should:","annex":8},{"id":"a-hrc-48-crp-1-p0031-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"31","seq":436,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Ensure that a rapid improvement of the human rights situation is a priority in its mediation efforts.\n10.\tThe guarantors of the 2000 Arusha Agreement, in their capacity as committed proponents of a lasting peace in Burundi, should:","annex":8},{"id":"a-hrc-48-crp-1-p0032-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":"32","seq":437,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Meet with a view to finding a lasting solution to the political and human rights crisis in Burundi.","annex":8},{"id":"a-hrc-48-crp-1-u0438-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":null,"seq":438,"section":"IV. Indicateurs des facteurs de risque communs identifiés","text":"dans le Cadre d’analyse des atrocités criminelles\n(A/70/741–S/2016/71)\nVersion française\nFacteur de risque 1. Situations de conflit armé ou autres formes d’instabilité\na.\tConflit armé international ou non international;\nb.\tCrise sécuritaire provoquée, entre autres, par la dénonciation d’accords de paix, un conflit armé dans les pays voisins, des menaces d’interventions étrangères ou des actes de terrorisme;\nc.\tCrise ou urgence humanitaire, pouvant être causée notamment par une catastrophe naturelle ou une épidémie;\nd.\tInstabilité politique provoquée par un changement de régime ou un transfert de pouvoir soudain ou irrégulier;\ne.\tInstabilité politique provoquée par des luttes de pouvoir ou la montée en puissance de mouvements d’opposition nationalistes, armés ou radicaux;\nf.\tTension politique provoquée par des régimes autocratiques ou une lourde répression politique;\ng.\tInstabilité économique provoquée par une pénurie de ressources ou des différends concernant leur utilisation ou leur exploitation;\nh.\tInstabilité économique provoquée par une crise grave de l’économie nationale;\ni.\tInstabilité économique provoquée par la misère, un chômage de masse ou de profondes inégalités horizontales;\nj.\tInstabilité sociale provoquée par une résistance à l’autorité de l’État ou à ses politiques ou par des protestations de masse contre celles-ci;\nk.\tInstabilité sociale provoquée par l’exclusion ou des tensions fondées sur des questions d’identité, leur perception ou leurs formes extrémistes.\nFacteur de risque 2. Antécédents de violations graves du droit international des droits de l’homme et du droit international humanitaire\na.\tRestrictions ou violations graves, passées ou actuelles, des droits consacrés par le droit international des droits de l’homme et le droit international humanitaire, surtout si elles sont caractérisées par un comportement systématique observé préalablement et si elles visent des groupes, populations ou personnes protégés;\nb.\tActes de génocide, crimes contre l’humanité, crimes de guerre ou incitation à les commettre, survenus dans le passé;\nc.\tPolitique ou pratique d’impunité ou de tolérance à l’égard de violations graves du droit international des droits de l’homme et du droit international humanitaire, d’atrocités criminelles ou de l’incitation à les commettre;\nd.\tInaction, réticence à utiliser ou refus d’utiliser tous les moyens possibles pour faire cesser des violations graves prévues, prévisibles ou persistantes du droit international des droits de l’homme et du droit international humanitaire ou des atrocités criminelles probables, ou incitation à les commettre;\ne.\tMaintien d’une aide à des groupes accusés de participer à des violations graves du droit international des droits de l’homme et du droit international humanitaire, notamment des atrocités criminelles, ou non-condamnation de leurs actes;\nf.\tJustification de violations graves du droit international des droits de l’homme et du droit international humanitaire ou d’atrocités criminelles, rapports partiaux les concernant ou refus de les reconnaître;\ng.\tAbsence de processus de réconciliation ou de justice transitionnelle après un conflit, ou politisation de ce processus;\nh.\tMéfiance généralisée envers les institutions de l’État ou entre différents groupes en raison de l’impunité.\nFacteur de risque 3. Faiblesse des structures de l’État\na.\tCadre juridique national n’offrant pas une protection suffisante et efficace, notamment par la ratification et l’incorporation dans le droit interne des instruments relatifs au droit international des droits de l’homme et au droit international humanitaire;\nb.\tManque de ressources au sein des institutions nationales, en particulier les institutions judiciaires et celles chargées de l’application des lois et de la protection des droits de l’homme, et manque de représentation adéquate ou de formation;\nc.\tAbsence de justice indépendante et impartiale;\nd.\tAbsence de contrôle civil efficace des forces de sécurité;\ne.\tNiveaux élevés de corruption ou mauvaise gouvernance;\nf.\tAbsence ou insuffisance de mécanismes externes ou internes de contrôle et de responsabilité, notamment que les victimes peuvent saisir pour demander réparation;\ng.\tManque de sensibilisation et de formation des forces militaires, des forces irrégulières, des groupes armés non étatiques et des autres acteurs concernés au droit international des droits de l’homme et au droit international humanitaire;\nh.\tManque de capacité de vérifier que les moyens et méthodes de guerre sont conformes aux normes du droit international humanitaire;\ni.\tManque de moyens pour la réforme ou le renforcement des institutions, notamment par une aide régionale ou internationale;\nj.\tRessources insuffisantes pour mettre en œuvre des mesures globales de protection des populations.\nFacteur de risque 4. Motivations ou incitations\na.\tMotivations politiques, en particulier celles visant l’acquisition ou la consolidation du pouvoir;\nb.\tIntérêts économiques, notamment ceux fondés sur la préservation et le bien-être des élites ou de groupes d’identité, ou sur le contrôle de la répartition des ressources;\nc.\tIntérêts stratégiques ou militaires, notamment ceux fondés sur la protection ou la saisie de territoires et de ressources;\nd.\tAutres intérêts, notamment ceux visant à rendre une zone homogène dans son identité;\ne.\tMenaces réelles ou perçues comme telles de groupes, populations ou personnes protégés contre les intérêts ou les objectifs des auteurs d’actes criminels, notamment l’impression de déloyauté envers une cause;\nf.\tAppartenance ou adhésion réelle ou perçue comme telle de groupes, populations ou personnes protégés à des groupes d’opposition armés;\ng.\tIdéologies fondées sur la suprématie d’une certaine identité ou sur des versions extrémistes de l’identité;\nh.\tPolitisation de griefs, de tensions ou de cas d’impunité issus du passé;\ni.\tTraumatisme social provoqué par des situations de violence passées auxquelles il n’a pas été donné de suite satisfaisante et qui ont engendré des sentiments de perte, de déplacement et d’injustice et un désir possible de revanche.\nFacteur de risque 5. Capacité de commettre des atrocités criminelles\na.\tDisponibilité de personnel et d’armes et munitions ou de moyens financiers publics ou privés permettant de les acquérir;\nb.\tCapacité de transporter et déployer du personnel et de transporter et distribuer des armes et des munitions;\nc.\tCapacité d’encourager ou de recruter de nombreux partisans au sein de populations ou de groupes et disponibilité de moyens pour les mobiliser;\nd.\tSolide culture d’obéissance à l’autorité et de conformité au groupe;\ne.\tPrésence d’autres forces armées ou de groupes armés non étatiques ou existence de liens avec de tels forces ou groupes;\nf.\tPrésence d’acteurs commerciaux ou d’entreprises pouvant jouer un rôle déterminant en fournissant des biens, des services ou d’autres formes d’appui pratique ou technique contribuant à soutenir les auteurs;\ng.\tAppui financier, politique ou autre d’acteurs nationaux influents ou riches;\nh.\tAppui armé, financier, logistique ou autre, notamment sous la forme d’entraînement, fourni par des acteurs extérieurs, notamment des États, des organisations internationales ou régionales ou des entreprises privées.\nFacteur de risque 6. Absence de facteurs atténuants\na.\tInsuffisance ou absence de processus d’autonomisation, de ressources, d’alliés ou d’autres éléments qui pourraient contribuer à la capacité des groupes, populations ou personnes protégés de se protéger eux-mêmes;\nb.\tAbsence de société civile nationale solide, organisée et représentative et de médias nationaux libres, diversifiés et indépendants;\nc.\tAbsence d’intérêt et d’attention des acteurs de la société civile internationale ou d’accès aux médias internationaux;\nd.\tAbsence ou présence limitée des Nations Unies, d’organisations non gouvernementales internationales ou d’autres acteurs internationaux ou régionaux dans le pays ayant accès aux populations;\ne.\tAbsence d’adhésion ou de participation effective de l’État à des organisations internationales ou régionales établissant des obligations afférentes au statut de membre;\nf.\tManque de contact, d’ouverture ou de relations politiques ou économiques avec d’autres États ou organisations;\ng.\tCoopération limitée de l’État avec les mécanismes internationaux et régionaux des droits de l’homme;\nh.\tManque de volonté des parties à un conflit d’engager un dialogue, de faire des concessions et de solliciter l’appui de la communauté internationale, ou absence d’incitations à le faire;\ni.\tRéticence ou échec des États Membres de l’Organisation des Nations Unies ou des organisations internationales ou régionales à aider un État à assumer sa responsabilité de protéger ses populations contre les atrocités criminelles, ou à agir lorsque l’État n’assume manifestement pas cette responsabilité, ou indifférence à cet égard;\nj.\tManque de soutien des États voisins pour ce qui est de protéger les populations à risque en quête de refuge: fermeture des frontières, rapatriement forcé ou restrictions en matière d’aide;\nk.\tAbsence de mécanisme d’alerte rapide permettant de prévenir des atrocités criminelles.\nFacteur de risque 7. Circonstances propices ou action préparatoire restreignant les droits fondamentaux\na.\tImposition de l’état d’urgence ou de mesures de sécurité extraordinaires restreignant les droits fondamentaux;\nb.\tSuspension d’institutions vitales de l’État ou ingérence dans ces institutions, ou mesures provoquant des modifications de leur composition ou l’équilibre des pouvoirs, en particulier s’il en résulte l’exclusion ou une sous-représentation de groupes protégés;\nc.\tRenforcement de l’appareil de sécurité, réorganisation ou mobilisation de celui-ci contre des groupes, populations ou personnes protégés;\nd.\tAcquisition de grandes quantités d’armes et de munitions ou d’autres objets pouvant être utilisés pour causer des dommages;\ne.\tCréation de milices ou de groupes paramilitaires, ou intensification de l’appui à de tels milices ou groupes;\nf.\tImposition d’un contrôle strict sur l’utilisation des moyens de communication ou interdiction d’y avoir accès;\ng.\tExpulsion ou refus d’autoriser la présence d’organisations non gouvernementales, d’organisations internationales, de médias ou d’autres acteurs pertinents ou imposition de lourdes restrictions à leurs services et déplacements;\nh.\tAugmentation du nombre de violations du droit à la vie, de l’intégrité physique, de la liberté ou de la sécurité de membres de groupes, populations ou personnes protégés, ou adoption récente de mesures ou de lois qui leur portent atteinte ou constituent une discrimination délibérée envers eux;\ni.\tAugmentation du nombre d’actes de violence graves contre les femmes et les enfants ou création de conditions facilitant la commission d’agressions sexuelles contre eux, notamment comme instrument de terreur;\nj.\tImposition de conditions de vie délétères ou déportation, appréhension, regroupement, ségrégation, évacuation, déplacement ou transfert forcés de groupes, populations ou individus protégés vers des camps, des zones rurales, des ghettos ou d’autres lieux désignés;\nk.\tDestruction ou pillage de biens ou d’installations essentiels à des groupes, populations ou personnes protégés, ou de biens liés à l’identité culturelle et religieuse;\nl.\tMarquage de personnes ou de leurs biens au motif de leur appartenance à un groupe;\nm.\tPolitisation accrue de l’identité, d’événements du passé ou de motifs de se livrer à la violence;\nn.\tAugmentation du nombre de déclarations provocatrices, de campagnes de propagande ou d’incitations à la haine visant des groupes, populations ou personnes protégés.\nFacteur de risque 8. Facteurs déclencheurs\na.\tDéploiement soudain de forces de sécurité ou déclenchement d’hostilités armées;\nb.\tDébordement de conflits armés ou graves tensions dans les pays voisins;\nc.\tMesures prises par la communauté internationale, perçues par un État comme menaçant sa souveraineté;\nd.\tChangements de régime, transferts de pouvoir ou modifications du pouvoir politique des groupes, survenant soudainement ou irrégulièrement;\ne.\tAtteintes à la vie, à l’intégrité physique, à la liberté ou à la sécurité de dirigeants, de personnalités éminentes ou de membres de groupes opposés; autres actes de violence graves, notamment attentats terroristes;\nf.\tManifestations religieuses ou actes réels ou perçus comme tels d’intolérance religieuse ou d’irrespect, notamment en dehors des frontières nationales;\ng.\tActes d’incitation ou propagande haineuse visant des groupes ou des personnes particulières;\nh.\tRecensement, élections, activités essentielles liées à ces processus ou mesures qui les déstabilisent;\ni.\tChangements soudains affectant l’économie ou la population active, résultant notamment de crises financières, de catastrophes naturelles ou d’épidémies;\nj.\tDécouverte de ressources naturelles ou lancement de projets d’exploitation ayant de graves incidences sur les moyens de subsistance et la viabilité de groupes ou de populations civiles;\nk.\tCommémoration de crimes du passé ou d’épisodes traumatiques ou historiques pouvant exacerber les tensions entre groupes, notamment la glorification d’auteurs d’atrocités;\nl.\tActes liés aux processus d’établissement des responsabilités, en particulier s’ils sont perçus comme injustes.\nVersion anglaise\nRisk factor 1. Situations of armed conflict or other forms of instability\na.\tInternational or non-international armed conflict;\nb.\tSecurity crisis caused by, among other factors, defection from peace agreements, armed conflict in neighboring countries, threats of external interventions or acts of terrorism;\nc.\tHumanitarian crisis or emergency, including those caused by natural disasters or epidemics;\nd.\tPolitical instability caused by abrupt or irregular regime change or transfer of power;\ne.\tPolitical instability caused by disputes over power or growing nationalist, armed or radical opposition movements;\nf.\tPolitical tension caused by autocratic regimes or severe political repression;\ng.\tEconomic instability caused by scarcity of resources or disputes over their use or exploitation;\nh.\tEconomic instability caused by severe crisis in the national economy;\ni.\tEconomic instability caused by acute poverty, mass unemployment or deep horizontal inequalities;\nj.\tSocial instability caused by resistance to, or mass protests against, State authority or policies;\nk.\tSocial instability caused by exclusion or tensions based on identity issues, their perception or extremist forms.\nRisk factor 2. Record of serious violations of international human rights and humanitarian law\na.\tPast or present serious restrictions to or violations of international human rights and humanitarian law, particularly if assuming an early pattern of conduct and if targeting protected groups, populations or individuals;\nb.\tPast acts of genocide, crimes against humanity, war crimes or their incitement;\nc.\tPolicy or practice of impunity for or tolerance of serious violations of international human rights and humanitarian law, of atrocity crimes, or of their incitement;\nd.\tInaction, reluctance or refusal to use all possible means to stop planned, predictable or ongoing serious violations of international human rights and humanitarian law or likely atrocity crimes, or their incitement;\ne.\tContinuation of support to groups accused of involvement in serious violations of international human rights and humanitarian law, including atrocity crimes, or failure to condemn their actions;\nf.\tJustification, biased accounts or denial of serious violations of international human rights and humanitarian law or atrocity crimes;\ng.\tPoliticization or absence of reconciliation or transitional justice processes following conflict;\nh.\tWidespread.\nRisk factor 3. Weakness of State structures\na.\tNational legal framework that does not offer ample and effective protection, including through ratification and domestication of relevant international human rights and humanitarian law treaties;\nb.\tNational institutions, particularly judicial, law enforcement and human rights institutions that lack sufficient resources, adequate representation or training;\nc.\tLack of an independent and impartial judiciary;\nd.\tLack of effective civilian control of security forces;\ne.\tHigh levels of corruption or poor governance;\nf.\tAbsence or inadequate external or internal mechanisms of oversight and accountability, including those where victims can seek recourse for their claims;\ng.\tLack of awareness of and training on international human rights and humanitarian law to military forces, irregular forces and non-State armed groups, or other relevant actors;\nh.\tLack of capacity to ensure that means and methods of warfare comply with international humanitarian law standards;\ni.\tLack of resources for reform or institution-building, including through regional or international support;\nj.\tInsufficient resources to implement overall measures aimed at protecting populations.\nRisk factor 4. Motives or incentives\na.\tPolitical motives, particularly those aimed at the attainment or consolidation of power;\nb.\tEconomic interests, including those based on the safeguard and well-being of elites or identity groups, or control over the distribution of resources;\nc.\tStrategic or military interests, including those based on protection or seizure of territory and resources;\nd.\tOther interests, including those aimed at rendering an area homogeneous in its identity;\ne.\tReal or perceived threats posed by protected groups, populations or individuals against interests or objectives of perpetrators, including perceptions of disloyalty to a cause;\nf.\tReal or perceived membership of or support for armed opposition groups by protected groups, populations or individuals;\ng.\tIdeologies based on the supremacy of a certain identity or on extremist versions of identity;\nh.\tPoliticization of past grievances, tensions or impunity;\ni.\tSocial trauma caused by past incidents of violence not adequately addressed and that produced feelings of loss, displacement, injustice and a possible desire for revenge.\nRisk factor 5. Capacity to commit atrocity crimes\na.\tAvailability of personnel and of arms and ammunition, or of the financial resources, public or private, for their procurement;\nb.\tCapacity to transport and deploy personnel and to transport and distribute arms and ammunition;\nc.\tCapacity to encourage or recruit large numbers of supporters from populations or groups, and availability of the means to mobilize them;\nd.\tStrong culture of obedience to authority and group conformity;\ne.\tPresence of or links with other armed forces or with non-State armed groups;\nf.\tPresence of commercial actors or companies that can serve as enablers by providing goods, services, or other forms of practical or technical support that help to sustain perpetrators;\ng.\tFinancial, political or other support of influential or wealthy national actors;\nh.\tArmed, financial, logistic, training or other support of external actors, including States, international or regional organizations, private companies, or others.\nRisk factor 6. Absence of mitigating factors\na.\tLimited or lack of empowerment processes, resources, allies or other elements that could contribute to the ability of protected groups, populations or individuals to protect themselves;\nb.\tLack of a strong, organized and representative national civil society and of a free, diverse and independent national media;\nc.\tLack of interest and focus of international civil society actors or of access to international media;\nd.\tLack of, or limited presence of, the United Nations, international non-governmental organizations or other international or regional actors in the country and with access to populations;\ne.\tLack of membership and effective participation of the State in international or regional organizations that establish mandatory membership obligations;\nf.\tLack of exposure, openness or establishment of political or economic relations with other States or organizations;\ng.\tLimited cooperation of the State with international and regional human rights mechanisms;\nh.\tLack of incentives or willingness of parties to a conflict to engage in dialogue, make concessions and receive support from the international community;\ni.\tLack of interest, reluctance or failure of States Members of the United Nations or members of international or regional organizations to support a State to exercise its responsibility to protect populations from atrocity crimes, or to take action when the State manifestly fails that responsibility;\nj.\tLack of support by neighbouring States to protect populations at risk and in need of refuge, including by closure of borders, forced repatriation or aid restriction;\nk.\tLack of an early warning mechanism relevant to the prevention of atrocity crimes.\nRisk factor 7. Enabling circumstances or preparatory action\na.\tImposition of emergency laws or extraordinary security measures that erode fundamental rights;\nb.\tSuspension of or interference with vital State institutions, or measures that result in changes in their composition or balance of power, particularly if this results in the exclusion or lack of representation of protected groups;\nc.\tStrengthening of the security apparatus, its reorganization or mobilization against protected groups, populations or individuals;\nd.\tAcquisition of large quantities of arms and ammunition or of other objects that could be used to inflict harm;\ne.\tCreation of, or increased support to, militia or paramilitary groups;\nf.\tImposition of strict control on the use of communication channels, or banning access to them;\ng.\tExpulsion or refusal to allow the presence of non-governmental organizations, international organizations, media or other relevant actors, or imposition of severe restrictions on their services and movements;\nh.\tIncreased violations of the right to life, physical integrity, liberty or security of members of protected groups, populations or individuals, or recent adoption of measures or legislation that affect or deliberately discriminate against them;\ni.\tIncreased serious acts of violence against women and children, or creation of conditions that facilitate acts of sexual violence against those groups, including as a tool of terror;\nj.\tImposition of life-threatening living conditions or the deportation, seizure, collection, segregation, evacuation or forced displacement or transfer of protected groups, populations or individuals to camps, rural areas, ghettos or other assigned locations;\nk.\tDestruction or plundering of essential goods or installations for protected groups, populations or individuals, or of property related to cultural and religious identity;\nl.\tMarking of people or their property based on affiliation to a group;\nm.\tIncreased politicization of identity, past events or motives to engage in violence;\nn.\tIncreased inflammatory rhetoric, propaganda campaigns or hate speech targeting protected groups, populations or individuals.\nRisk factor 8. Triggering factors\na.\tSudden deployment of security forces or commencement of armed hostilities;\nb.\tSpillover of armed conflicts or serious tensions in neighbouring countries;\nc.\tMeasures taken by the international community perceived as threatening to a State’s sovereignty;\nd.\tAbrupt or irregular regime changes, transfers of power, or changes in political power of groups;\ne.\tAttacks against the life, physical integrity, liberty or security of leaders, prominent individuals or members of opposing groups; other serious acts of violence, such as terrorist attacks;\nf.\tReligious events or real or perceived acts of religious intolerance or disrespect, including outside national borders;\ng.\tActs of incitement or hate propaganda targeting particular groups or individuals;\nh.\tCensus, elections, pivotal activities related to those processes, or measures that destabilize them;\ni.\tSudden changes that affect the economy or the workforce, including as a result of financial crises, natural disasters or epidemics;\nj.\tDiscovery of natural resources or launching of exploitation projects that have a serious impact on the livelihoods and sustainability of groups or civilian populations;\nk.\tCommemoration events of past crimes or of traumatic or historical episodes that can exacerbate tensions between groups, including the glorification of perpetrators of atrocities;\nl.\tActs related to accountability processes, particularly when perceived as unfair.","unnumbered":true,"annex":8},{"id":"a-hrc-48-crp-1-u0439-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":null,"seq":439,"section":"V. Documents","text":"Français seulement\n2014 | 2015 | 2016 | 2017 | 2018 | 2019 | 2020\n32/100 | 19/100 | 19/100 | 18/100 | 14/100 | 13/100 | 14/100\n| 2013 | 2014 | 2015 | 2016 | 2017 | 2018 | 2019 | 2020 | 2021\nRang sur 180 pays  | 132 | 142 | 145 | 156 | 160 | 159 | 159 | 160 | 147\n| 2013 | 2014 | 2015 | 2016 | 2017 | 2018 | 2019 | 2020\nScore | 21 | 20 | 21 | 20 | 22 | 17 | 19 | 19","unnumbered":true,"annex":8},{"id":"a-hrc-48-crp-1-u0440-a8","rec_id":"rec44rTUuolNAIKRE","symbol":"A/HRC/48/CRP.1","n":null,"seq":440,"section":"V. Documents","text":"2010 | 2011 | 2012 | 2013 | 2014 | 2015 | 2016 | 2017 | 2018 | 2019 | 2010-2019\n40.5 | 41.0 | 42.1 | 41.9 | 41.8 | 38.1 | 37.2 | 37.2 | 36.4 | 36.9\n| -3,6\n| 2010 | 2011 | 2012 | 2013 | 2014 | 2015 | 2016 | 2017 | 2018 | 2019 | 2010-2019\nSécurité et État de droit | 42.9 | 42.8 | 42.3 | 39.9 | 39.3 | 29.9 | 29.2 | 30.7 | 29.7 | 30.2 | -12,7\nParticipation, droits, inclusion | 44.2 | 44.1 | 44.8 | 44.1 | 43.4 | 39.2 | 36.2 | 35.2 | 34.0 | 33.2 | -11.0\nBases des opportunités économiques | 34.0 | 35.2 | 36.8 | 38.5 | 36.9 | 36.6 | 36.4 | 36.5 | 35.7 | 37.0 | +3.0\nDéveloppement humain | 40.9 | 41.7 | 44.3 | 45.2 | 47.4 | 46.9 | 46.9 | 46.5 | 46.2 | 47.2 | +6.3","unnumbered":true,"annex":8},{"id":"a-hrc-48-68-p0001","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"1","seq":0,"section":"A. Mandate","text":"The Commission of Inquiry on Burundi was established by Human Rights Council resolution 33/24, adopted on 30 September 2016, to conduct a thorough investigation into human rights violations and abuses committed in Burundi since April 2015, determine whether any of them may constitute international crimes, identify their alleged perpetrators and formulate recommendations for ensuring that the perpetrators are held accountable for their acts. There have been four one-year renewals of the Commission’s mandate. In keeping with the provisions of Council resolution 45/19, the Commission submitted the present report to the Council on 6 October 2020 and gave an oral presentation at the Council’s forty-sixth session in March 2021."},{"id":"a-hrc-48-68-p0002","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"2","seq":1,"section":"A. Mandate","text":"Doudou Diène (Senegal) has been Chair of the Commission since 1 February 2018, and Françoise Hampson (United Kingdom of Great Britain and Northern Ireland) has been a member since 22 November 2016. Lucy Asuagbor (Cameroon), who was appointed on 5 March 2018, resigned from the Commission on 24 March 2021 due to the demands of her new national functions."},{"id":"a-hrc-48-68-p0003","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"3","seq":2,"section":"A. Mandate","text":"The Commission remains the only independent international mechanism capable of conducting impartial investigations into human rights violations committed recently in Burundi and providing in-depth analysis of the human rights situation in the country. It faced particular challenges during this reporting period. The Commission regrets, inter alia, that its work was adversely affected by the liquidity crisis at the United Nations, the ensuing staff reductions and the recruitment freeze, which delayed the establishment of its secretariat. These elements, together with the travel restrictions resulting from the coronavirus disease (COVID-19) pandemic, had an impact on the conduct of investigations in the field, especially those related to the economic underpinnings of the State and to gender-based and sexual violence."},{"id":"a-hrc-48-68-p0004","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"4","seq":3,"section":"A. Mandate","text":"The present report covers the human rights violations and abuses committed since the investiture of President Evariste Ndayishimiye on 18 June 2020 and examines notable developments in the areas of human rights, the fight against impunity and corruption, and the rule of law. The analysis of risk factors has been updated. The final conclusions of the investigations are detailed in a separate document."},{"id":"a-hrc-48-68-p0005","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"5","seq":4,"section":"B. Cooperation with the Commission","text":"The Human Rights Council urged the Government of Burundi to cooperate fully with the Commission, to authorize it to conduct visits to the country and to provide it with all the information necessary to carry out its mandate. The Commission pursued its efforts to establish a dialogue with the authorities of Burundi, including with a view to exchanging relevant information, but the Government of President Ndayishimiye has not officially replied to the Commission’s letters."},{"id":"a-hrc-48-68-p0006","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"6","seq":5,"section":"C. Methodology","text":"Despite the specific difficulties it encountered, the Commission held 170 targeted interviews with victims, witnesses and other sources living in Burundi and other countries. It has thus gathered over 1,770 statements since the start of its mandate."},{"id":"a-hrc-48-68-p0007","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"7","seq":6,"section":"C. Methodology","text":"The Commission continued to apply the same methodology and the same “reasonable grounds to believe” standard of evidence, both of which are fully consistent with internationally accepted guidance and practice for this type of inquiry."},{"id":"a-hrc-48-68-p0008","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"8","seq":7,"section":"D. Applicable law","text":"The applicable law still consists of international human rights law, international criminal law and anti-corruption treaties. Burundi remains a party to the same conventions as before."},{"id":"a-hrc-48-68-p0009","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"9","seq":8,"section":"D. Applicable law","text":"Burundi remains bound by obligations under customary international law concerning international crimes and under the Rome Statute of the International Criminal Court for the period from April 2015 to 27 October 2017, the date on which its withdrawal from the Rome Statute became effective. The Commission refers to the definitions of crimes set forth in the Rome Statute that are reflected in the Criminal Code of Burundi."},{"id":"a-hrc-48-68-p0010","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"10","seq":9,"section":"1. Human rights mechanisms","text":"The Government has not authorized the Office of the United Nations High Commissioner for Human Rights (OHCHR) to reopen its country office and only accepts capacity-building and technical cooperation from the United Nations Subregional Centre for Human Rights and Democracy in Central Africa."},{"id":"a-hrc-48-68-p0011","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"11","seq":10,"section":"1. Human rights mechanisms","text":"There have been no recent visits to Burundi by special procedures mandate holders, nor are any visits planned despite requests from several among them. Two joint communications were sent to Burundi by special procedures mandate holders regarding cases of alleged human rights violations, including the enforced disappearance, arbitrary arrest and detention, torture and murder of Burundian refugees in Tanzania and the arbitrary detention and enforced disappearance of Burundian refugees who had been forcibly repatriated to Burundi."},{"id":"a-hrc-48-68-p0012","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"12","seq":11,"section":"1. Human rights mechanisms","text":"The Working Group on Arbitrary Detention has adopted four opinions in which it found that the cases before it amounted to arbitrary detention, including those of four ex-FAB (officers of the former Burundian army) who were arrested in August 2015 and have been held in pretrial detention ever since. The Government of Burundi refused to cooperate with the Working Group. The Working Group on Enforced or Involuntary Disappearances, for its part, has before it 250 cases concerning Burundi."},{"id":"a-hrc-48-68-p0013","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"13","seq":12,"section":"2. Security Council","text":"On 4 December 2020, the Security Council removed Burundi from its programme of work and decided that the country would be covered in the Secretary-General’s regular reports on the Great Lakes region and Central Africa. The Council based its decision on the progress made in the country, while underscoring that much remained to be done to bring about national reconciliation, promote the rule of law and an effective and independent judicial system, preserve the democratic space and ensure respect for fundamental freedoms. It also noted that human rights violations remained a concern."},{"id":"a-hrc-48-68-p0014","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"14","seq":13,"section":"3. Office of the Special Envoy of the Secretary-General for Burundi","text":"The Office, which was established in 2015 to support the country in consolidating peace, officially ceased its activities on 31 May 2021. In November 2020, the Government of Burundi demanded its closure by 31 December 2021, while the Secretary-General called for it to remain operational under a modified mandate. In fact, in his report on the strategic assessment mission for United Nations engagement in Burundi dated November 2020, the Secretary-General noted that he had received assurances from President Ndayishimiye that his Government was prepared to discuss the topic."},{"id":"a-hrc-48-68-p0015","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"15","seq":14,"section":"B. Other entities","text":"In November 2020, on the basis of the elections held in 2020 and the commitments made by the new authorities, the International Organization of la Francophonie decided to resume multilateral cooperation with Burundi, which had been suspended since April 2016."},{"id":"a-hrc-48-68-p0016","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"16","seq":15,"section":"B. Other entities","text":"On 27 April 2021, the Peace and Security Council of the African Union decided to remove Burundi from its agenda and to terminate the mandate of the African Union Human Rights Observers and Military Experts Mission in Burundi on 31 May 2021."},{"id":"a-hrc-48-68-p0017","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"17","seq":16,"section":"B. Other entities","text":"In June 2021, the Global Alliance of National Human Rights Institutions restored A status to the National Independent Human Rights Commission of Burundi (NIHRC), meaning that the institution theoretically functions independently. However, in its 2020 annual report, NIHRC reported only a few minor violations of civil and political rights during the elections and no violations of the right to life and civil liberties or cases of kidnapping and enforced disappearance. While it reports cases of arbitrary detention and violations of the right to a fair trial, as well as a handful of cases of torture and sexual violence, none of them are linked to the elections. The Commission therefore expresses reservations about these findings. It does stress, however, that an NIHRC delegation contacted it in April 2021, thus enabling the bodies to discuss their respective work. The Commission hopes that its new accreditation will encourage NIHRC to demonstrate in practice that it is truly independent, in particular by addressing all cases of violations, including the most sensitive ones, even if it has to carry out its mission in a closed democratic space that warrants more than ever a national human rights commission that is independent and operational."},{"id":"a-hrc-48-68-p0018","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"18","seq":17,"section":"III. Human rights situation","text":"Human rights violations have continued but on a smaller scale than during the elections. The democratic space remains closed and the authorities tightly control the media and civil society despite some isolated symbolic gestures of openness by the President. The violations documented chiefly targeted members of opposition parties and individuals suspected of being involved in armed attacks or of collaborating with armed groups but also, to a lesser extent, returnees and the Burundian population in general. Agents of the National Intelligence Service, placed under the direct responsibility of President Ndayishimiye, were the main perpetrators of executions, enforced disappearances, arbitrary arrests and detentions, and torture in connection with armed attacks and have continued to operate with absolute impunity. Police officers of the Rapid Mobile Intervention Group and members of the Imbonerakure were also involved in some of the cases of execution, arrest and torture."},{"id":"a-hrc-48-68-p0019","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"19","seq":18,"section":"1. Increase in security incidents","text":"Since August 2020, security incidents have regularly been reported in Burundi, including armed clashes and exchanges of gunfire between members of the security forces, sometimes supported by the Imbonerakure, and armed groups that are often unidentified. Attacks on civilians by armed groups, some precisely targeted and others random, have also been reported. For example, vehicles and their occupants were riddled with machine gun fire and set on fire on the road between Gitega and Bujumbura on 9 May and 26 June 2021, and grenades were thrown into a crowd in Bujumbura on 25 May 2021."},{"id":"a-hrc-48-68-p0020","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"20","seq":19,"section":"1. Increase in security incidents","text":"The Burundian authorities, which did not systematically publish the official tolls of these incidents, referred to the first incidents as “criminal acts” but, since 25 May 2021, have spoken of “acts of terrorism”. Although they did make legitimate efforts to seek the perpetrators, in the process of doing so, they committed serious human rights violations."},{"id":"a-hrc-48-68-p0021","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"21","seq":20,"section":"2. Right to life","text":"Men suspected of belonging to or assisting armed groups involved in security incidents have been executed by police officers or agents of the National Intelligence Service. Others have died in detention after being tortured by these same State agents. No credible investigation into these incidents has been launched. The acts constitute violations of the obligation of Burundi to respect and protect the right to life."},{"id":"a-hrc-48-68-p0022","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"22","seq":21,"section":"2. Right to life","text":"Several people suspected of being involved in one way or another in security incidents that occurred in their region, notably members of the Congrès national pour la liberté (CNL), have been victims of enforced disappearance. Some of them reappeared in prison a few weeks later, often after having been tortured by intelligence agents. For the period during which they were missing, these individuals were removed from the protection of the law and were therefore victims of enforced disappearance. The fate of several other missing persons remains unknown. The Commission was unable to determine whether the authorities’ suspicions about the individuals’ involvement in attacks were based on objective evidence or were purely a function of their political affiliation or ethnic background. In most cases, they were arrested by police officers or intelligence agents and placed in the custody of the National Intelligence Service."},{"id":"a-hrc-48-68-p0023","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"23","seq":22,"section":"2. Right to life","text":"The Commission also received credible allegations of violations of the right to life. Some members of the Imbonerakure, members of the Conseil national pour la défense de la démocratie-Forces pour la défense de la démocratie (CNDD-FDD) with local administrative responsibilities and some of their relatives appear to have been killed deliberately by unidentified armed men. Groups of unidentified armed men are reported to be also responsible for random attacks resulting in the loss of many civilian lives. The Commission was unable to identify the perpetrators, as victims with ties to CNDD-FDD were reluctant to cooperate in inquiries regarding the targeted attacks and the Government refused to share information on the investigations that had been initiated."},{"id":"a-hrc-48-68-p0024","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"24","seq":23,"section":"3. Right to life and physical integrity","text":"Many people have been arbitrarily arrested and detained following security incidents; either they have been accused of collaborating with or supporting armed groups by, for instance, “giving them food”, often on the sole basis of their political affiliation or ethnic background, or they have been accused in the place of a relative who was wanted for these same reasons. Most of these individuals were detained by the National Intelligence Service and subjected to severe torture, including of a sexual nature, and to ill-treatment."},{"id":"a-hrc-48-68-p0025","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"25","seq":24,"section":"B. Media","text":"The main advances made since President Ndayishimiye’s accession to power concern the media. The Government has taken measures to loosen restrictions on the press; however, being more symbolic than structural, these measures cannot effectively or durably guarantee freedom of information and expression."},{"id":"a-hrc-48-68-p0026","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"26","seq":25,"section":"B. Media","text":"On 24 December 2020, President Ndayishimiye pardoned the journalists of the Iwacu press group who were arrested in October 2019 and convicted of “a failed attempt of complicity in undermining the internal security of the State” for exercising their profession. On 28 January 2021, he affirmed in front of media professionals his commitment to a free and responsible press and requested the National Media Council to find solutions that would allow suspended media outlets to resume their activities."},{"id":"a-hrc-48-68-p0027","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"27","seq":26,"section":"B. Media","text":"On 12 February 2021, the comments section of the Iwacu website was able to reopen, but direct access to the website from within Burundi remains barred. On 19 February, the sanctions imposed against Bonesha radio were lifted and its new management committed to preventing all “professional misconduct”. On 21 April 2021, four media outlets, including Isanganiro television, were authorized to resume broadcasting. On 16 June 2021, BBC radio, which had been suspended since March 2019, was “authorized to reapply for a broadcasting licence”. However, no noteworthy progress has been made with regard to Voice of America, which has also been suspended since 2019."},{"id":"a-hrc-48-68-p0028","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"28","seq":27,"section":"B. Media","text":"Journalists who dare to criticize the Government and its actions or to expose poor governance continue to be vilified. Journalists, including their movements, are closely surveilled by the National Media Council, which stands ready to punish any “deviation” and has no qualms about holding directors of media outlets accountable. Journalists are forced to self-censor, principally out of fear of suffering the same fate as the Iwacu journalists who were arbitrarily detained, and some have been intimidated or threatened while gathering information."},{"id":"a-hrc-48-68-p0029","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"29","seq":28,"section":"B. Media","text":"Furthermore, seven Burundian journalists living in exile were convicted in absentia of undermining State authority, murder and damage to property in connection with the attempted coup d’état of 13 May 2015 and were sentenced to life imprisonment. This judgment of the Supreme Court, dated 23 June 2020, was not made public until 2 February 2021. By way of reminder, in special criminal case No. 100, referred to as the RPS 100 case, 34 alleged coup instigators living in exile, including journalists, human rights defenders, lawyers, CNDD-FDD critics and military personnel, were prosecuted and convicted without representation by counsel. Their assets, which had been seized by the courts in May 2019, were sold at auction in November 2020."},{"id":"a-hrc-48-68-p0030","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"30","seq":29,"section":"B. Media","text":"The official media do not think critically and refuse to call into question government actions or to report on sensitive incidents such as the bodies that are regularly found in public areas and cases of rights violations."},{"id":"a-hrc-48-68-p0031","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"31","seq":30,"section":"B. Media","text":"The Government announced that the 2018 Press Act would be amended to regulate online media and community radio stations and to prevent “content that is contrary to Burundian culture” from circulating on social media. In other words, the only planned structural measure is actually aimed at tightening press controls."},{"id":"a-hrc-48-68-p0032","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"32","seq":31,"section":"C. Civil society","text":"The positive points of note with regard to civil society are generally ad hoc symbolic gestures. On 2 April 2021, Parole et Actions pour le Réveil des Consciences et l’Évolution des Mentalités was authorized to resume its activities after being suspended in June 2019 for “tarnishing the country’s image” by publishing a report critical of the socioeconomic situation in Burundi. Human rights defenders Nestor Nibitanga and Germain Rukuki were released on 27 April 2021 and 30 June 2021, Mr. Nibitanga after a presidential pardon and Mr. Rukuki following his second trial on appeal."},{"id":"a-hrc-48-68-p0033","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"33","seq":32,"section":"C. Civil society","text":"However, the Government has taken measures aimed more at strengthening its control over the activities and functioning of civil society organizations than at reopening the democratic space. The Burundian authorities consider civil society’s sole purpose to be to assist them, thereby denying the very principle of freedom of association, which includes the freedom to choose which objectives to pursue and how to achieve them. For example, the Government has decided to limit operating expenditure within projects funded by technical and financial partners, chiefly by aligning salaries with those in public entities in Burundi. In February 2021, the Government warned foreign non-governmental organizations active in Bubanza Province that they would be subject to inspections to check, inter alia, what they had delivered, the ethnic composition of their staff, the salary and benefits of their expatriate staff and the extent to which the recruitment committees introduced by the Government were involved in their hiring procedures. The authorities are thus making full use of their means of oversight."},{"id":"a-hrc-48-68-p0034","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"34","seq":33,"section":"C. Civil society","text":"In addition, five human rights defenders, lawyers and representatives of non-governmental organizations living in exile have been convicted in absentia and sentenced to life imprisonment in connection with the RPS 100 case and their assets have been confiscated and sold."},{"id":"a-hrc-48-68-p0035","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"35","seq":34,"section":"D. Opposition political parties","text":"After the elections, the many abusive restrictions and violations of the freedoms of association, peaceful assembly and expression that were directed at opposition parties, including CNL, were relaxed, including the bans on organizing gatherings and meetings and on opening offices. This can be explained by the fact that CNL scaled back its activities after the elections and no longer represents an imminent threat to the party in power, especially since it is not a part of the Government or of the National Assembly or Senate Bureaux."},{"id":"a-hrc-48-68-p0036","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"36","seq":35,"section":"D. Opposition political parties","text":"Sporadic incidents have nonetheless been reported in a few provinces; for instance, several CNL offices have been ransacked, including in June 2021. It remains difficult, if not, in some localities, impossible, for CNL to hold meetings. Some opposition militants have been harassed or ill-treated by members of the Imbonerakure in retaliation for their political engagement and others have been intimidated into joining CNDD-FDD. Some have been arbitrarily arrested and detained in connection with their political activities and, in some cases, have been tortured or ill-treated during their arrest and detention, although the number of such cases has fallen. Some active CNL members were victims of enforced disappearance in the months following the elections; they were seen for the last time being taken away by State agents or members of the Imbonerakure. Although at least one of the individuals was later found in detention, the fate of the other victims is unknown."},{"id":"a-hrc-48-68-p0037","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"37","seq":36,"section":"D. Opposition political parties","text":"Hate speech against opponents has by and large been replaced by official calls for tolerance in politics, but there are still occasional statements conflating opponents with “enemies of the State”. President Ndayishimiye himself has blown hot and cold on this subject, recognizing the right to freedom of expression for political parties only to denounce those who do not support the Government as “foreign government agents”. He appears to tolerate the political opposition only if it agrees to work with his Government."},{"id":"a-hrc-48-68-p0038","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"38","seq":37,"section":"D. Opposition political parties","text":"Opposition deputies who have dared to question or criticize government actions have borne the brunt of this mistrust for political opponents, which appears to be deeply entrenched among CNDD-FDD dignitaries. For instance, former deputy Fabien Banciryanino, a rare critic under President Nkurunziza’s regime, was arrested on 2 October 2020 and prosecuted for rebellion, false accusation and undermining the internal and external security of the State. On 7 May 2021, he was sentenced to a year’s imprisonment."},{"id":"a-hrc-48-68-p0039","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"39","seq":38,"section":"D. Opposition political parties","text":"While political violence has generally subsided, this is not necessarily a sign of greater political tolerance. No structural measures have been taken to ensure that the perpetrators of violence during the elections are punished or to prevent such actions from recurring, including during the next elections. Following the elections, the Imbonerakure were reportedly instructed to stop using violence against opponents, but they can still be called up at any time by the authorities and CNDD-FDD. In fact, since the armed attacks in the spring of 2021, CNL members are, in some places, once again being closely watched by the Imbonerakure. As noted previously, following these attacks, some CNL members were accused of collaborating with the rebels or of possessing weapons, but it has not been possible to ascertain whether this was due to their political affiliation or on the basis of objective evidence."},{"id":"a-hrc-48-68-p0040","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"40","seq":39,"section":"E. Returnees","text":"As at 30 June 2021, 276,275 Burundians officially remained refugees in neighbouring countries and 164,990 Burundian refugees had been repatriated under the tripartite voluntary repatriation programme launched in 2017, including 42,299 since January 2021. The refugees returned primarily from Tanzania (129,535) and Rwanda (28,212), where repatriation operations began in August 2020."},{"id":"a-hrc-48-68-p0041","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"41","seq":40,"section":"E. Returnees","text":"The climate of hostility and suspicion towards returnees has abated because, according to several witnesses, instructions were issued to local administrative chiefs and the Imbonerakure to ensure a better reception for returnees – a major challenge if the Government is to achieve its goal of large-scale refugee returns. However, in June 2021, the Conference of Catholic Bishops noted with regret that returnees were not being well received in certain localities and were being intimidated and oppressed."},{"id":"a-hrc-48-68-p0042","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"42","seq":41,"section":"E. Returnees","text":"Some recent returnees have been mistreated, including by members of the Imbonerakure. Certain returnees who had been politically active in the past have been accused of collaborating with armed groups, and some of them have been arbitrarily arrested and detained, then tortured in detention. Sometimes, the fear of being sought by the authorities, arrested or killed has led refugees – including some who had come by their own means to explore the possibility of returning to Burundi under the tripartite programme – to return to their host country."},{"id":"a-hrc-48-68-p0043","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"43","seq":42,"section":"E. Returnees","text":"There remain considerable barriers to the socioeconomic reintegration of returnees, as chronic poverty in the country makes for unstable reception conditions. Government pressure to step up the pace of returns has exceeded the absorption capacity of reception areas. An estimated 70 per cent of returnees are in serious humanitarian need and 23 per cent are in extreme humanitarian need."},{"id":"a-hrc-48-68-p0044","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"44","seq":43,"section":"E. Returnees","text":"Returnees face, inter alia, a lack of livelihoods, shelter and land and limited access to schools and health-care services, as well as security problems including land and intrafamily disputes that have gone unresolved due to justice system dysfunctions. They also experience harassment, persecution and discrimination on the part of local communities and others. Households headed by women are even more vulnerable and encounter specific difficulties. In 2021, 22 per cent of returnees believed that the security situation in Burundi had not improved since they had fled."},{"id":"a-hrc-48-68-p0045","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"45","seq":44,"section":"1. Socioeconomic situation","text":"The overall situation of the Burundian population in terms of its enjoyment of economic and social rights remains preoccupying. An estimated 84 per cent of the population lived under the poverty line in 2019, with an annual per capita income of US$ 260. In 2020, the cost of basic goods such as beans, rice and corn rose, mainly due to the border closures intended to prevent the spread of COVID-19 and to various natural disasters that damaged crops. In 2021, an estimated 2.3 million people in Burundi are in need of humanitarian assistance, and 661,000 are in acute need. The areas of greatest need are food security (2 million people) and nutrition (704,000 people, 63 per cent of whom are children), but also access to health care, water, sanitation, hygiene, shelter and education. These figures are up slightly from 2020, when 1.7 million people were in need."},{"id":"a-hrc-48-68-p0046","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"46","seq":45,"section":"1. Socioeconomic situation","text":"Burundi is particularly vulnerable to natural disasters. In 2020, 100,000 people were affected by natural disasters, including 44,222 who were displaced by them. In terms of health, access to health-care services is jeopardized by the population’s limited financial means and an inadequate network of medical facilities that cannot provide the breadth of services required. President Ndayishimiye’s pledge to ensure that all 119 communes have a hospital has yet to be fulfilled. Burundi took steps to curb the spread of COVID-19 as early as the summer of 2020 and announced at the end of July 2021 that it would finally authorize the population to get vaccinated. Cooperation with the World Health Organization has resumed, with the arrival of its new representative in April 2021."},{"id":"a-hrc-48-68-p0047","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"47","seq":46,"section":"1. Socioeconomic situation","text":"In 2021, an estimated 176,000 people (of whom 98 per cent are women) need protection, including from sexual and gender-based violence. However, most health-care centres do not have the resources or skills necessary to provide victims with appropriate care specific to their needs. Comprehensive emergency services are insufficient and hard to access, with only six integrated centres in the entire country, whose operational capacity has dropped significantly since World Bank funding came to an end. Women and girls living in extreme poverty run a greater risk of being exposed to sexual violence and often adopt harmful survival strategies, such as prostitution, which further heighten their risk of being subjected to sexual and gender-based violence."},{"id":"a-hrc-48-68-p0048","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"48","seq":47,"section":"1. Socioeconomic situation","text":"According to estimates by humanitarian actors, more than 160,000 children aged between 3 and 16 years old, including 80,000 girls, risk not being enrolled in school or having their schooling interrupted in 2021 owing to their family’s extreme poverty and to limited education services resulting from poor infrastructure and insufficient numbers of teachers. The environment remains unconducive to learning, with an average of 75 students per class (133 in Bujumbura Mairie Province) and a lack of teaching materials, water and electricity. Violence in schools, including sexual violence and unwanted pregnancy, are further specific barriers to girls’ education. In 2020, more than half of children aged between 4 and 19 years old in the provinces bordering Tanzania were not enrolled in school."},{"id":"a-hrc-48-68-p0049","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"49","seq":48,"section":"2. Main violations","text":"Despite severe poverty, the population has again been forced to make payments – often with no legal basis – in order to finance public infrastructure, contribute to development or support the party in power, on penalty of being denied access to public services and spaces or the issuance of administrative documents. A so-called “voluntary” contribution was set up by civil servants in at least one province to fund a football tournament in memory of President Nkurunziza. Some people have also been threatened because they were not contributing enough to CNDD-FDD."},{"id":"a-hrc-48-68-p0050","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"50","seq":49,"section":"2. Main violations","text":"Since Évariste Ndayishimiye came to power, the Imbonerakure have reportedly been instructed to stop committing violent acts against the population and usurping the functions of the police. The number of incidents involving members of the Imbonerakure has indeed fallen in several provinces, except in those along the border and those that are the scene of armed attacks, where they remain mobilized by the authorities to ensure security, including, for instance, through the joint committees. They continue to patrol these areas at night, which gives them the opportunity to rob those whose path they cross. On 30 June 2021, the defence forces received a written internal order to rely on “armed political movements” to neutralize armed gangs, in what is essentially official acknowledgement of the fact that the CNDD-FDD youth league is armed and provides support to the defence forces."},{"id":"a-hrc-48-68-p0051","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"51","seq":50,"section":"2. Main violations","text":"Corpses have regularly been found in public areas, including near roads and waterways. The local authorities have continued to bury them without seeking to identify the deceased or to investigate the cause of death and possible perpetrators even though most of the bodies present signs of violent death. According to the Iteka League, 554 people, including 118 women, were reportedly killed during President Ndayishimiye’s first year in power; 250 of the bodies were found in public areas."},{"id":"a-hrc-48-68-p0052","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"52","seq":51,"section":"2. Main violations","text":"Due to the authorities’ serious mishandling of this situation, it is impossible to differentiate between cases constituting violations of the right to life attributable to State agents or the Imbonerakure and cases constituting ordinary criminal offences such as murders linked to land or family disputes and offences committed for base motives, which are commonplace and committed with absolute impunity – especially when the victims belong to an opposition party. The authorities’ conduct in itself constitutes a violation inasmuch as, by refusing to launch credible and impartial investigations into these cases, they are failing in their obligation to protect the rights to life and to an effective remedy. The authorities’ ongoing silence about this situation could even be interpreted as tacit acquiescence to these practices, particularly when the victims do not belong to CNDD-FDD."},{"id":"a-hrc-48-68-p0053","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"53","seq":52,"section":"G. Justice","text":"There has been no notable progress in the fight against impunity. The first convictions in the summer of 2020 were not really followed by others that would have marked a clear departure from past practice. Although police officers and military personnel have been convicted of ordinary offences, which were often committed under the influence of alcohol, and members of the Imbonerakure have been arrested for serious violations, a good number of them were later released and/or “punished” internally. The outcome of proceedings for those still in detention remains uncertain. Agents of the National Intelligence Service and other State entities known for their involvement in numerous human rights violations have reportedly been arrested and detained. However, the opacity surrounding such proceedings makes it impossible to know whether this is in connection with past actions, other crimes and offences or an internal settling of scores."},{"id":"a-hrc-48-68-p0054","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"54","seq":53,"section":"G. Justice","text":"There are persistent dysfunctions in the justice system, including corruption, influence peddling, interference by various authorities and CNDD-FDD members, non-compliance with legal procedures and deadlines, failure to enforce judicial decisions, in particular release orders, and inertia in certain proceedings. Victims of violations continue to be deprived of effective remedies and to be subjected to threats and intimidation."},{"id":"a-hrc-48-68-p0055","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"55","seq":54,"section":"G. Justice","text":"The judiciary’s lack of independence is long-standing, but its instrumentalization for political or diplomatic gain has worsened under President Ndayishimiye, as clearly illustrated by the timeline in the Germain Rukuki case. The Supreme Court ruling quashing the first appeal decision that upheld his 32-year prison sentence was handed down on 30 June 2020, 12 days after President Ndayishimiye’s investiture. The second appeal hearing took place on 24 March 2021, after initial steps forward in the dialogue with the European Union. The decision of the Appeals Court, which should have been rendered within a month, was not promulgated until 21 June 2021, a few hours after the Ambassador of the European Union announced that the process of lifting sanctions on Burundi had been initiated."},{"id":"a-hrc-48-68-p0056","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"56","seq":55,"section":"G. Justice","text":"No structural measures have been taken to resolve these issues. On the contrary, the review by the Supreme Council of Justice will expand and institutionalize the means through which the executive branch may control the judiciary. The Supreme Council of Justice, led by the Head of State, will be responsible for overseeing the quality of judicial decisions and the measures used to enforce them and will even have the power to take corrective measures. At the end of July 2021, the Governor of Bujumbura Province announced that he wished to have control over judicial decisions and their enforcement. The Government also plans to abolish the specialized anti-corruption entities, namely, the Special Court and the Special Brigade, which some observers consider to be a step backwards in the fight against economic malfeasance."},{"id":"a-hrc-48-68-p0057","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"57","seq":56,"section":"H. Economic underpinnings of the State","text":"In its previous report, the Commission noted that corruption, misappropriation of public funds, conflicts of interest and illegal protection of interests underpin the functioning of the Burundian economy, thus depriving the State of the resources necessary to finance the protection and realization of human rights."},{"id":"a-hrc-48-68-p0058","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"58","seq":57,"section":"H. Economic underpinnings of the State","text":"President Ndayishimiye, in acknowledgement of the problem, made the fight against corruption one of his priorities. However, thus far, reforms have been rather modest, even questionable, such as the plan to abolish the specialized anti-corruption entities. Here too, the steps taken have for the most part been symbolic gestures, such as the dramatic ousting, on 1 May 2021, of the Minister for Trade, Transport, Industry and Tourism, whose actions were apparently “putting the country’s economy at risk”, and the mass dismissal, in spring 2021, of public servants accused of misappropriating funds, without thorough investigations or judicial proceedings having been conducted. While it remains to be proven whether such decisions act as deterrents, these collective punishments certainly have an arbitrary feel. Given the current state of affairs, and in the absence of a credible structural reform, the Commission has reasonable grounds to believe that corruption – whether of the kind that affects the daily lives of the population or large-scale corruption – remains endemic in Burundi."},{"id":"a-hrc-48-68-p0059","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"59","seq":58,"section":"H. Economic underpinnings of the State","text":"Moreover, the Head of State’s attitude has on occasions been ambiguous – for example, when he prevaricated over the asset declaration expected of public officials, despite it being required under the Constitution, and when he stated that only acts of corruption committed after he took office would be investigated, de facto entrenching impunity for prior acts."},{"id":"a-hrc-48-68-p0060","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"60","seq":59,"section":"H. Economic underpinnings of the State","text":"Nonetheless, there have been noteworthy developments in the mining sector. The Commission had observed that obtaining mining licences was contingent on the payment of large sums to high-level officials and that the lack of transparency around the annual aid earmarked for community development, combined with a lack of visible achievements on the ground, raised questions about possible misappropriation. However, President Ndayishimiye has ordered an audit of the mining sector, probably in reaction to the 2019 recommendations of the National Security Council, according to which mining companies were not fulfilling their commitments and issued biased reports on their production. On 8 April 2021, the Government banned Rainbow Mining Burundi from exporting the rare earth elements it mines in Gakara. This decision was taken following allegations that the company was making false claims about the prevalence of rare earths and about actual sale prices. On 15 April 2021, the Prime Minister denounced the practices of mining companies that “robbed the country of its natural resources”. On 1 July 2021, the President announced that mining concession agreements that had been established in unlawful conditions and/or contained loopholes would be suspended or terminated so that natural resources could truly be put towards the country’s development. In mid-July 2021, the Government suspended the activities of mining companies, accusing them of breaking mining agreements and adding that the agreements were not sufficiently profitable for Burundi and should be renegotiated."},{"id":"a-hrc-48-68-p0061","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"61","seq":60,"section":"H. Economic underpinnings of the State","text":"Threatening to unilaterally withdraw from mining agreements could well lead to more advantageous agreements for the country. However, negotiations have to be led with absolute transparency if they are to have an impact on corruption. Otherwise, the renegotiations are likely to bring opportunities for further payments to high-level officials. In the interest of all parties concerned, any measures intended to fight corruption or regulate mining activities must be adopted in keeping with the rule of law."},{"id":"a-hrc-48-68-p0062","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"62","seq":61,"section":"I. Rule of law","text":"The rule of law is based on three axioms: the State acts by way of the law; the State is subject to the law; and the law of the State has certain intrinsic attributes. Despite President Ndayishimiye’s desire to promote the rule of law, which has been seriously undermined for several years, it continues to be eroded by increasing disrespect for procedures and laws."},{"id":"a-hrc-48-68-p0063","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"63","seq":62,"section":"I. Rule of law","text":"Officials at the highest levels have openly authorized or accepted infringements of the Constitution and law. For example, ministers have not discharged their constitutional obligation to declare their assets. The President, who initially insisted that this should be done rapidly, later stated that such declarations were neither realistic nor feasible, only to then announce, on 9 June 2021, that the forms were now available and the declarations could be made. He has yet to confirm, however, whether the ministers have filled in their declarations. Furthermore, pursuant to the Arusha Peace and Reconciliation Agreement for Burundi, the Constitution establishes ethnicity quotas for the main institutions and the defence and security forces but, according to various estimates, the quotas are no longer being met anywhere apart from in parliament."},{"id":"a-hrc-48-68-p0064","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"64","seq":63,"section":"I. Rule of law","text":"Other agencies have exceeded their competence by taking decisions without respecting legal procedures. For instance, in February 2021, the Ministry of the Interior, Community Development and Public Security accused the tax collectors of Bujumbura city authority of misappropriating funds and announced that all of them would be replaced. On 9 April 2021, he announced the mass dismissal, with immediate effect, of the 119 communal accountants accused of complicity in the tax collectors’ actions. In February 2021, he decided that shop stalls located near to public markets had 10 days to shut down and relocate inside the markets, even though most of them were operating legally. In July 2021, the Minister of Justice announced the mass dismissal of tribunal de résidence (local court) judges following complaints from the public. The President of the Senate called for unmarried couples who lived together to be imprisoned and put to work in the fields. In addition, local authorities have been multiplying taxes and contributions of all kinds, often without any legal basis."},{"id":"a-hrc-48-68-p0065","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"65","seq":64,"section":"I. Rule of law","text":"By contrast, legitimate decisions have not been fully enforced or implemented. For example, the authorities did not begin to apply the presidential pardon that was theoretically granted to 5,200 prisoners in March 2021 until mid-April. By early July 2021, only 2,600 pardoned prisoners had been released, and some of them were apparently rearrested shortly thereafter while others were kidnapped and declared missing. Some judicial decisions have not been enforced, including, in particular, orders for release on bail pending trial and orders for release following acquittal. For instance, Germain Rukuki should have been released immediately after the Appeals Court rendered its verdict, but he did not leave prison until a week later, after pressure from civil society, NIHRC and the European Union. Other decisions, however, such as the one to destroy constructions considered anarchic or illegal, were enforced almost immediately, without the persons concerned being given an opportunity to contest them or a reasonable period to comply."},{"id":"a-hrc-48-68-p0066","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"66","seq":65,"section":"I. Rule of law","text":"President Ndayishimiye either directly or implicitly approved these decisions, which were taken without legal basis, in contempt of procedure and without any possibility of recourse being left open for the persons concerned. Such practices, no matter how legitimate the decision, undermine the principles of the rule of law, legal certainty and the separation of powers."},{"id":"a-hrc-48-68-p0067","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"67","seq":66,"section":"1. Responsibility of the Burundian State","text":"The Burundian State can be held accountable for acts constituting human rights violations committed by agents of the State, particularly officers of the National Intelligence Service and the police, and also for acts committed by the administrative authorities that represent the State at various levels."},{"id":"a-hrc-48-68-p0068","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"68","seq":67,"section":"1. Responsibility of the Burundian State","text":"The Imbonerakure often act alone, sometimes in support or instead of the security forces, in the presence of agents of the State, with their acquiescence or at their request. The Burundian authorities allow them considerable latitude in their activities, despite having the means to control them. Some Imbonerakure are in possession of material and equipment reserved for the defence and security forces, which attests to their central role within the formal and informal security structures of the State. The Burundian State is directly responsible for actions taken by the Imbonerakure at the instruction, or under the full authority or effective control, of agents of the State. Outside these scenarios, when the Burundian State fails to undertake effective investigations and prosecutions, its responsibility to protect human rights is engaged."},{"id":"a-hrc-48-68-p0069","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"69","seq":68,"section":"2. Responsibility of armed groups","text":"The Commission gathered information on a recent case of violation of the right to freedom, security and physical integrity involving several victims, including children, which was committed in Burundian territory by an unidentified armed group. Armed groups are reportedly also responsible for serious violations of the right to life in the context of armed attacks, but the Commission was unable to gather sufficient information to corroborate the facts and potentially identify the assailants, in part due to the Government’s refusal to cooperate."},{"id":"a-hrc-48-68-p0070","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"70","seq":69,"section":"A. Constituent elements and types of crimes","text":"The Commission still has reasonable grounds to believe that crimes against humanity, as defined in the Rome Statute of the International Criminal Court, continued to be committed in Burundi after the elections. These include imprisonment and other serious forms of deprivation of liberty, torture and politically motivated persecution, primarily targeting political opponents and, in some cases, their relatives."},{"id":"a-hrc-48-68-p0071","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"71","seq":70,"section":"A. Constituent elements and types of crimes","text":"These acts continued to be committed in various provinces by different actors with similar modus operandi, for the purpose of weakening the political opposition. Such incidents can therefore be described as “systematic attacks” deliberately targeting civilians. The alleged perpetrators of these international crimes were undoubtedly informed of this purpose, including through instructions received from various levels of CNDD-FDD and the local authorities, and therefore necessarily understood the context of their actions."},{"id":"a-hrc-48-68-p0072","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"72","seq":71,"section":"B. Individual responsibility","text":"The Commission has updated its list of alleged perpetrators of crimes against humanity, which remains confidential in order to protect its sources and respect the presumption of innocence. However, the Commission reserves the right to share the list."},{"id":"a-hrc-48-68-p0073","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"73","seq":72,"section":"A. Overview","text":"Since 2019, the Commission has examined risk factors for a potential deterioration of the human rights situation in Burundi using the Framework of Analysis for Atrocity Crimes. This approach is consistent with the principles of early warning and prevention. The presence of these risk factors, as measured using objective indicators, does not, however, determine the probability of atrocity crimes being perpetrated. Other relevant developments, in addition to those mentioned in the section on the human rights situation, are detailed in the analysis below."},{"id":"a-hrc-48-68-p0074","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"74","seq":73,"section":"A. Overview","text":"President Ndayishimiye fully embraces the legacy of President Nkurunziza, for whom he has nothing but praise and on whom he has conferred, despite his death, the title of Supreme Guide of Patriotism. The Burundian authorities always present the human rights violations committed since 2015 as “misunderstandings” and “divergences of views” that should be put aside. By entrenching impunity for perpetrators and the lack of remedies for victims in this way, the authorities are closing the door on any lasting reconciliation. Furthermore, the authorities refuse to cooperate with international human rights mechanisms and to discuss related matters. Any mention of violations is considered a politically motivated attack aimed at tarnishing the country’s image. The authorities reject all independent international observation missions on human rights issues and agree only to technical cooperation. Religion and politics remain tightly intertwined; for example, President Ndayishimiye, like his predecessor, holds frequent thanksgiving prayers."},{"id":"a-hrc-48-68-p0075","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"75","seq":74,"section":"A. Overview","text":"However, the President has not hesitated to break with Nkurunziza’s legacy in other domains, for instance in seeking to normalize relations with Rwanda, the European Union and the international community by conducting several official visits to African countries."},{"id":"a-hrc-48-68-p0076","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"76","seq":75,"section":"A. Overview","text":"The consociational democracy ushered in by the Arusha Agreement envisaged the participation of the political opposition, and President Nkurunziza’s successive Governments did include a few ministers from the opposition. However, the current political institutions, from the central to the local level, are completely dominated by CNDD-FDD. The services of the Office of the President have been reorganized to place eight specialized agencies, including the Bank of the Republic of Burundi, the National Intelligence Service, the Permanent Secretariats of the National Security Council and the Supreme Council of Justice, and the General State Inspectorate, under the direct oversight of the President. This concentration of power in favour of CNDD-FDD and the President is part of a locked political and democratic space devoid of any real checks and balances. The CNDD-FDD-controlled parliament adopts bills almost unanimously and is not a space for discussion or a means of overseeing the executive branch."},{"id":"a-hrc-48-68-p0077","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"77","seq":76,"section":"A. Overview","text":"Debate and disagreement are only possible within CNDD-FDD. Tensions between the hard-line wing, which includes Prime Minister Alain-Guillaume Bunyoni and the new Secretary-General of the party, Révérien Ndikuriyo, and the more flexible wing led by President Ndayishimiye are possible and likely. These tensions could explain some of the President’s inconsistencies and about-faces and why some of his decisions are not implemented."},{"id":"a-hrc-48-68-p0078","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"78","seq":77,"section":"A. Overview","text":"The Truth and Reconciliation Commission has continued to exhume the mass graves containing victims of the 1972 massacres but not those connected to other crises that have marked the country’s post-independence history. Between April and June 2021, the Senate organized conferences on the events of 1972, which led to urgent calls to consider the massacres as constituting genocide against the Hutu. The indisputably one-sided and biased view of the country’s history that dominates the transitional justice process magnifies the risk of the events being remembered from an ethnic perspective and the victimization of one ethnic group in relation to the other. Unsurprisingly, these activities have reignited conflicts within Burundian society, thus increasing the risk of incitement to ethnic hatred. On October 2020, the Government conducted a survey of all public servants containing questions on sensitive issues including ethnicity, without offering any guarantees as to how the information would be protected and used or explaining why the questions were necessary."},{"id":"a-hrc-48-68-p0079","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"79","seq":78,"section":"B. Risk factors","text":"The analysis of risk factors shows that the situation in Burundi still calls for special vigilance. The following indicators attest to the presence of forms of instability that generate an environment conducive to atrocity crimes (risk factor 1): a security crisis caused by acts of terrorism and increased security incidents (risk factor 1 (b)); a humanitarian emergency for Burundians in the country and abroad caused by natural disasters or epidemics (risk factor 1 (c)); political tension caused by an autocratic regime or severe political repression (risk factor 1 (f)); economic instability caused by scarcity of resources (risk factor 1 (g)); severe crisis in the national economy (risk factor 1 (h)); and acute poverty (risk factor 1 (i))."},{"id":"a-hrc-48-68-p0080","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"80","seq":79,"section":"B. Risk factors","text":"However, some indicators have improved. While the political crisis stemming from the lack of a peaceful transfer of power in 2015 has not been resolved, the 2020 elections and statements aimed at normalizing relations between Burundi and the international community have made it a less critical problem (risk factor 1 (d)). Moreover, the allegations of widespread electoral fraud in 2020 do not appear to have had an impact on the Government’s perceived legitimacy (risk factor 1 (d))."},{"id":"a-hrc-48-68-p0081","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"81","seq":80,"section":"B. Risk factors","text":"Risk factor 2 relates to a history of serious human rights violations that, because they have not been prevented or punished, create a risk of further violations. Therefore, this structural factor, which is linked to a lack of political willingness and institutional capacity to tackle impunity, remains significant due to: serious past or present violations of human rights (risk factor 2 (a)); the acts of genocide, crimes against humanity and war crimes that have marked the country’s recent history (risk factor 2 (b)); a policy or practice of impunity for or tolerance of serious human rights violations (risk factor 2 (c)); the refusal or reluctance of the Government to use all possible means to put an end to these violations (risk factor 2 (d)); continued support for groups accused of involvement in serious violations or failure to condemn their actions (risk factor 2 (e)); biased accounts or denial of serious human rights violations (risk factor 2 (f)); absence of an impartial and inclusive reconciliation or transitional justice process (risk factor 2 (g)); widespread mistrust in State institutions as a result of impunity (risk factor 2 (h))."},{"id":"a-hrc-48-68-p0082","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"82","seq":81,"section":"B. Risk factors","text":"Risk factor 3, which relates to weakness of State structures and calls into question the State’s capacity to prevent, halt and prosecute atrocity crimes, also remains present: lack of resources and adequate representation in judicial, law enforcement and human rights institutions (risk factor 3 (b)); lack of an independent and impartial judiciary (risk factor 3 (c)); lack of effective civilian control of security forces (risk factor 3 (d)); high levels of corruption or poor governance (risk factor 3 (e)); inadequate or ineffective internal oversight and accountability mechanisms and virtually non-existent or inaccessible external mechanisms for victims (risk factor 3 (f))."},{"id":"a-hrc-48-68-p0083","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"83","seq":82,"section":"B. Risk factors","text":"Risk factor 4 is the existence of reasons, aims or other drivers that justify the use of violence against specific groups. Several indicators of this risk factor remain present: political motives aimed at the consolidation of power (risk factor 4 (a)); economic interests linked to the conservation of power (risk factor 4 (b)); political opponents perceived as a threat to the interests or objectives of the Government or as disloyal to the country (risk factor 4 (e)); real or perceived membership of or support for armed opposition groups (risk factor 4 (f)); the ideology of CNDD-FDD, characterized by a view of the party as the embodiment of truth and thus belief in the supremacy of this political identity over all others (risk factor 4 (g)); the politicization of past grievances or cases of impunity (risk factor 4 (h)); social trauma caused by unresolved past incidents of violence that have aroused feelings of loss, displacement, injustice and a possible desire for revenge (risk factor 4 (i))."},{"id":"a-hrc-48-68-p0084","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"84","seq":83,"section":"B. Risk factors","text":"Risk factor 5, which refers to the capacity of potential perpetrators to commit atrocity crimes, remains present: availability of personnel and arms and ammunition, or of public or private financial resources for their procurement (risk factor 5 (a)); the capacity to transport and deploy personnel and to transport and distribute arms and ammunition (risk factor 5 (b)); the capacity to encourage or recruit large numbers of supporters from populations or groups and the availability of the means to mobilize them (risk factor 5 (c)); a strong culture of obedience to authority and group conformity among CNDD-FDD and the Imbonerakure (risk factor 5 (d)); the presence of other armed forces or non-State armed groups (risk factor 5 (e))."},{"id":"a-hrc-48-68-p0085","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"85","seq":84,"section":"B. Risk factors","text":"The absence of mitigating factors (risk factor 6) persists, notwithstanding a few gestures by the authorities in respect of the media, which remain insufficient to guarantee a free and independent press. The following indicators are present: lack of a strong, organized and representative national civil society and of a free, diverse and independent national media (risk factor 6 (b)); lack of access to international media (risk factor 6 (c)); limited, even non-existent, cooperation with international and regional human rights mechanisms (risk factor 6 (g)); lack of willingness of the Government to engage in dialogue, make concessions and receive support from the international community, including on human rights issues (risk factor 6 (h)); lack of support by some neighbouring States to protect the Burundian population in need of refuge (risk factor 6 (j)); lack of a national early warning mechanism (risk factor 6 (k))."},{"id":"a-hrc-48-68-p0086","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"86","seq":85,"section":"B. Risk factors","text":"The question of the country’s cooperation and engagement with the international community, the United Nations, international non-governmental organizations and other international or regional actors (risk factors 6 (d) and 6 (f)) has become complex. On the one hand, the country has redoubled diplomatic efforts to normalize its relations with the countries of the region and with international and regional organizations, including the European Union, but, on the other, it opposes any cooperation on political or human rights issues, as is apparent in the closure of the Office of the Special Envoy of the Secretary-General for Burundi and the refusal to authorize the reopening of the OHCHR country office."},{"id":"a-hrc-48-68-p0087","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"87","seq":86,"section":"B. Risk factors","text":"Risk factor 7 relates to a climate and circumstances conducive to violence and human rights violations, including the politically motivated exploitation of identity, past events or motives to engage in violence. The main indicators are: interference with vital State institutions, or measures that result in changes to their composition or balance of power, as is the case with the introduction of ethnic quotas (risk factor 7 (b)); the mobilization of the Imbonerakure in areas that are the scene of security incidents (risk factor 7 (e)); persistent violations of the right to life, physical integrity, liberty or security of political opponents (risk factor 7 (h)); the politicization of identity, though there are fewer provocative statements and propaganda or incitement to hatred campaigns with a political and/or ethnic dimension (risk factor 7 (m))."},{"id":"a-hrc-48-68-p0088","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"88","seq":87,"section":"B. Risk factors","text":"Triggering factors (risk factor 8) lessened after the 2020 elections, and there have been positive developments regarding other indicators: the success of the Burundian authorities’ diplomatic overtures to the international community, whose measures are no longer systematically perceived as threatening to the State’s sovereignty, except for those concerning human rights (risk factor 8 (c)); repeated allegations of fraud during the 2020 elections have not undermined the legitimacy of the governing power (risk factor 8 (d)); acts of incitement or hate propaganda targeting political opponents officially dropped after the elections (risk factor 8 (g))."},{"id":"a-hrc-48-68-p0089","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"89","seq":88,"section":"B. Risk factors","text":"However, there remain: serious acts of violence (risk factor 8 (e)); the issue of remembrance and official commemoration of past crimes or of traumatic or historical incidents based on ethnicity that could exacerbate tensions between groups (risk factor 8 (k)); and acts related to the process of determining accountability for past atrocities could be perceived as unfair (risk factor 8 (l)). Furthermore, it remains to be seen what will come of the public service survey and the upcoming population survey in the light of the fears and criticism elicited by the questions on ethnicity (risk factor 8 (h))."},{"id":"a-hrc-48-68-p0090","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"90","seq":89,"section":"VI. Conclusions and recommendations","text":"After more than a year in power, President Ndayishimiye and his Government have markedly improved relations between Burundi and the international community, but there has been little meaningful change in terms of human rights. Symbolic, sometimes sensational, gestures have been made, but these will not serve to advance the fight against impunity and corruption in the long term or to reopen the democratic space. Serious human rights violations have continued to be committed by State officials and members of the Imbonerakure at the instigation or with the acquiescence of the authorities. While the risk factors have improved, they nonetheless all remain present."},{"id":"a-hrc-48-68-p0091","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"91","seq":90,"section":"VI. Conclusions and recommendations","text":"The Commission therefore makes the following recommendations to the Burundian authorities:\n(a)\tTo implement the Commission’s previous recommendations, in particular those regarding the priority measures to be taken to put an end to human rights violations and international crimes, combat impunity and economic malfeasance, reopen the democratic space, guarantee civil liberties, reform the judicial system and control the Imbonerakure;\n(b)\tTo publicly recognize the human rights violations committed in Burundi since April 2015, seek and punish the perpetrators and grant reparations to the victims;\n(c)\tTo guarantee the security, freedom and physical integrity of political opponents and their relatives, journalists, members of civil society, human rights defenders and returnees and ensure that they are not subjected to acts of violence, intimidation, harassment or any form of discrimination, including in the exercise of their fundamental freedoms;\n(d)\tTo ensure that perpetrators of armed attacks are pursued in conformity with fundamental rights and legal procedures and without discrimination;\n(e)\tTo permanently stop the Imbonerakure from usurping the functions of the security forces and the judiciary and to prosecute and punish, as an example, those involved in violations;\n(f)\tTo establish a national torture prevention mechanism, in line with international standards, whose first task would be to prevent torture by agents of the National Intelligence Service;\n(g)\tTo fully cooperate with international and regional human rights mechanisms, including on sensitive matters, authorize them to conduct independent monitoring activities and, to this end, reopen the OHCHR country office;\n(h)\tTo take measures to effectively combat corruption, in particular by implementing the recommendations of the Implementation Review Group of the United Nations Convention against Corruption;\n(i)\tTo guarantee transparency and good governance in the management of resources derived from mining activities;\n(j)\tTo ensure that the Truth and Reconciliation Commission conducts its work in a professional, inclusive, impartial, objective, transparent, balanced, upstanding and credible manner so as to make a genuine and lasting contribution to national reconciliation;\n(k)\tTo take urgent steps to restore the rule of law by ensuring that the law is enforced, including within Government and State institutions, and that the separation of powers is respected;\n(l)\tTo guarantee the population’s right to life with dignity, as well as its economic and social rights, particularly the right to a decent standard of living, inter alia by drawing up and implementing State budgets to the maximum of available resources."},{"id":"a-hrc-48-68-p0092","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"92","seq":91,"section":"VI. Conclusions and recommendations","text":"The Commission recommends to the armed groups that they cease committing human rights violations and acts of violence against State institutions and civilians."},{"id":"a-hrc-48-68-p0093","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"93","seq":92,"section":"VI. Conclusions and recommendations","text":"The Commission makes the following recommendations to the international community:\n(a)\tTo keep following the human rights situation in Burundi, in particular through an independent international mechanism capable of objectively monitoring the human rights situation in the country;\n(b)\tTo ensure that refugees are not forced to return to Burundi under the tripartite voluntary repatriation programme, especially given the deterioration in living conditions, and that returns are voluntary, dignified and safe;\n(c)\tTo support independent civil society organizations in the field of human rights in Burundi, including those located abroad, in conducting investigations into human rights violations in the country and publishing reports on their findings;"},{"id":"a-hrc-48-68-p0094","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"94","seq":93,"section":"VI. Conclusions and recommendations","text":"The Commission makes the following recommendations to the technical and financial partners of Burundi:\n(a)\tTo put in place procedures to minimize and eliminate the risk of economic malfeasance in connection with development assistance projects;\n(b)\tTo prioritize projects designed to reduce risk factors on a lasting basis and to improve transparency and accountability in the management of public finances."},{"id":"a-hrc-48-68-p0001-a1","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"1","seq":94,"section":"1. Recommandations faites en 2020","text":"Vu la profondeur historique de la crise burundaise et la dimension en partie structurelle des violations des droits de l’homme, et prenant en compte le principe de la responsabilité de protéger le peuple burundais, y compris dans le cadre de la transition politique en cours au Burundi, ainsi que les mesures susceptibles d’atténuer les facteurs de risque, la Commission réitère tout d’abord ses précédentes recommandations, qui demeurent entièrement valables et pertinentes, particulièrement celles adressées aux autorités burundaises concernant les mesures prioritaires pour faire cesser les violations des droits de l’homme et les crimes internationaux, lutter contre l’impunité et améliorer la situation des droits de l’homme dans le pays, notamment la réouverture de l’espace démocratique et la protection des libertés publiques. Ses recommandations portant sur les mesures à plus long terme relatives à la révision du cadre juridique et à la réforme du système judiciaire restent cruciales.","annex":1},{"id":"a-hrc-48-68-p0002-a1","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"2","seq":95,"section":"1. Recommandations faites en 2020","text":"Ensuite, la Commission adresse aux autorités burundaises les recommandations suivantes:\na.\tRouvrir le bureau de pays du Haut-Commissariat aux droits de l’homme;\nb.\tLibérer immédiatement les défenseurs des droits de l’homme et journalistes détenus arbitrairement, ainsi que tous les prisonniers politiques, notamment ceux des partis d’opposition arrêtés et détenus dans le contexte des élections de 2020;\nc.\tGarantir la sécurité, la liberté et l’intégrité physique des membres des partis d’opposition, dont le CNL, et assurer qu’ils ne fassent pas l’objet d’actes d’intimidation, de harcèlement ou de toute forme de discrimination en représailles à leur engagement politique;\nd.\tRétablir toutes les libertés publiques pour permettre que les futures échéances électorales soient libres, crédibles et transparentes;\ne.\tFaire cesser l’usurpation des fonctions des forces de sécurité ou de la justice par des Imbonerakure, et poursuivre en justice et sanctionner de manière exemplaire ceux ayant été impliqués dans des violations − sinon dissoudre cette ligue;\nf.\tRéformer les comités mixtes de sécurité humaine afin de les rendre plus inclusifs et de limiter leurs compétences;\ng.\tS’acquitter de leurs obligations spécifiques en matière de droits des femmes et de droits de l’enfant;\nh.\tMettre fin au recrutement des enfants par les Imbonerakure et démanteler les « aiglons » du CNDD-FDD;\ni.\tÉtablir des services de prise en charge psychosociale pour les enfants victimes ou témoins de violations graves, particulièrement parmi les rapatriés;\nj.\tGarantir l’accès à la justice et à des services médicaux et psychosociaux adaptés aux victimes de violences sexuelles, y compris les victimes masculines;\nk.\tInstituer un quota de 30% de femmes dans les conseils collinaires;\nl.\tReprendre une pleine coopération avec l’Organisation mondiale de la Santé;\nm.\tPrendre des mesures afin de lutter efficacement contre les malversations économiques, notamment en assurant la transparence, la concurrence et l’établissement de critères objectifs et prédéterminés pour la passation des marchés publics, ainsi qu’un système de recours interne efficace, et ouvrir des enquêtes sur les allégations de cas de biens mal acquis;\nn.\tDevenir partie à l’Initiative pour la transparence dans les industries extractives et mettre en œuvre les normes associées;\no.\tPublier systématiquement le budget annuel exécuté;\np.\tGarantir que les hauts responsables politiques et administratifs procèdent systématiquement à une déclaration publique de leur patrimoine à leur prise de fonction et à la fin de leur mandat.","annex":1},{"id":"a-hrc-48-68-p0003-a1","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"3","seq":96,"section":"1. Recommandations faites en 2020","text":"Aux groupes rebelles d’opposition, la Commission recommande de s’abstenir de tout acte violent.","annex":1},{"id":"a-hrc-48-68-p0004-a1","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"4","seq":97,"section":"1. Recommandations faites en 2020","text":"À la communauté internationale, conformément à son devoir de vigilance, la Commission adresse les recommandations suivantes:\na.\tMaintenir un mécanisme international indépendant qui puisse suivre objectivement la situation des droits de l’homme au Burundi, y compris au moyen des facteurs de risque et de la mise en œuvre des recommandations de la Commission;\nb.\tBaser la reprise de la coopération internationale avec le Burundi et la levée des sanctions sur des progrès tangibles en matière de droits de l’homme et de lutte contre l’impunité et la corruption;\nc.\tS’assurer que les réfugiés ne soient pas forcés à rentrer au Burundi tant que les conditions dans le pays ne sont pas propices, et demander un accès libre aux rapatriés pour évaluer leur situation;\nd.\tSoutenir les organisations de la société civile actives dans le domaine des droits de l’homme au Burundi, notamment pour faire des enquêtes et des rapports publics.","annex":1},{"id":"a-hrc-48-68-p0005-a1","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"5","seq":98,"section":"1. Recommandations faites en 2020","text":"Aux États et aux organisations internationales qui financent des programmes d’aide internationale au développement, la Commission recommande de renforcer leurs procédures pour minimiser les risques de détournement de fonds et d’ouvrir systématiquement des enquêtes sur les allégations reçues à ce sujet, afin de s’assurer que ladite assistance est entièrement utilisée pour les objectifs prévus et au profit des bénéficiaires envisagés.","annex":1},{"id":"a-hrc-48-68-p0006-a1","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"6","seq":99,"section":"1. Recommandations faites en 2020","text":"Au système des Nations Unies, y compris à ses agences, la Commission adresse les recommandations suivantes:\na.\tConformément à la politique de diligence voulue en matière de droits de l’homme, fournir un appui uniquement lorsqu’il y a des garanties que ceux qui sont appelés à en bénéficier ne sont pas des auteurs de violations graves des droits de l’homme, sur le plan individuel ou institutionnel, et ne pas fournir un tel appui lorsqu’il y a eu des allégations crédibles à cet égard ou lorsque les autorités compétentes ne prennent pas les mesures de correction ou d’atténuation nécessaires;\nb.\tRenforcer l’appui à la réponse aux violences sexuelles ou fondées sur le genre pour mieux prendre en compte les besoins spécifiques des victimes, y compris parmi les réfugiés.\nVersion anglaise","annex":1},{"id":"a-hrc-48-68-p0001-a2","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"1","seq":100,"section":"1. Recommandations faites en 2020","text":"In view of the historical depth of the Burundian crisis and the partly structural dimension of human rights violations, and taking into account the principle of the responsibility to protect the people of Burundi, including in the context of the political transition under way in the country, as well as the measures likely to mitigate risk factors, the Commission first reiterates its previous recommendations. Those recommendations remain entirely valid and relevant, particularly those addressed to the Burundian authorities concerning measures to be given priority in order to put an end to human rights violations and international crimes, to combat impunity and to improve the human rights situation in the country, including the reopening of the democratic space and the protection of civil liberties. Its recommendations for longer-term measures relating to the review of the legal framework and the reform of the judiciary remain crucial.","annex":2},{"id":"a-hrc-48-68-p0002-a2","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"2","seq":101,"section":"1. Recommandations faites en 2020","text":"The Commission also makes the following recommendations to the Burundian authorities:\na.\tTo reopen the country office of the Office of the United Nations High Commissioner for Human Rights;\nb.\tTo immediately release human rights defenders and journalists who have been arbitrarily detained, as well as all political prisoners, including those from opposition parties arrested and detained in the context of the 2020 elections;\nc.\tTo guarantee the safety, freedom and physical integrity of members of opposition parties, including the Congrès national pour la liberté, and to ensure that they are not subjected to intimidation, harassment or any form of discrimination as a reprisal for their political activities;\nd.\tTo restore all civil liberties to enable future elections to be free, credible and transparent;\ne.\tTo stop the Imbonerakure from usurping the functions of the security forces and the judiciary and to prosecute and punish, as an example, those who have been involved in violations, or alternatively to dissolve the Imbonerakure;\nf.\tTo reform the Joint Human Security Committees to make them more inclusive and to limit the scope of their competence;\ng.\tTo fulfil the specific obligations of the authorities with regard to women’s rights and the rights of the child;\nh.\tTo put an end to the recruitment of children by the Imbonerakure and to disband the CNDD-FDD party’s “Little Eagles”;\ni.\tTo establish psychosocial care services for child victims and witnesses of serious human rights violations, particularly among returnees;\nj.\tTo ensure access to justice and appropriate medical and psychosocial services for victims of sexual violence, including male victims;\nk.\tTo establish a 30 per cent quota for women on hill district councils;\nl.\tTo resume full cooperation with the World Health Organization;\nm.\tTo take measures to effectively combat economic misfeasance, in particular by ensuring transparency, competition and the establishment of objective and pre-established criteria for the awarding of government contracts, as well as an effective system of domestic remedies, and to investigate allegations of cases of ill-gotten gains;\nn.\tTo become a party to the Extractive Industries Transparency Initiative and to implement the related standards;\no.\tTo systematically publish the annual budget, as implemented;\np.\tTo ensure that senior political and administrative officials systematically make a public declaration of their assets upon taking office and at the end of their term.","annex":2},{"id":"a-hrc-48-68-p0003-a2","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"3","seq":102,"section":"1. Recommandations faites en 2020","text":"The Commission recommends that opposition rebel groups refrain from violence.","annex":2},{"id":"a-hrc-48-68-p0004-a2","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"4","seq":103,"section":"1. Recommandations faites en 2020","text":"For the international community, in keeping with its duty of vigilance, the Commission has the following recommendations:\na.\tTo maintain an independent international mechanism that can objectively monitor the human rights situation in Burundi, including through the monitoring of risk factors and the implementation of the Commission’s recommendations;\nb.\tTo base the resumption of international cooperation with Burundi and the lifting of sanctions on tangible progress in the area of human rights and the fight against impunity and corruption;\nc.\tTo ensure that refugees are not forced to return to Burundi until conditions in the country are favourable and to request free access to returnees to assess their situation;\nd.\tTo support civil society organizations active in the field of human rights in Burundi, in particular for investigations and public reporting.","annex":2},{"id":"a-hrc-48-68-p0005-a2","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"5","seq":104,"section":"1. Recommandations faites en 2020","text":"The Commission recommends that States and international organizations funding international development assistance programmes strengthen their procedures to minimize the risk of misappropriation of funds and systematically investigate allegations that they receive in order to ensure that such assistance is fully utilized for the intended purposes and to the benefit of the intended beneficiaries.","annex":2},{"id":"a-hrc-48-68-p0006-a2","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"6","seq":105,"section":"1. Recommandations faites en 2020","text":"To the United Nations system, including its agencies, the Commission makes the following recommendations:\na.\tIn accordance with the human rights due diligence policy, to provide support only when there are guarantees that those who are to benefit from it are not perpetrators of serious human rights violations, either individually or institutionally, and not to provide such support when there have been credible allegations in this regard or when the competent authorities fail to take the necessary corrective or mitigating measures;\nb.\tTo strengthen support for the response to sexual and gender-based violence in order to better address the specific needs of victims, including among refugees.","annex":2},{"id":"a-hrc-48-68-p0001-a3","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"1","seq":106,"section":"2. Recommandations faites en 2019","text":"La tenue des élections de 2020 est un facteur de risque important. Afin qu’elles puissent se dérouler dans un climat apaisé tout en étant justes, libres, transparentes et crédibles, la Commission adresse aux autorités burundaises les recommandations suivantes:\na.\tMettre en œuvre toutes les recommandations précédentes de la Commission, qui restent plus que jamais valables et pertinentes, notamment celles concernant les mesures prioritaires afin de faire cesser les violations des droits de l’homme et les crimes internationaux, de lutter contre l’impunité, et d’améliorer la situation des droits de l’homme dans le pays, ainsi que celles à moyen et plus long termes relatives à la révision du cadre juridique et à la réforme du système judiciaire;\nb.\tDiligenter sans délai des enquêtes indépendantes et effectives sur les cas de violations documentés par la Commission depuis 2015, afin de permettre l’instauration d’un climat de confiance et de tolérance politique encourageant une participation inclusive dans le processus électoral;\nc.\tSe réengager de manière constructive et coopérative auprès de tous les mécanismes internationaux et régionaux des droits de l’homme et du Haut-Commissariat aux droits de l’homme, en leur permettant d’assurer pleinement et librement leurs mandats de suivi des droits de l’homme;\nd.\tAssurer l’indépendance structurelle et financière des mécanismes nationaux des droits de l’homme et renforcer la capacité de leurs membres;\ne.\tPrendre les mesures nécessaires afin de garantir la liberté d’établissement, d’organisation et de fonctionnement des ONG étrangères et nationales, y compris en révisant les lois qui les régissent;\nf.\tPrendre les mesures nécessaires afin de garantir la liberté d’information dans le pays et le droit des médias locaux et internationaux d’exercer leurs activités conformément aux normes internationales, y compris en révisant les lois sur la presse et le Conseil national de la communication;\ng.\tGarantir la jouissance effective des libertés publiques, notamment les libertés d’opinion, d’expression, d’accès à l’information, d’association, d’assemblée et de religion, y compris en mettant fin à toute pratique de recrutement forcé au sein du parti au pouvoir et de sa ligue des jeunes;\nh.\tAppliquer les Lignes directrices sur l’accès à l’information et les élections en Afrique et les Lignes directrices sur la liberté d’association et de réunion en Afrique de la Commission africaine des droits de l’homme et des peuples;\ni.\tGarantir que tous les partis politiques peuvent mener leurs activités légitimes en toute liberté et sécurité, dans un climat de tolérance politique, notamment en sanctionnant tout propos d’incitation à la haine et à la violence contre les autres partis politiques et leurs membres;\nj.\tGarantir, dans la pratique, notamment en révisant le Code électoral, le droit à prendre part à la gestion des affaires publiques sans discrimination;\nk.\tGarantir, dans la pratique, l’indépendance structurelle de la Commission électorale nationale indépendante, notamment en révisant le décret la régissant afin que sa composition soit inclusive et équilibrée, et renforcer les capacités de ses membres aux échelons municipal et provincial;\nl.\tPermettre l’accès d’observateurs électoraux indépendants, internationaux et régionaux, et leur garantir, ainsi qu’aux observateurs nationaux issus de la société civile ou des partis politiques, une liberté de mouvement et d’action avant, pendant et après les élections;\nm.\tAppliquer les Directives pour les missions d’observation et de suivi des élections de l’Union africaine;\nn.\tPermettre aux opposants politiques de rentrer d’exil afin de participer aux élections de 2020, et garantir leur liberté et leur sécurité, notamment en annulant les mandats d’arrêt contre ceux qui n’ont pas utilisé ou prôné la violence;\no.\tLibérer immédiatement tous les prisonniers politiques arrêtés et détenus en lien avec l’exercice de leurs droits démocratiques;\np.\tRenforcer la formation des forces de maintien de l’ordre, afin d’éviter les mauvais traitements et d’assurer une gestion pacifique des foules;\nq.\tAppliquer les Lignes directrices pour le maintien de l’ordre par les agents chargés de l’application des lois lors des réunions en Afrique, et le manuel de formation y relatif, élaborés par la Commission africaine des droits de l’homme et des peuples;\nr.\tMettre fin à l’impunité des Imbonerakure en exerçant un contrôle sur eux, afin d’éviter l’usurpation des fonctions des forces de sécurité ou de la justice et de faire cesser leurs activités répressives et démonstrations de force sur les collines;\ns.\tMettre fin à toutes les contributions illégales.","annex":3},{"id":"a-hrc-48-68-p0002-a3","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"2","seq":107,"section":"2. Recommandations faites en 2019","text":"À tous les partis politiques burundais, qu’ils participent ou non aux élections, la Commission recommande de s’abstenir de tout acte violent et de toute incitation à la haine et à la violence, notamment dans le contexte des élections de 2020.","annex":3},{"id":"a-hrc-48-68-p0003-a3","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"3","seq":108,"section":"2. Recommandations faites en 2019","text":"Aux groupes rebelles d’opposition, la Commission recommande de s’abstenir de tout acte violent et de toute incitation à la haine et à la violence.","annex":3},{"id":"a-hrc-48-68-p0004-a3","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"4","seq":109,"section":"2. Recommandations faites en 2019","text":"À la communauté internationale, y compris l’Union africaine et le système des Nations Unies, la Commission adresse les recommandations suivante:\na.\tRenouveler le mandat de la présente Commission pour une année supplémentaire;\nb.\tContinuer à suivre l’évolution de la situation des droits de l’homme au Burundi dans le contexte des élections de 2020 et, conformément aux principes de prévention et d’alerte précoce, faire régulièrement l’évaluation des risques, afin de permettre, en cas de détérioration, que soient développées et mises en œuvre des stratégies de réponse adaptées;\nc.\tMettre tout en œuvre pour assurer la tenue d’un dialogue interburundais inclusif afin de régler la crise politique;\nd.\tSoutenir le renforcement des capacités des observateurs électoraux internationaux, régionaux et nationaux;\ne.\tEnvoyer des observateurs régionaux ou internationaux uniquement si leur liberté d’action est garantie dans la pratique;\nf.\tS’assurer que l’aide humanitaire parvient intégralement à la population;\ng.\tRépondre à l’appel de financement du Haut-Commissariat des Nations Unies pour les réfugiés en faveur des réfugiés burundais;\nh.\tS’assurer que le suivi des rapatriés se fait dans la durée, de manière plus fréquente et transparente.","annex":3},{"id":"a-hrc-48-68-p0005-a3","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"5","seq":110,"section":"2. Recommandations faites en 2019","text":"Plus particulièrement, la Commission recommande au système des Nations Unies, conformément à l’initiative Les droits de l’homme avant tout, d’intensifier la promotion des droits de l’homme relevant des mandats propres aux agences et programmes concernés, de même que la collecte et la publication de données objectives et fiables sur la situation au Burundi.","annex":3},{"id":"a-hrc-48-68-p0006-a3","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"6","seq":111,"section":"2. Recommandations faites en 2019","text":"Aux États membres du Conseil de sécurité, la Commission recommande de maintenir le Burundi dans le programme de travail du Conseil, au regard des facteurs de risque identifiés, et d’inviter la Commission à lui rendre compte de ses conclusions.\nVersion anglaise","annex":3},{"id":"a-hrc-48-68-p0001-a4","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"1","seq":112,"section":"2. Recommandations faites en 2019","text":"The 2020 elections pose a major risk. To ensure that they are peaceful, fair, free, transparent and credible, the Commission makes the following recommendations to the Burundian authorities:\na.\tGive effect to all the Commission’s previous recommendations, which are more well-founded and relevant than ever, including those concerning priority measures to end human rights violations and international crimes, combat impunity and improve the human rights situation in the country and the medium- and longer-term recommendations on reforms to the legal framework and the judicial system;\nb.\tConduct prompt, independent and effective investigations into the cases of violations documented by the Commission since 2015 with a view to creating a climate of trust and political tolerance conducive to inclusive participation in the electoral process;\nc.\tRe-engage constructively and cooperatively with all international and regional human rights mechanisms and the Office of the United Nations High Commissioner for Human Rights, enabling them to carry out their human rights monitoring mandates fully and freely;\nd.\tEnsure that national human rights mechanisms are institutionally and financially independent and build the capacity of their members;\ne.\tTake the measures necessary to ensure that foreign and domestic NGOs can be freely established and organized and that they can operate freely, including by amending the laws regulating them;\nf.\tTake the measures necessary to ensure freedom of information in the country and the right of local and international media to operate in accordance with international standards, including by amending the laws on the press and the National Communication Council;\ng.\tGuarantee the effective enjoyment of civil liberties, including the freedoms of opinion, expression, access to information, association, assembly and religion, not least by ending all forced recruitment to the ruling party and its youth league;\nh.\tFollow the Guidelines on Access to Information and Elections in Africa and the Guidelines on Freedom of Association and Assembly of the African Commission on Human and Peoples’ Rights;\ni.\tEnsure that all political parties can engage in legitimate activities in complete freedom and security, in an environment of political tolerance, including by punishing any incitement to hatred and calls for violence against other political parties and their members;\nj.\tEnsure, in practice, the right to participate in the conduct of public affairs without discrimination, in particular by amending the Electoral Code;\nk.\tEnsure, in practice, the institutional independence of the Independent National Electoral Commission, including by amending the decree governing it to make certain that its composition is inclusive and balanced, and strengthen the capacity of its members at the municipal and provincial levels;\nl.\tProvide access to independent international and regional election observers and ensure that they and national observers from civil society or political parties enjoy freedom of movement and action before, during and after the elections;\nm.\tFollow the Guidelines for African Union Electoral Observation and Monitoring Missions;\nn.\tAllow political opponents to return from exile to participate in the 2020 elections and guarantee their freedom and security, including by revoking warrants for the arrest of those who have not used or advocated violence;\no.\tImmediately release all political prisoners arrested and detained in connection with the exercise of their democratic rights;\np.\tMake the training provided to law enforcement agencies more robust to avoid ill-treatment and ensure the peaceful control of crowds;\nq.\tFollow the Guidelines for the Policing of Assemblies by Law Enforcement Officials in Africa and the related training manual, both developed by the African Commission on Human and Peoples’ Rights;\nr.\tEnd the impunity of the Imbonerakure by exercising control over them so as to ensure that the functions of the security forces or the judiciary are not usurped and put an end to their repressive activities and shows of force in the hills;\ns.\tEnd all illegal contributions.","annex":4},{"id":"a-hrc-48-68-p0002-a4","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"2","seq":113,"section":"2. Recommandations faites en 2019","text":"The Commission recommends that, whether they participate in the elections or not, all political parties in Burundi refrain from violence and incitement to hatred or violence, particularly against the backdrop of the 2020 elections.","annex":4},{"id":"a-hrc-48-68-p0003-a4","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"3","seq":114,"section":"2. Recommandations faites en 2019","text":"The Commission recommends that opposition rebel groups refrain from violence and incitement to hatred or violence.","annex":4},{"id":"a-hrc-48-68-p0004-a4","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"4","seq":115,"section":"2. Recommandations faites en 2019","text":"For the international community, including the African Union and the United Nations system, the Commission has the following recommendations: \na.\tRenew the mandate of the Commission for an additional year;\nb.\tContinue to monitor developments in the human rights situation in Burundi in the context of the 2020 elections and, in accordance with the principles of prevention and early warning, carry out regular risk assessments to enable the development and use of appropriate response strategies in the event of deterioration;\nc.\tMake every effort to ensure that an inclusive inter-Burundi dialogue is held to resolve the political crisis;\nd.\tSupport capacity-building for international, regional and national election observers;\ne.\tSend regional or international observers only if their freedom of action is guaranteed in practice;\nf.\tEnsure that all humanitarian aid reaches the population;\ng.\tRespond to the appeal made by the Office of the United Nations High Commissioner for Refugees for funds for Burundi refugees;\nh.\tEnsure that returnees are monitored in a sustained and more regular and transparent manner.","annex":4},{"id":"a-hrc-48-68-p0005-a4","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"5","seq":116,"section":"2. Recommandations faites en 2019","text":"In particular, the Commission recommends that the United Nations system, in accordance with the initiative Human Rights Up Front, take stronger measures to promote human rights, under the mandates of the relevant agencies and programmes, and to collect and publish objective and reliable data on the situation in Burundi.","annex":4},{"id":"a-hrc-48-68-p0006-a4","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"6","seq":117,"section":"2. Recommandations faites en 2019","text":"In view of the risk factors that have been identified, the Commission recommends that the States members of the Security Council keep Burundi on the Council’s programme of work and that the Council invite the Commission to report to it on its conclusions.","annex":4},{"id":"a-hrc-48-68-p0001-a5","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"1","seq":118,"section":"3. Recommandations faites en 2018","text":"La Commission recommande au Gouvernement burundais, comme mesures prioritaires:\na.\tDe mettre immédiatement un terme aux violations graves des droits de l’homme commises par des agents de l’État et des Imbonerakure;\nb.\tD’établir, avec le soutien de la communauté internationale, des mécanismes ad hoc chargés d’enquêter sur les violations des droits de l’homme et de poursuivre les auteurs de crimes de droit international qui ne font pas l’objet d’une enquête par la Cour pénale internationale;\nc.\tD’établir, avec le soutien de la communauté internationale, une entité indépendante chargée de faire la lumière sur les cas de disparition signalés depuis avril 2015, de localiser les possibles fosses communes, d’exhumer et d’identifier les corps;\nd.\tDe prendre des mesures pour que les victimes de torture et les femmes ayant subi des violences sexuelles aient accès à des soins appropriés, en particulier un libre accès à tous les soins de santé sexuelle et reproductive, ainsi qu’à un soutien psychologique;\ne.\tD’appliquer les Lignes directrices sur la lutte contre les violences sexuelles et leurs conséquences en Afrique de la Commission africaine des droits de l’homme et des peuples;\nf.\tDe contrôler les hausses des prix, en particulier en revoyant l’augmentation des taxes et des impôts qui porte atteinte au droit à un niveau de vie suffisant de la population, et en supprimant les contributions qui touchent disproportionnellement les personnes les plus pauvres;\ng.\tDe coopérer avec les mécanismes internationaux des droits de l’homme, notamment:\n•\t(i) En accueillant à nouveau des missions de procédures spéciales;\n•\t(ii) En mettant en œuvre les recommandations de l’examen périodique universel, des organes conventionnels et des procédures spéciales, notamment en établissant un mécanisme national d’élaboration des rapports et de suivi;\nh.\tD’autoriser le Haut-Commissariat des Nations Unies aux droits de l’homme à reprendre sans entrave l’ensemble de ses activités au Burundi;\ni.\tDe signer et de mettre en œuvre le mémorandum d’entente avec l’Union africaine et de permettre le déploiement complet des 100 observateurs des droits de l’homme.","annex":5},{"id":"a-hrc-48-68-p0002-a5","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"2","seq":119,"section":"3. Recommandations faites en 2018","text":"La Commission recommande également au Gouvernement burundais, à moyen et plus long termes:\na.\tDe réviser la loi organique du 8 mars 2018 portant révision de la loi no 01/03 du 24 janvier 2013 portant missions, composition, organisation et fonctionnement du Conseil national de la communication afin de garantir l’indépendance de ce dernier;\nb.\tDe ratifier la Convention internationale pour la protection de toutes les personnes contre les disparitions forcées;\nc.\tDe réviser les dispositions du Code de procédure pénale pour les mettre en conformité avec les normes internationales, en particulier les dispositions relatives aux délais de garde à vue et de contrôle de la détention, aux perquisitions de nuit et sans mandat, à la procédure de « flagrance », à l’infraction d’« atteinte à la sûreté intérieure de l’État », et à celles accordant une impunité de jure aux magistrats et aux officiers de police judiciaire;\nd.\tDe mettre fin aux détentions arbitraires et d’améliorer les conditions de détention:\n•\t\tEn appliquant les Lignes directrices sur les conditions d’arrestation, de garde à vue et de détention provisoire en Afrique de la Commission africaine des droits de l’homme et des peuples;\n•\t\tEn garantissant le contrôle de la légalité des détentions et leur conformité avec les droits de l’homme.\ne.\tFaute d’un système judiciaire indépendant et performant, de coopérer pleinement avec la Cour pénale internationale dans l’enquête qu’elle a ouverte le 25 octobre 2017;\nf.\tD’engager une réforme en profondeur du système judiciaire afin de garantir son indépendance, son impartialité et son effectivité, notamment:\n•\t(i) En appliquant les Directives et les Principes sur le droit à un procès équitable et à l’assistance judiciaire en Afrique de la Commission africaine des droits de l’homme et des peuples;\n•\t(ii) En publiant les conclusions des états généraux de la justice de 2013 et en réunissant les acteurs du secteur et les partenaires internationaux pour discuter des mesures de suivi;\n•\t(iii) En augmentant le budget du secteur de la justice et en garantissant son autonomie de gestion;\n•\t(iv) En revalorisant la rémunération des magistrats des juridictions ordinaires ainsi que les moyens et l’équipement à leur disposition;\n•\t(v) En informatisant les greffes;\n•\t(vi) En revoyant la composition du Conseil supérieur de la magistrature afin que ses membres soient en majorité désignés par leurs pairs;\n•\t(vii) En revoyant les procédures de nomination, d’affectation, de notation et d’avancement des magistrats afin qu’elles ne dépendent pas du pouvoir exécutif;\n•\t(viii) En veillant au respect strict du principe d’inamovibilité des magistrats du siège;\n•\t(ix) En protégeant et en garantissant l’indépendance du système judiciaire en interdisant toute ingérence dans le fonctionnement de la justice par des autorités gouvernementales, des membres du parti au pouvoir ou par des membres des corps de défense et de sécurité, et en prenant des sanctions contre ceux qui influencent, ou cherchent à influencer, le fonctionnement de la justice;\n•\t(x) En développant des programmes d’aide juridictionnelle pour les plus vulnérables;\n•\t(xi) En renforçant les mécanismes de protection de victimes et de témoins, ainsi que leur efficacité, pour restaurer la confiance de la population et pour encourager les témoins à s’exprimer sans crainte pour leur sécurité.\ng.\tDe mettre en place, en consultation avec les bénéficiaires, un programme de réparations des victimes des violations des droits de l’homme qui comprenne des réparations matérielles, symboliques, individuelles et collectives, et qui ne soit pas dépendant de la condamnation des auteurs;\nh.\tD’établir le fond étatique pour les victimes de torture prévu par la loi et en conformité avec l’Observation générale no 4 de la Commission africaine des droits de l’homme et des peuples sur la Charte africaine des droits de l’homme et des peuples, concernant le droit à réparation des victimes de torture et autres peines ou traitements cruels, inhumains ou dégradants (art. 5);\ni.\tD’établir un fond pour l’indemnisation des victimes de détention arbitraire et illégale;\nj.\tDe réformer le secteur de la sécurité:\n•\t(i) En s’assurant que des éléments extérieurs n’accomplissent pas des activités de défense ou de sécurité;\n•\t(ii) En délimitant clairement les rôles des différents corps de défense et de sécurité, en particulier du SNR;\n•\t(iii) En suspendant les membres des corps de défense et de sécurité suspectés d’être impliqués dans des violations des droits de l’homme jusqu’au terme des enquêtes et des procédures judiciaires;\n•\t(iv) En établissant des procédures strictes et transparentes de sélection qui intègrent des mécanismes de vérification des antécédents;\n•\t(v) En renforçant le contrôle civil et démocratique des corps de défense et de sécurité, en particulier du SNR.\nk.\tDe s’acquitter de ses obligations internationales de respecter, de protéger et de garantir les droits économiques et sociaux:\n•\t(i) En élaborant et en mettant en œuvre les budgets de l’État de manière à utiliser au maximum les ressources disponibles pour assurer le respect des droits de l’homme à la population appauvrie par la crise politique, en particulier des droits à l’alimentation, à l’eau et à la santé, et pour développer des indicateurs désagrégés, y compris par genre, pour mieux informer ses politiques;\n•\t(ii) En entreprenant, en consultation avec les populations travaillant dans le secteur agricole, notamment les femmes, des réformes visant une meilleure protection des droits des femmes et une meilleure utilisation des terres pour l’agriculture, et en développant des perspectives de travail en dehors du secteur agricole;\n•\t(iii) En utilisant une approche fondée sur les droits de l’homme pour régler les conflits fonciers dont ceux touchant les personnes ayant fui le Burundi avant et après 2015;\n•\t(iv) En mettant fin à toute considération politique dans les processus de recrutement au sein de l’administration publique, des sociétés publiques et des sociétés mixtes.","annex":5},{"id":"a-hrc-48-68-p0003-a5","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"3","seq":120,"section":"3. Recommandations faites en 2018","text":"La Commission recommande aux partis politiques et aux groupes armés d’opposition de s’abstenir de toute attaque sur le territoire burundais et de tout discours appelant à la violence, et de s’engager dans la recherche d’une solution durable à la crise politique.","annex":5},{"id":"a-hrc-48-68-p0004-a5","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"4","seq":121,"section":"3. Recommandations faites en 2018","text":"La Commission recommande à l’Union africaine de donner une place importante, dans sa recherche d’une solution durable à la crise au Burundi, au respect des droits de l’homme et au rejet de l’impunité, tels que prévus par son Acte constitutif.","annex":5},{"id":"a-hrc-48-68-p0005-a5","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"5","seq":122,"section":"3. Recommandations faites en 2018","text":"La Commission recommande aux partenaires techniques et financiers du Burundi:\na.\tDe suspendre ou de maintenir la suspension de toute aide budgétaire directe au Gouvernement en l’absence de priorisation des ressources internes en faveur des objectifs de développement durable et des droits économiques et sociaux de la population, et de mesures effectives contre la corruption;\nb.\tDe cibler les dons et les financements attribués au Gouvernement sur des projets en faveur des besoins de la population et de s’assurer que ceux-ci sont gérés efficacement et de manière transparente;\nc.\tD’évaluer régulièrement l’impact des sanctions financières sur la population burundaise.","annex":5},{"id":"a-hrc-48-68-p0006-a5","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"6","seq":123,"section":"3. Recommandations faites en 2018","text":"La Commission recommande aux garants de l’Accord d’Arusha, en leur qualité d’acteurs engagés en faveur d’une paix durable au Burundi, de continuer à chercher une solution pérenne à la crise politique et des droits de l’homme qui préserve et garantit les acquis de l’Accord d’Arusha.\nVersion anglaise","annex":5},{"id":"a-hrc-48-68-p0001-a6","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"1","seq":124,"section":"3. Recommandations faites en 2018","text":"The Commission recommends that the Government of Burundi take the following measures as a matter of priority:\na.\tPut an immediate end to the gross human rights violations being committed by agents of the State and Imbonerakure;\nb.\tWith the support of the international community, establish ad hoc mechanisms with a mandate to investigate human rights violations and to prosecute perpetrators of international crimes that are not being investigated by the International Criminal Court;\nc.\tWith the support of the international community, establish an independent body with a mandate to investigate the cases of disappearance reported since April 2015, locate potential mass graves, and exhume and identify the remains;\nd.\tTake measures to ensure that victims of torture and women survivors of sexual violence have access to appropriate care, including free access to all sexual and reproductive health services and to psychological support;\ne.\tImplement the Guidelines on Combating Sexual Violence and its Consequences in Africa adopted by the African Commission on Human and Peoples’ Rights;\nf.\tControl price increases, in particular by reviewing duty and tax increases that are undermining the population’s right to an adequate standard of living and by abolishing contributions that disproportionately affect the poorest sectors;\ng.\tCooperate with international human rights mechanisms, in particular by:\n•\t(i) Resuming the practice of allowing special procedures mandate holders to conduct missions to Burundi;\n•\t(ii) Implementing the recommendations of the universal periodic review, treaty bodies and special procedures, including by establishing a national mechanism for reporting and follow-up.\nh.\tAuthorize the Office of the United Nations High Commissioner for Human Rights to resume all its activities in Burundi without hindrance;\n•\t(i) Sign and implement the memorandum of understanding with the African Union and permit the full deployment of the 100 human rights observers provided for therein.","annex":6},{"id":"a-hrc-48-68-p0002-a6","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"2","seq":125,"section":"3. Recommandations faites en 2018","text":"For the medium and longer terms, the Commission also recommends that the Government of Burundi:\na.\tAmend the Organization Act of 8 March 2018 amending Act No. 01/03 of 24 January 2013 on the mandate, composition, organization and functioning of the National Communication Council with a view to ensuring the latter’s independence;\nb.\tRatify the International Convention for the Protection of All Persons from Enforced Disappearance;\nc.\tAmend the Code of Criminal Procedure to align its provisions with international standards, in particular the provisions on time limits for police custody and on oversight of detention, night-time and warrantless searches, the flagrante delicto procedure and the offence of “undermining the internal security of the State”, and provisions that grant de jure impunity to judges and to officers of the criminal investigation police (police judiciaire);\nd.\tPut an end to arbitrary detention and improve conditions of detention by:\n•\t(i) Implementing the Guidelines on the Conditions of Arrest, Police Custody and Pre-Trial Detention in Africa adopted by the African Commission on Human and Peoples’ Rights;\n•\t(ii) Ensuring that detention is subject to oversight measures for assessing its legality and compatibility with human rights.\ne.\tIn the absence of an independent and efficient judicial system, cooperate fully with the International Criminal Court in the investigation opened on 25 October 2017;\nf.\tUndertake an in-depth reform of the judicial system to ensure its independence, impartiality and effectiveness, including by:\n•\t(i) Implementing the Principles and Guidelines on the Right to a Fair Trial and Legal Assistance in Africa adopted by the African Commission on Human and Peoples’ Rights;\n•\t(ii) Publishing the conclusions of the national forum on the justice system held in 2013 and convening a meeting of justice-sector stakeholders and international partners to discuss follow-up action;\n•\t(iii) Increasing the budget for the justice sector and ensuring that it is managed autonomously;\n•\t(iv) Raising the pay levels of judges in the ordinary courts and increasing the resources and facilities available to them;\n•\t(v) Computerizing court registries;\n•\t(vi) Reviewing the composition of the Judicial Service Commission to ensure that the majority of its members are appointed by their peers;\n•\t(vii) Reviewing procedures for the appointment, assignment, evaluation and promotion of judges to ensure that such procedures are not dependent on the executive branch;\n•\t(viii) Ensuring strict observance of the principle that judges should have security of tenure;\n•\t(ix) Protecting and safeguarding the independence of the judiciary by prohibiting any interference in the administration of justice by government authorities, members of the ruling party or members of the defence and security forces, and imposing penalties on anyone who influences or seeks to influence the administration of justice;\n•\t(x) Developing legal aid programmes for persons belonging to the most vulnerable groups;\n•\t(xi) Strengthening victim and witness protection mechanisms and improving their effectiveness in order to restore public trust and encourage witnesses to come forward without fear for their safety.\ng.\tIn consultation with the beneficiaries, establish a reparations programme for victims of human rights violations, ensuring that material, symbolic, individual and collective reparations are made available regardless of whether or not the perpetrators are convicted;\nh.\tEstablish the State fund for victims of torture provided for by law, in conformity with general comment No. 4 on the African Charter on Human and Peoples’ Rights, adopted by the African Commission on Human and Peoples’ Rights, concerning the right to redress for victims of torture and other cruel, inhuman or degrading punishment or treatment (art. 5);\ni.\tEstablish a compensation fund for victims of arbitrary and unlawful detention;\nj.\tReform the security sector by:\n•\t(i) Ensuring that outsiders are not involved in defence or security activities;\n•\t(ii) Clearly defining the roles of the various defence and security forces, in particular the National Intelligence Service;\n•\t(iii) Suspending members of the defence and security forces who are suspected of involvement in human rights violations until the relevant investigations and judicial proceedings have concluded;\n•\t(iv) Establishing rigorous and transparent selection procedures that include vetting mechanisms;\n•\t(v) Strengthening democratic civilian control over the defence and security forces, in particular the National Intelligence Service.\nk.\tMeet its international obligations to respect, protect and fulfil economic and social rights by:\n•\t(i) Developing and implementing State budgets in such a way as to maximize the use of available resources to ensure that the human rights of the sectors impoverished by the political crisis are respected, in particular the rights to food, water and health care, and to develop indicators disaggregated by factors such as gender in order to better inform its policies;\n•\t(ii) In consultation with population groups working in the agricultural sector, including women, undertaking reforms with the aim of better protecting women’s rights and making better use of land for agriculture, and developing employment opportunities outside the agricultural sector;\n•\t(iii) Taking a rights-based approach to the settlement of land conflicts, including those involving persons who fled Burundi either before or after 2015;\n•\t(iv) Ending the inclusion of any political considerations in hiring processes for the civil service, State enterprises and public-private enterprises.","annex":6},{"id":"a-hrc-48-68-p0003-a6","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"3","seq":126,"section":"3. Recommandations faites en 2018","text":"The Commission recommends that political parties and armed opposition groups refrain from engaging in any attacks on Burundian territory and from any speech calling for violence, and that they join the effort to find a lasting solution to the political crisis.","annex":6},{"id":"a-hrc-48-68-p0004-a6","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"4","seq":127,"section":"3. Recommandations faites en 2018","text":"The Commission recommends that the African Union, in its efforts to find a lasting solution to the crisis in Burundi, give priority to respect for human rights and the rejection of impunity, as provided for in its Constitutive Act.","annex":6},{"id":"a-hrc-48-68-p0005-a6","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"5","seq":128,"section":"3. Recommandations faites en 2018","text":"The Commission recommends that the technical and financial partners of Burundi:\na.\tSuspend, or maintain the suspension of, any direct budget support to the Government until such time as priority is given to the allocation of domestic resources for the fulfilment of the Sustainable Development Goals and the economic and social rights of the population, and effective measures are taken against corruption;\nb.\tEnsure that grants and financing provided to the Government are earmarked for projects to meet the population’s needs, and ensure that such funding is managed effectively and transparently;\nc.\tRegularly evaluate the impact of financial sanctions on the people of Burundi.","annex":6},{"id":"a-hrc-48-68-p0006-a6","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"6","seq":129,"section":"3. Recommandations faites en 2018","text":"The Commission recommends that the guarantors of the Arusha Agreement, in their capacity as committed proponents of a lasting peace in Burundi, continue to seek a durable solution to the political and human rights crisis that will preserve and safeguard the achievements of the Arusha Agreement.","annex":6},{"id":"a-hrc-48-68-p0001-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"1","seq":130,"section":"1. Aux autorités burundaises","text":"De mettre immédiatement un terme aux violations graves des droits de l’homme commises par des agents de l’État et des Imbonerakure sur lesquels l’État exerce un contrôle;","annex":7},{"id":"a-hrc-48-68-p0002-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"2","seq":131,"section":"1. Aux autorités burundaises","text":"D’enquêter sur ces violations et s’assurer que les auteurs présumés soient jugés dans les meilleurs délais, dans des procédures crédibles, indépendantes et équitables, et que les victimes obtiennent une juste réparation. Dans le cas où les auteurs présumés sont des agents de l’État, les suspendre jusqu’au terme de l’enquête et de la procédure judiciaire;","annex":7},{"id":"a-hrc-48-68-p0003-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"3","seq":132,"section":"1. Aux autorités burundaises","text":"De prendre des mesures concrètes pour une amélioration rapide de la situation des droits de l’homme, notamment en:\n•\tAnnulant les mandats d’arrêt contre des dirigeants de médias, d’organisations de la société civile et de partis politiques qui n’ont pas utilisé ou prôné la violence, et permettant leur retour en toute sécurité au Burundi;\n•\tLevant la suspension et la radiation des médias et organisations de la société civile, leur permettant de reprendre leurs activités en toute indépendance, et revoyant les lois adoptées en 2017 sur les organisations non-gouvernementales burundaises et internationales;\n•\tLibérant immédiatement tous les prisonniers politiques;\n•\tS’assurant que toute personne arrêtée soit détenue dans un lieu de détention officiel et que des observateurs nationaux et internationaux soient autorisés à leur rendre visite;\n•\tVeillant à ce que les officiers de police judiciaire ne soient pas habilités à mener des perquisitions sans mandat et de nuit comme envisagé dans les projets d’amendement du Code pénal et du Code de procédure pénale;\n•\tS’assurant que des individus qui n’y sont pas légalement habilités, en particulier des Imbonerakure, ne conduisent pas des activités de maintien de l’ordre ou n’y prennent pas part, y compris dans des lieux de détention, et qu’ils ne portent pas des uniformes militaires ou de police ou ne soient pas en possession d’armes;\n•\tPoursuivant les auteurs de discours haineux ou appelant à la violence;\n•\tMettant fin aux menaces, intimidations et actes d’extorsion par des agents de l’État et des Imbonerakure;\n•\tPermettant aux victimes de violences sexuelles et de torture d’avoir accès à des services médicaux et psychosociaux.","annex":7},{"id":"a-hrc-48-68-p0004-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"4","seq":133,"section":"1. Aux autorités burundaises","text":"D’engager une réforme en profondeur du système judiciaire, notamment en:\n•\tPubliant les conclusions des états généraux de la justice qui se sont tenus en 2013 à Gitega;\n•\tRevoyant la composition du Conseil national de la magistrature afin que ses membres soient en majorité désignés par leurs pairs;\n•\tRevoyant les procédures de nomination, d’affectation, de notation et d’avancement des magistrats afin qu’elles ne dépendent pas du pouvoir exécutif;\n•\tVeillant au respect strict du principe d’inamovibilité des magistrats du siège;\n•\tProtégeant et garantissant l’indépendance du système judiciaire en interdisant toute ingérence dans le fonctionnement de la justice par des autorités gouvernementales, des membres du parti au pouvoir ou des membres des corps de défense et de sécurité, et en prenant des sanctions contre ceux qui influencent, ou cherchent à influencer, le fonctionnement de la justice;\n•\tDéveloppant des programmes d’aide juridictionnelle pour les plus vulnérables;\n•\tRenforçant les mécanismes de protection de victimes et de témoins, ainsi que leur efficacité, pour restaurer la confiance de la population et encourager les témoins à s’exprimer sans crainte pour leur sécurité.","annex":7},{"id":"a-hrc-48-68-p0005-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"5","seq":134,"section":"1. Aux autorités burundaises","text":"De s’assurer que les membres des corps de défense et de sécurité respectent les droits de l’homme en toutes circonstances et servent les intérêts de la population dans son ensemble et pas uniquement ceux du parti au pouvoir, notamment en:\n•\tRenforçant le contrôle civil des corps de défense et de sécurité et l’indépendance des organes chargés de ce contrôle créés par la Constitution, en particulier le Parlement, la Commission nationale indépendante des droits de l’homme et l’Ombudsman;\n•\tRemédiant à la carence constitutionnelle de contrôle civil du SNR;\n•\tPrenant des mesures pour vérifier les antécédents, notamment en matière de droits de l’homme, des agents des corps de défense et de sécurité et intégrant ces mesures à une refonte des procédures de recrutement et d’avancement de ces agents.","annex":7},{"id":"a-hrc-48-68-p0006-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"6","seq":135,"section":"1. Aux autorités burundaises","text":"De revenir sur sa décision de se retirer du Statut de Rome et coopérer pleinement avec la CPI dans la procédure d’examen préliminaire en cours et, si une enquête est ouverte, poursuivre cette coopération et assurer la protection des victimes et témoins;","annex":7},{"id":"a-hrc-48-68-p0007-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"7","seq":136,"section":"1. Aux autorités burundaises","text":"D’autoriser le HCDH à reprendre ses activités de documentation des violations des droits de l’homme au Burundi, suspendues depuis octobre 2016;","annex":7},{"id":"a-hrc-48-68-p0008-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"8","seq":137,"section":"1. Aux autorités burundaises","text":"De signer et mettre en œuvre le mémorandum d’entente avec l’Union africaine et permettre le déploiement complet des 100 observateurs des droits de l’homme et des 100 experts militaires, décidé en 2016;","annex":7},{"id":"a-hrc-48-68-p0009-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"9","seq":138,"section":"1. Aux autorités burundaises","text":"De coopérer avec les mécanismes des droits de l’homme des Nations Unies en accueillant à nouveau des missions des procédures spéciales et en mettant en œuvre les recommandations récentes des organes de traité;","annex":7},{"id":"a-hrc-48-68-p0010-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"10","seq":139,"section":"1. Aux autorités burundaises","text":"De s’engager activement dans la voie d’une résolution durable de la crise politique, notamment dans le cadre d’initiatives de dialogue engagées au niveau international.","annex":7},{"id":"a-hrc-48-68-p0011-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"11","seq":140,"section":"2. Aux partis politiques et groupes armés d’opposition","text":"De mettre immédiatement un terme aux atteintes aux droits de l’homme et aux actes de violence commis par leurs membres;","annex":7},{"id":"a-hrc-48-68-p0012-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"12","seq":141,"section":"2. Aux partis politiques et groupes armés d’opposition","text":"De s’abstenir de tout discours appelant à la violence et s’engager dans la recherche d’une solution durable à la crise politique au Burundi.","annex":7},{"id":"a-hrc-48-68-p0013-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"13","seq":142,"section":"3. Au Conseil des droits de l’homme","text":"De prolonger le mandat de la Commission pour une durée d’un an aux fins d’approfondir et de poursuivre ses enquêtes en raison de la persistance des violations graves des droits de l’homme et des atteintes à ceux-ci et en l’absence d’autres mécanismes spécifiques en mesure de mener des enquêtes indépendantes et approfondies sur la situation des droits de l’homme au Burundi;","annex":7},{"id":"a-hrc-48-68-p0014-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"14","seq":143,"section":"3. Au Conseil des droits de l’homme","text":"De demander au Haut-Commissaire des Nations Unies aux droits de l’homme de faire un rapport sur l’évolution de sa coopération avec le Gouvernement du Burundi aux prochaines sessions du Conseil.","annex":7},{"id":"a-hrc-48-68-p0015-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"15","seq":144,"section":"4. À la Cour pénale internationale","text":"D’ouvrir dans les plus brefs délais une enquête sur les crimes commis au Burundi au vu des conclusions contenues dans le présent rapport et d’autres informations à sa disposition.","annex":7},{"id":"a-hrc-48-68-p0016-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"16","seq":145,"section":"5. Au Conseil de sécurité des Nations Unies","text":"De prendre dûment compte des présentes conclusions de la Commission et de la persistance de violations graves des droits de l’homme dans toute discussion sur le Burundi et, dans ce contexte, veiller à la mise en œuvre effective de la résolution 2303 (2016);","annex":7},{"id":"a-hrc-48-68-p0017-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"17","seq":146,"section":"5. Au Conseil de sécurité des Nations Unies","text":"De saisir la CPI de tout crime de droit international qui serait commis au Burundi après le 27 octobre 2017;","annex":7},{"id":"a-hrc-48-68-p0018-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"18","seq":147,"section":"5. Au Conseil de sécurité des Nations Unies","text":"De prendre des sanctions individuelles contre les principaux auteurs présumés de violations graves des droits de l’homme et de crimes de droit international au Burundi.","annex":7},{"id":"a-hrc-48-68-p0019-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"19","seq":148,"section":"6. Au Secrétaire-général des Nations Unies","text":"De veiller à ce que le respect des droits de l’homme et la restauration de l’État de droit soient parmi les priorités de son Envoyé spécial sur le Burundi;","annex":7},{"id":"a-hrc-48-68-p0020-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"20","seq":149,"section":"6. Au Secrétaire-général des Nations Unies","text":"De veiller à ce qu’aucun auteur présumé de violations des droits de l’homme ou de crimes de droit international au Burundi ne soit recruté dans des missions de maintien de la paix des Nations Unies.","annex":7},{"id":"a-hrc-48-68-p0021-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"21","seq":150,"section":"7. Aux États membres des Nations Unies","text":"D’accorder prima facie le statut de réfugié aux demandeurs d’asile burundais et veiller au respect strict du principe de non-refoulement, ainsi qu’à la protection des réfugiés;","annex":7},{"id":"a-hrc-48-68-p0022-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"22","seq":151,"section":"7. Aux États membres des Nations Unies","text":"De poursuivre, au titre de la compétence universelle, les auteurs présumés de crimes de droit international commis au Burundi se trouvant sur leur territoire;","annex":7},{"id":"a-hrc-48-68-p0023-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"23","seq":152,"section":"7. Aux États membres des Nations Unies","text":"De maintenir, en l’absence de toute amélioration de la situation des droits de l’homme dans le pays, les sanctions individuelles et la suspension de l’aide directe au Gouvernement burundais;","annex":7},{"id":"a-hrc-48-68-p0024-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"24","seq":153,"section":"7. Aux États membres des Nations Unies","text":"De fournir une assistance technique aux autorités burundaises, dans la mesure où ces dernières font preuve d’une véritable volonté politique, afin de mener des enquêtes crédibles et indépendantes, notamment en matière d’autopsie, d’exhumation et d’identification des corps;","annex":7},{"id":"a-hrc-48-68-p0025-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"25","seq":154,"section":"7. Aux États membres des Nations Unies","text":"De soutenir la mise en place de services médicaux et psychosociaux spécialisés, notamment pour les victimes de torture et de violences sexuelles;","annex":7},{"id":"a-hrc-48-68-p0026-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"26","seq":155,"section":"7. Aux États membres des Nations Unies","text":"De soutenir les autorités burundaises, si celles-ci font preuve d’une véritable volonté politique, dans tout effort de réforme du système judiciaire et du secteur de sécurité qu’elles voudront engager aux fins d’améliorer la situation des droits de l’homme.","annex":7},{"id":"a-hrc-48-68-p0027-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"27","seq":156,"section":"8. À l’Union africaine","text":"De reprendre l’initiative dans la recherche d’une solution durable à la crise au Burundi fondée sur le respect des droits de l’homme et le rejet de l’impunité, tels que prévus par son Acte constitutif, et s’y engager activement;","annex":7},{"id":"a-hrc-48-68-p0028-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"28","seq":157,"section":"8. À l’Union africaine","text":"De veiller à ce qu’aucun agent de l’État burundais accusé de violations des droits de l’homme ou de crimes de droit international ne soit recruté dans des missions de maintien de la paix de l’Union africaine;","annex":7},{"id":"a-hrc-48-68-p0029-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"29","seq":158,"section":"8. À l’Union africaine","text":"De s’assurer que l’équipe complète de ses observateurs des droits de l’homme et experts militaires soit rapidement déployée au Burundi;","annex":7},{"id":"a-hrc-48-68-p0030-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"30","seq":159,"section":"8. À l’Union africaine","text":"D’envisager, en cas de persistance de la situation actuelle au Burundi, l’application de l’article 4 (h) de son Acte constitutif, autorisant l’Union africaine à intervenir dans un État membre dans certaines circonstances, notamment en cas de crimes contre l’humanité.","annex":7},{"id":"a-hrc-48-68-p0031-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"31","seq":160,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"De s’assurer que l’amélioration rapide de la situation des droits de l’homme soit une priorité dans ses efforts de médiation.\n10.\tAux garants de l’Accords d’Arusha de 2000, en leur qualité d’acteurs engagés en faveur d’une paix durable au Burundi","annex":7},{"id":"a-hrc-48-68-p0032-a7","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"32","seq":161,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"De se réunir le plus rapidement possible en vue de trouver une solution pérenne à la crise politique et des droits de l’homme au Burundi.\nVersion anglaise\n1.\tThe Burundian authorities should:","annex":7},{"id":"a-hrc-48-68-p0001-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"1","seq":162,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Put an immediate end to the gross human rights violations being committed by agents of the State and Imbonerakure over which the State exercises control;","annex":8},{"id":"a-hrc-48-68-p0002-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"2","seq":163,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Investigate these violations, ensure that the alleged perpetrators are prosecuted promptly in accordance with credible, independent and fair procedures, and that the victims obtain just reparation, and, where the alleged perpetrators are agents of the State, suspend them from their duties pending the completion of the investigation and the judicial proceedings;","annex":8},{"id":"a-hrc-48-68-p0003-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"3","seq":164,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Take practical measures to bring about a rapid improvement of the human rights situation, in particular by:\n•\tWithdrawing the warrants for the arrest of heads of media outlets, civil society organizations and political parties who have neither used nor advocated violence, and permitting their safe return to Burundi;\n•\tLifting the suspension and reversing the revocation of the licences of media and civil society organizations, permitting them to resume their activities with complete independence and reviewing the laws adopted in 2017 concerning non-profit organizations and foreign non-governmental organizations;\n•\tImmediately releasing all political prisoners;\n•\tEnsuring that every person arrested is detained in an official place of detention and that national and international observers are allowed to visit them;\n•\tEnsure that criminal investigation officers (officiers de police judiciaire) are not authorized to conduct searches without a warrant, including at night, as envisaged in the draft amendments to the Criminal Code and the Code of Criminal Procedure;\n•\tEnsuring that individuals lacking legal authorization, particularly the Imbonerakure, do not perform or participate in law enforcement activities, including in places of detention, and do not wear military or police uniforms or possess weapons;\n•\tProsecuting individuals who incite hatred or violence;\n•\tPutting an end to threats, intimidation and acts of extortion by State officials and the Imbonerakure;\n•\tGiving victims of sexual violence and torture access to medical and psychosocial services.","annex":8},{"id":"a-hrc-48-68-p0004-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"4","seq":165,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Undertake a thorough reform of the judiciary, in particular by:\n•\tPublishing the conclusions of the General Convention on the Judiciary (États généraux de la justice) held in Gitega in 2013;\n•\tReviewing the composition of the Superior Council of Magistrates (Conseil supérieur de la magistrature) so that the majority of its members are designated by their peers;\n•\tReviewing the nomination, posting, evaluation and promotion procedures of magistrates so that they do not depend of the executive;\n•\tEnsuring the respect of the principle of security of tenure for judges;\n•\tProtecting and guaranteeing the independence of the judiciary by prohibiting all interference in their functions by governmental authorities, members of the ruling party or security and defence forces, and imposing sanctions on those who influence, or seek to influence, the functioning of the judiciary;\n•\tDeveloping legal aid programmes for the most vulnerable;\n•\tReinforcing the protection mechanisms for victims and witnesses, as well as their efficiency, in order to restore people’s confidence in the system and to encourage witnesses to testify without fear for their security.","annex":8},{"id":"a-hrc-48-68-p0005-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"5","seq":166,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Ensure that members of the defence and security forces respect human rights in all circumstances and serve the interests of the population as a whole, not solely those of the ruling party, in particular by:\n•\tReinforcing civilian control over the military and the independence of the competent organs created by the Constitution to supervise this control, in particular the Parliament, the National Human Rights Commission and the Ombudsman;\n•\tImplementing civilian control over the National Intelligence Service (Service national de renseignement) in line with the Constitution;\n•\tConducting background checks, in particular on human rights, on defense and security forces and incorporating these measures into reforms of the recruitment and career progression of these agents.","annex":8},{"id":"a-hrc-48-68-p0006-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"6","seq":167,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Reconsider their decision to withdraw from the Rome Statute, cooperate fully with the International Criminal Court in the ongoing preliminary examination and, if an investigation is initiated, continue that cooperation, inter alia by ensuring the protection of victims and witnesses;","annex":8},{"id":"a-hrc-48-68-p0007-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"7","seq":168,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Authorize the Office of the United Nations High Commissioner for Human Rights to resume its documentation of human rights violations in Burundi, which has been suspended since October 2016;","annex":8},{"id":"a-hrc-48-68-p0008-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"8","seq":169,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Sign and implement the memorandum of understanding with the African Union and permit the full deployment of 100 human rights observers and 100 military experts that was decided upon in 2016;","annex":8},{"id":"a-hrc-48-68-p0009-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"9","seq":170,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Cooperate with United Nations human rights mechanisms by once again receiving special procedures missions and implementing the recent recommendations of treaty bodies;","annex":8},{"id":"a-hrc-48-68-p0010-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"10","seq":171,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Actively seek a lasting solution to the political crisis, inter alia through international initiatives to promote dialogue.\n2.\tPolitical parties and armed opposition groups should:","annex":8},{"id":"a-hrc-48-68-p0011-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"11","seq":172,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Put an immediate end to human rights abuses and acts of violence committed by their members;","annex":8},{"id":"a-hrc-48-68-p0012-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"12","seq":173,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Refrain from any incitement of violence and participate in the quest for a lasting solution to the political crisis in Burundi.\n3.\tThe Human Rights Council should:","annex":8},{"id":"a-hrc-48-68-p0013-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"13","seq":174,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Extend the Commission’s mandate for a period of one year to enable it to conduct further and more thorough investigations in view of the persistence of gross human rights violations and abuses and the absence of other specific mechanisms capable of undertaking independent and thorough investigations into the human rights situation in Burundi;","annex":8},{"id":"a-hrc-48-68-p0014-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"14","seq":175,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Request the Office of the United Nations High Commissioner for Human Rights to report, at the forthcoming sessions of the Council, on the development of its cooperation with the Burundian Government.\n4.\tThe International Criminal Court should:","annex":8},{"id":"a-hrc-48-68-p0015-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"15","seq":176,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Initiate, as soon as possible, an investigation into the crimes committed in Burundi in light of the conclusions contained in the present report and other information at its disposal.\n5.\tThe United Nations Security Council should:","annex":8},{"id":"a-hrc-48-68-p0016-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"16","seq":177,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Take due account of the Commission’s conclusions, as well as persistence of gross violations of human rights, in any discussion on Burundi and, in this context, ensure the effective implementation of resolution 2303 (2016);","annex":8},{"id":"a-hrc-48-68-p0017-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"17","seq":178,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Refer to the International Criminal Court any international crime that might be committed in Burundi after 27 October 2017;","annex":8},{"id":"a-hrc-48-68-p0018-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"18","seq":179,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Impose individual sanctions against the principal alleged perpetrators of gross human rights violations and international crimes in Burundi.\n6.\tThe Secretary-General of the United Nations should:","annex":8},{"id":"a-hrc-48-68-p0019-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"19","seq":180,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Ensure that respect for human rights and restoration of the rule of law are among the priorities of his Special Envoy for Burundi;","annex":8},{"id":"a-hrc-48-68-p0020-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"20","seq":181,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Ensure that no alleged perpetrator of human rights violations or international crimes in Burundi is recruited for United Nations peacekeeping missions.\n7.\tThe States Members of the United Nations should:","annex":8},{"id":"a-hrc-48-68-p0021-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"21","seq":182,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Grant prima facie refugee status to Burundian asylum seekers and ensure strict re64ect for the principle of non-refoulement and refugee protection;","annex":8},{"id":"a-hrc-48-68-p0022-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"22","seq":183,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Prosecute, in accordance with the principle of universal jurisdiction, alleged perpetrators of international crimes committed in Burundi who are found to be in their territory;","annex":8},{"id":"a-hrc-48-68-p0023-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"23","seq":184,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Maintain, in the absence of any improvement in the human rights situation in Burundi, the individual sanctions and the suspension of direct aid to the Government;","annex":8},{"id":"a-hrc-48-68-p0024-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"24","seq":185,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Provide technical assistance inter alia in respect to autopsies, exhumations and identification of bodies, to enable the Burundian to conduct credible and independent investigations;","annex":8},{"id":"a-hrc-48-68-p0025-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"25","seq":186,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Support the establishment of specialized medical and psychosocial services, especially for victims of torture and sexual violence;","annex":8},{"id":"a-hrc-48-68-p0026-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"26","seq":187,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Support Burundian authorities in any judicial and security sector reform endeavors that they might wish to undertake in order to improve the human rights situation.\n8.\tThe African Union should:","annex":8},{"id":"a-hrc-48-68-p0027-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"27","seq":188,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Retake the lead in seeking a lasting solution to the crisis in Burundi based on respect for human rights and rejection of impunity, as provided for in its Constitutive Act, and play an active role in that process;","annex":8},{"id":"a-hrc-48-68-p0028-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"28","seq":189,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Ensure that no agent of the Burundian State who is accused of human rights violations or international crimes is recruited for African Union peacekeeping missions;","annex":8},{"id":"a-hrc-48-68-p0029-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"29","seq":190,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Ensure that the full complement of African Union human rights observers and military experts is deployed rapidly in Burundi;","annex":8},{"id":"a-hrc-48-68-p0030-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"30","seq":191,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Consider, in the event that the current situation in Burundi persists, the application of Article 4 (h) of the Constitutive Act of the African Union, under which it is authorized to intervene in a member State in certain circumstances, particularly in the event of crimes against humanity.\n9.\tThe East African Community should:","annex":8},{"id":"a-hrc-48-68-p0031-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"31","seq":192,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Ensure that a rapid improvement of the human rights situation is a priority in its mediation efforts.\n10.\tThe guarantors of the 2000 Arusha Agreement, in their capacity as committed proponents of a lasting peace in Burundi, should:","annex":8},{"id":"a-hrc-48-68-p0032-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":"32","seq":193,"section":"9. À la Communauté des États d’Afrique de l’Est","text":"Meet with a view to finding a lasting solution to the political and human rights crisis in Burundi.","annex":8},{"id":"a-hrc-48-68-u0194-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":null,"seq":194,"section":"IV. Indicateurs des facteurs de risque communs identifiés dans le Cadre d’analyse des atrocités criminelles (A/70/741–S/2016/71)","text":"Version française\nFacteur de risque 1. Situations de conflit armé ou autres formes d’instabilité\na.\tConflit armé international ou non international;\nb.\tCrise sécuritaire provoquée, entre autres, par la dénonciation d’accords de paix, un conflit armé dans les pays voisins, des menaces d’interventions étrangères ou des actes de terrorisme;\nc.\tCrise ou urgence humanitaire, pouvant être causée notamment par une catastrophe naturelle ou une épidémie;\nd.\tInstabilité politique provoquée par un changement de régime ou un transfert de pouvoir soudain ou irrégulier;\ne.\tInstabilité politique provoquée par des luttes de pouvoir ou la montée en puissance de mouvements d’opposition nationalistes, armés ou radicaux;\nf.\tTension politique provoquée par des régimes autocratiques ou une lourde répression politique;\ng.\tInstabilité économique provoquée par une pénurie de ressources ou des différends concernant leur utilisation ou leur exploitation;\nh.\tInstabilité économique provoquée par une crise grave de l’économie nationale;\ni.\tInstabilité économique provoquée par la misère, un chômage de masse ou de profondes inégalités horizontales;\nj.\tInstabilité sociale provoquée par une résistance à l’autorité de l’État ou à ses politiques ou par des protestations de masse contre celles-ci;\nk.\tInstabilité sociale provoquée par l’exclusion ou des tensions fondées sur des questions d’identité, leur perception ou leurs formes extrémistes.\nFacteur de risque 2. Antécédents de violations graves du droit international des droits de l’homme et du droit international humanitaire\na.\tRestrictions ou violations graves, passées ou actuelles, des droits consacrés par le droit international des droits de l’homme et le droit international humanitaire, surtout si elles sont caractérisées par un comportement systématique observé préalablement et si elles visent des groupes, populations ou personnes protégés;\nb.\tActes de génocide, crimes contre l’humanité, crimes de guerre ou incitation à les commettre, survenus dans le passé;\nc.\tPolitique ou pratique d’impunité ou de tolérance à l’égard de violations graves du droit international des droits de l’homme et du droit international humanitaire, d’atrocités criminelles ou de l’incitation à les commettre;\nd.\tInaction, réticence à utiliser ou refus d’utiliser tous les moyens possibles pour faire cesser des violations graves prévues, prévisibles ou persistantes du droit international des droits de l’homme et du droit international humanitaire ou des atrocités criminelles probables, ou incitation à les commettre;\ne.\tMaintien d’une aide à des groupes accusés de participer à des violations graves du droit international des droits de l’homme et du droit international humanitaire, notamment des atrocités criminelles, ou non-condamnation de leurs actes;\nf.\tJustification de violations graves du droit international des droits de l’homme et du droit international humanitaire ou d’atrocités criminelles, rapports partiaux les concernant ou refus de les reconnaître;\ng.\tAbsence de processus de réconciliation ou de justice transitionnelle après un conflit, ou politisation de ce processus;\nh.\tMéfiance généralisée envers les institutions de l’État ou entre différents groupes en raison de l’impunité.\nFacteur de risque 3. Faiblesse des structures de l’État\na.\tCadre juridique national n’offrant pas une protection suffisante et efficace, notamment par la ratification et l’incorporation dans le droit interne des instruments relatifs au droit international des droits de l’homme et au droit international humanitaire;\nb.\tManque de ressources au sein des institutions nationales, en particulier les institutions judiciaires et celles chargées de l’application des lois et de la protection des droits de l’homme, et manque de représentation adéquate ou de formation;\nc.\tAbsence de justice indépendante et impartiale;\nd.\tAbsence de contrôle civil efficace des forces de sécurité;\ne.\tNiveaux élevés de corruption ou mauvaise gouvernance;\nf.\tAbsence ou insuffisance de mécanismes externes ou internes de contrôle et de responsabilité, notamment que les victimes peuvent saisir pour demander réparation;\ng.\tManque de sensibilisation et de formation des forces militaires, des forces irrégulières, des groupes armés non étatiques et des autres acteurs concernés au droit international des droits de l’homme et au droit international humanitaire;\nh.\tManque de capacité de vérifier que les moyens et méthodes de guerre sont conformes aux normes du droit international humanitaire;\ni.\tManque de moyens pour la réforme ou le renforcement des institutions, notamment par une aide régionale ou internationale;\nj.\tRessources insuffisantes pour mettre en œuvre des mesures globales de protection des populations.\nFacteur de risque 4. Motivations ou incitations\na.\tMotivations politiques, en particulier celles visant l’acquisition ou la consolidation du pouvoir;\nb.\tIntérêts économiques, notamment ceux fondés sur la préservation et le bien-être des élites ou de groupes d’identité, ou sur le contrôle de la répartition des ressources;\nc.\tIntérêts stratégiques ou militaires, notamment ceux fondés sur la protection ou la saisie de territoires et de ressources;\nd.\tAutres intérêts, notamment ceux visant à rendre une zone homogène dans son identité;\ne.\tMenaces réelles ou perçues comme telles de groupes, populations ou personnes protégés contre les intérêts ou les objectifs des auteurs d’actes criminels, notamment l’impression de déloyauté envers une cause;\nf.\tAppartenance ou adhésion réelle ou perçue comme telle de groupes, populations ou personnes protégés à des groupes d’opposition armés;\ng.\tIdéologies fondées sur la suprématie d’une certaine identité ou sur des versions extrémistes de l’identité;\nh.\tPolitisation de griefs, de tensions ou de cas d’impunité issus du passé;\ni.\tTraumatisme social provoqué par des situations de violence passées auxquelles il n’a pas été donné de suite satisfaisante et qui ont engendré des sentiments de perte, de déplacement et d’injustice et un désir possible de revanche.\nFacteur de risque 5. Capacité de commettre des atrocités criminelles\na.\tDisponibilité de personnel et d’armes et munitions ou de moyens financiers publics ou privés permettant de les acquérir;\nb.\tCapacité de transporter et déployer du personnel et de transporter et distribuer des armes et des munitions;\nc.\tCapacité d’encourager ou de recruter de nombreux partisans au sein de populations ou de groupes et disponibilité de moyens pour les mobiliser;\nd.\tSolide culture d’obéissance à l’autorité et de conformité au groupe;\ne.\tPrésence d’autres forces armées ou de groupes armés non étatiques ou existence de liens avec de tels forces ou groupes;\nf.\tPrésence d’acteurs commerciaux ou d’entreprises pouvant jouer un rôle déterminant en fournissant des biens, des services ou d’autres formes d’appui pratique ou technique contribuant à soutenir les auteurs;\ng.\tAppui financier, politique ou autre d’acteurs nationaux influents ou riches;\nh.\tAppui armé, financier, logistique ou autre, notamment sous la forme d’entraînement, fourni par des acteurs extérieurs, notamment des États, des organisations internationales ou régionales ou des entreprises privées.\nFacteur de risque 6. Absence de facteurs atténuants\na.\tInsuffisance ou absence de processus d’autonomisation, de ressources, d’alliés ou d’autres éléments qui pourraient contribuer à la capacité des groupes, populations ou personnes protégés de se protéger eux-mêmes;\nb.\tAbsence de société civile nationale solide, organisée et représentative et de médias nationaux libres, diversifiés et indépendants;\nc.\tAbsence d’intérêt et d’attention des acteurs de la société civile internationale ou d’accès aux médias internationaux;\nd.\tAbsence ou présence limitée des Nations Unies, d’organisations non gouvernementales internationales ou d’autres acteurs internationaux ou régionaux dans le pays ayant accès aux populations;\ne.\tAbsence d’adhésion ou de participation effective de l’État à des organisations internationales ou régionales établissant des obligations afférentes au statut de membre;\nf.\tManque de contact, d’ouverture ou de relations politiques ou économiques avec d’autres États ou organisations;\ng.\tCoopération limitée de l’État avec les mécanismes internationaux et régionaux des droits de l’homme;\nh.\tManque de volonté des parties à un conflit d’engager un dialogue, de faire des concessions et de solliciter l’appui de la communauté internationale, ou absence d’incitations à le faire;\ni.\tRéticence ou échec des États Membres de l’Organisation des Nations Unies ou des organisations internationales ou régionales à aider un État à assumer sa responsabilité de protéger ses populations contre les atrocités criminelles, ou à agir lorsque l’État n’assume manifestement pas cette responsabilité, ou indifférence à cet égard;\nj.\tManque de soutien des États voisins pour ce qui est de protéger les populations à risque en quête de refuge: fermeture des frontières, rapatriement forcé ou restrictions en matière d’aide;\nk.\tAbsence de mécanisme d’alerte rapide permettant de prévenir des atrocités criminelles.\nFacteur de risque 7. Circonstances propices ou action préparatoire restreignant les droits fondamentaux\na.\tImposition de l’état d’urgence ou de mesures de sécurité extraordinaires restreignant les droits fondamentaux;\nb.\tSuspension d’institutions vitales de l’État ou ingérence dans ces institutions, ou mesures provoquant des modifications de leur composition ou l’équilibre des pouvoirs, en particulier s’il en résulte l’exclusion ou une sous-représentation de groupes protégés;\nc.\tRenforcement de l’appareil de sécurité, réorganisation ou mobilisation de celui-ci contre des groupes, populations ou personnes protégés;\nd.\tAcquisition de grandes quantités d’armes et de munitions ou d’autres objets pouvant être utilisés pour causer des dommages;\ne.\tCréation de milices ou de groupes paramilitaires, ou intensification de l’appui à de tels milices ou groupes;\nf.\tImposition d’un contrôle strict sur l’utilisation des moyens de communication ou interdiction d’y avoir accès;\ng.\tExpulsion ou refus d’autoriser la présence d’organisations non gouvernementales, d’organisations internationales, de médias ou d’autres acteurs pertinents ou imposition de lourdes restrictions à leurs services et déplacements;\nh.\tAugmentation du nombre de violations du droit à la vie, de l’intégrité physique, de la liberté ou de la sécurité de membres de groupes, populations ou personnes protégés, ou adoption récente de mesures ou de lois qui leur portent atteinte ou constituent une discrimination délibérée envers eux;\ni.\tAugmentation du nombre d’actes de violence graves contre les femmes et les enfants ou création de conditions facilitant la commission d’agressions sexuelles contre eux, notamment comme instrument de terreur;\nj.\tImposition de conditions de vie délétères ou déportation, appréhension, regroupement, ségrégation, évacuation, déplacement ou transfert forcés de groupes, populations ou individus protégés vers des camps, des zones rurales, des ghettos ou d’autres lieux désignés;\nk.\tDestruction ou pillage de biens ou d’installations essentiels à des groupes, populations ou personnes protégés, ou de biens liés à l’identité culturelle et religieuse;\nl.\tMarquage de personnes ou de leurs biens au motif de leur appartenance à un groupe;\nm.\tPolitisation accrue de l’identité, d’événements du passé ou de motifs de se livrer à la violence;\nn.\tAugmentation du nombre de déclarations provocatrices, de campagnes de propagande ou d’incitations à la haine visant des groupes, populations ou personnes protégés.\nFacteur de risque 8. Facteurs déclencheurs\na.\tDéploiement soudain de forces de sécurité ou déclenchement d’hostilités armées;\nb.\tDébordement de conflits armés ou graves tensions dans les pays voisins;\nc.\tMesures prises par la communauté internationale, perçues par un État comme menaçant sa souveraineté;\nd.\tChangements de régime, transferts de pouvoir ou modifications du pouvoir politique des groupes, survenant soudainement ou irrégulièrement;\ne.\tAtteintes à la vie, à l’intégrité physique, à la liberté ou à la sécurité de dirigeants, de personnalités éminentes ou de membres de groupes opposés; autres actes de violence graves, notamment attentats terroristes;\nf.\tManifestations religieuses ou actes réels ou perçus comme tels d’intolérance religieuse ou d’irrespect, notamment en dehors des frontières nationales;\ng.\tActes d’incitation ou propagande haineuse visant des groupes ou des personnes particulières;\nh.\tRecensement, élections, activités essentielles liées à ces processus ou mesures qui les déstabilisent;\ni.\tChangements soudains affectant l’économie ou la population active, résultant notamment de crises financières, de catastrophes naturelles ou d’épidémies;\nj.\tDécouverte de ressources naturelles ou lancement de projets d’exploitation ayant de graves incidences sur les moyens de subsistance et la viabilité de groupes ou de populations civiles;\nk.\tCommémoration de crimes du passé ou d’épisodes traumatiques ou historiques pouvant exacerber les tensions entre groupes, notamment la glorification d’auteurs d’atrocités;\nl.\tActes liés aux processus d’établissement des responsabilités, en particulier s’ils sont perçus comme injustes.\nVersion anglaise\nRisk factor 1. Situations of armed conflict or other forms of instability\na.\tInternational or non-international armed conflict;\nb.\tSecurity crisis caused by, among other factors, defection from peace agreements, armed conflict in neighboring countries, threats of external interventions or acts of terrorism;\nc.\tHumanitarian crisis or emergency, including those caused by natural disasters or epidemics;\nd.\tPolitical instability caused by abrupt or irregular regime change or transfer of power;\ne.\tPolitical instability caused by disputes over power or growing nationalist, armed or radical opposition movements;\nf.\tPolitical tension caused by autocratic regimes or severe political repression;\ng.\tEconomic instability caused by scarcity of resources or disputes over their use or exploitation;\nh.\tEconomic instability caused by severe crisis in the national economy;\ni.\tEconomic instability caused by acute poverty, mass unemployment or deep horizontal inequalities;\nj.\tSocial instability caused by resistance to, or mass protests against, State authority or policies;\nk.\tSocial instability caused by exclusion or tensions based on identity issues, their perception or extremist forms.\nRisk factor 2. Record of serious violations of international human rights and humanitarian law\na.\tPast or present serious restrictions to or violations of international human rights and humanitarian law, particularly if assuming an early pattern of conduct and if targeting protected groups, populations or individuals;\nb.\tPast acts of genocide, crimes against humanity, war crimes or their incitement;\nc.\tPolicy or practice of impunity for or tolerance of serious violations of international human rights and humanitarian law, of atrocity crimes, or of their incitement;\nd.\tInaction, reluctance or refusal to use all possible means to stop planned, predictable or ongoing serious violations of international human rights and humanitarian law or likely atrocity crimes, or their incitement;\ne.\tContinuation of support to groups accused of involvement in serious violations of international human rights and humanitarian law, including atrocity crimes, or failure to condemn their actions;\nf.\tJustification, biased accounts or denial of serious violations of international human rights and humanitarian law or atrocity crimes;\ng.\tPoliticization or absence of reconciliation or transitional justice processes following conflict;\nh.\tWidespread.\nRisk factor 3. Weakness of State structures\na.\tNational legal framework that does not offer ample and effective protection, including through ratification and domestication of relevant international human rights and humanitarian law treaties;\nb.\tNational institutions, particularly judicial, law enforcement and human rights institutions that lack sufficient resources, adequate representation or training;\nc.\tLack of an independent and impartial judiciary;\nd.\tLack of effective civilian control of security forces;\ne.\tHigh levels of corruption or poor governance;\nf.\tAbsence or inadequate external or internal mechanisms of oversight and accountability, including those where victims can seek recourse for their claims;\ng.\tLack of awareness of and training on international human rights and humanitarian law to military forces, irregular forces and non-State armed groups, or other relevant actors;\nh.\tLack of capacity to ensure that means and methods of warfare comply with international humanitarian law standards;\ni.\tLack of resources for reform or institution-building, including through regional or international support;\nj.\tInsufficient resources to implement overall measures aimed at protecting populations.\nRisk factor 4. Motives or incentives\na.\tPolitical motives, particularly those aimed at the attainment or consolidation of power;\nb.\tEconomic interests, including those based on the safeguard and well-being of elites or identity groups, or control over the distribution of resources;\nc.\tStrategic or military interests, including those based on protection or seizure of territory and resources;\nd.\tOther interests, including those aimed at rendering an area homogeneous in its identity;\ne.\tReal or perceived threats posed by protected groups, populations or individuals against interests or objectives of perpetrators, including perceptions of disloyalty to a cause;\nf.\tReal or perceived membership of or support for armed opposition groups by protected groups, populations or individuals;\ng.\tIdeologies based on the supremacy of a certain identity or on extremist versions of identity;\nh.\tPoliticization of past grievances, tensions or impunity;\ni.\tSocial trauma caused by past incidents of violence not adequately addressed and that produced feelings of loss, displacement, injustice and a possible desire for revenge.\nRisk factor 5. Capacity to commit atrocity crimes\na.\tAvailability of personnel and of arms and ammunition, or of the financial resources, public or private, for their procurement;\nb.\tCapacity to transport and deploy personnel and to transport and distribute arms and ammunition;\nc.\tCapacity to encourage or recruit large numbers of supporters from populations or groups, and availability of the means to mobilize them;\nd.\tStrong culture of obedience to authority and group conformity;\ne.\tPresence of or links with other armed forces or with non-State armed groups;\nf.\tPresence of commercial actors or companies that can serve as enablers by providing goods, services, or other forms of practical or technical support that help to sustain perpetrators;\ng.\tFinancial, political or other support of influential or wealthy national actors;\nh.\tArmed, financial, logistic, training or other support of external actors, including States, international or regional organizations, private companies, or others.\nRisk factor 6. Absence of mitigating factors\na.\tLimited or lack of empowerment processes, resources, allies or other elements that could contribute to the ability of protected groups, populations or individuals to protect themselves;\nb.\tLack of a strong, organized and representative national civil society and of a free, diverse and independent national media;\nc.\tLack of interest and focus of international civil society actors or of access to international media;\nd.\tLack of, or limited presence of, the United Nations, international non-governmental organizations or other international or regional actors in the country and with access to populations;\ne.\tLack of membership and effective participation of the State in international or regional organizations that establish mandatory membership obligations;\nf.\tLack of exposure, openness or establishment of political or economic relations with other States or organizations;\ng.\tLimited cooperation of the State with international and regional human rights mechanisms;\nh.\tLack of incentives or willingness of parties to a conflict to engage in dialogue, make concessions and receive support from the international community;\ni.\tLack of interest, reluctance or failure of States Members of the United Nations or members of international or regional organizations to support a State to exercise its responsibility to protect populations from atrocity crimes, or to take action when the State manifestly fails that responsibility;\nj.\tLack of support by neighbouring States to protect populations at risk and in need of refuge, including by closure of borders, forced repatriation or aid restriction;\nk.\tLack of an early warning mechanism relevant to the prevention of atrocity crimes.\nRisk factor 7. Enabling circumstances or preparatory action\na.\tImposition of emergency laws or extraordinary security measures that erode fundamental rights;\nb.\tSuspension of or interference with vital State institutions, or measures that result in changes in their composition or balance of power, particularly if this results in the exclusion or lack of representation of protected groups;\nc.\tStrengthening of the security apparatus, its reorganization or mobilization against protected groups, populations or individuals;\nd.\tAcquisition of large quantities of arms and ammunition or of other objects that could be used to inflict harm;\ne.\tCreation of, or increased support to, militia or paramilitary groups;\nf.\tImposition of strict control on the use of communication channels, or banning access to them;\ng.\tExpulsion or refusal to allow the presence of non-governmental organizations, international organizations, media or other relevant actors, or imposition of severe restrictions on their services and movements;\nh.\tIncreased violations of the right to life, physical integrity, liberty or security of members of protected groups, populations or individuals, or recent adoption of measures or legislation that affect or deliberately discriminate against them;\ni.\tIncreased serious acts of violence against women and children, or creation of conditions that facilitate acts of sexual violence against those groups, including as a tool of terror;\nj.\tImposition of life-threatening living conditions or the deportation, seizure, collection, segregation, evacuation or forced displacement or transfer of protected groups, populations or individuals to camps, rural areas, ghettos or other assigned locations;\nk.\tDestruction or plundering of essential goods or installations for protected groups, populations or individuals, or of property related to cultural and religious identity;\nl.\tMarking of people or their property based on affiliation to a group;\nm.\tIncreased politicization of identity, past events or motives to engage in violence;\nn.\tIncreased inflammatory rhetoric, propaganda campaigns or hate speech targeting protected groups, populations or individuals.\nRisk factor 8. Triggering factors\na.\tSudden deployment of security forces or commencement of armed hostilities;\nb.\tSpillover of armed conflicts or serious tensions in neighbouring countries;\nc.\tMeasures taken by the international community perceived as threatening to a State’s sovereignty;\nd.\tAbrupt or irregular regime changes, transfers of power, or changes in political power of groups;\ne.\tAttacks against the life, physical integrity, liberty or security of leaders, prominent individuals or members of opposing groups; other serious acts of violence, such as terrorist attacks;\nf.\tReligious events or real or perceived acts of religious intolerance or disrespect, including outside national borders;\ng.\tActs of incitement or hate propaganda targeting particular groups or individuals;\nh.\tCensus, elections, pivotal activities related to those processes, or measures that destabilize them;\ni.\tSudden changes that affect the economy or the workforce, including as a result of financial crises, natural disasters or epidemics;\nj.\tDiscovery of natural resources or launching of exploitation projects that have a serious impact on the livelihoods and sustainability of groups or civilian populations;\nk.\tCommemoration events of past crimes or of traumatic or historical episodes that can exacerbate tensions between groups, including the glorification of perpetrators of atrocities;\nl.\tActs related to accountability processes, particularly when perceived as unfair.","unnumbered":true,"annex":8},{"id":"a-hrc-48-68-u0195-a8","rec_id":"recJZU7nZWB5R5U4c","symbol":"A/HRC/48/68","n":null,"seq":195,"section":"V. Document","text":"| United Nations | A/HRC/48/68 | A/HRC/48/68\n| General Assembly | General Assembly | Distr.: General\n12 August 2021\nEnglish\nOriginal: French\nSummary\nSince President Ndayishimiye took power, the democratic space has remained closed and tolerance for criticism remains limited, but the dynamics of relations between Burundi and the international community have changed. Notwithstanding a few isolated symbolic gestures in the area of human rights, no structural reform has been undertaken to durably improve the situation. Serious human rights violations have continued to be committed by State officials and members of the Imbonerakure with the acquiescence of the authorities or even at their instigation. The rule of law continues to be progressively eroded and the risk factors for a deterioration in the human rights situation, though improved in some cases, remain present overall.","unnumbered":true,"annex":8}]});